GP_GH_FLAG_TABLE
}

_gp_gh_load() {
  local p r ap='!alias '
  if [ "$_GP_GH_N" -gt 0 ]; then return 0; fi
  _GP_GH_P=(); _GP_GH_S=(); _GP_GH_AN=(); _GP_GH_AT=()
  while IFS='|' read -r p r; do
    case "$p" in
      gh-version=*|'') ;;
      "$ap"*)
        _GP_GH_AN[${#_GP_GH_AN[@]}]="${p#"$ap"}"
        _GP_GH_AT[${#_GP_GH_AT[@]}]="$r" ;;
      -)
        _GP_GH_P[${#_GP_GH_P[@]}]=''
        _GP_GH_S[${#_GP_GH_S[@]}]="$r" ;;
      *)
        _GP_GH_P[${#_GP_GH_P[@]}]="$p"
        _GP_GH_S[${#_GP_GH_S[@]}]="$r" ;;
    esac
  done <<GP_GH_LOAD
$(gp_gh_flag_table)
GP_GH_LOAD
  _GP_GH_N="${#_GP_GH_P[@]}"
  return 0
}

# `_gp_gh_row <path>` — the row index of that node in `_GP_GH_I`, -1 if none.
_gp_gh_row() {
  local k=0
  _GP_GH_I=-1
  while [ "$k" -lt "$_GP_GH_N" ]; do
    if [ "${_GP_GH_P[$k]}" = "$1" ]; then
      _GP_GH_I="$k"
      return 0
    fi
    k=$((k + 1))
  done
  return 0
}

_gp_gh_has_children() {
  local k=0 pre="${1:+$1 }"
  while [ "$k" -lt "$_GP_GH_N" ]; do
    case "${_GP_GH_P[$k]}" in
      "$pre"?*)
        if [ -n "$1" ] || [ -n "${_GP_GH_P[$k]}" ]; then return 0; fi ;;
    esac
    k=$((k + 1))
  done
  return 1
}

# `_gp_spec_find <spec> <long> <short>` — find a flag in one row by its long or
# its short name; its long name lands in `_GP_FL` and its arity in `_GP_FA`.
_gp_spec_find() {
  local rest="$1 " e s l a
  _GP_FL=''
  _GP_FA=''
  while [ -n "$rest" ]; do
    e="${rest%% *}"
    rest="${rest#* }"
    [ -n "$e" ] || continue
    s="${e%%:*}"
    a="${e#*:}"
    l="${a%%:*}"
    a="${a#*:}"
    if { [ -n "$2" ] && [ "$l" = "$2" ]; } || { [ -n "$3" ] && [ "$s" = "$3" ]; }; then
      _GP_FL="$l"
      _GP_FA="$a"
      return 0
    fi
  done
  return 1
}

# Whether a flag takes no following word at this node: a bool, or an optional
# value (which only `=` supplies). An unknown flag does take one — that is what
# cobra assumes while it looks for the subcommand.
_gp_gh_novalue() {
  if _gp_spec_find "$1" "$2" "$3"; then
    case "$_GP_FA" in
      b|o=*) return 0 ;;
    esac
  fi
  return 1
}

# Whether some group lends the flag to the commands under it: the group's row
# and a row below it both carry it. That is what `-R` is — gh attaches it per
# group, so `pr` and `pr view` have it while `repo` and `repo delete` do not. A
# flag only some leaves declare for themselves, like `-q/--jq`, is not lent by
# anything.
_gp_gh_known() {
  local k=0 m p
  while [ "$k" -lt "$_GP_GH_N" ]; do
    p="${_GP_GH_P[$k]}"
    if [ -n "$p" ] && _gp_spec_find "${_GP_GH_S[$k]}" "$1" "$2"; then
      m=0
      while [ "$m" -lt "$_GP_GH_N" ]; do
        case "${_GP_GH_P[$m]}" in
          "$p "?*)
            if _gp_spec_find "${_GP_GH_S[$m]}" "$1" "$2"; then return 0; fi ;;
        esac
        m=$((m + 1))
      done
    fi
    k=$((k + 1))
  done
  return 1
}

# A flag this leaf does not take is `flag-not-on-leaf` when the family lends it
# to other commands — a spelling that is right one level over — and
# `unknown-flag` when nothing in the family lends it.
_gp_gh_flag_err() {
  if _gp_gh_known "$2" "$3"; then
    _gp_form "gh:flag-not-on-leaf:$1"
  else
    _gp_form "gh:unknown-flag:$1"
  fi
  return 0
}

_gp_bool() {
  case "$1" in
    1|t|T|TRUE|true|True) _GP_BOOL=true ;;
    0|f|F|FALSE|false|False) _GP_BOOL=false ;;
    *) return 1 ;;
  esac
  return 0
}

# Record one option with its scope: `root` when the root node declares it,
# `group` when a group on the path lends it, `leaf` otherwise.
_gp_gh_opt_add() {
  local sc=leaf k=0 p=''
  _gp_gh_row ''
  if [ "$_GP_GH_I" -ge 0 ] && _gp_spec_find "${_GP_GH_S[$_GP_GH_I]}" "$1" ''; then
    sc=root
  else
    while [ $((k + 1)) -lt "${#GP_PATH[@]}" ]; do
      p="${p:+$p }${GP_PATH[$k]}"
      _gp_gh_row "$p"
      if [ "$_GP_GH_I" -ge 0 ] && _gp_spec_find "${_GP_GH_S[$_GP_GH_I]}" "$1" ''; then
        sc=group
        break
      fi
      k=$((k + 1))
    done
  fi
  GP_OK[${#GP_OK[@]}]="$1"
  GP_OV[${#GP_OV[@]}]="$2"
  GP_OS[${#GP_OS[@]}]="$sc"
  return 0
}

_gp_gh() {
  local -a av used
  local n i k w cand path='' spec child name val hasval j c ddash=0
  av=("$@")
  _gp_gh_load
  # A built-in alias expands only in the first position, which is the only
  # place gh looks for one.
  if [ "${#av[@]}" -gt 0 ]; then
    k=0
    while [ "$k" -lt "${#_GP_GH_AN[@]}" ]; do
      if [ "${av[0]}" = "${_GP_GH_AN[$k]}" ]; then
        GP_ALIAS="${av[0]}"
        _gp_split_ws "${_GP_GH_AT[$k]}"
        av=("${_GP_WORDS[@]}" "${av[@]:1}")
        break
      fi
      k=$((k + 1))
    done
  fi
  n="${#av[@]}"
  used=()
  i=0
  while [ "$i" -lt "$n" ]; do used[$i]=0; i=$((i + 1)); done

  # Pass one — the node.
  while :; do
    _gp_gh_row "$path"
    spec="${_GP_GH_S[$_GP_GH_I]}"
    cand=-1
    i=0
    while [ "$i" -lt "$n" ]; do
      if [ "${used[$i]}" = 1 ]; then i=$((i + 1)); continue; fi
      w="${av[$i]}"
      case "$w" in
        --) break ;;
        --*=*) ;;
        --*) _gp_gh_novalue "$spec" "${w#--}" '' || _gp_gh_skip ;;
        -?) _gp_gh_novalue "$spec" '' "${w#-}" || _gp_gh_skip ;;
        -*|'') ;;
        *) cand="$i"; break ;;
      esac
      i=$((i + 1))
    done
    [ "$cand" -ge 0 ] || break
    if [ -n "$path" ]; then child="$path ${av[$cand]}"; else child="${av[$cand]}"; fi
    _gp_gh_row "$child"
    if [ "$_GP_GH_I" -lt 0 ]; then
      if _gp_gh_has_children "$path"; then
        _gp_form "gh:unknown-path:${av[$cand]}"
        return 0
      fi
      break
    fi
    used[$cand]=1
    path="$child"
    GP_PATH[${#GP_PATH[@]}]="${av[$cand]}"
  done

  # Pass two — every flag against the node found.
  _gp_gh_row "$path"
  spec="${_GP_GH_S[$_GP_GH_I]}"
  i=0
  while [ "$i" -lt "$n" ]; do
    if [ "${used[$i]}" = 1 ]; then i=$((i + 1)); continue; fi
    w="${av[$i]}"
    if [ "$ddash" = 1 ]; then
      GP_POS[${#GP_POS[@]}]="$w"
      i=$((i + 1))
      continue
    fi
    case "$w" in
      --)
        ddash=1
        GP_DDASH="${#GP_POS[@]}" ;;
      --*)
        name="${w#--}"; hasval=0; val=''
        case "$name" in
          *=*) val="${name#*=}"; name="${name%%=*}"; hasval=1 ;;
        esac
        if ! _gp_spec_find "$spec" "$name" ''; then
          _gp_gh_flag_err "--$name" "$name" ''
          return 0
        fi
        case "$_GP_FA" in
          b)
            if [ "$hasval" = 1 ]; then
              _gp_bool "$val" || { _gp_form "gh:bool-literal:$w"; return 0; }
              val="$_GP_BOOL"
            else
              val=true
            fi ;;
          v)
            if [ "$hasval" = 0 ]; then
              _gp_gh_skip
              if [ "$i" -ge "$n" ]; then _gp_form ''; return 0; fi
              val="${av[$i]}"
            fi ;;
          *)
            [ "$hasval" = 1 ] || val="${_GP_FA#o=}" ;;
        esac
        _gp_gh_opt_add "$_GP_FL" "$val" ;;
      -?*)
        j=1
        while [ "$j" -lt "${#w}" ]; do
          c="${w:j:1}"
          if ! _gp_spec_find "$spec" '' "$c"; then
            _gp_gh_flag_err "-$c" '' "$c"
            return 0
          fi
          if [ "$_GP_FA" = v ]; then
            if [ "${w:j+1:1}" = '=' ]; then
              val="${w:j+2}"
            elif [ $((j + 1)) -lt "${#w}" ]; then
              val="${w:j+1}"
            else
              _gp_gh_skip
              if [ "$i" -ge "$n" ]; then _gp_form ''; return 0; fi
              val="${av[$i]}"
            fi
            _gp_gh_opt_add "$_GP_FL" "$val"
            break
          fi
          if [ "${w:j+1:1}" = '=' ]; then
            val="${w:j+2}"
            if [ "$_GP_FA" = b ]; then
              _gp_bool "$val" || { _gp_form "gh:bool-literal:$w"; return 0; }
              val="$_GP_BOOL"
            fi
            _gp_gh_opt_add "$_GP_FL" "$val"
            break
          fi
          if [ "$_GP_FA" = b ]; then val=true; else val="${_GP_FA#o=}"; fi
          _gp_gh_opt_add "$_GP_FL" "$val"
          j=$((j + 1))
        done ;;
      *) GP_POS[${#GP_POS[@]}]="$w" ;;
    esac
    i=$((i + 1))
  done
  GP_STATUS=ok
  return 0
}

# Advance `i` to the next word that is not a path word — the word a value flag
# takes, in the argv cobra hands pflag with the path words removed.
_gp_gh_skip() {
  i=$((i + 1))
  while [ "$i" -lt "$n" ] && [ "${used[$i]}" = 1 ]; do i=$((i + 1)); done
  return 0
}

# ---------------------------------------------------------------------------
# Accessors. Pure, and they answer by rc.
# ---------------------------------------------------------------------------

# `gp_opt NAME` — NAME's last value (pflag lets the last one win); rc 1 if absent.
gp_opt() {
  local k="${#GP_OK[@]}"
  while [ "$k" -gt 0 ]; do
    k=$((k - 1))
    if [ "${GP_OK[$k]}" = "$1" ]; then
      printf '%s' "${GP_OV[$k]}"
      return 0
    fi
  done
  return 1
}

gp_opt_count() {
  local k=0 c=0
  while [ "$k" -lt "${#GP_OK[@]}" ]; do
    if [ "${GP_OK[$k]}" = "$1" ]; then c=$((c + 1)); fi
    k=$((k + 1))
  done
  printf '%s' "$c"
  return 0
}

# `gp_opt_at NAME I` — NAME's I-th value, from 0; rc 1 past the end.
gp_opt_at() {
  local k=0 c=0
  while [ "$k" -lt "${#GP_OK[@]}" ]; do
    if [ "${GP_OK[$k]}" = "$1" ]; then
      if [ "$c" = "$2" ]; then
        printf '%s' "${GP_OV[$k]}"
        return 0
      fi
      c=$((c + 1))
    fi
    k=$((k + 1))
  done
  return 1
}

# `gp_has NAME` — rc 0 when NAME's winning value is true.
gp_has() {
  local v
  v=$(gp_opt "$1") || return 1
  [ "$v" = true ]
}

gp_path_is() {
  [ "$#" -eq "${#GP_PATH[@]}" ] || return 1
  gp_path_prefix "$@"
}

gp_path_prefix() {
  local k=0 w
  [ "$#" -le "${#GP_PATH[@]}" ] || return 1
  for w in "$@"; do
    [ "${GP_PATH[$k]}" = "$w" ] || return 1
    k=$((k + 1))
  done
  return 0
}

gp_wrap_has() {
  local r
  for r in ${GP_WRAP[@]+"${GP_WRAP[@]}"}; do
    if [ "${r%%"$_GP_TAB"*}" = "$1" ]; then return 0; fi
  done
  return 1
}

# `gp_env_get NAME` — NAME's value after the chain: the last assignment since
# the last clear, unless a later `-NAME` removed it. rc 1 when the chain leaves
# it unset; what the process environment holds is the caller's to consult.
gp_env_get() {
  local k="$_GP_ENV_BASE" e set=0 val=''
  while [ "$k" -lt "${#GP_ENV[@]}" ]; do
    e="${GP_ENV[$k]}"
    case "$e" in
      "-$1") set=0; val='' ;;
      "$1="*) set=1; val="${e#*=}" ;;
    esac
    k=$((k + 1))
  done
  [ "$set" = 1 ] || return 1
  printf '%s' "$val"
  return 0
}

# `gp_each_sub FN [A...]` — call `FN A... <words>` for each piece of the body.
gp_each_sub() {
  local fn="$1" el rest
  local -a pre words
  shift
  pre=("$@")
  for el in ${GP_SUB[@]+"${GP_SUB[@]}"}; do
    words=()
    rest="$el"
    while :; do
      case "$rest" in
        *"$_GP_US"*)
          words[${#words[@]}]="${rest%%"$_GP_US"*}"
          rest="${rest#*"$_GP_US"}" ;;
        *)
          words[${#words[@]}]="$rest"
          break ;;
      esac
    done
    "$fn" ${pre[@]+"${pre[@]}"} "${words[@]}" || true
  done
  return 0
}

# `gp_gh_repo` — `<repo> TAB <explicit> TAB <host>`. The repository is the last
# `-R`/`--repo`, else `GH_REPO` from the chain; `explicit` is 1 when either
# named it. The host is `--hostname`, else `GH_HOST`, else the host a
# `HOST/OWNER/REPO` or URL spelling carries. A named value that does not reduce
# to `[host/]owner/repo` is rc 2.
gp_gh_repo() {
  local repo='' explicit=0 host='' rc=0 r
  if r=$(gp_opt repo); then
    repo="$r"; explicit=1
  elif r=$(gp_env_get GH_REPO); then
    repo="$r"; explicit=1
  fi
  if r=$(gp_opt hostname); then
    host="$r"
  elif r=$(gp_env_get GH_HOST); then
    host="$r"
  fi
  if [ "$explicit" = 1 ]; then
    if _gp_repo_reduce "$repo"; then
      repo="$_GP_RR"
      if [ -n "$_GP_RH" ]; then host="$_GP_RH"; fi
    else
      rc=2
    fi
  fi
  printf '%s%s%s%s%s' "$repo" "$_GP_TAB" "$explicit" "$_GP_TAB" "$host"
  return "$rc"
}

_gp_repo_reduce() {
  local v="$1" host='' rest owner repo url=0
  _GP_RR=''
  _GP_RH=''
  case "$v" in
    *://*)
      url=1
      rest="${v#*://}"
      host="${rest%%/*}"
      host="${host#*@}"
      host="${host%%:*}"
      case "$rest" in
        */*) rest="${rest#*/}" ;;
        *) return 1 ;;
      esac ;;
    *@*:*)
      url=1
      host="${v%%:*}"
      host="${host#*@}"
      rest="${v#*:}" ;;
    *) rest="$v" ;;
  esac
  rest="${rest%/}"
  if [ "$url" = 0 ]; then
    case "$rest" in
      */*/*/*) return 1 ;;
      */*/*) host="${rest%%/*}"; rest="${rest#*/}" ;;
    esac
    owner="${rest%%/*}"
    repo="${rest#*/}"
  else
    owner="${rest%%/*}"
    repo="${rest#*/}"
    repo="${repo%%/*}"
  fi
  [ "$owner" != "$rest" ] || return 1
  repo="${repo%.git}"
  case "$owner" in
    ''|*[!A-Za-z0-9._-]*) return 1 ;;
  esac
  case "$repo" in
    ''|*[!A-Za-z0-9._-]*) return 1 ;;
  esac
  case "$host" in
    *[!A-Za-z0-9.:-]*) return 1 ;;
  esac
  _GP_RR="$owner/$repo"
  _GP_RH="$host"
  return 0
}

# ---------------------------------------------------------------------------
# `gp_canon` — the act as one line of escaped words, for comparing against a
# pre-authorized shape. Words are separated by one space; inside a word `\`,
# space, TAB, LF and CR are written `\\`, `\x20`, `\t`, `\n`, `\r`, so a word
# boundary and a line boundary survive the trip. `form` prints nothing, rc 1.
#
# THE FIRST WORD IS WHAT WILL RUN, NOT WHAT WAS SPELLED. A bare argv0 is itself.
# A path argv0 is compared with what the gate's PATH resolves the bare name to:
# the same file prints the bare name, a different one prints its physical path —
# so `<dir>/evil/gh` can match only a shape that names that path.
#
# A decomposed family continues with its path words and positionals and leaves
# the options out; a raw argv continues with every word after argv0 except
# `-*=*` ones, which is the normalization the pre-authorization rule's awk
# applies. `list` and `opaque` print one line per piece whose grade is above a
# read, so that each of them is compared on its own.
# ---------------------------------------------------------------------------
gp_canon() {
  local line k w
  case "$GP_STATUS" in
    form|'') return 1 ;;
    list|opaque)
      gp_each_sub _gp_canon_frag
      return 0 ;;
  esac
  _gp_esc "$(_gp_argv0_ident)"
  line="$_GP_ESC"
  if [ "$GP_FAMILY" = raw ]; then
    k=1
    while [ "$k" -lt "${#GP_INNER[@]}" ]; do
      case "${GP_INNER[$k]}" in
        -*=*) ;;
        *) _gp_esc "${GP_INNER[$k]}"; line="$line $_GP_ESC" ;;
      esac
      k=$((k + 1))
    done
  else
    for w in ${GP_PATH[@]+"${GP_PATH[@]}"} ${GP_POS[@]+"${GP_POS[@]}"}; do
      _gp_esc "$w"
      line="$line $_GP_ESC"
    done
  fi
  printf '%s\n' "$line"
  return 0
}

_gp_argv0_ident() {
  local raw="$GP_ARGV0_RAW" dir pdir spelled resolved
  case "$raw" in
    */*) ;;
    *) printf '%s' "$GP_ARGV0"; return 0 ;;
  esac
  dir="${raw%/*}"
  [ -n "$dir" ] || dir=/
  pdir=$(cd "$dir" 2>/dev/null && pwd -P) || pdir=''
  if [ -z "$pdir" ]; then
    printf '%s' "$raw"
    return 0
  fi
  spelled="${pdir%/}/${raw##*/}"
  resolved=$(command -v "$GP_ARGV0" 2>/dev/null) || resolved=''
  case "$resolved" in
    /*)
      if [ -e "$spelled" ] && [ "$spelled" -ef "$resolved" ]; then
        printf '%s' "$GP_ARGV0"
        return 0
      fi ;;
  esac
  printf '%s' "$spelled"
  return 0
}

# A piece's grade decides whether it is a write piece: the builtins read, and
# anything else is answered by the grading table.
_gp_frag_grade() {
  local a
  case "$1" in
    cd|echo|printf|pwd|true|false|:|test|'['|'[['|set|export|unset|shift|read|local|wait|return|exit|type|hash|compgen|trap|ulimit|umask)
      printf '읽기'
      return 0 ;;
    awk)
      shift
      for a in "$@"; do
        case "$a" in
          *'system('*|*'|'*|*'>'*|-f|-f?*) printf '등급 미상'; return 0 ;;
        esac
      done
      printf '읽기'
      return 0 ;;
  esac
  if declare -F surface_of_argv0 >/dev/null 2>&1; then
    surface_of_argv0 "$@"
  else
    printf '등급 미상'
  fi
  return 0
}

_gp_canon_frag() {
  local g
  g=$(_gp_frag_grade "$@") || g=''
  [ "$g" != '읽기' ] || return 0
  ( _GP_ENTRY_DEPTH=$((GP_DEPTH + 1)); gp_parse "$@"; gp_canon ) || true
  return 0
}

_gp_esc() {
  local s="$1" c i=0
  _GP_ESC=''
  while [ "$i" -lt "${#s}" ]; do
    c="${s:i:1}"
    case "$c" in
      '\') _GP_ESC="$_GP_ESC\\\\" ;;
      ' ') _GP_ESC="$_GP_ESC\\x20" ;;
      "$_GP_TAB") _GP_ESC="$_GP_ESC\\t" ;;
      "$_GP_LF") _GP_ESC="$_GP_ESC\\n" ;;
      "$_GP_CR") _GP_ESC="$_GP_ESC\\r" ;;
      *) _GP_ESC="$_GP_ESC$c" ;;
    esac
    i=$((i + 1))
  done
  return 0
}

_gp_unesc() {
  local s="$1" c d i=0
  _GP_UNESC=''
  while [ "$i" -lt "${#s}" ]; do
    c="${s:i:1}"
    if [ "$c" = '\' ]; then
      d="${s:i+1:1}"
      case "$d" in
        '\') _GP_UNESC="$_GP_UNESC\\"; i=$((i + 2)) ;;
        t) _GP_UNESC="$_GP_UNESC$_GP_TAB"; i=$((i + 2)) ;;
        n) _GP_UNESC="$_GP_UNESC$_GP_LF"; i=$((i + 2)) ;;
        r) _GP_UNESC="$_GP_UNESC$_GP_CR"; i=$((i + 2)) ;;
        x)
          if [ "${s:i+2:2}" = 20 ]; then
            _GP_UNESC="$_GP_UNESC "; i=$((i + 4))
          else
            _GP_UNESC="$_GP_UNESC$c"; i=$((i + 1))
          fi ;;
        *) _GP_UNESC="$_GP_UNESC$c"; i=$((i + 1)) ;;
      esac
    else
      _GP_UNESC="$_GP_UNESC$c"
      i=$((i + 1))
    fi
  done
  return 0
}

surface_of_argv0() {
  local cmd="${1##*/}"
  # THE GATE'S OWN HELPERS ARE TRUSTED BY WHERE THEY ARE, NOT BY THEIR NAME.
  # Their rows below grade a read, a tracker write the collaboration surface
  # admits, and a form the kickoff freezes as a `사전 인가` row — and a name is
  # something any caller can give a file. A `./clickup-create.py` written into
  # the worktree is an arbitrary program, so it takes `등급 미상` like any other
  # command the table has no row for, and the refusal that grade carries.
  case "$cmd" in
    clickup-create.py|clickup-relate.py|base-split.py|similar-items.py)
      gate_own_helper "$1" || { printf '등급 미상'; return 0; } ;;
    visual-config.sh|visual-check.sh|visual-capture.sh)
      gate_own_helper "$1" || { printf '등급 미상'; return 0; } ;;
    # The stage rules helper is reached by its path only. A bare name is
    # whatever the act's PATH puts first, and nothing tells the person who runs
    # `status` to put this directory there.
    stage-rules.sh)
      case "$1" in */*) ;; *) printf '등급 미상'; return 0 ;; esac
      gate_own_helper "$1" || { printf '등급 미상'; return 0; } ;;
  esac
  shift
  case "$cmd" in
    # This column has no way to run some other command. `which git merge` is a
    # read and rightly so — it looks a name up and prints it.
    cat|ls|grep|head|tail|wc|stat|file|diff|which)
      printf '읽기' ;;
    # THESE THREE RUN WHAT THEY WRAP, so a name cannot answer for them. They sat
    # in the read row above and graded `읽기` unconditionally, which made
    # `command git merge` an HONESTLY declared read — and the review rule exits
    # on the read grade before it ever reaches the history-integration predicate,
    # so a wrapped merge was exempted from the review requirement outright.
    # Widening that predicate cannot reach this: the exemption happens one layer
    # up, in the grade. Measured on this tree, with the rule's read early-return
    # standing fifteen lines above the line that first reads the predicate.
    #
    # DELEGATED, NOT DELETED FROM THE TABLE. Dropping the three names answers
    # `등급 미상`, which refuses — every ordinary `find` and `rg` read in this
    # pipeline would stop, including the walks over the manifest's own directory
    # the guard below is written to keep passing. And a maintainer who hits that
    # puts the names back on the read row, which reopens this hole exactly as it
    # was. The delegation form is the one `git`, `gh` and `lockf` already use.
    command) surface_of_command "$@" ;;
    find)    surface_of_find "$@" ;;
    rg)      surface_of_rg "$@" ;;
    # The launchers. Same delegation as the three above and for the same reason:
    # `env X=1 git merge seg` is a merge, and a fixed grade here would record it
    # as whatever constant this row named.
    env)     surface_of_env "$@" ;;
    timeout) surface_of_timeout "$@" ;;
    nice)    surface_of_nice "$@" ;;
    nohup)   surface_of_nohup "$@" ;;
    stdbuf)  surface_of_stdbuf "$@" ;;
    time)    surface_of_time "$@" ;;
    # Digest tools. Their absence was a DEADLOCK rather than a gap: the
    # unattended implement arm's process B may enter only after comparing the
    # plan's digest against the one on the ledger row, and computing that digest
    # is the only way to make the comparison. With no row here every spelling
    # was refused, so the one path left was wrapping the command in an
    # interpreter to hide argv0 — which is the exact hole the stage had been
    # dispatched to close. Measured: a stage arrived, found this, and stopped
    # rather than use the hole to land the hole's fix, on the ground that the
    # artifact would then refute itself and the ledger row would state the act's
    # authorization falsely.
    #
    # `openssl` is deliberately NOT here. It computes digests, and it also
    # opens network connections — one name covering both is the kind of
    # imprecision this table exists to refuse.
    # `md5`/`md5sum` are deliberately absent: they are the BSD and GNU spellings
    # of one tool, so naming both trips the portability lint on this very line —
    # and nothing here needs them, since every digest this pipeline compares is
    # sha256.
    shasum|sha256sum|sha1sum|sha512sum|cksum|b2sum)
      printf '읽기' ;;
    # Witness primitives. The same DEADLOCK shape as the digest tools above, one
    # layer out: the agent-team protocol requires a scratch directory and a
    # CSPRNG nonce before any member is spawned, and it forbids the model
    # generating that nonce itself. With no row here every spelling was refused,
    # so a review stage could not reach the point of dispatching its team at all
    # — and the merge rule wants a review record, so one missing row closed the
    # whole back half of the pipeline. Measured: a review stage arrived, tried
    # `mktemp -d`, `openssl rand`, `uuidgen`, `xxd` and `od` in turn, was refused
    # on every one, and halted before spawning.
    #
    # `uuidgen` takes no file operand and writes nothing, so its grade is the
    # same as reading. `mktemp` DOES write, and where it writes depends on a
    # template it may or may not be given, so it takes the higher of the two
    # spellings rather than a guess — `트리밖쓰기` covers a tree path too.
    #
    # `xxd` and `od` stay out. They were tried here only as nonce fallbacks and
    # are not needed once the two above resolve; `xxd` also takes an output file
    # as its second operand, so a bare-name grade would be the same imprecision
    # the `openssl` note below refuses.
    uuidgen)
      printf '읽기' ;;
    mktemp)
      printf '트리밖쓰기' ;;
    # The team witness directory, minted by one script rather than by four
    # statements the caller has to run in a single shell. Same grade as the
    # `mktemp` above because that is what it does — it roots under the driver's
    # run directory or the system temp dir, both out of tree, and writes one
    # `.attempt` file inside the directory it just made. Nothing under the
    # worktree is touched on any path.
    #
    # THE ROW IS WHAT MAKES THE HONEST DECLARATION POSSIBLE. Four statements in
    # one call is `bash -c`, and `bash` is graded a worktree write below without
    # inspecting what it wraps; the comparator is strict equality, so declaring
    # the effect that actually happens was refused exactly as laundering is
    # refused. The caller was left choosing between a false declaration and not
    # running.
    cc-team-witness-init.sh)
      printf '트리밖쓰기' ;;
    # The similar-item lookup. Called with no offline flag it sends issue titles
    # and bodies to a classification model off this machine — whether a key is
    # present is only known at run time, so argv cannot prove the send does not
    # happen, and the honest grade is the external one. `--lexical-only` and
    # `--replay-log` are the two spellings under which the tool builds no HTTP
    # transport at all; the unit test pins zero requests under both, which is
    # what makes the read grade here safe to hand out.
    #
    # `--log` IS THE TOOL'S ONLY FILE WRITE, and the run-directory write guard
    # skips a read grade, so leaving it `읽기` would let that write happen with
    # the guard never looking. The tool refuses option abbreviations, so the
    # spellings read here are the spellings it accepts.
    similar-items.py)
      if gate_argv_has_opt - lexical-only "$@" || gate_argv_has_opt - replay-log "$@"; then
        if gate_argv_has_opt - log "$@"; then printf '트리밖쓰기'; else printf '읽기'; fi
      else
        printf '외부상태변경'
      fi ;;
    # The measurement harness runs the lookup as a child process, which this
    # gate never sees. Its live mode sends every judgment the lookup would, so
    # without this row the send hides behind a name the table does not carry and
    # a `읽기` declaration passes. Without `--live` it replays a recorded log and
    # runs the no-key leg against a closed loopback port — nothing leaves.
    measure-similar-items.py)
      if gate_argv_has_opt - live "$@"; then printf '외부상태변경'; else printf '읽기'; fi ;;
    # The ClickUp ticket creator. It is one POST that files a ticket, and no
    # argument lowers that. It is a separate file from the lookup on purpose, so
    # a tracker write never sits behind the lookup's name and its read grade.
    clickup-create.py)
      printf '외부상태변경' ;;
    # The ClickUp dependency writer: one POST that hangs one task on another.
    clickup-relate.py)
      printf '외부상태변경' ;;
    # The base split helper is graded by its subcommand, which is its first
    # argument. `check` only reads the document; `plan` writes its plan file
    # under the run directory; `record` rewrites the ticket registry beside the
    # document. Anything else is a spelling the helper refuses, and it takes the
    # highest of the three rather than a guess.
    base-split.py)
      case "${1:-}" in
        check)  printf '읽기' ;;
        plan)   printf '트리밖쓰기' ;;
        *)      printf '워크트리쓰기' ;;
      esac ;;
    # The stage rules helper. `status` only reads the instruction file it is
    # given and prints counts. `extract --out-dir` writes the run's snapshot and
    # `migrate` writes a proposal, and neither is a stage's act, so every other
    # spelling takes the unknown grade and its refusal.
    stage-rules.sh)
      case "${1:-}" in
        status) printf '읽기' ;;
        *)      printf '등급 미상' ;;
      esac ;;
    # The three visual helpers, graded by their subcommand. `visual-config.sh
    # snapshot` reads the run's copy of the visual settings; its other
    # subcommands write the settings home or the sidecar, which is the seat's
    # work and never a stage's, so they take the unknown grade and its refusal.
    # `visual-check.sh` only reads the document, the sidecar and the screens.
    # `visual-capture.sh` writes its screenshots into an output directory outside
    # the tree, and `app` serves the build on a loopback port it takes down itself.
    visual-config.sh)
      case "${1:-}" in
        snapshot) printf '읽기' ;;
        *)        printf '등급 미상' ;;
      esac ;;
    visual-check.sh)
      case "${1:-}" in
        scan|size|approval|bundle) printf '읽기' ;;
        *)                         printf '등급 미상' ;;
      esac ;;
    visual-capture.sh)
      case "${1:-}" in
        ref|app) printf '트리밖쓰기' ;;
        *)       printf '등급 미상' ;;
      esac ;;
    # A HEADLESS CHROME SCREENSHOT, AND NOTHING ELSE CHROME DOES. Rendering a
    # local page to an image file is how an unattended review compares a screen,
    # and with no row the binary fell to `등급 미상`. The row is narrow on
    # purpose: only the headless screenshot form — `--headless`, one
    # `--screenshot=` path outside the tree, one local `file:///` target and
    # no flag outside a short allow-list (`gate_chrome_headless_screenshot`) —
    # writes one file outside the tree; any other spelling may open a remote
    # page, sync, serve a port or launch another program, and keeps the unknown
    # grade. The names are the ones the capture helper searches for, and the
    # macOS bundle binary's own name.
    google-chrome|chromium|chromium-browser|chrome|'Google Chrome')
      if gate_chrome_headless_screenshot "$@"; then printf '트리밖쓰기'; else printf '등급 미상'; fi ;;
    # The note above says `openssl` may not sit in the digest row because one
    # name would cover both hashing and opening a socket. That reasoning holds
    # and is not overturned here — it is the reason this is a subcommand table
    # rather than a name, the same shape `git`, `gh` and `terraform` already use.
    openssl) surface_of_openssl "$@" ;;
    eas|eas-cli) surface_of_eas "$@" ;;
    git) surface_of_git "$@" ;;
    gh)  surface_of_gh "$@" ;;
    # `lockf` WRAPS another command, so it carries no grade of its own. Three
    # unattended skills make the document lock a MUST — every write to a design
    # document goes through `lockf -k -t 0 <lockfile> <command>` — and with no
    # row here that mandated spelling fell to `등급 미상`, which refuses. A stage
    # was then left with three moves: break its own skill's MUST and write
    # unlocked, hide argv0 behind an interpreter and launder the act, or stop.
    # One stopped, classified `gate-unanswerable`, which is the honest move and
    # also a night spent.
    #
    # A FIXED grade would be the laundering this table refuses — `lockf … curl …`
    # would record a network act as whatever constant this row named. So the
    # grade is the WRAPPED command's, exactly as `git` and `gh` delegate to
    # their subcommand. The digest-tool comment above records the first instance
    # of this shape; this is the second.
    #
    # THE SAME LAUNDERING RAN FOR A WHILE ON A DIFFERENT AXIS. This row held it
    # shut while the opacity axis, which decides whether the floor and the mark
    # are computed at all, asked argv0 once and answered 0 for anything wrapped —
    # so `lockf … sh -c 'curl …'` kept an honest-looking `워크트리쓰기` that its
    # bare spelling could not. A refusal on one axis is not a refusal until the
    # axes that gate the other checks peel the same word.
    lockf) surface_of_lockf "$@" ;;
    make|npm|npx|yarn|pnpm|pytest|go|cargo|bash|sh|zsh|python3|node)
      printf '워크트리쓰기' ;;
    mkdir|touch|cp|sed|tee|install)
      printf '워크트리쓰기' ;;
    # `mv` AND `rm` ARE GRADED BY WHAT THEY TOUCH, not by their name. The shared
    # agent-team contract publishes every witness with an atomic `mv -n` into an
    # out-of-tree scratch directory, and a name-level `워크트리쓰기` made the
    # honest `트리밖쓰기` declaration come back refused while the false spelling
    # ran — leaving the caller to choose between a wrong ledger row and not
    # publishing at all. Reading the operands takes the choice away.
    mv) surface_of_mv "$@" ;;
    rm) surface_of_rm "$@" ;;
    terraform)
      surface_of_terraform "$@" ;;
    # FOUR OF THESE ARE SUBCOMMAND TABLES NOW, and the reason is the measured
    # one: blanket-grading them `외부상태변경` made `gh pr view`-shaped reads —
    # `aws rds describe-db-instances`, a GET `curl`, `kubectl get` — issue
    # approvals nobody was awake to answer. 25 of the 29 act approvals this
    # pipeline has ever issued were reads of exactly this shape.
    curl)    surface_of_curl "$@" ;;
    aws)     surface_of_aws "$@" ;;
    kubectl) surface_of_kubectl "$@" ;;
    docker)  surface_of_docker "$@" ;;
    brew)    surface_of_brew "$@" ;;
    # Not split here, and each for its own reason. `ssh`/`scp`/`rsync` carry the
    # effect in an operand rather than a verb, `wget` has no read-only form worth
    # carving out, and `gcloud`'s verb surface is wide enough that a partial
    # table would answer confidently about arms nobody checked.
    wget|ssh|scp|rsync|gcloud)
      printf '외부상태변경' ;;
    # Read utilities. Their absence made ordinary shell plumbing — `printenv`,
    # `basename`, `jq` — fall to `등급 미상`, which refuses; a stage that needed
    # one had `bash -c` as its only way through, and that records a read as a
    # worktree write.
    true|false|sleep|pwd|echo|printf|test|basename|dirname|realpath|du|ps|uname|whoami|id|seq|cut|tr|nl|comm|cmp|column|expr|shellcheck|jq|printenv)
      printf '읽기' ;;
    # Four tools whose effect is decided by ONE option, so the row reads it
    # rather than taking the wider grade for the common case.
    yq)   if gate_argv_has_opt -i inplace "$@"; then printf '워크트리쓰기'; else printf '읽기'; fi ;;
    sort) if gate_argv_has_opt -o output "$@";  then printf '트리밖쓰기'; else printf '읽기'; fi ;;
    tsc)  case " $* " in *" --noEmit "*|*" --version "*|*" --showConfig "*) printf '읽기' ;; *) printf '워크트리쓰기' ;; esac ;;
    chmod|ln) printf '워크트리쓰기' ;;
    # Browser automation. With no row here every spelling fell to `등급 미상`,
    # which refuses — so a stage that needed a browser either spent the night in
    # an approval nobody was awake to answer, or reached it through `bash -c`
    # and passed while the ledger recorded a network session as a worktree
    # write. The second is worse than the first: the morning report reads axis 2
    # to say what left the machine, so the laundered spelling makes the audit
    # trail quietly false rather than merely stuck.
    #
    # Graded `외부상태변경` unconditionally, and NOT split by subcommand the way
    # `git` and `terraform` are. Those two have subcommands whose names decide
    # the effect; a browser driver's argv says which page to open, and opening
    # any page is already a network act. There is no read-only arm to carve out.
    playwright|playwright-cli|chromedriver|geckodriver|puppeteer|selenium)
      printf '외부상태변경' ;;
    # Database clients. A schema migration is a standard step BEFORE a deploy,
    # not an exotic one, and with no row here every one of them fell to `등급
    # 미상` — which refuses. All three ways out were closed at once: `--surface`
    # is a checked claim and any claim mismatches an unknown grade; the basename
    # normalization makes the absolute-path spelling identical; and wrapping in
    # `bash -c` passes while recording a DDL against a database as a worktree
    # write, which is the laundering this table exists to refuse.
    #
    # Graded `외부상태변경` even though these clients can also read. The grade is
    # taken from argv0 alone, so a read-only `SELECT` cannot be told apart from a
    # migration here — and of the two ways to be wrong, requiring a
    # pre-authorization row for a read costs a line in the manifest, while
    # letting a migration through as a read costs the database.
    mysql|mysqladmin|mysqldump|psql|pg_dump|pg_restore|createdb|dropdb|sqlite3|mongo|mongosh|redis-cli)
      printf '외부상태변경' ;;

    # CI/CD triggers. Same shape as the database clients above and the same
    # measured failure: a run whose target carries the `배포` cutpoint reached
    # its apply command and was refused, because the manifest's apply command is
    # a site-local script and no row named it. `등급 미상` refuses rather than
    # issuing an approval, so all three ways out were closed at once —
    # `--surface` is a checked claim and every claim mismatches an unknown
    # grade, the basename normalization makes the absolute-path spelling
    # identical, and `bash -c` would record a production deploy as a worktree
    # write, which is the laundering this table exists to refuse. The run could
    # not deploy at all despite holding the cutpoint that authorizes it.
    #
    # Graded `외부상태변경` from argv0 alone, so a read-only probe of the same
    # script (`--probe`) grades the same way. That is the intended side of the
    # trade: a probe needing a pre-authorization row costs a line in the
    # manifest, while a deploy passing as a read costs the environment.
    dasee-jenkins-trigger.sh)
      printf '외부상태변경' ;;
    *) printf '등급 미상' ;;
  esac
}

gate_unwrap_lockf() {
  # gate_unwrap_lockf <resolver> <lock-only> <unknown-opt> [-k] [-s] [-t <sec>] <lockfile> <command> [args...]
  #
  # Skip lockf's own options and its lockfile operand, then hand what is left to
  # <resolver>. `-t` takes a value; `-k`, `-s` and `-n` do not. The lockfile is
  # the first non-option word and is never itself the command.
  #
  # ONE UNWRAP SHARED BY TWO TABLES. The grader and the history-integration
  # predicate both have to see through `lockf`, and while each carried its own
  # skip loop the two could resolve the SAME argv differently — a wrapped local
  # merge graded `워크트리쓰기` while the predicate answered "not an integration"
  # and exempted it from the review rule. Only the terminal answers differ, so
  # only those are parameters: the grader passes `워크트리쓰기`/`등급 미상`, the
  # predicate passes `0`/`1`.
  #
  # ARGV0 IS ALREADY GONE. `surface_of_argv0` drops it before dispatching and the
  # lockf arm of the predicate drops it explicitly, so this loop starts at the
  # first option. The old code shifted a SECOND time here, which ate whatever
  # stood first: `lockf <file> git status` then read `git` as the lockfile and
  # graded `status` alone, and `lockf -t 5 <file> git commit` read `5` as the
  # lockfile. Both are the shapes the fixtures below now pin.
  local resolver="$1" lock_only="$2" unknown_opt="$3"; shift 3
  local seen_file=0
  while [ "$#" -gt 0 ]; do
    case "$1" in
      # `-t` with no value after it emits NOTHING, which is what this did before
      # it was factored out. Repairing that here would mix a second change into
      # the one these fixtures measure.
      -t) shift 2 || return 0 ;;
      -t*) shift ;;
      -k|-s|-n) shift ;;
      -*) printf '%s' "$unknown_opt"; return 0 ;;
      *)
        if [ "$seen_file" = 0 ]; then seen_file=1; shift; continue; fi
        "$resolver" "$@"
        return 0 ;;
    esac
  done
  # A lock with nothing after it locks and exits — that is a worktree write (it
  # creates the lockfile) and there is no wrapped command to defer to.
  [ "$seen_file" = 1 ] && { printf '%s' "$lock_only"; return 0; }
  printf '%s' "$unknown_opt"
}

surface_of_lockf() {
  # surface_of_lockf <lockf-args-after-argv0...>
  gate_unwrap_lockf surface_of_argv0 '워크트리쓰기' '등급 미상' "$@"
}

gate_unwrap_command() {
  # gate_unwrap_command <resolver> <no-exec> <unknown-opt> <command's args after argv0...>
  #
  # `command` skips shell functions and aliases and runs the NEXT word. Its own
  # options are `-p` (default PATH) and `-v`/`-V`, which print what would run and
  # execute nothing. Everything after that belongs to the wrapped command.
  #
  # THE SAME ONE-UNWRAP-TWO-TABLES SHAPE AS `gate_unwrap_lockf`, and for the same
  # reason: the grader and the history-integration predicate both have to see
  # through this word, and two copies of the skip loop are two chances for them
  # to disagree about which word is the command. Only the terminal answers are
  # parameters — the grader passes `읽기`/`등급 미상`, the predicate `0`/`1`.
  local resolver="$1" no_exec="$2" unknown_opt="$3"; shift 3
  while [ "$#" -gt 0 ]; do
    case "$1" in
      -v|-V|-pv|-pV|-vp|-Vp) printf '%s' "$no_exec"; return 0 ;;
      -p) shift ;;
      --) shift; break ;;
      -*) printf '%s' "$unknown_opt"; return 0 ;;
      *)  break ;;
    esac
  done
  [ "$#" -ge 1 ] || { printf '%s' "$no_exec"; return 0; }
  "$resolver" "$@"
}

gate_call_prefix() {
  # gate_call_prefix <n> <resolver> <args...> — call <resolver> with the FIRST
  # <n> of <args> and with NOTHING that stood behind them.
  #
  # Rotating the list left by <n> moves that prefix to the end, so dropping the
  # words that were behind it leaves exactly the prefix. Positional rather than
  # an array because every other loop in this file is positional, and because an
  # empty array under `set -u` is a second idiom that fails differently on
  # bash 3.2 than on 5.
  local n="$1" resolver="$2" i=0 rest; shift 2
  rest=$(( $# - n ))
  while [ "$i" -lt "$n" ]; do
    set -- "$@" "$1"; shift
    i=$((i + 1))
  done
  shift "$rest"
  "$resolver" "$@"
}

gate_unwrap_find() {
  # gate_unwrap_find <resolver> <walk-only> <writes> <form-unknown> <combiner> <find's args after argv0...>
  #
  # EVERY PRIMARY IS READ, NOT JUST THE FIRST. A word whose FIRST CHARACTER is
  # `;` always terminates an `-exec`, and one whose first character is `+`
  # terminates it only directly after `{}` — anywhere else a `+` word is an
  # argument of the inner command. That is how the BSD `find` on macOS reads
  # them: `-exec cat {} ';;' -delete` ends the `-exec` at `;;` and deletes.
  # Comparing the whole word let that `-delete` be swallowed as an argument of
  # `cat` and graded `읽기`. GNU `find` compares the whole word, so there the
  # first-character rule grades a later primary it would not have split off —
  # over-reading, which is the safe side on both hosts. What follows a
  # terminator is the NEXT primary rather than a further argument of the inner
  # command. Handing the whole remainder to the resolver and returning
  # read `find <d> -name f -exec cat {} ';' -delete` as the inner command
  # `[cat {} ; -delete]`, so the deletion was graded as an argument of `cat`:
  # argv came back `읽기` and both write guards returned on their first line.
  # The scan now consumes one primary at a time and folds the answers with
  # <combiner>, which each consumer supplies because their answers are of
  # different types. The grader's combiner lets an unrecognized answer WIN over
  # a recognized one, so one primary the table cannot grade makes the whole argv
  # ungradable rather than being erased by a `-exec cat` beside it.
  #
  # `-execdir` AND `-okdir` ANSWER <form-unknown> AND STOP. They run the inner
  # command from EACH MATCH's directory, which the gate does not know and cannot
  # enumerate without walking the tree itself, so every base a resolver could
  # compute from the grading directory is the wrong one. Measured before this
  # arm existed: with no `-C`, with `-C .`, under `-okdir`, and with a bare name
  # operand, the second base came back EMPTY and both write guards passed the
  # act at rc 0. Empty means "no base" and no base is the allowing direction, so
  # the residual was not an under-read — it was a hole. The third answer refuses
  # instead, and unlike `등급 미상` no declaration lifts it.
  #
  # Two ways a `find` writes. Four primaries hand the match to another command,
  # and five act on their own — `-delete` removes the match, while `-fprintf`,
  # `-fprint`, `-fprint0` and `-fls` each open a file named in argv and write to
  # it. The last four are GNU-only, so on a BSD host `find` rejects them before
  # anything happens; on the Linux CI runner they are the cheapest way to
  # overwrite a file through a command that argv0 alone grades as a read.
  # THE OPTION SET IS NOT INVENTED HERE — it is the one this file already carries
  # in both write guards below, and a fifth spelling of the same list is how
  # those two quietly drift apart.
  #
  # THIS LIST IS NOT CLAIMED TO BE COMPLETE. It is the set the two guards below
  # enforce, and the three have to be changed together; a reader checking one
  # against the others finds them equal, which says nothing about whether some
  # sixth primary writes.
  #
  # A PLAIN `find` WITH NO PRIMARY KEEPS COMING BACK `읽기`. The manifest guard
  # states that cost in place: without it every read that walks the manifest's
  # directory becomes a refusal.
  local resolver="$1" walk_only="$2" writes="$3" form_unknown="$4" combiner="$5"; shift 5
  local acc="" seen=0 ans="" n term a prev
  while [ "$#" -gt 0 ]; do
    case "$1" in
      -execdir|-okdir) printf '%s' "$form_unknown"; return 0 ;;
      -exec|-ok)
        shift
        # The inner command is the words up to one starting with `;`, or up to
        # one starting with `+` that stands directly after `{}`. Taking every
        # bare `+` as the terminator cut
        # `-exec curl + -X POST https://x ';'` down to `curl` and graded it
        # `읽기`. A `-exec` with nothing behind it has no command to defer to,
        # which is the shape the old early return already answered `writes`.
        n=0; term=0; prev=""
        for a in "$@"; do
          case "$a" in
            ';'*) term=1; break ;;
            '+'*) [ "$prev" = '{}' ] && { term=1; break; } ;;
          esac
          prev="$a"
          n=$((n + 1))
        done
        if [ "$n" -eq 0 ]; then
          ans="$writes"
        else
          ans=$(gate_call_prefix "$n" "$resolver" "$@")
        fi
        shift "$n"
        if [ "$term" = 1 ]; then shift; fi ;;
      # NOT A RETURN ANY MORE. A higher-graded primary can stand behind this
      # one, and the operands these take are consumed by the arm below as
      # ordinary words — reading one of them as a primary can only over-grade.
      -delete|-fprintf|-fprint|-fprint0|-fls) ans="$writes"; shift ;;
      *) shift; continue ;;
    esac
    if [ "$seen" = 0 ]; then acc="$ans"; seen=1; else acc=$("$combiner" "$acc" "$ans"); fi
  done
  [ "$seen" = 1 ] && { printf '%s' "$acc"; return 0; }
  printf '%s' "$walk_only"
}

gate_find_exec_substitutes() {
  # gate_find_exec_substitutes <name> <find's args after argv0...> — true when
  # one `-exec`/`-ok` command both names <name> (by basename, anywhere in its
  # words) and carries a word holding `{}`.
  #
  # THE UNWRAP HANDS THE INNER COMMAND OVER AS WRITTEN, `{}` AND ALL, and find
  # does not run it as written: BSD and GNU find both put the match's path in
  # place of `{}` inside any word, so `-exec git push origin <sha>:{} ';'` run
  # in `master` pushes to the base while its dry-run aimed at `refs/heads/{}`,
  # and `gh api -X PUT repos/o/r/pulls/N/{}` run in `merge` merges while it
  # read as no merge at all. find also runs the command once per match, which
  # one reading cannot stand for. So the readers that need to know what such
  # a command reaches do not read it: the push is `불투명`, a gh call is a
  # merge with no binding. The terminators are the ones `gate_unwrap_find`
  # reads.
  local name="$1"; shift
  local a prev in_exec=0 named=0 subst=0
  while [ "$#" -gt 0 ]; do
    a="$1"; shift
    if [ "$in_exec" = 0 ]; then
      case "$a" in -exec|-ok) in_exec=1; named=0; subst=0; prev="" ;; esac
      continue
    fi
    case "$a" in
      ';'*) in_exec=0 ;;
      '+'*) [ "$prev" = '{}' ] && in_exec=0 ;;
    esac
    if [ "$in_exec" = 1 ]; then
      [ "${a##*/}" = "$name" ] && named=1
      case "$a" in *'{}'*) subst=1 ;; esac
      prev="$a"
    fi
    [ "$named" = 1 ] && [ "$subst" = 1 ] && return 0
  done
  return 1
}

gate_unwrap_rg() {
  # gate_unwrap_rg <resolver> <search-only> <truncated> <rg's args after argv0...>
  #
  # `--pre` names a program every searched file is fed through before the search.
  # The value is one program and takes no arguments of its own, so exactly that
  # one word goes to the resolver.
  local resolver="$1" search_only="$2" truncated="$3"; shift 3
  while [ "$#" -gt 0 ]; do
    case "$1" in
      --pre)
        shift
        [ "$#" -ge 1 ] || { printf '%s' "$truncated"; return 0; }
        "$resolver" "$1"
        return 0 ;;
      --pre=*)
        "$resolver" "${1#--pre=}"
        return 0 ;;
      *) shift ;;
    esac
  done
  printf '%s' "$search_only"
}

# The grader's terminal answers. They point the OPPOSITE way from the
# predicate's, which is deliberate and is the discipline the two-table comment
# below already sets: this table answers `등급 미상` to what it does not
# understand and the gate refuses, while the predicate answers `1` and keeps the
# act under the check.
surface_of_command() { gate_unwrap_command surface_of_argv0 '읽기' '등급 미상' "$@"; }
surface_of_find()    { gate_unwrap_find    surface_of_argv0 '읽기' '워크트리쓰기' "$GATE_FORM_UNKNOWN" gate_surface_fold_find "$@"; }
surface_of_rg()      { gate_unwrap_rg      surface_of_argv0 '읽기' '등급 미상' "$@"; }

gate_history_integration() {
  # gate_history_integration <argv...> — prints 1 when this argv integrates one
  # line of history into another, 0 when it does not.
  #
  # THIS EXISTS BECAUSE THE GRADED SURFACE CANNOT SPLIT ITS OWN WORKTREE-WRITE
  # CELL. The table below grades a local `merge`, `rebase` and `cherry-pick` as
  # `워크트리쓰기`, and the same cell holds `mkdir` and `touch`. Exempting the
  # cell lets a local merge carry an honest segment and pass the review rule
  # with no review record at all; checking the cell whole demands a review
  # record from an ordinary directory creation, and that is not an edge case —
  # the router labels every act with its TARGET's cutpoint, so an ordinary write
  # declared at `배포` is the normal path, not noise.
  #
  # THE SPLITTING VALUE IS READ FROM argv AND NEVER FROM A DECLARATION. `--kind`
  # has no vocabulary check, so any word at all rides there; and `exec` refuses
  # `--kind` outright, so under that verb the kind is always the empty string.
  # A cell split on the kind would therefore exempt both `exec -- git merge` and
  # `act --kind x -- git merge`, which is the surface-exemption hole surviving
  # with nothing changed but the axis it hides behind.
  #
  # AN UNRECOGNIZED SPELLING ANSWERS 1, AND THAT IS WHY THIS IS NOT A SECOND
  # COPY OF THE GRADING TABLE. That table answers `등급 미상` and refuses; this
  # one answers "check it". The two therefore fail in OPPOSITE directions, so
  # where they drift the drift can only over-check — one manifest line — and
  # never open the bypass this rule exists to close.
  #
  # THE argv0 LAYER IS A TABLE, NOT AN EQUALITY AGAINST `git`. Comparing argv0
  # to one name answered 0 for every wrapper, so both spellings that reach the
  # `워크트리쓰기` CELL without the grading table seeing what they wrap fell out
  # of the check entirely: `lockf … git merge` and `bash -c 'git merge …'` each
  # graded `워크트리쓰기` and each answered "not an integration". That is the
  # exemption this predicate exists to close, reached by the shortest possible
  # detour.
  #
  # THAT COUNT IS SCOPED TO THAT CELL AND TO NOTHING ELSE. Stated without the
  # scope it reads as a census of every wrapper this file is blind to, and it
  # never was one — the sentence stood unscoped here while three more wrappers
  # were escaping through a DIFFERENT cell, and a maintainer reading it went
  # looking for the leak in the argv0 list below, where it could not be. The
  # three were `command`, `find` and `rg`: each runs some other command, each was
  # graded `읽기` from argv0 alone, and the review rule exits on the read grade
  # fifteen lines before it first reads this predicate. So `command git merge`
  # declared `읽기` honestly, agreed with its own grade, and was exempted with
  # this predicate never consulted. Widening the list below could not have
  # touched it.
  #
  # They are fixed in the grading table instead (`surface_of_command`,
  # `surface_of_find`, `surface_of_rg`), and the arms below consume those SAME
  # unwraps so the two tables cannot disagree about which word was wrapped. IF A
  # WRAPPER IS ESCAPING THIS CHECK, LOOK AT ITS GRADE FIRST — the grade decides
  # whether the rule ever gets here.
  local cmd="${1##*/}"
  case "$cmd" in
    # `lockf` wraps, so unwrap it with the same routine the grader uses and ask
    # this question of what it wrapped. Sharing the unwrap is the point: two
    # copies of the skip loop are two chances for the tables to disagree about
    # which word is the command.
    lockf)
      shift
      gate_unwrap_lockf gate_history_integration '0' '1' "$@"
      return 0 ;;
    # The three the grading table now sees through. THIS HALF IS NOT OPTIONAL:
    # move `command git merge` into `워크트리쓰기` and leave this predicate
    # answering 0, and the review rule exempts it again on the very next line —
    # the repair would be green and inert. The unwraps are shared with the grader
    # for the reason the `lockf` arm above gives.
    command)
      shift
      gate_unwrap_command gate_history_integration '0' '1' "$@"
      return 0 ;;
    find)
      shift
      # `1` for the unreadable shape as well, which is this predicate's own
      # discipline stated above: where it cannot read, it over-checks.
      gate_unwrap_find gate_history_integration '0' '1' '1' gate_answer_or "$@"
      return 0 ;;
    rg)
      shift
      gate_unwrap_rg gate_history_integration '0' '1' "$@"
      return 0 ;;
    # The launchers, unwrapped here for exactly the reason the three above are:
    # wired into the grading table alone, `env X=1 git merge seg` grades a
    # worktree write while this predicate answers 0, and the review rule exempts
    # the merge on the next line — green and inert.
    env)
      shift
      gate_unwrap_env gate_history_integration '0' '1' "$@"
      return 0 ;;
    timeout|nice|nohup|stdbuf)
      local wname="$cmd"
      shift
      gate_unwrap_wrapper "$wname" gate_history_integration '0' '1' "$@"
      return 0 ;;
    time)
      shift
      gate_unwrap_time gate_history_integration '0' '1' "$@"
      return 0 ;;
    # Names the grading table answers `워크트리쓰기` WITHOUT asking what they
    # wrap. This predicate cannot parse a shell word without being a shell, so
    # it answers 1 rather than guessing — the direction the paragraph above
    # already commits to, where drift can only over-check. What that costs is
    # bounded: the review rule exits before asking for a record unless the
    # target's cutpoint is at or above `머지`.
    bash|sh|zsh|make|npm|npx|yarn|pnpm|pytest|go|cargo|python3|node)
      printf '1'; return 0 ;;
    git) ;;
    *) printf '0'; return 0 ;;
  esac
  shift
  # The same global-option skip the grader does, spelled the same way, because a
  # global option left in place puts a non-subcommand in the slot below. The one
  # divergence is the unknown arm, for the reason given above.
  while [ $# -gt 0 ]; do
    case "$1" in
      -C|-c|--git-dir|--work-tree|--namespace|--exec-path|--config-env)
        [ $# -ge 2 ] || { printf '1'; return 0; }
        shift 2 ;;
      --git-dir=*|--work-tree=*|--namespace=*|--exec-path=*|--config-env=*)
        shift ;;
      -p|-P|--paginate|--no-pager|--bare|--no-replace-objects)
        shift ;;
      --literal-pathspecs|--no-optional-locks|--glob-pathspecs|--noglob-pathspecs|--icase-pathspecs)
        shift ;;
      -*) printf '1'; return 0 ;;
      *)  break ;;
    esac
  done
  # `merge-base` is a query and is NOT on this list — `case` matches whole
  # patterns, so it does not reach the `merge` arm. `pull` is here even though
  # the grader puts it in `외부상태변경`, a cell this split never reaches: the
  # list states what the predicate MEANS rather than what the caller happens to
  # ask about, and a predicate that omits a case because today's caller cannot
  # reach it is one refactor away from being wrong.
  #
  # `reset` IS ON THE LIST EVEN THOUGH ITS NAME DOES NOT DECIDE. Aimed at another
  # ref it moves this branch onto another line of history, which is the thing
  # this predicate names; aimed at nothing but `--hard` it only discards local
  # work. Telling those apart means telling a ref operand from a pathspec, and
  # that needs the repository — so the name goes on the list and the cost is an
  # over-check. `revert` stays OFF: it writes a new commit on this branch undoing
  # one already in this branch's history, so no second line is integrated.
  case "${1:-}" in
    merge|rebase|cherry-pick|am|pull|reset) printf '1' ;;
    *) printf '0' ;;
  esac
}

gate_git_config_key_execs() {
  # Does this configuration key name a COMMAND git will run? The list is the
  # keys whose value is a command line or a program name, and it is deliberately
  # wider than the ones anyone has abused: a key that runs something and is not
  # here grades as the verb it rides on, which is the failure direction this
  # whole predicate exists to close.
  #
  # `core.pager` and `pager.*` are NOT here. Git does not start a pager when its
  # stdout is not a terminal, and every act this gate runs is captured — measured
  # on this machine with `git -c core.pager='touch …' log -1 >/dev/null`, which
  # created no file.
  #
  # THE KEY IS COMPARED WITHOUT CASE. Git reads section and variable names
  # without case, so `core.SSHCOMMAND` is the same key and passed a
  # case-sensitive list.
  local k; k=$(printf '%s' "$1" | tr '[:upper:]' '[:lower:]')
  case "$k" in
    core.sshcommand|core.gitproxy|core.editor|core.fsmonitor|core.hookspath|core.askpass|sequence.editor|diff.external|gpg.program|credential.helper|uploadpack.packobjectshook|web.browser)
      return 0 ;;
    gpg.*.program|credential.*.helper|alias.*|protocol.allow|protocol.*.allow|url.*|http.proxy|remote.*.uploadpack|remote.*.receivepack|remote.*.proxy|filter.*|merge.*.driver|diff.*.command|diff.*.textconv|include.path|includeif.*|browser.*)
      return 0 ;;
    *) return 1 ;;
  esac
}

surface_of_git_fetch() {
  # A fetch that only moves REMOTE-TRACKING refs changes nothing a later act
  # reads as its own state, so it is a read — and it is the single most common
  # act approval this pipeline ever issued. What makes a fetch a write is a
  # refspec whose DESTINATION is a local ref, or an option that rewrites the
  # local repository's own shape.
  case " $* " in
    *" --upload-pack "*|*" --upload-pack="*) printf '%s' "$GATE_FORM_UNKNOWN"; return 0 ;;
    *" --depth "*|*" --depth="*|*" --deepen "*|*" --deepen="*|*" --shallow-since"*|*" --shallow-exclude"*|*" --unshallow "*|*" --update-shallow "*|*" --prune-tags "*|*" -P "*|*" --set-upstream "*|*" --update-head-ok "*|*" --refetch "*)
      printf '워크트리쓰기'; return 0 ;;
  esac
  local a seen_remote=0
  for a in "$@"; do
    case "$a" in
      fetch) continue ;;
      -*) continue ;;
    esac
    if [ "$seen_remote" = "0" ]; then seen_remote=1; continue; fi
    # A refspec. An empty destination (`<src>` alone) and one under
    # `refs/remotes/` leave local branches alone; anything else names a local ref.
    case "$a" in
      *:*)
        local dst="${a#*:}"
        case "$dst" in
          ''|refs/remotes/*) ;;
          *) printf '워크트리쓰기'; return 0 ;;
        esac ;;
    esac
  done
  printf '읽기'
}

surface_of_git() {
  # git's GLOBAL options come BEFORE the subcommand, so `git -C <path> commit`
  # puts `-C` in the slot the table reads and the whole act graded `등급 미상`.
  #
  # Only the globals git actually defines are skipped, and an UNRECOGNIZED dash
  # option ends the scan as unknown rather than guessing whether it consumes the
  # next word. Guessing wrong would shift the subcommand out of view and grade a
  # `push` by whatever word landed in its place — a wrong grade is worse here
  # than no grade, because `등급 미상` refuses and a wrong grade performs.
  while [ $# -gt 0 ]; do
    case "$1" in
      # `-c <key>=<value>` CAN NAME A PROGRAM. A dozen git configuration keys are
      # command lines git runs itself — a pager, an ssh command, a credential
      # helper, a filter driver — so `git -c core.sshCommand=… fetch` is not the
      # fetch its verb says it is. The keys are refused as a FORM rather than
      # graded, because what they run is arbitrary and invisible to this table.
      -c)
        [ $# -ge 2 ] || { printf '등급 미상'; return 0; }
        if gate_git_config_key_execs "${2%%=*}"; then
          printf '%s' "$GATE_FORM_UNKNOWN"; return 0
        fi
        shift 2 ;;
      # `--exec-path` moves the directory git runs its own subcommands from and
      # `--config-env` names an environment variable holding one of those same
      # keys; neither is readable here.
      --exec-path|--exec-path=*|--config-env|--config-env=*)
        printf '%s' "$GATE_FORM_UNKNOWN"; return 0 ;;
      -C|--git-dir|--work-tree|--namespace)
        [ $# -ge 2 ] || { printf '등급 미상'; return 0; }
        shift 2 ;;
      --git-dir=*|--work-tree=*|--namespace=*)
        shift ;;
      -p|-P|--paginate|--no-pager|--bare|--no-replace-objects)
        shift ;;
      --literal-pathspecs|--no-optional-locks|--glob-pathspecs|--noglob-pathspecs|--icase-pathspecs)
        shift ;;
      -*) printf '등급 미상'; return 0 ;;
      *)  break ;;
    esac
  done
  case "${1:-}" in
    status|log|show|diff|rev-parse|rev-list|merge-base|blame|cat-file|ls-files|ls-tree|check-ignore|check-attr|for-each-ref|show-ref|diff-tree|describe|name-rev|shortlog|count-objects|cherry|range-diff|version|merge-tree|grep|ls-remote)
      # These print and do not change a ref — EXCEPT where an option turns one
      # into a writer or a program runner. `--output=<file>` puts the result on
      # disk, `--ext-diff` and `grep -O` hand the content to a command of the
      # caller's choosing, and `ls-remote --upload-pack` names a program to run
      # on the other side.
      case " $* " in
        *" --ext-diff "*|*" -O "*|*" --open-files-in-pager "*|*" --upload-pack "*|*" --upload-pack="*)
          printf '%s' "$GATE_FORM_UNKNOWN"; return 0 ;;
        *" --output "*|*" --output="*)
          printf '트리밖쓰기'; return 0 ;;
      esac
      printf '읽기' ;;
    # `archive` writes only where told to; with no `-o` it goes to stdout. Its
    # `--remote`/`--exec` pair runs a program on another machine.
    archive)
      case " $* " in
        *" --remote "*|*" --remote="*|*" --exec "*|*" --exec="*)
          printf '%s' "$GATE_FORM_UNKNOWN" ;;
        *) if gate_argv_has_opt -o output "$@"; then printf '트리밖쓰기'; else printf '읽기'; fi ;;
      esac ;;
    fetch) surface_of_git_fetch "$@" ;;
    # `clone` writes a tree out of the current one, so it is a write rather than
    # an external change — but three of its options make it RUN something: an
    # upload-pack command of the caller's choosing, a template directory whose
    # hooks execute during checkout, and clone's own `-c` carrying the same exec
    # keys the global `-c` above refuses.
    clone)
      case " $* " in
        *" -u "*|*" --upload-pack "*|*" --upload-pack="*|*" --template "*|*" --template="*)
          printf '%s' "$GATE_FORM_UNKNOWN"; return 0 ;;
      esac
      local a
      for a in "$@"; do
        case "$a" in
          --config=*|-c=*) gate_git_config_key_execs "${a#*=}" && { printf '%s' "$GATE_FORM_UNKNOWN"; return 0; } ;;
        esac
      done
      printf '트리밖쓰기' ;;
    # Three subcommands whose NAME says nothing about their effect, and all three
    # sat on the read arm above: `git worktree add` creates a working tree,
    # `git branch -D` deletes a ref, and `git config --global` rewrites the
    # user's own configuration under $HOME — each recorded as a read. Two things
    # broke at once. The reversibility floor read `git config --global <k> <v>`
    # as a costless undo, so an act could be auto-adopted on the strength of a
    # rollback that edits $HOME. And a worktree creation declared honestly as
    # `워크트리쓰기` came back exit 6 while the same act declared `읽기` ran, so
    # the only spelling that worked was the false one.
    #
    # None of the three shifts. The caller already dropped argv0 and the
    # global-option loop above has ended, so `$1` is still the subcommand and
    # `$2` onward are its arguments — the reading `surface_of_terraform` records
    # for `state`.
    worktree) surface_of_git_worktree "$@" ;;
    branch)   surface_of_git_branch "$@" ;;
    config)   surface_of_git_config "$@" ;;
    add|commit|checkout|switch|restore|rebase|merge|cherry-pick|revert|stash|apply|am|reset|tag)
      printf '워크트리쓰기' ;;
    remote)   surface_of_git_remote "$@" ;;
    # `fetch` and `clone` left this arm: the first only moves remote-tracking
    # refs unless a refspec names a local branch, and the second writes a tree.
    # `push` and `pull` stay — one publishes and the other merges what it fetched.
    #
    # `push --receive-pack=<cmd>` and `--exec=<cmd>` name a program git runs —
    # on this machine, for a remote that is a local path — so they are refused
    # as a form, the way `fetch --upload-pack` is. Git takes any unambiguous
    # prefix of a long option, so every prefix is refused: `--e…` of `--exec`,
    # and `--rec…` of `--receive-pack` from the first letter that is not also
    # `--recurse-submodules`'s or `--repo`'s (`--rec` and shorter are ambiguous
    # and git refuses them itself). This holds for a push to any target, with a
    # base branch or without.
    push)
      local pa po
      shift
      for pa in "$@"; do
        [ "$pa" = '--' ] && break
        po="${pa%%=*}"
        case "$po" in
          --e|--ex|--exe|--exec|--rece|--recei|--receiv|--receive|--receive-|--receive-p|--receive-pa|--receive-pac|--receive-pack)
            printf '%s' "$GATE_FORM_UNKNOWN"; return 0 ;;
        esac
      done
      printf '외부상태변경' ;;
    pull)
      printf '외부상태변경' ;;
    *) printf '등급 미상' ;;
  esac
}

surface_of_git_remote() {
  # `git remote` and `git remote -v` list what local config already records —
  # no packet leaves the machine. Lumping them with `push`/`fetch` made reading
  # the remote configuration issue an approval, and unattended there is nobody
  # to answer it, so a stage could not even see the state it was about to act
  # on. The same repair was already made for `terraform`, whose comment records
  # the identical reasoning; this row is that repair reaching `git remote`.
  case "${2:-}" in
    ''|-v|--verbose)                                   printf '읽기' ;;
    add|remove|rm|rename|set-url|set-head|set-branches) printf '워크트리쓰기' ;;
    # `show` and `update` and `prune` contact the remote. `show -n` does not,
    # but grading on a flag that may sit anywhere in argv is the kind of
    # precision this table refuses to fake — the safe direction is the wider
    # grade, which costs a manifest line rather than a false audit trail.
    show|update|prune)                                  printf '외부상태변경' ;;
    *)                                                  printf '등급 미상' ;;
  esac
}

surface_of_git_worktree() {
  # `git worktree list` is what the verification contract's boundary gate runs
  # before and after every recipe, so it has to stay a read. Everything else
  # here adds, removes, relocates or locks a working tree.
  case "${2:-}" in
    list|'') printf '읽기' ;;
    add|remove|move|prune|repair|lock|unlock) printf '워크트리쓰기' ;;
    *) printf '등급 미상' ;;
  esac
}

surface_of_git_branch() {
  # Listing by default; creating, deleting, renaming, copying or repointing an
  # upstream writes a ref.
  #
  # The option scan exists for ONE reason: `--contains`, `--merged`, `--sort`
  # and their kin take the NEXT WORD as their value, and a value left in place
  # looks like a positional branch name — which would grade `git branch
  # --contains HEAD`, a pure query, as a branch creation. `--color` is on the
  # valueless side on purpose: git spells it `--color[=<when>]`, so eating the
  # next word there would make `git branch --color newbr` read as a query, which
  # is the same mistake with its sign flipped.
  local a skip=1 want=0
  for a in "$@"; do
    # The first word is `branch` itself — this function is handed the whole
    # subcommand argv and does not shift.
    if [ "$skip" = 1 ]; then skip=0; continue; fi
    if [ "$want" = 1 ]; then want=0; continue; fi
    case "$a" in
      -d|-D|--delete|-m|-M|--move|-c|-C|--copy|-u|--set-upstream-to|--set-upstream-to=*|--unset-upstream|--edit-description|-f|--force)
        printf '워크트리쓰기'; return 0 ;;
      --contains|--no-contains|--merged|--no-merged|--points-at|--sort|--format)
        want=1 ;;
      -a|--all|-r|--remotes|-v|-vv|--verbose|-q|--quiet|-l|--list|--show-current)
        : ;;
      -i|--ignore-case|--omit-empty|--no-abbrev|--no-color|--column|--no-column|--track|--no-track|--color)
        : ;;
      --contains=*|--no-contains=*|--merged=*|--no-merged=*|--points-at=*|--sort=*|--format=*|--abbrev=*|--column=*|--color=*)
        : ;;
      -*) printf '등급 미상'; return 0 ;;
      # Options accounted for and a word left over: it is a branch NAME, and
      # naming one here creates it.
      *) printf '워크트리쓰기'; return 0 ;;
    esac
  done
  # A value-taking option with nothing after it is malformed, and this table
  # refuses rather than guesses.
  [ "$want" = 1 ] && { printf '등급 미상'; return 0; }
  printf '읽기'
}

surface_of_git_config() {
  # Two axes multiply here — the OPERATION (query or write) and the SCOPE (in
  # the tree or outside it) — so no single list decides the grade.
  #
  # A `git config` not spelled as an explicit query grades as a write, and that
  # over-grade is deliberate. This table sees argv alone, so `git config
  # --global user.name` (a query) and `git config --global user.name x` (a
  # write) differ by one word, and deciding on word COUNT would hang the whole
  # grade on details like whether `-f` consumed the next one. Of the two ways to
  # be wrong, demanding authorization for a query costs a line in the manifest,
  # while letting a rewrite of $HOME through as a read is the hole this repair
  # exists to close. A query spelled with `--get` still grades exactly `읽기`,
  # so the form the pipeline actually runs loses nothing.
  local a skip=1 want=0 scope='' query=0
  for a in "$@"; do
    # The first word is `config` itself.
    if [ "$skip" = 1 ]; then skip=0; continue; fi
    if [ "$want" = 1 ]; then want=0; continue; fi
    case "$a" in
      --get|--get-all|--get-regexp|--get-urlmatch|--get-color|--get-colorbool|-l|--list)
        query=1 ;;
      --global|--system)  scope='트리밖쓰기' ;;
      --file|-f)          scope='트리밖쓰기'; want=1 ;;
      --file=*)           scope='트리밖쓰기' ;;
      --local|--worktree) : ;;
      -*) printf '등급 미상'; return 0 ;;
      # A key or a value. Neither decides anything on its own — the options
      # above already did.
      *) : ;;
    esac
  done
  [ "$want" = 1 ] && { printf '등급 미상'; return 0; }
  [ "$query" = 1 ] && { printf '읽기'; return 0; }
  printf '%s' "${scope:-워크트리쓰기}"
}

surface_of_gh() {
  # `-R/--repo` rides BEFORE the verb, so it is skipped by name — otherwise
  # `gh -R o/r pr view` reads `-R` as the group and grades unknown, and
  # `gh pr -R o/r view` reads `-R` as the verb (see `gate_gh_strip_repo`).
  # A merge is found by the parse before any word is read by position, so a
  # value flag ahead of the verb (`gh pr -b x merge 1`) grades as the merge it
  # is (see `gate_gh_pr_merge_kind`).
  case "$(gate_gh_pr_merge_kind "$@")" in
    merge) printf '외부상태변경'; return 0 ;;
    form)  printf '%s' "$GATE_FORM_UNKNOWN"; return 0 ;;
  esac
  gate_gh_strip_repo "$@"
  [ "$GATE_GH_API_UNREAD" = 0 ] || { printf '%s' "$GATE_FORM_UNKNOWN"; return 0; }
  set -- ${GATE_GH_ARGV[@]+"${GATE_GH_ARGV[@]}"}
  case "${1:-}" in
    -R|--repo) printf '%s' "$GATE_FORM_UNKNOWN"; return 0 ;;
  esac
  # `--web` and its short spelling open a BROWSER, which is a program this table
  # cannot answer for. Refused as a form wherever it appears, before the verb is
  # read: `gh pr view -w` is not the read that `gh pr view` is.
  case " $* " in
    *" --web "*) printf '%s' "$GATE_FORM_UNKNOWN"; return 0 ;;
  esac
  case "${1:-}" in
    pr|issue|run|workflow|repo|release|project|label|cache|secret|ssh-key|gpg-key|variable|gist|config|alias|ruleset|org|search|status|browse|codespace|extension)
      case " $* " in
        *" -w "*) printf '%s' "$GATE_FORM_UNKNOWN"; return 0 ;;
      esac ;;
  esac
  case "${1:-}" in
    api) surface_of_gh_api "$@" ;;
    # THE READ VERBS OF EACH GROUP, enumerated positively. Blanket-grading a
    # group by its noun is what made `gh pr view`, `gh issue list` and `gh run
    # view` issue approvals — 12 of the 13 recoverable act approvals in the
    # corpus were exactly these three shapes.
    pr)
      case "${2:-}" in
        list|view|status|diff|checks) printf '읽기' ;;
        checkout) printf '워크트리쓰기' ;;
        '') printf '%s' "$GATE_FORM_UNKNOWN" ;;
        *) printf '외부상태변경' ;;
      esac ;;
    issue)
      case "${2:-}" in
        list|view|status) printf '읽기' ;;
        develop) case " $* " in *" --list "*) printf '읽기' ;; *) printf '외부상태변경' ;; esac ;;
        '') printf '%s' "$GATE_FORM_UNKNOWN" ;;
        *) printf '외부상태변경' ;;
      esac ;;
    run)
      case "${2:-}" in
        list|view|watch) printf '읽기' ;;
        download) printf '트리밖쓰기' ;;
        '') printf '%s' "$GATE_FORM_UNKNOWN" ;;
        *) printf '외부상태변경' ;;
      esac ;;
    workflow)
      case "${2:-}" in
        list|view) printf '읽기' ;;
        '') printf '%s' "$GATE_FORM_UNKNOWN" ;;
        *) printf '외부상태변경' ;;
      esac ;;
    repo)
      case "${2:-}" in
        list|view) printf '읽기' ;;
        set-default) case " $* " in *" --view "*) printf '읽기' ;; *) printf '워크트리쓰기' ;; esac ;;
        clone) printf '트리밖쓰기' ;;
        '') printf '%s' "$GATE_FORM_UNKNOWN" ;;
        *) printf '외부상태변경' ;;
      esac ;;
    release)
      case "${2:-}" in
        list|view) printf '읽기' ;;
        download) printf '트리밖쓰기' ;;
        '') printf '%s' "$GATE_FORM_UNKNOWN" ;;
        *) printf '외부상태변경' ;;
      esac ;;
    project)
      case "${2:-}" in
        list|view|field-list|item-list) printf '읽기' ;;
        '') printf '%s' "$GATE_FORM_UNKNOWN" ;;
        *) printf '외부상태변경' ;;
      esac ;;
    label|cache|secret|ssh-key|gpg-key)
      case "${2:-}" in
        list) printf '읽기' ;;
        '') printf '%s' "$GATE_FORM_UNKNOWN" ;;
        *) printf '외부상태변경' ;;
      esac ;;
    variable)
      case "${2:-}" in
        list|get) printf '읽기' ;;
        '') printf '%s' "$GATE_FORM_UNKNOWN" ;;
        *) printf '외부상태변경' ;;
      esac ;;
    gist)
      case "${2:-}" in
        list|view) printf '읽기' ;;
        clone) printf '트리밖쓰기' ;;
        '') printf '%s' "$GATE_FORM_UNKNOWN" ;;
        *) printf '외부상태변경' ;;
      esac ;;
    config)
      case "${2:-}" in
        get|list) printf '읽기' ;;
        '') printf '%s' "$GATE_FORM_UNKNOWN" ;;
        *) printf '트리밖쓰기' ;;
      esac ;;
    alias)
      case "${2:-}" in
        list) printf '읽기' ;;
        '') printf '%s' "$GATE_FORM_UNKNOWN" ;;
        *) printf '트리밖쓰기' ;;
      esac ;;
    ruleset)
      case "${2:-}" in
        list|view|check) printf '읽기' ;;
        '') printf '%s' "$GATE_FORM_UNKNOWN" ;;
        *) printf '외부상태변경' ;;
      esac ;;
    org)
      case "${2:-}" in
        list) printf '읽기' ;;
        '') printf '%s' "$GATE_FORM_UNKNOWN" ;;
        *) printf '외부상태변경' ;;
      esac ;;
    search|status) printf '읽기' ;;
    # `project` sits beside `issue` because filing an issue and putting it on the
    # board are one obligation, not two. A run that files the issue and then
    # cannot reach the board leaves the tracking half-done in the direction that
    # hides itself: the issue exists, so nothing looks missing, and it is absent
    # from the only place the items are enumerated. Measured — three issues were
    # filed and all three `item-add` calls came back `등급 미상`.
    # `auth status` and `auth token` READ the credential and are graded as reads
    # — what makes them safe is not the grade but the `비밀출력` mark, which
    # parks the token-printing forms whatever their grade. The rest of `auth`
    # rewrites the credential the whole separation rests on, so it stays unknown:
    # an act that reached it would be editing the thing that limits it.
    auth)
      case "${2:-}" in
        status|token) printf '읽기' ;;
        *) printf '등급 미상' ;;
      esac ;;
    *) printf '등급 미상' ;;
  esac
}

surface_of_gh_api() {
  # `gh api` is graded by the HTTP METHOD it will send, not by the word `api`.
  # Grading the subcommand made a read of a pull request's review threads
  # indistinguishable from a merge and refused both — which took away the only
  # spelling that submits several inline comments as ONE review
  # (`POST …/pulls/{n}/reviews`; `gh pr review` carries no comments array), and
  # every read of a value `gh pr view --json` does not expose along with it.
  #
  # The method is the one `gate_gh_api_parse` reads — an explicit method wins,
  # otherwise a body is what makes gh switch from GET to POST. This table kept a
  # reading of its own, and it drifted: `-iXPUT` and `--raw-field=k=v` were a
  # GET here while the merge ladder read a merge, and a read is passed before
  # the reach cells are looked at.
  shift
  gate_gh_api_parse "$@"
  case "$GATE_GHAPI_METHOD" in
    GET|get|HEAD|head) printf '읽기' ;;
    *) printf '외부상태변경' ;;
  esac
}

# ---------------------------------------------------------------------------
# The permission RUNG argv itself claims — a second reading of the same argv,
# answering a different question from the grading table above.
#
# Axis 2 asks "how far out of this worktree does this reach"; this asks "which
# rung of the permission ladder does this climb". They are orthogonal: `gh pr
# merge` and `curl` share the `외부상태변경` cell and only one of them is a merge.
#
# THE RETURN IS A `CUTPOINTS` TOKEN OR THE EMPTY STRING, and never an integer and
# never a `등급 미상`-shaped sentinel. An integer would put a copy of the ladder's
# ORDER here, which is the drift `gate_export_cutpoints` already refuses on the
# checkers' behalf. A sentinel is worse: to be comparable it would have to enter
# `CUTPOINTS`, and then every caller of `cutpoint_index` — seventeen of them
# across this file and `run.sh` — acquires an exception. The empty string asserts
# nothing and needs no rung, so the comparison below simply does not run.
#
# THE DEFAULT IS SILENCE, AND IT POINTS THE OPPOSITE WAY FROM THE GRADING TABLE.
# That table answers `등급 미상` to what it does not recognize and the gate
# refuses, because guessing low there is the laundering it exists to stop. Here
# guessing HIGH is what costs: an over-derivation is a refusal the run cannot
# widen — `리뷰-후-머지` is a refusal and not a delay — so a wrong high answer
# bricks the night, while the empty string falls back to the declared value,
# which is exactly today's behaviour.
#
# WHAT THIS TABLE DELIBERATELY STAYS SILENT ABOUT, and the silence is load-bearing.
# `git push`, `git merge` and `git branch` have no row. A refspec's destination
# decides whether a push IS the merge, and knowing that means reading the
# manifest's target row — which this table does not do and must not start doing,
# because it runs before target resolution. Worse, guessing `push` for them turns
# an honestly declared `--cutpoint 머지` into an OVER-declaration and drags the
# effective rung DOWN below the merge rung, switching off the review rule and the
# obligation issuer for the very act they exist to cover.
# ---------------------------------------------------------------------------
# 형태 미상 — an INTERNAL token, and never a grade a caller may declare.
#
# It separates "this tool has never been in the table" (`등급 미상`, which the
# declaration path may rescue) from "this IS a table tool and the form hides
# what it does" (this token, which nothing rescues). Without the split, a
# `curl --x -X POST` whose option the parser could not read fell to the unknown
# arm and could then be declared `읽기` and performed — the table's own
# ignorance turned into a passing claim.
# ---------------------------------------------------------------------------
readonly GATE_FORM_UNKNOWN='형태 미상'

surface_of_aws() {
  # Global value options come before the service name and may sit anywhere, so
  # they are skipped by NAME rather than by position — `aws --profile p ssm …`
  # put `--profile` in the slot the service is read from and the whole call
  # graded `등급 미상`.
  while [ $# -gt 0 ]; do
    case "$1" in
      --profile|--region|--output|--query|--endpoint-url|--color|--ca-bundle|--cli-read-timeout|--cli-connect-timeout|--cli-binary-format)
        [ $# -ge 2 ] || { printf '%s' "$GATE_FORM_UNKNOWN"; return 0; }
        shift 2 ;;
      --profile=*|--region=*|--output=*|--query=*|--endpoint-url=*|--color=*|--ca-bundle=*|--cli-read-timeout=*|--cli-connect-timeout=*|--cli-binary-format=*)
        shift ;;
      --no-verify-ssl|--no-paginate|--debug|--no-cli-pager|--cli-auto-prompt|--no-cli-auto-prompt|--no-sign-request)
        shift ;;
      -*) printf '%s' "$GATE_FORM_UNKNOWN"; return 0 ;;
      *)  break ;;
    esac
  done
  local svc="${1:-}" op="${2:-}"
  case "$svc" in
    s3)
      case "$op" in
        ls|presign) printf '읽기' ;;
        cp|sync)
          # The destination decides it. A `--dryrun` performs nothing at all, a
          # copy INTO `s3://` changes external state, and a copy out of it writes
          # a local file — one name cannot carry the three.
          case " $* " in *" --dryrun "*|*" --dry-run "*) printf '읽기'; return 0 ;; esac
          local last=""; local a
          for a in "$@"; do case "$a" in -*) ;; *) last="$a" ;; esac; done
          case "$last" in s3://*) printf '외부상태변경' ;; *) printf '트리밖쓰기' ;; esac ;;
        mv|rm|rb|mb|website) printf '외부상태변경' ;;
        *) printf '등급 미상' ;;
      esac ;;
    s3api)
      case "$op" in
        get-object|get-object-torrent|select-object-content) printf '트리밖쓰기' ;;
        list-*|head-*|get-*) printf '읽기' ;;
        *) printf '외부상태변경' ;;
      esac ;;
    configure)
      case "$op" in
        list|get|list-profiles|export-credentials) printf '읽기' ;;
        set|add-model|import) printf '트리밖쓰기' ;;
        *) printf '등급 미상' ;;
      esac ;;
    # `sso` and `login` write credential caches and open browsers; neither is a
    # read and neither is one effect this table can name from the verb alone.
    sso|login) printf '등급 미상' ;;
    lambda)
      case "$op" in
        invoke) printf '외부상태변경' ;;
        list-*|get-*) printf '읽기' ;;
        *) printf '외부상태변경' ;;
      esac ;;
    '') printf '%s' "$GATE_FORM_UNKNOWN" ;;
    *)
      # The operation name carries the effect for the rest of the API surface.
      # Read-shaped prefixes are enumerated POSITIVELY and everything else is an
      # external change: a new service whose verbs nobody here has seen must not
      # inherit the safest answer.
      case "$op" in
        describe-*|list-*|get-*|head-*|lookup-*|search-*|batch-get-*|filter-*|simulate-*|validate-*)
          printf '읽기' ;;
        wait|tail|scan|query|help) printf '읽기' ;;
        '') printf '%s' "$GATE_FORM_UNKNOWN" ;;
        *) printf '외부상태변경' ;;
      esac ;;
  esac
}

surface_of_curl() {
  # The METHOD decides the grade, and it is not always spelled. An explicit `-X`
  # wins; otherwise a body option means POST, `-I` means HEAD, and everything
  # else is a GET. An output-file option raises the floor to a write wherever
  # the method lands, because the response is put on disk either way.
  local method="" body=0 head=0 out=0 i
  while [ $# -gt 0 ]; do
    case "$1" in
      -X|--request)
        [ $# -ge 2 ] || { printf '%s' "$GATE_FORM_UNKNOWN"; return 0; }
        method="$2"; shift 2 ;;
      --request=*) method="${1#--request=}"; shift ;;
      -d|--data|--data-raw|--data-binary|--data-urlencode|--data-ascii|-F|--form|--form-string|-T|--upload-file)
        [ $# -ge 2 ] || { printf '%s' "$GATE_FORM_UNKNOWN"; return 0; }
        body=1; shift 2 ;;
      --data=*|--data-raw=*|--data-binary=*|--data-urlencode=*|--form=*|--upload-file=*)
        body=1; shift ;;
      -I|--head) head=1; shift ;;
      -G|--get) body=0; shift ;;
      -o|--output|-D|--dump-header|-c|--cookie-jar|--trace|--trace-ascii|--stderr|--etag-save|--hsts|--alt-svc|--libcurl|--output-dir|--create-dirs)
        [ $# -ge 2 ] || { printf '%s' "$GATE_FORM_UNKNOWN"; return 0; }
        out=1; shift 2 ;;
      --output=*|--dump-header=*|--cookie-jar=*|--trace=*|--output-dir=*) out=1; shift ;;
      -O|--remote-name|-J|--remote-header-name) out=1; shift ;;
      -w|--write-out)
        [ $# -ge 2 ] || { printf '%s' "$GATE_FORM_UNKNOWN"; return 0; }
        case "$2" in *'%output{'*) out=1 ;; esac
        shift 2 ;;
      # Options that make curl read its argv from elsewhere, or that this parser
      # has no table for. Refused as a form rather than guessed at — `-K` alone
      # can carry a whole other request.
      -K|--config|--next|--variable|--expand-*) printf '%s' "$GATE_FORM_UNKNOWN"; return 0 ;;
      -H|--header|-u|--user|-A|--user-agent|-e|--referer|-b|--cookie|--url|--retry|--max-time|--connect-timeout|--resolve|--cacert|--cert|--key|--proxy|-x)
        [ $# -ge 2 ] || { printf '%s' "$GATE_FORM_UNKNOWN"; return 0; }
        shift 2 ;;
      -s|-S|-k|-L|-v|-f|--silent|--show-error|--insecure|--location|--verbose|--fail|--compressed|--no-progress-meter|-i|--include)
        shift ;;
      # AN UNRECOGNIZED OPTION IS A FORM THIS PARSER CANNOT READ, not a word to
      # skip. Skipping it silently is how `curl --x -X POST` graded as an
      # ordinary POST — and, declared `읽기`, would have been performed: the one
      # spelling this token exists to refuse.
      --*) printf '%s' "$GATE_FORM_UNKNOWN"; return 0 ;;
      -?*)
        # A short-option bundle: every letter is read, because one of them may be
        # the letter that decides the method — and an unknown letter refuses the
        # whole form for the same reason the long arm above does.
        local flags="${1#-}"
        while [ -n "$flags" ]; do
          case "$flags" in
            I*) head=1 ;;
            O*|J*) out=1 ;;
            G*) body=0 ;;
            [sSkLvfing46]*) ;;
            *) printf '%s' "$GATE_FORM_UNKNOWN"; return 0 ;;
          esac
          flags="${flags#?}"
        done
        shift ;;
      *)
        case "$1" in
          http://*|https://*|file://*) ;;
          *://*) printf '%s' "$GATE_FORM_UNKNOWN"; return 0 ;;
        esac
        shift ;;
    esac
  done
  [ -n "$method" ] || { if [ "$head" = "1" ]; then method=HEAD; elif [ "$body" = "1" ]; then method=POST; else method=GET; fi; }
  case "$method" in
    GET|HEAD|get|head)
      [ "$out" = "1" ] && { printf '트리밖쓰기'; return 0; }
      printf '읽기' ;;
    *) printf '외부상태변경' ;;
  esac
}

surface_of_kubectl() {
  while [ $# -gt 0 ]; do
    case "$1" in
      --context|--namespace|-n|--kubeconfig|--cluster|--user|--server|--token|--as|--as-group|--request-timeout|--kube-context)
        [ $# -ge 2 ] || { printf '%s' "$GATE_FORM_UNKNOWN"; return 0; }
        shift 2 ;;
      --context=*|--namespace=*|--kubeconfig=*|--cluster=*|--user=*|--server=*|--token=*|--as=*|--request-timeout=*|--kube-context=*)
        shift ;;
      --insecure-skip-tls-verify|-v|--v=*) shift ;;
      -*) printf '%s' "$GATE_FORM_UNKNOWN"; return 0 ;;
      *)  break ;;
    esac
  done
  case "${1:-}" in
    get|describe|logs|top|events|diff|wait|explain|api-resources|api-versions|version|cluster-info|help|completion|options)
      printf '읽기' ;;
    auth)
      case "${2:-}" in
        can-i|whoami) printf '읽기' ;;
        *) printf '외부상태변경' ;;
      esac ;;
    rollout)
      case "${2:-}" in
        status|history) printf '읽기' ;;
        *) printf '외부상태변경' ;;
      esac ;;
    config)
      case "${2:-}" in
        view|get-contexts|current-context|get-clusters|get-users) printf '읽기' ;;
        *) printf '트리밖쓰기' ;;
      esac ;;
    apply|create|replace|patch|edit|delete|scale|autoscale|set|label|annotate|taint|cordon|uncordon|drain|expose|run|exec|attach|cp|port-forward|proxy|debug|certificate)
      printf '외부상태변경' ;;
    # An unrecognized verb is a `kubectl-<verb>` PLUGIN — an arbitrary program on
    # PATH — so it is unknown rather than an external change: the declaration
    # path is where a caller says what their own plugin does.
    *) printf '등급 미상' ;;
  esac
}

surface_of_docker() {
  case "${1:-}" in
    ps|images|inspect|logs|top|history|port|diff|events|search|stats|version|info)
      printf '읽기' ;;
    system)
      case "${2:-}" in
        df|info|events) printf '읽기' ;;
        *) printf '트리밖쓰기' ;;
      esac ;;
    image|container|volume|network|node|service|secret|config|context|builder|buildx|manifest)
      case "${2:-}" in
        ls|list|inspect) printf '읽기' ;;
        push) printf '외부상태변경' ;;
        *)
          case " $* " in *" --push "*) printf '외부상태변경'; return 0 ;; esac
          if gate_docker_output_pushes "$@"; then printf '외부상태변경'; else printf '트리밖쓰기'; fi ;;
      esac ;;
    # THREE SPELLINGS OF A REGISTRY PUSH, and the top-level `build` fell to the
    # catch-all below with all three: `--push`, and an exporter whose value says
    # `type=registry` or `push=true`. Graded a local write, each passed as one.
    build)
      case " $* " in *" --push "*) printf '외부상태변경'; return 0 ;; esac
      if gate_docker_output_pushes "$@"; then printf '외부상태변경'; else printf '트리밖쓰기'; fi ;;
    compose)
      case "${2:-}" in
        ps|logs|config|ls|images|top|version|port) printf '읽기' ;;
        push) printf '외부상태변경' ;;
        *) printf '트리밖쓰기' ;;
      esac ;;
    save)
      # Writes only where told to; with no `-o` it goes to stdout.
      if gate_argv_has_opt -o output "$@"; then printf '트리밖쓰기'; else printf '읽기'; fi ;;
    push) printf '외부상태변경' ;;
    '') printf '%s' "$GATE_FORM_UNKNOWN" ;;
    *) printf '트리밖쓰기' ;;
  esac
}

gate_docker_output_pushes() {
  # gate_docker_output_pushes <argv after `docker`...> — true when an exporter
  # value (`--output=v`, `-o=v`, or `--output`/`-o` followed by v) sends the
  # build to a registry. It only ever raises a grade: a value that names a file
  # or a local exporter is left to the row it was already in.
  local a v next=0
  for a in "$@"; do
    if [ "$next" = 1 ]; then v="$a"; next=0
    else
      case "$a" in
        --) break ;;
        --output|-o) next=1; continue ;;
        --output=*) v="${a#--output=}" ;;
        -o=*) v="${a#-o=}" ;;
        *) continue ;;
      esac
    fi
    case "$v" in *type=registry*|*push=true*) return 0 ;; esac
  done
  return 1
}

surface_of_brew() {
  # surface_of_brew <argv after `brew`...>. A verb that changes what is installed
  # on this machine writes outside the tree; a verb that only reports is a read.
  # EVERY OTHER VERB STAYS `등급 미상`, not the form-unknown token: that token is
  # refused before the declaration is even read, which would turn `brew update`
  # and `brew shellenv` from passing on their declaration into refusals — and
  # the merge-time grade probe skips an argv whose base grade is `등급 미상`, so
  # it could not see that narrowing either.
  case "${1:-}" in
    install|upgrade|uninstall|remove|rm|reinstall|tap|untap|link|unlink|pin|unpin|cleanup|autoremove|services)
      printf '트리밖쓰기' ;;
    list|ls|info|search|deps|uses|outdated|leaves|desc|home|config|doctor|--prefix|--version|--cellar|--repository)
      printf '읽기' ;;
    *) printf '등급 미상' ;;
  esac
}

# ---------------------------------------------------------------------------
# 표지 — two marks the grade cannot carry, because they cut ACROSS it.
#
# `비밀출력` is a read whose output is a credential; `파괴` is a write whose
# effect cannot be undone by writing again. Both are decided from argv alone and
# from a NARROW list: a mark that fires on a guess would park ordinary work, and
# the whole value of the two is that they are believable when they fire.
#
# Output is `<표지>\t<트리거 단어>`. The trigger rides along because the
# pre-authorization matcher needs to ask whether the row that authorized the act
# named THIS destructive word — a shape that carries the mark but a different
# word is not authorization for this one.
# ---------------------------------------------------------------------------

# The answer with no mark, for the unwrap terminals below. Built with `printf`
# for the reason `GATE_FLOOR_NONE` gives.
GATE_MARK_NONE=$(printf '\t')
readonly GATE_MARK_NONE

gate_answer_mark_max() {
  # The stronger of two `<표지>\t<트리거>` answers: `비밀출력`, then `파괴`, then
  # none. The fold for a `find` whose primaries are marked one by one.
  local am="${1%%	*}" bm="${2%%	*}"
  case "$bm" in
    비밀출력) [ "$am" = "비밀출력" ] || { printf '%s' "$2"; return 0; } ;;
    파괴) [ -z "$am" ] && { printf '%s' "$2"; return 0; } ;;
  esac
  printf '%s' "$1"
}

gate_act_mark() {
  local cmd="${1##*/}"; shift 2>/dev/null || true
  local all=" $* "

  # ---- 래퍼 -------------------------------------------------------------
  # THE SAME PEEL THE GRADE AND THE OPAQUE AXIS APPLY, with the same unwraps.
  # This axis asked for argv0 once and stopped, so `lockf -k <lock> aws ssm
  # get-parameter --with-decryption` carried no `비밀출력` while its bare
  # spelling did, and the floor's rescue runs only for an opaque or ungraded
  # argv — a wrapped `aws` is neither. `xargs` and `sudo` stay unpeeled for the
  # reason `gate_argv_opaque` gives; both grade `등급 미상`, so the floor scans
  # their payload and recovers the mark there.
  case "$cmd" in
    lockf)   gate_unwrap_lockf   gate_act_mark "$GATE_MARK_NONE" "$GATE_MARK_NONE" "$@"; return 0 ;;
    command) gate_unwrap_command gate_act_mark "$GATE_MARK_NONE" "$GATE_MARK_NONE" "$@"; return 0 ;;
    time)    gate_unwrap_time    gate_act_mark "$GATE_MARK_NONE" "$GATE_MARK_NONE" "$@"; return 0 ;;
    timeout|nice|nohup|stdbuf)
      gate_unwrap_wrapper "$cmd" gate_act_mark "$GATE_MARK_NONE" "$GATE_MARK_NONE" "$@"; return 0 ;;
    find)
      gate_unwrap_find gate_act_mark "$GATE_MARK_NONE" "$GATE_MARK_NONE" "$GATE_MARK_NONE" \
        gate_answer_mark_max "$@"; return 0 ;;
  esac

  # ---- git 전역 플래그 -----------------------------------------------------
  # git's subcommand is read where git reads it, past its global flags, and
  # the word match below covers only what follows the subcommand: `git -C <x>
  # push --force` and `git -c a=b credential fill` carried no mark while their
  # bare spellings did, and a global flag's value is not an option of the
  # subcommand.
  if [ "$cmd" = git ]; then
    gate_git_subcommand "$@" >/dev/null
    if [ "$GATE_GIT_SUBIDX" -gt 0 ]; then
      set -- "${@:$GATE_GIT_SUBIDX}"
      all=" ${*:2} "
    fi
  fi

  # ---- 비밀출력 -----------------------------------------------------------
  case "$cmd" in
    gh)
      case "${1:-}:${2:-}" in
        auth:token) printf '비밀출력\ttoken'; return 0 ;;
      esac
      case "${1:-}:${2:-}" in
        auth:status)
          case "$all" in
            *" -t "*|*" --show-token "*) printf '비밀출력\t--show-token'; return 0 ;;
          esac ;;
      esac ;;
    aws)
      case "${1:-}" in
        ssm)
          case "${2:-}" in
            get-parameter|get-parameters|get-parameters-by-path|get-parameter-history)
              case "$all" in *" --with-decryption "*) printf '비밀출력\t--with-decryption'; return 0 ;; esac ;;
          esac ;;
        secretsmanager)
          case "${2:-}" in
            get-secret-value|batch-get-secret-value) printf '비밀출력\t%s' "$2"; return 0 ;;
          esac ;;
        sts)
          case "${2:-}" in
            get-session-token|get-federation-token|assume-role|assume-role-with-saml|assume-role-with-web-identity)
              printf '비밀출력\t%s' "$2"; return 0 ;;
          esac ;;
        ecr)
          case "${2:-}" in
            get-login-password|get-authorization-token) printf '비밀출력\t%s' "$2"; return 0 ;;
          esac ;;
        codeartifact)
          case "${2:-}" in get-authorization-token) printf '비밀출력\t%s' "$2"; return 0 ;; esac ;;
        eks)
          case "${2:-}" in get-token) printf '비밀출력\tget-token'; return 0 ;; esac ;;
        rds)
          case "${2:-}" in generate-db-auth-token) printf '비밀출력\tgenerate-db-auth-token'; return 0 ;; esac ;;
        iam)
          case "${2:-}" in create-access-key) printf '비밀출력\tcreate-access-key'; return 0 ;; esac ;;
        configure)
          case "${2:-}" in
            export-credentials) printf '비밀출력\texport-credentials'; return 0 ;;
            get)
              case "${3:-}" in
                aws_secret_access_key|aws_session_token) printf '비밀출력\t%s' "$3"; return 0 ;;
              esac ;;
          esac ;;
      esac ;;
    gcloud)
      case "${1:-}:${2:-}" in
        auth:print-access-token|auth:print-identity-token) printf '비밀출력\t%s' "$2"; return 0 ;;
      esac
      case "${1:-} ${2:-} ${3:-}" in
        'secrets versions access') printf '비밀출력\taccess'; return 0 ;;
      esac ;;
    kubectl)
      case "${1:-}" in
        get)
          case "${2:-}" in
            secret|secrets)
              # `-ojson` is the spelling people actually type, and the literal
              # match this replaces did not see it.
              if gate_argv_has_opt -o output "$@"; then printf '비밀출력\tsecret'; return 0; fi ;;
          esac ;;
        config)
          case "${2:-}" in
            view) case "$all" in *" --raw "*) printf '비밀출력\t--raw'; return 0 ;; esac ;;
          esac ;;
        create)
          case "${2:-}" in token) printf '비밀출력\ttoken'; return 0 ;; esac ;;
      esac ;;
    security)
      case "${1:-}" in
        find-generic-password|find-internet-password)
          case "$all" in *" -w "*|*" -g "*) printf '비밀출력\t%s' "$1"; return 0 ;; esac ;;
        dump-keychain)
          case "$all" in *" -d "*) printf '비밀출력\tdump-keychain'; return 0 ;; esac ;;
      esac ;;
    terraform)
      case "${1:-}" in
        output) case "$all" in *" -json "*|*" -raw "*) printf '비밀출력\toutput'; return 0 ;; esac ;;
        state)  case "${2:-}" in pull) printf '비밀출력\tpull'; return 0 ;; esac ;;
      esac ;;
    git)
      case "${1:-}:${2:-}" in credential:fill) printf '비밀출력\tfill'; return 0 ;; esac ;;
    op)
      case "${1:-}" in read) printf '비밀출력\tread'; return 0 ;; esac ;;
    vault)
      case "${1:-}" in
        read) printf '비밀출력\tread'; return 0 ;;
        kv) case "${2:-}" in get) printf '비밀출력\tget'; return 0 ;; esac ;;
      esac ;;
    # THE WHOLE ENVIRONMENT, PRINTED. The pipeline's own read-only token lives in
    # the environment of every act this gate runs — measured — so a bare `env` or
    # `printenv` puts it on stdout and into the stage transcript. Named variables
    # are fine and are the spelling the unattended skills are told to use; what
    # parks is the form that prints everything, and the form that names a
    # secret-shaped variable.
    env)
      local rest_has_cmd=0 a
      for a in "$@"; do
        case "$a" in
          -i|-0|-v|--) ;;
          -u) rest_has_cmd=0 ;;
          *=*) ;;
          -*) ;;
          *) rest_has_cmd=1; break ;;
        esac
      done
      [ "$rest_has_cmd" = "0" ] && { printf '비밀출력\tenv'; return 0; }
      # A command after the assignments: its own mark is the answer.
      gate_unwrap_env gate_act_mark "$GATE_MARK_NONE" "$GATE_MARK_NONE" "$@"; return 0 ;;
    printenv)
      [ "$#" -eq 0 ] && { printf '비밀출력\tprintenv'; return 0; }
      local n
      for n in "$@"; do
        case "$(printf '%s' "$n" | tr '[:lower:]' '[:upper:]')" in
          *TOKEN*|*SECRET*|*PASSWORD*|*PASSWD*|*PASSPHRASE*|*CREDENTIAL*|*PRIVATE_KEY*|*ACCESS_KEY*|*API_KEY*|*APIKEY*|*_KEY|*COOKIE*|*SESSION*|*AUTH*)
            printf '비밀출력\t%s' "$n"; return 0 ;;
        esac
      done ;;
    jq)
      case "$all" in
        *'$ENV'*|*' env '*|*'env.'*) printf '비밀출력\tenv'; return 0 ;;
      esac ;;
    cat|head|tail|less|more|strings|xxd|od|base64)
      local f
      for f in "$@"; do
        case "$f" in
          *"/.aws/credentials"|*"/.config/gh/hosts.yml"|*"/.netrc"|*"/.docker/config.json"|*"/.kube/config"|*"/.pgpass")
            printf '비밀출력\t%s' "$f"; return 0 ;;
          */.config/cc-cmds/*.env) printf '비밀출력\t%s' "$f"; return 0 ;;
          */.ssh/id_*.pub) ;;
          */.ssh/id_*) printf '비밀출력\t%s' "$f"; return 0 ;;
        esac
      done ;;
  esac

  # ---- 파괴 ---------------------------------------------------------------
  # `remove-*` and `stop-*` are deliberately absent: both name acts this tree
  # can undo by acting again, and a mark that fires on them would park ordinary
  # teardown.
  case "$cmd" in
    terraform)
      case "${1:-}" in
        destroy) printf '파괴\tdestroy'; return 0 ;;
        apply)
          case "$all" in
            *" -destroy "*) printf '파괴\t-destroy'; return 0 ;;
            *" -replace="*) printf '파괴\t-replace'; return 0 ;;
          esac ;;
        state) case "${2:-}" in rm) printf '파괴\trm'; return 0 ;; esac ;;
        workspace) case "${2:-}" in delete) printf '파괴\tdelete'; return 0 ;; esac ;;
      esac ;;
    aws)
      case "${1:-}" in
        s3)
          case "${2:-}" in
            rm|rb|mv) printf '파괴\t%s' "$2"; return 0 ;;
            sync) case "$all" in *" --delete "*) printf '파괴\t--delete'; return 0 ;; esac ;;
          esac ;;
      esac
      case "${2:-}" in
        *delet*|terminate-*|purge-*|deregister-*) printf '파괴\t%s' "$2"; return 0 ;;
      esac ;;
    kubectl)
      case "${1:-}" in
        delete|drain) printf '파괴\t%s' "$1"; return 0 ;;
        replace) case "$all" in *" --force "*) printf '파괴\t--force'; return 0 ;; esac ;;
        apply)   case "$all" in *" --prune "*) printf '파괴\t--prune'; return 0 ;; esac ;;
        scale)   case "$all" in *" --replicas=0 "*) printf '파괴\t--replicas=0'; return 0 ;; esac ;;
      esac ;;
    gcloud)
      local g
      for g in "$@"; do
        [ "$g" = "delete" ] && { printf '파괴\tdelete'; return 0; }
      done ;;
    gh)
      case "${2:-}" in
        delete|item-delete|field-delete) printf '파괴\t%s' "$2"; return 0 ;;
      esac
      # The method is the one `gate_gh_api_parse` reads, upper-cased: matched
      # as ` -X DELETE `, the spellings `--method=DELETE`, `-XDELETE` and
      # `-Xdelete` sent a DELETE with no mark. `api` is found past the flags
      # ahead of it (see `gate_gh_strip_repo`): read at the first position,
      # `gh --hostname=github.com api --method=DELETE …` carried no mark.
      gate_gh_strip_repo "$@"
      if [ "${GATE_GH_ARGV[0]:-}" = api ]; then
        gate_gh_api_parse "${GATE_GH_ARGV[@]:1}"
        case "$GATE_GHAPI_METHOD" in [Dd][Ee][Ll][Ee][Tt][Ee]) printf '파괴\tDELETE'; return 0 ;; esac
      fi ;;
    curl)
      case "$all" in
        *" -X DELETE "*|*" --request DELETE "*|*" --request=DELETE "*) printf '파괴\tDELETE'; return 0 ;;
      esac ;;
    git)
      case "${1:-}" in
        push)
          case "$all" in
            *" -f "*|*" --force "*) printf '파괴\t--force'; return 0 ;;
            *" --force-with-lease"*) printf '파괴\t--force-with-lease'; return 0 ;;
            *" --delete "*|*" -d "*) printf '파괴\t--delete'; return 0 ;;
            *" --mirror "*) printf '파괴\t--mirror'; return 0 ;;
            *" --prune "*) printf '파괴\t--prune'; return 0 ;;
          esac
          local r
          for r in "$@"; do
            case "$r" in
              +*) printf '파괴\t%s' "$r"; return 0 ;;
              :*) printf '파괴\t%s' "$r"; return 0 ;;
            esac
          done ;;
      esac ;;
    docker)
      # The subcommand is read past docker's global options, so a leading
      # `--context default` or `-H unix://…` does not hide `system prune`.
      local _dn; _dn=$(gate_docker_globals "$@"); _dn=${_dn%%	*}
      [ "$_dn" -gt 0 ] && shift "$_dn"
      case "${1:-}" in
        rm|rmi|prune) printf '파괴\t%s' "$1"; return 0 ;;
        volume) case "${2:-}" in rm|prune) printf '파괴\t%s' "$2"; return 0 ;; esac ;;
        # The management-group spellings of the same removals carry the same
        # mark, so the grouped form is not the unmarked way to delete an image.
        image|container) case "${2:-}" in rm|prune) printf '파괴\t%s' "$2"; return 0 ;; esac ;;
        system|builder|buildx) case "${2:-}" in prune) printf '파괴\tprune'; return 0 ;; esac ;;
        compose) case "${2:-}" in down) case "$all" in *" -v "*|*" --volumes "*) printf '파괴\t-v'; return 0 ;; esac ;; esac ;;
      esac ;;
    rsync)
      case "$all" in
        *" --delete"*) printf '파괴\t--delete'; return 0 ;;
        *" --remove-source-files "*) printf '파괴\t--remove-source-files'; return 0 ;;
      esac ;;
    dropdb) printf '파괴\tdropdb'; return 0 ;;
    mysqladmin)
      case "$all" in *" drop "*) printf '파괴\tdrop'; return 0 ;; esac ;;
    redis-cli)
      case "$all" in *" flushall "*|*" flushdb "*) printf '파괴\tflush'; return 0 ;; esac ;;
    psql|mysql)
      # The statement text, when it rides in argv at all. A statement arriving on
      # stdin is invisible here and is the residual the design records.
      case "$(printf '%s' "$all" | tr '[:upper:]' '[:lower:]')" in
        *"drop "*)        printf '파괴\tdrop'; return 0 ;;
        *"truncate "*)    printf '파괴\ttruncate'; return 0 ;;
        *"delete from"*)  printf '파괴\tdelete'; return 0 ;;
      esac ;;
  esac
  printf '\t'
}

# The opaque runners — argv0 names a program that runs SOMETHING ELSE, and the
# table cannot see what. The list is exactly the names the table already pins to
# `워크트리쓰기`, plus the docker forms that start a container; an interpreter
# the table has never listed (`dash`, `python`, `perl`) is not opaque, it is
# unknown, and it keeps taking the unknown path in both modes.
#
# THE REGISTERED WRAPPERS ARE PEELED FIRST, with the table's own helpers. This
# axis asked `case "${1##*/}"` once and stopped, so a wrapper in front of an
# interpreter answered 0 — and 0 is not a small error here: the floor and the
# mark are computed only when this answers 1, so `lockf -k -t 0 <lock> sh -c
# 'curl …'` lost the `외부상태변경` floor its bare spelling gets and a declared
# `워크트리쓰기` was accepted for a network act. With `aws … --with-decryption`
# inside, the `비밀출력` mark went with it, and that mark is a value the
# pre-authorization reads. The grading table's own `lockf` row already refuses
# this laundering in so many words; this axis was the one seam it was still open
# at. `xargs` and `sudo` stay unpeeled here for the reason the table gives: what
# they run is not a word this file can honestly read.
gate_argv_opaque() {
  local cmd="${1##*/}"; shift 2>/dev/null || true
  case "$cmd" in
    lockf)   gate_unwrap_lockf   gate_argv_opaque '0' '1' "$@"; return 0 ;;
    command) gate_unwrap_command gate_argv_opaque '0' '1' "$@"; return 0 ;;
    rg)      gate_unwrap_rg      gate_argv_opaque '0' '1' "$@"; return 0 ;;
    env)     gate_unwrap_env     gate_argv_opaque '0' '1' "$@"; return 0 ;;
    time)    gate_unwrap_time    gate_argv_opaque '0' '1' "$@"; return 0 ;;
    timeout|nice|nohup|stdbuf)
      gate_unwrap_wrapper "$cmd" gate_argv_opaque '0' '1' "$@"; return 0 ;;
    # A shape that cannot be read is opaque rather than transparent, which is
    # why `find`'s unreadable answer here is `1` and not the table's token.
    find)    gate_unwrap_find    gate_argv_opaque '0' '0' '1' gate_answer_or "$@"; return 0 ;;
  esac
  case "$cmd" in
    bash|sh|zsh|python3|node|make|npm|npx|yarn|pnpm|pytest|go|cargo)
      # The named arms are not opaque: `npm publish` and `go version` say what
      # they do, and the grading table answers them directly.
      case "$cmd:${1:-}" in
        npm:publish|yarn:publish|pnpm:publish|cargo:publish|go:install|cargo:install) printf 0; return 0 ;;
        npm:view|npm:info|npm:show|npm:ls|npm:list|npm:outdated|npm:ping|npm:search|npm:explain|npm:why|go:version|go:env) printf 0; return 0 ;;
      esac
      printf 1 ;;
    docker)
      case "${1:-}" in
        run|exec|start|create|attach|restart) printf 1 ;;
        compose)
          case "${2:-}" in
            up|run|exec|start|restart|create) printf 1 ;;
            *) printf 0 ;;
          esac ;;
        *) printf 0 ;;
      esac ;;
    *) printf 0 ;;
  esac
}

# ---------------------------------------------------------------------------
# 하한 — what the gate can still SEE inside a command it cannot grade.
#
# A misuse detector, not a parser. It is quote-blind by construction, so a
# recognizable command named inside a string raises the floor even when the
# shell would have treated it as an argument. That direction is the safe one:
# the cost of a false positive is a refusal the caller answers by declaring
# honestly, and the cost of a false negative is an external act recorded as a
# worktree write. Measured on the corpus: of 41 distinct calls whose floor came
# back `외부상태변경`, at least 30 were real external acts laundered through
# `sh -c` and at most 8 were false positives.
#
# What it does NOT see is written down rather than implied: `eval`, a command
# held in a variable, `source`, a function or alias, and the contents of any
# script file. Those are the residual the design records, and the boundary that
# holds there is the credential split and the declaration ceiling.
#
# Output is `<하한>\t<표지>\t<트리거>`.
# ---------------------------------------------------------------------------

# That shape with nothing in it. Built with `printf` rather than written with
# two literal tabs so the two empty fields stay visible to a reader.
GATE_FLOOR_NONE=$(printf '읽기\t\t')
readonly GATE_FLOOR_NONE

gate_answer_floor_max() {
  # The fold for two `<하한>\t<표지>\t<트리거>` triples: the higher floor and the
  # stronger mark. `비밀출력` outranks `파괴` for the reason this function's
  # caller gives — a disclosure cannot be taken back once printed.
  local ar="${1#*	}" br="${2#*	}"
  local f m t bm bt
  f=$(gate_surface_max "${1%%	*}" "${2%%	*}")
  m="${ar%%	*}"; t="${ar#*	}"
  bm="${br%%	*}"; bt="${br#*	}"
  case "$bm" in
    비밀출력) m="$bm"; t="$bt" ;;
    파괴) [ "$m" = "비밀출력" ] || { m="$bm"; t="$bt"; } ;;
  esac
  printf '%s\t%s\t%s' "$f" "$m" "$t"
}

gate_opaque_floor() {
  local cmd="${1##*/}"; shift 2>/dev/null || true
  # THE SAME PEEL THE OPAQUE AXIS APPLIES, and it has to be here rather than
  # only there. `lockf -k -t 0 <lock> sh -c 'curl …'` has `-k` in the first word
  # position of the payload below, and the scanner skips a line whose first word
  # is an option — so even with the axis repaired the floor came back `읽기`.
  # What raises it is reaching `sh` as argv0, because only then is the `-c`
  # STRING read instead of the whole argument list. Both terminal answers are
  # "nothing readable", which is what the `*)` arm already answered for these
  # shapes.
  case "$cmd" in
    lockf)   gate_unwrap_lockf   gate_opaque_floor "$GATE_FLOOR_NONE" "$GATE_FLOOR_NONE" "$@"; return 0 ;;
    command) gate_unwrap_command gate_opaque_floor "$GATE_FLOOR_NONE" "$GATE_FLOOR_NONE" "$@"; return 0 ;;
    rg)      gate_unwrap_rg      gate_opaque_floor "$GATE_FLOOR_NONE" "$GATE_FLOOR_NONE" "$@"; return 0 ;;
    env)     gate_unwrap_env     gate_opaque_floor "$GATE_FLOOR_NONE" "$GATE_FLOOR_NONE" "$@"; return 0 ;;
    time)    gate_unwrap_time    gate_opaque_floor "$GATE_FLOOR_NONE" "$GATE_FLOOR_NONE" "$@"; return 0 ;;
    timeout|nice|nohup|stdbuf)
      gate_unwrap_wrapper "$cmd" gate_opaque_floor "$GATE_FLOOR_NONE" "$GATE_FLOOR_NONE" "$@"; return 0 ;;
    # A write primary (`-delete`, `-fprint` …) is a worktree write whatever
    # stands beside it, so that terminal is not "nothing readable".
    find)
      gate_unwrap_find gate_opaque_floor_find_inner "$GATE_FLOOR_NONE" "$(printf '워크트리쓰기\t\t')" \
        "$GATE_FLOOR_NONE" gate_answer_floor_max "$@"; return 0 ;;
  esac
  local payload="" shell_push=0
  case "$cmd" in
    bash|sh|zsh|dash|ksh)
      # ONLY the `-c` string. A script FILE operand is not scanned — its bytes
      # are not in argv, and pretending to have read them would be the kind of
      # confident wrong answer this whole table refuses. The string is found
      # the way the push reader finds it, so `-c --`, `-ec` and `-c -e` reach
      # it: reading only an exact `-c` and the word after it scanned `--` and
      # left `bash -c -- 'git push …'` at `읽기`.
      #
      # A STRING THE PUSH READER TAKES FOR A PUSH IS AT LEAST `외부상태변경`,
      # whatever the command positions below read. They split at `&` and
      # newlines and keep redirections glued to words, so `git 2>&1 push`,
      # `git push>/dev/null`, `git p\<newline>ush` and a push run through the
      # string's positional parameters read `읽기` there — and the floor is what
      # an under-declaration of the shell is compared against.
      payload=$(gate_push_shell_payload "$@")
      gate_push_text_has_push "$payload" && shell_push=1 ;;
    # The wrappers that assemble a command line out of their own arguments, and
    # the table-less argv0 whose operands may name one. `docker run` is
    # deliberately absent: its image name is a word like `mysql`, and reading
    # that as a database client would park every container the pipeline starts.
    xargs|sudo|npx) payload="$*" ;;
    docker) payload="" ;;
    *) payload="$*" ;;
  esac
  [ -n "$payload" ] || { printf '읽기\t\t'; return 0; }

  # Heredoc bodies are dropped before the split: their text is DATA, and a SQL
  # heredoc naming `drop table` is not the shell running `drop`.
  payload=$(printf '%s' "$payload" | sed 's/<<[-~]*[A-Za-z_'"'"'"]*//g')

  # Quote removal before the command positions are read: `\git push`,
  # `'git' push` and `git${IFS}push` all run `git push`, and read as written
  # their first word was `\git`, `'git'` or `git{IFS}push` and the floor stayed
  # `읽기`. `$IFS` in any of its spellings parts words.
  payload=$(printf '%s' "$payload" | sed 's/\$[{]IFS[^}]*[}]/ /g; s/\$IFS/ /g' | tr -d '\\"'"'")

  local floor='읽기' mark='' trig='' fi_ fidx
  fidx=$(surface_index '읽기')
  local line first
  # Command POSITIONS only — the word after a separator. `grep "gh pr merge"` is
  # an argument to grep and does not raise anything.
  while IFS= read -r line; do
    # Leading `VAR=value` assignments belong to the command that follows them.
    set -f
    # shellcheck disable=SC2086
    set -- $line
    set +f
    while [ $# -gt 0 ]; do
      case "$1" in
        *=*) case "$1" in -*) break ;; *) shift ;; esac ;;
        *) break ;;
      esac
    done
    [ $# -gt 0 ] || continue
    first="$1"
    case "$first" in -*|'') continue ;; esac
    local g; g=$(surface_of_argv0 "$@")
    case "$g" in
      읽기|워크트리쓰기|트리밖쓰기|외부상태변경)
        fi_=$(surface_index "$g" 2>/dev/null) || fi_=""
        if [ -n "$fi_" ] && [ "$fi_" -gt "$fidx" ]; then fidx="$fi_"; floor="$g"; fi ;;
    esac
    local mk; mk=$(gate_act_mark "$@")
    case "$mk" in
      비밀출력*) mark='비밀출력'; trig="${mk#*	}" ;;
      파괴*) [ "$mark" = "비밀출력" ] || { mark='파괴'; trig="${mk#*	}"; } ;;
    esac
  done <<EOF
$(printf '%s' "$payload" | tr ';&|(){}`\n' '\n\n\n\n\n\n\n\n' | sed 's/\$//g')
EOF
  if [ "$shell_push" = 1 ]; then
    fi_=$(surface_index '외부상태변경' 2>/dev/null) || fi_=""
    if [ -n "$fi_" ] && [ "$fi_" -gt "$fidx" ]; then fidx="$fi_"; floor='외부상태변경'; fi
  fi
  printf '%s\t%s\t%s' "$floor" "$mark" "$trig"
}

gate_opaque_floor_find_inner() {
  # The floor of ONE `-exec` inner command of a `find`.
  #
  # `gate_opaque_floor` drops its own argv0 before it scans, which is right for
  # `sh -c` — the shell is not the act — and wrong for an inner command, where
  # argv0 IS the act. `find <d> -exec unknowncmd {} ';' -exec curl -X POST …
  # ';'` handed `[curl -X POST …]` to it, `curl` was dropped, the leading `-X`
  # made the scanner skip the line, and the floor came back `읽기`. The grade of
  # that argv is `등급 미상` (one primary the table cannot read), so the floor was
  # the only thing the declaration was compared against, and `--surface 읽기`
  # was admitted for a network write.
  #
  # So a non-opaque inner command is graded the way it would be graded bare — by
  # the table, straight from its argv0 — and its mark is read the same way. Only
  # a recognized surface raises the floor: `등급 미상` and `형태 미상` are verdicts
  # the grade itself carries, not floors. The inner argv is NOT re-joined into a
  # payload string for this: the payload splitter breaks on `{`, and `-exec curl
  # {} …` would leave only `curl ` on the first line.
  #
  # An opaque inner command (`sh -c`, `make` …) keeps the payload scan alone,
  # which is what the same command gets written bare.
  local base g mk
  base=$(gate_opaque_floor "$@")
  [ "$(gate_argv_opaque "$@")" = "1" ] && { printf '%s' "$base"; return 0; }
  g=$(surface_of_argv0 "$@")
  case "$g" in
    읽기|워크트리쓰기|트리밖쓰기|외부상태변경) ;;
    *) g='읽기' ;;
  esac
  mk=$(gate_act_mark "$@")
  gate_answer_floor_max "$base" "$(printf '%s\t%s' "$g" "$mk")"
}

gate_unwrap_env() {
  # gate_unwrap_env <resolver> <no-command> <unknown-opt> <env's args after argv0...>
  #
  # `env` consumes `-i`, `-0`, `-v`, `-u NAME` and any number of `NAME=VAL`
  # assignments, then runs what is left. Anything it does not recognize ends the
  # scan rather than being guessed at — a guess about whether an option eats the
  # next word moves the command out of view, which is the failure
  # `surface_of_git` already records.
  #
  # IT IS SHARED BY FIVE TABLES on purpose. Wired into the grader alone,
  # `env X=1 git merge seg` graded `워크트리쓰기` while the history predicate
  # answered 0 and the ladder saw no merge — the inert-repair shape this tree
  # already carries a comment about.
  #
  # A WORD STARTING WITH `-` IS AN OPTION EVEN WHEN IT CARRIES A `=`. Matched
  # as an assignment first, `--split-string=git push origin HEAD:main` (and
  # GNU env's abbreviation `--s=…`, and `--chdir=…`) was skipped like `X=1`,
  # no command was left, and the act graded a read while GNU env ran the
  # payload. No variable name starts with `-`, so nothing is lost.
  local resolver="$1" no_cmd="$2" unknown_opt="$3"; shift 3
  while [ $# -gt 0 ]; do
    case "$1" in
      -i|-0|-v|--) shift ;;
      -u) [ $# -ge 2 ] || { printf '%s' "$unknown_opt"; return 0; }; shift 2 ;;
      -u*) shift ;;
      -*) printf '%s' "$unknown_opt"; return 0 ;;
      *=*) shift ;;
      *) break ;;
    esac
  done
  [ $# -gt 0 ] || { printf '%s' "$no_cmd"; return 0; }
  "$resolver" "$@"
}

gate_unwrap_wrapper() {
  # gate_unwrap_wrapper <wrapper> <resolver> <no-command> <unknown-opt> <args...>
  #
  # The four launchers that run one command with a changed process attribute.
  # Each consumes ONLY its own options, and an unrecognized one ends the scan —
  # the shared discipline of every unwrap in this file.
  local w="$1" resolver="$2" no_cmd="$3" unk="$4"; shift 4
  case "$w" in
    timeout)
      while [ $# -gt 0 ]; do
        case "$1" in
          -f|--foreground|-p|--preserve-status|-v|--verbose) shift ;;
          -k|--kill-after|-s|--signal)
            [ $# -ge 2 ] || { printf '%s' "$unk"; return 0; }; shift 2 ;;
          --kill-after=*|--signal=*) shift ;;
          -*) printf '%s' "$unk"; return 0 ;;
          *) break ;;
        esac
      done
      # The duration operand, which is not the command.
      [ $# -ge 1 ] || { printf '%s' "$no_cmd"; return 0; }
      shift ;;
    nice)
      while [ $# -gt 0 ]; do
        case "$1" in
          -n) [ $# -ge 2 ] || { printf '%s' "$unk"; return 0; }; shift 2 ;;
          -n*|--adjustment=*) shift ;;
          -*) printf '%s' "$unk"; return 0 ;;
          *) break ;;
        esac
      done ;;
    nohup)
      case "${1:-}" in -*) printf '%s' "$unk"; return 0 ;; esac ;;
    stdbuf)
      while [ $# -gt 0 ]; do
        case "$1" in
          -i|-o|-e) [ $# -ge 2 ] || { printf '%s' "$unk"; return 0; }; shift 2 ;;
          -i*|-o*|-e*|--input=*|--output=*|--error=*) shift ;;
          -*) printf '%s' "$unk"; return 0 ;;
          *) break ;;
        esac
      done ;;
  esac
  [ $# -gt 0 ] || { printf '%s' "$no_cmd"; return 0; }
  "$resolver" "$@"
}

gate_unwrap_time() {
  # `time` differs from the three above by one option: `-o <file>` WRITES, so the
  # wrapped command's grade is not the whole answer there.
  local resolver="$1" no_cmd="$2" unk="$3"; shift 3
  local wrote=0
  while [ $# -gt 0 ]; do
    case "$1" in
      -p|-l|-h|--portability|--verbose) shift ;;
      -o|--output) [ $# -ge 2 ] || { printf '%s' "$unk"; return 0; }; wrote=1; shift 2 ;;
      --output=*) wrote=1; shift ;;
      -a|--append) wrote=1; shift ;;
      -*) printf '%s' "$unk"; return 0 ;;
      *) break ;;
    esac
  done
  [ $# -gt 0 ] || { printf '%s' "$no_cmd"; return 0; }
  local inner; inner=$("$resolver" "$@")
  [ "$wrote" = "1" ] || { printf '%s' "$inner"; return 0; }
  # Only the GRADING table has a floor to raise; the other tables pass their own
  # terminal answer through, which is what `''` means for them.
  case "$inner" in
    읽기|워크트리쓰기) printf '트리밖쓰기' ;;
    *) printf '%s' "$inner" ;;
  esac
}

surface_of_env()     { gate_unwrap_env     surface_of_argv0 '읽기' "$GATE_FORM_UNKNOWN" "$@"; }
surface_of_timeout() { gate_unwrap_wrapper timeout surface_of_argv0 '읽기' "$GATE_FORM_UNKNOWN" "$@"; }
surface_of_nice()    { gate_unwrap_wrapper nice    surface_of_argv0 '읽기' "$GATE_FORM_UNKNOWN" "$@"; }
surface_of_nohup()   { gate_unwrap_wrapper nohup   surface_of_argv0 '읽기' "$GATE_FORM_UNKNOWN" "$@"; }
surface_of_stdbuf()  { gate_unwrap_wrapper stdbuf  surface_of_argv0 '읽기' "$GATE_FORM_UNKNOWN" "$@"; }
surface_of_time()    { gate_unwrap_time            surface_of_argv0 '읽기' "$GATE_FORM_UNKNOWN" "$@"; }

ladder_of_argv0() {
  [ "$#" -ge 1 ] || return 0
  local cmd="${1##*/}"
  shift
  case "$cmd" in
    # The four wrappers run some other command, so a name cannot answer for them.
    # The unwraps are SHARED with the grading table and the history-integration
    # predicate rather than re-spelled, for the reason `gate_unwrap_lockf` states:
    # two copies of a skip loop are two chances to disagree about which word is
    # the command. Only the terminal answers are parameters, and both of this
    # table's are the empty string — a wrapper whose payload cannot be read
    # asserts nothing, the same as any other name with no row.
    lockf)   gate_unwrap_lockf   ladder_of_argv0 '' '' "$@" ;;
    command) gate_unwrap_command ladder_of_argv0 '' '' "$@" ;;
    # A gh call whose words find fills in with a path may be a merge the parse
    # below cannot see (`…/pulls/N/{}` run in `merge`), so it is read as one
    # and meets the merge binding, which answers `없음` for it.
    find)
      if gate_find_exec_substitutes gh "$@"; then
        printf '머지'
      else
        gate_unwrap_find ladder_of_argv0 '' '' '' gate_answer_ladder_max "$@"
      fi ;;
    rg)      gate_unwrap_rg      ladder_of_argv0 '' '' "$@" ;;
    env)     gate_unwrap_env     ladder_of_argv0 '' '' "$@" ;;
    timeout) gate_unwrap_wrapper timeout ladder_of_argv0 '' '' "$@" ;;
    nice)    gate_unwrap_wrapper nice    ladder_of_argv0 '' '' "$@" ;;
    nohup)   gate_unwrap_wrapper nohup   ladder_of_argv0 '' '' "$@" ;;
    stdbuf)  gate_unwrap_wrapper stdbuf  ladder_of_argv0 '' '' "$@" ;;
    time)    gate_unwrap_time            ladder_of_argv0 '' '' "$@" ;;
    git)       ladder_of_git "$@" ;;
    gh)        ladder_of_gh "$@" ;;
    terraform) ladder_of_terraform "$@" ;;
    *) : ;;
  esac
  return 0
}

ladder_of_git() {
  # The SAME global-option skip `surface_of_git` performs, spelled the same way,
  # because a global left in place puts a non-subcommand in the slot below. The
  # unknown arm diverges: that table answers `등급 미상` and refuses, this one
  # answers silence and defers to the declaration.
  while [ $# -gt 0 ]; do
    case "$1" in
      -C|-c|--git-dir|--work-tree|--namespace|--exec-path|--config-env)
        [ $# -ge 2 ] || return 0
        shift 2 ;;
      --git-dir=*|--work-tree=*|--namespace=*|--exec-path=*|--config-env=*)
        shift ;;
      -p|-P|--paginate|--no-pager|--bare|--no-replace-objects)
        shift ;;
      --literal-pathspecs|--no-optional-locks|--glob-pathspecs|--noglob-pathspecs|--icase-pathspecs)
        shift ;;
      -*) return 0 ;;
      *)  break ;;
    esac
  done
  case "${1:-}" in
    # `커밋` is the BOTTOM rung, so this row can never produce an
    # under-declaration — its only effect is to pull an over-declared commit back
    # down to what it is. That is the common case rather than a corner: the
    # router labels an ordinary commit with its target's cutpoint.
    commit) printf '커밋' ;;
    # `push`, `merge`, `branch` are deliberately absent — see the note above.
    *) : ;;
  esac
  return 0
}

gate_gh_strip_repo() {
  # gate_gh_strip_repo <gh's args after argv0...> — fills GATE_GH_ARGV with the
  # args minus every `-R <v>`, `-R<v>`, `--repo <v>` and `--repo=<v>` that
  # stands before the verb (the second bare word). gh takes `-R` before the
  # group and between the group and the verb alike, so `gh pr -R o/r merge`
  # is the merge `gh pr merge -R o/r` is; reading `$2` as the verb took `-R`
  # for it and the merge asserted nothing. A `-R` with no value is kept, so
  # the caller sees it as written. The three readers of gh — the grade, the
  # ladder and the merge binding — share this skip.
  #
  # A `-R` THAT IS ANOTHER FLAG'S VALUE IS KEPT. cobra drops the word after a
  # two-letter flag or a `--flag` without `=` as that flag's value (see
  # `gate_gh_group_verb`), so in `gh pr -t -R new -l x` the `-R` is the title
  # and gh runs `pr create --title -R --label x`. Taking that `-R` with the
  # word after it removed the verb, and every reader saw `pr -t -l x`: the
  # label went on with no `라벨 인정` row and the create took no rung.
  #
  # `api` IS FOUND THE WAY gh FINDS IT, AND MOVED TO THE FRONT. cobra looks for
  # the command past every flag ahead of it, so `gh --hostname=github.com api
  # -X PUT repos/o/r/pulls/1/merge` merges, and each flag is then parsed
  # against `api` wherever it stood. Read at the first position, that argv had
  # no rung, bound nothing, graded unknown and carried no DELETE mark, and the
  # preauthorization rewrite left it as written — so a merge declared honestly
  # passed unbound. When the command is `api`, GATE_GH_ARGV is `api` followed
  # by every other word in its order: the words ahead of it are flags and their
  # values, and they mean the same after it. When a word is `api` but where
  # gh takes its command cannot be told (a `--` or a run of value flags with no
  # command after them), GATE_GH_API_UNREAD is 1 and every reader takes the
  # argv for the unbound merge it may be.
  #
  # `pr new` IS WRITTEN `pr create`. gh documents `new` as the alias of `pr
  # create` and takes the same flags under it, so `gh pr new --label x` opens a
  # pull request with a label. The label detector and the ladder read the verb
  # from this array, and with `new` left as written neither took it for a
  # create: the label went on with no `라벨 인정` row and the act took no rung.
  # The flag table parses the argv as written and only to find a merge or a
  # `repo sync`, so it keeps the one `pr create` row.
  GATE_GH_ARGV=()
  GATE_GH_API_UNREAD=0
  local bare=0 grp='' val=0
  while [ "$#" -gt 0 ]; do
    if [ "$bare" -lt 2 ]; then
      if [ "$val" = 1 ]; then
        val=0
        case "$1" in
          -*|'') GATE_GH_ARGV+=("$1"); shift; continue ;;
        esac
      fi
      case "$1" in
        -R|--repo)
          if [ "$#" -ge 2 ]; then shift 2; continue; fi ;;
        --repo=*|-R?*) shift; continue ;;
        --|-h|--help|--*=*) : ;;
        --*|-?) val=1 ;;
        -*) : ;;
        *)
          bare=$((bare + 1))
          if [ "$bare" = 1 ]; then
            grp="$1"
          elif [ "$grp" = pr ] && [ "$1" = new ]; then
            GATE_GH_ARGV+=(create)
            shift
            continue
          fi ;;
      esac
    fi
    GATE_GH_ARGV+=("$1")
    shift
  done
  [ "${GATE_GH_ARGV[0]:-}" != api ] || return 0
  local w has_api=0
  for w in ${GATE_GH_ARGV[@]+"${GATE_GH_ARGV[@]}"}; do
    [ "$w" != api ] || has_api=1
  done
  [ "$has_api" = 1 ] || return 0
  local i=0 n="${#GATE_GH_ARGV[@]}" cand=-1 spec
  _gp_gh_load
  _gp_gh_row ''
  spec="${_GP_GH_S[$_GP_GH_I]}"
  while [ "$i" -lt "$n" ]; do
    w="${GATE_GH_ARGV[$i]}"
    case "$w" in
      --) break ;;
      --*=*) ;;
      --*) _gp_gh_novalue "$spec" "${w#--}" '' || i=$((i + 1)) ;;
      -?) _gp_gh_novalue "$spec" '' "${w#-}" || i=$((i + 1)) ;;
      -*|'') ;;
      *) cand="$i"; break ;;
    esac
    i=$((i + 1))
  done
  if [ "$cand" -lt 0 ]; then GATE_GH_API_UNREAD=1; return 0; fi
  [ "${GATE_GH_ARGV[$cand]}" = api ] || return 0
  GATE_GH_ARGV=(api "${GATE_GH_ARGV[@]:0:$cand}" "${GATE_GH_ARGV[@]:$((cand + 1))}")
}

gate_gh_pr_merge_kind() {
  # gate_gh_pr_merge_kind <gh's args after argv0...> — whether this gh argv is
  # `pr merge`, found the way gh finds its command: `merge` when the gh flag
  # table parses it to the path `pr merge`, `form` when the table cannot parse
  # it but its words carry both `pr` and `merge`, `none` otherwise. The grade,
  # the ladder, the collaboration surface and the merge binding all ask this
  # one question, so a spelling one of them takes for a merge all of them take.
  #
  # THE COMMAND IS FOUND BY THE PARSE, NOT BY POSITION. gh skips a value flag
  # and its value wherever they stand, so `gh pr -b x merge 1` and `gh -t y pr
  # merge 1` merge. Read positionally after `-R` was stripped they were `pr -b`
  # and `-t y`: the binding answered `해당없음`, the ladder named no rung and
  # the collaboration surface let the act through, so an unreviewed head could
  # land. A spelling the table cannot read is not known not to merge, which is
  # why it is `form` and not `none`. `gh api` has its own reader and is left
  # to it.
  local w p=0 m=0 first=''
  for w in "$@"; do
    case "$w" in
      pr) p=1 ;;
      merge) m=1 ;;
    esac
  done
  if [ "$p" = 0 ] || [ "$m" = 0 ]; then printf '%s' none; return 0; fi
  gate_gh_strip_repo "$@"
  first="${GATE_GH_ARGV[0]:-}"
  [ "$first" != api ] || { printf '%s' none; return 0; }
  gp_parse gh "$@"
  if [ "$GP_STATUS" = ok ]; then
    if gp_path_is pr merge; then printf '%s' merge; else printf '%s' none; fi
    return 0
  fi
  printf '%s' form
}

gate_gh_repo_sync_remote() {
  # gate_gh_repo_sync_remote <gh's args after argv0...> — true when the argv is
  # a `gh repo sync` that names a destination repository, or one the gh flag
  # table cannot read whose words carry both `repo` and `sync`.
  #
  # WITH A DESTINATION, `gh repo sync` WRITES THE REMOTE BRANCH. It moves
  # `--branch` of that repository to its source's, and `--force` replaces it,
  # without a pull request or a head to hold — the REST `merge-upstream` under
  # another name. Read as nothing, it answered `해당없음` to the binding, took
  # no rung and passed the merge binding check. Without a destination it
  # updates the local clone, which no remote reads.
  local w r=0 s=0
  for w in "$@"; do
    case "$w" in
      repo) r=1 ;;
      sync) s=1 ;;
    esac
  done
  [ "$r" = 1 ] && [ "$s" = 1 ] || return 1
  gp_parse gh "$@"
  [ "$GP_STATUS" = ok ] || return 0
  gp_path_is repo sync || return 1
  [ "${#GP_POS[@]}" -ge 1 ]
}

ladder_of_gh() {
  case "$(gate_gh_pr_merge_kind "$@")" in
    merge|form) printf '머지'; return 0 ;;
  esac
  if gate_gh_repo_sync_remote "$@"; then printf '머지'; return 0; fi
  gate_gh_strip_repo "$@"
  [ "$GATE_GH_API_UNREAD" = 0 ] || { printf '머지'; return 0; }
  set -- ${GATE_GH_ARGV[@]+"${GATE_GH_ARGV[@]}"}
  # A create behind a value flag (`gh pr -t x new`) is found the way gh finds
  # it (see `gate_gh_group_verb`), so it takes the same rung as `gh pr create`.
  if [ "${1:-}" != api ]; then
    gate_gh_group_verb "$@"
    case "$GATE_GH_CG:$GATE_GH_CV" in
      pr:create|pr:new) printf 'PR'; return 0 ;;
    esac
  fi
  case "${1:-}" in
    api) ladder_of_gh_api "$@" ;;
    pr)
      case "${2:-}" in
        # `merge` was answered above, by the parse.
        create) printf 'PR' ;;
        # `view`, `list`, `review`, `comment` and everything else this row does
        # not name assert nothing. Naming them would be guessing, and the guess
        # that costs is the high one.
        *) : ;;
      esac ;;
    # OPENING OR COMMENTING ON AN ISSUE, AND PUTTING ONE ON A PROJECT, ARE
    # `커밋`. They change a tracker, never a branch, so no review requirement
    # is about them. Without these rows the effective cutpoint is whatever the
    # caller declared, and a routing shift that declares its target cutpoint
    # `머지` for a carry-over issue meets the merge review rule on the very
    # cycle the issue exists to settle. `커밋` is the floor of the ladder, so
    # this cannot become an under-declaration refusal either.
    issue)
      case "${2:-}" in
        create|comment) printf '커밋' ;;
        *) : ;;
      esac ;;
    project)
      case "${2:-}" in
        item-add) printf '커밋' ;;
        *) : ;;
      esac ;;
    *) : ;;
  esac
  return 0
}

gate_gh_api_field() {
  # gate_gh_api_field <typed 0|1> <k=v> — records one body field. A typed field
  # (`-F`, `--field`) whose value is `@<file>` is read from a file this gate
  # does not open.
  GATE_GHAPI_FIELDS+=("$2")
  if [ "$1" = 1 ]; then
    case "${2#*=}" in @*) GATE_GHAPI_OPAQUE=1 ;; esac
  fi
  return 0
}

gate_gh_api_parse() {
  # gate_gh_api_parse <gh api's args after `api`...> — the one reading of a
  # `gh api` argv the merge ladder, the merge binding and the collaboration
  # surface share. Sets:
  #
  #   GATE_GHAPI_METHOD  the method gh will send (`-X`, else POST with a body,
  #                      else GET)
  #   GATE_GHAPI_PATH    the endpoint with any `?query`, `#fragment`, leading
  #                      and trailing `/` removed
  #   GATE_GHAPI_ENDPOINT the endpoint word exactly as written. gh wraps the
  #                      fields into `variables` only when it is `graphql`, so
  #                      a reading that depends on that wrapping reads this
  #   GATE_GHAPI_FIELDS  every `-f`/`-F`/`--field`/`--raw-field` value, `k=v`
  #   GATE_GHAPI_OPAQUE  1 when part of the body is in a file this gate does not
  #                      read (`--input`, or a `-F`/`--field` value `@<file>`)
  #
  # ONE READING, BECAUSE THREE DRIFTED. The ladder matched `*/pulls/*/merge`
  # exactly, so `…/merge?merge_method=squash` and `…/merge/` were no merge and
  # the binding never asked for a head; the collaboration surface matched a
  # substring and took them; and `--field=sha=…` set no body in the ladder, so
  # the merge read as a GET.
  #
  # SHORT OPTIONS ARE READ THE WAY PFLAG READS THEM: one letter at a time, and a
  # value letter takes the rest of the word or, at its end, the next word. Read
  # as one word, `-iXPUT` and `-iX PUT` were an unknown option, the method stayed
  # GET, and the merge they send was graded a read with no binding asked. The
  # letters are `gh api`'s own: `i` is its one short bool, and `X f F H p q t`
  # take a value. A letter outside them is a word gh refuses, so it is read as
  # nothing.
  GATE_GHAPI_METHOD="" GATE_GHAPI_PATH="" GATE_GHAPI_ENDPOINT="" GATE_GHAPI_OPAQUE=0
  GATE_GHAPI_FIELDS=()
  local body=0 ddash=0 w c val j
  while [ $# -gt 0 ]; do
    w="$1"; shift
    if [ "$ddash" = 1 ]; then
      [ -n "$GATE_GHAPI_PATH" ] || GATE_GHAPI_PATH="$w"
      continue
    fi
    case "$w" in
      --) ddash=1 ;;
      --method)    [ $# -ge 1 ] || break; GATE_GHAPI_METHOD="$1"; shift ;;
      --method=*)  GATE_GHAPI_METHOD="${w#--method=}" ;;
      --input)     body=1; GATE_GHAPI_OPAQUE=1; [ $# -ge 1 ] || break; shift ;;
      --input=*)   body=1; GATE_GHAPI_OPAQUE=1 ;;
      --raw-field) body=1; [ $# -ge 1 ] || break; gate_gh_api_field 0 "$1"; shift ;;
      --field)     body=1; [ $# -ge 1 ] || break; gate_gh_api_field 1 "$1"; shift ;;
      --raw-field=*) gate_gh_api_field 0 "${w#--raw-field=}"; body=1 ;;
      --field=*)     gate_gh_api_field 1 "${w#--field=}"; body=1 ;;
      --header|--jq|--template|--hostname|--cache|--preview)
        [ $# -ge 1 ] || break; shift ;;
      --*) : ;;
      -?*)
        j=1
        while [ "$j" -lt "${#w}" ]; do
          c="${w:j:1}"
          case "$c" in
            X|f|F|H|p|q|t)
              if [ $((j + 1)) -lt "${#w}" ]; then
                val="${w:j+1}"; val="${val#=}"
              elif [ $# -ge 1 ]; then
                val="$1"; shift
              else
                break
              fi
              case "$c" in
                X) GATE_GHAPI_METHOD="$val" ;;
                f) gate_gh_api_field 0 "$val"; body=1 ;;
                F) gate_gh_api_field 1 "$val"; body=1 ;;
              esac
              break ;;
            i) j=$((j + 1)) ;;
            *) break ;;
          esac
        done ;;
      # The first bare word is the endpoint. Anything later is a positional this
      # table has no use for, so the first one wins and the scan continues —
      # stopping here would leave a trailing `-X` unread.
      *) [ -n "$GATE_GHAPI_PATH" ] || GATE_GHAPI_PATH="$w" ;;
    esac
  done
  if [ -z "$GATE_GHAPI_METHOD" ]; then
    if [ "$body" = 1 ]; then GATE_GHAPI_METHOD=POST; else GATE_GHAPI_METHOD=GET; fi
  fi
  GATE_GHAPI_ENDPOINT="$GATE_GHAPI_PATH"
  local p="$GATE_GHAPI_PATH"
  p="${p%%[#]*}"; p="${p%%[?]*}"
  while [ "${p%/}" != "$p" ]; do p="${p%/}"; done
  while [ "${p#/}" != "$p" ]; do p="${p#/}"; done
  GATE_GHAPI_PATH="$p"
}

gate_gh_api_pct_decode() {
  # gate_gh_api_pct_decode <s> — <s> with its `%XX` escapes decoded and nothing
  # else touched. A backslash is doubled before `printf '%b'` reads the string,
  # so a literal `\c` in a path no longer ends the output there and hides the
  # segments after it, and a literal `\n` stays two characters.
  #
  # THE BYTES ARE READ AS BYTES, AND A FAILED `sed` RETURNS 1 WITH NOTHING
  # PRINTED. The run picks a UTF-8 locale, and macOS `sed` stops at the first
  # byte that is not valid UTF-8 there, so the prefix it had written read as
  # the whole path. The callers take a status of 1 as a path they cannot read.
  local d
  d=$(printf '%s' "$1" | LC_ALL=C sed -e 's/\\/\\\\/g' -e 's/%/\\x/g') || return 1
  printf '%b' "$d"
}

gate_gh_api_rest_path() {
  # After `gate_gh_api_parse`: the path with an absolute URL's scheme and host
  # removed, and the `api/v3/` prefix an Enterprise host puts before
  # `repos/…`. gh sends an absolute URL as written, so `https://<host>/repos/…`
  # reaches the same endpoint as `repos/…` and is read as it.
  local p="$GATE_GHAPI_PATH"
  case "$p" in
    http://*|https://*)
      p="${p#*://}"
      case "$p" in */*) p="${p#*/}" ;; *) p="" ;; esac
      case "$p" in api/v3/*) p="${p#api/v3/}" ;; api/graphql) p=graphql ;; esac ;;
  esac
  printf '%s' "$p"
}

gate_gh_api_endpoint_raw() {
  # gate_gh_api_endpoint_raw <s> — 0 when <s> holds a byte outside printable
  # ASCII, a control byte or one of 0x80 and above, or when that cannot be
  # told.
  #
  # SUCH AN ENDPOINT IS NOT READ, IN ANY LOCALE. Every reading of the endpoint
  # here splits or matches it, and in the run's UTF-8 locale macOS `tr`, `sed`
  # and bash's own regex stop at or fail on a byte not valid there — each one
  # a reading that saw a prefix, or nothing, and answered as if it had seen the
  # whole. gh sends the bytes as written, so what reaches the server is the
  # endpoint none of those readings saw. Taking the byte itself as the signal
  # does not depend on which locale the next reading runs in. A label or path
  # that needs such a character percent-escapes it, and an escape is ASCII.
  local rest
  case "$1" in *$'\n'*) return 0 ;; esac
  rest=$(printf '%s' "$1" | LC_ALL=C tr -d ' -~') || return 0
  [ -n "$rest" ]
}

gate_gh_api_authority_unread() {
  # After `gate_gh_api_parse`: 0 when the endpoint is an absolute URL whose
  # authority — userinfo, host or port — holds something gh fills in before
  # sending the request.
  #
  # gh FILLS THE WHOLE REQUEST STRING, NOT ONLY ITS PATH, and puts the current
  # branch's name in unescaped. With a branch named
  # `api.github.com/repos/o/r/pulls/7/merge#`, `https://{branch}/repos/o/r/issues/1`
  # is the merge endpoint of pull request 7 and the rest is a fragment.
  # `gate_gh_api_rest_path` drops the authority before any segment is read, so
  # the placeholder there was seen by nothing and the merge passed as an issue
  # edit. Nothing after such an authority says what the endpoint is.
  local a="$GATE_GHAPI_PATH"
  case "$a" in
    http://*|https://*) a="${a#*://}"; a="${a%%/*}" ;;
    *) return 1 ;;
  esac
  gate_gh_api_seg_placeholder "$a"
}

gate_gh_api_seg_placeholder() {
  # 0 when the path segment <seg> holds something gh replaces before sending
  # the request: a `{…}`, or `:owner`, `:repo` or `:branch` not followed by a
  # word character. gh matches `\{[a-z]+\}` and `:(owner|repo|branch)\b`; any
  # brace pair is taken here, so a spelling gh leaves alone only reads as
  # unread too.
  #
  # THE SEGMENT IS MATCHED AS BYTES, AND A MATCH THAT FAILS TO RUN IS A
  # PLACEHOLDER. A `[[ =~ ]]` runs in the run's UTF-8 locale, and macOS bash
  # 3.2 matched nothing in a segment that also held a byte not valid there:
  # `:branch<byte>` read as no placeholder, while gh's `\b` treats the byte as
  # a non-word character and fills the branch in. A merge reached through the
  # branch's name then passed as an issue write with no rung.
  local re=':(owner|repo|branch)([^A-Za-z0-9_]|$)' rc=0
  case "$1" in *'{'*'}'*) return 0 ;; esac
  printf '%s' "$1" | LC_ALL=C grep -Eq -e "$re" || rc=$?
  [ "$rc" != 1 ]
}

gate_gh_api_rest_class() {
  # After `gate_gh_api_parse`, on a non-GET REST call: prints `merge`,
  # `merge-async` or `merges` when the path is exactly that endpoint, `inert`
  # when it is one of the issue, pull request, label, milestone and comment
  # endpoints, which write no git ref, and nothing otherwise.
  #
  # THE PATH IS READ SEGMENT BY SEGMENT FROM `repos/<owner>/<repo>/`. A `case`
  # glob's `*` crosses `/`, so `*/pulls/*/merge` took
  # `repos/o/r/contents/pulls/1/merge` — a file write that commits to the
  # branch it names — for a pull request merge, bound it to its `sha` field and
  # put it on the collaboration surface. Each endpoint here is matched at its
  # own position and by its segment count.
  #
  # A SEGMENT THAT IS EMPTY, `.`, `..` OR DECODES TO ONE, OR WHOSE ESCAPES
  # DECODE TO A `/`, is a path the server may resolve to another endpoint, so
  # no endpoint here is read from it.
  #
  # NOR FROM A SEGMENT gh FILLS IN BEFORE SENDING. gh replaces `{owner}`,
  # `{repo}`, `{branch}` and `:owner`, `:repo`, `:branch` anywhere in the
  # endpoint, and puts the current branch's name in unescaped, so after
  # `git switch -c 7/merge` the path `repos/{owner}/{repo}/pulls/{branch}`
  # reaches `…/pulls/7/merge`. Read as written it had five segments and was a
  # pull request edit, so a merge bound to nothing passed as a write that moves
  # no ref. Only `repos/{owner}/{repo}/` (or `:owner`, `:repo`) is read through:
  # an owner or repository name holds no `/`, so it is one segment whatever it
  # is. Any other segment gh fills in leaves the endpoint unread, and so does
  # one in an absolute URL's authority (`gate_gh_api_authority_unread`).
  #
  # A PATH THE SPLIT DID NOT FINISH READING NAMES NO ENDPOINT. Split by a `tr`
  # in the run's UTF-8 locale, a byte that is not valid UTF-8 stopped macOS `tr`
  # there, and the prefix it had written — `repos/o/r/issues` before
  # `…/1<byte>/../../../pulls/1/merge` — read as an issue write, so a merge
  # bound to nothing passed with no rung. The split reads bytes, and a split
  # that fails prints nothing here, which the caller reads as a write that
  # moves a ref.
  local p seg d n segs i=0
  local -a s=()
  gate_gh_api_authority_unread && return 0
  p=$(gate_gh_api_rest_path)
  segs=$(printf '%s' "$p" | LC_ALL=C tr '/' '\n') || return 0
  while IFS= read -r seg; do
    s[${#s[@]}]="$seg"
  done <<GATE_GHAPI_REST_SEGS
$segs
GATE_GHAPI_REST_SEGS
  for seg in ${s[@]+"${s[@]}"}; do
    case "$seg" in ''|.|..) return 0 ;; esac
    case "$seg" in
      *%*)
        d=$(gate_gh_api_pct_decode "$seg") || return 0
        case "$d" in ''|.|..|*/*) return 0 ;; esac ;;
    esac
    if gate_gh_api_seg_placeholder "$seg"; then
      case "$i:$seg" in
        '1:{owner}'|'1::owner'|'2:{repo}'|'2::repo') : ;;
        *) return 0 ;;
      esac
    fi
    i=$((i + 1))
  done
  n="${#s[@]}"
  [ "$n" -ge 4 ] && [ "${s[0]}" = repos ] || return 0
  case "${s[3]}" in
    issues|labels|milestones|comments) printf 'inert' ;;
    merges) [ "$n" = 4 ] && printf 'merges' ;;
    commits)
      [ "$n" = 6 ] && [ "${s[5]}" = comments ] && printf 'inert' ;;
    pulls)
      if [ "$n" -le 5 ]; then printf 'inert'; return 0; fi
      if [ "${s[4]}" = comments ]; then printf 'inert'; return 0; fi
      case "${s[5]}" in
        merge) [ "$n" = 6 ] && printf 'merge' ;;
        merge-async) [ "$n" = 6 ] && printf 'merge-async' ;;
        reviews|comments|requested_reviewers) printf 'inert' ;;
      esac ;;
  esac
  return 0
}

gate_gh_api_path_unread() {
  # After `gate_gh_api_parse`: true when the path names a `pulls` segment once
  # its `%` escapes are decoded, and is not a path this gate can read as
  # written — it has a `%` escape, or a `.`, `..` or empty segment. An absolute
  # URL is read from its path, so the `//` after its scheme is no empty segment.
  #
  # A decode or split that fails is a path this gate cannot read, and true:
  # stopped at a byte that is not valid UTF-8, the prefix before it held no
  # `pulls` segment and the merge after it went unseen.
  local p d seg segs odd=0 pulls=0
  p=$(gate_gh_api_rest_path)
  case "$p" in *%*) odd=1 ;; esac
  d=$(gate_gh_api_pct_decode "$p") || return 0
  segs=$(printf '%s' "$d" | LC_ALL=C tr '/' '\n') || return 0
  while IFS= read -r seg; do
    case "$seg" in
      pulls) pulls=1 ;;
      ''|.|..) odd=1 ;;
    esac
  done <<GATE_GHAPI_SEGS
$segs
GATE_GHAPI_SEGS
  [ "$pulls" = 1 ] && [ "$odd" = 1 ]
}

gate_gh_api_merge_kind() {
  # After `gate_gh_api_parse`: prints `rest` for a pull request merge over REST,
  # `rest-unbound` for a pull request path it cannot read as written,
  # `rest-async` for the background pull request merge, `rest-ref` for any
  # other REST write but the ones that write no git ref, `branch` for a REST
  # branch merge, `graphql` for a GraphQL mutation that merges, nothing
  # otherwise.
  #
  # A REST merge is a non-GET against `…/pulls/<n>/merge`. `…/merges` merges a
  # branch or a commit into another with no pull request at all, and its body
  # has no parameter that pins the head (`base`, `head`, `commit_message`), so it
  # is a kind of its own: a `sha` field sent to it is not a binding the server
  # enforces, and reading it as one let an unreviewed branch merge under an
  # honest declaration. A GraphQL merge is any body that names
  # `mergePullRequest`, `mergeBranch`, `enqueuePullRequest` or
  # `enablePullRequestAutoMerge` — the field name is literal in the document
  # whatever its alias.
  #
  # A GRAPHQL BODY THAT NAMES NO MERGE IS NOT THEREBY HARMLESS. `updateRefs`,
  # `updateRef` and `createCommitOnBranch` move the base without merging
  # anything, and reading "no merge field" as "merges nothing" sent them to the
  # push branch, which found no push and passed them, and onto the
  # collaboration surface under an honest `협업`. So the default is reversed:
  # a readable body is `graphql-ref`, a base change with no binding, unless
  # `gate_gh_graphql_inert` shows every operation is a query or calls only
  # mutations that move no ref. A body in a file is left to the callers, which
  # already take it as a merge they cannot bind.
  #
  # A PULL REQUEST PATH THIS GATE CANNOT READ AS WRITTEN IS `rest-unbound`. gh
  # sends the endpoint verbatim, so `…/pulls/1/merge/reviews/..`,
  # `…/merge/labels/%2e%2e` or `…/pulls//1/merge` reach a server that may
  # resolve them to the merge endpoint. Read as written they ended in neither
  # `/merge` nor anything else this table knows, so the ladder named no rung,
  # the binding answered `해당없음` and the `*/reviews/*` substring put them on
  # the collaboration surface. A non-GET path with a `pulls` segment once
  # percent-decoded, and with a `.`, `..` or empty segment or any `%` escape,
  # is a merge with no binding. A label or comment path with no `pulls`
  # segment is not touched by this, so an escaped label name stays a label.
  #
  # THE BACKGROUND MERGE AND THE REST REF WRITES ARE MERGES TOO. `…/merge-async`
  # merges a pull request in the background or adds it to a merge queue, and
  # GitHub recommends it over `…/merge`; ending in neither `/merge` nor
  # `/merges`, it named no rung, answered `해당없음` to the binding and stayed
  # off the collaboration surface, so a remote merge passed with nothing tied
  # to the reviewed HEAD. Its merge comes after the request, as a queue entry's
  # does, so it is `rest-async`, a merge with no binding whatever `sha` it
  # carries. The REST twins of the GraphQL ref writes move a branch without
  # merging anything: a write to `…/git/refs…`, a write to `…/contents/…`
  # (which commits to the default branch when it names no `branch`) and
  # `…/merge-upstream`. They are `rest-ref`, a base change with no binding,
  # whichever branch they name — as `updateRef` is.
  #
  # AND SO IS EVERY OTHER REST WRITE, as a GraphQL body is. Listing the REST
  # writes that move a branch left the ones not listed — `…/branches/<b>/rename`,
  # for one — answering `해당없음` to the binding, off the collaboration
  # surface and with no rung, so the binding check passed them and a base
  # renamed or replaced under an honest declaration. A non-GET REST call is
  # `rest-ref` unless `gate_gh_api_rest_class` reads it as one of the
  # endpoints that write no git ref — which it never does for a path with a
  # segment gh fills in (`{branch}`, `:branch`) past `repos/{owner}/{repo}/`.
  #
  # GRAPHQL IS THE ENDPOINT `graphql` AND NOTHING ELSE. Matched as
  # `*/graphql`, a file write to `repos/o/r/contents/graphql` was read as a
  # GraphQL body with no merge in it.
  #
  # AN AUTHORITY gh FILLS IN NAMES NO ENDPOINT AT ALL, so a non-GET call to one
  # is `rest-ref` before the path is read — `https://{branch}/graphql` included,
  # whose path only looks like the GraphQL endpoint.
  #
  # AN ENDPOINT WITH A BYTE OUTSIDE PRINTABLE ASCII NAMES NONE EITHER — see
  # `gate_gh_api_endpoint_raw` — so a non-GET call to one is `rest-ref` before
  # any reading of it runs, and its binding is `없음` whatever `sha` it carries.
  case "$GATE_GHAPI_METHOD" in GET|get|HEAD|head) return 0 ;; esac
  if gate_gh_api_endpoint_raw "$GATE_GHAPI_ENDPOINT"; then printf 'rest-ref'; return 0; fi
  if gate_gh_api_authority_unread; then printf 'rest-ref'; return 0; fi
  if gate_gh_api_path_unread; then printf 'rest-unbound'; return 0; fi
  if [ "$(gate_gh_api_rest_path)" != graphql ]; then
    case "$(gate_gh_api_rest_class)" in
      merge) printf 'rest' ;;
      merge-async) printf 'rest-async' ;;
      merges) printf 'branch' ;;
      inert) : ;;
      *) printf 'rest-ref' ;;
    esac
    return 0
  fi
  local f
  for f in ${GATE_GHAPI_FIELDS[@]+"${GATE_GHAPI_FIELDS[@]}"}; do
    case "$f" in
      *mergePullRequest*|*mergeBranch*|*enqueuePullRequest*|*enablePullRequestAutoMerge*)
        printf 'graphql'; return 0 ;;
    esac
  done
  [ "$GATE_GHAPI_OPAQUE" = 1 ] && return 0
  gate_gh_graphql_inert || printf 'graphql-ref'
  return 0
}

gate_gh_graphql_mutation_inert() {
  # 0 when the named top-level mutation field writes no git ref — comments,
  # reactions, labels, assignees, issues, reviews, pull request state and
  # project items. Anything not listed is taken as one that may.
  case "$1" in
    addComment|updateIssueComment|deleteIssueComment|minimizeComment|unminimizeComment) return 0 ;;
    addReaction|removeReaction) return 0 ;;
    addLabelsToLabelable|removeLabelsFromLabelable|clearLabelsFromLabelable) return 0 ;;
    addAssigneesToAssignable|removeAssigneesFromAssignable) return 0 ;;
    createIssue|updateIssue|closeIssue|reopenIssue|pinIssue|unpinIssue|addSubIssue|removeSubIssue) return 0 ;;
    lockLockable|unlockLockable) return 0 ;;
    addPullRequestReview|submitPullRequestReview|updatePullRequestReview|deletePullRequestReview|dismissPullRequestReview) return 0 ;;
    addPullRequestReviewComment|updatePullRequestReviewComment|deletePullRequestReviewComment) return 0 ;;
    addPullRequestReviewThread|addPullRequestReviewThreadReply|resolveReviewThread|unresolveReviewThread) return 0 ;;
    requestReviews|markPullRequestReadyForReview|convertPullRequestToDraft) return 0 ;;
    createPullRequest|updatePullRequest|closePullRequest|reopenPullRequest) return 0 ;;
    disablePullRequestAutoMerge|dequeuePullRequest) return 0 ;;
    addProjectV2ItemById|addProjectV2DraftIssue|updateProjectV2ItemFieldValue|clearProjectV2ItemFieldValue) return 0 ;;
    deleteProjectV2Item|archiveProjectV2Item|unarchiveProjectV2Item|updateProjectV2ItemPosition) return 0 ;;
  esac
  return 1
}

gate_gh_graphql_inert() {
  # After `gate_gh_api_parse` on a non-GET GraphQL body that names no merge
  # field: 0 when the single `query` document holds only `query` operations, or
  # every top-level field of every other definition passes
  # `gate_gh_graphql_mutation_inert`; 1 otherwise, and for every body this
  # cannot read — a `"""` block string, a fragment spread or a directive among
  # the top-level fields of a definition that is not a query, an unbalanced
  # document, or not exactly one `query` field. `#` comments are
  # skipped to the end of their line, so a word in one is never a field.
  #
  # The keyword of an operation is the first word at the document's top level
  # since the last definition closed; a `{` with none is the query shorthand.
  # Braces inside an argument list (an input object, a variable's default) do
  # not open or close a definition.
  local f q="" nq=0
  for f in ${GATE_GHAPI_FIELDS[@]+"${GATE_GHAPI_FIELDS[@]}"}; do
    case "$f" in query=*) q="${f#query=}"; nq=$((nq + 1)) ;; esac
  done
  [ "$nq" = 1 ] || return 1
  case "$q" in *'"""'*) return 1 ;; esac
  local n="${#q}" i=0 j k ch word prev nx instr=0 esc=0 incm=0 pd=0 bd=0 kw="" op="" cur
  while [ "$i" -lt "$n" ]; do
    ch="${q:i:1}"
    if [ "$incm" = 1 ]; then
      case "$ch" in $'\n'|$'\r') incm=0 ;; esac
      i=$((i + 1)); continue
    fi
    if [ "$instr" = 1 ]; then
      if [ "$esc" = 1 ]; then esc=0
      elif [ "$ch" = '\' ]; then esc=1
      elif [ "$ch" = '"' ]; then instr=0
      fi
      i=$((i + 1)); continue
    fi
    case "$ch" in
      '"') instr=1 ;;
      '#') incm=1 ;;
      '(') pd=$((pd + 1)) ;;
      ')') pd=$((pd - 1)) ;;
      '{')
        if [ "$bd" = 0 ] && [ "$pd" = 0 ]; then op="${kw:-query}"; fi
        bd=$((bd + 1)) ;;
      '}')
        bd=$((bd - 1))
        if [ "$bd" = 0 ] && [ "$pd" = 0 ]; then kw=""; fi ;;
      '.'|'@')
        # A spread or a directive can add or drop a top-level field only where
        # the top-level fields are: in a definition's own selection set or its
        # header, outside every argument list. Inside a query nothing it adds
        # writes, and deeper down it selects from a payload. Refusing it
        # everywhere turned `... on PullRequest`, `@include` and `1.5` in a
        # read into a merge every declaration refused.
        if [ "$pd" = 0 ] && [ "$bd" -le 1 ]; then
          if [ "$bd" = 0 ]; then cur="$kw"; else cur="$op"; fi
          [ "$cur" = query ] || return 1
        fi ;;
      [A-Za-z_])
        j=$((i + 1))
        while [ "$j" -lt "$n" ]; do
          case "${q:j:1}" in [A-Za-z0-9_]) j=$((j + 1)) ;; *) break ;; esac
        done
        word="${q:i:j-i}"
        prev=""; [ "$i" -eq 0 ] || prev="${q:i-1:1}"
        if [ "$prev" != '$' ] && [ "$pd" = 0 ]; then
          if [ "$bd" = 0 ]; then
            [ -n "$kw" ] || kw="$word"
          elif [ "$bd" = 1 ] && [ "$op" != query ]; then
            k="$j"
            while [ "$k" -lt "$n" ]; do
              case "${q:k:1}" in ' '|','|$'\t'|$'\n'|$'\r') k=$((k + 1)) ;; *) break ;; esac
            done
            nx="${q:k:1}"
            if [ "$nx" != ':' ]; then
              gate_gh_graphql_mutation_inert "$word" || return 1
            fi
          fi
        fi
        i="$j"; continue ;;
    esac
    i=$((i + 1))
  done
  [ "$instr" = 0 ] && [ "$bd" = 0 ] && [ "$pd" = 0 ] || return 1
  return 0
}

ladder_of_gh_api() {
  # `gh pr merge` is not the only spelling of a merge — `gh api -X PUT
  # repos/o/r/pulls/1/merge` is the same act through the other door, and it is
  # the door a run takes when it wants the merge method spelled out; a GraphQL
  # `mergePullRequest` is a third. See `gate_gh_api_merge_kind` for what counts,
  # and every other endpoint asserts nothing.
  #
  # A GraphQL body in a file (`-F query=@f`, `--input`) names nothing this gate
  # can read, so a non-GET one is taken at `머지`: it may be a merge, and
  # asserting nothing let it be declared `커밋`, under every check a merge
  # meets. At `머지` the binding refuses it, with the inline body as the repair.
  shift
  gate_gh_api_parse "$@"
  if [ -n "$(gate_gh_api_merge_kind)" ]; then printf '머지'; return 0; fi
  case "$GATE_GHAPI_PATH" in
    graphql|*/graphql)
      if [ "$GATE_GHAPI_OPAQUE" = 1 ]; then
        case "$GATE_GHAPI_METHOD" in GET|get|HEAD|head) : ;; *) printf '머지' ;; esac
      fi ;;
  esac
  return 0
}

gate_gh_graphql_binding() {
  # After `gate_gh_api_parse` on a GraphQL merge: the bound head, or `없음`.
  #
  # ONE SHAPE IS READ, AND IT IS THE ONE THE SERVER BINDS. The document — the
  # single `query` field — must hold one operation whose only top-level field is
  # a `mergePullRequest`, and exactly one `expectedHeadOid` argument, inside
  # that field's arguments and outside every string. Its value is inline as a string, or a `$variable`
  # whose value is a top-level `-f`/`-F` field gh sends as a variable — any
  # field but `query` and `operationName`, on the endpoint written `graphql`.
  #
  # Counting the words did not tell the argument the server reads from text it
  # does not: an `expectedHeadOid` inside a `"""` block string, or the argument
  # of a sibling `createCommitOnBranch` or `updatePullRequestBranch`, bound a
  # `mergePullRequest` the server merged whatever its head. So every other shape
  # is refused, with the inline spelling as the repair: a block string, a `#`
  # comment, a fragment spread, a directive, a second operation or top-level
  # field, an input object passed whole as a variable (`input: $input`), and a
  # second `expectedHeadOid` anywhere.
  #
  # `enablePullRequestAutoMerge` AND `enqueuePullRequest` CARRY THE ARGUMENT
  # AND BIND NOTHING. GitHub compares their `expectedHeadOid` when the request
  # is made and merges later, so a commit pushed to the head branch in between
  # is what merges — the same window as `gh pr merge --auto`. They are read as
  # merges and always answer `없음`.
  local f q="" nq=0
  for f in ${GATE_GHAPI_FIELDS[@]+"${GATE_GHAPI_FIELDS[@]}"}; do
    case "$f" in query=*) q="${f#query=}"; nq=$((nq + 1)) ;; esac
  done
  [ "$nq" = 1 ] || { printf '%s' '없음'; return 0; }
  case "$q" in *'"""'*|*'#'*) printf '%s' '없음'; return 0 ;; esac
  local n="${#q}" i=0 j k ch word prev nx instr=0 esc=0 pd=0 bd=0 ops=0
  local top=0 topname="" pend=0 mpd=-1 inm=0 nb=0 bin=0 rest=""
  while [ "$i" -lt "$n" ]; do
    ch="${q:i:1}"
    if [ "$instr" = 1 ]; then
      if [ "$esc" = 1 ]; then esc=0
      elif [ "$ch" = '\' ]; then esc=1
      elif [ "$ch" = '"' ]; then instr=0
      fi
      i=$((i + 1)); continue
    fi
    case "$ch" in
      '"') instr=1 ;;
      '(')
        pd=$((pd + 1))
        if [ "$pend" = 1 ]; then mpd="$pd"; inm=1; pend=0; fi ;;
      ')')
        if [ "$inm" = 1 ] && [ "$pd" = "$mpd" ]; then inm=0; fi
        pd=$((pd - 1)) ;;
      '{') [ "$bd" != 0 ] || ops=$((ops + 1)); bd=$((bd + 1)) ;;
      '}') bd=$((bd - 1)) ;;
      '.'|'@') printf '%s' '없음'; return 0 ;;
      [A-Za-z_])
        j=$((i + 1))
        while [ "$j" -lt "$n" ]; do
          case "${q:j:1}" in [A-Za-z0-9_]) j=$((j + 1)) ;; *) break ;; esac
        done
        word="${q:i:j-i}"
        prev=""; [ "$i" -eq 0 ] || prev="${q:i-1:1}"
        if [ "$prev" != '$' ]; then
          k="$j"
          while [ "$k" -lt "$n" ]; do
            case "${q:k:1}" in ' '|','|$'\t'|$'\n'|$'\r') k=$((k + 1)) ;; *) break ;; esac
          done
          nx="${q:k:1}"
          if [ "$bd" = 1 ] && [ "$pd" = 0 ] && [ "$nx" != ':' ]; then
            top=$((top + 1)); topname="$word"
            case "$word" in
              mergePullRequest) [ "$nx" != '(' ] || pend=1 ;;
            esac
          fi
          if [ "$word" = expectedHeadOid ]; then
            nb=$((nb + 1)); bin="$inm"; rest="${q:j}"
          fi
        fi
        i="$j"; continue ;;
    esac
    i=$((i + 1))
  done
  if [ "$instr" = 1 ] || [ "$ops" != 1 ] || [ "$top" != 1 ] || [ "$nb" != 1 ] || [ "$bin" != 1 ]; then
    printf '%s' '없음'; return 0
  fi
  case "$topname" in
    mergePullRequest) : ;;
    *) printf '%s' '없음'; return 0 ;;
  esac
  local v="" name g
  local re_str='^[[:space:]]*:[[:space:]]*"([^"]*)"'
  local re_var='^[[:space:]]*:[[:space:]]*[$]([A-Za-z_][A-Za-z0-9_]*)'
  if [[ "$rest" =~ $re_str ]]; then
    v="${BASH_REMATCH[1]}"
  elif [[ "$rest" =~ $re_var ]]; then
    name="${BASH_REMATCH[1]}"
    # gh sends every field but `query` and `operationName` as a variable, and
    # those two as the request's own keys. A `$operationName` bound to
    # `-f operationName=<HEAD>` is a variable the server never receives, so the
    # nullable `expectedHeadOid` goes unset and whatever head is there merges.
    # The same holds for every field when the endpoint is not written exactly
    # `graphql`: gh then sends the fields flat beside `query` rather than
    # inside `variables`, so `/graphql`, `graphql/`, `graphql?x=1` and the
    # absolute URL reach the same server with `$h` unset.
    case "$name" in query|operationName) name="" ;; esac
    [ "$GATE_GHAPI_ENDPOINT" = graphql ] || name=""
    for g in ${GATE_GHAPI_FIELDS[@]+"${GATE_GHAPI_FIELDS[@]}"}; do
      [ -n "$name" ] || break
      case "$g" in "$name="*) v="${g#*=}" ;; esac
    done
    case "$v" in @*) v="" ;; esac
  fi
  gate_merge_binding_value "$v"
}

# ---------------------------------------------------------------------------
# The head a remote merge is bound to.
#
# The review rule compares the review against the segment worktree's HEAD, and
# a remote merge merges whatever the pull request's head is on the server at
# that moment. Nothing tied the two together: a push after the check, or a
# worktree that never pushed its last commit, merged a head the rule had not
# looked at, and the ledger recorded a pass. The remote spellings carry an
# argument that makes the server refuse any other head — the REST merge's `sha`
# field, `gh pr merge --admin --match-head-commit <sha>` and the GraphQL
# `expectedHeadOid` — so the gate requires that argument and requires it to
# name the worktree HEAD. A merge spelling with no such argument (`…/merges`,
# `mergeBranch`), a REST write that moves a branch (`…/git/refs…`,
# `…/contents/…`, `…/merge-upstream`, `…/branches/<b>/rename`, and every other
# REST write outside the issue, pull request, label and comment endpoints), a
# `gh repo sync` that names a destination, one that merges after the request
# (`…/merge-async`, `--auto`,
# `enablePullRequestAutoMerge`, `enqueuePullRequest`, and a `gh pr merge`
# without `--admin`, which enables auto-merge or enters the merge queue on a
# base that requires one, `--match-head-commit` or not), a REST merge with a
# `sha` in its query string, a pull request path with a dot segment, an empty
# segment or a `%` escape, a gh call inside a `find -exec` whose words carry
# `{}`, and a GraphQL body in a file the gate does not read are merges with no
# binding, and are refused the same way.
# ---------------------------------------------------------------------------
gate_merge_binding_of_argv0() {
  # gate_merge_binding_of_argv0 <argv...> — prints `해당없음` when the argv is
  # not a remote merge spelling, `없음` when it is one carrying no usable
  # binding, and the bound sha otherwise. The wrapper unwraps are the ones
  # `ladder_of_argv0` shares, so a merge the ladder sees through a wrapper is
  # the merge this reads.
  local out=""
  if [ "$#" -ge 1 ]; then
    local cmd="${1##*/}"
    shift
    case "$cmd" in
      lockf)   out=$(gate_unwrap_lockf   gate_merge_binding_of_argv0 '해당없음' '해당없음' "$@") ;;
      command) out=$(gate_unwrap_command gate_merge_binding_of_argv0 '해당없음' '해당없음' "$@") ;;
      find)
        if gate_find_exec_substitutes gh "$@"; then
          out='없음'
        else
          out=$(gate_unwrap_find gate_merge_binding_of_argv0 '해당없음' '해당없음' '해당없음' gate_merge_binding_combine "$@")
        fi ;;
      rg)      out=$(gate_unwrap_rg      gate_merge_binding_of_argv0 '해당없음' '해당없음' "$@") ;;
      env)     out=$(gate_unwrap_env     gate_merge_binding_of_argv0 '해당없음' '해당없음' "$@") ;;
      timeout|nice|nohup|stdbuf)
               out=$(gate_unwrap_wrapper "$cmd" gate_merge_binding_of_argv0 '해당없음' '해당없음' "$@") ;;
      time)    out=$(gate_unwrap_time    gate_merge_binding_of_argv0 '해당없음' '해당없음' "$@") ;;
      gh)      out=$(gate_merge_binding_of_gh "$@") ;;
    esac
  fi
  printf '%s' "${out:-해당없음}"
}

gate_merge_binding_combine() {
  # Folds two answers for `find`, which can run several commands: a merge
  # anywhere in the argv decides, and an unbound one wins over a bound one.
  local a="$1" b="$2"
  if [ "$a" = '해당없음' ]; then printf '%s' "$b"
  elif [ "$b" = '해당없음' ]; then printf '%s' "$a"
  elif [ "$a" = "$b" ]; then printf '%s' "$a"
  else printf '%s' '없음'
  fi
}

gate_gh_api_query_names_sha() {
  # After `gate_gh_api_parse`: true when the endpoint's query string has a key
  # that is or may decode to `sha` — `sha`, `sha[…]`, or any key with a `%`
  # escape. Pairs are split at `&` and `;`, and a `#fragment` is not sent.
  #
  # THE SPLIT READS BYTES, AND A QUERY IT CANNOT READ NAMES `sha`. Split by a
  # bare `tr` in the run's UTF-8 locale, `?x=<byte>&sha=<X>` stopped macOS `tr`
  # at the byte with its status lost, so the query's `sha` went unseen and the
  # merge read as bound to its body `sha`. A query holding a byte outside
  # printable ASCII is not read at all (`gate_gh_api_endpoint_raw`).
  local q="$GATE_GHAPI_ENDPOINT" pair key pairs
  case "$q" in *'?'*) q="${q#*\?}" ;; *) return 1 ;; esac
  q="${q%%#*}"
  gate_gh_api_endpoint_raw "$q" && return 0
  pairs=$(printf '%s' "$q" | LC_ALL=C tr '&;' '\n\n') || return 0
  while IFS= read -r pair; do
    key="${pair%%=*}"
    case "$key" in
      sha|sha\[*|*%*) return 0 ;;
    esac
  done <<GATE_GHAPI_QUERY
$pairs
GATE_GHAPI_QUERY
  return 1
}

gate_merge_binding_value() {
  # A binding is a full lowercase sha. An abbreviation or a revision name is
  # resolved by the server against its own refs, which is the thing the
  # binding exists not to trust.
  case "$1" in
    *[!0-9a-f]*|'') printf '%s' '없음' ;;
    *) if [ "${#1}" = 40 ]; then printf '%s' "$1"; else printf '%s' '없음'; fi ;;
  esac
}

gate_merge_binding_of_gh() {
  # gate_merge_binding_of_gh <gh's args after argv0...>. The LAST occurrence of
  # the argument wins, as it does for gh's own flag parsing.
  #
  # A MERGE THAT HAPPENS LATER IS NOT BOUND. `gh pr merge --auto` enables
  # auto-merge or enters the merge queue, and GitHub compares
  # `--match-head-commit` only when the request is made; the merge itself comes
  # later, and a commit pushed to the head branch in between — a fix cycle's
  # push, for one — is what merges. So `--auto` answers `없음` whatever head it
  # names.
  #
  # NOR IS A BARE `gh pr merge`, WITHOUT `--admin`. On a base that requires a
  # merge queue it enables auto-merge while required checks are pending and
  # adds the pull request to the queue once they have passed — the same
  # compare-now, merge-later shape as `--auto`. Whether a base requires a
  # queue is not in the argv, so the gate reads a bare `gh pr merge` as
  # unbound on every target, `--match-head-commit` or not. `--admin` bypasses
  # the queue and merges at once, so with it `--match-head-commit` binds; that
  # argv then passes the binding check and the `인가-자기확장-금지` rule
  # refuses it. The spelling that binds on every base is the REST merge with
  # its `sha` field, which merges at once or is refused (405 on a queue base,
  # 409 on another head) and never enqueues.
  #
  # THE FLAGS ARE READ AS gh READS THEM, through the gh flag table. A value flag
  # takes the next word even when it starts with `-`, so in `-b
  # --match-head-commit=<HEAD>` the binding is the merge's body and in
  # `--match-head-commit <X> --body --match-head-commit=<HEAD>` gh binds X.
  # Skipping one word per unknown flag read both as bound to HEAD. A spelling
  # the table cannot read binds nothing.
  local have=0 v="" auto=0 kind
  local -a orig
  orig=("$@")
  kind=$(gate_gh_pr_merge_kind "$@")
  case "$kind" in
    form) printf '%s' '없음'; return 0 ;;
  esac
  # A `gh repo sync` with a destination moves that repository's branch with no
  # head to hold — see `gate_gh_repo_sync_remote`.
  if gate_gh_repo_sync_remote "$@"; then printf '%s' '없음'; return 0; fi
  gate_gh_strip_repo "$@"
  [ "$GATE_GH_API_UNREAD" = 0 ] || { printf '%s' '없음'; return 0; }
  set -- ${GATE_GH_ARGV[@]+"${GATE_GH_ARGV[@]}"}
  [ "$kind" != merge ] || set -- pr merge
  case "${1:-}" in
    pr)
      # Only a `pr merge` the parse found gets here; any other `pr` verb binds
      # nothing because it merges nothing.
      [ "$kind" = merge ] || { printf '%s' '해당없음'; return 0; }
      gp_parse gh ${orig[@]+"${orig[@]}"}
      if v=$(gp_opt match-head-commit); then have=1; else v=""; fi
      if gp_has auto; then auto=1; fi
      if [ "$auto" = 1 ]; then printf '%s' '없음'; return 0; fi
      gp_has admin || { printf '%s' '없음'; return 0; } ;;
    api)
      shift
      gate_gh_api_parse "$@"
      local mk fv
      mk=$(gate_gh_api_merge_kind)
      case "$mk" in
        graphql)
          if [ "$GATE_GHAPI_OPAQUE" = 1 ]; then printf '%s' '없음'; return 0; fi
          gate_gh_graphql_binding; return 0 ;;
        # `…/merges` has no argument the server holds the head to, whatever
        # fields it carries, and neither does a GraphQL ref write: the
        # `expectedHeadOid` of `createCommitOnBranch` pins the branch it writes
        # on, not the content it puts there.
        # Nor does a pull request path the gate cannot read as written: the
        # endpoint a `sha` field would reach is the server's resolution of it.
        # Nor does the background merge, which merges after the request, nor
        # a REST ref write, which moves a branch with no head to hold.
        branch|graphql-ref|rest-unbound|rest-async|rest-ref) printf '%s' '없음'; return 0 ;;
        rest) : ;;
        *)
          # A GraphQL body this gate cannot read may be a merge it cannot
          # bind; where a binding is asked for, that is no binding.
          case "$GATE_GHAPI_PATH" in
            graphql|*/graphql)
              if [ "$GATE_GHAPI_OPAQUE" = 1 ]; then
                case "$GATE_GHAPI_METHOD" in GET|get|HEAD|head) : ;; *) printf '%s' '없음'; return 0 ;; esac
              fi ;;
          esac
          printf '%s' '해당없음'; return 0 ;;
      esac
      # `-F sha=@<file>` and `--input` put the value in a file this gate does
      # not read, so they bind nothing it can compare.
      if [ "$GATE_GHAPI_OPAQUE" = 1 ]; then printf '%s' '없음'; return 0; fi
      # A `sha` IN THE QUERY STRING IS A SECOND VALUE THE SERVER MAY READ. gh
      # sends the endpoint's query as written, and the parse drops it, so
      # `…/merge?sha=<X>` with `-f sha=<HEAD>` showed this reading the HEAD
      # while the server received both — and which one a server takes when
      # the two collide is not something this gate can know. Such a merge is
      # no binding. Other query keys (`merge_method`) are left alone.
      if gate_gh_api_query_names_sha; then printf '%s' '없음'; return 0; fi
      for fv in ${GATE_GHAPI_FIELDS[@]+"${GATE_GHAPI_FIELDS[@]}"}; do
        case "$fv" in
          sha=*) have=1; v="${fv#sha=}" ;;
        esac
      done
      case "$v" in @*) v="" ;; esac ;;
    *) printf '%s' '해당없음'; return 0 ;;
  esac
  if [ "$have" = 1 ]; then gate_merge_binding_value "$v"; else printf '%s' '없음'; fi
}

ladder_of_terraform() {
  # The same global skip `surface_of_terraform` performs, so `terraform -chdir=x
  # apply` reads like `terraform apply`.
  while [ $# -gt 0 ]; do
    case "$1" in
      -chdir=*|-help|-version|--help|--version) shift ;;
      -*) return 0 ;;
      *) break ;;
    esac
  done
  case "${1:-}" in
    # `배포` and not `머지`: these two change an environment, and the ladder puts
    # that rung above merge. `state rm`/`import` reach production state too, but
    # they are not the rung a manifest authorizes a deploy for — silence there
    # keeps the declared value, and the axis-2 grade already refuses them out of
    # a read.
    apply|destroy) printf '배포' ;;
    *) : ;;
  esac
  return 0
}

# ---------------------------------------------------------------------------
# Ledger append — serialized, capped, chained.
#
# run.sh's comment says the ledger has one writer, and that is true of the
# COMPONENT: one function appends. It is not true of the PROCESSES — every gate
# invocation is its own shell, so two acts in flight are two writers against one
# file. Concurrent appends splice field values above 1024 bytes of total line
# length while the line count stays correct, which no row-grammar check can see.
# Three things together close that: the lock makes interleaving rare, the cap
# keeps a row under the measured threshold, and the chain makes the rare case
# detectable rather than silent.
# ---------------------------------------------------------------------------
# Every read below goes through this. A ledger that does not exist yet is the
# NORMAL state at the first act of a run, and `grep` answers a missing file with
# exit 2 — which `pipefail` promotes to the whole pipeline's status and `set -e`
# turns into a silent exit of the snapshot. The first act of the first run is
# exactly when a router most needs the snapshot to answer, so the tolerance is
# not defensive padding: it is the case that always happens.
#
# THE READ-ZONE MEMO. The four `GATE_ROWS_MEMO_*` names exist only as `local`s
# of a warming function (see `gate_ledger_warm`), so they are cleared here at
# load. A caller whose environment carried one of them in would otherwise have
# that scalar read as element 0 of the memo, and `gate_rows` would answer rows
# the ledger does not hold.
unset GATE_ROWS_MEMO_LEDGER GATE_ROWS_MEMO_N GATE_ROWS_MEMO_KINDS GATE_ROWS_MEMO_ROWS
gate_rows() {
  # gate_rows <series>
  #
  # Inside a warmed zone a series the zone warmed is answered from the memo,
  # with builtins only, so the read spawns no process. The memo is consulted
  # only while `LEDGER` is still the path it was filled from; a string compare,
  # not a freshness probe — a probe would be a process per call, the very cost
  # the memo removes. Everything else falls through to the grep, unchanged.
  if [ -n "${GATE_ROWS_MEMO_LEDGER:-}" ] && [ "$GATE_ROWS_MEMO_LEDGER" = "$LEDGER" ]; then
    local m=0
    while [ "$m" -lt "${GATE_ROWS_MEMO_N:-0}" ]; do
      if [ "${GATE_ROWS_MEMO_KINDS[$m]}" = "$1" ]; then
        [ -z "${GATE_ROWS_MEMO_ROWS[$m]}" ] || printf '%s\n' "${GATE_ROWS_MEMO_ROWS[$m]}"
        return 0
      fi
      m=$((m + 1))
    done
  fi
  grep -E "^- \`$1\`" "$LEDGER" 2>/dev/null || true
}

gate_has_row() {
  # gate_has_row <series> <키=값> [<키=값>…]
  #
  # True only when ONE row of the series carries, for every argument, a field
  # that is byte-identical to it — the whole field between two ` | `
  # separators (or between the last one and the end of the row), never a
  # substring of the row. A substring read takes a key spelled inside another
  # field's value, a key that ends another key (`사유=` inside `처분 사유=`) and
  # an id that prefixes another id as the field asked for, and a needle that
  # joins two fields with a space matches nothing at all, so the guard it
  # protects never fires and no one can tell that from "correctly absent". A
  # field split cannot read any of those as the field.
  #
  # Each argument is normalized first: one leading `|`, one trailing `|` and the
  # whitespace around them are dropped, so the anchored `"| 키=값 |"` spelling
  # the older call sites use names the same field as a bare `"키=값"`, and those
  # sites read unchanged. An argument is ONE field; two fields are two
  # arguments, and they are joined on the same row — two fields found on two
  # different rows are not a hit. No argument, or one that normalizes to
  # nothing, is "absent".
  #
  # WHAT THIS DOES NOT DEFEND. The answer is sound only while every writer keeps
  # the row grammar, removing `|` and line breaks from keys and values alike. A
  # ` | ` spliced into a row by a writer that skipped that step is, at the byte
  # level, a real separator, and nothing on the reading side can tell it from
  # one the writer meant; the defense for that is in the writers.
  #
  # NOT `gate_rows X | grep -qF Y`. Under `pipefail` an early-exiting reader on
  # the right of a pipe kills the writer with SIGPIPE and the pipeline reports
  # failure — so a row that IS present can come back as "absent", and every one
  # of these call sites uses absence to decide whether to append. The result
  # would be duplicate approvals and duplicate obligations, which the
  # termination conditions then count. The match below is builtins only, so it
  # adds no process to the one read `gate_rows` makes (none inside a warmed zone).
  local series="$1" out w row nl=$'\n'
  local -a want
  shift
  [ "$#" -gt 0 ] || return 1
  want=()
  for w in "$@"; do
    w="${w#"${w%%[![:space:]]*}"}"; w="${w#|}"; w="${w#"${w%%[![:space:]]*}"}"
    w="${w%"${w##*[![:space:]]}"}"; w="${w%|}"; w="${w%"${w##*[![:space:]]}"}"
    [ -n "$w" ] || return 1
    want+=("$w")
  done
  out=$(gate_rows "$series")
  [ -n "$out" ] || return 1
  # Every field is preceded by ` | ` (the series token is the row's head and
  # never a field), and is followed by ` | ` or by the end of its row.
  for w in "${want[@]}"; do
    case "$out$nl" in *" | $w | "*|*" | $w$nl"*) ;; *) return 1 ;; esac
  done
  [ "${#want[@]}" -gt 1 ] || return 0
  while IFS= read -r row; do
    row="$row | "
    for w in "${want[@]}"; do
      case "$row" in *" | $w | "*) ;; *) continue 2 ;; esac
    done
    return 0
  done <<EOF
$out
EOF
  return 1
}

gate_count() {
  # Count of non-empty lines on stdin. `grep -c` answers 0 with exit 1 on empty
  # input, so the usual `|| printf 0` fallback prints a SECOND zero and the
  # caller ends up interpolating `0\n0` — which produced a syntactically
  # invalid snapshot object rather than a wrong number, so nothing downstream
  # could even read far enough to notice.
  grep -c . || true
}

gate_ledger_warm() {
  # gate_ledger_warm <series>... — read each named series from the ledger ONCE
  # and hold it for the rest of the calling function.
  #
  # THE CALLER DECLARES THE FOUR `GATE_ROWS_MEMO_*` NAMES `local` BEFORE CALLING.
  # That is what bounds the memo: bash scopes dynamically, so everything the
  # caller calls — `$( )` subshells included — reads these values, nothing above
  # the caller sees them, and they are gone when the caller returns. There is no
  # invalidation because the zone has no append in it: a warmed function reads
  # one ledger state from top to bottom, where unwarmed it could see a different
  # state on every call. A row another process appends mid-zone shows up in the
  # next zone.
  #
  # The grep is called directly, never through `gate_rows` or `gate_has_row` —
  # the cost pins in `scripts/test-measure-gate-cost.sh` rest on the fixed paths
  # not calling `gate_has_row`. Command substitution strips the trailing newline
  # and `gate_rows` puts it back with `printf '%s\n'`; every matched line starts
  # with `` - ` `` and so is never empty, which makes the final newline the only
  # one stripped and the answer byte-identical to the grep.
  local k n=0
  for k in "$@"; do
    GATE_ROWS_MEMO_KINDS[$n]="$k"
    GATE_ROWS_MEMO_ROWS[$n]=$(grep -E "^- \`$k\`" "$LEDGER" 2>/dev/null || true)
    n=$((n + 1))
  done
  GATE_ROWS_MEMO_N=$n
  GATE_ROWS_MEMO_LEDGER="$LEDGER"
}

gate_chain_tip() {
  # The digest of the ledger's last ROW, or of the run block heading when no row
  # has been written yet.
  #
  # Rows and not lines, and the difference was not cosmetic. The ledger file is
  # also the morning report, so prose lands in it between rows — the kickoff's
  # stub alone puts two lines there before any act. Hashing the last LINE made
  # the first row point at the stub's identifying line while the verifier, which
  # walks rows, started from the heading, so an UNTOUCHED ledger read as broken
  # at row 1 on every run.
  #
  # A permanently broken chain is worse than no chain: a real splice then looks
  # exactly like a normal kickoff, and a reader who sees `끊김` every morning
  # learns to skip the one field that would have told them.
  #
  # The body lives in `run.sh` as `run_chain_tip`, byte for byte, locale pin
  # included — the driver writes chained rows too, and the unlocked fallback of
  # the shared append reads the tip from there. This name stays for the callers
  # that already read it. Byte-exact for the same reason `gate_chain_verify` is:
  # this is the value the verifier's walk is compared against, so a locale that
  # changed one and not the other would manufacture breaks out of nothing.
  run_chain_tip
}

gate_ancestry_window() {
  # The last GATE_ANCESTRY_WINDOW rows — the set an observed tip may still be an
  # ancestor from. See that constant for why the window is a bound on concurrent
  # writers rather than on elapsed time.
  #
  # ROWS AND NOT LINES, for the reason gate_chain_tip records one function up:
  # the ledger is also the morning report, so prose lands in it between rows.
  # Reading raw lines would let a few paragraphs shrink the window without
  # anybody choosing to, and the shrink would show up as a refusal nobody could
  # explain.
  { grep '^- `' "$LEDGER" 2>/dev/null || true; } | tail -n "$GATE_ANCESTRY_WINDOW"
}

gate_append_cost() {
  # gate_append_cost <이번 스테이지 usd> <스테이지 수> <관측 시각>
  #
  # THE ACCUMULATION IS READ AND WRITTEN INSIDE ONE LOCK, and it used to be a
  # read outside the lock followed by a write inside one. `gate_append`'s own
  # header records the same defect for the chain tip and the same repair; this
  # is that repair applied to the other read-then-act in this file.
  #
  # The cost row accumulates, so the value that makes it correct is the previous
  # row's total. Two stages terminating together both read the same previous
  # total and both wrote `prev + own`, and the second write erased the first —
  # not a corrupt row, a QUIET one. The run's only cost figure is then a lower
  # bound that nothing announces as one, and the cost ceiling is a boundary that
  # decides when the night ends. Measured: 80 cost rows written and a final
  # accumulation of roughly half the sum of what they carried.
  #
  # `gate_append` CANNOT ABSORB THIS, and that is why there is a second writer.
  # Its critical section starts after the body is assembled, and the body is
  # what depends on the read — widening it would mean handing `gate_append` a
  # per-series accumulation rule.
  #
  # The locked command is `/bin/sh` and cannot see this shell's functions, so
  # `gate_rows` and `gate_chain_tip` are re-spelled inline against `$LEDGER`,
  # exactly as the chain tip already is. Both row prefixes travel as positional
  # arguments so the backticks in them are parsed by neither shell.
  #
  # The row is fixed-shape — two numbers and a timestamp — so it cannot approach
  # the row cap `gate_append` checks, and no value in it can carry a separator.
  local cost="$1" n_stage="$2" at="$3" tool rc=0
  tool=$(lock_tool)
  # The same selection-versus-observation rule `gate_append` states above: a
  # platform-selected path is used only if the file is actually there.
  if [ -n "$tool" ] && [ -x "$tool" ] && [ -n "${RUN_DIR:-}" ]; then
    "$tool" -k "$RUN_DIR/ledger.lock" \
      /bin/sh -c '
        led=$2
        prevusd=$(grep "$7" "$led" 2>/dev/null | tail -1 | tr "|" "\n" \
                  | sed -n "s/^ *누적 usd=//p" | tr -d " " | tail -1)
        total=$(awk -v a="${prevusd:-0}" -v b="$1" "BEGIN{ printf \"%.4f\", a + b }")
        body="$8 | 누적 usd=$total | 스테이지 수=$3 | 관측 시각=$4"
        last=$(grep "$5" "$led" 2>/dev/null | tail -1)
        [ -n "$last" ] || last=$6
        prev=$(printf "%s" "$last" | shasum -a 256 | cut -d" " -f1)
        printf "%s | prev=%s\n" "$body" "$prev" >> "$led"
      ' _ "$cost" "$LEDGER" "$n_stage" "$at" '^- `' "## 실행 $RUN_ID" '^- `cost`' '- `cost`' || rc=$?
  else
    # THIS BRANCH IS NOT SERIALIZED, and the comment here used to claim it did
    # not need to be — "no lock tool means no concurrency to serialize", which
    # is a statement about the platform rather than about this code. The
    # accurate statement is narrower: the branch is reached only where
    # `lock_tool` yields an empty string, the refusal that keeps the pipeline
    # off such a host lives in `run.sh`'s `main`, and the gate sources that file
    # for its definitions without ever executing `main`. So the protection is
    # real but it is somewhere else, and two concurrent writers arriving here
    # would lose an accumulation exactly as the header describes. The sequence
    # below is the locked one with the lock removed; behaviour is unchanged.
    local prevusd total
    prevusd=$(gate_rows 'cost' | tail -1 | tr '|' '\n' \
              | sed -n 's/^ *누적 usd=//p' | sed 's/[[:space:]]*$//' | tail -1)
    total=$(awk -v a="${prevusd:-0}" -v b="$cost" 'BEGIN{ printf "%.4f", a + b }')
    printf '%s | prev=%s\n' \
      "- \`cost\` | 누적 usd=$total | 스테이지 수=$n_stage | 관측 시각=$at" \
      "$(gate_chain_tip)" >> "$LEDGER" || rc=$?
  fi
  [ "$rc" = "0" ] || die "could not write the ledger row (rc=$rc) — an act with no record is not performed: cost"
  return 0
}

gate_row_body() {
  # gate_row_body <계열> <field=value> ... — the row text `gate_append` will write
  # for these arguments, minus the ` | prev=<sha256>` tail: separators mapped
  # out of every key and value, the shift number added unless the caller
  # supplied one. THE ONE DEFINITION OF THE ROW GRAMMAR — `gate_append` builds
  # its body through this, and a caller that has to know a row's length before
  # deciding what goes on it (`gate_row_projected_bytes`) reads the same
  # function, so the two cannot disagree about what a row looks like.
  #
  # The grammar itself is `run_row_body` in `run.sh`, so the driver's chained
  # rows are built by the same text; this name is its gate-side spelling.
  run_row_body "$@"
}

gate_row_bytes_of_body() {
  # gate_row_bytes_of_body <body> — the byte count `gate_append` compares
  # against `GATE_ROW_MAX`: the body, a 64-character stand-in for `prev` and the
  # newline, BYTES by `wc -c`. The measurement is `run_row_bytes_of_body`, which
  # knows no cap; the cap stays this file's.
  run_row_bytes_of_body "$1"
}

gate_row_projected_bytes() {
  # gate_row_projected_bytes <계열> <field=value> ... — the byte count the row
  # these arguments would produce will be measured at, by the same ruler
  # `gate_append` uses. For a writer that may drop an optional field to keep a
  # row under the cap: project with the field, and without it if that is over.
  gate_row_bytes_of_body "$(gate_row_body "$@")"
}

gate_base_tree_state() {
  # gate_base_tree_state <dir> — two words on one line, `<tracked> <untracked>`,
  # each `있음` / `없음`, or `(미상) (미상)` when the directory or `git status`
  # does not answer. Tracked is every porcelain line that is not `??`: a
  # modified, staged, deleted or conflicted tracked file. One `git status`, so
  # the two values describe the same instant.
  local out
  if ! out=$( cd "$1" 2>/dev/null && git --no-optional-locks status --porcelain 2>/dev/null ); then
    printf '(미상) (미상)\n'
    return 0
  fi
  printf '%s\n' "$out" | LC_ALL=C awk '
    BEGIN { t = "없음"; u = "없음" }
    /^\?\? / { u = "있음"; next }
    NF { t = "있음" }
    END { print t, u }'
}

gate_base_check_baseline() {
  # gate_base_check_baseline <dir> — whether every script the base's `make
  # check` would call exists: `녹색`, `적색(<missing>, …)`, `(해당 없음)` when
  # the base has no makefile, `(미상)` when `make -n` itself fails.
  #
  # `-n` PRINTS THE RECIPES AND RUNS NONE OF THEM, which is why this is cheap
  # enough for kickoff and leaves the tree as it found it. It is not zero
  # execution: make still evaluates the makefile's own `$(shell …)` and runs
  # recursive `$(MAKE)` lines with `-n` passed down. What is extracted is the
  # tokens ending in `.sh`; one carrying `$` or `=` is an expansion or an
  # assignment and is not a path this can check, so it is left out rather
  # than guessed at. The question answered is therefore "is a script missing",
  # not "is the check green" — the one kind of red a nightly stage cannot have
  # caused and would otherwise take for its own.
  local dir="$1" out tok p missing=""
  if [ ! -f "$dir/GNUmakefile" ] && [ ! -f "$dir/makefile" ] && [ ! -f "$dir/Makefile" ]; then
    printf '(해당 없음)'
    return 0
  fi
  if ! out=$(make -n -C "$dir" --no-print-directory check 2>/dev/null); then
    printf '(미상)'
    return 0
  fi
  # Separators are whitespace, the shell operators and the three quotes; a
  # subshell's parentheses are stripped from the token's ends afterwards.
  for tok in $(printf '%s\n' "$out" | LC_ALL=C awk '{
      n = split($0, a, "[ \t;&|<>\"\047`]+")
      for (i = 1; i <= n; i++) {
        t = a[i]; sub(/^\(+/, "", t); sub(/\)+$/, "", t)
        if (t ~ /^[A-Za-z0-9_.\/][A-Za-z0-9_.\/-]*\.sh$/) print t
      }
    }' | LC_ALL=C sort -u); do
    case "$tok" in /*) p="$tok" ;; *) p="$dir/$tok" ;; esac
    [ -e "$p" ] || missing="$missing${missing:+, }$tok"
  done
  if [ -n "$missing" ]; then printf '적색(%s)' "$missing"; else printf '녹색'; fi
}

gate_base_check_baseline_fit() {
  # gate_base_check_baseline_fit <value> <room in bytes> — the baseline value
  # the `run` row can carry. The row is never lost to this field: a red value
  # that does not fit keeps its colour and its count, `적색(<n>개 — 행 길이로
  # 생략)`, and anything that still does not fit is `생략(행 길이)` — the
  # spelling the segment row already uses for the field it may drop. The full
  # list goes to the log whenever it is shortened, so it is recorded
  # somewhere a person reads.
  local v="$1" room="$2" n short
  if [ "$(printf '%s' "$v" | wc -c | tr -d ' ')" -le "$room" ]; then
    printf '%s' "$v"
    return 0
  fi
  warn "the base-check baseline does not fit the run row and is shortened — full value: $v"
  case "$v" in
    '적색('*)
      n=$(printf '%s' "${v#'적색('}" | LC_ALL=C awk -F', ' '{ print NF }')
      short="적색(${n}개 — 행 길이로 생략)"
      if [ "$(printf '%s' "$short" | wc -c | tr -d ' ')" -le "$room" ]; then
        printf '%s' "$short"
        return 0
      fi
      ;;
  esac
  printf '생략(행 길이)'
}

gate_append() {
  # gate_append <계열> <field=value> ...
  #
  # The writer hashes what it INTENDED to write, not a re-read of the file — a
  # chain built from a re-read certifies whatever landed, including a splice.
  # THE CHAIN TIP IS READ INSIDE THE LOCK, and it used to be read outside it.
  # This is a read-then-act whose critical section excluded the value that makes
  # the row correct: two concurrent appends read the same tip and both wrote
  # rows carrying the same `prev`, so the verifier reported a break for a ledger
  # nobody had touched. Measured on a 227-row ledger written by one stage going
  # through the gate for each of its Bash calls — rows 85 and 86 chained to the
  # same parent, both present and well-formed, and the run was told it had been
  # spliced.
  #
  # A false break is worse than no chain: a real splice then looks exactly like
  # the noise a reader has learned to skip.
  local series="$1"; shift
  local body f k v

  # EVERY FIELD IS MADE ROW-SAFE HERE, KEY AND VALUE ALIKE, NOT AT THE CALL
  # SITES.
  #
  # `|` separates fields and a newline ends the row, so a value carrying either
  # SPLICES the grammar. `gate_row_safe` performs exactly this transform but is
  # applied to a hand-picked few fields, and the values the ROUTER supplies —
  # `사유`, `근거`, `선행`, `선언 파일 집합`, `의존 세그먼트`, `재개 명령` —
  # went in raw. Korean review prose contains pipes routinely.
  #
  # What made that more than untidy is that the write-time checks and the
  # readers had DIFFERENT FIELD VIEWS. A check reads the argv list through
  # `gate_field_of`, one element per field; every reader splits the row TEXT on
  # `|`. A pipe inside one argv element is invisible to the first and is a new
  # field to the second, so `사유=… | 스코프=run` passed the cone check as
  # `cone` and then enumerated as an unresolved run-scope block in termination
  # condition 5. The same splice reached `gate_segment_ids`, which extracted the
  # id with a greedy `id=` pattern and therefore took the LAST match, changing
  # which segment a row is about. That extraction now splits the row on its own
  # separators (`gate_row_ids`), so neither a splice nor a value that merely ends
  # in `id=` can be read as the key — the normalization below and that split are
  # two independent reasons the id field is now the only thing answering for it.
  #
  # Normalizing before the body is assembled collapses the two views into one:
  # after this loop no field value can contain a separator, so reading the argv
  # and reading the row give the same answer by construction — and no writer
  # added later can forget. A value that legitimately needs a pipe uses the
  # contract's other answer (a fence plus its info string); the one value in this
  # file that used `|` as an internal separator now spells it `/`.
  #
  # THE KEY HALF USED TO GO THROUGH UNTRANSFORMED, and the header above said
  # "every field value" because that was all this loop did. It split `키=값`,
  # mapped the separators out of the VALUE, and put the key back exactly as the
  # caller spelled it — so a caller that spliced BEFORE the first `=` kept both
  # characters. A pipe there forges a field boundary; a newline there forges a
  # whole second ROW, and among the rows worth forging is a `승인` row saying
  # `상태=승인`. Both halves take the same two maps now. `%%=*` guarantees the key
  # holds no `=`, so reassembling cannot change how many fields the row has, and
  # for every field this file writes today the key transform is the identity.
  # An argument with no `=` skipped that split altogether and went in exactly as
  # passed, so it could carry the same pipe or newline; every argument is now
  # mapped as a whole before the `case`, which makes that branch row-safe too.
  # Rotated through the positional parameters rather than collected into an
  # array: the interpreter floor is bash 3.2 and the argument list is the one
  # ordered container available without one.
  #
  # `--transition <승인 id> <허용 상태…> <처분 사유 금지 0|1>` RIGHT AFTER THE
  # SERIES makes the append conditional on that approval's last row, re-read
  # INSIDE the lock: its `상태` must be one of the space-separated allowed
  # states, and with the third value `1` its `처분 사유` must be empty or `-`.
  # When it is not, nothing is written and this returns 90 instead of dying — a
  # refused transition is an answer the caller acts on, not a lost row. Taken as
  # arguments rather than read from variables so a value in the environment can
  # never turn an ordinary append into a conditional one; placed after the
  # series so every call site still opens with the literal series name the
  # field table lint reads.
  local guard_id="" guard_states="" guard_noreason="0"
  if [ "${1:-}" = "--transition" ]; then
    guard_id="$2"; guard_states="$3"; guard_noreason="$4"
    shift 4
  fi
  # THE TWO ROUTING SERIES ARE CHECKED ON THE ARGUMENTS AS PASSED, before the
  # normalization below: once `|` has become `/` a check can no longer see that
  # a value was two. The check is `run.sh`'s, the same one the driver's writer
  # runs, so the two writers refuse the same inputs; a refusal is rc 2 there and
  # the vocabulary exit here, with nothing written.
  case "$series" in
    stage-lease|stage-wait)
      run_ledger_series_check "$series" "$@" || return "$GATE_EXIT_VOCAB" ;;
  esac
  local n_args=$# i=0
  while [ "$i" -lt "$n_args" ]; do
    f="$1"; shift; i=$((i + 1))
    f=$(printf '%s' "$f" | tr '|' '/' | tr '\n\r' '  ')
    case "$f" in
      *=*) k="${f%%=*}"; v="${f#*=}"
           k=$(printf '%s' "$k" | tr '|' '/' | tr '\n\r' '  ')
           v=$(printf '%s' "$v" | tr '|' '/' | tr '\n\r' '  ')
           f="$k=$v" ;;
    esac
    set -- "$@" "$f"
  done

  # THE SCOPE CHECK SITS HERE AND NOT AT THE CALL SITES. Cone rows are appended
  # through this function rather than through `park()`, and the four literal
  # spellings already in this file plus every one added later are covered in one
  # place by putting the check where the row is actually written. It runs AFTER
  # the normalization above so that what it reads is what the row will say.
  if [ "$series" = "blocked" ]; then
    local scope=""
    for f in "$@"; do
      case "$f" in 스코프=*) scope="${f#스코프=}" ;; esac
    done
    gate_check_scope "$scope" || return "$GATE_EXIT_VOCAB"
  fi
  # THE APPROVAL STATE IS CHECKED HERE FOR THE SAME REASON. Every reader of the
  # `승인` series takes the last row's `상태` as current and compares it against
  # literals, so a value outside the set is not a row that says something odd —
  # it is an approval no reader can see as open, closed, or anything. `철회` is
  # in the set and written by nothing yet; the check accepts it because the
  # vocabulary is the contract's and not the caller list's.
  if [ "$series" = "승인" ]; then
    local astate=""
    for f in "$@"; do
      case "$f" in 상태=*) astate="${f#상태=}" ;; esac
    done
    gate_check_approval_state "$astate" || return "$GATE_EXIT_VOCAB"
  fi

  # THE SHIFT SCALE IS ADDED HERE, WHERE EVERY ROW IS WRITTEN AND NOWHERE
  # ELSE. The morning report asks how many routing shifts ran after the
  # instruction files were applied, and no row carried a shift number at all —
  # so the question had no scale to be answered on. Put on one series it could
  # only count that series; put here it is on every row by construction, and a
  # writer added later cannot forget it.
  #
  # A caller that supplies its own `교대` keeps it. The `handoff` row names the
  # shift that is ENDING, which is the number as of before this row — the same
  # value this function would derive, stated by the writer that knows why.
  # Deriving it a second time would put two spellings of one field on one row.
  body=$(gate_row_body "$series" "$@")

  # The length check runs on the body plus a 64-character stand-in, because
  # `prev` is a sha256 in every case and its width is therefore known before the
  # value is. Deferring the whole check into the lock would put a `die` inside
  # the critical section. THE MEASUREMENT IS `gate_row_bytes_of_body`, shared
  # with `gate_row_projected_bytes`: a caller that decides what to put on a row
  # by how long the row will be has to be measuring with this ruler, and two
  # rulers is how a projection passes and the append dies.
  local n
  n=$(gate_row_bytes_of_body "$body")
  if [ "$n" -gt "$GATE_ROW_MAX" ]; then
    die "the ledger row is over the cap (${n} > ${GATE_ROW_MAX} bytes) — a long value has to be moved out to a sidecar: ${series}"
  fi

  # An UNGUARDED append is `run_chained_append`, the tail the driver's writer
  # shares: the same locked script with the guard arguments absent, which is
  # what the script below does when `$5` is empty, so the bytes are the same.
  # The guarded tail stays here because its unlocked fallback reads the
  # approval through functions only this file defines.
  local tool rc=0
  if [ -z "$guard_id" ]; then
    run_chained_append "$body" || rc=$?
    [ "$rc" = "0" ] || die "could not write the ledger row (rc=$rc) — an act with no record is not performed: ${series}"
    return 0
  fi

  # The tip logic is inlined rather than calling `gate_chain_tip`, because the
  # locked command is `/bin/sh` and cannot see this shell's functions. The row
  # prefix is passed as a positional argument so the backtick in it is never
  # parsed by either shell.
  tool=$(lock_tool)
  # THE TOOL IS SELECTED BY PLATFORM AND USED ONLY IF IT IS THERE. Selection
  # answers "which lock does this platform use"; it does not observe the file.
  # The suite drives the darwin branches on any runner by injecting the host OS,
  # so on a linux runner this arm was reached with a BSD path that does not
  # exist — the locked command failed, the row was never appended, and the
  # assertion above it read an empty ledger. Falling through on absence is the
  # same disposition the comment below already states for "no tool at all".
  if [ -n "$tool" ] && [ -x "$tool" ] && [ -n "${RUN_DIR:-}" ]; then
    "$tool" -k "$RUN_DIR/ledger.lock" \
      /bin/sh -c '
        if [ -n "$5" ]; then
          grow=$(grep -- "$8" "$2" 2>/dev/null | grep -F -- "| 승인 id=$5 |" | tail -1)
          gst=$(printf "%s" "$grow" | tr "|" "\n" | sed -n "s/^ *상태=//p" | sed "s/[[:space:]]*\$//" | tail -1)
          [ -n "$gst" ] || exit 90
          case " $6 " in *" $gst "*) ;; *) exit 90 ;; esac
          if [ "$7" = "1" ]; then
            grsn=$(printf "%s" "$grow" | tr "|" "\n" | sed -n "s/^ *처분 사유=//p" | sed "s/[[:space:]]*\$//" | tail -1)
            case "$grsn" in ""|-) ;; *) exit 90 ;; esac
          fi
        fi
        last=$(grep "$3" "$2" 2>/dev/null | tail -1)
        [ -n "$last" ] || last="$4"
        prev=$(printf "%s" "$last" | shasum -a 256 | cut -d" " -f1)
        printf "%s | prev=%s\n" "$1" "$prev" >> "$2"
      ' _ "$body" "$LEDGER" '^- `' "## 실행 $RUN_ID" \
        "$guard_id" "$guard_states" "$guard_noreason" '^- `승인` ' || rc=$?
  else
    # No lock tool means no concurrency to serialize, so the same sequence is
    # correct here — it is the interleaving that the lock removes, not the order.
    local prev gst grsn
    if [ -n "$guard_id" ]; then
      gst=$(gate_approval_state "$guard_id")
      case " $guard_states " in
        *" ${gst:-미상} "*) ;;
        *) rc=90 ;;
      esac
      if [ "$rc" = "0" ] && [ "$guard_noreason" = "1" ]; then
        grsn=$(gate_row_field "$(gate_approval_last_row "$guard_id")" '처분 사유')
        case "$grsn" in ''|-) ;; *) rc=90 ;; esac
      fi
    fi
    if [ "$rc" = "0" ]; then
      prev=$(gate_chain_tip)
      printf '%s | prev=%s\n' "$body" "$prev" >> "$LEDGER" || rc=$?
    fi
  fi
  if [ "$rc" = "90" ] && [ -n "$guard_id" ]; then
    return 90
  fi
  # A LOST ROW IS NOT A WARNING. The whole design forbids an act with no row, so
  # an append that fails — an unwritable lock path, a full disk, a bad ledger
  # path — has to stop the act rather than let it proceed unrecorded. This
  # failed silently once: with `RUN_DIR` empty the lock path became `/ledger.lock`,
  # every append failed, and the caller went on believing it had written.
  [ "$rc" = "0" ] || die "could not write the ledger row (rc=$rc) — an act with no record is not performed: ${series}"
  return 0
}

# ---------------------------------------------------------------------------
# Progress vector and its digest.
#
# This is NOT the snapshot. The snapshot is what the router reads and is
# deliberately rich; P is what stagnation is measured over and is deliberately
# poor. Excluded on purpose: cost (monotone), recurrence counts (monotone),
# the no-progress counter itself (self-referential), timestamps, absolute paths,
# and — the one that is easy to get wrong — pending approvals.
#
# Pending approvals are excluded because every boundary that fires ISSUES one.
# With them inside, the boundary's own remedy mutates the hashed input and
# resets the counter that fired it, so the bound can never be reached. That is
# the same defect one layer up from the counter-inside-its-own-hash bug this
# design was written to remove.
# ---------------------------------------------------------------------------
gate_progress_vector() {
  local a
  local GATE_ROWS_MEMO_LEDGER GATE_ROWS_MEMO_N GATE_ROWS_MEMO_KINDS GATE_ROWS_MEMO_ROWS
  gate_ledger_warm segment cycle '자율 승인' stage-result '종료 절' blocked
  printf 'goal=%s\n' "$(manifest_field '인가' '종료 지점' | shasum -a 256 | cut -d' ' -f1)"
  for a in $(target_aliases); do
    printf 'target=%s|%s|%s\n' "$a" \
      "$(target_field "$a" '원격 슬러그')" "$(target_field "$a" '절단점')"
  done | sort
  gate_rows 'segment' | gate_row_ids | sort -u \
    | while IFS= read -r sid; do
        [ -n "$sid" ] || continue
        # STATE ONLY. `커밋` used to sit here and it moved nothing: removing the
        # component outright changed the worst-case window on 0 of 43 replayed
        # ledgers, and the top fifteen matched to the digit. It is not a broken
        # progress input, it is an input that does nothing — carried by 5 of 259
        # segment rows, because the router contract's row grammar names four
        # fields and `커밋` is not one of them while the sidecar's field table
        # declares eleven and it is.
        #
        # The fix is the vector giving up the read, not the grammar gaining a
        # field. "Write it in the grammar and the router will fill it" is false
        # here — the declared file set IS in the grammar at 18.5%, and `브랜치`
        # is in the sidecar only at 41.7%. What decides compliance is write-time
        # enforcement and whether the router can see a consumer, and `커밋` has
        # neither. Adding it to both is the same move as adding it to neither,
        # plus a value in the ledger nobody reads.
        #
        # THE SIDECAR'S FIELD TABLE KEEPS `커밋`. That table describes the ledger
        # schema, the router really does write the value, and a person reads it
        # in the morning. What is withdrawn is this vector's read of it.
        printf 'segment=%s|%s\n' "$sid" "$(gate_segment_field "$sid" '상태')"
      done
  # `cycle` rows are progress and were missing. A review completing, a
  # remediation landing, a re-review coming back clean — each writes one, and
  # none of them moved this vector, so a run could record a review, push a
  # branch and merge a pull request while the boundary counted it as motionless.
  # They are safe to include for the same reason segment rows are: the gate does
  # not write one on every act, only when a cycle is actually recorded.
  gate_rows 'cycle' \
    | gate_rows_field_values '세그먼트' | LC_ALL=C sort -u \
    | while IFS= read -r cseg; do
        [ -n "$cseg" ] || continue
        printf 'cycle=%s|%s\n' "$cseg" \
          "$(gate_rows 'cycle' | gate_rows_field_eq '세그먼트' "$cseg" | gate_count)"
      done
  # A DISPATCH IS PROGRESS. The router's own above-read acts used to be counted
  # here as `acts=`, and under the judgment definition `gate_boundaries` applies
  # that count is the number of judgments itself — so the counter sat inside
  # its own hash input: the digest judgment k compared against had already been
  # moved by judgment k-1's row, and `n` could never climb past 0. That is the
  # counter-inside-its-own-hash defect this file names in the preamble above,
  # one layer up. The above-read exec count now lives ONLY in the act budget
  # (B3), where it is the thing being spent rather than the thing being
  # measured against.
  #
  # What replaced it is the one act that can move the run: a stage dispatch.
  # `교대 기동` is not counted (a shift is a structural event, not progress) and
  # a pid file is not consulted (it is not a fact of the ledger).
  #
  # A DISPATCH COUNTS WHEN IT HAS AN OBSERVED OUTCOME, NOT WHEN IT WAS
  # AUTHORISED. The `kind=skill | 결정=act` row is appended BEFORE the launch —
  # that ordering is what makes a crash mid-act still leave a record — so a
  # component that read the authorisation row counted a dispatch that never
  # produced a process: a launch-path fault leaves `종단 부류=크래시 rc=1`, no pid
  # file and no process, and the row that reset the stagnation counter was the
  # same row that will be written again on the re-dispatch. That is a loop with
  # nothing in it, and the ledger's own failure row (`결정=결과`) does not undo
  # the authorisation row it follows. This component therefore reads the
  # `stage-result` rows — the terminal record the gate writes after the stage
  # was waited on — and counts only a class that says the stage ran and left a
  # trace: `정상 완료`, `의도된 park` (a halt record) or `산출물 없는 정지` (a
  # permission-denial trace). `크래시` and `공허한 성공` contribute nothing, for
  # the reason `stage-normal=` below gives: those classes exist to name a
  # dispatch that produced nothing, and counting them voids the name. Positive
  # selection, so a class added later contributes nothing until it is listed.
  #
  # THE ACTOR IS STILL THE ROUTER'S, read through the segment. A stage-result
  # row carries no seat, so the seat comes from the dispatch authorisation row of
  # the SAME segment: the segment counts only if some `kind=skill | 결정=act` row
  # for it carries `행위자` with a value other than `스테이지` — delimiter-anchored
  # so a `근거=` prose field that mentions `kind=skill` cannot match. Nothing
  # stops a stage from calling `act --kind skill`, and `교대=` is 0 for the lead
  # and for a stage alike, so without that field a stage could dispatch a
  # trivial nested stage and reset the counter that constrains its router. A
  # segment whose dispatch rows predate the field, and one nobody dispatched
  # through the gate at all, contribute nothing — the safe direction.
  #
  # NOT THE SAME COUNT AS `gate_pin_attempt`, ON PURPOSE. That function counts
  # the authorisation rows of a segment to number the NEXT attempt, and it has
  # to: the number is needed before the outcome exists, and a failed attempt
  # consumed its number as surely as a successful one. Progress asks the
  # opposite question — did anything come of it — so the two readers of the
  # `kind=skill` rows want opposite semantics and must not share a helper.
  #
  # A KNOWN SIDE EFFECT, accepted: with `acts=` gone the vector half of
  # `--snapshot-digest` no longer goes stale on another actor's above-read exec;
  # what remains is the tip half's ancestry window. That is the direction the
  # `gate_snapshot_digest` comment already argued for.
  #
  # The same one-pass awk shape as `stage-normal=` below, for the same reasons:
  # the class is located by its delimiter and compared whole (the driver writes
  # a prose `관측=` field on these rows), and `LC_ALL=C` keeps the byte offsets
  # host-independent. The segment set is handed in as one space-padded string
  # so membership is a single `index`, with no per-row subshell.
  local disp_segs
  disp_segs=$( { gate_rows '자율 승인' | grep -F '| kind=skill |' || true; } \
       | { grep -F '| 결정=act |' || true; } \
       | { grep -F '| 행위자=' || true; } \
       | { grep -vF '| 행위자=스테이지 |' || true; } \
       | sed -n 's/.*| 세그먼트=\([^|]*\) |.*/\1/p' | sed 's/[[:space:]]*$//' \
       | LC_ALL=C sort -u | tr '\n' ' ')
  printf 'dispatches=%s\n' \
    "$( { gate_rows 'stage-result' || true; } | LC_ALL=C awk -v segs=" $disp_segs" '
        function field(line, key, klen,    rest, p, q, v) {
          rest = line; v = ""
          while ((p = index(rest, key)) > 0) {
            rest = substr(rest, p + klen)
            q = index(rest, sep)
            v = (q > 0) ? substr(rest, 1, q - 1) : rest
          }
          return v
        }
        BEGIN { skey = " | 세그먼트="; slen = length(skey)
                ckey = " | 종단 부류="; clen = length(ckey); sep = " | "; n = 0 }
        {
          seg = field($0, skey, slen); cls = field($0, ckey, clen)
          if (seg == "" || index(segs, " " seg " ") == 0) next
          if (cls == "정상 완료" || cls == "의도된 park" || cls == "산출물 없는 정지") n++
        }
        END { printf "%d", n }
      ')"
  # A STAGE FINISHING NORMALLY IS PROGRESS, and until now nothing here saw it.
  # Segment rows move only when the STATE changes, so a segment that runs several
  # stages under `실행중` contributes a constant — and the two processes of one
  # implement stage are BOTH `실행중`, so not even that transition is expressible
  # as a segment row. Measured: a stage terminated normally, the ledger grew by a
  # `stage-result` row and a `cost` row, the chain stayed intact, and both the
  # progress digest and the stagnation window key came back byte-identical.
  #
  # A ROW COUNT AND NOT A SET. `gate_record_stage_outcome` writes `세그먼트=$seg`
  # and `스테이지=$seg` from one variable, so a set keyed on that pair collapses
  # to the segment alone — twenty-one normal terminations became three elements
  # on a real ledger. And the element count was the wrong measure regardless:
  # what the act budget watches is the GAP between movements, and replaying a
  # real run's 1033 rows put the worst gap at 59 for the count against 128 for
  # the best set and 195 for the vector without this line.
  #
  # Selected POSITIVELY — the field must be present and its value must be exactly
  # `정상 완료`. An exclusion-based selector (`everything but 크래시`) would count
  # `공허한 성공`, and that class exists precisely to name a stage that produced
  # nothing, so counting it as progress voids the reason it was named.
  #
  # Parsed rather than substring-matched, in ONE awk pass. The driver writes a
  # prose `관측=` field on these rows, so a match on the class value alone can be
  # satisfied by a sentence; this locates the field by its delimiter and compares
  # the WHOLE value. The last occurrence wins, the way every other field read in
  # this file does. And it is awk rather than a shell loop because the vector is
  # walked five times per act — a per-row subshell measured 1.92 seconds against
  # 0.007 for this on the same ledger.
  #
  # `LC_ALL=C` makes `index`, `substr` and `length` byte operations on both the
  # BWK awk this ships on and the gawk a Linux runner has, so the two hosts agree
  # on where a field starts. Without it the same row could be cut at a different
  # offset on each side and the vector would be host-dependent.
  printf 'stage-normal=%s\n' \
    "$( { gate_rows 'stage-result' || true; } | LC_ALL=C awk '
        BEGIN { key = " | 종단 부류="; klen = length(key); sep = " | "; n = 0 }
        {
          rest = $0; value = ""; seen = 0
          while ((p = index(rest, key)) > 0) {
            rest = substr(rest, p + klen)
            q = index(rest, sep)
            value = (q > 0) ? substr(rest, 1, q - 1) : rest
            seen = 1
          }
          if (seen && value == "정상 완료") n++
        }
        END { printf "%d", n }
      ')"
  # Settling a clause and clearing a run-scope block are progress by definition
  # — they are the only two moves whose whole purpose is to bring the run nearer
  # to being able to end. A run that spends a judgment doing one of them and is
  # then told it has not moved is being told something false.
  #
  # The series is `종료 절`, not `clause`. `gate_rows` matches on the ROW HEAD,
  # and the only writer of a settlement row spells it `종료 절`; `clause` is the
  # `--kind` token on the authorisation row, which is a field value and never a
  # row head. Written the wrong way this counter is a constant zero — measured
  # on a real run whose ledger held four settlements and zero `clause` rows —
  # so the one move that takes a run closest to being able to end contributed
  # nothing to the vector that decides whether it is moving.
  printf 'clauses=%s\n' "$( { gate_rows '종료 절' || true; } | gate_count)"
  printf 'unblocks=%s\n' \
    "$( { gate_rows 'blocked' | grep -F '원인=해소' || true; } | gate_count)"
  # THERE IS NO OBLIGATION COMPONENT, and there used to be the open set here. The
  # open set moved on a new problem row, on a closing act, and on a parked segment
  # walked to `실행중` and back — so once obligations could be closed, opening one
  # and closing it again reset this stagnation count for the price of two `읽기`
  # rows, while another obligation stayed blocked. A monotone replacement (the
  # disposition latch) still moves on that pair, and this vector has no window
  # to tell a disposal the run was waiting on from one it staged. Obligation
  # progress is B2's to judge, against its window; B3's key already drops the
  # component for the same reason.
}

gate_progress_digest() {
  gate_progress_vector | shasum -a 256 | cut -d' ' -f1
}

gate_ledger_row_count() {
  # Rows and not lines — the ledger carries prose between them. Used as a
  # POSITION: `gate_b1_stagnation` records this at the moment the progress
  # digest moves so the read credit can count forward from there instead of
  # re-enumerating which row kinds move the vector.
  local n
  n=$( { grep -c '^- `' "$LEDGER" 2>/dev/null || true; } | tr -d ' ')
  printf '%s' "${n:-0}"
}

gate_snapshot_digest() {
  # TWO DIGESTS, BECAUSE ONE VALUE CANNOT HAVE BOTH PROPERTIES.
  #
  # The stagnation boundary needs a value that moves only on PROGRESS — that is
  # `gate_progress_digest`, and every ledger append must be invisible to it or
  # the gate's own writes would reset the counter that watches for the gate not
  # writing.
  #
  # `--snapshot-digest` needs the opposite. It exists to catch a router acting
  # on state that has moved, explicitly including a compacted router carrying a
  # remembered value instead of re-reading. With the progress vector as its
  # source it could not do that: the vector is manifest-derived plus segment
  # rows plus obligations, so it is constant across long stretches of a run —
  # measured, two runs against different manifests, one with a 3-row ledger and
  # one with 227, produced the byte-identical value. Exit 4 could not fire, and
  # the check passed while the premise it protected was false.
  #
  # SO THIS ONE CARRIES BOTH, AND CARRIES THEM SEPARABLY. The two halves are
  # joined by `-` rather than hashed together, and that is the whole repair.
  #
  # Folded into one hash, the ledger's tip made EVERY append invalidate the value
  # no matter who wrote it — and `gate_verb_act` appends its authorisation row
  # before dispatching, so one actor's successful act invalidated every other
  # actor's digest the moment it landed. Measured in a single review session:
  # twelve exit 4s, as many as four in a row against one command, every one of
  # them cleared by re-running the identical argv with nothing else changed. A
  # check that a bare retry satisfies is not testing the premise it names; it is
  # a toll on concurrency. There was no ceiling on the re-reads and no backoff.
  #
  # Kept apart, each half is compared the way it should be — the vector for exact
  # equality, the tip for ANCESTRY — and the comparison lives at the call site
  # because only there is refusing an option. See `gate_verb_act`.
  #
  # ONE PASS OVER THE VECTOR. It is the expensive half: this file already
  # measured the row scan at 1.92s per-row-subshell against 0.007s in `awk`, and
  # calling `gate_progress_digest` for the first component would walk it a second
  # time for a value this function already holds.
  local vec
  vec=$(gate_progress_vector)
  printf '%s-%s' \
    "$(printf '%s\n' "$vec" | shasum -a 256 | cut -d' ' -f1)" \
    "$(gate_chain_tip)"
}

gate_snapshot_digest_legacy() {
  # THE PRE-SPLIT FORM, KEPT ONLY TO BE COMPARED AGAINST. A caller carrying a
  # one-part digest got it from a gate that hashed the progress vector together
  # with the ledger's length and tip, and honouring that value's original meaning
  # — exact equality — requires being able to compute it. The callers this exists
  # for are runs that were already in flight when the format split, and other
  # sessions' older copies of this file.
  #
  # NOTHING PRODUCES THIS FORMAT ANY MORE, so this is a reader and not a second
  # writer: the two forms cannot drift apart into two live conventions.
  local n
  n=$( { grep -c '^- `' "$LEDGER" 2>/dev/null || true; } | tr -d ' ')
  { gate_progress_vector
    printf 'ledger=%s|%s\n' "${n:-0}" "$(gate_chain_tip)"
  } | shasum -a 256 | cut -d' ' -f1
}

gate_segment_field() {
  # Last row for this segment id wins — the append-only advance of contract 3.4.
  local sid="$1" key="$2"
  # The `grep` is guarded for the same reason as `cc_unresolved_blocked`: asking
  # for a segment id that has no rows yet is ordinary — the router does it on the
  # first act of every run — and an unguarded middle `grep` turns that into a
  # `pipefail` non-zero which `set -e` reads as a fatal, message-less failure.
  #
  # THE ROW IS CHOSEN BY ITS `id` FIELD, NOT BY A SUBSTRING. `grep -F "id=$sid "`
  # also took another segment's row whose free text carried `id=<sid> `, and that
  # row then answered this segment's worktree, state and policy without one row
  # of this segment being written.
  gate_rows 'segment' | gate_rows_field_eq 'id' "$sid" | tail -1 \
    | tr '|' '\n' | sed -n "s/^ *$key=//p" | sed 's/[[:space:]]*$//' | tail -1
}

gate_segment_anchor_worktree() {
  # gate_segment_anchor_worktree <segment> <alias> — the `워크트리` of the
  # segment's FIRST NON-TERMINAL row THAT DOES NOT NAME THE TARGET'S MAIN
  # CHECKOUT; empty when the segment has no such row.
  #
  # A terminal row is compared against this, and a merged row reads its tip
  # here, so it has to be a value a later row cannot move. The last row was
  # not: a `리뷰중` row naming an old checkout re-pointed it, and the merged row
  # naming the same checkout then passed the comparison and read the old base's
  # tip. The first non-terminal row cannot be moved by a later one.
  #
  # THE FIRST NON-TERMINAL ROW IS NOT ALWAYS THE SEGMENT'S OWN TREE. The router
  # writes the segment's `계획됨` row at planning time, before the segment's
  # worktree exists, and names the target's main checkout there — the boundary
  # check on a non-terminal row admits that checkout, since it lives in the
  # declared common git directory. Anchored on that row, the merged row read
  # the main checkout's HEAD, which sits on the fork point or moves ahead with
  # the base and has nothing to do with what the segment merged: a merge no
  # review had covered read `충족`, and a fully reviewed one read
  # `위반(미포함)` that no further review could clear. So the main checkout is
  # never the record. It is matched as spelled against the target's declared
  # `메인 워크트리`, and as `pwd -P` resolves it against the anchor repository
  # root when both exist. A segment that names nothing else has no record.
  #
  # SKIPPING THE MAIN CHECKOUT'S ROOT WAS NOT ENOUGH, because it named what the
  # record is not instead of what it is. A row naming a subdirectory of the
  # main checkout (`<main>/docs`) passed the skip and became the record, and a
  # merge recorded from that directory read the main checkout's HEAD as `충족`.
  # So a row whose directory still exists is identified positively: it has to
  # be the top level of its own checkout (`--show-toplevel`, compared through
  # `pwd -P`), and that top level must not be the main checkout. A directory
  # that is gone, or that is not inside a repository, gets the spelling and
  # realpath skips above only — a segment's worktree is routinely removed
  # before its merge is recorded, and the record has to survive that.
  #
  # ONLY ROWS WRITTEN BEFORE THE SEGMENT'S FIRST `머지됨` ROW ARE CANDIDATES. A
  # segment whose rows named only the main checkout merged with `판정 불가`,
  # a `리뷰중` row naming another linked worktree written after it became the
  # record, and a second merged row naming that worktree then read `충족` and
  # cleared condition 11. After a merge is recorded there is no record left to
  # establish. `완료` and `park` do not end the candidates, because a segment
  # resumes after them.
  #
  # "THE TOP LEVEL OF A CHECKOUT OTHER THAN THE MAIN ONE" IS STILL A SHAPE, and
  # every other linked worktree of the same repository has it. A first row
  # naming a linked worktree sitting on another branch became the record; a
  # merge carrying commits no review had covered then read `충족` from that
  # tree's tip, and the honest terminal row naming the segment's own tree was
  # refused. So THE RECORD IS PINNED TO ONE BRANCH:
  #
  #   - the segment's branch is the branch of the FIRST candidate whose branch
  #     is known. Only the first counts: a union of every row's `브랜치` let
  #     one later row naming another branch move the record back to an earlier
  #     linked worktree on that branch;
  #   - a candidate's branch is what its directory has checked out when it
  #     still exists and is the top level of a checkout — unknown when that
  #     HEAD is detached — and the row's own `브랜치` only when the directory
  #     is gone or is not inside a repository;
  #   - the record is the first candidate on the pinned branch;
  #   - with no pinned branch there is no record, and THERE IS NONE EITHER when
  #     a candidate whose branch is known is on another branch. The segment's
  #     rows then name checkouts of two branches and the gate cannot tell which
  #     one the merge came from. A re-fork (`-A` abandoned for `-A2`) lands
  #     here too.
  #
  # No record is the closed side: the terminal row passes the worktree
  # comparison, the merged row cannot read a tip and records `머지 대조=판정
  # 불가`, and termination condition 11 holds the run.
  #
  # A tree another segment named earlier is NOT excluded. A follow-up or fix
  # segment that inherits a tree and its branch is a legitimate shape — the
  # same shape the sibling-merge exemption of a `완료` row admits — and the spelling of a path cannot
  # tell it from a router naming a sibling's tree. Excluding by path took the
  # record from every segment that was not the first to name a shared tree, and
  # their honestly reviewed merges were held as `판정 불가`.
  #
  # THE GAP LEFT OPEN: a router that names a sibling's tree on every row of a
  # segment and never names the segment's own tree is, to this function, a
  # segment that inherited that tree and its branch.
  #
  # The target's declared `실행 워크트리` is not excluded by name: it records
  # the linked worktree the target's branch is checked out in, which for a
  # segment inherited from an earlier run is the segment's own tree. When it
  # has another branch checked out, the branch pin rejects it.
  local seg="$1" al="${2:-}" main="" main_p="" rows row wt wt_p top_p br rbr
  local pin="" first="" mixed="" cand="" w b
  if [ -n "$al" ]; then
    main=$(target_field "$al" '메인 워크트리' 2>/dev/null) || main=""
    main_p=$(alias_root "$al" 2>/dev/null) || main_p=""
    if [ -n "$main_p" ]; then
      main_p=$(cd "$main_p" 2>/dev/null && pwd -P) || main_p=""
    fi
  fi
  # This segment's non-terminal rows in ledger order, stopping at its first
  # `머지됨` row. Fields are read as `gate_row_field` and `gate_rows_field_eq`
  # read them — trimmed, the last one with a key wins.
  rows=$(gate_rows 'segment' | gate_rows_field_eq 'id' "$seg" \
          | awk -v ts=" $TERMINAL_SEGMENT_STATES " '
              { n = split($0, f, "|"); st = ""
                for (i = 2; i <= n; i++) {
                  s = f[i]; sub(/^ +/, "", s); sub(/[ \t]+$/, "", s)
                  if (index(s, "상태=") == 1) st = substr(s, length("상태=") + 1)
                }
                if (st == "머지됨") exit
                if (st != "" && index(ts, " " st " ") == 0) print $0 }')
  [ -n "$rows" ] || return 0
  # First pass: the candidates as `<branch or empty><TAB><worktree>`, and the
  # pinned branch.
  while IFS= read -r row; do
    [ -n "$row" ] || continue
    wt=$(gate_row_field "$row" '워크트리')
    [ -n "$wt" ] || continue
    if [ -n "$main" ] && [ "$wt" = "$main" ]; then continue; fi
    wt_p=$(cd "$wt" 2>/dev/null && pwd -P) || wt_p=""
    if [ -n "$main_p" ] && [ -n "$wt_p" ] && [ "$wt_p" = "$main_p" ]; then continue; fi
    rbr=$(gate_row_field "$row" '브랜치' | sed 's#^refs/heads/##')
    [ "$rbr" != '-' ] || rbr=""
    br="$rbr"
    if [ -n "$wt_p" ]; then
      top_p=$(cd "$wt_p" 2>/dev/null && git rev-parse --show-toplevel 2>/dev/null) || top_p=""
      if [ -n "$top_p" ]; then
        top_p=$(cd "$top_p" 2>/dev/null && pwd -P) || top_p=""
        [ "$top_p" = "$wt_p" ] || continue
        if [ -n "$main_p" ] && [ "$top_p" = "$main_p" ]; then continue; fi
        b=$(cd "$wt_p" 2>/dev/null && git symbolic-ref --quiet --short HEAD 2>/dev/null) || b=""
        # The checkout answers, and only the checkout: a detached HEAD is a
        # candidate whose branch is unknown, and the row's `브랜치` does not
        # stand in for it. A row naming a detached checkout of a reviewed
        # commit with the segment's branch written beside it became the
        # record, and an unreviewed merge read `충족` from that tree's tip.
        # A `브랜치` naming another branch than the checkout is on is not read
        # either, so it cannot move the record.
        br="$b"
      fi
    fi
    if [ -z "$first" ] && [ -n "$br" ]; then pin="$br"; first=1; fi
    cand="${cand}${br}	${wt}
"
  done <<GATE_ANCHOR_ROWS
$rows
GATE_ANCHOR_ROWS
  [ -n "$pin" ] || return 0
  # Second pass: refuse a record when the candidates name two branches, then
  # take the first candidate on the pinned branch.
  while IFS= read -r row; do
    [ -n "$row" ] || continue
    b=${row%%"	"*}
    if [ -n "$b" ] && [ "$b" != "$pin" ]; then mixed=1; break; fi
  done <<GATE_ANCHOR_CANDS
$cand
GATE_ANCHOR_CANDS
  [ -z "$mixed" ] || return 0
  while IFS= read -r row; do
    [ -n "$row" ] || continue
    b=${row%%"	"*}
    w=${row#*"	"}
    if [ "$b" = "$pin" ]; then printf '%s' "$w"; return 0; fi
  done <<GATE_ANCHOR_CANDS
$cand
GATE_ANCHOR_CANDS
  return 0
}

gate_segment_row_branch() {
  # gate_segment_row_branch <alias> <worktree> — the branch checked out at
  # <worktree> when it is the top level of a checkout other than the target's
  # main one; empty otherwise (gone, a subdirectory, the main checkout, a
  # detached HEAD).
  #
  # The record above is pinned to the first row carrying `브랜치`, and the
  # router's row template and the driver's planning row did not carry one, so
  # for most segments there was nothing to pin to and the record fell to
  # whichever linked worktree came first. The gate fills the field on a
  # non-terminal row the caller left it off, from the checkout the row names.
  local al="$1" wt="$2" main="" main_p="" wt_p top_p
  main=$(target_field "$al" '메인 워크트리' 2>/dev/null) || main=""
  [ -z "$main" ] || [ "$wt" != "$main" ] || return 0
  wt_p=$(cd "$wt" 2>/dev/null && pwd -P) || return 0
  main_p=$(alias_root "$al" 2>/dev/null) || main_p=""
  if [ -n "$main_p" ]; then
    main_p=$(cd "$main_p" 2>/dev/null && pwd -P) || main_p=""
  fi
  top_p=$(cd "$wt_p" 2>/dev/null && git rev-parse --show-toplevel 2>/dev/null) || return 0
  top_p=$(cd "$top_p" 2>/dev/null && pwd -P) || return 0
  [ "$top_p" = "$wt_p" ] || return 0
  [ -z "$main_p" ] || [ "$top_p" != "$main_p" ] || return 0
  (cd "$wt_p" 2>/dev/null && git symbolic-ref --quiet --short HEAD 2>/dev/null) || true
}

# ---------------------------------------------------------------------------
# The run-scope design step — a step of the graph that is not a segment.
#
# A design step has no worktree, no predecessor and no declared file set, so a
# `segment` row for it would be counted by termination condition 1 as a segment
# and carried into the morning report as one. The router dispatches it with
# `--segment -` instead, and the driver's design arm already writes its row as
# `세그먼트=-`; the two paths converge on ONE row shape, `세그먼트=- | 스테이지=<step
# id> | 종류=design`, so a reader never has to reconcile two.
#
# THE STEP ID IS DERIVED, NOT PASSED. The dispatch argv carries `-` where a
# segment id would be, and the run directory still needs a key for the pin, the
# stream, the pid record and the halt record. The frozen plan names exactly one
# step whose skill is `design`; that id is the key. A flag carrying the id would
# let a router type a key the plan never named, and zero or several design steps
# is a plan this exemption does not know how to read, so both are refused.
#
# THE AUDIT IS THE SECOND RUN-SCOPE STEP, ON THE SAME TERMS. It reads the frozen
# document rather than building a segment, so it has no worktree, no `선행` and
# no declared files either, and a `segment` row for it would hold condition 1
# open until somebody wrote `완료` by hand. Its key is the plan's single
# `design-audit` step id, derived the same way and refused the same way when the
# plan names zero or several.
#
# AN AUDIT DOES NOT NEED A DESIGN STEP IN FRONT OF IT. A run anchored on a
# document frozen before the run began — a document anchor, or a `lead-solo`
# design the kickoff wrote itself — has no design step and its plan opens on the
# audit. Requiring `design_required=true` for the audit as well left that run
# with no way to dispatch its first step: the gate refused it with exit 3 and
# the shift ended on a stop handoff. So the audit is a run-scope step either
# when the plan requires a design, or when the plan names no design step at all.
# A plan that does not require a design yet still carries a design step is one
# this exemption does not know how to read, and it stays refused.
# ---------------------------------------------------------------------------
gate_plan_skill_step_count() {
  # gate_plan_skill_step_count <skill> — how many object steps of the frozen
  # plan carry that skill, whether or not they have an id.
  local n
  n=$(manifest_plan_json 2>/dev/null \
        | jq -r --arg s "$1" '[.steps[]? | select(type == "object" and .skill == $s)] | length' 2>/dev/null \
        || true)
  printf '%s' "${n:-0}"
}

gate_run_scope_step() {
  # gate_run_scope_step <종류> — `design`, `audit`, `split` or `visual`. Prints
  # the plan's single step id of that kind and returns 0, or returns 1. A design
  # step exists only in a plan that requires a design. An audit step is
  # run-scope in that plan, and in a plan with no design step at all, whose
  # audit reads a document that was frozen before the run. A split step and a
  # visual step are run-scope wherever the plan names exactly one.
  local skill req ids
  case "${1:-}" in
    design) skill='design' ;;
    audit)  skill='design-audit' ;;
    split)  skill='split' ;;
    visual) skill='visual' ;;
    *)      return 1 ;;
  esac
  req=$(manifest_plan_json 2>/dev/null | jq -r '.design_required' 2>/dev/null || true)
  if [ "$skill" != "split" ] && [ "$skill" != "visual" ] && [ "$req" != "true" ]; then
    [ "$skill" = "design-audit" ] || return 1
    [ "$(gate_plan_skill_step_count design)" = "0" ] || return 1
  fi
  ids=$( { manifest_plan_json 2>/dev/null \
           | jq -r --arg s "$skill" '.steps[]? | select(type == "object" and .skill == $s) | .id // empty' 2>/dev/null \
           || true; } | grep -v '^$' || true)
  [ -n "$ids" ] || return 1
  [ "$(printf '%s\n' "$ids" | grep -c .)" = "1" ] || return 1
  printf '%s' "$ids"
}

# ---------------------------------------------------------------------------
# The run-scope step table — the design step's exemption, generalized.
#
#   stage kind token | plan step skill | row `종류`
#   design           | design          | design
#   audit            | design-audit    | audit
#   split            | split           | split
#   visual           | visual          | visual
#
# A base run is `design → design-audit → split` and none of the three is a
# segment, so all three are dispatched with `--segment -` and keyed on their
# plan step id. The visual step is the fourth row: it generates the night's
# screens from the audited document, before any segment is implemented, and
# builds no segment of its own. Each kind binds to exactly ONE plan step carrying its skill —
# zero or several is a plan this table does not know how to read, and the
# dispatch is refused rather than a key being picked. `gate_run_scope_step`
# above resolves all four, with the design and the audit also held to the
# plan's `design_required`.
# ---------------------------------------------------------------------------
gate_run_scope_skill_of() {
  # gate_run_scope_skill_of <kind token> — the plan skill the table binds it to.
  case "$1" in
    design) printf 'design' ;;
    audit)  printf 'design-audit' ;;
    split)  printf 'split' ;;
    visual) printf 'visual' ;;
    *) return 1 ;;
  esac
}

gate_run_scope_kind_of_key() {
  # gate_run_scope_kind_of_key <stage-key> — prints the row kind whose run-scope
  # step id is this key and returns 0, or returns 1. A key that also has a
  # `segment` row is a segment, whatever the plan calls it.
  local key="$1" k s
  [ -z "$(gate_segment_field "$key" '상태')" ] || return 1
  for k in design audit split visual; do
    if s=$(gate_run_scope_step "$k" 2>/dev/null) && [ "$s" = "$key" ]; then
      printf '%s' "$k"
      return 0
    fi
  done
  return 1
}

gate_run_scope_rows() {
  # gate_run_scope_rows <step id> <row kind> — every `stage-result` row of a
  # run-scope step in ledger order, in either writer's shape: the router's
  # (`세그먼트=- | 스테이지=<id> | 종류=<k>`) or the driver's, which names its stage
  # `S2` (audit: `종류=audit`, or no `종류` on a row written before the driver
  # stamped it), `S2split` (`종류=split`) or `S2V` (`종류=visual`). Any other `종류`
  # on an `S2` row is not an audit. The driver's names are read only when the
  # plan's id has no row of its own.
  local id="$1" k="$2" rows
  rows=$( { gate_rows 'stage-result' || true; } \
          | { grep -F "세그먼트=- | 스테이지=$id | 종류=$k " || true; })
  if [ -z "$rows" ]; then
    case "$k" in
      audit)
        rows=$( { gate_rows 'stage-result' || true; } \
                | { grep -F '세그먼트=- | 스테이지=S2 |' || true; } \
                | awk 'index($0, "| 종류=audit ") || !index($0, "| 종류=")') ;;
      split)
        rows=$( { gate_rows 'stage-result' || true; } \
                | { grep -F '세그먼트=- | 스테이지=S2split |' || true; } \
                | { grep -F '| 종류=split ' || true; }) ;;
      visual)
        rows=$( { gate_rows 'stage-result' || true; } \
                | { grep -F '세그먼트=- | 스테이지=S2V |' || true; } \
                | { grep -F '| 종류=visual ' || true; }) ;;
    esac
  fi
  printf '%s' "$rows"
}

gate_run_scope_last_row() {
  # gate_run_scope_last_row <step id> <row kind> — the latest of those rows.
  gate_run_scope_rows "$1" "$2" | tail -1
}

gate_stage_row_segment() {
  # gate_stage_row_segment <stage-key> <stage-kind> — the `세그먼트` value every
  # ledger row about this stage carries: `-` for a run-scope step of the table
  # above, the key itself for everything else. Decided from facts the gate
  # re-reads (the kind, the absence of a `segment` row, the plan), so the
  # dispatch half, the supervisor and the settlement agree without handing the
  # answer across.
  local key="$1" skind="$2" rk
  # A re-convergence on the audit step's key is that step's stage too, and so
  # is one on the design step's key — the review a person opens on a design
  # stage's residual ladder.
  if rk=$(gate_run_scope_kind_of_key "$key") \
     && { [ "$rk" = "$skind" ] \
          || { { [ "$rk" = "audit" ] || [ "$rk" = "design" ]; } && [ "$skind" = "reconverge" ]; }; }; then
    printf '%s' '-'
  else
    printf '%s' "$key"
  fi
}

gate_stage_result_rows_of() {
  # gate_stage_result_rows_of <stage-key> — this stage's `stage-result` rows in
  # either shape: a segment's (`세그먼트=<key>`) or a run-scope step's
  # (`세그먼트=- | 스테이지=<key> | 종류=<k>`, `<k>` the table's row kind for that
  # key). The kind is part of the second pattern so a driver row of another
  # run-scope stage, which carries no `종류`, is never read as this one. The
  # audit step's key also carries the re-convergence an adopted requirement
  # sends there, and the design step's key the one a person's `골격 재검토`
  # opens on its residual ladder (`gate_design_reconverge_entry`).
  local rk rk2
  rk=$(gate_run_scope_kind_of_key "$1" 2>/dev/null) || rk=design
  rk2=$rk
  { [ "$rk" = "audit" ] || [ "$rk" = "design" ]; } && rk2=reconverge
  { gate_rows 'stage-result' || true; } \
    | { grep -F -e "세그먼트=$1 " -e "세그먼트=- | 스테이지=$1 | 종류=$rk " \
               -e "세그먼트=- | 스테이지=$1 | 종류=$rk2 " || true; }
}

gate_reconverge_verdict() {
  # gate_reconverge_verdict <stream> — `재설계 필요`, `불필요` or `없음`, read
  # from the text of the stream's last `result` object that ran a turn, and
  # nothing else.
  #
  # THE TERMINAL TEXT ONLY, AND WHOLE LINES ONLY. The transcript quotes the
  # skill's own grammar — `판정: 재설계 필요|불필요` sits on one line in its
  # template — so a substring match over the stream reads a normal
  # re-convergence as both verdicts, or as one it did not give. A verdict is a
  # line that IS `판정: 재설계 필요` or `판정: 불필요`, in a text that also
  # carries the closing literal; a text with neither line, with both, or
  # without the literal is `없음`, and `없음` cites nothing for a re-plan.
  #
  # ZERO-TURN ENVELOPES ARE SKIPPED, as `stage_refusal_exit` skips them: a
  # resumed session can end in an empty envelope after the one that carried
  # the verdict, and reading that one turned every such re-convergence into
  # `없음` whatever the stage wrote. The line's own spelling is loosened only
  # where it cannot change the words — leading and trailing whitespace, one
  # list marker (`- `, `* `, `1. `, `1) `), bold or backticks around the whole
  # line, a bold key (`**판정**:` or `**판정:**`), a full-width colon,
  # bold or backticks around the value and one closing period; a verdict in the middle
  # of a sentence is still no verdict. The router's re-plan items read only
  # the row this writes, so a spelling read as `없음` here leaves a stale plan
  # standing with nothing else to catch it.
  local out="${1:-}" txt need=0 unneeded=0 line w inner val dot
  [ -n "$out" ] && [ -s "$out" ] && command -v jq >/dev/null 2>&1 || { printf '없음'; return 0; }
  txt=$(jq -R -n -r '
    reduce (inputs | select(test("\\S")) | (try fromjson catch null)
            | select(type == "object" and .type == "result"
                     and ((.num_turns | if type == "number" then . else 0 end) > 0))) as $r
      (null; $r)
    | if . == null then empty else (.result // empty) end' "$out" 2>/dev/null || true)
  case "$txt" in *"$LIT_RECONVERGE_TERMINAL"*) ;; *) printf '없음'; return 0 ;; esac
  while IFS= read -r line; do
    line="${line%"${line##*[![:space:]]}"}"
    line="${line#"${line%%[![:space:]]*}"}"
    case "$line" in
      '- '*|'* '*) line="${line#??}" ;;
      [0-9]'. '*|[0-9]') '*) line="${line#???}" ;;
      [0-9][0-9]'. '*|[0-9][0-9]') '*) line="${line#????}" ;;
    esac
    for w in '**' '`'; do
      case "$line" in
        "$w"?*"$w")
          inner="${line#"$w"}"; inner="${inner%"$w"}"
          case "$inner" in *"$w"*) ;; *) line="$inner" ;; esac ;;
      esac
    done
    case "$line" in
      '**판정**:'*) line="판정:${line#'**판정**:'}" ;;
      '**판정:**'*) line="판정:${line#'**판정:**'}" ;;
      '**판정**：'*) line="판정:${line#'**판정**：'}" ;;
      '**판정：**'*) line="판정:${line#'**판정：**'}" ;;
      '판정：'*) line="판정:${line#'판정：'}" ;;
    esac
    case "$line" in '판정:'*) ;; *) continue ;; esac
    val="${line#'판정:'}"
    val="${val#"${val%%[![:space:]]*}"}"
    dot=0
    case "$val" in
      *.) val="${val%.}"; dot=1 ;;
      *。) val="${val%。}"; dot=1 ;;
    esac
    for w in '**' '`'; do
      case "$val" in "$w"?*"$w") val="${val#"$w"}"; val="${val%"$w"}" ;; esac
    done
    if [ "$dot" = 0 ]; then
      case "$val" in
        *.) val="${val%.}" ;;
        *。) val="${val%。}" ;;
      esac
    fi
    val="${val%"${val##*[![:space:]]}"}"
    case "$val" in
      '재설계 필요') need=$((need + 1)) ;;
      '불필요') unneeded=$((unneeded + 1)) ;;
    esac
  done <<EOF
$txt
EOF
  if [ "$need" -gt 0 ] && [ "$unneeded" = "0" ]; then printf '재설계 필요'
  elif [ "$unneeded" -gt 0 ] && [ "$need" = "0" ]; then printf '불필요'
  else printf '없음'
  fi
}

gate_replan_eval() {
  # gate_replan_eval <sibling> <스테이지>#<실행 버전> — the seven clauses of a
  # sibling re-plan, decided once for both readers: `act --kind replan` refuses
  # on the first false clause, and `replan_due[]` derives `state` from the same
  # answers. Returns 0 when every clause holds.
  #
  # Sets, for the caller:
  #   GATE_REPLAN_C1 … GATE_REPLAN_C7  `1` or `0`, one per clause
  #   GATE_REPLAN_CLAUSE / _WHY        the first false clause and why
  #   GATE_REPLAN_ROUND                the `회차` the row would carry
  #
  # 1 the sibling has a `segment` row and has not ended;
  # 2 no stage of the sibling is live;
  # 3 the sibling has an implement row with `plan_sha256` above the cited row;
  # 4 the cite key names exactly one row, a gate-written `종류=reconverge` row
  #   with `재수렴 판정=재설계 필요` whose `세그먼트` is not the sibling;
  # 5 no earlier `재계획` row pairs the sibling with this cite;
  # 6 the sibling's round is at most two in this run;
  # 7 no question of the person set (`사람-결정`, `시각-승인`) holds the
  #   sibling, directly or through `선행` — an open one, or a refusal not yet
  #   consumed (`gate_person_hold_ids`).
  local sib="$1" cite="$2" st at out n4 ok4 plan3 dup5 nrep held held_cls
  GATE_REPLAN_C1=0 GATE_REPLAN_C2=0 GATE_REPLAN_C3=0 GATE_REPLAN_C4=0
  GATE_REPLAN_C5=0 GATE_REPLAN_C6=0 GATE_REPLAN_C7=0
  GATE_REPLAN_CLAUSE="" GATE_REPLAN_WHY="" GATE_REPLAN_ROUND=1
  st="${cite%#*}"; at="${cite##*#}"
  case "$cite" in *'#'*) ;; *) st=""; at="" ;; esac
  case "$at" in ''|*[!0-9]*) st=""; at="" ;; esac
  if [ -n "$(gate_segment_field "$sib" '상태')" ] && ! gate_segment_terminal "$sib"; then GATE_REPLAN_C1=1; fi
  gate_stage_live_attempt "$sib" || GATE_REPLAN_C2=1
  # Clauses 3 to 6 in one pass over the ledger, so the order clause 3 asks
  # about is the ledger's own. Whole-field matches on the row padded with a
  # trailing separator, the way `gate_has_row` reads a field.
  out=$(awk -v sib="$sib" -v st="$st" -v at="$at" '
    BEGIN { n4 = 0; ok4 = 0; cl = 0; minplan = 0; dup = 0; nrep = 0 }
    { r = $0 " | " }
    index($0, "- `stage-result`") == 1 {
      if (st != "" && index(r, " | 스테이지=" st " | ") && index(r, " | 실행 버전=" at " | ")) {
        n4++; cl = NR
        ok4 = (index(r, " | 기록자=게이트 | ") && index(r, " | 종류=reconverge | ") \
               && index(r, " | 재수렴 판정=재설계 필요 | ") && !index(r, " | 세그먼트=" sib " | "))
      }
      # An implement row is `종류=implement`, or the driver`s `스테이지=S4` row,
      # which carries no `종류` — the reading `implement_process_b` makes.
      if (index(r, " | 세그먼트=" sib " | ") && index(r, " | plan_sha256=") \
          && (index(r, " | 종류=implement | ") || index(r, " | 스테이지=S4 | ")) && minplan == 0) minplan = NR
    }
    index($0, "- `재계획`") == 1 && index(r, " | 세그먼트=" sib " | ") {
      nrep++
      if (st != "" && index(r, " | 재수렴=" st "#" at " | ")) dup = 1
    }
    END { printf "%d %d %d %d %d", n4, ok4, (minplan > 0 && cl > 0 && minplan < cl), dup, nrep }
  ' "$LEDGER" 2>/dev/null) || out="0 0 0 0 0"
  read -r n4 ok4 plan3 dup5 nrep <<EOF
$out
EOF
  [ "${plan3:-0}" = "1" ] && GATE_REPLAN_C3=1
  [ "${n4:-0}" = "1" ] && [ "${ok4:-0}" = "1" ] && GATE_REPLAN_C4=1
  [ "${dup5:-0}" = "1" ] || GATE_REPLAN_C5=1
  GATE_REPLAN_ROUND=$(( ${nrep:-0} + 1 ))
  [ "$GATE_REPLAN_ROUND" -le 2 ] && GATE_REPLAN_C6=1
  held=$(for id in $(gate_person_hold_ids); do gate_approval_field "$id" '막는 세그먼트'; printf ' '; done)
  # shellcheck disable=SC2086
  if [ -z "${held// /}" ] || ! gate_slice_reaches_any "$sib" $held; then GATE_REPLAN_C7=1; fi
  # The class the clause-7 reason names is the one actually holding: the hold
  # set is wider than `사람-결정`, and a reason that names a class not open
  # sends the reader to the wrong question.
  held_cls=""
  if [ "$GATE_REPLAN_C7" != 1 ]; then
    held_cls=$(for id in $(gate_person_hold_ids); do
      # shellcheck disable=SC2046
      if gate_slice_reaches_any "$sib" $(gate_approval_field "$id" '막는 세그먼트'); then
        gate_approval_field "$id" '판단 부류'; printf ' '
      fi
    done)
    held_cls=$(printf '%s\n' $held_cls | awk '!seen[$0]++' | paste -sd '/' -)
  fi
  export GATE_REPLAN_C1 GATE_REPLAN_C2 GATE_REPLAN_C3 GATE_REPLAN_C4 GATE_REPLAN_C5 \
    GATE_REPLAN_C6 GATE_REPLAN_C7 GATE_REPLAN_ROUND
  local c cv
  for c in 1 2 3 4 5 6 7; do
    cv="GATE_REPLAN_C$c"
    [ "${!cv}" = 1 ] && continue
    GATE_REPLAN_CLAUSE=$c
    case "$c" in
      1) GATE_REPLAN_WHY="$sib has no segment row, or has ended" ;;
      2) GATE_REPLAN_WHY="a stage of $sib is still live — read again after it ends" ;;
      3) GATE_REPLAN_WHY="$sib has no implement row with plan_sha256 before the cited row" ;;
      4) GATE_REPLAN_WHY="the cite does not name exactly one gate-written reconverge row with 재수렴 판정=재설계 필요 on another segment (rows found: ${n4:-0})" ;;
      5) GATE_REPLAN_WHY="$sib was already re-planned for $cite" ;;
      6) GATE_REPLAN_WHY="$sib has been re-planned twice in this run — raise a 사람-결정 instead" ;;
      7) GATE_REPLAN_WHY="an open ${held_cls:-사람-결정} holds $sib" ;;
    esac
    export GATE_REPLAN_CLAUSE GATE_REPLAN_WHY
    return 1
  done
  return 0
}

gate_snapshot_cone_blocks_json() {
  # One element per line of `cc_cone_blocked`: `subject`, `state` (`held` or
  # `unresolved`, passed through), `cause`, `reason` and `observed` — `null`
  # where the row carries no `관측`. The fold, the hiding rule and the order are
  # that function's; this only changes the encoding.
  local LC_CTYPE=C; export LC_CTYPE
  # The tabs become a unit separator before the split: a tab is IFS
  # whitespace, so two of them around an empty field would collapse into one
  # and shift every field after it.
  local k s c r o first=1 obs us
  us=$(printf '\037')
  while IFS="$us" read -r k s c r o; do
    [ -n "$k" ] || continue
    [ "$first" = "1" ] || printf ',\n'
    first=0
    if [ -z "$o" ] || [ "$o" = "-" ]; then obs='null'; else obs="\"$(gate_json_escape "$o")\""; fi
    printf '    {"subject": "%s", "state": "%s", "cause": "%s", "reason": "%s", "observed": %s}' \
      "$(gate_json_escape "$s")" "$(gate_json_escape "$k")" \
      "$(gate_json_escape "$c")" "$(gate_json_escape "$r")" "$obs"
  done <<EOF
$( { cc_cone_blocked "$LEDGER" 2>/dev/null || true; } | tr '\t' '\037')
EOF
  [ "$first" = "1" ] || printf '\n'
}

gate_replan_person_decided() {
  # gate_replan_person_decided <sibling> <스테이지>#<실행 버전> — 0 when a
  # `사람-결정` question on the sibling, first issued after the cited
  # re-convergence row, has been answered `승인` and spent by a `자율 승인` row
  # that reads `결정=채택` or `결정=자유 입력 소비`.
  #
  # The class is the literal `사람-결정`, not the person set: this reads how
  # the re-plan cap's own question was answered, and `시각-승인` is never that
  # question.
  #
  # A PERSON WHO DECIDED THE CAPPED SIBLING HAS ANSWERED THE KEY. The `상한`
  # element asks the router for that question, and nothing the approved answer
  # leads to clears the element: a re-dispatch writes no `재계획` row (clause 5)
  # and clause 3 compares the sibling's first plan row. So once the answer was
  # spent the hold lifted and the element came back `상한` after every stage —
  # the router asked the person again, or met the cap and parked the segment
  # the person had just told it to run. A refusal needs no such reading: its
  # consumption follows the park, and a parked sibling fails clause 1.
  local sib="$1" cite="$2" st at
  st="${cite%#*}"; at="${cite##*#}"
  awk -v sib="$sib" -v st="$st" -v at="$at" -v cls="사람-결정" '
    function fld(r, key,   k, i, s, j) {
      k = " | " key "="; i = index(r, k); if (!i) return ""
      s = substr(r, i + length(k)); j = index(s, " | ")
      s = (j ? substr(s, 1, j - 1) : s); sub(/[ \t]+$/, "", s); return s
    }
    BEGIN { cl = 0; hit = 0 }
    { r = $0 " | " }
    index($0, "- `stage-result`") == 1 && index(r, " | 스테이지=" st " | ") \
      && index(r, " | 실행 버전=" at " | ") && index(r, " | 종류=reconverge | ") { cl = NR }
    index($0, "- `승인`") == 1 && index(r, " | 판단 부류=" cls " | ") \
      && index(r, " | 막는 세그먼트=" sib " | ") {
      id = fld(r, "승인 id"); if (id != "" && !(id in first)) first[id] = NR
    }
    index($0, "- `자율 승인`") == 1 \
      && (index(r, " | 결정=채택 | ") || index(r, " | 결정=자유 입력 소비 | ")) {
      id = fld(r, "해소 승인"); if (id != "" && id != "-") spent[id] = 1
    }
    END {
      if (cl == 0) exit 1
      for (id in first) if (first[id] > cl && (id in spent)) hit = 1
      exit (hit ? 0 : 1)
    }
  ' "$LEDGER" 2>/dev/null
}

gate_replan_due_json() {
  # One element per sibling a gate-written `재설계 필요` re-convergence leaves
  # with a void plan: clauses 1, 3 and 4 hold and clause 5 finds no earlier row.
  # `state` names the first of the remaining clauses that is false, in the
  # order the router acts on — `보류` (7), `살아 있음` (2), `상한` (6) — and
  # `가능` when none is. Same evaluation as the `replan` act, so an element
  # whose state is `가능` is an act the gate admits. A capped sibling a person
  # has decided since the re-convergence (`gate_replan_person_decided`) is left
  # out: the question its `상한` asked for has been answered and carried out.
  local LC_CTYPE=C; export LC_CTYPE
  local row rs st at cite sib state first=1
  while IFS= read -r row; do
    [ -n "$row" ] || continue
    rs=$(gate_row_field "$row" '세그먼트')
    st=$(gate_row_field "$row" '스테이지')
    at=$(gate_row_field "$row" '실행 버전')
    [ -n "$st" ] && [ -n "$at" ] || continue
    cite="$st#$at"
    for sib in $(gate_segment_ids); do
      [ -n "$sib" ] && [ "$sib" != "$rs" ] || continue
      # STDIN IS CUT. This loop reads its rows from the here-document, and the
      # clause 7 readers called inside the evaluation read standard input once
      # a `사람-결정` is open — so they ate the rows still to come, and every
      # re-convergence after the first went missing from the key.
      gate_replan_eval "$sib" "$cite" </dev/null || true
      [ "$GATE_REPLAN_C1$GATE_REPLAN_C3$GATE_REPLAN_C4$GATE_REPLAN_C5" = "1111" ] || continue
      if [ "$GATE_REPLAN_C7" = 1 ] && [ "$GATE_REPLAN_C6" != 1 ] \
         && gate_replan_person_decided "$sib" "$cite" </dev/null; then
        continue
      fi
      if [ "$GATE_REPLAN_C7" != 1 ]; then state='보류'
      elif [ "$GATE_REPLAN_C2" != 1 ]; then state='살아 있음'
      elif [ "$GATE_REPLAN_C6" != 1 ]; then state='상한'
      else state='가능'
      fi
      [ "$first" = "1" ] || printf ',\n'
      first=0
      printf '    {"segment": "%s", "reconverge": "%s", "state": "%s"}' \
        "$(gate_json_escape "$sib")" "$(gate_json_escape "$cite")" "$(gate_json_escape "$state")"
    done
  done <<EOF
$( { gate_rows 'stage-result' || true; } | { grep -F '| 종류=reconverge |' || true; } \
     | { grep -F '| 기록자=게이트 |' || true; } | { grep -F '| 재수렴 판정=재설계 필요 |' || true; })
EOF
  [ "$first" = "1" ] || printf '\n'
}

gate_plan_rows_of() {
  # gate_plan_rows_of <stage-key> — `gate_stage_result_rows_of` with the key's
  # `재계획` rows interleaved in ledger order: the input `implement_process_b`
  # reads, because a re-plan voids a plan the way a re-convergence does and the
  # reader has to see which of the two came last. One read over both series, so
  # the order is the ledger's and not a merge of two reads; `awk` with `index`
  # rather than a regex, because a Korean series name handed to a regex engine
  # is the construction run.sh had to rewrite after it failed on one CI leg.
  local rk rk2
  rk=$(gate_run_scope_kind_of_key "$1" 2>/dev/null) || rk=design
  rk2=$rk
  { [ "$rk" = "audit" ] || [ "$rk" = "design" ]; } && rk2=reconverge
  { awk 'index($0, "- `stage-result`") == 1 || index($0, "- `재계획`") == 1' "$LEDGER" 2>/dev/null || true; } \
    | { grep -F -e "세그먼트=$1 " -e "세그먼트=- | 스테이지=$1 | 종류=$rk " \
               -e "세그먼트=- | 스테이지=$1 | 종류=$rk2 " || true; }
}

gate_audit_result_rows_of() {
  # gate_audit_result_rows_of <audit step id> — the run-scope audit step's own
  # `종류=audit` rows, without the re-convergence that may share its key, in
  # either writer's shape (see `gate_run_scope_rows`). What the audit concluded
  # is read from these alone: a re-convergence that ended `정상 완료` has edited
  # the document, not audited it, so it must not stand in for the fresh audit
  # that follows it.
  gate_run_scope_rows "$1" audit
}

gate_audit_skeleton_count() {
  # gate_audit_skeleton_count — the audit report fence's skeletal count
  # (`골격급 수` plus `합성 요구 골격급 수`), or `미상` when the report carries
  # no single fence.
  local n
  n=$(audit_skeleton_fence_skeletal)
  printf '%s' "${n:-미상}"
}

# ---------------------------------------------------------------------------
# The `감사 공시` row — one per audit attempt, the material the design-path
# collector compares cohorts on.
#
# TWO WRITERS, ONE BUILDER. The gate's audit recorder calls it right after an
# audit's `stage-result` row; the fixed-graph driver calls it through
# `run_gate_call` after its S2 row and after a continued S2 attempt's row. The
# reconcile path writes none: its row is not an audit's end.
#
# VALUES COME FROM INSIDE THE FENCES ONLY. The counts are read between the
# disclosure v1 fence pair and the skeletal fence pair of the audit report, by
# the rule the measurement script follows: a report without exactly one pair
# reads `미상` for every slot of that fence, and no prose is read as a value.
# ---------------------------------------------------------------------------
GATE_AUDIT_DISCLOSURE_BEGIN='<!-- cc-design-audit-disclosure v1 begin -->'
GATE_AUDIT_DISCLOSURE_END='<!-- /cc-design-audit-disclosure v1 end -->'

gate_audit_disclosure_field() {
  # gate_audit_disclosure_field <slot> — the value of the disclosure v1 fence's
  # `**<slot>**: <n>` line when it is a count, `미상` otherwise (no report, not
  # exactly one fence pair, no such slot, not a number).
  local rp v
  rp=$(audit_report_path) || { printf '미상'; return 0; }
  [ -f "$rp" ] || { printf '미상'; return 0; }
  v=$(awk -v b="$GATE_AUDIT_DISCLOSURE_BEGIN" -v e="$GATE_AUDIT_DISCLOSURE_END" -v k="**$1**: " '
    { sub(/\r$/, "") }
    $0 == b { nb++; if (nb == 1 && ne == 0) inside = 1; next }
    $0 == e { ne++; if (inside) { inside = 0; closed = 1 }; next }
    inside && v == "" && index($0, k) == 1 { v = substr($0, length(k) + 1); sub(/[ \t]+$/, "", v) }
    END { if (nb != 1 || ne != 1 || !closed) exit 1; print v }' "$rp" 2>/dev/null) || v=""
  case "$v" in ''|*[!0-9]*) printf '미상' ;; *) printf '%s' "$v" ;; esac
}

gate_audit_skeletal_fence_count() {
  # gate_audit_skeletal_fence_count <field> — a count line of the skeletal
  # fence, `미상` when the fence or the line is absent or not a number.
  local v
  v=$(audit_skeleton_fence_field "$1")
  case "$v" in ''|*[!0-9]*) printf '미상' ;; *) printf '%s' "$v" ;; esac
}

gate_audit_version() {
  # gate_audit_version — the audit edition: the first 12 hex of the sha256 over
  # the audit's instruction files, read from the plugin copy this gate runs
  # from (`$(dirname "$GATE_DIR")`), in this order — the unattended audit
  # skill, the four shared references 01..04, then the `audit-reader` row of
  # the team model tier table (chosen by its first cell; left out when absent).
  # The plugin version moves on every merge, so two audits are compared only
  # when their instruction bytes are the same. `미상` on a run with no plugin
  # pin — its copy is not the one its stages read — and when a file is missing.
  [ -n "${RUN_DIR:-}" ] && [ -f "$RUN_DIR/plugin-pin" ] || { printf '미상'; return 0; }
  local pd f
  pd=$(dirname "$GATE_DIR")
  set -- skills/design-audit-unattended/SKILL.md \
    skills/design-audit/references/01-reader-prompt.md \
    skills/design-audit/references/02-deterministic-checks.md \
    skills/design-audit/references/03-adjustment-pass.md \
    skills/design-audit/references/04-disclosure-block.md
  for f in "$@"; do
    [ -f "$pd/$f" ] || { printf '미상'; return 0; }
  done
  { for f in "$@"; do cat "$pd/$f"; done
    awk 'index($0, "| `audit-reader` |") == 1' "$pd/skills/_common/team-model-tier.md" 2>/dev/null || true
  } | shasum -a 256 | cut -c1-12
}

gate_audit_plugin_word() {
  # gate_audit_plugin_word — `<version>@<commit 12>` from the run's plugin pin,
  # the shape the solo-audit experiment's `pin_of` writes; `미상` without one.
  local p="${RUN_DIR:-}/plugin-pin" v c
  [ -n "${RUN_DIR:-}" ] && [ -f "$p" ] || { printf '미상'; return 0; }
  v=$(awk -F'\t' '$1 == "version" { print $2; exit }' "$p" 2>/dev/null)
  c=$(awk -F'\t' '$1 == "commit" { print $2; exit }' "$p" 2>/dev/null)
  printf '%s@%s' "${v:-?}" "$(printf '%s' "$c" | cut -c1-12)"
}

gate_record_audit_disclosure() {
  # gate_record_audit_disclosure <audit step id> <attempt> — one `감사 공시` row.
  # `회차` is `재감사` when the key already carries a re-convergence in this run
  # (`audit_pass_of`), `최초` otherwise. `경로` uses the `설계 티어` row's words.
  local astep="$1" att="$2" pass
  pass=$(audit_pass_of "$astep")
  gate_append '감사 공시' "세그먼트=-" "스테이지=$astep" "실행 버전=${att:-미상}" \
    "경로=$(gate_design_path_word)" \
    "회차=$([ "$pass" = reaudit ] && printf '재감사' || printf '최초')" \
    "감사 판=$(gate_audit_version)" "플러그인=$(gate_audit_plugin_word)" \
    "원시=$(gate_audit_disclosure_field '원시 발견 수')" \
    "고유=$(gate_audit_disclosure_field '고유 결함 수')" \
    "미보강=$(gate_audit_disclosure_field '미보강 잔여 수')" \
    "바이트=$(gate_audit_disclosure_field '동결 문서 바이트')" \
    "골격급=$(gate_audit_skeletal_fence_count '골격급 수')" \
    "합성 후보=$(gate_audit_skeletal_fence_count '합성 요구 후보 수')" \
    "합성 골격급=$(gate_audit_skeletal_fence_count '합성 요구 골격급 수')"
}

# ---------------------------------------------------------------------------
# The `토론 패스` row — what the design team's late passes did, read from the
# durable witness corpus `$RUN_DIR/design/$DOC_SLUG/witness/` once the design
# attempt has ended. No stop condition reads it; the metrics collector and the
# design path report are its only readers.
#
# ONE WITNESS PER (MEMBER, ROUND/PHASE). A re-instruction inside the same round
# or phase is published as `{role-slug}.<P>-rev<k>.md` and replaces `<P>` whole,
# so the file with the largest k is chosen, the original only when no revision
# exists, and the two are never counted together. A name outside that grammar
# (`INDEX.md`, `SWEEP.md`, `*.prompt.md`, `*.coherence.epoch-6.md`) is not a
# witness. `scripts/measure-discussion-passes.sh` reads the same corpus by the
# same rules.
# ---------------------------------------------------------------------------
gate_discussion_pass_select() {
  # gate_discussion_pass_select <witness dir> <round/phase> — the chosen witness
  # of each member for that round or phase, one path per line, sorted. A
  # directory with no *.md leaves the glob unexpanded; `|| continue` keeps
  # that from becoming the pipeline's failing status under pipefail.
  local d="$1" p="$2" f
  for f in "$d"/*.md; do
    [ -f "$f" ] || continue
    printf '%s\n' "${f##*/}"
  done | awk -v p="$p" -v d="$d" '
    { n = substr($0, 1, length($0) - 3); k = 0
      if (match(n, /-rev[0-9]+$/)) { k = substr(n, RSTART + 4) + 0; n = substr(n, 1, RSTART - 1) }
      s = "." p
      if (length(n) <= length(s) || substr(n, length(n) - length(s) + 1) != s) next
      r = substr(n, 1, length(n) - length(s))
      if (r !~ /^[A-Za-z0-9_-]+$/) next
      if (!(r in best) || k > best[r]) { best[r] = k; file[r] = $0 } }
    END { for (r in file) print d "/" file[r] }' | LC_ALL=C sort
}

gate_discussion_read() {
  # gate_discussion_read <what> — reads the witness paths on stdin, one per
  # line, in one awk process however many there are, and prints:
  #   declarations — `<measure> <undeclared>`: how many witnesses declare
  #     `measure` and how many declare nothing. A witness's declaration is the
  #     last line that is exactly `round-3: none` or starts
  #     `round-3: measure — `, chosen across both forms.
  #   findings — the sum of each witness's last line that is exactly
  #     `findings: <n>`; `미상` with no witness or when any witness lacks the
  #     line, because a partial sum reads like a number.
  #   reopens — the number of `- type: decision-reopen` lines; `미상` with no
  #     witness.
  awk -v what="$1" '
    $0 == "" { next }
    { f = $0; n++; d = ""; v = ""
      while ((getline line < f) > 0) {
        sub(/\r$/, "", line)
        if (line == "round-3: none") d = "none"
        else if (index(line, "round-3: measure — ") == 1) d = "measure"
        if (line ~ /^findings: [0-9]+$/) v = substr(line, 11)
        s = line; sub(/^[ \t]+/, "", s); sub(/[ \t]+$/, "", s)
        if (s == "- type: decision-reopen") reopen++
      }
      close(f)
      if (d == "measure") measure++; else if (d == "") undeclared++
      if (v == "") missing++; else sum += v }
    END {
      if (what == "declarations") printf "%d %d", measure, undeclared
      else if (n == 0) printf "미상"
      else if (what == "reopens") printf "%d", reopen
      else if (missing) printf "미상"
      else printf "%d", sum }'
}

gate_discussion_last_mtime() {
  # gate_discussion_last_mtime — the latest modification time, in epoch
  # seconds, of the witness paths on stdin; empty when none can be read.
  local f t m=''
  while IFS= read -r f; do
    [ -n "$f" ] || continue
    t=$(gate_mtime "$f")
    case "$t" in ''|*[!0-9]*) continue ;; esac
    { [ -z "$m" ] || [ "$t" -gt "$m" ]; } && m=$t
  done
  printf '%s' "$m"
}

gate_record_discussion_passes() {
  # gate_record_discussion_passes <design step id> <attempt> — one `토론 패스`
  # row, or none when the corpus is absent or holds no `*.round-1.md`: the solo
  # design branch has no team. `R3 사유` is the first of five lines that holds —
  # closed with a measurement named `지명 미개방`, any other closed `해당 없음`,
  # open with a measurement named `측정 지명`, an R2 witness without a
  # declaration `미상`, and what is left `선언 없음`. Sweep rebuttals are not an
  # entry to R3 and stay out of the rule; `스윕 반박` carries them.
  local step="$1" att="$2" wd r1 r2 r3 fid coh
  [ -n "${RUN_DIR:-}" ] && [ -n "${DOC_SLUG:-}" ] || return 0
  wd="$RUN_DIR/design/$DOC_SLUG/witness"
  [ -d "$wd" ] || return 0
  r1=$(gate_discussion_pass_select "$wd" round-1)
  [ -n "$r1" ] || return 0
  r2=$(gate_discussion_pass_select "$wd" round-2)
  r3=$(gate_discussion_pass_select "$wd" round-3)
  fid=$(gate_discussion_pass_select "$wd" fidelity)
  coh=$(gate_discussion_pass_select "$wd" coherence)
  local open=0 m u named sweep why mins='미상' t2 t3
  [ -n "$r3" ] && open=1
  read -r m u <<EOF
$(printf '%s\n' "$r2" | gate_discussion_read declarations)
EOF
  named=$m
  [ "$m" -eq 0 ] && [ "$u" -gt 0 ] && named='미상'
  if [ -f "$wd/SWEEP.md" ]; then
    sweep=$(awk '{ sub(/\r$/, "") } index($0, "round-3: sweep — ") == 1 { c++ } END { printf "%d", c }' "$wd/SWEEP.md" 2>/dev/null) || sweep='미상'
  else
    sweep='미상'
  fi
  if [ "$open" -eq 0 ] && [ "$m" -ge 1 ]; then why='지명 미개방'
  elif [ "$open" -eq 0 ]; then why='해당 없음'
  elif [ "$m" -ge 1 ]; then why='측정 지명'
  elif [ "$u" -gt 0 ]; then why='미상'
  else why='선언 없음'
  fi
  if [ "$open" -eq 1 ] && [ -n "$r2" ]; then
    t2=$(printf '%s\n' "$r2" | gate_discussion_last_mtime)
    t3=$(printf '%s\n' "$r3" | gate_discussion_last_mtime)
    if [ -n "$t2" ] && [ -n "$t3" ] && [ "$t3" -ge "$t2" ]; then
      mins=$(( (t3 - t2) / 60 ))
    fi
  fi
  gate_append '토론 패스' "세그먼트=-" "스테이지=$step" "실행 버전=${att:-미상}" \
    "경로=$(gate_design_path_word)" "팀원=$(printf '%s\n' "$r1" | grep -c .)" \
    "R3=$([ "$open" -eq 1 ] && printf '열림' || printf '닫힘')" \
    "측정 지명=$named" "스윕 반박=$sweep" "R3 사유=$why" "R3 분=$mins" \
    "충실도 좌석=$(printf '%s\n' "$fid" | grep -c . || true)" \
    "충실도 발견=$(printf '%s\n' "$fid" | gate_discussion_read findings)" \
    "충실도 재개=$(printf '%s\n' "$fid" | gate_discussion_read reopens)" \
    "정합 좌석=$(printf '%s\n' "$coh" | grep -c . || true)" \
    "정합 발견=$(printf '%s\n' "$coh" | gate_discussion_read findings)"
}

gate_audit_concluded() {
  # gate_audit_concluded <audit step id> — 0 when what the audit's key says last
  # is an audit that ended `정상 완료` without asking for a re-convergence: the
  # key's last row is an audit row (not a re-convergence on that key), its
  # class is `정상 완료`, and its `재수렴 요청` is not `예`. 1 otherwise, with
  # GATE_AUDIT_WAIT naming what the key waits for — `없음` (no audit row in this
  # run), `재수렴` (a re-convergence came after the last audit, so a fresh audit
  # comes next), `골격급` (the last audit asked for a re-convergence) or `부류`
  # (the last audit ended another way) — and GATE_AUDIT_WHY the reason line.
  # Every place that asks whether the audit has concluded asks here.
  local astep="$1" arow al rl cls
  GATE_AUDIT_WAIT=''; GATE_AUDIT_WHY=''
  arow=$(gate_audit_result_rows_of "$astep" | tail -1)
  if [ -z "$arow" ]; then
    GATE_AUDIT_WAIT='없음'; GATE_AUDIT_WHY='이 런에 감사 행이 없습니다'
    return 1
  fi
  al=$( { grep -n -F -x -- "$arow" "$LEDGER" 2>/dev/null || true; } | tail -1 | cut -d: -f1)
  rl=$(audit_key_reconverge_rows "$astep" "$LEDGER" | tail -1 | cut -d: -f1)
  if [ -n "$rl" ] && { [ -z "$al" ] || [ "$rl" -gt "$al" ]; }; then
    GATE_AUDIT_WAIT='재수렴'; GATE_AUDIT_WHY='재수렴 뒤 새 감사를 기다립니다'
    return 1
  fi
  cls=$(gate_row_field "$arow" '종단 부류')
  if [ "$cls" != '정상 완료' ]; then
    GATE_AUDIT_WAIT='부류'; GATE_AUDIT_WHY="마지막 결과가 ${cls:-미상} 입니다"
    return 1
  fi
  if [ "$(gate_row_field "$arow" '재수렴 요청')" = '예' ]; then
    GATE_AUDIT_WAIT='골격급'; GATE_AUDIT_WHY='골격급 재수렴을 기다립니다'
    return 1
  fi
  return 0
}

gate_audit_skeleton_due_json() {
  # gate_audit_skeleton_due_json — `{"step": "<audit step id>", "skeletal": <n>}`
  # when the run-scope audit step waits on its skeletal re-convergence, `null`
  # otherwise. `skeletal` is the last audit row's `골격급`.
  local astep n
  if astep=$(gate_run_scope_step audit 2>/dev/null) \
     && ! gate_audit_concluded "$astep" && [ "$GATE_AUDIT_WAIT" = '골격급' ]; then
    n=$(gate_row_field "$(gate_audit_result_rows_of "$astep" | tail -1)" '골격급')
    case "$n" in ''|*[!0-9]*) n=0 ;; esac
    jq -cn --arg s "$astep" --argjson k "$n" '{step: $s, skeletal: $k}'
  else
    printf 'null'
  fi
}

gate_audit_wait_of() {
  # gate_audit_wait_of <audit step id> — prints what `gate_audit_concluded`
  # found the key waiting for, or nothing when the audit has concluded; for a
  # caller in another process, which cannot read the variables.
  gate_audit_concluded "$1" || printf '%s' "$GATE_AUDIT_WAIT"
}

gate_design_reconverge_after_audit() {
  # gate_design_reconverge_after_audit <audit step id> — 0 when the design
  # step's key carries a re-convergence on a later ledger line than the audit
  # step's last `종류=audit` row, or the audit has no row yet: the document has
  # been edited since anything audited it, so a fresh audit comes first. A
  # re-convergence that never spawned edited nothing and does not count.
  local dstep rl arow al
  dstep=$(gate_run_scope_step design 2>/dev/null) || return 1
  rl=$( { grep -n -F "세그먼트=- | 스테이지=$dstep | 종류=reconverge " "$LEDGER" 2>/dev/null || true; } \
        | { grep "^[0-9]*:- \`stage-result\` " || true; } \
        | { grep -vF '| 관측=스폰 전 대기 중' || true; } | tail -1 | cut -d: -f1)
  [ -n "$rl" ] || return 1
  arow=$(gate_audit_result_rows_of "$1" | tail -1)
  [ -n "$arow" ] || return 0
  al=$( { grep -n -F -x -- "$arow" "$LEDGER" 2>/dev/null || true; } | tail -1 | cut -d: -f1)
  [ -n "$al" ] || return 0
  [ "$rl" -gt "$al" ]
}

gate_design_reconverge_entry() {
  # gate_design_reconverge_entry <design step id> — 0 when a `- reconverge` on
  # the design step's key is the review a person opened on that stage's
  # residual ladder, with GATE_DRC_RECORD the ladder record it reviews; 1
  # otherwise, with GATE_DRC_WHY saying which fact is missing.
  #
  # THE ONE PERSON'S ANSWER TO A DESIGN STAGE THAT COMES BACK AS A PASS. Every
  # other answer to a design stage's record re-attaches that stage; a
  # `골격 재검토` on a `/ ladder-unsettled` record asks for the skeleton to be
  # reviewed against the residual items the ladder left, which the design
  # stage, already frozen, cannot do. Two states admit it, read from the
  # ledger alone:
  #
  # - BEFORE THE FREEZE. The person answered the record; the design stage was
  #   re-attached with that answer, wrote the review marker, froze, and its
  #   `정상 완료` row took the answer up.
  # - AFTER THE FREEZE. The seat (or a person) answered `잔여로 두고 동결`, the
  #   design stage froze on it — a design row ended `정상 완료` between the two
  #   answers — and a person later answered the same record `골격 재검토`, which
  #   no stage has taken up yet. The second answer is the immediately next one
  #   on that record, an answer a routing block returned to a person not
  #   counted.
  #
  # ONLY A PERSON'S ANSWER, AND EACH RECORD ONCE. The last `중단 답` of the key
  # is a person's `골격 재검토`, and no re-convergence of the key lands after
  # the record's first answer: a record that already opened a review does not
  # open a second one. A `--resume` of the review is admitted the way the
  # audit's is — the key's last row is a re-convergence of the session being
  # resumed.
  local dstep="$1" lines last ln row rec first c prev pln dr lrow
  GATE_DRC_RECORD=''; GATE_DRC_WHY=''
  lines=$( { grep -n -F "| 세그먼트=$dstep |" "$LEDGER" 2>/dev/null || true; } \
           | { grep "^[0-9]*:- \`중단 답\` " || true; })
  last=$(printf '%s\n' "$lines" | sed -n '$p')
  if [ -z "$last" ]; then
    GATE_DRC_WHY="설계 단계($dstep)에 중단 답 행이 없습니다"
    return 1
  fi
  ln=${last%%:*}; row=${last#*:}
  rec=$(gate_row_field "$row" '중단 기록')
  if [ -n "${GATE_RESUME:-}" ]; then
    lrow=$(gate_stage_result_rows_of "$dstep" | tail -1)
    if [ "$(gate_row_field "$lrow" '종류')" = "reconverge" ] \
       && [ "$(gate_row_field "$lrow" '세션 id')" = "$GATE_RESUME" ]; then
      GATE_DRC_RECORD=$rec
      return 0
    fi
  fi
  if [ "$(gate_row_field "$row" '선택지')" != '골격 재검토' ] \
     || [ "$(gate_halt_answered_by "$row")" != '사람' ]; then
    GATE_DRC_WHY="설계 단계($dstep)의 마지막 중단 답(원장 ${ln}번째 줄)이 사람의 「골격 재검토」 가 아닙니다"
    return 1
  fi
  case "$(sed -n 's/^\*\*스텝\*\*: //p' "$rec" 2>/dev/null | sed -n '1p')" in
    *'/ ladder-unsettled'*) ;;
    *) GATE_DRC_WHY="그 답의 중단 기록이 잔여 사다리(/ ladder-unsettled) 기록이 아닙니다: $rec"
       return 1 ;;
  esac
  first=$(printf '%s\n' "$lines" | awk -F: -v r="| 중단 기록=$rec |" '!f && index($0, r) { print $1; f = 1 }')
  if [ -n "$( { grep -n -F "세그먼트=- | 스테이지=$dstep | 종류=reconverge " "$LEDGER" 2>/dev/null || true; } \
               | { grep "^[0-9]*:- \`stage-result\` " || true; } \
               | { grep -vF '| 관측=스폰 전 대기 중' || true; } \
               | awk -F: -v l="$first" '$1 > l')" ]; then
    GATE_DRC_WHY="이 잔여 사다리 기록은 이미 재수렴을 한 번 열었습니다 — 같은 기록으로 두 번 열지 않습니다: $rec"
    return 1
  fi
  c=$(gate_halt_answer_consumer "$LEDGER" "$dstep" "$ln")
  if [ -n "$c" ]; then
    if [ "$(gate_row_field "${c#*:}" '종류')" != "design" ] \
       || [ "$(gate_row_field "${c#*:}" '종단 부류')" != "정상 완료" ]; then
      GATE_DRC_WHY="「골격 재검토」 답을 받은 행(원장 ${c%%:*}번째 줄)이 정상 완료로 끝난 설계 행이 아닙니다"
      return 1
    fi
  else
    # AN ANSWER A ROUTING BLOCK RETURNED IS SKIPPED. The shift could not carry
    # it out — a re-convergence refused while the audit was live, or one that
    # also fitted the audit's continuation — and handed the record back, so the
    # person's new answer stands where that one stood. Reading the returned
    # `골격 재검토` as the answer before would close this entry for the rest of
    # the run on one refusal the normal flow reaches.
    prev=''
    for pln in $(printf '%s\n' "$lines" | awk -F: -v l="$ln" -v r="| 중단 기록=$rec |" '$1 < l && index($0, r) { print $1 }' | LC_ALL=C sort -rn); do
      case "$(gate_halt_answer_consumer "$LEDGER" "$dstep" "$pln")" in
        *':- `blocked` '*) continue ;;
      esac
      prev="$pln:$(sed -n "${pln}p" "$LEDGER")"
      break
    done
    if [ -z "$prev" ] || [ "$(gate_row_field "${prev#*:}" '선택지')" != '잔여로 두고 동결' ]; then
      GATE_DRC_WHY="아직 아무 스테이지도 받지 않은 「골격 재검토」 는 같은 기록의 바로 앞 답이 「잔여로 두고 동결」 일 때만 재수렴을 엽니다: $rec"
      return 1
    fi
    pln=${prev%%:*}
    dr=$( { grep -n -F "세그먼트=- | 스테이지=$dstep | 종류=design " "$LEDGER" 2>/dev/null || true; } \
          | { grep "^[0-9]*:- \`stage-result\` " || true; } \
          | { grep -F '| 종단 부류=정상 완료 ' || true; } \
          | awk -F: -v a="$pln" -v b="$ln" '$1 > a && $1 < b')
    if [ -z "$dr" ]; then
      GATE_DRC_WHY="「잔여로 두고 동결」 답(원장 ${pln}번째 줄)과 「골격 재검토」 답 사이에 정상 완료로 끝난 설계 행이 없습니다 — 아직 동결되지 않았습니다"
      return 1
    fi
  fi
  GATE_DRC_RECORD=$rec
}

gate_stage_live_attempt() {
  # gate_stage_live_attempt <stage-key> — 0 when a dispatch of that stage key is
  # still running. The shared predicate the snapshot's `live_stages` loops over,
  # so a refusal here and the router's view of the run cannot disagree.
  cc_stage_is_live "$RUN_DIR" "$1"
}

gate_design_next_undispatched_step() {
  # gate_design_next_undispatched_step — the plan step that should follow a
  # frozen design and has not started: the audit step while it has no
  # `stage-result` row, else (no audit step, or an audit that ended `정상 완료`)
  # the plan's first implement step. Prints it and returns 0, or returns 1. The
  # caller asks only while no `segment` row exists, so an implement step named
  # here has no segment yet. An audit that has not concluded
  # (`gate_audit_concluded`) names nothing — one waiting on its skeletal
  # re-convergence included. A design-key re-convergence after the audit's last
  # row names the audit again: the document it audited has changed.
  local astep arows istep
  if astep=$(gate_run_scope_step audit); then
    arows=$(gate_audit_result_rows_of "$astep")
    if [ -z "$arows" ] || gate_design_reconverge_after_audit "$astep"; then
      printf '%s' "$astep"
      return 0
    fi
    gate_audit_concluded "$astep" || return 1
  fi
  istep=$(manifest_plan_json 2>/dev/null \
            | jq -r '[.steps[]? | select(type == "object" and .skill == "implement") | .id // empty | select(. != "")][0] // empty' 2>/dev/null \
            || true)
  [ -n "$istep" ] || return 1
  printf '%s' "$istep"
}

gate_plan_ends_at_design() {
  # gate_plan_ends_at_design — 0 when the plan's steps are a non-empty array of
  # objects whose `skill` is only `design` or `design-audit`, so the graph ends
  # at the design (or at its audit) and nothing follows. 1 otherwise, an
  # unparsable plan included: a plan this cannot read keeps its present verdict.
  manifest_plan_json 2>/dev/null \
    | jq -e '(.steps | type == "array" and length > 0)
             and all(.steps[]; type == "object" and (.skill == "design" or .skill == "design-audit"))' \
      >/dev/null 2>&1
}

# ---------------------------------------------------------------------------
# The segment plan, read from the frozen document rather than transcribed.
#
# A router that copies a slice's fields into `act --kind segment` drops them:
# the copy is prose, and prose is what the omission got past. So the values
# come from the document's `## 구현 슬라이싱` here, through the driver's own
# parsers, and the caller names only the segment, the state and the worktree.
# The driver's `plan_from_declaration` is not called whole — it writes rows
# through the driver's writer, parks through the driver's `park`, and names a
# worktree that does not exist yet, which the segment arm refuses for a
# non-terminal row. What is shared is the parsing, field by field.
#
# THREE BRANCHES, THE DRIVER'S. `미통치` (no declaration) plans one segment
# keyed on the plan's first implement step; `선언통치` plans one segment per
# slice; `선언불완전` is refused, naming every slice and every field it lacks,
# because the router can neither complete a declaration nor guess one.
# ---------------------------------------------------------------------------
gate_slicing_branch() {
  # gate_slicing_branch — `미통치`, `선언통치` or `선언불완전`. Never dies: the
  # driver's `slicing_branch` ends the process on an unclosed fence or a doubled
  # heading, and in the gate both are a declaration nobody can plan from, which
  # is `선언불완전` with its reason in `gate_slicing_defects`.
  local doc="${DOC:-}" rc=0
  { [ -n "$doc" ] && [ -f "$doc" ]; } || { printf '미통치'; return 0; }
  slicing_present "$doc" || rc=$?
  case "$rc" in
    0) if slicing_fields_ok "$doc" >/dev/null 2>&1; then printf '선언통치'; else printf '선언불완전'; fi ;;
    1) printf '미통치' ;;
    *) printf '선언불완전' ;;
  esac
}

gate_slicing_defects() {
  # gate_slicing_defects — one line per defect of an incomplete declaration:
  # every missing required field of every slice — the reason fields a
  # new-grammar block owes included — every `라벨 인정` defect and every
  # merge-order defect of every slice, then the driver's own first complaint
  # when something else is wrong.
  #
  # EVERY SLICE TO THE END, NOT THE FIRST DEFECT. The defect set decides which
  # slices park, so a second defective slice left out of it would be judged
  # clean and planned. The merge-order lines are `slicing_order_defects`' own,
  # which the driver's validator warns with, so the two speak the same bytes.
  local doc="${DOC:-}" rc=0 id="" f="" n=0 msg="" ord="" la=""
  slicing_present "$doc" || rc=$?
  case "$rc" in
    2) printf '「## 구현 슬라이싱」이 펜스 밖에 둘 이상 있습니다\n'; return 0 ;;
    3) printf '닫히지 않은 펜스가 있어 그 뒤 전부가 펜스 안으로 읽힙니다\n'; return 0 ;;
  esac
  for id in $(slice_ids "$doc" 2>/dev/null || true); do
    for f in 스킬 레포 '선언 파일' 선행 절단점; do
      if [ -z "$(slice_field "$doc" "$id" "$f" 2>/dev/null || true)" ]; then
        printf '슬라이스 %s: 필수 필드 「%s」 없음\n' "$id" "$f"
        n=$((n + 1))
      fi
    done
    while IFS= read -r f; do
      [ -n "$f" ] || continue
      if [ -z "$(slice_field "$doc" "$id" "$f" 2>/dev/null || true)" ]; then
        printf '슬라이스 %s: 필수 필드 「%s」 없음\n' "$id" "$f"
        n=$((n + 1))
      fi
    done <<EOF
$(slice_reason_keys "$doc" "$id" 2>/dev/null || true)
EOF
  done
  # The `라벨 인정` lines count into `n` with the missing fields: `base` mode
  # leaves them out, so without the count an otherwise clean declaration would
  # gain the unreadable-declaration line and lose its slice-owned reading.
  la=$(slicing_label_ack_defects "$doc" 2>/dev/null || true)
  if [ -n "$la" ]; then
    printf '%s\n' "$la"
    n=$((n + $(printf '%s\n' "$la" | wc -l | tr -d ' ')))
  fi
  ord=$(slicing_order_defects "$doc" 2>/dev/null || true)
  [ -z "$ord" ] || printf '%s\n' "$ord"
  [ "$n" = "0" ] || return 0
  msg=$( { slicing_fields_ok "$doc" base 2>&1 >/dev/null || true; } | sed -E 's/^[^]]*\] *(\[warn\] *)?//' | sed -n 1p)
  [ -z "$msg" ] && [ -n "$ord" ] && return 0
  printf '%s\n' "${msg:-선언을 읽을 수 없습니다}"
}

gate_slice_alias() {
  # gate_slice_alias <slice id> — the target alias the slice's `레포` names,
  # backticks stripped the way `plan_repo` strips them. Returns 1 when the slug
  # names no declared target.
  local slug=""
  slug=$(slice_field "$DOC" "$1" '레포' 2>/dev/null | tr -d '`' | sed 's/^[[:space:]]*//; s/[[:space:]]*$//')
  [ -n "$slug" ] || return 1
  alias_for_slug "$slug"
}

gate_plan_implement_step() {
  # The plan's first implement step id — the one segment of a run with no
  # declaration. Empty when the plan names none.
  manifest_plan_json 2>/dev/null \
    | jq -r '[.steps[]? | select(type == "object" and .skill == "implement") | .id // empty | select(. != "")][0] // empty' 2>/dev/null \
    || true
}

gate_decl_worktree() {
  # gate_decl_worktree <alias> <segment id> — the worktree path the driver's
  # `wt_path` gives the same segment, derived from the alias rather than from
  # `seg_root`, which reads the driver's `plan.tsv` and so resolves to the home
  # target on every router run.
  local root=""
  root=$(alias_root "$1" 2>/dev/null) || return 1
  [ -n "$root" ] || return 1
  printf '%s/%s%s%s-%s' "$(dirname "$root")" "$(basename "$root")" "$WORKTREE_INFIX" "$RUN_ID" "$2"
}

gate_adoption_row() {
  # gate_adoption_row <segment id> — the manifest's `세그먼트 입양` row for that
  # segment, or nothing. `check_manifest` has already refused a second row for
  # one segment, so the first match is the only one.
  local row
  while IFS= read -r row; do
    [ -n "$row" ] || continue
    if [ "$(manifest_row_fields "$row" '세그먼트')" = "$1" ]; then
      printf '%s' "$row"
      return 0
    fi
  done <<EOF
$(manifest_adoption_rows)
EOF
  return 1
}

gate_adoption_source_key() {
  # gate_adoption_source_key <adoption row> — the key the earlier run gave the
  # segment, which is what its ledger rows, its halt records and its pid files
  # are named after.
  #
  # NOT THE SEGMENT ID THIS RUN GIVES IT. The adoption row maps the earlier
  # run's segment onto a slice of this run's document, and the two names can
  # differ: a run with no `## 구현 슬라이싱` keys its one segment on the plan's
  # implementation step id, and the next run of the same work can declare the
  # slice under the ticket's name. Read with this run's id, the earlier ledger
  # has no row for the segment, so "the earlier run landed it" and "a stage of
  # the earlier run is still running on it" both come back false. The earlier
  # run named the worktree `<repo>-run-<run id>-<key>`, so the key is read from
  # there; the branch is no witness, since a stage may have checked out a branch
  # of its own. A worktree that does not carry that name falls back to the
  # segment id.
  local wt src base
  wt=$(manifest_row_fields "$1" '워크트리')
  src=$(manifest_row_fields "$1" '출처 런')
  base=$(basename "$wt")
  case "$base" in
    *"$WORKTREE_INFIX$src-"?*) printf '%s' "${base##*"$WORKTREE_INFIX$src-"}" ;;
    *) manifest_row_fields "$1" '세그먼트' ;;
  esac
}

gate_adoption_check() {
  # gate_adoption_check <segment id> <alias> <adoption row> — 0 when the
  # adopted segment may be planned in this run; otherwise a warning and 1.
  #
  # THE MANIFEST ROW IS A PERSON'S CLAIM AND THE DISK IS THE EVIDENCE, read
  # here rather than in `check_manifest` because that check runs on every gate
  # entry and the worktree is torn down once the segment lands. Three things:
  # the worktree is a tree of this segment's target and has the declared branch
  # checked out; the earlier run did not land the segment; and nothing of the
  # earlier run is still running on it, so two runs never write one worktree.
  # The last two are read under the earlier run's own key
  # (`gate_adoption_source_key`).
  #
  # A ROW WITH `출처 런=-` NAMES A SEGMENT NO RUN CUT — a person made the branch
  # and the pull request outside any run. Only the first check applies to it:
  # there is no earlier ledger to say it landed and no earlier stage that could
  # still be running. Whether its pull request is still open is the kickoff's to
  # verify and read back to the person; the gate reads only the disk.
  local seg="$1" al="$2" row="$3" wt br src skey cg want_cg cur src_ledger src_row src_st src_dir
  wt=$(manifest_row_fields "$row" '워크트리')
  br=$(manifest_row_fields "$row" '브랜치')
  src=$(manifest_row_fields "$row" '출처 런')
  skey=$(gate_adoption_source_key "$row")
  if [ ! -d "$wt" ]; then
    warn "입양 세그먼트 ${seg} 의 워크트리가 없습니다: $wt"
    return 1
  fi
  want_cg=$(target_field "$al" '공통 git 디렉터리')
  cg=$( { cd "$wt" && git rev-parse --path-format=absolute --git-common-dir 2>/dev/null; } || true)
  if [ -z "$cg" ] || [ "$cg" != "$want_cg" ]; then
    warn "입양 세그먼트 ${seg} 의 워크트리가 대상 ${al} 의 레포가 아닙니다: $wt"
    return 1
  fi
  cur=$( { cd "$wt" && git symbolic-ref --quiet --short HEAD 2>/dev/null; } || true)
  if [ "$cur" != "$br" ]; then
    warn "입양 세그먼트 ${seg} 의 워크트리에 체크아웃된 브랜치가 ${cur:-(분리된 HEAD)} 입니다 — 입양 행은 ${br} 를 선언합니다"
    return 1
  fi
  [ "$src" != "-" ] || return 0
  src_ledger="$(dirname "$LEDGER")/$src.md"
  if [ ! -f "$src_ledger" ]; then
    warn "입양 세그먼트 ${seg} 의 출처 런 원장이 없습니다: $src_ledger — 출처 런이 그 세그먼트를 착지시키지 않았는지 판정할 수 없습니다"
    return 1
  fi
  # The landing is found by the walk the import uses (`gate_landing_walk`), so
  # a segment merged and then parked is not adopted to be done again; the row
  # it stops on counts when it is `머지됨` or `완료`, as the last row did.
  if gate_landing_walk gate_adoption_row_landed <<ROWS
$( { grep -E '^- `segment` ' "$src_ledger" 2>/dev/null || true; } | { grep -F "| id=$skey |" || true; })
ROWS
  then
    src_st=$(gate_row_field "$GATE_WALK_ROW" '상태')
    warn "입양 세그먼트 ${seg} 는 출처 런 ${src} 가 이미 ${src_st} 로 끝냈습니다 — 착지한 세그먼트는 입양하지 않습니다"
    return 1
  fi
  src_dir="$(dirname "$RUN_DIR")/$src"
  if cc_stage_is_live "$src_dir" "$skey"; then
    warn "입양 세그먼트 ${seg} 에 출처 런 ${src} 의 스테이지가 아직 살아 있습니다 — 두 런이 한 워크트리에 쓰지 않도록 그 스테이지가 끝난 뒤 계획하세요"
    return 1
  fi
  return 0
}

gate_adoption_halt_source() {
  # gate_adoption_halt_source <segment id> — whether the earlier run of an
  # adopted segment left a person's answer to a halt that no stage took up, and
  # whether that answer can be carried into this run. 0 when it can, with the
  # earlier row in GATE_CARRY_ROW, its line in GATE_CARRY_LINE, the earlier run
  # in GATE_CARRY_SRC and the record and attachment paths in GATE_CARRY_REC and
  # GATE_CARRY_ATT; 1 when there is nothing open to carry; 2 when there is an
  # open answer that does not carry, with the reason in GATE_CARRY_WHY.
  # Writes nothing.
  #
  # WHAT IS OPEN IS DECIDED AS THE EARLIER RUN DECIDES IT: its last `중단 답`
  # row on the segment's earlier key, not spent by `gate_halt_answer_spent` in
  # its own ledger. An answer some ledger in the same directory already carried
  # — this run's on a repeated planning act, or a run that adopted the segment
  # before this one — is not open either: carrying it twice would hand one
  # answer to two stages.
  #
  # ONLY AN ANSWER THIS RUN CAN CARRY OUT WITHOUT THE HALTED SESSION CARRIES.
  # Every other answer is handed on by re-attaching the session that halted,
  # and that session belongs to the earlier run: the gate admits a resume only
  # of a session on this run's own `stage-result` rows, the session was born
  # under the earlier run's settings, plugin copy and instruction synthesis,
  # and the plan it would continue lives in the earlier run's directory and
  # ledger, which this run's stages cannot read. Two answers need no session.
  # An implement stage's binding-tier stop (CFI-U3 BT-STOP) answered `재수렴`:
  # its route re-converges the document on the record and plans the segment
  # again from its first process. And an answer the earlier run's ledger names
  # in an `이월` row (`gate_halt_answer_deferred`): a carry act there found no
  # room before the deadline and kept the answer for the next run, and only a
  # halt of the re-entry table is carried that way, so a fresh session of this
  # run takes it up through this run's own carry act. Any other open answer —
  # one the earlier run never tried to carry — is warned about and stays.
  #
  # Every guarantee of the seat's own `halt-answer` holds for the copy. The
  # answer must be the seat's — a person's, or the record's recommendation the
  # seat copied, whose `답한 주체` the copy keeps — and a shift's pre-adopted
  # `재수렴` is told apart by the prefix the gate stamps on its `근거`; the record must still be the
  # complete halt record that row hashed and list the option verbatim, the
  # attachment must still hash to its row, no stage of the earlier run may be
  # alive on the key, and a record the earlier run already re-converged once
  # does not go to a second re-convergence. The earlier run's document must be
  # this run's, since the record quotes it.
  local seg="$1" adrow src skey sdir sledger lines row ln rec att opt skill step e
  GATE_CARRY_ROW=''; GATE_CARRY_LINE=''; GATE_CARRY_SRC=''; GATE_CARRY_REC=''; GATE_CARRY_ATT=''; GATE_CARRY_WHY=''
  adrow=$(gate_adoption_row "$seg") || return 1
  src=$(manifest_row_fields "$adrow" '출처 런')
  # A segment no run cut (`출처 런=-`) has no earlier run to carry from.
  [ "$src" != "-" ] || return 1
  skey=$(gate_adoption_source_key "$adrow")
  sledger="$(dirname "$LEDGER")/$src.md"
  sdir="$(dirname "$RUN_DIR")/$src"
  [ -f "$sledger" ] || return 1
  lines=$( { grep -n "^- \`중단 답\` " "$sledger" 2>/dev/null || true; } | { grep -F "| 세그먼트=$skey |" || true; })
  row=$(printf '%s\n' "$lines" | tail -1)
  [ -n "$row" ] || return 1
  ln=${row%%:*}
  row=${row#*:}
  if gate_halt_answer_spent "$sledger" "$skey" "$ln"; then return 1; fi
  rec=$(gate_row_field "$row" '중단 기록')
  [ -n "$rec" ] || return 1
  if gate_carry_already_imported "$rec"; then return 1; fi
  GATE_CARRY_SRC=$src; GATE_CARRY_LINE=$ln
  case "$(gate_row_field "$row" '근거')" in
    '자동 채택(구속-이탈) — '*)
      GATE_CARRY_WHY="교대가 매니페스트의 자동 채택으로 쓴 답이라 사람의 답이 아닙니다"
      return 2 ;;
  esac
  skill=$(gate_row_field "$row" '스킬')
  opt=$(gate_row_field "$row" '선택지')
  case "$rec" in
    "$sdir"/halt/*.md) ;;
    *) GATE_CARRY_WHY="중단 기록이 출처 런의 halt 디렉터리 밖에 있습니다: $rec"; return 2 ;;
  esac
  case "$rec" in
    */../*|*/./*) GATE_CARRY_WHY="중단 기록 경로에 상대 구간이 있습니다: $rec"; return 2 ;;
  esac
  if [ ! -f "$rec" ]; then
    GATE_CARRY_WHY="중단 기록이 없습니다: $rec"
    return 2
  fi
  step=$(sed -n 's/^\*\*스텝\*\*: //p' "$rec" | sed -n '1p')
  step="${step%% — *}"
  if { [ "$skill" != "implement-unattended" ] || [ "$opt" != "재수렴" ] \
       || [ "${step#*CFI-U3 BT-STOP}" = "$step" ]; } \
     && ! gate_halt_answer_deferred "$sledger" "$ln"; then
    GATE_CARRY_WHY="스킬 ${skill:-미상} 의 기록(스텝 「${step}」)에 대한 답 「${opt}」 은 멈춘 세션을 다시 붙여 넘기는 답인데, 그 세션은 출처 런의 것이라 이 런에서 다시 붙일 수 없고, 출처 원장에 그 답을 다음 런으로 넘긴 이월 행도 없습니다 — implement-unattended 기록 중 스텝 문면의 첫 \` — \` 앞에 CFI-U3 BT-STOP 이 있는 기록에 대한 「재수렴」 답과, 출처 원장의 이월 행이 이름 짓는 답만 이 런으로 이어집니다"
    return 2
  fi
  if cc_stage_is_live "$sdir" "$skey"; then
    GATE_CARRY_WHY="출처 런의 스테이지가 그 키에서 아직 살아 있습니다"
    return 2
  fi
  gate_carry_record_whole "$sdir" "$rec" "$row" || return 2
  att=$(gate_row_field "$row" '첨부')
  # ONCE PER RECORD, as the earlier run would have counted it: an earlier
  # `재수렴` answer on the same record followed by a re-convergence of the key.
  for e in $(printf '%s\n' "$lines" | { grep -F "| 중단 기록=$rec |" || true; } \
             | { grep -F '| 선택지=재수렴 |' || true; } | cut -d: -f1); do
    [ "$e" -lt "$ln" ] || continue
    if { grep -n -F "세그먼트=$skey " "$sledger" 2>/dev/null || true; } \
         | { grep "^[0-9]*:- \`stage-result\` " || true; } | { grep -F '| 종류=reconverge |' || true; } \
         | awk -F: -v l="$e" '$1 > l { n++ } END { exit n ? 0 : 1 }'; then
      GATE_CARRY_WHY="출처 런이 그 기록으로 이미 한 번 재수렴했습니다 — 두 번째는 사람에게 갑니다"
      return 2
    fi
  done
  gate_carry_source_doc_same "$src" || return 2
  GATE_CARRY_ROW=$row; GATE_CARRY_REC=$rec; GATE_CARRY_ATT=$att
  return 0
}

gate_carry_already_imported() {
  # gate_carry_already_imported <earlier record> — whether some ledger in this
  # directory already brought in the answer to <earlier record>: a row names it
  # as `출처 기록` (a first carry) or as `경유 기록` (a carry of a copy, whose
  # `출처 기록` is the record the person answered). Carrying it twice would hand
  # one answer to two stages.
  grep -qlF -e "| 출처 기록=$1 |" -e "| 경유 기록=$1 |" "$(dirname "$LEDGER")"/*.md 2>/dev/null
}

gate_carry_record_whole() {
  # gate_carry_record_whole <earlier run dir> <record> <earlier `중단 답` row> —
  # whether the record that row answered is still the record the person
  # answered, and its attachment the one they gave: the record is a complete
  # halt record listing the row's option verbatim and hashing to the row's
  # `기록 다이제스트`, and the attachment, when there is one, lies under the
  # earlier run's `halt/`, is not empty, hashes to `첨부 다이제스트` and is not
  # itself a record. 1 with the reason in GATE_CARRY_WHY otherwise. The
  # adoption and the re-kickoff import ask it alike before copying.
  local sdir="$1" rec="$2" row="$3" opt dig att adig hfirst=''
  opt=$(gate_row_field "$row" '선택지')
  dig=$(gate_row_field "$row" '기록 다이제스트')
  IFS= read -r hfirst < "$rec" || true
  if [ "${hfirst#<!-- cc-pipeline-halt v1;}" = "$hfirst" ] \
     || ! grep -qxF '<!-- /cc-pipeline-halt v1 -->' "$rec" \
     || ! grep -qF -- "- \`$opt\`" "$rec"; then
    GATE_CARRY_WHY="중단 기록이 완결된 기록이 아니거나 그 선택지를 축자로 싣지 않습니다: $rec"
    return 1
  fi
  case "$dig" in
    ''|-) GATE_CARRY_WHY="출처 행에 기록 다이제스트가 없어 기록을 대조할 기준이 없습니다"; return 1 ;;
  esac
  if [ "$(shasum -a 256 "$rec" | cut -d' ' -f1)" != "$dig" ]; then
    GATE_CARRY_WHY="중단 기록이 출처 행의 기록 다이제스트와 다릅니다 — 사람이 답한 뒤 기록이 바뀌었습니다: $rec"
    return 1
  fi
  att=$(gate_row_field "$row" '첨부')
  [ -n "$att" ] || return 0
  adig=$(gate_row_field "$row" '첨부 다이제스트')
  case "$att" in
    "$sdir"/halt/*.md) ;;
    *) GATE_CARRY_WHY="첨부가 출처 런의 halt 디렉터리 밖에 있습니다: $att"; return 1 ;;
  esac
  case "$att" in
    */../*|*/./*) GATE_CARRY_WHY="첨부 경로에 상대 구간이 있습니다: $att"; return 1 ;;
  esac
  if [ ! -s "$att" ] || [ "$(shasum -a 256 "$att" | cut -d' ' -f1)" != "$adig" ]; then
    GATE_CARRY_WHY="첨부가 없거나 비었거나 출처 행의 첨부 다이제스트와 다릅니다: $att"
    return 1
  fi
  if grep -q '^<!-- cc-pipeline-halt v1' "$att"; then
    GATE_CARRY_WHY="첨부가 중단 기록 머리를 싣고 있습니다: $att"
    return 1
  fi
  return 0
}

gate_carry_source_doc_same() {
  # gate_carry_source_doc_same <earlier run id> — whether the earlier run's
  # frozen manifest names this run's design document; 1 with the reason in
  # GATE_CARRY_WHY otherwise. A halt record quotes its own run's document, so
  # an answer to it means nothing against another one.
  local sman sdoc doc
  sman="$(dirname "$LEDGER")/$1.plan.md"
  sdoc=$( [ -f "$sman" ] && awk '$0 == "## 요소" { inb=1; next } inb && /^## / { exit }
            inb && sub(/^\*\*설계 문서\*\*: /, "") { print; exit }' "$sman" )
  doc=$(manifest_field '요소' '설계 문서')
  if [ -z "$sdoc" ] || [ "$sdoc" != "$doc" ]; then
    GATE_CARRY_WHY="출처 런의 설계 문서(${sdoc:-확인 불가})가 이 런의 설계 문서(${doc:-없음})와 다릅니다 — 기록이 인용한 구속 티어가 이 런의 문서에 있다고 볼 수 없습니다"
    return 1
  fi
  return 0
}

gate_carry_copy() {
  # gate_carry_copy <source> <destination> <sha256> — copy a file into this
  # run's halt directory and succeed only when the copy hashes to <sha256>. A
  # destination already there with those bytes — a repeated act — is kept.
  local src="$1" dst="$2" want="$3" tmp
  if [ -f "$dst" ]; then
    [ "$(shasum -a 256 "$dst" | cut -d' ' -f1)" = "$want" ]
    return
  fi
  tmp=$(mktemp "$(dirname "$dst")/.carry.XXXXXX") || return 1
  if ! cp "$src" "$tmp" || [ "$(shasum -a 256 "$tmp" | cut -d' ' -f1)" != "$want" ]; then
    rm -f "$tmp"
    return 1
  fi
  mv -n "$tmp" "$dst"
  rm -f "$tmp"
  [ -f "$dst" ] && [ "$(shasum -a 256 "$dst" | cut -d' ' -f1)" = "$want" ]
}

gate_adoption_halt_carry() {
  # gate_adoption_halt_carry <segment id> — the adopted segment's planning act
  # brings the earlier run's open answer into this run, after the segment row.
  #
  # THE PERSON IS NOT ASKED AGAIN FOR AN ANSWER THEY ALREADY GAVE. A run that
  # ends with an answer it could not hand on — its deadline passed, its budget
  # ran out — leaves that answer in its own ledger, and the run that adopts the
  # segment reads only its own: measured, a person answered a binding-tier stop
  # at the seat, said the answer would go on in a new run, and had to answer
  # the same question again at that run's kickoff.
  #
  # A COPY, NOT A REFERENCE. The record and the attachment are copied under
  # this run's `halt/`, where every reader of a halt answer already looks — the
  # prompt rule that a `.md` under this run's `halt/` is never a document
  # argument, the stages' readable directories, and the once-per-record count
  # on this ledger — and each copy is compared with the earlier row's digest.
  # The attachment copy is named as the seat names an attachment beside its
  # record, `<record copy>.answer.md`: every count of unanswered records passes
  # over that suffix, and under any other name the copy would read as a
  # question nobody answered and hold the run's hand-off and ending.
  # The row written is an ordinary `중단 답` row of this run plus `출처 런` and
  # `출처 기록`, so the snapshot lists it and spends it exactly as it does an
  # answer given here; `근거` says where it came from, and `레인` and
  # `기록 시각` are the earlier row's, the person's answer's own.
  #
  # NEVER A REFUSAL. The segment is already planned when this runs, and an
  # answer that does not carry leaves the adopted segment where it was before
  # this existed — its first stage a full review — so what does not carry is
  # warned about by name and nothing else happens.
  local seg="$1" rc=0 dst adst='' adig=''
  gate_adoption_halt_source "$seg" || rc=$?
  case "$rc" in
    0) ;;
    1) return 0 ;;
    *) warn "입양 세그먼트 ${seg} 에 출처 런 ${GATE_CARRY_SRC} 의 열린 중단 답(그 원장 ${GATE_CARRY_LINE} 번째 줄)이 있지만 이 런으로 이어지지 않습니다 — ${GATE_CARRY_WHY}"
       return 0 ;;
  esac
  mkdir -p "$RUN_DIR/halt"
  dst="$RUN_DIR/halt/$seg#adopted-$GATE_CARRY_SRC.md"
  if ! gate_carry_copy "$GATE_CARRY_REC" "$dst" "$(gate_row_field "$GATE_CARRY_ROW" '기록 다이제스트')"; then
    warn "입양 세그먼트 ${seg} 의 출처 런 중단 기록을 이 런으로 복사하지 못했습니다 — 답을 들여오지 않습니다: $GATE_CARRY_REC"
    return 0
  fi
  if [ -n "$GATE_CARRY_ATT" ]; then
    adst="${dst%.md}.answer.md"
    adig=$(gate_row_field "$GATE_CARRY_ROW" '첨부 다이제스트')
    if ! gate_carry_copy "$GATE_CARRY_ATT" "$adst" "$adig"; then
      warn "입양 세그먼트 ${seg} 의 출처 런 첨부를 이 런으로 복사하지 못했습니다 — 답을 들여오지 않습니다: $GATE_CARRY_ATT"
      return 0
    fi
  fi
  if ! gate_carry_import_row "$seg" "$dst" "$adst" "$adig" '입양 이월'; then
    warn "입양 세그먼트 ${seg} 의 이월 중단 답 행이 행 상한에 들지 않습니다 — 답을 들여오지 않습니다"
    return 0
  fi
  log "중단 답 이월 — $seg ← 출처 런 $GATE_CARRY_SRC ($(gate_row_field "$GATE_CARRY_ROW" '선택지'))"
}

gate_carry_import_row() {
  # gate_carry_import_row <key> <record copy> <attachment copy> <attachment
  # digest> <basis prefix> [<row kind>] — write the `중단 답` row of this run
  # that hands on the earlier run's answer in GATE_CARRY_ROW (its ledger line
  # GATE_CARRY_LINE, its run GATE_CARRY_SRC, its record GATE_CARRY_REC) under
  # <key>, naming the copies already made under this run's `halt/`. `근거` is
  # `<basis prefix>(출처 런 … 원장 N 번째 줄) — <the earlier 근거>`, narrowed
  # until the row fits; 1 with nothing written when even the narrowest does
  # not. The attachment arguments are empty when the answer had none. A
  # re-kickoff import passes the run-scope kind it brought the answer in for,
  # written as `연쇄 종류`, so a run that carries this copy on finds the key here
  # by kind even when no attempt of it ever ran in this run.
  #
  # ONE WRITER FOR THE ADOPTION AND THE RE-KICKOFF IMPORT, so the two copies
  # carry the same fields and every reader — the snapshot, the carry act's
  # check against `출처 런`, the once-per-record count — reads them alike.
  #
  # `출처 런` IS THE RUN THE PERSON ANSWERED IN, however many runs the answer
  # went through. A copy carried over again names no attempt of its own: the
  # run that brought it in deferred it before any stage took it up. Every
  # reader of `출처 런` — the carry act's currency and scope checks, the route
  # the snapshot gives, the refusal of other dispatches of the key — asks that
  # ledger for the attempt that halted, so a row that named the run in between
  # would send them to a ledger where nothing halted. When the earlier row is
  # itself a copy, its `출처 런` and `출처 기록` are written again, and the copy
  # this answer came through is `경유 기록`, which the once-per-record count
  # reads beside `출처 기록`.
  #
  # WHO ANSWERED TRAVELS WITH THE ANSWER. A seat's automatic answer carried in
  # under this run's key is still automatic, so the `구속-이탈` count and the
  # one-automatic-answer-per-record check here see it for what it is. The
  # fields are listed one by one; if carrying ever widens to a seat's answer to
  # a design ladder, its `잔여 판정` stamp has to join this list.
  local key="$1" dst="$2" adst="$3" adig="$4" pre="$5" ck="${6:-}" why w=300 len lane at by kinds
  local osrc="$GATE_CARRY_SRC" orec="$GATE_CARRY_REC" via=''
  lane=$(gate_row_field "$GATE_CARRY_ROW" '레인')
  at=$(gate_row_field "$GATE_CARRY_ROW" '기록 시각')
  by=$(gate_halt_answered_by "$GATE_CARRY_ROW")
  kinds=$(gate_row_field "$GATE_CARRY_ROW" '근거 종류')
  if [ -n "$(gate_row_field "$GATE_CARRY_ROW" '출처 런')" ]; then
    osrc=$(gate_row_field "$GATE_CARRY_ROW" '출처 런')
    orec=$(gate_row_field "$GATE_CARRY_ROW" '출처 기록')
    via=$GATE_CARRY_REC
  fi
  while [ "$w" -ge 40 ]; do
    why=$(gate_row_safe "${pre}(출처 런 $GATE_CARRY_SRC 원장 ${GATE_CARRY_LINE} 번째 줄) — $(gate_row_field "$GATE_CARRY_ROW" '근거')" "$w")
    len=$(gate_row_projected_bytes '중단 답' "세그먼트=$key" "중단 기록=$dst" \
      "스킬=$(gate_row_field "$GATE_CARRY_ROW" '스킬')" "선택지=$(gate_row_field "$GATE_CARRY_ROW" '선택지')" \
      "답한 주체=$by" "근거=$why" ${kinds:+"근거 종류=$kinds"} \
      "기록 다이제스트=$(gate_row_field "$GATE_CARRY_ROW" '기록 다이제스트')" \
      ${adst:+"첨부=$adst"} ${adst:+"첨부 다이제스트=$adig"} \
      "출처 런=$osrc" "출처 기록=$orec" ${via:+"경유 기록=$via"} ${ck:+"연쇄 종류=$ck"} \
      "레인=${lane:-미상}" "기록 시각=${at:-미상}")
    [ "$len" -le "$GATE_ROW_MAX" ] && break
    w=$((w - 40))
  done
  [ "$len" -le "$GATE_ROW_MAX" ] || return 1
  gate_append '중단 답' "세그먼트=$key" "중단 기록=$dst" \
    "스킬=$(gate_row_field "$GATE_CARRY_ROW" '스킬')" "선택지=$(gate_row_field "$GATE_CARRY_ROW" '선택지')" \
    "답한 주체=$by" "근거=$why" ${kinds:+"근거 종류=$kinds"} \
    "기록 다이제스트=$(gate_row_field "$GATE_CARRY_ROW" '기록 다이제스트')" \
    ${adst:+"첨부=$adst"} ${adst:+"첨부 다이제스트=$adig"} \
    "출처 런=$osrc" "출처 기록=$orec" ${via:+"경유 기록=$via"} ${ck:+"연쇄 종류=$ck"} \
    "레인=${lane:-미상}" "기록 시각=${at:-미상}"
}

gate_chain_source_key() {
  # gate_chain_source_key <earlier ledger> <row kind> — the run-scope step id
  # the earlier run keyed that kind on: the `스테이지` of its last
  # `stage-result` row of the router's run-scope shape
  # (`세그먼트=- | 스테이지=<id> | 종류=<kind>`), or nothing. A re-kickoff's
  # manifest is planned anew, so its step ids are not taken to be the earlier
  # run's; the kind is what the two runs share.
  #
  # AN EARLIER RUN THAT ONLY PASSED THE ANSWER ON RAN NO ATTEMPT OF THE KEY. It
  # brought the answer in at the step's first dispatch, refused that dispatch,
  # and deferred the answer again before any stage took it up, so it holds no
  # `stage-result` row of that kind. Its key is then the one its own import
  # wrote under that kind (`연쇄 종류`), the last such row.
  local k
  k=$( { grep "^- \`stage-result\` " "$1" 2>/dev/null || true; } \
    | { grep -F "| 세그먼트=- | " || true; } | { grep -F "| 종류=$2 |" || true; } \
    | while IFS= read -r r; do gate_row_field "$r" '스테이지'; printf '\n'; done \
    | awk 'NF { k = $0 } END { if (k != "") print k }')
  if [ -z "$k" ]; then
    k=$( { grep "^- \`중단 답\` " "$1" 2>/dev/null || true; } \
      | { grep -F "| 연쇄 종류=$2 |" || true; } \
      | while IFS= read -r r; do gate_row_field "$r" '세그먼트'; printf '\n'; done \
      | awk 'NF { k = $0 } END { if (k != "") print k }')
  fi
  [ -z "$k" ] || printf '%s\n' "$k"
}

gate_chain_halt_source() {
  # gate_chain_halt_source <key> <row kind> <earlier run id> — whether the
  # earlier run of a re-kickoff left an answer to a halt of the run-scope step
  # of that kind which it carried over to the next run (an `이월` row of its
  # ledger names it). 0 when it can be brought in, with GATE_CARRY_ROW,
  # GATE_CARRY_LINE, GATE_CARRY_SRC, GATE_CARRY_REC and GATE_CARRY_ATT set as
  # `gate_adoption_halt_source` sets them; 1 when there is none; 2 when there
  # is one that cannot be brought in, with the reason in GATE_CARRY_WHY.
  # Writes nothing.
  #
  # ONLY AN `이월` ANSWER. An answer the earlier run never tried to carry is
  # left where it is, as before: the re-kickoff notice lists it and a person
  # answers it again if it is still the question. An answer some ledger in this
  # directory already brought in — this run's, or another follow-up's — is not
  # brought in twice.
  local key="$1" rk="$2" src="$3" skey sledger sdir row ln rec
  GATE_CARRY_ROW=''; GATE_CARRY_LINE=''; GATE_CARRY_SRC=''; GATE_CARRY_REC=''; GATE_CARRY_ATT=''; GATE_CARRY_WHY=''
  sledger="$(dirname "$LEDGER")/$src.md"
  sdir="$(dirname "$RUN_DIR")/$src"
  [ -f "$sledger" ] || return 1
  skey=$(gate_chain_source_key "$sledger" "$rk")
  [ -n "$skey" ] || return 1
  row=$( { grep -n "^- \`중단 답\` " "$sledger" 2>/dev/null || true; } \
         | { grep -F "| 세그먼트=$skey |" || true; } | tail -1)
  [ -n "$row" ] || return 1
  ln=${row%%:*}
  row=${row#*:}
  if gate_halt_answer_spent "$sledger" "$skey" "$ln"; then return 1; fi
  gate_halt_answer_deferred "$sledger" "$ln" || return 1
  rec=$(gate_row_field "$row" '중단 기록')
  [ -n "$rec" ] || return 1
  if gate_carry_already_imported "$rec"; then return 1; fi
  GATE_CARRY_SRC=$src; GATE_CARRY_LINE=$ln
  case "$rec" in
    "$sdir"/halt/*.md) ;;
    *) GATE_CARRY_WHY="중단 기록이 출처 런의 halt 디렉터리 밖에 있습니다: $rec"; return 2 ;;
  esac
  case "$rec" in
    */../*|*/./*) GATE_CARRY_WHY="중단 기록 경로에 상대 구간이 있습니다: $rec"; return 2 ;;
  esac
  if [ ! -f "$rec" ]; then
    GATE_CARRY_WHY="중단 기록이 없습니다: $rec"
    return 2
  fi
  if cc_stage_is_live "$sdir" "$skey"; then
    GATE_CARRY_WHY="출처 런의 스테이지가 그 키에서 아직 살아 있습니다"
    return 2
  fi
  gate_carry_record_whole "$sdir" "$rec" "$row" || return 2
  gate_carry_source_doc_same "$src" || return 2
  GATE_CARRY_ROW=$row; GATE_CARRY_REC=$rec; GATE_CARRY_ATT=$(gate_row_field "$row" '첨부')
  return 0
}

gate_chain_halt_import() {
  # gate_chain_halt_import <key> <verb> — on a re-kickoff's follow-up run, the
  # first dispatch of a run-scope step brings in the earlier run's answer
  # carried over to the next run for the step of the same kind, and is refused.
  # Returns 0 when nothing was brought in (the dispatch goes on), and
  # GATE_EXIT_RULE when an answer was brought in — by `act`, which writes the
  # copy and its row — or would be, by `plan`, which writes nothing.
  #
  # THE EARLIER RUN IS THE MANIFEST'S PROVENANCE ROW. A re-kickoff writes one
  # `사전 인가` row whose first field is `이어받은 런=<id>`, a person's and a
  # seat's re-kickoff alike, and the row sits inside the binding digest, so the
  # earlier run cannot change within the run. It is read by the reader the
  # driver uses (`manifest_provenance_field`); a manifest without it brings in
  # nothing. A segment brings an answer in through its adoption row instead.
  #
  # THE DISPATCH THAT BROUGHT THE ANSWER IN DOES NOT LAUNCH. Its `stage-result`
  # would land after the new `중단 답` row and spend it by position, with no
  # card handed to the session — the answer would be gone without anyone asked
  # again. The refusal names the line for `--carry-answer`, and the shift
  # dispatches the carry act; this run holds no session of the key, so the carry
  # asks for a fresh one.
  local key="$1" verb="$2" src rk rc=0 dst adst='' adig='' ln
  src=$(manifest_provenance_field '이어받은 런' 2>/dev/null) || return 0
  [ -n "$src" ] || return 0
  rk=$(gate_run_scope_kind_of_key "$key" 2>/dev/null) || return 0
  [ -z "$(gate_stage_result_rows_of "$key" 2>/dev/null)" ] || return 0
  gate_chain_halt_source "$key" "$rk" "$src" || rc=$?
  case "$rc" in
    0) ;;
    1) return 0 ;;
    *) warn "${key} 에 이어받은 런 ${GATE_CARRY_SRC} 의 이월 중단 답(그 원장 ${GATE_CARRY_LINE} 번째 줄)이 있지만 이 런으로 들여오지 않습니다 — ${GATE_CARRY_WHY}"
       return 0 ;;
  esac
  if [ "$verb" != "act" ]; then
    warn "act 는 이어받은 런 ${GATE_CARRY_SRC} 원장 ${GATE_CARRY_LINE} 번째 줄의 이월 중단 답(선택지 $(gate_row_field "$GATE_CARRY_ROW" '선택지'))을 이 런으로 들여오고 이 파견을 거절합니다 — 그 뒤 --carry-answer 로 그 답을 내세요"
    return "$GATE_EXIT_RULE"
  fi
  mkdir -p "$RUN_DIR/halt"
  dst="$RUN_DIR/halt/$key#chained-$GATE_CARRY_SRC.md"
  if ! gate_carry_copy "$GATE_CARRY_REC" "$dst" "$(gate_row_field "$GATE_CARRY_ROW" '기록 다이제스트')"; then
    warn "${key} 의 이어받은 런 중단 기록을 이 런으로 복사하지 못했습니다 — 답을 들여오지 않습니다: $GATE_CARRY_REC"
    return 0
  fi
  if [ -n "$GATE_CARRY_ATT" ]; then
    adst="${dst%.md}.answer.md"
    adig=$(gate_row_field "$GATE_CARRY_ROW" '첨부 다이제스트')
    if ! gate_carry_copy "$GATE_CARRY_ATT" "$adst" "$adig"; then
      warn "${key} 의 이어받은 런 첨부를 이 런으로 복사하지 못했습니다 — 답을 들여오지 않습니다: $GATE_CARRY_ATT"
      return 0
    fi
  fi
  if ! gate_carry_import_row "$key" "$dst" "$adst" "$adig" '연쇄 이월' "$rk"; then
    warn "${key} 의 연쇄 이월 중단 답 행이 행 상한에 들지 않습니다 — 답을 들여오지 않습니다"
    return 0
  fi
  ln=$( { grep -n "^- \`중단 답\` " "$LEDGER" 2>/dev/null || true; } \
        | { grep -F "| 중단 기록=$dst |" || true; } | tail -1 | cut -d: -f1)
  log "중단 답 이월 — $key ← 이어받은 런 $GATE_CARRY_SRC ($(gate_row_field "$GATE_CARRY_ROW" '선택지'))"
  warn "${key} 에 이어받은 런 ${GATE_CARRY_SRC} 의 이월 중단 답을 원장 ${ln:-?} 번째 줄로 들여왔습니다 — 이 파견은 띄우지 않습니다. 그 답은 --carry-answer ${ln:-?} 로 내세요"
  return "$GATE_EXIT_RULE"
}

gate_json_id_array() {
  # gate_json_id_array <id>... — a JSON array of strings; none gives `[]`.
  local t first=1
  printf '['
  for t in "$@"; do
    [ "$first" = "1" ] || printf ', '
    first=0
    printf '"%s"' "$(gate_json_escape "$t")"
  done
  printf ']'
}

gate_snapshot_slicing_json() {
  # The segment plan the frozen document declares, for the shift that has to
  # write it: the branch, and per segment its id, branch name and worktree path
  # in declaration order. Read-only — the snapshot is a read verb, so the values
  # are written by `act --kind segment --from-declaration`, never from here.
  local br="" ids="" id="" al="" wt="" bn="" ad="" adx="" first=1 defects="" dpre="" dmo=""
  br=$(gate_slicing_branch)
  case "$br" in
    미통치) ids=$(gate_plan_implement_step) ;;
    *)      ids=$(slice_ids "$DOC" 2>/dev/null || true) ;;
  esac
  printf '{"분기": "%s", "세그먼트": [' "$(gate_json_escape "$br")"
  for id in $ids; do
    if [ "$br" = "미통치" ]; then al=$(home_alias 2>/dev/null || true); else al=$(gate_slice_alias "$id") || al=""; fi
    wt=""; bn="seg/$RUN_ID-$id"; adx=""
    [ -z "$al" ] || wt=$(gate_decl_worktree "$al" "$id") || wt=""
    # AN ADOPTED SEGMENT NAMES THE EARLIER RUN'S BRANCH AND WORKTREE, and says
    # so: `입양` carries the run it came from and `PR` the pull request the
    # segment already has, so the router neither cuts a branch nor opens a PR.
    if ad=$(gate_adoption_row "$id"); then
      bn=$(manifest_row_fields "$ad" '브랜치')
      wt=$(manifest_row_fields "$ad" '워크트리')
      adx=$(printf ', "입양": "%s", "PR": "%s"' \
        "$(gate_json_escape "$(manifest_row_fields "$ad" '출처 런')")" \
        "$(gate_json_escape "$(manifest_row_fields "$ad" 'PR')")")
    fi
    # THE TWO PREDECESSOR LISTS, as normalized ids. The router dispatches a
    # `머지 순서` predecessor beside this slice and holds only its merge, so it
    # has to see the two kinds apart; the planner path declares neither.
    dpre=""; dmo=""
    if [ "$br" != "미통치" ]; then
      dpre=$(gate_dep_tokens "$(slice_field "$DOC" "$id" '선행' 2>/dev/null || true)")
      dmo=$(gate_dep_tokens "$(slice_field "$DOC" "$id" '머지 순서' 2>/dev/null || true)")
    fi
    [ "$first" = "1" ] || printf ', '
    first=0
    printf '{"id": "%s", "대상": "%s", "브랜치": "%s", "워크트리": "%s", "선행": %s, "머지 순서": %s%s}' \
      "$(gate_json_escape "$id")" "$(gate_json_escape "$al")" \
      "$(gate_json_escape "$bn")" "$(gate_json_escape "$wt")" \
      "$(gate_json_id_array $dpre)" "$(gate_json_id_array $dmo)" "$adx"
  done
  printf ']'
  if [ "$br" = "선언불완전" ]; then
    defects=$(gate_slicing_defects)
    printf ', "결함": ['
    first=1
    while IFS= read -r id; do
      [ -n "$id" ] || continue
      [ "$first" = "1" ] || printf ', '
      first=0
      printf '"%s"' "$(gate_json_escape "$id")"
    done <<EOF
$defects
EOF
    printf ']'
  fi
  printf '}'
}

gate_doc_arg_path() {
  # The path the driver's `doc_arg` hands every document consumer, computed
  # without writing: the design document when the run has one, the anchor brief
  # under the run directory when it does not.
  if [ -n "${DOC:-}" ]; then printf '%s' "$DOC"; else printf '%s' "$RUN_DIR/anchor-brief.md"; fi
}

gate_dispatch_doc_arg() {
  # gate_dispatch_doc_arg <stage kind> — make the anchor brief a run without a
  # design document hands its implement, review and reconverge stages, the way
  # the driver's `doc_arg` does on first use. The driver's own writer, so the
  # two produce the same bytes.
  case "${1:-}" in implement|review|lead-fix|reconverge) : ;; *) return 0 ;; esac
  [ -z "${DOC:-}" ] || return 0
  doc_arg >/dev/null
}

gate_skill_prompt_of() {
  # gate_skill_prompt_of <stage kind> <cli args...> — the value after `-p`, or
  # nothing when the dispatch carries no prompt.
  shift
  while [ "$#" -gt 0 ]; do
    if [ "$1" = "-p" ] && [ "$#" -ge 2 ]; then printf '%s' "$2"; return 0; fi
    shift
  done
}

gate_prompt_doc_arg() {
  # gate_prompt_doc_arg <stage kind> <prompt> — the document argument the stage
  # skill will read out of its prompt, by each skill's own rule: the first `.md`
  # token for implement and reconverge, the path after `설계는 ` for review and
  # for the lead fix, which runs the review skill with that prompt. The
  # report path behind `--report-path` is never a document argument. Empty when
  # the prompt names none.
  #
  # NOR IS A HALT RECORD OF THIS RUN. The router hands a halt answer on with a
  # fixed sentence that names the record — a `.md` path under the run's `halt/`
  # — and, on a resume, names no document at all, so read by the first-`.md`
  # rule that record was the argument and every halt answer to a re-convergence
  # was refused as naming another document. The record is skipped by the same
  # prefix the halt-answer row is held to; any other `.md` is still compared.
  local sk="$1" prompt="$2"
  case "$sk" in
    review|lead-fix)
      case "$prompt" in *'설계는 '*) : ;; *) return 0 ;; esac
      printf '%s' "${prompt#*설계는 }" | sed -E 's/".*$//; s/[[:space:]]+$//'
      ;;
    implement|reconverge)
      # Split on whitespace by `tr`, not by an unquoted expansion, so a glob
      # character in the prompt is never expanded against the working directory.
      printf '%s' "$prompt" | tr -s ' \t' '\n\n' | tr -d "\"'" \
        | awk -v halt="${RUN_DIR:-/nonexistent}/halt/" \
            'prev != "--report-path" && /\.md$/ && index($0, halt) != 1 { print; exit } { prev = $0 }'
      ;;
  esac
}

gate_prompt_report_path() {
  # gate_prompt_report_path <prompt> — the word after the first `--report-path`
  # in a dispatch prompt, split the way `gate_prompt_doc_arg` splits it; empty
  # when the prompt carries none. A review dispatch row records it so a
  # recovery can be held to the same path, and the review stream does not
  # carry it.
  printf '%s' "$1" | tr -s ' \t' '\n\n' | tr -d "\"'" \
    | awk 'prev == "--report-path" { print; exit } { prev = $0 }'
}

gate_segment_cycle_cap() {
  # gate_segment_cycle_cap <segment> — the re-implementation cycle cap, the
  # driver's REIMPL_CYCLE_CAP sourced from run.sh. The segment's declared file
  # count does not enter it; the argument is kept for the callers.
  printf '%s' "$REIMPL_CYCLE_CAP"
}

gate_segment_cycle_count() {
  # gate_segment_cycle_count <segment> — the `cycle` rows the segment has. Crash
  # retries and resumes write none, so they spend nothing. A resolution cycle
  # (`모드=해소`) is not counted: the base resolution has a cap of its own, and
  # one budget for both would let a fix cycle and a resolution spend each
  # other's.
  gate_rows 'cycle' | gate_rows_field_eq '세그먼트' "$1" | gate_rows_field_ne '모드' '해소' | gate_count
}

gate_segment_review_ordinal() {
  # gate_segment_review_ordinal <segment> — the number the segment's next review
  # report takes: every `cycle` row of the segment, resolution rows included,
  # plus one. NOT the cap count above, which skips `모드=해소`: two resolution
  # reviews in a row then took the same number, and the second report wrote
  # over the first. Nor the row's `사이클`, which the driver can lower and the
  # router chooses. The cap count stays what the caps read.
  local n
  n=$(gate_rows 'cycle' | gate_rows_field_eq '세그먼트' "$1" | gate_count)
  printf '%s' "$(( ${n:-0} + 1 ))"
}

gate_report_norm() {
  # gate_report_norm <absolute path> — the spelling two report paths are
  # compared in: the nearest existing directory resolved physically, so `//`, a
  # `/var` against `/private/var` symlink and a `..` do not make one file two,
  # with the components below it kept as written and repeated slashes squeezed.
  # The nearest EXISTING one, not the report's own directory: before a
  # segment's first review `docs/reviews` is often not there yet, and the
  # canonical path and the one the router spelled would otherwise be compared
  # letter for letter across the symlink. The base name is kept as written.
  local d b rest=""
  d=$(dirname "$1"); b=$(basename "$1")
  while [ ! -d "$d" ] && [ "$d" != "/" ] && [ "$d" != "." ]; do
    rest="/$(basename "$d")$rest"; d=$(dirname "$d")
  done
  if [ -d "$d" ] && d=$(cd "$d" 2>/dev/null && pwd -P); then
    printf '%s%s/%s' "${d%/}" "$rest" "$b" | tr -s '/'
  else
    printf '%s' "$1" | tr -s '/'
  fi
}

gate_review_report_path() {
  # gate_review_report_path <segment> [<k>] — THE canonical report path of the
  # segment's next review, absolute: `docs/reviews/seg-<run>-<segment>-cycle<n>.md`
  # under the run's base, with `-r<k>` before `.md` for the driver's k-th
  # dispatch of the same review (k ≥ 2). One function for the review line, the
  # review dispatch check, the driver and the `cycle` row check, so the four
  # cannot name one review two ways.
  local seg=$1 k=${2:-} n
  n=$(gate_segment_review_ordinal "$seg")
  gate_report_abs "docs/reviews/seg-$RUN_ID-$seg-cycle$n${k:+-r$k}.md"
}

gate_decl_block() {
  # gate_decl_block <verb> <사유> — the run-scope block a structural planning
  # refusal leaves. The router may resolve a run-scope block and may not create
  # one, so the act that judged the declaration unplannable is the one that
  # records it. A dry run records nothing, and the same reason is written once.
  #
  # This block is reached only for a defect no single slice owns (a checksum,
  # an unreadable declaration, a plan with no review step); a defect that one
  # slice owns parks that slice instead (`gate_decl_slice_park`). It carries
  # `재킥 원인=슬라이싱` either way, and it is a run-scope `blocked` row that
  # does not end the run, so it settles no end token and writes no marker.
  [ "$1" = "act" ] || return 0
  gate_has_row 'blocked' '스코프=run' '원인=무효화' "사유=$2" && return 0
  gate_append 'blocked' "대상=-" "스코프=run" "원인=무효화" "사유=$2" "관측=$(now_iso)" \
    "재개 명령=설계 문서의 ## 구현 슬라이싱 을 고쳐 새 런으로 다시 킥오프 — 이 런의 동결 문서는 바뀌지 않습니다" \
    "재킥 원인=슬라이싱"
}

gate_decl_defect_slices() {
  # gate_decl_defect_slices — the slice ids an incomplete declaration's defects
  # belong to, space-separated, or nothing when any defect belongs to no single
  # slice. Read off `gate_slicing_defects`, whose per-slice lines name their
  # slice and come alone: when it prints them it prints nothing else.
  local line ids="" id
  while IFS= read -r line; do
    [ -n "$line" ] || continue
    case "$line" in
      "슬라이스 "*": 필수 필드 「"*"」 없음"|"슬라이스 "*": 머지 순서 "*|"슬라이스 "*": 라벨 인정 "*)
        id=${line#슬라이스 }; id=${id%%:*}
        case " $ids " in *" $id "*) : ;; *) ids="$ids $id" ;; esac ;;
      *) return 0 ;;
    esac
  done <<EOF
$(gate_slicing_defects)
EOF
  printf '%s' "${ids# }"
}

gate_slice_reaches_any() {
  # gate_slice_reaches_any <slice id> <id>... — true when the slice is one of
  # the ids or depends on one through `선행 ∪ 머지 순서`, transitively. A
  # dependent of a parked slice cannot land on it, and a merge-order successor
  # cannot merge after it, so either parks with it.
  local todo="$1" ids d want seen=""
  shift
  ids=" $* "
  while [ -n "$todo" ]; do
    d=${todo%% *}
    case "$todo" in *" "*) todo=${todo#* } ;; *) todo="" ;; esac
    case " $seen " in *" $d "*) continue ;; esac
    seen="$seen $d"
    case "$ids" in *" $d "*) return 0 ;; esac
    for want in $(slice_chain_tokens "$DOC" "$d" 2>/dev/null || true); do
      todo="${todo:+$todo }$want"
    done
  done
  return 1
}

gate_decl_slice_park() {
  # gate_decl_slice_park <verb> <alias> <segment> <사유> — a declaration defect
  # that ONE slice owns parks that slice and what depends on it, and nothing
  # else: the row names the slice, it is act-scope rather than run-scope, and
  # an independent slice is still planned and dispatched. A dry run records
  # nothing, and the same reason for the same slice is written once.
  [ "$1" = "act" ] || return 0
  gate_has_row 'blocked' "세그먼트=$3" '재킥 원인=슬라이싱' "사유=$4" && return 0
  gate_append 'blocked' "대상=$2" "세그먼트=$3" "스코프=act" "원인=막힘" "사유=$4" \
    "관측=$(now_iso)" \
    "재개 명령=설계 문서의 ## 구현 슬라이싱 에서 이 슬라이스를 고쳐 새 런으로 다시 킥오프 — 독립 슬라이스는 이 런에서 계속 갑니다" \
    "재킥 원인=슬라이싱"
}

gate_decl_norm() {
  # gate_decl_norm <value> — `decl_norm`, the one normalization `slice_decl_digest`
  # hashes, so a field compared here and the digest agree on what is equal.
  decl_norm "$1"
}

gate_prior_decl_whole() {
  # gate_prior_decl_whole <path> — the whole value a planned row clipped and kept
  # beside its run, printed; 1 when there is no such file to read.
  #
  # THE PATH COMES FROM ANOTHER RUN'S ROW, so it is held to the shape the two
  # writers give it — absolute, no `..`, a regular file of bounded size — before
  # anything is read. Reading it decides nothing on its own: a value that is not
  # the declaration simply fails to compare equal.
  local p="$1" n
  case "$p" in /*) : ;; *) return 1 ;; esac
  case "/$p/" in */../*) return 1 ;; esac
  [ -f "$p" ] && [ -r "$p" ] || return 1
  n=$(wc -c < "$p" 2>/dev/null | tr -d ' ')
  [ -n "$n" ] && [ "$n" -le 65536 ] || return 1
  cat "$p" 2>/dev/null || return 1
}

gate_segment_declared_whole() {
  # gate_segment_declared_whole <segment> [<before line>] — the declared set of the segment as
  # the last of its rows carrying `선언 파일 집합` states it, read back whole
  # when the row writer clipped it and normalized by `gate_decl_norm`; empty
  # when no row carries one. 1 when the value was clipped and the file it names
  # cannot be read back: a reader that needs the whole set cannot judge then.
  #
  # The last value any row carried, because a later state row does not repeat
  # it. The review line and the enforcement-surface readers share this so the
  # two cannot disagree about which set a segment declared.
  #
  # With <before line>, only the rows above that ledger line are read: the set
  # as it stood when that line was written, which is what a seat-apply
  # inheritance re-derives the person's approved scope from.
  local rows decl side
  if [ -n "${2:-}" ]; then
    rows=$(LC_ALL=C awk -v l="$2" 'NR < l && index($0, "- `segment` ") == 1' "$LEDGER" 2>/dev/null \
           | gate_rows_field_eq 'id' "$1")
  else
    rows=$(gate_rows 'segment' | gate_rows_field_eq 'id' "$1")
  fi
  decl=$(printf '%s\n' "$rows" | gate_rows_field_values '선언 파일 집합' | awk 'NF { v = $0 } END { print v }')
  case "$decl" in
    *"(전체: "*")")
      side=${decl##*"(전체: "}; side=${side%)}
      decl=$(gate_prior_decl_whole "$side") || return 1 ;;
  esac
  gate_decl_norm "$decl"
}

gate_surface_stamp() {
  # gate_surface_stamp [<path>…] — the `강제 표면` value for these declared
  # paths: `<n>건 <분류목록>`, `없음`, or `판정불가` when the classifier could
  # not be loaded. Never fails: an unloadable classifier is a value, not a
  # refusal of the row.
  local v
  if v=$(gate_es es_stamp "$@") && [ -n "$v" ]; then
    printf '%s' "$v"
  else
    printf '%s' '판정불가'
  fi
}

gate_prior_decl_diff() {
  # gate_prior_decl_diff <segment> <ledger> <terminal-row> — empty when that
  # earlier ledger planned <segment> under the declaration the frozen document
  # carries now; otherwise one phrase naming what differs, or that there is no
  # plan row to compare. See `gate_prior_run_landed` for why.
  local seg="$1" f="$2" row="$3" pr="" org of rr k dk pv cv pd side
  # THE TERMINAL ROW NAMES THE DECLARATION THE SLICE LANDED UNDER, when it
  # carries a digest. The segment arm stamps one on every landing it writes,
  # and a reconvergence inside that run widens the declaration after the plan
  # row — so the plan row names a narrower slice than the one reviewed and
  # merged, and comparing it would refuse a landing that holds. A digest on the
  # terminal row decides alone; when it differs and the slice landed as it was
  # planned, the plan row below still names the field that differs.
  pr=$( { grep -E '^- `segment` ' "$f" 2>/dev/null || true; } | { grep -F "| id=$seg |" || true; } \
        | { grep -F '| 상태=계획됨 |' || true; } | tail -1)
  pd=$(gate_row_field "$row" '선언 다이제스트')
  case "$pd" in *[!0-9a-f]*) pd="" ;; esac
  [ "${#pd}" -eq 64 ] || pd=""
  if [ -n "$pd" ]; then
    [ "$pd" != "$(slice_decl_digest "$DOC" "$seg")" ] || return 0
    if [ -z "$pr" ] || [ "$(gate_row_field "$pr" '선언 다이제스트')" != "$pd" ]; then
      if [ "$(gate_row_field "$row" '출처')" = "매니페스트" ]; then
        printf '%s' "슬라이스 선언 불일치(선언 다이제스트) — 그 런이 매니페스트의 선행 착지 행으로 들인 ${seg} 의 선언과 지금 문서의 선언 전체가 다릅니다"
      else
        printf '%s' "슬라이스 선언 불일치(선언 다이제스트) — 그 런이 ${seg} 를 착지시킬 때의 선언과 지금 문서의 선언 전체가 다릅니다"
      fi
      return 0
    fi
  fi
  # A LANDING THE MANIFEST BROUGHT IN WAS NEVER PLANNED BY ANY RUN. Its row is a
  # person's `선행 착지` claim that the gate checked against the base branch
  # when it wrote the row, and the caller checks that merge commit against the
  # base branch again, so `출처=매니페스트` names no ledger to follow and is its
  # own evidence. A row written before it kept a declaration digest rests on the
  # claim and the landing alone.
  if [ -z "$pr" ] && [ "$(gate_row_field "$row" '출처')" = "매니페스트" ]; then
    return 0
  fi
  if [ -z "$pr" ]; then
    org=$(gate_row_field "$row" '출처')
    of="$(dirname "$f")/$org.md"
    case "$org" in ''|*/*|*.*) of="" ;; esac
    if [ -n "$of" ] && [ -f "$of" ] && [ "$of" != "${LEDGER:-}" ] && [ "$of" != "$f" ]; then
      rr=$( { grep -E '^- `run` ' "$of" 2>/dev/null || true; } | sed -n 1p)
      if [ "$(gate_row_field "$rr" '설계 문서')" = "$DOC_KEY" ]; then
        pr=$( { grep -E '^- `segment` ' "$of" 2>/dev/null || true; } | { grep -F "| id=$seg |" || true; } \
              | { grep -F '| 상태=계획됨 |' || true; } | tail -1)
      fi
    fi
  fi
  if [ -z "$pr" ]; then
    printf '%s' "슬라이스 선언 증거 없음 — 그 런과 출처 런 어디에도 ${seg} 의 계획됨 행이 없습니다"
    return 0
  fi
  # THE DIGEST DECIDES WHEN THE ROW CARRIES ONE. It covers the whole of every
  # field, so a long `선언 파일` grown at its end — past the clip the row keeps —
  # still differs. Equal digests end it here; unequal ones fall through to the
  # field loop only to name the field.
  pd=$(gate_row_field "$pr" '선언 다이제스트')
  case "$pd" in *[!0-9a-f]*) pd="" ;; esac
  [ "${#pd}" -eq 64 ] || pd=""
  if [ -n "$pd" ] && [ "$pd" = "$(slice_decl_digest "$DOC" "$seg")" ]; then
    return 0
  fi
  for k in '선언 파일 집합' '레포' '선행' '절단점' '리뷰 정책'; do
    dk=$k
    [ "$k" = '선언 파일 집합' ] && dk='선언 파일'
    pv=$(gate_row_field "$pr" "$k")
    cv=$(slice_field "$DOC" "$seg" "$dk" 2>/dev/null || true)
    # A VALUE TOO LONG FOR ONE ROW holds a clip and names the file its whole was
    # kept in (`<clip> (전체: <path>)`, or `(전체: <path>)` alone when the whole
    # row spilled). The clip is not the declaration — two lists that differ only
    # past it clip to the same bytes — so the whole is read back and compared,
    # and a row whose whole cannot be read is no evidence at all.
    case "$pv" in
      *"(전체: "*")")
        side=${pv##*"(전체: "}; side=${side%)}
        if ! pv=$(gate_prior_decl_whole "$side"); then
          printf '%s' "슬라이스 선언 증거 없음 — 그 런의 계획 행이 ${k} 를 잘라 적었고 전체를 둔 파일 ${side} 를 읽을 수 없습니다"
          return 0
        fi ;;
    esac
    if [ "$(gate_decl_norm "$pv")" != "$(gate_decl_norm "$cv")" ]; then
      printf '%s' "슬라이스 선언 불일치(${k}) — 그 런의 계획 「$(gate_row_safe "$(gate_decl_norm "$pv")" 120)」, 지금 문서 「$(gate_row_safe "$(gate_decl_norm "$cv")" 120)」"
      return 0
    fi
  done
  # `머지 순서` on the condition the digest uses: `없음` and an absent field are
  # one value, so a new document reading `없음` matches an old one without the
  # line, and only a declared merge-order predecessor can differ.
  pv=$(gate_row_field "$pr" '머지 순서')
  cv=$(slice_field "$DOC" "$seg" '머지 순서' 2>/dev/null || true)
  [ -n "$(gate_dep_tokens "$pv")" ] || pv=""
  [ -n "$(gate_dep_tokens "$cv")" ] || cv=""
  if [ "$(gate_decl_norm "$pv")" != "$(gate_decl_norm "$cv")" ]; then
    printf '%s' "슬라이스 선언 불일치(머지 순서) — 그 런의 계획 「$(gate_row_safe "$(gate_decl_norm "$pv")" 120)」, 지금 문서 「$(gate_row_safe "$(gate_decl_norm "$cv")" 120)」"
    return 0
  fi
  if [ -n "$pd" ]; then
    printf '%s' "슬라이스 선언 불일치(선언 다이제스트) — 그 런의 계획과 지금 문서의 선언 전체가 다릅니다"
  fi
  return 0
}

GATE_PRIOR_RUN=""
GATE_PRIOR_ROW=""
GATE_PRIOR_KIND=""
GATE_PRIOR_DECL_MOVED=""
GATE_PRIOR_OUTSIDE=""
GATE_PRIOR_PR=""
GATE_PRIOR_BRANCH=""
gate_prior_run_landed() {
  # gate_prior_run_landed <segment> — 0 when an EARLIER RUN OF THIS DOCUMENT
  # ended <segment> landed, with that run's id in GATE_PRIOR_RUN and the
  # `segment` row that records the landing in GATE_PRIOR_ROW; 1 when none did.
  #
  # A SLICE CAN BE DELIVERED BY ONE RUN AND DEPENDED ON BY THE NEXT. One frozen
  # document is often implemented a slice per run, and every run has a ledger of
  # its own, so the run planning S2 has never seen the S1 the previous run
  # merged. The segment arm's floor then refused `선행=S1` as a segment nobody
  # knows, and the only way past it was a person hand-writing the S1 row — a row
  # that carries the gate's frame and none of its checks.
  #
  # THE EVIDENCE IS ANOTHER LEDGER IN THE SAME DIRECTORY, and the document is
  # matched by the `설계 문서` of its `run` row rather than by a header. Ledgers
  # the gate opens begin with the report title and carry no header comment, so
  # the `run` row is the one place every ledger states which document it ran.
  # A file whose name holds a second dot is a companion of a run — `.plan`,
  # `.kickoff`, a segment's trace — and is not read.
  #
  # ONLY A LANDED ENDING QUALIFIES: `머지됨` or `완료`, carrying a `머지 커밋`
  # shaped as a hex object name (`gate_prior_row_landed`). The merge commit is
  # the claim the caller then checks against the base branch; a row without one
  # says the run ended the segment and not where it went. The row is found by
  # `gate_landing_walk` over that ledger's rows for the id: the last row, or —
  # when the last row is a `park` — the first row before it that is neither
  # `park` nor `적용 준비`, because a segment merged and then parked is on the
  # base all the same.
  #
  # A LEDGER THAT NEVER RECORDED A LANDING may still have landed: a person can
  # merge the pull request after the run is over, and no row is written for
  # that. Such a ledger — its last row for the id a `park`, or a non-terminal
  # row a shift halt left in place — is an outside-merge candidate when one of
  # its rows for the id carries a numeric `PR` — the last `segment` row that
  # does, else the last `원격 판독` row of `세그먼트=<id>` — and it is chosen
  # only when no ledger has a landing row. It comes back with
  # GATE_PRIOR_OUTSIDE=1, GATE_PRIOR_KIND=PR, that number in GATE_PRIOR_PR, the
  # id's last `브랜치` in GATE_PRIOR_BRANCH and that last row in
  # GATE_PRIOR_ROW; the caller brings it in only as a merged request.
  #
  # A SLICE WHOSE DECLARED CUTPOINT IS PR LANDS AS A PULL REQUEST, and its
  # terminal row is `완료` with a numeric `PR` and a hex `커밋` — the head the
  # run left the request at — and no merge commit at all. That row qualifies
  # only for a slice the frozen document declares with `절단점: PR`: the value
  # on the row is the run's account, the declaration is what the slice was
  # supposed to deliver, and a merge-cutpoint slice that stopped at an open PR
  # has not delivered. Which arm qualified is left in GATE_PRIOR_KIND (`머지` or
  # `PR`); the PR arm is still only a claim, which the caller checks against the
  # live pull request.
  #
  # THE MOST RECENTLY OPENED RUN WINS, by the `시작` of its `run` row. File mtime
  # moves on every append, so a late row in an older run would make it look
  # newer than the run that merged the segment again after it; `시작` is fixed
  # when the run opens and is `now_iso`'s UTC shape, which sorts as text.
  #
  # THE SAME PATH IS NOT THE SAME SLICE. A run that ends with its binding
  # surface moved parks the rest for the next run, and that next run is a
  # kickoff of the REVISED document at the same path — so matching the path
  # alone brought in a landing made under a narrower `선언 파일` or a weaker
  # `리뷰 정책`, the slice was not dispatched, and the scope the revision added
  # was never built. A candidate therefore also has to show the slice was
  # built to the declaration the frozen document carries now. A terminal row
  # carrying a `선언 다이제스트` says so by itself — the segment arm stamps the
  # declaration the slice landed under, which a reconvergence inside that run
  # may have widened past its plan row. Without one, it is the last
  # `계획됨` row for the id in that ledger, compared on `선언 파일 집합`,
  # `레포`, `선행`, `절단점` and `리뷰 정책` — by the row's `선언 다이제스트`
  # of the whole declaration when it carries one, and otherwise field by field,
  # a clipped field by the whole its row names and never by the clip. A ledger that
  # brought the slice in rather than planning it holds no such row, so its
  # terminal row's `출처` is followed to that run's ledger once — the run that
  # did the work is the one whose plan counts — and a chain that leaves no plan
  # row anywhere is no evidence. A row whose `출처` is `매니페스트` is the one
  # exception: no run planned that slice, so the row's own `선언 다이제스트`,
  # when it carries one, is compared instead, and the merge commit is checked
  # against the base branch as for any landing. Either way the ledger drops out of the
  # candidates with one warning naming the field that differs. The whole-
  # document digest is deliberately not compared: any edit anywhere would make
  # every slice be done again.
  local seg="$1" dir f rrow rows row ln p br rid cand="" ocand="" best tab dd c out
  tab=$(printf '\t')
  GATE_PRIOR_RUN=""; GATE_PRIOR_ROW=""; GATE_PRIOR_KIND=""; GATE_PRIOR_DECL_MOVED=""
  GATE_PRIOR_OUTSIDE=""; GATE_PRIOR_PR=""; GATE_PRIOR_BRANCH=""
  [ -n "${LEDGER:-}" ] && [ -n "${DOC_KEY:-}" ] && [ -n "${DOC:-}" ] || return 1
  GATE_WALK_PRCUT=""
  c=$(slice_field "$DOC" "$seg" '절단점' 2>/dev/null | tr -d '`' | sed 's/^[[:space:]]*//; s/[[:space:]]*$//')
  [ "$(cutpoint_token "$c" 2>/dev/null || true)" = "PR" ] && GATE_WALK_PRCUT=1
  dir=$(dirname "$LEDGER")
  for f in "$dir"/*.md; do
    [ -f "$f" ] || continue
    [ "$f" != "$LEDGER" ] || continue
    case "$(basename "$f" .md)" in *.*) continue ;; esac
    rrow=$( { grep -E '^- `run` ' "$f" 2>/dev/null || true; } | sed -n 1p)
    [ -n "$rrow" ] || continue
    [ "$(gate_row_field "$rrow" '설계 문서')" = "$DOC_KEY" ] || continue
    # `<line>:` prefixed, so the landing the walk picks names its own line; the
    # prefix sits in the row's first field, which no field reader reads.
    rows=$( { grep -nE '^- `segment` ' "$f" 2>/dev/null || true; } | { grep -F "| id=$seg |" || true; })
    [ -n "$rows" ] || continue
    out=""
    rid=$(gate_row_field "$rrow" 'run-id')
    [ -n "$rid" ] || rid=$(basename "$f" .md)
    if gate_landing_walk gate_prior_row_landed <<ROWS
$rows
ROWS
    then
      ln=${GATE_WALK_ROW%%:*}
      row=${GATE_WALK_ROW#*:}
    else
      # A RUN THAT LEFT THE SLICE UNLANDED AND A PERSON WHO MERGED IT AFTERWARDS
      # leave no landing row: the run was over before the merge, so nothing
      # wrote it. The pull request the ledger names is the only evidence, and it
      # is held back as a candidate of its own — a ledger with a landing row
      # beats every such one — for the import to check against the live request.
      # The last row need not be a `park`: a shift halt stops the segment with
      # rows of other kinds and leaves its last `segment` row where it was, at
      # `계획됨` or `실행중`. Only a terminal last row (`머지됨`, `완료`) that
      # carries no landing is passed over, since the run already said where the
      # segment ended.
      row=$(printf '%s\n' "$rows" | tail -1)
      row=${row#*:}
      case "$(gate_row_field "$row" '상태')" in 머지됨|완료) continue ;; esac
      # Only a ledger that never recorded a landing: a `머지됨` the walk passed
      # over because the slice was planned again after it is redone work, and
      # the request that merged the first round is not evidence for the second.
      gate_landing_rows_any gate_prior_row_landed <<ROWS && continue
$rows
ROWS
      p=$(printf '%s\n' "$rows" | awk -F' [|] ' '{ for (i = 2; i <= NF; i++) if ($i ~ /^PR=[0-9]+$/) { v = $i; sub(/^PR=/, "", v); r = v } } END { print r }')
      if [ -z "$p" ]; then
        p=$( { grep -E '^- `원격 판독` ' "$f" 2>/dev/null || true; } | gate_rows_field_eq '세그먼트' "$seg" \
             | awk -F' [|] ' '{ for (i = 2; i <= NF; i++) if ($i ~ /^PR=[0-9]+$/) { v = $i; sub(/^PR=/, "", v); r = v } } END { print r }')
      fi
      [ -n "$p" ] || continue
      br=$(printf '%s\n' "$rows" | awk -F' [|] ' '{ for (i = 2; i <= NF; i++) if (index($i, "브랜치=") == 1) { v = $i; sub(/^브랜치=/, "", v); r = v } } END { print r }')
      ln=$(printf '%s\n' "$rows" | tail -1)
      ln=${ln%%:*}
      out=1
    fi
    dd=$(gate_prior_decl_diff "$seg" "$f" "$row")
    if [ -n "$dd" ]; then
      warn "이전 런 ${rid} 의 슬라이스 ${seg} 착지는 들여오지 않습니다 — ${dd}"
      # Left for `gate_import_self_landed`: a landing dropped because its
      # declaration differs is a different fact from no landing at all, and
      # a `P0잔존` successor parks on the first rather than redoing merged work.
      case "$dd" in "슬라이스 선언 불일치"*) GATE_PRIOR_DECL_MOVED=1 ;; esac
      continue
    fi
    if [ -n "$out" ]; then
      ocand="$ocand$(gate_row_field "$rrow" '시작')$tab$p$tab$br$tab$ln$tab$rid$tab$f
"
    else
      cand="$cand$(gate_row_field "$rrow" '시작')$tab$ln$tab$rid$tab$f
"
    fi
  done
  if [ -n "$cand" ]; then
    best=$(printf '%s' "$cand" | LC_ALL=C sort | tail -1)
  elif [ -n "$ocand" ]; then
    best=$(printf '%s' "$ocand" | LC_ALL=C sort | tail -1)
    GATE_PRIOR_OUTSIDE=1
  else
    return 1
  fi
  f=${best##*"$tab"}; best=${best%"$tab"*}
  GATE_PRIOR_RUN=${best##*"$tab"}; best=${best%"$tab"*}
  ln=${best##*"$tab"}; best=${best%"$tab"*}
  GATE_PRIOR_ROW=$(sed -n "${ln}p" "$f" 2>/dev/null)
  [ -n "$GATE_PRIOR_ROW" ] || { GATE_PRIOR_RUN=""; GATE_PRIOR_OUTSIDE=""; return 1; }
  if [ -n "$GATE_PRIOR_OUTSIDE" ]; then
    GATE_PRIOR_BRANCH=${best##*"$tab"}; best=${best%"$tab"*}
    GATE_PRIOR_PR=${best##*"$tab"}
    GATE_PRIOR_KIND="PR"
    return 0
  fi
  case "$(gate_row_field "$GATE_PRIOR_ROW" '머지 커밋')" in
    ''|*[!0-9a-f]*) GATE_PRIOR_KIND="PR" ;;
    *) GATE_PRIOR_KIND="머지" ;;
  esac
  return 0
}

GATE_DECL_SELF_IMPORTED=""
GATE_IMPORT_PR_STATE=""
gate_import_prior_landed() {
  # gate_import_prior_landed <verb> <segment> [self] — bring in the terminal row
  # an earlier run of this document left for <segment>: 0 when it was brought
  # in (on `plan`, when it would be), 1 when there is nothing to bring in, and
  # GATE_EXIT_RULE when a predecessor's landing is claimed and not borne out.
  #
  # TWO CALLERS, ONE WRITER. The planning act calls it for each predecessor this
  # ledger does not know and, with `self`, for the slice being planned; the
  # fixed-graph driver calls it through `run_gate_call` for every declared slice
  # before it writes the planned rows. Keeping the row in one function is what
  # keeps `출처=` to one writer — the segment arm refuses a caller's.
  #
  # THE DRIVER'S CHILD SHELL CARRIES NO DOCUMENT. `run_gate_call` rebinds the
  # manifest, the run and the ledger and nothing else, so `DOC_KEY` is empty
  # there and the ledger walk below would find nothing and report success. The
  # document is derived from the manifest here, and the ledger and grant the
  # caller handed in are kept over whatever the derivation computes.
  #
  # A PREDECESSOR'S CLAIM THAT DOES NOT HOLD REFUSES THE PLAN; THE SLICE'S OWN
  # DOES NOT. A dependent slice dispatched onto a predecessor that did not land
  # builds on nothing, so that is refused as before. A slice whose own earlier
  # landing does not hold is simply done again — skipping work that never
  # landed is the harm here, and redoing it is the remedy.
  #
  # A PULL REQUEST IS ACCEPTED ONLY AS IT STANDS NOW. The PR arm brings the row
  # in when the request is open with its head still the `커밋` the row names,
  # or merged. A merged request is not held to that head: a person finishing
  # it — a review fix pushed, the branch updated — moves the head before the
  # merge, and the merge is a person's act already. What ties a merged request
  # to this slice instead is one `gh pr view` answer carrying all three of: a
  # merge commit on the target's base branch, a head branch named exactly as
  # the row's `브랜치` and shaped as this slice's segment branch, and a base
  # branch that is the target's own. A request closed, moved while open,
  # unreadable, or merged without those three brings nothing in, and the slice
  # is done again. `출처` carries the run that did the work: the earlier row's
  # own `출처` when it had one, so a chain's third run still names the first,
  # and otherwise the earlier run; `브랜치` rides along so that third run can
  # hold the request to the branch again.
  #
  # NOT DOING A SLICE AGAIN IS NOT THE SAME AS BUILDING ON IT. Every segment
  # branches from the tip of its base, so the work of a request that is still
  # open is in no tree a dependent would be cut from. An open request therefore
  # brings in only the slice's own row — the work is not sent out a second time
  # — and never a predecessor's: a predecessor is brought in through a request
  # only once it is merged and its merge commit is on the base branch, and the
  # row then carries that `머지 커밋`. An open request's row carries none, which
  # is what keeps the dispatch floor from reading it as a landing; the state the
  # request was in is left in GATE_IMPORT_PR_STATE (`OPEN`, `MERGED`, or empty
  # for the merge arm) for a caller that has to tell the two apart.
  local verb="$1" seg="$2" mode="${3:-}" kl="${LEDGER:-}" kg="${GRANT:-}" kb="${BASE:-}"
  local dal="" pst="" pm="" ppr="" pc="" pwt="" pdp="" pbr="" org="" pdg="" slug="" obs="" ost="" ohd="" omc="" ohr="" obr="" abr="" what="" why="" noun=""
  GATE_DECL_SELF_IMPORTED=""
  GATE_IMPORT_PR_STATE=""
  if [ -z "${DOC_KEY:-}" ] && [ -n "${MANIFEST:-}" ]; then
    derive_paths_from_manifest >/dev/null 2>&1 || true
    [ -z "$kl" ] || LEDGER=$kl
    [ -z "$kg" ] || GRANT=$kg
    [ -z "$kb" ] || BASE=$kb
  fi
  [ -n "${DOC:-}" ] || return 1
  # A SLICE THIS LEDGER ALREADY BROUGHT IN STAYS BROUGHT IN. A second planning
  # act for it — the router asking again — finds its imported terminal row as
  # the last one and writes nothing; any other known slice plans as before.
  if [ "$mode" = "self" ]; then
    case " $(gate_segment_ids | tr '\n' ' ') " in
      *" $seg "*)
        case "$(gate_segment_field "$seg" '상태')" in 머지됨|완료) : ;; *) return 1 ;; esac
        [ -n "$(gate_segment_field "$seg" '출처')" ] || return 1
        case "$(gate_segment_field "$seg" '머지 커밋')" in
          ''|*[!0-9a-f]*) GATE_IMPORT_PR_STATE="OPEN" ;;
        esac
        GATE_DECL_SELF_IMPORTED=1
        return 0 ;;
    esac
  fi
  dal=$(gate_slice_alias "$seg" 2>/dev/null) || return 1
  gate_prior_run_landed "$seg" || return 1
  pst=$(gate_row_field "$GATE_PRIOR_ROW" '상태')
  pm=$(gate_row_field "$GATE_PRIOR_ROW" '머지 커밋')
  ppr=$(gate_row_field "$GATE_PRIOR_ROW" 'PR')
  pc=$(gate_row_field "$GATE_PRIOR_ROW" '커밋')
  pwt=$(gate_row_field "$GATE_PRIOR_ROW" '워크트리')
  pdp=$(gate_row_field "$GATE_PRIOR_ROW" '선행')
  pbr=$(gate_row_field "$GATE_PRIOR_ROW" '브랜치')
  org=$(gate_row_field "$GATE_PRIOR_ROW" '출처')
  [ -n "$org" ] || org=$GATE_PRIOR_RUN
  # The declaration digest a landing carries travels on the row it is brought
  # in as, and the next run in the chain compares that.
  pdg=$(gate_row_field "$GATE_PRIOR_ROW" '선언 다이제스트')
  case "$pdg" in *[!0-9a-f]*) pdg="" ;; esac
  [ "${#pdg}" -eq 64 ] || pdg=""
  # AN OUTSIDE MERGE IS AN UNLANDED LAST ROW AND A REQUEST NUMBER — a `park`, or
  # the `계획됨`/`실행중` row a shift halt left in place. The request and the
  # branch come from the walk, not from that row, which need carry neither;
  # only a merged request brings it in, and it comes in as `머지됨` with the
  # request's merge commit — the same row a run that merged it would have left.
  if [ "$GATE_PRIOR_OUTSIDE" = "1" ]; then
    ppr=$GATE_PRIOR_PR
    pbr=$GATE_PRIOR_BRANCH
    pc=""
  fi
  if [ "$GATE_PRIOR_KIND" = "머지" ]; then
    if [ "$pst" = "머지됨" ] && gate_segment_owes_apply "$dal" "$seg"; then
      if [ "$mode" = "self" ]; then
        warn "슬라이스 ${seg} 는 같은 문서의 이전 런 ${GATE_PRIOR_RUN} 이 머지했지만 적용이 남았습니다 — 들여오지 않고 다시 합니다"
        return 1
      fi
      warn "세그먼트 계획 거부: 선행 ${seg} 는 이 런의 원장에 없고, 같은 문서의 이전 런 ${GATE_PRIOR_RUN} 이 머지했지만 적용이 남았습니다 — 적용이 남은 머지는 들여오지 않습니다"
      return "$GATE_EXIT_RULE"
    fi
    gate_obligation_landing "$dal" "$pm"
    if [ "$GATE_LANDING_VERDICT" != "착지" ]; then
      if [ "$mode" = "self" ]; then
        warn "슬라이스 ${seg} 의 이전 런 ${GATE_PRIOR_RUN} 머지 커밋 ${pm} 은 대상 ${dal} 의 베이스 브랜치에 ${GATE_LANDING_VERDICT:-판정 불가} 입니다 — 들여오지 않고 다시 합니다: ${GATE_LANDING_WHY}"
        return 1
      fi
      warn "세그먼트 계획 거부: 선행 ${seg} 는 이 런의 원장에 없고, 같은 문서의 이전 런 ${GATE_PRIOR_RUN} 이 남긴 머지 커밋 ${pm} 은 대상 ${dal} 의 베이스 브랜치에 ${GATE_LANDING_VERDICT:-판정 불가} 입니다 — ${GATE_LANDING_WHY}"
      return "$GATE_EXIT_RULE"
    fi
    what="머지 커밋=${pm}"
  else
    slug=$(alias_slug "$dal" 2>/dev/null) || slug=""
    if [ -z "$slug" ]; then
      why="대상 ${dal} 의 원격 슬러그를 알 수 없습니다"
    elif ! obs=$(gh_q "$slug" pr view "$ppr" --json state,headRefOid,mergeCommit,headRefName,baseRefName --jq '.state + " " + .headRefOid + " " + (.mergeCommit.oid // "-") + " " + (.headRefName // "-") + " " + (.baseRefName // "-")' 2>/dev/null); then
      why="PR #${ppr} 을 원격 ${slug} 에서 읽지 못했습니다"
    else
      # Five words, `-` standing for an absent one: a field left empty would
      # collapse under `read` and shift every name after it one place left.
      read -r ost ohd omc ohr obr <<EOF
$obs
EOF
      [ "$omc" != "-" ] || omc=""
      [ "$ohr" != "-" ] || ohr=""
      [ "$obr" != "-" ] || obr=""
      case "$ost" in
        OPEN)
          if [ "$GATE_PRIOR_OUTSIDE" = "1" ]; then
            why="PR #${ppr} 이 그 런의 ${pst} 뒤에도 열려 있습니다 — 머지되지 않은 작업은 들이지 않습니다"
          else
            [ "$ohd" = "$pc" ] || why="PR #${ppr} 의 head ${ohd:-(없음)} 가 행의 커밋 ${pc} 와 다릅니다"
          fi ;;
        MERGED) : ;;
        *) why="PR #${ppr} 의 상태가 ${ost:-(없음)} 입니다 — 열려 있거나 머지된 PR 만 들여옵니다" ;;
      esac
      if [ -z "$why" ] && [ "$ost" = "OPEN" ] && [ "$mode" != "self" ]; then
        why="PR #${ppr} 이 아직 열려 있습니다 — 머지되지 않은 PR 의 작업은 이 슬라이스가 가지를 칠 베이스에 없으므로 선행으로 들이지 않습니다"
      fi
      if [ -z "$why" ] && [ "$ost" = "MERGED" ]; then
        case "$omc" in
          ''|*[!0-9a-f]*) why="머지된 PR #${ppr} 의 머지 커밋을 읽지 못했습니다" ;;
        esac
        if [ -z "$why" ]; then
          case "$pbr" in
            ''|*[!A-Za-z0-9._/-]*) why="머지된 PR #${ppr} 를 슬라이스에 묶을 행의 브랜치 ${pbr:-(없음)} 가 없거나 브랜치 이름이 아닙니다" ;;
            seg/*-"$seg") : ;;
            *) why="머지된 PR #${ppr} 를 슬라이스에 묶을 행의 브랜치 ${pbr} 가 슬라이스 ${seg} 의 세그먼트 브랜치 꼴(seg/<슬러그>-${seg})이 아닙니다" ;;
          esac
        fi
        if [ -z "$why" ] && [ "$ohr" != "$pbr" ]; then
          why="머지된 PR #${ppr} 의 head 브랜치 ${ohr:-(없음)} 가 행의 브랜치 ${pbr} 와 다릅니다"
        fi
        if [ -z "$why" ]; then
          abr=$(base_branch "$dal" 2>/dev/null) || abr=""
          if [ -z "$abr" ]; then
            why="머지된 PR #${ppr} 의 base 브랜치를 대조할 대상 ${dal} 의 베이스 브랜치를 해소하지 못했습니다"
          elif [ "$obr" != "$abr" ]; then
            why="머지된 PR #${ppr} 의 base 브랜치 ${obr:-(없음)} 가 대상 ${dal} 의 베이스 브랜치 ${abr} 와 다릅니다"
          fi
        fi
        if [ -z "$why" ]; then
          gate_obligation_landing "$dal" "$omc"
          [ "$GATE_LANDING_VERDICT" = "착지" ] \
            || why="머지된 PR #${ppr} 의 머지 커밋 ${omc} 은 대상 ${dal} 의 베이스 브랜치에 ${GATE_LANDING_VERDICT:-판정 불가} 입니다: ${GATE_LANDING_WHY}"
        fi
      fi
    fi
    if [ -n "$why" ]; then
      if [ "$GATE_PRIOR_OUTSIDE" = "1" ]; then
        warn "슬라이스 ${seg} 는 이전 런 ${GATE_PRIOR_RUN} 이 ${pst} 에서 멈췄고 런 밖 머지로도 들여오지 않습니다 — ${why}"
      else
        warn "슬라이스 ${seg} 의 이전 런 ${GATE_PRIOR_RUN} PR 절단점 종단 행은 들여오지 않습니다 — ${why}"
      fi
      return 1
    fi
    GATE_IMPORT_PR_STATE=$ost
    what="커밋=${pc}"
    [ "$ost" = "MERGED" ] || omc=""
    if [ "$GATE_PRIOR_OUTSIDE" = "1" ]; then
      # The `머지됨` import rule, not a new one: a merge that still owes this
      # run's apply is not the slice's ending.
      if gate_segment_owes_apply "$dal" "$seg"; then
        if [ "$mode" = "self" ]; then
          warn "슬라이스 ${seg} 는 이전 런 ${GATE_PRIOR_RUN} 이 ${pst} 에서 멈춘 뒤 런 밖에서 PR #${ppr} 로 머지됐지만 적용이 남았습니다 — 들여오지 않고 다시 합니다"
          return 1
        fi
        warn "세그먼트 계획 거부: 선행 ${seg} 는 이 런의 원장에 없고, 같은 문서의 이전 런 ${GATE_PRIOR_RUN} 이 ${pst} 에서 멈춘 뒤 런 밖에서 PR #${ppr} 로 머지됐지만 적용이 남았습니다 — 적용이 남은 머지는 들여오지 않습니다"
        return "$GATE_EXIT_RULE"
      fi
      pst="머지됨"
      what=""
    fi
  fi
  noun="선행"
  [ "$mode" != "self" ] || { noun="슬라이스"; GATE_DECL_SELF_IMPORTED=1; }
  if [ "$verb" != "act" ]; then
    warn "act 로 내면 ${noun} ${seg} 를 이전 런 ${GATE_PRIOR_RUN} 의 종단 행(상태=${pst}${what:+ · $what}${omc:+ · 머지 커밋=$omc})으로 이 원장에 먼저 들여옵니다"
    return 0
  fi
  case "$pbr" in ''|*[!A-Za-z0-9._/-]*) pbr="" ;; esac
  gate_append 'segment' "id=$seg" "상태=$pst" ${ppr:+"PR=$ppr"} ${what:+"$what"} ${omc:+"머지 커밋=$omc"} \
    ${pbr:+"브랜치=$pbr"} "워크트리=${pwt:--}" "선행=${pdp:-없음}" "출처=$org" \
    ${pdg:+"선언 다이제스트=$pdg"}
  log "${noun} 들여오기 — ${seg} (${pst}, 출처 ${org}${what:+, $what}${omc:+, 머지 커밋 $omc})"
  return 0
}

gate_import_self_landed() {
  # gate_import_self_landed <verb> <segment> — the fixed-graph driver's form of
  # the slice's own import: the exit code of `gate_import_prior_landed … self`,
  # and on 0 one word on stdout saying what came in. `착지` is a landing the
  # slices after it may build on; `건너뜀` is a slice whose work stands at a
  # pull request still open — not done again, and not a predecessor either.
  # The word is the only way the answer leaves `run_gate_call`'s child shell.
  #
  # A THIRD WORD, `선언 이동`, ALSO ON 0 AND WITH NO ROW WRITTEN. An earlier run
  # landed the slice and every such landing was dropped because the frozen
  # declaration now differs from the one it was built to. Every other run does
  # the slice again, as it did; a `P0잔존` successor stops before planning
  # instead, because the declaration moved under work that already merged. The
  # rc contract of `gate_import_prior_landed` is untouched — this is read off
  # the state its walk left behind.
  local rc=0
  GATE_PRIOR_DECL_MOVED=""
  gate_import_prior_landed "$1" "$2" self || rc=$?
  if [ "$rc" = "1" ] && [ "$GATE_PRIOR_DECL_MOVED" = "1" ] && [ -z "$GATE_PRIOR_RUN" ]; then
    printf '선언 이동\n'
    return 0
  fi
  [ "$rc" = "0" ] || return "$rc"
  case "$GATE_IMPORT_PR_STATE" in
    OPEN) printf '건너뜀\n' ;;
    *) printf '착지\n' ;;
  esac
}

gate_prior_landed_ids() {
  # gate_prior_landed_ids — the slice ids earlier runs of this document left
  # landed (`머지됨` or `완료` on that ledger's last row for the id, or on the
  # first row before a trailing `park` that is neither `park` nor `적용 준비` —
  # the walk of `gate_landing_walk`), one per line, sorted. The `P0잔존`
  # successor compares them with the slice ids its new document declares
  # before planning: a redesign that renamed or dropped
  # a landed slice never reaches `선언 이동`, because no planned id matches the
  # landing at all.
  local kl="${LEDGER:-}" kg="${GRANT:-}" kb="${BASE:-}" dir f rrow
  if [ -z "${DOC_KEY:-}" ] && [ -n "${MANIFEST:-}" ]; then
    derive_paths_from_manifest >/dev/null 2>&1 || true
    [ -z "$kl" ] || LEDGER=$kl
    [ -z "$kg" ] || GRANT=$kg
    [ -z "$kb" ] || BASE=$kb
  fi
  [ -n "${LEDGER:-}" ] && [ -n "${DOC_KEY:-}" ] || return 0
  dir=$(dirname "$LEDGER")
  for f in "$dir"/*.md; do
    [ -f "$f" ] || continue
    [ "$f" != "$LEDGER" ] || continue
    case "$(basename "$f" .md)" in *.*) continue ;; esac
    rrow=$( { grep -E '^- `run` ' "$f" 2>/dev/null || true; } | sed -n 1p)
    [ -n "$rrow" ] || continue
    [ "$(gate_row_field "$rrow" '설계 문서')" = "$DOC_KEY" ] || continue
    { grep -E '^- `segment` ' "$f" 2>/dev/null || true; } | awk '
      { n = split($0, x, / \| /); id = ""; st = ""
        for (i = 2; i <= n; i++) {
          v = x[i]
          if (index(v, "id=") == 1) { sub(/^id=/, "", v); id = v }
          else if (index(v, "상태=") == 1) { sub(/^상태=/, "", v); st = v }
        }
        if (id != "") { n_[id]++; s_[id, n_[id]] = st } }
      END {
        for (k in n_) {
          i = n_[k]; st = s_[k, i]
          if (st == "park") {
            for (i = i - 1; i >= 1; i--) if (s_[k, i] != "park" && s_[k, i] != "적용 준비") break
            st = (i >= 1) ? s_[k, i] : ""
          }
          if (st == "머지됨" || st == "완료") print k
        }
      }'
  done | LC_ALL=C sort -u
}

gate_manifest_landing_row() {
  # gate_manifest_landing_row <slice> — the `선행 착지` row the kickoff froze for
  # that slice; status 1 when the manifest carries none. `check_manifest` has
  # already refused a second row for one slice, so the first is the only one.
  local row
  row=$( { manifest_predecessor_landing_rows | grep -F "| 슬라이스=$1 |" || true; } | sed -n 1p)
  [ -n "$row" ] || return 1
  printf '%s' "$row"
}

gate_remote_landing() {
  # gate_remote_landing <원격 슬러그> <머지 커밋> — the three-way verdict of
  # `gate_obligation_landing`, for a repository that is NOT a declared target
  # and so has no anchor root on this host to ask. The remote's default branch
  # is the base, and the remote's own comparison of the commit against it is
  # the evidence: `ahead` or `identical` means the branch contains the commit.
  #
  # ANY FAILURE IS 판정 불가, never 미착지. A missing `gh`, an unreadable
  # repository, a commit the remote does not know and a status outside the four
  # all leave the question unanswered, and the caller refuses on both.
  local slug="$1" m="$2" br="" st=""
  GATE_LANDING_VERDICT=""
  GATE_LANDING_WHY=""
  if ! command -v gh >/dev/null 2>&1; then
    GATE_LANDING_WHY="gh 를 찾지 못해 원격 $slug 에 물을 수 없습니다"
    GATE_LANDING_VERDICT='판정 불가'; return 0
  fi
  br=$(gh api "repos/$slug" --jq .default_branch 2>/dev/null) || br=""
  if [ -z "$br" ]; then
    GATE_LANDING_WHY="원격 $slug 의 기본 브랜치를 읽지 못했습니다"
    GATE_LANDING_VERDICT='판정 불가'; return 0
  fi
  st=$(gh api "repos/$slug/compare/$m...$br" --jq .status 2>/dev/null) || st=""
  case "$st" in
    ahead|identical)
      GATE_LANDING_WHY="원격 $slug 의 $br 가 머지 커밋을 담고 있습니다 (비교: $st)"
      GATE_LANDING_VERDICT='착지' ;;
    behind|diverged)
      GATE_LANDING_WHY="원격 $slug 의 $br 가 머지 커밋을 담고 있지 않습니다 (비교: $st)"
      GATE_LANDING_VERDICT='미착지' ;;
    *)
      GATE_LANDING_WHY="원격 $slug 에서 머지 커밋과 $br 의 비교가 답하지 못했습니다"
      GATE_LANDING_VERDICT='판정 불가' ;;
  esac
  return 0
}

GATE_DECL_FIELDS=()
gate_from_declaration() {
  # gate_from_declaration <verb> <alias> <segment> <키=값>... — the fields of a
  # planned segment row, filled from the frozen document into GATE_DECL_FIELDS.
  # Returns the exit code of a refusal, or 0. Everything it refuses, it refuses
  # before anything is written about the act; the rows it may write are the
  # run-scope block of a structural refusal and, on `act`, the terminal row of
  # a predecessor an earlier run of the same document landed or the manifest's
  # `선행 착지` row names, and the slice's own terminal row when an earlier run
  # landed it — then GATE_DECL_SELF_IMPORTED is set and no planned row follows.
  local verb="$1" alias="$2" seg="$3"
  shift 3
  local f="" k="" st="" wt="" want="" br="" why="" al="" astep="" alast="" step="" d="" ids="" declared="" derived=""
  local known="" dal="" pm="" pdp="" adrow="" prow="" pslug="" dslug="" pwhere="" irc=0
  GATE_DECL_FIELDS=()
  GATE_DECL_SELF_IMPORTED=""

  # THE CALLER NAMES THE SEGMENT, THE STATE AND THE WORKTREE, AND NOTHING THE
  # DOCUMENT DECLARES. A caller value beside the gate's would be a second
  # source, and the segment arm takes the last of two.
  for f in "$@"; do
    k=${f%%=*}
    case "$k" in
      레포|'선언 파일 집합'|선행|'머지 순서'|절단점|'리뷰 정책'|'선언 다이제스트'|'강제 표면'|plan-binding-digest)
        warn "--from-declaration 은 「${k}」 를 동결 문서에서 채웁니다 — 호출자가 넘길 수 없습니다"
        return "$GATE_EXIT_VOCAB" ;;
    esac
  done
  st=$(gate_field_of '상태' "$@")
  if [ "$st" != "계획됨" ]; then
    warn "--from-declaration 은 계획 행에만 씁니다 — 「상태=계획됨」 이어야 하는데 ${st:-(없음)} 입니다"
    return "$GATE_EXIT_VOCAB"
  fi
  case "$seg" in
    ''|-) warn "--from-declaration 은 --segment 로 세그먼트 id 를 받아야 합니다"; return "$GATE_EXIT_VOCAB" ;;
  esac

  # THE DOCUMENT IS STILL FROZEN. The audit edits the document after the
  # freeze and its reconciliation could change the status line; a plan read
  # from a document that is no longer frozen plans something nobody froze. A
  # run that names no document has nothing to re-read and plans undeclared.
  if [ -n "${DOC:-}" ] && ! grep -qxF '**상태**: 동결됨' "$DOC" 2>/dev/null; then
    warn "세그먼트 계획은 동결된 설계 문서에서만 읽습니다 — $DOC 에 「**상태**: 동결됨」 한 줄이 없습니다"
    return "$GATE_EXIT_RULE"
  fi

  # THE AUDIT HAS ENDED. Planning reads the document the audit is still free to
  # edit, and both hold the same lock, so the order is the gate's to keep.
  # An audit that ended `정상 완료` but asked for a skeletal re-convergence, or
  # one a re-convergence on its key came after, has not concluded either.
  if astep=$(gate_run_scope_step audit); then
    if ! gate_audit_concluded "$astep"; then
      case "$GATE_AUDIT_WAIT" in
        재수렴|골격급)
          warn "세그먼트 계획은 감사 단계($astep)의 마지막 결과가 정상 완료일 때만 씁니다 — 감사 단계($astep)가 $GATE_AUDIT_WHY" ;;
        *)
          alast=$(gate_row_field "$(gate_audit_result_rows_of "$astep" | tail -1)" '종단 부류')
          warn "세그먼트 계획은 감사 단계($astep)의 마지막 결과가 정상 완료일 때만 씁니다 — 지금은 ${alast:-결과 행 없음} 입니다" ;;
      esac
      return "$GATE_EXIT_RULE"
    fi
    if gate_stage_live_attempt "$astep"; then
      warn "세그먼트 계획은 감사 단계($astep)에 살아 있는 시도가 없을 때만 씁니다"
      return "$GATE_EXIT_RULE"
    fi
    # A design-key re-convergence after the last audit edited what it audited.
    if gate_design_reconverge_after_audit "$astep"; then
      warn "세그먼트 계획은 설계 단계의 재수렴 뒤 새 감사가 정상 완료로 끝난 뒤에만 씁니다 — 감사 단계($astep)가 재수렴 뒤 새 감사를 기다립니다"
      return "$GATE_EXIT_RULE"
    fi
  fi

  br=$(gate_slicing_branch)
  # A DEFECT ONE SLICE OWNS PARKS THAT SLICE, NOT THE RUN. When every defect is
  # a missing field of a named slice, the slice being planned is refused only
  # if it is one of those slices or depends on one, with an act-scope park row
  # naming it; any other slice is planned as under a complete declaration. A
  # defect that names no single slice keeps the run-scope block below.
  local dslices=""
  if [ "$br" = "선언불완전" ]; then
    dslices=$(gate_decl_defect_slices)
    if [ -n "$dslices" ]; then
      if gate_slice_reaches_any "$seg" $dslices; then
        why="구현 슬라이싱 선언 불완전 — $(gate_slicing_defects | grep -F "슬라이스 " | tr '\n' ';' | sed 's/;$//; s/;/; /g')"
        warn "세그먼트 계획 거부: 슬라이스 ${seg} — $why"
        gate_decl_slice_park "$verb" "$alias" "$seg" "$why"
        return "$GATE_EXIT_RULE"
      fi
      br=선언통치
    fi
  fi
  case "$br" in
    선언불완전)
      why="구현 슬라이싱 선언 불완전 — $(gate_slicing_defects | tr '\n' ';' | sed 's/;$//; s/;/; /g')"
      warn "세그먼트 계획 거부: $why"
      gate_decl_block "$verb" "$why"
      return "$GATE_EXIT_RULE" ;;
    선언통치)
      ids=" $(slice_ids "$DOC" 2>/dev/null | tr '\n' ' ') "
      case "$ids" in
        *" $seg "*) : ;;
        *) warn "세그먼트 ${seg} 는 동결 문서의 ## 구현 슬라이싱 에 없습니다 — 선언된 슬라이스:${ids% }"
           return "$GATE_EXIT_VOCAB" ;;
      esac
      if ! al=$(gate_slice_alias "$seg"); then
        # This slice owns the defect, so it parks alone (see above).
        why="구현 슬라이싱 선언 불완전 — 슬라이스 $seg: 레포 「$(slice_field "$DOC" "$seg" '레포')」 가 매니페스트의 어느 대상도 아닙니다"
        warn "세그먼트 계획 거부: $why"
        gate_decl_slice_park "$verb" "$alias" "$seg" "$why"
        return "$GATE_EXIT_RULE"
      fi
      GATE_DECL_FIELDS=( "상태=계획됨" \
        "선언 파일 집합=$(declared_field_for_row "$seg" "$(slice_field "$DOC" "$seg" '선언 파일')")" \
        "레포=$(slice_field "$DOC" "$seg" '레포')" \
        "선행=$(slice_field "$DOC" "$seg" '선행')" \
        "절단점=$(slice_field "$DOC" "$seg" '절단점')" )
      # `머지 순서` only when it is not `없음`, the condition the declaration
      # digest uses for its sixth line: an absent field reads as `없음`.
      k=$(slice_field "$DOC" "$seg" '머지 순서')
      [ -z "$(gate_dep_tokens "$k")" ] || GATE_DECL_FIELDS+=( "머지 순서=$k" )
      k=$(slice_field "$DOC" "$seg" '리뷰 정책')
      [ -z "$k" ] || GATE_DECL_FIELDS+=( "리뷰 정책=$k" )
      GATE_DECL_FIELDS+=( "선언 다이제스트=$(slice_decl_digest "$DOC" "$seg")" )
      # `강제 표면` from the same declared files, through the classifier the run
      # hook sources: a slice that has to edit what the hook refuses says so on
      # its planned row, before any stage runs into the refusal. The driver's
      # `plan_from_declaration` stamps the same value the same way.
      local -a sdf=()
      while IFS= read -r d; do [ -z "$d" ] || sdf+=("$d"); done <<<"$(slice_decl_files "$DOC" "$seg")"
      GATE_DECL_FIELDS+=( "강제 표면=$(gate_surface_stamp ${sdf[@]+"${sdf[@]}"})" )
      ;;
    *)
      step=$(gate_plan_implement_step)
      if [ -z "$step" ] || [ "$seg" != "$step" ]; then
        warn "슬라이싱 선언이 없는 런의 세그먼트는 하나이고 그 id 는 계획의 구현 단계 id(${step:-없음}) 입니다 — 받은 값: $seg"
        return "$GATE_EXIT_VOCAB"
      fi
      al=$(home_alias)
      GATE_DECL_FIELDS=( "상태=계획됨" "선행=없음" )
      k=""
      ;;
  esac

  if [ "$alias" != "$al" ]; then
    warn "세그먼트 ${seg} 의 대상은 ${al} 입니다 — --target ${alias} 로는 계획하지 않습니다"
    return "$GATE_EXIT_VOCAB"
  fi

  # STRICT WHEN UNDECLARED, AND STOPPED HERE WHEN NOTHING CAN REVIEW. A slice
  # that declares no policy reads as `선리뷰후머지`, and a plan with no review
  # step can never satisfy it — the merge would be refused forever, and that
  # surfaces nights later as a refusal naming the review, not the plan.
  if [ "${k:-선리뷰후머지}" != "리뷰없음" ] \
     && [ -z "$(manifest_plan_json 2>/dev/null | jq -r '[.steps[]? | select(type == "object" and .skill == "review")][0].skill // empty' 2>/dev/null || true)" ]; then
    if [ -z "$k" ]; then
      why="리뷰 정책 미선언 · 계획에 리뷰 단계 없음 — 세그먼트 $seg"
    else
      why="리뷰 정책 $k · 계획에 리뷰 단계 없음 — 세그먼트 $seg"
    fi
    warn "세그먼트 계획 거부: $why — 선언하지 않은 정책은 선리뷰후머지로 읽히고, 리뷰 단계가 없는 계획에서는 머지가 영영 막힙니다"
    gate_decl_block "$verb" "$why"
    return "$GATE_EXIT_RULE"
  fi

  want=$(gate_decl_worktree "$al" "$seg") || want=""
  # AN ADOPTED SEGMENT IS PLANNED IN THE TREE THE MANIFEST NAMES, and only once
  # the disk agrees with that row (see `gate_adoption_check`).
  if adrow=$(gate_adoption_row "$seg"); then
    want=$(manifest_row_fields "$adrow" '워크트리')
    gate_adoption_check "$seg" "$al" "$adrow" || return "$GATE_EXIT_RULE"
    # The planning act brings in the earlier run's open answer to a halt
    # (`gate_adoption_halt_carry`); a dry run says what that act would do.
    if [ "$verb" = "plan" ]; then
      local crc=0
      gate_adoption_halt_source "$seg" || crc=$?
      case "$crc" in
        0) warn "act 는 출처 런 ${GATE_CARRY_SRC} 원장 ${GATE_CARRY_LINE} 번째 줄의 중단 답(선택지 $(gate_row_field "$GATE_CARRY_ROW" '선택지'))을 이 런으로 들여옵니다" ;;
        1) ;;
        *) warn "출처 런 ${GATE_CARRY_SRC} 원장 ${GATE_CARRY_LINE} 번째 줄의 열린 중단 답은 이 런으로 이어지지 않습니다 — ${GATE_CARRY_WHY}" ;;
      esac
    fi
  fi
  wt=$(gate_field_of '워크트리' "$@")
  if [ -z "$want" ] || [ "$wt" != "$want" ]; then
    warn "세그먼트 ${seg} 의 「워크트리」는 ${want:-(유도 실패)} 여야 합니다 — 받은 값: ${wt:-(없음)}"
    return "$GATE_EXIT_VOCAB"
  fi

  # THE FIRST PLANNING ACT CHECKS THE WHOLE DECLARATION, the two checks the
  # driver runs before its first row: the slice-count checksum, and that every
  # `선행` names a declared slice. Later acts find the earlier rows and the
  # segment arm's own floors take over.
  if [ "$br" = "선언통치" ] && [ -z "$(gate_segment_ids)" ]; then
    declared=$(slicing_body "$DOC" | sed -n 's/^\*\*슬라이스 수\*\*: //p' | sed 's/[[:space:]]*$//' | sed -n 1p)
    derived=$(slicing_pr_count "$DOC")
    # A parked slice with no `절단점` cannot be counted either way, so the
    # checksum holds when the declared count lies between the slices that are
    # counted and those plus every such slice. Without this the defect one
    # slice owns comes back as a run-scope checksum block and stops the
    # independent slices after all.
    local unknown=0
    for f in $dslices; do
      [ -n "$(slice_field "$DOC" "$f" '절단점' 2>/dev/null || true)" ] || unknown=$((unknown + 1))
    done
    if [ -n "$declared" ] && [ "$unknown" -gt 0 ] \
       && [ "$declared" -ge "$derived" ] 2>/dev/null && [ "$declared" -le $((derived + unknown)) ] 2>/dev/null; then
      declared=$derived
    fi
    if [ -n "$declared" ] && [ "$declared" != "$derived" ]; then
      why="구현 슬라이싱 선언 불완전 — 슬라이스 수 체크섬 불일치: 선언 ${declared} vs 파생 ${derived}"
      warn "세그먼트 계획 거부: $why"
      gate_decl_block "$verb" "$why"
      return "$GATE_EXIT_RULE"
    fi
    # A `머지 순서` token naming no declared slice has no owner either, so it
    # joins the same run-scope check.
    for f in $(slice_ids "$DOC" 2>/dev/null || true); do
      for k in 선행 '머지 순서'; do
        for d in $(gate_dep_tokens "$(slice_field "$DOC" "$f" "$k")"); do
          case "$ids" in
            *" $d "*) : ;;
            *) why="구현 슬라이싱 선언 불완전 — 슬라이스 $f: 「${k}」이 지목한 슬라이스가 선언에 없습니다: $d"
               warn "세그먼트 계획 거부: $why"
               gate_decl_block "$verb" "$why"
               return "$GATE_EXIT_RULE" ;;
          esac
        done
      done
    done
  fi

  # A PREDECESSOR AN EARLIER RUN OF THIS DOCUMENT LANDED IS BROUGHT IN FIRST,
  # after the whole-declaration checks and before the planned row exists. The
  # segment arm refuses a `선행` token this ledger does not know, which is right
  # for a typo and wrong for a slice the previous run merged: that predecessor
  # can never get a row here, so the dependent slice could never be planned.
  #
  # THE PRIOR LEDGER IS A CLAIM AND THE BASE BRANCH IS THE EVIDENCE. The row is
  # copied only when the merge commit it names has landed on the predecessor's
  # own target's base branch, through the same three-way verdict the deferred
  # review obligation closes on; `미착지` and `판정 불가` refuse the plan and
  # write nothing, because a row saying "landed" over a commit that did not is
  # exactly the base this slice would then be dispatched onto.
  #
  # A MERGE THAT STILL OWES ITS APPLY IS NOT BROUGHT IN. Termination condition 1
  # reads `머지됨` without `적용=대기` as an ending, and the apply this run's
  # declaration owes for that slice would then be skipped without a word; the
  # earlier run has to finish it, or a person decides.
  #
  # THE ROW IS TERMINAL, AND THAT IS WHAT KEEPS IT OUT OF THIS RUN'S WORK. Every
  # reader that decides what is still to do — the cone, condition 1, the CI
  # poller, the dispatch-time landing check — skips or accepts a terminal row,
  # and no review obligation is issued from a row. `출처` names the run that
  # did the work; only this writer sets it, since the segment arm refuses a
  # caller's. Written once: a later act finds the id in `gate_segment_ids` and
  # does nothing. A dry run writes nothing and says what the act would bring in.
  #
  # A PREDECESSOR NO RUN LEDGER RECORDS IS BROUGHT IN FROM THE MANIFEST, when the
  # kickoff froze a `선행 착지` row for it. Two shapes leave a landed slice with
  # no ledger to find: the run that delivered it used a different segment id or
  # recorded no `머지 커밋`, or the slice lives in a repository this run does
  # not target, whose segments no ledger of this run's targets ever holds. The
  # row is a person's claim and is checked the way a prior ledger's is — the
  # slug must be the slice's declared `레포`, and the commit must be on that
  # repository's base branch: through the target's anchor when the repository
  # is a target, through the remote's own comparison when it is not. The row
  # written is `머지됨` with `출처=매니페스트` and no worktree.
  #
  # BOTH KINDS ARE BROUGHT IN. A `머지 순서` token is held by the same
  # known-token floor as a `선행` token, so a merge-order predecessor an earlier
  # run landed would otherwise leave its successor unplannable for good.
  if [ "$br" = "선언통치" ]; then
    known=" $(gate_segment_ids | tr '\n' ' ') "
    for d in $(slice_chain_tokens "$DOC" "$seg"); do
      case "$known" in *" $d "*) continue ;; esac
      dal=$(gate_slice_alias "$d" 2>/dev/null) || dal=""
      if [ -n "$dal" ]; then
        irc=0
        gate_import_prior_landed "$verb" "$d" || irc=$?
        case "$irc" in 0) continue ;; 1) : ;; *) return "$irc" ;; esac
      fi
      prow=$(gate_manifest_landing_row "$d") || continue
      pslug=$(gate_row_field "$prow" '원격 슬러그')
      pm=$(gate_row_field "$prow" '머지 커밋')
      dslug=$(slice_field "$DOC" "$d" '레포' 2>/dev/null | tr -d '`' | sed 's/^[[:space:]]*//; s/[[:space:]]*$//')
      if [ "$pslug" != "$dslug" ]; then
        warn "세그먼트 계획 거부: 선행 착지 행의 슬라이스 ${d} 는 원격 슬러그 ${pslug} 를 들지만 동결 문서가 선언한 레포는 ${dslug:-(없음)} 입니다"
        return "$GATE_EXIT_RULE"
      fi
      if [ -n "$dal" ]; then
        if gate_segment_owes_apply "$dal" "$d"; then
          warn "세그먼트 계획 거부: 선행 ${d} 는 이 런의 선언상 적용이 남는 슬라이스입니다 — 선행 착지 행은 머지만 말하므로 적용이 남은 슬라이스는 들여오지 않습니다"
          return "$GATE_EXIT_RULE"
        fi
        gate_obligation_landing "$dal" "$pm"
        pwhere="대상 ${dal} 의 베이스 브랜치"
      else
        gate_remote_landing "$pslug" "$pm"
        pwhere="원격 ${pslug} 의 기본 브랜치"
      fi
      if [ "$GATE_LANDING_VERDICT" != "착지" ]; then
        warn "세그먼트 계획 거부: 선행 ${d} 는 이 런의 원장에 없고, 매니페스트의 선행 착지 행이 든 머지 커밋 ${pm} 은 ${pwhere}에 ${GATE_LANDING_VERDICT:-판정 불가} 입니다 — ${GATE_LANDING_WHY}"
        return "$GATE_EXIT_RULE"
      fi
      pdp=$(slice_field "$DOC" "$d" '선행' 2>/dev/null || true)
      if [ "$verb" != "act" ]; then
        warn "act 로 내면 선행 ${d} 를 매니페스트의 선행 착지 행(상태=머지됨 · 머지 커밋=${pm})으로 이 원장에 먼저 들여옵니다"
        continue
      fi
      gate_append 'segment' "id=$d" "상태=머지됨" "머지 커밋=$pm" "워크트리=-" \
        "선행=${pdp:-없음}" "출처=매니페스트" "선언 다이제스트=$(slice_decl_digest "$DOC" "$d")"
      log "선행 들여오기 — ${d} (머지됨, 출처 매니페스트, 머지 커밋 ${pm})"
    done

    # THE SLICE BEING PLANNED MAY ITSELF HAVE LANDED IN AN EARLIER RUN — a run
    # re-kicked by hand or by the chain after this slice merged or stopped at its
    # PR. Its planned row would send the same work out again, so the terminal
    # row is brought in instead and no planned row is written; the caller sees
    # GATE_DECL_SELF_IMPORTED and stops there. Nothing to bring in plans as before.
    irc=0
    gate_import_prior_landed "$verb" "$seg" self || irc=$?
    case "$irc" in 0) return 0 ;; 1) : ;; *) return "$irc" ;; esac
  fi

  GATE_DECL_FIELDS+=( "워크트리=$wt" )
  for f in "$@"; do
    case "${f%%=*}" in
      상태|워크트리) : ;;
      *) GATE_DECL_FIELDS+=( "$f" ) ;;
    esac
  done
  return 0
}

gate_row_field() {
  # gate_row_field <row-text> <key> — the last value with that key in ONE row.
  # `gate_field_of` reads an argv field LIST; carrying a value forward needs a
  # field of a row already written, and the two are not interchangeable.
  local row="$1" key="$2"
  printf '%s' "$row" | tr '|' '\n' | sed -n "s/^ *$key=//p" | sed 's/[[:space:]]*$//' | tail -1
}

gate_rows_field_eq() {
  # stdin: rows. gate_rows_field_eq <key> <value> — prints each row whose LAST
  # field with that key equals <value> exactly, the same "last wins" reading
  # `gate_row_field` gives.
  #
  # NOT `grep -F "<key>=<value> "`. A substring match picks up any field whose
  # key merely ends in <key> and any value that merely begins with <value>, so a
  # segment `A` selected the rows of `A2`, and `세그먼트=` was matched inside a
  # key like `선행 세그먼트=`. The values travel through the environment rather
  # than `-v`, which would read a backslash in them as an escape.
  GATE_FEQ_K="$1" GATE_FEQ_V="$2" awk '
    { n = split($0, f, "|"); have = 0; last = ""
      for (i = 2; i <= n; i++) {
        s = f[i]; sub(/^ +/, "", s); sub(/[ \t]+$/, "", s)
        p = index(s, "=")
        if (p > 0 && substr(s, 1, p - 1) == ENVIRON["GATE_FEQ_K"]) { have = 1; last = substr(s, p + 1) }
      }
      if (have && last == ENVIRON["GATE_FEQ_V"]) print }'
}

gate_rows_field_ne() {
  # stdin: rows. gate_rows_field_ne <key> <value> — the complement of
  # `gate_rows_field_eq`: each row whose last field with that key is not
  # <value>, a row without the key included.
  GATE_FEQ_K="$1" GATE_FEQ_V="$2" awk '
    { n = split($0, f, "|"); have = 0; last = ""
      for (i = 2; i <= n; i++) {
        s = f[i]; sub(/^ +/, "", s); sub(/[ \t]+$/, "", s)
        p = index(s, "=")
        if (p > 0 && substr(s, 1, p - 1) == ENVIRON["GATE_FEQ_K"]) { have = 1; last = substr(s, p + 1) }
      }
      if (!(have && last == ENVIRON["GATE_FEQ_V"])) print }'
}

gate_rows_having_field() {
  # stdin: rows. gate_rows_having_field <key> — prints each row that carries a
  # field with exactly that key, whatever its value. A substring match would
  # also take a row whose free-text value merely mentions `<key>=`.
  GATE_FEQ_K="$1" awk '
    { n = split($0, f, "|"); have = 0
      for (i = 2; i <= n; i++) {
        s = f[i]; sub(/^ +/, "", s)
        p = index(s, "=")
        if (p > 0 && substr(s, 1, p - 1) == ENVIRON["GATE_FEQ_K"]) have = 1
      }
      if (have) print }'
}

gate_rows_field_values() {
  # stdin: rows. gate_rows_field_values <key> — prints, per row that carries a
  # field with exactly that key, the last such value (the reading
  # `gate_rows_field_eq` compares against). A `sed 's/.*<key>=…'` extraction
  # is greedy and takes the value of a later key that merely ends in <key>.
  GATE_FEQ_K="$1" awk '
    { n = split($0, f, "|"); have = 0; last = ""
      for (i = 2; i <= n; i++) {
        s = f[i]; sub(/^ +/, "", s); sub(/[ \t]+$/, "", s)
        p = index(s, "=")
        if (p > 0 && substr(s, 1, p - 1) == ENVIRON["GATE_FEQ_K"]) { have = 1; last = substr(s, p + 1) }
      }
      if (have) print last }'
}

# ---------------------------------------------------------------------------
# `stage-lease` / `stage-wait`: envelope to row, and the three readers.
#
# TWO LAUNCH SITES CALL THESE, AND ONLY WITH ROUTING ON. The driver's
# `stage_spawn` (through a child shell that sources this file) and the gate's
# own `gate_launch_stage` write one `stage-lease` row per grant before the
# spawn — a seat or dormant grant included; the gate's launch writes a
# `stage-wait` row when the router answers `WAIT` and the dispatch is stopped.
# With routing off neither is called and neither series is written.
# `--self-check` enumerates `run.sh` functions only, so these are not reported
# by it — this is where their callers are named.
#
# The builders live HERE and not in `run.sh`: there their only callers would be
# gate functions nothing calls, and `--self-check` would count them as wired by
# the letter alone. The driver's capability is `ledger_row`'s branch for the two
# series, reached with the literal argv; the check fixes the keys and their
# order, so a misspelt or reordered call is refused at run time.
# ---------------------------------------------------------------------------

gate_route_bp_jq() {
  # The jq definitions both builders share: a null as `-`, basis points as
  # `I.FFFF`, and the envelope's `cost` as two cells — `비용` and `비용 출처`,
  # each `<five_hour>/<seven_day>`, or both `-` when the envelope carries none.
  # `bp_open` is the threshold's form: `I.FFFF` with no 10000 ceiling, and `-`
  # for anything that is not a non-negative integer. It never fails — a
  # threshold `bp` refuses would refuse the row and stop the stage.
  cat <<'JQ'
def s: if . == null then "-" else tostring end;
def four: tostring | ("0000" + .) | .[-4:];
def bp: if (type == "number") and (. == floor) and (. >= 0) and (. <= 10000)
        then "\(. / 10000 | floor).\(. % 10000 | four)" else error("reservation_bp") end;
def bp_open: if (type == "number") and (. == floor) and (. >= 0)
             then "\(. / 10000 | floor).\(. % 10000 | four)" else "-" end;
def cost_cells:
  if ((.cost | type) == "object") and ((.cost.five_hour | type) == "object") and ((.cost.seven_day | type) == "object")
  then ((.cost.five_hour.bp | bp) + "/" + (.cost.seven_day.bp | bp)),
       ((.cost.five_hour.source | s) + "/" + (.cost.seven_day.source | s))
  else "-", "-" end;
JQ
}

gate_stage_lease_row() {
  # gate_stage_lease_row <파견 id> <봉투 json> [<구속 토큰>] — one `stage-lease`
  # row from a `GRANT` envelope. rc 2 and no row for anything but a `GRANT`, for
  # a `reservation_bp` component that is not an integer in 0..10000, for a value
  # carrying a line break, and for `근거=resume-bound` without a binding the
  # envelope satisfies; otherwise whatever `gate_append` answers.
  #
  # FIELDS ARE READ BY NAME and the envelope is never serialized onto the row. A
  # null renders as `-`, never as jq's `null`, which would pass the identity rule
  # as an account called "null". `계보` is derived, not taken from the caller.
  # `단계`, `단계 출처` and `문턱` come from the envelope's `order`; a grant
  # without one (a held lease, a seat grant) renders all three as `-`.
  #
  # THE VALUES ARE CAPTURED BEFORE THEY ARE READ: under bash 3.2 a builder's
  # status inside a heredoc's command substitution is lost, and the row would be
  # written from whatever the failed builder left.
  #
  # NO DORMANT BRANCH. A valid `GRANT` renders whether or not it is dormant,
  # and with routing on both launch sites write the row for every grant, a
  # dormant or seat grant included.
  local did="${1:-}" env="${2:-}" bind="${3:-}" verdict vals lineage acct cdir lane bp cost csrc basis obs
  local phase psrc thr
  verdict=$(printf '%s' "$env" | jq -r 'if type == "object" then (.verdict // "") else "" end' 2>/dev/null) || return 2
  [ "$verdict" = "GRANT" ] || return 2
  vals=$(printf '%s' "$env" | jq -r "$(gate_route_bp_jq)"'
    [ (.account | s),
      (if .config_dir == null then "-" else "=" + (.config_dir | tostring) end),
      (if .reservation_bp == null then "-"
       else (.reservation_bp.five_hour | bp) + "/" + (.reservation_bp.seven_day | bp) end),
      cost_cells,
      (.basis | s),
      (.observed | s),
      ((if (.order | type) == "object" then .order else {} end) as $o
       | (if ($o.phase | type) == "string" and ($o.phase_source | type) == "string"
          then ($o.phase | s), ($o.phase_source | s) else "-", "-" end),
         ($o.threshold_bp | bp_open)) ]
    | if any(.[]; test("[\r\n]")) then error("line break") else .[] end' 2>/dev/null) || return 2
  [ -n "$vals" ] || return 2
  { IFS= read -r acct; IFS= read -r cdir; IFS= read -r bp; IFS= read -r cost; IFS= read -r csrc
    IFS= read -r basis; IFS= read -r obs; IFS= read -r phase; IFS= read -r psrc; IFS= read -r thr; } <<EOF
$vals
EOF
  lineage=$(route_lineage_of "$did")
  if [ "$cdir" = "-" ]; then lane="-"; else lane=$(lane_label_of "${cdir#=}"); fi
  if [ "$basis" = "resume-bound" ]; then
    [ -n "$bind" ] || return 2
    gate_resume_grant_ok "$bind" "$env" || return 2
  fi
  gate_append 'stage-lease' "파견 id=$did" "계보=$lineage" "계정=$acct" "레인=$lane" \
    "예약=$bp" "비용=$cost" "비용 출처=$csrc" "근거=$basis" "관측=$obs" \
    "단계=$phase" "단계 출처=$psrc" "문턱=$thr"
}

gate_stage_wait_row() {
  # gate_stage_wait_row <파견 id> <봉투 json> [<구속 토큰>] [<중단 답 줄>] — one
  # `stage-wait` row from a `WAIT` envelope, built the way `gate_stage_lease_row`
  # builds its row. The envelope carries no dispatch id, so the caller passes it
  # and `계보` is derived from it. `까지` is `floor|todate`, the byte shape of
  # `now_iso`. A `resume-bound-*` reason needs the binding the same way a
  # `resume-bound` grant does. An attempt that waits with a halt answer's card
  # names the answer's ledger line in `답 운반`, so the ledger tells a wait that
  # holds an answer from one that does not.
  local did="${1:-}" env="${2:-}" bind="${3:-}" carry="${4:-}" verdict vals lineage grp acct upto cost csrc reason
  verdict=$(printf '%s' "$env" | jq -r 'if type == "object" then (.verdict // "") else "" end' 2>/dev/null) || return 2
  [ "$verdict" = "WAIT" ] || return 2
  vals=$(printf '%s' "$env" | jq -r "$(gate_route_bp_jq)"'
    [ (.group | s),
      (.account | s),
      (if .until_epoch == null then "-" else (.until_epoch | floor | todate) end),
      cost_cells,
      (.reason | s) ]
    | if any(.[]; test("[\r\n]")) then error("line break") else .[] end' 2>/dev/null) || return 2
  [ -n "$vals" ] || return 2
  { IFS= read -r grp; IFS= read -r acct; IFS= read -r upto; IFS= read -r cost; IFS= read -r csrc
    IFS= read -r reason; } <<EOF
$vals
EOF
  lineage=$(route_lineage_of "$did")
  case "$reason" in
    resume-bound-*)
      [ -n "$bind" ] || return 2
      gate_resume_grant_ok "$bind" "$env" || return 2 ;;
  esac
  gate_append 'stage-wait' "계보=$lineage" "그룹=$grp" "계정=$acct" "까지=$upto" \
    "비용=$cost" "비용 출처=$csrc" "근거=$reason" ${carry:+"답 운반=$carry"}
}

gate_lease_of() {
  # gate_lease_of <파견 id|계보> — the lineage's lease JSON, empty when there is
  # none, with `route_lease_of`'s status passed through. The lease format is
  # route.sh's and is not spelled a second time here; `route_lineage_of` is
  # idempotent, so a dispatch id and an already-stripped lineage read the same.
  route_lease_of "$(run_pace_root)/leases" "$RUN_ID" "$(route_lineage_of "${1:-}")"
}

gate_resume_binding_of() {
  # gate_resume_binding_of <seg> <sid> — the account on the rows that recorded
  # this session, which is what a resume is bound to. Prints one account id, `-`
  # for a seat, or nothing when the rows carry no binding (no `계정` field, or
  # `(미상)`), all rc 0. rc 3 when the session id does not have a session id's
  # shape or no row of this stage records it; rc 4 when the rows disagree.
  #
  # THE SHAPE COMES FIRST. The gate writes `세션 id=미상` for a stage with no
  # terminal result line, and that value repeats across attempts and runs; read
  # as a session, every such row would fall into one "session" and answer with
  # whatever account they share.
  #
  # DISAGREEMENT IS REFUSED, not resolved. A re-attached stage can leave several
  # rows for one session, and three classes are counted apart — account ids
  # (each value its own), the seat `-`, and no binding. Two classes, or two
  # different ids, is rc 4: a resume that could be bound to either answer is not
  # bound. Absent and `(미상)` are one class, so a mix of only those is no binding.
  local seg="${1:-}" sid="${2:-}" rows row v ids="" seat=0 none=0 hit=0 n=0
  run_session_id_shape_ok "$sid" || return 3
  rows=$(gate_stage_result_rows_of "$seg")
  while IFS= read -r row; do
    [ -n "$row" ] || continue
    [ "$(gate_row_field "$row" '세션 id')" = "$sid" ] || continue
    hit=1
    v=$(gate_row_field "$row" '계정')
    case "$v" in
      ''|'(미상)') none=1 ;;
      -) seat=1 ;;
      *) case " $ids " in *" $v "*) ;; *) ids="${ids:+$ids }$v" ;; esac ;;
    esac
  done <<EOF
$rows
EOF
  [ "$hit" = "1" ] || return 3
  [ -z "$ids" ] || n=1
  [ "$((n + seat + none))" -le 1 ] || return 4
  case "$ids" in *' '*) return 4 ;; esac
  if [ -n "$ids" ]; then printf '%s' "$ids"
  elif [ "$seat" = "1" ]; then printf '%s' '-'
  fi
  return 0
}

gate_resume_grant_ok() {
  # gate_resume_grant_ok <구속> <봉투 json> — 0 when this envelope may carry a
  # resume bound as given: the account on the row that recorded the session has
  # to be the account the resume runs on, letter for letter.
  #
  # - A dormant `GRANT` has no account to compare, so it passes only with no
  #   binding (empty) or a seat binding (`-`). Every binding is empty until the
  #   launch writes the record's fourth line, so today's resumes are unchanged.
  # - An account `GRANT` passes when `.account` equals the binding exactly; a
  #   seat binding passes on a seat envelope. Nothing else passes.
  # - A `resume-bound-*` `WAIT` is held to the same rule: route.sh's live-lease
  #   branch hands back the lease's account without consulting the binding, so
  #   route cannot be assumed to refuse a wrong resume on its own.
  local bind="${1:-}" env="${2:-}" facts verdict dormant acct reason
  facts=$(printf '%s' "$env" | jq -r '
    if type != "object" then error("envelope") else . end
    | [ (.verdict // "" | tostring),
        (if .dormant == true then "1" else "0" end),
        (if .account == null then "" else (.account | tostring) end),
        (.reason // "" | tostring) ]
    | if any(.[]; test("[\r\n]")) then error("line break") else .[] end' 2>/dev/null) || return 1
  { IFS= read -r verdict; IFS= read -r dormant; IFS= read -r acct; IFS= read -r reason; } <<EOF
$facts
EOF
  case "$verdict" in
    GRANT)
      if [ "$dormant" = "1" ]; then
        case "$bind" in ''|-) return 0 ;; esac
        return 1
      fi ;;
    WAIT)
      case "$reason" in resume-bound-*) ;; *) return 1 ;; esac ;;
    *) return 1 ;;
  esac
  if [ -n "$acct" ]; then
    [ -n "$bind" ] && [ "$bind" = "$acct" ] && return 0
    return 1
  fi
  [ "$bind" = "-" ] && [ "$verdict" = "GRANT" ] && return 0
  return 1
}

gate_row_ids() {
  # stdin: rows. Prints each row's `id` FIELD value, one per line.
  #
  # THE GREEDY EXPRESSION THIS REPLACES READ THE WRONG FIELD. Every caller used
  # `sed -n 's/.*id=\([^|]*\).*/\1/p'`, whose `.*` is greedy and therefore takes
  # the LAST `id=` in the row rather than the id field, which sits near the
  # front. Pipes are stripped from every value before a row is assembled, so a
  # spliced field can no longer do this — but a value that merely ENDS in `id=`
  # still can, and `headRefOid=` does. Measured: a `segment` row whose `근거`
  # quoted a PR head as `headRefOid=<sha>, 체크 … 모두 SUCCESS` produced four
  # segment ids that no row was ever written for, and since a segment that does
  # not exist can never reach a terminal state, termination condition 1 was
  # unsatisfiable for the rest of that run.
  #
  # Splitting the row on its own separators is what the readers already do
  # (`gate_row_field`), so this reads the key the same way rather than tightening
  # the pattern: a tightened pattern would still be one expression away from the
  # same class of bug, while a field split cannot read a value as a key at all.
  #
  # ONE PROCESS FOR THE WHOLE STREAM, which is why this is `awk` and not a shell
  # loop calling `gate_row_field` per row. That loop is the obvious spelling and
  # it costs four processes per row: measured, it took the per-segment-id cost
  # from 14 processes to 18, which `test-measure-gate-cost.sh` pins exactly. The
  # expression it replaces was also a single pass, so the cost is unchanged.
  awk -F'|' '{
    for (i = 1; i <= NF; i++) {
      f = $i
      sub(/^[[:space:]]+/, "", f)
      sub(/[[:space:]]+$/, "", f)
      if (f ~ /^id=/) { print substr(f, 4); break }
    }
  }'
}

gate_report_abs() {
  # gate_report_abs <path> — an absolute path as-is; a relative one resolved two
  # levels above the manifest's directory, which is the same derivation the merge
  # rule uses (`<base>/docs/pipeline-run/<run-id>.plan.md` sits two below the base).
  # ONE helper for every reader of a `cycle` row's `리포트 경로` in this file, so
  # the delta checks below cannot resolve a relative path one way while the rule
  # resolves it another.
  case "${1:-}" in
    '')  printf '' ;;
    /*)  printf '%s' "$1" ;;
    *)   printf '%s/%s' "$(cd "$(dirname "$MANIFEST")/../.." 2>/dev/null && pwd)" "$1" ;;
  esac
}

gate_cycle_fingerprint() {
  # gate_cycle_fingerprint <absolute report path> <P0> <P1> — the value of the
  # `발견 지문` field the `cycle` arm writes: `-` when P0 and P1 are both zero,
  # `(미상)` when the report is absent or yields no identifier, and otherwise
  # the first 12 hex characters of the sha256 of the report's finding
  # identifiers. Always returns 0: the VALUE refuses nothing.
  #
  # A SET, NOT A LIST. The identifiers are sorted and de-duplicated before they
  # are hashed. As a list, a report that names the same file in two bullets
  # hashes differently from one that names it once, and a repetition that really
  # happened stops looking like one.
  #
  # THE HEADING MATCHER IS A BYTE PREFIX, NOT A REGEX: a section opens only on a
  # line that begins `## 🔴 P0` or `## 🟠 P1`, and any other `## ` heading closes
  # it. The emoji are octal escapes so the bytes of this source do not depend on
  # the locale. A template change nobody foresaw makes the matcher find nothing,
  # and the field then reads `(미상)` — it fails toward fewer labels, never
  # toward a false one.
  #
  # IDENTIFIER GUARD AND SPELLING FOLD, BOTH INSIDE ONE REPORT. A token with
  # neither `/` nor `.`, or `##`, is a table or quote fragment and is dropped.
  # A bare identifier that another identifier of the same report ends in
  # `/<identifier>` is the same file spelt short and is dropped. Spellings are
  # never folded ACROSS reports.
  #
  # The value is fixed on the row when the row is written, so a later report
  # overwritten at the same path does not change a past reading.
  local rep=$1 p0=$2 p1=$3 ids
  case "$p0" in
    ''|*[!0]*) : ;;
    *) case "$p1" in
         ''|*[!0]*) : ;;
         *) printf -- '-'; return 0 ;;
       esac ;;
  esac
  if [ -z "$rep" ] || [ ! -f "$rep" ]; then
    printf '(미상)'
    return 0
  fi
  ids=$(gate_report_finding_ids "$rep" 0)
  if [ -z "$ids" ]; then
    printf '(미상)'
    return 0
  fi
  printf '%s\n' "$ids" | LC_ALL=C sort -u | shasum -a 256 | cut -c1-12
}

gate_cycle_p0_fingerprint() {
  # gate_cycle_p0_fingerprint <absolute report path> — the `P0잔존` component
  # of one segment: `gate_cycle_fingerprint`'s value taken over the bullets
  # under the P0 heading alone. `(미상)` when the report is absent or its P0
  # section yields no identifier. Always returns 0.
  #
  # P0 ONLY, BY HEADING AND NOT BY COUNT. The `발견 지문` of the cycle row mixes
  # both headings whatever the counts say, so a re-check that kept the same P0
  # and changed its P1 bullets read as a different defect. An empty P0 section
  # never borrows a value from the P1 section: a component the P0 bullets do
  # not determine is `(미상)`, which stops the chain.
  local rep=$1 ids
  if [ -z "$rep" ] || [ ! -f "$rep" ]; then
    printf '(미상)'
    return 0
  fi
  ids=$(gate_report_finding_ids "$rep" 1)
  if [ -z "$ids" ]; then
    printf '(미상)'
    return 0
  fi
  printf '%s\n' "$ids" | LC_ALL=C sort -u | shasum -a 256 | cut -c1-12
}

gate_report_finding_ids() {
  # gate_report_finding_ids <report> <p0 only: 0|1> — the report's finding
  # identifiers, one per line, after the guard and the spelling fold that
  # `gate_cycle_fingerprint` describes; nothing when there is none. With 1 only
  # the P0 heading opens a section. The two fingerprints share this walk so a
  # change to the identifier rule moves both.
  LC_ALL=C awk -v p0only="$2" '
    function ident(b,   tok, rest, sym) {
      if (!match(b, /`[^`]+`/)) return ""
      tok = substr(b, RSTART + 1, RLENGTH - 2)
      rest = substr(b, RSTART + RLENGTH)
      sub(/[: ].*$/, "", tok)
      if (tok == "" || tok == "##") return ""
      if (index(tok, "/") == 0 && index(tok, ".") == 0) return ""
      if (match(rest, /^ ?\(`[^`]+`\)/)) {
        sym = substr(rest, RSTART, RLENGTH)
        gsub(/[ (`)]/, "", sym)
        tok = tok "#" sym
      }
      return tok
    }
    /^## / {
      inl = (index($0, "## \360\237\224\264 P0") == 1 || (p0only != 1 && index($0, "## \360\237\237\240 P1") == 1))
      next
    }
    inl && /^- / {
      t = ident($0)
      if (t != "" && !(t in seen)) { seen[t] = 1; ord[++n] = t }
    }
    END {
      for (i = 1; i <= n; i++) {
        a = ord[i]; drop = 0
        for (j = 1; j <= n; j++) {
          b = ord[j]
          if (j == i || length(b) < length(a) + 1) continue
          if (substr(b, length(b) - length(a)) == "/" a) { drop = 1; break }
        }
        if (!drop) print a
      }
    }' "$1" 2>/dev/null || true
}

gate_review_report_counts() {
  # gate_review_report_counts <report> — THE ONE PARSER of a review report's
  # counts and P1 classification. Every reader that needs a number or a
  # classification out of a report takes it from here, so the cycle arm, the
  # carry-over eligibility and the driver cannot read one report two ways.
  # Prints `key=value` lines and returns 0; returns 1 when the file is absent.
  #
  #   요약=정규|복구|없음   the first summary line: canonical, the recovery head
  #                         `발견 요약(부분 복구)`, or none at all
  #   P0= P1=               its numbers, only when 요약=정규
  #   리뷰 HEAD=            the sha of the `- **리뷰 HEAD**: \`<sha>\`` line
  #   분류=정규|미상        whether the `P1 분류` line parses; 차단= 이월 가능=
  #                         follow only when it does
  #   몫=<n>|미상           the `다른 슬라이스 몫` line; absent reads 0
  #   태그=정규|미상        whether every tag line of the P1 section keeps the
  #                         rules below; 태그 차단= 태그 이월 가능= count them
  #   본문=정규|미상        whether every carry-over item passes the body checks
  #   몫 항목=<n>           items of the other-slice section; 배정=<id> per
  #                         line of that section carrying `**배정**`, `(미상)`
  #                         unless it is exactly `    - **배정**: 슬라이스 <id>`
  #                         with nothing or ` — …` after the id
  #   몫 배정=정규|미상     whether every item of that section carries exactly
  #                         one such line and no such line stands outside an
  #                         item
  #   이월 <k> 제목=        title of the k-th carry-over item, in tag order
  #   이월 <k> 본문=        one line per body line, the six-space indent removed
  #   결함 수준=정규|미상   whether the `결함 수준` lines of a re-check report
  #                         parse; 결함 수준 설계= 결함 수준 구현= follow only
  #                         when they do
  #
  # DEFECT LEVEL. A re-check review writes one summary line
  # `- **결함 수준**: 설계 N건 | 구현 N건` and, under every item it counts as a
  # residual, one line `    - **결함 수준**: 설계 — …` or `구현 — …`. It is
  # `정규` only when the summary parses, its two numbers equal the item lines of
  # each kind, and their sum equals the residual count — P0 plus the blocking P1
  # when the P1 classification parses, P0 plus every P1 when it does not.
  # Anything else is `미상`, which the `다음` table reads as no design-level
  # item. Unlike the other counts, `미상` here never refuses the cycle row: a
  # malformed line must not stop the ladder, only send it the cheaper way.
  #
  # TAG LINES. Inside the P1 section — from a line that begins `## 🟠 P1` to the
  # next line that begins `## ` — any line carrying `**[차단]**` or
  # `**[이월 가능]**` is a tag line. It must begin `- ` or `### ` and carry one
  # token exactly once; anything else makes the report `분류 미상`. So a parser
  # that counts every line carrying a token and one that counts only `- ` and
  # `### ` tag lines reach the same verdict on every report.
  #
  # ITEM RANGE. A carry-over item runs from its tag line to the line before the
  # next tag line, or to the end of the section. Its `이월 제목` and `이월 본문`
  # are matched at four spaces of indentation and its body lines at exactly six,
  # in both item shapes; a line written otherwise is not one of them. The body
  # ends at the first line that is not six spaces and a non-space.
  #
  # The emoji are octal escapes and the read runs under `LC_ALL=C`, the same as
  # `gate_cycle_fingerprint`, so the bytes matched do not depend on the locale.
  local rep=$1
  [ -n "$rep" ] && [ -f "$rep" ] || return 1
  LC_ALL=C awk '
    function cnt(s, t,   n, p) {
      n = 0
      while ((p = index(s, t)) > 0) { n++; s = substr(s, p + length(t)) }
      return n
    }
    function num(s, key,   v) {
      if (!match(s, key " [0-9]+")) return ""
      v = substr(s, RSTART + length(key) + 1, RLENGTH - length(key) - 1)
      return v + 0
    }
    BEGIN {
      R = "\360\237\224\264"; O = "\360\237\237\240"
      Y = "\360\237\237\241"; G = "\360\237\237\242"
      TB = "**[차단]**"; TC = "**[이월 가능]**"
      summ = ""; cls = ""; share = ""; head = ""; sec = ""
      bad = 0; nb = 0; nc = 0; ns = 0; na = 0; cur = ""; inbody = 0
      dl = ""; dlbad = 0; dls = 0; dli = 0
    }
    { line = $0; sub(/[ \t\r]+$/, "", line) }
    index(line, "## ") == 1 {
      if (index(line, "## " O " P1") == 1) sec = "p1"
      else if (index(line, "## 다른 슬라이스 몫") == 1) sec = "share"
      else sec = ""
      cur = ""; inbody = 0
      next
    }
    summ == "" && index(line, "- **발견 요약(부분 복구)**:") == 1 { summ = "복구"; next }
    summ == "" && index(line, "- **발견 요약**: ") == 1 {
      s = line
      gsub(R, "@R", s); gsub(O, "@O", s); gsub(Y, "@Y", s); gsub(G, "@G", s)
      if (s ~ /^- \*\*발견 요약\*\*: @R P0 [0-9]+건 \| @O P1 [0-9]+건 \| @Y P2 [0-9]+건 \| @G P3 [0-9]+건/) {
        summ = "정규"; p0 = num(s, "P0"); p1 = num(s, "P1")
      }
      next
    }
    cls == "" && index(line, "- **P1 분류**:") == 1 {
      if (line ~ /^- \*\*P1 분류\*\*: 차단 (0|[1-9][0-9]*)건 \| 이월 가능 (0|[1-9][0-9]*)건$/) {
        cls = "정규"; split(line, w, " "); cb = w[5]; cc = w[9]
        sub(/건$/, "", cb); sub(/건$/, "", cc)
      } else cls = "미상"
      next
    }
    share == "" && index(line, "- **다른 슬라이스 몫**:") == 1 {
      if (line ~ /^- \*\*다른 슬라이스 몫\*\*: (0|[1-9][0-9]*)건 \(집계 제외\)$/) {
        split(line, w, " "); share = w[5]; sub(/건$/, "", share)
      } else share = "미상"
      next
    }
    head == "" && line ~ /^- \*\*리뷰 HEAD\*\*: `[0-9a-f]+`$/ {
      head = line; sub(/^[^`]*`/, "", head); sub(/`$/, "", head)
      next
    }
    index(line, "- **결함 수준**:") == 1 {
      if (dl != "") dlbad = 1
      else if (line ~ /^- \*\*결함 수준\*\*: 설계 (0|[1-9][0-9]*)건 \| 구현 (0|[1-9][0-9]*)건$/) {
        split(line, w, " "); ds = w[5]; di = w[8]
        sub(/건$/, "", ds); sub(/건$/, "", di); dl = "정규"
      } else { dl = "미상"; dlbad = 1 }
      next
    }
    index(line, "**결함 수준**:") > 0 {
      if (line ~ /^    - \*\*결함 수준\*\*: 설계 — ./) dls++
      else if (line ~ /^    - \*\*결함 수준\*\*: 구현 — ./) dli++
      else dlbad = 1
      inbody = 0
      next
    }
    sec == "p1" {
      b = cnt(line, TB); c = cnt(line, TC)
      if (b + c > 0) {
        inbody = 0
        if (b + c != 1 || (index(line, "- ") != 1 && index(line, "### ") != 1)) bad = 1
        if (b) { nb++; cur = "" } else { nc++; cur = nc }
        next
      }
      if (cur == "") next
      if (inbody) {
        if (line ~ /^      [^ ]/) {
          nbody[cur]++; body[cur, nbody[cur]] = substr(line, 7)
          if (index(line, "docs/") > 0) dirty[cur] = 1
          next
        }
        inbody = 0
      }
      if (index(line, "    - **이월 제목**: ") == 1) {
        nt[cur]++; title[cur] = substr(line, length("    - **이월 제목**: ") + 1)
      } else if (line == "    - **이월 본문**:") {
        nh[cur]++; inbody = 1
      }
      next
    }
    # Every line of the section that carries `**배정**` is an assignment, at
    # whatever indentation: a line the canonical match skipped would leave its
    # item unchecked, and the item would still be dropped from the count.
    sec == "share" {
      if (index(line, "- ") == 1) { ns++; na_of[ns] = 0; next }
      if (index(line, "**배정**") == 0) next
      if (line ~ /^    - \*\*배정\*\*: 슬라이스 [A-Za-z0-9]+( — .*)?$/) {
        id = substr(line, length("    - **배정**: 슬라이스 ") + 1); sub(/ .*$/, "", id)
      } else id = "(미상)"
      as[++na] = id
      if (ns) na_of[ns]++; else stray = 1
    }
    END {
      print "요약=" (summ == "" ? "없음" : summ)
      if (summ == "정규") { print "P0=" p0; print "P1=" p1 }
      if (head != "") print "리뷰 HEAD=" head
      if (cls == "정규") { print "분류=정규"; print "차단=" cb; print "이월 가능=" cc }
      else print "분류=미상"
      print "몫=" (share == "" ? 0 : share)
      print "태그=" (bad ? "미상" : "정규")
      print "태그 차단=" nb; print "태그 이월 가능=" nc
      ok = 1
      for (k = 1; k <= nc; k++) {
        if (nt[k] != 1 || title[k] == "" || nh[k] != 1 || nbody[k] < 1 || dirty[k]) ok = 0
        else if (title[k] in seen) ok = 0
        else seen[title[k]] = 1
      }
      print "본문=" (ok ? "정규" : "미상")
      print "몫 항목=" ns
      sok = !stray
      for (k = 1; k <= ns; k++) if (na_of[k] != 1) sok = 0
      print "몫 배정=" (sok ? "정규" : "미상")
      for (k = 1; k <= na; k++) print "배정=" as[k]
      for (k = 1; k <= nc; k++) {
        if (nt[k] >= 1) print "이월 " k " 제목=" title[k]
        for (j = 1; j <= nbody[k]; j++) print "이월 " k " 본문=" body[k, j]
      }
      dok = (dl == "정규" && !dlbad && summ == "정규" && ds + 0 == dls && di + 0 == dli \
             && ds + di == p0 + (cls == "정규" ? cb : p1))
      if (dok) { print "결함 수준=정규"; print "결함 수준 설계=" ds + 0; print "결함 수준 구현=" di + 0 }
      else print "결함 수준=미상"
    }' "$rep" 2>/dev/null
}

gate_report_count() {
  # gate_report_count <counts> <key> — the first value of <key> in the output
  # of `gate_review_report_counts`. Exact key, so `P1` never reads `P1 분류`.
  # No early `exit`: under `pipefail` a reader that quits first can fail the
  # pipeline it sits in, and a value that is there reads as absent.
  printf '%s\n' "$1" | GATE_FEQ_K="$2" awk '
    !got { p = index($0, "=")
           if (p && substr($0, 1, p - 1) == ENVIRON["GATE_FEQ_K"]) { print substr($0, p + 1); got = 1 } }'
}

gate_review_report_shape() {
  # gate_review_report_shape <report> — the item shape of a review report's P0
  # and P1 sections, read beside THE ONE PARSER above: the summary, its numbers
  # and the `리뷰 HEAD` line are taken from `gate_review_report_counts`, so the
  # two cannot read the summary two ways, and only the item walk is new here.
  # Prints `key=value` lines and returns 0; returns 1 when the file is absent.
  #
  #   요약=정규|복구|없음   as the counts read it
  #   요약 P0= 요약 P1=     the summary's numbers, only when 요약=정규
  #   리뷰 HEAD=            the report's `리뷰 HEAD` line, when there is one
  #   항목=<p0>/<p1>        column-0 `- **[` lines of each section
  #   비불릿=<n>            `### ` lines inside the two sections — the old
  #                         `### P1-n` head and any other id head alike
  #   앵커 없음=<n>         items whose first backtick token is not `파일:라인`
  #   태그 밖=<n>           items whose category is not in the template's list
  #   문제=<line>: <kind>: <text>
  #                         one per problem `report-check` names, in line order
  #
  # The category is the first `**[…]**` of the item line that is not
  # `CI-CONFIRMED` or a disposition tag; `[CI-CONFIRMED]` is a marker, not a
  # category, and a backtick token reading `[CI-CONFIRMED]` is skipped when the
  # anchor is looked for. A P0 item carries no disposition tag and is not
  # flagged for it. With 요약=복구 the summary has no numbers, so the item counts
  # are not compared and a missing `리뷰 HEAD` line is not a problem — the
  # recovery arm has no head to write and nothing can stand in for it.
  local rep=$1 counts summ sp0 sp1 head
  [ -n "$rep" ] && [ -f "$rep" ] && [ -r "$rep" ] || return 1
  counts=$(gate_review_report_counts "$rep") || return 1
  summ=$(gate_report_count "$counts" '요약')
  sp0=$(gate_report_count "$counts" 'P0')
  sp1=$(gate_report_count "$counts" 'P1')
  head=$(gate_report_count "$counts" '리뷰 HEAD')
  printf '요약=%s\n' "${summ:-없음}"
  if [ "$summ" = "정규" ]; then printf '요약 P0=%s\n요약 P1=%s\n' "$sp0" "$sp1"; fi
  [ -z "$head" ] || printf '리뷰 HEAD=%s\n' "$head"
  LC_ALL=C awk -v summ="${summ:-없음}" -v sp0="$sp0" -v sp1="$sp1" -v head="$head" '
    BEGIN {
      R = "\360\237\224\264"; O = "\360\237\237\240"
      split("security performance code-quality logic error-handling type-safety testing api-contract concurrency data-integrity design-conformance", cl, " ")
      for (i in cl) okcat[cl[i]] = 1
      sec = ""; n0 = 0; n1 = 0; nh = 0; na = 0; nt = 0; np = 0; sl = 0
    }
    function prob(ln, kind, text) { pr[++np] = ln ": " kind ": " text }
    function category(s,   t) {
      while (match(s, /\*\*\[[^]]*\]\*\*/)) {
        t = substr(s, RSTART + 3, RLENGTH - 6)
        s = substr(s, RSTART + RLENGTH)
        if (t == "CI-CONFIRMED" || t == "차단" || t == "이월 가능") continue
        return t
      }
      return ""
    }
    function anchor(s,   t) {
      while (match(s, /`[^`]*`/)) {
        t = substr(s, RSTART + 1, RLENGTH - 2)
        s = substr(s, RSTART + RLENGTH)
        if (t == "[CI-CONFIRMED]") continue
        return t
      }
      return ""
    }
    { line = $0; sub(/[ \t\r]+$/, "", line) }
    sl == 0 && index(line, "- **발견 요약") == 1 { sl = NR }
    index(line, "## ") == 1 {
      if (index(line, "## " R " P0") == 1) sec = "p0"
      else if (index(line, "## " O " P1") == 1) sec = "p1"
      else sec = ""
      next
    }
    sec == "" { next }
    index(line, "### ") == 1 { nh++; prob(NR, "비불릿", line); next }
    index(line, "- **[") == 1 {
      if (sec == "p0") n0++; else n1++
      c = category(line)
      if (!(c in okcat)) { nt++; prob(NR, "태그 밖", (c == "" ? "(분류 없음)" : c)) }
      a = anchor(line)
      if (a !~ /^[^ `]+:[0-9]+(-[0-9]+)?$/) { na++; prob(NR, "앵커 없음", line) }
    }
    END {
      if (summ == "없음")
        prob(sl, "요약 없음", (sl ? "정규 발견 요약 줄의 모양이 아니다" : "발견 요약 줄이 없다"))
      if (summ == "정규") {
        if (n0 != sp0 + 0) prob(sl, "항목 수", "P0 요약 " sp0 "건, 항목 " n0 "개")
        if (n1 != sp1 + 0) prob(sl, "항목 수", "P1 요약 " sp1 "건, 항목 " n1 "개")
      }
      if (summ != "복구" && head == "") prob(0, "HEAD 줄 없음", "- **리뷰 HEAD**: 줄이 없다")
      print "항목=" n0 "/" n1
      print "비불릿=" nh
      print "앵커 없음=" na
      print "태그 밖=" nt
      for (i = 1; i <= np; i++) print "문제=" pr[i]
    }' "$rep" 2>/dev/null
}

gate_report_format_fields() {
  # gate_report_format_fields <report> <row's 리뷰 HEAD> — the seven report
  # format fields of a `cycle` row, one `key=value` per line, in row order:
  # `리포트 형식` `항목` `비불릿` `앵커 없음` `태그 밖` `요약` `HEAD 줄`. Every value
  # is a closed word or a number. They are recorded, never refused on.
  #
  # `판독 불가` when the report is absent or unreadable, and the other six read
  # `-`. Otherwise `정합` when the summary is 정규 or 복구, no head, anchor or
  # category problem is left, and — outside 복구 — the items equal the summary
  # and the head line does not differ from the row. A missing head line reads
  # `HEAD 줄=없음` and does not stop `정합`. The row carries 7 to 40 hex
  # characters and the report 40, so the row's value being a prefix is `일치`.
  local rep=$1 rhead=$2 sh summ items nh na nt sp0 sp1 head hl fmt
  if ! sh=$(gate_review_report_shape "$rep"); then
    printf '리포트 형식=판독 불가\n항목=-\n비불릿=-\n앵커 없음=-\n태그 밖=-\n요약=-\nHEAD 줄=-\n'
    return 0
  fi
  summ=$(gate_report_count "$sh" '요약')
  items=$(gate_report_count "$sh" '항목')
  nh=$(gate_report_count "$sh" '비불릿')
  na=$(gate_report_count "$sh" '앵커 없음')
  nt=$(gate_report_count "$sh" '태그 밖')
  sp0=$(gate_report_count "$sh" '요약 P0')
  sp1=$(gate_report_count "$sh" '요약 P1')
  head=$(gate_report_count "$sh" '리뷰 HEAD')
  if [ -z "$head" ]; then hl='없음'
  elif [ -n "$rhead" ] && [ "${head#"$rhead"}" != "$head" ]; then hl='일치'
  else hl='다름'
  fi
  fmt='불일치'
  case "$summ" in
    정규|복구)
      if [ "$nh" = 0 ] && [ "$na" = 0 ] && [ "$nt" = 0 ]; then
        if [ "$summ" = "복구" ]; then fmt='정합'
        elif [ "$items" = "$sp0/$sp1" ] && [ "$hl" != "다름" ]; then fmt='정합'
        fi
      fi ;;
  esac
  printf '리포트 형식=%s\n항목=%s\n비불릿=%s\n앵커 없음=%s\n태그 밖=%s\n요약=%s\nHEAD 줄=%s\n' \
    "$fmt" "$items" "$nh" "$na" "$nt" "$summ" "$hl"
}

gate_verb_report_check() {
  # gate_verb_report_check <report> — the `report-check` verb. One
  # `<줄>: <종류>: <문면>` line per problem `gate_review_report_shape` finds, then
  # exit 0 when there is none, or the last line `report-check: 불일치 <n>` and
  # exit 1. THAT LAST LINE IS THE VERDICT, NOT THE CODE: `die` of the sourced
  # driver also exits 1, so a 1 without the line is a gate failure and the
  # review lead ends the stage without editing. An absent or unreadable report
  # is refused (3) — it is not a report with problems. Reads only.
  local rep=$1 sh probs n
  case "$rep" in
    /*) : ;;
    *) warn "report-check needs an absolute --report path (received: $rep)"; exit "$GATE_EXIT_VOCAB" ;;
  esac
  if ! sh=$(gate_review_report_shape "$rep"); then
    warn "report-check: no readable report at $rep"
    exit "$GATE_EXIT_RULE"
  fi
  probs=$(printf '%s\n' "$sh" | sed -n 's/^문제=//p')
  if [ -z "$probs" ]; then
    exit 0
  fi
  printf '%s\n' "$probs"
  n=$(printf '%s\n' "$probs" | gate_count)
  printf 'report-check: 불일치 %s\n' "$n"
  exit 1
}

gate_problem_identities() {
  # Every distinct identity a `problem` row has ever carried, disposed or not.
  #
  # `LC_ALL=C` here and at every other `sort -u` over a FIELD VALUE. These sorts
  # are set operations, not presentation, and `-u` drops whatever collation calls
  # equal — the `en_US.UTF-8` collation orders no Hangul, so two different Korean
  # values compare equal and one of them disappears. `동일성` is Korean free text
  # by contract, so this is the sort where it bites hardest: distinct problems
  # would merge into one, the cone built from them would be wrong, and every
  # check over it would report success.
  gate_rows 'problem' \
    | tr '|' '\n' | sed -n 's/^ *동일성=//p' | sed 's/[[:space:]]*$//' \
    | LC_ALL=C sort -u | grep -v '^$' || true
}

gate_obligation_id() {
  # gate_obligation_id <identity> — `PO-<8 hex>`, derived and never stored.
  #
  # DERIVED FROM THE FREE-TEXT IDENTITY, and deliberately not from any row's
  # chain predecessor. An obligation is the BUNDLE of problem rows sharing an
  # identity and that bundle crosses segments, so no single row's `prev=` can
  # name it — the row anchor is a different derived value answering a different
  # question, and conflating the two would make the closing row point at one row
  # of a bundle instead of at the bundle.
  #
  # Reading it rather than storing it is what lets a problem row written before
  # this verb existed be closed with no migration: the identity is already in the
  # ledger and the id is a function of it.
  #
  # `RUN_ID` is in the preimage so the value is scoped to this run, which is the
  # scope an obligation has.
  printf 'PO-%s' "$(printf '%s|%s' "$RUN_ID" "$1" | shasum -a 256 | cut -c1-8)"
}

gate_obligation_display() {
  # The identity, truncated, for a person reading the morning. NO PREDICATE READS
  # THIS — the row line has a 1024-byte cap and a free-text identity cannot be
  # carried verbatim, so a truncated copy would be an unsafe key and a useful
  # label. It is carried as the label only.
  printf '%s' "$1" | cut -c1-60
}

gate_obligation_disposed() {
  # gate_obligation_disposed <identity> <series> — a closing row of that series
  # names this obligation.
  #
  # MATCHED AS A WHOLE FIELD, `| 의무 id=<id> |`, the same discipline the approval
  # id lookups hold. A substring match read the closing row's free-text `근거` as
  # well: writing `근거=A-<유효> 의무 id=PO-<다른 의무>` closed that other
  # obligation too, with none of the evidence, order, collision or reuse checks
  # run for it. `gate_append` strips pipes from every value, so a `|`-bounded
  # match can only land on the field the gate itself wrote.
  gate_has_row "$2" "| 의무 id=$(gate_obligation_id "$1") |"
}

gate_obligation_disposition() {
  # gate_obligation_disposition <identity> — `종결`, `포기`, `면제`, or empty.
  #
  # ORDERED BY TENSE, and the order is what makes `포기` re-verifiable. A `종결`
  # row cites a past act, so nothing about it can be withdrawn and it is reported
  # first. A `포기` row cites a CURRENT segment state, so it is honoured only
  # while that state still holds — this is the re-verification the design puts at
  # exclusion time rather than at write time, because a row checked only when it
  # was written is a permanent verdict standing on a reversible field, which is
  # the amnesty defect this file opens with.
  local ident="$1"
  if gate_obligation_disposed "$ident" '의무 종결'; then printf '종결'; return 0; fi
  if gate_obligation_disposed "$ident" '의무 포기'; then
    if gate_obligation_segments_terminal "$ident"; then printf '포기'; return 0; fi
    return 0
  fi
  if gate_obligation_excused "$ident"; then printf '면제'; return 0; fi
  return 0
}

gate_obligation_segments_terminal() {
  # gate_obligation_segments_terminal <identity> — EVERY problem row carrying the
  # identity sits in a terminal segment, judged now.
  #
  # Universally quantified for the same reason the excusal is: the bundle crosses
  # segments, and reading one row's segment lets a later row naming a parked
  # segment decide for rows that are not parked at all.
  local ident="$1" rows row seg st n=0
  rows=$( { gate_rows 'problem' | grep -F "동일성=$ident " || true; } )
  [ -n "$rows" ] || return 1
  while IFS= read -r row; do
    [ -n "$row" ] || continue
    n=$((n + 1))
    seg=$(gate_row_field "$row" '세그먼트')
    [ -n "$seg" ] || return 1
    st=$(gate_segment_field "$seg" '상태')
    case " $TERMINAL_SEGMENT_STATES " in
      *" $st "*) : ;;
      *) return 1 ;;
    esac
  done <<GATE_OBL_SEGS
$rows
GATE_OBL_SEGS
  [ "$n" -gt 0 ]
}

gate_open_obligations() {
  # The identities with NO disposition. Three dispositions subtract here —
  # `종결`, `포기` and `면제` — and until this slice there were none: the function
  # emitted every problem identity unconditionally, so an obligation could be
  # opened and never closed by anything.
  #
  # THE OLD COMMENT PROMISED SOMETHING NO CODE DID. It said a later `cycle` row
  # for the same segment closes the obligation; nothing here ever read a `cycle`
  # row. That design is not implemented now either, and the reasons are three.
  # Silence is the cheapest output, so a router writing the minimum would close
  # every obligation while asserting nothing. The aggregation keys do not line up
  # — the described scheme is scoped by segment while this function bundles by
  # identity ACROSS segments. And it does not resolve the incident that exposed
  # the defect. Being written down does not create an obligation to implement it.
  local ident
  gate_problem_identities | while IFS= read -r ident; do
    [ -n "$ident" ] || continue
    if [ -z "$(gate_obligation_disposition "$ident")" ]; then
      printf 'obligation=%s\n' "$ident"
    fi
  done
  return 0
}

gate_obligation_evidence_anchors() {
  # gate_obligation_evidence_anchors <근거> — the pointers a rationale names, from
  # a CLOSED SET of four forms: a row anchor `A-<8 hex>`, an approval id
  # `J-<8 hex>`, a review-obligation id `RO-<8 hex>`, and a segment id declared in
  # this ledger.
  #
  # PROSE ALONE YIELDS NOTHING, which is the point. "확인했다" is the most
  # convincing sentence a person can read and is nothing at all to the gate;
  # admitting it would make the whole evidence requirement decorative.
  #
  # Tokenised by complementing the identifier alphabet rather than by a word
  # boundary — `\b` is a GNU extension and this file runs on both hosts.
  local why="$1" segs toks t
  segs=" $(gate_rows 'segment' | sed -n 's/.*id=\([^|]*\).*/\1/p' \
           | sed 's/[[:space:]]*$//' | LC_ALL=C sort -u | tr '\n' ' ')"
  toks=$(printf '%s' "$why" | tr -c 'A-Za-z0-9_-' '\n' | { grep -v '^$' || true; })
  printf '%s\n' "$toks" | while IFS= read -r t; do
    [ -n "$t" ] || continue
    case "$t" in
      A-*|J-*)
        # THE DIGIT SHAPE IS CHECKED WITH A GLOB, not through a pipe. `grep -q`
        # stops at the first match and kills the writer with SIGPIPE, and under
        # `pipefail` the pipeline then reports failure even though the match was
        # found — so a well-formed anchor could come back as unrecognised, and an
        # empty answer here is what refuses a rationale outright. The segment arm
        # below already answers its own question with a `case`, and the prefix is
        # already established by the arm this sits in, so what is left to test is
        # exactly eight hex digits.
        case "${t#?-}" in
          [0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f])
            printf '%s\n' "$t" ;;
        esac ;;
      RO-*)
        # The same shape the issuer derives (`RO-` plus eight hex digits). With
        # no shape check a bare `RO-` or any extension of a real id passed here
        # and was then resolved by a substring search.
        case "${t#RO-}" in
          [0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f])
            printf '%s\n' "$t" ;;
        esac ;;
      *)
        case "$segs" in *" $t "*) printf '%s\n' "$t" ;; esac ;;
    esac
  done
  return 0
}

gate_evidence_row_line() {
  # gate_evidence_row_line <anchor> — the ledger line of the row that DECLARES
  # the object the anchor names, or empty when it names nothing.
  #
  # A row anchor addresses by the chain predecessor every row already carries, so
  # every row in the ledger is addressable with no schema change at all.
  #
  # EVERY ARM RESOLVES TO A DECLARING ROW, never to wherever the token happens to
  # appear. The three id arms used to search the whole ledger and take the LAST
  # match, so an object older than the problem row passed the order check the
  # moment any later row — a `근거`, a payload — merely mentioned it. The anchor
  # is supposed to name an OBJECT:
  #   - `A-` is the row whose own chain field (`| prev=` at the end of the row)
  #     begins with those digits;
  #   - `J-` is the `승인` row carrying it as `| 승인 id=… |`;
  #   - `RO-` is the `리뷰 의무` row carrying it as `| 의무 id=… |`.
  # For those three the FIRST declaring row is taken: an approval or a review
  # obligation is born on its first row, and its later transition rows are the
  # object being re-stated, not re-created. Taking the first also makes the answer
  # a fixed function of an append-only file, which the reuse check below relies on.
  #
  # THE SEGMENT ARM RESOLVES TO THE SEGMENT'S OWN ROW, not to the last line the
  # identifier happens to appear on. A segment id is stamped on nearly every row
  # of that segment, so a whole-ledger match answered with the identifier's LAST
  # occurrence — which is later than almost anything, and so satisfied the order
  # check for free. The row that declares the object is the `segment` row
  # carrying it as `id=`; its LAST such row stays the answer, because a segment's
  # later state row is the segment advancing, which is what that anchor cites.
  # The id is compared as the row's `id` FIELD, split the way `gate_row_ids`
  # splits it, not as a substring: `id=S1 ` also sits inside a value that merely ends in `id=`, such
  # as a quoted `headRefOid=`, and that row is not the segment's.
  #
  # A RESIDUAL THIS DOES NOT CLOSE. The rows a closing act itself writes — the
  # `의무 종결`/`의무 포기` row and the `자율 승인` row after it — are rows like any
  # other, so an `A-` anchor on them is well formed and later than an older
  # problem row. One closing act can therefore supply the anchor for the next.
  # Excluding them would change which rows the layer-1 contract admits, and that
  # contract says every row is addressable; the chain is instead visible in the
  # terminal enumeration, where each closing row's anchor sits beside it.
  #
  # `sed -n 1p` AND NOT `head -1` for the first match: `head` exits early, the
  # writer takes SIGPIPE, and `pipefail` then reports a found row as a failure.
  local tok="$1" hits
  case "$tok" in
    A-*) hits=$( { grep -nE " \\| prev=${tok#A-}[0-9a-f]*\$" "$LEDGER" 2>/dev/null || true; } \
                | { grep '^[0-9][0-9]*:- `' || true; } | sed -n 1p) ;;
    J-*) hits=$( { grep -n '^- `승인`' "$LEDGER" 2>/dev/null || true; } \
                | { grep -F "| 승인 id=$tok |" || true; } | sed -n 1p) ;;
    RO-*)
         hits=$( { grep -n '^- `리뷰 의무`' "$LEDGER" 2>/dev/null || true; } \
                | { grep -F "| 의무 id=$tok |" || true; } | sed -n 1p) ;;
    *)   hits=$( { grep -n '^- `segment`' "$LEDGER" 2>/dev/null || true; } \
                | LC_ALL=C awk -F'|' -v t="$tok" '{
                    for (i = 1; i <= NF; i++) {
                      f = $i
                      sub(/^[[:space:]]+/, "", f)
                      sub(/[[:space:]]+$/, "", f)
                      if (f ~ /^id=/) { if (substr(f, 4) == t) print; break }
                    }
                  }' | tail -1) ;;
  esac
  printf '%s\n' "$hits" | { grep '^[0-9][0-9]*:- `' || true; } | cut -d: -f1
}

gate_evidence_object_key() {
  # gate_evidence_object_key <anchor> — what the anchor names, as a value two
  # spellings of the same object compare equal on.
  #
  # The three id arms answer with their declaring row's line: first declaration
  # in an append-only file, so the answer never moves, and two anchors naming the
  # same row — an `A-` and a `J-` for one approval row, say — collide as they
  # should. A segment answers with its id, because its resolved row is the LAST
  # segment row and would move as the segment advances.
  #
  # AN `A-` THAT LANDS ON A `segment` ROW ANSWERS WITH THAT ROW'S SEGMENT ID, so
  # it collides with the bare segment token. Keyed by line it did not: `근거=S1`
  # closed one obligation and `A-<prefix of an S1 segment row>` closed another,
  # two spellings of one object, each passing the reuse check against the other.
  local line row
  case "$1" in
    A-*|J-*|RO-*)
      line=$(gate_evidence_row_line "$1")
      case "$1" in
        A-*)
          if [ -n "$line" ]; then
            row=$(sed -n "${line}p" "$LEDGER" 2>/dev/null || true)
            case "$row" in
              '- `segment` '*)
                printf 'S%s' "$(printf '%s\n' "$row" | gate_row_ids)"
                return 0 ;;
            esac
          fi ;;
      esac
      printf 'L%s' "$line" ;;
    *) printf 'S%s' "$1" ;;
  esac
}

gate_problem_last_line() {
  # gate_problem_last_line <identity> — the ledger line of the last problem row
  # carrying it. The ORDER CHECK measures against this line.
  { grep -n '^- `problem`' "$LEDGER" 2>/dev/null || true; } \
    | { grep -F "동일성=$1 " || true; } | tail -1 | cut -d: -f1
}

gate_ledger_damage() {
  # Rows that do not parse as rows. Never silently zero: a skipped row could be
  # the cycle row carrying the P0 that the merge rule reads, and skipping it
  # makes a live defect look resolved.
  local n total
  # Pinned for the same reason as the chain walk, and it is not optional here
  # either: `grep` on an invalid byte under a UTF-8 locale can fail outright, and
  # this reader's caller interpolates its output into the snapshot object. A
  # reader that dies mid-object truncates the JSON, so the ledger's DAMAGE COUNT
  # — the field whose whole job is to report a malformed ledger — became
  # unreadable on exactly the ledgers it exists to describe.
  local LC_CTYPE=C; export LC_CTYPE
  n=$(grep -E '^- `[^`]+`( \|.*)?$' "$LEDGER" 2>/dev/null | gate_count)
  total=$(grep -E '^- `' "$LEDGER" 2>/dev/null | gate_count)
  printf '%s' $(( total - n ))
}

# ---------------------------------------------------------------------------
# Per-target cutpoint adjudication.
#
# `authorized()` is deliberately NOT used. It takes one argument, reads the
# grant's run-level maximum, and no call site passes a target — so a run
# declaring `frontend: PR` alongside `infra: 배포` authorizes deploy-grade acts
# against the front end. That is filed as Nharu/cc-cmds#208. The value that
# authorizes an act is the one on that act's target row, and this reads it there.
# ---------------------------------------------------------------------------
# The gate resolves the vocabulary — it holds run.sh's tables — and the catalog
# decides. Keeping the comparison here as well would put the same rule in two
# places, and the one that drifts is the one nobody is looking at.
gate_export_cutpoints() {
  # gate_export_cutpoints <alias> <act-token>
  local alias="$1" act="$2" tgt
  GATE_ACT_INDEX=$(cutpoint_index "$act") || return "$GATE_EXIT_VOCAB"
  tgt=$(target_field "$alias" '절단점')
  [ -n "$tgt" ] || { warn "the cutpoint of target '$alias' is not in the manifest"; return 1; }
  GATE_TARGET_CUTPOINT="$tgt"
  GATE_TARGET_INDEX=$(cutpoint_index "$tgt") || return "$GATE_EXIT_VOCAB"
  # The merge rung as an integer, for checkers that fire at merge OR ABOVE. A
  # checker comparing the token would need its own copy of the ladder order to
  # know what "above" means, and a second copy of an order is the drift this
  # exporter exists to prevent — so the gate, which holds the table, resolves it
  # and the checker compares two integers.
  GATE_MERGE_INDEX=$(cutpoint_index '머지') || return "$GATE_EXIT_VOCAB"
  export GATE_ACT_INDEX GATE_TARGET_CUTPOINT GATE_TARGET_INDEX GATE_MERGE_INDEX
  return 0
}

# gate_resolve_review_policy <segment> <alias>
#
# Resolves this act's review policy and publishes it to the rule checkers, which
# are separate `/bin/sh` processes and have no other way to learn it. Same
# division of labour as the cutpoint exporter directly above: the gate holds
# run.sh's tables and resolves the vocabulary, the catalog decides.
#
# The effective value comes from the ledger's segment row, the ceiling from the
# manifest's target row. ABSENCE IS THE STRICT VALUE on both sides, and on the
# segment side that is not "the default" — the segment arm of `gate_record_row`
# carries the field forward on every write, so a row with no value is a segment
# that never had one.
#
# EXCEEDING THE CEILING IS A REFUSAL AND NOT A CLAMP. Quietly tightening makes a
# forged row and a conservative row indistinguishable in the ledger.
#
# This runs on EVERY act and BEFORE the rule loop. Behind the loop there would
# be nothing for the checkers to read; behind `gate_rule_enabled` it would be
# something `끔` could switch off, and the ceiling is the one part of this axis
# that a manifest may not turn off — that is the whole reason it lives here and
# not inside a checker.
gate_resolve_review_policy() {
  local seg="$1" alias="$2" kind="$3" pol ceil apol api
  shift 3
  pol=$(gate_segment_field "$seg" '리뷰 정책')
  [ -n "$pol" ] || pol='선리뷰후머지'
  ceil=$(target_field "$alias" '리뷰 정책 상한')
  [ -n "$ceil" ] || ceil='선리뷰후머지'
  GATE_REVIEW_POLICY_INDEX=$(review_policy_index "$pol") || {
    warn "the review policy token of segment '$seg' is not in the vocabulary: '$pol'"
    return "$GATE_EXIT_VOCAB"
  }
  GATE_REVIEW_CEILING_INDEX=$(review_policy_index "$ceil") || {
    warn "the review policy ceiling token of target '$alias' is not in the vocabulary: '$ceil'"
    return "$GATE_EXIT_VOCAB"
  }
  # THE TIGHTENING ROW IS ALWAYS WRITABLE. This resolution runs before the rule
  # loop AND before the ledger writer, so a segment row that already carries a
  # value above the ceiling had no verb left to repair it: writing the corrected
  # row needs `act --kind segment` on that same id, and that act re-enters here
  # and is refused on the OLD value first. The segment then stays in a
  # non-terminal state, termination condition 1 never holds, and the run has no
  # ending it can propose. Keying the row on a different segment does not reach
  # the stuck id, so nothing else could unstick it.
  #
  # So the ONE act that can repair it resolves from its own argv instead of from
  # the prior row — and only when that argv is at or below the ceiling. Relaxing
  # past the ceiling is refused exactly as before, so the property the refusal
  # protects is untouched: what changes is only that the direction which restores
  # compliance stops being unreachable.
  if [ "$kind" = "segment" ]; then
    apol=$(gate_field_of '리뷰 정책' "$@")
    if [ -n "$apol" ] && api=$(review_policy_index "$apol" 2>/dev/null) \
       && [ "$api" -le "$GATE_REVIEW_CEILING_INDEX" ]; then
      pol="$apol"
      GATE_REVIEW_POLICY_INDEX="$api"
    fi
  fi
  if [ "$GATE_REVIEW_POLICY_INDEX" -gt "$GATE_REVIEW_CEILING_INDEX" ]; then
    warn "the review policy '$pol' of segment '$seg' exceeds the ceiling '$ceil' of target '$alias' — a ceiling violation is refused, not tightened into place"
    return "$GATE_EXIT_VOCAB"
  fi
  GATE_REVIEW_POLICY="$pol"
  export GATE_REVIEW_POLICY GATE_REVIEW_POLICY_INDEX GATE_REVIEW_CEILING_INDEX
  return 0
}

# ---------------------------------------------------------------------------
# Rule catalog.
#
# A rule is a `.rule` declaration plus a checker script, and the loader reads
# the pair. A declaration whose checker is missing is not loaded at all, so
# "declared but unenforceable" is not a state this catalog can be in — which is
# the property the design asked for and the reason the catalog is a directory
# rather than a table.
# ---------------------------------------------------------------------------
gate_rules_dir() { printf '%s/rules' "$GATE_DIR"; }

gate_rule_order() {
  # Declaration paths, ascending by `순서:`. A declaration with no `순서:` sorts
  # last rather than being dropped — a rule missing one field is still a rule,
  # and silently unloading it is the "declared but unenforceable" state this
  # catalog is shaped to make impossible.
  local d f n
  d=$(gate_rules_dir)
  for f in "$d"/*.rule; do
    [ -f "$f" ] || continue
    # Quit AFTER a match, not on the first line: `/./q` tests the pattern
    # space, which is never empty, so it ends the script before the address
    # that matters is ever reached.
    n=$(sed -n '/^순서:/{s/^순서: *\([0-9][0-9]*\).*/\1/p;q;}' "$f")
    [ -n "$n" ] || n=999
    printf '%s\t%s\n' "$n" "$f"
  done | sort -n | cut -f2
}

gate_rule_enabled() {
  # A rule is on unless the manifest turns it off. FOUR ignore the setting, and
  # the `case` below is the list: `절단점-준수`, `사전-인가-대조`,
  # `인가-자기확장-금지` and `리뷰-후-적용`. This comment named three of them
  # while the code exempted four, which is the shape that makes an operator
  # believe a rule can be switched off when it cannot.
  #
  # The authorization record means nothing if the first two can be switched off;
  # a self-widening ban that can be switched off is not a ban at all — after the
  # first time it is turned off, the record does not even say what was turned
  # off; and `리뷰-후-적용` guards a change to the instruction file this whole
  # mechanism reads.
  #
  # `리뷰-후-머지` IS NOT ON THIS LIST and must not be added to it. What that
  # rule holds is a policy the manifest is entitled to relax, and the parts of
  # the review axis a manifest may NOT relax — the ceiling comparison and the
  # anchor check — already live outside the catalog, where `끔` cannot reach
  # them.
  local name="$1"
  case "$name" in
    절단점-준수|사전-인가-대조|인가-자기확장-금지|리뷰-후-적용) return 0 ;;
  esac
  local setting
  setting=$(manifest_field '룰 설정' "$name")
  [ "$setting" = "끔" ] && return 1
  return 0
}

gate_run_rules() {
  # gate_run_rules <act-token> <alias> <segment> <argv-string> [<preauth-argv>]
  # Returns 0 when every loaded rule passes, GATE_EXIT_RULE on the first refusal.
  # The preauthorization rule reads <preauth-argv> (`gate_preauth_argv`) when
  # it is given, so the catalog and the reach disposition compare one string.
  local act="$1" alias="$2" seg="$3" argv="$4" pargv="${5-$4}"
  local dir decl name checker
  # THE FIRST APPROVAL REQUEST NO LONGER ENDS THE CATALOG. A checker that asks
  # for an approval used to return immediately, so every rule ordered after it
  # never ran — measured: a merge with no pre-authorization row asked for
  # approval at 순서 30 and the review requirement at 순서 40 was never checked,
  # so answering the approval let the merge through with no review record. The
  # request is remembered and the loop continues; a refusal anywhere still wins,
  # because "there is something to fix" outranks "someone has to answer".
  local approval_seen=0 approval_rule=""
  dir=$(gate_rules_dir)
  [ -d "$dir" ] || return 0
  # Ordered by each declaration's `순서:` field, not by the glob. Glob order
  # over Korean filenames is arbitrary, and the first refusal is the one the
  # run reports — so under the shipped order a cutpoint violation came back as
  # "the ledger is unreadable", which sends a 3am reader to the wrong repair.
  # The cheapest and most fundamental checks go first so the reported reason is
  # the most fundamental one that holds.
  for decl in $(gate_rule_order); do
    [ -f "$decl" ] || continue
    name=$(basename "$decl" .rule)
    checker="$dir/$name.sh"
    if [ ! -f "$checker" ]; then
      warn "rule '$name' has no checker, so it is not loaded — a declaration on its own enforces nothing"
      continue
    fi
    gate_rule_enabled "$name" || continue
    local rc=0 cargv="$argv"
    [ "$name" = "사전-인가-대조" ] && cargv="$pargv"
    GATE_ACT="$act" GATE_ALIAS="$alias" GATE_SEGMENT="$seg" GATE_ARGV="$cargv" \
      GATE_LEDGER="$LEDGER" GATE_MANIFEST="$MANIFEST" GATE_GRANT="$GRANT" \
      GATE_CLAUDEMD_PROPOSAL="${GATE_CLAUDEMD_PROPOSAL:-}" \
      /bin/sh "$checker" || rc=$?
    [ "$rc" = "0" ] && continue
    # A checker may ask for an approval instead of refusing. Folding that into a
    # plain refusal is what turns "nobody is awake to ask" into "the answer is
    # no" — the collapse this design exists to undo.
    if [ "$rc" = "$GATE_EXIT_APPROVAL" ]; then
      warn "rule '$name' requires an approval wait"
      approval_seen=1
      [ -n "$approval_rule" ] || approval_rule="$name"
      continue
    fi
    warn "rule refused: $name"
    return "$GATE_EXIT_RULE"
  done
  if [ "$approval_seen" = "1" ]; then
    warn "the rule that raised the approval wait: $approval_rule (every other rule in the catalog passed)"
    return "$GATE_EXIT_APPROVAL"
  fi
  return 0
}

# ---------------------------------------------------------------------------
# Snapshot — the router's entire declared input.
#
# JSON on stdout rather than a table: a table cannot express arrays, cannot be
# canonically serialized, and cannot be validated. `--render` turns the same
# object into the human form for the terminal.
#
# Two fields are unbounded in run length and are therefore capped, with their
# true totals reported separately. Truncating a list while reporting the real
# total is safe; truncating the total is how a router concludes a P0 is gone.
# ---------------------------------------------------------------------------
readonly GATE_OBLIGATION_CAP=50

# The unmet-condition TEXT list is capped; its NUMBERS are not, and the two are
# carried together for that reason. Conditions 1 and 3 emit one line per segment
# and per obligation, so they grow with the length of the night and take the
# front of this list — which pushes the singleton tails off it, and those tails
# (the review obligation, "no termination clause parses") are exactly the answer
# to "why can this run not end". The number list is deduplicated and cannot
# exceed eleven values, so it survives any night. There is no arrangement that keeps
# the cap and drops the numbers: dropping them means dropping the cap too.
readonly GATE_UNMET_CAP=20

gate_json_escape() {
  printf '%s' "$1" | sed -e 's/\\/\\\\/g' -e 's/"/\\"/g'
}

gate_snapshot() {
  local a total shown
  printf '{\n'
  printf '  "run_id": "%s",\n' "$(gate_json_escape "$RUN_ID")"
  printf '  "goal": "%s",\n' "$(gate_json_escape "$(manifest_field '인가' '종료 지점')")"
  printf '  "goal_digest": "%s",\n' \
    "$(manifest_field '인가' '종료 지점' | shasum -a 256 | cut -d' ' -f1)"

  printf '  "targets": [\n'
  local first=1
  for a in $(target_aliases); do
    [ "$first" = "1" ] || printf ',\n'
    first=0
    printf '    {"alias": "%s", "slug": "%s", "cutpoint": "%s", "home": "%s"}' \
      "$(gate_json_escape "$a")" \
      "$(gate_json_escape "$(target_field "$a" '원격 슬러그')")" \
      "$(gate_json_escape "$(target_field "$a" '절단점')")" \
      "$(gate_json_escape "$(target_field "$a" '홈')")"
  done
  [ "$first" = "1" ] || printf '\n'
  printf '  ],\n'

  printf '  "obligations": [\n'
  total=$(gate_open_obligations | gate_count)
  shown=0
  first=1
  gate_open_obligations | awk -v cap="$GATE_OBLIGATION_CAP" 'NR<=cap' | while IFS= read -r o; do
    [ -n "$o" ] || continue
    [ "$shown" = "0" ] || printf ',\n'
    shown=1
    printf '    "%s"' "$(gate_json_escape "${o#obligation=}")"
  done
  [ "$first" = "1" ] && [ "$total" = "0" ] || printf '\n'
  printf '  ],\n'
  printf '  "obligations_total": %s,\n' "$total"

  # THE COUNT BESIDE THE ARRAY, because the array alone could not be read as a
  # number. `obligations` has carried its total since it was capped; this side
  # had only the list, so anything wanting the count — the render line, and now
  # the emitted digest — had to derive it, and two derivations of one number is
  # how two surfaces come to disagree about the same run.
  printf '  "pending_approvals_total": %s,\n' "$(gate_pending_approval_ids | gate_count)"

  printf '  "pending_approvals": [\n'
  gate_pending_approvals_json
  printf '  ],\n'

  # ANSWERED AND NOT YET CONSUMED — the array a ROUTER-driven run reads, and the
  # only consumer it has. The fixed-graph traversal reaches the same answers
  # through its own relay; a run the router drives never enters that loop, so
  # without this key an answered judgment reaches nobody there. Both readings
  # compute from the same ledger facts so they cannot disagree about which
  # answers are outstanding.
  printf '  "answered_judgments": [\n'
  gate_answered_judgments_json
  printf '  ],\n'
  printf '  "answered_halts": [\n'
  gate_answered_halts_json
  printf '  ],\n'
  # The records a shift returned to a person — read as unanswered again.
  printf '  "returned_halts": [\n'
  gate_returned_halts_json
  printf '  ],\n'
  # The shift stops no answer has reached yet — what a shift holds.
  printf '  "shift_halts": [\n'
  gate_shift_halts_json
  printf '  ],\n'
  # Each termination clause with its wording, state and open evidence request.
  printf '  "clauses": [\n'
  gate_clauses_json
  printf '  ],\n'
  # The refusals of a target's own hook, the last row of each key, each with
  # whether its condition still holds — `같음` means the same act meets the
  # same refusal, so a shift does not issue it again.
  printf '  "guard_refusals": [\n'
  gate_guard_refusals_json
  printf '  ],\n'

  # WHAT IS KEEPING THE RUN FROM ENDING, in the object the router is contracted
  # to read every turn. The top-level keys carried the goal, the targets, the
  # obligations, the approvals, the damage count and the two digests — and
  # nothing at all about the termination conditions. So a router obeying the
  # contract and reading only this could learn what blocked the end only by
  # proposing it and reading the refusal, which is finding out by doing on the
  # one question looking was supposed to answer.
  local unmet unmet_total
  unmet=$(gate_done_conditions)
  unmet_total=$(printf '%s\n' "$unmet" | grep -c . || true)
  printf '  "unmet_conditions": [\n'
  shown=0
  printf '%s\n' "$unmet" | awk -v cap="$GATE_UNMET_CAP" 'NF { c++; if (c <= cap) print }' \
    | while IFS= read -r u; do
        [ -n "$u" ] || continue
        [ "$shown" = "0" ] || printf ',\n'
        shown=1
        printf '    "%s"' "$(gate_json_escape "$u")"
      done
  [ "${unmet_total:-0}" = "0" ] || printf '\n'
  printf '  ],\n'
  printf '  "unmet_conditions_total": %s,\n' "${unmet_total:-0}"
  # UNCAPPED, and that is the point of carrying it beside the capped list. It is
  # deduplicated, ascending, and cannot exceed eleven values, so it never loses its
  # tail — while the text list loses precisely the singleton causes once a long
  # night fills its front with per-segment and per-obligation lines.
  printf '  "unmet_condition_numbers": [%s],\n' \
    "$(gate_unmet_numbers "$unmet" | tr '\n' ',' | sed 's/,$//')"
  printf '  "disposition": "%s",\n' "$(gate_json_escape "$(gate_done_disposition "$unmet")")"

  # WHAT A SUCCESSOR SHIFT NEEDS AND WHAT `--resume` USED TO SUPPLY INSTEAD.
  # Until the routing loop moved out of the lead session, a cut router was
  # resumed rather than replaced, so the conversation history carried the
  # segments, the blocks and the cycle results and nobody noticed the snapshot
  # did not. A shift is a NEW process with no history at all: handed the object
  # as it stood, it could not name a single segment. The claim that the router
  # holds no state a snapshot does not was false the moment it was written and
  # became load-bearing only now.
  #
  # Every block is BOUNDED. The point of the shift is a smaller starting
  # context, and an unbounded resume payload spends on the first turn exactly
  # what the mechanism exists to save.
  #
  # THE STEP GRAPH, because one step of it is not a segment. A design step has no
  # `segment` row, so `segments[]` cannot name it, and a shift has no other input
  # than this object — reading `## 실행 계획` itself would be a second input, and
  # the first exception opened makes the next one free. So the two facts a shift
  # needs to dispatch the design stage travel here: whether the plan requires a
  # design, and the graph with each step's id, skill and dependencies. `summary`
  # stays out — it is free prose a routing decision does not branch on, and the
  # object is bounded on purpose.
  #
  # `design_doc` is the document path the prelude resolved from the manifest key,
  # and a shift passes it to every design-side dispatch as it stands. The key
  # alone cannot be joined onto a worktree: outside a repository it is an
  # absolute path with its leading `/` removed. `null` when the run names none.
  printf '  "design_required": %s,\n' "$(gate_snapshot_design_required_json)"
  if [ -n "${DOC:-}" ]; then
    printf '  "design_doc": "%s",\n' "$(gate_json_escape "$DOC")"
  else
    printf '  "design_doc": null,\n'
  fi
  # THE DESIGN SCOPE, because it picks which slash command the design dispatch
  # sends and whether the audit carries `--base` and a split follows. A plan
  # frozen before the field existed has no key and reads as `single`.
  printf '  "design_scope": "%s",\n' "$(gate_snapshot_design_scope)"
  # THE DESIGN SKILL, so a shift sends `/cc-cmds:<design_skill>` rather than
  # mapping scope and tier itself. The value is `manifest_design_skill`'s, the
  # same function the driver's design arm and the design-dispatch check below
  # read; `null` when the plan has no design step to dispatch.
  printf '  "design_skill": %s,\n' "$(gate_snapshot_design_skill_json)"
  printf '  "steps": %s,\n' "$(gate_snapshot_steps_json)"
  # THE DECLARED SEGMENT PLAN, beside the graph for the same reason: the shift
  # that plans segments has no other input, and the values it would otherwise
  # copy out of the document are what the copy used to drop.
  printf '  "슬라이싱": %s,\n' "$(gate_snapshot_slicing_json)"
  # THE DOCUMENT ARGUMENT a dispatch puts first, announced and not written: the
  # snapshot is a read, so the brief of a run without a design document is made
  # by the dispatch arm that first needs it (`gate_dispatch_doc_arg`).
  printf '  "문서 인자": "%s",\n' "$(gate_json_escape "$(gate_doc_arg_path)")"
  printf '  "segments": [\n'
  gate_snapshot_segments_json
  printf '  ],\n'
  printf '  "segments_total": %s,\n' "$(gate_segment_ids | gate_count)"
  printf '  "blocked": [\n'
  gate_snapshot_blocked_json
  printf '  ],\n'
  # THE CONE BLOCKS, right after the run-wide ones they are not part of. A cone
  # row anchored on a segment holds what stands on that segment and nothing
  # else, so `blocked[]` leaves it out — and with no other key carrying it, a
  # shift could not see that a sibling was held at all. A projection of
  # `cc_cone_blocked`, the fold the run pane already shows, and no new
  # judgement: outside the default `--fields` projection and outside `H`, and
  # no termination condition reads it. Always emitted, empty included.
  printf '  "cone_blocks": [\n'
  gate_snapshot_cone_blocks_json
  printf '  ],\n'
  # THE SIBLINGS A `재설계 필요` RE-CONVERGENCE LEFT WITH A VOID PLAN, and
  # whether each may be re-planned now. The same evaluation the `replan` act
  # makes (`gate_replan_eval`), so a router reading `state` here is reading the
  # gate's own answer. Outside the default projection and `H`; always emitted.
  printf '  "replan_due": [\n'
  gate_replan_due_json
  printf '  ],\n'
  # THE AUDIT THAT ASKED FOR ITS SKELETAL RE-CONVERGENCE, or null. The same
  # evaluation the segment plan, the split and condition 1 make
  # (`gate_audit_concluded`), so a router that dispatches on it is acting on the
  # gate's own answer. Outside the default projection and `H`; always emitted.
  printf '  "audit_skeleton_due": %s,\n' "$(gate_audit_skeleton_due_json)"
  printf '  "cycles": [\n'
  gate_snapshot_cycles_json
  printf '  ],\n'
  # THE STALL LABELS, right after the reviews they are derived from. Always
  # emitted, empty included, so no reader has to tell an absent key from an empty
  # list. Outside the default `--fields` projection and outside `H`: the labels
  # are a pure function of rows the chain already covers. And outside the
  # dispatch path by construction — `act` reads `gate_snapshot_digest`, never
  # this object — so no label can refuse, park or hold anything.
  printf '  "stalls": [\n'
  gate_snapshot_stalls_json
  printf '  ],\n'
  # `다음` PER UNMERGED SEGMENT, the one value the routers branch on after a
  # review. The cycle cap rides beside it for display only; a router that read
  # it would hold a second copy of the table `gate_segment_review_next` owns.
  # After `stalls`, which keeps its place right after `cycles`.
  printf '  "review_carry": {"REIMPL_CYCLE_CAP": %s, "RECHECK_ROUND_CAP": %s},\n' "$REIMPL_CYCLE_CAP" "$RECHECK_ROUND_CAP"
  printf '  "review_next": [\n'
  gate_snapshot_review_next_json
  printf '  ],\n'
  # THE SEGMENTS WHOSE RERUN MAY GO OUT WHILE THEIR REVIEW STILL RUNS
  # (`gate_ci_early`), each with the head, the PR and the failing checks the act
  # names. A review stage holds `다음` back until it ends, so without this a
  # flaky check waited out the whole review before its one rerun. Always
  # emitted, empty included; outside the default `--fields` projection and
  # outside `H`.
  printf '  "ci_early": [\n'
  gate_snapshot_ci_early_json
  printf '  ],\n'
  # `다음` PER SEGMENT WHOSE IMPLEMENTATION JUST ENDED `정상 완료`, the one value
  # the routers branch on there: whether that run only emitted a plan or left
  # commits behind is nowhere else in the snapshot, and `종단 부류` reads the
  # same for both. Always emitted, empty included; outside the default
  # `--fields` projection and outside `H`. Its git reads are one ref check per
  # base ref and one `rev-list` per element.
  printf '  "implement_next": [\n'
  gate_snapshot_implement_next_json
  printf '  ],\n'
  printf '  "shift": %s,\n' "$(gate_shift_state)"
  # THE PACING VERDICT, beside `shift` and ahead of `handoff`, read from the
  # sensor's last published tick and never computed here. Absent, stale or of
  # another schema it is `null` with the reason beside it — three reasons from
  # file evidence alone, so this read never calls `launchctl`. The block does
  # not move `H`: the digest hashes the progress vector and the chain tip.
  local pace_obj pace_why
  pace_obj=$(gate_pace_state)
  if [ -n "$pace_obj" ]; then
    printf '  "pace": %s,\n' "$pace_obj"
  else
    pace_why=$(gate_pace_absent_reason)
    printf '  "pace": null,\n'
    printf '  "pace_absent_reason": "%s",\n' "$(gate_json_escape "$pace_why")"
  fi
  printf '  "handoff": [\n'
  gate_snapshot_handoff_json
  printf '  ],\n'

  # THE LOST-DISPATCH ALARM, and it is in the snapshot rather than only in the
  # render because the router reads the object and is judged on doing so. A key
  # that exists in the output and nowhere in the contract is a key nothing looks
  # for; this one names the failure whose whole cost was that no layer said it.
  printf '  "orphan_stages": [%s],\n' \
    "$( { cc_orphan_stages "$RUN_DIR" || true; } | sed 's/.*/"&"/' | paste -sd, - )"
  # THE LIVE-STAGE LIST, beside the alarm and for the same reason. `마지막
  # 스테이지` comes from the last `stage-result` row, so it names a stage that
  # has ENDED and cannot answer "is one running now?" — which is the question a
  # successor shift must answer before it dispatches or waits. One source,
  # `cc_live_stage_records`, feeds this and the render's list, so the two
  # cannot disagree. The pid inside does not move `H`: the digest hashes the
  # progress vector and the chain tip, not this object.
  printf '  "live_stages": [\n'
  gate_snapshot_live_stages_json
  printf '  ],\n'
  # THE STAGES WAITING FOR AN ACCOUNT BEFORE THEY SPAWN. A dispatch the router
  # answered `WAIT` has a supervisor (or a driver) but no CLI yet, so it is in
  # neither list above — and a key in neither list is a key a router dispatches
  # again. Always emitted, empty included; an empty list does not move `H`.
  printf '  "waiting_stages": [\n'
  gate_snapshot_waiting_stages_json
  printf '  ],\n'
  printf '  "ledger_damage": %s,\n' "$(gate_ledger_damage)"
  printf '  "chain_intact": %s,\n' "$(gate_chain_verify >/dev/null 2>&1 && printf 'true' || printf 'false')"
  printf '  "H": "%s"\n' "$(gate_snapshot_digest)"
  printf '}\n'
}

# `snapshot --fields` — a projection of the snapshot object, and the hook's
# prescribed replacement for `snapshot | jq -r .H`. ONE field prints its raw
# value on one line (so `--fields H` is a drop-in for the pipe it retires); two
# or more print a JSON object in the order asked. A name the snapshot does not
# carry is refused with exit 2 rather than answered `null`, because `null` is
# also what an absent `pace` block legitimately reads as.
readonly GATE_SNAPSHOT_FIELDS_DEFAULT='H,disposition,unmet_conditions_total,pending_approvals_total,live_stages,waiting_stages,shift,pace'

gate_snapshot_fields() {
  # gate_snapshot_fields <comma-list>
  local list="$1" snap keys f n=0 hit
  snap=$(gate_snapshot)
  keys=$(printf '%s' "$snap" | jq -r 'keys_unsorted[]')
  for f in $(printf '%s' "$list" | tr ',' ' '); do
    hit=$(printf '%s\n' "$keys" | grep -cFx -- "$f" || true)
    if [ "${hit:-0}" -eq 0 ]; then
      printf 'gate: snapshot --fields: 알 수 없는 필드 %s — 스냅숏이 가진 키: %s\n' "$f" "$(printf '%s' "$keys" | tr '\n' ',' | sed 's/,$//')" >&2
      exit 2
    fi
    n=$(( n + 1 ))
  done
  [ "$n" -gt 0 ] || { printf 'gate: snapshot --fields: 필드가 비어 있습니다\n' >&2; exit 2; }
  if [ "$n" -eq 1 ]; then
    printf '%s' "$snap" | jq -r --arg k "$list" '.[$k]'
    return 0
  fi
  # shellcheck disable=SC2046
  printf '%s' "$snap" | jq -c --args '. as $s | $ARGS.positional | map({key: ., value: $s[.]}) | from_entries' \
    $(printf '%s' "$list" | tr ',' ' ')
}

gate_snapshot_design_required_json() {
  # `true`, `false` or `null` — never folded. jq's `//` reads `false` as absent,
  # and a declared `false` is the one value a shift must not lose. A plan block
  # that is absent or does not parse is `null`.
  local v
  v=$( { manifest_plan_json 2>/dev/null | jq -c '.design_required' 2>/dev/null; } || true)
  case "$v" in
    true|false) printf '%s' "$v" ;;
    *) printf 'null' ;;
  esac
}

gate_snapshot_design_scope() {
  # `single` or `base`. An absent key, an unparsable plan block and a value
  # outside the two all read `single` — the shape every run had before the field.
  local v
  v=$( { manifest_plan_json 2>/dev/null | jq -r '.design_scope // "single"' 2>/dev/null; } || true)
  case "$v" in
    base) printf 'base' ;;
    *) printf 'single' ;;
  esac
}

gate_snapshot_design_skill_json() {
  # `"<skill>"` when the plan has a step whose skill is `design`, `null`
  # otherwise — a `lead-solo` plan frozen before `solo` existed, a document-
  # anchored run, a plan block that does not parse. The name itself comes from
  # `manifest_design_skill` and nowhere else.
  if [ "$(gate_plan_skill_step_count design)" != "0" ]; then
    printf '"%s"' "$(gate_json_escape "$(manifest_design_skill)")"
  else
    printf 'null'
  fi
}

gate_design_path_word() {
  # The `경로` word of the `설계 티어` and `감사 공시` rows: `base` on a base
  # scope, otherwise `manifest_design_path` with `none` written `해당 없음` — a
  # run that audits a document with no design step reads that way too. A plan
  # without the key reads by the contract's absence rule (`discuss-audit` on a
  # team-4 single-scope design). `미상` only when the plan block itself cannot
  # be read, so `해당 없음` and `미상` never mix in a collector's key.
  manifest_plan_json 2>/dev/null | jq -e 'type == "object"' >/dev/null 2>&1 \
    || { printf '미상'; return 0; }
  if [ "$(manifest_design_scope)" = "base" ]; then
    printf 'base'
    return 0
  fi
  case "$(manifest_design_path)" in
    none) printf '해당 없음' ;;
    *) manifest_design_path ;;
  esac
}

# ---------------------------------------------------------------------------
# The `설계 티어` row — the entry judgment's tier, as the run opened on it.
#
# WRITTEN HERE AND NOWHERE ELSE: once, at run open, right after the `run` row.
# Run open happens once per run and before the driver's first stage, so this
# one writer covers the router path and the fixed-graph driver alike; the
# driver and `feed.sh` neither write nor relay it. The kickoff writes no ledger,
# so the plan in the manifest is the only place the judged value survives a
# raise, and this row is where the morning reads it beside the reviews.
#
# NOT `자율 승인`. That series is what the run decided; the tier was decided
# before the run, by the kickoff and the person, and a raise reads as
# `판정 ≠ 확정` on this row.
#
# ONLY FOR A PLAN THAT CARRIES `design_tier_judged`, and only when the series
# is still empty — the guard rides on top of run open's once-only property. A
# plan frozen before the key existed gets no row. `사유` and `근거` are clipped
# excerpts (200 and 240 bytes); the whole values stay in the manifest's plan.
# ---------------------------------------------------------------------------
gate_record_design_tier() {
  manifest_plan_json 2>/dev/null | jq -e 'type == "object" and has("design_tier_judged")' >/dev/null 2>&1 \
    || return 0
  [ -z "$(gate_rows '설계 티어')" ] || return 0
  local dt_judged dt_tier dt_skill dt_audit dt_est dt_reasons dt_why
  dt_judged=$(manifest_plan_field '.design_tier_judged')
  dt_tier=$(manifest_plan_field '.design_tier')
  if [ "$(gate_plan_skill_step_count design)" != "0" ]; then
    dt_skill=$(manifest_design_skill)
  else
    dt_skill='없음'
  fi
  if [ "$(gate_plan_skill_step_count design-audit)" != "0" ]; then
    dt_audit='있음'
  else
    dt_audit='없음'
  fi
  dt_est=$(manifest_plan_field '.estimated_files')
  dt_reasons=$( { manifest_plan_json 2>/dev/null \
                  | jq -r '[.design_heavy_reasons[]? | tostring] | join(" / ")' 2>/dev/null; } || true)
  [ -n "$dt_reasons" ] || dt_reasons='없음'
  dt_why=$( { manifest_plan_json 2>/dev/null | jq -r '.design_tier_rationale // "" | tostring' 2>/dev/null; } || true)
  [ -n "$dt_why" ] || dt_why='없음'
  gate_append '설계 티어' \
    "판정=$(gate_row_safe "$dt_judged" 40)" \
    "확정=$(gate_row_safe "$dt_tier" 40)" \
    "범위=$(manifest_design_scope)" \
    "경로=$(gate_design_path_word)" \
    "설계 스킬=$dt_skill" \
    "감사=$dt_audit" \
    "추정 파일=$(gate_row_safe "$dt_est" 40)" \
    "사유=$(gate_row_safe "$dt_reasons" 200)" \
    "근거=$(gate_row_safe "$dt_why" 240)"
}

gate_snapshot_steps_json() {
  # The plan's steps as `{id, skill, depends_on}`, one JSON array on one line. A
  # step written as a bare skill string (an older plan shape) keeps its skill and
  # has a `null` id, so a shift can see it exists and cannot key anything on it.
  local v
  v=$( { manifest_plan_json 2>/dev/null | jq -c '
        [ .steps[]? | if type == "object"
            then {id: (.id // null), skill: (.skill // null), depends_on: (.depends_on // [])}
            else {id: null, skill: ., depends_on: []} end ]' 2>/dev/null; } || true)
  case "$v" in
    '['*) printf '%s' "$v" ;;
    *) printf '[]' ;;
  esac
}

gate_snapshot_live_stages_json() {
  # One object per line of `cc_live_stage_records`, comma-separated. The keys
  # are the contract the router's skill table names; a key emitted here and
  # absent there is a key nobody reads.
  local first=1 seg sid pid sup start
  while IFS="$(printf '\t')" read -r seg sid pid sup start; do
    [ -n "$seg" ] || continue
    [ "$first" = "1" ] || printf ',\n'
    first=0
    printf '    {"세그먼트": "%s", "스테이지": "%s", "pid": "%s", "감독": "%s", "시작": "%s"}' \
      "$(gate_json_escape "$seg")" "$(gate_json_escape "$sid")" \
      "$(gate_json_escape "$pid")" "$(gate_json_escape "$sup")" "$(gate_json_escape "$start")"
  done <<EOF
$( { cc_live_stage_records "$RUN_DIR" || true; } )
EOF
  [ "$first" = "1" ] || printf '\n'
}

gate_snapshot_waiting_stages_json() {
  # One object per line of `cc_waiting_records`, comma-separated: the key, the
  # lineage, the group, the expected release (`null` when unknown), the last
  # refresh, the holder pid, the writer and the freshness. A stale waiter whose
  # holder lives stays listed with `fresh: false` — it is still not dispatched
  # again, and killing the holder is what lets settlement close the attempt.
  local first=1 key lin grp upto upd holder writer fresh
  while IFS="$(printf '\t')" read -r key lin grp upto upd holder writer fresh; do
    [ -n "$key" ] || continue
    [ "$first" = "1" ] || printf ',\n'
    first=0
    printf '    %s' "$(jq -cn --arg s "$key" --arg l "$lin" --arg g "$grp" --arg u "$upto" \
                         --arg r "$upd" --arg h "$holder" --arg w "$writer" --arg f "$fresh" '
      def num: if test("^[0-9]+$") then tonumber else null end;
      {segment: $s, lineage: $l, group: $g, until: ($u | num), refreshed_at: ($r | num),
       holder: ($h | num), writer: $w, fresh: ($f == "true")}')"
  done <<EOF
$( { cc_waiting_records "$RUN_DIR" "$LEDGER" || true; } )
EOF
  [ "$first" = "1" ] || printf '\n'
}

# ---------------------------------------------------------------------------
# The post-mutation digest, written to a file the caller names.
#
# WHAT IT BUYS. Every acting call has to carry `--snapshot-digest`, and the only
# way to learn that value was a separate `snapshot` call — so each act cost two
# gate invocations, and the first of the two existed solely to read back a value
# this process had just finished deciding. Emitting it at the end of the act the
# caller already made removes the read-back without weakening the binding: the
# flag stays in the argv, the comparison stays where it was, and what changes is
# only where the caller gets the number.
#
# WHY A FILE AND NOT A FILE DESCRIPTOR. "One value, one file under the run
# directory" is this script's dominant idiom already — `surface-digest`,
# `ledger-path` and `progress-digest` are all written that way — and there is
# not one `exec 3>` in the file to copy instead. A fixed descriptor also
# collides with the `exec` verb structurally: `gate_run_readonly` runs the
# wrapped argv in a subshell, which inherits every open descriptor, so the
# judgment channel would be writable by the command under judgment. bash 3.2 is
# the floor here, so `{fd}>` dynamic allocation is not available either, and a
# fixed number would have to be opened by the hook, the test suite and the stage
# wrapper — three call sites frozen as literal lines.
#
# AND A LINE ON STDERR BESIDES THE FILE. A model caller that has to open the
# file spends one more request per act on reading back a value that was
# already in this call's output, so `H` and `actor` are also printed as the
# last stderr line, `[gate-digest] H=<H> actor=<actor>`. Stderr is where the
# `log`/`warn` diagnostics go, and a run log reader could once mistake a bare
# hash there for a diagnostic; three things keep that from happening now. The
# line carries a fixed `[gate-digest]` tag no diagnostic uses; only a call
# given `--emit-digest` prints it, and only model callers pass that flag, so
# the driver's own logs never see it; and the exit 4 refusal already prints
# the live `H` on stderr, so a hash appearing there is not a new exposure.
# Stdout is not used because `exec` hands the wrapped command's stdout through
# untouched. The line is the value the file gets, computed once before the
# file is written, so the freshness comparison the next call makes is the same
# whichever of the two the caller copied from. The file stays: a caller whose
# output was truncated, or that was compacted, has no line to read.
#
# WHY THE TWO TOTALS COME ALONG. A caller reading this file is reading it
# INSTEAD of a `snapshot` round trip, and those two counts are the other things
# it would have gone there for. The key names match `snapshot`'s exactly so no
# consumer has to learn a second vocabulary for the same values.
#
# BEST EFFORT, and deliberately so. This runs after the act and after its ledger
# row; refusing here would report a failure that did not happen. A caller that
# finds no file falls back to `snapshot --fields H`, which is the same path a
# gate too old to know this flag already leaves it on.
# ---------------------------------------------------------------------------
gate_digest_path() {
  # gate_digest_path — where THIS process emits, derived in one place.
  #
  # ONE DERIVATION, BECAUSE TWO DRIFT. The hook tells a stage which file to
  # open, and it used to build that path itself — same shape, but interpolating
  # the stage id verbatim while this file sanitizes it. Every stage id this
  # pipeline mints carries a character outside the sanitized class, so the two
  # paths agreed only for the router, which is the one actor the hook is never
  # installed for. The failure was silent in both directions: the gate emitted
  # correctly, the stage opened a name that did not exist, and it fell back to
  # the round trip the flag exists to remove — with the run green throughout.
  #
  # Anything that needs the path asks for it now. `gate.sh digest-path` prints
  # this same value, so a second copy of the rule cannot exist; the character
  # rule itself is `thp_key_norm`, which names every file under `admit/` too.
  printf '%s/digest/gate-digest-%s.json' "$RUN_DIR" \
    "$(gate_thp thp_key_norm "${CC_PIPELINE_STAGE_ID:-router}")"
}

gate_on_exit() {
  # THE EXIT STATUS ON THE WAY OUT IS NOT THIS FUNCTION'S TO CHANGE. This runs
  # from an EXIT trap, and a trap body that fails under `errexit` REPLACES the
  # status the script was exiting with — so a hiccup here could turn a refusal
  # into a success, which is the one outcome this whole file exists to make
  # impossible. The status is captured first and restored last, and the body
  # runs with `errexit` off so no single command can short-circuit that.
  #
  # ONE TRAP, TWO DUTIES, IN THIS ORDER. Bash keeps a single EXIT trap per
  # shell, so a second `trap … EXIT` anywhere in the verb would silently
  # replace the first — the segment arm of `gate_record_row` learned this
  # when it wanted its own trap for `settings.lock`. The lock is released
  # first because the digest emission is a write the next re-derivation may
  # be waiting behind; the digest is emitted last so the value the caller
  # reads is the state at exit, appends included.
  local __rc=$?
  set +e
  gate_dispatch_lock_release
  gate_settings_lock_release
  gate_ci_rerun_lock_release
  gate_ci_match_lock_release
  # The one-read copy of a seat-apply record is the gate's own scratch file.
  [ -z "${GATE_SA_COPY:-}" ] || rm -f "$GATE_SA_COPY"
  gate_emit_digest_body
  set -e
  return "$__rc"
}

# ---------------------------------------------------------------------------
# The per-key dispatch lock — `<key>.dispatching`, held by a routed
# `act --kind skill` from before its first row about the dispatch until it
# exits. Two lines: the holding process's pid and its fingerprint.
#
# THE LOCK IS WHAT KEEPS ONE KEY TO ONE DISPATCH. The exclusive attempt claim
# only keeps attempt numbers unique, and two acts of one key can derive two
# different numbers; the check "is this key already in flight" alone lets two
# acts that arrive before either has written `.sup` both through. Held across
# check and launch, the lock makes the two one step per key: once it is
# released, the launch it covered is visible to the next act's check.
# ---------------------------------------------------------------------------
#
# THE HOLDER IS THE PROCESS THIS SHELL REALLY IS, read as `$(exec sh -c 'echo
# $PPID')` at the call site: `$$` in a subshell is the parent's under bash 3.2,
# and the `exec` keeps the substitution from adding a process of its own.
GATE_DISPATCH_LOCK=""
readonly GATE_DISPATCH_LOCK_EMPTY_GRACE=60

gate_dispatch_lock_holder_live() {
  # gate_dispatch_lock_holder_live <lock file> — 0 when the recorded holder is
  # the live process that wrote it.
  local f="$1" pid fp
  pid=$( { sed -n '1p' "$f" 2>/dev/null || true; } | tr -d '[:space:]')
  fp=$(sed -n '2p' "$f" 2>/dev/null || true)
  cc_holder_is_live "$pid" "$fp"
}

gate_dispatch_lock_take() {
  # gate_dispatch_lock_take <key> — 0 with the lock held by this process, 1 when
  # a live act holds it.
  #
  # A STALE LOCK IS JUDGED ON ONE READING, AND ONLY THAT READING IS REMOVED. The
  # body is read once; the holder is judged from that copy, and the file moved
  # aside is compared with that same copy. Judging the file and reading it in
  # two steps let a second act judge the dead holder, read the lock a first act
  # had just re-created in its place, find the moved file equal to what it read
  # and delete a live lock: two acts held one key and both dispatched it. A
  # moved file that differs is someone else's lock, so it is put back and never
  # deleted — if a third act has created a lock in the moment it was away, the
  # moved file is left beside the lock rather than destroyed.
  #
  # AN EMPTY LOCK IS A LOCK BEING WRITTEN. The exclusive create and the body's
  # write are two steps, and a reader between them sees no holder; reading that
  # as dead took the lock from a live owner. An empty body counts as held until
  # it is older than `GATE_DISPATCH_LOCK_EMPTY_GRACE`, so one whose writer died
  # in that gap is still taken over.
  local key="$1" f me body seen pid fp mine ts
  f="$RUN_DIR/$key.dispatching"
  me=$(exec sh -c 'echo $PPID')
  body=$(printf '%s\n%s' "$me" "$(cc_proc_fingerprint "$me")")
  if ( set -C; printf '%s\n' "$body" > "$f" ) 2>/dev/null; then
    GATE_DISPATCH_LOCK=$f; return 0
  fi
  seen=$(cat "$f" 2>/dev/null || true)
  if [ -z "$seen" ]; then
    if [ ! -e "$f" ]; then
      # Released between the failed create and the read: one more create.
      ( set -C; printf '%s\n' "$body" > "$f" ) 2>/dev/null || return 1
      GATE_DISPATCH_LOCK=$f; return 0
    fi
    ts=$(gate_mtime "$f")
    [ -n "$ts" ] && [ $(( $(date -u +%s) - ts )) -ge "$GATE_DISPATCH_LOCK_EMPTY_GRACE" ] || return 1
  else
    pid=$(printf '%s\n' "$seen" | sed -n '1p' | tr -d '[:space:]')
    fp=$(printf '%s\n' "$seen" | sed -n '2p')
    cc_holder_is_live "$pid" "$fp" && return 1
  fi
  mine="$f.stale.$me"
  mv "$f" "$mine" 2>/dev/null || return 1
  if [ "$(cat "$mine" 2>/dev/null || true)" != "$seen" ]; then
    mv -n "$mine" "$f" 2>/dev/null || true
    return 1
  fi
  rm -f "$mine"
  if ( set -C; printf '%s\n' "$body" > "$f" ) 2>/dev/null; then
    GATE_DISPATCH_LOCK=$f; return 0
  fi
  return 1
}

gate_dispatch_lock_release() {
  # Removes the lock only while it is still this process's.
  local f="${GATE_DISPATCH_LOCK:-}" me
  [ -n "$f" ] || return 0
  GATE_DISPATCH_LOCK=""
  me=$(exec sh -c 'echo $PPID')
  [ "$( { sed -n '1p' "$f" 2>/dev/null || true; } | tr -d '[:space:]')" = "$me" ] || return 0
  rm -f "$f"
}

gate_key_in_flight() {
  # gate_key_in_flight <key> — 0 when a dispatch of this key is still alive: a
  # live supervisor, a live stage, or a waiting stage.
  local key="$1"
  cc_supervisor_is_live "$RUN_DIR" "$key" && return 0
  cc_stage_is_live "$RUN_DIR" "$key" && return 0
  cc_waiting_is_member "$RUN_DIR" "$LEDGER" "$key" && return 0
  return 1
}

gate_emit_digest_body() {
  [ -n "${GATE_EMIT_DIGEST_TO:-}" ] || return 0
  # NOT SINGLE SHOT, AND THERE ARE NO EXPLICIT CALLS LEFT. Disarming on the
  # first success made the trap cover only "exits that happen before the first
  # emission" — any ledger append landing after that call was invisible to it,
  # which is the same defect the enumeration had, turned around. The rule is
  # "the value the caller reads is the state at exit", so the only call site is
  # the trap and the last write wins.
  #
  # THE TEMP IS MINTED, NOT NAMED. A predictable sibling can be pre-created as a
  # symlink by anything that can write this directory, and `>` follows it — so
  # the redirection would land wherever the link points, outside every check the
  # target path passed. `mktemp` in the same directory keeps the rename atomic
  # and takes the name out of the attacker's hands.
  #
  # H AND THE ACTOR ARE COMPUTED BEFORE THE TEMP FILE, because the stderr line
  # carries them whether or not the file can be written, a failed `mktemp`
  # included. The line is
  # the same value the file gets, printed once at the single exit below, after
  # every warning, so it is the last line of the call's output.
  local tmp h actor
  h=$(gate_snapshot_digest)
  # THE EMITTING ACTOR TRAVELS WITH THE VALUE. The file name separates actors by
  # convention, and a convention is exactly what a caller can get wrong — so the
  # object also says who wrote it, and a consumer that finds an id other than
  # its own knows it is holding someone else's digest rather than a stale one.
  # `CC_PIPELINE_STAGE_ID` is empty in the router and set in a stage, which is
  # the same distinction this file already relies on elsewhere.
  #
  # WRITTEN RAW, so a consumer can compare it against its own
  # `$CC_PIPELINE_STAGE_ID` VERBATIM. A first version sanitized it on the same
  # character class the directory names use, and every stage id this pipeline
  # mints carries a character outside that class — `<segment>#<attempt>` from
  # the gate, `S5:<segment>:<cycle>` from the driver — so a verbatim comparison
  # reported every stage's own file as someone else's. Only the two characters
  # that would break the JSON string are replaced.
  actor=$(printf '%s' "${CC_PIPELINE_STAGE_ID:-router}" | tr -d '\000-\037' | tr '"\\' '__')
  # Same directory as the target by construction, so the rename is atomic and a
  # reader never sees a half-written object.
  if ! tmp=$(mktemp "$(dirname "$GATE_EMIT_DIGEST_TO")/.gate-digest.XXXXXX" 2>/dev/null); then
    warn "could not create the digest temp file: $GATE_EMIT_DIGEST_TO — the consumer falls back to snapshot"
  elif ! { printf '{"H":"%s","obligations_total":%s,"pending_approvals_total":%s,"actor":"%s"}\n' \
             "$h" \
             "$(gate_open_obligations | gate_count)" \
             "$(gate_pending_approval_ids | gate_count)" \
             "$actor" >"$tmp" 2>/dev/null \
           && mv "$tmp" "$GATE_EMIT_DIGEST_TO" 2>/dev/null; }; then
    rm -f "$tmp" 2>/dev/null || true
    warn "could not emit the digest: $GATE_EMIT_DIGEST_TO — the consumer falls back to snapshot"
  fi
  [ -n "$h" ] && printf '[gate-digest] H=%s actor=%s\n' "$h" "$actor" >&2
  return 0
}

gate_pending_approvals_json() {
  # THE CUTPOINT AND THE QUESTION TRAVEL WITH THE ID, because the array mixes two
  # kinds of answer whose lifetimes are opposite and gave the router no field to
  # tell them apart. Termination condition 2 does not count an approval whose
  # cutpoint is `판단`: an act approval's answer is valid only against the tree
  # its binding tuple named, while a question's answer is durable and a successor
  # run consumes it. A router reading this array as uniformly blocking cannot end
  # a run that one open question does not block — which is the defect this design
  # exists to remove, arriving through a different door.
  #
  # The question text comes along for the same reason the id alone was not
  # enough: an id is a hash and says nothing about what is being asked, so a
  # person handed the array had to go read the ledger to know what to answer.
  local ids id state row first=1
  # Pinned for the same reason as the chain walk. This one emits INTO the
  # snapshot object, so a `tr`/`sed` that dies on an invalid byte does not just
  # lose the approvals array — it truncates the JSON at that point and every
  # field after it, including the chain verdict, never reaches the reader. The
  # ledger the reader most needs a verdict about is precisely the malformed one.
  #
  # NOTE FOR ANYONE WIDENING THIS: this function DOES contain a `sort -u`, and
  # the pin is still safe. The order it produces is decided by `LC_COLLATE`,
  # which the driver has already fixed to C; `LC_CTYPE` does not enter into it.
  # The "no `sort` in scope" reasoning that once justified the narrower pin was
  # never the load-bearing part, and repeating it here would make this look like
  # a violation of a rule that does not exist.
  local LC_CTYPE=C; export LC_CTYPE
  ids=$(gate_rows '승인' \
        | tr '|' '\n' | sed -n 's/^ *승인 id=//p' | sed 's/[[:space:]]*$//' | sort -u)
  for id in $ids; do
    # The LAST row for the id decides, and it is read once here rather than
    # re-grepped per field — three reads of the same row could straddle a
    # concurrent append and describe two different rows as one object.
    row=$( { gate_rows '승인' | grep -F "| 승인 id=$id |" || true; } | tail -1)
    state=$(gate_row_field "$row" '상태')
    [ "$state" = "대기" ] || continue
    [ "$first" = "1" ] || printf ',\n'
    first=0
    # `disposition` IS HOW A FREE-INPUT ANSWER REACHES THE MORNING. An approval
    # whose last `대기` row carries `처분 사유` was answered by a person and the
    # gate could derive no disposition from the answer; without this field it
    # is indistinguishable in the array from one nobody has answered.
    local disp pcls
    disp=$(gate_row_field "$row" '처분 사유'); [ -n "$disp" ] || disp='-'
    # `class` IS WHAT SEPARATES A QUESTION ONLY A PERSON ANSWERS from one the
    # gate holds for any other reason: a person-set approval (`사람-결정`,
    # `시각-승인`) keeps its segment
    # held and counts against the run's end, and the router reads that here.
    # Every row the issuer and the free-input close write for a judgment
    # approval carries the class; an act approval, or one issued before the field
    # existed, reads `-`.
    pcls=$(gate_row_field "$row" '판단 부류'); [ -n "$pcls" ] || pcls='-'
    printf '    {"id": "%s", "blocks": "%s", "cutpoint": "%s", "class": "%s", "disposition": "%s", "question": "%s"}' \
      "$(gate_json_escape "$id")" \
      "$(gate_json_escape "$(gate_row_field "$row" '막는 세그먼트')")" \
      "$(gate_json_escape "$(gate_row_field "$row" '절단점')")" \
      "$(gate_json_escape "$pcls")" \
      "$(gate_json_escape "$disp")" \
      "$(gate_json_escape "$(gate_row_field "$row" '질문 문면')")"
  done
  [ "$first" = "1" ] || printf '\n'
}

gate_render_snapshot() {
  local a
  printf '목표      : %s\n' "$(manifest_field '인가' '종료 지점')"
  printf '진전 해시 : %s\n' "$(gate_progress_digest)"
  printf '스냅숏 해시: %s\n' "$(gate_snapshot_digest)"
  printf '원장 손상 : %s\n' "$(gate_ledger_damage)"
  # The break's ROW NUMBER reaches the reader. `gate_chain_verify` has always
  # reported it, and every caller threw it away into `2>&1` — so the render said
  # `끊김` and gave the morning nowhere to look.
  local chain_out
  chain_out=$(gate_chain_verify 2>&1 >/dev/null || true)
  if [ -z "$chain_out" ]; then
    printf '해시 체인 : 무결\n'
  else
    printf '해시 체인 : 끊김 — %s\n' "$chain_out"
  fi
  printf '대상      :\n'
  for a in $(target_aliases); do
    printf '  %-12s %-24s 절단점 %s\n' "$a" \
      "$(target_field "$a" '원격 슬러그')" "$(target_field "$a" '절단점')"
  done
  # THE DISPOSED COUNTS SIT BESIDE THE UNRESOLVED ONE, BROKEN OUT BY DISPOSITION.
  # The single count cannot show an amnesty: the open list de-duplicates by
  # identity, so a second problem row for an identity that flips the excusal moves
  # nothing on this line. Naming what left the set, and by which of the three
  # exits, is what makes that visible at a glance.
  printf '미해결 의무: %s건 · 처분 %s\n' \
    "$(gate_open_obligations | gate_count)" "$(gate_disposition_counts)"

  # PENDING APPROVALS, AND THIS LINE DOES NOT DISAPPEAR AT ZERO. The JSON carried
  # them and the render did not, so a run held by an approval printed `원장 손상`,
  # `해시 체인` and `미해결 의무` in a row — three lines all reading fine — while
  # a person was the only thing that could move it, and the word `승인` appeared
  # nowhere in the whole output. A line that shows up only when the count is
  # non-zero cannot be told apart from a line nobody wrote, which is the same
  # absence wearing a different face.
  local n_pending
  n_pending=$(gate_pending_approval_ids | gate_count)
  printf '대기 승인 : %s건\n' "$n_pending"

  # WHY THE RUN CANNOT END, beside the rest of it. NO COUNT OF CONDITIONS GOES ON
  # THIS LINE — the number was already written down wrong in two comments, and a
  # third copy is a third thing to keep in step with a function that decides it.
  # What the line carries is the disposition and the condition numbers, both
  # derived at the moment of printing.
  local r_unmet r_disposition r_numbers
  r_unmet=$(gate_done_conditions)
  r_disposition=$(gate_done_disposition "$r_unmet")
  r_numbers=$(gate_unmet_numbers "$r_unmet" | tr '\n' ',' | sed 's/,$//')
  if [ "$r_disposition" = "충족" ]; then
    printf '미충족 조건: 없음 — 종료 조건이 전부 성립합니다\n'
  elif [ "$r_disposition" = "무효화" ]; then
    printf '미충족 조건: 조건 %s — 무효화만 남았습니다. act --kind propose-done 이 충족이 아니라 무효로 기록하고 런을 닫습니다. 이 런의 기준선은 다시 잡히지 않습니다\n' \
      "${r_numbers:-미상}"
  else
    printf '미충족 조건: 조건 %s\n' "${r_numbers:-미상}"
  fi

  # LIVENESS, because "is this still going?" had no cheap answer. The heartbeat
  # a watcher prints goes to a stdout that its launching tool call already
  # closed, so it reaches nobody; the render did not carry a live-stage count,
  # a ledger age, or the run's own terminal state. Answering it needed the row
  # grammar and a manual pid comparison.
  local n_live now_s led_s hb_s done_line orphans
  # Counting pid FILES reported stages that were not there: measured 21 files
  # against 5 live processes, and a render claiming "진행 중" for a run whose
  # recorded pid was dead. The shared predicate tests the process.
  n_live=$(cc_live_stages "$RUN_DIR")
  now_s=$(date -u +%s)
  led_s=$(gate_mtime "$LEDGER")
  hb_s=$(gate_mtime "$RUN_DIR/watch.heartbeat")
  # THE NAMES FOLLOW THE COUNT, so a person can find the pid to stop without
  # an `ls` of the run directory — the stop instruction is "kill `<seg>.pid`
  # (the CLI), never `<seg>.sup` first", and it needs the numbers on screen.
  local live_list
  live_list=$( { cc_live_stage_records "$RUN_DIR" || true; } \
               | awk -F'\t' '{ printf "%s%s(pid %s, sup %s)", (NR>1 ? " " : ""), $1, $3, $4 }')
  if [ -n "$live_list" ]; then printf '살아 있는 스테이지: %s개 — %s\n' "$n_live" "$live_list"
  else                         printf '살아 있는 스테이지: %s개\n' "$n_live"; fi
  # The stages waiting for an account, rendered only when there is one, with
  # the holder a person stops when a waiter's refresh has stopped.
  local wait_list
  wait_list=$( { cc_waiting_records "$RUN_DIR" "$LEDGER" || true; } \
               | awk -F'\t' '{ printf "%s%s(그룹 %s, 까지 %s, 보유자 %s%s)", (NR>1 ? " " : ""), $1, $3, $4, $6, ($8 == "true" ? "" : ", 갱신 멈춤") }')
  [ -z "$wait_list" ] || printf '대기 중인 스테이지: %s\n' "$wait_list"
  # Rendered only when there is one. A line that reads "0" every night is a line
  # nobody sees on the night it reads 1, and unlike the pending-approval count
  # this one has no second reading to preserve — no orphan is no line.
  #
  # THE WORDING SAYS ONLY WHAT THE PREDICATE KNOWS: the record outlived the
  # process, and no result was recorded. The cause is not among its inputs.
  # With the supervisor detached, a surviving orphan means the supervisor died
  # too, so the branches named are machine-level, not routing mistakes — and
  # the settlement token is spelled out so the morning can grep for it.
  orphans=$( { cc_orphan_stages "$RUN_DIR" || true; } | paste -sd' ' -)
  [ -n "$orphans" ] && \
    printf '잃어버린 파견: %s — 파견 기록이 남았는데 그 프로세스가 없습니다. 스테이지 결과가 기록되지 않았습니다 — 원인은 이 술어의 입력에 없습니다. 감독자까지 사라졌다는 뜻이므로 기계 재부팅·절전·OOM, 사람이 보낸 종료가 감독자에 닿은 것, 또는 정산이 도중에 멈춘 것일 수 있습니다. 다음 게이트 호출이 이를 `외부 종료` 로 정산합니다\n' "$orphans"
  if [ -n "$led_s" ]; then printf '원장 갱신 : %s초 전\n' "$((now_s - led_s))"
  else                     printf '원장 갱신 : (없음)\n'; fi
  if [ -n "$hb_s" ]; then printf '감시자    : %s초 전 하트비트\n' "$((now_s - hb_s))"
  else                    printf '감시자    : 하트비트 없음 (안 돌거나 옛 판입니다)\n'; fi
  done_line=$(cat "$RUN_DIR/done" 2>/dev/null || true)
  if [ -n "$done_line" ]; then printf '런 상태   : 종단 — %s\n' "$done_line"
  else                         printf '런 상태   : 진행 중\n'; fi
  # NAMED, or nobody finds it. The enumeration is a sibling file precisely so
  # `done` keeps its one-line contract, and a sibling nothing points at is a file
  # that exists for no reader.
  if [ -f "$RUN_DIR/done-obligations" ]; then
    printf '처분 의무 : %s/done-obligations\n' "$RUN_DIR"
  fi
  printf '스테이지 스트림: %s/log/<세그먼트>.json\n' "$RUN_DIR"
}

gate_mtime() {
  # gate_mtime <path> — epoch seconds, or empty. `stat` diverges between BSD and
  # GNU on the very flag this needs, so neither spelling is used: `find -newer`
  # against a probe would need a probe, and `ls` output is locale-shaped. `date
  # -r` is present on both and takes the file directly.
  # `-e` RATHER THAN `-f`, because the reap lock is a DIRECTORY and dating it is
  # what lets a lock with no readable owner line expire instead of standing
  # forever. `date -u -r` takes a directory on both platforms — verified on this
  # host — and every other caller passes a file, so widening the guard adds a
  # case rather than changing one.
  [ -e "$1" ] || return 0
  date -u -r "$1" +%s 2>/dev/null || true
}

# ---------------------------------------------------------------------------
# The pacing sensor's published tick, READ AND NEVER COMPUTED.
#
# `fleet.sh sensor` is the single writer of `pace/state.json`; this file reads
# it for the snapshot's `pace` block and for the `pace` ledger row, and does
# nothing else with it. No inline computation — the sensor joins the seat
# binding and the tracker's allowance table in ONE tick, and a consumer that
# re-read either on its own clock would tear that join at the moment a seat is
# re-bound. Read-only is a coupling requirement, not a performance choice.
#
# STALENESS IS MEASURED IN SENSOR PERIODS, NOT IN THE BURN CACHE'S TTL. The
# sensor fires every `FLEET_START_INTERVAL` (55s) and caps its own runtime at
# `FLEET_TICK_BUDGET_SECONDS` (5s), so three periods is 3 x (55 + 5) = 180s —
# the same number `fleet.sh` declares as `FLEET_STATE_STALE_SECONDS`, and
# `scripts/lint-pace-threshold-pins.sh` refuses the two drifting apart. The
# schema is compared by EQUALITY: an unknown version is treated as absence, not
# read as "newer and probably compatible".
#
# A `state.json` THAT NEVER EXISTED falls into the same branch as one older than
# three periods. There is no `computed_at` to compare, so it is not "stale",
# but the disposition is identical and the invariant underneath it is that the
# pacing sensor can never stop dispatch by being absent — a consumer reads no
# verdict as `유지`.
# ---------------------------------------------------------------------------
readonly GATE_PACE_STALE_SECONDS=180
readonly GATE_PACE_SCHEMA='cc-pace-state v1'

gate_pace_root() {
  printf '%s' "${GATE_PACE_ROOT:-${XDG_STATE_HOME:-$HOME/.local/state}/cc-cmds/pace}"
}

gate_pace_state() {
  # gate_pace_state — the published state object on one line, or nothing.
  # Nothing for: file absent, unparseable, schema not equal, or
  # `computed_at_epoch` older than GATE_PACE_STALE_SECONDS.
  local f s age now
  f="$(gate_pace_root)/state.json"
  [ -r "$f" ] || return 0
  s=$(jq -c --arg schema "$GATE_PACE_SCHEMA" 'select(.schema == $schema)' "$f" 2>/dev/null) || return 0
  [ -n "$s" ] || return 0
  now=$(date -u +%s)
  age=$(printf '%s' "$s" | jq -r --argjson now "$now" '($now - (.computed_at_epoch // 0)) | floor' 2>/dev/null || true)
  case "$age" in ''|*[!0-9-]*) return 0 ;; esac
  [ "$age" -le "$GATE_PACE_STALE_SECONDS" ] || return 0
  printf '%s' "$s"
}

gate_pace_absent_reason() {
  # gate_pace_absent_reason — which of three states the absence is, from the
  # heartbeat file alone (never `launchctl`):
  #   no heartbeat                         -> 센서 미등록
  #   heartbeat older than three periods   -> 센서 정지
  #   heartbeat fresh, state.json not      -> 센서 기동 실패
  local hb mt now age
  hb="$(gate_pace_root)/sensor.heartbeat"
  [ -e "$hb" ] || { printf '센서 미등록'; return 0; }
  mt=$(gate_mtime "$hb")
  now=$(date -u +%s)
  age=$(( now - ${mt:-0} ))
  if [ -z "$mt" ] || [ "$age" -gt "$GATE_PACE_STALE_SECONDS" ]; then printf '센서 정지'; return 0; fi
  printf '센서 기동 실패'
}

gate_pace_row_if_changed() {
  # gate_pace_row_if_changed — one `pace` row per CHANGE of verdict, run-scoped.
  #
  # THE COMPARISON BASIS IS THIS RUN'S LEDGER, NOT THE SENSOR'S OWN MEMORY. The
  # sensor keeps `prev_verdict` across every run on the machine, so keying on it
  # would make a run whose verdict never moved write nothing at all — and the
  # ancestry window would then have no `pace` row to show for the night. Keying
  # on the last `pace` row here bounds the series at one row per run plus one
  # per change, which is what an 8-row window can absorb.
  #
  # ABSENCE IS WRITTEN, NOT SKIPPED. A state that is missing, unreadable, on
  # another schema or older than three periods becomes `판정=(미상)` with the
  # tick and observation fields `-`: the row says the gate looked and found no
  # verdict, which the morning reader needs to tell apart from "the gate never
  # looked". Only `snapshot` never reaches here — it is a read and stays one.
  local state verdict reason tick obs last prev
  state=$(gate_pace_state)
  if [ -n "$state" ]; then
    verdict=$(printf '%s' "$state" | jq -r '.verdict // "(미상)"')
    reason=$(printf '%s' "$state" | jq -r '.verdict_reason // "(미상)"')
    tick=$(printf '%s' "$state" | jq -r '.tick_seq // "-"')
    obs=$(printf '%s' "$state" | jq -r '.computed_at // "-"')
  else
    verdict='(미상)'; reason='(미상)'; tick='-'; obs='-'
  fi
  last=$(gate_rows pace | tail -1)
  prev='(미상)'
  if [ -n "$last" ]; then
    prev=$(gate_row_field "$last" '판정')
    [ "$prev" = "$verdict" ] && return 0
  fi
  gate_append 'pace' "판정=$verdict" "이전=$prev" "기준 틱=$tick" "관측=$obs" "사유=$reason"
}

# ---------------------------------------------------------------------------
# The base branch's shared-failure reading, READ AND NEVER COMPUTED.
#
# The host's master stage keeps one file per (repository, base branch) under the
# pace root: what the base branch's tip fails with, as signatures, and the
# failure events those signatures belong to. This file reads it and copies it
# into the run's own ledger as a `master 판독` row; every disposition that uses
# it reads the row and nothing else, so `review_next[]` and the merge check
# judge from one observation and never from a file that moved between them.
#
# FRESHNESS IS THE ROW'S `관측` AGAINST THE CLOCK, NOT THE FILE'S AGE. A row the
# run wrote ten minutes ago from a file nobody has refreshed since is as old as
# that file, and the dispositions that wait on a red base fall back to today's
# behaviour once it is older than `GATE_MASTER_STALE_SECONDS`. The schema is
# compared by EQUALITY, as with the pace state: an unknown version is absence.
#
# NO FILE, NO ROW. A run on a host where the master stage has never written
# anything keeps exactly today's ledger — the first row appears when a file
# does, and the `(미상)` row is written only when a reading the run already
# holds goes away.
# ---------------------------------------------------------------------------
readonly GATE_MASTER_STALE_SECONDS=600
readonly GATE_MASTER_SCHEMA='cc-master-state v1'
# The row's two growing fields: the events it lists (about 35 bytes each) and
# the repair reasons it carries, sized so the widest row stays near 850 bytes.
readonly GATE_MASTER_EVENTS_MAX=10
readonly GATE_MASTER_REASON_MAX=160
# The match act's two bounds: one job log is cut at this many bytes before the
# adapter reads it, and one `gh` call is abandoned after this many seconds.
readonly GATE_CI_MATCH_LOG_MAX_BYTES=8388608
readonly GATE_CI_MATCH_GH_SECONDS=60

gate_master_enc() {
  # gate_master_enc <piece> — one piece of the file name with `%`, `/` and `_`
  # percent-encoded, so `__` joins the three pieces without ambiguity.
  printf '%s' "$1" | sed -e 's/%/%25/g' -e 's#/#%2F#g' -e 's/_/%5F/g'
}

gate_master_file() {
  # gate_master_file <owner/name> <base branch> — the reading's path.
  printf '%s/master/%s__%s__%s.json' "$(gate_pace_root)" \
    "$(gate_master_enc "${1%%/*}")" "$(gate_master_enc "${1#*/}")" "$(gate_master_enc "$2")"
}

gate_master_state() {
  # gate_master_state <owner/name> <base branch> — the file's object on one
  # line, or nothing for a file that is absent, unparseable or on another
  # schema. No freshness here: that is judged on the ledger row.
  local f s
  f=$(gate_master_file "$1" "$2")
  [ -r "$f" ] || return 0
  s=$(jq -c --arg schema "$GATE_MASTER_SCHEMA" 'select(type == "object" and .schema == $schema)' "$f" 2>/dev/null) || return 0
  printf '%s' "$s"
}

gate_master_last_row() {
  # gate_master_last_row <alias> — the target's newest `master 판독` row.
  gate_rows 'master 판독' | gate_rows_field_eq '대상' "$1" | awk 'NF { r = $0 } END { if (r != "") print r }'
}

gate_master_fresh() {
  # gate_master_fresh <alias> — the target's newest reading is a reading (not
  # `(미상)`) and its `관측` is within GATE_MASTER_STALE_SECONDS of now.
  local row ep now
  row=$(gate_master_last_row "$1")
  [ -n "$row" ] || return 1
  [ "$(gate_row_field "$row" '상태')" != '(미상)' ] || return 1
  ep=$(cc_iso_to_epoch "$(gate_row_field "$row" '관측')")
  [ -n "$ep" ] || return 1
  now=$(date -u +%s)
  [ $((now - ep)) -le "$GATE_MASTER_STALE_SECONDS" ]
}

gate_ci_signature() {
  # gate_ci_signature <subcommand> <args…> — the signature adapter beside this file.
  bash "$GATE_DIR/ci-signature.sh" "$@"
}

gate_ci_signature_file() {
  # gate_ci_signature_file <name> — where a signature list is kept: the rows
  # carry its count and fingerprint, the run directory carries the list. The
  # name is the list's fingerprint, or `event-<사건 id>` for an event's list —
  # an id is derived from the event's first commit and its signatures, so
  # either name stands for one list only.
  printf '%s/ci-signatures/%s.txt' "$RUN_DIR" "$1"
}

gate_ci_signature_keep() {
  # gate_ci_signature_keep <name> — stdin (the list) into its file, written
  # once and atomically; a list already kept under the same name is the same
  # list.
  local f tmp
  f=$(gate_ci_signature_file "$1")
  if [ -z "${RUN_DIR:-}" ] || [ -f "$f" ]; then cat > /dev/null; return 0; fi
  mkdir -p "${f%/*}" 2>/dev/null || { cat > /dev/null; return 0; }
  tmp=$(mktemp "${f%/*}/.sig.XXXXXX") || { cat > /dev/null; return 0; }
  cat > "$tmp"
  mv -f "$tmp" "$f" 2>/dev/null || rm -f "$tmp"
}

gate_master_reading() {
  # gate_master_reading <state json> — the row's fields as `키<TAB>값` lines, or
  # 1 when a value is outside its vocabulary (read as absence, like a schema
  # that does not match). The signature list is kept as a side effect.
  local s=$1 tip st prec obs sigs n fp ev reason
  tip=$(printf '%s' "$s" | jq -r '.tip // ""')
  st=$(printf '%s' "$s" | jq -r '.state // ""')
  prec=$(printf '%s' "$s" | jq -r '.precision // "-"')
  obs=$(printf '%s' "$s" | jq -r '.observed_at // ""')
  [[ $tip =~ ^[0-9a-f]{40}$ ]] || return 1
  case "$st" in 초록|빨강|'진행 중'|'판정 불가') ;; *) return 1 ;; esac
  case "$prec" in 단언|단계|-) ;; *) return 1 ;; esac
  [ -n "$(cc_iso_to_epoch "$obs")" ] || return 1
  sigs=$(printf '%s' "$s" | jq -r '(.signatures // [])[] | strings' 2>/dev/null | grep -v '^$' | LC_ALL=C sort -u || true)
  n=$(printf '%s\n' "$sigs" | gate_count)
  if [ "$n" -gt 0 ]; then
    fp=$(printf '%s\n' "$sigs" | gate_ci_signature fingerprint)
    printf '%s\n' "$sigs" | gate_ci_signature_keep "$fp"
  else
    fp='-'
  fi
  # `<id>:<처음 커밋 7>:<해소 커밋 7 | ->:<수리 상태>` per event, the newest
  # GATE_MASTER_EVENTS_MAX of them — the field grows with the base branch's
  # history and the row does not. An id or a repair state outside its
  # vocabulary would put a separator on the row, so either reads the file as
  # absent.
  ev=$(printf '%s' "$s" | jq -r --argjson m "$GATE_MASTER_EVENTS_MAX" '[(.events // [])[-$m:][] |
        [(.id // ""), ((.first_commit // "")[0:7]),
         ((.resolved_commit // "") | if . == "" then "-" else .[0:7] end),
         (.repair.state // "대기")] | join(":")] | join(",")' 2>/dev/null) || return 1
  if [ -n "$ev" ]; then
    # Lengths and a negated class rather than interval expressions, which the
    # awk shipped with macOS has not always read.
    printf '%s\n' "$ev" | tr ',' '\n' | LC_ALL=C awk -F':' '
      function hexn(v, n) { return length(v) == n && v !~ /[^0-9a-f]/ }
      !hexn($1, 12) || !hexn($2, 7) || !($3 == "-" || hexn($3, 7)) { bad = 1 }
      { st = $0; sub(/^[^:]*:[^:]*:[^:]*:/, "", st)
        if (st != "대기" && st != "보류" && st != "띄움" && st != "정지" && st != "띄울 수 없음" && st != "해소") bad = 1 }
      END { exit bad }' || return 1
    # Each listed event's signatures, for the match act's comparison set and
    # for a repair run's own event.
    local id
    for id in $(printf '%s' "$ev" | tr ',' '\n' | cut -d: -f1); do
      printf '%s' "$s" | jq -r --arg id "$id" \
        '[(.events // [])[] | select(.id == $id)][0].signatures // [] | .[] | strings' 2>/dev/null \
        | { grep -v '^$' || true; } | LC_ALL=C sort -u | gate_ci_signature_keep "event-$id"
    done
  else
    ev='-'
  fi
  reason=$(printf '%s' "$s" | jq -r '[(.events // [])[] | select((.repair.reason // "") != "") | (.id + " " + .repair.reason)] | join("; ")' 2>/dev/null || true)
  printf '팁\t%s\n상태\t%s\n정밀도\t%s\n서명 수\t%s\n서명 지문\t%s\n사건\t%s\n수리 사유\t%s\n관측\t%s\n' \
    "$tip" "$st" "$prec" "$n" "$fp" "$ev" "${reason:--}" "$obs"
}

gate_master_row_one() {
  # gate_master_row_one <alias> <owner/name> <base branch> — one target's row,
  # when the reading changed or a held reading is about to go stale.
  local al=$1 slug=$2 br=$3 s rd last tip st prec n fp ev reason obs ep lep now
  s=$(gate_master_state "$slug" "$br")
  last=$(gate_master_last_row "$al")
  rd=""
  [ -z "$s" ] || rd=$(gate_master_reading "$s") || rd=""
  if [ -z "$rd" ]; then
    { [ -n "$last" ] && [ "$(gate_row_field "$last" '상태')" != '(미상)' ]; } || return 0
    gate_append 'master 판독' "대상=$al" "팁=-" "상태=(미상)" "정밀도=-" "서명 수=0" \
      "서명 지문=-" "사건=-" "수리 사유=-" "관측=-"
    return 0
  fi
  tip=$(printf '%s\n' "$rd" | awk -F'\t' '$1 == "팁" { print $2 }')
  st=$(printf '%s\n' "$rd" | awk -F'\t' '$1 == "상태" { print $2 }')
  prec=$(printf '%s\n' "$rd" | awk -F'\t' '$1 == "정밀도" { print $2 }')
  n=$(printf '%s\n' "$rd" | awk -F'\t' '$1 == "서명 수" { print $2 }')
  fp=$(printf '%s\n' "$rd" | awk -F'\t' '$1 == "서명 지문" { print $2 }')
  ev=$(printf '%s\n' "$rd" | awk -F'\t' '$1 == "사건" { print $2 }')
  reason=$(printf '%s\n' "$rd" | awk -F'\t' '$1 == "수리 사유" { print $2 }')
  obs=$(printf '%s\n' "$rd" | awk -F'\t' '$1 == "관측" { print $2 }')
  if [ -n "$last" ] && [ "$(gate_row_field "$last" '팁')" = "$tip" ] \
     && [ "$(gate_row_field "$last" '상태')" = "$st" ] \
     && [ "$(gate_row_field "$last" '서명 지문')" = "$fp" ] \
     && [ "$(gate_row_field "$last" '사건')" = "$ev" ]; then
    # The same reading. It is written again only to keep it from going stale
    # while acts go on: when the held row is past half the bound and the file
    # has been observed since.
    lep=$(cc_iso_to_epoch "$(gate_row_field "$last" '관측')")
    ep=$(cc_iso_to_epoch "$obs")
    now=$(date -u +%s)
    [ -n "$lep" ] && [ -n "$ep" ] || return 0
    [ $((now - lep)) -gt $((GATE_MASTER_STALE_SECONDS / 2)) ] && [ "$ep" -gt "$lep" ] || return 0
  fi
  gate_append 'master 판독' "대상=$al" "팁=$tip" "상태=$st" "정밀도=$prec" "서명 수=$n" \
    "서명 지문=$fp" "사건=$ev" "수리 사유=$(gate_row_safe "$reason" "$GATE_MASTER_REASON_MAX")" "관측=$obs"
}

gate_master_row_if_changed() {
  # gate_master_row_if_changed — the `master 판독` rows of every target, on a
  # routed run. Called where the `pace` row is, and at a routing shift's start.
  local al slug br
  run_routed || return 0
  while IFS= read -r al; do
    [ -n "$al" ] || continue
    slug=$(target_field "$al" '원격 슬러그' 2>/dev/null || true)
    br=$(base_branch "$al" 2>/dev/null || true)
    { [ -n "$slug" ] && [ -n "$br" ]; } || continue
    gate_master_row_one "$al" "$slug" "$br"
  done <<EOF
$(target_aliases 2>/dev/null || true)
EOF
}

# ---------------------------------------------------------------------------
# Bounded reclamation of the state directory.
#
# WHERE, AND WHY ONLY THERE. The gate is re-entered on every verb, so the one
# place that runs exactly once per run is the run-open branch further down. A
# reap on every entry was ruled out by measurement rather than by taste: the
# busiest run's ledger carries 875 rows and gate entries outnumber them, which at
# ~400ms a victim is six minutes of pure overhead per run.
#
# 보존 기준 30일 — the retention floor, in seconds. This is the one constant here
# that gets restated outside its own declaration (in this block's prose and in
# the gate suite's fixtures), which is why it is the one that gets a lint:
# `scripts/lint-reap-retention.sh` extracts it from the line below and refuses a
# bare copy of the number anywhere else. The extraction anchors on the whole
# line, so this has to stay a single `readonly <NAME>=<digits>` and nothing more.
readonly GATE_REAP_RETENTION=2592000
# The other three correct themselves when wrong — a cap set too low leaves work
# for the next cycle, a budget set too tight ends the pass early, an interval set
# too long only delays it — so they get `readonly` and no lint. 20 x (75ms of
# state predicate + 400ms of removal), plus the pre-filter, the age checks and
# one index scan, is about 11.1s: the count cap and the wall clock bite together.
readonly GATE_REAP_MAX=20
readonly GATE_REAP_BUDGET_S=12
readonly GATE_REAP_INTERVAL=21600
# The metrics collector shares the reaper's cadence and lock SHAPE, not its
# state: a separate stamp, a separate lock directory, so neither cycle can
# switch the other off. Same interval because both are "once in a while, from
# whichever gate call happens to be first".
#
# THE ROUND DOES NOT RUN INSIDE THE CALLER'S GATE CALL. The caller pays for the
# stamp, the lock and the launch; the collector and the filing run in a
# detached `metrics-round` child. The collector's population read sits outside
# its own budget on purpose — counting it there once starved the first
# collection for good — and it grows with the number of ledgers, so a round run
# inside the caller made every verb that happened to meet an expired stamp wait
# for it, with nothing bounding the wait.
#
# The child's collector is cut after `GATE_METRICS_ROUND_TIMEOUT_S`. That is a
# guard against a hang, not a plan for a backlog. The lock expiry is longer than
# the deadline plus the filing tail (at most 5+k `gh` calls of
# `GATE_METRICS_GH_TIMEOUT_S` each), so a live round's lock is never broken
# under it, and shorter than the interval, so a child that died with the lock
# held does not hold the next round off.
readonly GATE_METRICS_INTERVAL=21600
readonly GATE_METRICS_LOCK_TTL=7200
readonly GATE_METRICS_ROUND_TIMEOUT_S=3600
# Per `gh` call of the filing path. A GitHub call that hangs would hold the
# round's lock for as long as it hangs; a timed-out call takes the branch a
# failed one already takes.
readonly GATE_METRICS_GH_TIMEOUT_S=10
# Where instrument issues go, whichever run's ledger the round was hosted by.
# They measure this plugin's own collector and compaction window, so they belong
# to this plugin's repository; left to gh, the destination would follow the
# hosting run's anchor checkout, its remotes and an inherited `GH_REPO`, and an
# issue body naming local paths would land in whatever repository that was. The
# tracker is public and every base files into it, so neither a title nor a body
# names the hosting checkout: both carry `gate_metrics_repo_tag` instead.
readonly GATE_METRICS_REPO=Nharu/cc-cmds
# The halt reporter has its own stamp and lock beside the two above, for the
# same reason they have theirs. Half an hour rather than six: a run that
# stopped for a reason nobody intended should be on the tracker before the
# morning, and the round costs one directory listing when nothing settled.
#
# THE DESTINATION IS A CONSTANT, NOT A SETTING. The repository, the Project
# number and its owner are where these reports belong whichever base the run
# came from, and a missing setting is not a reason to file nowhere.
readonly GATE_HALT_INTERVAL=1800
readonly GATE_HALT_LOCK_TTL=7200
readonly GATE_HALT_REPO=Nharu/cc-cmds
readonly GATE_HALT_PROJECT=1
readonly GATE_HALT_OWNER=Nharu
# gh writes per round — creations, comments and Project adds alike. What does
# not fit waits for the next round as `미룸`.
readonly GATE_HALT_WRITES_MAX=8
# A failed lookup and a failed Project add are each tried this many rounds.
readonly GATE_HALT_RETRIES=3
readonly GATE_HALT_SCHEMA='cc-halt-report-run v1'
# The fleet's backlog schema and park reasons, declared again here because the
# gate does not source `fleet.sh` (its `main` runs unguarded under errexit).
# The gate suite holds these against the fleet's own spelling.
readonly GATE_HALT_BACKLOG_SCHEMA='cc-pace-backlog v1'
readonly GATE_HALT_BACKLOG_REASONS='manifest-missing clock-incoherent deadline-passed doc-changed base-moved'

gate_reap_root() {
  printf '%s' "${XDG_STATE_HOME:-$HOME/.local/state}/cc-cmds"
}

gate_halt_root() {
  printf '%s' "$(gate_reap_root)/halt-report"
}

gate_halt_stamp() {
  printf '%s' "$(gate_reap_root)/halt.stamp"
}

gate_halt_lockdir() {
  printf '%s' "$(gate_reap_root)/.halt.lock"
}

gate_halt_record_path() {
  # gate_halt_record_path <run-id> — the run's record. A run id is checked for
  # being non-empty and nothing else, and names outside the usual shape exist
  # on real hosts, so only a name that is safe as a file name is used as one;
  # any other id is stored under the first 16 hex of its sha256, and the id
  # itself lives inside the record.
  #
  # The check deletes the allowed bytes and wants nothing left, newlines
  # included. A line-matching `grep` would pass an id whose first line is safe
  # and whose second is not, and on the right of a pipe it can fail under
  # `pipefail` by exiting early. The trailing `x` is there because command
  # substitution strips trailing newlines, which would hide one at the end.
  local id="$1" name
  if [ -n "$id" ] && [ "$id" != "." ] && [ "$id" != ".." ] \
     && [ "$(printf '%s' "$id" | LC_ALL=C tr -d 'A-Za-z0-9._-'; printf x)" = x ]; then
    name="$id"
  else
    name=$(printf '%s' "$id" | shasum -a 256 | cut -c1-16)
  fi
  printf '%s' "$(gate_halt_root)/runs/$name.json"
}

gate_halt_stops() {
  # gate_halt_stops <ledger> <run-dir> <manifest> — the classifier's lines.
  # `CC_HALT_STOPS` names another program for tests; the gate suite exports one
  # that prints nothing, so no fixture run ever reaches GitHub from a host that
  # holds a write credential.
  if [ -n "${CC_HALT_STOPS:-}" ]; then
    "$CC_HALT_STOPS" "$1" "$2" --manifest "$3"
  else
    bash "$GATE_DIR/run-stops.sh" "$1" "$2" --manifest "$3"
  fi
}

gate_halt_backlog() {
  # The fleet backlog the round reads. `CC_HALT_BACKLOG` set to a path names
  # another file; set and empty switches the fleet half off.
  if [ "${CC_HALT_BACKLOG+x}" = x ]; then
    printf '%s' "$CC_HALT_BACKLOG"
  else
    printf '%s' "$(gate_pace_root)/backlog.jsonl"
  fi
}

gate_metrics_stamp() {
  printf '%s' "$(gate_reap_root)/metrics.stamp"
}

gate_metrics_lockdir() {
  printf '%s' "$(gate_reap_root)/.metrics.lock"
}

gate_metrics_config_file() {
  printf '%s' "${CC_METRICS_FILING_FILE:-${XDG_CONFIG_HOME:-$HOME/.config}/cc-cmds/metrics-filing}"
}

gate_metrics_config() {
  # gate_metrics_config <key> — one value from the filing settings file, or
  # empty. `키<TAB>값` lines, the same shape as `plugin-pin`, and READ WITH awk
  # RATHER THAN SOURCED: the file sits in the user's config directory beside
  # credential files, and sourcing would execute whatever is there. Only the
  # two known keys are answered; `project` must be all digits or it reads as
  # absent, because a Project number is the only thing it can be.
  local f v
  f=$(gate_metrics_config_file)
  [ -f "$f" ] || return 0
  case "$1" in project|account) ;; *) return 0 ;; esac
  v=$(awk -F'\t' -v k="$1" '$1 == k { v = $2 } END { printf "%s", v }' "$f" 2>/dev/null || true)
  if [ "$1" = "project" ]; then
    case "$v" in ''|*[!0-9]*) v="" ;; esac
  fi
  printf '%s' "$v"
}

gate_metrics_collector() {
  # Resolved at CALL time, not at source time, so a test that sources this file
  # in-process can still point it at a stub.
  printf '%s' "${CC_METRICS_COLLECTOR:-$GATE_DIR/collect-run-metrics.sh}"
}

gate_metrics_gh() {
  # The `gh` program the filing path runs, resolved at call time like the
  # collector. A stub ahead on the caller's PATH cannot stand in for it: run.sh
  # puts the system prefixes first, so on a host whose `gh` is /usr/bin/gh (the
  # Ubuntu CI runner) the real program wins and the stub is never called — the
  # identity lookup then fails and every filing case reads `조회 실패`. A test
  # names the stub here instead. The value must name an external program, never
  # a function, for the reason `gate_metrics_timed` gives.
  printf '%s' "${CC_METRICS_GH:-gh}"
}

gate_reap_day_epoch() {
  # gate_reap_day_epoch <YYYYMMDD> — 00:00:00Z of that day in epoch seconds, or
  # empty for anything that is not eight digits or not a real date.
  #
  # ARITHMETIC RATHER THAN `date`. The two spellings that parse a date string,
  # `date -d` and `date -j`, are both on the portability lint's denylist because
  # they diverge between GNU and BSD, so the days-from-civil conversion is done
  # here instead. March is treated as the first month, which is what removes the
  # leap-day special case from the expression.
  local s="$1" y m d era yoe doy doe days
  case "$s" in
    [0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9]) ;;
    *) return 0 ;;
  esac
  y=$((10#${s:0:4})); m=$((10#${s:4:2})); d=$((10#${s:6:2}))
  { [ "$m" -ge 1 ] && [ "$m" -le 12 ]; } || return 0
  { [ "$d" -ge 1 ] && [ "$d" -le 31 ]; } || return 0
  [ "$m" -le 2 ] && y=$((y - 1))
  era=$(( (y >= 0 ? y : y - 399) / 400 ))
  yoe=$(( y - era * 400 ))
  doy=$(( (153 * (m + (m > 2 ? -3 : 9)) + 2) / 5 + d - 1 ))
  doe=$(( yoe * 365 + yoe / 4 - yoe / 100 + doy ))
  days=$(( era * 146097 + doe - 719468 ))
  printf '%s' $(( days * 86400 ))
}

gate_reap_eligible() {
  # gate_reap_eligible <run-dir> <run-id> <now> — 0 when all five clauses hold.
  #
  # FAIL-CLOSED IN EVERY CLAUSE. Reclamation needs positive evidence of age: a
  # clock that is missing, empty, unreadable or unparsable means "unknown", and
  # unknown is never reclaimed. The `age=$(cc_mtime …); [ -z "$age" ] && age=0`
  # shape is forbidden here for exactly that reason — it reads a ledger that a
  # `git clean` in some other repo removed as "1970, infinitely old", which turns
  # that command into a remote delete for this run's state directory.
  local rd="$1" id="$2" now="$3" started ledger state day_epoch
  # 4 — a symlink is not a candidate at all. This is also what makes the
  # slash-free victim path safe rather than merely tidy.
  [ ! -L "$rd" ] || return 1
  [ -d "$rd" ] || return 1
  # 3 — never the current run. Structurally unreachable anyway, because
  # `rundir_init` rewrites this run's `started-at` to `now` before the run-open
  # branch is reached, but the comparison is one test and says so out loud.
  [ "$rd" != "${RUN_DIR:-}" ] || return 1
  # 2 — the retention clock is the CONTENT of `started-at`, which `rundir_init`
  # rewrites on every gate entry. Its name says "run start" and its meaning is
  # "last gate entry", and the second is what retention actually asks: is anyone
  # still reaching for this? Selection sorts on `done`/ledger mtime instead, so
  # the two clocks diverge — measured, in one direction only (97 runs at +0 days,
  # 2 at +1, 1 at +2, 3 at +4, and zero the other way), because every gate entry
  # that could write `done` rewrote `started-at` first. Retention is therefore
  # always the more conservative of the two and the early-delete direction is
  # unreachable.
  started=$(sed -n '1s/^\([0-9][0-9]*\)$/\1/p' "$rd/started-at" 2>/dev/null || true)
  [ -n "$started" ] || return 1
  [ "$started" -gt 0 ] 2>/dev/null || return 1
  [ $((now - started)) -ge "$GATE_REAP_RETENTION" ] || return 1
  # 1 — terminal, evaluated HERE and never from a cache. A run with no
  # `ledger-path` hands an empty ledger to the predicate, which then counts zero
  # segments and cannot answer 종단, so those fall out of candidacy on their own.
  # The thresholds are passed explicitly rather than inherited, per the rule that
  # two consumers must not grade one run with two values; this clause's answer
  # happens to be independent of both.
  #
  # A RUN CARRYING `ends-on-done` THAT STOPPED IN ITS SETTLEMENT WINDOW never
  # reads 종단 — it ends on `done` and nobody wrote one — so it is a candidate
  # when `cc_run_settle_stuck` holds. That keeps its fate what it was before the
  # marker existed, when the same run read 종단 by derivation and was reclaimed
  # after the same retention.
  ledger=$(cat "$rd/ledger-path" 2>/dev/null || true)
  state=$(cc_run_state "$rd" "$ledger" 180 3600 2>/dev/null || true)
  [ "$state" = "종단" ] || cc_run_settle_stuck "$rd" "$ledger" || return 1
  # 5 — an id that parses as a date must not be NEWER than the retention clock it
  # is paired with. An id that does not parse passes: the clause is a conditional
  # and its antecedent is "parses as a date".
  case "$id" in
    [0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9]-*)
      day_epoch=$(gate_reap_day_epoch "${id%%-*}")
      [ -n "$day_epoch" ] || return 0
      [ "$day_epoch" -le "$started" ] || return 1
      ;;
  esac
  return 0
}

gate_reap_note() {
  # One line of PROSE into this run's report, which is the same file as its
  # ledger. Deliberately not a row: every row predicate anchors on a backticked
  # series token at the start of the line, so a line opening with a timestamp is
  # invisible to all of them and is counted toward no termination condition.
  # `gate_drain_notify_state` is the existing precedent for the shape.
  #
  # THE REPORT OF THE RUN THAT DID THE REAPING, not of the run that was reaped.
  # The victim's report is a closed record of a finished run, may live in another
  # repo entirely, and would have the run writing down that it was deleted.
  [ -n "${LEDGER:-}" ] || return 0
  printf '%s · %s\n' "$(now_iso)" "$1" >> "$LEDGER" 2>/dev/null || true
  return 0
}

gate_reap_unwind() {
  # gate_reap_unwind <trash> <run-dir> <id> <now> — the last reversal point of a
  # reclamation. Returns 0 when the victim was NOT reclaimed (restored, or parked
  # in the trash under a `.keep`), 1 when its clock still says reclaim and the
  # caller should proceed with the removal.
  #
  # THE RETENTION CLOCK IS READ AGAIN, AFTER THE RENAME. Nothing holds a lock on
  # the victim between the verdict and this call: `.reap.lock` excludes reapers
  # from one another and says nothing about the run being judged, and the
  # never-the-current-run clause compares against the reaping process's own
  # `RUN_DIR` only. So an ordinary gate entry can land on this id after the
  # eligibility clock was read — and `rundir_init` rewrites `started-at` to now
  # on every entry — while the reaper is still inside `cc_run_state` and the
  # recursive `du -sk` walk.
  #
  # Deleting through that window does not merely lose a live run. The run's own
  # verbs carry on to an unguarded `mkdir -p "$RUN_DIR/log"` and rebuild the
  # directory with no `started-at` in it, which the eligibility clock then
  # refuses forever while the `-mtime` pre-filter hides it for another 25 days:
  # this feature would be manufacturing the immortal run it exists to remove.
  #
  # The rename is what makes the re-read possible and it is the last moment at
  # which the deletion is still reversible. `started-at` moved with the
  # directory, so a writer that got in first left its bytes on this same inode,
  # and reading them costs one `sed`. A missing or zero clock is "unknown" and
  # unknown is not reclaimed, exactly as in the eligibility clause.
  #
  # IT IS A FUNCTION AND NOT THREE LINES INLINE because the only way into its two
  # outcomes is a race the caller cannot stage: the fresh clock has to be written
  # by some other process in the window between two reads of one file. Inline,
  # both arms were unreachable from any test — the whole re-verification could be
  # deleted with the suite staying green — and a cross-review found a real defect
  # inside one of them. Named, each arm is reached by calling this with the state
  # the race would have produced.
  local trash="$1" rd="$2" id="$3" now2="$4" started2
  started2=$(sed -n '1s/^\([0-9][0-9]*\)$/\1/p' "$trash/started-at" 2>/dev/null || true)
  if [ -n "$started2" ] && [ "$started2" -gt 0 ] 2>/dev/null \
     && [ $((now2 - started2)) -ge "$GATE_REAP_RETENTION" ]; then
    return 1
  fi
  # PUT IT BACK ONLY IF ITS PLACE IS STILL EMPTY. `mv a b` with `b` an existing
  # directory moves `a` INSIDE it, so an unguarded restore against an
  # already-resurrected `run/<id>` would nest the old run under the new one — a
  # second husk, in a stranger shape than the one being avoided. When the place
  # is taken the copy stays in the trash under a `.keep` sibling the sweep
  # honours, because at that moment it is the only copy of the run's handles and
  # settings that exists.
  #
  # THE `mv` RESULT IS PART OF THE CONDITION rather than assumed: a restore that
  # fails after the emptiness test passes — the place filled in between, the
  # filesystem refused — would otherwise write "restored" into the report for a
  # directory still sitting in the trash, and the report is the only record that
  # the reclamation was undone.
  if [ ! -e "$rd" ] && mv "$trash" "$rd" 2>/dev/null; then
    gate_reap_note "회수 취소: 런 $id — 판정 이후 보존 시계가 신선해져 제자리로 되돌렸다"
  else
    : > "$trash.keep" 2>/dev/null || true
    gate_reap_note "회수 보류: 런 $id — 판정 이후 보존 시계가 신선해졌으나 제자리가 이미 차 있어 .reap-trash 에 남긴다"
  fi
  return 0
}

gate_reap_lock() {
  # gate_reap_lock <root> — ONE ATTEMPT, NO WAITING. Contention means another
  # gate is already reaping, so the work is being done and queueing behind it
  # buys nothing. That is why this cannot be `gate_settings_lock`, which waits;
  # and `ledger.lock` is worse still — it is scoped per run, it guards a file in
  # the repo, and it lives INSIDE a directory a reap may be deleting.
  #
  # A lock older than fifteen minutes is broken, judged from the owner line
  # written straight after the `mkdir`. Without that line the expiry cannot be
  # decided at all, and what a never-expiring lock produces here is a reaper that
  # is switched off forever with no symptom.
  local root="$1" lock owner ots now
  lock="$root/.reap.lock"
  if mkdir "$lock" 2>/dev/null; then
    printf '%s %s\n' "$$" "$(date -u +%s)" > "$lock/owner" 2>/dev/null || true
    return 0
  fi
  owner=$(cat "$lock/owner" 2>/dev/null || true)
  ots=$(printf '%s' "$owner" | sed -n 's/^[0-9][0-9]*[[:space:]][[:space:]]*\([0-9][0-9]*\)$/\1/p')
  # AN UNREADABLE OWNER LINE FALLS BACK TO THE LOCK DIRECTORY'S OWN mtime, and
  # refusing outright was the bug rather than the caution. Refusing was meant to
  # avoid racing a live holder, but it also made an owner-less lock PERMANENT,
  # and that shape was reachable with no crash at all: the release used to remove
  # the owner line and then the directory, so every ordinary release passed
  # through it, and any failure of the second step froze the reaper for good with
  # no symptom anywhere. The directory is created by the `mkdir` above and its
  # mtime is set then, so it dates the acquisition exactly as the owner line
  # does — a holder younger than the expiry is still protected, because the same
  # threshold decides both.
  [ -n "$ots" ] || ots=$(gate_mtime "$lock")
  [ -n "$ots" ] || return 1
  now=$(date -u +%s)
  [ $((now - ots)) -ge 900 ] || return 1
  rm -rf "$lock" 2>/dev/null || true
  mkdir "$lock" 2>/dev/null || return 1
  printf '%s %s\n' "$$" "$(date -u +%s)" > "$lock/owner" 2>/dev/null || true
  return 0
}

gate_reap_sweep() {
  # gate_reap_sweep <root> <cycle-start> — empties `.reap-trash/` and prints the
  # names it has given up on, space separated.
  #
  # An entry there is a directory whose rename succeeded and whose removal did
  # not. It is invisible to every enumeration of runs, because `.reap-trash/` is
  # a SIBLING of `run/`, but it still holds the bytes the cycle came for.
  local root="$1" start="$2"
  local trash entry name fails now swept=0 gave_up=""
  trash="$root/.reap-trash"
  [ -d "$trash" ] || return 0
  for entry in "$trash"/*; do
    # Also what skips the `.fails` and `.keep` siblings: those are files.
    [ -d "$entry" ] || continue
    # A `.keep` SIBLING IS A DELIBERATE HOLD, NOT A LEFTOVER. The deletion loop
    # writes one when a victim's retention clock turned out to be fresh after
    # the rename and its place in `run/` had already been taken. The copy here
    # is then the only one there is, so sweeping it would destroy the very run
    # the re-read had just saved. It is not folded into `gave_up`: that name
    # means "the OS refused to remove this", and reporting a deliberate hold
    # under it would erase the distinction. The record of the hold is the
    # `회수 보류` line written at the moment it happened.
    [ ! -e "$entry.keep" ] || continue
    now=$(date -u +%s)
    [ "$swept" -lt "$GATE_REAP_MAX" ] || break
    [ $((now - start)) -lt "$GATE_REAP_BUDGET_S" ] || break
    name=$(basename "$entry")
    fails=$(sed -n '1s/^\([0-9][0-9]*\)$/\1/p' "$entry.fails" 2>/dev/null || true)
    [ -n "$fails" ] || fails=0
    # THREE STRIKES AND THE NAME GOES IN THE SUMMARY LINE. Retrying forever turns
    # a local failure into a global one — it eats the cycle's budget every cycle.
    if [ "$fails" -ge 3 ]; then gave_up="$gave_up $name"; continue; fi
    rm -rf "$entry" 2>/dev/null || true
    if [ ! -e "$entry" ]; then
      rm -f "$entry.fails" 2>/dev/null || true
    else
      printf '%s\n' "$((fails + 1))" > "$entry.fails" 2>/dev/null || true
    fi
    swept=$((swept + 1))
  done
  printf '%s' "${gave_up# }"
  return 0
}

gate_index_lock() {
  # gate_index_lock <index-file> — a mutex over ONE forward session index file,
  # held by the appender and by the prune's swap. Returns 0 when held, 1 when
  # the caller must go without it.
  #
  # WHY A LOCK AT ALL, when the append side spent a paragraph explaining that it
  # does not take one. The two sides had written down contracts that cannot both
  # be true: the appender said a lost id SELF-HEALS on the session's next gate
  # entry and left the hazard to the prune, while the prune said a lost append
  # is the one failure it is not allowed to have. Its compare-and-swap cannot
  # deliver that — the (size, mtime) pair is re-read BEFORE the `mv`, so an
  # append landing between the comparison and the rename is overwritten by a
  # swap that already decided nothing had moved. Check-then-act with another
  # writer in the gap is not a guarantee, it is a narrow window, and that window
  # has been observed closing TWICE. Once locally while eight other suites were
  # running, which is the reading the issue was filed on and which reads as "make
  # enough load and it reproduces". Then on a CI runner, where by the time this
  # suite reached the assertion the job's other fifteen had been finished for
  # twenty minutes and it was the only thing running. So load OUTSIDE this suite
  # is not what opens it. Load inside is — the case runs a writer against the
  # reaper on purpose, and without a concurrent writer there is no window at all,
  # because check-then-act with nobody in the gap does nothing.
  #
  # `mkdir` because it is atomic on every filesystem this runs on and needs no
  # external tool, the same reason the settings mutex uses it. The lock is PER
  # INDEX FILE, not over the directory: two sessions appending to their own
  # indexes have no reason to wait on each other, and the prune walks files one
  # at a time anyway.
  #
  # THE BUDGET IS DELIBERATELY SHORT. The appender runs on every gate entry —
  # over 875 times in the busiest run measured — so the thing that must not
  # happen is a gate entry stalling behind a reaper. Twenty sleeps of 50ms
  # across twenty-one `mkdir` attempts hold the wait to about a second — about,
  # because `sleep` is a floor rather than a ceiling and the attempts fork. A
  # caller that times out is expected to skip its
  # write rather than force it: that is exactly the self-healing the append side
  # already documented, and it is now the ONLY path that skips, instead of being
  # a property invoked to excuse a race.
  #
  # THAT BUDGET IS PER INDEX FILE, not per cycle, and the prune walks every file
  # in the directory. A cycle that meets N locked indexes waits about N seconds,
  # and nothing caps the total. At this tree's scale the prune runs on a sparse
  # cadence and meets contention almost never, so the sum has not been worth
  # bounding; a tree with many actively-appended session indexes would have to
  # revisit it.
  #
  # A LOCK THAT OUTLIVES ITS HOLDER EXPIRES, and leaving that out would have been
  # worse here than anywhere else in this file. The settings mutex can refuse
  # forever and stay safe, because a caller that cannot take it returns its
  # previous answer; a caller that cannot take THIS one skips its write. A
  # lockdir left behind by a process killed between the `mkdir` and the release
  # would therefore switch off this session's index updates permanently and the
  # prune's pass over that file with them, with no symptom anywhere. The reap
  # lock already had to learn this and the shape is copied from it: an owner line
  # written straight after the `mkdir`, the directory's own mtime as the fallback
  # when that line cannot be read, and a threshold that decides both.
  #
  # SIXTY SECONDS, against a critical section measured in milliseconds — one
  # file's scan and rename, or one `grep` and one `printf`. Four orders of
  # magnitude of headroom is what keeps the expiry from ever reaching a live
  # holder, and the reap lock's fifteen minutes would be the wrong number for
  # the same reason in the other direction: this path runs on every gate entry.
  local lockdir="$1.lock" waited=0 owner ots now dead
  while ! mkdir "$lockdir" 2>/dev/null; do
    waited=$(( waited + 1 ))
    if [ "$waited" -gt 20 ]; then
      owner=$(cat "$lockdir/owner" 2>/dev/null || true)
      ots=$(printf '%s' "$owner" | sed -n 's/^[0-9][0-9]*[[:space:]][[:space:]]*\([0-9][0-9]*\)$/\1/p')
      [ -n "$ots" ] || ots=$(gate_mtime "$lockdir")
      # "THE LOCK IS GONE" AND "THE LOCK CANNOT BE DATED" ARE DIFFERENT EVENTS
      # and used to fall down the same branch. If the holder releases between
      # the last failed `mkdir` and the `cat` above, the owner line is
      # unreadable AND the directory has no mtime, so both reads come back
      # empty — and giving up there skips a write against a lock that is not
      # there any more. One attempt separates them: it succeeds exactly when the
      # lock is gone, and fails exactly when the lock is present but undateable,
      # which is the case that must still give up.
      if [ -z "$ots" ]; then
        mkdir "$lockdir" 2>/dev/null || return 1
        break
      fi
      now=$(date -u +%s)
      [ $((now - ots)) -ge 60 ] || return 1
      # THE STEAL IS A RENAME, so exactly one waiter wins it. `rm -rf` and then
      # `mkdir` lets two waiters that timed out together both believe they hold
      # the lock: the second `rm -rf` removes the directory the first has just
      # created. A rename names one winner and the losers get ENOENT. Whoever
      # loses the `mkdir` that follows returns 1 and skips this write, which is
      # the same safe direction as any other failure to take the lock.
      dead="$lockdir.dead.$$.$now"
      mv "$lockdir" "$dead" 2>/dev/null || return 1
      rm -rf "$dead" 2>/dev/null || true
      mkdir "$lockdir" 2>/dev/null || return 1
      break
    fi
    sleep 0.05
  done
  printf '%s %s\n' "$$" "$(date -u +%s)" > "$lockdir/owner" 2>/dev/null || true
  return 0
}

gate_index_unlock() {
  # THE RELEASE IS ONE RENAME, the form the reap lock already arrived at. An
  # earlier version of this function used a single `rm -rf`, on the reasoning
  # that not producing an owner-less lock is cheaper than covering one — but
  # `rm -rf` on a directory unlinks the owner line and THEN removes the
  # directory, so that version passed through the very state it claimed not to
  # produce, on every ordinary release, and leaned entirely on the mtime
  # fallback it was arguing against.
  #
  # THE DESTINATION CARRIES THE PID AND A TIMESTAMP because `mv` into a
  # directory that already exists moves the source INSIDE it rather than
  # failing. A fixed name would nest retired locks inside one another the first
  # time a pid was reused and a cleanup had failed, and the nested one would
  # never be walked again.
  #
  # THE RETIRED LOCK LANDS IN THE SESSION DIRECTORY, which is not where the reap
  # lock puts its own — that one retires into a place nothing enumerates, so its
  # comment can say no scan walks it. This one does not get to say that: the
  # prune globs this directory every cycle. It is still harmless, because that
  # walk takes `[ -f "$f" ]` and a retired lock is a directory. What it is not
  # is free — an `rm -rf` that keeps failing leaves them to accumulate and the
  # glob grows.
  local dead="$1.lock.dead.$$.$(date -u +%s)"
  if mv "$1.lock" "$dead" 2>/dev/null; then
    rm -rf "$dead" 2>/dev/null || true
  fi
}

gate_reap_prune_index() {
  # gate_reap_prune_index <root> <pair-file> — drops from the forward session
  # index every entry whose run directory is gone, and appends one
  # `<id> <index-file-name>` line per removal to <pair-file>, which is what lets
  # each victim's report line name its own share.
  #
  # THE CRITERION IS RE-DERIVED FROM DISK rather than carried over from the
  # deletions above, and that is what makes the prune STATELESS BETWEEN CYCLES: a
  # file this cycle gives up on is simply walked again by the next one. Carrying
  # the id list instead would make "given up for this cycle" indistinguishable
  # from "stuck forever", because the next cycle would arrive with a different
  # list and never look at the skipped file's real contents again.
  #
  # ONE BATCH SCAN PER CYCLE, not one per victim: the scan cost is FLAT in the
  # number of victims (0.40s for one, 0.37s for three). The reverse index cannot
  # stand in for it — `session-lineage` covers 143 of 930 forward entries,
  # because the forward append has no stage guard and lineage does.
  #
  # AFTER THE DELETIONS, and the order is the whole point of the criterion. Run
  # before them and every victim still has a directory, so nothing is pruned at
  # all; run after and the entries that survive are exactly the runs that did. An
  # index entry whose directory is gone is a stale pointer the reader already
  # filters out; a directory whose index entry is gone is a live run nobody can
  # find.
  #
  # COMPARE AND SWAP ON (size, mtime), immediately before the swap, and the
  # contract is SAFETY GUARANTEED, PROGRESS NOT. The append side takes no lock
  # and runs on every gate entry, so a naive read-modify-write loses concurrent
  # appends — measured 384 to 401 of 1200. Re-reading both turns that loss into a
  # skip. Under unbroken append pressure every attempt skips and nothing is ever
  # pruned (0 writes in 3600 appends); at the cadence a real gate produces, 6 of
  # 6 succeeded on the first try. The asymmetry is the right way round: a lost
  # append costs that session its status-line pin, while an unpruned entry costs
  # nothing at all, since the reader skips entries whose directory is gone.
  local root="$1" pairs="$2"
  local dir f tmp line kept dropped n_after size_before size_after
  local mtime_before mtime_after
  dir="$root/session"
  [ -d "$dir" ] || return 0
  for f in "$dir"/*; do
    [ -f "$f" ] || continue
    case "$f" in *.reap-tmp.*) continue ;; esac
    # THE FIRST PASS ONLY ASKS WHETHER THERE IS ANYTHING TO DROP, and it forks
    # nothing. Most index files have no stale entry at all, and they leave here
    # without paying for the two stat calls the swap below needs.
    dropped=""
    while IFS= read -r line; do
      [ -n "$line" ] || continue
      [ -d "$root/run/$line" ] || { dropped="있음"; break; }
    done < "$f"
    [ -n "$dropped" ] || continue
    # THE SWAP RUNS UNDER THE INDEX LOCK, and everything from the stamp to the
    # rename is inside it. Without the lock the comparison below is a
    # check-then-act: it is re-read before the `mv`, so an append arriving in
    # the gap between them is silently overwritten by a rename that has already
    # decided the file did not move. Failing to take the lock means giving this
    # file up for this cycle, which costs nothing — the criterion is re-derived
    # from disk next cycle, and an unpruned entry is one the reader skips.
    gate_index_lock "$f" || continue
    # THE STAMP IS TAKEN BEFORE THE READ IT GUARDS, and that order is the whole
    # of what makes the comparison below mean anything. Reading first and
    # stamping afterwards leaves a window — from the last line read to the
    # stamp — in which an append lands, is counted into `size_before`, matches
    # `size_after` exactly, and is dropped by a swap that believes nothing
    # moved. The second pass re-reads underneath the stamp, so an append in that
    # window is either seen by the read or caught by the comparison. A lost
    # append is the one failure this function is not allowed to have.
    size_before=$(wc -c < "$f" 2>/dev/null | tr -d ' ')
    mtime_before=$(gate_mtime "$f")
    kept=""; dropped=""
    while IFS= read -r line; do
      [ -n "$line" ] || continue
      if [ -d "$root/run/$line" ]; then
        kept="$kept$line
"
      else
        dropped="$dropped$line
"
      fi
    done < "$f"
    [ -n "$dropped" ] || { gate_index_unlock "$f"; continue; }
    # The temp file is in the SAME directory, so the swap is one `rename(2)`.
    tmp="$f.reap-tmp.$$"
    printf '%s' "$kept" > "$tmp" 2>/dev/null || { gate_index_unlock "$f"; continue; }
    n_after=$(grep -c . "$tmp" 2>/dev/null || true)
    [ -n "$n_after" ] || n_after=0
    # THE COMPARISON STAYS even though the lock now excludes the appender, and
    # it is not redundant. The lock has a give-up budget, so a writer that could
    # not take it is free to proceed without one; and a file left behind by an
    # interrupted reaper leaves a stale lockdir that the next cycle will take.
    # Keeping the stamp means the swap refuses whenever the file moved, whoever
    # moved it, and the lock turns that refusal from the common case into the
    # rare one.
    size_after=$(wc -c < "$f" 2>/dev/null | tr -d ' ')
    mtime_after=$(gate_mtime "$f")
    if [ "$size_after" != "$size_before" ] || [ "$mtime_after" != "$mtime_before" ]; then
      # Give this file up FOR THIS CYCLE and leave no state behind.
      rm -f "$tmp" 2>/dev/null || true
      gate_index_unlock "$f"
      continue
    fi
    if [ "$n_after" -eq 0 ]; then
      # An index with nothing left in it is REMOVED, not emptied.
      rm -f "$f" "$tmp" 2>/dev/null || true
    else
      mv "$tmp" "$f" 2>/dev/null || {
        rm -f "$tmp" 2>/dev/null || true
        gate_index_unlock "$f"
        continue
      }
    fi
    gate_index_unlock "$f"
    while IFS= read -r line; do
      [ -n "$line" ] || continue
      printf '%s %s\n' "$line" "$(basename "$f")" >> "$pairs" 2>/dev/null || true
    done <<< "$dropped"
  done
  return 0
}

gate_reap_locked() {
  # gate_reap_locked <root> — the body, split out so the unlock has one caller
  # rather than one per return path. This file has no `trap` habit
  # (`gate_settings_unlock` is called by hand on each path), so the split follows
  # that rather than introducing one.
  local root="$1"
  local start now cand cand_list id rd trash kb bytes days started
  local now2 started2
  local recfile pairs v_items v_files sweep_note
  local deleted=0 candidates=0 total_bytes=0 capped="미도달" gave_up=""
  start=$(date -u +%s)

  # THE SWEEP GOES FIRST, and draws on the same wall clock as the deletions.
  gave_up=$(gate_reap_sweep "$root" "$start")

  mkdir -p "$root/.reap-trash" 2>/dev/null || true
  recfile=$(mktemp "${TMPDIR:-/tmp}/cc-reap-rec.XXXXXX" 2>/dev/null) || return 1
  pairs=$(mktemp "${TMPDIR:-/tmp}/cc-reap-pairs.XXXXXX" 2>/dev/null) \
    || { rm -f "$recfile" 2>/dev/null || true; return 1; }

  # THE PRE-FILTER IS A SUPERSET AND NOTHING MORE. `+25` rather than `+30` is
  # SLACK, not a constant: BSD `find -mtime +30` selects 31 days and over —
  # measured, it missed exactly 30 days, 30 days + 1 second and 30 days + 12
  # hours, a one-day systematic error rather than a rounding edge — so five days
  # of margin keeps this a superset of the authoritative check on any `find`.
  # THE POLICY IS DEFINED BY THE EPOCH ARITHMETIC IN `gate_reap_eligible` AND BY
  # NOTHING ELSE. Anyone "tidying" this to 30 restores that error.
  cand_list=$(find "$root/run" -maxdepth 1 -mindepth 1 -type d -mtime +25 2>/dev/null || true)
  candidates=$(printf '%s' "$cand_list" | grep -c . || true)
  [ -n "$candidates" ] || candidates=0

  while IFS= read -r cand; do
    [ -n "$cand" ] || continue
    now=$(date -u +%s)
    if [ "$deleted" -ge "$GATE_REAP_MAX" ] \
       || [ $((now - start)) -ge "$GATE_REAP_BUDGET_S" ]; then
      capped="걸림"; break
    fi
    # The victim path is assembled from a basename off the directory listing and
    # nothing else — no manifest string, no ledger field, nothing a model wrote —
    # and carries NO TRAILING SLASH, because `rm -rf dir/` follows a symlink on
    # BSD.
    id=$(basename "$cand")
    rd="$root/run/$id"
    gate_reap_eligible "$rd" "$id" "$now" || continue
    started=$(sed -n '1s/^\([0-9][0-9]*\)$/\1/p' "$rd/started-at" 2>/dev/null || true)
    days=$(( (now - started) / 86400 ))
    # Measured BEFORE the rename: after the removal there is nothing left to
    # measure. `du -sk` reports allocation blocks, so this is size on disk rather
    # than the sum of the file lengths.
    kb=$(du -sk "$rd" 2>/dev/null | sed -n '1s/^\([0-9][0-9]*\).*/\1/p')
    [ -n "$kb" ] || kb=0
    bytes=$((kb * 1024))
    trash="$root/.reap-trash/$id.$$.$now"
    # RENAME, THEN DELETE. `rm -rf` under a concurrent writer does not fail
    # cleanly — measured rc=1 with a `watch.heartbeat`-only husk left in place,
    # and a husk with no `ledger-path` counts zero segments and is permanently
    # non-terminal. A partially failed reclamation would therefore MANUFACTURE
    # the immortal run this whole change exists to remove. One atomic
    # `rename(2)` takes the directory out of `run/` first.
    mv "$rd" "$trash" 2>/dev/null || continue
    # THE RETENTION CLOCK IS READ AGAIN, AFTER THE RENAME. Nothing holds a lock
    # on the victim between the verdict and this line: `.reap.lock` excludes
    # reapers from one another and says nothing about the run being judged, and
    # clause 3 compares against THIS process's `RUN_DIR` only. So an ordinary
    # gate entry can land on this id after clause 2 read its clock — and
    # `rundir_init` rewrites `started-at` to now on every entry — while the
    # reaper is still inside `cc_run_state` and the recursive `du -sk` walk
    # above. That is hundreds of milliseconds per victim, times up to
    # `GATE_REAP_MAX` victims a cycle.
    #
    # Deleting through that window does not merely lose a live run. The run's
    # own verbs carry on to an unguarded `mkdir -p "$RUN_DIR/log"` and rebuild
    # the directory with no `started-at` in it, which clause 2 then refuses
    # forever while the `-mtime` pre-filter hides it for another 25 days: this
    # feature would be manufacturing the immortal run it exists to remove.
    #
    # The rename is what makes the re-read possible and it is the last moment at
    # which the deletion is still reversible. `started-at` moved with the
    # directory, so a writer that got in first left its bytes on this same
    # inode, and reading them costs one `sed`. A missing or zero clock is
    # "unknown" and unknown is not reclaimed, exactly as in clause 2.
    if gate_reap_unwind "$trash" "$rd" "$id" "$(date -u +%s)"; then
      continue
    fi
    # A failing removal now leaves the bytes in the trash rather than a husk in
    # `run/`, and the next cycle's sweep takes it from there.
    rm -rf "$trash" 2>/dev/null || true
    deleted=$((deleted + 1))
    total_bytes=$((total_bytes + bytes))
    printf '%s\t%s\t%s\n' "$id" "$days" "$bytes" >> "$recfile" 2>/dev/null || true
  done <<< "$cand_list"

  gate_reap_prune_index "$root" "$pairs"

  # One line per deletion, then one summary line. The per-deletion line carries
  # the run id (the surviving ledger is findable by it), the age AND WHAT THE AGE
  # IS OF — "since the last gate entry", not "since it ended", because the two
  # clocks diverge and an unnamed age is read as the wrong one — the byte count
  # (the only size information that outlives the directory) and the index share.
  # IT DOES NOT CARRY A PATH: the path derives from the id and the state root,
  # and a path in a report is a thing somebody pastes into a command.
  while IFS="$(printf '\t')" read -r id days bytes; do
    [ -n "$id" ] || continue
    v_items=$(grep -c "^$id " "$pairs" 2>/dev/null || true)
    [ -n "$v_items" ] || v_items=0
    v_files=$( { grep "^$id " "$pairs" 2>/dev/null || true; } \
                 | LC_ALL=C sort -u | grep -c . || true )
    [ -n "$v_files" ] || v_files=0
    gate_reap_note "회수: 런 $id — 마지막 게이트 진입 이후 ${days}일 · ${bytes}바이트 · 인덱스 항목 ${v_items}개/${v_files}개 파일에서 제거"
  done < "$recfile"

  # THE SUMMARY IS WRITTEN EVEN WHEN NOTHING WAS DELETED. That is what separates
  # "nothing qualified" from "the reaper never ran" — the distinction this
  # codebase keeps drawing about silence. It is not written when the cadence gate
  # returned early, because that is "not this cycle's turn" rather than "ran and
  # found none".
  now=$(date -u +%s)
  sweep_note=""
  if [ -n "$gave_up" ]; then sweep_note=" · 스윕 포기: $gave_up"; fi
  gate_reap_note "회수 요약: 후보 ${candidates}건 · 삭제 ${deleted}건 · 상한 ${capped} · $((now - start))초 · ${total_bytes}바이트${sweep_note}"

  rm -f "$recfile" "$pairs" 2>/dev/null || true
  return 0
}

gate_reap_cycle() {
  local root stamp now rc lock dead
  root=$(gate_reap_root)
  [ -d "$root/run" ] || return 0
  now=$(date -u +%s)
  # THE CADENCE GATE, one cheap read. autopilot opens runs in bursts, so "once
  # per run" is not the same as "rarely".
  #
  # NOT fail-closed, unlike the retention predicate. A missing or unparsable
  # stamp means "this has never run", not "we cannot tell how old something is":
  # the stamp answers whose turn it is, never whether a directory may die.
  stamp=$(sed -n '1s/^\([0-9][0-9]*\)$/\1/p' "$root/reap.stamp" 2>/dev/null || true)
  if [ -n "$stamp" ] && [ $((now - stamp)) -lt "$GATE_REAP_INTERVAL" ]; then
    return 0
  fi
  gate_reap_lock "$root" || return 0
  gate_reap_locked "$root"; rc=$?
  # THE STAMP ADVANCES WHETHER OR NOT THE CAP WAS HIT. Candidates left over wait
  # for the next window rather than being picked up by the next run-open, which
  # is the premise the backlog arithmetic rests on — 103 directories in about six
  # cycles rather than in one burst.
  date -u +%s > "$root/reap.stamp" 2>/dev/null || true
  # THE RELEASE IS ONE RENAME, so no moment exists in which the lock stands
  # without its owner line. Removing the owner and then the directory put every
  # ordinary release through that state, and a `rmdir` that failed for any reason
  # — a leftover artifact inside, `EBUSY`, a filesystem that renames on delete —
  # left behind a lock nothing could date and nothing could break. What this form
  # leaves behind when its own cleanup fails is an inert directory beside the
  # lock: no scan here walks it and no later cycle consults it.
  lock="$root/.reap.lock"
  dead="$lock.dead.$$"
  if mv "$lock" "$dead" 2>/dev/null; then
    rm -rf "$dead" 2>/dev/null || true
  fi
  return $rc
}

# ---------------------------------------------------------------------------
# Run settings — one file per stage kind, written by the gate, injected by the
# wrapper.
#
# This file is the premise of three separate decisions and had no producing step
# in any of them; two of those decisions also disagreed about its shape, one
# calling for a single shared file and the other for a `design`-specific variant.
# It is settled here: a DIRECTORY under the run directory with one file per stage
# kind, the common gate hook in every variant, and the two web research tools
# (`WebFetch`, `WebSearch`) allowed in every stage variant and denied in the
# shift variant only.
#
# The whole directory is an enforcement surface, not one file inside it — the
# digest set the gate re-derives on every hook consultation takes the directory
# as its element, because adding a variant must not be a way to escape the
# comparison.
# ---------------------------------------------------------------------------
# `shift` IS A SETTINGS VARIANT, NOT A UNIT OF WORK. Nothing dispatches into
# it — it IS the routing loop, moved out of the lead session and into a
# headless one. It is on this list because this list is what
# `gate_write_settings` iterates and what `gate_settings_file` resolves
# against, and the shift needs a settings file of its own precisely so it can
# be handed LESS than any stage gets.
#
# TWO LAYERS, TWO NAMES, AND THEY ARE NOT THE SAME NAME. `act --kind
# router-shift` is the LEDGER ROW KIND that authorises the launch; `shift`
# here is the SETTINGS VARIANT handed to the wrapper. Spelling either one in
# the other's slot produces a shift running under settings that are not its
# own — which is the same confusion the warning about the first token after
# `--` already names one layer down.
#
# `split` IS ITS OWN TOKEN WITH `generic`'s SETTINGS. A base run's split stage is
# dispatched with `--segment -`, and that exemption is keyed on the kind; were
# the split a `generic` stage, every other generic stage would inherit a
# segment-less dispatch. The variant below writes it exactly as it writes
# `generic`. `visual` is the fourth run-scope step and takes the same footing.
readonly STAGE_KINDS="design implement review audit reconverge generic shift split visual"

gate_settings_dir() {
  # The override exists for ONE caller: the re-derivation probe, which needs to
  # render the settings somewhere harmless to compare them against what is on
  # disk. Rendering them in place to find out whether they changed would move
  # the very surface it is asking about.
  printf '%s' "${CC_GATE_SETTINGS_OVERRIDE:-$RUN_DIR/settings}"
}

gate_settings_file() {
  # gate_settings_file <stage-kind>
  local k="$1"
  case " $STAGE_KINDS " in
    *" $k "*) : ;;
    *) k="generic" ;;
  esac
  printf '%s/%s.json' "$(gate_settings_dir)" "$k"
}

# --- compaction window: what the stage will run under, and where it came from
#
# The CLI compacts a session's context when it nears a window, and that window
# can be set in four places that the supervisor does not otherwise look at. A
# stage-result row that says only "rc=0" cannot tell a reader whether the
# stage ran under the lane's window, the run settings' window, or a flag the
# gate itself passed — so the effective value AND its source are recorded on
# the row, in one closed grammar:
#
#   `-`                        no layer sets a window
#   `(꺼짐)`                   the highest layer that says anything about
#                              `autoCompactEnabled` says false
#   `(미상)`                   a layer's file exists but could not be read
#   `<정수>(argv|런설정|프로젝트|레인)`  the window and the layer that won
#
# The layers, highest priority first: the argv the gate injects, the run's
# per-kind settings file, the stage cwd's project settings
# (`.claude/settings.local.json`, then `.claude/settings.json`), the lane's
# `<config home>/settings.json`. The two keys are resolved per key across the
# layers, the way the CLI merges settings, not per layer. THIS ORDER IS THE
# CLI'S DOCUMENTED ORDER AND NOT YET A MEASURED ONE — which is why argv
# injection is switched on for one stage kind only and carries a kill switch.

gate_autocompact_argv_value() {
  # gate_autocompact_argv_value <stage-kind> — the window the gate injects on
  # the wrapper's argv for this kind, or nothing. `CC_ORCH_STAGE_AUTOCOMPACT=off`
  # injects nothing for any kind; it does not touch the settings layers.
  local kind="$1"
  [ "${CC_ORCH_STAGE_AUTOCOMPACT:-}" = "off" ] && return 0
  case "$kind" in
    review) printf '300000' ;;
    *) : ;;
  esac
}

gate_lane_label() {
  # The lane this process resolves now, in tilde form. Resolved by the driver's
  # `resolve_account` and labelled by its `lane_label_of`, both sourced with
  # `run.sh`, so the gate and the driver name one lane by one resolver. The
  # gate used to keep its own copy of the resolver, and the copy drifted: it
  # lacked the operator's setting-file tier and printed a recorded lane that is
  # not a directory where the driver refuses it. A refusal here falls to the
  # CLI's default directory, as the driver's `stage_lane_of` does, because a
  # label must not stop a row or a launch record from being written.
  #
  # ONLY A LAUNCH RESOLVES. A row written after the stage has gone reads the
  # lane its launch recorded (`gate_lane_sidecar_read`); resolving again there
  # names the recording process's lane, not the stage's.
  local cfg
  cfg=$(resolve_account 2>/dev/null || true)
  lane_label_of "${cfg:-${HOME:-}/.claude}"
}

gate_autocompact_layer() {
  # gate_autocompact_layer <settings-file> — one layer's reading, as
  # `<enabled>\t<window>`: each side is the key's value or empty when absent.
  # Prints nothing for a missing file; returns 1 when the file exists and
  # cannot be read (jq missing or the JSON refuses to parse), which the caller
  # turns into `(미상)` rather than into "no value here".
  local f="$1" out
  [ -f "$f" ] || return 0
  command -v jq >/dev/null 2>&1 || return 1
  # `has(…)` and not `//`: a `false` on the right of `//` reads as absent, and
  # an explicit "disabled" is the one value this layer must not lose.
  out=$(jq -r '[(if has("autoCompactEnabled") then .autoCompactEnabled | tostring else "" end), (if has("autoCompactWindow") then .autoCompactWindow | tostring else "" end)] | join("\t")' "$f" 2>/dev/null) || return 1
  printf '%s\n' "$out"
}

gate_autocompact_effective() {
  # gate_autocompact_effective <argv-value> <settings-file> <project-dir> [<lane-dir>]
  # The effective window in the grammar above. THE TWO KEYS ARE MERGED PER KEY,
  # NOT PER LAYER: `autoCompactEnabled` is taken from the highest layer that
  # defines it and `autoCompactWindow` from the highest layer that holds a
  # plain integer, each on its own — a layer that only disables does not hide
  # a window below it, and a layer that only sets a window does not hide a
  # disable below it. Every layer is read before anything is decided, so an
  # unreadable file anywhere is `(미상)` and the argv value never stands in
  # for a reading that failed. Then: disabled wins over everything, argv
  # included, since a flag on a disabled session is a value the CLI throws
  # away and the row must not claim it; otherwise the argv layer exists only
  # when <argv-value> is non-empty and beats the settings window; a window
  # that is not a plain integer is "this layer sets none" (a format the CLI
  # may accept is not a read failure).
  local argv_val="$1" settings="$2" proj="$3" lane_given="${4:-}"
  local f tok reading layer_enabled layer_window lane_dir
  local enabled="" window="" window_tok=""
  # The lane layer is the directory the driver's resolver names. A refusal is
  # a lane layer that cannot be read, which is `(미상)` like any other layer
  # that cannot be read — never the default directory's settings instead. A
  # routed launch passes the directory its grant named as a fourth argument,
  # because that, not the run's seat, is where the stage reads its settings.
  if [ -n "$lane_given" ]; then
    lane_dir="$lane_given"
  else
    lane_dir=$(resolve_account 2>/dev/null) || { printf '(미상)'; return 0; }
  fi
  for tok in 런설정 프로젝트로컬 프로젝트 레인; do
    case "$tok" in
      런설정) f="$settings" ;;
      프로젝트로컬) f="$proj/.claude/settings.local.json"; tok=프로젝트 ;;
      프로젝트) f="$proj/.claude/settings.json" ;;
      레인) f="${lane_dir%/}/settings.json" ;;
    esac
    [ -n "$f" ] || continue
    reading=$(gate_autocompact_layer "$f") || { printf '(미상)'; return 0; }
    [ -n "$reading" ] || continue
    layer_enabled="${reading%%	*}"
    layer_window="${reading#*	}"
    [ -n "$enabled" ] || enabled="$layer_enabled"
    if [ -z "$window_tok" ]; then
      case "$layer_window" in
        ''|*[!0-9]*) : ;;
        *) window="$layer_window"; window_tok="$tok" ;;
      esac
    fi
  done
  if [ "$enabled" = "false" ]; then
    printf '(꺼짐)'
    return 0
  fi
  if [ -n "$argv_val" ]; then
    printf '%s(argv)' "$argv_val"
    return 0
  fi
  if [ -n "$window_tok" ]; then
    printf '%s(%s)' "$window" "$window_tok"
    return 0
  fi
  printf '%s' '-'
}

gate_window_sidecar_read() {
  # gate_window_sidecar_read <segment> — line 1 of `<seg>.window`, or `(미상)`.
  # The sidecar is a record of what the launch read, never a precondition:
  # a row is written whether or not it is there.
  local f="$RUN_DIR/$1.window" v=""
  [ -f "$f" ] && v=$(sed -n '1p' "$f" 2>/dev/null || true)
  printf '%s' "${v:-(미상)}"
}

gate_lane_sidecar_read() {
  # gate_lane_sidecar_read <segment> — line 2 of `<seg>.window`, or `(미상)`.
  # The lane is what the launch recorded. The process writing the row is a
  # supervisor or a later settler with its own environment, so the lane it
  # would resolve is not evidence of where the stage ran; without the record
  # the row says it does not know.
  local f="$RUN_DIR/$1.window" v=""
  [ -f "$f" ] && v=$(sed -n '2p' "$f" 2>/dev/null || true)
  printf '%s' "${v:-(미상)}"
}

gate_settings_key() {
  # A digest of everything `gate_write_settings` renders FROM. When it has not
  # moved, that function cannot produce different bytes, so the probe render and
  # the `diff -r` that compares it against disk are pure cost — which is what
  # the caller below skips.
  #
  # THE LEDGER'S GROWTH IS NOT AN INPUT, and that is the property the whole
  # saving rests on. The ledger grows on every act, so a key that read it whole
  # would change at moments when the settings provably cannot, and the skip
  # would never fire. What IS an input is the set of worktrees the `segment`
  # rows name, because those are interpolated — and that set moves only when a
  # new value appears, which is exactly when the settings move too.
  # NO WALL CLOCK AND NO FILE CONTENT either, for the same reason — only the
  # values the renderer interpolates.
  #
  # `gate.sh` ITSELF IS AN INPUT, because the JSON template lives here: a
  # redeploy that changes what a variant contains must re-derive rather than
  # match a key written by the old template.
  #
  # AN INPUT MISSED HERE FAILS CLOSED. The settings then fail to WIDEN, so a
  # stage is refused a directory and the run stops with a refusal naming it —
  # never the other direction, where an authorization silently grows.
  local hookp plugind
  hookp="$(dirname "$GATE_DIR")/hooks/gate-pretool.sh"
  plugind=$(cd "$(dirname "$GATE_DIR")" 2>/dev/null && pwd)
  {
    printf 'stage-kinds\t%s\n' "$STAGE_KINDS"
    printf 'hook\t%s\n' "$hookp"
    printf 'hook-exists\t%s\n' "$( [ -f "$hookp" ] && printf 'yes' || printf 'no' )"
    printf 'plugin-dir\t%s\n' "$plugind"
    printf 'run-dir\t%s\n' "${RUN_DIR:-}"
    printf 'base\t%s\n' "${BASE:-}"
    printf 'manifest-dir\t%s\n' "$(dirname "${MANIFEST:-}")"
    printf 'ledger-dir\t%s\n' "$(dirname "${LEDGER:-}")"
    printf 'grant-dir\t%s\n' "$(dirname "${GRANT:-}")"
    printf 'doc\t%s\n' "${DOC:-}"
    printf 'doc-dir\t%s\n' "${DOC_DIR:-}"
    printf 'doc-base\t%s\n' "${DOC_BASE:-}"
    printf 'doc-dir-phys\t%s\n' "$( [ -n "${DOC_DIR:-}" ] && cd "$DOC_DIR" 2>/dev/null && pwd -P || true)"
    printf 'doc-base-phys\t%s\n' "$( [ -n "${DOC_BASE:-}" ] && cd "$DOC_BASE" 2>/dev/null && pwd -P || true)"
    printf 'config-dir\t%s\n' "${CLAUDE_CONFIG_DIR:-}"
    printf 'home\t%s\n' "${HOME:-}"
    # The target rows verbatim: both worktree fields of every declared target
    # are interpolated into `additionalDirectories`.
    manifest_targets | sed 's/^/target\t/'
    # The segment worktrees, sorted so row order cannot move the key.
    gate_segment_worktrees_for_settings | LC_ALL=C sort -u | sed 's/^/segment-worktree\t/'
    printf 'gate\t%s\n' "$(shasum -a 256 "$GATE_DIR/gate.sh" 2>/dev/null | cut -d' ' -f1)"
    # The `enabledPlugins` inputs: every key the render turns off or on, the
    # seed's bytes, and the file that derives them. A user key missed here
    # would leave a plugin the account enabled after the last render loaded
    # until some other input moved.
    gate_plugin_user_keys 2>/dev/null | sed 's/^/plugin-off\t/'
    gate_plugin_allow_keys | sed 's/^/plugin-allow\t/'
    printf 'plugin-seed\t%s\n' "$(pi_seed_hash "$GATE_DIR/plugin-allow.seed")"
    printf 'plugin-isolation\t%s\n' "$(shasum -a 256 "$GATE_DIR/plugin-isolation.sh" 2>/dev/null | cut -d' ' -f1)"
  } | shasum -a 256 | cut -d' ' -f1
}

gate_plugin_account_dirs() {
  # The account directories a stage of this run can be launched under, one per
  # line: the directory the run was opened from, and every `config_dir` of the
  # run's routing inventory when it holds one. The inventory is read without the
  # router's eligibility filter — a directory listed there but not lendable today
  # can become lendable during the run, and its keys cost nothing to turn off.
  {
    gate_personal_rules_seat_dir
    printf '\n'
    if [ -f "$RUN_DIR/inventory.json" ] && [ ! -L "$RUN_DIR/inventory.json" ]; then
      jq -r '.accounts[]? | .config_dir // empty' "$RUN_DIR/inventory.json" 2>/dev/null || true
    fi
  } | sed '/^$/d' | LC_ALL=C sort -u
}

gate_plugin_user_keys() {
  # The user-plugin keys every variant names: installed or enabled in any of the
  # run's account directories. A file that does not parse warns on stderr.
  local dirs
  dirs=$(gate_plugin_account_dirs)
  [ -n "$dirs" ] || return 0
  # Word splitting on newlines only: a directory name may hold a space.
  local IFS='
'
  # shellcheck disable=SC2086
  pi_user_keys $dirs
}

gate_plugin_allow_keys() {
  # The keys a stage variant turns on: the pinned copy's seed plus the
  # manifest's `플러그인 허용` rows.
  local IFS='
'
  # shellcheck disable=SC2046
  pi_allow_keys "$GATE_DIR/plugin-allow.seed" \
    $(manifest_plugin_allow_rows 2>/dev/null | sed -n 's/^- `플러그인 허용` | 플러그인=\([^ |]*\) |.*/\1/p')
}

gate_settings_key_record() {
  # Written ONLY where the render and the baseline BOTH just succeeded. A key
  # recorded on a failed path would claim settings are settled that were never
  # written, and the next call would skip the re-derivation that repairs them.
  #
  # Never under the probe override: that render goes to a temporary directory
  # and says nothing about what is on disk.
  local k keyf
  [ -n "${RUN_DIR:-}" ] || return 0
  [ -z "${CC_GATE_SETTINGS_OVERRIDE:-}" ] || return 0
  k=$(gate_settings_key)
  [ -n "$k" ] || return 0
  keyf="$RUN_DIR/settings-key"
  # Same directory, then rename: a reader never sees a half-written key, and a
  # failure to write leaves the previous state rather than a truncated one.
  printf '%s\n' "$k" > "$keyf.$$" 2>/dev/null || { rm -f "$keyf.$$"; return 0; }
  mv "$keyf.$$" "$keyf" 2>/dev/null || rm -f "$keyf.$$"
  return 0
}

gate_write_settings() {
  # Writes every variant. Called at run start and idempotent — a re-run after a
  # session cut must find the same bytes, because those bytes are in the
  # enforcement-surface digest set and a regenerated-but-different file would
  # read as tampering.
  local dir hook k f deny_extra plugin_dir extra_dirs doc_ws a wt_all d
  local kind_dirs kind_allow
  dir=$(gate_settings_dir)
  mkdir -p "$dir" || return 1
  hook="$(dirname "$GATE_DIR")/hooks/gate-pretool.sh"
  [ -f "$hook" ] || die "the gate hook script is missing: $hook"

  # THE STAGE MUST BE ABLE TO READ ITS OWN SKILL'S DOCUMENTS.
  #
  # Every skill here opens by Reading several `_common/*` files, and those live
  # in the plugin cache — outside the working directory, so outside what the
  # ambient configuration permits. Measured: a review stage ran seven turns,
  # collected five `Read` denials under the plugin directory, reported that it
  # had stopped before its first step, and exited 0 with no artifact. It
  # explicitly declined to reach the same bytes with `cat`, on the ground that
  # doing so would defeat a permission decision rather than satisfy it — which
  # is the right call and is exactly why the permission has to be granted here.
  #
  # The run's own files are listed for the same reason: the manifest, ledger and
  # grant live under the HOME worktree, so a stage acting in any other target
  # cannot reach them from its own directory.
  #
  # The DESIGN DOCUMENT's directory is listed separately from the run's base
  # because in a polyrepo workspace it is in neither — the repositories are
  # siblings under one directory and the documents describing work across them
  # belong to none of them. A stage measured against a document it cannot read
  # produces nothing and reports success.
  #
  # Read is deliberately NOT added to the hook matcher below. That matcher is
  # default-deny, so adding Read there would deny every read instead of
  # recording it; what a denied read costs is a ledger row, and the price of
  # buying that row with this hook is the whole read surface.
  #
  # Every path is derived, so the bytes stay identical across a re-run — which
  # they must, since this file is in the enforcement-surface digest set.
  #
  # A DOCUMENT THAT DEFERS TO ANOTHER DOCUMENT. Design documents routinely name
  # a second one as the source of truth for part of their content — a task
  # design and an applied design as separate files is the normal shape — and
  # that second file is a sibling or a parent, not a child. For a document
  # INSIDE a repository the grant already reaches it, because `DOC_BASE` is the
  # repository root. For one outside every repository `DOC_BASE` collapses onto
  # the document's own folder, and the grant was exactly that folder.
  #
  # So the containing WORKSPACE is granted in that case, and only that case: for
  # a document that belongs to no repository, its workspace is its parent
  # directory. This is read-only and it is the same widening the in-repo branch
  # already has. The failure it removes is the quiet one — the stage has
  # something to read, so it does not stop; it produces output measured against
  # half a specification and nothing in the artifact says which half.
  #
  # `$DOC` and not `$DOC_DIR` in the guard: a run with NO document still sets
  # `DOC_DIR` and `DOC_BASE` to the run's base, so testing their equality alone
  # would widen the grant to the base's parent on every documentless run — a
  # directory nothing in the run has any business reading.
  doc_ws=""
  if [ -n "${DOC:-}" ] && [ "${DOC_BASE:-}" = "${DOC_DIR:-}" ]; then
    doc_ws=$(dirname "$DOC_DIR")
  fi
  plugin_dir=$(cd "$(dirname "$GATE_DIR")" && pwd)
  # EVERY TARGET'S WORKTREES, both of them, for every declared target.
  #
  # The list used to carry only the run's own base — the HOME worktree — so a
  # stage acting in any other target could not read that target at all, and a
  # stage woken in an EXECUTION worktree could not read the tree it was standing
  # in. That second one is not an edge case: `실행 워크트리` exists for `pr` and
  # `branch` anchors, and for those the landing surface is always outside the
  # main worktree because git refuses to check one branch out twice. Measured: a
  # stage passed every earlier step and then halted before its first write with
  # "Claude requested permissions to read from <execution worktree>/… but you
  # haven't granted it yet".
  #
  # Physical paths go in beside the spelled ones. `DOC_DIR` and `DOC_BASE` are
  # derived from how the path was WRITTEN, so a design document reached through
  # a symlink grants the link's directory and not the file's real one — and the
  # out-of-repo widening does not fire either, because by spelling the link sits
  # inside the repository. `pwd -P` resolves it; adding both costs one line and
  # covers either spelling.
  wt_all=""
  for a in $(target_aliases); do
    wt_all="$wt_all
$(target_field "$a" '메인 워크트리')
$(target_field "$a" '실행 워크트리')"
  done
  # EVERY SEGMENT'S OWN WORKTREE, from the ledger. The router creates one per
  # segment after kickoff and records it on the `segment` row; without this the
  # only tree a stage could write was the shared main worktree, so segment
  # isolation existed on the row and nowhere else.
  wt_all="$wt_all
$(gate_segment_worktrees_for_settings)"
  # EVERY ENTRY GOES THROUGH `gate_json_escape`, the same escaper every other
  # JSON string this file emits goes through. The list is interpolated into
  # the settings file as JSON source, so a `"` or a `\` in a directory name
  # would otherwise close the string early and let the rest of the name stand
  # as syntax — one more entry, or a file the harness cannot parse. The
  # `segment` arm refuses those bytes before a worktree reaches the ledger,
  # but this renderer also reads the manifest and the document paths, and a
  # renderer that is safe only because every caller was checked first is not
  # safe; each half holds on its own. Newlines are the one byte escaping
  # cannot mend here, because the list is line-delimited by the time it is
  # read — that is the arm's refusal, not this line's.
  extra_dirs=$(printf '%s\n%s\n%s\n%s\n%s\n%s\n%s\n%s\n%s\n%s\n%s\n%s\n' \
      "$plugin_dir" "$RUN_DIR" "$BASE" \
      "$(dirname "$MANIFEST")" "$(dirname "$LEDGER")" "$(dirname "$GRANT")" \
      "${DOC_DIR:-}" "${DOC_BASE:-}" "$doc_ws" \
      "$( [ -n "${DOC_DIR:-}" ] && cd "$DOC_DIR" 2>/dev/null && pwd -P || true)" \
      "$( [ -n "${DOC_BASE:-}" ] && cd "$DOC_BASE" 2>/dev/null && pwd -P || true)" \
      "$wt_all" \
    | sed '/^$/d' | sed 's/^(없음)$//' | sed '/^$/d' \
    | LC_ALL=C sort -u \
    | while IFS= read -r d; do printf '"%s"\n' "$(gate_json_escape "$d")"; done \
    | tr '\n' ',' | sed 's/,$//')

  # THE READ ALLOW-LIST, AND WHY IT IS NOT A DIRECTORY WIDENING. A stage that
  # builds a CLAUDE.md proposal has to read the live file, and the live slots sit
  # outside every directory above. `additionalDirectories` would reach them, but
  # it opens whole trees — the user config directory holds credentials-adjacent
  # state and a skill that handles external logins, and the workspace root holds
  # every sibling repository. Measured: a `permissions.allow` entry naming ONE
  # FILE grants that read and nothing else, and the same read without the entry
  # is refused outright ("Claude requested permissions to read from … but you
  # haven't granted it yet"). So the narrow form is not merely preferable, it is
  # sufficient, and the wide one buys nothing this needs.
  #
  # DERIVED, NEVER ENUMERATED. The slots are absolute paths outside the
  # repository and differ per machine; a literal list would be correct on the
  # author's box and silently empty everywhere else. The set built here is
  # exactly the chain the harness itself loads into every session's prefix — the
  # user-scope file plus a `CLAUDE.md` in each ancestor of the base worktree — so
  # granting a read of it grants nothing the stage's own prompt did not already
  # contain.
  local cfgdir adir aprev allow_extra=""
  cfgdir="${CLAUDE_CONFIG_DIR:-}"
  [ -n "$cfgdir" ] || cfgdir="${HOME:-}${HOME:+/.claude}"
  cfgdir="${cfgdir%/}"
  # `Read(` takes the path with ONE extra leading slash — the repo's own
  # `.claude/settings.local.json` spells `/tmp` as `Read(//tmp/**)`. These values
  # are already absolute, so the literal here is a single slash and the path
  # supplies the second. A third slash was measured and it also resolves, so this
  # is a convention rather than a correctness constraint; it is written the one
  # way the tree already spells it so a reader comparing the two files does not
  # have to wonder which spelling is the working one.
  [ -n "$cfgdir" ] && allow_extra="\"Read(/$cfgdir/CLAUDE.md)\""
  # TERMINATION IS ON `dirname` SHRINKING, not on reaching `/`. `dirname .` is
  # `.` and `dirname x` is `.` as well, so a relative or empty `BASE` walks this
  # loop forever — and it runs at run open, before anything has been recorded, so
  # the run would hang with no row saying why. The `/` test alone never fires on
  # those inputs. Bounded twice: the value has to keep changing, and it has to be
  # absolute to contribute a rule at all.
  adir="$BASE"
  while [ -n "$adir" ] && [ "$adir" != "/" ]; do
    case "$adir" in
      /*) if [ -n "$allow_extra" ]; then allow_extra="$allow_extra, "; fi
          allow_extra="$allow_extra\"Read(/$adir/CLAUDE.md)\"" ;;
      *)  break ;;
    esac
    aprev="$adir"
    adir=$(dirname "$adir")
    [ "$adir" != "$aprev" ] || break
  done

  # THE USER'S PLUGINS ARE NAMED IN EVERY VARIANT. A session launched with
  # `--settings` still loads whatever the account's own settings enable, so a
  # variant that leaves `enabledPlugins` out hands every stage the skill and
  # command lists of plugins the pipeline never calls. Each user key is written
  # `false` and each allow key `true` — `true` turns on a plugin the account has
  # switched off, and on an account where it is not installed it does nothing.
  # The keys are derived once here and only the shift branch below differs: the
  # router's shift turns every one of them off, allow keys included.
  local pl_user pl_allow pl_obj pl_shift
  pl_user=$(gate_plugin_user_keys)
  pl_allow=$(gate_plugin_allow_keys)

  for k in $STAGE_KINDS; do
    f=$(gate_settings_file "$k")
    # Every stage variant ALLOWS `WebFetch` / `WebSearch` explicitly (the else
    # branch below). Removing a deny is not enough: a headless stage whose
    # variant named neither tool has had those calls denied, so opening them
    # means writing the allow. This does not claim a variant without the allow
    # entry is always denied. No spend cap dedicated to web research is kept —
    # that was a person's decision — and a `curl` GET through the gate has
    # always passed as a read with no cap either. The settings file is not the
    # only enforcement point for these tools: a PreToolUse hook matcher can see
    # them too, so a later cap or check has a place to go.
    #
    # THE CLAUDE DESIGN TOOLS ARE REFUSED TO EVERY VARIANT, THE SHIFT INCLUDED,
    # so they sit in the initial value and not in either branch below. A stage
    # never publishes to or reads from the Design canvas; that belongs to the
    # seat. Under `CLAUDE_CODE_ARTIFACT=1` the headless tool list carries exactly
    # `Artifact`, `ArtifactComments` and `ArtifactData` besides `DesignSync`, and
    # the set matches `CLAUDE_DESIGN_TOOLS` in run.sh, which refuses the same
    # names on every judgment call's own command line.
    deny_extra="\"DesignSync\", \"Artifact\", \"ArtifactComments\", \"ArtifactData\", "

    # THE SHIFT VARIANT IS NARROWER THAN EVERY STAGE, AND THE NARROWING HAS TO
    # HAPPEN INSIDE THIS LOOP. `extra_dirs` and the read allow-list are computed
    # ONCE above and interpolated identically into every variant; before this
    # branch the only thing that branched per kind was `deny_extra`. So adding
    # the token to `STAGE_KINDS` without this branch writes the file and leaves
    # the permissions wide — the file exists, the launch succeeds, and nothing says
    # the narrowing did not happen.
    #
    # A shift writes no files. Its loop is snapshot → decide → gate, and
    # everything it changes goes through the gate's own bash path, so a Write
    # that leaked would land somewhere git has no history to undo it.
    # `additionalDirectories` is READ authorisation as well, so the stage list
    # would also let the routing seat read files routing has no use for — and
    # every directory in that list is an element of the enforcement-surface
    # digest, so an unnecessary one widens the surface an `exit 7` is measured
    # against.
    #
    # BOTH HALVES COME OUT, and dropping only one is the trap. The directories
    # go out through `additionalDirectories` and the individual CLAUDE.md reads
    # through `permissions.allow`; leaving the allow-list in place re-opens
    # exactly as much as narrowing the directory list just closed.
    #
    # THE HOOK'S CLAUDE.md REFUSAL ARM STAYS IN EVERY VARIANT, THIS ONE
    # INCLUDED. It never fires here, because the path is unreachable to begin
    # with. But where a run reaches those files through the read allow-list
    # instead of through a directory grant, that arm is the only defence left,
    # so it is not this branch's to remove.
    kind_dirs="$extra_dirs"
    kind_allow="$allow_extra"
    if [ "$k" = "shift" ]; then
      kind_dirs=""
      kind_allow=""
      deny_extra="${deny_extra}\"WebFetch\", \"WebSearch\", \"Write\", \"Edit\", \"MultiEdit\", \"NotebookEdit\", "
    else
      kind_allow="\"WebFetch\", \"WebSearch\"${kind_allow:+, $kind_allow}"
    fi
    pl_shift=0
    [ "$k" != "shift" ] || pl_shift=1
    pl_obj=$(pi_render_enabled "$pl_shift" "$pl_user" "$pl_allow")
    # A VARIANT THAT FAILS TO WRITE FAILS THE FUNCTION. The loop used to swallow
    # the status, so a caller re-baselined and recorded a settled key over files
    # that were never rewritten. Returning here is what makes "both the rewrite
    # and the baseline succeeded" a condition rather than a hope.
    cat > "$f" <<JSON || return 1
{
  "permissions": {
    "deny": [ ${deny_extra}"Bash(sudo:*)" ],
    "allow": [ ${kind_allow} ],
    "additionalDirectories": [ ${kind_dirs} ]
  },
  "hooks": {
    "PreToolUse": [
      {
        "matcher": "Bash|Write|Edit|MultiEdit|NotebookEdit",
        "hooks": [
          {
            "type": "command",
            "command": "bash '$hook' --run-dir '$RUN_DIR' --gate '$GATE_DIR/gate.sh' --ledger '$LEDGER' --grant '$GRANT' --manifest '$MANIFEST'"
          }
        ]
      }
    ]
  },
  "enabledPlugins": ${pl_obj}
}
JSON
  done
  # NOT under the probe. The probe renders these files somewhere harmless to
  # find out whether they changed, and its digest is taken over that other
  # directory — writing it here would replace the real baseline with a value
  # that describes a temporary path, and every act afterwards would read as a
  # moved surface.
  if [ -z "${CC_GATE_SETTINGS_OVERRIDE:-}" ]; then
    local _lines
    _lines=$(gate_surface_lines_capture)
    printf '%s\n' "$(shasum -a 256 < "$_lines" | cut -d' ' -f1)" > "$RUN_DIR/surface-digest"
    gate_surface_files_from "$_lines"
    log "런 설정 생성: $dir (강제 표면 기준선 기록)"
  fi
}

gate_resettle_settings_for_segment() {
  # gate_resettle_settings_for_segment <세그먼트> <워크트리> — re-derive the
  # stage settings as they will stand once the non-terminal `segment` row
  # naming <워크트리> is on the ledger, and when they differ from disk rewrite +
  # re-baseline. Prints the field the caller puts on that row, and the print
  # says which of THREE things happened:
  #
  #   (nothing)                the settings did not move — the derivation's
  #                            inputs are the ones already settled, or the
  #                            render matched disk byte for byte
  #   인가면=<before>→<after>  rewritten and re-baselined
  #   인가면=실패(<사유>)      the re-derivation did not land: `기준선 불일치`,
  #                            `프로브 렌더` or `렌더` (the caller adds `락 대기
  #                            초과` and `런 디렉터리 없음` for the two arms it
  #                            decides before calling here)
  #
  # A FAILURE ARM IS NEVER SILENT. Every one of them used to print nothing and
  # return 0, which the caller then wrote as a row WITHOUT the field — and the
  # field's contract reads absence as "this row widened nothing". So a lock
  # that timed out, a render that failed and a row that genuinely had nothing
  # to widen were one and the same on the ledger, and since the row itself is
  # the only trigger there is (the prelude re-derivation is gone), a widening
  # missed here stayed missed for the stage's whole life with nothing saying
  # so. Now each arm prints a marker naming itself and `warn`s, and the caller
  # keeps the row: a refused row would lose the state transition the router
  # was recording, which costs more than the widening. What the marker buys is
  # the repair path — THE KEY IS NOT RECORDED ON ANY FAILURE ARM, so the next
  # non-terminal `segment` row from ANY segment misses the settled-key return
  # below, takes the full path, and renders this worktree from the ledger row
  # that carries the marker.
  #
  # `settings.lock` IS HELD BY THE CALLER, from before this call until after
  # the row is appended, and this function never takes or drops it. The lock
  # used to be taken and released in here, which put the row's append OUTSIDE
  # it: a sibling segment writing its own row could take the lock between this
  # function's return and the caller's append, and its render read the ledger
  # without this row and `GATE_SEGMENT_WT_PENDING` without this pair — so it
  # wrote a list that lacked the worktree this row had just admitted, and the
  # earlier writer's stage ran unadmitted until the next non-terminal row from
  # anyone. Parallel dispatch is the ordinary case for this pipeline, so that
  # interleaving is not a corner. Holding the lock across the append is what
  # makes "the pending pair and the row" one atomic step to every other
  # writer, and the settled-key read moved inside the lock with it, so the key
  # it compares is the one the last writer recorded and not a value another
  # writer is about to replace.
  #
  # THIS RUNS AT ROW-WRITE TIME, FROM THE ROW ITSELF. The set it derives from
  # is the manifest's target rows (each target's main and execution worktree),
  # the worktrees the ledger's non-terminal `segment` rows name (last row per
  # segment id, only those sharing a declared target's common git directory),
  # PLUS THE ROW ABOUT TO BE WRITTEN — carried in through
  # `GATE_SEGMENT_WT_PENDING`, because the row is not on the ledger yet and the
  # render has to see the worktree it is authorizing before the row that names
  # it exists. Deriving before the append is what closes the window the old
  # prelude-time re-derivation left open: the first act from a new worktree
  # used to be the one that re-rendered, so the row that named the worktree
  # landed before the settings that admit it, and a stale `settings-key` from a
  # sibling could leave them unadmitted for the whole stage.
  #
  # THE `대상 추가` ROW THE OLD FORM APPENDED IS GONE, for two reasons that can
  # each be checked in this file. The prelude re-derivation ran AFTER the
  # caller's snapshot digest had been taken and BEFORE the staleness check in
  # `gate_verb_act` read it, so on the call that widened, the gate invalidated
  # its own caller's digest — the same ordering hazard that check's own comment
  # records for target registration. And the row landed under a series whose
  # meaning is "a repository joined the run" (`gate_undeclared_target` writes
  # it with an actual alias and remote): the re-derivation's rows carried
  # `별칭=-` and every target field as `-`, which no reader of the series — the
  # dedup guard in `gate_undeclared_target`, the renderer in `feed.sh` —
  # refuses, but which put a non-target on the target-shaped series. The
  # manifest census (`manifest_targets` in `run.sh`) reads the manifest alone
  # and never saw those rows. Recording the widening on the segment row that
  # caused it is what that row was for and keeps the series to actual targets.
  #
  # An edit by anything that is not this function still lands as exit 7, which
  # is the property the digest exists for.
  local seg="$1" wt="$2"
  local before after tmpdir base
  local key keyf
  GATE_SEGMENT_WT_PENDING="$(printf '%s\t%s' "$seg" "$wt")"
  # THE INPUTS HAVE NOT MOVED, SO NEITHER CAN THE OUTPUT. Everything below —
  # two surface digests, a whole second render of the settings tree and a
  # recursive `diff` — exists to answer "did the derivation change?", and this
  # answers it from the derivation's own inputs instead. The key includes the
  # pending pair, so a row that re-names a worktree already admitted is settled
  # here without a render.
  #
  # IT SKIPS NO DETECTION. Finding a difference here never refuses anything;
  # `gate_surface_check` owns that verdict and runs independently on every act.
  # A tampered settings file is still exit 7 whether or not this returned early,
  # and the branch below would not have repaired it either — it returns
  # untouched when the baseline has already moved.
  #
  # The key is recorded only after a successful render, so an absent key file —
  # a run that started before this existed, or one whose last write failed —
  # takes the full path.
  keyf="$RUN_DIR/settings-key"
  key=$(gate_settings_key)
  if [ -n "$key" ] && [ -f "$keyf" ] && [ "$key" = "$(cat "$keyf" 2>/dev/null)" ]; then
    GATE_SEGMENT_WT_PENDING=""; return 0
  fi
  before=$(gate_surface_digest_raw)

  # ONLY FROM A KNOWN-GOOD BASELINE. If the surface has already moved, this is
  # not the place to decide about it — `gate_surface_check` owns that verdict,
  # and rewriting here would erase the very evidence it reads. Without this
  # guard the re-derivation silently repairs and re-baselines an edit made by
  # anything at all, which is exactly the detection the digest exists for.
  base=$(cat "$RUN_DIR/surface-digest" 2>/dev/null || true)
  if [ -z "$base" ] || [ "$before" != "$base" ]; then
    GATE_SEGMENT_WT_PENDING=""
    warn "인가 디렉터리를 재유도하지 못했습니다 — 강제 표면 기준선이 이미 옮겨져 있어 손대지 않습니다 (기준선 ${base:0:12}… · 관측 ${before:0:12}…); 세그먼트 $seg 의 행은 인가면=실패(기준선 불일치) 로 남기고, 다음 비종단 segment 행이 다시 유도합니다"
    printf '인가면=실패(기준선 불일치)'
    return 0
  fi

  tmpdir="$(gate_settings_dir).probe.$$"
  rm -rf "$tmpdir"
  if ! ( CC_GATE_SETTINGS_OVERRIDE="$tmpdir"; export CC_GATE_SETTINGS_OVERRIDE
         gate_write_settings >/dev/null 2>&1 ); then
    rm -rf "$tmpdir"; GATE_SEGMENT_WT_PENDING=""
    warn "인가 디렉터리를 재유도하지 못했습니다 — 프로브 렌더가 실패해 디스크와 비교할 수 없습니다; 세그먼트 $seg 의 행은 인가면=실패(프로브 렌더) 로 남기고, 다음 비종단 segment 행이 다시 유도합니다"
    printf '인가면=실패(프로브 렌더)'
    return 0
  fi
  if diff -r -q "$tmpdir" "$(gate_settings_dir)" >/dev/null 2>&1; then
    # The render matches disk and the baseline matched above, so the settings
    # are settled for these inputs: record the key so the next call can say so
    # without rendering again. This is the arm that adopts a run which started
    # before the key existed.
    rm -rf "$tmpdir"; gate_settings_key_record
    GATE_SEGMENT_WT_PENDING=""; return 0
  fi
  rm -rf "$tmpdir"

  if ! gate_write_settings >/dev/null 2>&1; then
    GATE_SEGMENT_WT_PENDING=""
    warn "인가 디렉터리를 재유도하지 못했습니다 — 실제 렌더가 실패했습니다 ($(gate_settings_dir)); 세그먼트 $seg 의 행은 인가면=실패(렌더) 로 남기고, 다음 비종단 segment 행이 다시 유도합니다. 표면 검사가 exit 7 을 내면 반쯤 쓰인 설정 파일이 남은 것입니다"
    printf '인가면=실패(렌더)'
    return 0
  fi
  # The baseline and its per-file list come from one read of the surface; see
  # `gate_surface_lines_capture`. The lock is ours already, so that read is raw.
  local _lines
  _lines=$(gate_surface_lines_capture)
  after=$(shasum -a 256 < "$_lines" | cut -d' ' -f1)
  printf '%s\n' "$after" > "$RUN_DIR/surface-digest"
  gate_surface_files_from "$_lines"
  # After BOTH the rewrite and the re-baseline, never between them.
  gate_settings_key_record
  GATE_SEGMENT_WT_PENDING=""
  log "인가 디렉터리를 다시 유도했습니다 — 강제 표면 기준선을 갱신하고 세그먼트 행에 남깁니다"
  printf '인가면=%s→%s' "$before" "$after"
}

gate_settings_lock_release() {
  # Drops the settings lock the `segment` arm holds across its re-derivation
  # and append, if it still holds one. Called by the arm after its append and
  # by `gate_on_exit` — the one EXIT trap `act`/`exec` install — because
  # `gate_append` ends the process on a failed write (`die`) and a lock
  # directory left behind by a dead holder would make every later
  # re-derivation wait out the timeout and land as `인가면=실패(락 대기 초과)`
  # for the rest of the run. `mkdir`-based, so releasing is `rmdir`, and a lock
  # this process does not hold is never touched.
  if [ -n "${GATE_SETTINGS_LOCK_HELD:-}" ]; then
    gate_settings_unlock "$GATE_SETTINGS_LOCK_HELD"
    GATE_SETTINGS_LOCK_HELD=""
  fi
  return 0
}

gate_chain_verify() {
  # Re-walks the chain: each row's `prev=` must equal the digest of the row
  # before it. This is what covers the ledger, since the whole-file digest
  # cannot (see above). A break is reported with the row number so the morning
  # reader has somewhere to look.
  #
  # ONE PROCESS FOR THE WHOLE LEDGER, NOT THREE PER ROW. This walk used to spawn
  # `sed`, `shasum` and `cut` once per row — exactly 3n+2 processes for n rows —
  # and on this platform `shasum` is itself a Perl program wrapping
  # `Digest::SHA`. Calling that module directly is therefore not a different hash
  # implementation but the SAME ENGINE with n-1 interpreter startups removed,
  # which is the strongest equivalence argument available for rewriting a path
  # that issues verdicts.
  #
  # THE CHARACTER-TYPE PIN IS GONE FROM THIS FUNCTION, and its absence is not a
  # relaxation. The pin was here because `sed` extracted `prev=`, and under a
  # UTF-8 `LC_CTYPE` that extractor stopped being a function of the row's
  # content — BSD `sed` aborted on an invalid byte and printed nothing, GNU `sed`
  # returned output with the unsubstituted prefix still attached, and neither was
  # the hex the row carried. There is no `sed` here now: the file is opened raw
  # and matched as bytes unconditionally, which is what the pin was buying. The
  # other three ledger readers still pin, because they still shell out.
  #
  # ANOTHER RUN'S LEDGER IS NAMED BY ARGUMENT, both halves or neither:
  # `gate_chain_verify [<ledger> <run-id>]`. The chain's seed is that run's
  # heading, so a ledger path without its own run id would be walked from this
  # run's seed and reported broken at row one. The walk only reads, so naming a
  # predecessor's ledger here writes nothing to it.
  if [ "$#" -ne 0 ] && [ "$#" -ne 2 ]; then
    warn "gate_chain_verify 는 인자를 받지 않거나 <원장> <런 id> 둘을 받습니다 — 미검증"
    return 1
  fi
  local LEDGER="${1:-$LEDGER}" RUN_ID="${2:-$RUN_ID}"
  local walk rc broke cause
  # AN ABSENT LEDGER USED TO VERIFY. The redirection below fails, the loop body
  # never runs, `broke` stays 0, and the function returns "intact" for a file it
  # never opened — so deleting the ledger outright was quieter than editing one
  # row of it. Nothing can be said about a chain that was not read, and this is
  # the difference between "verified intact" and "not verified".
  #
  # This sentence is not translated: scripts/test-gate-chain-equiv.sh compares
  # the verifier's stderr with the digest-pinned Korean reference sentence for
  # sentence after normalization (`normalize_err` drops the timestamp prefix and
  # rewrites paths), so rewording it reads as a divergence in the verifier itself.
  if [ ! -f "$LEDGER" ]; then
    warn "원장 파일이 없어 해시 체인을 검증하지 못했습니다 — 무결이 아니라 미검증입니다: $LEDGER"
    return 1
  fi
  # The whole walk, in one pass. Four behaviours are decided deliberately here
  # and none of them is incidental:
  #
  #   * ROW SELECTION and ROW NUMBERING are unchanged — a line is a row when it
  #     starts with "- `", and an unreadable row still consumes its number, so
  #     every committed fixture keeps the `broke` value it pins.
  #   * THE EXTRACTOR keeps its greedy match, so it takes the LAST `| prev=` on
  #     the row and yields nothing unless what follows is hex all the way to the
  #     end of the line.
  #   * A ROW WHOSE `prev=` CANNOT BE READ IS A BREAK, not a row to step over.
  #     Stepping over it left `prev` un-advanced, so the chain re-joined across
  #     the row as though it had never been there and a forged approval spliced
  #     in with no `prev=` — or with one made unreadable by a single invalid
  #     byte — was reported as intact. That is a fixed defect; reproducing it
  #     here for the sake of "same verdict as before" would be an instruction to
  #     regress.
  #   * `read`'s EOF SEMANTICS ARE NOT REPRODUCED, and dropping them tightens
  #     detection rather than relaxing it. A final chunk with no terminating
  #     newline used to end the walk before it was counted, so a forged approval
  #     row appended with the newline left off was never visited at all — while
  #     every other consumer read it as a valid row and the authorization took
  #     effect. It is cheaper to produce than any of the three shapes above:
  #     not printing one byte is the whole attack.
  #
  #     A FALSE POSITIVE IS NOT POSSIBLE HERE, and the reason is in `gate_append`
  #     rather than in this function. That is the ledger's only writer, and both
  #     of its branches — the locked `/bin/sh -c` and the no-lock fallback — write
  #     through a `printf` whose format ends in `\n`. A ledger the gate wrote
  #     therefore always ends with a newline, so a final row that does not is by
  #     itself evidence of a write that did not come through the gate.
  #
  #     Only a ROW-SHAPED chunk is judged. A partial write that is not row-shaped
  #     — a truncated heading, half a prose line — still ends the walk silently,
  #     because counting a non-row as a row would move the `broke` value every
  #     committed fixture pins.
  #
  #     The other thing NOT reproduced is what `read` does to a NUL byte — it
  #     drops or truncates there depending on the interpreter, and hashing the
  #     row's true bytes instead is a gain in detection, listed as such rather
  #     than hidden.
  walk=$(perl -MDigest::SHA=sha256_hex -e '
    my ($ledger, $seed) = @ARGV;
    open(my $fh, "<", $ledger) or exit 3;
    binmode($fh);
    my $prev = sha256_hex($seed);
    my ($n, $broke, $cause) = (0, 0, 0);
    while (defined(my $line = <$fh>)) {
      unless ($line =~ s/\n\z//) {
        last unless substr($line, 0, 3) eq "- `";
        $n++; $broke = $n; $cause = 2; last;
      }
      next unless substr($line, 0, 3) eq "- `";
      $n++;
      my $want = $line =~ /^.*\| prev=([0-9a-f]*)\z/ ? $1 : "";
      if ($want eq "") { $broke = $n; $cause = 1; last }
      if ($want ne $prev) { $broke = $n; last }
      $prev = sha256_hex($line);
    }
    print "$broke $cause\n";
    exit 0;
  ' -- "$LEDGER" "## 실행 $RUN_ID" 2>&1)
  rc=$?
  # A FAILING TOOL AND A BROKEN CHAIN ARE NOT THE SAME FINDING. If `perl` or the
  # module is missing, or the process dies, then no verdict was reached at all —
  # and answering "splice, delete or reorder" there sends the morning reader
  # looking for something that did not happen. Every morning report would say the
  # chain broke, and a reader who sees that daily learns to skip the one field
  # that would have told them. The 0/1 return contract is NOT widened: two
  # consumers read it as a boolean, and what separates the two cases is the
  # sentence. stderr is folded into the captured output so a diagnostic cannot
  # reach the render path, which reads any stderr as a break.
  case "$walk" in
    [0-9]*" "[012]) ;;
    *) rc=1 ;;
  esac
  if [ "$rc" != 0 ]; then
    warn "could not verify the ledger hash chain — the single-pass verifier produced no verdict (perl or Digest::SHA): ${walk}"
    return 1
  fi
  broke=${walk%% *}
  cause=${walk##* }
  [ "$broke" = "0" ] && return 0
  # Three causes, three sentences. They are NOT the same finding: a mismatch
  # means some row moved, an unreadable `prev=` means THIS row cannot be placed
  # in the chain at all, and a row that does not end with a newline means the row
  # was appended by something other than the gate. Pointing a reader at
  # splice/delete/reorder for either of the last two sends them to look for
  # something that did not happen. `cause` is an encoding internal to this
  # function — the 0/1 return contract and the boolean `chain_intact` field both
  # stay exactly as they were, and the two consumers go on reading non-zero as a
  # break. What the number selects is the sentence.
  #
  # These three sentences are not translated, and what holds them is the
  # reference, not the suite's regex. tests/fixtures/gate-chain-equiv/reference-v1.sh
  # is pinned by digest and cannot be updated, and whenever its verdict tuple
  # agrees with this verifier's, `compare_impl` in
  # scripts/test-gate-chain-equiv.sh compares the two stderr sentences whole
  # (after normalization) — so translating even the tail of the unreadable
  # `prev=` sentence or the splice sentence fails that suite. The row number the
  # suite reads out of the head (`체인이 N번째 행에서`) is a second reader, but a
  # test regex can change with the sentence; the pinned reference cannot. The
  # no-newline sentence has no counterpart in the reference, which predates that
  # cause, so only its head is pinned, by that row-number extraction.
  if [ "$cause" = "2" ]; then
    warn "원장 해시 체인이 ${broke}번째 행에서 끊겼습니다 — 그 행이 개행으로 끝나지 않습니다 (게이트가 쓴 원장은 언제나 개행으로 끝나므로 게이트 밖에서 덧붙여진 행입니다)"
  elif [ "$cause" = "1" ]; then
    warn "원장 해시 체인이 ${broke}번째 행에서 끊겼습니다 — 그 행의 prev= 를 읽을 수 없습니다 (필드가 없거나 hex 가 아니거나 무효 바이트가 섞였습니다)"
  else
    warn "원장 해시 체인이 ${broke}번째 행에서 끊겼습니다 — 스플라이스·삭제·재배열 중 하나입니다"
  fi
  return 1
}

# This run's grant block, read ONCE per gate call. `gate_check_grant` asks for
# ten fields and each ask was four processes over the whole file; the block is
# cut out once below and every ask answers from it with shell expansions. Keyed
# to both the path and the run id so a memo can never answer for another
# grant or another run — a mismatch falls back to the file.
GATE_GRANT_MEMO_PATH=""; GATE_GRANT_MEMO_RUN=""; GATE_GRANT_MEMO_BLOCK=""

gate_grant_block_take() {
  GATE_GRANT_MEMO_PATH=""; GATE_GRANT_MEMO_RUN=""; GATE_GRANT_MEMO_BLOCK=""
  [ -f "$GRANT" ] || return 0
  # The same range the file-reading form cuts: from the line equal to this
  # run's heading through the next `## ` line. A leading newline makes the
  # first line addressable by the same `<newline>**key**: ` prefix as the rest.
  GATE_GRANT_MEMO_BLOCK="
$(sed -n "/^## 인가 ${RUN_ID}\$/,/^## /p" "$GRANT" 2>/dev/null)"
  GATE_GRANT_MEMO_PATH="$GRANT"; GATE_GRANT_MEMO_RUN="$RUN_ID"
}

gate_grant_field() {
  # gate_grant_field <필드명> — the CANON rendering inside this run's block.
  #
  # sed and shell string equality, not awk. A Korean key fed to `awk`'s regex
  # engine is the exact construction this repository already had to rewrite once
  # after it failed on the macOS leg of CI and nowhere else.
  #
  # From the memo when one was taken for this grant and run: the first line of
  # the block starting with `**<field>**: `, trailing whitespace stripped —
  # the same bytes the four-process form below produces.
  local v pre="
**$1**: "
  if [ -n "$GATE_GRANT_MEMO_PATH" ] && [ "$GATE_GRANT_MEMO_PATH" = "$GRANT" ] \
     && [ "$GATE_GRANT_MEMO_RUN" = "$RUN_ID" ]; then
    case "$GATE_GRANT_MEMO_BLOCK" in
      *"$pre"*)
        v="${GATE_GRANT_MEMO_BLOCK#*"$pre"}"; v="${v%%
*}"; v="${v%"${v##*[![:space:]]}"}"
        printf '%s\n' "$v" ;;
    esac
    return 0
  fi
  sed -n "/^## 인가 ${RUN_ID}\$/,/^## /p" "$GRANT" 2>/dev/null \
    | sed -n "s/^\\*\\*${1}\\*\\*: //p" | sed 's/[[:space:]]*$//' | sed -n '1p'
}

gate_check_grant() {
  # THE ROUTER PATH READ THE AUTHORIZATION RECORD NOWHERE, and this is where it
  # starts. `check_grant` lives on the fixed graph, which the router never
  # enters — the router only ever calls the gate's verbs — so a run could
  # execute with a grant that was absent, corrupt, or belonged to another run,
  # and nothing looked. Measured: a stage declaring cutpoint `배포` was launched
  # and ran 40 minutes while the file did not exist at the path the gate
  # derives; it appeared 9 hours 42 minutes later.
  #
  # The four fields the grant carries were being recorded and never compared,
  # which is precisely the defect class this contract exists to delete. And the
  # protection everyone relied on — "the driver has no write path to the grant,
  # so it cannot widen its own authority" — is true and worthless on its own: a
  # document nobody reads cannot be widened because it does not bind.
  local blocks b found=0 foreign="" gmax gi a tc ti gowner mowner
  if [ ! -f "$GRANT" ]; then
    warn "the authorization record is missing: $GRANT — kickoff has to run first"
    return "$GATE_EXIT_RULE"
  fi
  # One cut of this run's block for the ten field reads below. Every check
  # after this line runs unchanged, in the same order, with the same messages
  # and exit codes — only the number of times the file is opened changes.
  gate_grant_block_take
  blocks=$(grep -E '^## 인가 ' "$GRANT" 2>/dev/null | sed -E 's/^## 인가 //' | sed 's/[[:space:]]*$//' || true)
  while IFS= read -r b; do
    [ -n "$b" ] || continue
    if [ "$b" = "$RUN_ID" ]; then found=1; else foreign="${foreign}${b} "; fi
  done <<EOF
$blocks
EOF
  if [ -n "$foreign" ]; then
    # One document folds every one of its runs onto one grant path, so run N+1
    # meets a block it did not write. Inheriting an earlier run's merge
    # permission is the failure here that is both invisible and irreversible.
    warn "there is a foreign authorization block: ${foreign}— a person has to check it"
    return "$GATE_EXIT_RULE"
  fi
  if [ "$found" != "1" ]; then
    warn "the authorization block for this run ($RUN_ID) is not in the authorization record: $GRANT"
    return "$GATE_EXIT_RULE"
  fi

  # Ownership proof. Where the manifest names a document the grant must name the
  # same one; where it does not, the grant must carry the explicit absence
  # marker rather than omit the field — so "no document" stays distinguishable
  # from "field forgotten", which is what makes absence fail closed.
  # Through `owner_doc_match`, which is the driver's reader too. Two readers with
  # independently spelled acceptance sets is what let a grant pass kickoff and
  # then have every act here refused — the stage did nothing, exited clean, and
  # was recorded as a hollow success.
  mowner=$(manifest_hdr_field 'owner-doc')
  gowner=$(grant_owner_doc)
  if [ -z "$gowner" ]; then
    warn "the authorization record has no owner-doc= — fail-closed"
    return "$GATE_EXIT_RULE"
  fi
  if ! owner_doc_match "$mowner" "$gowner"; then
    warn "the owner-doc= of the authorization record differs from the manifest: '$gowner' vs '$mowner'"
    return "$GATE_EXIT_RULE"
  fi

  # The run maximum, cross-checked against the per-target values that actually
  # authorize acts. The grant's own field is a derived audit value and nothing
  # reads it to authorize anything — so without this comparison the two could
  # disagree for a whole night and the disagreement would be the one thing a
  # person could have caught by looking.
  # THE NINE FIELDS ARE CHECKED FOR PRESENCE, because until now exactly one of
  # them was ever read. The contract fixes the block at nine fields in a fixed
  # order and gives it no rewrite form — a block appended with a field missing
  # is frozen that way, and re-authorizing is a NEW run rather than an edit. So
  # a check that runs after the block is written cannot repair it; what it can
  # do is refuse to run on it, which is the only remaining moment the omission
  # is cheap. Measured: the kickoff's own template emitted eight, dropping
  # `직렬 웨이브 고지`, and nothing anywhere noticed.
  local gf
  for gf in '인가 일시' '종료 지점' '권한 절단점' '말단 행위 상한' '직렬 웨이브 고지' \
            '시각 정합 마커' '사용자 확인 문면' '설계 문서 전체 sha256' '보고서'; do
    if [ -z "$(gate_grant_field "${gf}")" ]; then
      warn "the authorization record has no \`${gf}\` — the contract requires all nine fields, and this block carries no rewritten form"
      return "$GATE_EXIT_RULE"
    fi
  done

  gmax=$(gate_grant_field '권한 절단점')
  if [ -z "$gmax" ]; then
    warn "the authorization record has no \`권한 절단점\`"
    return "$GATE_EXIT_RULE"
  fi
  gi=$(cutpoint_index "$gmax")
  if [ -z "$gi" ]; then
    warn "the \`권한 절단점\` of the authorization record is out of vocabulary: $gmax"
    return "$GATE_EXIT_VOCAB"
  fi
  for a in $(target_aliases); do
    tc=$(target_field "$a" '절단점')
    [ -n "$tc" ] || continue
    ti=$(cutpoint_index "$tc")
    [ -n "$ti" ] || continue
    if [ "$ti" -gt "$gi" ] 2>/dev/null; then
      warn "the cutpoint ($tc) of target ${a} exceeds the run maximum ($gmax) of the authorization record"
      return "$GATE_EXIT_RULE"
    fi
  done
  gate_check_repair_grant "$gi" || return $?
  return 0
}

readonly GATE_REPAIR_CONSENT='호스트 수리 런 — 플러그인 기본 동의'

gate_check_repair_grant() {
  # gate_check_repair_grant <index of 권한 절단점> — a run whose manifest carries
  # a `수리 사건` row is a repair run the plugin starts on the host's default
  # consent, not on a person's kickoff, so its authorization is held to that
  # consent's bounds: the block's confirmation text is the consent's own words,
  # the run reaches no further than `머지`, every target reviews before it
  # merges, and the preauthorization rows open nothing beyond a push, a pull
  # request and the merge call. A manifest without the row is checked as before.
  local gi=$1 mi a ceil
  [ -n "$(gate_repair_event_row)" ] || return 0
  if [ "$(gate_grant_field '사용자 확인 문면')" != "$GATE_REPAIR_CONSENT" ]; then
    warn "a repair run's authorization must carry \`사용자 확인 문면\` = '$GATE_REPAIR_CONSENT'"
    return "$GATE_EXIT_RULE"
  fi
  mi=$(cutpoint_index '머지')
  if [ -z "$mi" ] || [ "$gi" -gt "$mi" ] 2>/dev/null; then
    warn "a repair run's \`권한 절단점\` reaches past 머지"
    return "$GATE_EXIT_RULE"
  fi
  for a in $(target_aliases); do
    ceil=$(target_field "$a" '리뷰 정책 상한')
    if [ -n "$ceil" ] && [ "$ceil" != '선리뷰후머지' ]; then
      warn "a repair run reviews before it merges, but target ${a} allows '${ceil}'"
      return "$GATE_EXIT_RULE"
    fi
  done
  gate_repair_preauth_subset || return "$GATE_EXIT_RULE"
}

gate_repair_preauth_subset() {
  # gate_repair_preauth_subset — every `사전 인가` row of the manifest has one of
  # the repair run's fixed shapes: `git push`, `gh pr`, `gh api -X PUT`. The
  # shape is read the way the preauthorization rule reads it.
  local line shape
  while IFS= read -r line; do
    case "$line" in
      '- `사전 인가`'*) ;;
      *) continue ;;
    esac
    shape=$(printf '%s' "$line" | tr '|' '\n' | sed -n 's/^ *형태=//p' | sed 's/[[:space:]]*$//')
    case "$shape" in
      'git push'|'gh pr'|'gh api -X PUT') ;;
      *) warn "a repair run's preauthorization row '$shape' is outside git push, gh pr, gh api -X PUT"
         return 1 ;;
    esac
  done < "$MANIFEST"
  return 0
}

gate_surface_check() {
  # gate_surface_check <호출 동사>
  #
  # Compared on every act, not only at run start. The four surfaces the hook
  # cannot deny a write to get after-the-fact detection only, and after-the-fact
  # is still before the NEXT act — which is the difference between one act
  # slipping through and the rest of the night doing so.
  #
  # THE VERB DECIDES ONLY WHETHER THE CONSEQUENCE IS RECORDED, never whether the
  # comparison happens. Everything down to the verdict is a pure read — the
  # baseline file, the digest, the equality — so a dry run can answer this axis
  # exactly and cheaply, and a verb that could answer it and returned zero
  # instead is the defect class this whole change removes.
  # NO BASELINE FILE AND AN EMPTY ONE ARE DIFFERENT ANSWERS, and reading them as
  # the same one made this check fail OPEN on exactly the input it exists to
  # catch. A missing file means the run has not been baselined yet — kickoff
  # writes it, and every act before that has nothing to compare against, so
  # returning zero there is the only thing it can do. A file that is PRESENT and
  # EMPTY means the baseline was written and the value in it is gone: the digest
  # this comparison needs was lost, not never taken. Collapsed together, that
  # second state passed every act for the rest of the night without ever
  # comparing anything, silently, while the surrounding documentation promises
  # the opposite — that a run whose surface moved does not recover. Lost signal
  # takes the same exit as a moved surface, which is what fail-closed means here.
  local verb="${1:-act}" base now lk
  [ -f "$RUN_DIR/surface-digest" ] || return 0
  # THE BASELINE AND THE DIGEST ARE READ UNDER ONE HOLD OF `settings.lock`.
  # The `segment` arm rewrites the settings AND the baseline file under that
  # lock, so a check that read the baseline, then took the lock for the
  # digest, could straddle a sibling's re-derivation: an old baseline against
  # a new digest, on a surface nobody outside the gate had touched, and the
  # act took exit 7 and a `blocked` row for it. Two parallel segments writing
  # their first non-terminal rows is the ordinary case for this pipeline. A
  # process that already holds the lock (the arm itself) reads raw; a lock
  # that cannot be taken falls back to the unlocked read, which is the
  # fail-closed direction — a stale-but-consistent pair refuses rather than
  # permits.
  lk="$RUN_DIR/settings.lock"
  if [ -n "${GATE_SETTINGS_LOCK_HELD:-}" ]; then
    base=$(cat "$RUN_DIR/surface-digest" 2>/dev/null || true)
    now=$(gate_surface_digest_raw)
  elif gate_settings_lock "$lk"; then
    base=$(cat "$RUN_DIR/surface-digest" 2>/dev/null || true)
    now=$(gate_surface_digest_raw)
    gate_settings_unlock "$lk"
  else
    base=$(cat "$RUN_DIR/surface-digest" 2>/dev/null || true)
    now=$(gate_surface_digest_raw)
  fi
  if [ -z "$base" ]; then
    warn "the enforcement-surface baseline file is empty — the value disappeared after the baseline was recorded, so there is nothing to compare against"
    base='(비어 있음)'
  fi
  [ "$now" = "$base" ] && return 0
  warn "the enforcement surface changed after the run started (baseline ${base}, now ${now}) — one of the settings, the rules, the hook or the project settings was edited"

  # THE DISPOSITION FOR THIS CODE IS THE ROUTER'S AND ONLY THE ROUTER'S: stop
  # and tell the user. A stage cannot do either half. The cause is outside it by
  # definition — the surfaces are the run's settings, the rule catalog, the hook
  # and the project settings, none of which a stage touched and none of which it
  # can inspect, because looking needs Bash and Bash is what was just refused.
  # Re-baselining would be a stage moving the boundary that binds it.
  #
  # So a stage has retry or give up, and neither is the prescribed disposition.
  # Measured on one run: five stages, four of them retried into the same refusal
  # 3, 9, 12 and 15 times and produced no finding; the fifth stopped, and what
  # separated it from the other four was its own judgment rather than anything
  # the contract said. That is what this branch converts into an instruction.
  #
  # A prose fence and not a structural one, deliberately: the stage READ the old
  # message and retried, so the failure is an interpretable misjudgment on a
  # message that described a condition without prescribing an action. What it
  # gets now is an action, plus a run-scope `blocked` row so the run's state is
  # observable to the router and to the morning instead of living in the count
  # of a stage's wasted turns.
  # THE ROW IS WRITTEN WHOEVER IS CALLING, and it used to be written only for a
  # stage. The router is the one caller whose refusal nobody else can report:
  # when it takes this exit the ledger got no row at all, so the snapshot went
  # on rendering `진행 중` with zero live stages and zero open obligations —
  # byte-identical to a healthy run waiting for its next act, while in fact
  # every further act would take the same refusal. Measured: a run died here at
  # 113 rows and $33.36 and kept rendering as in-flight.
  #
  # The resume line is the only place a person is told what to do next, so
  # dropping it exactly when the router — the one that would have carried it to
  # them — is the caller inverted its purpose.
  # A DRY RUN STOPS HERE, and the three things below are each independently a
  # reason it must. The row it would append carries `원인=무효화`, which
  # condition 5 declares permanently unresolvable — so a question about the run
  # would end the run. The `done` path then opens for a run nobody proposed to
  # finish. And the same branch fires a desktop banner at a sleeping person to
  # report an event that did not happen.
  #
  # What the caller gets instead is the exit code by itself: on `plan`, 7 is a
  # forecast rather than an event.
  if [ "$verb" = "plan" ]; then
    warn "plan(dry-run): an act with the same argv gets exit 7 here — this is a preview, so no \`blocked\` row and no banner were left"
    return "$GATE_EXIT_SURFACE"
  fi
  if ! gate_has_row 'blocked' '사유=강제 표면 이동'; then
    gate_append 'blocked' "대상=${CC_PIPELINE_TARGET:--}" "스코프=run" "원인=무효화" \
      "사유=강제 표면 이동" "관측=$(now_iso)" \
      "재개 명령=새 런으로 다시 킥오프 — 이 런의 기준선은 다시 잡히지 않습니다" \
      "재킥 원인=표면이동"
    # This row ends the run without `done`, so it is the row that settles the
    # end token: the router stops after exit 7 and reaches no other ending site.
    # THE RUN ANCHORED AND CANNOT BE UNANCHORED. This is one of the two places
    # the run's own end is decided rather than observed, and the notice belongs
    # here because the other channel cannot carry it: the watcher's terminal arm
    # keys on a predicate that requires zero unresolved run-scope blocks, and
    # this row is exactly such a block, so that arm is silent for this run
    # forever.
    #
    # `rekick` and not `hands`: the gate refuses to resolve a block whose cause
    # is invalidation, so it is not something a person can put their hands on. It
    # fails the stacking test — "an individually identified thing that stays put
    # until a person touches THAT" — so it takes the per-run replace slot, and
    # the title names the one action actually available here, which is to open a
    # fresh run because this one's baseline cannot be taken again.
    if gate_may_raise_banner && [ -n "${RUN_DIR:-}" ] && [ ! -f "$RUN_DIR/notify.announced-void" ]; then
      : > "$RUN_DIR/notify.announced-void" 2>/dev/null || true
      cc_notify_fire rekick \
        "이 런은 여기서 끝났습니다 — 기준선은 다시 잡히지 않으니 새 런으로 다시 킥오프하세요" || true
    fi
  fi
  if [ -n "${CC_PIPELINE_SEGMENT:-}" ]; then
    warn "this condition is not resolved inside this run — do not retry. Stop now, write in your return message what you were trying to do when you were blocked, and go back. The remaining calls get the same refusal."
  else
    warn "this run ended here — the baseline is not taken again. Do not retry; tell the user what moved the surface and kick off again as a new run."
  fi
  return "$GATE_EXIT_SURFACE"
}

# FOUR OF THE SIX SURFACES ARE DELIBERATELY NOT IN THIS DIGEST, for two
# different reasons. Two of them move on their own, which is the same defect the
# progress vector was rebuilt to remove; the other two — the rule catalog and
# the hook — are shared installation paths whose legitimate redeployment is
# indistinguishable here from tampering, and they are covered by layer 1
# instead (see `gate_surface_digest`).
#
# The **ledger** legitimately grows on every act — written by this very function's
# caller. Comparing a digest over it at each act means the gate's own write moves
# the value it is about to check, so every act after the first is refused. Its
# integrity is the hash CHAIN's job instead, and the chain is strictly stronger
# here: it detects a splice, a deletion and a reordering, which a whole-file
# digest cannot distinguish from an ordinary append.
#
# The **transcript directory** is appended to by the harness continuously, for
# the same structural reason and with the same result. Its protection is layer
# 1's Write/Edit denial, and the honest statement is that this surface has ONE
# layer rather than two — layer 2 does not reach it at all, because a local file
# write is not an operation any credential governs.
#
# So this covers the two that neither move on their own nor are shared with the
# installation: the run's own settings directory and each target's project
# settings. A design sentence that counts six surfaces is describing what must
# be protected; this is which mechanism protects each, and for four of the six
# that mechanism is layer 1 alone.
gate_settings_lock() {
  # A mutex over the settings directory, held by BOTH the readers and the
  # writer. `mkdir` because it is atomic on every filesystem this runs on and
  # needs no external tool — `lockf` is darwin-only here, and this hazard is not.
  #
  # Locking only the writer would not be enough: `gate_write_settings` truncates
  # each file in place (`cat > "$f"`), so a concurrent digest walks a directory
  # that is half old and half new and gets a value that matches neither side.
  # That is what turned two parallel stages into a pair of re-derivations
  # undoing each other — measured as A→B then B→A in one run's ledger, with no
  # directory actually added and the run invalidated inside twelve minutes.
  local lockdir="$1" waited=0
  while ! mkdir "$lockdir" 2>/dev/null; do
    waited=$(( waited + 1 ))
    # Give up rather than hang. A caller that could not take the lock returns
    # its previous answer, which is the safe direction: the digest is compared
    # against a baseline, and a stale-but-consistent value refuses rather than
    # permits.
    [ "$waited" -gt 200 ] && return 1
    sleep 0.05
  done
  return 0
}

gate_settings_unlock() { rmdir "$1" 2>/dev/null || true; }

gate_surface_digest() {
  local lk="${RUN_DIR:-}/settings.lock" out
  # A process already holding the lock (the `segment` arm, across its
  # re-derivation and append) reads raw; taking it again would wait out the
  # timeout against itself.
  if [ -n "${GATE_SETTINGS_LOCK_HELD:-}" ]; then
    gate_surface_digest_raw
  elif [ -n "${RUN_DIR:-}" ] && gate_settings_lock "$lk"; then
    out=$(gate_surface_digest_raw)
    gate_settings_unlock "$lk"
    printf '%s' "$out"
  else
    gate_surface_digest_raw
  fi
}

gate_surface_digest_raw() {
  # The extension is read from the manifest on every call: the second element
  # is the project-scope settings file of each target row's main worktree. The
  # target list CANNOT GROW DURING A RUN. It comes from the manifest alone, the
  # manifest is written at kickoff and every later write to it is refused, and
  # no ledger row is an input — the `대상 추가` rows the layer-1 enrolment
  # appends are never read back here or by any other derivation. So this
  # digest's cost follows the number of targets, not how far the run has
  # progressed.
  #
  # THE INSTALLED PLUGIN'S OWN FILES ARE NOT IN HERE, and that is the whole
  # reason this digest stopped ending runs for doing nothing wrong. The rule
  # catalog and the hook are shared installation paths, not per-run copies, so
  # a digest over them cannot tell "a stage edited the boundary it stands in"
  # from "the operator deployed a new version" — and the second is ordinary
  # operation. Measured: two runs were executing stages on this machine while a
  # rule file needed fixing; deploying killed both, and not deploying kept every
  # router-driven run's merge refused.
  #
  # What covers them instead is layer 1: the hook denies Write/Edit to
  # `*/orchestrator/rules/*` and to its own directory outright, so a stage
  # cannot reach either through the edit tools at all. Dropping them here takes
  # those two surfaces from two layers to one rather than to zero — the same
  # trade this file already states in as many words for the transcript
  # directory, and stated here for the same reason: so the count is honest.
  gate_surface_lines_raw | shasum -a 256 | cut -d' ' -f1
}

gate_surface_lines_raw() {
  # The digest's input, one `<sha256>  <path>` line per file that exists: the
  # run's rendered settings first, then each target's project settings. The
  # digest is the hash of exactly these bytes, so the per-file list written
  # beside a baseline is taken from the same lines and cannot disagree with it.
  local a wt
  {
    find "$(gate_settings_dir)" -type f 2>/dev/null | sort
    for a in $(target_aliases); do
      wt=$(target_field "$a" '메인 워크트리')
      [ -n "$wt" ] || continue
      printf '%s\n' "$wt/.claude/settings.json"
    done
  } | while IFS= read -r f; do
        [ -f "$f" ] || continue
        printf '%s  %s\n' "$(shasum -a 256 "$f" | cut -d' ' -f1)" "$f"
      done
}

gate_surface_lines_capture() {
  # gate_surface_lines_capture — read the surface ONCE into a file under the
  # run directory and print its path. A site that writes a baseline takes the
  # digest and the per-file list from this one file (`gate_surface_files_from`),
  # so the two cannot describe different moments.
  #
  # AN AGGREGATE HASH CANNOT SAY WHAT MOVED. When the surface moves, whether
  # the run's own rendered settings moved or a target's `.claude/settings.json`
  # did decides who may answer for it, and one hash over both answers neither.
  # So every site that writes a baseline writes the list beside it; a baseline
  # written without its list is a run whose surface move nobody can classify.
  #
  # Under the settings lock unless the caller already holds it; a lock that
  # cannot be taken falls back to the unlocked read, as `gate_surface_digest`
  # does.
  local lk="$RUN_DIR/settings.lock" lines="$RUN_DIR/surface-digest.lines.$$" held=0
  if [ -z "${GATE_SETTINGS_LOCK_HELD:-}" ] && gate_settings_lock "$lk"; then
    held=1
  fi
  gate_surface_lines_raw > "$lines" 2>/dev/null || true
  [ "$held" = 1 ] && gate_settings_unlock "$lk"
  printf '%s' "$lines"
}

gate_surface_files_from() {
  # gate_surface_files_from <lines-file> — classify the captured lines into
  # `$RUN_DIR/surface-digest.files`, published by rename, and drop the capture.
  #
  # Each line is `<구분>\t<sha256>  <path>`: `런설정` for a file under the run's
  # settings directory, `대상설정` for a target's project settings. The column
  # after the tab is byte for byte a line of the digest's input.
  local sd tmp="$RUN_DIR/surface-digest.files.$$"
  sd="$(gate_settings_dir)/"
  if awk -v sd="$sd" '{
        path = substr($0, 67)
        printf "%s\t%s\n", (index(path, sd) == 1 ? "런설정" : "대상설정"), $0
      }' "$1" > "$tmp" 2>/dev/null; then
    mv -f "$tmp" "$RUN_DIR/surface-digest.files" 2>/dev/null || rm -f "$tmp" 2>/dev/null || true
  else
    rm -f "$tmp" 2>/dev/null || true
  fi
  rm -f "$1" 2>/dev/null || true
}

# ---------------------------------------------------------------------------
# Verb dispatch
# ---------------------------------------------------------------------------
gate_usage() {
  sed -n '/^# Usage:/,/^#$/p' "$0" | sed 's/^# \{0,1\}//'
}

gate_pin_hop() {
  # gate_pin_hop <orchestrator-dir> — re-run this whole call from the pinned
  # copy. Does not return.
  #
  # THE CAPTURED ARGV, NOT `"$@"`. The two hop points sit after the argument
  # loop has already consumed the array, and the test harness enters through
  # `gate_main` directly rather than through the file's trailing call — so the
  # only copy of the original argument vector is the one the first statement of
  # `gate_main` put aside. The bash 3.2 spelling below is what keeps an empty
  # array from tripping `set -u`.
  #
  # `CC_GATE_SOURCE_ONLY` IS STRIPPED. The copy's trailing guard returns rc 0
  # without calling `gate_main` when that variable is set, and the source-only
  # seam (`scripts/test-gate.sh`) exports it — so a value inherited across the
  # hop would turn every gate call in a pinned run into a silent no-op.
  # `CC_ORCH_SOURCE_ONLY` needs no such care: the copy's own sourcing block sets
  # it again before it sources the driver.
  local dir="$1"
  unset CC_GATE_SOURCE_ONLY
  exec "${BASH:-/bin/bash}" "$dir/gate.sh" ${GATE_HOP_ARGV[@]+"${GATE_HOP_ARGV[@]}"}
}

gate_hop_or_die() {
  # gate_hop_or_die <run-dir> — hop into that run's pinned copy if there is one.
  # Returns only when there is nothing to hop into; every refusal is a `die`.
  #
  # ONE SPELLING FOR BOTH HOP POINTS. The two sites carried the same call and the
  # same `case` in two copies, which is a refusal text that gets fixed on one
  # side and a new return code that gets handled on one side.
  local t rc=0
  t=$(pin_hop_target "$1" "$GATE_DIR") || rc=$?
  case "$rc" in
    0) gate_pin_hop "$t" ;;
    2) die "plugin-pin is present but the copy is not: $1/plugin-pin — recovery: rm \"$1/plugin-pin\"" ;;
    3) die "plugin-pin points at something that is not this run's copy: $1/plugin-pin — it is not a pin this run published, so nothing is executed" ;;
  esac
  return 0
}

gate_pin_version_field() {
  # gate_pin_version_field <commit|tree|digest> — the value of one of the `run`
  # row's three version fields, read from this run's pin.
  #
  # An unpinned run answers `(고정 안 함)` for all three: the seeded test runs
  # and every run opened before pinning existed are unpinned, and a morning
  # reader has to be able to tell that apart from a pin whose value is unknown.
  # A dirty subtree answers `(미커밋)` for the tree, because there is no tree
  # object naming the bytes that were copied — the copy in the run directory is
  # then the only one there is, which the restore recipe says out loud.
  local rd="${RUN_DIR:-}" v d
  { [ -n "$rd" ] && [ -f "$(pin_file "$rd")" ]; } || { printf '(고정 안 함)'; return 0; }
  case "$1" in
    commit)
      v=$(pin_read "$rd" 'commit'); [ -n "$v" ] || v='(미상)'; printf '%s' "$v" ;;
    tree)
      d=$(pin_read "$rd" 'dirty')
      if [ "$d" = '예' ]; then printf '(미커밋)'; return 0; fi
      v=$(pin_read "$rd" 'tree'); [ -n "$v" ] || v='(미상)'; printf '%s' "$v" ;;
    digest)
      printf '%s' "$(pin_read "$rd" 'digest')" ;;
  esac
}

gate_main() {
  # FIRST STATEMENT, ahead of even the arity check. The harness calls this
  # function directly, so the file's trailing `gate_main "$@"` is not a place
  # the capture could live.
  GATE_HOP_ARGV=("$@")
  [ $# -ge 1 ] || { gate_usage >&2; exit 2; }
  local verb="$1"; shift
  local kind="" alias="" segment="-" cutpoint="" surface="" snapdig="" rationale=""
  local approval="" render=0 worktree="" void=0 reject=0
  local emit_digest_seen=0 emit_digest_dir=""
  local reach="" destructive=0
  local wait_interval="" wait_timeout="" nonce=""
  local fields="" fields_seen=0
  local end_cause="" end_successor=""
  local -a ss_flags=()
  local sa_record=""
  GATE_RESUME=""; export GATE_RESUME
  # A plain global, reset here, so a value the caller's environment carries
  # never reaches the arm that reads it — only the argv flag below sets it.
  GATE_FROM_DECLARATION=""
  # The recovery marker of a review re-dispatch, the same way: only the argv
  # flag sets it, and only `act --kind skill` of a review takes it.
  GATE_RECOVERY=""
  # The ledger line of the `중단 답` row a carry act hands on, the same way: only
  # the argv flag sets it, and only `act --kind skill` takes it.
  GATE_CARRY_ANSWER=""
  # The trigger a review dispatch declares and the reason a `라우터 판단` one
  # gives, the same way: only the argv flags set them, and only `act`/`plan
  # --kind skill` of a review takes them.
  GATE_TRIGGER=""; GATE_TRIGGER_SEEN=""; GATE_TRIGGER_REASON=""
  # The report `report-check` reads; no other verb takes it.
  local report_arg="" report_seen=0
  # THE APPLY ACT'S THREE VALUES ARE CLEARED ON ENTRY, AND NO FLAG SETS THEM.
  # `GATE_SUBJECT_HEAD` is the head the merge rule judges an apply against, and
  # the act sets it only after its own preconditions proved `M^2` to be the
  # reviewed head or its honest renumbering merge; an exec that inherited one from its environment would carry a
  # head nobody proved into the rule. `GATE_APPLY_ARM` is the marker that lets
  # the segment arm accept `적용 준비` and `완료` for a segment that still owes
  # an apply, and a caller that could export it would write those states by hand.
  unset GATE_SUBJECT_HEAD
  # The renumbering merge the merge rule passes is proved by the act itself,
  # below, and by nothing a caller can set.
  unset GATE_META_RESOLVED_HEAD
  GATE_APPLY_ARM=""; GATE_APPLY_COMMAND=""
  # The rerun act's marker, verdict and runs are set by this process's own
  # precondition and eligibility checks and by nothing a caller exports: a
  # verdict inherited from the environment would send a POST no check chose.
  unset GATE_CI_RERUN_PRE GATE_CI_RERUN_VERDICT GATE_CI_RERUN_RUNS GATE_PARK_OBS
  # The match act's admission and the target it read are this process's own
  # in the same way: an inherited admission would write a match row no check
  # admitted.
  unset GATE_CI_MATCH_ADMIT GATE_CI_MATCH_ALIAS GATE_CI_MATCH_HEAD
  # The label act's the same way.
  unset GATE_LABEL_ACK_PRE GATE_LABEL_ACK_VERDICT
  # The emit path travels to `gate_verb_act` as a global rather than as an
  # eleventh positional argument, the same way `GATE_RESUME`, `GATE_ACT_CWD` and
  # `GATE_SURFACE` already do. Adding a position would mean fixing the call site
  # and the `shift 9` arithmetic inside the callee at the same time, for a value
  # neither of them decides anything on.
  GATE_EMIT_DIGEST_TO=""; export GATE_EMIT_DIGEST_TO
  # The site of a shift's halt record travels the same way, for the same reason.
  GATE_SHIFT_HALT_SITE=""
  # The marker that lets `shift-halt` carry its four record fields onto a cone
  # row is set by that act around its one call. A caller that could export it
  # would write a row vouching for a record the gate never wrote.
  GATE_SHIFT_HALT_WRITING=""
  # The admit marker turns the exec pipeline into the bare form's; only the
  # `admit` arm sets it, after it has read the request.
  GATE_ADMIT=""
  local request=""
  MANIFEST=""
  MANIFEST_MEMO_PATH=""; MANIFEST_MEMO=""
  GATE_GRANT_MEMO_PATH=""; GATE_GRANT_MEMO_RUN=""; GATE_GRANT_MEMO_BLOCK=""

  while [ $# -gt 0 ]; do
    case "$1" in
      --manifest)        MANIFEST="$2"; shift 2 ;;
      --kind)            kind="$2"; shift 2 ;;
      --target)          alias="$2"; shift 2 ;;
      --segment)         segment="$2"; shift 2 ;;
      --cutpoint)        cutpoint="$2"; shift 2 ;;
      --surface)         surface="$2"; shift 2 ;;
      --reach)           reach="$2"; shift 2 ;;
      --destructive)     destructive=1; shift ;;
      --snapshot-digest) snapdig="$2"; shift 2 ;;
      # A BOOLEAN. It took a path once; see the emission block for why it does
      # not any more. The old spelling is refused rather than ignored, because a
      # caller passing a path believes it chose where the value lands.
      --emit-digest)     emit_digest_seen=1; shift ;;
      --emit-digest-to)  printf 'gate: --emit-digest-to is gone — use --emit-digest with no path (the gate picks the path under the run directory)\n' >&2
                         exit 2 ;;
      --rationale)       rationale="$2"; shift 2 ;;
      --approval)        approval="$2"; shift 2 ;;
      --worktree)        worktree="$2"; shift 2 ;;
      --render)          render=1; shift ;;
      --void)            void=1; shift ;;
      --reject)          reject=1; shift ;;
      --resume)          GATE_RESUME="$2"; shift 2 ;;
      --carry-answer)    GATE_CARRY_ANSWER="$2"; shift 2 ;;
      --site)           GATE_SHIFT_HALT_SITE="$2"; shift 2 ;;
      --from-declaration) GATE_FROM_DECLARATION=1; shift ;;
      --recovery)        GATE_RECOVERY="$2"; shift 2 ;;
      --trigger)         GATE_TRIGGER="$2"; GATE_TRIGGER_SEEN=1; shift 2 ;;
      --trigger-reason)  GATE_TRIGGER_REASON="$2"; GATE_TRIGGER_SEEN=1; shift 2 ;;
      --report)          report_arg="$2"; report_seen=1; shift 2 ;;
      --interval)        wait_interval="$2"; shift 2 ;;
      --timeout)         wait_timeout="$2"; shift 2 ;;
      --nonce)           nonce="$2"; shift 2 ;;
      --request)         request="$2"; shift 2 ;;
      --cause)           end_cause="$2"; shift 2 ;;
      --successor)       end_successor="$2"; shift 2 ;;
      --record)          sa_record="$2"; shift 2 ;;
      # The screening tool's own three switches, handed to it as they came.
      --list|--tokens|-z) ss_flags+=("$1"); shift ;;
      # THE SELECTOR OWNS THE COMMA. A bare `--fields` (no value, or the next
      # token is another flag or the `--` separator) selects the default list;
      # the value is never read as a filename, so `--fields --` cannot swallow
      # the argv separator.
      --fields)          fields_seen=1
                         case "${2:-}" in ''|--*) fields=""; shift ;; *) fields="$2"; shift 2 ;; esac ;;
      --)                shift; break ;;
      *) printf 'gate: unknown argument: %s\n' "$1" >&2; exit 2 ;;
    esac
  done

  if [ -n "$sa_record" ] && [ "$verb" != "seat-apply-preview" ]; then
    printf 'gate: --record is used only with seat-apply-preview (verb received: %s)\n' "$verb" >&2
    exit 2
  fi
  if [ "$verb" = "seat-apply-preview" ] && [ -z "$sa_record" ]; then
    printf 'gate: seat-apply-preview needs --record <halt record>\n' >&2
    exit 2
  fi
  if [ "${#ss_flags[@]}" -gt 0 ] && [ "$verb" != "surface-screen" ]; then
    printf 'gate: --list, --tokens and -z are used only with surface-screen (verb received: %s)\n' "$verb" >&2
    exit 2
  fi
  if [ "$fields_seen" = "1" ] && [ "$verb" != "snapshot" ]; then
    printf 'gate: --fields is used only with snapshot (verb received: %s)\n' "$verb" >&2
    exit 2
  fi

  # `--from-declaration` fills a segment row and nothing else; on any other kind
  # or verb it would be a flag the caller believes is working.
  if [ "$GATE_FROM_DECLARATION" = "1" ]; then
    case "$verb:$kind" in
      act:segment|plan:segment) ;;
      *) printf 'gate: --from-declaration is used only with act/plan --kind segment (received: %s --kind %s)\n' "$verb" "${kind:-(none)}" >&2
         exit 2 ;;
    esac
  fi
  # `--recovery` marks a review re-dispatch after a dropped connection; on any
  # other verb or kind it would be a marker the caller believes is recorded.
  # The stage kind is checked where the dispatch argv is known.
  if [ -n "$GATE_RECOVERY" ]; then
    if [ "$verb:$kind" != "act:skill" ]; then
      printf 'gate: --recovery is used only with act --kind skill (received: %s --kind %s)\n' "$verb" "${kind:-(none)}" >&2
      exit 2
    fi
    if [ "$GATE_RECOVERY" != "전송 단절" ]; then
      printf 'gate: --recovery takes one value, 전송 단절 (received: %s)\n' "$GATE_RECOVERY" >&2
      exit 2
    fi
  fi
  # `--carry-answer` names the `중단 답` row a stage dispatch hands on. Whether
  # the halted session is re-attached is the gate's decision, so a caller that
  # also names the session to resume is refused with no row (exit 3), the same
  # way the carry's other refusals end.
  if [ -n "$GATE_CARRY_ANSWER" ]; then
    if [ "$verb:$kind" != "act:skill" ]; then
      printf 'gate: --carry-answer is used only with act --kind skill (received: %s --kind %s)\n' "$verb" "${kind:-(none)}" >&2
      exit 2
    fi
    case "$GATE_CARRY_ANSWER" in
      *[!0-9]*|0*) printf 'gate: --carry-answer takes the ledger line number of a 중단 답 row (received: %s)\n' "$GATE_CARRY_ANSWER" >&2
                   exit 2 ;;
    esac
    if [ -n "$GATE_RESUME" ]; then
      printf 'gate: --carry-answer and --resume together — the gate decides whether the halted session is re-attached; pass --carry-answer alone\n' >&2
      exit 3
    fi
  fi
  # `--trigger` and `--trigger-reason` declare why a review is dispatched; on
  # any other verb or kind they would be a declaration the caller believes is
  # checked. The stage kind is checked where the dispatch argv is known.
  if [ -n "$GATE_TRIGGER_SEEN" ]; then
    case "$verb:$kind" in
      act:skill|plan:skill) ;;
      *) printf 'gate: --trigger and --trigger-reason are used only with act/plan --kind skill of a review dispatch (received: %s --kind %s)\n' "$verb" "${kind:-(none)}" >&2
         exit 2 ;;
    esac
  fi
  # `--report` names the report `report-check` reads, and nothing else reads it.
  if [ "$report_seen" = "1" ] && [ "$verb" != "report-check" ]; then
    printf 'gate: --report is used only with report-check (verb received: %s)\n' "$verb" >&2
    exit 2
  fi
  # `--site` names a row of the shift-halt site table and nothing else.
  if [ -n "$GATE_SHIFT_HALT_SITE" ] && [ "$verb:$kind" != "act:shift-halt" ]; then
    printf 'gate: --site is used only with act --kind shift-halt (received: %s --kind %s)\n' "$verb" "${kind:-(none)}" >&2
    exit 2
  fi
  # `apply` names an act the gate performs and a forecast of it; under any other
  # verb the kind would be carried by a verb that never reads it.
  if [ "$kind" = "apply" ]; then
    case "$verb" in
      act|plan) ;;
      *) printf 'gate: --kind apply is used only with act/plan (verb received: %s)\n' "$verb" >&2
         exit 2 ;;
    esac
  fi
  # `ci-rerun` the same way: the gate performs the rerun, and a forecast of it.
  # `label-ack` likewise: the gate performs the label POST.
  if [ "$kind" = "ci-rerun" ] || [ "$kind" = "label-ack" ]; then
    case "$verb" in
      act|plan) ;;
      *) printf 'gate: --kind %s is used only with act/plan (verb received: %s)\n' "$kind" "$verb" >&2
         exit 2 ;;
    esac
  fi
  # `ci-match` too: the gate reads the failing logs and writes the match row.
  if [ "$kind" = "ci-match" ]; then
    case "$verb" in
      act|plan) ;;
      *) printf 'gate: --kind ci-match is used only with act/plan (verb received: %s)\n' "$verb" >&2
         exit 2 ;;
    esac
  fi

  # ACCEPTED ONLY WHERE THEY DECIDE SOMETHING — the `--reach` precedent below.
  # `--interval`/`--timeout` govern one verb's loop and `--nonce` is the launch
  # token only the two detached verbs consume; a flag that is silently inert is a
  # flag a caller believes is working. Non-numeric values are refused for the
  # same reason a vocabulary miss is: a loop bound that reads as text degrades
  # to a shell arithmetic error deep inside a poll nobody is watching.
  if [ -n "$wait_interval" ] || [ -n "$wait_timeout" ]; then
    case "$verb" in
      wait) ;;
      *) printf 'gate: --interval and --timeout are used only with wait (verb received: %s)\n' "$verb" >&2
         exit 2 ;;
    esac
    case "${wait_interval:-1}${wait_timeout:-1}" in
      *[!0-9]*) printf 'gate: --interval and --timeout have to be integers in seconds\n' >&2; exit 2 ;;
    esac
  fi
  if [ -n "$nonce" ]; then
    case "$verb" in
      supervise-stage|metrics-round|halt-report-round) ;;
      *) printf 'gate: --nonce is used only with supervise-stage, metrics-round and halt-report-round (verb received: %s)\n' "$verb" >&2
         exit 2 ;;
    esac
  fi
  # The same rule for the two closing flags: they decide something on one verb
  # only. Their vocabulary is checked in that verb, after the run is known.
  if [ -n "$end_cause" ] || [ -n "$end_successor" ]; then
    case "$verb" in
      end-abandoned) ;;
      *) printf 'gate: --cause and --successor are used only with end-abandoned (verb received: %s)\n' "$verb" >&2
         exit 2 ;;
    esac
  fi
  # `wait` is not an act: it writes no row, so a digest bound to the ledger's
  # state has nothing to bind to, and accepting one would let a caller believe
  # the verb checks it.
  if [ "$verb" = "wait" ] && [ -n "$snapdig" ]; then
    printf 'gate: wait does not take --snapshot-digest — it is a verb that writes no row\n' >&2
    exit 2
  fi

  # THE EMIT PATH IS SETTLED BEFORE ANYTHING READS THE LEDGER, because its
  # failure is an argv error and not a run state — and because the failure the
  # caller cannot afford is the silent one. A caller that asked for the digest
  # and got no file falls back to the round trip forever, which looks exactly
  # like the flag working and saving nothing. Refusing with the same exit 2 the
  # unknown-argument arm uses is what makes that case audible.
  # ARGV SHAPE ONLY. Everything that touches the filesystem moved below
  # `rundir_init`, and the reason is not tidiness: creating the parent directory
  # here happened before the manifest existence check, before `check_manifest`,
  # before `gate_check_grant` and before the run directory exists, so a call
  # that was about to be refused had already made a directory and no row
  # recorded it.
  # ACCEPTED ONLY WHERE IT DOES SOMETHING. Emission happens on the acting verbs
  # and nowhere else, but the flag used to be parsed, validated and have its
  # parent directory created on every verb — so `snapshot`, `grade` and `plan`
  # took a value they would never use and made a directory for it. A flag that
  # is silently inert is a flag a caller believes is working.
  # `--request` names the bare request `admit` grades, and nothing else reads it.
  if [ -n "$request" ] && [ "$verb" != "admit" ]; then
    printf 'gate: --request is used only with admit (verb received: %s)\n' "$verb" >&2
    exit 2
  fi
  if [ "$verb" = "admit" ]; then
    [ -n "$request" ] || { printf 'gate: admit needs --request <id|last>\n' >&2; exit 2; }
    [ -z "$kind" ] || { printf 'gate: admit takes no --kind — it grades the request'"'"'s own words\n' >&2; exit 2; }
    [ $# -eq 0 ] || { printf 'gate: admit takes no command after -- — the command is the request the run hook recorded\n' >&2; exit 2; }
  fi
  if [ "$emit_digest_seen" = "1" ]; then
    case "$verb" in
      act|exec|admit) ;;
      *) printf 'gate: --emit-digest is used only with act, exec and admit (verb received: %s)\n' "$verb" >&2
         exit 2 ;;
    esac
  fi

  # ACCEPTED ONLY WHERE THEY DECIDE SOMETHING — the `--emit-digest` precedent
  # directly above. The reach axis governs one bash line's disposition, so it
  # rides `exec` and the dry run that forecasts the same argv, and nowhere else.
  # A `plan --kind …` forecasts a ledger row instead of a command, and a row
  # reaches nothing, so it is refused here rather than taking a value it would
  # never read: a flag that is silently inert is a flag a caller believes is
  # working.
  if [ -n "$reach" ] || [ "$destructive" = "1" ]; then
    case "$verb" in
      exec|admit) ;;
      # The remote read names where it reaches; it changes nothing there.
      act) [ "$kind" = "remote-check" ] && [ "$destructive" = "0" ] || {
              printf 'gate: --reach is used with act only on --kind remote-check, and --destructive never\n' >&2
              exit 2; } ;;
      plan) [ -z "$kind" ] || {
              printf 'gate: --reach and --destructive are used only with a plan that has no --kind\n' >&2
              exit 2; } ;;
      *) printf 'gate: --reach and --destructive are used only with exec and with a plan that has no --kind (verb received: %s)\n' "$verb" >&2
         exit 2 ;;
    esac
  fi
  # CLOSED VOCABULARY, checked before anything reads it. An unrecognized token is
  # exit 2 and never a silent fallback to the safest value: the whole point of
  # the axis is that a stage says where its write lands, and a misspelling that
  # degrades to `런로컬` would make the safest disposition the easiest one to
  # reach by accident.
  if [ -n "$reach" ]; then reach_index "$reach" >/dev/null || exit 2; fi
  GATE_REACH="$reach"; export GATE_REACH
  GATE_DESTRUCTIVE="$destructive"; export GATE_DESTRUCTIVE

  [ -n "$MANIFEST" ] || { printf 'gate: --manifest is required\n' >&2; exit 2; }
  # ABSOLUTE, BEFORE ANYTHING COMPARES AGAINST IT. The manifest write guard asks
  # whether an act names this file, and it asked by comparing strings — so the
  # same file reached through a relative path, or through any other spelling of
  # the same absolute path, was a different string and the guard missed it. The
  # value is a path the caller chose; normalizing it once here is what makes
  # every later comparison a question about the FILE.
  #
  # Only when the directory exists. `cd` into a missing directory fails, and
  # letting the failure through would leave `/$(basename …)` — a path naming
  # nothing, which the guard would then compare against and never match. A
  # manifest whose directory is absent is a hard stop one line later anyway, so
  # keeping the original value costs nothing and removes a way to disarm the
  # guard by pointing it somewhere unreachable.
  #
  # LOGICAL, not physical, and deliberately so. `MANIFEST` is also the value the
  # digest path reads, the value the refusal messages print and the value a
  # caller sees echoed back, so resolving symlinks here would rewrite the path
  # every caller spelled into one they never used. Symlink identity belongs to
  # the comparison that needs it: `gate_manifest_write_guard` resolves both
  # sides physically at the point of comparison and leaves this value alone.
  if [ -d "$(dirname "$MANIFEST")" ]; then
    MANIFEST="$(cd "$(dirname "$MANIFEST")" && pwd)/$(basename "$MANIFEST")"
  fi
  # ONE READ OF THE MANIFEST FOR THIS WHOLE CALL. Taken after the path is
  # settled and before the first reader, in this shell so every reader — the
  # ones inside command substitutions included — answers from the same bytes.
  # A missing file leaves the memo empty and `check_manifest` refuses it with
  # the same message it always did.
  manifest_snapshot_take

  # HOP (A) — AN ALREADY PINNED RUN, AT THE EARLIEST POINT IT CAN BE DETECTED.
  #
  # Nothing above this line writes: the manifest read is a memo in this shell.
  # That matters because `exec` carries the pid and the start-time fingerprint
  # forward but DROPS every EXIT trap, so a marker or a lock taken before a hop
  # is a ghost that passes its own liveness check. The placement is the
  # invariant, not a convenience.
  #
  # The run id comes from the manifest header, which the memo above already
  # answers, and the run directory from the one helper `rundir_init` uses. The
  # header/body cross-check has not run yet; the copy's own `check_manifest`
  # performs it a moment later, so nothing is skipped.
  #
  # THE HEADER VALUE IS NOT TRUSTED, AND THE REFUSAL IS FAIL-CLOSED. These are
  # caller-supplied bytes read before the header/body cross-check, so the one
  # helper that builds the path refuses an id carrying a path component and the
  # call dies rather than continuing with an unchecked directory.
  local hop_rid hop_rd hop_tg hop_al
  hop_rid=$(manifest_hdr_field 'run-id' 2>/dev/null) || hop_rid=""
  if [ -n "$hop_rid" ]; then
    hop_rd=$(rundir_of_run_id "$hop_rid") \
      || die "the run id in the manifest header carries a path component: $hop_rid"
    gate_hop_or_die "$hop_rd"
  fi

  check_manifest
  derive_paths_from_manifest
  gate_check_grant || exit $?

  # HOP (B) — A RUN OPENING RIGHT NOW. Still above `rundir_init`, and for the
  # same reason: everything that leaves a trace in the run directory is below it.
  #
  # "New run" is the pair of absences, and both halves are needed. `settings/`
  # alone would re-pin a run opened before this code existed — those runs are
  # deliberately left unpinned rather than retrofitted, because their watcher and
  # their in-flight shift are already running the old file. `plugin-pin` alone
  # would say nothing about a run that opened seconds ago on the older gate.
  #
  # `CC_GATE_PIN_DISABLE` is a TEST SEAM AND ONLY THAT: it suppresses pinning a
  # new run and never makes hop (A) ignore an existing pin. A stage cannot set it
  # — the stage hook refuses a leading assignment in front of the gate path — so
  # it cannot be used to escape a pinned run's copy. Its sibling seam
  # `CC_GATE_PIN_SYNC_DISABLE` is read by `pin_sync` in pin.sh and keeps the pin
  # on while turning off only the fetch and fast-forward before it.
  #
  # THE TARGET LIST IS HANDED TO THE PIN so `pin_sync` can tell a source that is
  # a declared target — and take that target's base branch — from one that is
  # not: one line per alias, its common git directory and its base branch.
  #
  # THE HOP IS UNCONDITIONAL; ONLY THE PINNING IS CONDITIONAL. It used to sit
  # INSIDE the pair of absences, so a second opener that arrived after the pin was
  # published — the window between hop (A) and here holds `check_manifest`,
  # `derive_paths_from_manifest` and `gate_check_grant`, which is the widest of
  # the three races in this path — skipped the block entirely: it did not pin
  # (right, one exists) and did not hop either (wrong, the copy exists). It then
  # ran its verb from the shared checkout while the `run` row it wrote reported
  # the winner's pin, so the ledger claimed a pinned run that was not one. A run
  # that opened before this code exists still passes through untouched: it has no
  # pin, so `pin_hop_target` answers rc 1 and nothing happens.
  if [ "${CC_GATE_PIN_DISABLE:-0}" != "1" ]; then
    hop_rd=$(rundir_of_run_id "$RUN_ID") \
      || die "the run id carries a path component: $RUN_ID"
    if [ ! -d "$hop_rd/settings" ] && [ ! -f "$hop_rd/plugin-pin" ]; then
      hop_tg=""
      for hop_al in $(target_aliases); do
        hop_tg="$hop_tg$(printf '%s\t%s' "$(target_field "$hop_al" '공통 git 디렉터리')" "$(target_field "$hop_al" '베이스 브랜치')")"$'\n'
      done
      pin_take "$hop_rd" "$(cd "$(dirname "$GATE_DIR")" && pwd -P)" "$hop_tg" \
        || die "version pin failed — no copy could be obtained that a concurrent checkout stampede had not torn"
    fi
    gate_hop_or_die "$hop_rd"
  fi

  rundir_init

  # THE DETACHED METRICS ROUND LEAVES HERE, before anything below writes. What
  # follows is the per-entry bookkeeping of a caller — the ledger handle, the
  # session index, lineage, the run-open block, lost-dispatch settlement and the
  # metrics hook itself — and a child started by another gate call is none of
  # those: settling dispatches from here would write `외부 종료` rows beside the
  # caller doing the same. The manifest, the grant and the run directory above
  # are what the round needs, and all of them have been checked by now.
  if [ "$verb" = "metrics-round" ]; then
    [ -n "$nonce" ] || { printf 'gate: metrics-round requires --nonce\n' >&2; exit 2; }
    if [ "$(cat "$(gate_metrics_lockdir)/nonce" 2>/dev/null || true)" != "$nonce" ]; then
      printf 'gate: metrics-round nonce mismatch — the lock does not carry this nonce, so nothing runs\n' >&2
      exit "$GATE_EXIT_RULE"
    fi
    gate_metrics_round "$nonce"
    exit 0
  fi
  # The halt-report round leaves at the same point for the same reasons.
  if [ "$verb" = "halt-report-round" ]; then
    [ -n "$nonce" ] || { printf 'gate: halt-report-round requires --nonce\n' >&2; exit 2; }
    if [ "$(cat "$(gate_halt_lockdir)/nonce" 2>/dev/null || true)" != "$nonce" ]; then
      printf 'gate: halt-report-round nonce mismatch — the lock does not carry this nonce, so nothing runs\n' >&2
      exit "$GATE_EXIT_RULE"
    fi
    gate_halt_round "$nonce"
    exit 0
  fi

  # THE GATE CHOOSES THE PATH. THE CALLER DOES NOT NAME ONE.
  #
  # This flag used to take a path, and four review cycles were spent on the
  # checks that made a caller-named path safe: confinement to the run
  # directory, then to a quarantine inside it, a basename pattern, a `..`
  # rejection, physical resolution of both sides, an ordering between the
  # creation guard and the physical test. Each round closed a hole and two of
  # them opened a new one — the anchor derived from the component it was
  # confining, and a `mkdir -p` that ran before the test that would refuse it.
  #
  # None of those checks buy anything, because no caller ever needed to choose.
  # The gate already knows the run directory and already knows the actor, so the
  # path is a value it can compute — and a value it computes is a value nobody
  # can point somewhere else. Removing the parameter removes the entire class,
  # rather than adding a seventh check to it.
  if [ "$emit_digest_seen" = "1" ]; then
    emit_digest_dir="$RUN_DIR/digest"
    mkdir -p "$emit_digest_dir" 2>/dev/null || true
    GATE_EMIT_DIGEST_TO=$(gate_digest_path)
  fi
  # THE RULE IS "EVERY PATH THAT APPENDS A ROW EMITS AFTER ITS LAST APPEND",
  # and an enumeration of exit points is the wrong shape for it — the first
  # enumeration missed four refusals that append a row and then exit, and a
  # caller reading no file there falls back to the round trip forever, which
  # looks exactly like the flag working and saving nothing. A trap states the
  # rule once and cannot fall behind a new exit.
  #
  # Emitting on a path that appended nothing is harmless: the value is the
  # current digest either way, and a caller holding a correct digest is the
  # point. `plan` is excluded because it is excluded by contract, not because
  # it happens to write no row.
  #
  # THE TRAP IS INSTALLED WHETHER OR NOT A DIGEST WAS ASKED FOR, because it
  # carries a second duty that does not depend on the flag: `gate_record_row`'s
  # segment arm holds `settings.lock` across its re-derivation and append, and
  # `gate_append` exits the process on a failed write. Without the trap that
  # exit would leave the lock directory behind and every later re-derivation
  # would time out on it. `gate_on_exit` releases the lock first and emits the
  # digest only when `GATE_EMIT_DIGEST_TO` was set above.
  case "$verb" in
    act|exec|admit) trap 'gate_on_exit' EXIT ;;
  esac

  # THE HANDLES A LATER READER NEEDS, written on EVERY entry rather than at run
  # open. A run that was cut and resumed still has to be findable, and the run
  # open block below runs once per run — putting these inside it would leave a
  # resumed run without the files that make it addressable.
  #
  # `ledger-path` exists because the ledger's location is derived from the
  # manifest's `origin-worktree`, and the things that need to read the ledger —
  # a status line, anything outside the driver — do not know the manifest. The
  # gate does. Idempotent overwrite.
  printf '%s\n' "$LEDGER" > "$RUN_DIR/ledger-path"

  # The FORWARD index: session id → run ids. `session-lineage` runs the other
  # way (run → its session ids) and answering "which run belongs to this
  # session?" from it means scanning every run directory. One session can hold
  # several runs, so this is a LIST — one run id per line, appended, deduped.
  # THIS PATH TAKES THE INDEX LOCK, and the paragraph that used to stand here
  # saying it deliberately did not is replaced rather than amended, because its
  # reasoning was load-bearing for a guarantee the other side could not keep.
  # It argued that a lost id SELF-HEALS on the session's next gate entry and
  # that the prune's compare-and-swap carried the hazard; the prune meanwhile
  # declared a lost append the one failure it was not allowed to have. Both
  # could not be true, and it was the prune's sentence that was wrong — its
  # comparison is re-read before the rename, so an append in that gap is
  # overwritten. Observed twice, one id of sixty each time — once under local
  # load and once on a CI runner with nothing else left in the job.
  #
  # The cost argument against locking does not survive either. The measurement
  # it cited is the call count, over 875 gate entries in the busiest run, and it
  # never priced the lock: an uncontended `mkdir` and `rmdir` is a fraction of a
  # millisecond, so the whole run pays well under a tenth of a second for it.
  #
  # A WRITER THAT CANNOT TAKE THE LOCK SKIPS ITS APPEND rather than forcing it.
  # Forcing would reinstate exactly the window the lock exists to close, with
  # the added harm of looking locked. Skipping is the self-healing the old
  # paragraph described — the append is unconditional, so this session's next
  # gate entry puts the id back — and that property is now a fallback for a
  # bounded wait instead of an excuse for a race.
  #
  # Entries for runs whose directory is gone stay put until a reap cycle removes
  # them: the reader filters with `[ -d ]`, and that filter is what makes an entry
  # outliving its directory harmless — which in turn is why the prune can run on a
  # sparse schedule instead of tracking every deletion.
  if [ -n "${CLAUDE_CODE_SESSION_ID:-}" ]; then
    mkdir -p "${XDG_STATE_HOME:-$HOME/.local/state}/cc-cmds/session"
    _idx="${XDG_STATE_HOME:-$HOME/.local/state}/cc-cmds/session/$CLAUDE_CODE_SESSION_ID"
    if gate_index_lock "$_idx"; then
      grep -qxF "$RUN_ID" "$_idx" 2>/dev/null \
        || printf '%s\n' "$RUN_ID" >> "$_idx"
      gate_index_unlock "$_idx"
    fi
    unset _idx
  fi

  # Lineage is recorded here rather than only where it is consumed. Its one
  # caller was `gate_transcript_files`, which is reached only by `close` — so a
  # run that never opened an approval had no lineage at all, and a `--resume`
  # across that gap left the earlier session id unrecorded for good.
  #
  # THE GUARD IS THE POINT, not a precaution. Lineage is what
  # `gate_transcript_files` searches to find the transcript an approval was
  # answered in, so every id in it is an id allowed to ANSWER. Promoting the
  # call to the entry point without this test would enrol every stage: stages
  # reach the gate too — the pre-tool hook routes each of their Bash, Write and
  # Edit through it — and each carries its own session id. The run's approvals
  # would then be answerable from inside the very stages they gate, which is the
  # self-approval path the separation exists to keep shut.
  #
  # `CC_PIPELINE_STAGE_ID` is exported to stage children by the driver and to
  # nothing else, so its presence is the router/stage distinction rather than a
  # heuristic.
  # AND NOT A SHIFT EITHER, WHICH THE STAGE TEST ALONE DOES NOT COVER. A router
  # shift IS a router, so it walks through this gate and gets enrolled — and an
  # enrolled session id is an id allowed to ANSWER, so `gate_close` would then
  # read the shift's own transcript as a person's reply. That is the
  # self-approval path the separation exists to keep shut, arriving through the
  # one door the guard was not watching. A person can answer only at the lead,
  # so the lead is the only seat lineage holds.
  #
  # `CC_PIPELINE_SHIFT_ID` is exported by `gate_launch_shift` and by nothing
  # else, so like the stage marker beside it this is a structural distinction
  # rather than a heuristic.
  #
  # THE WRITER IS A SEPARATE FUNCTION FROM THE READER, and that is what makes
  # this guard the whole door rather than one of several. While enrolment was a
  # side effect of reading, anything that read the lineage enrolled its caller
  # past this test — `gate_shift_state` reaches the reader from `snapshot`, so a
  # stage that took a snapshot put itself in the set of ids allowed to answer.
  [ -n "${CC_PIPELINE_STAGE_ID:-}" ] || [ -n "${CC_PIPELINE_SHIFT_ID:-}" ] \
    || gate_session_lineage_record

  # Run start is "the settings directory does not exist yet".
  #
  # THIS IS THE ONE CALL THAT RENDERS THE SETTINGS FROM THE PRELUDE, and it runs
  # once per run. The settings used to be RE-DERIVED here as well, on every
  # other entry, whenever what they derive from had moved — and what moves
  # during a run is the set of worktrees the ledger's `segment` rows name, since
  # kickoff happens BEFORE segmentation and a segment's own worktree is never in
  # the manifest. That re-derivation lives in `gate_record_row`'s `segment` arm
  # now, at the moment the row that names a new worktree is written, and the
  # record of the widening is a field ON THAT ROW (`인가면=<before>→<after>`)
  # rather than a `대상 추가` row appended by whichever call came next.
  #
  # Two things that form removed. The prelude re-derivation ran AFTER the
  # caller's snapshot digest had been taken and BEFORE the staleness check read
  # it, so on the call that widened, the gate invalidated its own caller's
  # digest — the ancestry window hides that only while the tip stays inside the
  # window. And the `대상 추가` row it appended reported a widening under the
  # series whose meaning is "a repository joined the run": every such row in the
  # local ledgers carried an empty alias, because the enrolment path that series
  # exists for has never fired. Moving the trigger past the staleness check
  # closes the first; putting the record on the segment row closes the second.
  #
  # BEFORE THE FIRST `segment` ROW the surface is exactly what this branch
  # renders: the declared targets' worktrees, the run directory, the document
  # directories and the plugin directory — zero segment worktrees. Kickoff, a
  # shift launch and a run that never segments all run on that set.
  #
  # The widening is bounded by construction: every directory the segment arm
  # can add is a worktree of a target the run already acts in — a row whose
  # path does not share a declared target's common git directory is REFUSED at
  # write time rather than silently dropped from the list. Nothing here grants a
  # cutpoint, and the cutpoint is what governs whatever leaves the machine.
  if [ ! -d "$(gate_settings_dir)" ]; then
    gate_write_settings
    # The baseline is written inside that call, so both halves have succeeded
    # by here and the key describes what is on disk.
    gate_settings_key_record
    # Run open is the one moment this belongs — the comment on `cred_check`
    # already says a run whose cutpoint reaches `머지` should learn at kickoff
    # and not at 3am, and until now nothing called it, so nothing ever did. It
    # warns and does not refuse: no host has provisioned these yet, and a stop
    # here would end every run before its first act. What it removes is the
    # silence, which is what made an unseparated run indistinguishable from a
    # separated one at every surface.
    if ! cred_check >/dev/null 2>&1; then
      warn "the pipeline credential is not in place — acts in this run use the ambient credential (it is recorded on every row in the \`자격\` field of the ledger)"
      cred_check >&2 || true
    fi
    # The `run` row, written once, here. It had no writer at all, so a ledger
    # opened without one carried no statement of what the run was — the report
    # path, the document and its digest, and the enforcement-surface baseline
    # all lived in memory or in a file beside the ledger rather than in it. This
    # is also the row that makes the chain's first anchor a row rather than the
    # stub's prose.
    # `강제 코드`, `베이스 추적 변경` and `베이스 미추적 파일` DESCRIBE THE
    # TARGET BASE, NOT THE JUDGE. They are the base's HEAD at kickoff and what
    # that worktree held beside it — a run opened on a base with uncommitted
    # changes to tracked files ran against code no review saw, and without these
    # the morning cannot tell that apart from a clean night. What enforced the
    # run is a different question and has its own answer now: `plugin-pin` and
    # the three version fields below. The surface digest still excludes the
    # plugin files on purpose — a redeploy that rewrites a rule must not kill a
    # running run — and pinning is what makes that exclusion cost nothing,
    # because the enforcing bytes no longer move.
    #
    # TWO FIELDS, NOT ONE, and the one they replace measured the wrong thing.
    # `git status --porcelain` lists untracked files too, and in this way of
    # working a new file lying beside the checkout is the normal state — so a
    # single "is the output empty" predicate answered "dirty" for a base whose
    # tracked files were byte-for-byte committed, and the morning could not tell
    # "code no review saw ran tonight" from "someone has a draft open". Split,
    # the first field carries the claim the old one was written for and the
    # second carries the ambient fact on its own. A `cd` or `git status` that
    # fails is `(미상)` on both, where the old expression read a failed probe as
    # an empty output and wrote "clean".
    #
    # `--no-optional-locks` ON THE PROBE, and this is a requirement rather than
    # a tidy-up. A plain `git status` rewrites the index and holds `index.lock`
    # for 0.24–0.47s; this probe runs inside the very call that takes the pin,
    # and the command it would lock out is `git pull --ff-only`, which is how
    # every slice of this design is applied.
    #
    # `베이스 검사 기준선` IS WHETHER THE BASE'S OWN `make check` COULD HAVE BEEN
    # GREEN AT KICKOFF, so a stage that meets a red check at 3am can tell a
    # failure it caused from one it inherited. Recorded, never refused on: a run
    # does not stop because the base was already red. See
    # `gate_base_check_baseline` for what is and is not measured, and
    # `gate_base_check_baseline_fit` for how the value gives way to the row cap.
    local rr_start rr_whole rr_surf rr_forced rr_tracked rr_untracked rr_check
    local rr_pin_commit rr_pin_tree rr_pin_digest rr_fixed
    rr_start=$(now_iso)
    rr_whole=$(whole_digest 2>/dev/null || printf '(해당 없음)')
    rr_surf=$(cat "$RUN_DIR/surface-digest" 2>/dev/null || printf '(미기록)')
    rr_forced=$( { cd "$BASE" 2>/dev/null && git --no-optional-locks rev-parse HEAD 2>/dev/null; } || printf '(미상)')
    read -r rr_tracked rr_untracked <<< "$(gate_base_tree_state "$BASE")"
    rr_check=$(gate_base_check_baseline "$BASE")
    rr_pin_commit=$(gate_pin_version_field commit)
    rr_pin_tree=$(gate_pin_version_field tree)
    rr_pin_digest=$(gate_pin_version_field digest)
    # The row as it would be with the baseline value empty — every other field
    # is measured exactly as written, and only the baseline gives way.
    rr_fixed=$(gate_row_projected_bytes 'run' "run-id=$RUN_ID" "시작=$rr_start" \
      "설계 문서=${DOC_KEY:-(없음)}" "전체 sha256=$rr_whole" \
      "구속면 다이제스트=$rr_surf" "강제 코드=$rr_forced" \
      "베이스 추적 변경=$rr_tracked" "베이스 미추적 파일=$rr_untracked" \
      "베이스 검사 기준선=" \
      "판본=$rr_pin_commit" "판본 트리=$rr_pin_tree" "판본 다이제스트=$rr_pin_digest" \
      "RUN_DIR=$RUN_DIR" "보고서=$LEDGER")
    rr_check=$(gate_base_check_baseline_fit "$rr_check" "$(( GATE_ROW_MAX - rr_fixed ))")
    gate_append 'run' "run-id=$RUN_ID" "시작=$rr_start" \
      "설계 문서=${DOC_KEY:-(없음)}" "전체 sha256=$rr_whole" \
      "구속면 다이제스트=$rr_surf" \
      "강제 코드=$rr_forced" \
      "베이스 추적 변경=$rr_tracked" \
      "베이스 미추적 파일=$rr_untracked" \
      "베이스 검사 기준선=$rr_check" \
      "판본=$rr_pin_commit" \
      "판본 트리=$rr_pin_tree" \
      "판본 다이제스트=$rr_pin_digest" \
      "RUN_DIR=$RUN_DIR" "보고서=$LEDGER"
    gate_record_design_tier
    # THE PERSONAL RULES SNAPSHOT, ONCE PER RUN. Every stage of this run gets
    # the same `# Personal rules` block, copied here from the seat's CLAUDE.md;
    # an edit of that file during the night reaches the next run, not tonight's
    # stages. A failed extract is a log line and a pointer, never a refusal:
    # the stages then run on the frozen v6 policy.
    gate_personal_rules_extract || true
    gate_personal_rules_lease_notice || true
    # The run's halt-report record, created only when absent. A run whose
    # record is missing is never reported, so a run opened before this existed
    # is outside the reporter's population by construction. `|| true` for the
    # reason the reap below has one.
    gate_halt_record_open || true
    # AFTER the `run` row, and only here. Before it, a reap that died would leave
    # the run without so much as its own opening row; and this is the one branch
    # that runs once per run rather than once per gate entry.
    #
    # `|| true` because reclamation is housekeeping, not the run's work. A run
    # must not fail to open because a directory somewhere else could not be
    # removed.
    gate_reap_cycle || true
    # The dashboard's server, once per run and from no seat but a non-stage
    # one — see `gate_dashboard_ensure`. Not re-checked during the run.
    gate_dashboard_ensure "$verb" || true
  fi

  # LOST DISPATCHES ARE SETTLED HERE, ON EVERY VERB BUT `plan`. The prelude is
  # already where every verb writes the `run` row; a lost dispatch (a record
  # that outlived its process) is settled in the same place
  # so that a blocked run whose only activity is `snapshot` reads, or a `wait`
  # that spends its whole turn inside one call, still gets the `외부 종료` row.
  # `plan` is excluded by CONTRACT — it is the verb that writes no row, and the
  # dry run's meaning stands on that — not because it happens to write none.
  #
  # BEFORE THE VERB BRANCH, so a `snapshot` cannot both list a segment as an
  # orphan and report it settled: settlement finishes and removes `.pid` first,
  # then `orphan_stages[]` is computed. `GATE_SETTLED_SEGMENTS` is the shell
  # variable `wait` reads as its fast path — the same process, so no file and
  # no cleanup, and it cannot go stale because it cannot outlive the call.
  # THE CONTEXT CAP STANDS ON `wait` TOO, AND AHEAD OF THE SETTLEMENT ABOVE IT —
  # that settlement writes rows, and a capped shift is to come back having
  # written none. Exempting `wait` would let a shift past the cap go on routing
  # for as long as the stage it watches runs, which on a long stage postpones
  # the cap by hours and is the cap's whole point undone. Waiting is not
  # ownership: the stage's supervisor is detached and writes the result and cost
  # rows itself, so the successor has only to wait on the same segment again.
  # `wait` carries no `--kind`, so nothing on this verb is exempt. The other
  # verbs meet the same predicate inside `gate_verb_act`, after the digest
  # comparison, where their own first writer is.
  if [ "$verb" = "wait" ]; then gate_cap_directive wait ''; fi

  GATE_SETTLED_SEGMENTS=""
  [ "$verb" = "plan" ] || gate_settle_lost_dispatches
  # The metrics round is started from the same prelude for the same reason and
  # is kept out of `plan` by the same contract; it is stamped, so almost every
  # call stops at one read. The call that meets an expired stamp pays for the
  # lock and the launch only — the round itself runs in a detached child — so
  # no verb waits for the collector. `|| true` as the reaper has it: whatever
  # the round runs into, it is not the verb's work. `digest-path` is kept out
  # too: the PreToolUse hook calls it before every tool call, and it has no
  # business paying even for the launch. The stamp is not touched, so the round
  # starts on the next verb that is not excluded.
  # The halt-report round is started from the same place under the same
  # exclusions, on its own stamp and lock.
  case "$verb" in
    plan|digest-path) ;;
    *) gate_metrics_cycle || true
       gate_halt_cycle || true ;;
  esac

  case "$verb" in
    digest-path)
      # Reading, not acting: it prints where an emission would land and writes
      # nothing. The hook calls this instead of rebuilding the path.
      gate_digest_path; printf '\n' ;;
    snapshot)
      if [ "$render" = "1" ]; then gate_render_snapshot
      elif [ "$fields_seen" = "1" ]; then gate_snapshot_fields "${fields:-$GATE_SNAPSHOT_FIELDS_DEFAULT}"
      else gate_snapshot; fi
      ;;
    grade)
      [ $# -ge 1 ] || { printf 'gate: grade needs an argv after --\n' >&2; exit 2; }
      local g
      g=$(surface_of_argv0 "$@")
      # The pacing guard answers here, because a write into the dispatcher's
      # directory has no grade a declaration could meet. A read
      # grade passes it, so naming the directory while reading still grades.
      if ! gate_pace_write_guard "$g" "$@"; then
        printf '축2=거부\n'
        exit "$GATE_EXIT_RULE"
      fi
      printf '축2=%s\n' "$g"
      # `[ … ] && exit` as the arm's last command hands the FALSE test's status
      # to the caller — a successful grade then exits 1 and reads as a refusal.
      #
      # The version-skew hint belongs here as much as on the acting path, and
      # arguably more: `grade` is what a caller runs to find out what to declare,
      # so this is where the answer "the table has no row for a script sitting
      # next to me" is cheapest to receive. The acting path reaches the same
      # helper through `gate_verb_act`; this arm never gets there, because it
      # calls the table directly and returns.
      if [ "$g" = "등급 미상" ]; then
        gate_orchestrator_script_hint "$1"
        exit "$GATE_EXIT_VOCAB"
      fi
      ;;
    plan|act|exec)
      gate_verb_act "$verb" "$kind" "$alias" "$segment" "$cutpoint" "$surface" \
                    "$snapdig" "$rationale" "$worktree" "$@"
      ;;
    admit)
      # THE BARE FORM. The bytes are the request the run hook recorded, never
      # an argument of this call, so what is graded is what will be issued.
      [ -n "$alias" ] || { printf 'gate: admit requires --target\n' >&2; exit 2; }
      gate_admit_load "$request"
      gate_admit_words
      gate_admit_wrapped_push_refuse
      # THE CELL IS DERIVED, not asked for: the table's rung, and `push` at
      # least for a git push, whose rung the table leaves to the act's own
      # destination check — which raises a base update to `머지` with exit 8.
      if [ -z "$cutpoint" ]; then
        cutpoint=$(ladder_of_argv0 "${GATE_ADMIT_WORDS[@]}" 2>/dev/null || true)
        [ -n "$cutpoint" ] || cutpoint="커밋"
        if gate_admit_words_push; then
          local _ci _pi
          _ci=$(cutpoint_index "$cutpoint" 2>/dev/null || printf 0)
          _pi=$(cutpoint_index push)
          [ "$_ci" -ge "$_pi" ] || cutpoint=push
        fi
      fi
      GATE_ADMIT=1
      gate_verb_act exec "" "$alias" "$segment" "$cutpoint" "$surface" \
                    "$snapdig" "$rationale" "" "${GATE_ADMIT_WORDS[@]}"
      ;;
    wait)
      [ "$segment" != "-" ] && [ -n "$segment" ] \
        || { printf 'gate: wait requires --segment\n' >&2; exit 2; }
      gate_verb_wait "$segment" "${wait_interval:-$GATE_WAIT_INTERVAL_DEFAULT}" \
                     "${wait_timeout:-$GATE_WAIT_TIMEOUT_DEFAULT}"
      ;;
    supervise-stage)
      [ -n "$alias" ] || { printf 'gate: supervise-stage requires --target\n' >&2; exit 2; }
      [ "$segment" != "-" ] && [ -n "$segment" ] \
        || { printf 'gate: supervise-stage requires --segment\n' >&2; exit 2; }
      [ -n "$nonce" ] || { printf 'gate: supervise-stage requires --nonce\n' >&2; exit 2; }
      [ $# -ge 1 ] || { printf 'gate: supervise-stage needs the stage kind and the CLI argv after --\n' >&2; exit 2; }
      gate_verb_supervise_stage "$alias" "$segment" "$nonce" "$@"
      ;;
    # `metrics-round` and `halt-report-round` never arrive here: they leave
    # right after `rundir_init`.
    close)
      [ -n "$approval" ] || { printf 'gate: close requires --approval\n' >&2; exit 2; }
      # The two refusing dispositions are different CLAIMS about the same
      # approval — one says the question should not have been asked, the other
      # that it was asked and the answer is no. Taking both would leave the
      # row's state decided by whichever branch runs first, so the pair is
      # refused rather than ranked.
      if [ "$void" = "1" ] && [ "$reject" = "1" ]; then
        printf 'gate: --void and --reject are different dispositions — choose one\n' >&2; exit 2
      fi
      gate_close "$approval" "$void" "$reject"
      ;;
    prompt)
      # Reading, not acting: it prints the canonical question and the gate's
      # menu for one approval and writes nothing.
      [ -n "$approval" ] || { printf 'gate: prompt requires --approval\n' >&2; exit 2; }
      gate_prompt "$approval"
      ;;
    carry-body)
      # Writing under the run directory and nowhere else: the body files of a
      # carry-over the routing shift then files as issues. No ledger row — the
      # issues and the `리뷰 이월` row are the acts, and both are rows.
      gate_carry_body "$segment"
      ;;
    residual-body)
      # The same shape for the one issue of a segment parked `리뷰 잔여`.
      gate_residual_body "$segment"
      ;;
    review-line)
      # Reading, not acting: the prompt of the segment's next review dispatch,
      # with the flags after `--` in it. No ledger row — the dispatch is the act.
      gate_review_line "$segment" "$@"
      ;;
    surface-screen)
      # Reading, not acting: the screening tool from beside this file, with the
      # same arguments and the same output, so a stage whose only Bash is the
      # gate reaches it. No ledger row — nothing is performed. Its exit status
      # passes through: 2 is a classifier that could not be loaded.
      local ss_rc=0
      bash "$GATE_DIR/enforcement-surface-screen.sh" ${ss_flags[@]+"${ss_flags[@]}"} -- "$@" || ss_rc=$?
      exit "$ss_rc"
      ;;
    seat-apply-preview)
      # Reading, not acting: the diff a seat apply of the record would commit,
      # built in an isolated object directory, and the question the seat asks.
      # No ledger row, no ref, no object in the common store.
      gate_seat_apply_preview "$sa_record" "$alias"
      ;;
    surface-provenance)
      # Reading, not acting: the merge-time provenance check of one segment's
      # enforcement surface, the one the merge act and the cone seed run. No
      # ledger row — the merge it precedes is the act.
      [ "$segment" != "-" ] && [ -n "$segment" ] \
        || { printf 'gate: surface-provenance requires --segment\n' >&2; exit 2; }
      gate_surface_provenance "$segment" "$alias"
      ;;
    binding-digest)
      # Reading, not acting: the driver's own `binding_digest` over the document
      # named after `--`, so a re-convergence stage takes its before and after
      # baselines with the same computation the plan admission compares. No
      # ledger row. The document is named rather than taken from the manifest
      # because a base-scope run re-converges a child document too.
      [ $# -eq 1 ] || { printf 'gate: binding-digest needs exactly one document path after --\n' >&2; exit 2; }
      { [ -f "$1" ] && [ -r "$1" ]; } \
        || { printf 'gate: binding-digest: 읽을 수 있는 파일이 아닙니다: %s\n' "$1" >&2; exit 2; }
      DOC="$1"
      binding_digest; printf '\n'
      ;;
    report-check)
      # Reading, not acting: the review stage's own check of the report it
      # wrote, before it ends. No ledger row, no edit to the report.
      [ -n "$report_arg" ] || { printf 'gate: report-check requires --report <absolute path>\n' >&2; exit 2; }
      gate_verb_report_check "$report_arg"
      ;;
    meta-merge)
      # Writing into the segment's repository and nowhere else: the merge
      # commit of a release-metadata resolution. No ledger row — the push and
      # the merge after it are the acts, and the merge act judges the commit.
      gate_meta_merge "$segment"
      ;;
    answers)
      # Reading, and the reader is a STAGE rather than the router: it picks up
      # what the person said in answer to the judgment it raised. With an id it
      # prints that answer, without one it lists the ids that have one.
      gate_answers "$approval"
      ;;
    end-overdue)
      # Writing: a run no verb reaches cannot meet the acting path's deadline
      # branch, so this is the one place its end row can come from.
      gate_verb_end_overdue
      ;;
    end-abandoned)
      # Writing, and the writer is the seat in the person's turn or a kickoff
      # taking over this run: the run did not end at any boundary, so no
      # acting path reaches an end row for it.
      gate_verb_end_abandoned "$end_cause" "$end_successor"
      ;;
    *)
      printf 'gate: unknown verb: %s\n' "$verb" >&2; exit 2 ;;
  esac
}

gate_answered_judgments_json() {
  # The judgments a person has ANSWERED and no stage has yet used.
  #
  # THE SNAPSHOT USED TO SHOW ONLY `대기`, and it carries no `절단점` either — so
  # a judgment that had been answered left the pending list and appeared nowhere
  # else. The answer was in the ledger, in the sidecar and in the approval's
  # state, and the run still could not move: the router's declared input is the
  # snapshot, and the snapshot had stopped mentioning it. That is the same
  # broken-consumer shape this whole change exists to close, one field later.
  #
  # WHAT THE ROUTER DOES WITH AN ELEMENT is decided by the router — the gate says
  # what is true, not what to run next. Each element is a RE-DISPATCH CANDIDATE
  # for the stage that emitted the judgment, which is why `segment` is on it;
  # without that field the router would know an answer exists and not know whom
  # to hand it to.
  #
  # THE SPENT TEST REUSES THE PREDICATE THAT ALREADY EXISTS. A `자율 승인` row
  # naming `해소 승인=<id>` is what "this answer opened an adoption" already
  # means in two other places. A second bookkeeping of consumption would be a
  # second floor, and two floors disagree.
  #
  # `막는 세그먼트` IS READ OFF THE ISSUING ROW, not the last one. The rows that
  # close an approval carry the question and the answer and no segment, so a
  # `tail -1` — which is right for state — yields an empty segment here. The
  # narrowing to `절단점=판단` picks the issuing row for both duties at once.
  local ids id row st iss seg disp first=1
  # Pinned for the same reason as `gate_pending_approvals_json` above, and the
  # note there about `sort -u` applies here unchanged: the order is decided by
  # `LC_COLLATE`, which the driver has already fixed to C, and `LC_CTYPE` does
  # not enter into it. This function emits INTO the snapshot object too, so a
  # `tr`/`sed` that dies on an invalid byte does not merely lose this array — it
  # truncates the JSON at that point and every field after it, `chain_intact`
  # included, never reaches the reader. The ledger a reader most needs a verdict
  # about is precisely the malformed one.
  local LC_CTYPE=C; export LC_CTYPE
  local GATE_ROWS_MEMO_LEDGER GATE_ROWS_MEMO_N GATE_ROWS_MEMO_KINDS GATE_ROWS_MEMO_ROWS
  gate_ledger_warm '승인' '자율 승인'
  # ALL THREE LOOKUPS ARE WHOLE FIELDS — `| 승인 id=<id> |`, `| 절단점=판단 |`
  # and `| 해소 승인=<id> |` — the way every other reader of these series is.
  # A judgment that cites another's id in its `기준` carries that text into its
  # own issue and close rows, and read as a substring those rows spoke for the
  # cited id: a refused judgment came out as an answered candidate behind the
  # citing judgment's `승인`, and an answered one vanished behind a citing
  # judgment's `거부`.
  ids=$(gate_rows '승인' \
        | tr '|' '\n' | sed -n 's/^ *승인 id=//p' | sed 's/[[:space:]]*$//' | sort -u)
  for id in $ids; do
    [ -n "$id" ] || continue
    row=$( { gate_rows '승인' | grep -F "| 승인 id=$id |" || true; } | tail -1)
    st=$(gate_row_field "$row" '상태')
    case "$st" in 승인|거부|무효) ;; *) continue ;; esac
    iss=$( { gate_rows '승인' | grep -F "| 승인 id=$id |" || true; } \
           | { grep -F '| 절단점=판단 |' || true; } | tail -1)
    [ -n "$iss" ] || continue
    # A REFUSAL IS AN ANSWER HERE ONLY FOR THE PERSON SET (`사람-결정`,
    # `시각-승인`). Those classes' `거부` and `무효` are what the router parks the
    # segment on, so they are candidates until the parking resubmission spends
    # them — the same `해소 승인=<id>` test below, which is why `state` travels
    # on the element: the router must not read a refusal as a recommendation to
    # carry out. Every other class's refusal stays a closed question nobody acts
    # on, and is left out as before.
    if [ "$st" != "승인" ] && ! judgment_class_person "$(gate_row_field "$iss" '판단 부류')"; then
      continue
    fi
    if gate_has_row '자율 승인' "| 해소 승인=$id |"; then continue; fi
    seg=$(gate_row_field "$iss" '막는 세그먼트')
    # `disposition` IS THE LAST ROW'S `처분 사유`, `-` when it has none. It is
    # what tells a `사람-결정` answered by a menu label (`-`: carry out the
    # recommendation) from one answered in the person's own words
    # (`자유 입력`: carry out what the answer file says) — both close `승인`,
    # so `state` alone sent the router to the recommendation either way.
    disp=$(gate_row_field "$row" '처분 사유')
    [ "$first" = "1" ] || printf ',\n'
    first=0
    # A MISSING SIDECAR IS REPORTED AS `null`, NOT AS A MISSING ELEMENT. The
    # path was emitted unconditionally, so a run whose `$RUN_DIR` had been
    # collected handed the router a path to a file that is not there — and the
    # obvious repair, dropping the element, is worse: an element that vanishes
    # is indistinguishable from one a stage consumed, which is the state the
    # spent test above is the sole owner of. `null` keeps the candidate visible
    # and says the bytes are gone, and the ledger's `답변 문면` still holds the
    # clipped copy.
    if [ -f "$RUN_DIR/answer/$id.md" ]; then
      printf '    {"id": "%s", "segment": "%s", "state": "%s", "disposition": "%s", "answer": "%s"}' \
        "$(gate_json_escape "$id")" \
        "$(gate_json_escape "${seg:--}")" \
        "$(gate_json_escape "$st")" \
        "$(gate_json_escape "${disp:--}")" \
        "$(gate_json_escape "$RUN_DIR/answer/$id.md")"
    else
      printf '    {"id": "%s", "segment": "%s", "state": "%s", "disposition": "%s", "answer": null}' \
        "$(gate_json_escape "$id")" \
        "$(gate_json_escape "${seg:--}")" \
        "$(gate_json_escape "$st")" \
        "$(gate_json_escape "${disp:--}")"
    fi
  done
  [ "$first" = "1" ] || printf '\n'
}

gate_shift_halts_json() {
  # One element per segment a routing shift stopped that no answer has reached
  # yet: each cone row `shift-halt` wrote whose record no `중단 답` row names,
  # and each cone row a shift wrote when the gate could not write the record
  # (`사유=교대 정지 기록 불가 — <자리>`), which no answer can reach and which
  # therefore holds for the rest of the run. `보류` is the cone's members now,
  # the anchor left out. A segment that has ended is left out.
  #
  # THIS IS THE HOLD A LATER SHIFT READS. The gate does not refuse acts on such
  # a cone, and the shift that wrote it hands over with no memory its successor
  # shares. Without this array the next shift saw the segment as routable,
  # sent the same merge again and wrote a second record of the same question.
  #
  # The answered test is one awk pass that reads to the end, not `grep -q` on
  # the right of a pipe, for the SIGPIPE reason `gate_answered_halts_json`
  # gives.
  local first=1 r ln row seg rec site why held m
  while IFS= read -r r; do
    [ -n "$r" ] || continue
    ln=${r%%:*}; row=${r#*:}
    [ "$(gate_row_field "$row" '스코프')" = "cone" ] || continue
    seg=$(gate_row_field "$row" '앵커 세그먼트')
    [ -n "$seg" ] || continue
    rec=$(gate_row_field "$row" '중단 기록')
    if [ -n "$rec" ]; then
      [ "$(gate_shift_halt_row_of "$rec" | cut -d: -f1)" = "$ln" ] || continue
      site=$(gate_row_field "$row" '자리')
      LC_ALL=C awk -v r="| 중단 기록=$rec |" '
        index($0, "- `중단 답` ") == 1 && index($0, r) { f = 1 }
        END { exit !f }' "$LEDGER" 2>/dev/null && continue
    else
      why=$(gate_row_field "$row" '사유')
      case "$why" in
        '교대 정지 기록 불가 — '*) site=${why#'교대 정지 기록 불가 — '} ;;
        *) continue ;;
      esac
    fi
    gate_segment_terminal "$seg" && continue
    held=''
    for m in $(GATE_CONE_MEMBERS_ONLY=1 gate_cone_members "$seg"); do
      [ "$m" = "$seg" ] && continue
      held="$held${held:+, }\"$(gate_json_escape "$m")\""
    done
    [ "$first" = "1" ] || printf ',\n'
    first=0
    printf '    {"세그먼트": "%s", "자리": "%s", "기록": "%s", "줄": %s, "보류": [%s]}' \
      "$(gate_json_escape "$seg")" "$(gate_json_escape "$site")" \
      "$(gate_json_escape "$rec")" "$ln" "$held"
  done <<EOF
$( { grep -n "^- \`blocked\` " "${LEDGER:-/dev/null}" 2>/dev/null || true; } )
EOF
  [ "$first" = "1" ] || printf '\n'
}

gate_answered_halts_json() {
  # The halt records a person has ANSWERED at the seat (`중단 답` rows) that no
  # stage has yet taken up.
  #
  # SPENT BY THE NEXT `stage-result` OF THE SAME KEY, on a later ledger line.
  # The shift hands the answer on by re-attaching the halted session or by
  # dispatching the next stage on that key, and either one lands a
  # `stage-result` row for the key when it ends. An answer read twice would
  # re-attach the same session with the same answer twice; an answer that
  # stayed visible after it was used would do exactly that. An answer to a
  # shift's halt record is spent by the next shift carrying its option out as
  # well (`gate_halt_answer_consumer`), and an answer `세그먼트 park` by the
  # later `상태=park` row of that segment, since parking dispatches nothing.
  #
  # A ROW THAT SETTLES AN ATTEMPT WHICH NEVER SPAWNED does not spend the answer:
  # its `관측` starts `스폰 전 대기 중`, and no stage read the answer.
  #
  # ONE ELEMENT PER KEY, THE LAST ROW. A person who answers the same halt again
  # has changed their mind, and the later answer is the one to hand on.
  local LC_CTYPE=C; export LC_CTYPE
  # Every reader below consumes its whole input — no `exit` in awk, no `head` —
  # because an early-exiting reader kills the writer with SIGPIPE and, under
  # `pipefail`, the pipeline then fails though the match was found.
  local lines ln row key keys first=1
  lines=$(grep -n "^- \`중단 답\` " "$LEDGER" 2>/dev/null || true)
  [ -n "$lines" ] || return 0
  keys=$(printf '%s\n' "$lines" | while IFS= read -r row; do
           gate_row_field "${row#*:}" '세그먼트'
         done | awk 'NF && !seen[$0]++')
  for key in $keys; do
    row=$( { printf '%s\n' "$lines" | grep -F "| 세그먼트=$key |" || true; } | tail -1)
    [ -n "$row" ] || continue
    ln=${row%%:*}
    row=${row#*:}
    if gate_halt_answer_spent "$LEDGER" "$key" "$ln"; then continue; fi
    [ "$first" = "1" ] || printf ',\n'
    first=0
    # `attachment` is the empty string when the seat attached nothing. The
    # person's `근거` is not copied here: the shift points the stage at the row's
    # ledger line, which holds it whole as recorded. `origin_run` is the empty
    # string for an answer given in this run, and the earlier run's id for one
    # brought over from it: by the adopted segment's planning act
    # (`gate_adoption_halt_carry`) — a binding-tier stop's `재수렴`, or an answer
    # the earlier ledger names in an `이월` row — or by a re-kickoff's first
    # dispatch of a run-scope step (`gate_chain_halt_import`), an `이월` answer
    # only. An `이월` answer goes on through the carry act; whether the earlier
    # ledger holds that row is read from `출처 런`, not from this element.
    # `answered_by` is `사람`, `좌석` or `교대` (`gate_halt_answered_by`), so the
    # shift's re-attach message can say who chose the option. `state` is `이월`
    # when an `이월` row of this run names the line — a carry found no room
    # before the deadline and the next run takes the answer up, so this run does
    # not carry it again — and `열림` otherwise. `route` is the
    # route id `gate_halt_answer_route` gives the answer now and
    # `route_refusal` its reason when it gives none — the same verdict
    # `halt-answer` gave when it recorded the row, read again because the
    # ledger has moved since; the shift maps `route` to its item and hands a
    # refused one back to a person. Both are empty when the record file is
    # gone, since there is nothing to read the branch from. Neither enters the
    # digest H or the default `--fields` projection.
    local rrec rby rroute='' rwhy=''
    rrec=$(gate_row_field "$row" '중단 기록')
    rby=$(gate_halt_answered_by "$row")
    if [ -f "$rrec" ]; then
      if gate_halt_answer_route "$key" "$rrec" "$(gate_row_field "$row" '선택지')" "$rby" >/dev/null 2>&1; then
        rroute=$GATE_HALT_ROUTE_ID
      else
        rwhy=$GATE_HALT_ROUTE_REASON
      fi
    fi
    printf '    {"segment": "%s", "record": "%s", "skill": "%s", "option": "%s", "answered_by": "%s", "attachment": "%s", "origin_run": "%s", "route": "%s", "route_refusal": "%s", "line": %s, "state": "%s"}' \
      "$(gate_json_escape "$key")" \
      "$(gate_json_escape "$rrec")" \
      "$(gate_json_escape "$(gate_row_field "$row" '스킬')")" \
      "$(gate_json_escape "$(gate_row_field "$row" '선택지')")" \
      "$(gate_json_escape "$rby")" \
      "$(gate_json_escape "$(gate_row_field "$row" '첨부')")" \
      "$(gate_json_escape "$(gate_row_field "$row" '출처 런')")" \
      "$(gate_json_escape "$rroute")" \
      "$(gate_json_escape "$rwhy")" \
      "$ln" \
      "$(if gate_halt_answer_deferred "$LEDGER" "$ln"; then printf '이월'; else printf '열림'; fi)"
  done
  [ "$first" = "1" ] || printf '\n'
}

gate_returned_halts_json() {
  # The snapshot's `returned_halts[]`: the halt records whose answer a shift
  # could not carry out and returned to a person with a routing block, which
  # the gate stamped with the answer's line (`막힌 답 줄`). One element per
  # record, while `cc_halt_returned` holds — a person's new `중단 답` ends it.
  #
  # `option` and `answered_by` are the returned answer's, so the seat can say
  # which choice came back from whom; `reason` is the block's `사유` after the
  # record name; `answer_line` the answer's ledger line and `line` the block's.
  # Not in the digest H, nor in the default `--fields` projection.
  local LC_CTYPE=C; export LC_CTYPE
  local r bl brow aln arow rec last first=1 why
  while IFS= read -r r; do
    [ -n "$r" ] || continue
    bl=${r%%:*}; brow=${r#*:}
    [ "$(gate_row_field "$brow" '스코프')" = "cone" ] || continue
    [ "$(gate_row_field "$brow" '원인')" = "막힘" ] || continue
    aln=$(gate_row_field "$brow" '막힌 답 줄')
    case "$aln" in ''|*[!0-9]*) continue ;; esac
    arow=$(sed -n "${aln}p" "$LEDGER" 2>/dev/null)
    case "$arow" in "- \`중단 답\` "*) ;; *) continue ;; esac
    rec=$(gate_row_field "$arow" '중단 기록')
    last=$( { grep -n "^- \`중단 답\` " "$LEDGER" 2>/dev/null || true; } \
            | { grep -F "| 중단 기록=$rec |" || true; } | tail -1)
    [ "${last%%:*}" = "$aln" ] || continue
    gate_halt_record_returned "$rec" || continue
    why=$(gate_row_field "$brow" '사유')
    why=${why#'중단 답 라우팅 — '}
    why=${why#* — }
    [ "$first" = "1" ] || printf ',\n'
    first=0
    printf '    {"segment": "%s", "record": "%s", "option": "%s", "answered_by": "%s", "answer_line": %s, "reason": "%s", "line": %s}' \
      "$(gate_json_escape "$(gate_row_field "$arow" '세그먼트')")" \
      "$(gate_json_escape "$rec")" \
      "$(gate_json_escape "$(gate_row_field "$arow" '선택지')")" \
      "$(gate_json_escape "$(gate_halt_answered_by "$arow")")" \
      "$aln" \
      "$(gate_json_escape "$why")" \
      "$bl"
  done <<EOF
$( { grep -n "^- \`blocked\` " "${LEDGER:-/dev/null}" 2>/dev/null || true; } | { grep -F '| 막힌 답 줄=' || true; } )
EOF
  [ "$first" = "1" ] || printf '\n'
}

gate_halt_answer_spent() {
  # gate_halt_answer_spent <ledger> <key> <line> — true when a `stage-result`
  # row of that key lands on a later line of that ledger than the `중단 답` row
  # at <line>: the stage the shift dispatched with the answer has taken it.
  #
  # ONE DEFINITION FOR BOTH LEDGERS IT IS ASKED OF. The snapshot asks it of
  # this run's ledger to decide what `answered_halts[]` still lists, and the
  # adopted segment's planning act asks it of the earlier run's ledger to decide
  # whether an answer given there is still open. Two spellings of "taken up"
  # would let an answer the earlier run already handed on be handed on again
  # here.
  #
  # A row settling an attempt that never spawned (`관측=스폰 전 대기 중 …`) does
  # not count: no stage read the answer.
  #
  # The reader consumes its whole input, for the SIGPIPE reason
  # `gate_answered_halts_json` gives.
  [ -n "$(gate_halt_answer_consumer "$1" "$2" "$3")" ]
}

gate_halt_answer_consumer() {
  # gate_halt_answer_consumer <ledger> <key> <line> — the `stage-result` row that
  # took up the `중단 답` row at <line>, as `<line>:<row>`, or nothing. It is the
  # one `gate_halt_answer_spent` tests for, so "spent" and "spent by whom" can
  # never name two different rows: the automatic-answer checks read its `종류`
  # and `종단 부류` to tell a re-convergence that ran from an attempt that
  # crashed before doing anything with the answer.
  #
  # A SHIFT'S HALT RECORD IS TAKEN UP BY THE NEXT SHIFT, not by a stage. The
  # answer to one names a site table option the next shift carries out itself
  # — a retry dispatches or acts on the segment, `세그먼트 park` writes its
  # segment row — so the first of these on a later line spends it as well: a
  # `stage-result` of the key, a `segment` row of the key, an act a shift took
  # on the key, or a resolution of a block anchored on it. Whichever comes
  # first is the consumer. A termination clause's evidence request
  # (`clause-<id>`) has no segment to act on: the shift carries its answer out
  # by writing that clause's `종료 절` row, or by asking again on the same key
  # when the attachment falls short, so either of those spends it too.
  #
  # AN ANSWER `세그먼트 park` TO A STAGE'S RECORD IS TAKEN UP BY THE PARK. The
  # shift carries it out by writing the segment's `상태=park` row and dispatches
  # nothing, so no `stage-result` would ever spend it; the first such `segment`
  # row of the key on a later line is a candidate beside the `stage-result` one,
  # and the earlier of the two is the consumer. An answer `보류` to a
  # `Step 3 강제 표면 좌석 적용` record is carried out the same way (route
  # `적용-보류`) and spent the same way. Every other option is spent the way it
  # was.
  #
  # AN ATTEMPT THAT CARRIED THE ANSWER AND DIED BEFORE ITS SESSION does not take
  # it up either: its row carries `답 운반` and `세션 id=미상`, the card was never
  # read, and the answer is still the one to carry. The two filters below are
  # `gate_row_is_pre_session_death` spelled for a line-numbered stream, so the
  # routing that reads the key's last row sees the same rows passed over.
  local sr st pk arow aopt
  arow=$(sed -n "${3}p" "$1" 2>/dev/null)
  aopt=$(gate_row_field "$arow" '선택지')
  if [ "$aopt" = '보류' ] \
     && [ "$(gate_row_field "$arow" '스킬')" = 'implement-unattended' ]; then
    case "$(sed -n 's/^\*\*스텝\*\*: //p' "$(gate_row_field "$arow" '중단 기록')" 2>/dev/null | sed -n '1p')" in
      'Step 3 강제 표면 좌석 적용'*) aopt='세그먼트 park' ;;
    esac
  fi
  sr=$( { grep -n -F -e "세그먼트=$2 " -e "세그먼트=- | 스테이지=$2 | 종류=" "$1" 2>/dev/null || true; } \
    | { grep "^[0-9]*:- \`stage-result\` " || true; } \
    | { grep -vF '| 관측=스폰 전 대기 중' || true; } \
    | awk -F: -v l="$3" '$1 > l && !p && !(index($0, "| 세션 id=미상 |") && index($0, "| 답 운반=")) { print; p = 1 }')
  if [ "$1" = "${LEDGER:-}" ] \
     && [ -n "$(gate_shift_halt_row_of "$(gate_row_field "$(sed -n "${3}p" "$1" 2>/dev/null)" '중단 기록')")" ]; then
    st=$(LC_ALL=C awk -v l="$3" -v k="$2" '
      NR > l && !p {
        if ((index($0, "- `segment` ") == 1 && index($0, "| id=" k " |")) \
            || ((index($0, "- `자율 승인` ") == 1 || index($0, "- `승인` ") == 1) \
                && index($0, "| 세그먼트=" k " |") && index($0, "| 결정=act |") \
                && index($0, "| 행위자=교대 |")) \
            || (index($0, "- `blocked` ") == 1 && index($0, "| 앵커 세그먼트=" k " |") \
                && index($0, "| 원인=해소 |")) \
            || (cid != "" && index($0, "- `종료 절` ") == 1 && index($0, "| id=" cid " |")) \
            || (cid != "" && index($0, "- `blocked` ") == 1 && index($0, "| 앵커 세그먼트=" k " |") \
                && index($0, "| 중단 기록="))) { print NR ":" $0; p = 1 }
      }' cid="$(gate_clause_key_id "$2" 2>/dev/null || true)" "$1" 2>/dev/null)
    if [ -n "$st" ] && { [ -z "$sr" ] || [ "${st%%:*}" -lt "${sr%%:*}" ]; }; then
      sr=$st
    fi
  fi
  # AN ANSWER A ROUTING BLOCK RETURNED IS TAKEN UP BY THAT BLOCK. The shift
  # could not carry it out and handed the record back to a person; the gate
  # stamped the block with this answer's line. Read on every ledger this is
  # asked of — the earlier run's too, through the adoption carry — so an
  # answer returned there is not carried into this run as an open one.
  local bk
  bk=$(LC_ALL=C awk -v l="$3" '
    NR > l && !p && index($0, "- `blocked` ") == 1 && index($0, "| 스코프=cone |") \
      && index($0, "| 원인=막힘 |") && index($0, "| 막힌 답 줄=" l " |") { print NR ":" $0; p = 1 }' "$1" 2>/dev/null)
  if [ -n "$bk" ] && { [ -z "$sr" ] || [ "${bk%%:*}" -lt "${sr%%:*}" ]; }; then
    sr=$bk
  fi
  if [ "$aopt" = '세그먼트 park' ]; then
    pk=$(LC_ALL=C awk -v l="$3" -v k="$2" '
      NR > l && !p && index($0, "- `segment` ") == 1 && index($0, "| id=" k " |") \
        && index($0, "| 상태=park |") { print NR ":" $0; p = 1 }' "$1" 2>/dev/null)
    if [ -n "$pk" ] && { [ -z "$sr" ] || [ "${pk%%:*}" -lt "${sr%%:*}" ]; }; then
      sr=$pk
    fi
  fi
  [ -z "$sr" ] || printf '%s\n' "$sr"
}

gate_open_answer_line_of() {
  # gate_open_answer_line_of <key> <record file name> — the ledger line of the
  # key's open answer (the element `answered_halts[]` lists for it) when that
  # answer names a record of this file name, or nothing.
  local key="$1" name="$2" row ln
  row=$( { grep -n "^- \`중단 답\` " "$LEDGER" 2>/dev/null || true; } \
         | { grep -F "| 세그먼트=$key |" || true; } | tail -1)
  [ -n "$row" ] || return 0
  ln=${row%%:*}
  gate_halt_answer_spent "$LEDGER" "$key" "$ln" && return 0
  row=$(gate_row_field "${row#*:}" '중단 기록')
  [ "${row##*/}" = "$name" ] || return 0
  printf '%s' "$ln"
}

gate_halt_answer_is_auto() {
  # gate_halt_answer_is_auto <row> — true for a `중단 답` row no person wrote:
  # `답한 주체` is `교대` or `좌석`, or — on a row written before that field
  # existed — `근거` opens with the shift's pre-adopted prefix.
  case "$(gate_row_field "$1" '답한 주체')" in
    교대|좌석) return 0 ;;
    '') ;;
    *) return 1 ;;
  esac
  case "$(gate_row_field "$1" '근거')" in
    '자동 채택(구속-이탈) — '*) return 0 ;;
  esac
  return 1
}

gate_halt_answered_by() {
  # gate_halt_answered_by <row> — `사람`, `좌석` or `교대`. A row written before
  # `답한 주체` existed reads `교대` when it carries the shift's prefix and
  # `사람` otherwise, since those were the only two writers then.
  local by
  by=$(gate_row_field "$1" '답한 주체')
  if [ -z "$by" ]; then
    if gate_halt_answer_is_auto "$1"; then by=교대; else by=사람; fi
  fi
  printf '%s' "$by"
}

gate_halt_recommendation() {
  # gate_halt_recommendation <record> — whether the seat may answer this halt
  # record without a person, and with what. On success GATE_HALT_REC_LABEL holds
  # the recommended option's label and GATE_HALT_REC_KINDS the `/`-joined
  # 근거 kinds the record names (`미상` when it names none of the four); on
  # failure the reason is warned and the exit is GATE_EXIT_RULE.
  #
  # THE SEAT NEVER PICKS AN OPTION. The stage that wrote the record already
  # chose one where it stood, and the seat copies that choice, so what the run
  # answered unattended is decided by bytes a fixture can hold — not by a model
  # reading the record at night.
  #
  # `**추천**` IS FOUND AT THE START OF A LINE. The option check is a substring
  # match, so it would also find a label quoted inside `**추천 근거**`; a
  # recommendation is one line of its own or it is none.
  #
  # A RISK-ACCEPTANCE OPTION IS NOT THE SEAT'S TO TAKE. `judgment-grade.md`
  # grade 2 names four shapes of a person accepting risk that is theirs, and
  # risk acceptance is never delegated, so a recommendation whose description
  # carries one of them goes to a person however the record's writer argued it.
  local rec="$1" cls step n line lab ol desc='' found='' kinds
  GATE_HALT_REC_LABEL=''; GATE_HALT_REC_KINDS=''
  cls=$(sed -n 's/^\*\*분류\*\*: //p' "$rec" | sed -n '1p' | sed 's/[[:space:]]*$//')
  if [ "$cls" != "gate-unanswerable" ]; then
    warn "the seat answers only a \`gate-unanswerable\` halt record without a person — this one is ${cls:-unclassified}: $rec"
    return "$GATE_EXIT_RULE"
  fi
  if [ -z "$(gate_halt_option_lines "$rec")" ]; then
    warn "the halt record has no option line in its \`**선택지**:\` block, so there is nothing for the seat to answer: $rec"
    return "$GATE_EXIT_RULE"
  fi
  step=$(sed -n 's/^\*\*스텝\*\*: //p' "$rec" | sed -n '1p')
  case "$step" in
    'Step 3 잔여 검증 좌석 실행'*|'Step 3 게이트 도달 좌석 실행'*)
      warn "a \`좌석 실행\` halt is run by the seat, not answered from a recommendation: $rec"
      return "$GATE_EXIT_RULE" ;;
    # A seat apply commits files a person has to see first, so it is never a
    # recommendation's: the seat answers it only by inheriting a person's
    # earlier answer, which is the seat-apply branch's and not this one.
    'Step 3 강제 표면 좌석 적용'*)
      warn "a \`Step 3 강제 표면 좌석 적용\` halt is answered by a person or inherited from one, never from a recommendation: $rec"
      return "$GATE_EXIT_RULE" ;;
  esac
  n=$(grep -c '^\*\*추천\*\*: ' "$rec" || true)
  if [ "$n" != "1" ]; then
    warn "the seat answers only a halt record with exactly one \`**추천**\` line at the start of a line — this one has ${n:-0}: $rec"
    return "$GATE_EXIT_RULE"
  fi
  line=$(sed -n 's/^\*\*추천\*\*: //p' "$rec")
  case "$line" in
    '`'*'`'*) ;;
    *) warn "the record recommends no option (\`**추천**: ${line%% — *}\`), so a person answers it: $rec"
       return "$GATE_EXIT_RULE" ;;
  esac
  lab=${line#\`}
  lab=${lab%%\`*}
  while IFS= read -r ol; do
    case "$ol" in
      "- \`$lab\` — "*) desc=${ol#"- \`$lab\` — "}; found=1; break ;;
      "- \`$lab\`") found=1; break ;;
    esac
  done <<EOF
$(gate_halt_option_lines "$rec")
EOF
  # THE OLD SEAT-RUN PATH IS SCREENED HERE. A record with no `좌석 실행` step
  # whose first option spells a command is run by the seat and answered with
  # that option's label, and that answer comes down this path, not the
  # `좌석 실행` branch — so the option line gets the same token screen.
  if [ -n "$found" ]; then
    gate_halt_surface_tokens "$ol" "the recommended option \`$lab\`" "$rec" || return "$?"
  fi
  if [ -z "$lab" ] || [ -z "$found" ]; then
    warn "\`**추천**\` names \`$lab\`, which is not one of this halt record's option labels byte for byte: $rec"
    return "$GATE_EXIT_RULE"
  fi
  case "$desc" in
    *'위험 수용'*|*'게이트 비활성'*|*'그대로 진행'*|*'범위 축소'*)
      warn "the recommended option \`$lab\` is described as accepting risk (위험 수용 · 게이트 비활성 · 그대로 진행 · 범위 축소), which only a person accepts: $rec"
      return "$GATE_EXIT_RULE" ;;
  esac
  kinds=$(sed -n 's/^\*\*추천 근거\*\*: //p' "$rec" | sed -n '1p' | LC_ALL=C awk 'BEGIN { FS = " / " }
    { for (i = 1; i <= NF; i++) { k = $i; sub(/^ +/, "", k); sub(/:.*/, "", k)
        if ((k == "인터뷰 기록" || k == "매니페스트 인가" || k == "기기 사실" || k == "상시 지침") && !s[k]++)
          o = o (o == "" ? "" : "/") k } }
    END { print o }')
  GATE_HALT_REC_LABEL=$lab
  GATE_HALT_REC_KINDS=${kinds:-미상}
}

gate_halt_option_lines() {
  # gate_halt_option_lines <record> — the option lines of a halt record, verbatim:
  # the lines of its `**선택지**:` block — from that line to the next line that
  # starts with `**`, or the closing fence — that read `` - `<label>` `` alone or
  # followed by ` — <description>`.
  #
  # INSIDE THE BLOCK, BECAUSE OTHER LINES SHARE THE SHAPE'S HEAD. A command line
  # of a command halt starts with ``- ` `` too, and so can a line quoted into
  # the question, so a check that scanned the whole record for ``- `<label>` ``
  # found an option in a line nobody offered as one. Every reader of a record's
  # options — the option check of `halt-answer`, the recommendation, the
  # routable labels and the seat-apply frame check — reads them here.
  LC_ALL=C awk '
    $0 == "<!-- /cc-pipeline-halt v1 -->" { exit }
    inb && /^\*\*/ { inb = 0 }
    /^\*\*선택지\*\*:[ \t]*$/ { inb = 1; next }
    inb && /^- `[^`]+`$/ { print; next }
    inb && /^- `[^`]+` — / { print }
  ' "$1" 2>/dev/null || true
}

gate_halt_option_labels() {
  # gate_halt_option_labels <record> — the labels of `gate_halt_option_lines`,
  # one per line.
  gate_halt_option_lines "$1" | LC_ALL=C awk '{ l = substr($0, 4); sub(/`.*/, "", l); print l }'
}

gate_halt_surface_tokens() {
  # gate_halt_surface_tokens <line> <what> <record> — 0 when no token of the
  # line is an enforcement surface; otherwise warns, naming the tokens, and
  # returns GATE_EXIT_RULE. A classifier that could not be loaded refuses too:
  # "cannot judge" is never "no surface".
  #
  # A COMMAND THE SEAT RUNS NAMES NO ENFORCEMENT SURFACE. The seat runs what a
  # record lists without a person, and a `cp` onto a rule file or a CLAUDE.md
  # run that way commits nothing a review sees and nothing a person approved.
  # Such an edit has its own halt, `Step 3 강제 표면 좌석 적용`, which a person
  # answers. Backticks are blanked first, so a command quoted in a record is
  # read as the words it is made of. A string check, as the classifier says:
  # a script whose body writes a surface passes, and the merge's provenance
  # check is what closes that.
  local out rc=0
  out=$(gate_es es_class_command "$(printf '%s' "$1" | tr '`' ' ')") || rc=$?
  case "$rc" in
    0) warn "$2 names an enforcement surface ($(printf '%s' "$out" | LC_ALL=C awk -F '\t' '{ printf "%s%s=%s", (NR > 1 ? ", " : ""), $1, $2 }')) — the seat does not run a command on one without a person; a stage commits such an edit through a \`Step 3 강제 표면 좌석 적용\` halt: $3"
       return "$GATE_EXIT_RULE" ;;
    1) return 0 ;;
    *) warn "the enforcement-surface classifier could not be loaded, so whether $2 names an enforcement surface cannot be judged — the seat does not answer it without a person: $3"
       return "$GATE_EXIT_RULE" ;;
  esac
}

# The body of every seat-apply commit. A fixed sentence: the subject is the
# stage's, and the run directory, the record or a trailer would put a path or a
# name into the branch's history that the review and the person never chose.
readonly GATE_SA_BODY='강제 표면 파일을 사람 승인에 따라 좌석 적용으로 커밋했다.'
# The one-read copy of the record a `halt-answer` seat apply is reading, which
# the exit trap removes.
GATE_SA_COPY=""

gate_seat_apply_path_shape() {
  # gate_seat_apply_path_shape <path> — 0 when <path> is a repository-relative
  # path with no `..`, `.`, empty or `.git` component, no leading `/`, `-` or
  # trailing `/`, and no control character, backtick or backslash.
  case "$1" in ''|/*|*/|-*) return 1 ;; esac
  case "/$1/" in */../*|*/./*|*//*|*/.git/*) return 1 ;; esac
  case "$1" in *[[:cntrl:]]*|*'`'*|*\\*) return 1 ;; esac
  return 0
}

gate_seat_apply_parse() {
  # gate_seat_apply_parse <record> — reads a `Step 3 강제 표면 좌석 적용` record
  # into GATE_SA_BASE, GATE_SA_SUBJECT, GATE_SA_FILES (one
  # `<path>\t<class>\t<blob|없음>\t<mode>\t<base64|삭제>` line per file the seat
  # applies), GATE_SA_HUMAN (one `<path>\t<class>` line per file left to a
  # person) and their counts GATE_SA_NA and GATE_SA_NH. A record whose fields
  # do not have the written shape is warned about and refused with
  # GATE_EXIT_RULE. Shape and class only: whether a path may be applied in the
  # segment worktree is `gate_seat_apply_check`'s.
  #
  # A FILE LINE STARTS `- 파일 `, NEVER ``- ` ``. That head is an option line's,
  # and a path read as an option label is one a person could be offered.
  local rec="$1" out ln tag rest counts='' c_b c_s c_a c_h p cls blob mode pay want rc_es seen=$'\n'
  GATE_SA_BASE=''; GATE_SA_SUBJECT=''; GATE_SA_FILES=''; GATE_SA_HUMAN=''; GATE_SA_NA=0; GATE_SA_NH=0
  out=$(LC_ALL=C awk '
    BEGIN { sep = " — "; nb = ns = na = nh = 0; fh = "- 파일 `"
            kb = "**좌석 적용 기준**: "; ks = "**좌석 적용 커밋 제목**: " }
    $0 == "<!-- /cc-pipeline-halt v1 -->" { exit }
    /^\*\*/ { blk = "" }
    index($0, kb) == 1 { nb++; print "B\t" substr($0, length(kb) + 1); next }
    index($0, ks) == 1 { ns++; print "S\t" substr($0, length(ks) + 1); next }
    /^\*\*좌석 적용 파일\*\*:[ \t]*$/ { blk = "A"; na++; next }
    /^\*\*사람 몫 파일\*\*:[ \t]*$/ { blk = "H"; nh++; next }
    blk == "" || /^[ \t]*$/ { next }
    index($0, fh) != 1 { print "E\t" NR; next }
    {
      r = substr($0, length(fh) + 1); q = index(r, "`")
      if (q < 2) { print "E\t" NR; next }
      p = substr(r, 1, q - 1); r = substr(r, q + 1)
      if (index(r, sep) != 1) { print "E\t" NR; next }
      n = split(substr(r, length(sep) + 1), f, sep)
      if (blk == "A") {
        if (n != 4 || index(f[2], "기준 ") != 1 || index(f[3], "모드 ") != 1) { print "E\t" NR; next }
        print "A\t" p "\t" f[1] "\t" substr(f[2], length("기준 ") + 1) "\t" substr(f[3], length("모드 ") + 1) "\t" f[4]
      } else {
        if (n < 2 || f[2] == "") { print "E\t" NR; next }
        print "H\t" p "\t" f[1]
      }
    }
    END { print "C\t" nb "\t" ns "\t" na "\t" nh }
  ' "$rec" 2>/dev/null || true)
  while IFS= read -r ln; do
    [ -n "$ln" ] || continue
    tag=${ln%%$'\t'*}; rest=${ln#*$'\t'}
    case "$tag" in
      B) GATE_SA_BASE=$rest ;;
      S) GATE_SA_SUBJECT=$rest ;;
      A) GATE_SA_FILES="$GATE_SA_FILES$rest"$'\n'; GATE_SA_NA=$((GATE_SA_NA + 1)) ;;
      H) GATE_SA_HUMAN="$GATE_SA_HUMAN$rest"$'\n'; GATE_SA_NH=$((GATE_SA_NH + 1)) ;;
      E) warn "line $rest of the record's file fields is not a file line of the written shape (\`- 파일 \`<path>\` — <class> — …\`): $rec"
         return "$GATE_EXIT_RULE" ;;
      C) counts=$rest ;;
    esac
  done <<EOF
$out
EOF
  IFS=$'\t' read -r c_b c_s c_a c_h <<EOF
${counts:-0	0	0	0}
EOF
  if [ "$c_b" -gt 1 ] || [ "$c_s" -gt 1 ] || [ "$c_a" -gt 1 ] || [ "$c_h" -gt 1 ]; then
    warn "a seat-apply record carries each of \`**좌석 적용 기준**\`, \`**좌석 적용 파일**\`, \`**사람 몫 파일**\` and \`**좌석 적용 커밋 제목**\` at most once: $rec"
    return "$GATE_EXIT_RULE"
  fi
  if [ "$GATE_SA_NA" -gt 0 ]; then
    if [ "$c_b" != 1 ] || [ "$c_s" != 1 ]; then
      warn "a seat-apply record with files to apply carries \`**좌석 적용 기준**\` and \`**좌석 적용 커밋 제목**\`: $rec"
      return "$GATE_EXIT_RULE"
    fi
    case "$GATE_SA_BASE" in
      *[!0-9a-f]*|'') warn "\`**좌석 적용 기준**\` is not a 40-hex commit: ${GATE_SA_BASE:-(empty)}: $rec"; return "$GATE_EXIT_RULE" ;;
    esac
    [ "${#GATE_SA_BASE}" -eq 40 ] || { warn "\`**좌석 적용 기준**\` is not a 40-hex commit: $GATE_SA_BASE: $rec"; return "$GATE_EXIT_RULE"; }
  elif [ "$c_b" != 0 ] || [ "$c_s" != 0 ] || [ "$c_a" != 0 ] || [ "$GATE_SA_NH" -eq 0 ]; then
    warn "a seat-apply record either applies files (\`**좌석 적용 기준**\`, \`**좌석 적용 파일**\` with file lines, \`**좌석 적용 커밋 제목**\`) or leaves them all to a person (\`**사람 몫 파일**\` with file lines and none of the three): $rec"
    return "$GATE_EXIT_RULE"
  fi
  while IFS=$'\t' read -r p cls blob mode pay; do
    [ -n "$p" ] || continue
    gate_seat_apply_path_shape "$p" || { warn "\`$p\` is not a repository-relative path without \`..\`, \`.\`, a leading or doubled \`/\` or a control character: $rec"; return "$GATE_EXIT_RULE"; }
    case "$seen" in *$'\n'"$p"$'\n'*) warn "\`$p\` is named twice in the record's file fields: $rec"; return "$GATE_EXIT_RULE" ;; esac
    seen="$seen$p"$'\n'
    want=''; rc_es=0
    want=$(gate_es es_class "/$p") || rc_es=$?
    [ "$rc_es" -le 1 ] || { warn "the enforcement-surface classifier could not be loaded, so the record's paths cannot be judged: $rec"; return "$GATE_EXIT_RULE"; }
    if [ -z "$want" ]; then
      warn "\`$p\` is not an enforcement surface (the classifier gives it no class), so it is committed by the stage, not by a seat apply: $rec"
      return "$GATE_EXIT_RULE"
    fi
    [ "$cls" = "$want" ] || { warn "\`$p\` is written as \`$cls\` and the classifier calls it \`$want\`: $rec"; return "$GATE_EXIT_RULE"; }
    [ -n "$mode" ] || continue
    gate_es es_seat_applicable_class "$cls" || {
      warn "\`$p\` is a \`$cls\` path, which the run never commits — it is a file left to a person (\`**사람 몫 파일**\`): $rec"
      return "$GATE_EXIT_RULE"; }
    case "$blob" in
      없음) ;;
      *[!0-9a-f]*|'') warn "the base blob of \`$p\` is neither a 40-hex blob nor \`없음\`: $blob: $rec"; return "$GATE_EXIT_RULE" ;;
      *) [ "${#blob}" -eq 40 ] || { warn "the base blob of \`$p\` is neither a 40-hex blob nor \`없음\`: $blob: $rec"; return "$GATE_EXIT_RULE"; } ;;
    esac
    case "$mode:$pay" in
      삭제:삭제) [ "$blob" != 없음 ] || { warn "\`$p\` is deleted but the base has no such path: $rec"; return "$GATE_EXIT_RULE"; } ;;
      삭제:*|*:삭제) warn "\`$p\` is deleted in one of its mode and content fields and not in the other: $rec"; return "$GATE_EXIT_RULE" ;;
      100644:*|100755:*)
        case "$pay" in *[!A-Za-z0-9+/=]*) warn "the content of \`$p\` is not one line of base64: $rec"; return "$GATE_EXIT_RULE" ;; esac
        # The bytes decode and encode back to the same line, so a payload the
        # decoder would read leniently — wrapped, padded oddly — is refused
        # rather than committed as whatever it decodes to.
        [ "$(printf '%s' "$pay" | openssl base64 -d -A 2>/dev/null | openssl base64 -A 2>/dev/null)" = "$pay" ] || {
          warn "the content of \`$p\` does not decode to bytes that encode back to the same base64 line: $rec"
          return "$GATE_EXIT_RULE"; } ;;
      *) warn "the mode of \`$p\` is not one of 100644 · 100755 · 삭제: $mode: $rec"; return "$GATE_EXIT_RULE" ;;
    esac
  done <<EOF
$GATE_SA_FILES$(printf '%s' "$GATE_SA_HUMAN" | LC_ALL=C awk -F '\t' 'NF { print $1 "\t" $2 }')
EOF
  return 0
}

gate_seat_apply_subject_ok() {
  # gate_seat_apply_subject_ok <subject> — 0 for one line of the form
  # `type(scope): <title>`, at most 100 characters, with no trailer-shaped text.
  local s="$1" n
  case "$s" in *[[:cntrl:]]*) return 1 ;; esac
  printf '%s' "$s" | LC_ALL=C grep -Eq '^[a-z]+\([^()[:space:]]+\): [^[:space:]]' || return 1
  printf '%s' "$s" | LC_ALL=C grep -Eqi 'co-authored-by|signed-off-by|generated with' && return 1
  # Characters, not bytes: the continuation bytes of UTF-8 are dropped first.
  n=$(printf '%s' "$s" | LC_ALL=C tr -d '\200-\277' | wc -c | tr -d ' ')
  [ "$n" -le 100 ]
}

gate_seat_apply_scope() {
  # gate_seat_apply_scope <declared set> — the apply scope of a declaration,
  # one entry per line, sorted and unique: each declared entry the classifier
  # puts in a class the seat may commit, and each declared directory (an entry
  # ending in `/`). A path is in the scope when it is one of them or under a
  # directory among them, by the declared-set prefix rule. Exit 2 when the
  # classifier could not be loaded.
  local d c rc out=''
  while IFS= read -r d; do
    [ -n "$d" ] || continue
    case "$d" in
      */) out="$out$d"$'\n'; continue ;;
    esac
    rc=0; c=$(gate_es es_class "/$d") || rc=$?
    [ "$rc" -le 1 ] || return 2
    [ -n "$c" ] || continue
    gate_es es_seat_applicable_class "$c" && out="$out$d"$'\n'
  done <<EOF
$(printf '%s' "$1" | tr ',' '\n' | sed -e 's/^[[:space:]]*//' -e 's/[[:space:]]*$//')
EOF
  printf '%s' "$out" | LC_ALL=C sort -u
}

gate_seat_apply_under() {
  # gate_seat_apply_under <path> <entries, one per line> — 0 when <path> is one
  # of the entries or starts with one, the prefix rule `gate_fileset_escape`
  # reads a declaration by.
  local e
  while IFS= read -r e; do
    [ -n "$e" ] || continue
    case "$1" in "$e"|"$e"*) return 0 ;; esac
  done <<EOF
$2
EOF
  return 1
}

gate_seat_apply_scope_digest() {
  # gate_seat_apply_scope_digest <scope> — sha256 of the scope's lines, each
  # ended by a newline.
  printf '%s\n' "$1" | grep -v '^$' | shasum -a 256 | cut -d' ' -f1
}

gate_seat_apply_check() {
  # gate_seat_apply_check <segment> <alias> — the per-path and worktree checks of
  # a seat apply against the parsed record (GATE_SA_*), with the worktree taken
  # from the segment row and never from the record. Sets GATE_SA_WT; warns and
  # returns GATE_EXIT_RULE on the first failure.
  #
  # THE WORKTREE IS THE SEGMENT'S, CLEAN, AND AT THE RECORD'S BASE. The apply
  # never touches the working tree until the fast-forward, so a dirty tree or a
  # moved HEAD would make that fast-forward carry something nobody approved,
  # and the rollback's `reset --hard` would lose it.
  #
  # NO SYMBOLIC LINK ON THE WAY. Every component of every target path is
  # `lstat`ed — tracked, untracked or ignored alike: a fast-forward replaces an
  # ignored symlinked directory with a real one without a word, and
  # `git status` stays clean.
  local seg="$1" al="$2" wt top decl p cls blob mode pay ent emode etype eoid pre comp rest
  wt=$(gate_segment_worktree "$seg")
  GATE_SA_WT=$wt
  if [ -z "$wt" ] || [ ! -d "$wt" ]; then
    warn "segment $seg has no worktree on its row, so there is nothing to apply into: '${wt:-(none)}'"
    return "$GATE_EXIT_RULE"
  fi
  gate_path_of_target "$wt" "$al" || {
    warn "the worktree of $seg is not a worktree of target $al (its common git directory is not the target's): $wt"
    return "$GATE_EXIT_RULE"; }
  top=$( { cd "$wt" 2>/dev/null && env -u GIT_DIR -u GIT_COMMON_DIR -u GIT_WORK_TREE git rev-parse --show-toplevel 2>/dev/null; } || true)
  if [ -z "$top" ] || [ "$(cd "$top" 2>/dev/null && pwd -P)" != "$(cd "$wt" 2>/dev/null && pwd -P)" ]; then
    warn "the worktree of $seg is not the top of its own repository (${top:-not a repository}): $wt"
    return "$GATE_EXIT_RULE"
  fi
  if [ "$(gate_worktree_tip "$wt" || true)" != "$GATE_SA_BASE" ]; then
    warn "the HEAD of $seg is not the record's \`**좌석 적용 기준**\` ($GATE_SA_BASE) — the stage's last commit is the base the edit was written against: $wt"
    return "$GATE_EXIT_RULE"
  fi
  if [ -n "$( (cd "$wt" && git status --porcelain --untracked-files=no) 2>/dev/null || printf 'x')" ]; then
    warn "the worktree of $seg has uncommitted changes, so the apply could not be undone without losing them: $wt"
    return "$GATE_EXIT_RULE"
  fi
  decl=$(gate_segment_declared_whole "$seg") || {
    warn "the whole declared file set of $seg cannot be read back, so whether the record's paths are inside it cannot be judged"
    return "$GATE_EXIT_RULE"; }
  decl=$(printf '%s' "$decl" | tr ',' '\n' | sed -e 's/^[[:space:]]*//' -e 's/[[:space:]]*$//' | grep -v '^$' || true)
  while IFS=$'\t' read -r p cls blob mode pay; do
    [ -n "$p" ] || continue
    gate_seat_apply_under "$p" "$decl" || {
      warn "\`$p\` is not inside the declared file set of $seg — an enforcement-surface edit outside the declaration leaves the design's binding tier"
      return "$GATE_EXIT_RULE"; }
    if (cd "$wt" && git check-ignore -q --no-index -- "$p") 2>/dev/null; then
      warn "\`$p\` is ignored in the worktree of $seg, so no review could see it as a commit — it is a file left to a person"
      return "$GATE_EXIT_RULE"
    fi
    ent=$( (cd "$wt" && GIT_LITERAL_PATHSPECS=1 git ls-tree -z "$GATE_SA_BASE" -- "$p") 2>/dev/null | tr '\0' '\n' | sed -n '1p')
    emode=''; etype=''; eoid=''
    if [ -n "$ent" ]; then
      ent=${ent%%$'\t'*}
      read -r emode etype eoid <<EOF
$ent
EOF
      if [ "$etype" != blob ] || { [ "$emode" != 100644 ] && [ "$emode" != 100755 ]; }; then
        warn "\`$p\` is a \`$emode $etype\` entry at the base, not a regular file"
        return "$GATE_EXIT_RULE"
      fi
    fi
    if [ "$blob" = 없음 ]; then
      [ -z "$ent" ] || { warn "the record says the base has no \`$p\`, and it has $eoid"; return "$GATE_EXIT_RULE"; }
    elif [ "$blob" != "$eoid" ]; then
      warn "the base blob of \`$p\` is ${eoid:-absent}, not the record's $blob — the edit was written against other bytes"
      return "$GATE_EXIT_RULE"
    fi
    if [ "$cls" = 지침파일 ] && [ -z "$ent" ]; then
      warn "\`$p\` is a CLAUDE.md the base does not track — that slot is written by the gate's own CLAUDE.md route, not by a seat apply"
      return "$GATE_EXIT_RULE"
    fi
    pre=$wt; rest=$p
    while :; do
      comp=${rest%%/*}
      pre="$pre/$comp"
      if [ -L "$pre" ]; then
        warn "\`${pre#"$wt"/}\` on the way to \`$p\` is a symbolic link in the worktree of $seg"
        return "$GATE_EXIT_RULE"
      fi
      [ "$rest" != "$comp" ] || break
      rest=${rest#*/}
    done
  done <<EOF
$GATE_SA_FILES
EOF
  return 0
}

gate_seat_apply_build() {
  # gate_seat_apply_build <worktree> — the commit a seat apply lands, printed:
  # the record's files over `**좌석 적용 기준**` in a temporary index, written
  # as a tree and committed with the record's subject and the fixed body. The
  # working tree, the index and every ref stay as they were. With
  # `gate_iso_open` in force the objects go into the isolated directory, which
  # is how the preview shows the very commit the apply would make.
  local wt="$1" idxd p cls blob mode pay oid tree c rc=0
  idxd=$(mktemp -d "${TMPDIR:-/tmp}/gate-sa-index.XXXXXX") || return 1
  (
    GIT_INDEX_FILE="$idxd/index"; export GIT_INDEX_FILE
    gate_iso_git "$wt" read-tree "$GATE_SA_BASE" || exit 1
    while IFS=$'\t' read -r p cls blob mode pay; do
      [ -n "$p" ] || continue
      if [ "$mode" = 삭제 ]; then
        gate_iso_git "$wt" update-index --force-remove -- "$p" || exit 1
      else
        oid=$(printf '%s' "$pay" | openssl base64 -d -A | gate_iso_git "$wt" hash-object -w --no-filters --stdin) || exit 1
        gate_iso_git "$wt" update-index --add --cacheinfo "$mode" "$oid" "$p" || exit 1
      fi
    done <<EOF
$GATE_SA_FILES
EOF
    tree=$(gate_iso_git "$wt" write-tree) || exit 1
    printf '%s\n\n%s\n' "$GATE_SA_SUBJECT" "$GATE_SA_BODY" | gate_iso_git "$wt" commit-tree "$tree" -p "$GATE_SA_BASE"
  ) || rc=1
  rm -rf "$idxd"
  return "$rc"
}

gate_seat_apply_question() {
  # gate_seat_apply_question <record digest> <segment> <scope> — the question
  # line the seat puts to the person verbatim, and the frame check looks for in
  # the question the person was shown.
  local paths
  if [ "$GATE_SA_NA" -gt 0 ]; then
    paths=$(printf '%s' "$GATE_SA_FILES" | LC_ALL=C awk -F '\t' 'NF { printf "%s%s", (n++ ? ", " : ""), $1 }')
    printf '기록 %s — 세그먼트 %s 의 강제 표면 편집 %s건을 게이트가 좌석 적용으로 커밋합니다: %s. 이 답은 같은 세그먼트에서 뒤에 나오는 적용 범위 %s건(%s) 안의 강제 표면 편집에도 쓰입니다.' \
      "$1" "$2" "$GATE_SA_NA" "$paths" "$(printf '%s\n' "$3" | grep -c . || true)" \
      "$(printf '%s\n' "$3" | grep -v '^$' | LC_ALL=C awk '{ printf "%s%s", (n++ ? ", " : ""), $0 }')"
  else
    paths=$(printf '%s' "$GATE_SA_HUMAN" | LC_ALL=C awk -F '\t' 'NF { printf "%s%s", (n++ ? ", " : ""), $1 }')
    printf '기록 %s — 세그먼트 %s 의 강제 표면 편집 %s건은 런이 커밋할 수 없어 사람 몫으로 넘깁니다: %s.' \
      "$1" "$2" "$GATE_SA_NH" "$paths"
  fi
}

gate_seat_apply_frame() {
  # gate_seat_apply_frame <record digest> <question line> <record copy> <option>
  # — 0 with GATE_SA_FRAME set to the `tool_use_id` when the caller's lineage
  # holds the harness-written answer of an `AskUserQuestion` whose question
  # carried the question line, whose options were the record's labels and whose
  # answer is <option>; otherwise a warning and GATE_EXIT_RULE.
  #
  # THE PERSON'S FIRST ANSWER IS PROVED BY THE FRAME, NOT TOLD BY THE SEAT. The
  # binding of the frame reader is the token alone, so the question line is
  # required verbatim: a frame that carries the digest in another question
  # would otherwise pass. The id is spent once — a frame already quoted as some
  # row's `승인 프레임` proves nothing new.
  local dig="$1" q="$2" rec="$3" opt="$4" shown want r
  GATE_SA_FRAME=''
  if gate_transcript_torn; then
    warn "a transcript of this session's lineage ends mid-line, so the person's answer cannot be read yet — answer again once it is written out: $rec"
    return "$GATE_EXIT_RULE"
  fi
  gate_frame_candidate "$dig" || true
  if [ "$GATE_FRAME_KIND" != answers ]; then
    warn "no answered \`AskUserQuestion\` carrying record digest $dig is in this session's lineage (${GATE_FRAME_KIND}) — ask the person with the preview's question line first"
    return "$GATE_EXIT_RULE"
  fi
  gate_frame_parse "$GATE_FRAME_FILE" "$GATE_FRAME_LINE" "$dig"
  if [ "$GATE_FRAME_TYPE" != user ] || [ -z "$GATE_FRAME_TID" ] || [ "$GATE_FRAME_ERR" = 1 ] \
     || [ "$GATE_FRAME_TOOL" != AskUserQuestion ] || [ "$GATE_FRAME_HASANS" != 1 ] || [ "$GATE_FRAME_HASKEY" != 1 ]; then
    warn "the frame carrying record digest $dig is not the harness-written answer of an \`AskUserQuestion\` (tool ${GATE_FRAME_TOOL:-미상}, error ${GATE_FRAME_ERR:-0}, answer map ${GATE_FRAME_HASANS:-0}/${GATE_FRAME_HASKEY:-0})"
    return "$GATE_EXIT_RULE"
  fi
  case "$GATE_FRAME_KEY" in
    *"$q"*) ;;
    *) warn "the question the person was shown does not carry the preview's question line verbatim — ask with the line \`seat-apply-preview\` prints"
       return "$GATE_EXIT_RULE" ;;
  esac
  if [ "$GATE_FRAME_ANSWER" != "$opt" ]; then
    warn "the person answered \`$GATE_FRAME_ANSWER\`, not \`$opt\` — a free answer or another label is not a seat-apply approval"
    return "$GATE_EXIT_RULE"
  fi
  shown=$(printf '%s\n' "$GATE_FRAME_LABELS" | while IFS= read -r r; do [ -n "$r" ] && gate_menu_normalize "$r" && printf '\n'; done | LC_ALL=C sort -u)
  want=$(gate_halt_option_labels "$rec" | LC_ALL=C sort -u)
  if [ "$shown" != "$want" ]; then
    warn "the options the person was shown are not the record's labels ($(printf '%s' "$want" | tr '\n' ' '))"
    return "$GATE_EXIT_RULE"
  fi
  while IFS= read -r r; do
    [ -n "$r" ] || continue
    if [ "$(gate_row_field "$r" '승인 프레임')" = "$GATE_FRAME_TID" ]; then
      warn "the question frame $GATE_FRAME_TID already approved a seat apply, and one frame approves one record"
      return "$GATE_EXIT_RULE"
    fi
  done <<EOF
$( { gate_rows '중단 답' || true; } )
EOF
  GATE_SA_FRAME=$GATE_FRAME_TID
}

gate_halt_seat_apply_covered() {
  # gate_halt_seat_apply_covered <key> — 0 when the parsed record (GATE_SA_*) is
  # covered by a person's earlier seat-apply answer of the same segment, with
  # GATE_SA_COV_FRAME and GATE_SA_COV_REC set to that answer's frame and record;
  # otherwise a warning and GATE_EXIT_RULE, and the seat asks the person.
  #
  # THE PERSON ANSWERS ONCE PER SEGMENT, FOR THE SCOPE THEY WERE SHOWN. The
  # latest `중단 답` row of the key that a person gave to a seat apply, with its
  # frame, carried in by no adoption (`출처 런`); its commit still an ancestor
  # of the worktree's HEAD; no `park` of the segment, no run end by `포기` or
  # `이어받음` and no adopted answer of the key after it; every path of the new
  # record inside its scope; and nothing left to a person. The scope is
  # re-derived from the declaration that stood when the person answered and
  # compared with the digest the row keeps, so a side file read differently
  # later inherits nothing.
  local key="$1" r ln row last='' lastln='' sc scope wt sha p cls blob mode pay
  GATE_SA_COV_FRAME=''; GATE_SA_COV_REC=''
  if [ "$GATE_SA_NH" -gt 0 ]; then
    warn "the record leaves files to a person, so the seat does not answer it — a person sees every such file"
    return "$GATE_EXIT_RULE"
  fi
  while IFS= read -r r; do
    [ -n "$r" ] || continue
    ln=${r%%:*}; row=${r#*:}
    [ "$(gate_row_field "$row" '세그먼트')" = "$key" ] || continue
    [ -z "$(gate_row_field "$row" '출처 런')" ] || continue
    [ "$(gate_row_field "$row" '선택지')" = '좌석 적용' ] || continue
    [ "$(gate_row_field "$row" '답한 주체')" = '사람' ] || continue
    [ "$(gate_row_field "$row" '근거 종류')" = '좌석 적용' ] || continue
    [ -n "$(gate_row_field "$row" '승인 프레임')" ] || continue
    last=$row; lastln=$ln
  done <<EOF
$( { grep -n "^- \`중단 답\` " "$LEDGER" 2>/dev/null || true; } )
EOF
  if [ -z "$last" ]; then
    warn "$key has no seat apply a person approved, so this one is the person's to answer"
    return "$GATE_EXIT_RULE"
  fi
  sha=$(gate_row_field "$last" '좌석 커밋')
  wt=$(gate_segment_worktree "$key")
  if [ -z "$sha" ] || [ -z "$wt" ] || ! (cd "$wt" && git merge-base --is-ancestor "$sha" HEAD) 2>/dev/null; then
    warn "the seat commit ${sha:-(none)} the person approved (ledger line $lastln) is no longer an ancestor of $key's HEAD — the branch was rebuilt or rebased, so the person answers again"
    return "$GATE_EXIT_RULE"
  fi
  if [ -n "$(LC_ALL=C awk -v l="$lastln" -v k="$key" '
        NR <= l { next }
        index($0, "- `segment` ") == 1 && index($0, " | id=" k " |") && index($0, " | 상태=park ") { print NR; exit }
        index($0, "- `segment` ") == 1 && index($0, " | id=" k " |") && $0 ~ / \| 상태=park$/ { print NR; exit }
        index($0, "- `자율 승인` ") == 1 && (index($0, "| 종료 부류=포기") || index($0, "| 종료 부류=이어받음")) { print NR; exit }
        index($0, "- `중단 답` ") == 1 && index($0, " | 세그먼트=" k " |") && index($0, " | 출처 런=") { print NR; exit }
      ' "$LEDGER" 2>/dev/null)" ]; then
    warn "$key was parked, the run was given up or taken over, or an answer was adopted into it after the person's seat apply (ledger line $lastln), so that answer covers nothing later"
    return "$GATE_EXIT_RULE"
  fi
  sc=$(gate_segment_declared_whole "$key" "$lastln") || {
    warn "the declaration $key had when the person answered cannot be read back whole, so the scope they approved cannot be re-derived"
    return "$GATE_EXIT_RULE"; }
  scope=$(gate_seat_apply_scope "$sc") || {
    warn "the enforcement-surface classifier could not be loaded, so the scope the person approved cannot be re-derived"
    return "$GATE_EXIT_RULE"; }
  if [ "$(gate_seat_apply_scope_digest "$scope")" != "$(gate_row_field "$last" '적용 범위 다이제스트')" ]; then
    warn "the scope re-derived from $key's declaration is not the one the person approved (ledger line $lastln) — the person answers again"
    return "$GATE_EXIT_RULE"
  fi
  while IFS=$'\t' read -r p cls blob mode pay; do
    [ -n "$p" ] || continue
    gate_seat_apply_under "$p" "$scope" || {
      warn "\`$p\` is outside the scope the person approved (ledger line $lastln) — a path the approval did not show goes to the person"
      return "$GATE_EXIT_RULE"; }
  done <<EOF
$GATE_SA_FILES
EOF
  GATE_SA_COV_FRAME=$(gate_row_field "$last" '승인 프레임')
  GATE_SA_COV_REC=$(gate_row_field "$last" '중단 기록')
}

gate_seat_apply_preview() {
  # gate_seat_apply_preview <record> [<alias>] — what a seat apply of the record would
  # commit, and the question the seat asks: the record digest, the unified diff
  # and `--numstat` of the commit, the apply scope and the question line. The
  # commit is built in an isolated object directory and dropped, so nothing is
  # written to the ledger, the worktree, the branch or the common object store.
  #
  # THE SAME DECODE AND THE SAME TREE AS THE APPLY. `gate_seat_apply_build` is
  # the one function both run, so what the person sees is the diff the apply
  # commits — not a second rendering of the record that could differ from it.
  local rec="$1" al="${2:-}" seg first cp dig scope decl c rc=0 dd q
  # The target the apply would run against: `--target`, or the manifest's one
  # target when it declares one.
  if [ -z "$al" ]; then
    al=$(target_aliases 2>/dev/null || true)
    case "$al" in
      *[[:space:]]*|'') warn "seat-apply-preview needs --target when the manifest declares more than one target"; return "$GATE_EXIT_VOCAB" ;;
    esac
  fi
  case "$rec" in
    "$RUN_DIR"/halt/*.md) ;;
    *) warn "--record has to be a file under this run's halt directory ($RUN_DIR/halt/): $rec"; return "$GATE_EXIT_VOCAB" ;;
  esac
  case "$rec" in */../*|*/./*) warn "--record cannot carry a relative segment: $rec"; return "$GATE_EXIT_VOCAB" ;; esac
  [ -f "$rec" ] || { warn "the halt record does not exist: $rec"; return "$GATE_EXIT_VOCAB"; }
  cp=$(mktemp "${TMPDIR:-/tmp}/gate-sa-rec.XXXXXX") || return 1
  cat "$rec" > "$cp" || { rm -f "$cp"; return 1; }
  dig=$(shasum -a 256 "$cp" | cut -d' ' -f1)
  first=$(sed -n '1p' "$cp")
  seg=$(printf '%s' "$first" | sed -n 's/^<!-- cc-pipeline-halt v1;.* stage=\([^;#]*\)[#;].*/\1/p')
  if [ -z "$seg" ] || ! grep -qxF '<!-- /cc-pipeline-halt v1 -->' "$cp"; then
    rm -f "$cp"; warn "not a complete halt record whose header names its stage: $rec"; return "$GATE_EXIT_VOCAB"
  fi
  case "$(sed -n 's/^\*\*스텝\*\*: //p' "$cp" | sed -n '1p')" in
    'Step 3 강제 표면 좌석 적용'*) ;;
    *) rm -f "$cp"; warn "the record is not a \`Step 3 강제 표면 좌석 적용\` halt: $rec"; return "$GATE_EXIT_RULE" ;;
  esac
  gate_seat_apply_parse "$cp" || { rc=$?; rm -f "$cp"; return "$rc"; }
  decl=$(gate_segment_declared_whole "$seg") || decl=''
  scope=$(gate_seat_apply_scope "$decl") || scope=''
  printf '기록 다이제스트: %s\n' "$dig"
  printf '세그먼트: %s\n' "$seg"
  if [ "$GATE_SA_NA" -gt 0 ]; then
    gate_seat_apply_check "$seg" "$al" || { rc=$?; rm -f "$cp"; return "$rc"; }
    gate_iso_open "$GATE_SA_WT" || { rm -f "$cp"; warn "cannot open an isolated object directory for $GATE_SA_WT"; return 1; }
    c=$(gate_seat_apply_build "$GATE_SA_WT") || rc=1
    if [ "$rc" = 0 ]; then
      dd=$(gate_iso_git "$GATE_SA_WT" -c core.quotePath=false diff --no-renames --numstat "$GATE_SA_BASE" "$c")
      printf '%s\n' '--numstat:' "$dd"
      printf '%s\n' '통합 diff:'
      gate_iso_git "$GATE_SA_WT" -c core.quotePath=false diff --no-renames --no-color "$GATE_SA_BASE" "$c"
    fi
    gate_iso_close
    [ "$rc" = 0 ] || { rm -f "$cp"; warn "the apply commit could not be built from the record"; return "$GATE_EXIT_RULE"; }
  fi
  if [ "$GATE_SA_NH" -gt 0 ]; then
    printf '%s\n' '사람 몫 파일:'
    printf '%s' "$GATE_SA_HUMAN" | LC_ALL=C awk -F '\t' 'NF { print "- " $1 " (" $2 ")" }'
  fi
  printf '적용 범위 다이제스트: %s\n' "$(gate_seat_apply_scope_digest "$scope")"
  printf '적용 범위:\n'
  printf '%s\n' "$scope" | grep -v '^$' | sed 's/^/- /' || true
  q=$(gate_seat_apply_question "$dig" "$seg" "$scope")
  printf '질문 줄: %s\n' "$q"
  rm -f "$cp"
}

gate_halt_design_check() {
  # gate_halt_design_check <record> — the further checks a seat answer meets on
  # an unattended design stage's `/ ladder-unsettled` or `/ skeleton` record,
  # after gate_halt_recommendation passed. On success GATE_HALT_LADDER_STAMP
  # holds the `잔여 판정` value the row carries (`코드-부재:R2,R3/사람-환경:R1`),
  # empty for any other record; on failure the reason is warned and the exit
  # is GATE_EXIT_RULE. A person's answer is never checked here: a person may
  # take any option.
  #
  # THE LADDER'S RECOMMENDATION IS A RULE APPLIED, NOT A JUDGMENT. The writer
  # recommends `잔여로 두고 동결` only when every item the ladder left open is
  # blocked by code not yet written, a person's environment or an external
  # preparation, each of the last two stated `구현 후`, and the run is not a
  # base design. The record's `**잔여 판정**` says which, and this checks it
  # against the design document — the record alone is the writer vouching for
  # itself. What the comparison cannot see (a W3 mark that is forged or left
  # from an earlier run, a class the document and the record agree on wrongly,
  # a premise nobody tested) the design discloses as residual risk.
  #
  # THE STEP IS FOUND BY SUBSTRING. Three spellings of the ladder step have been
  # observed (`Step 7U / ladder-unsettled`, `Step 7U.4 / ladder-unsettled` and
  # one with a trailing clause), and a prefix or suffix match misses some.
  local rec="$1" step ladder='' skel='' line parts p k bad='' skill pairs pair_labs lab cls doc pend dup heads h own sid nslice
  GATE_HALT_LADDER_STAMP=''
  step=$(sed -n 's/^\*\*스텝\*\*: //p' "$rec" | sed -n '1p')
  case "$step" in
    *'/ ladder-unsettled'*) ladder=1 ;;
    *'/ skeleton'*) skel=1 ;;
    *) return 0 ;;
  esac
  # G5 — every part of `**추천 근거**` names one of the four kinds. The kinds
  # stamp keeps the parts it recognises and drops the rest without a word, so
  # it is not what decides here; a ladder's parts are all `기기 사실`, the
  # document's own `차단 부류` lines.
  line=$(sed -n 's/^\*\*추천 근거\*\*: //p' "$rec" | sed -n '1p' | sed 's/[[:space:]]*$//')
  parts=$(printf '%s\n' "$line" | LC_ALL=C awk 'BEGIN { FS = " / " }
    { for (i = 1; i <= NF; i++) { k = $i; sub(/^ +/, "", k)
        if (index(k, ":") == 0) k = ""; else k = substr(k, 1, index(k, ":") - 1)
        print k } }')
  [ -n "$line" ] || bad='(없음)'
  while IFS= read -r k; do
    [ -n "$line" ] || break
    case "$k" in
      '기기 사실') ;;
      '인터뷰 기록'|'매니페스트 인가'|'상시 지침') [ -z "$ladder" ] || bad="$k" ;;
      *) bad="${k:-(종류 없음)}" ;;
    esac
    [ -z "$bad" ] || break
  done <<EOF
$parts
EOF
  if [ -n "$bad" ]; then
    if [ -n "$ladder" ]; then
      warn "a \`/ ladder-unsettled\` recommendation rests on \`기기 사실\` alone, one part per item — \`**추천 근거**\` carries \`$bad\`: $rec"
    else
      warn "every part of \`**추천 근거**\` names one of 인터뷰 기록 · 매니페스트 인가 · 기기 사실 · 상시 지침 — this one carries \`$bad\`, so a person answers it: $rec"
    fi
    return "$GATE_EXIT_RULE"
  fi
  [ -n "$ladder" ] || return 0
  # G1 — exactly one `**잔여 판정**` line, in its grammar, each item once.
  if [ "$(grep -c '^\*\*잔여 판정\*\*: ' "$rec" || true)" != "1" ]; then
    warn "a \`/ ladder-unsettled\` record carries exactly one \`**잔여 판정**\` line: $rec"
    return "$GATE_EXIT_RULE"
  fi
  line=$(sed -n 's/^\*\*잔여 판정\*\*: //p' "$rec" | sed 's/[[:space:]]*$//')
  if ! grep -qE '^(코드-부재|사람-환경|외부-준비|전제-반증|미분류): R[0-9]+(, R[0-9]+)*( / (코드-부재|사람-환경|외부-준비|전제-반증|미분류): R[0-9]+(, R[0-9]+)*)*$' <<EOF
$line
EOF
  then
    warn "\`**잔여 판정**\` reads \`<부류>: R<n>, R<n> / <부류>: R<n>\` with 부류 one of 코드-부재 · 사람-환경 · 외부-준비 · 전제-반증 · 미분류 — this one is \`$line\`: $rec"
    return "$GATE_EXIT_RULE"
  fi
  pairs=$(printf '%s\n' "$line" | awk 'BEGIN { FS = " / " }
    { for (i = 1; i <= NF; i++) { c = $i; sub(/: .*/, "", c); r = $i; sub(/^[^:]*: /, "", r)
        n = split(r, a, ", "); for (j = 1; j <= n; j++) print a[j] " " c } }')
  pair_labs=$(printf '%s\n' "$pairs" | cut -d' ' -f1)
  dup=$(printf '%s\n' "$pair_labs" | sort | uniq -d | sed -n '1p')
  if [ -n "$dup" ]; then
    warn "\`**잔여 판정**\` names $dup more than once: $rec"
    return "$GATE_EXIT_RULE"
  fi
  # G2 — the freeze, on freezable classes only, never a base design's, never a
  # record whose own step calls it a `설계-골격` judgment.
  if [ "$GATE_HALT_REC_LABEL" != "잔여로 두고 동결" ]; then
    warn "a \`/ ladder-unsettled\` record the seat answers recommends \`잔여로 두고 동결\` — this one recommends \`$GATE_HALT_REC_LABEL\`: $rec"
    return "$GATE_EXIT_RULE"
  fi
  while IFS=' ' read -r lab cls; do
    case "$cls" in
      코드-부재|사람-환경|외부-준비) ;;
      *) warn "$lab is \`$cls\` in \`**잔여 판정**\`, so the ladder's freeze is a person's to choose: $rec"
         return "$GATE_EXIT_RULE" ;;
    esac
  done <<EOF
$pairs
EOF
  skill=$(sed -n 's/^\*\*스킬\*\*: //p' "$rec" | sed -n '1p' | sed 's/[[:space:]]*$//')
  if [ "$skill" = "design-base-unattended" ]; then
    warn "a base design's ladder is never frozen without a person — no implement slice of its run owns the residual items: $rec"
    return "$GATE_EXIT_RULE"
  fi
  case "$step" in
    *'설계-골격'*)
      warn "the record's own step calls this a \`설계-골격\` judgment, which only a person answers: $rec"
      return "$GATE_EXIT_RULE" ;;
  esac
  # G3 — against the design document: every label is an open item, every open
  # item without a W3 mark is listed, each class is the document's reading,
  # and each person or external item states `구현 후`.
  doc=${DOC:-}
  if [ -z "$doc" ] || [ ! -f "$doc" ] || [ ! -r "$doc" ]; then
    warn "the manifest's design document cannot be read, so the ladder record cannot be checked against it: ${doc:-(none)}"
    return "$GATE_EXIT_RULE"
  fi
  pend=$(residual_items_pending "$doc")
  while IFS=' ' read -r lab cls; do
    if ! grep -qxF -- "$lab" <<EOF2
$pend
EOF2
    then
      warn "$lab is not an item of the design document still at \`구현 시 검증\`: $rec"
      return "$GATE_EXIT_RULE"
    fi
    if [ "$cls" != "전제-반증" ] && [ "$(residual_item_block_class "$doc" "$lab")" != "$cls" ]; then
      warn "$lab reads \`$(residual_item_block_class "$doc" "$lab")\` in the design document, not \`$cls\`: $rec"
      return "$GATE_EXIT_RULE"
    fi
    case "$cls" in
      사람-환경|외부-준비)
        residual_item_after_explicit "$doc" "$lab" || {
          warn "$lab is \`$cls\` but the design document does not state \`**검증 시점**: 구현 후\` for it, so a freeze would stop the implement stage on it: $rec"
          return "$GATE_EXIT_RULE"; } ;;
    esac
  done <<EOF
$pairs
EOF
  while IFS= read -r lab; do
    [ -n "$lab" ] || continue
    grep -qxF -- "$lab" <<EOF2 && continue
$pair_labs
EOF2
    residual_item_w3_marked "$doc" "$lab" && continue
    warn "$lab is still at \`구현 시 검증\` with no W3 mark, and \`**잔여 판정**\` leaves it out: $rec"
    return "$GATE_EXIT_RULE"
  done <<EOF
$pend
EOF
  # G4 — with two or more implement slices, each item has exactly one owner.
  nslice=$(implement_slice_count "$doc")
  if [ "$nslice" -ge 2 ]; then
    heads=$(defenced "$doc" | awk '/^## /{ inr = ($0 == "## 구현 시 검증 항목") } inr && /^### R[0-9]+/ { s = $0; sub(/[ \t\r]+$/, "", s); print s }')
    while IFS=' ' read -r lab cls; do
      h=$(printf '%s\n' "$heads" | awk -v l="$lab" '{ if (match($0, /^### R[0-9]+/) && substr($0, 5, RLENGTH - 4) == l) { print; exit } }')
      own=0
      for sid in $(slice_ids "$doc"); do
        [ "$(slice_field "$doc" "$sid" '스킬')" = "implement" ] || continue
        [ "$(slice_residual_headings "$doc" "$sid" | grep -cxF -- "$h")" -gt 0 ] && own=$((own + 1))
      done
      if [ "$own" != "1" ]; then
        warn "$lab is owned by $own implement slices' \`**잔여 항목**\` — a frozen item needs exactly one owner: $rec"
        return "$GATE_EXIT_RULE"
      fi
    done <<EOF
$pairs
EOF
  fi
  GATE_HALT_LADDER_STAMP=$(printf '%s\n' "$line" | sed -e 's/: /:/g' -e 's/, /,/g' -e 's| / |/|g')
}

gate_halt_record_tail() {
  # gate_halt_record_tail <record> — the record path from the run directory's
  # own name down, the tail `cc_unanswered_halts` matches `중단 기록=` on. A
  # record outside the run directory is its own tail.
  local rd="${RUN_DIR%/}"
  case "$1" in
    "$rd"/*) printf '/%s/%s' "${rd##*/}" "${1#"$rd"/}" ;;
    *) printf '%s' "$1" ;;
  esac
}

gate_halt_record_returned() {
  # gate_halt_record_returned <record> — `cc_halt_returned` on this run's
  # ledger, so the gate's bound and the watcher read the same answer.
  cc_halt_returned "$LEDGER" "$(gate_halt_record_tail "$1")"
}

gate_bind_escape_cap() {
  # gate_bind_escape_cap — the `상한` of the manifest's `자동 채택` row of class
  # `구속-이탈`, or nothing when `## 인가` carries no such row.
  local row cls
  while IFS= read -r row; do
    [ -n "$row" ] || continue
    cls=$(gate_row_field "$row" '판단 부류')
    [ "$cls" = "구속-이탈" ] || continue
    gate_row_field "$row" '상한'
    printf '\n'
    return 0
  done <<EOF
$(manifest_autoadopt_rows)
EOF
}

gate_halt_auto_answer_admit() {
  # gate_halt_auto_answer_admit <key> <record> <option> — the checks an answer no
  # person gave has to pass, whoever wrote it (the shift's pre-adopted `재수렴`
  # or the seat's copy of a recommendation). A person's answer takes none of
  # them: they may answer the same record twice, and change their mind.
  #
  # TWO CLASSES OF CHECK, AND THEY DO NOT OVERLAP. The bounds here count
  # repeats or read currency — the same record re-converged once, one
  # automatic answer per record, the manifest's `상한`, one automatic adoption
  # per audit key, a record a shift returned — and hold for automatic answers
  # only, each refusing with its own reason line. Routability —
  # whether a branch of the shift can carry the answer out at all — is
  # `gate_halt_answer_route`'s, holds for every writer, a person included, and
  # refuses with `라우팅 불가 — ` and the routable options. So "a person's
  # answer takes no automatic bound" stays true as written, and a person still
  # cannot record an answer no branch can carry out.
  #
  # SAME RECORD, RE-CONVERGED ONCE. A `재수렴` answer to a record whose earlier
  # `재수렴` answer — anyone's — was taken up by a re-convergence that ran goes
  # to a person: the same repair has been tried once and the stage stopped on
  # the same record again. An attempt that ended `크래시`, `한도 종료` or
  # `외부 종료` did nothing with the answer, so it does not count.
  #
  # ONE AUTOMATIC ANSWER PER RECORD, with the same exception. An earlier
  # automatic answer still waiting for its stage is a duplicate; one a stage
  # took up and acted on settles the record for the run.
  #
  # NEVER OVER AN ANSWER STILL WAITING — ANYONE'S, ON THE RECORD OR THE KEY.
  # The seat answers only records nobody has answered yet. A person's answer
  # no stage has taken up is the one the shift must hand on, and the snapshot
  # lists one answer per key — the last row — so an automatic row written
  # after it, to the same record or to another record of the same key, would
  # hand on the recommendation instead and drop the person's choice without a
  # trace. A person may still answer again over anything.
  #
  # THE MANIFEST'S `상한` COUNTS AUTOMATIC `재수렴` ANSWERS PER KEY. `없음` is
  # unbounded and an integer N admits N; a person's `재수렴` never uses up the
  # bound, because the bound is a property of the pre-adoption, not of the
  # key. With no `구속-이탈` row the count has nothing to be compared against
  # and only the two rules above hold.
  local key="$1" rec="$2" opt="$3" r ln row c cls n=0 cap rkey rrec
  local rows
  rows=$( { grep -n "^- \`중단 답\` " "$LEDGER" 2>/dev/null || true; } )
  while IFS= read -r r; do
    [ -n "$r" ] || continue
    ln=${r%%:*}; row=${r#*:}
    rkey=$(gate_row_field "$row" '세그먼트')
    rrec=$(gate_row_field "$row" '중단 기록')
    [ "$rrec" = "$rec" ] || [ "$rkey" = "$key" ] || continue
    c=$(gate_halt_answer_consumer "$LEDGER" "$rkey" "$ln")
    if [ -z "$c" ] && ! gate_halt_answer_is_auto "$row"; then
      warn "a person's answer (ledger line $ln, $rrec) is still waiting for its stage — an automatic answer over it would hand on the recommendation instead of the person's choice: $rec"
      return "$GATE_EXIT_RULE"
    fi
    if [ -z "$c" ] && [ "$rrec" != "$rec" ]; then
      warn "$rkey already has an automatic answer to another record (ledger line $ln, $rrec) that no stage has taken up yet — a second one would hide it: $rec"
      return "$GATE_EXIT_RULE"
    fi
    [ "$rrec" = "$rec" ] || continue
    if [ "$opt" = "재수렴" ] && [ "$(gate_row_field "$row" '선택지')" = "재수렴" ] && [ -n "$c" ]; then
      cls=$(gate_row_field "${c#*:}" '종단 부류')
      if [ "$(gate_row_field "${c#*:}" '종류')" = "reconverge" ]; then
        case "$cls" in
          크래시|'한도 종료'|'외부 종료') ;;
          *) warn "같은 정지 기록을 두 번 재수렴하려면 사람의 답이 필요합니다 — 원장 ${ln} 번째 줄의 \`재수렴\` 답을 ${c%%:*} 번째 줄의 재수렴이 이미 받았습니다: $rec"
             return "$GATE_EXIT_RULE" ;;
        esac
      fi
    fi
    gate_halt_answer_is_auto "$row" || continue
    if [ -z "$c" ]; then
      warn "this halt record already has an automatic answer no stage has taken up yet (ledger line $ln) — a second one would hand the stage two answers: $rec"
      return "$GATE_EXIT_RULE"
    fi
    # The consumer of an answer to a shift's record is usually not a
    # `stage-result` row — the next shift's segment row, act or resolution
    # spends it — so `종단 부류` reads empty and the second automatic answer to
    # that record goes to a person. That is intended: no attempt ended
    # `크래시`, `한도 종료` or `외부 종료` there, so nothing excuses a second one.
    cls=$(gate_row_field "${c#*:}" '종단 부류')
    case "$cls" in
      크래시|'한도 종료'|'외부 종료') ;;
      *) warn "this halt record already had an automatic answer (ledger line $ln) that a stage took up and ended \`${cls:-미상}\` — a second automatic answer goes to a person: $rec"
         return "$GATE_EXIT_RULE" ;;
    esac
  done <<EOF
$rows
EOF
  # A RECORD A SHIFT RETURNED TO A PERSON IS A PERSON'S. The shift could not
  # carry its answer out and said so with a routing block; an automatic answer
  # over it would change the choice before any person saw why it came back.
  if gate_halt_record_returned "$rec"; then
    warn "교대가 이 기록의 답을 사람에게 되돌렸습니다 — 되돌려진 기록에는 사람의 답이 필요합니다: $rec"
    return "$GATE_EXIT_RULE"
  fi
  # ONE AUTOMATIC ADOPTION PER AUDIT KEY. An audit's synthesis question
  # answered `adopt as a requirement` re-converges the document and audits it
  # again; when the key already ran a re-convergence and the audit parked on
  # the synthesis again, the automatic answer would loop the same repair. A
  # re-convergence that ended `크래시`, `한도 종료` or `외부 종료` did nothing
  # with the answer and is not counted — the same exclusion as the record
  # bound above. A person's adoption takes none of this and is routed like the
  # first.
  if [ "$opt" = "adopt as a requirement" ] \
     && [ "$(sed -n 's/^\*\*스킬\*\*: //p' "$rec" 2>/dev/null | sed -n '1p' | sed 's/[[:space:]]*$//')" = "design-audit-unattended" ]; then
    while IFS= read -r r; do
      [ -n "$r" ] || continue
      [ "$(gate_row_field "$r" '종류')" = "reconverge" ] || continue
      cls=$(gate_row_field "$r" '종단 부류')
      case "$cls" in
        크래시|'한도 종료'|'외부 종료') continue ;;
      esac
      warn "같은 감사 키를 두 번 재수렴하려면 사람의 답이 필요합니다 — $key 는 이미 재수렴을 돌렸습니다(실행 버전 $(gate_row_field "$r" '실행 버전'), 종단 부류=${cls:-미상}): $rec"
      return "$GATE_EXIT_RULE"
    done <<EOF
$( { gate_stage_result_rows_of "$key" || true; } )
EOF
  fi
  [ "$opt" = "재수렴" ] || return 0
  cap=$(gate_bind_escape_cap)
  [ -n "$cap" ] || return 0
  case "$cap" in
    없음) return 0 ;;
    *[!0-9]*) warn "the \`구속-이탈\` row's \`상한\` is neither \`없음\` nor a count: $cap"
              return "$GATE_EXIT_RULE" ;;
  esac
  while IFS= read -r r; do
    [ -n "$r" ] || continue
    [ "$(gate_row_field "$r" '세그먼트')" = "$key" ] || continue
    [ "$(gate_row_field "$r" '선택지')" = "재수렴" ] || continue
    gate_halt_answer_is_auto "$r" && n=$((n + 1))
  done <<EOF
$( { gate_rows '중단 답' || true; } )
EOF
  if [ "$n" -ge "$cap" ]; then
    warn "$key already had $n automatic \`재수렴\` answers, and the manifest's \`구속-이탈\` row bounds them at \`상한=$cap\` — the next one goes to a person"
    return "$GATE_EXIT_RULE"
  fi
}

gate_halt_auto_answer_current() {
  # gate_halt_auto_answer_current <key> <record> — an answer no person gave goes
  # only to the key's latest halt, and only once that halt is settled. A
  # person's answer takes none of this: the person reads the record and the run
  # before answering.
  #
  # NOT WHILE AN ATTEMPT OF THE KEY IS STILL OPEN. A stage writes its record and
  # ends its turn, and the supervisor writes the attempt's `stage-result` row
  # only after the CLI exits; the dispatch record `<key>.pid` stays until then,
  # through the window in which the CLI is gone and the row is being written.
  # An automatic answer written in that window is taken up by that very row —
  # the first `stage-result` after it — so it reads as handed on although no
  # stage ever received it. A waiting member of the key is an attempt still to
  # come back, which would take the answer up the same way.
  #
  # ONLY THE ATTEMPT THE KEY LAST SETTLED. The last `stage-result` row of the
  # key has to read `의도된 park`, and the record has to be that attempt's —
  # `halt/<스테이지>#<실행 버전>.md`, or a record whose header names that stage
  # id. The shift re-attaches the key's last session with the answer, so an
  # answer to an older record would resume that session with a question it
  # never asked, and a binding-tier stop the key already moved past would send
  # the document to re-convergence over a decision that no longer stands. An
  # attempt that ended `크래시`, `한도 종료` or `외부 종료` halted nowhere and is
  # passed over, which is what keeps the second answer
  # `gate_halt_auto_answer_admit` allows after such an attempt reachable.
  local key="$1" rec="$2" f row last='' cls ver stg want hst
  for f in "$RUN_DIR/$key.pid" "$RUN_DIR/$key.pid.settling."*; do
    [ -e "$f" ] || continue
    warn "an attempt of $key is still open (its dispatch record $f is still there), so its \`stage-result\` row would take an automatic answer up without any stage receiving it — answer once the attempt has settled: $rec"
    return "$GATE_EXIT_RULE"
  done
  if [ -f "$RUN_DIR/$key.waiting" ] && cc_waiting_is_member "$RUN_DIR" "$LEDGER" "$key"; then
    warn "$key is waiting to come back, and its next attempt would take an automatic answer up — answer once it has settled: $rec"
    return "$GATE_EXIT_RULE"
  fi
  # A SHIFT'S RECORD IS CURRENT BY ITS ROW, since no attempt of the key halted
  # on it: the bytes are still the ones the gate wrote, and nothing on a later
  # line has moved the key past it — no later block anchored on the key, which
  # would be a newer stop, and no later `stage-result` of the key, which would
  # mean the segment ran again after the shift stopped it.
  local srow sln
  srow=$(gate_shift_halt_row_of "$rec")
  if [ -n "$srow" ]; then
    gate_shift_halt_record_intact "$key" "$rec" "$srow" || return "$?"
    sln=${srow%%:*}
    if [ -n "$(LC_ALL=C awk -v l="$sln" -v k="$key" 'NR > l && index($0, "- `blocked` ") == 1 && index($0, "| 앵커 세그먼트=" k " |") { print NR }' "$LEDGER" 2>/dev/null)" ]; then
      warn "a later block is anchored on $key after this shift's record (ledger line $sln), so this record is not the question the key is stopped on — an automatic answer goes only to the key's latest stop: $rec"
      return "$GATE_EXIT_RULE"
    fi
    if [ -n "$( { grep -n -F -e "세그먼트=$key " -e "세그먼트=- | 스테이지=$key | 종류=" "$LEDGER" 2>/dev/null || true; } \
                | { grep "^[0-9]*:- \`stage-result\` " || true; } \
                | awk -F: -v l="$sln" '$1 > l { print $1 }')" ]; then
      warn "$key ran again after this shift's record (a \`stage-result\` follows ledger line $sln), so the record no longer describes where the key stands: $rec"
      return "$GATE_EXIT_RULE"
    fi
    return 0
  fi
  # A file under `halt/shift/` that no shift-halt row vouches for never takes
  # the stage branch below: its header's `stage=<세그먼트>#<n>` could match the
  # key's last attempt and pass by header alone, past the digest and the
  # latest-stop checks above.
  case "$rec" in
    "$RUN_DIR"/halt/shift/*)
      warn "no \`shift-halt\` row of this run wrote this record, so it is not a question this run asked: $rec"
      return "$GATE_EXIT_RULE" ;;
  esac
  local lp
  gate_halt_record_of_last_park "$LEDGER" "$RUN_DIR" "$key" "$rec"
  lp=$?
  cls=$GATE_LAST_PARK_CLASS; want=$GATE_LAST_PARK_STAGE
  case "$lp" in
    0) return 0 ;;
    2) warn "$key's last settled attempt did not halt (\`종단 부류=${cls:-미상}\`), so this record is not the question the key is stopped on — an automatic answer goes only to the key's latest halt: $rec"
       return "$GATE_EXIT_RULE" ;;
  esac
  warn "this record is not the halt of $key's last settled attempt ($want, \`halt/$want.md\`) — an automatic answer goes only to the key's latest halt, and an older one goes to a person: $rec"
  return "$GATE_EXIT_RULE"
}

gate_halt_record_of_last_park() {
  # gate_halt_record_of_last_park <ledger> <run dir> <key> <record> — 0 when
  # <record> is the halt of the attempt the key last settled in <ledger>, and
  # that attempt ended `의도된 park`; 2 when the key's last settled attempt did
  # not halt; 1 when it halted on another record. GATE_LAST_PARK_CLASS holds
  # that attempt's `종단 부류`, GATE_LAST_PARK_STAGE its `<스테이지>#<실행 버전>`
  # and GATE_LAST_PARK_ROW its whole `stage-result` row.
  #
  # ONE DEFINITION FOR THE TWO ANSWERS THAT NEED IT. An automatic answer goes
  # only to the key's latest halt (`gate_halt_auto_answer_current`), and a carry
  # act hands an answer on only when its record is that halt: a fresh session
  # given an answer to an older question would apply a decision the key already
  # moved past. The ledger is an argument so an answer brought over from an
  # earlier run is judged against the run whose attempt halted on it.
  #
  # The record is that attempt's when it is `<run dir>/halt/<스테이지>#<실행
  # 버전>.md`, or when its header names that stage id. An attempt that never
  # spawned (`관측=스폰 전 대기 중`) or ended `크래시`, `한도 종료` or `외부
  # 종료` halted nowhere and is passed over.
  #
  # AN EARLIER RUN'S LEDGER IS READ BY THE KEY ALONE. This run's plan says
  # which kinds a run-scope step id carries here (`gate_stage_result_rows_of`),
  # and a re-kickoff plans its step ids anew, so on another run's ledger every
  # router-shaped row of that step id is the key's, whatever its `종류`.
  local own="${LEDGER:-}"
  local LEDGER="$1" rd="$2" key="$3" rec="$4" row last='' ver stg hst
  GATE_LAST_PARK_CLASS=''; GATE_LAST_PARK_STAGE=''; GATE_LAST_PARK_ROW=''
  while IFS= read -r row; do
    [ -n "$row" ] || continue
    case "$row" in *'| 관측=스폰 전 대기 중'*) continue ;; esac
    case "$(gate_row_field "$row" '종단 부류')" in
      크래시|'한도 종료'|'외부 종료') continue ;;
    esac
    last=$row
  done <<EOF
$( if [ "$LEDGER" = "$own" ]; then
     { gate_stage_result_rows_of "$key" || true; }
   else
     { grep "^- \`stage-result\` " "$LEDGER" 2>/dev/null || true; } \
       | { grep -F -e "세그먼트=$key " -e "세그먼트=- | 스테이지=$key | 종류=" || true; }
   fi )
EOF
  GATE_LAST_PARK_ROW=$last
  GATE_LAST_PARK_CLASS=$(gate_row_field "$last" '종단 부류')
  ver=$(gate_row_field "$last" '실행 버전')
  stg=$(gate_row_field "$last" '스테이지')
  [ -z "$stg" ] || [ -z "$ver" ] || GATE_LAST_PARK_STAGE="$stg#$ver"
  if [ "$GATE_LAST_PARK_CLASS" != "의도된 park" ] || [ -z "$GATE_LAST_PARK_STAGE" ]; then
    return 2
  fi
  [ "$rec" = "$rd/halt/$GATE_LAST_PARK_STAGE.md" ] && return 0
  hst=$(sed -n '1s/^<!-- cc-pipeline-halt v1;.* stage=\([^;]*\);.*/\1/p' "$rec" 2>/dev/null)
  [ "$hst" = "$GATE_LAST_PARK_STAGE" ] && return 0
  return 1
}

# HOW MANY ATTEMPTS THAT CARRIED ONE HALT ANSWER MAY DIE BEFORE A SESSION. The
# next carry of that answer is refused with GATE_EXIT_CARRY_CAP. No count of
# this kind existed: the driver's REDISPATCH_MAX bounds re-attachments that
# carry an approval's answer, at 2, and is a different count.
readonly GATE_CARRY_DEATH_MAX=3

# THE PROMPT A CARRY'S RE-ATTACHMENT RECEIVES in place of the dispatch form. The
# halted session holds the question in its own transcript; the answer is in the
# card its environment names.
readonly GATE_CARRY_RESUME_MESSAGE='멈췄던 스텝의 사람 답이 CC_PIPELINE_HALT_ANSWER 의 답 카드에 있다. 카드를 읽고 기록 다이제스트를 대조한 뒤, 멈췄던 스텝에서 그 답을 적용해 이어 간다. 같은 질문을 다시 묻지 않는다.'

gate_reentry_table() {
  # gate_reentry_table — the closed table of the halts whose answer a fresh
  # session can take up, one row per line:
  # `<스킬>|<**스텝** pattern>|<stage kind>|<dispatch form>`.
  #
  # The form is a fixed frame with named slots. `<문서>` is the document
  # argument the run's own dispatches of that kind carry, and `<범위>` is a
  # re-convergence scope that names a halt record or an `R<n>`. A halt the
  # table does not hold is answered by re-attaching its own session
  # (GATE_EXIT_CARRY_UNTABLED), as before the table existed.
  #
  # A review's halts are not here, and neither are the re-convergence scopes the
  # gate cannot check — a problem identity, `설계 수준 잔여` and `상한 P0 잔여`.
  printf '%s\n' \
    'design-audit-unattended|Step 6*CFI-3b*|audit|/cc-cmds:design-audit-unattended <문서>' \
    'design-reconverge|Step 3*|reconverge|/cc-cmds:design-reconverge <문서> <범위>'
}

gate_halt_record_step() {
  # gate_halt_record_step <record> — the record's first `**스텝**` value.
  sed -n 's/^\*\*스텝\*\*: //p' "$1" 2>/dev/null | sed -n '1p'
}

gate_halt_record_question() {
  # gate_halt_record_question <record> — the record's `**질문 문면**`, from its
  # field line to the next field line, with every run of white space (line
  # breaks included) made one space and the ends trimmed. Two records ask the
  # same question when these are equal: a record's path changes with every
  # attempt, so the path cannot tell a repeated question.
  LC_ALL=C awk '
    !q && index($0, "**질문 문면**:") == 1 { q = 1; s = substr($0, length("**질문 문면**:") + 1); next }
    q && (/^\*\*[^*][^*]*\*\*:/ || index($0, "<!-- /cc-pipeline-halt") == 1) { q = 0; done = 1 }
    q && !done { s = s " " $0 }
    END { gsub(/[ \t\r]+/, " ", s); sub(/^ /, "", s); sub(/ $/, "", s); print s }' "$1" 2>/dev/null
}

gate_halt_card_path() {
  # gate_halt_card_path <key#attempt> — where the answer card of that attempt
  # lives. Not under `halt/`: every reader of that directory takes a file there
  # for a record. Not under `answer/`: that is the approval answers' store.
  printf '%s/halt-answer/%s.md' "$RUN_DIR" "$1"
}

gate_halt_card_line() {
  # gate_halt_card_line <key#attempt> — the `중단 답` ledger line the attempt's
  # card carries, or nothing when the attempt was given no card.
  local c
  c=$(gate_halt_card_path "$1")
  [ -f "$c" ] || return 0
  sed -n 's/^\*\*중단 답 줄\*\*: //p' "$c" 2>/dev/null | sed -n '1p'
}

gate_halt_card_write() {
  # gate_halt_card_write <key#attempt> <line> — write the answer card of the
  # `중단 답` row at ledger <line> for that attempt: the row's line, the record
  # and its digest, the option line as the record wrote it, who answered, the
  # reason and the attachment. The directory is 700 and the file 600, and the
  # file lands by rename so the stage never reads half a card. Written before
  # the launch token, so a stage that starts finds it.
  local stage="$1" ln="$2" row rec opt line att d tmp
  row=$(sed -n "${ln}p" "$LEDGER" 2>/dev/null)
  case "$row" in
    '- `중단 답` '*) ;;
    *) warn "ledger line $ln is not a \`중단 답\` row — no answer card for $stage"; return 1 ;;
  esac
  rec=$(gate_row_field "$row" '중단 기록')
  opt=$(gate_row_field "$row" '선택지')
  line=$( { grep -F -- "- \`$opt\`" "$rec" 2>/dev/null || true; } \
          | LC_ALL=C awk -v l="- \`$opt\`" '$0 == l || index($0, l " — ") == 1 { print; exit }')
  [ -n "$line" ] || line="- \`$opt\`"
  att=$(gate_row_field "$row" '첨부')
  d="$RUN_DIR/halt-answer"
  mkdir -p "$d" && chmod 700 "$d" || { warn "could not make the answer card directory: $d"; return 1; }
  tmp=$(mktemp "$d/.card.XXXXXX") || { warn "could not write the answer card ($stage)"; return 1; }
  chmod 600 "$tmp"
  {
    printf '<!-- cc-halt-answer v1; stage=%s -->\n' "$stage"
    printf '**중단 답 줄**: %s\n' "$ln"
    printf '**중단 기록**: %s\n' "$rec"
    printf '**기록 다이제스트**: %s\n' "$(gate_row_field "$row" '기록 다이제스트')"
    printf '**선택지**:\n%s\n' "$line"
    printf '**답한 주체**: %s\n' "$(gate_halt_answered_by "$row")"
    printf '**근거**: %s\n' "$(gate_row_field "$row" '근거')"
    printf '**첨부**: %s\n' "${att:-(없음)}"
    printf '<!-- /cc-halt-answer v1 -->\n'
  } > "$tmp" && mv -f "$tmp" "$(gate_halt_card_path "$stage")" \
    || { rm -f "$tmp"; warn "could not write the answer card ($stage)"; return 1; }
}

gate_halt_card_crash_line() {
  # gate_halt_card_crash_line <key> — the `중단 답` line to hand again when the
  # key's last attempt carried an answer and ended `크래시`, `한도 종료` or
  # `외부 종료`: that attempt may have died holding the answer, so the next
  # dispatch of the key — a re-attachment or a fresh one — gets the same card
  # under its own attempt. Nothing otherwise.
  local last c
  last=$( { gate_stage_result_rows_of "$1" || true; } | tail -1)
  c=$(gate_row_field "$last" '답 운반')
  [ -n "$c" ] || return 0
  case "$(gate_row_field "$last" '종단 부류')" in
    크래시|'한도 종료'|'외부 종료') printf '%s' "$c" ;;
  esac
}

gate_halt_answer_deferred() {
  # gate_halt_answer_deferred <ledger> <line> — true when <ledger> holds an
  # `이월` row naming the `중단 답` row at <line>: the answer found no room
  # before the deadline, and the next run takes it up. Found by `사유` and
  # `중단 답 줄`, whatever the row's scope.
  local r
  while IFS= read -r r; do
    [ -n "$r" ] || continue
    case "$(gate_row_field "$r" '사유')" in '중단 답 이월 — '*) ;; *) continue ;; esac
    [ "$(gate_row_field "$r" '중단 답 줄')" = "$2" ] && return 0
  done <<EOF
$( { grep "^- \`blocked\` " "$1" 2>/dev/null || true; } | { grep -F '| 사유=중단 답 이월 — ' || true; })
EOF
  return 1
}

gate_halt_answers_by_state() {
  # gate_halt_answers_by_state <이월|열림> — `<line>\t<key>\t<record>`, one line
  # per key, for the answers `answered_halts[]` lists with that `state`: each
  # key's last `중단 답` row no stage has taken up, named by an `이월` row of
  # this run (`이월`) or not (`열림`). The same selection the snapshot makes, so
  # the hand-off checks and the snapshot never disagree on what is carried over.
  local LC_CTYPE=C; export LC_CTYPE
  local want="$1" lines ln row key keys st
  # The completion conditions ask this on every snapshot; a ledger with no
  # `이월` row has nothing carried over, and the walk below is skipped.
  if [ "$want" = "이월" ] && ! grep -qF '| 사유=중단 답 이월 — ' "$LEDGER" 2>/dev/null; then
    return 0
  fi
  lines=$(grep -n "^- \`중단 답\` " "$LEDGER" 2>/dev/null || true)
  [ -n "$lines" ] || return 0
  keys=$(printf '%s\n' "$lines" | while IFS= read -r row; do
           gate_row_field "${row#*:}" '세그먼트'
         done | awk 'NF && !seen[$0]++')
  for key in $keys; do
    row=$( { printf '%s\n' "$lines" | grep -F "| 세그먼트=$key |" || true; } | tail -1)
    [ -n "$row" ] || continue
    ln=${row%%:*}
    row=${row#*:}
    if gate_halt_answer_spent "$LEDGER" "$key" "$ln"; then continue; fi
    if gate_halt_answer_deferred "$LEDGER" "$ln"; then st='이월'; else st='열림'; fi
    [ "$st" = "$want" ] || continue
    printf '%s\t%s\t%s\n' "$ln" "$key" "$(gate_row_field "$row" '중단 기록')"
  done
}

gate_key_deferred_answer() {
  # gate_key_deferred_answer <key> — the `중단 답` line of the key's answer that
  # is carried over to the next run (`gate_halt_answers_by_state 이월`), or
  # nothing.
  gate_halt_answers_by_state '이월' | awk -F '\t' -v k="$1" '$2 == k { print $1 }'
}

gate_carry_source_row() {
  # gate_carry_source_row <earlier ledger> <record> — the earlier run's
  # `중단 답` row that answered <record>, as `<line>:<row>` (the last such row),
  # or nothing. A copy brought into this run names that record as `출처 기록`.
  { grep -n "^- \`중단 답\` " "$1" 2>/dev/null || true; } \
    | { grep -F "| 중단 기록=$2 |" || true; } | tail -1
}

gate_carry_source_last_row() {
  # gate_carry_source_last_row <line> — for the `중단 답` row at <line> of this
  # run that an earlier run's answer was brought in as (`출처 런`), the last
  # attempt of the key it answered in the earlier run's ledger that did not die
  # before or during its session (`gate_halt_record_of_last_park`), or nothing.
  local row src lpl sr
  row=$(sed -n "${1}p" "$LEDGER" 2>/dev/null)
  src=$(gate_row_field "$row" '출처 런')
  [ -n "$src" ] || return 0
  lpl="$(dirname "$LEDGER")/$src.md"
  sr=$(gate_carry_source_row "$lpl" "$(gate_row_field "$row" '출처 기록')")
  [ -n "$sr" ] || return 0
  gate_halt_record_of_last_park "$lpl" "$(dirname "$RUN_DIR")/$src" \
    "$(gate_row_field "${sr#*:}" '세그먼트')" "$(gate_row_field "$row" '출처 기록')" >/dev/null 2>&1 || true
  printf '%s' "$GATE_LAST_PARK_ROW"
}

gate_key_imported_deferred_answer() {
  # gate_key_imported_deferred_answer <key> — the `중단 답` line of this run
  # holding an answer brought over from an earlier run that the earlier run
  # carried over to the next run (an `이월` row of its ledger names it), when
  # no stage of this run has taken it up yet; nothing otherwise. Adopted and
  # re-kickoff copies alike: the key's last `중단 답` row carries `출처 런` and
  # `출처 기록`, and the earlier ledger's row for that record is deferred there.
  local row ln src sr
  row=$( { grep -n "^- \`중단 답\` " "$LEDGER" 2>/dev/null || true; } \
         | { grep -F "| 세그먼트=$1 |" || true; } | tail -1)
  [ -n "$row" ] || return 0
  ln=${row%%:*}
  row=${row#*:}
  src=$(gate_row_field "$row" '출처 런')
  [ -n "$src" ] || return 0
  gate_halt_answer_spent "$LEDGER" "$1" "$ln" && return 0
  sr=$(gate_carry_source_row "$(dirname "$LEDGER")/$src.md" "$(gate_row_field "$row" '출처 기록')")
  [ -n "$sr" ] || return 0
  gate_halt_answer_deferred "$(dirname "$LEDGER")/$src.md" "${sr%%:*}" || return 0
  printf '%s' "$ln"
}

gate_defer_handoff_unmet() {
  # gate_defer_handoff_unmet — the first reason a `handoff 사유=이월` cannot be
  # taken now, or nothing when it can. The hand-off's own `CI 대기` field is
  # the fifth condition and the caller's to check; the other four are the
  # run's: no live stage or supervisor (they are still what the run waits on),
  # no halt record no row answers (that is a question to a person, so the
  # shift hands off `중단`), at least one answer carried over (otherwise there
  # is nothing to hand to the next run), and no ending (a run that has ended
  # hands off `종단`).
  if [ -n "$(cc_relay_wait_stages "$RUN_DIR")" ]; then
    printf '살아 있는 스테이지나 감독자가 있습니다 — 기다릴 것이 있으면 사유=대기 입니다'; return 0
  fi
  if [ "$(cc_unanswered_halts "$RUN_DIR" "$LEDGER")" != "0" ]; then
    printf '답 없는 정지 기록이 있습니다 — 사람에게 묻는 것이므로 사유=중단 입니다'; return 0
  fi
  if [ -z "$(gate_halt_answers_by_state '이월')" ]; then
    printf '다음 런으로 넘긴 중단 답이 없습니다'; return 0
  fi
  if [ -s "$RUN_DIR/done" ] || [ -n "$(gate_end_token)" ]; then
    printf '런이 이미 끝났습니다 — 사유=종단 입니다'; return 0
  fi
}

gate_defer_only_left() {
  # gate_defer_only_left — succeeds when nothing but answers carried over to
  # the next run holds the run. The ending of such a run past its deadline
  # (`gate_defer_end_ready`) and re-ask guard 1 of the `중단` hand-off read
  # this one judgment: were they two, a run past its deadline whose ending
  # does not hold would refuse its `이월` hand-off and its `중단` alike.
  #
  # All of: no live stage or supervisor; no halt record no row answers; at
  # least one answer carried over (`이월`) and none still open (`열림`); no
  # pending act approval and no pending person-set question — any other
  # question is an input the next run consumes, the same reason termination
  # condition 2 leaves it out; no run-holding `blocked` row left unresolved but
  # the `이월` rows themselves (a run-scope halt writes no halt record, and a
  # carry's cap writes a `blocked` row on a key whose answer was already
  # given); and every segment terminal and not waiting to be applied, or
  # waiting on its own carried-over answer. A segment waiting on CI or left to
  # merge is not terminal, so a run that can still do that past its deadline
  # without a stage is not one the next run takes over by its answers.
  local cause why sid st
  [ -z "$(cc_relay_wait_stages "$RUN_DIR")" ] || return 1
  [ "$(cc_unanswered_halts "$RUN_DIR" "$LEDGER")" = "0" ] || return 1
  [ -n "$(gate_halt_answers_by_state '이월')" ] || return 1
  [ -z "$(gate_halt_answers_by_state '열림')" ] || return 1
  [ -z "$(gate_pending_approval_ids act)" ] || return 1
  [ -z "$(gate_pending_approval_ids 사람)" ] || return 1
  while IFS="$(printf '\t')" read -r cause why; do
    [ -n "$why" ] || continue
    case "$why" in '중단 답 이월 — '*) continue ;; esac
    return 1
  done <<EOF
$(cc_unresolved_blocked "$LEDGER" 2>/dev/null)
EOF
  for sid in $(gate_segment_ids); do
    [ -n "$sid" ] || continue
    gate_step_deferred_line "$sid" >/dev/null && continue
    gate_segment_apply_pending "$sid" && return 1
    st=$(gate_segment_field "$sid" '상태')
    case " $TERMINAL_SEGMENT_STATES " in
      *" $st "*) ;;
      *) return 1 ;;
    esac
  done
  return 0
}

gate_text_names_file() {
  # gate_text_names_file <text> <name> — true when <name> appears in <text> at a
  # token boundary: the bytes on either side are not a letter, a digit or one of
  # `. _ # -`. A record's file name in a sentence is followed by a particle
  # (`A#1.md를`) or punctuation, and neither is part of the name; a name that is
  # only part of a longer token (`A#1.md.bak`, `xA#1.md`) is not that file.
  T="$1" N="$2" LC_ALL=C awk 'BEGIN {
    t = ENVIRON["T"]; n = ENVIRON["N"]; off = 0
    if (n == "") exit 1
    while ((i = index(substr(t, off + 1), n)) > 0) {
      p = off + i
      pre = (p > 1) ? substr(t, p - 1, 1) : ""
      post = substr(t, p + length(n), 1)
      if (pre !~ /[A-Za-z0-9._#-]/ && post !~ /[A-Za-z0-9._#-]/) exit 0
      off = p
    }
    exit 1
  }'
}

gate_text_names_deferred() {
  # gate_text_names_deferred <text> — the first record carried over to the next
  # run that <text> names, by its path or by its file name at a token boundary
  # (`gate_text_names_file`), or nothing. The file name's stem counts too when
  # it carries the attempt mark `#`, which no ordinary word does; a bare stem
  # such as a one-letter segment id is not looked for, so a sentence that uses
  # the letter as a word is not taken for the record.
  local ln key rec b stem
  while IFS="$(printf '\t')" read -r ln key rec; do
    [ -n "$rec" ] || continue
    case "$1" in *"$rec"*) printf '%s' "$rec"; return 0 ;; esac
    b=${rec##*/}
    if gate_text_names_file "$1" "$b"; then printf '%s' "$rec"; return 0; fi
    stem=${b%.md}
    case "$stem" in
      *'#'*) if gate_text_names_file "$1" "$stem"; then printf '%s' "$rec"; return 0; fi ;;
    esac
  done <<EOF
$(gate_halt_answers_by_state '이월')
EOF
}

gate_carry_cap_row() {
  # gate_carry_cap_row <alias> <key> <stage kind> <사유> <line> <basis> — the
  # act-scope row a carry refused by its cap leaves before GATE_EXIT_CARRY_CAP.
  # The answer stays where it is; a person reads this row and the record.
  #
  # ONE ROW PER ANSWER AND CAUSE. The cap counts what is already on the
  # ledger, so a later shift that carries the same answer again is refused
  # again on the same count; it writes no second row for it.
  local rowseg
  if [ -n "$( { grep '^- `blocked` ' "$LEDGER" 2>/dev/null || true; } \
              | { grep -F "| 스코프=act | 원인=막힘 | 사유=$4 | 중단 답 줄=$5 | " || true; })" ]; then
    warn "$4 — $2 는 파견하지 않습니다 (상한 행은 이미 있습니다)"
    return 0
  fi
  rowseg=$(gate_stage_row_segment "$2" "$3")
  gate_append 'blocked' "대상=$1" "스코프=act" "원인=막힘" "사유=$4" "중단 답 줄=$5" \
    "세그먼트=$rowseg" "스테이지=$2" "근거=$(gate_row_safe "$6" 300)" "관측=$(now_iso)" \
    "재개 명령=사람이 이 정지 기록과 답을 다시 본다 — 운반을 되풀이하지 않는다" \
    || warn "could not write the carry cap row ($2)"
  warn "$4 — $2 는 파견하지 않습니다"
}

gate_carry_defer_row() {
  # gate_carry_defer_row <alias> <row segment> <key> <lineage> <line> <observed>
  # — the `이월` row: a carry that found no room before the deadline keeps its
  # answer for the next run instead of writing the ordinary deadline row. The
  # shape is the deadline park's cone row with four fields of its own; a cone
  # the gate refuses (a run-scope key with no `segment` row) falls back to the
  # act scope with the same four fields, so every reader finds it by `사유` and
  # `중단 답 줄` and never by its scope.
  local alias="$1" rowseg="$2" key="$3" lin="$4" ln="$5" obs="$6" rc=0
  local why='중단 답 이월 — 마감 안에 자리 없음'
  local redo='다음 런이 이 답을 이어받는다 — 다시 묻지 않는다'
  gate_record_cone "$alias" "스코프=cone" "원인=막힘" "사유=$why" "중단 답 줄=$ln" \
    "앵커 세그먼트=$key" "세그먼트=$rowseg" "스테이지=$key" \
    "근거=계보=$lin" "관측=$(gate_row_safe "$obs" 300)" \
    "재개 명령=$(gate_row_safe "$redo" 360)" || rc=$?
  if [ "$rc" != "0" ]; then
    warn "the carry-over cone row was refused (rc=$rc) — an act-scope row stands in ($key)"
    gate_append 'blocked' "대상=$alias" "스코프=act" "원인=막힘" "사유=$why" "중단 답 줄=$ln" \
      "세그먼트=$rowseg" "스테이지=$key" "근거=계보=$lin" "관측=$(gate_row_safe "$obs" 300)" \
      "재개 명령=$(gate_row_safe "$redo" 360)" \
      || warn "could not write the carry-over row ($key)"
  fi
  warn "중단 답 이월 — $key 는 마감 안에 자리가 없어 원장 ${ln} 번째 줄의 답을 다음 런으로 넘깁니다"
}

gate_carry_check() {
  # gate_carry_check <alias> <key> <stage kind> <prompt> — the checks a carry
  # act (`--carry-answer <line>`) passes before anything about the dispatch is
  # written. On success GATE_HA_LINE holds the line and GATE_HA_BOUND the session
  # of the key's halted attempt in this run, or nothing when there is none to
  # re-attach. Every refusal but two writes no row: GATE_EXIT_RULE for an answer
  # that is not this dispatch's to carry, and GATE_EXIT_CARRY_UNTABLED for a
  # halt the re-entry table does not hold. The two cap refusals write their row
  # and end GATE_EXIT_CARRY_CAP.
  #
  # AN ANSWER ANOTHER ITEM OF THE SHIFT CONTRACT ROUTES IS NOT CARRIED, so a
  # shift that picks the wrong branch cannot hand it to a fresh session: an
  # audit's adopted requirement and a binding-tier stop's `재수렴` go to
  # re-convergence, a review's empty-target halt and a shift's own record are
  # carried out by the shift, and a `좌석 실행` halt by the seat.
  #
  # THE RECORD IS THE KEY'S LATEST HALT, judged by the same helper the automatic
  # answers use. An answer brought over from an earlier run is judged against
  # that run's ledger, where its attempt halted.
  local alias="$1" key="$2" skind="$3" prompt="$4" ln="$GATE_CARRY_ANSWER"
  local row rec skill opt step s1 dig cur src lp lpl lprd lprec skey adrow
  local tskill tglob tkind frame found=0 doc head scope pm prec n r
  GATE_HA_LINE=''; GATE_HA_BOUND=''; GATE_HA_SCOPE=''
  row=$(sed -n "${ln}p" "$LEDGER" 2>/dev/null)
  case "$row" in
    '- `중단 답` '*) ;;
    *) warn "원장 ${ln} 번째 줄은 중단 답 행이 아닙니다 — --carry-answer 는 스냅숏 answered_halts[] 의 line 값을 받습니다"
       return "$GATE_EXIT_RULE" ;;
  esac
  if [ "$(gate_row_field "$row" '세그먼트')" != "$key" ]; then
    warn "원장 ${ln} 번째 줄의 답은 키 $(gate_row_field "$row" '세그먼트') 의 것이라 $key 파견에 싣지 않습니다"
    return "$GATE_EXIT_RULE"
  fi
  rec=$(gate_row_field "$row" '중단 기록')
  skill=$(gate_row_field "$row" '스킬')
  opt=$(gate_row_field "$row" '선택지')
  if [ -z "$rec" ] || [ ! -f "$rec" ]; then
    warn "답한 중단 기록이 없습니다 — 운반하지 않습니다: ${rec:-(없음)}"
    return "$GATE_EXIT_RULE"
  fi
  step=$(gate_halt_record_step "$rec")
  s1="${step%% — *}"
  case "$rec" in
    "$RUN_DIR"/halt/shift/*)
      warn "교대 정지 기록의 답은 교대가 그 선택지를 스스로 수행합니다 — 운반하지 않습니다: $rec"
      return "$GATE_EXIT_RULE" ;;
  esac
  case "$step" in
    'Step 3 잔여 검증 좌석 실행'*|'Step 3 게이트 도달 좌석 실행'*)
      warn "좌석 실행 정지는 좌석이 실행한 뒤 그 세션에 재부착합니다 — 운반하지 않습니다: $rec"
      return "$GATE_EXIT_RULE" ;;
  esac
  if [ "$skill" = "design-audit-unattended" ] && [ "${step#*CFI-3b}" != "$step" ] \
     && [ "$opt" = "adopt as a requirement" ]; then
    warn "감사 종합 요구를 채택한 답은 재수렴으로 갑니다 — 운반하지 않습니다: $rec"
    return "$GATE_EXIT_RULE"
  fi
  if [ "$skill" = "implement-unattended" ] && [ "${s1#*CFI-U3 BT-STOP}" != "$s1" ] \
     && [ "$opt" = "재수렴" ]; then
    warn "구속 티어 이탈 정지의 재수렴 답은 재수렴으로 갑니다 — 운반하지 않습니다: $rec"
    return "$GATE_EXIT_RULE"
  fi
  if [ "$skill" = "review-unattended" ]; then
    case "$step" in
      'Step 1b 빈 대상'*)
        warn "리뷰의 빈 대상 정지 답은 교대가 그 선택지대로 처리합니다 — 운반하지 않습니다: $rec"
        return "$GATE_EXIT_RULE" ;;
    esac
  fi
  if gate_halt_answer_spent "$LEDGER" "$key" "$ln"; then
    warn "원장 ${ln} 번째 줄의 답은 이미 스테이지가 받았습니다 — 다시 운반하지 않습니다"
    return "$GATE_EXIT_RULE"
  fi
  if [ -n "$(LC_ALL=C awk -v l="$ln" -v k="| 세그먼트=$key |" 'NR > l && index($0, "- `중단 답` ") == 1 && index($0, k) { print NR }' "$LEDGER" 2>/dev/null)" ]; then
    warn "$key 에는 원장 ${ln} 번째 줄 뒤에 쓴 답이 있습니다 — 나중 답을 운반하세요"
    return "$GATE_EXIT_RULE"
  fi
  if gate_halt_answer_deferred "$LEDGER" "$ln"; then
    warn "원장 ${ln} 번째 줄의 답은 이 런에서 이미 이월됐습니다 — 다음 런이 이어받으며, 이 런에서는 다시 운반하지 않습니다"
    return "$GATE_EXIT_RULE"
  fi
  dig=$(gate_row_field "$row" '기록 다이제스트')
  cur=$( { shasum -a 256 "$rec" 2>/dev/null || true; } | cut -d' ' -f1)
  if [ -z "$dig" ] || [ "$cur" != "$dig" ]; then
    warn "중단 기록이 답한 뒤에 바뀌었습니다 (기록 다이제스트 ${dig:-없음}, 지금 ${cur:-읽을 수 없음}) — 운반하지 않습니다: $rec"
    return "$GATE_EXIT_RULE"
  fi
  src=$(gate_row_field "$row" '출처 런')
  if [ -n "$src" ]; then
    lpl="$(dirname "$LEDGER")/$src.md"; lprd="$(dirname "$RUN_DIR")/$src"
    lprec=$(gate_row_field "$row" '출처 기록')
    # The key the earlier run halted on: the key of the earlier row that
    # answered the record — a re-kickoff plans its step ids anew, and an answer
    # carried over twice names the run the person answered in, not the run the
    # segment was adopted from — or, without that row, the adopted segment's
    # earlier key.
    skey=$key
    r=$(gate_carry_source_row "$lpl" "$lprec")
    if [ -n "$r" ]; then
      skey=$(gate_row_field "${r#*:}" '세그먼트')
    elif adrow=$(gate_adoption_row "$key" 2>/dev/null); then
      skey=$(gate_adoption_source_key "$adrow")
    fi
    if [ ! -f "$lpl" ] || [ -z "$lprec" ] \
       || [ "$( { shasum -a 256 "$lprec" 2>/dev/null || true; } | cut -d' ' -f1)" != "$dig" ]; then
      warn "출처 런 ${src} 의 기록이 사본과 같지 않거나 읽을 수 없습니다 — 운반하지 않습니다: ${lprec:-(없음)}"
      return "$GATE_EXIT_RULE"
    fi
  else
    lpl=$LEDGER; lprd=$RUN_DIR; lprec=$rec; skey=$key
  fi
  lp=0
  gate_halt_record_of_last_park "$lpl" "$lprd" "$skey" "$lprec" || lp=$?
  if [ "$lp" != "0" ]; then
    warn "이 기록은 $key 의 마지막 의도된 park 시도(${GATE_LAST_PARK_STAGE:-없음}, 종단 부류=${GATE_LAST_PARK_CLASS:-미상})의 기록이 아닙니다 — 운반하지 않습니다: $rec"
    return "$GATE_EXIT_RULE"
  fi
  while IFS='|' read -r tskill tglob tkind frame; do
    [ -n "$tskill" ] || continue
    [ "$tskill" = "$skill" ] || continue
    # shellcheck disable=SC2254
    case "$step" in $tglob) found=1; break ;; esac
  done <<EOF
$(gate_reentry_table)
EOF
  if [ "$found" != "1" ]; then
    warn "재진입 표에 없는 정지입니다 (스킬 ${skill:-미상}, 스텝 ${step:-없음}) — 멈춘 세션을 --resume 으로 재부착하세요"
    return "$GATE_EXIT_CARRY_UNTABLED"
  fi
  if [ "$tkind" != "$skind" ]; then
    warn "이 정지의 답은 ${tkind} 파견으로 운반합니다 — 받은 스테이지 종류는 ${skind:-없음} 입니다"
    return "$GATE_EXIT_RULE"
  fi
  case "$tkind" in
    reconverge) doc=$(gate_doc_arg_path) ;;
    *) doc=${DOC:-} ;;
  esac
  # The frame is filled by splitting, never by `${var/pat/rep}`: a document path
  # with `&` in it would be rewritten by the replacement under newer shells.
  head="${frame%%<문서>*}$doc${frame#*<문서>}"
  if [ "${frame%<범위>}" = "$frame" ]; then
    if [ "$prompt" != "$head" ]; then
      warn "운반 act 의 프롬프트는 재진입 표의 틀 그대로여야 합니다 — 「${head}」"
      return "$GATE_EXIT_RULE"
    fi
  else
    head=${head% <범위>}
    case "$prompt" in
      "$head "?*) scope=${prompt#"$head "} ;;
      *) warn "운반 act 의 프롬프트는 재진입 표의 틀 그대로여야 합니다 — 「${head} <범위>」"
         return "$GATE_EXIT_RULE" ;;
    esac
    case "$scope" in
      *$'\n'*) warn "운반 act 의 범위는 한 줄입니다"; return "$GATE_EXIT_RULE" ;;
    esac
    if ! gate_carry_scope_ok "$skey" "$scope" "$lpl" "$lprd" "$rec" "$ln"; then
      return "$GATE_EXIT_CARRY_UNTABLED"
    fi
    GATE_HA_SCOPE=$scope
  fi
  # THE SAME QUESTION AGAIN. The attempt that halted on this record carried an
  # answer itself, and it stopped on the same step with the same question —
  # handing the new answer on would go round the same loop with no person.
  pm=$(gate_row_field "$GATE_LAST_PARK_ROW" '답 운반')
  if [ -n "$pm" ]; then
    prec=$(gate_row_field "$(sed -n "${pm}p" "$lpl" 2>/dev/null)" '중단 기록')
    if [ -n "$prec" ] && [ -f "$prec" ] && [ "$(gate_halt_record_step "$prec")" = "$step" ] \
       && [ "$(gate_halt_record_question "$prec")" = "$(gate_halt_record_question "$rec")" ]; then
      gate_carry_cap_row "$alias" "$key" "$skind" "중단 답 라우팅 — 새 파견이 같은 질문에 다시 멈췄다" "$ln" \
        "원장 ${pm} 번째 줄의 답을 받은 시도 ${GATE_LAST_PARK_STAGE} 가 같은 스텝과 같은 질문 문면으로 다시 멈췄다: $rec"
      return "$GATE_EXIT_CARRY_CAP"
    fi
  fi
  # THE ANSWER'S PRE-SESSION DEATHS. An attempt that died before its session
  # started never read the card, so it did not spend the answer; three of them
  # mean the dispatch itself is what fails. Such a death is either a crash with
  # `세션 id=미상` or a waiter whose supervisor vanished before the spawn
  # (`관측=스폰 전 대기 중`, written with `세션 id=-` by the waiter settlement).
  n=0
  while IFS= read -r r; do
    [ -n "$r" ] || continue
    [ "$(gate_row_field "$r" '답 운반')" = "$ln" ] || continue
    gate_row_is_pre_session_death "$r" && n=$((n + 1))
  done <<EOF
$( { gate_stage_result_rows_of "$key" || true; } )
EOF
  if [ "$n" -ge "$GATE_CARRY_DEATH_MAX" ]; then
    gate_carry_cap_row "$alias" "$key" "$skind" "중단 답 라우팅 — 세션 전에 세 번 죽었다" "$ln" \
      "원장 ${ln} 번째 줄의 답을 실은 시도가 세션이 생기기 전에 ${n} 번 죽었다: $rec"
    return "$GATE_EXIT_CARRY_CAP"
  fi
  if [ -z "$src" ]; then
    r=$(gate_row_field "$GATE_LAST_PARK_ROW" '세션 id')
    if run_session_id_shape_ok "$r"; then GATE_HA_BOUND=$r; fi
  fi
  GATE_HA_LINE=$ln
  return 0
}

gate_halt_record_detail() {
  # gate_halt_record_detail <record> — the record's `**관측 상세**` value, its
  # continuation lines joined with single spaces, the way the question is read.
  awk '
    !q && index($0, "**관측 상세**:") == 1 { q = 1; s = substr($0, length("**관측 상세**:") + 1); next }
    q && (/^\*\*[^*][^*]*\*\*:/ || index($0, "<!-- /cc-pipeline-halt") == 1) { q = 0; done = 1 }
    q && !done { s = s " " $0 }
    END { gsub(/[ \t\r]+/, " ", s); sub(/^ /, "", s); sub(/ $/, "", s); print s }' "$1" 2>/dev/null
}

gate_detail_hex() {
  # gate_detail_hex <관측 상세> <name> — the 64-hex value of `<name>=` in that
  # detail, where the name starts the detail or follows a space or `·`, or
  # nothing.
  printf '%s\n' "$1" | sed 's/·/ /g' | LC_ALL=C awk -v n=" $2=" '
    {
      s = " " $0 " "
      while ((i = index(s, n)) > 0) {
        v = substr(s, i + length(n), 64)
        if (v ~ /^[0-9a-f]+$/ && length(v) == 64 && substr(s, i + length(n) + 64, 1) == " ") { print v; exit }
        s = substr(s, i + length(n))
      }
    }'
}

gate_doc_key_of() {
  # gate_doc_key_of <document> — the document key of `_common/sidecar.md`
  # §1.1: the path relative to the repository root found from the document's
  # own directory, or the absolute path without its leading `/` when no root
  # holds it.
  local doc="$1" dir top phys
  dir=$(dirname "$doc")
  phys="$(cd "$dir" 2>/dev/null && pwd -P)/$(basename "$doc")"
  top=$(cd "$dir" 2>/dev/null && git --no-optional-locks rev-parse --show-toplevel 2>/dev/null) || top=""
  case "$phys" in
    "$top"/*) [ -n "$top" ] && { printf '%s' "${phys#"$top"/}"; return 0; } ;;
  esac
  printf '%s' "${doc#/}"
}

gate_reconverge_carrier_path() {
  # gate_reconverge_carrier_path <document> — `<base>/docs/design-reconverge/
  # {slug}.md` for that document, by `_common/sidecar.md` §1.1: `<base>` is
  # the main worktree root of the repository holding the document, or the
  # document's own directory when none does.
  local doc="$1" dir key base cg slug
  dir=$(dirname "$doc")
  key=$(gate_doc_key_of "$doc")
  base=$dir
  if [ "$key" != "${doc#/}" ]; then
    cg=$(cd "$dir" 2>/dev/null && git --no-optional-locks rev-parse --path-format=absolute --git-common-dir 2>/dev/null) || cg=""
    [ -z "$cg" ] || base=$(dirname "$cg")
  fi
  slug=${key%.md}
  slug=$(printf '%s' "$slug" | tr '/' '-')
  printf '%s/docs/design-reconverge/%s.md' "$base" "$slug"
}

gate_reconverge_block_waiting() {
  # gate_reconverge_block_waiting <document> <R<n>> — true when the document's
  # re-convergence carrier is whole (its last non-empty line outside a fence is
  # the terminator), belongs to that document (`owner-doc=` on its second line
  # is the document key) and holds a `## 회차` block whose `대상 항목` names
  # that item and whose `상태` is `대기`. Fence-aware: inside an open fence no
  # line is a heading or a field.
  local f key
  f=$(gate_reconverge_carrier_path "$1")
  key=$(gate_doc_key_of "$1")
  [ -f "$f" ] || return 1
  case "$(sed -n '2p' "$f" 2>/dev/null)" in *"owner-doc=$key;"*) ;; *) return 1 ;; esac
  LC_ALL=C awk -v item="§구현 시 검증 항목 $2 — " '
    function close_block() { if (inb && st == "대기" && it) found = 1 }
    /^[[:space:]]*```/ { fence = !fence; if (!fence) last = $0; next }
    fence { next }
    /^[[:space:]]*$/ { next }
    { last = $0 }
    /^## 회차 [0-9]+[[:space:]]*$/ { close_block(); inb = 1; st = ""; it = 0; next }
    inb && index($0, "**상태**: ") == 1 { st = substr($0, length("**상태**: ") + 1); sub(/[[:space:]]+$/, "", st) }
    inb && index($0, "**대상 항목**: " item) == 1 { it = 1 }
    END { close_block(); exit !(found && !fence && last == "<!-- cc-design-reconverge: end -->") }' "$f"
}

gate_carry_scope_answer() {
  # gate_carry_scope_answer <ledger> <key> <before line> — the answer a
  # re-convergence on <key> took its scope from: walking <ledger> back from
  # <before line>, past the answers handed to re-convergence attempts, the
  # first `중단 답` row of the key whose `스킬` is not `design-reconverge` and
  # which a stage took up. Printed as `<스킬><TAB><중단 기록>`, or nothing.
  local l row
  for l in $(LC_ALL=C awk -v lim="$3" -v k="| 세그먼트=$2 |" \
               'NR < lim && index($0, "- `중단 답` ") == 1 && index($0, k) { print NR }' "$1" 2>/dev/null | sort -rn); do
    row=$(sed -n "${l}p" "$1" 2>/dev/null)
    [ "$(gate_row_field "$row" '스킬')" != design-reconverge ] || continue
    gate_halt_answer_spent "$1" "$2" "$l" || continue
    printf '%s\t%s' "$(gate_row_field "$row" '스킬')" "$(gate_row_field "$row" '중단 기록')"
    return 0
  done
  return 1
}

gate_carry_scope_ok() {
  # gate_carry_scope_ok <key> <scope> <ledger> <run dir> <record> <answer line>
  # — whether a re-convergence carry's `<범위>` slot names the scope the halted
  # attempt worked on, measured where the gate can measure it. <ledger> is the
  # one the halted attempt ran in (an adopted answer's `출처 런` ledger), and
  # <answer line> bounds the walk in this run's own ledger.
  #
  # THE RECORD CARRIES THE STEP 1 BASELINES. The fresh session compares against
  # `사전 sha256` and `사전 구속 표면 다이제스트` from the record rather than a
  # hash taken now, because the halted attempt may already have edited the
  # document; a record without both is outside the table.
  #
  # THE TWO SHAPES WITH A RECORD are checked against the ledger: walking back
  # past the answers handed to re-convergence attempts, the first answer a stage
  # took up whose skill is not `design-reconverge` is the one that started this
  # re-convergence, and its record is the scope's record. `감사 종합 요구` is an
  # audit's answer and `구속 티어 이탈` an implement stage's.
  #
  # `R<n>` is checked against the carrier and the record: the block naming the
  # item is still `대기` (a finished re-convergence closes it), and the record
  # says it worked on that item (`범위=R<n>`). A problem identity, `설계 수준
  # 잔여` and `상한 P0 잔여` are outside the table — nothing the gate can read
  # says which scope the halted attempt had.
  local key="$1" scope="$2" led="$3" rec="$5" ln="$6" det lim got want
  det=$(gate_halt_record_detail "$rec")
  if [ -z "$(gate_detail_hex "$det" '사전 sha256')" ] || [ -z "$(gate_detail_hex "$det" '사전 구속 표면 다이제스트')" ]; then
    warn "재수렴 정지 기록의 관측 상세에 사전 sha256 과 사전 구속 표면 다이제스트가 모두 있어야 새 세션에 운반합니다 — 멈춘 세션을 --resume 으로 재부착하세요: $rec"
    return 1
  fi
  case "$scope" in
    '감사 종합 요구 /'*|'구속 티어 이탈 /'*)
      case "$scope" in
        '감사 종합 요구 '*) want=design-audit-unattended ;;
        *) want=implement-unattended ;;
      esac
      lim=999999999
      [ "$led" != "${LEDGER:-}" ] || lim=$ln
      got=$(gate_carry_scope_answer "$led" "$key" "$lim") || got=""
      if [ "$got" != "$want"$'\t'"${scope#* * * }" ]; then
        warn "재수렴 범위가 이 키를 재수렴으로 보낸 답과 다릅니다 (범위 「${scope}」, 원장의 답 「$(printf '%s' "${got:-없음}" | tr '\t' ' ')」) — 멈춘 세션을 --resume 으로 재부착하세요"
        return 1
      fi
      ;;
    R[0-9]*)
      case "${scope#R}" in
        *[!0-9]*) warn "재진입 표가 검사할 수 없는 재수렴 범위입니다 — 멈춘 세션을 --resume 으로 재부착하세요: $scope"; return 1 ;;
      esac
      case " $(printf '%s' "$det" | sed 's/·/ /g') " in
        *" 범위=$scope "*) ;;
        *) warn "재수렴 정지 기록의 관측 상세가 범위=$scope 를 싣지 않습니다 — 멈춘 세션을 --resume 으로 재부착하세요: $rec"
           return 1 ;;
      esac
      if ! gate_reconverge_block_waiting "$(gate_doc_arg_path)" "$scope"; then
        warn "재수렴 운반 블록에 대기 중인 $scope 블록이 없습니다 — 멈춘 세션을 --resume 으로 재부착하세요: $(gate_reconverge_carrier_path "$(gate_doc_arg_path)")"
        return 1
      fi
      ;;
    *) warn "재진입 표가 검사할 수 없는 재수렴 범위입니다 — 멈춘 세션을 --resume 으로 재부착하세요: $scope"
       return 1 ;;
  esac
  return 0
}

gate_halt_settle_line_parse() {
  # gate_halt_settle_line_parse <option line> — the machine settlement line of a
  # re-convergence halt, read strictly. On success prints `<path><TAB><64 hex>
  # <TAB><verdict>` and returns 0; any other line returns 1 with nothing printed.
  #
  #   - `<label>` — 검사 sha256 <absolute document path>=<64 hex> → 종단 재설계 필요|불필요
  #
  # THE WHOLE OPTION LINE IS THE GRAMMAR. A re-convergence that prepared its
  # edit and computed its verdict before stopping already knows what the answer
  # leads to: the document has to hash to one value, and the verdict is fixed.
  # Nothing else may ride on the line — a trailing word, a relative path, a
  # verdict outside the two, a value that is not 64 lowercase hex — because the
  # gate writes the verdict into a row without a session to read it again.
  local line="$1" rest label body left hex path verd
  case "$line" in
    '- `'*) ;;
    *) return 1 ;;
  esac
  rest=${line#'- `'}
  case "$rest" in
    *'` — '*) ;;
    *) return 1 ;;
  esac
  label=${rest%%'` — '*}
  body=${rest#*'` — '}
  case "$label" in ''|*'`'*) return 1 ;; esac
  case "$body" in
    '검사 sha256 '*) body=${body#'검사 sha256 '} ;;
    *) return 1 ;;
  esac
  case "$body" in
    *' → 종단 '*' → 종단 '*) return 1 ;;
    *' → 종단 '*) ;;
    *) return 1 ;;
  esac
  left=${body%%' → 종단 '*}
  verd=${body#*' → 종단 '}
  case "$verd" in '재설계 필요'|'불필요') ;; *) return 1 ;; esac
  case "$left" in *=*) ;; *) return 1 ;; esac
  hex=${left##*=}
  path=${left%=*}
  case "$hex" in *[!0-9a-f]*) return 1 ;; esac
  [ "${#hex}" -eq 64 ] || return 1
  case "$path" in
    /*) ;;
    *) return 1 ;;
  esac
  case "$path" in *[[:space:]]*|*'`'*) return 1 ;; esac
  printf '%s\t%s\t%s' "$path" "$hex" "$verd"
}

gate_halt_detail_scope() {
  # gate_halt_detail_scope <관측 상세> — the scope a re-convergence halt says it
  # was handed (`범위=<scope>`), or nothing. The two shapes with a record are
  # three words and the record's path; anything else is its first token, which
  # is enough for a caller that refuses every other shape.
  printf '%s\n' "$1" | sed 's/·/ /g' | LC_ALL=C awk '
    {
      s = " " $0 " "
      i = index(s, " 범위=")
      if (!i) exit
      v = substr(s, i + length(" 범위="))
      n = split(v, w, " ")
      if (n >= 4 && ((w[1] == "구속" && w[2] == "티어" && w[3] == "이탈") \
                     || (w[1] == "감사" && w[2] == "종합" && w[3] == "요구"))) {
        print w[1] " " w[2] " " w[3] " " w[4]; exit
      }
      if (n >= 1) print w[1]
    }'
}

gate_halt_settle() {
  # gate_halt_settle <key> <answer line> — settle a person's answer to a halted
  # re-convergence without a session, when the answer's outcome is already
  # fixed: its option carries the machine settlement line, the document hashes
  # to the line's value, and the verdict is the line's. 0 with the row written;
  # GATE_EXIT_RULE with no row, and the answer left open for the carry act.
  #
  # WHY IT EXISTS. A re-convergence that prepared its edit and computed its
  # verdict sometimes stops only to ask how the edit is to land. Once a person
  # answered and the edit is on disk, what the resumed session would do is hash
  # the document and end with the verdict it already wrote down — measured: that
  # resumption was refused at the deadline because the session's account opened
  # after it, and the answer reached nothing in the run. The row this writes is
  # the row that session would have ended with.
  #
  # EVERY CHECK FAILS CLOSED, and a failure writes nothing: the answer is still
  # the key's open answer, and the shift carries it instead. An `R<n>` scope is
  # never settled — its carrier block outlives the run and only a session closes
  # it — and neither is an adopted answer, whose attempt halted in another run.
  local key="$1" ln="$2" row rec skill opt dig cur oline parsed spath shex sverd now det scope lp
  row=$(sed -n "${ln}p" "$LEDGER" 2>/dev/null)
  case "$row" in
    '- `중단 답` '*) ;;
    *) warn "원장 ${ln} 번째 줄은 중단 답 행이 아닙니다 — 정산하지 않습니다"
       return "$GATE_EXIT_RULE" ;;
  esac
  if [ "$(gate_row_field "$row" '세그먼트')" != "$key" ]; then
    warn "원장 ${ln} 번째 줄의 답은 키 $(gate_row_field "$row" '세그먼트') 의 것이라 $key 로 정산하지 않습니다"
    return "$GATE_EXIT_RULE"
  fi
  skill=$(gate_row_field "$row" '스킬')
  if [ "$skill" != "design-reconverge" ]; then
    warn "정산은 재수렴 정지의 답만 받습니다 (이 답의 스킬은 ${skill:-미상}) — 운반 act 로 넘기세요"
    return "$GATE_EXIT_RULE"
  fi
  if [ -n "$(gate_row_field "$row" '출처 런')" ]; then
    warn "다음 런에 들인 답은 그 시도가 이 런에 없어 정산하지 않습니다 — 운반 act 로 넘기세요"
    return "$GATE_EXIT_RULE"
  fi
  rec=$(gate_row_field "$row" '중단 기록')
  opt=$(gate_row_field "$row" '선택지')
  if [ -z "$rec" ] || [ ! -f "$rec" ]; then
    warn "답한 중단 기록이 없습니다 — 정산하지 않습니다: ${rec:-(없음)}"
    return "$GATE_EXIT_RULE"
  fi
  case "$rec" in
    "$RUN_DIR"/halt/shift/*)
      warn "교대 정지 기록의 답은 정산하지 않습니다: $rec"
      return "$GATE_EXIT_RULE" ;;
  esac
  oline=$(LC_ALL=C awk -v p="- \`$opt\` — " 'index($0, p) == 1 { print; exit }' "$rec" 2>/dev/null)
  if ! parsed=$(gate_halt_settle_line_parse "$oline"); then
    warn "답한 선택지 「${opt}」 의 줄이 기계 정산 줄 문법에 맞지 않습니다 — 운반 act 로 넘기세요: ${oline:-(그 선택지 줄 없음)}"
    return "$GATE_EXIT_RULE"
  fi
  spath=${parsed%%$'\t'*}
  shex=${parsed#*$'\t'}; shex=${shex%%$'\t'*}
  sverd=${parsed##*$'\t'}
  if [ "$spath" != "$(gate_doc_arg_path)" ]; then
    warn "기계 정산 줄의 문서 ${spath} 는 이 런의 설계 문서 $(gate_doc_arg_path) 가 아닙니다 — 정산하지 않습니다"
    return "$GATE_EXIT_RULE"
  fi
  now=$( { shasum -a 256 "$spath" 2>/dev/null || true; } | cut -d' ' -f1)
  if [ "$now" != "$shex" ]; then
    warn "설계 문서의 지금 sha256 ${now:-읽을 수 없음} 이 기계 정산 줄의 값 ${shex} 와 다릅니다 — 정산하지 않습니다"
    return "$GATE_EXIT_RULE"
  fi
  dig=$(gate_row_field "$row" '기록 다이제스트')
  cur=$( { shasum -a 256 "$rec" 2>/dev/null || true; } | cut -d' ' -f1)
  if [ -z "$dig" ] || [ "$cur" != "$dig" ]; then
    warn "중단 기록이 답한 뒤에 바뀌었습니다 (기록 다이제스트 ${dig:-없음}, 지금 ${cur:-읽을 수 없음}) — 정산하지 않습니다: $rec"
    return "$GATE_EXIT_RULE"
  fi
  lp=0
  gate_halt_record_of_last_park "$LEDGER" "$RUN_DIR" "$key" "$rec" || lp=$?
  if [ "$lp" != "0" ]; then
    warn "이 기록은 $key 의 마지막 의도된 park 시도(${GATE_LAST_PARK_STAGE:-없음}, 종단 부류=${GATE_LAST_PARK_CLASS:-미상})의 기록이 아닙니다 — 정산하지 않습니다: $rec"
    return "$GATE_EXIT_RULE"
  fi
  det=$(gate_halt_record_detail "$rec")
  scope=$(gate_halt_detail_scope "$det")
  case "$scope" in
    '감사 종합 요구 /'*|'구속 티어 이탈 /'*) ;;
    *) warn "정산은 기록을 가진 두 범위(감사 종합 요구, 구속 티어 이탈)의 재수렴만 받습니다 (기록의 범위 ${scope:-없음}) — 운반 act 로 넘기세요: $rec"
       return "$GATE_EXIT_RULE" ;;
  esac
  if ! gate_carry_scope_ok "$key" "$scope" "$LEDGER" "$RUN_DIR" "$rec" "$ln"; then
    warn "재수렴 범위를 원장으로 확인하지 못해 정산하지 않습니다 — 운반 act 로 넘기세요: $rec"
    return "$GATE_EXIT_RULE"
  fi
  local f
  for f in "$RUN_DIR/$key.pid" "$RUN_DIR/$key.pid.settling."*; do
    [ -e "$f" ] || continue
    warn "$key 의 시도가 아직 열려 있습니다 (파견 기록 $f) — 정산하지 않습니다"
    return "$GATE_EXIT_RULE"
  done
  if gate_key_in_flight "$key"; then
    warn "$key 에 살아 있거나 기다리는 시도가 있습니다 — 정산하지 않습니다"
    return "$GATE_EXIT_RULE"
  fi
  if gate_halt_answer_spent "$LEDGER" "$key" "$ln"; then
    warn "원장 ${ln} 번째 줄의 답은 이미 쓰였습니다 — 다시 정산하지 않습니다"
    return "$GATE_EXIT_RULE"
  fi
  if [ -n "$(LC_ALL=C awk -v l="$ln" -v k="| 세그먼트=$key |" 'NR > l && index($0, "- `중단 답` ") == 1 && index($0, k) { print NR }' "$LEDGER" 2>/dev/null)" ]; then
    warn "$key 에는 원장 ${ln} 번째 줄 뒤에 쓴 답이 있습니다 — 그 답을 넘기세요"
    return "$GATE_EXIT_RULE"
  fi
  if gate_halt_answer_deferred "$LEDGER" "$ln"; then
    warn "원장 ${ln} 번째 줄의 답은 이 런에서 이미 이월됐습니다 — 정산하지 않습니다"
    return "$GATE_EXIT_RULE"
  fi
  # A NUMBER OF ITS OWN, CLAIMED THE WAY A ROUTED DISPATCH CLAIMS ONE. A sibling's
  # re-plan cites a re-convergence by `<스테이지>#<실행 버전>` and refuses a key
  # that names two rows, so the row needs a number no attempt of the key holds.
  # The dispatch lock keeps a dispatch of the key from deriving the same number
  # in between.
  local attempt rowseg
  if ! gate_dispatch_lock_take "$key"; then
    warn "$key 를 다른 act 가 파견하고 있습니다 — 정산하지 않습니다"
    return "$GATE_EXIT_RULE"
  fi
  attempt=$(gate_derive_attempt "$key")
  if ! ( set -C; : > "$RUN_DIR/$key.attempt.$attempt" ) 2>/dev/null; then
    gate_dispatch_lock_release
    warn "시도 번호 $attempt 를 다른 파견이 이미 청구했습니다 — 정산하지 않습니다"
    return "$GATE_EXIT_RULE"
  fi
  rowseg=$(gate_stage_row_segment "$key" reconverge)
  gate_append 'stage-result' "세그먼트=$rowseg" "스테이지=$key" "종류=reconverge" \
    "종료 코드=-" "실행 버전=$attempt" "세션 id=-" "부모=-" "기록자=게이트" \
    "effort=(미상)" "서빙 모델=(미상)" "재수렴 판정=$sverd" "종단 부류=정상 완료" \
    "실패 서명=$(failure_signature reconverge '정상 완료' - "$(stage_progress_of reconverge - -)")" \
    "정산=중단 답 줄 $ln" "관측=중단 답 정산"
  gate_dispatch_lock_release
  # The same void the stream path makes after a re-convergence row, so the
  # segment's next implement dispatch plans again.
  void_segment_plan "$rowseg"
  log "중단 답 정산 — $key#$attempt (원장 ${ln} 번째 줄, 재수렴 판정 $sverd)"
  return 0
}

# The routes a shift hands an answered halt on by, one id per branch of
# 「Handing on a person's answer to a halt」 in the routing shift's skill. The
# skill maps each id to its item; `scripts/test-gate.sh` reads the ids from
# this line and fails when the skill stops naming one.
readonly GATE_HALT_ROUTES='재부착 감사-재수렴 구속-재수렴 교대-정지 빈-대상 적용-보류 설계-재수렴 골격급-재수렴'

gate_row_is_pre_session_death() {
  # gate_row_is_pre_session_death <stage-result row> — whether the row settles
  # an attempt that died before its session started: one that carried an
  # answer (`답 운반`) and reads `세션 id=미상`, or a waiter settled with
  # `관측=스폰 전 대기 중` after its supervisor vanished. Such an attempt never
  # read a card or a prompt, so it moved nothing. Which answer it carried does
  # not matter: a person may answer the record again after it. A crash with a
  # real session still counts as the key's state.
  #
  # ONE TEST FOR EVERY READER THAT LOOKS PAST THESE ROWS — the routing of an
  # answer, the run-scope re-convergence admission, the carried-over reading
  # and the consumer. The death cap counts the same rows of one answer. Two
  # spellings let one reader see a dead attempt as the key's state while
  # another passes over it, and the answer the consumer keeps open is then the
  # one the routing refuses.
  if [ -n "$(gate_row_field "$1" '답 운반')" ] \
     && [ "$(gate_row_field "$1" '세션 id')" = '미상' ]; then
    return 0
  fi
  case "$(gate_row_field "$1" '관측')" in '스폰 전 대기 중'*) return 0 ;; esac
  return 1
}

gate_stage_last_settled_row() {
  # gate_stage_last_settled_row <key> — the key's last `stage-result` row that
  # is not a pre-session death (`gate_row_is_pre_session_death`), or nothing.
  local r last=''
  while IFS= read -r r; do
    [ -n "$r" ] || continue
    gate_row_is_pre_session_death "$r" && continue
    last=$r
  done <<EOF
$( { gate_stage_result_rows_of "$1" || true; } | { grep -F -- '- `stage-result`' || true; })
EOF
  printf '%s' "$last"
}

gate_audit_reconverge_keyable() {
  # gate_audit_reconverge_keyable <audit step id> [<resumed session>] — whether
  # a `- reconverge` dispatch is admitted on the run-scope audit step: the step
  # has no `segment` row, and its last `stage-result` row is an audit that
  # parked on purpose, a re-convergence whose session is the one being resumed
  # (under `--resume`), or a re-convergence that parked on purpose when the act
  # carries a halt answer (GATE_CARRY_ANSWER). GATE_AUDIT_RECONVERGE_LAST holds
  # that last row for the caller's refusal text.
  #
  # ONE DEFINITION FOR THE DISPATCH AND THE ANSWER. The dispatch refuses a
  # `- reconverge` on this test, and `gate_halt_answer_route` refuses an answer
  # the shift would carry out by that dispatch on the same test, so an answer
  # recorded is one the dispatch takes.
  #
  # THE LAST ROW IS READ PAST PRE-SESSION DEATHS, carry or not
  # (`gate_stage_last_settled_row`). Such an attempt never read the card, so
  # the key still stands where the park left it; the carry check counts those
  # deaths against its cap, and this reading must not refuse the very retry
  # the cap is counting, nor the re-convergence a person's new `adopt as a
  # requirement` dispatches without a carry after one.
  #
  # AN ANSWER BROUGHT OVER FROM AN EARLIER RUN IS READ WHERE IT HALTED. A
  # re-kickoff's follow-up holds no row of the key yet when it carries the
  # earlier run's answer, so the last row is the earlier run's, read from the
  # carried row's `출처 런` ledger (`gate_carry_source_last_row`) — the carry
  # act's `--carry-answer` line, or, for the route the snapshot reads before
  # that act, the key's imported answer still owed (`gate_key_imported_deferred_answer`).
  local k="$1" res="${2:-}" last
  GATE_AUDIT_RECONVERGE_LAST=''
  [ -z "$(gate_segment_field "$k" '상태')" ] || return 1
  last=$(gate_stage_last_settled_row "$k")
  if [ -z "$last" ]; then
    local cl=${GATE_CARRY_ANSWER:-$(gate_key_imported_deferred_answer "$k")}
    [ -z "$cl" ] || last=$(gate_carry_source_last_row "$cl")
  fi
  GATE_AUDIT_RECONVERGE_LAST=$last
  case "$(gate_row_field "$last" '종류')|$(gate_row_field "$last" '종단 부류')" in
    'audit|의도된 park') return 0 ;;
    'reconverge|'*)
      if [ -n "$res" ] && [ "$(gate_row_field "$last" '세션 id')" = "$res" ]; then
        return 0
      fi
      if [ -n "${GATE_CARRY_ANSWER:-}" ] && [ "$(gate_row_field "$last" '종단 부류')" = "의도된 park" ]; then
        return 0
      fi
      ;;
  esac
  return 1
}

gate_audit_skeleton_reconverge_keyable() {
  # gate_audit_skeleton_reconverge_keyable <audit step id> — whether the audit
  # step's key waits on its skeletal re-convergence: no `segment` row, and the
  # key's last `stage-result` row is an audit that ended `정상 완료` with
  # `재수렴 요청=예`. GATE_AUDIT_RECONVERGE_LAST holds that last row. Kept apart
  # from `gate_audit_reconverge_keyable`, which a halt answer's route shares:
  # a skeletal re-convergence is not an answer to a halt.
  local k="$1" last
  GATE_AUDIT_RECONVERGE_LAST=''
  [ -z "$(gate_segment_field "$k" '상태')" ] || return 1
  last=$( { gate_stage_result_rows_of "$k" || true; } | { grep -vF '| 관측=스폰 전 대기 중' || true; } | tail -1)
  GATE_AUDIT_RECONVERGE_LAST=$last
  [ "$(gate_row_field "$last" '종류')" = "audit" ] \
    && [ "$(gate_row_field "$last" '종단 부류')" = "정상 완료" ] \
    && [ "$(gate_row_field "$last" '재수렴 요청')" = "예" ]
}

gate_implement_cycle_admissible() {
  # gate_implement_cycle_admissible <segment> — whether an implement dispatch
  # on the segment is inside its cycle budget. GATE_IMPL_CYCLE_N and
  # GATE_IMPL_CYCLE_CAP hold the count and the cap for the caller's refusal
  # text.
  #
  # THE RE-IMPLEMENTATION AFTER A RE-CONVERGENCE IS EXEMPT. It is the one
  # implement dispatch the ladder sends past the cap, and only while `다음`
  # reads `재구현`: once its row stands, `다음` is the re-check, so the
  # exemption covers that one dispatch and nothing after it.
  # THE EXEMPTION REACHES THE SAME RE-IMPLEMENTATION'S LATER RUNS. That
  # dispatch starts in process A, because the re-convergence voided the
  # plan, and its plan-only row already turns `다음` to the re-check. Until
  # a review of the re-implementation stands — `확인 리뷰`, a `정상 완료`
  # re-convergence after the last cycle row and no lead-fix row after it —
  # an implement dispatch passes while `implement_next[]` reads `구현`,
  # which the `무커밋 구현` limit already bounds.
  #
  # ONE DEFINITION FOR THE DISPATCH AND THE ANSWER, as
  # `gate_audit_reconverge_keyable` is: the exemption moves with later rows,
  # and a second copy of it would let an answer be recorded that the dispatch
  # then refuses.
  local seg="$1" n cap rn walk
  n=$(gate_segment_cycle_count "$seg")
  cap=$(gate_segment_cycle_cap "$seg")
  GATE_IMPL_CYCLE_N=${n:-0}
  GATE_IMPL_CYCLE_CAP=$cap
  [ "${n:-0}" -ge "$cap" ] || return 0
  rn=$(gate_segment_review_next "$seg")
  [ "$rn" = "재구현" ] && return 0
  if [ "$rn" = "확인 리뷰" ]; then
    walk=$(gate_segment_review_walk "$seg")
    if [ "$(gate_report_count "$walk" '마지막 뒤 재수렴')" = "정상" ] \
       && [ "$(gate_report_count "$walk" '리드 수정 뒤')" = "0" ]; then
      case "$(gate_implement_next_of "$seg" </dev/null)" in
        *'"다음": "구현",'*) return 0 ;;
      esac
    fi
  fi
  return 1
}

gate_halt_answer_route() {
  # gate_halt_answer_route <key> <record> <option> <answered_by> — the route id
  # (one of GATE_HALT_ROUTES) a shift hands this answer on by, printed with exit
  # 0; or GATE_HALT_ROUTE_REASON filled, `라우팅 불가 — <reason>` warned and
  # GATE_EXIT_RULE when no branch of the shift can carry the answer out.
  #
  # ROUTABILITY IS NOT AN AUTOMATIC-ANSWER BOUND. It asks only whether the
  # branch the answer falls into has its structural condition met in the
  # ledger as it stands, so it holds for every writer, a person included. The
  # bounds that count repeats or check currency are
  # `gate_halt_auto_answer_admit`'s and `gate_halt_auto_answer_current`'s, and
  # they hold for automatic answers only.
  #
  # ONLY WHAT THE LEDGER SETTLES NOW. A live attempt of the key, the exclusive
  # lock, the lane, the deadline and the stream the shift reads before
  # `--resume` move between this answer and its dispatch; they are refused when
  # the shift acts, and the shift then returns the answer to a person with a
  # routing block (item 8 of the shift's procedure).
  #
  # THE SAME TEST AT TWO TIMES. `halt-answer` asks it before writing the row,
  # and the snapshot asks it of each `answered_halts[]` element as `route` and
  # `route_refusal`, so the shift reads the same verdict the seat was given.
  #
  # `<answered_by>` is not read today: no routing condition depends on who
  # answered. It is in the signature so the snapshot and `halt-answer` pass the
  # same four facts.
  local key="$1" rec="$2" opt="$3" skill step hstep st last sid id='' why=''
  local terminal cl
  GATE_HALT_ROUTE_ID=''; GATE_HALT_ROUTE_REASON=''
  st=$(gate_segment_field "$key" '상태')
  terminal="세그먼트 $key 가 이미 종단(상태=$st)이라 교대가 이 답을 실행할 갈래가 없습니다"
  skill=$(sed -n 's/^\*\*스킬\*\*: //p' "$rec" 2>/dev/null | sed -n '1p' | sed 's/[[:space:]]*$//')
  step=$(sed -n 's/^\*\*스텝\*\*: //p' "$rec" 2>/dev/null | sed -n '1p')
  hstep=${step%% — *}
  if [ -n "$(gate_shift_halt_row_of "$rec")" ]; then
    # No terminal condition: two of the shift's stop sites arise on a segment
    # that already has its `머지됨` row, and their `재시도` writes a second one.
    id=교대-정지
    if cl=$(gate_clause_key_id "$key"); then
      # A clause's evidence request has no segment row; the shift carries the
      # answer out by settling that clause, which it can do only while the
      # clause is still unsettled.
      case "$(gate_clause_last_state "$cl")" in
        충족|불가능)
          why="종료 절 $cl 이 이미 $(gate_clause_last_state "$cl") 로 정산돼 교대가 이 답을 실행할 갈래가 없습니다" ;;
      esac
    else
      [ -n "$st" ] || why="$key 에 segment 행이 없어 교대가 교대 정지 기록의 답을 실행할 세그먼트가 없습니다"
    fi
  elif [ "$skill" = "design-audit-unattended" ] && [ "${step#*CFI-3b}" != "$step" ] \
       && [ "$opt" = "adopt as a requirement" ]; then
    id=감사-재수렴
    if gate_run_scope_kind_of_key "$key" >/dev/null 2>&1; then
      gate_audit_reconverge_keyable "$key" \
        || why="감사 단계 $key 의 마지막 행이 의도된 park 로 끝난 감사가 아니어서(종류=$(gate_row_field "$GATE_AUDIT_RECONVERGE_LAST" '종류') · 종단 부류=$(gate_row_field "$GATE_AUDIT_RECONVERGE_LAST" '종단 부류')) 교대가 - reconverge 를 띄울 수 없습니다"
    elif gate_segment_terminal "$key"; then
      why=$terminal
    fi
  elif [ "$skill" = "design-audit-unattended" ] && [ "${step#Step 7 / 골격급 재발}" != "$step" ] \
       && [ "$opt" = "재수렴" ]; then
    # A re-audit that still found skeleton-grade items parks; a person's
    # `재수렴` sends the document through one more re-convergence on the audit's
    # key, admitted on the same test as the dispatch that carries it out.
    id=골격급-재수렴
    if ! gate_audit_reconverge_keyable "$key"; then
      why="감사 단계 $key 의 마지막 행이 의도된 park 로 끝난 감사가 아니어서(종류=$(gate_row_field "$GATE_AUDIT_RECONVERGE_LAST" '종류') · 종단 부류=$(gate_row_field "$GATE_AUDIT_RECONVERGE_LAST" '종단 부류')) 교대가 - reconverge 를 띄울 수 없습니다"
    fi
  elif [ "$skill" = "implement-unattended" ] && [ "$opt" = "재수렴" ] \
       && [ "${hstep#*CFI-U3 BT-STOP}" != "$hstep" ]; then
    id=구속-재수렴
    ! gate_segment_terminal "$key" || why=$terminal
  elif [ "$skill" = "review-unattended" ] && [ "${step#Step 1b 빈 대상}" != "$step" ]; then
    id=빈-대상
    case "$opt" in
      '구현 재파견'|'세그먼트 park')
        if gate_segment_terminal "$key"; then
          why=$terminal
        elif [ "$opt" = "구현 재파견" ] && ! gate_implement_cycle_admissible "$key"; then
          why="세그먼트 $key 의 사이클 예산이 소진돼(cycle 행 ${GATE_IMPL_CYCLE_N}개, 상한 ${GATE_IMPL_CYCLE_CAP}) 구현 재파견이 거절됩니다"
        fi ;;
      *) why="빈 대상 리뷰 정지에는 \`$opt\` 를 실행할 갈래가 없습니다 — 갈래는 \`구현 재파견\` 과 \`세그먼트 park\` 뿐입니다" ;;
    esac
  elif [ "$skill" = "implement-unattended" ] && [ "$opt" = "보류" ] \
       && [ "${step#Step 3 강제 표면 좌석 적용}" != "$step" ]; then
    # A HELD SEAT APPLY PARKS THE SEGMENT, IT DOES NOT RE-ATTACH. The halted
    # session has nothing left to do with `보류`: re-attached, it ends without
    # a record under its new attempt's path, so its end reads `정상 완료` or
    # `공허한 성공` and the segment goes on to review or is resumed again. The
    # shift writes the segment's `park` row instead, and that row spends the
    # answer (`gate_halt_answer_consumer`).
    id=적용-보류
    ! gate_segment_terminal "$key" || why=$terminal
  elif [ "$opt" = "골격 재검토" ] && [ "${step#*/ ladder-unsettled}" != "$step" ] \
       && { [ "$skill" = "design-discuss-unattended" ] || [ "$skill" = "design-solo-unattended" ] \
            || [ "$skill" = "design-base-unattended" ]; } \
       && [ "$(gate_run_scope_kind_of_key "$key" 2>/dev/null)" = "design" ] \
       && last=$(gate_stage_last_settled_row "$key") \
       && [ "$(gate_row_field "$last" '종류')" = "design" ] \
       && [ "$(gate_row_field "$last" '종단 부류')" = "정상 완료" ]; then
    # A `골격 재검토` that arrives after the design froze on an earlier
    # `잔여로 두고 동결` cannot re-attach: the frozen stage does not review its
    # skeleton. It goes to the design key's re-convergence, whose entry
    # `gate_design_reconverge_entry` decides at dispatch time. Before the
    # freeze the halted design's last row is its park, and the answer
    # re-attaches below.
    id=설계-재수렴
  else
    # Every other answer, `좌석 실행` included, re-attaches the key's last
    # session; the shift reads the stream before `--resume` as well. A carry
    # that died before its session is passed over: the session to re-attach
    # is still the halted one, and the consumer keeps the answer open.
    #
    # AN ANSWER BROUGHT OVER FROM AN EARLIER RUN IS READ WHERE IT HALTED, as
    # `gate_audit_reconverge_keyable` reads it: this run holds no attempt of
    # the key before the carry act takes the answer up, so the last row is the
    # earlier run's, and the shift hands the answer on by that act.
    id=재부착
    last=$(gate_stage_last_settled_row "$key")
    if [ -z "$last" ]; then
      cl=$(gate_key_imported_deferred_answer "$key")
      [ -z "$cl" ] || last=$(gate_carry_source_last_row "$cl")
    fi
    sid=$(gate_row_field "$last" '세션 id')
    case "$sid" in
      ''|미상) why="$key 의 마지막 정산 stage-result 행에 세션 id 가 없어(세션 id=${sid:-빈 값}) 교대가 재부착할 세션이 없습니다" ;;
    esac
  fi
  if [ -z "$why" ]; then
    GATE_HALT_ROUTE_ID=$id
    printf '%s\n' "$id"
    return 0
  fi
  GATE_HALT_ROUTE_REASON=$why
  warn "라우팅 불가 — $why"
  return "$GATE_EXIT_RULE"
}

gate_halt_answer_routable_options() {
  # gate_halt_answer_routable_options <key> <record> <answered_by> — the option
  # labels of the record that `gate_halt_answer_route` routes, joined with
  # `, `, or nothing. The seat shows them beside a refusal so a person does not
  # pick a refused label again.
  local key="$1" rec="$2" by="$3" lab out=''
  while IFS= read -r lab; do
    [ -n "$lab" ] || continue
    gate_halt_answer_route "$key" "$rec" "$lab" "$by" >/dev/null 2>&1 || continue
    out="$out${out:+, }$lab"
  done <<EOF
$(gate_halt_option_labels "$rec")
EOF
  printf '%s' "$out"
}

gate_shift_halt_site_table() {
  # gate_shift_halt_site_table — the closed table of the sites at which a
  # routing shift stops ONE segment on a question only a person can answer, one
  # line per site: `<자리>|<추천>|<what only a person knows>|<재시도 설명>`.
  #
  # THE OPTIONS ARE THE TABLE'S, NOT THE SHIFT'S. Every site offers the same two
  # labels, `재시도` and `세그먼트 park`, and the next shift executes whichever
  # one is answered — so an answer always names something a shift of this run
  # can carry out, and no shift composes an option a person would then be
  # bound by.
  #
  # `추천=없음` IS FIXED FOR THE IRREVERSIBLE SITES. A push the remote disagrees
  # with, a reach the gate refused, a base that could not be resolved and a
  # target repository's own hook refusing an act, and a base branch broken in a
  # way no repair run on this host could be started for, each hang on the state of
  # something outside this run, which no record of the run settles. Whatever the shift passes as a recommendation there is dropped
  # and the record reads `(없음)`.
  #
  # Run-scope stops are not here: the enforcement surface moving (exit 7), a
  # lane or limit wait, a design step's stop and a structural refusal stop the
  # whole run, and stay a `handoff` with `사유=중단`. Neither are two stops a
  # site could not carry out an answer to. A refused predecessor landing or
  # adoption leaves the slice with no `segment` row, so there is nothing to
  # anchor a cone on or to park. An apply that failed has already been parked
  # by the apply act itself, with its own `blocked` row, and the apply's first
  # precondition refuses every retry of a parked segment.
  cat <<'EOF'
적용 전제 거부|가능|교대가 기록에서 고를 근거를 찾지 못했다 — 어느 선택지인지는 사람이 고른다|사람이 적용 전제를 갖춘 뒤, 다음 교대가 이 세그먼트의 적용을 다시 시도한다
병합 거절|가능|교대가 기록에서 고를 근거를 찾지 못했다 — 어느 선택지인지는 사람이 고른다|다음 교대가 거절 원인을 다시 읽고 이 세그먼트의 병합을 다시 시도한다
push원격불일치|없음|원격 가지가 왜 어긋났고 어느 쪽을 남길지는 원격을 본 사람만 안다|사람이 원격 가지를 맞춘 뒤, 다음 교대가 이 세그먼트의 push 를 다시 시도한다
도달 거부|없음|그 행위가 닿는 곳에 이 런이 닿아도 되는지는 사람만 정한다|사람이 그 도달을 정한 뒤, 다음 교대가 이 세그먼트의 막힌 행위를 다시 시도한다
베이스 해소 한도|없음|어느 베이스 위에 다시 쌓을지는 사람만 정한다|사람이 베이스를 정해 이 세그먼트의 가지에 해소를 올린 뒤, 다음 교대가 그 해소를 리뷰에 보낸다 — 충돌 수는 세그먼트마다 쌓이므로 교대의 해소 파견은 다시 열리지 않는다
워크트리 기록 없음|가능|교대가 기록에서 고를 근거를 찾지 못했다 — 어느 선택지인지는 사람이 고른다|다음 교대가 세그먼트 행의 워크트리를 다시 읽고 이 세그먼트를 다시 시도한다
종료 조건 11 판독 불가|가능|교대가 기록에서 고를 근거를 찾지 못했다 — 어느 선택지인지는 사람이 고른다|다음 교대가 이 세그먼트의 가지 끝을 다시 읽고 종료 조건 11 판정을 다시 시도한다
대상 훅 거절|없음|대상 저장소의 훅 규칙이 그 행위를 왜 막는지, 규칙과 행위 중 어느 쪽을 바꿀지는 그 저장소를 맡은 사람만 정한다|사람이 대상 저장소의 훅이나 그 행위를 고친 뒤, 이 답이 거절 조건을 옮기므로 다음 교대가 이 세그먼트의 막힌 행위를 다시 시도한다
종료 절 근거|없음|그 절이 요구하는 실행과 그 결과는 이 런의 읽기로 만들 수 없고, 실행할지는 사람이 정한다|-
master 수리 불가|없음|수리 런을 띄울 수 없게 한 원인(끄는 스위치·렌더·적재)을 고칠지, 사람이 직접 고칠지는 사람만 정한다|사람이 원인을 고치거나 고침을 master 에 넣은 뒤, 다음 교대가 이 세그먼트의 CI 를 다시 대조한다
EOF
}

gate_shift_halt_site_row() {
  # gate_shift_halt_site_row <자리> — that site's table line, or nothing (exit
  # 1) when the site is not in the table.
  local line
  line=$(gate_shift_halt_site_table | awk -F'|' -v s="$1" '$1 == s { print }')
  [ -n "$line" ] || return 1
  printf '%s\n' "$line"
}

gate_shift_halt_options() {
  # gate_shift_halt_options <자리> — the option lines of that site's record,
  # each `- \`<라벨>\` — <설명>`, the form the seat's answer is matched against.
  local row retry
  row=$(gate_shift_halt_site_row "$1") || return 1
  # A clause's evidence request settles a termination clause, not a segment,
  # so neither `재시도` nor `세그먼트 park` names anything a shift could do.
  if [ "$1" = "종료 절 근거" ]; then
    printf '%s\n' "- \`근거 제출\` — 좌석이나 사람이 질문이 요구하는 실행·확인을 하고 그 결과를 첨부로 남기면, 다음 교대가 첨부를 읽어 이 절을 충족으로 정산하거나, 모자라면 다시 요청한다"
    printf '%s\n' "- \`불가능으로 정산\` — 다음 교대가 이 답을 근거로 이 절을 불가능으로 정산한다. 런은 무효화로 끝난다"
    return 0
  fi
  retry=$(printf '%s' "$row" | cut -d'|' -f4)
  printf '%s\n' "- \`재시도\` — $retry"
  printf '%s\n' "- \`세그먼트 park\` — 다음 교대가 이 세그먼트를 park 로 기록하고, 이 세그먼트에 기대는 세그먼트를 빼고 나머지로 계속한다"
}

gate_clause_key_id() {
  # gate_clause_key_id <key> — the termination clause id a `clause-<id>` key
  # names, or nothing (exit 1) when the key has another shape or the manifest
  # declares no such clause. The gate makes these keys itself, so a key that
  # resolves here is never a segment id.
  local id
  case "$1" in clause-?*) id="${1#clause-}" ;; *) return 1 ;; esac
  case " $(gate_clause_ids | tr '\n' ' ') " in
    *" $id "*) printf '%s' "$id" ;;
    *) return 1 ;;
  esac
}

gate_clause_last_state() {
  # gate_clause_last_state <id> — the `상태` of the last `종료 절` row naming
  # that clause, or nothing when no row names it.
  local row last=""
  while IFS= read -r row; do
    [ -n "$row" ] || continue
    [ "$(gate_row_field "$row" 'id')" = "$1" ] && last=$(gate_row_field "$row" '상태')
  done <<EOF
$(gate_rows '종료 절')
EOF
  printf '%s' "$last"
}

gate_clause_open_request() {
  # gate_clause_open_request <id> — the record of that clause's evidence
  # request whose answer no shift has carried out yet, or nothing. A request
  # is closed by a later `종료 절` row of the same id; a later request on the
  # same key takes its place.
  local key="clause-$1" r rec=''
  while IFS= read -r r; do
    [ -n "$r" ] || continue
    case "$r" in
      '- `blocked`'*)
        [ "$(gate_row_field "$r" '앵커 세그먼트')" = "$key" ] || continue
        [ -n "$(gate_row_field "$r" '중단 기록')" ] && rec=$(gate_row_field "$r" '중단 기록') ;;
      '- `종료 절`'*)
        [ "$(gate_row_field "$r" 'id')" = "$1" ] && rec='' ;;
    esac
  done <<EOF
$( { grep -E '^- `(blocked|종료 절)`' "${LEDGER:-/dev/null}" 2>/dev/null || true; } )
EOF
  printf '%s' "$rec"
}

gate_clauses_json() {
  # The snapshot's `clauses[]`: one element per termination clause of the
  # manifest, with its wording, the state `gate_clause_settled` reads
  # (`미정산` when that says unsettled, the last row's `상태` otherwise), that
  # row's `근거`, and the evidence request still open on it. The wording is
  # here because a shift reads the manifest through nothing else, and without
  # it cannot tell what evidence a clause asks for.
  local first=1 id row st why req
  for id in $(gate_clause_ids); do
    row=$( { manifest_clause_rows_raw | grep -F "id=$id " || true; } | sed -n '1p')
    if gate_clause_settled "$id"; then
      st=$(gate_clause_last_state "$id")
    else
      st=미정산
    fi
    why=$( { gate_rows '종료 절' | grep -F "id=$id " || true; } | tail -1)
    why=$(gate_row_field "$why" '근거')
    req=$(gate_clause_open_request "$id")
    [ "$first" = "1" ] || printf ',\n'
    first=0
    printf '    {"id": "%s", "문면": "%s", "상태": "%s", "근거": "%s", "요청": "%s"}' \
      "$(gate_json_escape "$id")" "$(gate_json_escape "$(gate_row_field "$row" '문면')")" \
      "$(gate_json_escape "$st")" "$(gate_json_escape "$why")" "$(gate_json_escape "$req")"
  done
  [ "$first" = "1" ] || printf '\n'
}

gate_shift_halt_dir() {
  # gate_shift_halt_dir — the run's `halt/shift` directory, or nothing (exit 1)
  # when it is not a real directory at the place it is named.
  #
  # A SYMLINK ANYWHERE ON THE WAY IS REFUSED, by comparing physical paths: a
  # `halt/shift` that resolves elsewhere would put a record the gate vouches for
  # in a directory something else controls, and a record the seat answers from
  # in a place a later write could swap. Checked when the record is written and
  # again when it is answered.
  local d="$RUN_DIR/halt/shift" have want
  [ -n "${RUN_DIR:-}" ] && [ -d "$d" ] && [ ! -L "$d" ] || return 1
  have=$(cd -P -- "$d" 2>/dev/null && pwd -P) || return 1
  want="$(cd -P -- "$RUN_DIR" 2>/dev/null && pwd -P)/halt/shift" || return 1
  [ "$have" = "$want" ] || return 1
  printf '%s' "$d"
}

gate_shift_halt_row_of() {
  # gate_shift_halt_row_of <record> — the ledger's cone `blocked` row that
  # wrote <record>, as `<line>:<row>`, or nothing when <record> is not a
  # shift's halt record.
  #
  # THE ROW DECIDES, NOT THE RECORD. A shift's record is one the gate wrote,
  # and the gate's own row naming it — with the digest of the bytes it wrote —
  # is the only thing that says so. A file under `halt/shift/` with no such row,
  # or a record elsewhere whose header or `**스킬**` reads like a shift's, is
  # not one: a header is bytes anybody can write.
  local rec="$1" r ln row hit=''
  case "$rec" in
    "$RUN_DIR"/halt/shift/*.md) ;;
    *) return 0 ;;
  esac
  case "$rec" in */../*|*/./*) return 0 ;; esac
  case "${rec#"$RUN_DIR"/halt/shift/}" in */*) return 0 ;; esac
  while IFS= read -r r; do
    [ -n "$r" ] || continue
    ln=${r%%:*}; row=${r#*:}
    [ "$(gate_row_field "$row" '스코프')" = "cone" ] || continue
    [ "$(gate_row_field "$row" '중단 기록')" = "$rec" ] || continue
    [ -n "$(gate_row_field "$row" '기록 다이제스트')" ] || continue
    hit="$ln:$row"
  done <<EOF
$( { grep -n "^- \`blocked\` " "$LEDGER" 2>/dev/null || true; } | { grep -F "중단 기록=$rec " || true; } )
EOF
  [ -z "$hit" ] || printf '%s\n' "$hit"
}

gate_shift_halt_record_intact() {
  # gate_shift_halt_record_intact <key> <record> <line:row> — whether a shift's
  # halt record is still the one its row vouches for: the row is anchored on
  # <key>, `halt/shift` is still a real directory at its own place, and the
  # file's bytes hash to the row's `기록 다이제스트`. Warned and GATE_EXIT_RULE
  # otherwise. Asked of every answer to such a record, a person's included —
  # a person answers from what the seat shows them, and that has to be what the
  # gate wrote.
  local key="$1" rec="$2" row="${3#*:}" want have
  if [ "$(gate_row_field "$row" '앵커 세그먼트')" != "$key" ]; then
    warn "this shift's record stops $(gate_row_field "$row" '앵커 세그먼트'), not $key: $rec"
    return "$GATE_EXIT_RULE"
  fi
  gate_shift_halt_dir >/dev/null || {
    warn "this run's halt/shift is no longer a real directory at its own place, so the record cannot be vouched for: $rec"
    return "$GATE_EXIT_RULE"; }
  [ -f "$rec" ] && [ ! -L "$rec" ] || {
    warn "the shift's record is not a regular file: $rec"
    return "$GATE_EXIT_RULE"; }
  want=$(gate_row_field "$row" '기록 다이제스트')
  have=$(shasum -a 256 "$rec" | cut -d' ' -f1)
  if [ "$have" != "$want" ]; then
    warn "the shift's record changed after the gate wrote it (digest $have, the row says $want): $rec"
    return "$GATE_EXIT_RULE"
  fi
}

gate_shift_halt_fields_refused() {
  # gate_shift_halt_fields_refused <키=값>... — true (and warned) when a caller
  # of `act --kind blocked` passed one of the four fields only `shift-halt`
  # writes. A `blocked` row carrying `중단 기록` and `기록 다이제스트` is what
  # makes a file a shift's halt record, so a router able to write them by hand
  # could vouch for a record the gate never wrote.
  #
  # `막힌 답 줄` IS THE GATE'S STAMP AND NEVER AN ARGUMENT, from any caller: it
  # consumes the answer on that line and returns the record to a person, so a
  # caller able to write it could retire any answer by line number.
  local f
  for f in "$@"; do
    case "${f%%=*}" in
      '막힌 답 줄')
        warn "\`막힌 답 줄\` on a \`blocked\` row is stamped by the gate — a routing block names its record in \`사유\` (\`중단 답 라우팅 — <기록 파일 이름> — <이유>\`) and the gate finds the answer's line"
        return 0 ;;
    esac
  done
  [ -z "${GATE_SHIFT_HALT_WRITING:-}" ] || return 1
  for f in "$@"; do
    case "${f%%=*}" in
      '중단 기록'|'기록 다이제스트'|'자리'|'교대')
        warn "\`${f%%=*}\` on a \`blocked\` row is written by \`act --kind shift-halt\` only — the gate writes the halt record and its digest itself"
        return 0 ;;
    esac
  done
  return 1
}

gate_shift_halt_grounds() {
  # gate_shift_halt_grounds <alias> <추천 근거> — whether every part of a shift's
  # recommendation grounds is a kind the shift may rest on and a quote that
  # stands, verbatim, in the file that kind names. Warned and GATE_EXIT_RULE on
  # the first part that is not.
  #
  # FEWER KINDS THAN A STAGE'S RECORD MAY NAME. `기기 사실` is a measurement no
  # file holds, so nothing here can find its quote, and a part with no kind the
  # gate knows reads `미상` on the row — both are refused rather than written,
  # because the seat answers from this line without a person.
  local alias="$1" grounds="$2" part kind quote file interview root rest
  [ -n "$grounds" ] || { warn "a recommendation needs \`추천 근거\` — each part \`<종류>:<인용>\`"; return "$GATE_EXIT_RULE"; }
  interview="$(dirname "$MANIFEST")/${RUN_ID}.interview.md"
  root=$(target_field "$alias" '메인 워크트리' 2>/dev/null || true)
  rest="$grounds"
  while [ -n "$rest" ]; do
    case "$rest" in
      *' / '*) part=${rest%%' / '*}; rest=${rest#*' / '} ;;
      *) part=$rest; rest='' ;;
    esac
    case "$part" in
      *:*) kind=${part%%:*}; quote=${part#*:} ;;
      *) kind=''; quote='' ;;
    esac
    kind="${kind#"${kind%%[![:space:]]*}"}"; kind="${kind%"${kind##*[![:space:]]}"}"
    quote="${quote#"${quote%%[![:space:]]*}"}"; quote="${quote%"${quote##*[![:space:]]}"}"
    case "$kind" in
      '인터뷰 기록') file=$interview ;;
      '매니페스트 인가') file=$MANIFEST ;;
      '상시 지침') file="${root:-/nonexistent}/CLAUDE.md" ;;
      *) warn "a shift's recommendation rests on \`인터뷰 기록\`, \`매니페스트 인가\` or \`상시 지침\` only — \`${kind:-미상}\` is not one the gate can check: $part"
         return "$GATE_EXIT_RULE" ;;
    esac
    [ -n "$quote" ] || { warn "a part of \`추천 근거\` quotes nothing: $part"; return "$GATE_EXIT_RULE"; }
    if [ ! -f "$file" ] || ! grep -qF -- "$quote" "$file"; then
      warn "the quote of \`$kind\` does not stand verbatim in $file: $quote"
      return "$GATE_EXIT_RULE"
    fi
  done
}

gate_cycle_dismissed() {
  # gate_cycle_dismissed <segment> <사이클> <리뷰 HEAD> — true when a person's
  # `리뷰 기각` row names exactly that cycle of that segment. Written once and
  # asked by every reader — the merge rule's input, the apply precondition and
  # the snapshot — so the three cannot disagree on what binds. Each caller
  # passes the segment's LAST cycle row, which is what keeps a dismissal from
  # outliving a newer review.
  [ -n "$1" ] && [ -n "$2" ] && [ -n "$3" ] || return 1
  gate_has_row '리뷰 기각' "세그먼트=$1" "사이클=$2" "리뷰 HEAD=$3"
}

gate_segment_last_cycle_row() {
  # gate_segment_last_cycle_row <segment> — the segment's last `cycle` row, the
  # one whose `세그먼트` field equals <segment> exactly. Every decision that
  # reads "the last review of this segment" takes it from here, so a row of
  # segment `A2`, or one carrying `선행 세그먼트=<segment>`, is never read as it.
  [ -n "$1" ] || return 0
  gate_rows 'cycle' | gate_rows_field_eq '세그먼트' "$1" | tail -1
}

gate_ledger_rows_after() {
  # gate_ledger_rows_after <row-text> — every ledger row written after the line
  # that is byte-identical to <row-text>; the whole ledger's rows when it is
  # empty. Rows carry their chain hash, so the line names one place in the file.
  GATE_RA_ROW="$1" awk '
    BEGIN { on = (ENVIRON["GATE_RA_ROW"] == "") }
    on && index($0, "- `") == 1 { print; next }
    !on && $0 == ENVIRON["GATE_RA_ROW"] { on = 1 }' "$LEDGER" 2>/dev/null || true
}

# The closed trigger vocabulary of a review cycle: ten tokens a ledger fact or
# the ancestry of two commits stands behind, and `라우터 판단`, which none does.
GATE_TRIGGER_TOKENS='첫 리뷰|리뷰 P0|리뷰 P1|CI 실패|베이스 충돌|버전 경합|리베이스|해소 리뷰|중단 답|중단 인계|라우터 판단'

gate_segment_target_alias() {
  # gate_segment_target_alias <segment> — the target alias the segment acts in:
  # the `대상` of its last authorization row, and the run's one target when it
  # has none yet. The `segment` row carries no alias, so this is the nearest
  # row that does. Empty when neither answers.
  local seg=$1 a
  a=$(gate_rows '자율 승인' | gate_rows_field_eq '세그먼트' "$seg" | gate_rows_field_values '대상' \
        | awk 'NF && $0 != "-" { v = $0 } END { print v }')
  if [ -z "$a" ]; then
    a=$(target_aliases 2>/dev/null | awk 'NF { n++; v = $0 } END { if (n == 1) print v }')
  fi
  printf '%s' "$a"
}

gate_head_relation() {
  # gate_head_relation <worktree> <earlier sha> <later sha> — how two reviewed
  # heads stand, read in the segment's worktree: `같음` when both resolve to one
  # commit, `후손` when the earlier is an ancestor of the later, `비조상` when
  # `merge-base --is-ancestor` answers 1, and `미상` when it answers 2 or more,
  # when an object is missing or when there is no worktree. Both shas are
  # resolved to 40 characters first: the row takes 7 to 40. Never refuses.
  local wt=$1 a=$2 b=$3 fa fb rc=0
  if [ -z "$wt" ] || [ ! -d "$wt" ] || [ -z "$a" ] || [ -z "$b" ]; then
    printf '미상'; return 0
  fi
  fa=$(gate_commit_in "$wt" "$a") || { printf '미상'; return 0; }
  fb=$(gate_commit_in "$wt" "$b") || { printf '미상'; return 0; }
  if [ "$fa" = "$fb" ]; then printf '같음'; return 0; fi
  ( cd "$wt" 2>/dev/null && git --no-optional-locks merge-base --is-ancestor "$fa" "$fb" ) >/dev/null 2>&1 || rc=$?
  case "$rc" in
    0) printf '후손' ;;
    1) printf '비조상' ;;
    *) printf '미상' ;;
  esac
}

gate_cycle_trigger_facts() {
  # gate_cycle_trigger_facts <segment> — the set F of trigger tokens the ledger
  # stands behind for the segment's next review, one per line, in vocabulary
  # order. P is the segment's last `cycle` row; "after P" is every row appended
  # after it whose `세그먼트` is this segment — the whole ledger's when there is
  # no P — and every field is read as a field:
  #
  #   첫 리뷰      the segment has no `cycle` row
  #   리뷰 P0      P.P0 > 0, unless a `리뷰 기각` of (segment, P.사이클) follows
  #   리뷰 P1      P.P1 > 0, unless a `리뷰 기각` or `리뷰 이월` of (segment,
  #                P.사이클) follows or P.리뷰 종결 is `이월`
  #   CI 실패      `checks 상태=실패` or `blocked 도달 판정=CI실패` after P
  #   베이스 충돌  `베이스 판정 판정=충돌 부류=일반` after P
  #   버전 경합    `베이스 판정 판정=충돌 부류=릴리스 메타` after P
  #   리베이스     P.리뷰 HEAD is not an ancestor of the worktree's HEAD — the
  #                answer 1; 2 or more, or no worktree, adds nothing
  #   해소 리뷰    the gate's `다음` for the segment is `해소 리뷰`
  #   중단 답      a `중단 답` row after P
  #   중단 인계    a `사유=중단` `교대 기동` or `handoff` row after P whose `대상`
  #                is the segment's alias, and a row of the segment after P, not
  #                a `cycle` row, carrying `교대=<n>` of the shift that ended —
  #                `서수`−1 of the launch, `교대` of the handoff. Those two rows
  #                carry no `세그먼트`: the fact is run-scope, and the activity
  #                condition is how near it comes to "this segment's shift".
  #
  # Never refuses and writes nothing; `라우터 판단` is never in F.
  local seg=$1 p p0='' p1='' pcyc='' pend='' phead='' al wt wh
  p=$(gate_segment_last_cycle_row "$seg")
  al=$(gate_segment_target_alias "$seg")
  if [ -n "$p" ]; then
    p0=$(gate_row_field "$p" 'P0'); p1=$(gate_row_field "$p" 'P1')
    pcyc=$(gate_row_field "$p" '사이클'); pend=$(gate_row_field "$p" '리뷰 종결')
    phead=$(gate_row_field "$p" '리뷰 HEAD')
  fi
  gate_ledger_rows_after "$p" | GATE_TF_SEG="$seg" GATE_TF_AL="$al" GATE_TF_P="${p:+1}" \
    GATE_TF_P0="${p0:-0}" GATE_TF_P1="${p1:-0}" GATE_TF_CYC="$pcyc" GATE_TF_END="$pend" awk '
    function fv(k) { return (k in F) ? F[k] : "" }
    {
      delete F
      n = split($0, part, / \| /)
      s = part[1]; sub(/^- `/, "", s); sub(/`.*$/, "", s)
      for (i = 2; i <= n; i++) {
        q = index(part[i], "="); if (!q) continue
        k = substr(part[i], 1, q - 1); v = substr(part[i], q + 1); sub(/[ \t]+$/, "", v)
        F[k] = v
      }
      if (s == "교대 기동" || s == "handoff") {
        if (fv("사유") == "중단" && fv("대상") == ENVIRON["GATE_TF_AL"]) {
          e = (s == "교대 기동") ? fv("서수") - 1 : fv("교대") + 0
          ended[e] = 1
        }
        next
      }
      if (fv("세그먼트") != ENVIRON["GATE_TF_SEG"]) next
      if (s != "cycle" && fv("교대") != "") act[fv("교대") + 0] = 1
      if (s == "리뷰 기각" && fv("사이클") == ENVIRON["GATE_TF_CYC"]) dismissed = 1
      if (s == "리뷰 이월" && fv("사이클") == ENVIRON["GATE_TF_CYC"]) carried = 1
      if ((s == "checks" && fv("상태") == "실패") || (s == "blocked" && fv("도달 판정") == "CI실패")) ci = 1
      if (s == "베이스 판정" && fv("판정") == "충돌") {
        if (fv("부류") == "일반") bc = 1
        else if (fv("부류") == "릴리스 메타") vc = 1
      }
      if (s == "중단 답") ha = 1
    }
    END {
      if (ENVIRON["GATE_TF_P"] == "") print "첫 리뷰"
      else {
        if (ENVIRON["GATE_TF_P0"] + 0 > 0 && !dismissed) print "리뷰 P0"
        if (ENVIRON["GATE_TF_P1"] + 0 > 0 && !dismissed && !carried && ENVIRON["GATE_TF_END"] != "이월") print "리뷰 P1"
      }
      if (ci) print "CI 실패"
      if (bc) print "베이스 충돌"
      if (vc) print "버전 경합"
      print "@리베이스"
      if (ha) print "중단 답"
      for (e in ended) if (e in act) { print "중단 인계"; break }
    }' | while IFS= read -r t; do
      case "$t" in
        '@리베이스')
          # The two facts git and `다음` answer go in their vocabulary places.
          if [ -n "$phead" ]; then
            wt=$(gate_segment_worktree "$seg")
            if [ -n "$wt" ] && [ -d "$wt" ] && wh=$(gate_worktree_tip "$wt" 2>/dev/null) \
               && [ "$(gate_head_relation "$wt" "$phead" "$wh")" = "비조상" ]; then
              printf '리베이스\n'
            fi
          fi
          if [ -n "$p" ] && [ "$(gate_segment_review_next "$seg" 2>/dev/null || true)" = '해소 리뷰' ]; then
            printf '해소 리뷰\n'
          fi ;;
        *) printf '%s\n' "$t" ;;
      esac
    done
}

gate_cycle_trigger_derive() {
  # gate_cycle_trigger_derive <segment> — the trigger of a `cycle` row no review
  # dispatch row declared one for: the driver's. The first of F in the order
  # 첫 리뷰, 리뷰 P0, 리뷰 P1, CI 실패, 베이스 충돌, 버전 경합, 리베이스, 중단 답;
  # then whatever else F holds; `(미상)` when F is empty. The driver re-reviews
  # for no reason only a router knows, so `(미상)` on its row marks a defect,
  # not a category.
  local f t nl=$'\n'
  f=$(gate_cycle_trigger_facts "$1")
  for t in '첫 리뷰' '리뷰 P0' '리뷰 P1' 'CI 실패' '베이스 충돌' '버전 경합' '리베이스' '중단 답'; do
    case "$nl$f$nl" in *"$nl$t$nl"*) printf '%s' "$t"; return 0 ;; esac
  done
  t=$(printf '%s\n' "$f" | awk 'NF { print; exit }')
  printf '%s' "${t:-(미상)}"
}

gate_cycle_trigger_of() {
  # gate_cycle_trigger_of <segment> <report> — the `계기` of the `cycle` row
  # about to be written for <report>: copied from the segment's last review
  # dispatch row that names the same report — both paths resolved by
  # `gate_report_abs` — and carries `계기`, so a recovery dispatch, which
  # declares none, inherits the one its first dispatch declared. Derived by
  # `gate_cycle_trigger_derive` when no dispatch row names it (the driver's
  # path). Never compared against F again: the dispatch already was.
  local seg=$1 want row t='' p
  want=$(gate_report_norm "$(gate_report_abs "$2")")
  while IFS= read -r row; do
    [ -n "$row" ] || continue
    p=$(gate_row_field "$row" '리포트 경로')
    [ -n "$p" ] && [ -n "$(gate_row_field "$row" '계기')" ] || continue
    [ "$(gate_report_norm "$(gate_report_abs "$p")")" = "$want" ] && t=$(gate_row_field "$row" '계기')
  done <<EOF
$(gate_rows '자율 승인' | gate_rows_field_eq '세그먼트' "$seg")
EOF
  [ -n "$t" ] || t=$(gate_cycle_trigger_derive "$seg")
  printf '%s' "$t"
}

gate_cycle_fix_path() {
  # gate_cycle_fix_path <segment> <리뷰 HEAD> — the `수정 경로` of the `cycle`
  # row about to be written: what changed the tree between the segment's last
  # `cycle` row P and this review. Those that hold, in this order and joined by
  # commas:
  #   리드 수정   a lead-fix row follows P
  #   재수렴      a re-convergence row follows P, whatever it ended as
  #   구현        an implement row follows P — a base resolution included
  #   리드 직접   an `자율 승인` exec row follows P with `행위자=리드`, this
  #               `세그먼트`, `절단점` 커밋 or push and `축2` 워크트리쓰기 or
  #               외부상태변경; the lead's reads carry the segment and the
  #               cutpoint too, so the axis keeps them out
  # None holding, `기록 밖 커밋` when the two review HEADs name different
  # commits and `없음` when they name one; `-` when the ledger has no P. Both
  # HEADs are resolved first, as the row takes 7 to 40 characters; where the
  # worktree cannot resolve them, one being a prefix of the other is `없음`.
  local seg=$1 rh=$2 p walk out='' ph wt a b
  p=$(gate_segment_last_cycle_row "$seg")
  [ -n "$p" ] || { printf -- '-'; return 0; }
  walk=$(gate_segment_review_walk "$seg")
  [ "$(gate_report_count "$walk" '리드 수정 뒤')" = "1" ] && out="리드 수정"
  [ "$(gate_report_count "$walk" '마지막 뒤 재수렴')" != "없음" ] && out="${out:+$out,}재수렴"
  [ "$(gate_report_count "$walk" '구현 뒤')" = "1" ] && out="${out:+$out,}구현"
  if gate_ledger_rows_after "$p" | GATE_FEQ_V="$seg" awk '
      function fld(k,   i, s, q, last) {
        last = ""
        for (i = 2; i <= nf; i++) {
          s = f[i]; sub(/^ +/, "", s); sub(/[ \t]+$/, "", s)
          q = index(s, "=")
          if (q > 0 && substr(s, 1, q - 1) == k) last = substr(s, q + 1)
        }
        return last
      }
      index($0, "- `자율 승인` ") == 1 {
        nf = split($0, f, "|")
        if (fld("결정") == "exec" && fld("행위자") == "리드" && fld("세그먼트") == ENVIRON["GATE_FEQ_V"] \
            && (fld("절단점") == "커밋" || fld("절단점") == "push") \
            && (fld("축2") == "워크트리쓰기" || fld("축2") == "외부상태변경")) hit = 1
      }
      END { exit !hit }'; then
    out="${out:+$out,}리드 직접"
  fi
  if [ -z "$out" ]; then
    ph=$(gate_row_field "$p" '리뷰 HEAD')
    wt=$(gate_segment_worktree "$seg")
    if [ -n "$wt" ] && [ -d "$wt" ] && a=$(gate_commit_in "$wt" "$ph" 2>/dev/null) \
       && b=$(gate_commit_in "$wt" "$rh" 2>/dev/null); then
      [ "$a" = "$b" ] && out='없음' || out='기록 밖 커밋'
    elif [ -n "$ph" ] && { [ "${ph#"$rh"}" != "$ph" ] || [ "${rh#"$ph"}" != "$rh" ]; }; then
      out='없음'
    else
      out='기록 밖 커밋'
    fi
  fi
  printf '%s' "$out"
}

gate_cycle_prev_head() {
  # gate_cycle_prev_head <segment> <worktree> <리뷰 HEAD> — the `앞 HEAD` of the
  # `cycle` row about to be written: how the segment's last `cycle` row's
  # review HEAD stands to this one (`gate_head_relation`), whatever the mode,
  # and `-` when the ledger has no such row. Never refuses.
  local p
  p=$(gate_segment_last_cycle_row "$1")
  [ -n "$p" ] || { printf -- '-'; return 0; }
  gate_head_relation "$2" "$(gate_row_field "$p" '리뷰 HEAD')" "$3"
}

gate_cycle_pin_review_head() {
  # gate_cycle_pin_review_head <segment> <리뷰 HEAD> — keeps the reviewed commit
  # reachable after its branch is gone: `git update-ref
  # refs/cc-cmds/review/<run id>/<segment>/<40-char sha> <sha>` in the repository
  # of the segment row's `워크트리`, and prints `예`, `실패` or `건너뜀`.
  #
  # ONLY THAT WORKTREE. An empty value, a directory that is gone or one no
  # declared target owns is `건너뜀`; no other repository is searched for one to
  # write into. A repository with `remote.*.mirror=true`, or a push refspec
  # whose source covers `refs/cc-cmds/`, is `건너뜀` too: an ordinary push does
  # not carry this namespace, and those two would. A leaf ref of fixed depth
  # only, written once per row; nothing in the gate lists or deletes them — a
  # person removes them by prefix. `실패` and `건너뜀` warn once and never stop
  # the row.
  local seg=$1 rh=$2 wt full ref kv k v src probe
  wt=$(gate_segment_worktree "$seg")
  if [ -z "$wt" ] || [ ! -d "$wt" ] || ! gate_path_of_some_target "$wt"; then
    warn "리뷰 HEAD 를 고정하지 않았습니다 — 세그먼트 $seg 의 워크트리가 없거나 선언 대상의 워크트리가 아닙니다: '${wt:-(없음)}'"
    printf '건너뜀'; return 0
  fi
  probe="refs/cc-cmds/review/$RUN_ID/$seg/0000000000000000000000000000000000000000"
  while IFS= read -r kv; do
    [ -n "$kv" ] || continue
    k=${kv%% *}; v=${kv#* }
    case "$k" in
      remote.*.mirror)
        case "$v" in true|yes|on|1)
          warn "리뷰 HEAD 를 고정하지 않았습니다 — 미러 원격($k)이 있는 레포입니다: $wt"
          printf '건너뜀'; return 0 ;;
        esac ;;
      remote.*.push)
        src=${v#+}; src=${src%%:*}
        # `:` and an empty source push matching refs, which may include these.
        case "$probe" in
          $src|*"$src"*)
            warn "리뷰 HEAD 를 고정하지 않았습니다 — push refspec '$v' ($k) 가 refs/cc-cmds/ 를 덮습니다: $wt"
            printf '건너뜀'; return 0 ;;
        esac ;;
    esac
  done <<EOF
$( cd "$wt" 2>/dev/null && git --no-optional-locks config --get-regexp '^remote\..*\.(mirror|push)$' 2>/dev/null || true )
EOF
  if ! full=$(gate_commit_in "$wt" "$rh" 2>/dev/null) || [ -z "$full" ]; then
    warn "리뷰 HEAD 를 고정하지 못했습니다 — $rh 를 $wt 에서 커밋으로 풀 수 없습니다"
    printf '실패'; return 0
  fi
  ref="refs/cc-cmds/review/$RUN_ID/$seg/$full"
  if ( cd "$wt" && git update-ref "$ref" "$full" ) >/dev/null 2>&1; then
    printf '예'
  else
    warn "리뷰 HEAD 를 고정하지 못했습니다 — git update-ref $ref 가 $wt 에서 실패했습니다"
    printf '실패'
  fi
}

gate_cycle_row_projected_bytes() {
  # gate_cycle_row_projected_bytes <segment> <caller field=value>... — the bytes
  # a `cycle` row of these caller fields can reach once the gate has added its
  # own: every field the gate writes or a router may add, at its widest value,
  # unless the caller already carries it. The driver projects with this and
  # leaves `lane 결정` off only when it is over `GATE_ROW_MAX`, so a row that
  # passes loses nothing else at the gate. The one ruler of the two writers.
  local seg=$1 a k have='|' extra=() w
  shift
  for a in "$@"; do
    case "$a" in *=*) have="$have${a%%=*}|" ;; esac
  done
  for w in '교대=999' '모드=해소' '기준 사이클=999' 'P2=999' 'P3=999' \
           '계기=라우터 판단' '수정 경로=리드 수정,재수렴,구현,리드 직접' '앞 HEAD=비조상' \
           '리뷰 HEAD 고정=건너뜀' '리포트 형식=판독 불가' '항목=999/999' '비불릿=999' \
           '앵커 없음=999' '태그 밖=999' '요약=정규' 'HEAD 줄=일치' \
           '발견 지문=000000000000' '리뷰 종결=잔여 보류'; do
    k=${w%%=*}
    case "$have" in *"|$k|"*) ;; *) extra+=("$w") ;; esac
  done
  gate_row_projected_bytes 'cycle' "세그먼트=$seg" "$@" ${extra[@]+"${extra[@]}"}
}

gate_review_recovery_refusal() {
  # gate_review_recovery_refusal <segment> <report path> — why a review
  # re-dispatch marked `--recovery '전송 단절'` may not go, one sentence; nothing
  # when every premise holds. The marker only repeats an authorized dispatch
  # with the same arguments, so what it needs is proof the review died of a
  # dropped connection before saving anything, and a count:
  #   (가) the segment's last gate `review` stage-result row is a `크래시` with
  #        `일시 원인=예`;
  #   (나) the segment's last review dispatch row that recorded `리포트 경로`
  #        names this path, and nothing is saved there;
  #   (다) no witness directory carries `<segment>#<실행 버전>` of that row in
  #        its `.attempt` stamp — a review that reached its team recovers by the
  #        `--recover` dispatch instead;
  #   (라) no `복구=전송 단절` row follows that crash row, so one crash buys one
  #        re-dispatch;
  #   (마) fewer than two `복구=전송 단절` rows follow the segment's last `cycle`
  #        row — two per cycle, the bound, and the third goes to a person.
  # The bound is its own count of rows and not the same-signature stop, which
  # belongs to the hollow-success continuation and never meets this path.
  local seg="$1" rp="$2" crow att prow ppath d stamp n
  crow=$(gate_rows 'stage-result' | gate_rows_field_eq '세그먼트' "$seg" \
           | gate_rows_field_eq '기록자' '게이트' | gate_rows_field_eq '종류' 'review' | tail -1)
  if [ -z "$crow" ] || [ "$(gate_row_field "$crow" '종단 부류')" != "크래시" ] \
     || [ "$(gate_row_field "$crow" '일시 원인')" != "예" ]; then
    printf '세그먼트 %s 의 마지막 review stage-result 행이 「종단 부류=크래시」·「일시 원인=예」 가 아닙니다' "$seg"
    return 0
  fi
  prow=$(gate_rows '자율 승인' | gate_rows_field_eq '세그먼트' "$seg" | gate_rows_field_eq 'kind' 'skill' \
           | gate_rows_having_field '리포트 경로' | tail -1)
  ppath=$(gate_row_field "$prow" '리포트 경로')
  if [ -z "$ppath" ] || [ "$ppath" != "$rp" ]; then
    printf '이번 --report-path (%s) 가 세그먼트 %s 의 마지막 리뷰 파견 행의 리포트 경로 (%s) 와 다릅니다' \
      "${rp:-없음}" "$seg" "${ppath:-없음}"
    return 0
  fi
  if [ -e "$(gate_report_abs "$ppath")" ]; then
    printf '리포트 %s 가 이미 있습니다 — 저장물이 있는 리뷰는 전송 단절 재파견 대상이 아닙니다' "$ppath"
    return 0
  fi
  att=$(gate_row_field "$crow" '실행 버전')
  for d in "$RUN_DIR"/cc-team-witness-*/; do
    [ -f "$d.attempt" ] || continue
    stamp=$( { cat "$d.attempt" 2>/dev/null || true; } | tr -d '\n')
    if [ "$stamp" = "$seg#$att" ]; then
      printf '시도 %s#%s 의 위트니스 디렉터리 %s 가 있습니다 — 팀까지 간 리뷰는 --recover 복구 파견으로 갑니다' \
        "$seg" "$att" "${d%/}"
      return 0
    fi
  done
  n=$(gate_ledger_rows_after "$crow" | { grep -E '^- `자율 승인`' || true; } \
        | gate_rows_field_eq '세그먼트' "$seg" | gate_rows_field_eq '복구' '전송 단절' | gate_count)
  if [ "${n:-0}" -ge 1 ]; then
    printf '세그먼트 %s 의 마지막 크래시 행 뒤에 이미 「복구=전송 단절」 파견이 있습니다 — 새 크래시 행 없이 다시 파견하지 않습니다' "$seg"
    return 0
  fi
  n=$(gate_ledger_rows_after "$(gate_segment_last_cycle_row "$seg")" | { grep -E '^- `자율 승인`' || true; } \
        | gate_rows_field_eq '세그먼트' "$seg" | gate_rows_field_eq '복구' '전송 단절' | gate_count)
  if [ "${n:-0}" -ge 2 ]; then
    printf '세그먼트 %s 의 마지막 cycle 행 뒤 「복구=전송 단절」 파견이 이미 %s번입니다 — 사이클마다 두 번이 상한입니다' "$seg" "$n"
    return 0
  fi
  return 0
}

gate_segment_last_segment_row() {
  # gate_segment_last_segment_row <segment> — the segment's last `segment` row
  # (`id` field equal to <segment>).
  [ -n "$1" ] || return 0
  gate_rows 'segment' | gate_rows_field_eq 'id' "$1" | tail -1
}

gate_segment_review_dismissed() {
  # gate_segment_review_dismissed <segment> — `<사이클>@<리뷰 HEAD>` of the
  # segment's last cycle when a person dismissed it, and nothing otherwise.
  local row c h
  row=$(gate_segment_last_cycle_row "$1")
  [ -n "$row" ] || return 0
  c=$(gate_row_field "$row" '사이클'); h=$(gate_row_field "$row" '리뷰 HEAD')
  gate_cycle_dismissed "$1" "$c" "$h" && printf '%s@%s' "$c" "$h"
  return 0
}

gate_cycle_carried() {
  # gate_cycle_carried <segment> <사이클> <리뷰 HEAD> — true when a `리뷰 이월`
  # row names exactly that cycle of that segment. The carry-over twin of
  # `gate_cycle_dismissed`.
  [ -n "$1" ] && [ -n "$2" ] && [ -n "$3" ] || return 1
  gate_has_row '리뷰 이월' "세그먼트=$1" "사이클=$2" "리뷰 HEAD=$3"
}

gate_segment_review_carried() {
  # gate_segment_review_carried <segment> — `<사이클>@<리뷰 HEAD>` of the
  # segment's last cycle when its open P1 findings were carried over to issues,
  # and nothing otherwise. The twin of `gate_segment_review_dismissed`: a carry
  # binds only the cycle it names, so a newer review is never covered by it.
  local row c h
  row=$(gate_segment_last_cycle_row "$1")
  [ -n "$row" ] || return 0
  c=$(gate_row_field "$row" '사이클'); h=$(gate_row_field "$row" '리뷰 HEAD')
  gate_cycle_carried "$1" "$c" "$h" && printf '%s@%s' "$c" "$h"
  return 0
}

gate_canon_count() {
  # gate_canon_count <value> — true for `0` and a decimal with no leading zero.
  # An empty or otherwise spelt count is never read as a number, so a row that
  # lost its count does not pass as a clean review.
  case "${1:-}" in
    0) return 0 ;;
    ''|0*|*[!0-9]*) return 1 ;;
  esac
  return 0
}

gate_preauth_argv() {
  # gate_preauth_argv <alias> <argv…> — the argv string the preauthorization
  # rule compares a `사전 인가` row's shape against. For every command but
  # `gh api` and a git command carrying global flags it is the argv as
  # written.
  #
  # A GIT COMMAND THAT ONLY SAYS WHERE IT RUNS IS COMPARED WITHOUT SAYING IT.
  # `git -C <worktree> push …` and `git --git-dir=<g> --work-tree=<w> push …`
  # are the `git push` a `git push` row authorizes when, and only when, those
  # flags land in a worktree of <alias> (`gate_git_argv_in_target`) and they are
  # the only global flags. Then it is rewritten to `git <subcommand…>`.
  #
  # ANY OTHER GIT COMMAND HAS ITS `-…=<value>` GLOBALS SPLIT, and is otherwise
  # passed as written. The rule drops every `-…=` word before it compares, so
  # `git --git-dir=<elsewhere>/.git push origin x` reached it as `git push
  # origin x` and matched a `git push` row while the space spelling
  # `git --git-dir <elsewhere>/.git push …` did not. Each such word ahead of
  # the subcommand goes as `<flag> <value>`, which the rule keeps, so another
  # global flag (`-c`, `--namespace`, …), a location outside the target or an
  # empty <alias> matches no `git <subcommand>` row in either spelling. The
  # words after the subcommand (`--push-option=…`) are left for the rule to
  # drop as before. With no subcommand read, every `-…=` word is split.
  #
  # A `gh api` ARGV IS COMPARED WITH THE METHOD gh WILL SEND IN FRONT. The rule
  # compares a shape's words with the argv's first words, and gh takes the
  # last `-X`/`--method`, so under a `gh api -X PUT` row the argv
  # `gh api -X PUT repos/o/r --method=DELETE` matched word for word and sent a
  # DELETE; `-XDELETE`, `-Xdelete` and a trailing `-X PATCH` did the same. The
  # method `gate_gh_api_parse` reads — the last one, or POST with a body, or
  # GET — is put upper-cased right after `api`, so a row naming a method opens
  # that method and nothing else, and a row of bare `gh api` still opens every
  # call as it says.
  #
  # `api` IS FOUND PAST THE FLAGS AHEAD OF IT (see `gate_gh_strip_repo`). The
  # rule drops every `-x=y` word before it compares, so `gh
  # --hostname=github.com api -X PUT …`, left as written, matched a `gh api -X
  # PUT` row word for word. The flags ahead of `api` go after it, where gh
  # reads them too. An argv with an `api` word whose place cannot be told gets
  # an `api` word no row names, so only a row of bare `gh` opens it.
  local alias="$1"; shift
  local cmd="${1##*/}" m
  if [ "$cmd" = git ] && [ -n "$alias" ]; then
    gate_git_subcommand "${@:2}" >/dev/null
    if [ "${#GATE_GIT_GLOBALS[@]}" -gt 0 ] && [ "$GATE_GIT_LOCONLY" = 1 ] \
       && [ -z "$GATE_GIT_UNREAD" ] && [ "$GATE_GIT_SUBIDX" -gt 0 ] \
       && gate_git_argv_in_target "$alias" "$@"; then
      printf '%s %s' "$1" "${*:$((GATE_GIT_SUBIDX + 1))}"
      return 0
    fi
  fi
  if [ "$cmd" = git ]; then
    gate_git_subcommand "${@:2}" >/dev/null
    local -a gw=("$1")
    local a k=1
    for a in "${@:2}"; do
      if [ "$GATE_GIT_SUBIDX" -eq 0 ] || [ "$k" -lt "$GATE_GIT_SUBIDX" ]; then
        case "$a" in
          -*=*) gw+=("${a%%=*}" "${a#*=}"); k=$((k + 1)); continue ;;
        esac
      fi
      gw+=("$a"); k=$((k + 1))
    done
    printf '%s' "${gw[*]}"
    return 0
  fi
  if [ "$cmd" = gh ]; then
    gate_gh_strip_repo "${@:2}"
    if [ "$GATE_GH_API_UNREAD" = 1 ]; then
      printf '%s api-위치미상 %s' "$1" "${*:2}"
      return 0
    fi
    if [ "${GATE_GH_ARGV[0]:-}" = api ]; then
      gate_gh_api_parse "${GATE_GH_ARGV[@]:1}"
      m=$(printf '%s' "$GATE_GHAPI_METHOD" | LC_ALL=C tr '[:lower:]' '[:upper:]')
      printf '%s api -X %s %s' "$1" "$m" "${GATE_GH_ARGV[*]:1}"
      return 0
    fi
  fi
  printf '%s' "$*"
}

gate_manifest_preauthorizes() {
  # gate_manifest_preauthorizes <argv…> — true when a `사전 인가` row of this
  # run's manifest covers that argv. Asks the preauthorization rule in its probe
  # mode, the same one copy the reach disposition asks, so the matching rule
  # cannot split into two.
  local probe
  probe=$(GATE_PREAUTH_PROBE=1 GATE_MARK='' GATE_MARK_TRIGGER='' \
          GATE_ARGV="$(gate_preauth_argv '' "$@")" GATE_MANIFEST="$MANIFEST" \
          /bin/sh "$(gate_rules_dir)/사전-인가-대조.sh" 2>/dev/null) || return 1
  case "$probe" in *"P=1"*) return 0 ;; esac
  return 1
}

gate_manifest_has_design_doc() {
  # True when the manifest's `## 요소` → `설계 문서` is a value other than empty
  # or `(없음)`. NOT the document-argument accessor: that one falls back to the
  # run's anchor brief when a run has no design document, so it always answers
  # "present".
  local d
  d=$(manifest_field '요소' '설계 문서' 2>/dev/null) || d=''
  [ -n "$d" ] && [ "$d" != "(없음)" ]
}

gate_carry_eligibility() {
  # gate_carry_eligibility <segment> — `적격`, or `부적격 <n>` naming the first
  # condition that failed for the segment's last cycle and its report.
  # `gate_segment_carry_eligible` asks this; the number is what a measurement
  # over a corpus reads to tell the demotions apart. Number 8 is no longer a
  # condition — the carry-over issues are opened under the router's declared
  # reach rather than a preauthorization — and is kept free so a recorded
  # demotion keeps its meaning.
  #
  #   1 the last cycle row is the re-check review: a lead-fix row of this
  #     segment precedes it in the ledger
  #   2 P0 = 0
  #   3 the report's `P1 분류` line parses
  #   4 차단 = 0
  #   5 이월 가능 = the report's summary P1 = the row's P1, at least 1
  #   6 the tag lines keep the rules and their counts equal the `P1 분류` line
  #   7 every carry-over item passes the body checks
  #   9 the `리뷰 이월` row, with an issue URL of the longest form per item,
  #     fits the row cap — a URL is never clipped, so a row that cannot fit
  #     would be refused after the issues were opened
  #
  # A second argument is a `cycle` row about to be written: it is judged as the
  # last one, and every lead-fix row already in the ledger precedes it — the
  # cycle arm stamps `리뷰 종결` that way before the append.
  local seg=$1 row c p0 p1 rep counts v
  if [ -n "${2:-}" ]; then
    row=$2
    gate_segment_has_lead_fix "$seg" || { printf '부적격 1'; return 0; }
  else
    row=$(gate_segment_last_cycle_row "$seg")
    [ -n "$row" ] || { printf '부적격 1'; return 0; }
    gate_segment_last_cycle_is_recheck "$seg" || { printf '부적격 1'; return 0; }
  fi
  c=$(gate_row_field "$row" '사이클'); p0=$(gate_row_field "$row" 'P0'); p1=$(gate_row_field "$row" 'P1')
  [ "$p0" = "0" ] || { printf '부적격 2'; return 0; }
  rep=$(gate_report_abs "$(gate_row_field "$row" '리포트 경로')")
  counts=$(gate_review_report_counts "$rep") || counts=''
  [ "$(gate_report_count "$counts" '분류')" = "정규" ] || { printf '부적격 3'; return 0; }
  [ "$(gate_report_count "$counts" '차단')" = "0" ] || { printf '부적격 4'; return 0; }
  v=$(gate_report_count "$counts" '이월 가능')
  if ! gate_canon_count "$p1" || [ "$v" != "$p1" ] \
     || [ "$(gate_report_count "$counts" '요약')" != "정규" ] \
     || [ "$(gate_report_count "$counts" 'P1')" != "$p1" ] \
     || [ "$p1" -lt 1 ]; then
    printf '부적격 5'; return 0
  fi
  if [ "$(gate_report_count "$counts" '태그')" != "정규" ] \
     || [ "$(gate_report_count "$counts" '태그 차단')" != "0" ] \
     || [ "$(gate_report_count "$counts" '태그 이월 가능')" != "$v" ]; then
    printf '부적격 6'; return 0
  fi
  [ "$(gate_report_count "$counts" '본문')" = "정규" ] || { printf '부적격 7'; return 0; }
  local es eu eiss='' ek=0
  es=$(seg_slug "$seg" 2>/dev/null) || es=''
  eu="https://github.com/${es:-owner/repository}/issues/9999999999"
  while [ "$ek" -lt "$p1" ]; do
    eiss="${eiss:+$eiss,}$eu"; ek=$((ek + 1))
  done
  if [ "$(gate_row_projected_bytes '리뷰 이월' "세그먼트=$seg" "사이클=$c" \
          "리뷰 HEAD=$(gate_row_field "$row" '리뷰 HEAD')" "건수=$p1" "이슈=$eiss" \
          "레인=$(gate_lane_label)" "기록 시각=$(now_iso)")" -gt "$GATE_ROW_MAX" ]; then
    printf '부적격 9'; return 0
  fi
  printf '적격'
}

gate_segment_carry_eligible() {
  # gate_segment_carry_eligible <segment> — true when the segment's last cycle
  # may be carried over. Any failed condition on the re-check reads as
  # `다음=잔여 보류`; it never refuses the cycle row.
  [ "$(gate_carry_eligibility "$1")" = "적격" ]
}

gate_segment_review_count_verdict() {
  # gate_segment_review_count_verdict <segment> — the count half of a merge
  # verdict: `리뷰 없음`, `기각` (a person dismissed the last cycle),
  # `판정 불가` (a count empty or not canonical), `충족` (P0 = P1 = 0), `이월`
  # (P0 = 0, P1 > 0 and that cycle carried over) or `위반`. The order is the
  # first three rows of the `다음` table: no cycle, then a dismissal, then the
  # counts' canonical form, then the counts. A dismissal is read before the
  # counts because the `다음` table and the merge rule read it there and let
  # the merge through on it, P0 included; reading it after `판정 불가` would
  # hold again a merge those two allowed.
  local row p0 p1
  row=$(gate_segment_last_cycle_row "$1")
  [ -n "$row" ] || { printf '리뷰 없음'; return 0; }
  [ -n "$(gate_segment_review_dismissed "$1")" ] && { printf '기각'; return 0; }
  p0=$(gate_row_field "$row" 'P0'); p1=$(gate_row_field "$row" 'P1')
  gate_canon_count "$p0" && gate_canon_count "$p1" || { printf '판정 불가'; return 0; }
  if [ "$p0" = "0" ] && [ "$p1" = "0" ]; then printf '충족'; return 0; fi
  if [ "$p0" = "0" ] && [ -n "$(gate_segment_review_carried "$1")" ]; then printf '이월'; return 0; fi
  printf '위반'
}

gate_segment_review_walk() {
  # gate_segment_review_walk <segment> — eight facts of the segment's review
  # loop, one walk over its `cycle` and `stage-result` rows in ledger order,
  # both chosen by field equality on `세그먼트`:
  #   리드 수정 있음=<0|1>   a lead-fix row of the segment exists
  #   리드 수정 뒤=<0|1>     a lead-fix row follows the last cycle row
  #   확인 리뷰=<0|1>        the segment's first lead-fix row precedes the last
  #                          cycle row, so that cycle is a re-check review
  #   저작 뒤=<0|1>          an authoring row follows the last cycle row
  #   재저작 뒤=<0|1>        a lead-fix row follows the last cycle row, or a
  #                          re-implementation does — an implement row after a
  #                          `정상 완료` re-convergence row that itself follows
  #                          the last cycle row
  #   확인 리뷰 수=<K>       the cycle rows after the first lead-fix row
  #   재수렴 뒤=<0|1>        a re-convergence row follows the first lead-fix row
  #   마지막 뒤 재수렴=<없음|정상|실패>
  #                          the last re-convergence row after the last cycle
  #                          row, `정상` when its `종단 부류` is `정상 완료`
  #   구현 뒤=<0|1>          an implement row follows the last cycle row,
  #                          the implement dispatch of a base resolution
  #                          included — the cycle row's `수정 경로` reads it
  #
  # A LEAD-FIX ROW is `종류=lead-fix`, or the driver's `스테이지=S5F` with no
  # `종류`; an AUTHORING ROW is that, `종류=implement`, or the driver's
  # `스테이지=S4` with no `종류`. A RE-CONVERGENCE ROW is `종류=reconverge`,
  # which the gate's settlement and the driver's `reconverge_row` both write.
  # Only a re-implementation makes an implement row re-author the re-check: the
  # base resolution after a carried-over re-check is an implement dispatch too,
  # and read as a re-implementation it would turn `이월 머지` — and the base
  # overlay's `해소 리뷰` on top of it — into a re-check.
  # Every attempt counts whatever it ended as: a crashed implementation may
  # still have committed, and a failed re-convergence still spent the
  # segment's one re-convergence.
  #
  # THE RE-CHECK IS EVERY CYCLE AFTER THE FIRST LEAD FIX, not only the one a
  # lead-fix row directly precedes: the review after a re-implementation is a
  # re-check too, and the ladder's outer cap counts them all.
  [ -n "${1:-}" ] || return 0
  { grep -E '^- `(cycle|stage-result)` ' "$LEDGER" 2>/dev/null || true; } \
    | GATE_FEQ_V="$1" awk '
      function fld(k,   i, s, p, last) {
        last = ""
        for (i = 2; i <= nf; i++) {
          s = f[i]; sub(/^ +/, "", s); sub(/[ \t]+$/, "", s)
          p = index(s, "=")
          if (p > 0 && substr(s, 1, p - 1) == k) last = substr(s, p + 1)
        }
        return last
      }
      { nf = split($0, f, "|")
        if (fld("세그먼트") != ENVIRON["GATE_FEQ_V"]) next
        if (index($0, "- `cycle` ") == 1) {
          recheck = lf; lfa = 0; aa = 0; ra = 0; ia = 0; rl = ""
          if (lf) kr++
          next
        }
        k = fld("종류"); st = fld("스테이지"); sub(/:.*/, "", st)
        if (k == "reconverge") {
          if (lf) rcv = 1
          rl = (fld("종단 부류") == "정상 완료") ? "정상" : "실패"
          next
        }
        islf = (k == "lead-fix" || (k == "" && st == "S5F"))
        isim = (k == "implement" || (k == "" && st == "S4"))
        if (islf) { lf = 1; lfa = 1; ra = 1 }
        if (islf || isim) aa = 1
        if (isim) ia = 1
        if (isim && rl == "정상") ra = 1
      }
      END {
        print "리드 수정 있음=" lf + 0; print "리드 수정 뒤=" lfa + 0
        print "확인 리뷰=" recheck + 0; print "저작 뒤=" aa + 0
        print "재저작 뒤=" ra + 0
        print "확인 리뷰 수=" kr + 0; print "재수렴 뒤=" rcv + 0
        print "마지막 뒤 재수렴=" (rl == "" ? "없음" : rl)
        print "구현 뒤=" ia + 0
      }'
}

gate_segment_has_lead_fix() {
  # gate_segment_has_lead_fix <segment> — true when the segment already has a
  # lead-fix row, so its cycles from then on are re-checks.
  [ "$(gate_report_count "$(gate_segment_review_walk "$1")" '리드 수정 있음')" = "1" ]
}

gate_segment_lead_fix_after_last_cycle() {
  # gate_segment_lead_fix_after_last_cycle <segment> — true when a lead-fix row
  # follows the segment's last cycle row: the re-check review is next.
  [ "$(gate_report_count "$(gate_segment_review_walk "$1")" '리드 수정 뒤')" = "1" ]
}

gate_segment_last_cycle_is_recheck() {
  # gate_segment_last_cycle_is_recheck <segment> — true when the segment's
  # first lead-fix row precedes its last cycle row, so that cycle is a re-check.
  [ "$(gate_report_count "$(gate_segment_review_walk "$1")" '확인 리뷰')" = "1" ]
}

gate_segment_authored_after_last_cycle() {
  # gate_segment_authored_after_last_cycle <segment> — true when an implement or
  # lead-fix row follows the segment's last cycle row.
  [ "$(gate_report_count "$(gate_segment_review_walk "$1")" '저작 뒤')" = "1" ]
}

gate_segment_recheck_cap() {
  # gate_segment_recheck_cap <segment> — the re-check rounds allowed after the
  # first re-check, the driver's RECHECK_ROUND_CAP sourced from run.sh. A
  # segment gets at most this + 1 re-check reviews; the argument is kept for
  # the callers, as with `gate_segment_cycle_cap`.
  printf '%s' "$RECHECK_ROUND_CAP"
}

gate_report_design_level() {
  # gate_report_design_level <report> — the report's design-level residual
  # count, 0 when the `결함 수준` lines read `미상` or the report is absent:
  # an unreadable line sends the ladder the cheaper way, never to a park.
  local counts
  counts=$(gate_review_report_counts "$1" 2>/dev/null) || counts=''
  if [ "$(gate_report_count "$counts" '결함 수준')" = "정규" ]; then
    printf '%s' "$(gate_report_count "$counts" '결함 수준 설계')"
  else
    printf '0'
  fi
}

gate_recheck_ladder_next() {
  # gate_recheck_ladder_next <segment> <row> <P0> <K> <재수렴 뒤> [종결]
  # — rows 8 to 12 of the `다음` table, for a re-check row <row>. With a sixth
  # argument the row is one about to be written: it has no carry-over yet, so
  # row 8 cannot hold and row 9 judges <row> itself. The table and the cycle
  # arm's `리뷰 종결` read the ladder from this one copy.
  local seg=$1 row=$2 p0=$3 k=$4 rcv=$5 closing=${6:-} dl
  if [ "$p0" = "0" ]; then
    if [ -n "$closing" ]; then
      [ "$(gate_carry_eligibility "$seg" "$row")" = "적격" ] && { printf '이월'; return 0; }
    else
      [ -n "$(gate_segment_review_carried "$seg")" ] && { printf '이월 머지'; return 0; }
      gate_segment_carry_eligible "$seg" && { printf '이월'; return 0; }
    fi
  fi
  [ "${k:-0}" -gt "$(gate_segment_recheck_cap "$seg")" ] && { printf '잔여 보류'; return 0; }
  if [ "${rcv:-0}" != "1" ] && gate_manifest_has_design_doc; then
    dl=$(gate_report_design_level "$(gate_report_abs "$(gate_row_field "$row" '리포트 경로')")")
    [ "${dl:-0}" -ge 1 ] 2>/dev/null && { printf '재수렴'; return 0; }
  fi
  printf '리드 수정'
}

gate_segment_review_next_table() {
  # gate_segment_review_next_table <segment> — `다음` as the review alone reads
  # it; `gate_segment_review_next` lays the base overlay on top. "Re-check" is a
  # last cycle row after the segment's first lead-fix row, K the number of such
  # cycle rows, and a re-authoring row a lead-fix row or an implement row after
  # a `정상 완료` re-convergence row — both after the last cycle row.
  # The first row of this table that holds wins:
  #    1 no cycle row                                        리뷰 없음
  #    2 the last cycle was dismissed by a person            머지
  #    3 its P0 or P1 is empty or not canonical              판정 불가
  #    4 P0 = 0, P1 = 0                                      머지
  #    5 a lead-fix row exists, a re-authoring row follows
  #      the last cycle row                                  확인 리뷰
  #    6 a lead-fix row exists, a re-convergence row after
  #      the last cycle row did not end `정상 완료`          리드 수정
  #    7 a lead-fix row exists, a `정상 완료` re-convergence
  #      row follows the last cycle row                      재구현
  #    8 re-check, P0 = 0, P1 > 0, that cycle carried over   이월 머지
  #    9 re-check, P0 = 0, P1 > 0, carry-over eligible       이월
  #   10 re-check, K > RECHECK_ROUND_CAP                     잔여 보류
  #   11 re-check, the manifest names a design document,
  #      the report's design-level count ≥ 1, no
  #      re-convergence row after the first lead-fix row     재수렴
  #   12 re-check, otherwise                                 리드 수정
  #   13 cycle rows ≥ REIMPL_CYCLE_CAP, no lead-fix row      리드 수정
  #   14 otherwise                                           수정
  # Row 5 stands before 6 and 7, so the authoring row that follows a
  # re-convergence turns `다음` to the re-check. A failed re-convergence is not
  # a park: row 11 cannot hold again on that segment, and row 10 bounds what
  # is left, so the segment parks only at the outer cap.
  # The implement dispatch's cap refusal reads the same cycle count. The routers
  # and the driver branch on this value and on nothing else, and the merge rule
  # reads the same facts through its environment in the same order.
  local seg=$1 row p0 p1 walk n
  row=$(gate_segment_last_cycle_row "$seg")
  [ -n "$row" ] || { printf '리뷰 없음'; return 0; }
  [ -n "$(gate_segment_review_dismissed "$seg")" ] && { printf '머지'; return 0; }
  p0=$(gate_row_field "$row" 'P0'); p1=$(gate_row_field "$row" 'P1')
  gate_canon_count "$p0" && gate_canon_count "$p1" || { printf '판정 불가'; return 0; }
  if [ "$p0" = "0" ] && [ "$p1" = "0" ]; then printf '머지'; return 0; fi
  walk=$(gate_segment_review_walk "$seg")
  if [ "$(gate_report_count "$walk" '리드 수정 있음')" = "1" ]; then
    [ "$(gate_report_count "$walk" '재저작 뒤')" = "1" ] && { printf '확인 리뷰'; return 0; }
    case "$(gate_report_count "$walk" '마지막 뒤 재수렴')" in
      실패) printf '리드 수정'; return 0 ;;
      정상) printf '재구현'; return 0 ;;
    esac
  fi
  if [ "$(gate_report_count "$walk" '확인 리뷰')" = "1" ]; then
    gate_recheck_ladder_next "$seg" "$row" "$p0" \
      "$(gate_report_count "$walk" '확인 리뷰 수')" "$(gate_report_count "$walk" '재수렴 뒤')"
    return 0
  fi
  n=$(gate_segment_cycle_count "$seg")
  if [ "${n:-0}" -ge "$(gate_segment_cycle_cap "$seg")" ] \
     && [ "$(gate_report_count "$walk" '리드 수정 있음')" != "1" ]; then
    printf '리드 수정'; return 0
  fi
  printf '수정'
}

gate_cycle_review_closure() {
  # gate_cycle_review_closure <segment> <row> — the `리뷰 종결` of a `cycle` row
  # about to be written: `다음` as it will read once that row is the last,
  # with `머지` spelt `수렴`. A new row has no dismissal, no carry-over and no
  # authoring or re-convergence row after it, so rows 2, 5 to 8 of the `다음`
  # table cannot hold and the seven values are 수렴, 수정, 리드 수정, 이월,
  # 잔여 보류, 판정 불가 and 재수렴. On a segment with a lead-fix row the new
  # row is a re-check, judged by rows 9 to 12 with K counting it.
  local seg=$1 row=$2 p0 p1 n walk
  p0=$(gate_row_field "$row" 'P0'); p1=$(gate_row_field "$row" 'P1')
  gate_canon_count "$p0" && gate_canon_count "$p1" || { printf '판정 불가'; return 0; }
  if [ "$p0" = "0" ] && [ "$p1" = "0" ]; then printf '수렴'; return 0; fi
  walk=$(gate_segment_review_walk "$seg")
  if [ "$(gate_report_count "$walk" '리드 수정 있음')" = "1" ]; then
    gate_recheck_ladder_next "$seg" "$row" "$p0" \
      "$(( $(gate_report_count "$walk" '확인 리뷰 수') + 1 ))" \
      "$(gate_report_count "$walk" '재수렴 뒤')" 종결
    return 0
  fi
  # A `모드=해소` row does not count toward the cap, so it adds nothing here.
  n=$(gate_segment_cycle_count "$seg")
  [ "$(gate_row_field "$row" '모드')" = 해소 ] || n=$(( ${n:-0} + 1 ))
  if [ "${n:-0}" -ge "$(gate_segment_cycle_cap "$seg")" ]; then printf '리드 수정'; return 0; fi
  printf '수정'
}

gate_segment_review_next() {
  # gate_segment_review_next <segment> — `다음`: the review table below, and on a
  # routed run the base overlay and the CI layer on top of its two merging
  # values.
  #
  # THE OVERLAYS STAND ONLY ON A ROUTED RUN. The fixed-graph driver rebases onto
  # its base and parks a conflict of its own, and it never calls `base-check` or
  # the rerun act, so the values the overlays add would reach a loop that has no
  # branch for them.
  #
  # A `수정` OF A CI JOIN TARGET CARRIES THE CI JOIN LAYER (`gate_ci_fix_next`),
  # so a review's findings and a CI failure that survived its rerun go back to
  # the implement stage in one dispatch. `리드 수정` is a review stage's own fix
  # and has no place for the failure, so it keeps the table's value.
  local seg=$1 nx
  nx=$(gate_segment_review_next_table "$seg")
  case "$nx" in
    머지|'이월 머지') run_routed && { gate_ci_next "$seg" "$nx"; return 0; } ;;
    수정) gate_ci_join_target "$seg" && { gate_ci_fix_next "$seg"; return 0; } ;;
  esac
  printf '%s' "$nx"
}

gate_ci_join_target() {
  # gate_ci_join_target <segment> — a CI join target: a routed run, and a
  # segment whose cutpoint is `PR`, `머지` or `배포`. Every changed CI reading
  # stands on this predicate alone — the merge rule, the two layers of `다음`,
  # the snapshot and the rerun act — so none judges one segment two ways.
  #
  # THE ALIAS COMES FROM `gate_segment_target_alias`, whatever the caller holds.
  # A segment whose alias is empty or whose cutpoint does not resolve is not a
  # target and keeps today's behaviour. Below `PR` no pull request is opened,
  # so no `checks` row ever comes, and a wait for one would never end.
  local seg=$1 al
  run_routed || return 1
  al=$(gate_segment_target_alias "$seg")
  [ -n "$al" ] || return 1
  case "$(gate_segment_cutpoint "$al" "$seg")" in PR|머지|배포) return 0 ;; esac
  return 1
}

gate_ci_wait_clock() {
  # gate_ci_wait_clock <segment> <head sha> <round> — the wait clock of that
  # round as a UTC time, read from the ledger alone (`cc_ci_wait_clock`).
  local t tab
  tab=$(printf '\t')
  t=$(cc_ci_wait_clock "" "$LEDGER" "$1" "$2" "$3" "$(gate_segment_worktree "$1")")
  printf '%s' "${t%%"$tab"*}"
}

gate_ci_wait_capped() {
  # gate_ci_wait_capped <segment> <head sha> <round> — the wait cap has passed.
  cc_ci_wait_capped "$(gate_ci_wait_clock "$1" "$2" "$3")"
}

gate_ci_ack_failure() {
  # gate_ci_ack_failure <segment> <V row> — true when one element of V's
  # `실패 체크`, split on ", " as the poller joins them, is exactly the `체크` of a
  # `라벨 인정` row of the segment's target. The target is the slice alias, else
  # the segment's target alias. L5m, M3a and E read this one predicate, so the
  # three never judge one failure two ways. Whether the pair already carries a
  # label row is the caller's to read.
  local seg=$1 v=$2 al acks
  al=$(gate_slice_alias "$seg" 2>/dev/null) || al=""
  [ -n "$al" ] || al=$(gate_segment_target_alias "$seg")
  [ -n "$al" ] || return 1
  acks=$(manifest_label_ack_checks "$al" 2>/dev/null || true)
  [ -n "$acks" ] || return 1
  gate_row_field "$v" '실패 체크' | GATE_CIN_ACKS="$acks" awk '
    BEGIN { n = split(ENVIRON["GATE_CIN_ACKS"], w, "\n"); for (i = 1; i <= n; i++) if (w[i] != "") ack[w[i]] = 1 }
    { m = split($0, e, /, /); for (j = 1; j <= m; j++) if (e[j] in ack) hit = 1 }
    END { exit hit ? 0 : 1 }'
}

gate_ci_fix_next() {
  # gate_ci_fix_next <segment> — the CI join layer over a table `수정` of a CI
  # join target. H, u·a·g, V and "settled" read as in `gate_ci_next`. The first
  # row that holds wins:
  #   M1  a = 열림 or a = 실패                                      수정
  #   MW  the wait cap, where M2 would wait                       CI 대기 한도
  #   M2  no V, V = 대기, V = 실패 with 진행 중 > 0, V = 판정 불가,
  #       or V = 미등록 not past the grace                         CI 대기
  #   M3  V = 통과, or round 0's 미등록 past the grace               수정
  #   M3a settled, (segment, H) has no 처분=라벨 row, and one of V's
  #       `실패 체크` is the `체크` of a `라벨 인정` row of the
  #       segment's target                                       수정
  #   M4  settled, u < CI_RERUN_CAP                               CI 재실행
  #   M5  settled, a = 수락, the round's request saw the base fail  수정
  #   M6  otherwise (settled, a = 수락)                            CI 합류 수정
  # M2 waits for the verdict when the review ends first; M4 keeps the one rerun
  # before a failure goes back to the implement stage. M1, M3a and M5 carry no
  # evidence that the segment's change can fix the failure, and the fix makes a
  # new head whose CI starts again at round 0. M3a is L5m's predicate: a
  # failure the manifest acknowledged is neither rerun nor handed to the
  # implement stage as a CI fix, and the label path takes it on the new head
  # once the review lets a merge through. A failed or open label round already
  # reads `수정` at M1. A tip that does not resolve leaves `수정`.
  local seg=$1 wt h rd u a g base lab v vst vpend
  wt=$(gate_segment_worktree "$seg")
  h=$(gate_worktree_tip "$wt") || { printf '수정'; return 0; }
  rd=$(cc_ci_round "$LEDGER" "$seg" "$h")
  u=$(cc_ci_round_get "$rd" u); a=$(cc_ci_round_get "$rd" a); g=$(cc_ci_round_get "$rd" g)
  base=$(cc_ci_round_get "$rd" base); lab=$(cc_ci_round_get "$rd" lab)
  case "$a" in 열림|실패) printf '수정'; return 0 ;; esac
  v=$(gate_ci_verdict_row "$seg" "$h" "${g:-0}")
  vst=""; vpend=0
  if [ -n "$v" ]; then
    vst=$(gate_row_field "$v" '상태')
    vpend=$(gate_row_field "$v" '진행 중')
    case "$vpend" in ''|*[!0-9]*) vpend=0 ;; esac
  fi
  if [ "$vst" = "통과" ] || cc_ci_unregistered_expired "$vst" "${g:-0}" "$(gate_row_field "$v" '관측')"; then
    printf '수정'; return 0
  fi
  if [ "$vst" != "실패" ] || [ "$vpend" -gt 0 ]; then
    if gate_ci_wait_capped "$seg" "$h" "${g:-0}"; then printf 'CI 대기 한도'; else printf 'CI 대기'; fi
    return 0
  fi
  if [ "$lab" != "1" ] && gate_ci_ack_failure "$seg" "$v"; then
    printf '수정'; return 0
  fi
  [ "${u:-0}" -lt "$CI_RERUN_CAP" ] && { printf 'CI 재실행'; return 0; }
  [ "$base" = "실패" ] && { printf '수정'; return 0; }
  printf 'CI 합류 수정'
}

gate_ci_early() {
  # gate_ci_early <segment> — E, the early rerun predicate: a CI join target
  # neither `머지됨` nor `park`, a live stage on it that is a review, its tip
  # resolves, no round of either kind on that head (max = 0), round 0's V a
  # settled failure none of whose `실패 체크` a `라벨 인정` row of the target
  # names, and no rerun `도달 park` row below the head's first `checks` row.
  # While a review runs, the rerun goes out now rather than after it. A live
  # implement or lead fix is about to make a new head, so rerunning the old one
  # buys nothing.
  #
  # NO ROUND, NOT NO RERUN. A label round raises g and max and never u, so
  # reading u = 0 here would read round 0's superseded V after an accepted
  # label and spend the one rerun a later failure was meant to keep. AN
  # ACKNOWLEDGED CHECK'S FAILURE IS THE LABEL PATH'S: L5m and M3a read the same
  # `gate_ci_ack_failure`, and a rerun here would only spend that rerun first.
  #
  # THE PARK CLAUSE IS WHAT ENDS IT. A rerun act that parks does so before its
  # `요청` row, so u stays 0; without the clause E would stay true and the same
  # refused act would go out every shift. The relay reads the same predicate
  # (`cc_ci_early_condition`) over the poller files too, without the
  # acknowledged-check clause, because it opens no manifest: its copy is a
  # superset of this one. A shift it wakes for an acknowledged check finds
  # `ci_early[]` empty and takes no act, and the consumption rule wakes it on
  # that evidence once; the clause only makes E false, so the relay never
  # misses a wake this copy would give.
  local seg=$1 h v
  gate_ci_join_target "$seg" || return 1
  case "$(gate_segment_field "$seg" '상태')" in 머지됨|park) return 1 ;; esac
  cc_stage_is_live "$RUN_DIR" "$seg" || return 1
  [ "$(cc_stage_kind "$RUN_DIR" "$LEDGER" "$seg")" = "review" ] || return 1
  h=$(gate_segment_tip "$seg") || return 1
  [ "$(cc_ci_round_get "$(cc_ci_round "$LEDGER" "$seg" "$h")" max)" = "0" ] || return 1
  v=$(gate_ci_verdict_row "$seg" "$h" 0)
  [ "$(gate_row_field "$v" '상태')" = "실패" ] || return 1
  case "$(gate_row_field "$v" '진행 중')" in ''|0) : ;; *) return 1 ;; esac
  if gate_ci_ack_failure "$seg" "$v"; then return 1; fi
  if cc_ci_rerun_parked "$LEDGER" "$seg" "$h"; then return 1; fi
  return 0
}

# ---------------------------------------------------------------------------
# The CI layer — what `다음` reads from the poller's verdicts and the
# `CI 처분` series, on a segment whose review lets a merge through.
#
# A REVIEWED SEGMENT WHOSE CHECK FAILED HAD NO WAY BACK. The merge check refused
# it with `CI실패` and nothing routed the segment to a rerun or to the stage that
# could fix the failure, so one flaky check stopped the run on a person. The
# layer sends the current round's failure to the rerun act, waits out a rerun in
# flight, and sends a second failure on the same head back to the implement
# stage — once per segment, apart from the re-implementation cap.
#
# IT READS THE LEDGER AND NOTHING ELSE. `review_next[]` calls this on every
# snapshot, so a network read here would be a call per segment per snapshot; the
# act asks the network inside its own lock and re-derives this value there.
CI_RERUN_CAP=1
CI_FIX_CAP=1

gate_ci_verdict_row() {
  # gate_ci_verdict_row <segment> <head sha> <round> — V: the newest `checks` row
  # of that segment and head whose `재실행 회차` is <round>. A row written before
  # the field existed is round 0, so a run that began on the older poller keeps
  # its verdicts.
  gate_rows 'checks' | gate_rows_field_eq '세그먼트' "$1" | gate_rows_field_eq 'head sha' "$2" \
    | GATE_CIV_G="$3" awk '
      { g = 0; n = split($0, f, "|")
        for (i = 2; i <= n; i++) {
          s = f[i]; sub(/^ +/, "", s); sub(/[ \t]+$/, "", s)
          if (index(s, "재실행 회차=") == 1) g = substr(s, length("재실행 회차=") + 1)
        }
        if (g + 0 == ENVIRON["GATE_CIV_G"] + 0) r = $0 }
      END { if (r != "") print r }'
}

gate_ci_fix_after_last_cycle() {
  # gate_ci_fix_after_last_cycle <segment> — true when a `CI 처분 처분=수정` row of
  # the segment was written after its last `cycle` row: the fix has not been
  # reviewed yet.
  local seg=$1 last
  last=$(gate_segment_last_cycle_row "$seg")
  [ -n "$last" ] || return 1
  [ -n "$(gate_ledger_rows_after "$last" | { grep -E '^- `CI 처분`' || true; } \
    | gate_rows_field_eq '세그먼트' "$seg" | gate_rows_field_eq '처분' '수정')" ]
}

gate_ci_next() {
  # gate_ci_next <segment> <다음 of the table> — the base overlay, then the CI
  # layer. H is the worktree tip, R the last cycle's `리뷰 HEAD`, u·a·g·f the
  # round of (segment, H) as `cc_ci_round` reads it, and V the verdict row of
  # round g. "Settled" is V = 실패 with nothing still running. The first row that
  # holds wins:
  #   L0  a fix row after the last cycle, H ≠ R, H's tree ≠ R's    CI 리뷰
  #   B   the base overlay changes the value                     that value
  #   L1  a = 열림, top round's 처분 재실행                          CI 재실행
  #   L1l a = 열림, top round's 처분 라벨                            CI 라벨 인정
  #   L2  g = 0, and no V or V ∈ {통과, 미등록, 판정 불가}           the table's
  #       — on a CI join target: g = 0, and V = 통과 or 미등록
  #         past the grace                                       the table's
  #   LW  a CI join target past the wait cap, where L3 or L4
  #       would wait                                             CI 대기 한도
  #   L3  V = 대기, or V = 실패 with 진행 중 > 0                     CI 대기
  #   L4  g ≥ 1, and no V or V ∈ {미등록, 판정 불가}                 CI 대기
  #       — on a CI join target, any round: no V, V = 판정 불가,
  #         or V = 미등록 not past the grace                      CI 대기
  #   L5  g ≥ 1, V = 통과                                         the table's
  #   L5l settled, top round's 처분 라벨 and a = 실패                CI 라벨 인정
  #   L5m settled, (segment, H) has no 처분=라벨 row, and one of V's
  #       `실패 체크` is the `체크` of a `라벨 인정` row of the
  #       segment's target                                       CI 라벨 인정
  #   L6  settled, u < CI_RERUN_CAP                               CI 재실행
  #   L6b settled, a = 실패, top round's 처분 재실행                  CI 재실행
  #   LM  a CI join target with a fresh reading of its base branch
  #       that is red, lists an event not yet resolved, or lists
  #       one resolved after the segment's base: the match rows
  #       of `gate_ci_master_next`                                CI 대조,
  #       — `초과` skips L7                     master 대기/재합류/수리 불가
  #   L7  settled, a = 수락, the round's request saw the base fail  CI 기존 실패
  #   L8  settled, a = 수락, f < CI_FIX_CAP or (segment, H) has
  #       a fix row                                               CI 수정
  #   L9  otherwise                                               CI 수정 한도
  # L0 stands before the base overlay because that overlay sends a head that
  # moved past R to `해소 리뷰`, which would read the CI fix as a base
  # resolution. L1 sends a round whose closing row never came to the act, which
  # finds the open request inside its lock and parks it, rather than letting the
  # spent budget read the old failure as a re-failure. L6b sends a round that
  # closed `실패` — nothing reran on GitHub, so V is still round 0's — to the act,
  # which parks it again instead of spending the fix budget on an API failure.
  # L1l is L1 for a label round. L5l stands after L5 and not at L1, so that a
  # person who fixes the change after a failed label round has the pass taken
  # by L2 or L5 rather than having the head held for good. L5m stands ahead of
  # L6 and so takes a failure of an acknowledged check before a rerun can, at
  # the cost that a transient failure of that check gets the label rather than
  # its rerun. The early rerun E and the fix layer's M3a read the same
  # predicate (`gate_ci_ack_failure`), so neither a review still running nor a
  # review that asked for a fix reruns that failure first or hands it to the
  # implement stage. A worktree whose tip does not resolve leaves the base overlay's
  # value: the merge rule reads the same HEAD and refuses on its own.
  #
  # ON A CI JOIN TARGET NOTHING RECORDED IS A WAIT, NOT A PASS. The merge rule
  # refuses the same head (`gate_check_merge_checks`), so a review that ends
  # before CI waits for the verdict, and every such wait ends: in a verdict, in
  # "no CI" once round 0's `미등록` is past the grace, or at the wait cap in
  # `CI 대기 한도`, which the router parks. Off a join target the layer reads as
  # before.
  local seg=$1 nx=$2 b wt h r rd u a g f fix base v vst vpend ad lab join=0
  wt=$(gate_segment_worktree "$seg")
  h=$(gate_worktree_tip "$wt") || { gate_base_next "$seg" "$nx"; return 0; }
  if gate_ci_fix_after_last_cycle "$seg"; then
    r=$(gate_commit_in "$wt" "$(gate_row_field "$(gate_segment_last_cycle_row "$seg")" '리뷰 HEAD')" || true)
    if [ -n "$r" ] && [ "$h" != "$r" ] \
       && [ "$(gate_iso_git "$wt" rev-parse "$h^{tree}" 2>/dev/null || true)" != "$(gate_iso_git "$wt" rev-parse "$r^{tree}" 2>/dev/null || true)" ]; then
      printf 'CI 리뷰'; return 0
    fi
  fi
  b=$(gate_base_next "$seg" "$nx")
  [ "$b" = "$nx" ] || { printf '%s' "$b"; return 0; }
  rd=$(cc_ci_round "$LEDGER" "$seg" "$h")
  u=$(cc_ci_round_get "$rd" u); a=$(cc_ci_round_get "$rd" a); g=$(cc_ci_round_get "$rd" g)
  f=$(cc_ci_round_get "$rd" f); fix=$(cc_ci_round_get "$rd" fix); base=$(cc_ci_round_get "$rd" base)
  ad=$(cc_ci_round_get "$rd" ad); lab=$(cc_ci_round_get "$rd" lab)
  if [ "$a" = "열림" ]; then
    if [ "$ad" = "라벨" ]; then printf 'CI 라벨 인정'; else printf 'CI 재실행'; fi
    return 0
  fi
  v=$(gate_ci_verdict_row "$seg" "$h" "${g:-0}")
  vst=""; vpend=0
  if [ -n "$v" ]; then
    vst=$(gate_row_field "$v" '상태')
    vpend=$(gate_row_field "$v" '진행 중')
    case "$vpend" in ''|*[!0-9]*) vpend=0 ;; esac
  fi
  if gate_ci_join_target "$seg"; then join=1; fi
  if [ "${g:-0}" -eq 0 ]; then
    if [ "$join" = 1 ]; then
      if [ "$vst" = "통과" ] || cc_ci_unregistered_expired "$vst" 0 "$(gate_row_field "$v" '관측')"; then
        printf '%s' "$nx"; return 0
      fi
    else
      case "$vst" in ''|통과|미등록|'판정 불가') printf '%s' "$nx"; return 0 ;; esac
    fi
  fi
  if [ "$vst" = "대기" ] || { [ "$vst" = "실패" ] && [ "$vpend" -gt 0 ]; } \
     || [ -z "$vst" ] || [ "$vst" = "미등록" ] || [ "$vst" = "판정 불가" ]; then
    if [ "$join" = 1 ] && gate_ci_wait_capped "$seg" "$h" "${g:-0}"; then
      printf 'CI 대기 한도'; return 0
    fi
    printf 'CI 대기'; return 0
  fi
  [ "$vst" = "통과" ] && { printf '%s' "$nx"; return 0; }
  # Only a settled failure is left: the poller writes no other value.
  [ "$ad" = "라벨" ] && [ "$a" = "실패" ] && { printf 'CI 라벨 인정'; return 0; }
  if [ "$lab" != "1" ] && gate_ci_ack_failure "$seg" "$v"; then
    printf 'CI 라벨 인정'; return 0
  fi
  [ "${u:-0}" -lt "$CI_RERUN_CAP" ] && { printf 'CI 재실행'; return 0; }
  [ "$a" = "실패" ] && [ "$ad" = "재실행" ] && { printf 'CI 재실행'; return 0; }
  local lm skip_base=0
  if [ "$join" = 1 ]; then
    lm=$(gate_ci_master_next "$seg" "$h" "${g:-0}" "$nx")
    case "$lm" in
      '') : ;;
      '초과') skip_base=1 ;;
      *) printf '%s' "$lm"; return 0 ;;
    esac
  fi
  if [ "$a" = "수락" ]; then
    [ "$skip_base" = 1 ] || [ "$base" != "실패" ] || { printf 'CI 기존 실패'; return 0; }
    if [ "${f:-0}" -lt "$CI_FIX_CAP" ] || [ "$fix" = "1" ]; then printf 'CI 수정'; return 0; fi
  fi
  printf 'CI 수정 한도'
}

gate_ci_match_row() {
  # gate_ci_match_row <segment> <head sha> <round> — the newest match row of
  # that head and rerun round, or nothing.
  gate_rows 'CI 처분' | gate_rows_field_eq '세그먼트' "$1" | gate_rows_field_eq 'head sha' "$2" \
    | gate_rows_field_eq '처분' '대조' | gate_rows_field_eq '회차' "$3" \
    | awk 'NF { r = $0 } END { if (r != "") print r }'
}

gate_ci_master_next() {
  # gate_ci_master_next <segment> <head sha> <round> <다음 of the table> — the
  # LM rows of `gate_ci_next`, read on a settled failure after the rerun rows.
  # They stand only on a routed run whose target has a fresh `master 판독` row
  # that is red, that lists an event with no resolving commit yet, or that
  # lists an event resolved after the segment's base:
  #   LM0  no match row for this head and round                  CI 대조
  #        — while the reading is unsettled                     master 대기
  #   LM1  결과 = 수리 통과, against the last reading               the table's
  #        — against an older reading                           CI 대조
  #        — while the reading is unsettled                     master 대기
  #   LM2  결과 = 초과                     prints `초과`: L8/L9, never L7
  #   LM3  결과 = 재합류 필요, or 부분집합/판정 불가 while the
  #        reading is green                                     master 재합류
  #   LM4  부분집합/판정 불가, 대표 = 예, and a waited event the
  #        reading says no repair run can be started for         master 수리 불가
  #   LM5  부분집합/판정 불가 against a reading whose
  #        signature fingerprint or event field has moved,
  #        while the reading is settled                         CI 대조
  #   LM6  부분집합/판정 불가 otherwise                            master 대기
  # A reading is settled when it is red or green; `진행 중` and `판정 불가` are
  # not. Nothing printed leaves the layer as it was. With no reading on the host
  # nothing is printed, so a run without a master stage keeps L7: the failure
  # that was on the base when the round was requested.
  #
  # A FLAKY FAILURE GETS ITS RERUN FIRST. The rows stand after L6 and L6b, so
  # only a failure that survived its rerun is compared with the base branch.
  #
  # AN OPEN EVENT KEEPS THE ROWS STANDING. Every new tip of the base branch —
  # the repair commit's own merge included — is read as `진행 중` before it is
  # read again as red or green, and an event is resolved only by a complete
  # observation. The open events keep a waiting segment off L7's `CI 기존 실패`
  # and the merge refusal through that reading, which is the very change the
  # relay wakes its shift on.
  #
  # AN UNSETTLED READING IS NOT MATCHED. Its signature list need not hold every
  # failure of its tip, so a `부분집합` or a `수리 통과` made against it could
  # hide a new failure. While it lasts the rows read the last match row as it
  # stands, a missing one or a pass included, and the match and the merge wait
  # for a red or green reading.
  local seg=$1 h=$2 g=$3 nx=$4 al mrow mst m res e settled=0
  run_routed || return 0
  al=$(gate_segment_target_alias "$seg")
  [ -n "$al" ] || return 0
  gate_master_fresh "$al" || return 0
  mrow=$(gate_master_last_row "$al")
  mst=$(gate_row_field "$mrow" '상태')
  if [ "$mst" != '빨강' ] && [ -z "$(gate_master_open_events "$al")" ] \
     && [ -z "$(gate_master_resolved_after "$seg" "$al")" ]; then
    return 0
  fi
  case "$mst" in 빨강|초록) settled=1 ;; esac
  m=$(gate_ci_match_row "$seg" "$h" "$g")
  if [ -z "$m" ]; then
    if [ "$settled" = 1 ]; then printf 'CI 대조'; else printf 'master 대기'; fi
    return 0
  fi
  res=$(gate_row_field "$m" '결과')
  case "$res" in
    # The merge check takes this pass only against the reading it was made
    # against, so a pass the reading has moved past is matched again.
    '수리 통과')
      if [ "$settled" = 0 ]; then printf 'master 대기'
      elif gate_ci_repair_pass "$seg" "$h" "$g"; then printf '%s' "$nx"
      else printf 'CI 대조'; fi
      return 0 ;;
    '초과') printf '초과'; return 0 ;;
    '재합류 필요') printf 'master 재합류'; return 0 ;;
    부분집합|'판정 불가') : ;;
    *) return 0 ;;
  esac
  [ "$mst" != '초록' ] || { printf 'master 재합류'; return 0; }
  if [ "$(gate_row_field "$m" '대표')" = '예' ]; then
    for e in $(gate_row_field "$m" '사건' | tr ',' ' '); do
      if [ "$(gate_master_event_state "$al" "$e")" = '띄울 수 없음' ]; then
        printf 'master 수리 불가'; return 0
      fi
    done
  fi
  # A WAIT IS MATCHED AGAIN WHEN ITS READING MOVES. The representative marker
  # is taken inside the match act alone, and the usual order is a wait first
  # and `띄울 수 없음` after it, when the repair run ends without resolving
  # the event; a wait kept against the old reading would never reach LM4. An
  # event resolved while another keeps the base red moves the comparison set
  # the same way. The new match records the reading it was made against, so
  # a reading that stays put is matched once. An unsettled reading is not
  # matched, so the wait holds until the reading is red or green again.
  if [ "$settled" = 1 ] && ! gate_ci_match_same_reading "$m" "$mrow"; then
    printf 'CI 대조'; return 0
  fi
  printf 'master 대기'
}

# ---------------------------------------------------------------------------
# The base check — `act --kind base-check`, and what `다음` reads from it.
#
# A REVIEWED PULL REQUEST THAT CONFLICTS WITH ITS BASE USED TO REACH NOTHING.
# The gate and the driver read no mergeable state, so a segment whose review had
# passed went to its merge, the merge was refused, and the shift ended with no
# record of why. The check asks the remote where the base is, merges in an
# object directory of its own, and writes what it found on a series of its own:
# `일치` and `이동` are not blocks, so `blocked` cannot carry them.
#
# R IS THE CYCLE THAT LETS THE MERGE THROUGH. The last cycle's `리뷰 HEAD` when
# the review table reads `머지` or `이월 머지` — a cycle that passed, one a
# person dismissed, one whose open findings went to issues — and nothing
# otherwise. A resolution cycle that passes becomes the next R.
#
# T IS WHAT THE REMOTE SAYS. A local tracking ref is moved by a spelling the
# grade table reads as a read, so the base is the answer `git ls-remote` gives
# for the base branch of the target's remote slug, and the gate does not fetch:
# an object it does not have is a refusal that names the fetch.

gate_base_rows() {
  # gate_base_rows <segment> — the segment's `베이스 판정` rows, oldest first.
  gate_rows '베이스 판정' | gate_rows_field_eq '세그먼트' "$1"
}

gate_base_last_row() {
  gate_base_rows "$1" | awk 'NF { r = $0 } END { if (r != "") print r }'
}

gate_base_conflict_count() {
  # gate_base_conflict_count <segment> — how many `베이스 판정` rows of the
  # segment say `충돌`. Counted apart from the review cycle budget: a fix cycle
  # and a base resolution must not spend each other's allowance.
  gate_base_rows "$1" | gate_rows_field_eq '판정' '충돌' | gate_count
}

gate_commit_in() {
  # gate_commit_in <dir> <rev> — the full commit sha <rev> names in <dir>, or 1.
  local out
  [ -n "$2" ] || return 1
  out=$( { cd "$1" 2>/dev/null && git rev-parse --verify --quiet "$2^{commit}" 2>/dev/null; } || true)
  [ -n "$out" ] || return 1
  printf '%s' "$out"
}

gate_base_review_head() {
  # gate_base_review_head <segment> — R, resolved in the segment worktree.
  local seg=$1 nx row
  nx=$(gate_segment_review_next_table "$seg")
  case "$nx" in 머지|'이월 머지') ;; *) return 1 ;; esac
  row=$(gate_segment_last_cycle_row "$seg")
  gate_commit_in "$(gate_segment_worktree "$seg")" "$(gate_row_field "$row" '리뷰 HEAD')"
}

gate_base_resolve_basis_row() {
  # gate_base_resolve_basis_row <segment> — B's cycle row: the segment's last
  # cycle whose `모드` is not `해소`. A resolution cycle is never a basis, so a
  # resolution stacked on a resolution reviews against the same B.
  gate_rows 'cycle' | gate_rows_field_eq '세그먼트' "$1" | gate_rows_field_ne '모드' '해소' \
    | awk 'NF { r = $0 } END { if (r != "") print r }'
}

gate_base_remote_tip() {
  # gate_base_remote_tip <alias> <dir> — T: the tip the remote reports for the
  # target's base branch, a 40-character sha, or 1 with the reason on stderr.
  # `GIT_TERMINAL_PROMPT=0` for the reason `base_fetch_ref` gives: a credential
  # prompt in an unattended night is a wait nobody answers.
  local al=$1 dir=$2 slug br out sha
  slug=$(target_field "$al" '원격 슬러그' 2>/dev/null || true)
  br=$(base_branch "$al" 2>/dev/null || true)
  if [ -z "$slug" ] || [ -z "$br" ]; then
    warn "cannot ask the remote for the base — target '$al' has no 원격 슬러그 or base branch"
    return 1
  fi
  if ! out=$(cd "$dir" 2>/dev/null && GIT_TERMINAL_PROMPT=0 git ls-remote "https://github.com/$slug.git" "refs/heads/$br" 2>/dev/null); then
    warn "git ls-remote did not answer for https://github.com/$slug.git refs/heads/$br"
    return 1
  fi
  sha=$(printf '%s\n' "$out" | GATE_FEQ_V="refs/heads/$br" awk '$2 == ENVIRON["GATE_FEQ_V"] { n++; s = $1 } END { if (n == 1) print s }')
  case "$sha" in
    *[!0-9a-f]*|'') warn "the remote does not report one tip for refs/heads/$br: ${out:-(nothing)}"; return 1 ;;
  esac
  [ "${#sha}" -eq 40 ] || { warn "the remote reported a tip that is not a full sha: $sha"; return 1; }
  printf '%s' "$sha"
}

# THE ISOLATED OBJECT DIRECTORY. A merge or an expected tree computed for a
# judgment writes blobs and trees nobody refers to; written into the common git
# they would pile up under every segment's check and every merge. Each judgment
# opens a directory of its own, reads the repository's objects through
# `GIT_ALTERNATE_OBJECT_DIRECTORIES`, and removes the directory when it is done.
# With no directory open the same functions write into the repository — the
# helper that builds the merge commit is the one caller that wants that.
GATE_ISO_DIR=""
GATE_ISO_ALT=""

gate_iso_open() {
  # gate_iso_open <dir> — opens the isolated object directory for <dir>'s repository.
  local common
  common=$( { cd "$1" 2>/dev/null && git rev-parse --path-format=absolute --git-common-dir 2>/dev/null; } || true)
  [ -n "$common" ] && [ -d "$common/objects" ] || return 1
  GATE_ISO_DIR=$(mktemp -d "${TMPDIR:-/tmp}/gate-iso.XXXXXX") || return 1
  GATE_ISO_ALT="$common/objects"
}

gate_iso_close() {
  [ -z "$GATE_ISO_DIR" ] || rm -rf "$GATE_ISO_DIR"
  GATE_ISO_DIR=""; GATE_ISO_ALT=""
}

gate_iso_git() {
  # gate_iso_git <dir> <git args…> — git in <dir>, writing into the isolated
  # object directory while one is open.
  local dir=$1; shift
  if [ -n "$GATE_ISO_DIR" ]; then
    ( cd "$dir" && GIT_OBJECT_DIRECTORY="$GATE_ISO_DIR" GIT_ALTERNATE_OBJECT_DIRECTORIES="$GATE_ISO_ALT" git "$@" )
  else
    ( cd "$dir" && git "$@" )
  fi
}

gate_merge_tree() {
  # gate_merge_tree <dir> <a> <b> — the merged tree on the first line and the
  # conflicted paths after it. 0 clean, 1 conflicted, anything else no answer.
  local rc=0
  gate_iso_git "$1" merge-tree --write-tree --name-only --no-messages "$2" "$3" 2>/dev/null || rc=$?
  return "$rc"
}

# --- release metadata --------------------------------------------------------
#
# TWO RELEASES OF THE SAME PLUGIN CONFLICT IN TWO FILES AND NOWHERE ELSE, and
# the resolution is not a judgment: this segment's version is the base's bumped
# by the grade the segment bumped its own, and its changelog entry goes on top
# of the base's. `release_meta_expected_tree` builds the one tree that answer
# allows, E*, and every reader compares a merge commit's tree to it whole — a
# conflict list cannot be the test, because two same-grade bumps merge
# `plugin.json` cleanly to the wrong number, and a path list hides a change
# inside the file. Any premise that does not hold returns 1 and the segment goes
# to a resolution review.
GATE_META_PLUGIN='plugins/cc-cmds/.claude-plugin/plugin.json'
GATE_META_LOG='CHANGELOG.md'
GATE_META_WHY=""
GATE_META_TREE=""

gate_meta_blob() {
  # gate_meta_blob <dir> <rev> <path> <out file> — the blob's bytes, or 1.
  gate_iso_git "$1" cat-file blob "$2:$3" > "$4" 2>/dev/null
}

gate_meta_version_of() {
  # gate_meta_version_of <plugin.json file> — the one version line's value.
  awk '/^[ \t]*"version"[ \t]*:[ \t]*"[0-9]+\.[0-9]+\.[0-9]+"[ \t]*,?[ \t]*$/ {
         n++; v = $0; sub(/^[^:]*:[ \t]*"/, "", v); sub(/".*$/, "", v) }
       END { if (n == 1) print v }' "$1"
}

gate_meta_log_split() {
  # gate_meta_log_split <changelog file> <preamble out> <head out> <rest out>
  # — the lines before the first `## [` heading, that first entry, and every
  # entry after it. 1 when there is no entry.
  awk -v p="$2" -v h="$3" -v r="$4" '
    /^## \[/ { e++ }
    { if (e == 0) print > p; else if (e == 1) print > h; else print > r }
    END { if (e == 0) exit 1 }' "$1" || return 1
  touch "$2" "$3" "$4"
}

gate_meta_head_version() {
  # gate_meta_head_version <head entry file> — X.Y.Z of `## [X.Y.Z] - YYYY-MM-DD`.
  awk 'NR == 1 && /^## \[[0-9]+\.[0-9]+\.[0-9]+\] - [0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9][ \t]*$/ {
         v = $0; sub(/^## \[/, "", v); sub(/\].*$/, "", v); print v }' "$1"
}

gate_meta_bump_grade() {
  # gate_meta_bump_grade <from> <to> — major, minor or patch when <to> is <from>
  # bumped one step with no suffix, nothing otherwise.
  local a1 a2 a3 b1 b2 b3
  IFS=. read -r a1 a2 a3 <<EOF
$1
EOF
  IFS=. read -r b1 b2 b3 <<EOF
$2
EOF
  if [ "$b1" -eq "$a1" ] && [ "$b2" -eq "$a2" ] && [ "$b3" -eq "$((a3 + 1))" ]; then printf patch
  elif [ "$b1" -eq "$a1" ] && [ "$b2" -eq "$((a2 + 1))" ] && [ "$b3" -eq 0 ]; then printf minor
  elif [ "$b1" -eq "$((a1 + 1))" ] && [ "$b2" -eq 0 ] && [ "$b3" -eq 0 ]; then printf major
  fi
}

gate_meta_bump() {
  # gate_meta_bump <version> <grade>
  local a1 a2 a3
  IFS=. read -r a1 a2 a3 <<EOF
$1
EOF
  case "$2" in
    patch) printf '%s.%s.%s' "$a1" "$a2" "$((a3 + 1))" ;;
    minor) printf '%s.%s.0' "$a1" "$((a2 + 1))" ;;
    major) printf '%s.0.0' "$((a1 + 1))" ;;
  esac
}

release_meta_expected_tree() {
  # release_meta_expected_tree <dir> <R> <T> — leaves E*, the tree an honest
  # renumbering merge of R onto T has, in `GATE_META_TREE`, or returns 1 with
  # the failed premise in `GATE_META_WHY`. Globals and not stdout, so a caller
  # keeps the reason: a command substitution would drop it with its subshell.
  # The premises:
  #   (a) the merge of R and T conflicts in the two release files at most;
  #   (b) from MB = merge-base(R, T) to R, plugin.json differs in its version
  #       line and nowhere else;
  #   (c) R's changelog is MB's with one entry added on top, and the preamble
  #       left as it was;
  #   (d) MB's version to R's is one step with no suffix, and R's head entry
  #       names R's version;
  #   (e) T's plugin.json version is the version of T's head changelog entry;
  #   (f) R's head entry body carries no version token — a sentence naming the
  #       previous release would change meaning under a new number, and no
  #       mechanical check can tell.
  # E* is the merged tree with plugin.json as T's bytes with the version line
  # bumped from T's by R's grade, and the changelog as T's preamble, R's head
  # entry under the new number with R's date, and T's entries.
  local dir=$1 r=$2 t=$3 w mb mt rc=0 p v rev v_mb v_r v_t v_h g v_new pm lm blob_p blob_l
  GATE_META_WHY=""; GATE_META_TREE=""
  w=$(mktemp -d "${TMPDIR:-/tmp}/gate-meta.XXXXXX") || { GATE_META_WHY="no scratch directory"; return 1; }
  # A subshell so every early return removes the scratch directory.
  (
    fail() { printf '%s' "$1" > "$w/why"; exit 1; }
    mb=$(gate_iso_git "$dir" merge-base "$r" "$t" 2>/dev/null) || fail "no merge base of R and T"
    mt=$(gate_merge_tree "$dir" "$r" "$t") || rc=$?
    case "$rc" in 0|1) ;; *) fail "the merge of R and T did not answer" ;; esac
    while IFS= read -r p; do
      [ -n "$p" ] || continue
      case "$p" in
        "$GATE_META_PLUGIN"|"$GATE_META_LOG") ;;
        *) fail "(a) the merge conflicts outside the release files: $p" ;;
      esac
    done <<EOF
$(printf '%s\n' "$mt" | sed '1d')
EOF
    mt=$(printf '%s\n' "$mt" | sed -n '1p')
    for v in mb r t; do
      eval "rev=\$$v"
      gate_meta_blob "$dir" "$rev" "$GATE_META_PLUGIN" "$w/$v.json" || fail "no $GATE_META_PLUGIN at $v"
      gate_meta_blob "$dir" "$rev" "$GATE_META_LOG" "$w/$v.log" || fail "no $GATE_META_LOG at $v"
      gate_meta_log_split "$w/$v.log" "$w/$v.pre" "$w/$v.head" "$w/$v.rest" || fail "$GATE_META_LOG at $v has no entry"
    done
    # (b) — lines, not JSON: a parser reads duplicate keys and order its own way.
    [ "$(wc -l < "$w/mb.json")" -eq "$(wc -l < "$w/r.json")" ] || fail "(b) plugin.json changed more than its version line"
    awk 'NR == FNR { a[FNR] = $0; next }
         a[FNR] != $0 { d++; if ($0 !~ /^[ \t]*"version"[ \t]*:/) bad = 1 }
         END { exit (d == 1 && !bad) ? 0 : 1 }' "$w/mb.json" "$w/r.json" \
      || fail "(b) plugin.json changed more than its version line"
    # (c)
    cmp -s "$w/r.pre" "$w/mb.pre" || fail "(c) R changed the changelog preamble"
    cat "$w/mb.head" "$w/mb.rest" > "$w/mb.entries"
    cmp -s "$w/r.rest" "$w/mb.entries" || fail "(c) R changed changelog entries below its own"
    # (d)
    v_mb=$(gate_meta_version_of "$w/mb.json"); v_r=$(gate_meta_version_of "$w/r.json")
    v_t=$(gate_meta_version_of "$w/t.json")
    [ -n "$v_mb" ] && [ -n "$v_r" ] && [ -n "$v_t" ] || fail "(d) a plugin.json does not carry one plain version line"
    g=$(gate_meta_bump_grade "$v_mb" "$v_r")
    [ -n "$g" ] || fail "(d) $v_mb to $v_r is not one bump step"
    [ "$(gate_meta_head_version "$w/r.head")" = "$v_r" ] || fail "(d) R's head changelog entry does not name $v_r"
    # (e)
    v_h=$(gate_meta_head_version "$w/t.head")
    [ "$v_h" = "$v_t" ] || fail "(e) T's plugin.json ($v_t) and head changelog entry (${v_h:-none}) disagree"
    # (f)
    awk 'NR > 1 && /[0-9]+\.[0-9]+\.[0-9]+/ { bad = 1 } END { exit bad ? 1 : 0 }' "$w/r.head" \
      || fail "(f) R's head changelog entry body carries a version token"
    v_new=$(gate_meta_bump "$v_t" "$g")
    GATE_FEQ_V="$v_new" awk '
      /^[ \t]*"version"[ \t]*:[ \t]*"[0-9]+\.[0-9]+\.[0-9]+"[ \t]*,?[ \t]*$/ {
        i = index($0, "\""); pre = substr($0, 1, i); rest = substr($0, i + 1)
        j = index(rest, ":"); pre = pre substr(rest, 1, j); rest = substr(rest, j + 1)
        k = index(rest, "\""); pre = pre substr(rest, 1, k); rest = substr(rest, k + 1)
        l = index(rest, "\""); print pre ENVIRON["GATE_FEQ_V"] substr(rest, l); next }
      { print }' "$w/t.json" > "$w/e.json"
    {
      cat "$w/t.pre"
      GATE_FEQ_V="$v_new" awk 'NR == 1 { i = index($0, "]"); print "## [" ENVIRON["GATE_FEQ_V"] substr($0, i); next } { print }' "$w/r.head"
      cat "$w/t.head" "$w/t.rest"
    } > "$w/e.log"
    pm=$(gate_iso_git "$dir" ls-tree "$t" -- "$GATE_META_PLUGIN" | awk '{ print $1 }')
    lm=$(gate_iso_git "$dir" ls-tree "$t" -- "$GATE_META_LOG" | awk '{ print $1 }')
    [ -n "$pm" ] && [ -n "$lm" ] || fail "T does not carry both release files"
    blob_p=$(gate_iso_git "$dir" hash-object -w --no-filters "$w/e.json") || fail "could not write the expected plugin.json"
    blob_l=$(gate_iso_git "$dir" hash-object -w --no-filters "$w/e.log") || fail "could not write the expected changelog"
    GIT_INDEX_FILE="$w/index" gate_iso_git "$dir" read-tree "$mt" 2>/dev/null || fail "could not read the merged tree"
    GIT_INDEX_FILE="$w/index" gate_iso_git "$dir" update-index \
      --cacheinfo "$pm,$blob_p,$GATE_META_PLUGIN" --cacheinfo "$lm,$blob_l,$GATE_META_LOG" 2>/dev/null \
      || fail "could not stage the expected release files"
    GIT_INDEX_FILE="$w/index" gate_iso_git "$dir" write-tree 2>/dev/null || fail "could not write the expected tree"
  ) > "$w/out" || rc=$?
  if [ "$rc" = 0 ]; then
    GATE_META_TREE=$(cat "$w/out")
  else
    GATE_META_WHY=$(cat "$w/why" 2>/dev/null || printf 'no answer')
  fi
  rm -rf "$w"
  return "$rc"
}

gate_meta_resolved() {
  # gate_meta_resolved <dir> <R> <H> [<T>] — 0 when H is the honest renumbering
  # merge of R: H's parents are exactly R and some X, X is T or an ancestor of T
  # when T is given, and H's tree is E*(R, X) to the object id. The reason of a
  # 1 is left in `GATE_META_WHY`. Every reader calls it in an isolated object
  # directory of its own, so a judgment leaves nothing behind.
  local dir=$1 r=$2 h=$3 t=${4:-} parents pself p1 p2 extra th e opened=0 rc=0
  GATE_META_WHY=""
  parents=$(gate_iso_git "$dir" rev-list --parents -n 1 "$h" 2>/dev/null) || { GATE_META_WHY="H does not resolve"; return 1; }
  read -r pself p1 p2 extra <<EOF
$parents
EOF
  if [ -z "$p2" ] || [ -n "$extra" ] || [ "$p1" != "$r" ]; then
    GATE_META_WHY="H is not a two-parent merge whose first parent is R"; return 1
  fi
  if [ -n "$t" ]; then
    gate_iso_git "$dir" merge-base --is-ancestor "$p2" "$t" >/dev/null 2>&1 \
      || { GATE_META_WHY="H's second parent is not the base or an ancestor of it"; return 1; }
  fi
  if [ -z "$GATE_ISO_DIR" ]; then gate_iso_open "$dir" || { GATE_META_WHY="no isolated object directory"; return 1; }; opened=1; fi
  release_meta_expected_tree "$dir" "$r" "$p2" || rc=1
  e=$GATE_META_TREE
  th=$(gate_iso_git "$dir" rev-parse "$h^{tree}" 2>/dev/null || true)
  [ "$opened" = 0 ] || gate_iso_close
  [ "$rc" = 0 ] || return 1
  [ -n "$th" ] && [ "$th" = "$e" ] || { GATE_META_WHY="H's tree is not the expected release tree"; return 1; }
}

gate_meta_resolved_export() {
  # gate_meta_resolved_export <segment> <HEAD> — THE RENUMBERING MERGE IS JUDGED
  # HERE AND HANDED TO THE MERGE RULE AS ONE SHA. A release-metadata conflict is
  # resolved by a merge commit whose tree is fixed by R and the base — see
  # `release_meta_expected_tree` — so no review reads it. The rule cannot compute
  # that tree (it is a `/bin/sh` checker that reads no ledger), so the gate
  # proves it against the base the segment's latest `베이스 판정` row named and
  # exports the HEAD it proved. Nothing is exported otherwise; the gate's entry
  # has already unset whatever a caller passed.
  local seg=$1 h=$2 r t wt
  [ -n "$h" ] || return 0
  r=$(gate_base_review_head "$seg") || return 0
  [ "$h" != "$r" ] || return 0
  t=$(gate_row_field "$(gate_base_last_row "$seg")" '베이스')
  wt=$(gate_segment_worktree "$seg")
  if [ -n "$t" ] && gate_meta_resolved "$wt" "$r" "$h" "$t"; then
    GATE_META_RESOLVED_HEAD=$h
    export GATE_META_RESOLVED_HEAD
  fi
  return 0
}

gate_base_next() {
  # gate_base_next <segment> <다음 of the table> — the overlay. First the subject
  # the base checks judge, the way base-check picks it:
  #   HEAD is R, or R's tree                      R
  #   HEAD is the honest renumbering merge of R   that merge
  #     onto the base a check observed
  #   HEAD moved past R otherwise                 none — 해소 리뷰
  # Then the latest check: `충돌` of that subject → 베이스 해소 (그 수가 3 을
  # 넘으면 베이스 해소 한도), anything else → the table's.
  # THE RENUMBERING IS PROVED, NOT READ OFF THE ROW'S `부류`. A check of the
  # merge itself writes `일치` with `부류=-` as the latest row, and reading the
  # class there would turn a merge the rule lets through into a review.
  # A worktree or a sha that does not resolve leaves the table's value: the
  # merge rule reads the same HEAD and refuses on its own.
  local seg=$1 nx=$2 wt r head brow t subj
  wt=$(gate_segment_worktree "$seg")
  r=$(gate_base_review_head "$seg") || { printf '%s' "$nx"; return 0; }
  head=$(gate_worktree_tip "$wt") || { printf '%s' "$nx"; return 0; }
  brow=$(gate_base_last_row "$seg")
  subj=$r
  if [ "$head" != "$r" ] \
     && [ "$(gate_iso_git "$wt" rev-parse "$head^{tree}" 2>/dev/null || true)" != "$(gate_iso_git "$wt" rev-parse "$r^{tree}" 2>/dev/null || true)" ]; then
    t=$(gate_row_field "$brow" '베이스')
    if [ -n "$t" ] && gate_meta_resolved "$wt" "$r" "$head" "$t"; then
      subj=$head
    else
      printf '해소 리뷰'; return 0
    fi
  fi
  if [ "$(gate_row_field "$brow" '판정')" = '충돌' ] \
     && [ "$(gate_commit_in "$wt" "$(gate_row_field "$brow" '판정 HEAD')" || true)" = "$subj" ]; then
    if [ "$(gate_base_conflict_count "$seg")" -gt 3 ]; then printf '베이스 해소 한도'; else printf '베이스 해소'; fi
    return 0
  fi
  printf '%s' "$nx"
}

gate_base_check_row() {
  # gate_base_check_row <segment> <alias> <argv…> — the `base-check` arm: judge
  # the segment's R (or its renumbering merge) against the remote's base and
  # write the `베이스 판정` row. Refused with GATE_EXIT_RULE when there is no R,
  # when HEAD has moved past it, when the remote does not answer or when its tip
  # is not here yet; nothing is written then.
  local seg=$1 al=$2 wt r head subj t last v cf cls rc=0 mt n
  shift 2
  if [ $# -gt 0 ]; then
    warn "\`base-check\` takes nothing after -- — R, the base and the verdict are the gate's: $*"
    return "$GATE_EXIT_VOCAB"
  fi
  wt=$(gate_segment_worktree "$seg")
  [ -n "$wt" ] && [ -d "$wt" ] || { warn "segment $seg has no worktree to judge: '${wt:-(none)}'"; return "$GATE_EXIT_RULE"; }
  if ! r=$(gate_base_review_head "$seg"); then
    warn "the review of $seg does not let a merge through (다음=$(gate_segment_review_next_table "$seg")) — base-check judges a segment whose review reads 머지 or 이월 머지"
    return "$GATE_EXIT_RULE"
  fi
  head=$(gate_worktree_tip "$wt") || { warn "cannot read the HEAD of $wt"; return "$GATE_EXIT_RULE"; }
  t=$(gate_base_remote_tip "$al" "$wt") || return "$GATE_EXIT_RULE"
  if ! gate_commit_in "$wt" "$t" >/dev/null; then
    warn "the base tip $t the remote reports is not in this repository — fetch the base first (the gate does not fetch), then call base-check again"
    return "$GATE_EXIT_RULE"
  fi
  subj=$r
  if [ "$head" != "$r" ]; then
    if [ "$(gate_iso_git "$wt" rev-parse "$head^{tree}" 2>/dev/null || true)" = "$(gate_iso_git "$wt" rev-parse "$r^{tree}" 2>/dev/null || true)" ]; then
      subj=$head
    elif gate_meta_resolved "$wt" "$r" "$head" "$t"; then
      subj=$head
    else
      warn "the HEAD of $seg ($head) moved past the reviewed $r and is not a renumbering merge of it onto $t ($GATE_META_WHY) — 다음 is 해소 리뷰; review first"
      return "$GATE_EXIT_RULE"
    fi
  fi
  # THE SAME QUESTION ASKED TWICE IS ONE ROW. The conflict cap counts rows, so a
  # second check of the same R, HEAD and base would spend it on nothing.
  last=$(gate_base_last_row "$seg")
  if [ -n "$last" ] && [ "$(gate_row_field "$last" '리뷰 HEAD')" = "$r" ] \
     && [ "$(gate_row_field "$last" '판정 HEAD')" = "$subj" ] && [ "$(gate_row_field "$last" '베이스')" = "$t" ]; then
    log "베이스 판정 — $seg 는 이미 같은 판정이 있습니다: $(gate_row_field "$last" '판정') (다음=$(gate_segment_review_next "$seg"))"
    return 0
  fi
  cf='-'; cls='-'
  if gate_iso_git "$wt" merge-base --is-ancestor "$t" "$subj" >/dev/null 2>&1; then
    v='일치'
  else
    gate_iso_open "$wt" || { warn "could not open an isolated object directory for $wt"; return "$GATE_EXIT_RULE"; }
    mt=$(gate_merge_tree "$wt" "$subj" "$t") || rc=$?
    case "$rc" in
      0) v='이동' ;;
      1) v='충돌'
         cf=$(printf '%s\n' "$mt" | sed '1d' | awk 'NF' | paste -sd, -)
         [ -n "$cf" ] || cf='-'
         if [ "$subj" = "$r" ] && release_meta_expected_tree "$wt" "$r" "$t"; then
           cls='릴리스 메타'
         else
           cls='일반'
         fi ;;
      *) gate_iso_close
         warn "the merge of $subj and $t did not answer (git rc=$rc)"
         return "$GATE_EXIT_RULE" ;;
    esac
    gate_iso_close
  fi
  # A long conflict list is clipped, not the row: the cap is the row's.
  n=$(printf '%s' "$cf" | tr ',' '\n' | gate_count)
  if [ "${#cf}" -gt 400 ]; then cf="$(printf '%s' "$cf" | cut -c1-400)…(${n}개)"; fi
  gate_append '베이스 판정' "세그먼트=$seg" "리뷰 HEAD=$r" "판정 HEAD=$subj" "베이스=$t" \
    "판정=$v" "충돌 파일=$cf" "부류=$cls" "기록 시각=$(now_iso)"
  log "베이스 판정 — $seg: $v$( [ "$cls" = '-' ] || printf ' (%s)' "$cls") (다음=$(gate_segment_review_next "$seg"))"
}

gate_meta_merge() {
  # gate_meta_merge <segment> — the fixed helper a resolution stage runs for a
  # `부류=릴리스 메타` conflict: builds the merge commit M whose parents are R
  # and the base T of the segment's latest `베이스 판정` row and whose tree is
  # E*(R, T), and moves the worktree's branch to it with a fast-forward. It
  # writes into the repository and pushes nothing; the stage pushes M.
  local seg=$1 wt row r t head e m
  wt=$(gate_segment_worktree "$seg")
  [ -n "$wt" ] && [ -d "$wt" ] || { warn "segment $seg has no worktree: '${wt:-(none)}'"; return "$GATE_EXIT_RULE"; }
  row=$(gate_base_last_row "$seg")
  if [ "$(gate_row_field "$row" '판정')" != '충돌' ] || [ "$(gate_row_field "$row" '부류')" != '릴리스 메타' ]; then
    warn "the latest 베이스 판정 of $seg is not a 릴리스 메타 conflict — the helper builds only that merge"
    return "$GATE_EXIT_RULE"
  fi
  r=$(gate_commit_in "$wt" "$(gate_row_field "$row" '리뷰 HEAD')") || { warn "R does not resolve in $wt"; return "$GATE_EXIT_RULE"; }
  t=$(gate_commit_in "$wt" "$(gate_row_field "$row" '베이스')") || { warn "the base does not resolve in $wt — fetch it first"; return "$GATE_EXIT_RULE"; }
  head=$(gate_worktree_tip "$wt") || { warn "cannot read the HEAD of $wt"; return "$GATE_EXIT_RULE"; }
  [ "$head" = "$r" ] || { warn "the HEAD of $seg ($head) is not R ($r) — the helper merges R only"; return "$GATE_EXIT_RULE"; }
  release_meta_expected_tree "$wt" "$r" "$t" || { warn "no expected tree: $GATE_META_WHY"; return "$GATE_EXIT_RULE"; }
  e=$GATE_META_TREE
  m=$( (cd "$wt" && printf 'merge: 베이스 %s 위에 릴리스 메타를 다시 매긴다\n' "$(printf '%s' "$t" | cut -c1-12)" \
        | git commit-tree "$e" -p "$r" -p "$t") ) || { warn "git commit-tree failed"; return "$GATE_EXIT_RULE"; }
  ( cd "$wt" && git merge --ff-only --quiet "$m" ) || { warn "could not fast-forward $wt to $m"; return "$GATE_EXIT_RULE"; }
  printf '%s\n' "$m"
}

gate_segment_body_source() {
  # gate_segment_body_source <segment> — where a residual or carry-over body
  # says its findings came from: `PR <n>` from the latest segment row that names
  # a numeric pull request, else `PR <n>` from the manifest's `세그먼트 입양` row
  # for the segment, else `브랜치 <branch>` from the latest segment row that
  # names a branch; status 1 when none stands.
  #
  # A SEGMENT WITH NO PULL REQUEST IS THE ORDINARY CASE BEFORE A MERGE. A
  # review-before-merge segment opens its pull request only once the review has
  # passed, so a segment parked or carried over after its re-check has none,
  # and refusing the body there left the park with no issue at all. The branch
  # is on the segment's planned row already, and the body names the reviewed
  # HEAD beside it.
  #
  # AN ADOPTED SEGMENT ALREADY HAS ONE. The `plan` arm plans it from the
  # adoption row's worktree and branch and never copies the row's `PR` onto a
  # segment row, so without this the body named the branch of a segment whose
  # pull request the manifest declares. The adoption row is read here rather
  # than stamped onto the planned row: the ledger bytes stay as they are, a run
  # planned before this rule still gets it, and a later segment row that names
  # its own pull request still wins.
  local seg=$1 pr br adopt
  # The latest segment row that names a PR: a later state row need not repeat it.
  pr=$(gate_rows 'segment' | gate_rows_field_eq 'id' "$seg" | gate_rows_field_values 'PR' \
         | awk 'NF { v = $0 } END { print v }')
  pr=${pr##*/}; pr=${pr#\#}
  case "$pr" in
    ''|*[!0-9]*) : ;;
    *) printf 'PR %s' "$pr"; return 0 ;;
  esac
  if adopt=$(gate_adoption_row "$seg" 2>/dev/null) && [ -n "$adopt" ]; then
    pr=$(manifest_row_fields "$adopt" 'PR')
    case "$pr" in
      ''|*[!0-9]*) : ;;
      *) printf 'PR %s' "$pr"; return 0 ;;
    esac
  fi
  br=$(gate_rows 'segment' | gate_rows_field_eq 'id' "$seg" | gate_rows_field_values '브랜치' \
         | awk 'NF { v = $0 } END { print v }')
  [ -n "$br" ] || return 1
  printf '브랜치 %s' "$br"
}

gate_carry_body() {
  # gate_carry_body <segment> — writes the body file of every carry-over item of
  # the segment's last cycle to `$RUN_DIR/carry/<segment>-<사이클>-<k>.md` and
  # prints, per item, `이월 <k> 제목=<issue title>` and `이월 <k> 본문 파일=<path>`.
  # Refused with GATE_EXIT_RULE unless the segment's `다음` is `이월`.
  #
  # THE GATE WRITES THE FILE, NOT THE SHIFT. The run directory is an allow-list
  # for a session's own writes, and a body file a shift wrote there with the
  # file-edit tool was refused before a single issue was opened, so every
  # carry-over fell back to the fix cycle it exists to end. Writing it here also
  # makes "every path files the same bytes" a property of one function rather
  # than of each reader's transcription of the report: the bytes are the
  # parser's, the same parser the eligibility read.
  #
  # The body is the item's body lines and then one line naming the pull request
  # and the cycle — or, on a segment with no pull request yet, its branch, the
  # cycle and that cycle's `리뷰 HEAD`; the title is
  # `[이월] <run id> <segment> 사이클 <n> — <title>`, the title
  # `gate_review_carry_row` later asks the remote for. A segment whose rows name
  # neither a pull request nor a branch is refused with GATE_EXIT_RULE.
  local seg=$1 nx row c rep counts src k n t f tmp src_line
  case "$seg" in
    ''|-|*/*|.*) warn "carry-body needs --segment naming one segment"; return "$GATE_EXIT_VOCAB" ;;
  esac
  nx=$(gate_segment_review_next "$seg")
  if [ "$nx" != "이월" ]; then
    warn "the next disposition of $seg is 「${nx}」, not 「이월」 — there is nothing to carry over"
    return "$GATE_EXIT_RULE"
  fi
  row=$(gate_segment_last_cycle_row "$seg")
  c=$(gate_row_field "$row" '사이클')
  rep=$(gate_report_abs "$(gate_row_field "$row" '리포트 경로')")
  counts=$(gate_review_report_counts "$rep") || counts=''
  if ! src=$(gate_segment_body_source "$seg"); then
    warn "the segment rows of $seg carry neither a pull request nor a branch — the body names where the finding came from"
    return "$GATE_EXIT_RULE"
  fi
  case "$src" in
    'PR '*) src_line=$(printf 'PR #%s 의 리뷰 사이클 %s 에서 넘어온 항목입니다.' "${src#PR }" "$c") ;;
    *) src_line=$(printf '브랜치 %s 의 리뷰 사이클 %s(리뷰 HEAD %s) 에서 넘어온 항목입니다.' \
         "${src#브랜치 }" "$c" "$(gate_row_field "$row" '리뷰 HEAD')") ;;
  esac
  n=$(gate_report_count "$counts" '태그 이월 가능')
  gate_canon_count "$n" && [ "$n" -ge 1 ] || { warn "the report of $seg's last cycle has no carry-over item: $rep"; return "$GATE_EXIT_RULE"; }
  mkdir -p "$RUN_DIR/carry" || return "$GATE_EXIT_RULE"
  k=1
  while [ "$k" -le "$n" ]; do
    t=$(gate_report_count "$counts" "이월 $k 제목")
    f="$RUN_DIR/carry/$seg-$c-$k.md"
    tmp=$(mktemp "$RUN_DIR/carry/.body.XXXXXX") || return "$GATE_EXIT_RULE"
    {
      printf '%s\n' "$counts" | GATE_FEQ_K="이월 $k 본문" awk '
        { p = index($0, "=") }
        p && substr($0, 1, p - 1) == ENVIRON["GATE_FEQ_K"] { print substr($0, p + 1) }'
      printf '%s\n' "$src_line"
    } > "$tmp" && mv -f "$tmp" "$f" || { rm -f "$tmp"; return "$GATE_EXIT_RULE"; }
    printf '이월 %s 제목=[이월] %s %s 사이클 %s — %s\n' "$k" "$RUN_ID" "$seg" "$c" "$t"
    printf '이월 %s 본문 파일=%s\n' "$k" "$f"
    k=$((k + 1))
  done
}

gate_residual_body() {
  # gate_residual_body <segment> — writes the body of the one issue a segment
  # parked with `리뷰 잔여` files, to `$RUN_DIR/carry/<segment>-<사이클>-잔여.md`,
  # and prints three lines: `잔여 제목=[잔여] <run id> <segment> 사이클 <n> —
  # <부류>`, `잔여 본문 파일=<path>` and `잔여 부류=<부류>`. The router and the
  # driver both call this and start the `blocked` row's `근거` with the third.
  #
  # THE CLASS. With `다음=잔여 보류` it comes from the re-check report: P0 above
  # zero is `P0 잔존`, a `P1 분류` line that does not parse is `분류 미상`, and
  # anything else is `차단 P1`. With `다음=이월` on a re-check it is `이월 실패`
  # — a carry-over that failed leaves the ledger as it was, so `다음` still
  # reads `이월` — and the body lists every carry-over item. Any other `다음`,
  # and a segment whose rows name neither a pull request nor a branch, is
  # refused with GATE_EXIT_RULE.
  #
  # THE FIRST LINE NAMES THE SOURCE AND THE LAST RE-CHECK, THE SECOND THE
  # LADDER. The pull request when a segment row names one, otherwise the
  # segment's branch and the last cycle's `리뷰 HEAD`; then
  # `확인 리뷰 <K> 회 · 재수렴 있음|없음`, so the reader sees at once whether the
  # segment stopped at the outer cap.
  #
  # EVERY P0 AND EVERY P1, TAGS AND ALL. A carry-over is all or nothing, so a
  # segment parked here carried nothing, and the park row holds no report path:
  # this issue is the one durable record a person gets. A `이월 가능` P1 left
  # out of it is a finding no issue holds. Each P1 line keeps its own
  # `**[차단]**` or `**[이월 가능]**` tag, so the reader still sees which ones
  # blocked the carry-over.
  #
  # The body names the findings by their heading lines, the pull request and
  # the cycle, never the report's path; a `docs/` path inside a heading is
  # left out of the issue.
  local seg=$1 nx row c rep counts src cls f tmp n k walk first
  case "$seg" in
    ''|-|*/*|.*) warn "residual-body needs --segment naming one segment"; return "$GATE_EXIT_VOCAB" ;;
  esac
  nx=$(gate_segment_review_next "$seg")
  row=$(gate_segment_last_cycle_row "$seg")
  rep=$(gate_report_abs "$(gate_row_field "$row" '리포트 경로')")
  counts=$(gate_review_report_counts "$rep") || counts=''
  case "$nx" in
    '잔여 보류')
      if [ "$(gate_row_field "$row" 'P0')" != "0" ]; then cls='P0 잔존'
      elif [ "$(gate_report_count "$counts" '분류')" != "정규" ]; then cls='분류 미상'
      else cls='차단 P1'
      fi ;;
    이월)
      if ! gate_segment_last_cycle_is_recheck "$seg"; then
        warn "the next disposition of $seg is 「이월」 but its last cycle is not the re-check — there is no residual"
        return "$GATE_EXIT_RULE"
      fi
      cls='이월 실패' ;;
    *)
      warn "the next disposition of $seg is 「${nx}」, not 「잔여 보류」 or a failed carry-over — there is no residual"
      return "$GATE_EXIT_RULE" ;;
  esac
  c=$(gate_row_field "$row" '사이클')
  if ! src=$(gate_segment_body_source "$seg"); then
    warn "the segment rows of $seg carry neither a pull request nor a branch — the body names where the findings came from"
    return "$GATE_EXIT_RULE"
  fi
  case "$src" in
    'PR '*) first=$(printf 'PR #%s 의 확인 리뷰(사이클 %s) 뒤에 남은 발견입니다. 사유 부류: %s' "${src#PR }" "$c" "$cls") ;;
    *) first=$(printf '브랜치 %s 의 확인 리뷰(사이클 %s, 리뷰 HEAD %s) 뒤에 남은 발견입니다. 사유 부류: %s' \
         "${src#브랜치 }" "$c" "$(gate_row_field "$row" '리뷰 HEAD')" "$cls") ;;
  esac
  walk=$(gate_segment_review_walk "$seg")
  mkdir -p "$RUN_DIR/carry" || return "$GATE_EXIT_RULE"
  f="$RUN_DIR/carry/$seg-$c-잔여.md"
  tmp=$(mktemp "$RUN_DIR/carry/.body.XXXXXX") || return "$GATE_EXIT_RULE"
  {
    printf '%s\n' "$first"
    printf '확인 리뷰 %s 회 · 재수렴 %s\n\n' "$(gate_report_count "$walk" '확인 리뷰 수')" \
      "$( [ "$(gate_report_count "$walk" '재수렴 뒤')" = 1 ] && printf '있음' || printf '없음')"
    if [ "$cls" = '이월 실패' ]; then
      n=$(gate_report_count "$counts" '태그 이월 가능')
      k=1
      while gate_canon_count "$n" && [ "$k" -le "$n" ]; do
        printf -- '- %s\n' "$(gate_report_count "$counts" "이월 $k 제목")"
        printf '%s\n' "$counts" | GATE_FEQ_K="이월 $k 본문" awk '
          { p = index($0, "=") }
          p && substr($0, 1, p - 1) == ENVIRON["GATE_FEQ_K"] { print "  " substr($0, p + 1) }'
        k=$((k + 1))
      done
    else
      LC_ALL=C awk '
        BEGIN { R = "\360\237\224\264"; O = "\360\237\237\240" }
        { line = $0; sub(/[ \t\r]+$/, "", line) }
        index(line, "## ") == 1 {
          sec = ""
          if (index(line, "## " R " P0") == 1) sec = "p0"
          else if (index(line, "## " O " P1") == 1) sec = "p1"
          next
        }
        sec == "" { next }
        index(line, "- ") != 1 && index(line, "### ") != 1 { next }
        { sub(/^### /, "- ", line); gsub(/[^ `]*docs\/[^ `]*/, "(문서 경로 생략)", line)
          print (sec == "p0" ? "[P0] " : "[P1] ") substr(line, 3) }' "$rep" 2>/dev/null | sed 's/^/- /'
    fi
  } > "$tmp" && mv -f "$tmp" "$f" || { rm -f "$tmp"; return "$GATE_EXIT_RULE"; }
  printf '잔여 제목=[잔여] %s %s 사이클 %s — %s\n' "$RUN_ID" "$seg" "$c" "$cls"
  printf '잔여 본문 파일=%s\n' "$f"
  printf '잔여 부류=%s\n' "$cls"
}

gate_review_line() {
  # gate_review_line <segment> [<flag>…] — prints the prompt of a review
  # dispatch of the segment, built the way the fixed-graph driver builds its
  # own: `/cc-cmds:review-unattended <브랜치> --report-path <경로>[ --slice
  # <id>][ --base-sha <sha>][ --declared-files "<집합>"][ <flag>…] "설계는
  # <문서>"`. Refused with GATE_EXIT_RULE when the segment has no row or no
  # branch to review.
  #
  # THE ROUTER HAD NOTHING TO SPELL THIS FROM. The lead fix, the re-check, the
  # resolution review and the delta review are each written as "the segment's
  # review prompt plus a flag", and neither the snapshot nor the ledger keeps
  # that prompt. Shifts rebuilt it by grepping earlier stage streams; when the
  # grep found nothing they ended on `사유=중단` with no stage alive, one shift
  # after another. Built here from the rows, the prompt is the same on every
  # shift and needs no memory of an earlier one.
  #
  # The report path is the canonical one, `gate_review_report_path`: every
  # `cycle` row of the segment, resolution rows included, plus one, under
  # `docs/reviews/` of the run's base. A review that crashed and is sent again
  # therefore names the same report, and two resolution reviews in a row do not.
  #
  # The declared set is the last value any of the segment's rows carried — a
  # later state row does not repeat it — and a value the row writer clipped is
  # read back whole from the file the row names.
  #
  # The caller's flags go in before the directive, because the review reads its
  # document argument from `설계는 ` to the end of the prompt. `--no-slice` is
  # the gate's own and never reaches the prompt: it drops `--slice` for the one
  # review that answers a `cycle` row refused for its other-slice section.
  local seg=$1 rows br n rp base decl side doc line a slice=1
  local -a extra=()
  shift
  for a in "$@"; do
    if [ "$a" = "--no-slice" ]; then slice=0; else extra+=("$a"); fi
  done
  case "$seg" in
    ''|-|*/*|.*) warn "review-line needs --segment naming one segment"; return "$GATE_EXIT_VOCAB" ;;
  esac
  rows=$(gate_rows 'segment' | gate_rows_field_eq 'id' "$seg")
  if [ -z "$rows" ]; then
    warn "segment $seg has no segment row — there is no branch to review"
    return "$GATE_EXIT_RULE"
  fi
  br=$(printf '%s\n' "$rows" | gate_rows_field_values '브랜치' | awk 'NF { v = $0 } END { print v }')
  if [ -z "$br" ]; then
    warn "no segment row of $seg names a branch — there is no branch to review"
    return "$GATE_EXIT_RULE"
  fi
  rp=$(gate_review_report_path "$seg")
  line="/cc-cmds:review-unattended $br --report-path $rp"
  if [ "$slice" = "1" ] && [ "$(gate_slicing_branch)" = "선언통치" ]; then line="$line --slice $seg"; fi
  base=$(printf '%s\n' "$rows" | gate_rows_field_values '베이스 sha' | awk 'NF { v = $0 } END { print v }')
  [ -z "$base" ] || line="$line --base-sha $base"
  decl=$(gate_segment_declared_whole "$seg") || decl=''
  case "$decl" in ''|'없음'|'(없음)') : ;; *) line="$line --declared-files \"$decl\"" ;; esac
  # The seat commits ride as a flag of their own: they are commits a stage did
  # not write, so the review is told which ones to read as the gate's.
  side=$(gate_segment_seat_commits "$seg")
  [ "$side" = "없음" ] || line="$line --seat-commits \"$side\""
  [ "${#extra[@]}" -eq 0 ] || line="$line ${extra[*]}"
  doc=$(gate_doc_arg_path)
  [ -z "$doc" ] || line="$line \"설계는 $doc\""
  printf '%s\n' "$line"
}

gate_segment_seat_commits() {
  # gate_segment_seat_commits <segment> — the seat commits of this run's
  # `좌석 적용` answers for the segment, in ledger order, as
  # `<sha> (<경로>, …); <sha> (<경로>, …)`, or `없음`. The paths are the ones
  # the commit changed, read off the commit; a commit the segment worktree
  # cannot find says so instead. The review line, the implement dispatch line
  # and the snapshot all print this, so the three cannot spell it differently.
  local seg="$1" wt r row s ps out=''
  wt=$(gate_segment_worktree "$seg" 2>/dev/null) || wt=''
  while IFS= read -r r; do
    [ -n "$r" ] || continue
    row=${r#*:}
    [ "$(gate_row_field "$row" '세그먼트')" = "$seg" ] || continue
    [ -z "$(gate_row_field "$row" '출처 런')" ] || continue
    [ "$(gate_row_field "$row" '선택지')" = '좌석 적용' ] || continue
    s=$(gate_row_field "$row" '좌석 커밋')
    [ -n "$s" ] || continue
    ps=''
    if [ -n "$wt" ] && [ -d "$wt" ] && (cd "$wt" && git cat-file -e "$s^{commit}") 2>/dev/null; then
      ps=$( { cd "$wt" && git -c core.quotePath=false diff-tree --no-renames -r -z --name-only "$s^" "$s" 2>/dev/null; } \
            | tr '\0' '\n' | awk 'NF { printf "%s%s", (n++ ? ", " : ""), $0 }') || ps=''
    else
      ps='커밋을 찾을 수 없음'
    fi
    out="$out${out:+; }$s (${ps:-변경 없음})"
  done <<EOF
$( { grep -n "^- \`중단 답\` " "$LEDGER" 2>/dev/null || true; } )
EOF
  printf '%s' "${out:-없음}"
}

gate_segment_surface_paths() {
  # gate_segment_surface_paths <segment> — the declared paths the classifier
  # names, as `<경로> (<분류>), …`, `없음`, or `판정불가` when the declared set
  # cannot be read whole or the classifier cannot be loaded. Recomputed from
  # `선언 파일 집합` rather than stored, because a row has a byte cap and the
  # list is a pure function of that field.
  local seg="$1" decl p out rc=0
  decl=$(gate_segment_declared_whole "$seg") || { printf '판정불가'; return 0; }
  case "$decl" in ''|'없음'|'(없음)') printf '없음'; return 0 ;; esac
  out=$(printf '%s' "$decl" | tr ',' '\n' | sed -e 's/^[[:space:]]*//' -e 's/[[:space:]]*$//' \
        | awk 'NF' | tr '\n' '\0' | gate_es gate__es_class_z) || rc=$?
  [ "$rc" != 2 ] || { printf '판정불가'; return 0; }
  [ -n "$out" ] || { printf '없음'; return 0; }
  printf '%s\n' "$out" | awk -F '\t' 'NF >= 2 { printf "%s%s (%s)", (n++ ? ", " : ""), $2, $1 }'
}

gate_carry_issue_view() {
  # gate_carry_issue_view <slug> <number> — `<state>\t<title>` of that issue as
  # the remote answers it, with the state `pr` when the number is a pull request
  # (the issues endpoint answers for both). Status 1 when `gh` is missing or the
  # remote does not answer, which the caller refuses on — the same rule as
  # `gate_remote_landing`: cannot judge is never a pass.
  local out
  command -v gh >/dev/null 2>&1 || return 1
  out=$(gh api "repos/$1/issues/$2" \
          --jq '(if .pull_request then "pr" else .state end) + "\t" + .title' 2>/dev/null) || return 1
  [ -n "$out" ] || return 1
  printf '%s' "$out"
}

gate_review_carry_row() {
  # gate_review_carry_row <segment> <키=값>… — one `리뷰 이월` row: the open P1
  # findings of the segment's last cycle were carried over to issues. The act
  # arm `review-carry` and the driver both call this, so the checks and the row
  # cannot differ between the two paths. Returns GATE_EXIT_VOCAB and writes
  # nothing for a malformed call, GATE_EXIT_RULE for one the run's state
  # refuses; otherwise whatever `gate_append` answers.
  #
  # NOT SEAT ONLY, unlike `리뷰 기각`. A dismissal is a person overriding a
  # review; a carry-over is the routing shift and the driver doing what the
  # review itself classified, and the eligibility check below is what holds it
  # to that classification.
  #
  # BOUND TO THE LAST CYCLE BY FIELD EQUALITY, by number and by head, the same
  # binding a dismissal takes. A second row for the same `<사이클>@<리뷰 HEAD>`
  # is refused: a shift that retries after its row landed reads
  # `다음=이월 머지` and goes to the merge instead.
  #
  # THE KEYS ARE LITERAL. `lint-sidecar-field-table.sh` compares a series with
  # the contract's field table only when every key of its append is a literal,
  # so passing the caller's argv through would silently switch that check off.
  local seg=${1:-} rf rk rseen=' ' rcyc rhead rn riss row rslug u n=0 useen=' ' rlane rat el
  shift || true
  if [ -z "$seg" ] || [ "$seg" = "-" ]; then
    warn "a \`리뷰 이월\` row needs --segment — it carries over the findings of one segment's last cycle"
    return "$GATE_EXIT_VOCAB"
  fi
  for rf in "$@"; do
    rk="${rf%%=*}"
    case "$rk" in
      사이클|리뷰\ HEAD|건수|이슈) ;;
      *) warn "a \`리뷰 이월\` row takes \`사이클\`, \`리뷰 HEAD\`, \`건수\` and \`이슈\` from argv and nothing else: ${rk} — the rest is the gate's"
         return "$GATE_EXIT_VOCAB" ;;
    esac
    case "$rseen" in
      *" $rk "*) warn "a \`리뷰 이월\` row takes \`${rk}\` once"; return "$GATE_EXIT_VOCAB" ;;
    esac
    rseen="$rseen$rk "
  done
  rcyc=$(gate_field_of '사이클' "$@"); rhead=$(gate_field_of '리뷰 HEAD' "$@")
  rn=$(gate_field_of '건수' "$@"); riss=$(gate_field_of '이슈' "$@")
  if [ -z "$rcyc" ] || [ -z "$rhead" ] || [ -z "$rn" ] || [ -z "$riss" ]; then
    warn "a \`리뷰 이월\` row needs \`사이클\` and \`리뷰 HEAD\` (of the cycle carried over), \`건수\` and \`이슈\`"
    return "$GATE_EXIT_VOCAB"
  fi
  row=$(gate_segment_last_cycle_row "$seg")
  [ -n "$row" ] || { warn "no \`cycle\` row names $seg — there is no review to carry over"; return "$GATE_EXIT_VOCAB"; }
  if [ "$(gate_row_field "$row" '사이클')" != "$rcyc" ] \
     || [ "$(gate_row_field "$row" '리뷰 HEAD')" != "$rhead" ]; then
    warn "the last \`cycle\` row of $seg is 사이클=$(gate_row_field "$row" '사이클') 리뷰 HEAD=$(gate_row_field "$row" '리뷰 HEAD') — a carry-over names that cycle exactly"
    return "$GATE_EXIT_VOCAB"
  fi
  if gate_cycle_carried "$seg" "$rcyc" "$rhead"; then
    warn "cycle $rcyc@$rhead of $seg is already carried over — read \`다음\` again; it is \`이월 머지\`"
    return "$GATE_EXIT_RULE"
  fi
  el=$(gate_carry_eligibility "$seg")
  if [ "$el" != "적격" ]; then
    warn "the last cycle of $seg is not eligible for carry-over (${el}) — read \`다음\` again; it is not \`이월\`"
    return "$GATE_EXIT_RULE"
  fi
  if [ "$rn" != "$(gate_row_field "$row" 'P1')" ]; then
    warn "\`건수\` ($rn) is not the P1 of the last cycle ($(gate_row_field "$row" 'P1')) — every carry-over item is carried, one issue each"
    return "$GATE_EXIT_VOCAB"
  fi
  rslug=$(seg_slug "$seg" 2>/dev/null) || rslug=''
  [ -n "$rslug" ] || { warn "cannot resolve the repository slug of $seg — the issues cannot be checked"; return "$GATE_EXIT_VOCAB"; }
  while IFS= read -r u; do
    case "$u" in
      "https://github.com/$rslug/issues/"[1-9]*) ;;
      *) warn "\`이슈\` takes issue URLs of $rslug only, comma-separated: '$u'"; return "$GATE_EXIT_VOCAB" ;;
    esac
    case "${u#"https://github.com/$rslug/issues/"}" in
      *[!0-9]*) warn "\`이슈\` takes issue URLs of $rslug only, comma-separated: '$u'"; return "$GATE_EXIT_VOCAB" ;;
    esac
    case "$useen" in
      *" $u "*) warn "\`이슈\` names $u twice — one issue per carried finding"; return "$GATE_EXIT_VOCAB" ;;
    esac
    useen="$useen$u "; n=$((n + 1))
  done <<EOF
$(printf '%s\n' "$riss" | tr ',' '\n')
EOF
  if [ "$n" != "$rn" ]; then
    warn "\`이슈\` names $n issue(s) but \`건수\` is $rn"
    return "$GATE_EXIT_VOCAB"
  fi
  # EACH URL IS ASKED OF THE REPOSITORY, NOT ONLY READ AS A SHAPE. The row is
  # what lets a cycle with open P1 findings merge, so a URL that names some
  # other issue — copied wrong from a command's output, or any number at all —
  # would carry the finding into nothing. The k-th URL must be an open issue
  # whose title is this run's and this segment's carry-over title for the k-th
  # item of the report, any cycle: a reused issue keeps the cycle it was opened
  # in. A repository that cannot be asked refuses the row as the state of the
  # run, never as a pass.
  local rcounts rk_n=0 rt rv rst rtt
  rcounts=$(gate_review_report_counts "$(gate_report_abs "$(gate_row_field "$row" '리포트 경로')")") || rcounts=''
  while IFS= read -r u; do
    [ -n "$u" ] || continue
    rk_n=$((rk_n + 1))
    rt=$(gate_report_count "$rcounts" "이월 $rk_n 제목")
    if ! rv=$(gate_carry_issue_view "$rslug" "${u##*/}"); then
      warn "cannot ask $rslug about issue ${u##*/} — a carry-over issue that cannot be confirmed is not recorded"
      return "$GATE_EXIT_RULE"
    fi
    rst=${rv%%"$(printf '\t')"*}; rtt=${rv#*"$(printf '\t')"}
    case "$rtt" in
      "[이월] $RUN_ID $seg 사이클 "*" — $rt") rtt=ok ;;
    esac
    if [ "$rst" != "open" ] || [ -z "$rt" ] || [ "$rtt" != "ok" ]; then
      warn "$u is not the open carry-over issue of item $rk_n — its title must read \`[이월] $RUN_ID $seg 사이클 <n> — ${rt:-?}\` (state: ${rst:-?}); take the URL the create or the reuse search printed for that item"
      return "$GATE_EXIT_VOCAB"
    fi
  done <<EOF
$(printf '%s\n' "$riss" | tr ',' '\n')
EOF
  rlane=$(gate_lane_label); rat=$(now_iso)
  # URLs are never clipped: a clipped URL names another issue or none.
  if [ "$(gate_row_projected_bytes '리뷰 이월' "세그먼트=$seg" "사이클=$rcyc" "리뷰 HEAD=$rhead" \
          "건수=$rn" "이슈=$riss" "레인=$rlane" "기록 시각=$rat")" -gt "$GATE_ROW_MAX" ]; then
    warn "the \`리뷰 이월\` row does not fit the row cap — issue URLs are not clipped"
    return "$GATE_EXIT_VOCAB"
  fi
  gate_append '리뷰 이월' "세그먼트=$seg" "사이클=$rcyc" "리뷰 HEAD=$rhead" "건수=$rn" "이슈=$riss" "레인=$rlane" "기록 시각=$rat"
}

gate_cycle_row() {
  # gate_cycle_row <target alias> <segment> <키=값>… — one `cycle` row, by the
  # same code the `cycle` act arm runs: every write-time refusal, the report
  # checks and the `발견 지문` the gate derives behind the caller's fields,
  # including the branch that drops it when the row would cross the cap. The
  # driver calls this through a child shell so its cycle rows meet the checks a
  # routed run's rows meet. Same exit codes as the act arm.
  [ "$#" -ge 2 ] || { warn "gate_cycle_row <target alias> <segment> <키=값>…"; return "$GATE_EXIT_VOCAB"; }
  local ca=$1 cs=$2
  shift 2
  gate_record_row 'cycle' "$cs" "$ca" "$@"
}

gate_segment_merged_row() {
  # gate_segment_merged_row <target alias> <segment> <키=값>… — the terminal
  # `segment` row `상태=머지됨`, by the same code the `segment` act arm runs,
  # so `적용=대기` and the inherited `리뷰 정책` are derived the same way on both
  # paths. The caller passes everything but `상태`; `워크트리` stays required,
  # and `워크트리=-` is the spelling for a tree the merge removed.
  [ "$#" -ge 2 ] || { warn "gate_segment_merged_row <target alias> <segment> <키=값>…"; return "$GATE_EXIT_VOCAB"; }
  local ma=$1 ms=$2 mf
  shift 2
  for mf in "$@"; do
    case "$mf" in
      상태=*) warn "gate_segment_merged_row writes \`상태=머지됨\` itself — leave \`상태\` out"; return "$GATE_EXIT_VOCAB" ;;
    esac
  done
  gate_record_row 'segment' "$ms" "$ma" '상태=머지됨' "$@"
}

gate_answer_servable() {
  # gate_answer_servable <승인 id> — the predicate BOTH forms of `answers` ask,
  # written once. It warns on the way out naming which fact is missing; the
  # listing form silences that stream rather than keeping a second, quieter copy
  # of the same tests, because two copies is how one of them comes to be fixed
  # alone.
  #
  # FOUR FACTS: a `승인` row carries the id, its latest `상태` is `승인`, the
  # issuing row has `절단점=판단`, and the sidecar is on disk.
  # `gate_answered_judgments_json` asks the first and third the same way but NOT
  # the second: it also lists a person-set question closed `거부` or `무효`,
  # with that state on the element, because the router parks on such a refusal.
  # Parking needs the state, never the refusal's words, so this door still serves
  # `승인` alone. The STATE test is the one that used to be
  # missing on this side, and its absence is not cosmetic. `gate_close` writes
  # the answer sidecar BEFORE it branches on a refusal, so a judgment closed as
  # 거부 or 무효 leaves a fully formed file behind — and without this test the
  # door handed a re-dispatched stage the text of a REFUSAL to act on as if it
  # were an instruction.
  #
  # The sidecar write is left where it is. A refusal's own words are a durable
  # record of why the answer was no, and that record has value; what was wrong
  # is the reader, so the reader is where the test goes.
  #
  # The lookups are pinned to whole fields for the reason given there.
  local id="$1" row iss st
  row=$( { gate_rows '승인' | grep -F "| 승인 id=$id |" || true; } | tail -1)
  [ -n "$row" ] || { warn "that approval id is not in the ledger: $id"; return 1; }
  st=$(gate_row_field "$row" '상태')
  [ "$st" = "승인" ] || { warn "that approval was not closed with an answer (\`상태\`=${st:-(none)}) — the refusal text of a judgment closed as rejected or void is not an answer: $id"; return 1; }
  iss=$( { gate_rows '승인' | grep -F "| 승인 id=$id |" || true; } \
         | { grep -F '| 절단점=판단 |' || true; } | tail -1)
  [ -n "$iss" ] || { warn "that approval is not a judgment question — an answer sidecar exists only for \`절단점=판단\`: $id"; return 1; }
  [ -f "$RUN_DIR/answer/$id.md" ] || { warn "the answer sidecar of that approval is missing: $id"; return 1; }
  # THE FILE IS COMPARED AGAINST THE ROW'S DIGEST. The row carries the sha256 of
  # the answer the gate wrote; the file lives in the volatile run directory,
  # which the four ledger facts above say nothing about. Serving it without the
  # comparison means the three ledger tests establish that a person answered and
  # then the bytes handed over are whatever is at that path now — and what reads
  # them is a stage, acting on them as an instruction.
  #
  # A MISSING DIGEST IS NOT A PASS. The field is `-` on rows written before the
  # gate carried it, and treating that as "nothing to compare" would make every
  # such row servable on the strength of its path alone. There is no answer
  # sidecar for those rows either, so this arm is unreachable for them today;
  # it is written as a refusal so that stays true if the store outlives a format.
  local adig afile
  adig=$(gate_row_field "$row" '답변 다이제스트')
  case "$adig" in
    ''|'-') warn "that approval row carries no answer digest — there is no baseline to check the file against, so it is not handed out: $id"; return 1 ;;
  esac
  # The writer stores the answer with a trailing newline that the digest does not
  # cover, so the file is compared with that byte removed — the same bytes the
  # row hashed.
  afile=$(printf '%s' "$(cat "$RUN_DIR/answer/$id.md")" | shasum -a 256 | cut -d' ' -f1)
  [ "$afile" = "$adig" ] || {
    warn "the answer file differs from the answer digest in the ledger — it is not handed out: $id (row $adig · file $afile)"
    return 1
  }
  return 0
}

gate_answers() {
  # gate.sh answers [<승인 id>] — the read-only door onto the answer sidecars.
  #
  # READ-ONLY AND SEPARATE FROM `close` because the readers are different
  # entities: `close` is the router recording a resolution, and this is the
  # re-dispatched STAGE picking up what the person said. A stage that had to
  # call `close` to see an answer would be a stage holding a recording verb.
  #
  # With an id it prints that answer's bytes; without one it lists the ids that
  # pass the same tests, one per line, which is what a reader with no id needs
  # to get one. Neither form fails when the directory is absent — "no answers
  # yet" is the ordinary state of a run and is not an error.
  #
  # THE LEDGER IS ASKED FIRST AND THE FILESYSTEM SECOND. What this verb hands
  # out is the bytes a person typed, and it used to decide on a path existing
  # under `$RUN_DIR/answer/` and nothing else — so any file that landed in that
  # directory was served as an answer, with no row behind it saying a person had
  # ever been asked. The predicate is `gate_answer_servable`, and its ledger
  # part is THREE facts: a `승인` row carries this id,
  # that row's latest `상태` is `승인`, and the row that ISSUED it has
  # `절단점=판단`. This comment used to name the first and the third while
  # calling them three, and the middle one — the state — was the one the code
  # was missing too. An enumeration that miscounts itself is how the gap got
  # past a reader.
  #
  # No new state, and the two forms of this verb cannot disagree about whether
  # an answer is one.
  local id="${1:-}"
  # THE CHARACTER-TYPE PIN, for the `gate_row_field` call the predicate makes.
  # `tr` and `sed` abort on a byte that is not valid in the locale's encoding,
  # and a ledger row is the input most likely to hold one. `local` is dynamic
  # scope in this shell, so this covers the extractor as called from the helper
  # below without touching the shared extractor itself — that one has other
  # callers and a pin of its own to earn.
  local LC_CTYPE=C; export LC_CTYPE
  if [ -n "$id" ]; then
    gate_answer_servable "$id" || return 1
    cat "$RUN_DIR/answer/$id.md"
    return 0
  fi
  [ -d "$RUN_DIR/answer" ] || return 0
  # THE LISTING GOES THROUGH THE SAME PREDICATE. It used to be a bare `find`
  # with no ledger question in it at all, while the comment above calls the
  # id-less form an intended use — so it handed a reader the ids the id form
  # would then refuse, one line at a time, and the reader had no way to tell
  # which of them were answers.
  find "$RUN_DIR/answer" -maxdepth 1 -type f -name '*.md' 2>/dev/null \
    | sed 's#.*/##;s#\.md$##' | sort \
    | while IFS= read -r aid; do
        [ -n "$aid" ] || continue
        gate_answer_servable "$aid" 2>/dev/null || continue
        printf '%s\n' "$aid"
      done
}

gate_field_of() {
  # gate_field_of <key> <키=값>... — the value of the LAST field with that key.
  local key="$1"; shift
  local f out=""
  for f in "$@"; do
    case "$f" in
      "$key"=*) out="${f#"$key"=}" ;;
    esac
  done
  printf '%s' "$out"
}

# ---------------------------------------------------------------------------
# The dependency cone.
#
# A question raises a cone and NOT a run stop: what stands on the refuted
# premise is held, and its siblings keep going. The cone is a PREDICATE, not a
# frozen set — at the moment a question goes up the dependent may not have
# branched yet, and freezing then would leave it outside forever. Everything
# below recomputes from the ledger and the live worktrees each time it is asked.
# ---------------------------------------------------------------------------
gate_segment_ids() {
  gate_rows 'segment' | gate_row_ids | sort -u
}

gate_segment_count_including() {
  # gate_segment_count_including <segment> — how many segments this ledger knows
  # once the row about to be written is counted. The row's own id is included
  # because the question the caller asks is about the state AFTER the write.
  local sid n=0 seen=0
  for sid in $(gate_segment_ids); do
    [ -n "$sid" ] || continue
    n=$((n + 1))
    if [ "$sid" = "$1" ]; then seen=1; fi
  done
  if [ "$seen" != "1" ]; then n=$((n + 1)); fi
  printf '%s' "$n"
}

gate_segment_worktree() { gate_segment_field "$1" '워크트리'; }

gate_segment_terminal() {
  local st
  st=$(gate_segment_field "$1" '상태')
  case " $TERMINAL_SEGMENT_STATES " in *" $st "*) return 0 ;; esac
  return 1
}

gate_common_git_of_dir() {
  # gate_common_git_of_dir <dir> — the absolute common git directory of the
  # repository <dir> is a worktree of, decided FROM THE DIRECTORY ALONE; status
  # 1 when it is not one. The one place this file asks git that question, so
  # the environment it asks in is spelled once.
  #
  # THE INHERITED GIT ENVIRONMENT IS DROPPED FIRST. `git rev-parse` honours
  # `GIT_DIR`, `GIT_COMMON_DIR`, `GIT_WORK_TREE` and `GIT_CEILING_DIRECTORIES`
  # over the working directory, and the gate runs a stage's command with the
  # stage's environment. Measured: a `bash -c` body prefixed `GIT_DIR=<a
  # declared target's .git>` made this answer the declared common directory
  # for `/`, so a non-terminal `segment` row naming `워크트리=/` passed
  # `gate_path_of_some_target` and the root landed on the stage's directory
  # list. The boundary is "is this directory a worktree of a declared target",
  # and a variable can answer that for any directory whatever — so the
  # variables are removed for this one call rather than trusted. `env -u` is
  # POSIX and does nothing when the name is unset. The same four names are on
  # `_gp_env_assign`'s refusal row as an exec form, which catches the prefix
  # on the way in; this is the half that holds when the assignment arrived by
  # some route the grammar did not see.
  local out
  [ -n "$1" ] || return 1
  [ -d "$1" ] || return 1
  out=$( { cd "$1" 2>/dev/null \
           && env -u GIT_DIR -u GIT_COMMON_DIR -u GIT_WORK_TREE -u GIT_CEILING_DIRECTORIES \
                git rev-parse --path-format=absolute --git-common-dir 2>/dev/null; } || true)
  [ -n "$out" ] || return 1
  printf '%s' "$out"
}

gate_segment_common_git() {
  local wt
  wt=$(gate_segment_worktree "$1")
  [ -n "$wt" ] || return 1
  gate_common_git_of_dir "$wt"
}

gate_path_common_git() {
  # gate_path_common_git <path> — the absolute common git directory of the
  # repository <path> is a worktree of; status 1 when it is not one.
  gate_common_git_of_dir "$1"
}

gate_path_of_target() {
  # gate_path_of_target <path> <alias> — 0 only when <path> is a worktree OF
  # THAT TARGET: an absolute path, an existing directory, and a common git
  # directory equal to the target row's. The same predicate the manifest check
  # puts on `실행 워크트리`.
  #
  # ONE PREDICATE FOR EVERYTHING A SEGMENT ROW WIDENS — the stage settings'
  # directory list, the directory a segment act runs in, and now the row itself:
  # a non-terminal `segment` row is refused at write time unless its `워크트리`
  # passes this for some declared target, so the ledger never carries a live
  # row naming a directory the settings could not admit. The contract bounds
  # every widening to a worktree of a target the run already acts in, and a
  # router writing a path from another repository, or one that does not exist,
  # must widen nothing. Status only: which condition failed is the caller's
  # message to write, because only the caller knows what the refusal means.
  #
  # THE COMMON DIRECTORY IS COMPARED IN BOTH SPELLINGS. The manifest records
  # `공통 git 디렉터리` as git printed it at kickoff, and git prints the path it
  # stored when the worktree was added — which for a worktree reached through
  # a symlink is the physical one. A target declared by its link spelling
  # would then never match its own worktrees; resolving both sides with
  # `pwd -P` before the second comparison admits either spelling and nothing
  # a plain string comparison would have refused for a reason other than
  # spelling.
  local wt="$1" cg want cg_p want_p
  case "$wt" in /*) : ;; *) return 1 ;; esac
  [ -d "$wt" ] || return 1
  want=$(target_field "$2" '공통 git 디렉터리')
  [ -n "$want" ] || return 1
  cg=$(gate_path_common_git "$wt") || return 1
  [ "$cg" = "$want" ] && return 0
  cg_p=$(cd "$cg" 2>/dev/null && pwd -P) || return 1
  want_p=$(cd "$want" 2>/dev/null && pwd -P) || return 1
  [ "$cg_p" = "$want_p" ]
}

gate_git_argv_in_target() {
  # gate_git_argv_in_target <alias> <argv...> — 0 only when the repository and
  # working tree this git command acts on are a worktree of THAT TARGET, read
  # from its global flags as git reads them. Any condition that cannot be
  # decided is a no.
  #
  # FOUR CONDITIONS, ALL OF THEM.
  #   1. No git location or configuration variable in the environment the act
  #      inherits — the gate's own, and an assignment written ahead of git in
  #      argv on the line `gate_push_base_updates` draws: `LANG`, `LC_*` and
  #      `TZ` only. Such a variable moves the repository git opens past every
  #      flag the argv carries, so a flag reading cannot speak for it.
  #   2. Every global flag was read (`GATE_GIT_UNREAD` empty).
  #   3. The common git directory git names for these location flags, asked in
  #      the act's directory with the inherited variables removed, is the
  #      target row's `공통 git 디렉터리` — compared as `gate_path_of_target`
  #      compares it, as written and then physically. The query is absolute so
  #      the main worktree compares too. Removing the variables is safe only
  #      because condition 1 already refused an act that would carry them.
  #   4. The top of the working tree is, physically, one of the `worktree`
  #      entries the target's own `git worktree list --porcelain` prints. A
  #      `--work-tree` pointing anywhere else checks files out somewhere the
  #      target's common directory does not own.
  local alias="$1"; shift
  local a v cmd_seen=0 out cg top want cg_p want_p top_p wt line
  for a in "$@"; do
    case "${a##*/}" in git) cmd_seen=1; break ;; esac
    case "$a" in
      LANG=*|LC_*=*|TZ=*) continue ;;
    esac
    [ "${a##*/}" = env ] && continue
    return 1
  done
  [ "$cmd_seen" = 1 ] || return 1
  while [ "$#" -gt 0 ]; do
    case "${1##*/}" in git) shift; break ;; esac
    shift
  done
  for v in GIT_DIR GIT_COMMON_DIR GIT_WORK_TREE GIT_NAMESPACE GIT_OBJECT_DIRECTORY ${!GIT_CONFIG@}; do
    [ -z "${!v+x}" ] || return 1
  done
  gate_git_subcommand "$@" >/dev/null
  [ -z "$GATE_GIT_UNREAD" ] || return 1
  [ -n "$GATE_GIT_SUB" ] || return 1
  want=$(target_field "$alias" '공통 git 디렉터리' 2>/dev/null) || return 1
  [ -n "$want" ] || return 1
  out=$( { cd "${GATE_ACT_CWD:-.}" 2>/dev/null \
           && env -u GIT_DIR -u GIT_COMMON_DIR -u GIT_WORK_TREE -u GIT_CEILING_DIRECTORIES \
                git ${GATE_GIT_LOCFLAGS[@]+"${GATE_GIT_LOCFLAGS[@]}"} rev-parse --path-format=absolute --git-common-dir --show-toplevel 2>/dev/null; } || true)
  cg=$(printf '%s\n' "$out" | sed -n 1p)
  top=$(printf '%s\n' "$out" | sed -n 2p)
  [ -n "$cg" ] && [ -n "$top" ] || return 1
  if [ "$cg" != "$want" ]; then
    cg_p=$(cd "$cg" 2>/dev/null && pwd -P) || return 1
    want_p=$(cd "$want" 2>/dev/null && pwd -P) || return 1
    [ "$cg_p" = "$want_p" ] || return 1
  fi
  top_p=$(cd "$top" 2>/dev/null && pwd -P) || return 1
  out=$(env -u GIT_DIR -u GIT_COMMON_DIR -u GIT_WORK_TREE -u GIT_CEILING_DIRECTORIES \
          git --git-dir="$want" worktree list --porcelain 2>/dev/null) || return 1
  while IFS= read -r line; do
    case "$line" in
      'worktree '*)
        wt="${line#worktree }"
        [ "$(cd "$wt" 2>/dev/null && pwd -P)" = "$top_p" ] && return 0 ;;
    esac
  done <<EOF
$out
EOF
  return 1
}

gate_path_of_some_target() {
  # gate_path_of_some_target <path> — 0 when <path> passes
  # `gate_path_of_target` for at least one declared target.
  local a
  for a in $(target_aliases); do
    gate_path_of_target "$1" "$a" && return 0
  done
  return 1
}

gate_segment_worktree_of_target() {
  # gate_segment_worktree_of_target <segment> <alias> — prints the segment row's
  # `워크트리` and returns 0 only when it passes `gate_path_of_target` for that
  # target. The segment-id form of the same predicate, for callers that start
  # from a row already on the ledger.
  local wt
  wt=$(gate_segment_worktree "$1")
  gate_path_of_target "$wt" "$2" || return 1
  printf '%s' "$wt"
}

gate_segment_worktree_other_target() {
  # gate_segment_worktree_other_target <segment> <own alias> — prints the alias
  # of some OTHER declared target whose worktree the segment row names, and
  # returns 0; returns 1 when no declared target owns that path.
  #
  # Separates the two things a failed predicate can mean. A row naming a path in
  # no declared repository, a path that is gone, or a relative one is a row that
  # has to be repaired, and the caller refuses. A row naming a worktree of
  # another target THIS RUN DECLARES is a true row read through the wrong target:
  # the run does act in that tree, just not through this act, so telling the
  # reader to fix the row would be telling them to break it. What was actually
  # wrong there is that the fallback said nothing, so the caller warns instead.
  local a
  for a in $(target_aliases); do
    if [ "$a" != "$2" ] && gate_segment_worktree_of_target "$1" "$a" >/dev/null; then
      printf '%s' "$a"
      return 0
    fi
  done
  return 1
}

gate_segment_worktrees_for_settings() {
  # The worktrees the ledger's `segment` rows name — the last row per segment
  # id, kept only when it passes gate_path_of_target for some declared target —
  # each as spelled on the row AND as `pwd -P` resolves it, one per line.
  #
  # AN INPUT OF THE SETTINGS DERIVATION. Kickoff happens before segmentation, so
  # a segment's own worktree is never in the manifest; this is the only way it
  # reaches `additionalDirectories`. The set moves only when a new value
  # appears, so the settings key built from it stays still while the ledger
  # merely grows.
  #
  # THE PENDING ROW IS PART OF THE SET. `gate_record_row` re-derives the
  # settings BEFORE it appends a non-terminal `segment` row, so the worktree
  # that row names is not on the ledger when the render runs; it arrives in
  # `GATE_SEGMENT_WT_PENDING` as `<segment>\t<worktree>` and stands in for
  # whatever the ledger says about that segment, because once appended it is
  # that segment's last row. Read here and nowhere else, and set only for the
  # duration of that one re-derivation.
  #
  # BOTH SPELLINGS, for the same reason `DOC_DIR` goes in twice: the harness
  # compares the directory a tool touches against the list as strings, a
  # worktree reached through a symlink is touched by the resolved path as often
  # as by the link, and a row that spelled the link would otherwise admit only
  # one of the two.
  local sid a wt pseg="" pwt="" tab
  tab=$(printf '\t')
  if [ -n "${GATE_SEGMENT_WT_PENDING:-}" ]; then
    pseg="${GATE_SEGMENT_WT_PENDING%%${tab}*}"
    pwt="${GATE_SEGMENT_WT_PENDING#*${tab}}"
  fi
  if [ -f "${LEDGER:-}" ]; then
    for sid in $(gate_segment_ids); do
      [ -n "$sid" ] || continue
      [ "$sid" != "$pseg" ] || continue
      for a in $(target_aliases); do
        if wt=$(gate_segment_worktree_of_target "$sid" "$a"); then
          gate_emit_worktree_spellings "$wt"
          break
        fi
      done
    done
  fi
  if [ -n "$pseg" ] && gate_path_of_some_target "$pwt"; then
    gate_emit_worktree_spellings "$pwt"
  fi
  # THE RUN-SCOPE AUDIT'S TREE, which no `segment` row names. Listed once it
  # exists as a worktree of its target, so the re-derivation its dispatch runs
  # keeps it and every later one does too.
  for a in $(target_aliases); do
    if wt=$(gate_audit_worktree_path "$a") && gate_path_of_target "$wt" "$a"; then
      gate_emit_worktree_spellings "$wt"
    fi
  done
  return 0
}

gate_emit_worktree_spellings() {
  # gate_emit_worktree_spellings <path> — <path> as given and, when it differs,
  # as `pwd -P` resolves it, one per line.
  local p
  printf '%s\n' "$1"
  p=$(cd "$1" 2>/dev/null && pwd -P) || return 0
  [ "$p" = "$1" ] || printf '%s\n' "$p"
}

gate_segment_tip() {
  gate_worktree_tip "$(gate_segment_worktree "$1")"
}

gate_worktree_tip() {
  # gate_worktree_tip <worktree> — the commit that worktree's HEAD names, or
  # return 1. Split out of `gate_segment_tip` for the writer of a segment row,
  # which has to read the tip of the worktree THAT ROW names before the row is
  # on the ledger; after the append the two answer the same thing.
  local wt="$1" out
  [ -n "$wt" ] || return 1
  [ -d "$wt" ] || return 1
  # `--verify` AND `^{commit}`: on an unborn branch a bare `git rev-parse HEAD`
  # exits 128 but still prints the literal `HEAD`, and the `|| true` below kept
  # that word as the tip — a later `is-ancestor HEAD …` then resolved it in
  # whatever repository it ran in rather than in this worktree.
  out=$( { cd "$wt" 2>/dev/null && git rev-parse --verify --quiet 'HEAD^{commit}' 2>/dev/null; } || true)
  [ -n "$out" ] || return 1
  printf '%s' "$out"
}

gate_dep_tokens() {
  # gate_dep_tokens <선행 값> — the dependency ids as whitespace-separated
  # tokens. THE ONE NORMALIZATION, used by the reader and by the write-time
  # floor alike.
  #
  # Two defects lived in having two of them. The reader split on comma AND
  # whitespace while the monotonicity floor DELETED whitespace and split on
  # comma only, so `선행=SA SB` — an ordinary prose spacing that flows in
  # verbatim from the design document's slice declaration, which `slice_field`
  # does not normalize — became the single token `SASB` to the floor. Restating
  # the same value then failed the floor, and since a repository with two
  # segments must carry `선행` on every row, that segment could not write a
  # second row at all: not a widening, not a state advance, nothing. The refusal
  # blamed a removal that had not happened.
  #
  # And `없음` was matched against the WHOLE value rather than per token, so
  # `없음,S1` kept `없음` as a dependency id. Nothing lands a segment named
  # `없음`, so the landing check refused that segment forever — and the
  # monotonicity floor refused the correction, because dropping `없음` is a
  # removal. That state is reached by FOLLOWING the instructions: the router is
  # told the field may be added to and not subtracted from, and a router holding
  # `없음` that acquires a dependency does exactly this.
  #
  # THE SENTINEL SET AND THE `슬라이스 ` PREFIX ARE SHARED WITH `run.sh`'s
  # `dep_tokens`, character for character. The driver's readers already accepted
  # `-` as a null and already stripped the prefix a design document's slice
  # declaration writes; this one did neither, so `**선행**: 슬라이스 SA` was one
  # dependency to the driver and two unknown tokens to the write-time floor that
  # decides whether the row may be written at all. Two normalizations for one
  # field is how the two sides came to disagree about whether a segment had any
  # dependencies.
  local t out=""
  for t in $(printf '%s' "${1:-}" | tr ',' ' '); do
    case "$t" in ''|'-'|'없음'|'(없음)') continue ;; esac
    t=${t#슬라이스}
    case "$t" in ''|'-'|'없음'|'(없음)') continue ;; esac
    out="$out $t"
  done
  printf '%s' "${out# }"
}

gate_deps_of() {
  # gate_deps_of <segment> — the `선행` of that segment's last row, as
  # whitespace-separated ids. `없음` yields the empty set, which is also what an
  # absent field yields — the two are told apart at WRITE time, because that is
  # the only moment at which the difference exists.
  gate_dep_tokens "$(gate_segment_field "$1" '선행')"
}

gate_chain_deps_of() {
  # gate_chain_deps_of <segment> — `선행 ∪ 머지 순서` of that segment's last
  # row, without duplicates. The cone's declared axis reads this union: a
  # merge-order predecessor that parks holds this segment's merge forever, so
  # it is an edge of the same kind an implementation predecessor is.
  local t out=" "
  for t in $(gate_deps_of "$1") $(gate_dep_tokens "$(gate_segment_field "$1" '머지 순서')"); do
    case "$out" in *" $t "*) continue ;; esac
    out="$out$t "
  done
  out=${out# }
  printf '%s' "${out% }"
}

gate_segment_row_landed() {
  # gate_segment_row_landed <row> — 0 when that one `segment` row records a
  # landing: `머지됨`, or `완료` — except a `완료` brought in from an earlier
  # run (`출처`) without a hex `머지 커밋`, which an open pull request left and
  # which put nothing on the base. The dispatch floor and the merge-order
  # check read landing through this one predicate.
  local row="$1"
  case "$(gate_row_field "$row" '상태')" in
    머지됨) return 0 ;;
    완료)
      [ -n "$(gate_row_field "$row" '출처')" ] || return 0
      case "$(gate_row_field "$row" '머지 커밋')" in
        ''|*[!0-9a-f]*) return 1 ;;
      esac
      return 0 ;;
  esac
  return 1
}

GATE_WALK_PRCUT=""
gate_prior_row_landed() {
  # gate_prior_row_landed <row> — 0 when that one `segment` row of an EARLIER
  # run's ledger records a landing the import may bring in: `머지됨` or `완료`
  # carrying a hex `머지 커밋`, or — only when GATE_WALK_PRCUT is set, for a
  # slice the frozen document declares with `절단점: PR` — a `완료` carrying a
  # numeric `PR` and a hex `커밋`. See `gate_prior_run_landed` for why.
  local row="$1" st m p c
  st=$(gate_row_field "$row" '상태')
  case "$st" in 머지됨|완료) : ;; *) return 1 ;; esac
  m=$(gate_row_field "$row" '머지 커밋')
  case "$m" in ''|*[!0-9a-f]*) : ;; *) return 0 ;; esac
  [ -n "$GATE_WALK_PRCUT" ] && [ "$st" = "완료" ] || return 1
  p=$(gate_row_field "$row" 'PR')
  c=$(gate_row_field "$row" '커밋')
  case "$p" in ''|*[!0-9]*) return 1 ;; esac
  case "$c" in ''|*[!0-9a-f]*) return 1 ;; esac
  return 0
}

GATE_WALK_ROW=""
GATE_WALK_VIA_PARK=""
gate_landing_walk() {
  # gate_landing_walk <predicate> — read one id's `segment` rows on stdin, in
  # ledger order, and find the row that records its landing: 0 with that row in
  # GATE_WALK_ROW, 1 with GATE_WALK_ROW empty when there is none. GATE_WALK_VIA_PARK
  # is 1 when the landing was found behind a trailing `park`.
  #
  # THE LAST ROW DECIDES, UNLESS IT IS A `park` THAT CAME AFTER A LANDING. A
  # segment can merge and then be parked — the apply arm's park, a person's
  # segment park answer — and the merged work stays on the base whatever the
  # park says. So when the last row is `park`, the walk steps back over every
  # `park` and `적용 준비` row, neither of which takes merged code back, and the
  # first other row it meets decides. A `계획됨`, `실행중` or `리뷰중` there means
  # the slice was being done again after its landing, and whether that work
  # landed is for the rows after it to say — so it is no landing, unlike
  # `gate_segment_ever_landed`, which answers a different question.
  #
  # Called without a subshell (`gate_landing_walk pred <<ROWS`) so the two
  # globals reach the caller.
  local pred="$1" rows last r i n
  GATE_WALK_ROW=""; GATE_WALK_VIA_PARK=""
  rows=$(sed '/^$/d')
  [ -n "$rows" ] || return 1
  last=$(printf '%s\n' "$rows" | tail -1)
  if "$pred" "$last"; then
    GATE_WALK_ROW=$last
    return 0
  fi
  [ "$(gate_row_field "$last" '상태')" = "park" ] || return 1
  n=$(printf '%s\n' "$rows" | wc -l | tr -d ' ')
  i=$n
  while [ "$i" -gt 1 ]; do
    i=$((i - 1))
    r=$(printf '%s\n' "$rows" | sed -n "${i}p")
    case "$(gate_row_field "$r" '상태')" in park|'적용 준비') continue ;; esac
    "$pred" "$r" || return 1
    GATE_WALK_ROW=$r
    GATE_WALK_VIA_PARK=1
    return 0
  done
  return 1
}

gate_adoption_row_landed() {
  # gate_adoption_row_landed <row> — 0 when that row of an adopted segment's
  # origin ledger is `머지됨` or `완료` (`gate_adoption_check`).
  case "$(gate_row_field "$1" '상태')" in 머지됨|완료) return 0 ;; esac
  return 1
}

gate_landing_rows_any() {
  # gate_landing_rows_any <predicate> — 0 when any row on stdin satisfies it.
  local r
  while IFS= read -r r; do
    [ -n "$r" ] || continue
    "$1" "$r" && return 0
  done
  return 1
}

gate_segment_landed_now() {
  # gate_segment_landed_now <segment> — whether that segment of THIS run has
  # landed, by `gate_landing_walk` over its rows with `gate_segment_row_landed`:
  # 0 landed, with the row in GATE_WALK_ROW; 1 not landed; 2 merged and then
  # parked while the apply this run owes it was still to do — `머지됨` is not
  # that segment's ending (`gate_segment_owes_apply`), so a park after it left
  # the slice unfinished. The dispatch floor and the snapshot's `착지` read
  # landing through this one function. The `적용=대기` the segment arm stamps
  # on such a merge says the same from the ledger alone, and either suffices.
  local seg="$1" dal
  gate_landing_walk gate_segment_row_landed <<ROWS || return 1
$(gate_rows 'segment' | gate_rows_field_eq 'id' "$seg")
ROWS
  if [ "$GATE_WALK_VIA_PARK" = "1" ] && [ "$(gate_row_field "$GATE_WALK_ROW" '상태')" = "머지됨" ]; then
    [ "$(gate_row_field "$GATE_WALK_ROW" '적용')" != "대기" ] || return 2
    dal=$(gate_slice_alias "$seg" 2>/dev/null) || dal=""
    if [ -n "$dal" ] && gate_segment_owes_apply "$dal" "$seg"; then
      return 2
    fi
  fi
  return 0
}

gate_segment_ever_landed() {
  # gate_segment_ever_landed <segment> — 0 when ANY `segment` row of that id
  # records a landing. The merge-order check asks "has the predecessor's work
  # reached the base", and a landing stays on the base whatever a later row
  # says, so a re-planned row after `머지됨` does not take it back.
  local row
  while IFS= read -r row; do
    [ -n "$row" ] || continue
    gate_segment_row_landed "$row" && return 0
  done <<ROWS
$(gate_rows 'segment' | gate_rows_field_eq 'id' "$1")
ROWS
  return 1
}

gate_ancestor_of() {
  # gate_ancestor_of <A> <B> — 0 A's tip is an ancestor of B's tip, 1 it is not,
  # 2 the question could not be answered.
  #
  # THE THREE EXIT CODES ARE NOT FOLDED INTO TWO. `--is-ancestor` answers 1 for
  # "no" and 128 for "that object is not here" — a vanished worktree path, a
  # damaged object database, a permission failure. Reading 128 as "no" turns
  # every one of those into "not in the cone, so nothing is held", which would
  # be this design's single unconditional fail-open. What the accepted residual
  # authorizes is STRUCTURAL under-parking, never under-parking caused by a
  # fault.
  #
  # AND IT IS A PROPER ANCESTOR — an equal tip is NOT an edge. `git merge-base
  # --is-ancestor X X` is true, which is the right answer to the question git was
  # asked and the wrong answer to the question this function asks. What the
  # ancestry axis trades on is "that member has already merged, so the candidate
  # stands on its commits"; a member whose tip IS the candidate's tip has
  # contributed no commit the candidate could stand on, so the implication is
  # simply absent. Left in, every segment sitting on one worktree answered
  # "ancestor" for every other, and a cone anchored on any one of them swallowed
  # the whole group. A genuine dependency between two such segments is still
  # seen: the declared axis is evaluated before this one and reads it straight
  # off `선행`.
  local tipa tipb wtb rc=0
  tipa=$(gate_segment_tip "$1") || return 2
  tipb=$(gate_segment_tip "$2") || return 2
  [ "$tipa" != "$tipb" ] || return 1
  wtb=$(gate_segment_worktree "$2")
  [ -d "$wtb" ] || return 2
  ( cd "$wtb" && git merge-base --is-ancestor "$tipa" "$tipb" ) >/dev/null 2>&1 || rc=$?
  case "$rc" in
    0) return 0 ;;
    1) return 1 ;;
    *) return 2 ;;
  esac
}

gate_record_undecidable() {
  # An ancestry probe that came back 2 or higher. The disposition is FAIL-CLOSED
  # — the candidate STAYS in the cone — and the row exists so that what the
  # morning reads is "this could not be measured" rather than "this was measured
  # and stood up". The two segments ride in closed fields of their own, so the
  # stop classifier can tell whether a stage or halt event of either already
  # explains the stop without reading them back out of `사유`.
  local m="$1" s="$2" why
  why="조상 관계 판정 불가 ${m}→${s}"
  gate_has_row 'blocked' "사유=$why" && return 0
  gate_append 'blocked' "대상=${CC_PIPELINE_TARGET:--}" "스코프=cone" "원인=판정 불가" \
    "사유=$why" "구성원 세그먼트=$m" "후보 세그먼트=$s" \
    "근거=$(gate_row_safe "워크트리 ${m}=$(gate_segment_worktree "$m") · ${s}=$(gate_segment_worktree "$s")" 300)" \
    "관측=$(now_iso)" \
    "재개 명령=세그먼트 워크트리와 객체 DB 를 복구한 뒤 같은 앵커로 원뿔을 다시 기록하세요"
  warn "could not measure the ancestry (${m}→${s}) — that segment stays inside the cone"
}

gate_fileset_escape() {
  # gate_fileset_escape <segment> — the paths this segment changed that its
  # declared file set does not cover, one per line.
  #
  # This is the one premise refutation the gate OBSERVES rather than infers, and
  # git cannot answer it at all: ancestry says whether B was built on A, and
  # says nothing about whether a segment reached outside what it declared. The
  # only input to that judgment is the `선언 파일 집합` field, which is why the
  # field is carried even though nothing about the cone's ancestry axis needs
  # it. A segment that declared nothing is silent here — a claim nobody made
  # cannot be violated.
  #
  # NEITHER SIDE OF THE COMPARISON IS WORD-SPLIT, because a path is not a word
  # and a declared prefix is not one either. `for f in $(git diff --name-only)`
  # tore `docs/설계 노트.md` into two fragments, neither of which any declaration
  # covers, so a segment that stayed strictly inside what it declared raised a
  # cone against itself — and the identical splitting on the declaration side
  # tore a prefix containing a space into two prefixes that cover nothing, which
  # fails the other way and lets a real escape through. `core.quotePath=false` is
  # the other half of the same repair: without it git renders every non-ASCII
  # byte as a `\nnn` escape inside double quotes, so a Korean path is compared in
  # a spelling it never has on disk and can never match its own prefix.
  local decl base wt f p covered decls
  decl=$(gate_segment_field "$1" '선언 파일 집합')
  case "$decl" in ''|'없음'|'(없음)') return 0 ;; esac
  base=$(gate_segment_field "$1" '베이스 sha')
  [ -n "$base" ] || return 0
  wt=$(gate_segment_worktree "$1")
  [ -n "$wt" ] || return 0
  [ -d "$wt" ] || return 0
  decls=$(printf '%s' "$decl" | tr ',' '\n' \
          | sed -e 's/^[[:space:]]*//' -e 's/[[:space:]]*$//' | grep -v '^$' || true)
  # The loop sits on the right of a pipe and therefore in a subshell. That is
  # harmless here and only here: this function reports on STDOUT and keeps no
  # state across iterations, so nothing it computes has to outlive the subshell.
  { cd "$wt" 2>/dev/null \
    && git -c core.quotePath=false diff -z --name-only "$base" HEAD 2>/dev/null || true; } \
  | while IFS= read -r -d '' f; do
      [ -n "$f" ] || continue
      covered=0
      while IFS= read -r p; do
        [ -n "$p" ] || continue
        case "$f" in "$p"|"$p"*) covered=1 ;; esac
      done <<DECL
$decls
DECL
      [ "$covered" = "1" ] || printf '%s\n' "$f"
    done
}

gate__es_class_z() {
  # Inside `gate_es`: NUL-separated repository-relative paths on stdin, one
  # `<class>\t<path>` line out for each the classifier names.
  local p c
  while IFS= read -r -d '' p; do
    [ -n "$p" ] || continue
    c=$(es_class "/$p") || continue
    printf '%s\t%s\n' "$c" "$p"
  done
}

gate__tree_entry() {
  # gate__tree_entry <rev> <path> — `<mode> <object id>` of the path in the
  # revision's tree, or `없음`. Run inside the worktree.
  local e
  e=$(GIT_LITERAL_PATHSPECS=1 git ls-tree -z "$1" -- "$2" 2>/dev/null | tr '\0' '\n' | sed -n '1p')
  if [ -z "$e" ]; then printf '없음'; return 0; fi
  e=${e%%$'\t'*}
  printf '%s %s' "${e%% *}" "${e##* }"
}

gate_surface_alias_of() {
  # gate_surface_alias_of <worktree> — the declared target the worktree belongs
  # to, by the predicate a segment row's `워크트리` is admitted with.
  local a
  for a in $(target_aliases 2>/dev/null || true); do
    gate_path_of_target "$1" "$a" && { printf '%s' "$a"; return 0; }
  done
  return 1
}

gate_surface_provenance() {
  # gate_surface_provenance <segment> [<alias>] — 0 when every enforcement-surface
  # path the segment branch changed stands as this run's seat applies left it or
  # as the base has it; otherwise one `<path>\t<why>` line per path that does
  # not, and status 3. Status 2, with one `-\t<why>` line, when the check cannot
  # be decided: the classifier, the merge base or the changed paths could not be
  # read. Every caller refuses on both, but only 3 says that a surface changed —
  # a reader that wrote "changed outside a seat apply" for an unreadable branch
  # would put a false reason on the ledger and hide the one that was true.
  #
  # THIS IS WHAT CLOSES THE GAP, AND THE EXEC REFUSAL IS ONLY A SIGNPOST. A
  # stage can reach a classified path through an interpreter, a script body or
  # `git checkout <rev> -- <path>`, none of which an argv check sees. What lands
  # is the branch, so the branch is examined: the cone seed holds a review on it,
  # the merge act refuses on it and the driver calls it right before its own
  # merge. All three call this one function.
  #
  # THREE TREES, WHETHER OR NOT THE BRANCH WAS REBASED: the segment HEAD, the
  # merge base and the base end. A path's HEAD entry has to equal the base end's
  # or the entry of the last seat commit of this run and this segment that
  # touched it. And a path the base changed since the merge base that HEAD does
  # not carry as the base has it is refused even when it equals a seat commit,
  # because on a branch that was not rebased HEAD still equals the seat commit
  # and the first comparison alone would let a change on both sides through.
  # On a rebased branch the merge base is the base end, so that condition does
  # not stand and the first comparison decides.
  #
  # THE MODE IS COMPARED WITH THE OBJECT, AND `없음` IS A VALUE. Many rule
  # checkers are executables, so a blob-only comparison would pass a mode-only
  # change; and a deletion only a seat apply or the base made passes while one
  # nobody approved does not.
  #
  # THE TOUCHED PATHS COME FROM THE COMMIT, NOT FROM THE ROW. `diff-tree` of
  # each seat commit against its parent says what it changed; a commit that
  # cannot be found refuses, because what it covered can no longer be shown.
  # Rows carried in by an adoption (`출처 런`) are not counted — a seat apply of
  # another run is that run's trust, not this one's.
  local seg="$1" al="${2:-}" wt bref bend mb mbrc=0 lst rc=0 out='' line cls p eh eb em s es found ok
  local shas='' r row tch anchored
  wt=$(gate_segment_worktree "$seg")
  case "$wt" in ''|-) return 0 ;; esac
  [ -d "$wt" ] || return 0
  if ! gate_es true; then
    printf '%s\t%s\n' '-' '분류 라이브러리를 읽을 수 없어 판정 불가'
    return 2
  fi
  case "$al" in ''|-) al=$(gate_surface_alias_of "$wt") || al='' ;; esac
  bend=''
  if [ -n "$al" ]; then
    bref=$(base_branch "$al" 2>/dev/null) || bref=''
    if [ -n "$bref" ]; then
      if (cd "$wt" && git remote get-url origin >/dev/null 2>&1); then
        bref="refs/remotes/origin/$bref"
      else
        bref="refs/heads/$bref"
      fi
      bend=$(cd "$wt" && git rev-parse --verify --quiet "$bref^{commit}" 2>/dev/null) || bend=''
    fi
  fi
  # The base the segment branched from stands in when the target's base ref
  # cannot be read: a branch is then compared with where it started.
  [ -n "$bend" ] || bend=$(gate_segment_field "$seg" '베이스 sha')
  [ -n "$bend" ] || return 0
  # A BRANCH WITH NO COMMON HISTORY IS COMPARED FROM THE EMPTY TREE. `merge-base`
  # exits 1 with nothing printed when the two ends share no ancestor — an orphan
  # tip, or a root the segment was cut from on purpose. Every path such a branch
  # carries is one it added, so the empty tree stands in for the merge base and
  # the same three-tree comparison decides. A classified path HEAD has exactly
  # as the base end has it passes. One the base end lacks needs a seat commit,
  # as on any branch. One the base end has differently is refused as changed on
  # both sides — the base "added" it too, measured from the empty tree — and no
  # seat commit lifts that: a person decides it. Any other failure (an object
  # the database cannot read, a HEAD that does not resolve) cannot be decided
  # and is status 2.
  #
  # A SHALLOW REPOSITORY IS NOT AN ORPHAN. Cut below the fork point, it also
  # makes `merge-base` exit 1, but the two ends do share history the clone does
  # not hold — the empty tree would then report every path the base changed as
  # changed on both sides. Exit 1 in a shallow repository cannot be decided.
  mb=$(cd "$wt" && git merge-base "$bend" HEAD 2>/dev/null) || mbrc=$?
  if [ "$mbrc" = 1 ] && [ -z "$mb" ] \
     && [ "$(cd "$wt" && git rev-parse --is-shallow-repository 2>/dev/null)" = true ]; then
    mb=''; mbrc='1, 얕은 저장소'
  elif [ "$mbrc" = 1 ] && [ -z "$mb" ]; then
    mb=$(cd "$wt" && git hash-object -t tree /dev/null 2>/dev/null) || mb=''
  elif [ "$mbrc" != 0 ]; then
    mb=''
  fi
  if [ -z "$mb" ]; then
    printf '%s\t%s\n' '-' "베이스 끝 ${bend} 과 HEAD 의 merge-base 를 구할 수 없어 판정 불가 (rc=$mbrc)"
    return 2
  fi
  lst=$( { cd "$wt" && git -c core.quotePath=false diff --no-renames -z --name-only "$mb" HEAD 2>/dev/null; } \
         | gate_es gate__es_class_z) || rc=$?
  case "$rc" in
    0) : ;;
    2) printf '%s\t%s\n' '-' '분류 라이브러리를 읽을 수 없어 판정 불가'
       return 2 ;;
    *) printf '%s\t%s\n' '-' "merge-base ${mb} 와 HEAD 사이의 변경 경로를 읽을 수 없어 판정 불가 (rc=$rc)"
       return 2 ;;
  esac
  [ -n "$lst" ] || return 0
  while IFS= read -r r; do
    [ -n "$r" ] || continue
    row=${r#*:}
    [ "$(gate_row_field "$row" '세그먼트')" = "$seg" ] || continue
    [ -z "$(gate_row_field "$row" '출처 런')" ] || continue
    [ "$(gate_row_field "$row" '선택지')" = '좌석 적용' ] || continue
    s=$(gate_row_field "$row" '좌석 커밋')
    [ -n "$s" ] && shas="$shas$s"$'\n'
  done <<EOF
$( { grep -n "^- \`중단 답\` " "$LEDGER" 2>/dev/null || true; } )
EOF
  while IFS=$'\t' read -r cls p; do
    [ -n "$p" ] || continue
    eh=$(cd "$wt" && gate__tree_entry HEAD "$p")
    eb=$(cd "$wt" && gate__tree_entry "$bend" "$p")
    em=$(cd "$wt" && gate__tree_entry "$mb" "$p")
    if [ "$eb" != "$em" ] && [ "$eh" != "$eb" ]; then
      out="$out$p"$'\t'"베이스와 세그먼트 양쪽에서 바뀜 ($cls)"$'\n'
      continue
    fi
    [ "$eh" = "$eb" ] && continue
    # A SEAT COMMIT IS AN APPROVAL OF BYTES OVER ONE BASE ENTRY. `anchored` says
    # some seat commit that touched the path was made over the entry the base end
    # holds now; when none was, the base changed the path under the approval,
    # and a rebase that replays the seat bytes over it still leaves HEAD equal
    # to the seat commit — the change on both sides the first test cannot see.
    found=''; ok=0; anchored=0
    while IFS= read -r s; do
      [ -n "$s" ] || continue
      if ! (cd "$wt" && git cat-file -e "$s^{commit}") 2>/dev/null; then
        found="!$s"; break
      fi
      # Captured, not piped into `grep -q`: under `pipefail` an early match
      # would make the writer's SIGPIPE the status of the test.
      tch=$( { cd "$wt" && git -c core.quotePath=false diff-tree --no-renames -r -z --name-only "$s^" "$s" 2>/dev/null; } \
             | tr '\0' '\n') || tch=''
      case $'\n'"$tch"$'\n' in
        *$'\n'"$p"$'\n'*)
          found=$s
          [ "$(cd "$wt" && gate__tree_entry "$s^" "$p")" != "$eb" ] || anchored=1 ;;
      esac
    done <<EOF
$shas
EOF
    case "$found" in
      '') out="$out$p"$'\t'"좌석 적용 커밋 없이 바뀜 ($cls)"$'\n' ;;
      '!'*) out="$out$p"$'\t'"좌석 커밋 ${found#!} 을 찾을 수 없음 ($cls)"$'\n' ;;
      *)
        es=$(cd "$wt" && gate__tree_entry "$found" "$p")
        [ "$es" = "$eh" ] && ok=1
        if [ "$ok" != 1 ]; then
          out="$out$p"$'\t'"마지막 좌석 커밋 ${found} 과 다름 ($cls)"$'\n'
        elif [ "$anchored" != 1 ]; then
          out="$out$p"$'\t'"베이스와 세그먼트 양쪽에서 바뀜 — 좌석 커밋이 지금의 베이스 위에서 만들어지지 않음 ($cls)"$'\n'
        fi ;;
    esac
  done <<EOF
$lst
EOF
  [ -n "$out" ] || return 0
  printf '%s' "$out"
  return "$GATE_EXIT_RULE"
}

gate_surface_provenance_hold() {
  # gate_surface_provenance_hold <segment> — 0 when the segment's branch fails
  # the provenance check, after recording a cone-scope `blocked` row anchored on
  # it once; 1 when it passes or the check cannot be decided. The cone seed
  # calls this, so a review is not dispatched onto a branch whose enforcement
  # surface nobody approved.
  #
  # AN UNDECIDED CHECK IS NOT A SEED. Its row would say a surface changed when
  # nothing was measured, `gate_has_row` keys on that reason so the false row
  # would also stand in for a later true one, and seeding first would skip the
  # ancestry axis, whose own `판정 불가` row is the one that names what could not
  # be read. The review dispatch and the merge act still refuse on it directly.
  #
  # A READ VERB COMPUTES MEMBERSHIP ONLY. `snapshot` reaches this through the
  # shift-halt array, and a read that appended a `blocked` row would change the
  # ledger it reports on; with `GATE_CONE_MEMBERS_ONLY=1` the answer is the same
  # and nothing is written or warned.
  local seg="$1" out rc=0 why='강제 표면이 좌석 적용 밖에서 바뀜'
  out=$(gate_surface_provenance "$seg") || rc=$?
  [ "$rc" = "$GATE_EXIT_RULE" ] || return 1
  [ "${GATE_CONE_MEMBERS_ONLY:-0}" = 1 ] && return 0
  if ! gate_has_row 'blocked' "앵커 세그먼트=$seg" "사유=$why"; then
    gate_append 'blocked' "대상=${CC_PIPELINE_TARGET:--}" "스코프=cone" "원인=막힘" \
      "앵커 세그먼트=$seg" "사유=$why" \
      "근거=$(gate_row_safe "$(printf '%s' "$out" | tr '\t\n' ' ;')" 300)" \
      "관측=$(now_iso)" \
      "재개 명령=그 경로의 편집을 \`Step 3 강제 표면 좌석 적용\` 기록으로 다시 적용하거나 세그먼트 브랜치에서 되돌리세요" || true
  fi
  warn "segment $seg changed an enforcement surface outside a seat apply — it stays inside the cone: $(printf '%s' "$out" | tr '\t\n' ' ;')"
  return 0
}

gate_check_surface_provenance() {
  # gate_check_surface_provenance <segment> <cutpoint> <alias> — refuse a merge
  # act whose segment branch fails the provenance check. The narrowing is the
  # CI verdict's, on the same two argv-derived values and for the same reason:
  # what is refused is what merges.
  local seg="$1" cut="$2" al="$3" out rc=0
  # A park already decided above is the act's disposition; it is not replaced.
  [ -z "${GATE_PARK_CELL:-}" ] || return 0
  [ "$cut" = "머지" ] || return 0
  [ -n "$seg" ] && [ "$seg" != "-" ] || return 0
  [ "${GATE_SURFACE:-}" = "읽기" ] && return 0
  if [ "${GATE_SURFACE:-}" = "워크트리쓰기" ] && [ "${GATE_HISTORY_INTEGRATION:-}" = "0" ]; then
    return 0
  fi
  out=$(gate_surface_provenance "$seg" "$al") || rc=$?
  [ "$rc" != 0 ] || return 0
  if [ "$rc" != "$GATE_EXIT_RULE" ]; then
    warn "rule refused: the enforcement-surface provenance of segment $seg could not be decided (강제 표면 출처 판정 불가) — $(printf '%s' "$out" | tr '\t\n' ' ;')"
    warn "repair the segment worktree, its HEAD or the plugin's classifier library and issue the same merge again"
    return "$GATE_EXIT_RULE"
  fi
  warn "rule refused: segment $seg changed an enforcement surface that no seat apply of this run left as it is, and the base does not have it either — $(printf '%s' "$out" | tr '\t\n' ' ;')"
  warn "apply the edit through a \`Step 3 강제 표면 좌석 적용\` halt record a person approves, or revert it on the segment branch; a path both the base and the segment changed goes to a person"
  return "$GATE_EXIT_RULE"
}

gate_cone_edge() {
  # gate_cone_edge <member> <candidate> — does <candidate> stand on <member>?
  local m="$1" s="$2" cgm cgs d rc=0
  # THE DECLARED AXIS IS ANSWERED FIRST, BEFORE ANYTHING READS A REPOSITORY.
  #
  # It is pure ledger data — no worktree, no git, no object database — so putting
  # it behind the repository probe made it pay for a measurement it does not use,
  # and it lost twice for that. A dependency declared ACROSS repositories was
  # answered by the cross-repository arm below and disappeared from the cone,
  # even though `선행` naming a member is the router stating the dependency on
  # purpose and is the only axis that sees one before the predecessor merges. And
  # when a member's worktree could not be read, the pair was written down as
  # unmeasurable while the declaration sitting right there answered it exactly.
  #
  # Nothing below is weakened by the move: the arms it precedes all answer "does
  # git place these two", and a declaration is not a claim about git.
  #
  # The axis reads `선행 ∪ 머지 순서`: a candidate whose merge waits on a parked
  # member is held by that member just as a dependent is.
  for d in $(gate_chain_deps_of "$s"); do
    if [ "$d" = "$m" ]; then return 0; fi
  done

  # A CROSS-REPOSITORY PAIR IS SETTLED WITHOUT ASKING GIT. Commits do not stack
  # across repositories, so such an edge orders work rather than placing it in
  # the cone. Splitting it off first is also what leaves `--is-ancestor`'s 128
  # meaning a genuine fault: without it the commonest benign case and every real
  # failure would arrive as the same number.
  cgm=$(gate_segment_common_git "$m" || true)
  cgs=$(gate_segment_common_git "$s" || true)
  if [ -n "$cgm" ] && [ -n "$cgs" ]; then
    if [ "$cgm" != "$cgs" ]; then return 1; fi
  else
    # ONE SIDE'S REPOSITORY COULD NOT BE READ, and that is settled HERE rather
    # than left to the ancestry probe below.
    #
    # The guard used to require both values to be non-empty, so an unreadable
    # one made it false and control fell through to `gate_ancestor_of` — which
    # returns 2 for the same reason — and the fail-closed arm then accepted the
    # edge. The effect was not one extra segment: a single member whose worktree
    # had been cleaned up (or whose path went stale across a `--resume`) emitted
    # an edge to EVERY candidate, including candidates in other repositories, so
    # the cone became the whole run. That is precisely the run stop a cone exists
    # instead of, and the residual this design accepted is STRUCTURAL
    # under-parking — not unbounded over-parking caused by a fault.
    #
    # The disposition splits by WHICH side is unreadable, because fail-closed is
    # a statement about the candidate:
    #   - the CANDIDATE is unmeasurable → it stays in the cone. Nothing can be
    #     shown about it, and holding one segment is the conservative direction.
    #   - the MEMBER is unmeasurable → no edge. The pair cannot even be placed in
    #     one repository, so "candidate stands on member" is not a question git
    #     was asked and answered; answering it yes for every candidate everywhere
    #     is the failure above. The candidate is still reachable through any
    #     other member that CAN be measured.
    # Either way the fact that it could not be measured is recorded.
    gate_record_undecidable "$m" "$s"
    if [ -z "$cgs" ]; then return 0; fi
    return 1
  fi

  # The ancestor axis — declaration-independent, so it catches stacking nobody
  # wrote down and rebases that pulled a segment in late.
  gate_ancestor_of "$m" "$s" || rc=$?
  case "$rc" in
    0) return 0 ;;
    1) return 1 ;;
  esac
  gate_record_undecidable "$m" "$s"
  return 0
}

gate_cone_members() {
  # gate_cone_members <anchor> — the cone as of now, one segment id per line.
  #
  #   anchor          the segment that raised the question, unconditionally
  #   defect identity segments sharing a `problem.동일성` with the anchor
  #   file-set escape non-terminal segments that reached outside what they
  #                   declared — seeding rather than anchoring can only WIDEN
  #                   the cone, and widening is the direction already declared
  #                   safe — and those whose branch changed an enforcement
  #                   surface outside a seat apply
  #   declared axis   non-terminal segments whose `선행` or `머지 순서` names a
  #                   member
  #   ancestor axis   non-terminal segments whose tip has a member's tip as an
  #                   ancestor
  #
  # THE LAST TWO COVER DIFFERENT WINDOWS. Segments branch from the resolved base
  # rather than from one another, so a member's tip being an ancestor means that
  # member has already merged — and the moment a cone typically stands up is
  # before that. In that window the ancestor axis is empty and only the declared
  # axis holds. In the other direction the ancestor axis catches what nobody
  # declared. Building one and calling it done leaves a suite that passes with
  # the main case void.
  local anchor="$1" members grew sid m ident idents
  members=" $anchor "

  # A RUN-SCOPE STEP STANDS IN FRONT OF EVERY SEGMENT — the design, the audit
  # and the split alike — so a cone anchored on one is the step and every
  # segment that has not ended. Such an anchor has no segment row, which
  # `gate_run_scope_kind_of_key` requires, so a segment id is never read as one.
  if gate_run_scope_kind_of_key "$anchor" >/dev/null 2>&1; then
    for sid in $(gate_segment_ids); do
      [ -n "$sid" ] || continue
      gate_segment_terminal "$sid" && continue
      members="$members$sid "
    done
    for m in $members; do printf '%s\n' "$m"; done
    return 0
  fi
  # A termination clause's key stands in front of no segment, so its cone is
  # the key alone.
  if gate_clause_key_id "$anchor" >/dev/null; then
    printf '%s\n' "$anchor"
    return 0
  fi

  # THE FIELD TERMINATOR IS PART OF THE MATCH. A trailing space alone ends the
  # value only when the next character is the separator, so `동일성=로그인 실패 `
  # also matched `동일성=로그인 실패 재현 불가` and pulled a different defect's
  # segments into this cone. `gate_append` writes ` | ` between every pair of
  # fields and always appends `prev=` last, so no field a caller supplies is ever
  # the final one and the pipe is always there to anchor against.
  idents=$( { gate_rows 'problem' | grep -F "세그먼트=$anchor |" || true; } \
            | tr '|' '\n' | sed -n 's/^ *동일성=//p' | sed 's/[[:space:]]*$//' | LC_ALL=C sort -u)
  while IFS= read -r ident; do
    [ -n "$ident" ] || continue
    for sid in $( { gate_rows 'problem' | grep -F "동일성=$ident |" || true; } \
                  | sed -n 's/.*세그먼트=\([^|]*\).*/\1/p' | sed 's/[[:space:]]*$//' | LC_ALL=C sort -u); do
      case "$members" in *" $sid "*) continue ;; esac
      # THE SAME TERMINAL FILTER THE OTHER THREE AXES CARRY. This seed loop was
      # the one that did not, so a segment already landed or abandoned was pulled
      # back in on a shared defect identity and held work that had nothing left
      # to wait for. Seeding widens the cone by design; widening it with segments
      # that are finished is not that design, it is the filter being missing from
      # one of four places.
      gate_segment_terminal "$sid" && continue
      members="$members$sid "
    done
  done <<EOF
$idents
EOF

  for sid in $(gate_segment_ids); do
    [ -n "$sid" ] || continue
    case "$members" in *" $sid "*) continue ;; esac
    gate_segment_terminal "$sid" && continue
    # An enforcement surface changed outside a seat apply seeds the same way a
    # file-set escape does, and holds the review with a row of its own.
    if [ -z "$(gate_fileset_escape "$sid")" ]; then
      gate_surface_provenance_hold "$sid" || continue
    fi
    members="$members$sid "
  done

  grew=1
  while [ "$grew" = "1" ]; do
    grew=0
    for sid in $(gate_segment_ids); do
      [ -n "$sid" ] || continue
      case "$members" in *" $sid "*) continue ;; esac
      gate_segment_terminal "$sid" && continue
      for m in $members; do
        gate_cone_edge "$m" "$sid" || continue
        members="$members$sid "
        grew=1
        break
      done
    done
  done

  for m in $members; do printf '%s\n' "$m"; done
}

gate_record_cone() {
  # gate_record_cone <alias> <키=값>...
  #
  # The row is a RECORD, not the enforcement: membership is recomputed at every
  # cone judgment, so what this leaves behind is what stood up and the command
  # that resumes it. What the gate does NOT do is take the router's declaration
  # on trust.
  local alias="$1"; shift
  local anchor declared derived d missing="" cause dstep
  # The four fields of a shift's halt record ride only when `shift-halt` is the
  # caller, which sets GATE_SHIFT_HALT_WRITING around this one call.
  gate_shift_halt_fields_refused "$@" && return "$GATE_EXIT_VOCAB"
  cause=$(gate_field_of '원인' "$@")
  # `거절 소진` is a `막힘` with its own name: the stage a model refusal ended
  # twice. Readers treat every cause but `무효화` alike, so it resolves the same
  # way, and the name is what lets the morning count it apart.
  case "$cause" in
    '막힘' | '거절 소진') : ;;
    *)
      warn "the \`원인\` of a cone row has to be \`막힘\` or \`거절 소진\` (observed: ${cause:-(none)}) — an invalidation means the run ended, and a cone is not that"
      return "$GATE_EXIT_VOCAB" ;;
  esac
  anchor=$(gate_field_of '앵커 세그먼트' "$@")
  if [ -z "$anchor" ]; then
    warn "a cone row needs an \`앵커 세그먼트\` — it is where the derivation starts"
    return "$GATE_EXIT_VOCAB"
  fi
  # A run-scope step — design, audit, split or visual — is the one anchor that has no
  # segment row: a stage of it that cannot finish inside the deadline, or an
  # answer to its halt the shift cannot carry out, holds every segment.
  # A termination clause's `clause-<id>` key has none either: its evidence
  # request holds that clause alone.
  if [ -z "$(gate_segment_field "$anchor" '상태')" ] \
     && ! gate_run_scope_kind_of_key "$anchor" >/dev/null 2>&1 \
     && ! gate_clause_key_id "$anchor" >/dev/null; then
    warn "there is no segment row for the anchor segment: $anchor — a cone is not stood up on an anchor the ledger does not resolve"
    return "$GATE_EXIT_VOCAB"
  fi

  derived=$(gate_cone_members "$anchor" | tr '\n' ',' | sed 's/,$//')
  if [ -z "$derived" ]; then
    warn "the cone is empty — a cone that does not even contain its anchor is not recorded"
    return "$GATE_EXIT_VOCAB"
  fi

  # THE FULL LIST GOES SOMEWHERE THE ROW CANNOT HOLD IT. `gate_append` dies over
  # 1024 bytes, and this row carries three Korean free-text fields whose own
  # clip budget is 400 bytes EACH — so the list is the field that has to be
  # bounded, and the morning still needs the whole of it. stderr is where the
  # reader is already looking; the run directory is where a later process can
  # find it.
  local nderived
  nderived=$(printf '%s' "$derived" | tr ',' '\n' | gate_count)
  if [ -n "${RUN_DIR:-}" ] && [ -d "$RUN_DIR" ]; then
    printf '%s\n' "$derived" > "$RUN_DIR/cone.$anchor" 2>/dev/null || true
  fi

  declared=$(gate_field_of '의존 세그먼트' "$@")
  # LENGTH IS JUDGED BEFORE THE SUPERSET, because the two refusals send the
  # reader to different repairs and the length one is the more fundamental: a
  # declaration that cannot be written is not a declaration whose CONTENT is
  # worth reporting on. Refused here rather than inside the writer, whose `die`
  # prescribes "move long values to a sidecar" — something no caller of this
  # verb can do, since declaring the field and omitting it write the same bytes.
  if [ -n "$declared" ] \
     && [ "$(printf '%s' "$declared" | wc -c | tr -d ' ')" -gt "$GATE_CONE_LIST_MAX" ]; then
    warn "the declared \`의존 세그먼트\` is over ${GATE_CONE_LIST_MAX} bytes — it does not fit inside the ledger row cap (${GATE_ROW_MAX})"
    warn "leave the declaration out and the gate records the derived list in bounded form and puts the whole of it at ${RUN_DIR:-<run directory>}/cone.${anchor}"
    return "$GATE_EXIT_VOCAB"
  fi
  # A ROUTING BLOCK RETURNS ITS ANSWER TO A PERSON. When the shift cannot carry
  # out an answered halt it writes this cone with `사유` opening
  # `중단 답 라우팅 — <기록 파일 이름> — `, and the gate stamps the line of the
  # anchor key's open answer to that record as `막힌 답 줄`. The stamp is what
  # spends the answer (`gate_halt_answer_consumer`) and what turns the record
  # back into a question (`cc_halt_returned`). A `원인=해소` row never reaches
  # here, so it is never stamped: the answer open at release is the person's
  # new one. No matching open answer, no stamp — the row still stands.
  local stamp=() why rname
  why=$(gate_field_of '사유' "$@")
  if [ "$cause" = "막힘" ]; then
    case "$why" in
      '중단 답 라우팅 — '*' — '*)
        rname=${why#'중단 답 라우팅 — '}
        rname=${rname%% — *}
        local sl
        sl=$(gate_open_answer_line_of "$anchor" "$rname")
        [ -z "$sl" ] || stamp=("막힌 답 줄=$sl")
        ;;
    esac
  fi

  if [ -n "$declared" ]; then
    # SUPERSET ONLY. Widening passes and narrowing does not, so the lie that
    # would pay — leaving a dependent out so it keeps running on a premise that
    # has been refuted — is the one direction refused.
    for d in $(printf '%s' "$derived" | tr ',' ' '); do
      case ",$declared," in *",$d,"*) ;; *) missing="$missing $d" ;; esac
    done
    if [ -n "$missing" ]; then
      warn "the declared \`의존 세그먼트\` is a proper subset of the derived result — missing:${missing}"
      return "$GATE_EXIT_GRADE"
    fi
    gate_append 'blocked' "대상=$alias" "$@" ${stamp[@]+"${stamp[@]}"} "의존 세그먼트 수=$nderived" || return $?
  else
    gate_append 'blocked' "대상=$alias" "$@" ${stamp[@]+"${stamp[@]}"} "의존 세그먼트 수=$nderived" \
      "의존 세그먼트=$(gate_row_safe "$derived" "$GATE_CONE_LIST_MAX")" || return $?
  fi
  printf 'gate: full cone list (anchor %s · %s entries): %s\n' "$anchor" "$nderived" "$derived" >&2
  log "의존 원뿔 기록 — 앵커 $anchor · $nderived 개"
}

# ---------------------------------------------------------------------------
# The approval sidecar — `<base>/docs/pipeline-approval/<run-id>.md`.
#
# A `승인` row carries an EXCERPT of the question and of the answer and a digest
# of each; the full text lives here, one block per approval id, so the digests
# on the row have something to be compared against. Keyed on the RUN and not on
# the design document: a run may start from a pull request or a bare intent
# and have no document to derive a slug from, so this kind proves its ownership
# with `owner-run=<run-id>` plus the existence of that run's authorization
# record, and a file that fails either half is not read and not extended.
#
# THE GATE IS ITS ONLY WRITER AND CREATES ITS DIRECTORY. The sidecar contract
# makes the directory the writer's duty, and without the `mkdir -p` the first
# approval of a fresh checkout would fail exactly on the path this file exists
# for — the free-input answer that the ledger deliberately does not carry.
#
# Blocks are `## 승인 <id>`. The IMMUTABLE region — the question's sha256 and
# its fenced text — is written when the approval is issued and never rewritten;
# the MUTABLE region — the answer's sha256 and its fenced text — is filled when
# the approval closes, and re-filled if a later answer supersedes an earlier
# one. Writes take the contract's atomic form: a temp file in the same
# directory, a compare-and-swap against the bytes the build read, a plain `mv`,
# a bounded retry. Nothing here deletes.
# ---------------------------------------------------------------------------
readonly GATE_APPROVAL_SIDECAR_KIND="cc-pipeline-approval v1"

gate_approval_sidecar_path() {
  # Nothing when either half of the path is unknown: a caller sourcing this
  # file without a manifest has no base and no run, and `/docs/pipeline-approval/.md`
  # is a real path that must not be created by accident.
  [ -n "${BASE:-}" ] && [ -n "${RUN_ID:-}" ] || return 1
  printf '%s/docs/pipeline-approval/%s.md' "$BASE" "$RUN_ID"
}

gate_approval_sidecar_anchor() {
  # gate_approval_sidecar_anchor <승인 id> — the row field that names the block.
  printf '%s#%s' "${RUN_ID:-(미상)}" "$1"
}

gate_approval_sidecar_ok() {
  # gate_approval_sidecar_ok [<path>] — 0 when the file is absent (creation is
  # legitimate) or proves itself this run's: the kind token is strictly equal,
  # `owner-run=` names this run, and the run's authorization record exists.
  # Anything else is fail-closed for reading and writing alike.
  local f="${1:-}" hdr
  [ -n "$f" ] || f=$(gate_approval_sidecar_path) || { warn "cannot derive the approval sidecar path (BASE and RUN_ID unknown)"; return 1; }
  [ -e "$f" ] || { [ -n "${GRANT:-}" ] && [ -f "$GRANT" ] && return 0; warn "writing the approval sidecar requires the authorization record of this run: ${GRANT:-(unknown)}"; return 1; }
  hdr=$(sed -n '2p' "$f" 2>/dev/null || true)
  case "$hdr" in
    "<!-- $GATE_APPROVAL_SIDECAR_KIND; "*"owner-run=$RUN_ID;"*) ;;
    *) warn "the machine header of the approval sidecar does not belong to this run (kind and owner-run mismatch) — it is neither read nor written: $f"; return 1 ;;
  esac
  [ -n "${GRANT:-}" ] && [ -f "$GRANT" ] || { warn "the authorization record that is the other half of the proof pair of the approval sidecar is missing: ${GRANT:-(unknown)} — it is neither read nor written"; return 1; }
  return 0
}

gate_fence_for() {
  # gate_fence_for <text> — a backtick fence one longer than the longest run
  # of backticks in the text, never shorter than three, so the payload cannot
  # close its own fence.
  local n
  n=$(printf '%s\n' "$1" | LC_ALL=C awk '
    { m = 0; c = 0; for (i = 1; i <= length($0); i++) { if (substr($0, i, 1) == "`") { c++; if (c > m) m = c } else c = 0 } if (m > best) best = m }
    END { printf "%d", (best + 1 > 3) ? best + 1 : 3 }')
  printf '%*s' "$n" '' | tr ' ' '`'
}

gate_approval_sidecar_header() {
  printf '# 파이프라인 승인 기록 — %s\n' "$RUN_ID"
  printf '<!-- %s; writer=gate; reader=gate; owner-run=%s; owner-doc=%s; NOT a design doc; mechanism-local, never staged by a skill -->\n' \
    "$GATE_APPROVAL_SIDECAR_KIND" "$RUN_ID" "${DOC_KEY:-(없음)}"
}

gate_approval_sidecar_region() {
  # gate_approval_sidecar_region <label> <text> — one fenced region: the
  # digest line, the fence, the text, the fence.
  local label="$1" text="$2" fence
  fence=$(gate_fence_for "$text")
  printf '**%s sha256**: %s\n' "$label" "$(printf '%s' "$text" | shasum -a 256 | cut -d' ' -f1)"
  printf '%stext\n%s\n%s\n' "$fence" "$text" "$fence"
}

gate_approval_sidecar_build() {
  # gate_approval_sidecar_build <snap> <id> <region-file> <mode> — the whole
  # new file on stdout, built from the snapshot. `mode` is `issue` (add the
  # block with its question region if no block exists; leave an existing block
  # alone) or `answer` (replace or add the answer region inside the block).
  #
  # Fence-aware: a `## 승인` line inside an open fence is payload, and the
  # tracker matches the CLOSING fence by the exact backtick string that opened
  # it, so a shorter run of backticks in the payload does not close it.
  local snap="$1" id="$2" region="$3" mode="$4"
  if [ ! -s "$snap" ]; then
    gate_approval_sidecar_header
    printf '\n## 승인 %s\n' "$id"
    cat "$region"
    return 0
  fi
  LC_ALL=C awk -v id="$id" -v mode="$mode" -v regionfile="$region" '
    function flush_region(   line) {
      while ((getline line < regionfile) > 0) print line
      close(regionfile)
    }
    function fence_len(s,   i, n) { n = 0; for (i = 1; i <= length(s); i++) { if (substr(s, i, 1) == "`") n++; else break } return n }
    BEGIN { infence = 0; inblock = 0; found = 0; inanswer = 0; done = 0 }
    {
      line = $0
      if (infence) {
        if (fence_len(line) == flen && length(line) == flen) { infence = 0 }
        if (inblock && mode == "answer" && inanswer) next
        print line; next
      }
      fl = fence_len(line)
      if (fl >= 3) {
        infence = 1; flen = fl
        if (inblock && mode == "answer" && inanswer) next
        print line; next
      }
      if (line ~ /^## 승인 /) {
        if (inblock && mode == "answer" && !done) { flush_region(); done = 1 }
        inblock = (line == "## 승인 " id); if (inblock) found = 1
        inanswer = 0
        print line; next
      }
      if (inblock && mode == "answer" && line ~ /^\*\*답변 sha256\*\*: /) { inanswer = 1; next }
      if (inblock && mode == "answer" && inanswer && line ~ /^[[:space:]]*$/) { next }
      inanswer = 0
      print line
    }
    END {
      if (mode == "answer" && inblock && !done) { flush_region(); done = 1 }
      if (!found) { printf "\n## 승인 %s\n", id; flush_region() }
    }
  ' "$snap"
}

gate_approval_sidecar_write() {
  # gate_approval_sidecar_write <id> <mode> <label> <text> — commit one region
  # through the atomic compare-and-swap. 0 on commit; non-zero means nothing
  # was written and the caller must not proceed as if it had.
  local id="$1" mode="$2" label="$3" text="$4" f dir snap t region attempt
  f=$(gate_approval_sidecar_path) || { warn "cannot derive the approval sidecar path (BASE and RUN_ID unknown)"; return 1; }
  dir=$(dirname "$f")
  gate_approval_sidecar_ok "$f" || return 1
  region=$(mktemp) || return 1
  gate_approval_sidecar_region "$label" "$text" > "$region"
  for attempt in 1 2 3; do
    mkdir -p "$dir" || { rm -f "$region"; return 1; }
    snap=$(mktemp) || { rm -f "$region"; return 1; }
    cp "$f" "$snap" 2>/dev/null || : > "$snap"
    t=$(mktemp "$dir/.$(basename "$f").XXXXXX") || { rm -f "$snap" "$region"; return 1; }
    if ! gate_approval_sidecar_build "$snap" "$id" "$region" "$mode" > "$t"; then
      rm -f "$t" "$snap" "$region"; return 1
    fi
    [ -s "$t" ] || { rm -f "$t" "$snap" "$region"; return 1; }
    if { [ -e "$f" ] && cmp -s "$snap" "$f"; } || { [ ! -e "$f" ] && [ ! -s "$snap" ]; }; then
      if mv "$t" "$f"; then
        rm -f "$snap" "$region"
        # Read-back: this attempt's own block heading must be present.
        grep -qxF "## 승인 $id" "$f" 2>/dev/null || { warn "read-back of the approval sidecar failed — the block is not visible: $f \`## 승인 $id\`"; return 1; }
        return 0
      fi
    fi
    rm -f "$t" "$snap"
  done
  rm -f "$region"
  warn "the approval sidecar write did not settle within three attempts — nothing was written: $f"
  return 1
}

gate_approval_sidecar_question() {
  # gate_approval_sidecar_question <id> — the full question text of a block,
  # or nothing when the file fails its proof pair or holds no such block.
  local f
  f=$(gate_approval_sidecar_path) || return 0
  [ -f "$f" ] || return 0
  gate_approval_sidecar_ok "$f" 2>/dev/null || return 0
  LC_ALL=C awk -v id="$1" '
    function fence_len(s,   i, n) { n = 0; for (i = 1; i <= length(s); i++) { if (substr(s, i, 1) == "`") n++; else break } return n }
    BEGIN { inblock = 0; want = 0; infence = 0 }
    {
      if (infence) {
        if (fence_len($0) == flen && length($0) == flen) { infence = 0; if (want) exit; next }
        if (want) print; next
      }
      fl = fence_len($0)
      if (fl >= 3) { infence = 1; flen = fl; next }
      if ($0 ~ /^## 승인 /) { inblock = ($0 == "## 승인 " id); next }
      if (inblock && $0 ~ /^\*\*질문 sha256\*\*: /) { want = 1; next }
    }
  ' "$f"
}

gate_canon_prompt() {
  # gate_canon_prompt <id> <question> — the canonical prompt. `승인 <id> — <question>`
  # is what the router must put verbatim into the question it asks, and the id
  # riding inside that question is how the answer frame is found again.
  #
  # ON STDERR AT ISSUE TIME AND ON STDOUT ONLY THROUGH THE `prompt` VERB. The
  # issuing paths run inside `act` and `exec`, whose stdout belongs to the act —
  # a boundary approval opening in the middle of `exec -- git rev-parse HEAD`
  # would otherwise put this line in front of the sha a caller captured. The
  # router gets the same bytes, as JSON, from `gate.sh prompt --approval <id>`.
  printf '승인 %s — %s' "$1" "$2"
}

gate_warn_canon_prompt() {
  warn "$(gate_canon_prompt "$1" "$2")"
}

gate_prompt() {
  # gate_prompt <승인 id> — the question the router must put to a person, as
  # one JSON object: `{"id","cutpoint","state","question","menu_version",
  # "options":[{"label","description"}...]}`. THIS IS THE CONSUMPTION POINT OF
  # THE CANONICAL PROMPT. The router carries `question` verbatim into
  # `AskUserQuestion` and renders `options[]` verbatim (adding at most the
  # authoring rule's ` ← 추천` suffix to one label); the gate then finds the
  # answer frame by the id inside that question and compares the menu the
  # person saw against the same table this printed from. Act and boundary
  # approvals have no menu, so `options` is empty for them and the router asks
  # as it does today.
  #
  # The question text is the sidecar's full text when the block exists and
  # proves itself this run's, and the row's excerpt otherwise — an approval
  # issued before the sidecar existed is still askable.
  local id="$1" row cutp full l opts
  row=$(gate_approval_last_row "$id")
  [ -n "$row" ] || die "no such approval id in the ledger: $id"
  cutp=$(gate_row_field "$row" '절단점')
  full=$(gate_approval_sidecar_question "$id" || true)
  [ -n "$full" ] || full=$(gate_row_field "$row" '질문 문면')
  opts='[]'
  if [ "$cutp" = "판단" ]; then
    opts=$(for l in $(gate_menu_labels); do
      jq -n --arg label "$l" --arg description "$(gate_menu_description "$l")" '{label: $label, description: $description}'
    done | jq -s '.')
  fi
  jq -n --arg id "$id" --arg cutpoint "$cutp" --arg state "$(gate_row_field "$row" '상태')" \
        --arg question "$(gate_canon_prompt "$id" "$full")" --arg mv "$GATE_MENU_VERSION" \
        --argjson options "$opts" \
        '{id: $id, cutpoint: $cutpoint, state: $state, question: $question, menu_version: $mv, options: $options}'
}

gate_tuple_snap() {
  # The snapshot component of a judgment binding tuple: the first
  # `GATE_TUPLE_SNAP_LEN` characters of the snapshot digest, which is the
  # progress-vector half — the value that moves on progress and on nothing else.
  local h
  h=$(gate_snapshot_digest)
  printf '%s' "${h:0:$GATE_TUPLE_SNAP_LEN}"
}

gate_approval_last_row() {
  # gate_approval_last_row <승인 id> — the last `승인` row for this id, or nothing.
  { gate_rows '승인' | grep -F "| 승인 id=$1 |" || true; } | tail -1
}

# ---------------------------------------------------------------------------
# Judgment approvals — the path grade 2's own refusal used to promise.
# ---------------------------------------------------------------------------
gate_judgment_question() {
  # gate_judgment_question <기준> <근거> — the question text, canonically.
  #
  # ONE PLACE, because the approval's identity and the text a person reads must
  # be derived from the same bytes. They were not: the id hashed `기준` alone
  # while the row carried `기준 — 근거`, so two judgments sharing a short,
  # writer-authored standard were ONE approval however different the rest of the
  # question was.
  gate_row_safe "${1:-미상} — ${2:-근거 없음}" 400
}

gate_judgment_approval_id() {
  # gate_judgment_approval_id <segment> <질문 문면>
  #
  # Derived from the JUDGMENT rather than from an act, so the same judgment
  # submitted twice yields one approval instead of a queue of duplicates. The
  # act variant hashes an argv, and a judgment has none.
  #
  # IT HASHES THE WHOLE QUESTION AND NOT JUST `기준`. A judgment approval has no
  # binding tuple — a question's answer is durable, so there is no tree to
  # re-derive freshness against — which means identity is the ONLY thing
  # separating one answered question from the next. Keyed on `기준`, a short
  # free-text field the submitting side writes, a later judgment that merely
  # reused the phrase inherited the earlier `승인` and was adopted without ever
  # meeting the auto-adoption floor and without anyone reading it. Hashing the
  # text a person actually saw makes the id and the answer inseparable.
  printf 'J-%s' "$(printf '%s|%s|%s' "$RUN_ID" "$1" \
    "$(printf '%s' "$2" | shasum -a 256 | cut -d' ' -f1)" | shasum -a 256 | cut -c1-8)"
}

gate_judgment_approval_disposition() {
  # gate_judgment_approval_disposition <rc> — the issuer's three returns turned
  # into a disposition a caller can act on.
  #
  # THE POINT IS THAT THE SIGNAL STOPS HERE. `GATE_APPROVAL_ANSWERED` is an
  # internal value; the comment beside its declaration says a copy escaping to
  # the shell would tell the router a code the contract never defined, and three
  # callers reached the issuer without translating anything at all. Naming the
  # translation once means a new caller has somewhere to go other than dropping
  # the value.
  case "$1" in
    0) printf '발행' ;;
    "$GATE_APPROVAL_ANSWERED") printf '답있음' ;;
    "$GATE_EXIT_RULE") printf '닫힘' ;;
    *) printf '미상' ;;
  esac
}

gate_judgment_seat() {
  # gate_judgment_seat — the seat of this act-path caller for a judgment
  # approval's `연 자리`: `라우터` when the caller is not a stage, otherwise the
  # stage kind the gate recorded when it dispatched this stage, otherwise
  # `미상`.
  #
  # THE KIND IS READ FROM THE DISPATCH RECORD, NOT FROM THE STAGE ID. A stage id
  # is `<segment>#<attempt>` and a segment id names no kind, while the dispatch
  # writes `<segment>.kind` beside the attempt it pinned. A stage the driver
  # started has no such record and reads `미상`, which the reporter treats as
  # not the design stage — reported rather than missed.
  local sid seg k
  if ! cc_caller_is_stage; then printf '라우터'; return 0; fi
  sid="${CC_PIPELINE_STAGE_ID:-}"
  seg="${sid%#*}"
  case "$seg" in ''|.*|*/*) printf '미상'; return 0 ;; esac
  k=$(sed -n '1p' "$RUN_DIR/$seg.kind" 2>/dev/null || true)
  case " $STAGE_KINDS " in
    *" $k "*) [ -n "$k" ] && { printf '%s' "$k"; return 0; } ;;
  esac
  printf '미상'
}

gate_issue_judgment_approval() {
  # gate_issue_judgment_approval <alias> <segment> <기준> <근거> [부류] [연 자리]
  #
  # `연 자리` IS WHO RAISED THE JUDGMENT — a stage kind, `라우터`, or `미상` for
  # anything else. It is carried on the row only and touches neither the id nor
  # the tuple, so the same judgment raised from two seats is still one approval.
  # The halt reporter reads it: a judgment the design stage left open is an
  # intended wait, one any other seat left open is reported.
  #
  # THE BINDING TUPLE IS `<세그먼트>/<질문 sha256>/<선택지판>/<스냅숏 앞자리>`, AND
  # THAT IS THE DIFFERENCE FROM AN ACT APPROVAL. An act approval's answer is
  # valid now and its window closes with the night, so it carries head and base
  # shas and re-derives freshness against the tree it named. A question's
  # answer is an input to work that has not happened yet — it is durable, and
  # there is no tree to measure — so what its tuple binds is not a tree but the
  # QUESTION a person saw and the MENU they were shown: the digest of the full
  # question text (compared against the sidecar block the anchor names) and the
  # version token of the gate's own label table (compared, at close, by
  # re-deriving the labels from that table against the transcript's menu).
  #
  # THE GATE ISSUES IT AND THE ROUTER CANNOT. The router only ever submits its
  # own recommendation through `act --kind judgment`; whether that becomes a
  # question is decided here.
  local alias="$1" seg="$2" std="$3" why="$4" cls="${5:-}" seat="${6:-}" id q qfull qdig
  GATE_AUTO_RESOLVED_APPROVAL=""
  [ -n "$seat" ] || seat='미상'
  case " $STAGE_KINDS 라우터 " in
    *" $seat "*) ;;
    *) seat='미상' ;;
  esac
  # The full text goes to the sidecar and is what the row's digest is OF; the
  # row itself carries the 400-byte excerpt, and the id keeps hashing the excerpt
  # so every id issued before the sidecar existed still derives to itself.
  qfull="${std:-미상} — ${why:-근거 없음}"
  q=$(gate_judgment_question "$std" "$why")
  id=$(gate_judgment_approval_id "$seg" "$q")
  # THE ID GOES OUT WITH THE RETURN VALUE. Every one of the three returns below
  # tells a caller WHAT happened and none of them tells it WHICH approval it
  # happened to, so a caller that wants to record the outcome has no id to name
  # and cannot re-derive one — the derivation needs the question text this
  # function built. Exported the way `GATE_ACT_CWD` and `GATE_SURFACE` already
  # are.
  GATE_LAST_JUDGMENT_APPROVAL_ID="$id"; export GATE_LAST_JUDGMENT_APPROVAL_ID
  # THE STATE DECIDES, AND THE FOUR STATES DECIDE DIFFERENTLY. Narrowing to
  # `대기` alone was half the repair: it stopped an answered approval from
  # silently satisfying a re-submission, but everything that was not `대기` then
  # fell through to the append below and RE-OPENED the same id as `대기` again.
  # So an approval a person had closed came back as an open question — the exact
  # loop the id derivation exists to prevent, reached from the other side. A
  # closed approval must not be re-opened by anyone resubmitting the judgment;
  # only a genuinely different question, which hashes to a different id, may open
  # one.
  local st
  st=$(gate_approval_state "$id")
  case "$st" in
    대기)
      # A `시각-승인` question is closed by its sidecar predicate first, switch
      # or no switch: a resubmission after the approval landed is what closes
      # the questions of the other screen segments.
      local vr=0
      gate_visual_approval_resolve "$id" "$q" "$cls" || vr=$?
      [ "$vr" = "0" ] || return "$vr"
      # An approval opened before auto-resolution existed, or while it was
      # switched off, is resolved on the resubmission that finds it — unless a
      # person already answered it and no disposition could be derived.
      if gate_auto_resolve_enabled && ! gate_approval_person_answered "$id"; then
        local ar=0
        gate_auto_resolve_judgment "$id" "$q" "$cls" || ar=$?
        return "$ar"
      fi
      log "판단 승인 $id 이 이미 열려 있습니다 — 같은 판단은 승인 하나로 모입니다"
      return 0 ;;
    무효|거부)
      # A CLOSED-NEGATIVE APPROVAL IS AN ANSWER TOO. Re-issuing here would ask
      # the person the same question they already declined, every night, off one
      # refusal they already gave.
      warn "judgment approval $id is already closed as '$st' — the same question is not opened again"
      warn "if that judgment is still needed, raise it as a new question with a different standard and different grounds"
      return "$GATE_EXIT_RULE" ;;
    승인)
      # There is an answer on file. Whether it may open THIS judgment depends on
      # whether it has been spent, and that is the caller's question rather than
      # this function's — issuing is what this function does, and here there is
      # nothing to issue.
      return "$GATE_APPROVAL_ANSWERED" ;;
  esac
  # A PERSON-SET QUESTION (`사람-결정`, `시각-승인`) IS OPENED ONLY AGAINST A
  # SEGMENT THE LEDGER KNOWS, AND AT MOST TWICE PER SEGMENT AND CLASS. The
  # approval holds that segment's dispatches until
  # a person answers, so a question naming no segment, or one this run never
  # dispatched, would hold nothing a reader can find and would still count
  # against the run's end. The cap counts distinct ids already issued for the
  # segment in any state: a third question is the router asking the same person
  # again instead of parking, and parking is what the refusal leaves it.
  if judgment_class_person "$cls"; then
    local nl=$'\n' pn
    if [ -z "$seg" ] || [ "$seg" = "-" ]; then
      warn "a '$cls' judgment names no segment — it is not opened (pass --segment)"
      return "$GATE_EXIT_RULE"
    fi
    case "$nl$(gate_segment_ids)$nl" in
      *"$nl$seg$nl"*) ;;
      *) warn "a '$cls' judgment names segment '$seg', which has no segment row in this ledger — it is not opened"
         return "$GATE_EXIT_RULE" ;;
    esac
    pn=$({ gate_rows '승인' | grep -F "| 판단 부류=$cls |" | grep -F "| 막는 세그먼트=$seg |" || true; } \
      | tr '|' '\n' | sed -n 's/^ *승인 id=//p' | sed 's/[[:space:]]*$//' | sort -u | gate_count)
    if [ "${pn:-0}" -ge 2 ]; then
      warn "segment $seg already has $pn '$cls' questions — a third is not opened; park the segment with a blocked row instead"
      return "$GATE_EXIT_RULE"
    fi
  fi
  # THE SIDECAR BLOCK IS WRITTEN BEFORE THE ROW, so the anchor the row carries
  # names a block that exists. A block whose row never lands is an orphan and
  # harmless; a row whose block never lands is an anchor to nothing, and the
  # digest beside it then proves nothing. The write failing is loud and does not
  # stop the issue: an act refused with nothing pending is the worse failure,
  # and the row still carries the digest a later reader can check the text
  # against once the sidecar is repaired.
  gate_approval_sidecar_write "$id" issue '질문' "$qfull" \
    || warn "could not write the full question text into the approval sidecar — the row is issued, but there is no block where the anchor $(gate_approval_sidecar_anchor "$id") points"
  qdig=$(printf '%s' "$qfull" | shasum -a 256 | cut -d' ' -f1)
  # `유도 절단점=-` AND NOT THE EXPORTED GLOBAL, for the same reason the act
  # digest beside it is `-`: a judgment approval HAS NO ACT. `GATE_ACT_DERIVED`
  # may well be set — the judgment is raised while some act is being adjudicated
  # — and carrying that value here would say the argv of an unrelated act was
  # the argv of this row, which has none. The field is written rather than
  # omitted because `절단점` is on the row, and a reader that finds one of the
  # pair without the other cannot tell "nothing was derived" from "this
  # recording site was forgotten".
  gate_append '승인' "승인 id=$id" "상태=대기" "대상=$alias" "절단점=판단" \
    "유도 절단점=-" \
    "행위 다이제스트=-" "구속 튜플=${seg:--}/$qdig/$GATE_MENU_VERSION/$(gate_tuple_snap)" \
    "막는 세그먼트=${seg:--}" "연 자리=$seat" "질문 문면=$q" "답변 문면=-" \
    "사이드카 앵커=$(gate_approval_sidecar_anchor "$id")" \
    "판단 부류=${cls:--}" \
    "발행 시각=$(now_iso)" "해소 시각=-"
  local vr=0
  gate_visual_approval_resolve "$id" "$q" "$cls" || vr=$?
  [ "$vr" = "0" ] || return "$vr"
  if gate_auto_resolve_enabled; then
    local ar=0
    gate_auto_resolve_judgment "$id" "$q" "$cls" || ar=$?
    return "$ar"
  fi
  warn "judgment approval wait issued $id — this judgment waits for a human answer (the run continues alongside it)"
  gate_warn_canon_prompt "$id" "$q"
}

gate_judgment_class_adoptable() {
  # gate_judgment_class_adoptable <판단 부류> — true when the class may be
  # adopted without a person: named, inside the vocabulary, and not one of the
  # classes that hand risk to the user. One predicate, because auto-resolution
  # and the emission absorber's answered branch both decide on it, and two
  # copies of the condition would grow apart.
  local cls="${1:-}"
  ! judgment_class_person "$cls" || return 1
  [ -n "$cls" ] && judgment_class_ok "$cls" && ! judgment_class_forbidden "$cls"
}

gate_segment_person_hold() {
  # gate_segment_person_hold <segment> — the id of an open person-set question
  # that names this segment in `막는 세그먼트`, or nothing. The first such id is
  # enough: the caller asks whether the segment is held, not by how many.
  local seg="$1" id
  for id in $(gate_person_hold_ids); do
    if [ "$(gate_approval_field "$id" '막는 세그먼트')" = "$seg" ]; then
      printf '%s' "$id"
      return 0
    fi
  done
  return 0
}

gate_segment_visual_refusal() {
  # gate_segment_visual_refusal <segment> — the id of a `시각-승인` question of
  # this run that names the segment in `막는 세그먼트` and that a person closed
  # `거부` or `무효`, consumed or not; nothing when there is none.
  #
  # A CONSUMED REFUSAL STILL SAYS NO. Consuming it (`결정=거절 소비`) takes it
  # out of the hold above, and the resubmission that consumes it ends on exit 0
  # like an adoption does; the sidecar's implementation approval is not touched
  # by the person's `거부`. So the predicate alone would let the screens the
  # person refused be implemented by a router that read that exit 0 as an
  # adoption.
  local seg="$1" id
  for id in $( { gate_rows '승인' || true; } | { grep -F '| 판단 부류=시각-승인 |' || true; } \
               | tr '|' '\n' | sed -n 's/^ *승인 id=//p' | sed 's/[[:space:]]*$//' | sort -u); do
    [ -n "$id" ] || continue
    [ "$(gate_approval_field "$id" '막는 세그먼트')" = "$seg" ] || continue
    case "$(gate_approval_state "$id")" in
      거부|무효) printf '%s' "$id"; return 0 ;;
    esac
  done
  return 0
}

gate_person_hold_ids() {
  # gate_person_hold_ids — the person-set approvals (`사람-결정`, `시각-승인`)
  # that hold their segment:
  # every open one, and every one a person closed `거부` or `무효` that no
  # `자율 승인` row has consumed yet.
  #
  # A REFUSAL HOLDS UNTIL THE PARK IS RECORDED. Read from the open ones alone,
  # the hold lifted the moment the person said no, and in that same snapshot
  # the sibling came out `가능` in `replan_due[]` beside its own `거부` in
  # `answered_judgments[]` — so a router reading the first key re-planned the
  # segment the person had just refused. The consumption that ends the hold is
  # admitted only once the segment is parked (`gate_person_refusal_consumable`),
  # so the hold and the park meet with nothing open between them. Termination
  # condition 2 and the boundaries still count the open ones alone: a refusal
  # is answered, and what it waits for is the router, not a person.
  local id
  gate_pending_approval_ids 사람
  for id in $( { gate_rows '승인' || true; } | { grep -F -e '| 판단 부류=사람-결정 |' -e '| 판단 부류=시각-승인 |' || true; } \
               | tr '|' '\n' | sed -n 's/^ *승인 id=//p' | sed 's/[[:space:]]*$//' | sort -u); do
    [ -n "$id" ] || continue
    case "$(gate_approval_state "$id")" in 거부|무효) ;; *) continue ;; esac
    gate_has_row '자율 승인' "| 해소 승인=$id |" || printf '%s\n' "$id"
  done
}

gate_person_refusal_consumable() {
  # gate_person_refusal_consumable <승인 id> — 0 when the approval is a
  # person-set question a person closed `거부` or `무효`, no `자율 승인` row
  # has named it yet, and its segment is parked; 2 when only the park is
  # missing; 1 otherwise.
  #
  # A PERSON'S NO TO THIS CLASS IS AN ANSWER THE ROUTER ACTS ON, so it is spent
  # once, the way a `승인` is. The router parks the segment on it and resubmits
  # the judgment to say so; the row that resubmission writes carries
  # `해소 승인=<id>` and `결정=거절 소비`, and that row is what takes the answer
  # out of `answered_judgments[]`. Every other class keeps its refusal as a
  # closed question: nobody acts on it, so there is nothing to consume.
  #
  # THE PARK COMES FIRST, AND IT IS A `segment` ROW. The consumption is what
  # lifts the hold (`gate_person_hold_ids`), so a consumption admitted before
  # the park left a refused segment unheld and unparked; and a cone `blocked`
  # row is no park, because the segment's state is what every reader of
  # "ended" reads.
  local id="$1" seg
  case "$(gate_approval_state "$id")" in 거부|무효) ;; *) return 1 ;; esac
  judgment_class_person "$(gate_approval_field "$id" '판단 부류')" || return 1
  ! gate_has_row '자율 승인' "| 해소 승인=$id |" || return 1
  seg=$(gate_approval_field "$id" '막는 세그먼트')
  [ "$(gate_segment_field "$seg" '상태')" = "park" ] || return 2
  return 0
}

gate_judgment_target_id() {
  # gate_judgment_target_id <segment> <키=값>... — the approval id a grade-2
  # judgment resolves to: the hash of its `기준 — 근거`, or, when the row
  # carries `답한 승인=<id>`, that id once it is shown to be an answered
  # `사람-결정` question on this segment that no row has consumed. Status 1,
  # with the reason warned, when the cited id is none of that.
  #
  # THE CITATION IS WHAT LETS `근거` SAY WHAT WAS DONE. The row that consumes a
  # person's answer has to carry what the router did with it, and the id is a
  # hash of `근거` — so a consuming row that wrote its action into `근거` hashed
  # to a new question, issued it, held the segment again and left the real
  # answer unspent. Naming the answered id lets the row keep its own `근거`.
  # The checks are the ones a cited id has to meet to stand for the hash: the
  # class, a closed state, the segment and the spent test. The class is the
  # literal `사람-결정` and not the person set: `답한 승인` consumes a free-text
  # answer, and a `시각-승인` question carries none to consume.
  local seg="$1" cited; shift
  cited=$(gate_field_of '답한 승인' "$@")
  if [ -z "$cited" ]; then
    gate_judgment_approval_id "$seg" \
      "$(gate_judgment_question "$(gate_field_of '기준' "$@")" "$(gate_field_of '근거' "$@")")"
    return 0
  fi
  if [ "$(gate_approval_field "$cited" '판단 부류')" != "사람-결정" ] \
     || [ "$(gate_approval_field "$cited" '절단점')" != "판단" ]; then
    warn "답한 승인=$cited 은 사람-결정 판단 승인이 아닙니다 — 이 키는 사람-결정의 답을 소비하는 행에만 씁니다"
    return 1
  fi
  case "$(gate_approval_state "$cited")" in
    승인|거부|무효) ;;
    *) warn "답한 승인=$cited 은 아직 답이 오지 않았습니다 (상태 $(gate_approval_state "$cited"))"; return 1 ;;
  esac
  if [ "$(gate_approval_field "$cited" '막는 세그먼트')" != "$seg" ]; then
    warn "답한 승인=$cited 이 세운 세그먼트는 $(gate_approval_field "$cited" '막는 세그먼트') 이고 이 판단의 세그먼트는 ${seg:--} 입니다"
    return 1
  fi
  if gate_has_row '자율 승인' "| 해소 승인=$cited |"; then
    warn "답한 승인=$cited 은 이미 소비되었습니다 — 한 답은 한 번만 소비합니다"
    return 1
  fi
  printf '%s' "$cited"
}

gate_auto_resolve_judgment() {
  # gate_auto_resolve_judgment <승인 id> <질문 문면> <판단 부류>
  #
  # Returns the issuer's own codes, so every caller's existing translation still
  # applies: `GATE_APPROVAL_ANSWERED` when the recommendation was adopted,
  # `GATE_EXIT_RULE` when it was refused. `GATE_AUTO_RESOLVED_APPROVAL` names the
  # id, which is what separates an answer closed just now from an old answer that
  # has already been spent.
  #
  # AN ALLOW LIST AND NOT A DENY LIST. Adoption needs a class that names what is
  # being adopted, and an empty value names nothing. Matching only the two
  # forbidden classes let every path that dropped the class on the way here fall
  # through to adoption: a stage that emitted `시각-면제` reached this function
  # with an empty class, and a grade-2 judgment submitted without one did too,
  # and both were adopted in a default configuration with nobody asked.
  #
  # A CLOSE THE TRANSITION GUARD REFUSED IS NOT THIS CALL'S RESOLUTION. Another
  # close reached the approval first, so the id is cleared and the code is
  # derived from the state that close left — the same three answers the issuer
  # gives for an approval it finds already closed or still open.
  local id="$1" q="$2" cls="${3:-}" st rec rc=0
  # THE PERSON SET IS HELD, NEITHER ADOPTED NOR REFUSED. Refusing it would close
  # the question nobody was asked, and the router would then park on a refusal
  # no person gave. The recorded class is read too, so a resubmission that
  # dropped the class still finds the approval held. The id is not exported:
  # nothing was resolved by this call. A `시각-승인` question reaches here only
  # after its sidecar predicate failed — the predicate arm runs first.
  local held=""
  if judgment_class_person "$cls"; then
    held="$cls"
  elif judgment_class_person "$(gate_approval_field "$id" '판단 부류')"; then
    held="$(gate_approval_field "$id" '판단 부류')"
  fi
  if [ -n "$held" ]; then
    GATE_AUTO_RESOLVED_APPROVAL=""; export GATE_AUTO_RESOLVED_APPROVAL
    warn "judgment approval $id is a '$held' question — the gate does not answer it, and it waits for a person"
    gate_warn_canon_prompt "$id" "$q"
    return 0
  fi
  GATE_AUTO_RESOLVED_APPROVAL="$id"; export GATE_AUTO_RESOLVED_APPROVAL
  if gate_judgment_class_adoptable "$cls"; then
    st=승인; rec="라우터 판단 채택"
  elif [ -z "$cls" ]; then
    st=거부; rec="판단 부류가 없어 채택하지 않음"
  elif judgment_class_forbidden "$cls"; then
    st=거부; rec="위험을 사용자에게 넘기는 부류라 채택하지 않음"
  else
    st=거부; rec="어휘 밖 부류라 채택하지 않음"
  fi
  gate_auto_close_approval "$id" "$st" "$q" "$rec" || rc=$?
  if [ "$rc" != "0" ]; then
    GATE_AUTO_RESOLVED_APPROVAL=""; export GATE_AUTO_RESOLVED_APPROVAL
    case "$(gate_approval_state "$id")" in
      승인) return "$GATE_APPROVAL_ANSWERED" ;;
      무효|거부) return "$GATE_EXIT_RULE" ;;
    esac
    return 0
  fi
  [ "$st" = "승인" ] && return "$GATE_APPROVAL_ANSWERED"
  return "$GATE_EXIT_RULE"
}

gate_segment_screen_slice() {
  # gate_segment_screen_slice <segment> — 0 when the segment carries a screen
  # slice: one whose implementation waits for the approved screens.
  #
  # Only a run governed by a declaration has slices, and there the segment id
  # IS the slice id. A run with no declaration plans one segment from the
  # plan's implement step and carries no `**화면**` field, so it does not wait.
  # In a declared run, `없음` waits for nothing and a screen-id list waits; an
  # omitted field waits for every screen when the plan has a visual stage or
  # the document has a visual sidecar, and for nothing otherwise.
  local seg="$1" v=""
  [ -n "${DOC:-}" ] && [ -f "${DOC:-}" ] || return 1
  [ "$(gate_slicing_branch)" = "선언통치" ] || return 1
  case "
$(slice_ids "$DOC" 2>/dev/null || true)
" in
    *"
$seg
"*) : ;;
    *) return 1 ;;
  esac
  v=$(slice_field "$DOC" "$seg" '화면' 2>/dev/null || true)
  [ "$v" != "없음" ] || return 1
  [ -z "$v" ] || return 0
  if [ -n "$( { manifest_plan_json 2>/dev/null \
                | jq -r '.steps[]? | select(type == "object" and .skill == "visual") | .id' 2>/dev/null \
                || true; } )" ]; then
    return 0
  fi
  bash "$GATE_DIR/visual-check.sh" bundle "$DOC" >/dev/null 2>&1
}

gate_visual_approval_holds() {
  # gate_visual_approval_holds — 0 when the run's design document carries a
  # valid implementation approval in its visual sidecar, 1 otherwise. Prints
  # the predicate's own one line either way (`승인 유효 <12 hex>`, or the
  # reason it does not hold), so every caller quotes the same words.
  #
  # ONE PREDICATE, `visual-check.sh approval`. The gate's dispatch refusal, the
  # predicate arm of a `시각-승인` question and the person's close all ask it,
  # so none of them can come to hold an approval the others would refuse. A run
  # with no design document has no sidecar to read, and the predicate does not
  # hold.
  local out rc=0
  if [ -z "${DOC:-}" ]; then
    printf '승인 없음 — 이 런에 설계 문서가 없다'
    return 1
  fi
  out=$(bash "$GATE_DIR/visual-check.sh" approval "$DOC" 2>&1) || rc=$?
  printf '%s' "$(printf '%s\n' "$out" | sed -n 1p)"
  [ "$rc" = "0" ]
}

gate_visual_approval_resolve() {
  # gate_visual_approval_resolve <승인 id> <질문 문면> <판단 부류>
  #
  # THE PREDICATE ARM. A `시각-승인` question asks whether the screens a slice
  # implements were approved at the fixed seat, and the sidecar answers that
  # without a person: when `visual-check.sh approval` holds, the question is
  # closed `승인` here, with the predicate's digest in the answer text, and the
  # same act adopts it. It runs only for that class and whatever
  # `CC_CMDS_AUTOPILOT_AUTO_RESOLVE` says — the switch governs adopting the
  # router's recommendation, and this is not one.
  #
  # Returns `GATE_APPROVAL_ANSWERED` with `GATE_AUTO_RESOLVED_APPROVAL` set to
  # the id when it closed the question, and 0 with that variable empty when it
  # did not; on 0 nothing was written, and the caller's existing path follows —
  # the hold for the person set, so the class never reaches the forbidden
  # classes' `거부`.
  #
  # A QUESTION A PERSON ANSWERED IN WORDS IS NOT CLOSED HERE. Its last row
  # carries `처분 사유=자유 입력`, the `'대기' 1` transition refuses that row,
  # and the seat asks the person again for the label.
  local id="$1" q="$2" cls="${3:-}" why
  GATE_AUTO_RESOLVED_APPROVAL=""; export GATE_AUTO_RESOLVED_APPROVAL
  [ -n "$cls" ] || cls=$(gate_approval_field "$id" '판단 부류')
  [ "$cls" = "시각-승인" ] || return 0
  [ "$(gate_approval_state "$id")" = "대기" ] || return 0
  gate_approval_person_answered "$id" && return 0
  why=$(gate_visual_approval_holds) || return 0
  gate_auto_close_approval "$id" 승인 "$q" "시각 승인 술어 성립: $why" || return 0
  GATE_AUTO_RESOLVED_APPROVAL="$id"; export GATE_AUTO_RESOLVED_APPROVAL
  return "$GATE_APPROVAL_ANSWERED"
}

gate_revert_surface() {
  # gate_revert_surface <되돌리는 법> — the axis-2 grade of the undo command.
  #
  # Prose has no argv0 the table recognises, so it lands on `등급 미상` — which
  # is exactly the discrimination arm (b-1) wants. An undo nobody can run is not
  # an undo, and a reversibility floor that accepts a sentence is a floor made
  # of the claim it was supposed to check.
  [ -n "${1:-}" ] || { printf '등급 미상'; return 0; }
  # Deliberately unquoted: the value is a command line and the table grades its
  # words, argv0 first.
  # shellcheck disable=SC2086
  surface_of_argv0 $1
}

gate_physical_path() {
  # gate_physical_path <경로> — the path with its directory resolved through
  # `pwd -P` and a symlinked final component followed, so that two spellings of
  # one file compare equal.
  #
  # `readlink -f` would do this in one call and is the spelling that differs
  # between the BSD and GNU builds, so the walk is written out. Bounded at eight
  # hops: a symlink cycle is a filesystem a caller can build, and an unbounded
  # follow would hang the gate rather than refuse anything.
  #
  # `cd -P`, NOT `cd`. The default `cd` folds `<component>/..` as text before it
  # changes directory, while the kernel follows a symlinked component first and
  # then takes `..` from where the link pointed. `<link>/../<…>/base-split.py`
  # then resolved here to the gate's own copy while the kernel ran a planted file
  # of that name — and the helper trust check compares exactly this value.
  local p="$1" d b link n=0
  d=$(dirname -- "$p"); b=$(basename -- "$p")
  [ -d "$d" ] || { printf '%s' "$p"; return 0; }
  p="$(cd -P -- "$d" && pwd -P)/$b"
  while [ -L "$p" ] && [ "$n" -lt 8 ]; do
    link=$(readlink "$p" 2>/dev/null) || break
    [ -n "$link" ] || break
    case "$link" in
      /*) p="$link" ;;
      *) p="$(dirname -- "$p")/$link" ;;
    esac
    d=$(dirname -- "$p"); b=$(basename -- "$p")
    [ -d "$d" ] || break
    p="$(cd -P -- "$d" && pwd -P)/$b"
    n=$((n + 1))
  done
  printf '%s' "$p"
}

gate_own_helper() {
  # gate_own_helper <argv0> — 0 when argv0 is the file of that name beside this
  # gate, compared as physical paths. A bare name is what the act's PATH finds,
  # and a relative one is read from the act's directory, because those are the
  # files that would run.
  local a0="$1" name="${1##*/}"
  case "$a0" in
    */*) ;;
    *) a0=$(command -v -- "$a0" 2>/dev/null) || return 1 ;;
  esac
  case "$a0" in
    /*) ;;
    */*) a0="${GATE_ACT_CWD:-$PWD}/$a0" ;;
    *) return 1 ;;
  esac
  [ -f "$a0" ] || return 1
  [ "$(gate_physical_path "$a0")" = "$(gate_physical_path "$GATE_DIR/$name")" ]
}

gate_chrome_headless_screenshot() {
  # gate_chrome_headless_screenshot <chrome argv after argv0> — 0 when the
  # argv is the headless screenshot form and nothing else: `--headless` (bare
  # or `=<mode>`), one `--screenshot=<absolute path outside the tree>`, exactly
  # one local `file:///` target, and otherwise only the flags listed below.
  #
  # AN ALLOW-LIST, NOT A PRESENCE CHECK. Requiring the two flags alone admitted
  # a remote page (`--screenshot=x https://…`, the spelling Chrome's own
  # documentation shows), a DOM dump or debugging port beside the screenshot,
  # and launcher switches such as `--renderer-cmd-prefix=<program>` that make
  # Chrome run another program — all as a write outside the tree, which needs
  # no pre-authorization row. Any flag or operand this list does not name keeps
  # the binary at `등급 미상`. The listed flags size the page, quiet Chrome's
  # own background traffic, point the proxy at the closed local port, or put
  # the profile in scratch space.
  local a v headless=0 shot=0 target=0
  for a in "$@"; do
    case "$a" in
      */../*|*/..) return 1 ;;
    esac
    case "$a" in
      --headless|--headless=*) headless=1 ;;
      --screenshot=/?*)
        gate_chrome_path_ok shot "${a#--screenshot=}" || return 1
        shot=$((shot + 1)) ;;
      --user-data-dir=/?*)
        gate_chrome_path_ok profile "${a#--user-data-dir=}" || return 1 ;;
      --window-size=?*)
        v=${a#--window-size=}
        case "$v" in *[!0-9,]*) return 1 ;; esac ;;
      --force-device-scale-factor=?*|--virtual-time-budget=?*)
        v=${a#*=}
        case "$v" in *[!0-9.]*) return 1 ;; esac ;;
      --default-background-color=?*)
        v=${a#*=}
        case "$v" in *[!0-9a-fA-F]*) return 1 ;; esac ;;
      --proxy-server=127.0.0.1:9) ;;
      --hide-scrollbars|--disable-gpu|--no-first-run|--disable-background-networking|--disable-component-update|--disable-sync) ;;
      file:///?*)
        v=${a#file://}
        v=${v%%[?#]*}
        case "$v" in *%*) return 1 ;; esac
        gate_chrome_path_ok page "$v" || return 1
        target=$((target + 1)) ;;
      *) return 1 ;;
    esac
  done
  [ "$headless" = 1 ] && [ "$shot" = 1 ] && [ "$target" = 1 ]
}

gate_chrome_path_ok() {
  # gate_chrome_path_ok <shot|profile|page> <absolute path> — 0 when every
  # spelling of the path stays where the Chrome row lets that operand point.
  # The spellings are the path as written, with its existing ancestors resolved
  # and with a symlinked last component followed, so a link under scratch space
  # that lands in the tree or in a configuration home is judged where it lands.
  #   shot    — outside the tree, the machine-global prefixes and the
  #             configuration homes;
  #   profile — under the temp directory, and outside the tree and the
  #             machine-global prefixes;
  #   page    — outside the configuration homes, so a key or token file is not
  #             rendered into an image.
  # The configuration homes are the dot-directories directly under `$HOME`
  # (`.ssh`, `.config`, `.claude*`, …), matched without regard to case
  # (`gate_chrome_in_home_dot`), and `CLAUDE_CONFIG_DIR` when it is set.
  #
  # THE MACHINE-GLOBAL PREFIXES ARE THE REACH FLOOR'S OWN. The floor compares
  # whole argv words, and Chrome's destination is always one word with the
  # path behind `--screenshot=`, so the floor never sees it; without this arm a
  # screenshot over `/opt/homebrew/bin/<tool>` kept a declared `런로컬` while
  # `cp` to the same path stops at `기기전역`.
  local kind="$1" p="$2" wp wl sp r t under homes root rootp tmp tmpp gpfx
  gpfx=$(gate_reach_global_prefixes)
  wp=$(gate_path_spelling "$(gate_real_prefix "$p")")
  wl=$(gate_leaf_spelling "$wp") || return 1
  root=$(gate_tree_root)
  rootp=$(gate_path_spelling "$(gate_real_prefix "$root")")
  tmp=${TMPDIR:-/tmp}
  while [ "$tmp" != "/" ] && [ "${tmp%/}" != "$tmp" ]; do tmp=${tmp%/}; done
  tmpp=$(gate_path_spelling "$(gate_real_prefix "$tmp")")
  homes=''
  if [ -n "${HOME:-}" ] && [ "$HOME" != "/" ]; then
    homes="${HOME%/}"$'\n'"$(gate_path_spelling "$(gate_real_prefix "${HOME%/}")")"
  fi
  for sp in "$p" "$wp" "$wl"; do
    [ -n "$sp" ] || continue
    if [ "$kind" != page ]; then
      for r in "$root" "$rootp"; do
        [ -n "$r" ] || continue
        gate_nocase_at_or_under "$sp" "$r" && return 1
        gate_path_is_at_or_under "$sp" "$r" && return 1
      done
      while IFS= read -r r; do
        gate_nocase_at_or_under "$sp" "$r" && return 1
        gate_path_is_at_or_under "$sp" "$r" && return 1
      done <<< "$gpfx"
    fi
    if [ "$kind" != profile ]; then
      while IFS= read -r r; do
        [ -n "$r" ] || continue
        gate_chrome_in_home_dot "$sp" "$r" && return 1
      done <<< "$homes"
      if [ -n "${CLAUDE_CONFIG_DIR:-}" ]; then
        gate_path_is_at_or_under "$sp" "${CLAUDE_CONFIG_DIR%/}" && return 1
      fi
    else
      under=0
      for t in "$tmp" "$tmpp" /tmp "$(gate_path_spelling "$(gate_real_prefix /tmp)")"; do
        [ -n "$t" ] && [ "$t" != "/" ] || continue
        if gate_path_is_at_or_under "$sp" "$t"; then under=1; break; fi
      done
      [ "$under" = 1 ] || return 1
    fi
  done
  return 0
}

gate_chrome_in_home_dot() {
  # gate_chrome_in_home_dot <absolute path> <home> — rc 0 when the path is a
  # dot-entry directly under the home or lies inside one, compared as text
  # without regard to case and then by device+inode of the home.
  #
  # CASE IS NOT IDENTITY ON THIS PLATFORM. APFS is case-insensitive by default
  # and `pwd -P` keeps the case the caller wrote, so `/USERS/<user>/.ssh/…`
  # names the real key directory; the text arm folds case for that. The
  # identity walk answers what text cannot fold — the firmlink spelling
  # `/System/Volumes/Data/Users/<user>/…` and a link that reaches the home.
  local rc=1 had=0 p c
  if shopt -q nocasematch; then had=1; fi
  shopt -s nocasematch
  case "$1" in "$2"/.*) rc=0 ;; esac
  if [ "$had" = 0 ]; then shopt -u nocasematch; fi
  [ "$rc" = 0 ] && return 0
  p="$1"
  while [ -n "$p" ] && [ "$p" != "/" ]; do
    c=${p##*/}
    p=${p%/*}
    [ -n "$p" ] || break
    case "$c" in
      .*) if [ "$p" -ef "$2" ]; then return 0; fi ;;
    esac
  done
  return 1
}

gate_path_spelling() {
  # gate_path_spelling <경로> — the path with redundant separators folded away: a
  # run of `/` becomes one, and a `/./` segment becomes `/`.
  #
  # Sibling of `gate_physical_path`, folding one layer below it. That one makes
  # two spellings of a DIRECTORY compare equal by resolving symlinks; this one
  # makes two spellings of a SEPARATOR compare equal. Arm 2 of the manifest guard
  # compares the caller's own bytes against a value the gate normalized, and those
  # two differ by separators alone whenever a path was built by concatenation:
  # `mktemp -d "${TMPDIR:-/tmp}/x.XXXXXX"` on a host whose `TMPDIR` ends in `/`
  # hands back `…/T//x.abc`, while the `cd`+`pwd` normalization at argument-parse
  # time folds the gate's copy to `…/T/x.abc`.
  #
  # Written out rather than delegated to `readlink -f` for the same reason
  # `gate_physical_path` is: that spelling differs between the BSD and GNU builds.
  #
  # Both folds have overlapping matches — `///` leaves a `//` behind, `/././`
  # leaves a `/./` — so this runs to a fixpoint rather than in one pass. Each pass
  # either shortens the string or changes nothing, so the loop terminates.
  local p="$1" prev=''
  while [ "$p" != "$prev" ]; do
    prev=$p
    p=${p//\/\//\/}
    p=${p//\/.\//\/}
  done
  printf '%s' "$p"
}

gate_manifest_write_refuse() {
  # The refusal text, in one place because three arms reach it. Two arms with
  # their own wording would read as two different rules to whoever hits them.
  warn "this is a write to the manifest — only kickoff writes this file: $MANIFEST"
  warn "the \`자동 채택\` rows under \`## 인가\` are declared only where a person is watching — a run growing its own pre-adoption list is authorization extending itself"
}

gate_claudemd_digest() {
  # The sha256 the review approved and the sha256 about to be applied have to be
  # computed the same way or the comparison is theatre. One definition, here, and
  # both sides call it: the review stage writes the value onto its `cycle` row,
  # the layer-3 checker receives this one and compares strings.
  #
  # Slot order is `LC_ALL=C sort`, not glob order, because glob order over these
  # names is locale-dependent and a digest that changes with the caller's locale
  # would refuse every apply on a machine with a different one.
  local d="${RUN_DIR:-}/claudemd" f
  [ -d "$d" ] || { printf '(제안본 없음)'; return 0; }
  f=$(ls "$d"/*.proposed.md 2>/dev/null | LC_ALL=C sort)
  [ -n "$f" ] || { printf '(제안본 없음)'; return 0; }
  # shellcheck disable=SC2086
  cat $f | shasum -a 256 | cut -d' ' -f1
}

gate_claudemd_slot_guard() {
  # gate_claudemd_slot_guard <graded-surface> <argv...>
  #
  # LAYER 2, AND IT REFUSES NOTHING. Its whole output is three exported values;
  # the decision belongs to the `리뷰-후-적용` rule, which is layer 3. Written as
  # a guard beside `gate_manifest_write_guard` because it needs the same thing
  # that one needs — the argv as it actually is, before an interpreter hides the
  # operand — and putting a second copy of that scanning inside a `/bin/sh`
  # checker would be the copy that drifts.
  #
  # THE EXPORT IS A DELIVERABLE, NOT A SIDE EFFECT. The rule fires on
  # `GATE_CLAUDEMD_SLOT` being non-empty and cannot fire on anything else: the
  # cutpoint ladder has no `적용` token, so the `GATE_ACT` idiom every other rule
  # opens with would `exit 0` on the first line, forever, while reading as a
  # check that passes. A layer 2 that catches the act and returns without
  # exporting leaves layer 3 asleep and the failure looks exactly like success.
  #
  # WHY THE READ GRADE RETURNS EARLY. A proposal stage has to read the live file
  # to write a proposal against it, and firing the rule on that read would demand
  # a review record for an act that changes nothing. The delegation caveat from
  # the sibling guard is kept verbatim in shape: a command graded `읽기` from
  # argv0 alone can still write through `-exec` or a wrapper, and those two axes
  # are the ones that decide.
  #
  # THE PROPOSAL OPERAND IS THE THIRD VALUE. The digest covers every proposal in
  # the run's `claudemd/` directory at once, so it cannot tell the rule which
  # file is about to become the slot — and the rule compares the stage rules
  # block of exactly that file with the slot's. Only an operand that sits in
  # this run's `claudemd/` directory is published; one anywhere else leaves the
  # value empty and the rule refuses.
  GATE_CLAUDEMD_SLOT=""
  GATE_CLAUDEMD_DIGEST=""
  GATE_CLAUDEMD_PROPOSAL=""
  export GATE_CLAUDEMD_SLOT GATE_CLAUDEMD_DIGEST GATE_CLAUDEMD_PROPOSAL
  local graded="$1"; shift
  [ "$#" -ge 1 ] || return 0
  case "$graded" in
    읽기)
      case " $* " in
        *" -exec "*|*" -execdir "*|*" -ok "*|*" -okdir "*|*" -delete "*) ;;
        *" -fprintf "*|*" -fprint "*|*" -fprint0 "*|*" -fls "*) ;;
        *)
          case "${1##*/}" in
            command|env|xargs|lockf|nice|nohup|time|timeout|stdbuf) ;;
            *) return 0 ;;
          esac ;;
      esac ;;
  esac

  local a argv0 joined slot="" proposal="" p cdir
  # ARM 1 — the act names its target as an argv element, which is the shape the
  # sanctioned apply has (`cp <제안본> <슬롯>`). This is the only arm that yields
  # a slot path, and the slot path is what the ledger row and the morning report
  # are able to say something about.
  for a in "$@"; do
    case "${a##*/}" in
      CLAUDE.md|CLAUDE.local.md) slot="$a" ;;
      *.proposed.md) proposal="$a" ;;
    esac
  done

  if [ -n "$slot" ]; then
    GATE_CLAUDEMD_SLOT=$(gate_physical_path "$slot")
    [ -n "$GATE_CLAUDEMD_SLOT" ] || GATE_CLAUDEMD_SLOT="$slot"
    GATE_CLAUDEMD_DIGEST=$(gate_claudemd_digest)
    if [ -n "$proposal" ] && [ -n "${RUN_DIR:-}" ] && [ -d "$RUN_DIR/claudemd" ]; then
      p=$(gate_physical_path "$proposal")
      cdir=$(cd -P -- "$RUN_DIR/claudemd" && pwd -P)
      [ -n "$cdir" ] && [ "${p%/*}" = "$cdir" ] && GATE_CLAUDEMD_PROPOSAL="$p"
    fi
    return 0
  fi

  # ARM 2 — AN INTERPRETER HID THE OPERAND. `bash -c 'cat p > ~/.claude-cc/CLAUDE.md'`
  # has no element whose basename is the file, so arm 1 sees nothing while the
  # redirection writes it. Here the whole command line is the operand, exactly as
  # the manifest guard reasons about the same evasion.
  #
  # THE SLOT IS DELIBERATELY NOT PARSED OUT OF IT. Recovering a path from a
  # program text needs a shell parser, and a wrong answer here is worse than no
  # answer: it would name a slot the act does not touch, and the row, the report
  # and the rollback would all point at the wrong file. So the value is the
  # marker below, and layer 3 refuses on it — an application has to name its
  # target as an element, which the sanctioned form already does.
  argv0=${1##*/}
  case "$argv0" in
    bash|sh|zsh|dash|ksh|python|python3|perl|ruby|node|npx|make|env|xargs|find|lockf|command|nice|nohup|time|timeout|stdbuf)
      joined=$(printf '%s ' "$@")
      case "$joined" in
        *CLAUDE.md*|*CLAUDE.local.md*)
          GATE_CLAUDEMD_SLOT='(세탁됨)'
          GATE_CLAUDEMD_DIGEST=$(gate_claudemd_digest) ;;
      esac ;;
  esac
  return 0
}

gate_rundir_is_foreign_run() {
  # gate_rundir_is_foreign_run <folded-path> <run-root> <run-root-physical> \
  #                            <own-physical> <own-logical>
  # rc 0 when the path names a run directory that is not this run's.
  #
  # OWN IS TESTED FIRST, so a legitimate write to this run's own `halt/` or
  # `<segment>.plan.md` never reaches the foreign arm and keeps its exception.
  # The run root is compared in both spellings for the same reason the run
  # directory is: `/var` is a symlink on this platform, so one directory has two
  # names and a test against either alone walks past half the paths.
  #
  # AND IT IS COMPARED BY IDENTITY AS WELL AS BY SPELLING, for the reason
  # `gate_path_ident_prefix` states: on a case-insensitive filesystem
  # `<state>/State/cc-cmds/run/<다른 런>/settings/x.json` is the sibling's real
  # file and matches neither prefix as text. Own is re-tested the same way
  # BEFORE the foreign arm, so a case variant of this run's own directory keeps
  # its exception instead of being read as somebody else's.
  local an="$1" own="$4" ownl="$5" r
  case "$an" in
    "$own"|"$own"/*|"$ownl"|"$ownl"/*) return 1 ;;
  esac
  case "$an" in
    /*)
      if gate_path_ident_prefix "$an" "$own" || gate_path_ident_prefix "$an" "$ownl"; then
        return 1
      fi ;;
  esac
  for r in "$2" "$3"; do
    [ -n "$r" ] || continue
    case "$an" in
      "$r"/*) return 0 ;;
    esac
  done
  case "$an" in
    /*) ;;
    *) return 1 ;;
  esac
  for r in "$2" "$3"; do
    [ -n "$r" ] || continue
    if gate_path_ident_prefix "$an" "$r" && [ "$GATE_IDENT_PREFIX" != "$an" ]; then
      return 0
    fi
  done
  return 1
}

gate_plugin_roots() {
  # gate_plugin_roots — the plugin roots the plugin-root write guard protects,
  # in four globals: `GATE_PR_RL`/`GATE_PR_RP` are the pin's `source` in its
  # lexical and physical spellings, `GATE_PR_HL`/`GATE_PR_HP` the same pair for
  # `dirname "$GATE_DIR"`. Any of the four may be empty.
  #
  # GLOBALS, NOT STANDARD OUTPUT. A root is a path and a path may carry a
  # newline, so a multi-line return would split one root into two wrong ones.
  # Both write guards need the same four values — the plugin guard to refuse,
  # the run directory guard to recognise a directly executed plugin script —
  # and computing them in two places is how the two lists drift apart.
  local src here t
  GATE_PR_RL=""; GATE_PR_RP=""; GATE_PR_HL=""; GATE_PR_HP=""; src=""
  if [ -n "${RUN_DIR:-}" ]; then src=$(pin_read "$RUN_DIR" 'source'); fi
  if [ -n "$src" ]; then
    GATE_PR_RL=$(gate_path_spelling "$src")
    t=$(cd "$src" 2>/dev/null && pwd -P) || t=""
    if [ -n "$t" ]; then GATE_PR_RP=$(gate_path_spelling "$t"); fi
  fi
  here=$(dirname "$GATE_DIR")
  if [ -n "$here" ]; then
    GATE_PR_HL=$(gate_path_spelling "$here")
    t=$(cd "$here" 2>/dev/null && pwd -P) || t=""
    if [ -n "$t" ]; then GATE_PR_HP=$(gate_path_spelling "$t"); fi
  fi
  return 0
}

gate_argv0_is_plugin_exec() {
  # gate_argv0_is_plugin_exec <argv0> — rc 0 when the act's argv0 is a file
  # directly inside `<plugin root>/orchestrator/`, spelled as an absolute path.
  #
  # RUNNING A FILE IS NOT WRITING IT, and the two write guards could not tell
  # the difference. The skills prescribe `<plugin root>/orchestrator/
  # cc-team-witness-init.sh <slug>`, the grading table pins that helper to
  # `트리밖쓰기` by name so no declaration moves it off the write path, and both
  # guards then read argv0 as a write operand: the plugin guard refused it
  # through its `orchestrator/` arm, and in a pinned run the run directory guard
  # refused the copy under `$RUN_DIR/plugin/` as well. Every team stage of an
  # unattended run was refused its witness directory, and the suite was green
  # because no row drove the guards through `gate_verb_act`.
  #
  # THE EXEMPTION IS EXACTLY THE PRESCRIBED SHAPE AND NO WIDER. Absolute, so a
  # relative spelling resolved against some other directory is not exempt. The
  # parent must EQUAL `<root>/orchestrator` as a string, so a spelling carrying
  # `..` (`<root>/orchestrator/../hooks/x`) or one level deeper
  # (`<root>/orchestrator/sub/x`) falls out without a separate arm. Only argv0,
  # so an interpreter-wrapped run (`bash <root>/orchestrator/x`) is not exempt:
  # there the script is an operand, and an operand is indistinguishable from a
  # write destination. `hooks/`, `env`/`lockf` wrappers and relative spellings
  # are not exempted either — each would re-open, through this exemption, a
  # wrapping the guards refuse elsewhere.
  local s d b r
  case "${1:-}" in /*) ;; *) return 1 ;; esac
  s=$(gate_path_spelling "$1")
  b=${s##*/}; d=${s%/*}
  case "$b" in ''|.|..) return 1 ;; esac
  gate_plugin_roots
  for r in "$GATE_PR_RL" "$GATE_PR_RP" "$GATE_PR_HL" "$GATE_PR_HP"; do
    [ -n "$r" ] || continue
    [ "$d" = "$r/orchestrator" ] && return 0
  done
  return 1
}

# The characters that make one argv element carry more than one path: shell
# metacharacters of an interpreter program string, the `=` of an option token,
# and the list separators `:` and `,`.
GATE_ARG_SEP='[=;&|<>()`"$:,[:space:]'"'"']'

# The return code `gate_leaf_spelling` gives when the final component is a link
# it could not follow to a non-link. It is not a spelling and it is not "no
# link": it is UNDECIDED, and the two write guards refuse on it.
GATE_LEAF_UNRESOLVED=2

# The return code `gate_arg_words` gives when a word carries a home-directory
# spelling it cannot resolve. Same disposition as the one above and for the same
# reason: a destination the gate cannot name is not a destination it may allow.
GATE_WORD_UNRESOLVED=2

gate_word_unresolved_refuse() {
  # The refusal text for `GATE_WORD_UNRESOLVED`, in one place for the reason the
  # sibling below gives.
  warn "rule refused: the program string carries a home-directory spelling this gate cannot resolve — a previous-directory tilde, a directory-stack tilde, or a tilde naming no account on this host. Where the write would land is undecided, and undecided is not allowed under a write grade. Spell the destination absolutely: $1"
}

gate_leaf_unresolved_refuse() {
  # The refusal text for `GATE_LEAF_UNRESOLVED`, in one place because five arms
  # across the two guards reach it — two arms with their own wording would read
  # as two different rules to whoever hits them.
  warn "rule refused: the final component is a symbolic link this gate could not resolve — the walk stops at eight hops while the kernel follows far more, so where the write would land is undecided. Undecided is not allowed, which is the answer the Write/Edit half already gives when its own walk overflows. Shorten the chain or name the destination directly: $1"
}

gate_arg_is_compound() {
  # gate_arg_is_compound <arg> — rc 0 when the argument is a compound token
  # (see `GATE_ARG_SEP`) rather than a single path.
  # shellcheck disable=SC2254
  case "$1" in
    *$GATE_ARG_SEP*) return 0 ;;
  esac
  return 1
}

gate_arg_words() {
  # gate_arg_words <compound token> — the words of the token that carry a `/`,
  # in the global array `GATE_ARG_WORDS`.
  #
  # WORDS, BECAUSE NORMALIZING THE WHOLE TOKEN DESTROYS THE PATH IN IT.
  # `gate_lexical_abs` prefixes a base to anything not starting with `/` and
  # rewinds every `..` it meets, so `bash -c "cp e <root>/orchestrator/gate.sh;
  # : /../../.."` normalizes to a string with the root rewound away, and
  # `--output=../../<다른 런>/…` rewinds `--output=..` instead of a directory
  # and never produces an absolute root spelling at all. Split at the
  # separators first and each word is resolved the way the shell will resolve
  # it — against the grading directory.
  #
  # `$HOME`/`${HOME}` and a leading `~` are expanded because they are the two
  # spellings of a home path a program string routinely carries. The split does
  # not glob: `read -a` fills the array without the pathname expansion an
  # unquoted `for w in $x` would do.
  #
  # AND SO ARE THE OTHER TILDE SPELLINGS, because `~` and `~/` are not the two
  # of them but two of five. `~<user>/…` and `~+/…` were left as written, did
  # not start with `/`, and were therefore prefixed with the grading directory —
  # so `bash -c "cp /tmp/e ~<user>/.local/state/…/<다른 런>/settings/x.json"` and
  # `bash -c "cp /tmp/e ~+/../installed/…/gate.sh"` reached the real files past
  # every arm of both guards while the `~/…` control was refused. The user name
  # is visible in every absolute path on this host, so it is not a secret that
  # made the spelling hard to find. `~+` is this act's own directory; a name is
  # resolved through the shell's own expansion; `~-` and a directory-stack
  # tilde name a directory this process does not have, so they are reported
  # unresolved and the caller refuses rather than guessing.
  #
  # With `bare` as the second argument, a word without a `/` that
  # `gate_arg_bare_name` accepts is kept too — `..` and `plugins` inside an
  # interpreter program are destinations the shell resolves exactly as it
  # resolves the same word passed on its own.
  local x="$1" mode="${2:-}" w i tn th
  local -a raw
  GATE_ARG_WORDS=()
  x=${x//'${HOME}'/$HOME}
  x=${x//'$HOME'/$HOME}
  # shellcheck disable=SC2295
  x=${x//$GATE_ARG_SEP/ }
  read -r -a raw <<< "$x"
  i=0
  while [ "$i" -lt "${#raw[@]}" ]; do
    w=${raw[$i]}; i=$((i + 1))
    case "$w" in
      '~') w=$HOME ;;
      '~/'*) w="$HOME/${w#'~/'}" ;;
      '~+'|'~+/'*) w="$(gate_grade_cwd)${w#'~+'}" ;;
      '~-'|'~-/'*) return "$GATE_WORD_UNRESOLVED" ;;
      '~'*)
        tn=${w#'~'}; tn=${tn%%/*}
        # A LOGIN NAME AND NOTHING ELSE. A leading digit is a directory-stack
        # reference rather than an account, and `+`/`-` inside the prefix is the
        # same. Everything outside this shape is reported unresolved.
        case "$tn" in
          ''|[0-9]*|*[!A-Za-z0-9._-]*) return "$GATE_WORD_UNRESOLVED" ;;
        esac
        # The shell's own tilde expansion is what knows where an account's home
        # is, and it needs the name UNQUOTED — hence `eval`, made safe by the
        # shape test directly above rather than by hoping. A name with no
        # account leaves the word unexpanded, which is not an absolute path and
        # is reported unresolved.
        th=""
        eval 'th=~'"$tn" 2>/dev/null || th=""
        case "$th" in
          /*) ;;
          *) return "$GATE_WORD_UNRESOLVED" ;;
        esac
        w="$th${w#"~$tn"}" ;;
    esac
    case "$w" in
      */*) ;;
      *)
        [ "$mode" = bare ] || continue
        gate_arg_bare_name "$w" || continue ;;
    esac
    GATE_ARG_WORDS[${#GATE_ARG_WORDS[@]}]="$w"
  done
  return 0
}

gate_path_ident_prefix() {
  # gate_path_ident_prefix <absolute path> <protected dir> — rc 0 when the
  # protected directory IS the path or one of its ancestors, judged by
  # device+inode rather than by spelling, with the matching ancestor of the
  # argument left in `GATE_IDENT_PREFIX`.
  #
  # SPELLING IS NOT IDENTITY ON THIS PLATFORM. APFS is case-insensitive by
  # default, `pwd -P` preserves whatever case the caller spelled, and every
  # comparison in the two write guards was a byte test — so
  # `<root>/Orchestrator/gate.sh` and `<state>/State/cc-cmds/run/<다른 런>/…`
  # matched no arm and wrote the real installed file. `-ef` is a bash builtin,
  # costs no fork, follows symlinks and reads the same on the BSD and GNU
  # builds. The walk starts at the argument and climbs, so a destination that
  # does not exist yet is answered by its deepest existing ancestor — which is
  # the normal case for `mv` and `cp`.
  #
  # NOT A REPLACEMENT FOR THE LEXICAL ARMS. A path whose whole spelling is
  # hypothetical has no inode anywhere, and the tail below the deepest existing
  # ancestor is still only comparable as text. Both layers run.
  local p="$1"
  GATE_IDENT_PREFIX=""
  [ -n "$2" ] || return 1
  while [ -n "$p" ] && [ "$p" != "/" ]; do
    if [ "$p" -ef "$2" ]; then GATE_IDENT_PREFIX="$p"; return 0; fi
    p=${p%/*}
  done
  return 1
}

gate_path_is_at_or_under() {
  # gate_path_is_at_or_under <path> <protected dir> — rc 0 when the path IS the
  # protected directory or lies under it, by spelling first and then by
  # device+inode. The mirror of `gate_path_is_at_or_above`, and the two together
  # are what a destination has to miss to be outside a protected tree.
  case "$1" in
    "$2"|"$2"/*) return 0 ;;
  esac
  case "$1" in
    /*) gate_path_ident_prefix "$1" "$2" ;;
    *) return 1 ;;
  esac
}

gate_path_is_at_or_above() {
  # gate_path_is_at_or_above <path> <protected dir> — rc 0 when the path is the
  # protected directory itself or one of its ancestors. `/` is answered apart
  # because `"/"/*` is `//*` and matches nothing.
  #
  # The identity arm walks the PROTECTED directory's ancestors and asks whether
  # any of them is the argument, which is this predicate read the other way
  # round — `cp -R x <plugins>/CC-CMDS` names an ancestor of the installed
  # `orchestrator/` that shares no prefix with it as text.
  [ "$1" = "/" ] && return 0
  case "$2/" in
    "$1"/*) return 0 ;;
  esac
  case "$1" in
    /*) gate_path_ident_prefix "$2" "$1" ;;
    *) return 1 ;;
  esac
}

gate_word_is_at_or_above() {
  # gate_word_is_at_or_above <word> <protected dir>... — rc 0 when the word,
  # resolved against the grading directory lexically, physically and through a
  # final link, is one of the protected directories or an ancestor of one.
  # `GATE_LEAF_UNRESOLVED` when the final link could not be followed, which is
  # neither answer and is refused by the caller.
  local w="$1" n p l r s; shift
  n=$(gate_path_spelling "$(gate_lexical_abs "$w")")
  p=$(gate_path_spelling "$(gate_real_prefix "$n")")
  l=$(gate_leaf_spelling "$p") || return "$GATE_LEAF_UNRESOLVED"
  for r in "$@"; do
    [ -n "$r" ] || continue
    for s in "$n" "$p" "$l"; do
      [ -n "$s" ] || continue
      if gate_path_is_at_or_above "$s" "$r"; then return 0; fi
    done
  done
  return 1
}

gate_arg_bare_name() {
  # gate_arg_bare_name <arg> [<base>] — rc 0 when an argument without a `/`
  # still names a directory the act can write into: `.`, `..`, or a name that
  # exists (or is a link) in the grading directory — or in <base> when one is
  # given, which is the directory the command itself resolves from when that is
  # not the grading one (`gate_argv_chdir_base`).
  #
  # THE `/` FILTER AT THE TOP OF BOTH GUARD LOOPS DROPPED THESE, and from a
  # segment worktree that sits beside the installed checkout `..` IS an
  # ancestor of the installed plugin root: `cp -R <evil>/cc-cmds ..` merged
  # over the installed `orchestrator/gate.sh` past both guards. A name that
  # does not exist is not resolved — it can be neither an ancestor of a
  # protected directory nor a link into one, and resolving every word of every
  # act costs a `cd` each. An option-looking token is not a name.
  local b
  case "$1" in
    ''|-*) return 1 ;;
    .|..) return 0 ;;
  esac
  b=${2:-$(gate_grade_cwd)}
  [ -e "$b/$1" ] || [ -L "$b/$1" ]
}

gate_arg_option_value() {
  # gate_arg_option_value <arg> — the value of an option-assignment token
  # (`--directory=<v>`, `-o=<v>`) on standard output, rc 1 when the argument is
  # not one or its value is empty or itself compound.
  #
  # THE VALUE IS ONE PATH, handed to the program whole. The token as a whole is
  # compound — its `=` is a separator — so the ancestor arms that take only a
  # whole-path argument never saw `--directory=<root>` or `--directory=..`.
  # A compound value (`--message=a / b`) is text rather than a path and is left
  # to the word arm.
  local v
  case "$1" in
    -*=*) v=${1#*=} ;;
    *) return 1 ;;
  esac
  [ -n "$v" ] || return 1
  if gate_arg_is_compound "$v"; then return 1; fi
  printf '%s' "$v"
}

gate_nocase_glob() {
  # gate_nocase_glob <string> <glob> — rc 0 when the string matches the glob
  # (given unquoted, so its `*` is a wildcard) without regard to case.
  #
  # CASE IS NOT IDENTITY ON THIS PLATFORM, and the identity walk
  # (`gate_path_is_at_or_under`) answers it only for a path whose ancestor
  # exists. A pacing root before its first lease and a record name before its
  # file is written have no inode, and on
  # the default case-insensitive volume `…/PACE/backlog.jsonl` and
  # `R8.PLAN.md` create or overwrite the real files. Text compared case-blind
  # closes that without touching the filesystem; on a case-sensitive volume it
  # also refuses a neighbour that differs only in case, which is the safe
  # direction. `nocasematch` is restored to what the caller had.
  local rc=1 had=0
  if shopt -q nocasematch; then had=1; fi
  shopt -s nocasematch
  # shellcheck disable=SC2254
  case "$1" in $2) rc=0 ;; esac
  if [ "$had" = 0 ]; then shopt -u nocasematch; fi
  return "$rc"
}

gate_nocase_at_or_under() {
  # gate_nocase_at_or_under <path> <root> — rc 0 when the path is the root or
  # lies under it, compared as text without regard to case. The root is taken
  # literally; see `gate_nocase_glob` for why case is folded.
  local rc=1 had=0
  if shopt -q nocasematch; then had=1; fi
  shopt -s nocasematch
  case "$1" in "$2"|"$2"/*) rc=0 ;; esac
  if [ "$had" = 0 ]; then shopt -u nocasematch; fi
  return "$rc"
}

gate_nocase_contains() {
  # gate_nocase_contains <haystack> <needle> — rc 0 when the needle, taken
  # literally, occurs in the haystack without regard to case.
  local rc=1 had=0
  if shopt -q nocasematch; then had=1; fi
  shopt -s nocasematch
  case "$1" in *"$2"*) rc=0 ;; esac
  if [ "$had" = 0 ]; then shopt -u nocasematch; fi
  return "$rc"
}

gate_record_suffix() {
  # gate_record_suffix <name> — rc 0 when the name ends in one of the three
  # kickoff-frozen record suffixes, without regard to case. Three calls rather
  # than one `a|b|c` glob: `|` from an expansion is a character, not syntax.
  gate_nocase_glob "$1" '*.plan.md' || gate_nocase_glob "$1" '*.interview.md' \
    || gate_nocase_glob "$1" '*.kickoff.md'
}

gate_dest_tails() {
  # gate_dest_tails <word> — every spelling of a destination the word can
  # carry, the word itself first, in the global array `GATE_DEST_TAILS`.
  #
  # A DESTINATION IS OFTEN GLUED TO A COMMAND LETTER OR AN OPTION, not separated
  # from it. `sed -n 'w<path>'`, `sed '1w<path>'`, `sed 's/a/b/w<path>'` and
  # `sort -o<path>` are standard spellings, and none of them has a character
  # `GATE_ARG_SEP` splits at — so the whole word was resolved against the act's
  # directory as `<cwd>/w<path>` and missed the protected file it writes.
  # Three readings are added beside the word:
  #   - a single-dash option's attached value (`-o<path>` → `<path>`);
  #   - the text after every `w` or `W` in the word (`1,5w<path>`,
  #     `!w<path>`, `1{w<path>`, `\%re%w<path>`, `0~1w<path>` → `<path>`);
  #   - every tail that starts at a `/`, so an absolute path anywhere inside
  #     the word (`s/a/b/w/<abs>`) is a candidate.
  # THE SED ADDRESS IS NOT ENUMERATED. A closed list of the characters that may
  # stand before the `w` let `$!w<relative path>` and `1{w<relative path>` past
  # both guards with BSD sed writing the file, because an address can end in
  # `!`, `{`, a regex delimiter or a GNU `~` step and the list named none of
  # them. Taking the text after every `w` needs no grammar of what precedes it.
  # A reading that names nothing is harmless: it resolves to a path the guard
  # does not protect. These are candidates for the at-or-under test only; the
  # ancestor test is not given tails, because every word with a `/` has `/`
  # itself among them.
  local w="$1" t
  GATE_DEST_TAILS=("$w")
  case "$w" in
    --*) ;;
    -?*)
      if [ -n "${w#-?}" ]; then
        GATE_DEST_TAILS[${#GATE_DEST_TAILS[@]}]=${w#-?}
      fi ;;
  esac
  t=$w
  while :; do
    case "$t" in *[wW]?*) ;; *) break ;; esac
    t=${t#*[wW]}
    GATE_DEST_TAILS[${#GATE_DEST_TAILS[@]}]=$t
  done
  t=${w#?}
  while :; do
    case "$t" in */*) ;; *) break ;; esac
    t="/${t#*/}"
    GATE_DEST_TAILS[${#GATE_DEST_TAILS[@]}]=$t
    t=${t#/}
  done
  return 0
}

gate_opt_attached_values() {
  # gate_opt_attached_values <word> — every value a single-dash option cluster
  # can carry glued to it, in the global array `GATE_OPT_VALUES`: the text after
  # each leading option letter (`-t<dir>` → `<dir>`, `-Rt<dir>` → `t<dir>` and
  # `<dir>`). Empty for a word that is not a single-dash cluster.
  #
  # AN OPTION'S GLUED VALUE IS A DESTINATION TOO. The ancestor arms skipped every
  # word starting with `-`, and `gate_arg_option_value` reads only the `-x=<v>`
  # form, so GNU `gcp -R <tree> -t<state>/cc-cmds` merged a replacement tree over
  # the pacing root with nothing looking at its target. Attaching an option's
  # value is the standard utility syntax, and getopt lets letters cluster in
  # front of it, so every split after a leading letter is a candidate; a reading
  # that names nothing resolves to a path no guard protects.
  local w="$1"
  GATE_OPT_VALUES=()
  case "$w" in
    --*|-|[!-]*|'') return 0 ;;
  esac
  w=${w#-}
  while [ -n "$w" ]; do
    case "$w" in
      [A-Za-z]*) ;;
      *) break ;;
    esac
    w=${w#?}
    [ -n "$w" ] && GATE_OPT_VALUES[${#GATE_OPT_VALUES[@]}]=$w
  done
  return 0
}

gate_pace_tail_may_hit() {
  # gate_pace_tail_may_hit <path> <base> <root name>... — rc 0 when the path
  # can lie at or under the pacing root and has to be resolved, rc 1 when it
  # cannot. Forks nothing.
  #
  # RESOLVING EVERY TAIL WAS THE COST. `gate_dest_tails` hands over one
  # candidate per `/` in a word, and each went through four command
  # substitutions before any comparison — measured, the pacing guard went from
  # 0.07 to 0.19 seconds a call on every write-graded act of every stage. A path
  # whose spelling holds none of the root's final names (compared case-blind)
  # can still land under the root only through a link somewhere on its way, so
  # a path that carries neither is answered here without a fork. The caller
  # skips this when its base itself lies under the root, because there a bare
  # name is a path under the root that spells nothing.
  local v="$1" base="$2" p n; shift 2
  for n in "$@"; do
    [ -n "$n" ] || continue
    if gate_nocase_contains "$v" "$n"; then return 0; fi
  done
  case "$v" in
    /*) p=$v ;;
    *) p="$base/$v" ;;
  esac
  while [ -n "$p" ] && [ "$p" != "/" ]; do
    if [ -L "$p" ]; then return 0; fi
    p=${p%/*}
  done
  return 1
}

gate_argv0_wraps() {
  # gate_argv0_wraps <argv0> — rc 0 when argv0 is an interpreter or a wrapper
  # whose later arguments are program text: the list the CLAUDE.md slot guard
  # and the manifest guard's second arm already read that way.
  case "${1##*/}" in
    bash|sh|zsh|dash|ksh|python|python3|perl|ruby|node|npx|make|env|xargs|find|lockf|command|nice|nohup|time|timeout|stdbuf)
      return 0 ;;
  esac
  return 1
}

gate_argv_chdir_base() {
  # gate_argv_chdir_base <argv...> — the directory a directly graded command
  # enters before it resolves its OWN relative operands, absolutized, or rc 1
  # when there is none.
  #
  # THE GUARD AND THE COMMAND WERE MEASURING FROM DIFFERENT DIRECTORIES.
  # `git -C <sibling> diff --output=<relative path>` resolves that output path
  # from the `-C` directory while every resolver here resolved it from the
  # grading directory, so a relative spelling reaching the installed
  # `orchestrator/gate.sh` matched no arm of either write guard and the command
  # then truncated the real file to zero bytes. `-C <dir>` is an allowed global
  # option that `surface_of_git` steps over in two tokens and `diff --output=`
  # is graded `트리밖쓰기`, so the declaration is honest and the grade is right —
  # it is the BASE that was wrong. The bypass needs a sibling directory and a
  # relative path, and nothing more: a wrapper in front of `git` does not stop
  # it, because the grading table unwraps `nohup`, `timeout`, `nice`, `stdbuf`,
  # `env`, `command`, `time`, `lockf` and `find -exec` and grades the inner
  # `git` as it grades a bare one. FOR `find` THAT HOLDS PRIMARY BY PRIMARY, not
  # for the argv as a whole: every primary is resolved and the answers are folded,
  # so `-exec true {} ';' -exec git … {} ';'` is read as the `git` and not as a
  # tail of `true`. `find -execdir` and `-okdir` run the inner `git` from each
  # match's directory rather than the grading one. An absolute `-C` would still
  # be the right base there, but with no `-C`, with `-C .`, under `-okdir` and
  # with a bare name operand no base stood at all and both write guards passed
  # the act at rc 0 — measured, which is what that spelling was waiting on. It
  # is no longer a residual: the unwrap answers `형태 미상` for those two
  # primaries and the act is refused before a base is needed. Measured:
  # `nohup git -C <sibling> diff --output=<relative path>` was graded
  # `트리밖쓰기`, honestly, and this function answered "no base" because argv0
  # was `nohup` — so the second base has to be computed after the
  # same unwrap the table applies. The declared residual about a `cd` INSIDE a
  # wrapper's program text is a different shape and still does not cover it.
  #
  # ONLY `git`, AND ONLY BEFORE THE SUBCOMMAND. `make -C` and `--directory=`
  # carry the same mechanism and `tar -C` does too, but `tar` is graded 미상 and
  # refused before this runs, and the other two were not measured. A second base
  # that is wrong refuses acts that were never going to land there, so the list
  # grows when a spelling is measured rather than when one is imagined. A `-C`
  # AFTER the subcommand belongs to the subcommand and is not this option.
  #
  # `--work-tree=` IS TAKEN CONSERVATIVELY. It does not chdir the process, so a
  # relative operand does not always resolve from it; including it can only
  # refuse an act git would have landed elsewhere, never miss one.
  local b
  b=$(gate_argv_chdir_base_of "$@")
  [ -n "$b" ] || return 1
  printf '%s' "$b"
}

gate_argv_chdir_base_of() {
  # gate_argv_chdir_base_of <argv...> — the body of `gate_argv_chdir_base`, with
  # the answer on standard output and nothing there when there is no base.
  # Always rc 0, because the unwrap helpers hand their remainder to a resolver
  # whose output they print through, and a non-zero return from inside a
  # command substitution is what an inherited `set -e` turns into an exit.
  #
  # THE WRAPPERS ARE PEELED WITH THE TABLE'S OWN HELPERS rather than a second
  # list: `gate_unwrap_wrapper`, `gate_unwrap_env`, `gate_unwrap_command`,
  # `gate_unwrap_time`, `gate_unwrap_lockf` and `gate_unwrap_find` each consume
  # exactly the options the table consumes and stop at one they do not know.
  # The parity holds for every name `surface_of_argv0` delegates to an unwrap
  # helper EXCEPT `rg`: `gate_unwrap_rg` hands on the one word after `--pre`, and
  # a single word cannot carry `-C <dir>` and an operand, so it has no base to
  # compute. `lockf` and `find` were missing from this case while the table
  # already delegated them, so `lockf -k -t 0 <lock> git -C <sibling> diff
  # --output=<relative path>` — the lock the unattended skills require around
  # every document write — was graded as the inner `git` and passed both write
  # guards with no second base. `test-run.sh` checks that every name the GRADING
  # TABLE delegates to an unwrap has an arm here, which is a containment in one
  # direction and not a comparison of two sets: a name added to the table turns
  # the suite red, a name added only here is caught by no assertion. The two empty terminal
  # answers mean "no command" and "unknown option" both come back as no base,
  # which is the same discipline the table keeps — a guess about whether an
  # option eats the next word is a guess about where the operands land.
  local argv0="$1" base d
  shift
  case "${argv0##*/}" in
    timeout|nice|nohup|stdbuf)
      gate_unwrap_wrapper "${argv0##*/}" gate_argv_chdir_base_of '' '' "$@"; return 0 ;;
    env)     gate_unwrap_env     gate_argv_chdir_base_of '' '' "$@"; return 0 ;;
    command) gate_unwrap_command gate_argv_chdir_base_of '' '' "$@"; return 0 ;;
    time)    gate_unwrap_time    gate_argv_chdir_base_of '' '' "$@"; return 0 ;;
    lockf)   gate_unwrap_lockf   gate_argv_chdir_base_of '' '' "$@"; return 0 ;;
    find)    gate_unwrap_find    gate_argv_chdir_base_of '' '' "$GATE_FORM_UNKNOWN" gate_answer_first "$@"; return 0 ;;
    git) ;;
    *) return 0 ;;
  esac
  base=$(gate_grade_cwd)
  d=$base
  while [ "$#" -ge 1 ]; do
    case "$1" in
      # `-C` IS CUMULATIVE — git resolves each one against the directory the
      # previous ones already selected, so the fold does too.
      -C) shift; [ "$#" -ge 1 ] || break; d=$(gate_lexical_abs "$1" "$d") ;;
      -C?*) d=$(gate_lexical_abs "${1#-C}" "$d") ;;
      --work-tree=*) d=$(gate_lexical_abs "${1#--work-tree=}" "$d") ;;
      --work-tree) shift; [ "$#" -ge 1 ] || break; d=$(gate_lexical_abs "$1" "$d") ;;
      # `-c <name>=<value>`, `--git-dir <dir>` and `--namespace <name>` take
      # their value as a separate token — the same list `surface_of_git` steps
      # over in two tokens, minus `--work-tree`, which is folded above. Reading
      # that value as the subcommand ended the fold one word early, so
      # `git --namespace x -C <sibling> …` had no base. Every other global
      # option carries its value with `=` or takes none; `--exec-path` and
      # `--config-env` never arrive here because the table refuses them as a
      # form.
      -c|--git-dir|--namespace) [ "$#" -ge 2 ] || break; shift ;;
      -*) ;;
      *) break ;;
    esac
    shift
  done
  [ -n "$d" ] && [ "$d" != "$base" ] || return 0
  printf '%s' "$(gate_path_spelling "$(gate_real_prefix "$d")")"
}

gate_second_base_spelling() {
  # gate_second_base_spelling <word> <second base> — the word resolved against a
  # base that is not the grading directory, or nothing when the word is absolute
  # (a second base cannot move it) or resolves to the same place anyway.
  case "$1" in
    /*) return 1 ;;
  esac
  [ -n "$2" ] || return 1
  local n
  n=$(gate_path_spelling "$(gate_lexical_abs "$1" "$2")")
  [ "$n" != "$(gate_path_spelling "$(gate_lexical_abs "$1")")" ] || return 1
  printf '%s' "$n"
}

gate_leaf_spelling() {
  # gate_leaf_spelling <physical-prefix spelling> — when the path's last
  # component is a symlink, the path it resolves to; otherwise nothing.
  #
  # `gate_real_prefix` folds only the deepest existing DIRECTORY, so a final
  # component that is a link to a FILE stays the link's own name, and
  # `cp e <tmp>/L` wrote through a link to `<root>/orchestrator/gate.sh` past
  # both guards. `gate_physical_path` already follows a final link — relative
  # link text against the link's own directory, `pwd -P` at every step, at
  # most eight hops — so it is reused rather than a third resolver written.
  # `gate_real_prefix` itself is not changed: it also grades every operand,
  # and following links there would move grades outside these two guards.
  #
  # THE HOP LIMIT FAILS CLOSED. `gate_physical_path` stops after eight hops and
  # returns the link it stopped on, and a failing `readlink` leaves the same
  # value — so a chain of nine or more file links came back as an unresolved
  # link NAME, matched no arm in either guard, and the kernel then followed it
  # to the end (32 hops on macOS, 40 on Linux) and performed the write. Measured:
  # a nine-step chain wrote the fixture's `orchestrator/gate.sh` while both
  # guards returned rc 0. So the overflow is reported instead of being spelled
  # away, and the guards refuse — the same disposition the hook's `Write`/`Edit`
  # half already has for its own walk.
  local p
  [ -L "$1" ] || return 0
  p=$(gate_physical_path "$1")
  [ -L "$p" ] && return "$GATE_LEAF_UNRESOLVED"
  gate_path_spelling "$p"
}

gate_halt_name_ok() {
  # gate_halt_name_ok <leaf under halt/> — true when a stage may write that name.
  # A caller with no stage id keeps the one-level allowance; a stage may write
  # its own `<stage-id>.md` and any dot-led temp name of the atomic write.
  [ -n "${CC_PIPELINE_STAGE_ID:-}" ] || return 0
  case "$1" in
    .*) return 0 ;;
  esac
  [ "$1" = "${CC_PIPELINE_STAGE_ID}.md" ]
}

gate_halt_name_refusal() {
  # gate_halt_name_refusal — the refusal text both write guards print for a halt
  # record under another name. `hooks/gate-pretool.sh` builds the same sentence
  # byte for byte and `scripts/test-gate.sh` pins that they agree.
  printf '%s' "the halt record of this stage is halt/${CC_PIPELINE_STAGE_ID}.md and no other name under halt/ — both readers look up that one name, attempt number included, so a record written under another name is never read; write it there"
}

gate_rundir_write_guard() {
  # gate_rundir_write_guard <graded-surface> <argv...>
  #
  # THE HOOK GUARDS THE RUN DIRECTORY AND THE GATE DID NOT, so the same write
  # was refused through `Write`/`Edit` and allowed through `Bash`. The hook lets
  # a stage write exactly two names under the run directory — `halt/<stage-id>.md`
  # and `<segment>.plan.md` — because everything else there is a baseline the
  # gate re-reads on every act. A stage that edits one of those baselines makes
  # the enforcement-surface check re-anchor on the stage's own bytes.
  #
  # An honest `--surface 트리밖쓰기` reached all of it. The worst reachable file
  # is a stage log: the re-dispatch path reads `log/<stage>.json` while the
  # writer pins `log/<stage>#<n>.json`, so a plain-named log placed there is what
  # a re-attach consumes, and the session id it carries is what the resume is
  # spawned with.
  #
  # THE ALLOW-LIST IS COPIED FROM THE HOOK RATHER THAN INVENTED, and the witness
  # scratch directory is the one addition — team members publish round products
  # there and the hook never saw those writes because they do not go through
  # `Write`. The same exception is added to the hook in this change, so the two
  # lists still say the same thing; `scripts/test-gate.sh` pins that they agree.
  #
  # THE WITNESS EXCEPTION NAMES WHAT IS ACTUALLY MINTED. `cc-team-witness-init.sh`
  # creates `cc-team-witness-<slug>[.<stage-id>].XXXXXX` DIRECTLY under the run
  # root, so a published product's relative path is `cc-team-witness-…/<file>`.
  # An exception spelled `witness/` or `team-witness/` matches none of that and
  # falls through to the `*/*` refusal — and nothing in this tree creates either
  # of those two names, so such an exception is not a wider allow-list, it is a
  # dead one. With it the unattended run's team stages are refused outright:
  # publishing a witness is `mv -n` into that directory, a lead that cannot
  # publish cannot observe, and a lead that cannot observe either parks forever
  # or synthesizes a round product it never saw.
  #
  # WHAT THIS DOES NOT DO. It matches the run directory by path, after
  # resolving a symlinked ancestor and a symlinked final component (eight hops
  # at most). A path built by a `cd` inside a wrapper, and a link swapped
  # between this check and the act running, are not seen — the same residual
  # the manifest guard states, and closed by the same thing: the
  # enforcement-surface digest is compared at the next entry.
  local graded="$1"; shift
  [ "$#" -ge 1 ] || return 0
  [ -n "${RUN_DIR:-}" ] || return 0
  case "$graded" in
    읽기) return 0 ;;
  esac
  # BOTH SPELLINGS OF THE RUN DIRECTORY ARE NEEDED, and taking only the physical
  # one is what made the first version of this guard refuse nothing at all on
  # this platform. `pwd -P` resolves `/var` to `/private/var` while the argv the
  # act carries says `/var`, so a prefix test against the physical spelling alone
  # matches none of the paths it exists to catch. Both are compared and neither
  # is preferred: an act may name either, and a guard that knows one spelling is
  # a guard the other spelling walks past.
  #
  # A SIBLING RUN'S DIRECTORY IS REFUSED BEFORE THIS RUN'S IS TESTED. The hook
  # already refuses both — it compares against the state root and not against one
  # run — while this guard only ever knew its own `RUN_DIR`, so the same write
  # was denied through `Write` and allowed through `Bash` whenever the target
  # belonged to another run. Measured: `cp` into a sibling's `settings/` returned
  # rc 0 here and `deny` from the hook. Pinning makes that gap worth closing
  # rather than merely inconsistent, because it puts executable code — the copy
  # every call of that run hops into — at a path under the sibling's directory.
  # There is no legitimate case: a stage writing into a run that is not its own
  # is either confused or hostile, and the refusal text says so.
  #
  # ARGV0 NAMES WHAT RUNS, NOT WHAT IS WRITTEN, and conflating the two closed the
  # run to its own pinned code. Pinning puts the copy every call hops into at
  # `<RUN_DIR>/plugin/cc-cmds/`, so a stage invoking one of those scripts by its
  # documented path hands this loop an argv0 under the run directory. It matches
  # no allow-list branch — `plugin/…` falls to `*/*` — and the act is refused
  # although nothing is written there. Measured: an unattended design stage was
  # refused at `cc-team-witness-init.sh`, spawned no team member, and the run
  # closed with all five termination clauses settled impossible. The allow-list
  # loses no coverage by skipping this element: a file is not written by being
  # executed, and where such a script does write under the run directory it
  # computes that path internally, which this loop never saw for any argv0.
  #
  # THE FOREIGN-RUN REFUSAL STILL READS ARGV0, deliberately: running a sibling
  # run's pinned copy is the confusion that check exists to name, and it is the
  # one judgment about argv0 that does not rest on it being a write target. So
  # argv0 is carried as far as that check and dropped immediately after it.
  #
  # THE ARGUMENT IS NORMALIZED BEFORE ANY COMPARISON, and folding separators was
  # not enough for it. `gate_path_spelling` collapses `//` and `/./` and stops
  # there — it does not rewind `..` and it does not absolutize — so two spellings
  # walked past every prefix test below: `<이 런>/cc-team-witness-x/../plugin/…`
  # was allowed by the witness exception it re-entered through, and a relative
  # path matched no arm at all because none of them are relative. `gate_lexical_abs`
  # answers both without touching the filesystem, which is what a guard over
  # not-yet-created destinations needs.
  # THE ARGUMENT IS ALSO RESOLVED PHYSICALLY, because every comparison below is
  # lexical and a symlinked ancestor defeats all of them at once. An argument
  # reaching a run directory through `ln -s <run root> /tmp/L` carries no `..`,
  # is not relative, is already in lexical normal form, and SHARES NO SUBSTRING
  # with either root — so the four prefix arms and the buried-path arm below all
  # miss it and the write lands. The hook's `Write`/`Edit` half carries a
  # device+inode layer for this vector; this is the Bash half, and it closes
  # less than that layer: a symlinked ancestor and a symlinked final component
  # are resolved, a path assembled by a `cd` inside a wrapper and a link
  # changed between this check and the act are not. `gate_real_prefix` is the
  # ancestor resolver rather than `gate_physical_path` for the reason that
  # function states: the destination of an `mv` normally does not exist yet,
  # and a resolver that needs it to exist returns the input unchanged, which
  # makes a prefix test miss rather than answer differently. The final
  # component is then followed by `gate_leaf_spelling` only when it is a link.
  # One `cd`+`pwd -P` per candidate argument, and per `/`-bearing word of a
  # compound token.
  #
  # BOTH SPELLINGS ARE CLASSIFIED AND A REFUSAL FROM EITHER WINS. Taking only the
  # physical one re-opens the `/var` gap the two run-directory spellings exist to
  # close, and taking only the lexical one is today's hole.
  #
  # `..` IS FOLDED BEFORE THE ALLOW-LIST IS CONSULTED, and folding only the
  # separators was a hole the shared-generation arm turned into a write. The
  # relative path the arms match is taken from the folded absolute spelling —
  # the same lexical fold the hook applies and `gate_shard_exec_guard` already
  # uses — because bash `case`'s `*` matches `/` and `..` alike, so an unfolded
  # `shared/../surface-digest` satisfies `shared/*/*` while naming a file the
  # gate re-reads on every act. `rundir_init` creates `shared/` on every run, so
  # that spelling always resolves in the kernel; the hook folds `..` before it
  # judges, which left `Write` refusing exactly the path `Bash` allowed. A
  # relative argument is absolutized against the grading directory for the same
  # reason: `../../.local/state/…/run/<id>/surface-digest` from the worktree is
  # one more spelling of the same file.
  local a rdp rdn rdln an ap al ar sp rel root rootp r matched argi w wn wp wl i
  local ov ovrc wraps mode cb ov2 ovw wn2 wp2 wl2 an2 ap2 al2
  argi=0
  rdp=$(cd "$RUN_DIR" 2>/dev/null && pwd -P) || rdp="$RUN_DIR"
  [ -n "$rdp" ] || rdp="$RUN_DIR"
  rdn=$(gate_lexical_abs "$rdp")
  rdln=$(gate_lexical_abs "$RUN_DIR")
  root=$(gate_lexical_abs "$(gate_reap_root)/run")
  rootp=$(cd "$(gate_reap_root)/run" 2>/dev/null && pwd -P) || rootp=""
  if [ -n "$rootp" ]; then rootp=$(gate_lexical_abs "$rootp"); fi
  wraps=0
  if gate_argv0_wraps "$1"; then wraps=1; fi
  # THE DIRECTORY THE COMMAND ITSELF RESOLVES FROM, when it is not this one.
  # `gate_argv_chdir_base` states the defect; every relative option value and
  # word below is measured from this base as well as from the grading one.
  cb=$(gate_argv_chdir_base "$@") || cb=""
  # "THE BASE CANNOT BE COMPUTED" IS NOT "THERE IS NO BASE". Both arrived here as
  # the empty string, and empty is the allowing direction — so a shape the unwrap
  # could not read passed this guard for the same reason a plain `cp` does. The
  # unwrap now answers `형태 미상` for those, and it is refused rather than
  # treated as an absent base. The `exec` path refuses this argv one step earlier
  # on the grade, so what this arm covers is a caller whose grade came from
  # elsewhere and a fixture that calls the guard directly.
  if [ "$cb" = "$GATE_FORM_UNKNOWN" ]; then
    warn "rule refused: this shape runs its inner command from a directory the gate cannot name — each match's own directory rather than this one — so where a relative destination inside it lands cannot be judged. Respell it with \`-exec\` and an absolute destination: $1"
    return "$GATE_EXIT_RULE"
  fi
  argi=0
  for a in "$@"; do
    argi=$((argi + 1))
    # A BARE ARGV0 IS A COMMAND NAME looked up in `PATH`, not a path, and is not
    # resolved. A bare later element is resolved by `gate_arg_bare_name`, which
    # is what carries `.`, `..` and an existing name into the ancestor arm.
    #
    # A COMPOUND TOKEN IS NOT A NAME, AND ASKING WHETHER IT IS ONE DROPPED IT.
    # `gate_arg_bare_name "rm -rf .."` tests `[ -e "<cwd>/rm -rf .." ]`, which is
    # false, so a program string carrying no `/` at all was skipped before the
    # word arm ever saw it — `bash -c "rm -rf .."` and `bash -c "cp -R x .."`
    # from a segment worktree beside the installed checkout, and `bash -c
    # "rm -rf ."` from inside a run, all passed both guards while the same
    # program with one `/` anywhere in it was refused. Compoundness is asked
    # FIRST so those tokens reach the word arm; the whole-path arms below
    # already exclude a compound token by `! gate_arg_is_compound`.
    case "$a" in
      */*|"$RUN_DIR"|"$rdp") ;;
      *) if [ "$argi" = 1 ]; then continue; fi
         # A bare name is also looked up in the second base: a name that exists
         # only in the `-C` directory is one the command will find there.
         gate_arg_is_compound "$a" || gate_arg_bare_name "$a" \
           || { [ -n "$cb" ] && gate_arg_bare_name "$a" "$cb"; } || continue ;;
    esac
    an=$(gate_path_spelling "$(gate_lexical_abs "$a")")
    ap=$(gate_path_spelling "$(gate_real_prefix "$an")")
    al=$(gate_leaf_spelling "$ap") || { gate_leaf_unresolved_refuse "$a"; return "$GATE_EXIT_RULE"; }
    # THE WHOLE-PATH ARGUMENT FROM THE SECOND BASE TOO. The three spellings above
    # absolutize against the grading directory only, and `gate_second_base_spelling`
    # was applied to an option's `=`-value and to the words of a compound token
    # and nowhere else — so `git -C <sibling> diff --output <relative>` (two
    # tokens), `archive -o <relative> HEAD` and `checkout HEAD -- <relative>`
    # carried the very path the `=` spelling was refused for, as a plain
    # argument, past every arm. The guard has no option table, so it cannot tell
    # `--output`'s operand from a pathspec; it does not need to — both are
    # resolved by git from the `-C` directory, and both are measured from it
    # here. A compound token is not a path and gets no second spelling of its
    # own; its words already do. An absolute argument, and one that resolves to
    # the same place from either base, come back empty and add nothing. argv0
    # names what runs and is looked up in `PATH`, not in the `-C` directory.
    an2=""; ap2=""; al2=""
    if [ "$argi" != 1 ] && ! gate_arg_is_compound "$a"; then
      an2=$(gate_second_base_spelling "$a" "$cb") || an2=""
      if [ -n "$an2" ]; then
        ap2=$(gate_path_spelling "$(gate_real_prefix "$an2")")
        al2=$(gate_leaf_spelling "$ap2") || { gate_leaf_unresolved_refuse "$a"; return "$GATE_EXIT_RULE"; }
      fi
    fi
    # OWN IS STILL TESTED FIRST, AND IT IS TESTED PER SPELLING. Deciding "is this
    # mine" from the lexical spelling and "is this a sibling's" from the physical
    # one would read a symlink pointing at THIS run as a foreign run, so each
    # spelling goes through the whole predicate and keeps its own exemption.
    for sp in "$an" "$ap" "$al" "$an2" "$ap2" "$al2"; do
      [ -n "$sp" ] || continue
      if gate_rundir_is_foreign_run "$sp" "$root" "$rootp" "$rdn" "$rdln"; then
        warn "rule refused: this is another run directory — there is no legitimate case for a stage writing into the directory of a run that is not its own (the pinned copy and the baseline of that run sit there): $a"
        return "$GATE_EXIT_RULE"
      fi
    done
    # ARGV0 IS DROPPED HERE, one arm after the foreign-run check and before every
    # arm that treats the argument as a destination. The preamble states why the
    # two judgments split at exactly this line.
    [ "$argi" = 1 ] && continue
    # AN OPTION VALUE IS ONE PATH (`gate_arg_option_value`), and an ancestor of
    # the run root named there is the same destination as one named whole.
    if ov=$(gate_arg_option_value "$a"); then
      # AND FROM THE DIRECTORY THE COMMAND WILL ACTUALLY RESOLVE IT FROM. The
      # second spelling is already absolute, so the resolver inside leaves it
      # alone and no second resolver is needed.
      ov2=$(gate_second_base_spelling "$ov" "$cb") || ov2=""
      for ovw in "$ov" "$ov2"; do
        [ -n "$ovw" ] || continue
        gate_word_is_at_or_above "$ovw" "$root" "$rootp"; ovrc=$?
        if [ "$ovrc" = 0 ]; then
          warn "rule refused: the option value is an ancestor directory of the run root — a verb that takes a directory as its destination creates or merges the source's own name underneath it, so it reaches the whole run root: $a"
          return "$GATE_EXIT_RULE"
        fi
        if [ "$ovrc" = "$GATE_LEAF_UNRESOLVED" ]; then
          gate_leaf_unresolved_refuse "$a"
          return "$GATE_EXIT_RULE"
        fi
      done
    fi
    matched=0
    # ONLY A WHOLE-PATH ARGUMENT IS CLASSIFIED AGAINST THE ALLOW-LIST, for the
    # reason the ancestor arm below gives: a compound token's lexical
    # normalization is a rewound STRING rather than a path, so `<run dir>/rm -rf
    # ..` would be read as a file named `rm -rf ..` under the run directory and
    # refused for not being on the allow-list. That refusal names the wrong arm
    # even where the act should be refused, and where it should not — a write
    # graded from inside a run directory carrying any compound token without a
    # `/` — it is a plain over-refusal. The paths INSIDE the token are not exempt
    # for that: the option value is tested above and the words below.
    if ! gate_arg_is_compound "$a"; then
    for sp in "$an" "$ap" "$al" "$an2" "$ap2" "$al2"; do
      [ -n "$sp" ] || continue
      rel=""
      case "$sp" in
        "$rdn") rel="." ;;
        "$rdn"/*) rel=${sp#"$rdn"/} ;;
        "$rdln") rel="." ;;
        "$rdln"/*) rel=${sp#"$rdln"/} ;;
        # NEITHER SPELLING MATCHES AS TEXT, WHICH IS NOT THE SAME AS NAMING
        # NOTHING HERE. A case variant of this run's own directory is the same
        # directory on this filesystem, so the relative tail is taken from the
        # ancestor that compared equal by device+inode rather than from a
        # spelling. When there is no such ancestor the argument really does name
        # nothing under a run directory; the other spelling may still, so it
        # falls through to the buried-path arm.
        *)
          case "$sp" in /*) ;; *) continue ;; esac
          gate_path_ident_prefix "$sp" "$rdp" || continue
          if [ "$sp" = "$GATE_IDENT_PREFIX" ]; then
            rel="."
          else
            rel=${sp#"$GATE_IDENT_PREFIX"/}
          fi ;;
      esac
      matched=1
      # THE RUN DIRECTORY ITSELF IS A DESTINATION, AND IT IS REFUSED. `rel` is `.`
      # when the argument names the run directory and nothing under it, and
      # letting that through was the whole of the hole: a verb whose destination
      # is a DIRECTORY takes the created name from the source's basename, so the
      # name never appears in the argv this guard inspects.
      # `mv /tmp/plugin "$RUN_DIR"` and `mv /tmp/plugin-pin "$RUN_DIR"` plant both
      # halves of a pin that way, and the confinement check downstream asks only
      # where the pin POINTS, never who wrote it. `Write`/`Edit` cannot name a
      # directory as a destination, so this form exists only through Bash and
      # this guard is its only layer.
      #
      # NO EXEMPTION IS CARVED FOR THE NON-DESTINATION USES, and that is a
      # decision rather than an oversight. A guard cannot tell
      # `mv x "$RUN_DIR"` from `cd "$RUN_DIR"` — the argv is the same — so an
      # exemption for the second is a re-entry for the first. Every legitimate
      # write already passes by naming its own destination: `halt/<stage-id>.md`,
      # a witness publication, and `<segment>.plan.md` are all spelled as paths
      # of their own.
      #
      # RESIDUAL, in the same shape the buried-path arm below states: a non-read
      # act that merely NAMES the run directory without writing there is refused
      # too. The way through is to spell the destination as its own argument or
      # to declare the read it is.
      #
      # `rel=''` is unreachable today — `gate_lexical_abs` drops the empty last
      # segment a trailing slash makes, so `an` is never `"$rdn"/` — and it is
      # refused beside `.` anyway, because splitting them lets an empty string
      # pass quietly on the day that normalization changes.
      case "$rel" in
        halt/*/*) ;;
        # A STAGE WRITES ONE HALT RECORD NAME, the one its own id spells. Both
        # readers look the record up by the id the launcher handed down, attempt
        # number included, so a record a stage named by its segment alone was
        # never read: measured, a stage of attempt 4 wrote `halt/S2.md`, both
        # readers classified the turn `정상 완료`, and the question it carried
        # waited for a person. The guard names the one allowed path, so the stage
        # writes it next. A name that begins with a dot is the same-directory temp
        # file of the atomic write and passes. A caller with no stage id — the
        # seat, a shift — keeps the old one-level allowance.
        halt/*)
          gate_halt_name_ok "${rel#halt/}" && continue
          warn "rule refused: $(gate_halt_name_refusal)"
          return "$GATE_EXIT_RULE" ;;
        cc-team-witness-*/*) continue ;;
        # THE WITNESS DIRECTORY ITSELF, for its teardown. The shared team-cleanup
        # procedure ends a finished workflow with `rm -rf` on the recorded
        # `scratchDir`, which names the directory and nothing under it, so the
        # arm above never saw it. Measured: a design stage's teardown came back 3
        # here and left two dozen witness copies and the ledger's scratch fields
        # behind. Only Bash can name a directory as an operand, so the Write/Edit
        # hook needs no twin of this arm. It opens the name to `rm` alone: any
        # other verb that names the directory creates it, and that creation stays
        # refused here, as it always was.
        cc-team-witness-*) [ "${1##*/}" = rm ] && continue ;;
        # THE SHARED GENERATION DIRECTORY, ONE LEVEL DOWN ONLY. Shifts publish
        # their products under `shared/<gen>/`; a file sitting directly under
        # `shared/` has no generation and falls through to the `*/*` refusal.
        shared/*/*) continue ;;
        # THE UNATTENDED DESIGN STAGE'S STATE ROOT AND PRE-IMAGES. The skill
        # declares both as paths it writes, and this list did not know them — so
        # the stage stopped before spawning a single team member. It stops THERE
        # rather than mid-discussion because a walkthrough resolution needs an undo
        # to be adoptable at all, and the undo is restored from the pre-image.
        #
        # Safe on the witness exception's own terms: neither exists when the run
        # opens, so neither is a baseline the gate re-reads on every act, and
        # neither is read by the enforcement-surface check. Depth is deliberately
        # unrestricted — the state root carries a `witness/` directory one level
        # further down — which is why these branches are not spelled like `halt/*`.
        design|design/*|preimage|preimage/*) continue ;;
        # THE BASE SPLIT STAGE'S PLAN DIRECTORY. `base-split.py plan --out
        # <run dir>/split/<stage id>/` writes the body files and the argv list
        # there, and the stage's tracker writes name those body files. The
        # directory itself is listed as well as what lies under it: the trailing
        # `/` of `--out` is stripped before this comparison, so `split/<id>`
        # alone would otherwise meet the refusal below. Safe on the witness
        # exception's terms — absent when the run opens, read by no
        # enforcement-surface check.
        split|split/*) continue ;;
        # THE CARRY-OVER BODY FILES, ONE LEVEL DOWN ONLY. `gate.sh carry-body`
        # writes them and the routing shift names one as the `--body-file` of
        # `gh issue create`, an act that names a path under this directory and
        # would meet the refusal below. Safe on the witness exception's terms —
        # absent when the run opens, read by no enforcement-surface check. The
        # run hook has no twin of this arm because no session writes here with
        # the file-edit tool: the gate does.
        carry/*/*) ;;
        carry/*) continue ;;
        # `mkdir -p` names the directories it creates, so `halt` itself appears as
        # an argument. Allowing the directory opens nothing beyond `halt/*`, which
        # is already allowed, and `halt/*/*` is refused above.
        halt) continue ;;
        # THE DESIGN DOCUMENT LOCK. Every stage that edits the design document —
        # the implementation arm's token writes, the audit's reconciliation pass
        # and the re-convergence pass — wraps the write in `lockf -k -t 0
        # "$RUN_DIR/designdoc.lock"`, and this list did not know the name, so a
        # re-convergence stage stopped at the lock before its one edit. Measured:
        # the stage halted `gate-unanswerable` with its edit prepared and unapplied.
        # Safe on the witness exception's terms: the file does not exist when the
        # run opens, the enforcement-surface digest does not read it, and `lockf
        # -k` leaves it empty. The exact name only — nothing beneath it.
        designdoc.lock) continue ;;
        */*) ;;
        *.plan.md) continue ;;
      esac
      warn "rule refused: run directory write — the only paths a stage is declared to write are halt/<stage-id>.md and <segment>.plan.md (the witness directory cc-team-witness-*/ and the shared generation directory shared/<gen>/ excepted; a file directly under shared/ is not). The rest are the baseline the gate re-reads on every act, so writing here re-baselines the enforcement-surface check against itself: $a"
      return "$GATE_EXIT_RULE"
    done
    fi
    if [ "$matched" = 1 ]; then continue; fi
    # AN ANCESTOR OF THE RUN ROOT IS A DESTINATION TOO. Every arm above is
    # anchored at a run directory, so the directories ABOVE the run root matched
    # none of them — and a verb whose destination is a directory creates or
    # merges the source's basename under it: macOS `cp -R <evil>/run
    # <state>/cc-cmds` merges into every run at once, and `rm -rf <state>` takes
    # them all. The test is "the run root is at or below this path".
    #
    # ONLY A WHOLE-PATH ARGUMENT HERE. A compound token's lexical normalization
    # is a rewound string rather than a path, and a string that happens to
    # rewind to `/` or to the grading directory would be refused for naming
    # nothing. The paths INSIDE a compound token are not exempt for that: an
    # option value is tested at the top of this loop and the words of an
    # interpreter program in the word arm below, each resolved as the shell
    # resolves it. `.`, `..` and an existing bare name arrive here too
    # (`gate_arg_bare_name`), so `rm -rf ..` from inside a run is refused.
    #
    # RESIDUAL, in the safe direction: in a pinned run the run directory and its
    # ancestors cannot be named whole by a write-graded act either.
    if ! gate_arg_is_compound "$a"; then
      for r in "$root" "$rootp"; do
        [ -n "$r" ] || continue
        for sp in "$an" "$ap" "$al" "$an2" "$ap2" "$al2"; do
          [ -n "$sp" ] || continue
          if gate_path_is_at_or_above "$sp" "$r"; then
            warn "rule refused: an ancestor directory of the run root is named as a write destination — a verb that takes a directory as its destination creates or merges the source's own name underneath it, so it reaches the whole run root: $a"
            return "$GATE_EXIT_RULE"
          fi
        done
      done
    fi
    # THE PATH THAT IS NOT AN ARGUMENT OF ITS OWN. Every arm above is a prefix
    # test on a WHOLE argument, so a run directory carried inside a larger token
    # walks past all of them: `git diff --output=<피해자>/…` spells the path
    # behind an option token, and `bash -c '… > <피해자>/…'` hands the whole
    # program text as one argument. Both are graded as writes and both reach the
    # file. Reading the command line as the operand is how the CLAUDE.md slot
    # guard and arm 2 of the manifest guard already treat a wrapper; this guard
    # was the one that followed neither.
    #
    # ONLY AFTER THE PREFIX ARMS, and the order carries the weight. Ahead of them
    # this would refuse this run's own `halt/<stage-id>.md`, `<segment>.plan.md`
    # and witness publications, which are spelled as plain paths under the run
    # root and are exactly what those exceptions allow.
    #
    # RESIDUAL, and it fails in the safe direction: a non-read act that merely
    # MENTIONS a run directory without writing there — a commit message quoting
    # the path — is refused as well. Passing the path as its own argument, or
    # dropping the wrapper, is the way through.
    #
    # THE ARGUMENT AS WRITTEN IS SEARCHED TOO. `an` has already rewound every
    # `..` in the token, and a trailing `; : /../../../..` in a program string
    # rewinds the run root out of it; `ar` folds separators only, so the root
    # it carries is still there to find. It is searched here and nowhere else:
    # as a PREFIX spelling it would let `<이 런>/cc-team-witness-x/../plugin/…`
    # back in through the witness exception.
    ar=$(gate_path_spelling "$a")
    for r in "$root" "$rootp"; do
      [ -n "$r" ] || continue
      for sp in "$an" "$ap" "$al" "$ar" "$an2" "$ap2" "$al2"; do
        [ -n "$sp" ] || continue
        case "$sp" in
          *"$r"*)
            warn "rule refused: a run directory path is buried inside an argument — a path carried inside an option token or an interpreter program string is invisible to a prefix test, so the whole argument is refused. Pass the path as its own argument and drop the wrapper: $a"
            return "$GATE_EXIT_RULE" ;;
        esac
      done
    done
    # A COMPOUND TOKEN IS JUDGED WORD BY WORD, because a path the shell resolves
    # RELATIVE to the grading directory never spells the run root at all:
    # `bash -c "cp e run/victim/settings/x.json"` graded from the run root's
    # parent, where neither the token's lexical normalization nor the token as
    # written carries a run root spelling. `gate_arg_words` gives each word
    # with a `/` and each is resolved the way the shell will — lexically,
    # physically, and through a final link. A word at or under the run root is
    # refused with the buried-path text. This run's own exceptions are not given
    # to words, the same rule the buried arm above applies to a wrapped path of
    # this run.
    #
    # WORDS, NOT A TAIL MATCH ON THE ROOT'S NAME AND NOT A BAN ON `..`. A tail
    # match refuses every text that merely names such a path relative to a
    # directory where it is an ordinary file; a `..` ban misses a relative
    # spelling that needs no `..` from where the act runs. Resolving the word
    # answers both the way the shell does.
    #
    # AN INTERPRETER'S WORDS ARE ALSO TESTED AS ANCESTORS. `bash -c "cp -R
    # <evil> <state>/cc-cmds"` names no path at or under the run root, and the
    # ancestor arm above takes whole-path arguments only, so it passed. For an
    # interpreter or wrapper argv0 (`gate_argv0_wraps`) every word — `/`-less
    # `.`, `..` and existing names included — is tested against the run root,
    # and a word that resolves to `/` alone is refused with the rest: the
    # program text is what the shell runs, so its words are destinations. The
    # words of any other compound token are not, because there they are text —
    # `git commit -m "a / b"` names nothing — and the price of that line is
    # that a non-interpreter token carrying an ancestor as a list element
    # (`:`- or `,`-joined) is not refused by this arm.
    #
    # RESIDUAL, stated rather than hidden: a `cd` inside the wrapper, variable
    # expansion other than `$HOME`, command substitution, concatenation and
    # globs are not interpreted — that needs a shell parser. This closes paths
    # written LITERALLY; the rest is left to the grading table ranking
    # `bash -c` as a write and to the stage convention of not wrapping external
    # commands in `bash -c`. In the safe direction, an interpreter program that
    # merely mentions an ancestor of the run root — `$HOME`, `/` — is refused
    # under a write grade; a read needs no wrapper to be declared as one.
    if gate_arg_is_compound "$a"; then
      mode=""
      if [ "$wraps" = 1 ]; then mode=bare; fi
      gate_arg_words "$a" "$mode" \
        || { gate_word_unresolved_refuse "$a"; return "$GATE_EXIT_RULE"; }
      i=0
      while [ "$i" -lt "${#GATE_ARG_WORDS[@]}" ]; do
        w=${GATE_ARG_WORDS[$i]}; i=$((i + 1))
        wn=$(gate_path_spelling "$(gate_lexical_abs "$w")")
        wp=$(gate_path_spelling "$(gate_real_prefix "$wn")")
        wl=$(gate_leaf_spelling "$wp") || { gate_leaf_unresolved_refuse "$a"; return "$GATE_EXIT_RULE"; }
        # The same word from the directory the command resolves it from, when
        # that is a different one — `--output=<relative>` after a `git -C`
        # arrives here as a word.
        wn2=$(gate_second_base_spelling "$w" "$cb") || wn2=""
        wp2=""; wl2=""
        if [ -n "$wn2" ]; then
          wp2=$(gate_path_spelling "$(gate_real_prefix "$wn2")")
          wl2=$(gate_leaf_spelling "$wp2") || { gate_leaf_unresolved_refuse "$a"; return "$GATE_EXIT_RULE"; }
        fi
        for r in "$root" "$rootp"; do
          [ -n "$r" ] || continue
          for sp in "$wn" "$wp" "$wl" "$wn2" "$wp2" "$wl2"; do
            [ -n "$sp" ] || continue
            if gate_path_is_at_or_under "$sp" "$r"; then
              warn "rule refused: a run directory path is buried inside an argument — a path carried inside an option token or an interpreter program string is invisible to a prefix test, so the whole argument is refused. Pass the path as its own argument and drop the wrapper: $a"
              return "$GATE_EXIT_RULE"
            fi
            if [ "$wraps" = 1 ] && gate_path_is_at_or_above "$sp" "$r"; then
              warn "rule refused: a path inside the interpreter program string is an ancestor directory of the run root — a verb that takes a directory as its destination creates or merges the source's own name underneath it, so it reaches the whole run root. Drop the wrapper and pass the destination as its own argument: $a"
              return "$GATE_EXIT_RULE"
            fi
          done
        done
      done
    fi
  done
  return 0
}

gate__surface_words() {
  # Inside `gate_es`: `<argument>\t<class>` for every argument the classifier
  # names — as written, with a leading `/` when relative, and the value after
  # an option's `=`.
  local w c cls
  for w in "$@"; do
    [ -n "$w" ] || continue
    for c in "$w" "${w#*=}"; do
      [ -n "$c" ] || continue
      if cls=$(es_class "$c") || { case "$c" in /*) false ;; *) cls=$(es_class "/$c") ;; esac; }; then
        printf '%s\t%s\n' "$c" "$cls"
        break
      fi
    done
  done
}

gate_surface_write_guard() {
  # gate_surface_write_guard <graded-surface> <argv...> — refuse a stage's write
  # act that names an enforcement-surface path, and point it at the seat apply.
  #
  # A SIGNPOST, NOT THE CLOSURE. Every comparison here is on argv strings, so a
  # script whose body writes a classified path, an interpreter that builds the
  # name, and `git checkout <rev> -- <path>` spelled through a variable all pass.
  # What closes the gap is the provenance check on the segment branch at the
  # merge; what this buys is that the common spelling — a stage `cp` or `git
  # add` of a rule file — learns at once where the edit belongs instead of at
  # the merge, a cycle later.
  #
  # ONLY A STAGE IS REFUSED, AND ONLY A WRITE. The seat and the router are not
  # touched, and a read returns early as the sibling guards do.
  #
  # ONE ARGUMENT IS ONE PATH, AND AN ARGUMENT WITH BLANKS IS NOT ONE. A commit
  # message or a PR body naming `plugins/cc-cmds/orchestrator/rules/` is text
  # about the file, and splitting it into words refused the commit that only
  # described an edit. An interpreter's program text is skipped for the same
  # reason, which is the residual the closure above covers.
  #
  # THE UNTRACKED CLAUDE.md SLOT IS THE ONE EXCEPTION. A `CLAUDE.md` the
  # segment worktree's HEAD does not track — a machine-global slot, or one the
  # target ignores — cannot be committed, so the seat apply cannot carry it; it
  # stays with the CLAUDE.md slot guard and the `리뷰-후-적용` rule. A tracked one
  # is refused like any other path, because written by exec it is refused at the
  # merge anyway.
  local graded="$1"; shift
  [ "$#" -ge 1 ] || return 0
  [ "$graded" = "읽기" ] && return 0
  cc_caller_is_stage || return 0
  shift   # argv0 is the program; running a classified script is not writing it
  [ "$#" -ge 1 ] || return 0
  local a hits rc=0 tok cls ab wt wtp rel trk refused=''
  local cands=()
  for a in "$@"; do
    case "$a" in *[[:space:]]*) continue ;; esac
    cands+=("$a")
    case "$a" in
      */*)
        ab=$(gate_physical_path "$(gate_lexical_abs "$a")" 2>/dev/null) || ab=''
        [ -n "$ab" ] && [ "$ab" != "$a" ] && cands+=("$ab") ;;
    esac
  done
  [ "${#cands[@]}" -ge 1 ] || return 0
  hits=$(gate_es gate__surface_words "${cands[@]}") || rc=$?
  if [ "$rc" = 2 ]; then
    warn "rule refused: the enforcement-surface classifier could not be loaded, so whether this write names a rule file, a CLAUDE.md or a settings file cannot be judged"
    return "$GATE_EXIT_RULE"
  fi
  [ -n "$hits" ] || return 0
  wt=$(gate_segment_worktree "${CC_PIPELINE_SEGMENT:-}" 2>/dev/null) || wt=''
  wtp=''
  [ -n "$wt" ] && [ -d "$wt" ] && wtp=$(cd -P "$wt" 2>/dev/null && pwd -P) || wtp=''
  while IFS=$'\t' read -r tok cls; do
    [ -n "$tok" ] || continue
    if [ "$cls" = "지침파일" ]; then
      ab=$(gate_physical_path "$(gate_lexical_abs "$tok")" 2>/dev/null) || ab=''
      [ -n "$ab" ] || ab=$(gate_lexical_abs "$tok")
      trk=''
      if [ -n "$wtp" ]; then
        case "$ab" in
          "$wtp"/*)
            rel=${ab#"$wtp"/}
            trk=$(cd "$wt" && GIT_LITERAL_PATHSPECS=1 git ls-tree --full-tree --name-only HEAD -- "$rel" 2>/dev/null) || trk='' ;;
        esac
      fi
      [ -n "$trk" ] || continue
    fi
    refused="$refused${refused:+, }$tok ($cls)"
  done <<EOF
$hits
EOF
  [ -n "$refused" ] || return 0
  warn "rule refused: a stage does not write an enforcement surface through exec — $refused. Write the bytes into a \`Step 3 강제 표면 좌석 적용\` halt record instead: a person approves it at the seat, and the gate commits it to the segment branch as a seat commit"
  warn "an edit outside the segment's declared files is a CFI-U3 BT-STOP, not this record; a file the seat cannot commit goes into the same record's \`**사람 몫 파일**\`"
  return "$GATE_EXIT_RULE"
}

gate_plugin_root_write_guard() {
  # gate_plugin_root_write_guard <graded-surface> <argv...>
  #
  # PINNING FREEZES THE BYTES A RUN *ENDS* ON, NOT THE ONES IT *STARTS* ON. Every
  # entry — the seat's call, the watcher, the feed, and any call of a run that is
  # not pinned — runs the SHARED checkout's `orchestrator/gate.sh` first, reads
  # that whole file and walks its argument loop, and only then reaches the hop.
  # Whoever controls those bytes controls every gate entry on the host, pinned
  # runs included, from above the hop. Recording a version digest on the `run`
  # row without this makes that worse rather than better: a reader who checks the
  # pin sees an integrity the executing bytes do not have.
  #
  # THE PERMISSION LAYER DOES NOT COVER IT. The plugin root is the first element
  # of the extra directories every settings variant grants, and when the target
  # of the run is this repository the checkout is inside the base worktree
  # anyway. So the refusal has to be a guard, and this is the Bash half of it.
  #
  # THE SEGMENT WORKTREE IS NOT THIS ROOT, and that negative control is the
  # safety condition of the whole guard: a run implementing a change to these
  # very files edits them in its own worktree, whose path shares no prefix with
  # the installed root. Without that distinction every implementation stage in
  # this repository would be unable to do its work.
  #
  # RUNNING ONE OF THESE FILES DIRECTLY IS EXEMPT; NAMING ONE IS NOT. argv0
  # spelled as `<root>/orchestrator/<file>` is skipped (`gate_argv0_is_plugin_exec`
  # states the exact shape), because the skills prescribe running
  # `cc-team-witness-init.sh` that way and the grading table pins that helper
  # to a write grade no declaration can lower. RESIDUAL, in the safe
  # direction: an interpreter-wrapped run (`bash <root>/orchestrator/x`) and a
  # path named as any later operand are still refused, because there the
  # argument looks the same as a write destination.
  local graded="$1"; shift
  [ "$#" -ge 1 ] || return 0
  case "$graded" in
    읽기) return 0 ;;
  esac
  # TWO ROOTS, BECAUSE A PINNED CALL IS NOT RUNNING FROM THE INSTALLED ONE. The
  # pin's `source` field is the physical path of the directory the run was opened
  # from, which is precisely the installed root a pinned call can no longer see
  # from `GATE_DIR`. Both spellings of each are kept for the reason the run
  # directory guard keeps both: `/var` is a symlink on this platform and an act
  # may name either.
  # THE ARGUMENT IS RESOLVED PHYSICALLY AS WELL, for the reason the run directory
  # guard states at the same place: every comparison here is lexical, `pwd -P` is
  # applied to the ROOTS and never to the argument, and an argument reaching this
  # root through a symlinked ancestor shares no substring with either spelling of
  # either root. The hook's `Write`/`Edit` half has a device+inode layer for that
  # vector; this Bash half resolves a symlinked ancestor and a symlinked final
  # component, and leaves a `cd` inside a wrapper and a link changed between
  # this check and the act — the same closure and residual the run directory
  # guard states.
  local a an ap al ar sp r rl rp hl hp first w wn wp wl i ov ovrc wraps mode
  local cb ov2 ovw wn2 wp2 wl2 an2 ap2 al2
  gate_plugin_roots
  rl=$GATE_PR_RL; rp=$GATE_PR_RP; hl=$GATE_PR_HL; hp=$GATE_PR_HP
  wraps=0
  if gate_argv0_wraps "$1"; then wraps=1; fi
  # The directory the command itself resolves from, as the run directory guard
  # states at the same place.
  cb=$(gate_argv_chdir_base "$@") || cb=""
  # The unreadable-shape arm, as the run directory guard states at the same place.
  if [ "$cb" = "$GATE_FORM_UNKNOWN" ]; then
    warn "rule refused: this shape runs its inner command from a directory the gate cannot name — each match's own directory rather than this one — so where a relative destination inside it lands cannot be judged. Respell it with \`-exec\` and an absolute destination: $1"
    return "$GATE_EXIT_RULE"
  fi
  first=1
  for a in "$@"; do
    if [ "$first" = 1 ]; then
      first=0
      if gate_argv0_is_plugin_exec "$a"; then continue; fi
      case "$a" in */*) ;; *) continue ;; esac
    fi
    # The option value and the `/`-less names, as the run directory guard
    # states at the same place.
    if ov=$(gate_arg_option_value "$a"); then
      # The second base, as the run directory guard states at the same place.
      ov2=$(gate_second_base_spelling "$ov" "$cb") || ov2=""
      for ovw in "$ov" "$ov2"; do
        [ -n "$ovw" ] || continue
        gate_word_is_at_or_above "$ovw" "$rl" "$rp" "$hl" "$hp"; ovrc=$?
        if [ "$ovrc" = 0 ]; then
          warn "rule refused: this is an orchestrator or hook script of the installed plugin — these bytes perform every gate entry, so writing here is a run editing the code that enforces it. Edit them in a worktree and apply the change by deploying: $a"
          return "$GATE_EXIT_RULE"
        fi
        if [ "$ovrc" = "$GATE_LEAF_UNRESOLVED" ]; then
          gate_leaf_unresolved_refuse "$a"
          return "$GATE_EXIT_RULE"
        fi
      done
    fi
    # A compound token is not a name — the run directory guard states at the same
    # place why asking `gate_arg_bare_name` about one dropped it before the word
    # arm.
    case "$a" in
      */*) ;;
      *) gate_arg_is_compound "$a" || gate_arg_bare_name "$a" \
           || { [ -n "$cb" ] && gate_arg_bare_name "$a" "$cb"; } || continue ;;
    esac
    an=$(gate_path_spelling "$(gate_lexical_abs "$a")")
    ap=$(gate_path_spelling "$(gate_real_prefix "$an")")
    al=$(gate_leaf_spelling "$ap") || { gate_leaf_unresolved_refuse "$a"; return "$GATE_EXIT_RULE"; }
    # The whole-path argument from the second base, as the run directory guard
    # states at the same place. A bare argv0 was dropped above; one spelled as
    # a path is measured like any operand, and an absolute one gets no second
    # spelling.
    an2=""; ap2=""; al2=""
    if ! gate_arg_is_compound "$a"; then
      an2=$(gate_second_base_spelling "$a" "$cb") || an2=""
      if [ -n "$an2" ]; then
        ap2=$(gate_path_spelling "$(gate_real_prefix "$an2")")
        al2=$(gate_leaf_spelling "$ap2") || { gate_leaf_unresolved_refuse "$a"; return "$GATE_EXIT_RULE"; }
      fi
    fi
    ar=$(gate_path_spelling "$a")
    for r in "$rl" "$rp" "$hl" "$hp"; do
      [ -n "$r" ] || continue
      # THE ROOT ITSELF AND EVERY ANCESTOR OF IT, for a whole-path argument.
      # Every needle below is anchored at `orchestrator` or `hooks`, so
      # `cp -R <evil>/orchestrator <root>` — which macOS `cp -R` merges into
      # the existing directory — and `rm -rf <root>/..` named nothing they
      # match. A compound token is excluded here for the reason the run
      # directory guard gives at its ancestor arm; its option value and, under
      # an interpreter, its words are tested where that guard tests them.
      #
      # RESIDUAL, in the safe direction: a stage in the main worktree cannot
      # name that worktree's root, `plugins`, `$HOME` or `/` as the operand of
      # a write-graded act — and since `.` there IS that root, `git add .` in
      # the main worktree is refused; naming the paths to add is the way
      # through. From a segment worktree `.` is not an ancestor and passes.
      if ! gate_arg_is_compound "$a"; then
        for sp in "$an" "$ap" "$al" "$an2" "$ap2" "$al2"; do
          [ -n "$sp" ] || continue
          if gate_path_is_at_or_above "$sp" "$r"; then
            warn "rule refused: this is an orchestrator or hook script of the installed plugin — these bytes perform every gate entry, so writing here is a run editing the code that enforces it. Edit them in a worktree and apply the change by deploying: $a"
            return "$GATE_EXIT_RULE"
          fi
        done
      fi
      # `ar` is the argument before `..` is rewound — the spelling in which a
      # program string's trailing `: /../../..` has not yet erased the root.
      for sp in "$an" "$ap" "$al" "$ar" "$an2" "$ap2" "$al2"; do
        [ -n "$sp" ] || continue
        # THE NEEDLE IS THE DIRECTORY, NOT THE WHOLE ARGUMENT, for the reason the
        # run directory guard's last arm gives: an option token and an interpreter
        # program string both carry the path inside a larger argument, and a
        # prefix test over arguments sees neither.
        #
        # THE CONTAINER IS MATCHED BESIDE ITS CONTENTS. Requiring a component
        # AFTER the directory name let the directory itself through, and a verb
        # whose destination is a directory takes the created name from the
        # source's basename — `cp /tmp/gate.sh <root>/orchestrator` replaces the
        # gate outright and `mv evil.sh <root>/hooks`, `tar -x -C
        # <root>/orchestrator` and `rm -rf <root>/orchestrator` have the same
        # shape. The trailing-slash spelling is NOT a second arm to add: it never
        # reaches this `case`, because `gate_lexical_abs` drops the empty last
        # segment first. Both spellings arrive here as `<root>/orchestrator`, so
        # the container arm is what closes both and a trailing-slash pattern
        # would change nothing.
        #
        # THE CONTAINER ARM ANCHORS AT THE END, deliberately. `*"$r"/orchestrator`
        # requires the argument to STOP there, so a sibling named
        # `<root>/orchestrator-backup` is not swallowed. Widening it to
        # `*"$r"/orchestrator*` would catch the residual below at the price of
        # refusing unrelated names, and that trade is not taken.
        #
        # A spelling that carries more text AFTER the bare directory — `bash -c
        # "rm -rf <root>/orchestrator; echo done"` — matches no arm here; the
        # word-by-word pass below the loop is what reaches it.
        case "$sp" in
          *"$r"/orchestrator|*"$r"/orchestrator/*|*"$r"/hooks|*"$r"/hooks/*)
            warn "rule refused: this is an orchestrator or hook script of the installed plugin — these bytes perform every gate entry, so writing here is a run editing the code that enforces it. Edit them in a worktree and apply the change by deploying: $a"
            return "$GATE_EXIT_RULE" ;;
        esac
      done
      # THE SAME CONTAINER, BY IDENTITY. `<root>/Orchestrator/gate.sh` is the
      # installed gate on a case-insensitive filesystem and matches none of the
      # needles above, which are byte tests. Only the absolutized spellings are
      # walked — `ar` is the argument as written and may be relative, and
      # climbing a relative path would climb from the gate's own directory.
      for sp in "$an" "$ap" "$al" "$an2" "$ap2" "$al2"; do
        [ -n "$sp" ] || continue
        case "$sp" in /*) ;; *) continue ;; esac
        if gate_path_ident_prefix "$sp" "$r/orchestrator" \
          || gate_path_ident_prefix "$sp" "$r/hooks"; then
          warn "rule refused: this is an orchestrator or hook script of the installed plugin — these bytes perform every gate entry, so writing here is a run editing the code that enforces it. Edit them in a worktree and apply the change by deploying: $a"
          return "$GATE_EXIT_RULE"
        fi
      done
    done
    # A COMPOUND TOKEN IS JUDGED WORD BY WORD, for the reason and with the
    # residual the run directory guard states at the same place. A word
    # resolves against the grading directory, so `git commit -m "…
    # plugins/cc-cmds/orchestrator/gate.sh …"` is refused where that relative
    # path lands in the installed root and passes in a segment worktree, where
    # it is the worktree's own file. Under an interpreter or wrapper argv0 each
    # word — `.`, `..` and existing bare names included — is also tested as an
    # ancestor of the root, so `bash -c "cp -R <evil> <root>"` and `bash -c
    # "rm -rf <root>/.."` are refused; the words of any other compound token
    # are text and are not, so `git commit -m "docs: touch plugins/ only"`
    # passes in the main worktree.
    if gate_arg_is_compound "$a"; then
      mode=""
      if [ "$wraps" = 1 ]; then mode=bare; fi
      gate_arg_words "$a" "$mode" \
        || { gate_word_unresolved_refuse "$a"; return "$GATE_EXIT_RULE"; }
      i=0
      while [ "$i" -lt "${#GATE_ARG_WORDS[@]}" ]; do
        w=${GATE_ARG_WORDS[$i]}; i=$((i + 1))
        wn=$(gate_path_spelling "$(gate_lexical_abs "$w")")
        wp=$(gate_path_spelling "$(gate_real_prefix "$wn")")
        wl=$(gate_leaf_spelling "$wp") || { gate_leaf_unresolved_refuse "$a"; return "$GATE_EXIT_RULE"; }
        # The same word from the directory the command resolves it from, as the
        # run directory guard states at the same place.
        wn2=$(gate_second_base_spelling "$w" "$cb") || wn2=""
        wp2=""; wl2=""
        if [ -n "$wn2" ]; then
          wp2=$(gate_path_spelling "$(gate_real_prefix "$wn2")")
          wl2=$(gate_leaf_spelling "$wp2") || { gate_leaf_unresolved_refuse "$a"; return "$GATE_EXIT_RULE"; }
        fi
        for r in "$rl" "$rp" "$hl" "$hp"; do
          [ -n "$r" ] || continue
          for sp in "$wn" "$wp" "$wl" "$wn2" "$wp2" "$wl2"; do
            [ -n "$sp" ] || continue
            case "$sp" in
              *"$r"/orchestrator|*"$r"/orchestrator/*|*"$r"/hooks|*"$r"/hooks/*)
                warn "rule refused: an orchestrator or hook script of the installed plugin is buried inside an argument — these bytes perform every gate entry, so writing here is a run editing the code that enforces it. Edit them in a worktree and apply the change by deploying: $a"
                return "$GATE_EXIT_RULE" ;;
            esac
            # The same container by identity, as the whole-path arm above.
            case "$sp" in
              /*)
                if gate_path_ident_prefix "$sp" "$r/orchestrator" \
                  || gate_path_ident_prefix "$sp" "$r/hooks"; then
                  warn "rule refused: an orchestrator or hook script of the installed plugin is buried inside an argument — these bytes perform every gate entry, so writing here is a run editing the code that enforces it. Edit them in a worktree and apply the change by deploying: $a"
                  return "$GATE_EXIT_RULE"
                fi ;;
            esac
            if [ "$wraps" = 1 ] && gate_path_is_at_or_above "$sp" "$r"; then
              warn "rule refused: the installed plugin root or an ancestor of it is buried inside an interpreter program string — these bytes perform every gate entry, so writing here is a run editing the code that enforces it. Drop the wrapper and pass the destination as its own argument: $a"
              return "$GATE_EXIT_RULE"
            fi
          done
        done
      done
    fi
  done
  return 0
}

gate_shard_exec_guard() {
  # gate_shard_exec_guard <argv...> — the routing seat never reaches `shared/`.
  #
  # THE FENCE IS THE EXEC PATH, NOT THE SETTINGS FILE. The shift settings
  # variant carries no `additionalDirectories` at all, so a shift cannot read a
  # shard through `Read` — but every command it runs goes through this gate's
  # bash path, and `cat "$RUN_DIR/shared/3/…"` is a read the settings layer
  # never sees. Adding a `shared/` row to that layer would widen the surface an
  # `exit 7` is measured against; refusing here widens nothing. "The exec path"
  # is the argv-running path and not the `exec` verb: an `act` of a general
  # kind runs its argv through the same `gate_run_readonly`, so the caller
  # applies this fence to both verbs.
  #
  # WHO IS FENCED. The actor test is the same one the approval row uses: a
  # caller that is not a stage and carries `CC_PIPELINE_SHIFT_ID` is the
  # routing seat. A stage a shift launched inherits the variable and is a stage
  # first, so it is not fenced — the lead seat publishes the shards and the
  # stages read them; only the routing seat is kept out.
  #
  # FOUR SPELLINGS ARE RESOLVED, and only the fourth is the interesting one:
  # absolute, relative to the act's directory, a symlink whose own path names
  # nothing under the fence, and a name that does not exist yet. The lexical
  # resolver handles the second and fourth, the real-prefix resolver folds a
  # symlinked ancestor, and a symlinked LEAF is read once with `readlink` —
  # `readlink -f` is a BSD/GNU divergence the portability lint refuses.
  [ -n "${RUN_DIR:-}" ] || return 0
  [ "$#" -ge 1 ] || return 0
  cc_caller_is_stage && return 0
  [ -n "${CC_PIPELINE_SHIFT_ID:-}" ] || return 0
  local fence fencep a abs real tgt
  fence=$(gate_lexical_abs "$RUN_DIR/shared")
  fencep=$(gate_real_prefix "$fence")
  for a in "$@"; do
    case "$a" in */*|shared) ;; *) continue ;; esac
    abs=$(gate_lexical_abs "$a")
    if [ -L "$abs" ]; then
      tgt=$(readlink "$abs" 2>/dev/null || true)
      if [ -n "$tgt" ]; then
        case "$tgt" in /*) ;; *) tgt="${abs%/*}/$tgt" ;; esac
        abs=$(gate_lexical_abs "$tgt")
      fi
    fi
    real=$(gate_real_prefix "$abs")
    case "$abs" in
      "$fence"|"$fence"/*) ;;
      *) case "$real" in "$fencep"|"$fencep"/*) ;; *) continue ;; esac ;;
    esac
    warn "rule refused: the routing seat does not reach the shard directory — shared/<gen>/ under the run directory is the shared snapshot the lead seat publishes for stages, the shift settings variant was narrowed to keep it out, and an exec that names it walks past that layer (fence: $fence): $a"
    return "$GATE_EXIT_RULE"
  done
  return 0
}

gate_manifest_write_guard() {
  # gate_manifest_write_guard <graded-surface> <argv...>
  #
  # THE MANIFEST BECAME AN AUTHORIZATION RECORD AND DID NOT GET THE GUARD ONE
  # HAS. `## 인가` now carries `자동 채택` rows, and one more of those means every
  # judgment of that class is adopted with no person and no reversibility
  # requirement — the same KIND of value the grant holds. The grant has a
  # structural guard (`인가-자기확장-금지` refuses any act that writes it); the
  # manifest had none, in this file or in the rule catalog, so an ordinary
  # `워크트리쓰기` act could append to its own pre-adoption list.
  #
  # The rule catalog is the natural home for this and is not reachable: it is an
  # enforcement surface, and a run editing the surface that binds it is the move
  # every other branch here refuses. So the guard lives on the gate's own path,
  # which is the layer this run may change.
  #
  # Shaped exactly like the grant arm it mirrors: any non-read act naming the
  # manifest is refused, whatever the cutpoint. Cutpoints say how far an act may
  # go; this act would change the answer.
  #
  # THREE ARMS, EACH CLOSING A SPELLING THE OTHERS CANNOT SEE. Equality on argv
  # elements had two ways out and both were reachable by ordinary spellings. A
  # different spelling of the same absolute path — an extra `/./`, a relative
  # path — is a different string; that half is closed by normalizing `MANIFEST`
  # at argument-parse time and by resolving both sides physically in arm 3. The
  # other half is not a path problem at all: `bash -c 'printf x >> <경로>'` puts
  # the path INSIDE an argv element, so no element equals the manifest and the
  # loop ran to the end while the redirection wrote the file.
  #
  # What each arm actually measures — spelled out because the sentence that stood
  # here claimed the basename scan by itself caught interpreter wrapping, and
  # measurement showed it caught only the one spelling that writes the path
  # verbatim. That claim was read as a check by someone auditing this guard, who
  # closed a finding on it and had to withdraw the closure:
  #   arm 2  an interpreter's or wrapper's WHOLE command line, against the
  #          basename, the basename's stem, the manifest's directory in three
  #          spellings — logical, physical, and relative to the act's own
  #          directory — and the two variable names. The stem is what catches
  #          `X.plan.m?`, a glob that shares no basename with the file it will
  #          open and need not name the directory at all when the act already
  #          runs there. The directory needles catch the spellings that name a
  #          place instead of a file, `find <디렉터리> … -exec` among them. Saying
  #          where is not the same as spelling it the gate's way, so both sides
  #          are separator-folded first; arm 2 below records what that cost.
  #   arm 3  physical path identity for elements shaped like a path. It is the
  #          only arm that sees an alias symlink, which shares neither basename
  #          nor directory with the file it writes.
  #   last   basename containment, for an element not shaped like a path at all.
  #          This is what refuses `tee …/X.plan.md` today.
  #
  # AND WHAT REMAINS OPEN, in the same breath. Arm 2 fires on an argv0 in its own
  # list, so a wrapper outside that list, reaching the file through a constructed
  # string, is not seen here. The stem needle lives in arm 2 only and not in the
  # basename scan below, so an element that carries the stem without an
  # interpreter around it passes — the measured bypass went through an
  # interpreter, and the scan below is already the arm with known false
  # positives. Those are acts that merely mention a file of that name elsewhere
  # in the tree, a cost kept on purpose rather than traded for the coverage. The
  # act-cwd-relative directory needle is as specific as the manifest's own
  # placement makes it: a manifest one level under the act's directory yields a
  # single-component needle, and every interpreter command naming that component
  # is refused. And none of the arms anchors a rollback: a write that gets past
  # all of them is caught at the next entry, where the binding digest is compared
  # against the frozen set.
  #
  # The false positives this admits are reads that merely MENTION the file, and
  # the read arm above has already returned for those. What is left is an act
  # that changes something and carries the manifest's name in its command line,
  # which is the thing to refuse.
  local graded="$1"; shift
  # NO COMMAND MEANS NOTHING TO GUARD. The arms below read `$1` to classify the
  # act, and under `set -u` an empty argv makes that read fatal rather than
  # falsy — the gate died before it could enumerate its own conditions, which
  # reads as the run being broken rather than as this call having nothing to do.
  [ "$#" -ge 1 ] || return 0
  [ -n "${MANIFEST:-}" ] || return 0
  # THE READ GRADE IS NOT A PASS FOR A COMMAND THAT DELEGATES. `find` grades
  # `읽기` from argv0 alone, so `find <디렉터리> … -exec sh -c 'printf x >> {}' \;`
  # arrived here declared and graded as a read, returned on this line, and the
  # guard never looked at the argv that was about to write. The self-declaration
  # check cannot catch it either: the declaration MATCHES the grade, and both are
  # wrong about the same command.
  #
  # Two axes decide, not one — whether the argv carries a primary that executes
  # or deletes, and whether argv0 is a wrapper that runs some other command.
  # `find` is deliberately NOT in the argv0 list: a plain `find` with no primary
  # has to keep returning here, or every read that walks the manifest's directory
  # becomes a refusal.
  case "$graded" in
    읽기)
      case " $* " in
        *" -exec "*|*" -execdir "*|*" -ok "*|*" -okdir "*|*" -delete "*) ;;
        *" -fprintf "*|*" -fprint "*|*" -fprint0 "*|*" -fls "*) ;;
        *)
          case "${1##*/}" in
            command|env|xargs|lockf|nice|nohup|time|timeout|stdbuf) ;;
            *) return 0 ;;
          esac ;;
      esac ;;
  esac
  local a mbase mstem mdir mdirp mreal adir areal joined argv0 joinedn
  local mdirn mdirpn mdirrel actcwdn
  mbase=$(basename "$MANIFEST")
  [ -n "$mbase" ] || return 0
  mdir=$(dirname "$MANIFEST")
  # BOTH SPELLINGS OF THE DIRECTORY, because arm 2 matches the caller's own
  # bytes and the caller may have written either one. `MANIFEST` is normalized
  # logically, so on a host where the temp or state root is itself a symlink the
  # physical spelling is a different string that names the same directory.
  #
  # A FALLBACK AND NOT AN OVERWRITE. Arm 2 now tests three needles instead of
  # one, and an empty needle matches every command line — so a `pwd -P` that
  # returns nothing would turn this guard into a refusal of everything. Each
  # needle is screened for emptiness below as well; this keeps the value itself
  # from ever being the empty one.
  mdirp=$(cd "$mdir" 2>/dev/null && pwd -P) || mdirp="$mdir"
  [ -n "$mdirp" ] || mdirp="$mdir"

  # ARM 2 — AN INTERPRETER HIDES THE PATH OPERAND, SO THE WHOLE COMMAND LINE IS
  # THE OPERAND. `bash -c` takes a program, not arguments: there is no element to
  # resolve and no way to tell which bytes of it will become a filename. So the
  # test here is containment over the joined argv, and it is deliberately wider
  # than the one below — the manifest's DIRECTORY counts, not only its basename.
  #
  # The directory is what closes the glob spelling. `…/X.plan.m?` shares no
  # basename with `X.plan.md`, but a glob that is going to reach the file has to
  # say where the file is. The environment variable names are here for the same
  # reason one step earlier: `printf x >> "$CC_PIPELINE_MANIFEST"` never spells
  # the path at all.
  #
  # HAVING TO SAY WHERE IS NOT HAVING TO SPELL IT THE GATE'S WAY. The sentence
  # that stood here said the glob "names the same directory verbatim", and that
  # was measured false in this very tree: the caller's bytes carried `…/T//x.abc`
  # — a `TMPDIR` ending in `/` fed straight into a `mktemp` template, which
  # `mktemp` returns as given — while the gate held `…/T/x.abc`, folded by the
  # `cd`+`pwd` normalization at argument-parse time. Same directory, different
  # spelling, containment missed, and the glob went through with the two other
  # arms blind to it by construction. The physical spelling `mdirp` did not help:
  # it was added for a symlinked root, which is a different divergence.
  #
  # So both sides go through `gate_path_spelling` before the comparison. That
  # closes every duplicate- and dot-separator spelling of this arm at once —
  # `//`, `///`, `/./` all fold to the same bytes — rather than the one glob that
  # happened to be measured. The basename and variable-name tests carry no
  # separator and are left on the raw bytes.
  # THE LIST IS INTERPRETERS AND WRAPPERS, for one reason. A wrapper cannot say
  # which bytes of its tail will become a filename any more than `bash -c` can,
  # so the whole command line is the operand there too. `find` is here because
  # `find <매니페스트 디렉터리> … -exec` reaches the file through an element that
  # is neither the manifest's path nor its basename; `lockf` is here because
  # three unattended skills MANDATE it around every document write, which made it
  # a wrapper the guard was guaranteed to meet.
  #
  # Applying arm 2 to every argv0 was measured and REJECTED: the directory needle
  # then fires on an unrelated file that merely lives beside the manifest, which
  # is an upper bound this suite already holds green.
  argv0=${1##*/}
  case "$argv0" in
    bash|sh|zsh|dash|ksh|python|python3|perl|ruby|node|npx|make|env|xargs|find|lockf|command|nice|nohup|time|timeout|stdbuf)
      joined=$(printf '%s ' "$@")
      case "$joined" in *"$mbase"*|*CC_PIPELINE_MANIFEST*|*MANIFEST*)
        gate_manifest_write_refuse; return "$GATE_EXIT_RULE" ;;
      esac
      # THE STEM ERASES THE ABSOLUTE/RELATIVE DISTINCTION. A glob one character
      # short of the basename shares no basename, and it need not spell the
      # directory at all when the act already runs there — so both needles above
      # and the directory needles below look past `printf x >> <이름>.plan.m?`
      # written from the manifest's own directory. The stem is the part of the
      # name a glob cannot drop while still opening the file, and it appears in
      # the command line however the caller spelled the path.
      #
      # Cut at the LAST dot, not the first. A manifest named `<런 id>.plan.md`
      # cut at the first dot yields the run id, which is also the run
      # directory's basename — and then every command mentioning the run
      # directory is refused. Screened for emptiness and for equality with the
      # basename: a name with no dot yields the basename back, and testing it
      # twice is a needle that costs a pass and buys nothing.
      mstem=${mbase%.*}
      case "$mstem" in
        ''|"$mbase") ;;
        *) case "$joined" in *"$mstem"*)
             gate_manifest_write_refuse; return "$GATE_EXIT_RULE" ;;
           esac ;;
      esac
      joinedn=$(gate_path_spelling "$joined")
      mdirn=$(gate_path_spelling "$mdir")
      mdirpn=$(gate_path_spelling "$mdirp")
      # THE DIRECTORY AS THE ACT WOULD SPELL IT. Both spellings above are
      # absolute, and an act running inside the tree writes the relative one.
      # The needle is built only when the act's directory is an ANCESTOR of the
      # manifest's, so there is no path by which it takes a value from another
      # repository or another worktree.
      mdirrel=''
      if [ -n "${GATE_ACT_CWD:-}" ]; then
        actcwdn=$(gate_path_spelling "$GATE_ACT_CWD")
        case "$mdirn" in "$actcwdn"/*) mdirrel=${mdirn#"$actcwdn"/} ;; esac
      fi
      # ONE SENTINEL PER NEEDLE, WHICH IS THE PREMISE OF WIDENING AT ALL. The
      # single screen that stood here read `mdirn` and then tested `mdirpn`
      # beside it, so an empty physical spelling refused every act while the
      # screen reported itself satisfied. With three needles the same hole is
      # three holes. Written as three blocks rather than a loop over a list:
      # this file has to run under bash 3.2, where arrays are the thing that
      # quietly differs.
      case "$mdirn" in
        ''|'/'|'.') ;;
        *) case "$joinedn" in *"$mdirn"*)
             gate_manifest_write_refuse; return "$GATE_EXIT_RULE" ;;
           esac ;;
      esac
      case "$mdirpn" in
        ''|'/'|'.') ;;
        *) case "$joinedn" in *"$mdirpn"*)
             gate_manifest_write_refuse; return "$GATE_EXIT_RULE" ;;
           esac ;;
      esac
      case "$mdirrel" in
        ''|'/'|'.') ;;
        *) case "$joinedn" in *"$mdirrel"*)
             gate_manifest_write_refuse; return "$GATE_EXIT_RULE" ;;
           esac ;;
      esac
      ;;
  esac

  # ARM 3 — PATH IDENTITY, RESOLVED PHYSICALLY ON BOTH SIDES. An element shaped
  # like a path is resolved the same way the manifest is and compared as a file
  # rather than as a string, so a symlinked directory in the path — or an alias
  # symlink pointing AT the manifest under some other name — is the manifest
  # here. The alias case is the one no other arm can reach: it shares neither
  # basename nor directory with the file it writes.
  #
  # Both sides are resolved in this function rather than trusting the value
  # normalized at argument-parse time. A comparison where only one side followed
  # symlinks is a comparison of spellings again, which is what all of this is
  # for.
  mreal=$(gate_physical_path "$MANIFEST")
  for a in "$@"; do
    case "$a" in */*) ;; *) continue ;; esac
    # `--`: a word like `--git-dir=<p>/x` is an operand here, not an option
    # of dirname.
    adir=$(dirname -- "$a")
    [ -d "$adir" ] || continue
    areal=$(gate_physical_path "$a")
    [ "$areal" = "$mreal" ] || continue
    gate_manifest_write_refuse
    return "$GATE_EXIT_RULE"
  done

  # THE BASENAME CONTAINMENT SCAN STAYS, BEHIND THE TWO ARMS ABOVE. It is the
  # only one of the three that catches a manifest name carried by an element
  # that is not shaped like a path at all, and it is what refuses `tee` on the
  # ordinary spelling today. Its cost is refusing acts that merely mention a
  # file of that name elsewhere in the tree, which is a false positive this
  # keeps rather than trade for the coverage.
  for a in "$@"; do
    case "$a" in *"$mbase"*) ;; *) continue ;; esac
    gate_manifest_write_refuse
    return "$GATE_EXIT_RULE"
  done
  gate_sibling_record_write_guard "$mdir" "$mdirp" "$@" || return $?
  return 0
}

gate_progfile_word() {
  # gate_progfile_word <sed|awk|xargs|vi> <element> — prints `hit` when the
  # element hands that program a file to read its program or its argument list
  # from, `arg` when it is an option whose value is the next element, `opt` for
  # any other option and `operand` for a non-option.
  #
  # Short options are read as a cluster, letter by letter, the way getopt reads
  # them: `-nf prog` and `-fprog` are `-f` as much as `-f prog` is, and a letter
  # that takes a value ends the cluster, so `-v x=-f` is not a hit.
  local k="$1" a="$2" c rest refl argl optl
  case "$k:$a" in
    sed:--file|sed:--file=*|awk:--file|awk:--file=*|awk:--exec|awk:--exec=*|awk:--include|awk:--include=*|awk:--load|awk:--load=*|xargs:--arg-file|xargs:--arg-file=*|vi:-s|vi:-S|vi:-S?*)
      printf 'hit'; return 0 ;;
    sed:--expression|sed:--line-length|awk:--field-separator|awk:--assign|xargs:--delimiter|xargs:--max-args|xargs:--max-procs|xargs:--max-chars|xargs:--max-lines|xargs:--process-slot-var|vi:-c|vi:--cmd|vi:-T|vi:-u|vi:-U|vi:-i|vi:-w|vi:-W|vi:-t|vi:-q)
      printf 'arg'; return 0 ;;
    *:--*|vi:-*|vi:+*) printf 'opt'; return 0 ;;
    *:-?*) ;;
    *) printf 'operand'; return 0 ;;
  esac
  case "$k" in
    sed) refl=f argl=el optl=i ;;
    awk) refl=fEil argl=FveWZ optl=dDLop ;;
    *) refl=a argl=EIJLnPRSsd optl=eil ;;
  esac
  rest=${a#-}
  while [ -n "$rest" ]; do
    c=${rest:0:1}; rest=${rest:1}
    case "$refl" in *"$c"*) printf 'hit'; return 0 ;; esac
    case "$argl" in
      *"$c"*) if [ -z "$rest" ]; then printf 'arg'; else printf 'opt'; fi; return 0 ;;
    esac
    case "$optl" in *"$c"*) printf 'opt'; return 0 ;; esac
  done
  printf 'opt'
}

gate_progfile_opt() {
  # gate_progfile_opt <argv...> — rc 0, with the program and the option in
  # GATE_PROGFILE_HIT, when the act hands sed, awk, xargs or vi a FILE to read
  # its program or its argument list from.
  #
  # THE PATH ARMS OF THE PACING AND SIBLING RECORD GUARDS READ ONLY WHAT THE ACT
  # SPELLS. `sed -n -f prog /dev/null` with `prog` holding `$!w <pace>/backlog.jsonl`,
  # `awk -f prog` printing into a sibling's `R8.plan.md`, and `xargs -a list cp …`
  # name the destination nowhere in the argv: it is a byte of a file the guards
  # never open, so both arms let all three write. Opening the file would not
  # settle it either — what it holds at the check is not what it holds when the
  # program reads it. A write grade carrying such an option is therefore refused
  # whatever the file says, and a read grade is not: these programs still read.
  #
  # A program counts where it is the act's argv0, or anywhere in the argv of an
  # act an interpreter or a wrapper leads (`env sed -f`, `find … -exec awk -f`,
  # `xargs sed -f`), because the argv0 alone says nothing there. Options are read
  # until `--` or a `find -exec` terminator; for xargs, until its command, whose
  # own options are not xargs's. vi takes `-s` and `-S`: in Ex mode `-s` reads
  # its commands from standard input, which no guard sees either.
  local n=$# i=0 j k a r lead=0
  local -a av
  av=("$@")
  GATE_PROGFILE_HIT=''
  if gate_argv0_wraps "${av[0]}"; then lead=1; fi
  case "${av[0]##*/}" in sudo|doas) lead=1 ;; esac
  while [ "$i" -lt "$n" ]; do
    if [ "$i" -gt 0 ] && [ "$lead" = "0" ]; then break; fi
    case "${av[i]##*/}" in
      sed|gsed) k=sed ;;
      awk|gawk|nawk|mawk) k=awk ;;
      xargs|gxargs) k=xargs ;;
      vi|vim|nvim|ex|view|rvim|gvim) k=vi ;;
      *) i=$((i + 1)); continue ;;
    esac
    j=$((i + 1))
    while [ "$j" -lt "$n" ]; do
      a=${av[j]}
      case "$a" in --|';'|'\;'|'+') break ;; esac
      r=$(gate_progfile_word "$k" "$a")
      case "$r" in
        hit) GATE_PROGFILE_HIT="${av[i]} $a"; return 0 ;;
        arg) j=$((j + 2)); continue ;;
        operand) [ "$k" = xargs ] && break ;;
      esac
      j=$((j + 1))
    done
    i=$((i + 1))
  done
  return 1
}

gate_progfile_refuse() {
  warn "rule refused: \`$GATE_PROGFILE_HIT\` reads its program or its argument list from a file, so where it writes is written in that file — a guard that does not open the file cannot judge the destination, and a write grade is not left to it ($1)"
}

gate_sibling_record_refuse() {
  warn "this is a write to another run's kickoff-frozen record — only kickoff writes it: $1"
  warn "a rekick copies the predecessor's manifest and grant record byte for byte, so a run that edits a sibling's record writes the authorization of the run that comes after it"
}

gate_sibling_record_write_guard() {
  # gate_sibling_record_write_guard <매니페스트 디렉터리> <그 물리 철자> <argv...>
  #
  # THE OWN-PATH ARMS ABOVE ARE NOT ENOUGH ONCE A RUN CAN BE DERIVED FROM
  # ANOTHER. A re-kickoff builds a new run by copying the previous run's
  # manifest and grant record byte for byte, so a stage that edits a SIBLING
  # run's `*.plan.md`, `*.interview.md`, `*.kickoff.md` or grant record has
  # written the authorization of a run it is not part of, and nothing above
  # looks: every arm there is keyed on this run's own manifest.
  #
  # Reached only past the read early return of the caller, so an act that
  # merely names a sibling path while reading it passes — the same boundary the
  # own-manifest arms keep.
  #
  # Two arms, mirroring the caller's. The interpreter arm reads the whole
  # command line, because `bash -c` hides which bytes become a filename; it
  # tests the grant directory in its spellings (the manifest directory is
  # already a needle of the caller's arm 2). The element arm resolves each
  # element carrying one of the three suffixes, or any element under the grant
  # directory, physically against the act's own directory and compares the
  # parent directory — so a bare `X.plan.md` written from inside the manifest
  # directory is caught, which no string test on the absolute spelling sees.
  #
  # THE ELEMENT ARM TAKES THE WORDS OF A COMPOUND ELEMENT, NOT THE ELEMENT. A
  # destination carried inside one larger element — `sed -n 'w <dir>/R8.plan.md'`,
  # `dd of=<dir>/R8.plan.md`, awk's `> "<path>"` — ends in the suffix the arm
  # matches, but resolving the whole element names a directory `w <dir>` that
  # does not exist, and the arm skipped it. A compound element is split by
  # `gate_arg_words`, the run directory guard's word split, and each word goes
  # through the arm as an element of its own. A word the split cannot resolve is
  # refused rather than guessed.
  #
  # AND EACH WORD BY EVERY DESTINATION IT CAN CARRY, COMPARED BY IDENTITY. The
  # split alone left three standard spellings open: a destination glued to a
  # command letter or option (`sed -n 'w<dir>/R8.plan.md'`, `sort -o<path>`),
  # which `gate_dest_tails` reads apart; a case variant (`R8.PLAN.md`,
  # `<DIR>/R8.plan.md`) on the default case-insensitive volume, which the
  # suffix test now folds and the directory test compares with `-ef`; and a
  # DIRECTORY destination (`cp R8.plan.md <dir>/`, `cp -t <dir> R8.plan.md`),
  # where the element naming the directory carries no suffix and the element
  # carrying the suffix is the source. An act that names the manifest directory
  # itself beside any record-suffixed name — or the grant directory beside any
  # `.md` — is refused.
  #
  # A LINK MADE BEFORE THE WRITE IS FOLLOWED, AND `ln` IS READ FROM THE LINK'S
  # DIRECTORY. Measured on the spellings above alone: `cp /dev/null sub/L` and
  # `tee -a sub/L` through a link `sub/L` → `../R8.plan.md` returned 0, so did
  # a `cp` through a link to the grant directory's record, and so did the `ln`
  # that made the link — the parent test looks at the directory the link sits
  # in, and a name with neither suffix was dropped before it. A final component
  # that is a link is now judged by the file it leads to
  # (`gate_sibling_target_hit`), a chain the walk cannot finish is refused, and
  # an `ln` whose target text lands on a record is refused the way the pacing
  # guard refuses one into its root (`gate_ln_operands`).
  #
  # RESIDUAL: an ancestor of either directory as the destination (`cp -R
  # ./pipeline-run <docs>/`) is not refused here, because `docs/` is a
  # directory ordinary writes name; neither is a path assembled by a `cd`
  # inside a wrapper, or a link swapped between this check and the act. A
  # destination written inside a script or an interpreter's program text is
  # not read either. A program or an argument list taken from a file
  # (`sed -f`, `awk -f`, `xargs -a`, `vim -s`) is refused outright, since no
  # arm here could read where it writes (`gate_progfile_opt`). The edit tools
  # are the hook's to refuse, and its guard keys on this run's own files only.
  local mdir="$1" mdirp="$2"; shift 2
  local gdir='' gdirp='' a b ap ad argv0 joinedn gdirn gdirpn cwd i x
  local rec to_mdir=0 to_gdir=0 has_rec=0 has_md=0
  local -a cand base_c raw
  # A destination read from a file is not one the arms below can see.
  if gate_progfile_opt "$@"; then
    gate_progfile_refuse "another run's kickoff-frozen record"; return "$GATE_EXIT_RULE"
  fi
  if [ -n "${GRANT:-}" ]; then
    gdir=$(dirname "$GRANT")
    gdirp=$(cd "$gdir" 2>/dev/null && pwd -P) || gdirp="$gdir"
    [ -n "$gdirp" ] || gdirp="$gdir"
  fi
  cwd="${GATE_ACT_CWD:-$PWD}"

  argv0=${1##*/}
  case "$argv0" in
    bash|sh|zsh|dash|ksh|python|python3|perl|ruby|node|npx|make|env|xargs|find|lockf|command|nice|nohup|time|timeout|stdbuf)
      joinedn=$(gate_path_spelling "$(printf '%s ' "$@")")
      if gate_nocase_contains "$joinedn" 'pipeline-grant/'; then
        gate_sibling_record_refuse "$joinedn"; return "$GATE_EXIT_RULE"
      fi
      if [ -n "$gdir" ]; then
        gdirn=$(gate_path_spelling "$gdir")
        gdirpn=$(gate_path_spelling "$gdirp")
        case "$gdirn" in
          ''|'/'|'.') ;;
          *) if gate_nocase_contains "$joinedn" "$gdirn"; then
               gate_sibling_record_refuse "$gdir"; return "$GATE_EXIT_RULE"
             fi ;;
        esac
        case "$gdirpn" in
          ''|'/'|'.') ;;
          *) if gate_nocase_contains "$joinedn" "$gdirpn"; then
               gate_sibling_record_refuse "$gdirp"; return "$GATE_EXIT_RULE"
             fi ;;
        esac
      fi
      # THE SUFFIX NEEDLE, ONLY FROM INSIDE THE MANIFEST DIRECTORY. There the
      # caller's arm 2 has no directory to find, because a relative name spells
      # none; everywhere else that needle already fires on the directory.
      x=$(cd "$cwd" 2>/dev/null && pwd -P) || x=""
      if [ -n "$x" ] && { [ "$x" = "$mdirp" ] || [ "$x" -ef "$mdirp" ]; }; then
        if gate_nocase_glob "$joinedn" '*.plan.*' || gate_nocase_glob "$joinedn" '*.interview.*' \
           || gate_nocase_glob "$joinedn" '*.kickoff.*'; then
          gate_sibling_record_refuse "$joinedn"; return "$GATE_EXIT_RULE"
        fi
      fi ;;
  esac

  cand=()
  for a in "$@"; do
    base_c=()
    if gate_arg_is_compound "$a"; then
      gate_arg_words "$a" \
        || { gate_word_unresolved_refuse "$a"; return "$GATE_EXIT_RULE"; }
      i=0
      while [ "$i" -lt "${#GATE_ARG_WORDS[@]}" ]; do
        base_c[${#base_c[@]}]=${GATE_ARG_WORDS[$i]}; i=$((i + 1))
      done
      # A `/`-less record name inside a compound element (`dd of=R8.plan.md`)
      # is dropped by the word split, and from inside the manifest directory it
      # is exactly the sibling's record.
      # shellcheck disable=SC2295
      x=${a//$GATE_ARG_SEP/ }
      read -r -a raw <<< "$x"
      for b in ${raw[@]+"${raw[@]}"}; do
        case "$b" in */*) continue ;; esac
        if gate_record_suffix "$b" || [ -L "$cwd/$b" ]; then
          base_c[${#base_c[@]}]=$b
        fi
      done
    else
      base_c[0]=$a
    fi
    for b in ${base_c[@]+"${base_c[@]}"}; do
      gate_dest_tails "$b"
      i=0
      while [ "$i" -lt "${#GATE_DEST_TAILS[@]}" ]; do
        cand[${#cand[@]}]=${GATE_DEST_TAILS[$i]}; i=$((i + 1))
      done
    done
  done
  for a in ${cand[@]+"${cand[@]}"}; do
    [ -n "$a" ] || continue
    case "$a" in
      /*) ap="$a" ;;
      *) ap="$cwd/$a" ;;
    esac
    # A FINAL COMPONENT THAT IS A LINK names the record it leads to, not
    # itself: `sub/L` made earlier as `../R8.plan.md` carries neither suffix
    # nor directory, so every test below passed it while `cp` and `tee -a`
    # wrote the sibling's plan. `-L` is a builtin, so only a link costs forks.
    if [ -L "$ap" ]; then
      i=0
      gate_sibling_target_hit "$ap" "$mdirp" "$gdirp" || i=$?
      if [ "$i" = 0 ]; then gate_sibling_record_refuse "$a"; return "$GATE_EXIT_RULE"; fi
      if [ "$i" = "$GATE_LEAF_UNRESOLVED" ]; then
        gate_leaf_unresolved_refuse "$a"; return "$GATE_EXIT_RULE"
      fi
    fi
    # THE DIRECTORY ITSELF AS A DESTINATION, remembered and judged after every
    # candidate is seen — the record-suffixed source may come before or after.
    if [ -d "$ap" ]; then
      if [ "$ap" -ef "$mdirp" ]; then to_mdir=1; fi
      if [ -n "$gdirp" ] && [ "$ap" -ef "$gdirp" ]; then to_gdir=1; fi
    fi
    rec=0
    if gate_record_suffix "$a"; then rec=1; has_rec=1; fi
    if gate_nocase_glob "$a" '*.md'; then has_md=1; fi
    if [ "$rec" = 0 ]; then
      if gate_nocase_glob "/$a" '*/pipeline-grant/*.md'; then
        gate_sibling_record_refuse "$a"; return "$GATE_EXIT_RULE"
      fi
      gate_nocase_glob "$a" '*/*.md' || continue
      [ -n "$gdir" ] || continue
    fi
    # THE PARENT IS COMPARED BY IDENTITY WITHOUT RESOLVING IT. `-ef` follows
    # every link and folds case the way the kernel does, so it answers what a
    # `cd -P` and a string compare answered, and neither it nor the parameter
    # expansion forks — every `.md` tail of every word reaches this line.
    ad=${ap%/*}
    [ -n "$ad" ] || continue
    [ -d "$ad" ] || continue
    if [ "$rec" = 1 ] && [ "$ad" -ef "$mdirp" ]; then
      gate_sibling_record_refuse "$a"; return "$GATE_EXIT_RULE"
    fi
    if [ -n "$gdirp" ] && [ "$ad" -ef "$gdirp" ]; then
      gate_sibling_record_refuse "$a"; return "$GATE_EXIT_RULE"
    fi
  done
  if [ "$to_mdir" = 1 ] && [ "$has_rec" = 1 ]; then
    gate_sibling_record_refuse "$mdir"; return "$GATE_EXIT_RULE"
  fi
  if [ "$to_gdir" = 1 ] && [ "$has_md" = 1 ]; then
    gate_sibling_record_refuse "$gdir"; return "$GATE_EXIT_RULE"
  fi
  # THE LINK ITSELF, its target text read from the link's own directory, the
  # way the pacing guard's link arm reads it: `ln -s ../R8.plan.md <dir>/sub/L`
  # names, against the act's directory, no record at all.
  if gate_ln_operands "$@"; then
    for a in "${GATE_LN_OPS[@]}"; do
      for b in "${GATE_LN_BASES[@]}"; do
        case "$a" in
          /*) ap="$a" ;;
          *) case "$b" in
               /*) ap="$b/$a" ;;
               *) ap="$cwd/$b/$a" ;;
             esac ;;
        esac
        i=0
        gate_sibling_target_hit "$ap" "$mdirp" "$gdirp" || i=$?
        if [ "$i" = 0 ]; then
          gate_sibling_record_refuse "ln $a (from $b)"; return "$GATE_EXIT_RULE"
        fi
        if [ "$i" = "$GATE_LEAF_UNRESOLVED" ]; then
          gate_leaf_unresolved_refuse "$a"; return "$GATE_EXIT_RULE"
        fi
      done
    done
  fi
  return 0
}

gate_pace_write_refuse() {
  warn "rule refused: the pacing directory belongs to the lane dispatcher — a stage writing there forges the launch of an unattended run (backlog.jsonl), so no declaration and no auto-resolve admits it (pace root: $2): $1"
}

gate_pace_write_guard() {
  # gate_pace_write_guard <graded-surface> <argv...>
  #
  # THE HOOK CLOSES THE PACING DIRECTORY TO THE EDIT TOOLS ONLY. Its own comment
  # leaves a write through Bash to the gate, and the gate had no arm looking at
  # that directory: measured, `cp x <pace>/backlog.jsonl` declared `트리밖쓰기 /
  # 런로컬` returned 0 and changed the file, with auto-resolve on or off and with
  # `--reach` left out. A backlog record is what the dispatcher launches an
  # unattended run from — a write no stage has a reason to make.
  #
  # THE ROOT IS THE ONE THE GATE PACES BY, IN EVERY SPELLING IT CAN TAKE. The
  # gate reads its verdict from `gate_pace_root` and holds leases under
  # `run_pace_root`; the two read different override variables, so both are
  # needles, each logically and through `gate_real_prefix` — a not-yet-created
  # root or a symlinked state directory (`/var` on this platform) is otherwise a
  # string no argument spells.
  #
  # A READ GRADE RETURNS AT ONCE, so an act that only names the directory while
  # reading it passes — the boundary the sibling record guard keeps. Not keyed on
  # the declared reach or on auto-resolve: neither appears here.
  #
  # Two arms. An interpreter or wrapper's whole command line is the operand, as
  # in the manifest guard's second arm, and is tested by containment of a root
  # spelling. Every other element (and an option's `=` value) is resolved
  # against the act's directory — logically, then through its deepest existing
  # ancestor, because a destination does not exist before it is written —
  # and refused when it is the root or lies under it. A symlinked final
  # component and a `..` after a symlinked directory are followed the way the
  # kernel follows them (`gate_pace_path_hit`), and `ln` is refused when its
  # target, read from the link's own directory, lands in the root
  # (`gate_pace_link_guard`). A program or an argument list taken from a file
  # (`sed -f`, `awk -f`, `xargs -a`, `vim -s`) is refused before either arm,
  # because its destination is in the file (`gate_progfile_opt`). RESIDUAL: a
  # `cd` inside a wrapper, a destination written inside a script or an
  # interpreter's program text, and a link swapped between this check and the
  # act running, are not seen here; the
  # dispatcher runs outside every gate, so nothing legitimate is refused by
  # widening later.
  #
  # A PATH CARRIED INSIDE A LARGER ELEMENT IS A DESTINATION TOO, and the two arms
  # above did not see it. `sed -n 'w <pace>/backlog.jsonl' /dev/null` grades as
  # a worktree write, `dd of=<pace>/rekick/<런>/at` and awk's `> "<path>"` carry
  # the path inside one element that is neither a whole path nor a `-x=` option,
  # and none of those argv0 are wrappers — so all three wrote the file past both
  # arms. A compound element is therefore split into words the way the run
  # directory guard's word arm splits it (`gate_arg_words`), and each word is
  # resolved like a whole element. A word the split cannot resolve (`~-`) is
  # refused rather than guessed, the same as that arm.
  #
  # THE SPLIT WAS NOT THE LAST SPELLING. Measured on the split alone, four
  # more standard ones wrote `backlog.jsonl`: a destination glued to a command
  # letter or option (`sed -n 'w<pace>/backlog.jsonl'`, `sort -o<pace>/…`),
  # which has no separator to split at and is now read apart by
  # `gate_dest_tails`; a case variant (`…/PACE/backlog.jsonl`) on the default
  # case-insensitive volume, now compared case-blind and by identity; and an
  # ANCESTOR of the root named as a directory destination (`cp -R ./pace
  # <state>/cc-cmds/`), which merges a whole replacement tree over the root
  # and is now refused by the run directory guard's ancestor predicate, on the
  # same terms. The value glued to a single-dash option is one of them (`gcp -R
  # ./pace -t<state>/cc-cmds`).
  #
  # THE ANCESTOR ARM ASKS WHERE A DESTINATION SITS, NOT WHAT AN ARGUMENT SPELLS.
  # It first took every element, `=` value and glued option value, and `/` is
  # an ancestor of every root and `$HOME` of the default one — so `awk -F/`,
  # `sort -t/ -o out in`, `xargs -d/`, `git -C $HOME commit` and `npm install
  # --prefix=$HOME` were all refused as pace writes, and on a Linux runner,
  # where the test root lies under `/tmp`, `git -C /tmp commit` failed the
  # suite. An ancestor is only dangerous where a tree is merged over the root or
  # removed with it, so the arm now reads those slots (`gate_pace_dest_slots`):
  # a copy, move, link or install destination and its `-t` value, `tar -C` when
  # extracting, an `rm` operand, and a `find` starting point under `-delete` or
  # `-exec`. An interpreter or wrapper keeps its whole operands and words.
  local graded="$1"; shift
  [ "$#" -ge 1 ] || return 0
  case "$graded" in
    읽기) return 0 ;;
  esac
  # A destination read from a file is not one the arms below can see. This is
  # the arm both verbs reach: `grade` calls this guard and not the sibling one.
  if gate_progfile_opt "$@"; then
    gate_progfile_refuse "pacing directory and every run's kickoff-frozen record"; return "$GATE_EXIT_RULE"
  fi
  local r1 r2 r1p r2p n a v an ap joinedn base first mode i ov gcwd eb inroot rc
  local -a prim names
  r1=$(gate_path_spelling "$(gate_lexical_abs "$(gate_pace_root)")")
  r2=''
  if declare -F run_pace_root >/dev/null 2>&1; then
    r2=$(gate_path_spelling "$(gate_lexical_abs "$(run_pace_root)")")
  fi
  r1p=$(gate_path_spelling "$(gate_real_prefix "$r1")")
  r2p=''
  [ -n "$r2" ] && r2p=$(gate_path_spelling "$(gate_real_prefix "$r2")")
  base="${GATE_ACT_CWD:-}"
  # Once per call, for the fork-free filter of the at-or-under arm: the
  # directory a relative path resolves from, whether that directory itself lies
  # under the root, and the root's final name in each spelling.
  gcwd=$(gate_grade_cwd)
  eb="${base:-$gcwd}"
  inroot=0
  if gate_pace_path_hit "$eb" "$base" "$r1" "$r1p" "$r2" "$r2p"; then inroot=1; fi
  names=()
  for n in "$r1" "$r1p" "$r2" "$r2p"; do
    case "$n" in ''|'/'|'.') continue ;; esac
    names[${#names[@]}]=${n##*/}
  done

  mode=""
  if gate_argv0_wraps "$1"; then
    mode=bare
    joinedn=$(gate_path_spelling "$(printf '%s ' "$@")")
    for n in "$r1" "$r1p" "$r2" "$r2p"; do
      case "$n" in ''|'/'|'.') continue ;; esac
      if gate_nocase_contains "$joinedn" "$n"; then
        gate_pace_write_refuse "$joinedn" "$n"; return "$GATE_EXIT_RULE"
      fi
    done
  fi

  # The ancestor arm: only the slots that merge a tree into a directory or
  # remove one. Behind an interpreter or wrapper the command can start at any
  # word, so every word that names one of those commands starts a reading.
  if [ "$mode" = bare ]; then
    gate_pace_dest_slots 1 "$@"
  else
    gate_pace_dest_slots 0 "$@"
  fi
  for v in ${GATE_PACE_SLOTS[@]+"${GATE_PACE_SLOTS[@]}"}; do
    case "$v" in -*) v="./$v" ;; esac
    rc=0
    gate_pace_ancestor_guard "$v" "$v" "$gcwd" "$r1" "$r1p" "$r2" "$r2p" || rc=$?
    [ "$rc" = 0 ] || return "$rc"
  done

  first=1
  for a in "$@"; do
    # argv0 names what runs, not what is written — the run directory guard's
    # reasoning at the same place.
    if [ "$first" = 1 ]; then first=0; continue; fi
    ov=""
    case "$a" in
      -*=*) ov=$(gate_arg_option_value "$a" 2>/dev/null) || ov="" ;;
    esac
    prim=()
    if ! gate_arg_is_compound "$a"; then prim[${#prim[@]}]=$a; fi
    if [ -n "$ov" ]; then prim[${#prim[@]}]=$ov; fi
    # An interpreter's operand is program text, so a whole one that names an
    # ancestor is refused as its words are below. Its options are not: the
    # destinations an option can carry are the slots read before this loop.
    if [ "$mode" = bare ] && ! gate_arg_is_compound "$a"; then
      case "$a" in
        -*) ;;
        *)
          rc=0
          gate_pace_ancestor_guard "$a" "$a" "$gcwd" "$r1" "$r1p" "$r2" "$r2p" || rc=$?
          [ "$rc" = 0 ] || return "$rc" ;;
      esac
    fi
    if gate_arg_is_compound "$a"; then
      gate_arg_words "$a" "$mode" \
        || { gate_word_unresolved_refuse "$a"; return "$GATE_EXIT_RULE"; }
      i=0
      while [ "$i" -lt "${#GATE_ARG_WORDS[@]}" ]; do
        v=${GATE_ARG_WORDS[$i]}; i=$((i + 1))
        prim[${#prim[@]}]=$v
        # An interpreter's words are destinations, so an ancestor among them
        # is refused as well — the run directory guard's word arm.
        [ "$mode" = bare ] || continue
        rc=0
        gate_pace_ancestor_guard "$a" "$v" "$gcwd" "$r1" "$r1p" "$r2" "$r2p" || rc=$?
        [ "$rc" = 0 ] || return "$rc"
      done
    fi
    # The at-or-under arm: every destination each primary spelling can carry.
    for v in ${prim[@]+"${prim[@]}"}; do
      gate_dest_tails "$v"
      i=0
      while [ "$i" -lt "${#GATE_DEST_TAILS[@]}" ]; do
        n=${GATE_DEST_TAILS[$i]}; i=$((i + 1))
        [ -n "$n" ] || continue
        if [ "$inroot" = 0 ] \
           && ! gate_pace_tail_may_hit "$n" "$eb" ${names[@]+"${names[@]}"}; then
          continue
        fi
        rc=0
        gate_pace_path_hit "$n" "$base" "$r1" "$r1p" "$r2" "$r2p" || rc=$?
        if [ "$rc" = 0 ]; then
          gate_pace_write_refuse "$a" "$GATE_PACE_HIT"; return "$GATE_EXIT_RULE"
        fi
        if [ "$rc" = "$GATE_LEAF_UNRESOLVED" ]; then
          gate_leaf_unresolved_refuse "$a"; return "$GATE_EXIT_RULE"
        fi
      done
    done
  done
  gate_pace_link_guard "$base" "$r1" "$r1p" "$r2" "$r2p" -- "$@"
}

gate_pace_link_guard() {
  # gate_pace_link_guard <base> <root spelling>... -- <argv...> — for `ln`,
  # `GATE_EXIT_RULE` with the refusal said when a link target resolves, from
  # the directory the link is made in, to the pacing root or under it; 0
  # otherwise and for every other argv0.
  #
  # A LINK'S TARGET TEXT IS READ FROM THE LINK'S DIRECTORY, not from the act's.
  # `ln -s ../../../home/…/pace/backlog.jsonl a/b` names, against the worktree,
  # a path that is nowhere near the root, so the at-or-under arm answered no
  # and the next act wrote the backlog through `a/b`. The write itself is now
  # refused by following the link, and this refuses the link in the first
  # place: a stage has no reason to point anything into the dispatcher's
  # directory. The operands and the directories they are read from come from
  # `gate_ln_operands`, which the sibling record guard reads them from too.
  local base="$1" a t rc i
  local -a roots bases ops
  shift
  roots=()
  while [ "$#" -gt 0 ] && [ "$1" != "--" ]; do
    roots[${#roots[@]}]=$1; shift
  done
  [ "$#" -gt 0 ] && shift
  gate_ln_operands "$@" || return 0
  ops=("${GATE_LN_OPS[@]}"); bases=("${GATE_LN_BASES[@]}")
  i=0
  while [ "$i" -lt "${#bases[@]}" ]; do
    bases[$i]=$(gate_lexical_abs "${bases[$i]}" "$base")
    i=$((i + 1))
  done
  for a in "${ops[@]}"; do
    for t in "${bases[@]}"; do
      rc=0
      gate_pace_path_hit "$a" "$t" "${roots[@]}" || rc=$?
      if [ "$rc" = 0 ]; then
        gate_pace_write_refuse "ln $a (from $t)" "$GATE_PACE_HIT"; return "$GATE_EXIT_RULE"
      fi
      if [ "$rc" = "$GATE_LEAF_UNRESOLVED" ]; then
        gate_leaf_unresolved_refuse "$a"; return "$GATE_EXIT_RULE"
      fi
    done
  done
  return 0
}

gate_ln_operands() {
  # gate_ln_operands <argv...> — rc 0 when argv0 is `ln` or `gln` with at least
  # one operand; the operands are left in `GATE_LN_OPS` and the directories a
  # link's target text is read from in `GATE_LN_BASES`, both as spelled.
  #
  # Every operand is tried against the directory of the last operand, against
  # the last operand itself (a directory receives the link inside it) and
  # against a `-t`/`--target-directory` value — the operand that is the source
  # is not told apart from the one that is the link, so both are tried.
  local a last t=""
  GATE_LN_OPS=(); GATE_LN_BASES=()
  [ "$#" -ge 1 ] || return 1
  case "${1##*/}" in
    ln|gln) ;;
    *) return 1 ;;
  esac
  shift
  while [ "$#" -gt 0 ]; do
    a="$1"; shift
    if [ -n "$t" ]; then GATE_LN_BASES[${#GATE_LN_BASES[@]}]=$a; t=""; continue; fi
    case "$a" in
      --target-directory=*) GATE_LN_BASES[${#GATE_LN_BASES[@]}]=${a#*=} ;;
      --target-directory|-t) t=1 ;;
      --) ;;
      -t?*) GATE_LN_BASES[${#GATE_LN_BASES[@]}]=${a#-t} ;;
      -*) ;;
      *) GATE_LN_OPS[${#GATE_LN_OPS[@]}]=$a ;;
    esac
  done
  [ "${#GATE_LN_OPS[@]}" -ge 1 ] || return 1
  last=${GATE_LN_OPS[$((${#GATE_LN_OPS[@]} - 1))]}
  GATE_LN_BASES[${#GATE_LN_BASES[@]}]=$last
  GATE_LN_BASES[${#GATE_LN_BASES[@]}]=$(dirname "$last")
  return 0
}

gate_sibling_target_hit() {
  # gate_sibling_target_hit <absolute path> <manifest dir, physical> <grant dir,
  # physical or empty> — rc 0 when the path, or the file its final link leads
  # to, is a sibling run's frozen record: a record-suffixed name directly in the
  # manifest directory, a `.md` directly in the grant directory, or any `.md`
  # under a `pipeline-grant/` directory. `GATE_LEAF_UNRESOLVED` when the final
  # link is a chain the walk cannot finish; 1 otherwise.
  #
  # The parent is compared with `-d` and `-ef`, which the kernel answers, so a
  # symlinked directory and a `..` after one inside the path resolve the way
  # the write would. Only the final component needs following by hand, and
  # `gate_leaf_spelling` is the walk the pacing guard follows it with — a link
  # to a record that does not exist yet still names it, because the walk stops
  # at the first name that is not a link.
  local p="$1" mp="$2" gp="$3" s d
  for s in "$p" "@leaf"; do
    if [ "$s" = "@leaf" ]; then
      [ -L "$p" ] || return 1
      s=$(gate_leaf_spelling "$p") || return "$GATE_LEAF_UNRESOLVED"
      [ -n "$s" ] || return 1
    fi
    if gate_nocase_glob "/$s" '*/pipeline-grant/*.md'; then return 0; fi
    d=${s%/*}
    [ -n "$d" ] && [ -d "$d" ] || continue
    if gate_record_suffix "$s" && [ "$d" -ef "$mp" ]; then return 0; fi
    if [ -n "$gp" ] && [ "$d" -ef "$gp" ] && gate_nocase_glob "$s" '*.md'; then
      return 0
    fi
  done
  return 1
}

gate_pace_ancestor_guard() {
  # gate_pace_ancestor_guard <element> <word> <grading dir> <root spelling>... —
  # `GATE_EXIT_RULE`, with the refusal said, when the word or a value glued to
  # it as an option is the pacing root or one of its ancestors; 0 otherwise.
  #
  # The ancestor arm of `gate_pace_write_guard`, for a whole element, an
  # option's `=` value and an interpreter's words alike. A single-dash cluster
  # is read through `gate_opt_attached_values`, so `-t<state>/cc-cmds` is
  # judged by its directory; a long option is judged by its `=` value and is
  # not a path otherwise.
  #
  # A NAME THAT CANNOT BE AN ANCESTOR IS NOT RESOLVED. Resolving forks four
  # times, so a word without a `/` goes through only when it is `.`, `..`, a
  # name that exists in the grading directory, or one component of a root
  # spelling — the last because the root and its parents need not exist yet,
  # and `cp -R x cc-cmds` from the state directory creates the tree the root
  # will be read from.
  local a="$1" v="$2" g="$3" w r hit anc; shift 3
  local -a cs
  case "$v" in
    ''|-|--) return 0 ;;
    --*=*) cs=("${v#*=}") ;;
    --*) return 0 ;;
    -?*)
      gate_opt_attached_values "$v"
      cs=(${GATE_OPT_VALUES[@]+"${GATE_OPT_VALUES[@]}"}) ;;
    *) cs=("$v") ;;
  esac
  for w in ${cs[@]+"${cs[@]}"}; do
    case "$w" in
      */*|.|..) ;;
      '') continue ;;
      *)
        if ! gate_arg_bare_name "$w" "$g"; then
          hit=0
          for r in "$@"; do
            [ -n "$r" ] || continue
            if gate_nocase_contains "$r/" "/$w/"; then hit=1; break; fi
          done
          [ "$hit" = 1 ] || continue
        fi ;;
    esac
    anc=0
    gate_word_is_at_or_above "$w" "$@" || anc=$?
    # `<link>/..` names the parent of the link's target, which the lexical
    # fold inside the predicate above cannot see.
    if [ "$anc" = 1 ]; then
      case "/$w/" in
        */../*)
          anc=$(gate_path_spelling "$(gate_physical_dotdot "$w")")
          anc=$(gate_path_spelling "$(gate_real_prefix "$anc")")
          for r in "$@"; do
            [ -n "$r" ] || continue
            if gate_path_is_at_or_above "$anc" "$r"; then
              gate_pace_write_refuse "$a" "$1"; return "$GATE_EXIT_RULE"
            fi
          done
          anc=1 ;;
      esac
    fi
    if [ "$anc" = "$GATE_LEAF_UNRESOLVED" ]; then
      gate_leaf_unresolved_refuse "$a"; return "$GATE_EXIT_RULE"
    fi
    if [ "$anc" = 0 ]; then
      gate_pace_write_refuse "$a" "$1"; return "$GATE_EXIT_RULE"
    fi
  done
  return 0
}

gate_pace_dest_slots() {
  # gate_pace_dest_slots <all: 0|1> <argv...> — the elements of an act that name
  # a directory a tree is merged into or removed from, in `GATE_PACE_SLOTS`, as
  # spelled. With <all> 0 only argv0 starts a reading; with 1 every word whose
  # name is one of the commands below starts one, for a command behind an
  # interpreter or wrapper.
  #
  # `cp`, `mv`, `ln`, `install` (and their `g` forms): the last operand and the
  # `-t`/`--target-directory` value. `rsync`, `ditto`: the last operand —
  # their `-t` is not a directory. `tar` when extracting: the `-C`/`--directory`
  # value. `rm`, `rmdir`: every operand, since removing an ancestor removes the
  # root. `find` with `-delete`, `-exec`, `-execdir`, `-ok` or `-okdir`: the
  # starting points. Over-reading an argument as a slot refuses more; it never
  # admits a write the at-or-under arm would refuse.
  local all="$1" k n
  shift
  GATE_PACE_SLOTS=()
  n=$#
  k=1
  while [ "$k" -le "$n" ]; do
    gate_pace_dest_slots_at "${@:$k}"
    [ "$all" = 1 ] || break
    k=$((k + 1))
  done
  return 0
}

gate_pace_cluster_value() {
  # gate_pace_cluster_value <word> <letter> — rc 0 when the single-dash cluster
  # <word> holds <letter> before any non-letter, with the text after it left in
  # `GATE_PACE_CV` (empty when the value is the next word); rc 1 otherwise.
  local w="$1" l="$2" c
  GATE_PACE_CV=""
  case "$w" in
    --*|-|[!-]*|'') return 1 ;;
  esac
  w=${w#-}
  while [ -n "$w" ]; do
    c=${w%"${w#?}"}
    case "$c" in
      [A-Za-z]) ;;
      *) return 1 ;;
    esac
    w=${w#?}
    if [ "$c" = "$l" ]; then GATE_PACE_CV=$w; return 0; fi
  done
  return 1
}

gate_pace_slot_add() {
  [ -n "$1" ] && GATE_PACE_SLOTS[${#GATE_PACE_SLOTS[@]}]=$1
  return 0
}

gate_pace_dest_slots_at() {
  # gate_pace_dest_slots_at <argv...> — appends to `GATE_PACE_SLOTS` the slots
  # of the one command argv0 names; see `gate_pace_dest_slots`.
  local cmd a last t ddash ex del
  local -a cv sp
  [ "$#" -ge 1 ] || return 0
  cmd=${1##*/}; shift
  last=""; t=""; ddash=0
  case "$cmd" in
    cp|gcp|mv|gmv|ln|gln|install|ginstall|rsync|ditto)
      for a in "$@"; do
        if [ -n "$t" ]; then gate_pace_slot_add "$a"; t=""; continue; fi
        if [ "$ddash" = 1 ]; then last=$a; continue; fi
        case "$a" in
          --) ddash=1 ;;
          --target-directory=*) gate_pace_slot_add "${a#*=}" ;;
          --target-directory) t=1 ;;
          -?*)
            case "$cmd" in rsync|ditto) continue ;; esac
            if gate_pace_cluster_value "$a" t; then
              if [ -n "$GATE_PACE_CV" ]; then gate_pace_slot_add "$GATE_PACE_CV"; else t=1; fi
            fi ;;
          *) last=$a ;;
        esac
      done
      gate_pace_slot_add "$last" ;;
    tar|gtar|bsdtar)
      ex=0; cv=()
      case "${1:-}" in
        -*|'') ;;
        *x*) ex=1 ;;
      esac
      for a in "$@"; do
        if [ -n "$t" ]; then cv[${#cv[@]}]=$a; t=""; continue; fi
        case "$a" in
          -x|--extract|--get) ex=1 ;;
          --directory=*) cv[${#cv[@]}]=${a#*=} ;;
          --directory) t=1 ;;
          --*) ;;
          -?*)
            if gate_pace_cluster_value "$a" x; then ex=1; fi
            if gate_pace_cluster_value "$a" C; then
              if [ -n "$GATE_PACE_CV" ]; then cv[${#cv[@]}]=$GATE_PACE_CV; else t=1; fi
            fi ;;
        esac
      done
      if [ "$ex" = 1 ]; then
        for a in ${cv[@]+"${cv[@]}"}; do gate_pace_slot_add "$a"; done
      fi ;;
    rm|grm|rmdir|grmdir)
      for a in "$@"; do
        if [ "$ddash" = 1 ]; then gate_pace_slot_add "$a"; continue; fi
        case "$a" in
          --) ddash=1 ;;
          -?*) ;;
          *) gate_pace_slot_add "$a" ;;
        esac
      done ;;
    find|gfind)
      sp=(); del=0
      while [ "$#" -gt 0 ]; do
        case "$1" in
          -H|-L|-P|-O*|-E|-X|-s|-x) shift ;;
          -D) shift; [ "$#" -gt 0 ] && shift ;;
          -f) shift; [ "$#" -gt 0 ] && { sp[${#sp[@]}]=$1; shift; } ;;
          *) break ;;
        esac
      done
      while [ "$#" -gt 0 ]; do
        case "$1" in
          -*|'('|'!'|')') break ;;
        esac
        sp[${#sp[@]}]=$1; shift
      done
      for a in "$@"; do
        case "$a" in
          -delete|-exec|-execdir|-ok|-okdir) del=1 ;;
        esac
      done
      if [ "$del" = 1 ]; then
        for a in ${sp[@]+"${sp[@]}"}; do gate_pace_slot_add "$a"; done
      fi ;;
  esac
  return 0
}

gate_pace_path_hit() {
  # gate_pace_path_hit <path> <base> <root spelling>... — rc 0 when the path,
  # resolved against <base> logically and through its deepest existing
  # ancestor, is one of the root spellings or lies under one; the spelling it
  # met is left in `GATE_PACE_HIT`. An empty, `/` or `.` spelling is skipped,
  # because a root that failed to resolve must not turn into a match on
  # everything.
  #
  # Compared as text without regard to case, and by device+inode through the
  # deepest existing ancestor (`gate_path_is_at_or_under`) — the two layers the
  # run directory guard keeps, because a byte test let `…/PACE/backlog.jsonl`
  # overwrite the real file on a case-insensitive volume.
  #
  # A LINK IS FOLLOWED THE WAY THE KERNEL FOLLOWS IT, and the two spellings
  # above did not. `gate_real_prefix` folds only the deepest existing
  # directory, so a final component that is a link to `<pace>/backlog.jsonl`
  # stayed the link's own name; and `gate_lexical_abs` folds `..` as text, so
  # `<link to pace/rekick>/../backlog.jsonl` lost the link before anything
  # looked at it. Measured: `tee -a <link>` and `cp /dev/null
  # <dirlink>/../backlog.jsonl` both wrote the backlog the lane dispatcher
  # launches unattended runs from, with this predicate answering no. The final
  # link is now followed by `gate_leaf_spelling`, as the run directory guard
  # does, and a path carrying `..` is also resolved with each `..` taken from
  # the physical parent (`gate_physical_dotdot`) and its own final link
  # followed. A link chain the walk cannot finish returns
  # `GATE_LEAF_UNRESOLVED`, which the caller refuses.
  local v="$1" base="$2" an ap al ad adl n s; shift 2
  GATE_PACE_HIT=""
  an=$(gate_path_spelling "$(gate_lexical_abs "$v" "$base")")
  ap=$(gate_path_spelling "$(gate_real_prefix "$an")")
  al=$(gate_leaf_spelling "$ap") || return "$GATE_LEAF_UNRESOLVED"
  ad=""; adl=""
  case "/$v/" in
    */../*)
      ad=$(gate_path_spelling "$(gate_physical_dotdot "$v" "$base")")
      ad=$(gate_path_spelling "$(gate_real_prefix "$ad")")
      adl=$(gate_leaf_spelling "$ad") || return "$GATE_LEAF_UNRESOLVED" ;;
  esac
  for n in "$@"; do
    case "$n" in ''|'/'|'.') continue ;; esac
    if gate_nocase_at_or_under "$an" "$n" || gate_nocase_at_or_under "$ap" "$n" \
       || gate_path_is_at_or_under "$ap" "$n"; then
      GATE_PACE_HIT="$n"; return 0
    fi
    for s in "$al" "$ad" "$adl"; do
      [ -n "$s" ] || continue
      if gate_nocase_at_or_under "$s" "$n" || gate_path_is_at_or_under "$s" "$n"; then
        GATE_PACE_HIT="$n"; return 0
      fi
    done
  done
  return 1
}

gate_physical_dotdot() {
  # gate_physical_dotdot <path> [<base>] — the path absolutized against <base>
  # (the grading directory by default) with every `..` taken from the PHYSICAL
  # parent of what precedes it, the way the kernel takes it. Other components
  # stay as spelled; the caller resolves the result's prefix and final link.
  #
  # `gate_lexical_abs` rewinds `..` as text, which is the right answer for a
  # name about to be created and the wrong one after a symlinked directory:
  # `<link>/..` is the parent of the link's TARGET. Each `..` resolves the
  # prefix so far through `gate_real_prefix` (which follows a link to a
  # directory) and drops its last component, so one `cd` per `..` and none for
  # a path without one.
  local p="$1" base="${2:-}" out='' seg d
  [ -n "$base" ] || base=$(gate_grade_cwd)
  case "$p" in
    /*) ;;
    *)  p="$base/$p" ;;
  esac
  while [ -n "$p" ]; do
    seg="${p%%/*}"
    if [ "$seg" = "$p" ]; then p=''; else p="${p#*/}"; fi
    case "$seg" in
      ''|.) ;;
      ..)
        d=$(gate_real_prefix "${out:-/}")
        out="${d%/*}" ;;
      *)  out="$out/$seg" ;;
    esac
  done
  printf '%s' "${out:-/}"
}

gate_autoadopt_ok() {
  # gate_autoadopt_ok <판단 부류> <되돌리는 법> — 0 adopt, non-zero escalate.
  #
  # THE FLOOR IS A UNION AND NOT AN INTERSECTION. Either arm alone admits. Under
  # an intersection even a class the manifest declared in advance would still
  # have to produce an undo command, so the night would stand in front of MORE
  # questions rather than fewer — which inverts what the floor is for.
  #
  # ONE IMPLEMENTATION, TWO CALLERS. The router submits judgments through
  # `act --kind judgment`; a stage has no verb at all and emits its judgment in
  # its terminal message. If the emitted path had its own copy of the floor, that
  # copy is the one that would drift into being the loose one, and a stage would
  # then adopt by emitting — which is this design routed around wholesale rather
  # than one check missed.
  local cls="$1" revert="$2" line mcls
  case "$cls" in '') return 1 ;; esac

  # THE FORBIDDEN CLASSES FALL OUT BEFORE EITHER ARM.
  #
  # `judgment_class_forbidden` had exactly one caller — `check_manifest`'s rule
  # 11 — and that one guards arm (a) only. Arm (b) branches on the argv0 grade
  # of the undo command and nothing else, so `판단 부류=시각-면제` with
  # `되돌리는 법=git checkout -- tests/visual/` was ADOPTED at runtime while
  # declaring the same class in the manifest is a hard stop. The whole mechanical
  # defence of "a decision that hands risk to the user" sat at freeze time, and
  # the runtime path walked around it.
  #
  # The disposition is ESCALATION and not row refusal. Recording a judgment of a
  # forbidden class is allowed by the contract; what is forbidden is adopting one
  # without a person. Returning non-zero routes to
  # `gate_issue_judgment_approval`, and that is what "a person decides this"
  # means here. Placed before both arms so a manifest declaration cannot admit
  # one either — the two guards then agree instead of contradicting.
  if judgment_class_forbidden "$cls"; then
    warn "\`자동 채택\` does not hold — \`${cls}\` is a judgment class that cannot be adopted in advance (a decision that hands risk to the user)"
    warn "this judgment is not refused; it is raised as an approval — recording is allowed, only unattended adoption is forbidden"
    return 1
  fi

  # Arm (a) — declared in advance. What makes this input one a run cannot forge
  # is now stated as what it IS rather than as four claims two of which were
  # false. It holds on three legs: `## 인가` must be exactly one section and this
  # scan reads only that section; the binding digest serializes these rows, so
  # appending one moves the digest and `check_manifest` refuses at the next gate
  # entry; and `gate_manifest_write_guard` refuses an act that writes the
  # manifest at all.
  #
  # The residual is stated rather than papered over: the manifest has no
  # ROLLBACK-proof anchor outside itself — both sides of the digest comparison
  # are read from the same file — so the guarantee is that a write is refused and,
  # failing that, detected at the next act. It is not that a write is impossible.
  if [ -f "$MANIFEST" ]; then
    while IFS= read -r line; do
      [ -n "$line" ] || continue
      mcls=$(printf '%s' "$line" | tr '|' '\n' | sed -n 's/^ *판단 부류=//p' | sed 's/[[:space:]]*$//' | tail -1)
      if [ "$mcls" = "$cls" ]; then
        log "자동 채택 — 팔 (a) 사전 선언 ($cls)"
        return 0
      fi
    done <<EOF
$(manifest_autoadopt_rows)
EOF
  fi

  # Arm (b) — reversible. The undo command's first token goes through the same
  # argv0 grading table every act goes through, so prose lands on `등급 미상`
  # and falls out here. The distinction that buys is between ASSERTING that
  # something is reversible and PRODUCING the thing that reverses it.
  #
  # THE ACCEPTED SET IS THE WORKTREE-WRITE GRADE ALONE, AND `읽기` IS NOT IN IT.
  # A command that reverses something CHANGES something — that is what reversing
  # is. `읽기` was the most permissive arm here while naming the grade with the
  # least power to undo anything: the first row of the grading table reads
  # `cat|ls|find|grep|…` as `읽기`, so `되돌리는 법=ls docs/` admitted a judgment
  # on the strength of an undo that cannot undo. There was no upper bound either,
  # but the upper end is the side an author has no incentive to reach — the
  # cheap, quiet spelling is a read, and it was the one being accepted.
  #
  # The grades above `워크트리쓰기` stay out for the reason they always did: an
  # undo that writes outside the tree or changes external state is not something
  # to adopt without a person, whatever it claims to reverse.
  case "$(gate_revert_surface "$revert")" in
    워크트리쓰기)
      # The second half of arm (b) — the act being at or below the target's
      # cutpoint — is `절단점-준수`'s, and that rule carries a lower order index,
      # so arriving here IS that condition holding.
      log "자동 채택 — 팔 (b) 가역 ($cls · $revert)"
      return 0 ;;
  esac
  warn "\`자동 채택\` does not hold — class '$cls' is not declared by the manifest, and its \`되돌리는 법\` is not a command that reverts the worktree"
  return 1
}

gate_judgment_fields_ok() {
  # gate_judgment_fields_ok <키=값>... — the vocabulary floor for a judgment
  # row. Its caller runs it BEFORE the auto-adoption floor, not after.
  #
  # ORDER IS THE POINT. The floor is consulted on every grade-1 judgment, and a
  # row missing a required field fails it for the wrong reason — arm (a) has no
  # class to match and arm (b) has no undo command to grade — so a MALFORMED row
  # came back as "a person has to answer this", exit 5, with an approval written
  # for a question nobody asked. The most fundamental reason that holds must
  # win, and a missing field is more fundamental than an unmet floor.
  #
  # THE TWO NEW FIELDS ARE REQUIRED AT GRADE 1 AND NOWHERE ELSE. `판단 부류` is
  # what arm (a) of that floor matches on and `되돌리는 법` is what arm (b) grades
  # and what the morning reads as the account of what can be undone, and the
  # floor runs only when the grade is 1. A grade-2 judgment reaches neither floor
  # arm. It does NOT necessarily reach a person: in the default configuration its
  # question is closed by auto-resolution instead, and that resolution adopts only
  # a class inside the vocabulary and outside `JUDGMENT_CLASSES_FORBIDDEN` — so a grade-2
  # judgment submitted without a class is refused there rather than adopted.
  # Demanding the class here would make ESCALATING a decision harder than adopting
  # one, which is the wrong polarity, and it would strand a router mid-run for a
  # field neither of its escalations can use.
  #
  # THAT LAST ARGUMENT HAD A WAY AROUND IT AND NO LONGER CARRIES THE WEIGHT ON ITS
  # OWN. Auto-resolution judges the class only on the submission that OPENS the
  # question; a submission that finds the approval already `승인` never enters it.
  # The approval id is a hash of `기준 — 근거` with no class in it, so a
  # resubmission carrying a class that resolution would have refused reached an
  # answer given about a different one. What makes leaving the field optional here
  # open nothing is that both acting arms now ask, before spending an answer
  # auto-resolution closed, whether THIS submission's class may be adopted with
  # nobody asked.
  local jk jcls jgrade
  jgrade=$(gate_field_of '등급' "$@")
  for jk in '등급' '기준' '근거'; do
    [ -n "$(gate_field_of "${jk}" "$@")" ] \
      || { warn "a judgment row needs \`${jk}\`"; return "$GATE_EXIT_VOCAB"; }
  done
  # The grade vocabulary itself is NOT decided here — `gate_record_row` owns it,
  # and it is the one place that knows what each grade does next. What this
  # function reads the grade for is which fields the row must carry.
  [ "$jgrade" = "1" ] || return 0
  for jk in '되돌리는 법' '판단 부류'; do
    [ -n "$(gate_field_of "${jk}" "$@")" ] \
      || { warn "a judgment row needs \`${jk}\`"; return "$GATE_EXIT_VOCAB"; }
  done
  # `판단 부류` and NOT `자율 승인.kind`. That field has never carried a
  # classification — its declared tokens appear zero times in the artifacts and
  # what does land there is the act kind — and the ledger is append-only, so the
  # rows already written can never be repaired. Arm (a) asks whether the manifest
  # declared this class in advance; on a field that also carries the act kind,
  # one manifest line would pre-adopt every stage dispatch there is.
  jcls=$(gate_field_of '판단 부류' "$@")
  if ! judgment_class_ok "$jcls"; then
    warn "the \`판단 부류\` of the judgment row is out of vocabulary: $jcls — allowed: $JUDGMENT_CLASSES"
    return "$GATE_EXIT_VOCAB"
  fi
  return 0
}

gate_judgment_adoption_row() {
  # gate_judgment_adoption_row <measure|append> <폭> <키=값>... — the one
  # definition of a judgment adoption row (`자율 승인` · `kind=judgment`).
  # `measure` prints the bytes `gate_append` will compare against
  # `GATE_ROW_MAX`; `append` writes the row. Both assemble it from the same
  # loop, so the row that was measured is the row that is written.
  #
  # ONLY THE THREE FREE-TEXT FIELDS ARE NARROWED. `기준`, `근거` and
  # `되돌리는 법` are prose a caller or a stage wrote, and they are what makes a
  # judgment row long; every other field is a fixed token, an id or a class, and
  # passes through in order and byte for byte. With `<폭>` set to `전체` nothing
  # is narrowed at all, so a row that already fits is written exactly as given.
  # Rotated through the positional parameters as `gate_append` does: the
  # interpreter floor is bash 3.2.
  local mode="$1" w="$2" f n_args i=0
  shift 2
  n_args=$#
  while [ "$i" -lt "$n_args" ]; do
    f="$1"; shift; i=$((i + 1))
    if [ "$w" != "전체" ]; then
      case "$f" in
        '기준='*|'근거='*|'되돌리는 법='*) f="${f%%=*}=$(gate_row_safe "${f#*=}" "$w")" ;;
      esac
    fi
    set -- "$@" "$f"
  done
  case "$mode" in
    measure) gate_row_projected_bytes '자율 승인' "$@" ;;
    append)  gate_append '자율 승인' "$@" ;;
    *) warn "gate_judgment_adoption_row: unknown mode '$mode'"; return "$GATE_EXIT_VOCAB" ;;
  esac
}

gate_judgment_adoption_width() {
  # gate_judgment_adoption_width <시작 폭> <키=값>... — print the widest width
  # for the three free-text fields at which the adoption row fits under
  # `GATE_ROW_MAX`, and return 0; return 1 when even the floor of 40 bytes does
  # not fit, which means the overflow is in a field this does not narrow.
  #
  # A FIXED CUT IS NOT A ROW CAP. Three free-text fields cut to 150 bytes each
  # still leave the row to whatever the other fields carry — a long segment id,
  # a long class, a field the caller added — and `gate_append` does not shorten
  # an over-long row, it ends the process. The width is narrowed by 40 a step and
  # measured each time, the way the carried `중단 답` row does it, and the last
  # step lands on 40 exactly whatever the start was. `<시작 폭>` of `전체` first
  # measures the row unnarrowed and starts the descent at 300 only when that
  # does not fit; a numeric start is the widest width a caller allows.
  local w="$1" len
  shift
  if [ "$w" = "전체" ]; then
    len=$(gate_judgment_adoption_row measure 전체 "$@")
    if [ "$len" -le "$GATE_ROW_MAX" ]; then printf '전체'; return 0; fi
    w=300
  fi
  while :; do
    len=$(gate_judgment_adoption_row measure "$w" "$@")
    if [ "$len" -le "$GATE_ROW_MAX" ]; then printf '%s' "$w"; return 0; fi
    [ "$w" -le 40 ] && return 1
    w=$((w - 40))
    [ "$w" -lt 40 ] && w=40
  done
}

gate_notify_segment_park() {
  # gate_notify_segment_park <segment>
  #
  # THE ONLY CHANNEL FOR A STOP NO TERMINAL CLASS CARRIES. The router can read a
  # snapshot and stand a segment down on its own judgment, with no stage-result
  # row in front of it — the stage-side notice cannot see that park and this one
  # can. Nothing in the gate holds segment rows to the router, though, so a stage
  # call reaches this site too; it raises nothing, and below it also leaves
  # nothing.
  #
  # THE OVERLAP IS EXACTLY ONE CASE and the marker settles it: a stage ends as a
  # deliberate park, the stage-side notice fires and leaves a marker named by the
  # segment, and the router then records that same segment as parked. Those are
  # one stop, so this side stays quiet when it finds the marker.
  #
  # THE MARKER IS SHORT-LIVED BY DESIGN and its expiry lives in the segment-row
  # writer, not here: keyed by the segment alone, a marker that outlived the park
  # would make a segment that was unblocked, re-dispatched and parked again read
  # as the same stop, and its second wait for a person would never be announced.
  #
  # THIS SIDE DERIVES NO ATTEMPT NUMBER. A segment row carries no such field —
  # the contract puts it on the stage-result row — and the only existing idiom
  # for deriving one counts ledger rows, which is time-sensitive. Two independent
  # derivations that disagree would give one stop two group keys and spend two of
  # the eight stacking slots on it. With no marker there is no attempt to be had,
  # so the item key carries the segment alone.
  local seg="$1" mk
  if [ -z "${RUN_DIR:-}" ]; then return 0; fi
  mk="$RUN_DIR/notify/park-$seg"
  if [ -f "$mk" ]; then return 0; fi
  if gate_may_raise_banner; then
    # THE MARKER IS WRITTEN ONLY BY A CALL THAT ACTUALLY RAISED THE NOTICE, and
    # being inside the guard is the whole of it. Written above the guard, one
    # stage call — which raises nothing — leaves the marker behind, and the
    # router's own park for that segment then reads it as "one stop, already
    # announced" and stays quiet forever. Nothing carries this class afterwards,
    # so the banner is not delayed by a pass; it is gone.
    mkdir -p "$RUN_DIR/notify" 2>/dev/null || true
    : > "$mk" 2>/dev/null || true
    cc_notify_fire hands \
      "세그먼트 \`$seg\` 가 park 되었습니다 — 아침 보고서의 보류 큐를 보세요" "park-$seg" || true
  fi
  return 0
}

gate_notify_approval() {
  # gate_notify_approval <approval-id> <question>
  #
  # THE CALLER BOUNDARY EARNS ITS KEEP HERE AND ESSENTIALLY NOWHERE ELSE. The
  # stage-result and segment sites are router calls by construction, but an act
  # approval is issued exactly when a STAGE reaches past its pre-authorization,
  # and the boundary approvals are evaluated on every act — so both open under
  # stage calls routinely. A stage-opened approval leaves its row and the watcher
  # carries it one pass later; only a router-opened one appears at once.
  #
  # THE DEDUPLICATION FILE IS THE WATCHER'S, BY NAME, and renaming it is the one
  # move that must not be made here: a plugin update landing mid-run leaves the
  # already-running watcher reading the old name while a fresh gate process
  # writes the new one, and every approval notice then arrives twice. The price
  # of keeping it is that the prefix now lies slightly about who writes the file,
  # which is cheaper than the rename.
  #
  # The id is written to that file ONLY when this seat actually raised the
  # notice. Writing it on a stage call would silence the watcher for an approval
  # nobody had been told about — which is the one route a stage-opened approval
  # has.
  #
  # ONE RACE IS ACCEPTED AND WRITTEN DOWN: a watcher pass overlapping a gate call
  # can leave both blind to the marker and both raising the same notice. The cost
  # is one duplicate banner; the fix would put a lock on the critical path of
  # every act. Recorded here because otherwise a later reader deletes one of the
  # two firing points and restores the delay this whole seat removed.
  local id="$1" q="$2"
  # A SHIFT DOES NOT DECIDE WHETHER A BANNER REACHES THE USER. It was launched
  # by the lead, and a launched process choosing what the user sees is the one
  # thing the notification rules forbid outright. That test used to sit here as a
  # second early return of its own, which is what left the other six firing sites
  # answering the seat question with a predicate that cannot see a shift; it now
  # lives in `gate_may_raise_banner` and this site reads it like every other one.
  #
  # NO BANNER IS LOST BY THIS. The watcher's approval arm fires from its own
  # seat the moment an approval is issued, and the watcher is orphaned to init
  # rather than launched by anyone — so this suppression tidies the seating
  # rather than removing the notice.
  if ! gate_may_raise_banner; then return 0; fi
  if [ -n "${RUN_DIR:-}" ] && [ -d "$RUN_DIR" ]; then
    if ! grep -qxF "$id" "$RUN_DIR/watch.announced-approvals" 2>/dev/null; then
      printf '%s\n' "$id" >> "$RUN_DIR/watch.announced-approvals" 2>/dev/null || true
    fi
  fi
  cc_notify_fire answer "$q" "$id" || true
  return 0
}

gate_notify_overflow_settled() {
  # THE WAITING-SLOT BANNER HAS TO COME DOWN TOO, and nothing was taking it down.
  #
  # An individual approval's notice is addressed by its own id, so closing that
  # approval clears it. The ninth and later arrivals never got an individual
  # address — they were demoted into the one shared waiting slot — so the
  # id-addressed clear at a close site aims at a group that never carried a
  # banner. The result was the exact inversion of what the address was added for:
  # the eight individual notices vanished as they were answered while "there is
  # more to answer — N" stayed on screen alone, telling a person that a run with
  # nothing left to answer still had N waiting.
  #
  # THE CONDITION IS "NOTHING IS WAITING", NOT "THE STACK IS EMPTY". An empty
  # stack means every notice that held an individual seat has been answered, and
  # says nothing about the demoted ones — which may still be open. Clearing on
  # that signal would take down a banner that is telling the truth.
  #
  # AND "NOTHING IS WAITING" IS NOT "NO APPROVAL IS OPEN". That was the first
  # form of this check and it had the same hole one population over: the waiting
  # slot does not hold approvals alone. The stacking branch admits `answer` AND
  # `hands` against one cap and demotes either the same way, so a stop summons
  # can be the thing the slot stands for — and a stop is not an approval row.
  # With approvals as the whole population, the last approval closing took down
  # a banner whose subject was still waiting for a person, and the stop firing
  # points all sit behind once-markers, so it never came back. The slot's own
  # occupants are the population, so this walks them.
  #
  # THE OVERFLOW LIST IS NOT RECLAIMED HERE. Whether a demoted item is ever
  # promoted back into an individual seat is a separate accepted trade-off; this
  # takes a false count off the screen and nothing else.
  #
  # No caller guard on this line: the clear verb carries the seat guard inside
  # itself, which is the whole reason it was put there rather than at call sites.
  local o key
  [ "$(cc_notify_overflow_count)" != "0" ] || return 0
  o="${RUN_DIR:-}/notify.overflow"
  [ -f "$o" ] || return 0
  # Redirected from the file rather than piped, so an early return leaves the
  # function rather than a subshell.
  while IFS= read -r key; do
    [ -n "$key" ] || continue
    if gate_notify_slot_key_alive "$key"; then return 0; fi
  done < "$o"
  cc_notify_clear overflow || true
  return 0
}

gate_notify_slot_key_alive() {
  # gate_notify_slot_key_alive <item-key> — 0 when the thing this key stands for
  # may still be waiting for a person, 1 when it is settled.
  #
  # UNKNOWN MEANS ALIVE. Of the two ways to be wrong, holding a banner that is no
  # longer needed shows a person something stale that one glance corrects, while
  # taking down a banner that is still true removes the only trace the demoted
  # item ever had — nobody can miss a notice that never arrived. So every arm
  # that cannot prove settlement answers "alive".
  local key="$1" seg st row
  case "$key" in
    park-*)
      # `park-<seg>` and `park-<seg>#<attempt>` both resolve to ONE marker file
      # named by the segment alone, which is why the attempt is the marker's
      # contents rather than part of its name. The router expires that marker the
      # moment the segment lands in any state other than park, and that writer is
      # the only one that sees the departure happen — so its absence is the
      # settlement signal and no second bookkeeping is needed.
      seg="${key#park-}"
      seg="${seg%%#*}"
      [ -f "${RUN_DIR:-}/notify/park-$seg" ] && return 0
      return 1 ;;
    stop-*|run-*)
      # NEITHER OF THESE HAS AN EXPIRY PATH. A stop with no artifact writes no
      # marker, and a run-scope anchor's key is a reason slug with nothing that
      # retires it. With no signal that says "settled", the honest answer is the
      # conservative one, and the cost is a waiting-slot banner that outlives its
      # subject rather than one that predeceases it.
      return 0 ;;
  esac
  # Everything else is an approval id — the same last-row-per-id fold the pending
  # census uses, applied to one id.
  row=$( { gate_rows '승인' | grep -F "| 승인 id=$key |" || true; } | tail -1)
  [ -n "$row" ] || return 0
  st=$(gate_row_field "$row" '상태')
  [ "$st" = "대기" ] && return 0
  return 1
}

gate_record_row() {
  # gate_record_row <kind> <segment-id> <target-alias> <키=값>...
  #
  # The alias is a parameter and not a global because two of the arms below
  # issue an approval, and an approval row names the target it blocks.
  #
  # The router's writer for the two row kinds the fixed graph used to own. This
  # is not bookkeeping polish. With no writer on this path `리뷰-후-머지` refuses
  # EVERY merge — not because a review is missing but because the row it reads
  # can never exist, so no argv, no ordering and no preparatory act satisfies it
  # — and termination condition 1 can never hold, so the run has no ending it is
  # able to propose. Both failures read as the mechanism working, which is why
  # the absence stayed invisible until a run tried to finish.
  local kind="$1" seg="$2" alias="$3"; shift 3
  local f k

  # `blocked` is the exception, and it has to be: the row it resolves is
  # run-scope, so demanding a segment would make the one kind that describes the
  # WHOLE run unwritable without naming a part of it. `obligation` is exempt for
  # the opposite reason — it HAS a segment and reads it from the row it closes,
  # so asking the router to name one again only creates a way for the two to
  # disagree. The two obligation-closing kinds are exempt on that same ground and
  # for a sharper version of it: their bundle CROSSES segments, so a segment
  # named in argv would not even have a single right answer to be checked
  # against. `limit-cleared` is a statement about the run's account window, not
  # about a part of the run, so it is exempt on the ground `blocked` is.
  # `reentry` is a boot of the machine the whole run was cut by, so it is too.
  # `shift-halt` checks its own key: a clause's evidence request takes
  # `--segment -` and the arm builds the key, and every other site still
  # refuses a key with no segment row.
  if [ "$kind" != "blocked" ] && [ "$kind" != "clause" ] && [ "$kind" != "judgment" ] \
     && [ "$kind" != "obligation" ] && [ "$kind" != "handoff" ] \
     && [ "$kind" != "obligation-done" ] && [ "$kind" != "obligation-drop" ] \
     && [ "$kind" != "limit-cleared" ] && [ "$kind" != "reentry" ] \
     && [ "$kind" != "shift-halt" ] \
     && { [ -z "$seg" ] || [ "$seg" = "-" ]; }; then
    warn "a $kind row needs --segment"
    return "$GATE_EXIT_VOCAB"
  fi
  # `base-check` takes nothing after `--`: every field of its row is the gate's.
  [ $# -ge 1 ] || [ "$kind" = "base-check" ] || [ "$kind" = "remote-check" ] \
    || { warn "a $kind row carries no fields at all"; return "$GATE_EXIT_VOCAB"; }

  # THE KEY IS CHECKED HERE AND NOT ONLY NORMALIZED IN `gate_append`. The two are
  # not redundant. Normalization rewrites the field silently; this path is the one
  # whose refusal reaches the caller, and a caller that spelled a separator into a
  # field name should be told rather than have the name quietly changed under it.
  # A key carrying a newline is an attempt to append a SECOND row — the row worth
  # forging is a `승인` saying `상태=승인` — and a key carrying a pipe forges a
  # field boundary inside the row it is on. The remaining half of the invariant,
  # that a key holds no `=`, is discharged by the split itself: `%%=*` cuts at the
  # first one, so there is nothing left for a branch here to find.
  #
  # THE NEWLINE IS A LITERAL, because `$(printf '\n')` is the EMPTY STRING —
  # command substitution strips exactly the character this pattern has to hold,
  # and an empty pattern matches every key there is.
  local nl='
'
  for f in "$@"; do
    case "$f" in
      *=*) k="${f%%=*}" ;;
      *) warn "a field of a $kind row has to be \`키=값\`: $f"; return "$GATE_EXIT_VOCAB" ;;
    esac
    case "$k" in
      *"$nl"*|*'|'*)
        warn "a field key of a $kind row cannot carry a newline or a pipe: $k"
        return "$GATE_EXIT_VOCAB" ;;
    esac
  done

  # A KEY IS READ AS EVERY READER TRIMS IT, so it is checked that way too, on
  # EVERY KIND OF ROW. The selectors strip the blanks around a field before
  # matching its key, while `gate_field_of` here matches the argv spelling
  # exactly — so ` 머지 대조=충족` passed the segment row's refusal and was then
  # read as the gate's field, and on a `cycle` row ` P1=0` after `P1=1`, or
  # ` 리뷰 HEAD=<ref>`, was the value the merge comparison and the merge rule
  # read. A key whose trimmed spelling differs from the one written is refused
  # outright, whatever the key and the kind: there is no honest reason to pad a
  # key, and a refusal tells the caller where an accepted row would not.
  # The key is shown with CR and tab spelled out: `printf %q` would escape
  # every Korean byte too, and a raw CR rewinds the line it is printed on.
  local kt kshow
  for f in "$@"; do
    k="${f%%=*}"
    kt="${k#"${k%%[![:space:]]*}"}"
    kt="${kt%"${kt##*[![:space:]]}"}"
    if [ "$kt" != "$k" ]; then
      kshow="${k//$'\r'/\\r}"
      kshow="${kshow//$'\t'/\\t}"
      warn "$kind 행의 필드 키 '${kshow}' 앞뒤에 공백·CR 이 붙어 있습니다 — 키를 공백 없이 다시 씁니다"
      return "$GATE_EXIT_VOCAB"
    fi
  done

  case "$kind" in
    segment)
      # `id` IS THE GATE'S FIELD, carried from `--segment`. A caller's own
      # `id=` rode on the row next to it, and the readers that take the last
      # value then read the row as another segment's — a `머지됨` row written
      # for one segment carried its `머지 대조=충족` onto another and cleared
      # that segment's condition 11.
      for f in "$@"; do
        if [ "${f%%=*}" = 'id' ]; then
          warn "segment 행의 「id」는 게이트가 --segment 에서 싣는 필드입니다 — 호출자가 넘길 수 없습니다"
          return "$GATE_EXIT_VOCAB"
        fi
      done

      local st wt
      st=$(gate_field_of '상태' "$@")
      wt=$(gate_field_of '워크트리' "$@")
      # `적용 준비` is quoted because it is the one state carrying a space, and
      # an unquoted arm would split it into two patterns that match neither.
      case "$st" in
        계획됨|실행중|리뷰중|머지됨|완료|park|'적용 준비') : ;;
        *) warn "the \`상태\` of a segment row is out of vocabulary: ${st:-(none)} — \`계획됨\` \`실행중\` \`리뷰중\` \`머지됨\` \`완료\` \`적용 준비\` \`park\`"
           return "$GATE_EXIT_VOCAB" ;;
      esac
      # `리뷰-후-머지` resolves the branch's current HEAD by entering this value,
      # so a segment row without it turns a merge refusal into one that names a
      # missing worktree instead of the review — the wrong repair at 3am.
      [ -n "$wt" ] || { warn "a segment row needs \`워크트리\`"; return "$GATE_EXIT_VOCAB"; }

      # `출처` IS THE GATE'S. It marks a row copied from an earlier run's
      # ledger or from the manifest's `선행 착지` row, and only the
      # declaration-filled planning act writes it, after checking the merge
      # commit against the base branch. A caller's `출처=` would claim that
      # provenance for a row nothing checked.
      if [ -n "$(gate_field_of '출처' "$@")" ]; then
        warn "segment 행의 「출처」는 게이트가 선행을 들여올 때만 쓰는 필드입니다 — 호출자가 넘길 수 없습니다"
        return "$GATE_EXIT_VOCAB"
      fi
      # `선언 다이제스트` is the gate's too: a later run takes a landing as built
      # to the declaration this digest names, so a caller's value would vouch
      # for a declaration nothing read. Only the declaration-filled act writes it.
      if [ "${GATE_FROM_DECLARATION:-}" != "1" ] && [ -n "$(gate_field_of '선언 다이제스트' "$@")" ]; then
        warn "segment 행의 「선언 다이제스트」는 게이트가 동결 문서에서 계획 행을 채울 때만 쓰는 필드입니다 — 호출자가 넘길 수 없습니다"
        return "$GATE_EXIT_VOCAB"
      fi
      # `머지 순서` is the gate's for the same reason: it holds a merge until
      # the slices it names have landed, so a caller who could write it could
      # also leave it off a row the declaration orders. The declaration-filled
      # act writes it, and later rows carry it forward below.
      if [ "${GATE_FROM_DECLARATION:-}" != "1" ] && [ -n "$(gate_field_of '머지 순서' "$@")" ]; then
        warn "segment 행의 「머지 순서」는 게이트가 동결 문서에서 계획 행을 채울 때만 쓰는 필드입니다 — 호출자가 넘길 수 없습니다"
        return "$GATE_EXIT_VOCAB"
      fi

      # THE APPLY STATES BELONG TO THE APPLY ARM. This arm carries a caller's
      # fields with no allow-list and lets a terminal row skip the worktree
      # check, so without this a router could write `완료` over a segment whose
      # apply never ran and condition 1 would read the run as finished — or
      # write `적용 준비` by hand, which takes the last row off `머지됨` and
      # makes the real apply fail its first precondition. The apply arm calls
      # this same arm with a marker that no argv sets and every entry clears, so
      # only a caller's `act --kind segment` meets the refusal. `적용` is the
      # arm's own field for the same reason: a caller's `적용=` would forge the
      # marker the termination readers count.
      if [ -z "${GATE_APPLY_ARM:-}" ]; then
        if [ -n "$(gate_field_of '적용' "$@")" ]; then
          warn "segment 행의 「적용」은 게이트가 쓰는 필드입니다 — 호출자가 넘길 수 없습니다"
          return "$GATE_EXIT_VOCAB"
        fi
        case "$st" in
          '적용 준비'|완료)
            if gate_segment_owes_apply "$alias" "$seg"; then
              warn "세그먼트 ${seg} 는 적용이 남은 세그먼트입니다 — 「${st}」 는 act --kind apply 만 씁니다"
              return "$GATE_EXIT_VOCAB"
            fi ;;
        esac
      fi

      # `브랜치` IS FILLED ON A NON-TERMINAL ROW THAT LEAVES IT OFF, from the
      # checkout the row names (see `gate_segment_row_branch`), so the record's
      # branch pin does not depend on the caller remembering an optional field.
      # A caller's own `브랜치` is kept as written. The filled field is part of
      # the row and of the projection below.
      case "$st" in
        머지됨|완료|park) ;;
        *)
          if [ -z "$(gate_field_of '브랜치' "$@")" ]; then
            local fill_br
            fill_br=$(gate_segment_row_branch "$alias" "$wt")
            [ -z "$fill_br" ] || set -- "$@" "브랜치=$fill_br"
          fi ;;
      esac

      # A TERMINAL ROW KEEPS THE SEGMENT'S OWN WORKTREE. The merged row reads its
      # tip there to decide whether the review covered the merge, so a row naming
      # another checkout — one still sitting on the old base — recorded `충족`
      # for a merge no review had looked at. The worktree is often gone by the
      # time the merge is recorded, so the two are compared as spelled, and as
      # `pwd -P` resolves them only when both still exist.
      #
      # THE RECORD IS THE SEGMENT'S OWN WORKTREE — the first non-terminal row,
      # written before the segment's first `머지됨` row, that names neither
      # the target's main checkout nor a directory inside a checkout, and that
      # sits on the branch of the first such row carrying `브랜치` — not its
      # last row: the last row is the one a caller writes next, so a `리뷰중`
      # row naming an old checkout moved the record and the merged row then
      # matched it. The router's `계획됨` row naming the main checkout or a
      # directory inside it is skipped, because that is not where the segment
      # worked, and rows naming checkouts of two branches leave no record (see
      # `gate_segment_anchor_worktree`). A later non-terminal row may still
      # name another worktree — the settings derivation follows it — but a
      # terminal row written after it is held to the record. The refusal does
      # not tell the caller to name the record: a record established on the
      # wrong tree is a halt, not a spelling to copy.
      #
      # The apply arm's own terminal rows are not held to it. They name the
      # apply worktree the gate itself pinned to the merge commit, after the
      # `머지됨` row, so no caller chose that path and it cannot move the
      # merge-tip read this pin protects.
      [ -n "${GATE_APPLY_ARM:-}" ] || case "$st" in
        머지됨|완료|park)
          local rec_wt rec_p wt_p
          rec_wt=$(gate_segment_anchor_worktree "$seg" "$alias")
          if [ -n "$rec_wt" ] && [ "$rec_wt" != "$wt" ]; then
            rec_p=$(cd "$rec_wt" 2>/dev/null && pwd -P) || rec_p=""
            wt_p=$(cd "$wt" 2>/dev/null && pwd -P) || wt_p=""
            if [ -z "$rec_p" ] || [ "$rec_p" != "$wt_p" ]; then
              if [ -z "$rec_p" ]; then
                warn "segment 행(상태=${st})의 「워크트리」 $wt 가 이 세그먼트의 기록된 워크트리 $rec_wt 와 다릅니다 — 기록된 디렉터리가 없어 철자로만 비교했습니다. 기록은 첫 머지됨 행 앞에 쓰인 비종단 행 중 메인 체크아웃이 아니고, 존재하는 저장소 디렉터리라면 그 체크아웃의 최상위이며, 「브랜치」 를 실은 첫 행의 브랜치에 있는 첫 행의 워크트리입니다(행들이 두 브랜치의 체크아웃을 대면 기록이 없습니다). 이 세그먼트가 그 트리에서 일했다면 그 트리를 답니다. 기록이 세그먼트가 일하지 않은 트리에 잘못 세워졌다면 다른 체크아웃을 대지 말고 halt 기록을 씁니다"
              else
                warn "segment 행(상태=${st})의 「워크트리」 $wt 가 이 세그먼트의 기록된 워크트리 $rec_wt 와 다릅니다 — 기록은 첫 머지됨 행 앞에 쓰인 비종단 행 중 메인 체크아웃이 아니고, 존재하는 저장소 디렉터리라면 그 체크아웃의 최상위이며, 「브랜치」 를 실은 첫 행의 브랜치에 있는 첫 행의 워크트리입니다(행들이 두 브랜치의 체크아웃을 대면 기록이 없습니다). 이 세그먼트가 그 트리에서 일했다면 그 트리를 답니다. 기록이 세그먼트가 일하지 않은 트리에 잘못 세워졌다면 다른 체크아웃을 대지 말고 halt 기록을 씁니다"
              fi
              return "$GATE_EXIT_VOCAB"
            fi
          fi ;;
      esac

      # `선행` — the declared axis of the cone, and the two floors the ledger can
      # hold on its own. The superset check cannot supply them: it compares the
      # router's cone declaration against the gate's derivation, and `선행` is
      # now an INPUT to that derivation, so declaring narrowly shrinks both sides
      # together and the comparison notices nothing.
      local deps prior prev_deps d nseg
      deps=$(gate_field_of '선행' "$@")
      prior=$(gate_rows 'segment' | gate_rows_field_eq 'id' "$seg" | tail -1)
      nseg=$(gate_segment_count_including "$seg")

      # ABSENCE AND `없음` ARE DIFFERENT THINGS, and write time is the only
      # moment at which the difference exists — read later they are the same
      # empty set. `없음` is a positive statement of independence; a missing
      # field is a writer who did not consider the question. A repository
      # carrying one segment is not asked, because there is nothing there for it
      # to depend on.
      if [ -z "$deps" ] && [ "${nseg:-0}" -ge 2 ]; then
        warn "a segment row in a repo with more than one segment needs \`선행\` — if it is independent, write \`선행=없음\`"
        warn "absence and \`없음\` are not the same: this is the one place where a silent omission turns into a refusal the writer can hear"
        return "$GATE_EXIT_VOCAB"
      fi

      # MONOTONE PER SEGMENT ID. Rows are append-only and the last row wins, so
      # the lie that pays is retroactive — narrowing `선행` AFTER the predecessor
      # parks takes this segment out of the cone. A later row may ADD and may not
      # REMOVE, which is the same polarity every other check here uses.
      # BOTH SIDES THROUGH ONE NORMALIZATION. Comparing a whitespace-stripped
      # haystack against comma-split needles made the floor reject values its
      # own reader accepts, and matched `없음` only as a whole value — see
      # `gate_dep_tokens` for what each of those cost.
      local cur_deps
      cur_deps=$(gate_dep_tokens "$deps")
      if [ -n "$prior" ]; then
        prev_deps=$(gate_dep_tokens "$(gate_row_field "$prior" '선행')")
        for d in $prev_deps; do
          case " $cur_deps " in
            *" $d "*) ;;
            *) warn "\`선행\` is monotone per segment — the '$d' of an earlier row is not on this one (it can be added to, not taken from)"
               return "$GATE_EXIT_VOCAB" ;;
          esac
        done
      fi

      # EVERY TOKEN NAMES A SEGMENT THIS LEDGER KNOWS, checked at write time.
      # `선행` is monotone, so a token that resolves to nothing is not a typo the
      # next row can correct: it is permanently required and permanently
      # un-landable, and the failure surfaces much later as "the predecessor has
      # not landed (상태=없음)", which sends the reader to look for a segment
      # rather than at the spelling. Refusing here lets the message say the true
      # thing — there is no such segment — at the moment it is cheap.
      #
      # A PREDECESSOR AN EARLIER RUN LANDED IS NOT REFUSED HERE, because it is
      # no longer unknown by the time this runs: `--from-declaration` brings its
      # terminal row in from that run's ledger first, or from the manifest's
      # `선행 착지` row. What still arrives here is a token none of the three
      # shows landed, and the message names all three so the reader does not go
      # looking in only one of them.
      local known
      known=" $(gate_segment_ids | tr '\n' ' ') $seg "
      for d in $cur_deps; do
        case "$known" in
          *" $d "*) ;;
          *) warn "the segment \`선행\` names is not in the ledger, and no earlier run ledger of the same document shows it landed: '$d' — such a segment cannot land, and \`선행\` is monotone, so writing this row cannot be undone"
             warn "write the segment row of the preceding segment first, or plan through --from-declaration once an earlier run has merged it, or if there is no dependency write \`선행=없음\`"
             warn "a predecessor that landed outside every run ledger is brought in only from a \`선행 착지\` row the kickoff froze into the manifest — a new run with that row"
             return "$GATE_EXIT_VOCAB" ;;
        esac
      done

      # `머지 순서` — the merge-order predecessors, CARRIED FORWARD AT WRITE
      # TIME like `리뷰 정책` below, and for the same reason: the router's row
      # template does not carry it, so an ordinary state transition would drop
      # the order and the merge check would read nothing. A token this row
      # names in `선행` leaves the carried value — an implementation
      # predecessor is also landed before the merge, so the stronger list
      # absorbs it. The same known-token floor holds, since the field reads a
      # landing just as `선행` does.
      local mo cur_mo prev_mo prev_union cur_union mo_out
      mo=$(gate_field_of '머지 순서' "$@")
      if [ -z "$mo" ] && [ -n "$prior" ]; then
        prev_mo=$(gate_dep_tokens "$(gate_row_field "$prior" '머지 순서')")
        mo_out=""
        for d in $prev_mo; do
          case " $cur_deps " in *" $d "*) continue ;; esac
          mo_out="${mo_out:+$mo_out, }슬라이스 $d"
        done
        [ -z "$mo_out" ] || { mo="$mo_out"; set -- "$@" "머지 순서=$mo"; }
      fi
      # A SLICE THE FROZEN DOCUMENT DECLARES IS NOT YET PLANNED, NOT UNLANDABLE.
      # A merge-order predecessor held back by its own `선행` has no row while
      # this slice is planned, and the refusal stays — the floor is what keeps
      # the order readable — but it must not read like the unknown-token one:
      # a router maps that one to "a new run with a `선행 착지` row", which is
      # false here, since planning the predecessor first is the whole remedy.
      #
      # THE REMEDY IS TO DEFER, AND THE TEXT SAYS SO IN THE SHAPE THE ROUTER
      # CAN DO. "Plan the predecessor first" is not always doable: a predecessor
      # still held back by its own `선행` may not be planned yet either, and
      # then the only thing that works is to leave this slice for a later pass
      # until the predecessor's row appears. So the refusal names the unlanded
      # `선행` of the predecessor when there is one, and in both cases says
      # "defer" rather than "stop". A declared slice whose `레포` names no
      # target of this run cannot be planned here at all, so it is not given
      # this remedy: it falls through to the unknown-token refusal, whose
      # remedy — a `선행 착지` row in a new run — is the true one for it.
      local decl_ids="" d_pre p
      if [ -n "${DOC:-}" ] && grep -qxF '**상태**: 동결됨' "$DOC" 2>/dev/null; then
        decl_ids=" $(slice_ids "$DOC" 2>/dev/null | tr '\n' ' ') "
      fi
      cur_mo=$(gate_dep_tokens "$mo")
      for d in $cur_mo; do
        case "$known" in
          *" $d "*) ;;
          *) case "$decl_ids" in
               *" $d "*)
                 if gate_slice_alias "$d" >/dev/null 2>&1; then
                   d_pre=""
                   for p in $(gate_dep_tokens "$(slice_field "$DOC" "$d" '선행' 2>/dev/null)"); do
                     gate_segment_ever_landed "$p" || d_pre="${d_pre:+$d_pre, }'$p'"
                   done
                   warn "the slice \`머지 순서\` names is declared in the frozen document and has no segment row on this ledger yet: '$d' — this is the order of planning, not a missing landing"
                   if [ -n "$d_pre" ]; then
                     warn "'$d' is held back by its own \`선행\` $d_pre and cannot be planned yet: defer this slice until '$d' has a row, which it gets once that \`선행\` lands — this is a wait, not a stop, and no new run is needed"
                   else
                     warn "defer this slice until '$d' has a row: plan '$d' first and then this slice again — this is a wait, not a stop, and no new run is needed"
                   fi
                   return "$GATE_EXIT_VOCAB"
                 fi ;;
             esac
             warn "the segment \`머지 순서\` names is not in the ledger, and no earlier run ledger of the same document shows it landed: '$d' — such a segment cannot land, so this segment could never merge"
             warn "a predecessor that landed outside every run ledger is brought in only from a \`선행 착지\` row the kickoff froze into the manifest — a new run with that row"
             return "$GATE_EXIT_VOCAB" ;;
        esac
      done
      # THE UNION IS MONOTONE. A token may move from `머지 순서` to `선행` and
      # never leave both: narrowing the union after the predecessor parks would
      # let this segment merge ahead of a slice the declaration ordered first.
      if [ -n "$prior" ]; then
        prev_union="$(gate_dep_tokens "$(gate_row_field "$prior" '선행')") $(gate_dep_tokens "$(gate_row_field "$prior" '머지 순서')")"
        cur_union=" $cur_deps $cur_mo "
        for d in $prev_union; do
          case "$cur_union" in
            *" $d "*) ;;
            *) warn "「선행 ∪ 머지 순서」는 세그먼트마다 단조롭습니다 — 앞선 행의 '$d' 가 이 행에 없습니다(더할 수는 있고 뺄 수는 없습니다)"
               return "$GATE_EXIT_VOCAB" ;;
          esac
        done
      fi

      # `리뷰 정책` — OPTIONAL on this row, and its absence in a LATER row is
      # INHERITANCE and not a reset. The router's row template carries the
      # required fields and not the optional ones, so an ordinary state
      # transition would otherwise erase a value an earlier row carried; every
      # later resolution would then fall to the strict default and nothing on any
      # surface would say why the merge was refused.
      #
      # CARRIED FORWARD AT WRITE TIME rather than folded at read time. A
      # read-time fallback would be a SECOND reader of this series holding a
      # different meaning from the first, and the one that drifts is the one
      # nobody is looking at. Writing it forward also means every row states the
      # policy in force at that moment, so the last row alone answers the
      # question.
      #
      # THE CARRY IS ON THIS FIELD ONLY, and deliberately not on `워크트리`. That
      # one is REQUIRED on every row above, so it cannot be erased in the first
      # place — and putting a required field into an inheritance loop creates a
      # branch that never runs, whose mere existence teaches the next reader that
      # the field is optional. That drifts the writer in the loosening direction,
      # which is worse than the defect the carry exists to fix.
      local rpol rceil rpi rci
      rpol=$(gate_field_of '리뷰 정책' "$@")
      if [ -z "$rpol" ] && [ -n "$prior" ]; then
        rpol=$(gate_row_field "$prior" '리뷰 정책')
        [ -n "$rpol" ] && set -- "$@" "리뷰 정책=$rpol"
      fi
      if [ -n "$rpol" ]; then
        # THE CEILING IS COMPARED BEFORE THE APPEND. The ledger is append-only,
        # so a value admitted here can never be taken back — the whole content of
        # this ordering is that the check precedes the only write on this arm.
        # And exceeding the ceiling is REFUSED, not clamped: a quietly tightened
        # row is indistinguishable from a conservative one.
        rpi=$(review_policy_index "$rpol") || {
          warn "the \`리뷰 정책\` of the segment row is out of vocabulary: '$rpol' — allowed tokens: ${REVIEW_POLICIES}"
          return "$GATE_EXIT_VOCAB"
        }
        rceil=$(target_field "$alias" '리뷰 정책 상한')
        [ -n "$rceil" ] || rceil='선리뷰후머지'
        rci=$(review_policy_index "$rceil") || {
          warn "the \`리뷰 정책 상한\` of target '$alias' is out of vocabulary: '$rceil'"
          return "$GATE_EXIT_VOCAB"
        }
        if [ "$rpi" -gt "$rci" ]; then
          warn "the \`리뷰 정책\` '$rpol' of the segment row exceeds the ceiling '$rceil' of target '$alias' — a ceiling violation is refused, not tightened into place"
          return "$GATE_EXIT_VOCAB"
        fi
        # ONCE THE SEGMENT HAS MERGED, THE POLICY CANNOT LOOSEN. Condition 11
        # holds a segment whose policy resolves to `선리뷰후머지`, and the
        # merged row's `머지 대조` reads `정책 면제` under a looser one, so a
        # row loosening the policy after the merge cleared the hold without
        # any review. What the ceiling allows is choosing a policy BEFORE the
        # segment lands; re-marking a merge already made under
        # `선리뷰후머지` exempts that code after the fact. Three shapes are
        # refused, and tightening or restating the same policy is accepted in
        # all of them:
        #
        #   - a `머지됨` row, always: the merge it records happened under the
        #     previous row's policy (the strict default when there is no
        #     previous row or it names none), and that is the policy the
        #     comparison has to be made under;
        #   - any row once the segment carries `머지 대조`;
        #   - any row once the segment has left planning — an earlier row of
        #     the segment in a state other than `계획됨`, or a `cycle` row of
        #     the segment.
        #
        # THE THIRD SHAPE IS DECIDED BY STATE, NOT BY ASKING WHETHER THE CODE
        # LANDED. Landing used to be asked commit by commit — the recorded
        # worktree's tip, the `커밋` of the segment's rows, the `리뷰 HEAD` of
        # its `cycle` rows — and a merge made outside the gate of a commit no
        # row named was never asked about: an unlanded tip on top of it answered
        # `미착지`, the row was accepted, and the merged row then read `정책 면제`
        # with condition 11 empty. Asking about the segment's whole range needs
        # its fork point, and the gate has nowhere of its own to read that from
        # — every candidate is a value the caller writes. Before execution the
        # segment has no code of its own, so there is nothing to ask about; a
        # planning row that left the policy off while the slice declares a
        # looser one is corrected on the `실행중` row.
        #
        # A DISPATCH ALSO ENDS PLANNING, whatever the rows say. A router can
        # dispatch a stage while every row of the segment still reads `계획됨`
        # — the ledgers carry many segments that went from `계획됨` straight
        # to `리뷰중` or `머지됨` — and the stage leaves code the gate cannot
        # see; a loosening row written after it was accepted and the merged
        # row read `정책 면제`. So a `kind=skill` approval row naming this
        # segment, or a `stage-result` row of this segment, refuses the
        # loosening as an earlier non-`계획됨` row does. The gate's own `exec`
        # rows are not counted: creating the segment's worktree is one, and it
        # comes before the `실행중` row that is the documented place to
        # correct a policy the planning row left off.
        #
        # THE GAP LEFT OPEN: a stage run that never went through this gate —
        # no approval row, no `stage-result` row — leaves nothing to read.
        if [ "$st" = '머지됨' ] || [ -n "$prior" ]; then
          local ppol ppi
          ppol=""
          [ -z "$prior" ] || ppol=$(gate_row_field "$prior" '리뷰 정책')
          ppi=$(review_policy_index "${ppol:-선리뷰후머지}") || ppi=0
          if [ "$rpi" -gt "$ppi" ]; then
            if [ "$st" = '머지됨' ]; then
              warn "segment 행(상태=머지됨)의 「리뷰 정책」 '$rpol' 은 앞 행의 '${ppol:-선리뷰후머지}' 보다 느슨합니다 — 이 머지는 앞 행의 정책 아래서 일어났고, 머지 대조와 종료 조건 11 은 그 정책으로 읽습니다. 정책은 착지 전에 고릅니다"
              return "$GATE_EXIT_VOCAB"
            fi
            if [ -n "$(gate_rows 'segment' | gate_rows_field_eq 'id' "$seg" | gate_rows_having_field '머지 대조')" ]; then
              warn "segment 행의 「리뷰 정책」 '$rpol' 은 앞 행의 '${ppol:-선리뷰후머지}' 보다 느슨합니다 — 머지가 기록된 세그먼트의 리뷰 정책은 느슨하게 바꿀 수 없습니다(종료 조건 11 이 읽는 정책입니다)"
              return "$GATE_EXIT_VOCAB"
            fi
            local lc_late lc_why=""
            lc_late=$(gate_rows 'segment' | gate_rows_field_eq 'id' "$seg" \
                        | tr '|' '\n' | sed -n 's/^ *상태=//p' | sed 's/[[:space:]]*$//' \
                        | { grep -v -x -F '계획됨' || true; } | sed -n 1p)
            if [ -n "$lc_late" ]; then
              lc_why="앞 행에 상태=${lc_late} 가 있습니다"
            elif [ -n "$(gate_rows 'cycle' | gate_rows_field_eq '세그먼트' "$seg")" ]; then
              lc_why="이 세그먼트의 cycle 행이 있습니다"
            elif [ -n "$( { gate_rows '자율 승인'; gate_rows '승인'; } \
                           | gate_rows_field_eq '세그먼트' "$seg" | gate_rows_field_eq 'kind' 'skill')" ]; then
              lc_why="이 세그먼트로 스테이지를 디스패치한 승인 행(kind=skill)이 있습니다"
            elif [ -n "$(gate_rows 'stage-result' | gate_rows_field_eq '세그먼트' "$seg")" ]; then
              lc_why="이 세그먼트의 stage-result 행이 있습니다"
            fi
            if [ -n "$lc_why" ]; then
              warn "segment 행의 「리뷰 정책」 '$rpol' 은 앞 행의 '${ppol:-선리뷰후머지}' 보다 느슨합니다 — ${lc_why}. 정책은 실행 전, 이 세그먼트의 앞 행이 모두 상태=계획됨 이고 cycle 행도 스테이지 디스패치 행(kind=skill 승인, stage-result)도 없을 때만 느슨하게 바꿀 수 있습니다. 실행이 시작된 뒤에는 게이트가 세그먼트의 코드가 베이스에 올라갔는지 가릴 수 없습니다. 앞 행의 정책을 그대로 다시 적습니다(생략하면 이어받습니다)"
              return "$GATE_EXIT_VOCAB"
            fi
          fi
        fi
      fi

      # --- the record of a merge: `머지 대조` and `최종 사이클` ---
      #
      # A `머지됨` row used to be a claim and nothing else. The merge rule is the
      # one place that compares a merge against its review, and it runs only
      # when the merge goes through the gate with the rule on; a merge made any
      # other way reached `상태=머지됨` with no trace of whether the review had
      # closed its findings or had even looked at the merged commit. So the
      # comparison is made HERE, at the row that says the merge happened, and
      # written on that row — unconditionally, whatever `룰 설정` says, because
      # this is an observation and not a refusal. What refuses is termination
      # condition 11, which reads this field and is the half the setting turns
      # off.
      #
      # THE NAMES ARE CHOSEN AGAINST THE READERS OF THIS LEDGER. Neither ends in
      # `세그먼트` or `id` — both are matched as suffixes by readers elsewhere, so
      # such a key would be read as the row's segment or id — and neither is a
      # bare `판정`, which another series already uses with another meaning.
      local rpol_eff="${rpol:-선리뷰후머지}" k
      local mc_field="" fc_field=""

      # THE GATE'S FIELDS ARE THE GATE'S ALONE, in every state. `수렴` is refused
      # with them because it is the cycle-row value of the same derivation, and a
      # segment row carrying it would read as a verdict nothing computed.
      #
      # THE KEY'S PRESENCE IS REFUSED, NOT A NON-EMPTY VALUE. Condition 11 reads
      # the last row carrying `머지 대조` whatever its value, so a later
      # `머지 대조=` was that row and cleared a violation recorded before it.
      for f in "$@"; do
        k="${f%%=*}"
        case "$k" in
          '머지 대조'|'최종 사이클'|'수렴')
            warn "segment 행의 「${k}」는 게이트가 유도해 적는 필드입니다 — 호출자가 넘길 수 없습니다"
            return "$GATE_EXIT_VOCAB" ;;
        esac
      done

      # A LANDED `커밋` ON A `완료` OR `park` ROW IS A MERGE RECORDED UNDER
      # ANOTHER NAME. Condition 11 reads `머지됨` rows, so a segment whose commit
      # is already on the base branch and whose row says `완료` walks past it with
      # no comparison ever made. The two exemptions are the two honest ways to be
      # there: this segment already has a `머지됨` row, or its commit reached the
      # base inside a sibling's merge that is itself on the ledger. This is an
      # acceptance check on the row being written — it does not depend on the
      # policy or on `룰 설정`, and it does not reach back to rows already written.
      local cm_commit
      cm_commit=$(gate_field_of '커밋' "$@")
      case "$st" in
        완료|park)
          if [ -n "$cm_commit" ]; then
            gate_obligation_landing "$alias" "$cm_commit"
            case "$GATE_LANDING_VERDICT" in
              착지)
                if ! gate_segment_landed_exempt "$seg" "$alias" "$cm_commit"; then
                  warn "segment 행의 「커밋」 $cm_commit 이 이미 베이스에 착지해 있습니다 ($GATE_LANDING_WHY) — 상태=${st} 로는 머지 대조 없이 머지를 기록하게 됩니다"
                  warn "머지했으면 상태=머지됨 으로 다시 쓰고, 자기 커밋이 없는 세그먼트이면 「커밋」 을 빼고 다시 씁니다"
                  return "$GATE_EXIT_VOCAB"
                fi ;;
              '판정 불가')
                if [ "$rpol_eff" = '선리뷰후머지' ]; then
                  warn "segment 행의 「커밋」 $cm_commit 의 착지를 판정할 수 없다 — 레포 접근이 돌아온 뒤 다시 쓴다: $GATE_LANDING_WHY"
                  return "$GATE_EXIT_VOCAB"
                fi ;;
            esac
          fi ;;
      esac

      # A `머지됨` ROW WHOSE TIP IS NOT ON THE BASE IS REFUSED, whatever the
      # policy: the row would record a merge that did not happen, and the
      # comparison below would then be made against a commit nothing merged. An
      # unreadable tip is not refused — the row is the record that the merge
      # happened, and the tree is routinely gone by then — and the coverage half
      # then reads `판정 불가`, which condition 11 holds on.
      #
      # THE TIP IS THE SEGMENT'S RECORDED WORKTREE'S — see
      # `gate_segment_anchor_worktree` for which row that is — not the one this
      # row names. The check above already ties the two together; reading the
      # recorded one keeps the comparison on the segment's own tree should that
      # check ever be loosened.
      #
      # A SEGMENT WITH NO SUCH ROW HAS NO RECORD — no non-terminal row before
      # its first merge, only rows naming the main checkout or a directory
      # inside a checkout, no row carrying `브랜치`, or rows naming checkouts of
      # two branches — and its tip is then left unread
      # rather than taken from this row: the caller's worktree is the one value
      # the comparison must not rest on, and the main checkout's HEAD is not
      # what the segment merged. The coverage half then reads `판정 불가` and
      # condition 11 holds. The row is not refused — a true merge claim is
      # accepted, and this one cannot be shown false.
      if [ "$st" = '머지됨' ]; then
        local mtip="" mwt
        mwt=$(gate_segment_anchor_worktree "$seg" "$alias")
        if [ -n "$mwt" ]; then
          mtip=$(gate_worktree_tip "$mwt") || mtip=""
        fi
        if [ -n "$mtip" ]; then
          gate_obligation_landing "$alias" "$mtip"
          if [ "$GATE_LANDING_VERDICT" = '미착지' ]; then
            warn "segment 행이 상태=머지됨 을 적지만 워크트리 팁 $mtip 이 베이스에 착지하지 않았습니다: $GATE_LANDING_WHY"
            return "$GATE_EXIT_VOCAB"
          fi
        fi
        gate_segment_cycle_verdict "$seg" "$alias" "$mtip"
        # A tip the review did not cover may be the renumbering merge of the
        # reviewed HEAD — the one merge whose tree R and its other parent fix
        # without a review. Proved the way the merge act proves it.
        # The other parent has to be the base this segment's latest
        # `베이스 판정` observed, or an ancestor of it: without that base any
        # commit could stand as the other side.
        local mmeta=0 mr mt_seen
        if [ "$GATE_CYCLE_COVER_VERDICT" = '덮지 않는다' ] && [ -n "$mtip" ]; then
          mr=$(gate_commit_in "$mwt" "$(gate_row_field "$(gate_segment_last_cycle_row "$seg")" '리뷰 HEAD')" || true)
          mt_seen=$(gate_row_field "$(gate_base_last_row "$seg")" '베이스')
          if [ -n "$mr" ] && [ "$mr" != "$mtip" ] && [ -n "$mt_seen" ] \
             && gate_meta_resolved "$mwt" "$mr" "$mtip" "$mt_seen"; then mmeta=1; fi
        fi
        mc_field="머지 대조=$(gate_merge_check_value "$rpol_eff" "$GATE_CYCLE_COUNT_VERDICT" "$GATE_CYCLE_COVER_VERDICT" "$mmeta")"
        fc_field="최종 사이클=$GATE_CYCLE_NUMBER"
        set -- "$@" "$mc_field" "$fc_field"
      fi

      # `적용=대기` ON A MERGE THAT STILL OWES ITS APPLY. Whether a segment owes
      # one is derived from the manifest and the frozen declaration, and the
      # shared run-state reader reads the ledger alone — so the judgment is
      # written where both termination readers can see it, and they agree.
      local ap_field=""
      if [ "$st" = "머지됨" ] && gate_segment_owes_apply "$alias" "$seg"; then
        ap_field="적용=대기"
        set -- "$@" "$ap_field"
      fi

      # `선언 다이제스트` ON A LANDING. A later run brings this landing in only
      # when it was built to the declaration the document carries then, and a
      # reconvergence inside this run can widen the declaration after the plan
      # row was written. The declaration the frozen document carries at the
      # landing is the one the work was reviewed against, so the gate stamps
      # it here; a slice the document does not declare gets none.
      local dd_field=""
      case "$st" in
        머지됨|완료)
          if [ -n "${DOC:-}" ] && grep -qxF '**상태**: 동결됨' "$DOC" 2>/dev/null \
             && grep -qxF "$seg" <<<"$(slice_ids "$DOC" 2>/dev/null)"; then
            dd_field="선언 다이제스트=$(slice_decl_digest "$DOC" "$seg")"
            set -- "$@" "$dd_field"
          fi ;;
      esac

      # THE ROW IS PROJECTED BEFORE IT IS WRITTEN, AND REFUSED RATHER THAN
      # TRIMMED. The gate's fields above cannot be dropped to make room: a merged
      # row without its comparison is the gap this record exists to close. So a
      # row over the cap is refused here with the caller field to shorten named,
      # instead of reaching `gate_append`'s cap and dying with the series name
      # alone. The exit code is the one that death gives, so a caller reading
      # codes sees nothing new, and it is not the vocabulary code — resending
      # the same argv cannot fit any better.
      local proj
      proj=$(gate_row_projected_bytes 'segment' "id=$seg" "$@")
      if [ "$proj" -gt "$GATE_ROW_MAX" ]; then
        local f big_k="" big_n=0 fn
        for f in "$@"; do
          [ "$f" = "$mc_field" ] && continue
          [ "$f" = "$fc_field" ] && continue
          [ -n "$ap_field" ] && [ "$f" = "$ap_field" ] && continue
          [ -n "$dd_field" ] && [ "$f" = "$dd_field" ] && continue
          fn=$(printf '%s' "$f" | wc -c | tr -d ' ')
          if [ "$fn" -gt "$big_n" ]; then big_n="$fn"; big_k="${f%%=*}"; fi
        done
        warn "the segment row is over the cap (projected ${proj} > ${GATE_ROW_MAX} bytes) — the longest caller field is \`${big_k}\` (${big_n} bytes): shorten it or move it out to a sidecar and write the row again; the fields the gate writes are not trimmed to make room"
        return 1
      fi

      # A CALLER'S OWN `id=` IS REFUSED at the top of this arm, so the gate's
      # `id` is the only one on the row. `cycle` and `problem` below carry the
      # same shape for `세그먼트=`. The `cycle` arm refuses a caller's
      # `세그먼트=` at record time as well, so only for `problem` does this note
      # still describe an open override.
      #
      # REORDERING MOVES THE HOLE RATHER THAN CLOSING IT, and that is why the
      # obvious repair is not the one to reach for. Readers do not agree on
      # which duplicate wins: this file's three take the LAST value, and
      # `feed.sh` takes the FIRST. Putting the gate's field last would close the
      # override for the readers here and open it for that one. Refusing the
      # caller's field in `gate_record_row` closes it for every reader, which is
      # what this arm now does for `id=`.
      #
      # THE GRAMMAR IS ALSO PINNED, which is the reason to leave the order
      # alone. Fixtures assert this row in two shapes — `교대=<n> | id=<seg>`
      # and `id=<seg> | <first caller field>` — so that the grammar is asserted
      # rather than assumed. One of those pins carries a note saying so; the
      # others are footing that rests on it. Counting them here would go stale
      # the moment one is added, so the shapes are named and the count is not.
      #
      # THE BOUNDARY AND THE RE-DERIVATION HAPPEN HERE, AT THE ROW — and only
      # for the states in which the segment still acts. A `segment` row is the
      # one input of the settings derivation the ledger supplies, so the moment
      # it is written is the moment the authorization surface can move, and
      # this is where the move is recorded: `인가면=<before>→<after>` on the row
      # that caused it. Re-deriving at the next act's prelude, as this used to,
      # ordered the two the wrong way round — the row naming a worktree landed
      # before the settings that admit it, and a sibling's `settings-key` could
      # then report the surface settled with the new worktree still outside it.
      #
      # TERMINAL STATES ARE EXEMPT FROM ALL THREE — the boundary check, the
      # re-derivation and the field. `완료`, `머지됨` and `park` are the states
      # in which nothing acts in the worktree any more, and the worktree is
      # routinely gone by then: a merged segment's tree is removed by the merge,
      # and refusing the row that says so would leave the segment live on the
      # ledger forever. A vanished worktree leaves the settings on the next
      # non-terminal row's re-derivation, because the derivation keeps only
      # directories that exist.
      #
      # NON-TERMINAL STATES ARE REFUSED OUTSIDE THE BOUNDARY, rather than
      # silently widening nothing as the derivation used to do for them. The
      # boundary is the one `gate_path_of_target` states: an absolute path, an
      # existing directory, a common git directory equal to some declared
      # target's. A row that fails it would put the segment's acts in a tree the
      # settings could not admit, and every act from that segment would then be
      # refused with a message naming a directory instead of this row.
      #
      # THE FIELD IS THE GATE'S ALONE. A caller-supplied `인가면=` is refused
      # because the value is a measurement this arm takes, and a row carrying
      # the caller's number would read as a widening that never happened.
      #
      # A BYTE NEITHER THE ROW NOR THE SETTINGS FILE CAN CARRY IS REFUSED, NOT
      # MAPPED. The boundary below is a check on a DIRECTORY — absolute,
      # existing, inside a declared target's common git directory — and a
      # subdirectory of an admitted worktree passes it whatever its name is.
      # The value then travels two ways that read it as TEXT: the row grammar
      # maps a newline to a space and a pipe to a slash, so the ledger can
      # never repeat the name it admitted; and the pending pair hands the raw
      # value to the renderer, which splits the list on newlines and quotes
      # each line. Measured on the shape: `<wt>/x<LF>/Users/ian` rendered as
      # TWO `additionalDirectories` entries, the second one a directory no
      # target declares, and every consumer downstream — the surface digest,
      # the hook, `jq` — accepted the file as well-formed. A double quote or a
      # backslash in the name does the same through the JSON syntax instead of
      # through the line structure. A pipe does it through the ROW instead:
      # `gate_row_body` maps `|` to `/` in every field, so `<wt>/a|b` was
      # admitted by the renderer as `<wt>/a|b` and recorded on the row as
      # `워크트리=<wt>/a/b` — a different directory, one this segment never
      # named, which the next re-derivation read back from the ledger and the
      # merge rule would `cd` into. So the closed set is the one the renderer's
      # JSON string and the row's grammar cannot spell: control bytes
      # (`[:cntrl:]`, which is 0x00–0x1F and 0x7F in the C locale, so a
      # multibyte path is untouched), `"`, `\` and `|`. The renderer escapes
      # as well, so that either half alone still holds — and the row half is
      # asserted as an invariant rather than as a list of bytes: the fixtures
      # compare the `워크트리` the row carries against the entry the settings
      # admit, byte for byte, on every accepted non-terminal row.
      #
      # `tr -d` under `LC_ALL=C` compares BYTES, which is the point: a UTF-8
      # path is made of bytes ≥ 0x80 and none of them is in the set, so a
      # Korean worktree name passes unchanged, and an invalid sequence cannot
      # make the filter fail open the way a locale-aware one might.
      #
      # THE ROW IS NEVER LOST TO THE FIELD. The field is two sha256s, and the
      # row cap is `GATE_ROW_MAX`; a row that would cross it with the field
      # carries `인가면=생략(행 길이)` instead — and if even that crosses, no
      # field at all. The projection uses `gate_row_projected_bytes`, the same
      # ruler `gate_append` measures with, so a row that passes here cannot die
      # there over length. Only this field is relaxed; every other field on the
      # row is the caller's and is measured as written. A failure marker
      # (`인가면=실패(<사유>)`) is short and is never rewritten as `생략(행
      # 길이)` — that spelling means the rewrite happened, and a failure did
      # not — so a marker that would not fit is dropped and the `warn` the arm
      # already emitted is the record.
      #
      # THE FAILURE ARMS LAND ON THE ROW, NOT AS A REFUSAL. A row in one of
      # these states is a state transition the router is recording, and
      # refusing it would lose that transition to a condition — a lock held by
      # a sibling, a render that failed — the router did not cause and cannot
      # repair by re-spelling the row. The row lands with a marker that names
      # the arm, the settings key stays unrecorded so the next non-terminal
      # row from any segment re-derives from the ledger, and the `warn` is on
      # the stage's stderr. What is refused is only what the row itself got
      # wrong: a path the settings could not admit.
      #
      # `settings.lock` IS HELD FROM BEFORE THE RE-DERIVATION UNTIL AFTER THE
      # APPEND. The function used to take and drop it around the render alone,
      # which left the append outside: a sibling segment could take the lock
      # in that gap and render from a ledger that did not yet carry this row,
      # so its list lacked the worktree this row had just admitted. The trap
      # covers `gate_append`'s `die` — a lock left by a dead holder would turn
      # every later re-derivation into a timeout.
      # `강제 표면` is the gate's in every state, beside `인가면`: it is the
      # classifier's count over the declared files, written by the
      # declaration-filled act, and a caller's value would claim — or deny —
      # an enforcement-surface edit nothing screened. The key's presence is
      # refused, an empty value included, as `머지 대조` is above.
      if [ "${GATE_FROM_DECLARATION:-}" != "1" ]; then
        for f in "$@"; do
          if [ "${f%%=*}" = '강제 표면' ]; then
            warn "segment 행의 「강제 표면」은 게이트가 동결 문서의 선언 파일을 분류해 적는 필드입니다 — 호출자가 넘길 수 없습니다"
            return "$GATE_EXIT_VOCAB"
          fi
        done
      fi
      local surf_field="" surf_lk=""
      case "$st" in
        완료|머지됨|park) : ;;
        *)
          if [ -n "$(gate_field_of '인가면' "$@")" ]; then
            warn "segment 행의 「인가면」은 게이트가 재유도 결과로 적는 필드입니다 — 호출자가 넘길 수 없습니다"
            return "$GATE_EXIT_VOCAB"
          fi
          if [ "$wt" != "$(printf '%s' "$wt" | LC_ALL=C tr -d '[:cntrl:]"\\|')" ]; then
            warn "segment 행의 「워크트리」에 큰따옴표·백슬래시·파이프·제어 문자를 담을 수 없습니다: '$(printf '%s' "$wt" | LC_ALL=C tr -d '[:cntrl:]')' — 비종단 상태(${st})의 행은 원장과 인가 목록이 그대로 실을 수 있는 경로만 가리킬 수 있습니다"
            return "$GATE_EXIT_VOCAB"
          fi
          case "$wt" in
            /*) : ;;
            *) warn "segment 행의 「워크트리」는 절대 경로여야 합니다: '$wt'"
               return "$GATE_EXIT_VOCAB" ;;
          esac
          if [ ! -d "$wt" ]; then
            warn "segment 행의 「워크트리」가 존재하지 않음: '$wt' — 비종단 상태(${st})의 행은 실재하는 워크트리만 가리킬 수 있습니다"
            return "$GATE_EXIT_VOCAB"
          fi
          if ! gate_path_of_some_target "$wt"; then
            warn "segment 행의 「워크트리」가 어느 선언 대상의 워크트리도 아닙니다: '$wt' — 공통 git 디렉터리가 매니페스트의 어느 대상 행과도 같지 않습니다"
            return "$GATE_EXIT_VOCAB"
          fi
          if [ -z "${RUN_DIR:-}" ]; then
            warn "인가 디렉터리를 재유도하지 못했습니다 — 런 디렉터리가 없어 인가 목록도 락도 없습니다; 세그먼트 $seg 의 행은 인가면=실패(런 디렉터리 없음) 로 남깁니다"
            surf_field='인가면=실패(런 디렉터리 없음)'
          else
            surf_lk="$RUN_DIR/settings.lock"
            if gate_settings_lock "$surf_lk"; then
              GATE_SETTINGS_LOCK_HELD="$surf_lk"
              surf_field=$(gate_resettle_settings_for_segment "$seg" "$wt")
            else
              warn "인가 디렉터리를 재유도하지 못했습니다 — settings.lock 을 기다리다 시간이 넘었습니다 ($surf_lk); 세그먼트 $seg 의 행은 인가면=실패(락 대기 초과) 로 남기고 워크트리 $wt 는 다음 비종단 segment 행이 다시 유도할 때까지 인가 목록에 오르지 않습니다"
              surf_field='인가면=실패(락 대기 초과)'
            fi
          fi
          if [ -n "$surf_field" ] \
             && [ "$(gate_row_projected_bytes 'segment' "id=$seg" "$@" "$surf_field")" -gt "$GATE_ROW_MAX" ]; then
            case "$surf_field" in
              '인가면=실패('*) surf_field="" ;;
              *) surf_field='인가면=생략(행 길이)' ;;
            esac
            if [ -n "$surf_field" ] \
               && [ "$(gate_row_projected_bytes 'segment' "id=$seg" "$@" "$surf_field")" -gt "$GATE_ROW_MAX" ]; then
              surf_field=""
            fi
          fi
          ;;
      esac
      if [ -n "$surf_field" ]; then
        gate_append 'segment' "id=$seg" "$@" "$surf_field"
      else
        gate_append 'segment' "id=$seg" "$@"
      fi
      # The lock taken above outlives the append and nothing else: released
      # here on the ordinary path, and by `gate_on_exit` when `gate_append`
      # exits the process instead of returning.
      gate_settings_lock_release
      if [ "$st" = "park" ]; then
        gate_notify_segment_park "$seg"
      elif [ -n "${RUN_DIR:-}" ]; then
        # THE PARK MARKER EXPIRES HERE, and this is the only writer that sees it
        # happen. The marker is keyed by the segment id alone, so without an
        # expiry a segment that leaves park and is parked again is read as the
        # same stop and its second wait for a person is swallowed. Any state
        # other than park is that departure.
        rm -f "$RUN_DIR/notify/park-$seg" 2>/dev/null || true
      fi
      log "세그먼트 기록 — $seg ($st)"
      # An adopted segment's planning act brings in the earlier run's open
      # answer to a halt, after the row it belongs to has landed.
      if [ "${GATE_FROM_DECLARATION:-}" = "1" ] && [ "$st" = "계획됨" ] && [ -n "${RUN_DIR:-}" ]; then
        gate_adoption_halt_carry "$seg"
      fi
      ;;
    cycle)
      # The five the merge rule actually reads. A cycle row missing any of them
      # does not fail at write time under the old path either — it fails later,
      # inside the rule, as "the review record has no HEAD", which reads as a
      # broken review rather than as a row this run wrote incompletely.
      #
      # `리포트 경로` JOINED THIS LIST WITH THE RULE THAT READS IT. The rule now
      # opens that file and looks for a findings summary, because a row claiming
      # `P0=0 P1=0` used to pass whatever produced it — including a review stage
      # that died in its first round and left a stub. Requiring the field only on
      # the reading side would put the failure at the merge, hours after the row
      # was written and in a run that can no longer repair it; requiring it here
      # puts the refusal on the call that omitted it, which is the one place a
      # router can still add the field.
      #
      # THE CALLER'S KEYS ARE REFUSED FROM THE ROW READER'S POINT OF VIEW, and
      # before any other check reads them. `gate_field_of` matches a key exactly,
      # but the row reader (`gate_row_field`) drops the spaces in front of a key
      # and takes the LAST value — so a check written against `gate_field_of`
      # passes ` 세그먼트=S2`, a newline- or CR-led `세그먼트=S2` (the append
      # turns both into a space), and ` P0=4` behind a valid `P0=0`, and every
      # one of them is then read back as a field the checks below never saw.
      # Three readers of this row disagree about which `세그먼트` wins — the last
      # value, the first value, and any occurrence — and the only thing that
      # makes them agree on a new row is refusing the second value at write
      # time. So: a key whose spelling changes when its surrounding spaces and
      # tabs are trimmed is refused; `세그먼트` is refused whatever its value,
      # because the gate writes it from `--segment`; and `발견 지문` is refused
      # because it is a field only the gate writes, as are the eleven cause
      # fields beside it — the trigger, the fix path, the previous head, the
      # pinned ref and the seven report-format fields. A refusal writes nothing.
      local ca ck ckt cnl cr ctb
      cnl=$'\n'; cr=$'\r'; ctb=$'\t'
      for ca in "$@"; do
        case "$ca" in *=*) ;; *) continue ;; esac
        ck=${ca%%=*}
        ck=${ck//$cnl/ }
        ck=${ck//$cr/ }
        ckt=${ck#"${ck%%[! $ctb]*}"}
        ckt=${ckt%"${ckt##*[! $ctb]}"}
        if [ "$ck" != "$ckt" ]; then
          warn "키 앞뒤에 공백이 있는 필드는 받지 않는다 — 공백을 지우고 다시 부른다: '${ckt}'"
          return "$GATE_EXIT_VOCAB"
        fi
        case "$ckt" in
          세그먼트)
            warn "\`세그먼트\` 는 게이트가 --segment 로 쓴다 — 이 필드를 빼고 다시 부른다"
            return "$GATE_EXIT_VOCAB" ;;
          '발견 지문'|'리뷰 종결'|계기|'수정 경로'|'앞 HEAD'|'리뷰 HEAD 고정'|'리포트 형식'|항목|비불릿|'앵커 없음'|'태그 밖'|요약|'HEAD 줄')
            warn "\`${ckt}\` 은 게이트만 쓰는 필드다 — 이 필드를 빼고 다시 부른다"
            return "$GATE_EXIT_VOCAB" ;;
        esac
      done
      for k in '사이클' 'P0' 'P1' '리뷰 HEAD' '리포트 경로'; do
        if [ -z "$(gate_field_of "$k" "$@")" ]; then
          # `${k}` and not `$k`: the closing bracket that follows is multibyte,
          # and bash reads its first byte as part of the variable NAME — the
          # lookup then fails as an unbound variable under `set -u`, turning a
          # vocabulary refusal into a bare exit 1 with no message a reader can
          # act on. Measured here, not imagined.
          warn "a cycle row needs \`${k}\`"
          return "$GATE_EXIT_VOCAB"
        fi
      done
      # "NOT EMPTY" IS NOT A SHAPE. The merge rule interpolates this field as a
      # revision expression, so `HEAD`, `@`, a branch name or `HEAD@{0}` all
      # resolve — against the tree the rule is reading at that moment, which is
      # the merged one. A review recorded that way passes the freshness ladder by
      # construction, no matter which tree was actually reviewed.
      #
      # CONSTRAINED AT WRITE TIME AND NOT AT READ TIME. Putting the check in the
      # rule would make a second copy of this vocabulary in a file that already
      # records the two drifting apart, and it would leave rows already on the
      # append-only ledger asserting a review that never happened. Here the value
      # the writer supplies is pinned before anything can read it.
      local rh rh_bad
      rh=$(gate_field_of '리뷰 HEAD' "$@")
      # `case` globbing and `${#rh}` rather than a regex engine, which is the
      # idiom the rest of this file uses and calls no second process.
      case "$rh" in
        *[!0-9a-f]*) rh_bad=1 ;;
        *) rh_bad=0 ;;
      esac
      if [ "$rh_bad" = 1 ] || [ "${#rh}" -lt 7 ] || [ "${#rh}" -gt 40 ]; then
        warn "the \`리뷰 HEAD\` of a cycle row has to be a resolved commit sha — only 7 to 40 lowercase hex characters are accepted: '$rh'"
        return "$GATE_EXIT_VOCAB"
      fi
      # --- DELTA MODE: the basis conditions are refused HERE, at write time ---
      #
      # A `cycle` row may claim `모드=델타` — a review that read only the files
      # changed since this segment's last FULL cycle and re-adjudicated that
      # cycle's P0/P1. The merge rule reads `P0`/`P1` off the newest row without
      # knowing the mode, so everything that makes a delta claim sound has to be
      # true before the row exists: the basis cycle is a real row of this
      # segment, it is itself a full cycle, it is the LATEST full cycle, its
      # review HEAD is an ancestor of this one, and its report is not a stub.
      #
      # ABSENCE READS AS `전체`. Making the field required would refuse every
      # `cycle` write from a shift session assembled from the older wording —
      # the same narrow failure shape as a rule-catalogue deploy. An absent
      # mode is the conservative claim ("no delta is asserted"), and check 8
      # below confirms against the report that the conservative reading is
      # also the true one.
      local cmode cbasis cbasis_n ccyc ccyc_ok eff_mode crow cs csn cm rnx brow brow_full latest bmode bhead wt rc brep delta_repair resolve_repair
      cmode=$(gate_field_of '모드' "$@")
      cbasis=$(gate_field_of '기준 사이클' "$@")
      # Every refusal of a delta row except the mode mismatch carries this
      # tail. Rewriting the row cannot clear those: rewritten as 델타 it meets
      # the same check, rewritten as 전체 it meets check 8 because the report
      # still says 델타. The only repair left is a review the gate accepts.
      delta_repair=" — if a row rewritten to match the review-mode line of the report and the cycle numbers of this segment still meets the same check, the row cannot repair it: re-dispatch the review of this segment as a full review without the three basis flags, and write no cycle row until there is a report the gate accepts"
      resolve_repair=" — the row cannot repair it: re-dispatch the review of this segment as a full review without the three resolution flags, and write no cycle row until there is a report the gate accepts"
      # Check 1 — vocabulary, whenever the field is present at all.
      case "$cmode" in
        ''|전체|델타|해소) ;;
        *) warn "the \`모드\` of a cycle row is out of vocabulary: '$cmode' — \`전체\` \`델타\` \`해소\`"
           return "$GATE_EXIT_VOCAB" ;;
      esac
      eff_mode=${cmode:-전체}
      # Check 2 — a full row asserts no basis; a delta row must name one.
      if [ "$eff_mode" = 전체 ] && [ -n "$cbasis" ]; then
        warn "a cycle row with \`모드=전체\` (or none) cannot carry \`기준 사이클\` — a full review claims no basis: '$cbasis'"
        return "$GATE_EXIT_VOCAB"
      fi
      if [ "$eff_mode" = 델타 ]; then
        # Cycle numbers are compared by INTEGER VALUE everywhere below. A
        # string comparison read `05` and `5` as different cycles in one check
        # and the same cycle in another, so a zero-padded basis was refused as
        # stale by the very number it named.
        case "$cbasis" in
          ''|*[!0-9]*)
            warn "a cycle row with \`모드=델타\` needs a positive integer \`기준 사이클\`: '${cbasis:-(none)}'$delta_repair"
            return "$GATE_EXIT_VOCAB" ;;
        esac
        cbasis_n=$((10#$cbasis))
        if [ "$cbasis_n" -lt 1 ]; then
          warn "a cycle row with \`모드=델타\` needs a positive integer \`기준 사이클\`: '$cbasis'$delta_repair"
          return "$GATE_EXIT_VOCAB"
        fi
        # A delta names an EARLIER cycle. `사이클=5 기준 사이클=5` passed every
        # check below (a commit is its own ancestor), and the row it left was
        # then picked by check 3 as the basis for cycle 5, so check 4 refused
        # every later delta of the segment.
        ccyc=$(gate_field_of '사이클' "$@")
        case "$ccyc" in
          ''|*[!0-9]*) ccyc_ok=0 ;;
          *) if [ "$((10#$ccyc))" -gt "$cbasis_n" ]; then ccyc_ok=1; else ccyc_ok=0; fi ;;
        esac
        if [ "$ccyc_ok" != 1 ]; then
          warn "the \`사이클\` ('$ccyc') of a \`모드=델타\` cycle row has to be an integer greater than \`기준 사이클\` ($cbasis) — a delta cannot take itself or a later cycle as its basis$delta_repair"
          return "$GATE_EXIT_VOCAB"
        fi
        # Checks 3 and 5 share one pass over this segment's cycle rows. FIELD
        # EQUALITY, not `grep -F`: `사이클=1` is a substring of `사이클=10`, so a
        # fixed-string match would find a basis row that does not exist.
        # Several rows with the same number → the last FULL one among them, and
        # the last of them only when none is full. The plain last-row rule let a
        # delta row an older gate accepted under its own number shadow the full
        # row beside it, and check 4 then refused for good.
        brow=''; brow_full=''; latest=0
        while IFS= read -r crow; do
          [ -n "$crow" ] || continue
          [ "$(gate_row_field "$crow" '세그먼트')" = "$seg" ] || continue
          cs=$(gate_row_field "$crow" '사이클')
          case "$cs" in ''|*[!0-9]*) continue ;; esac
          csn=$((10#$cs))
          cm=$(gate_row_field "$crow" '모드'); [ -n "$cm" ] || cm=전체
          if [ "$csn" -eq "$cbasis_n" ]; then
            brow="$crow"
            if [ "$cm" = 전체 ]; then brow_full="$crow"; fi
          fi
          if [ "$cm" = 전체 ] && [ "$csn" -gt "$latest" ]; then latest=$csn; fi
        done <<EOF
$(gate_rows 'cycle')
EOF
        if [ -n "$brow_full" ]; then brow="$brow_full"; fi
        # Check 3 — the basis row exists in THIS segment.
        if [ -z "$brow" ]; then
          warn "there is no cycle row for basis cycle $cbasis in segment $seg$delta_repair"
          return "$GATE_EXIT_VOCAB"
        fi
        # Check 4 — no delta of a delta: an inherited verdict crosses one step.
        bmode=$(gate_row_field "$brow" '모드'); [ -n "$bmode" ] || bmode=전체
        if [ "$bmode" != 전체 ]; then
          warn "basis cycle $cbasis is itself a delta cycle — a delta of a delta is not allowed$delta_repair"
          return "$GATE_EXIT_VOCAB"
        fi
        # Check 5 — the basis is the LATEST full cycle, and the refusal names
        # the one that is.
        if [ "$latest" -ne "$cbasis_n" ]; then
          warn "there is a full cycle more recent than basis cycle $cbasis: $latest — the basis has to be the last full cycle of this segment$delta_repair"
          return "$GATE_EXIT_VOCAB"
        fi
        # Check 6 — ancestry, in the segment's own worktree. `is-ancestor` has
        # THREE answers: exit 0 is "ancestor", exit 1 is "not an ancestor", and
        # exit ≥2 (128 for a missing object) is "cannot tell". Reading the third
        # as the second is fail-open — a sha that resolves to nothing would pass
        # as merely unrelated. A write-time check has no "held" state to park
        # in, so the undecidable case folds to a refusal with its own wording.
        bhead=$(gate_row_field "$brow" '리뷰 HEAD')
        wt=$(gate_segment_worktree "$seg")
        if [ -z "$wt" ] || [ ! -d "$wt" ]; then
          warn "cannot judge the ancestry of basis review HEAD $bhead and review HEAD $rh — there is no segment worktree: '${wt:-(none)}'$delta_repair"
          return "$GATE_EXIT_VOCAB"
        fi
        rc=0
        ( cd "$wt" && git merge-base --is-ancestor "$bhead" "$rh" ) >/dev/null 2>&1 || rc=$?
        case "$rc" in
          0) ;;
          1) warn "basis review HEAD $bhead is not an ancestor of the review HEAD $rh of this row (a rebase or similar) — a delta review does not hold$delta_repair"
             return "$GATE_EXIT_VOCAB" ;;
          *) warn "cannot judge the ancestry of basis review HEAD $bhead and review HEAD $rh (git exit $rc, worktree $wt)$delta_repair"
             return "$GATE_EXIT_VOCAB" ;;
        esac
        # Check 7 — the basis report exists and is not a stub. The anchor is
        # the merge rule's; the rule file is out of reach for this change, so
        # the regex lives in two places and moves together by hand.
        brep=$(gate_report_abs "$(gate_row_field "$brow" '리포트 경로')")
        if [ ! -f "$brep" ] || ! grep -qE '^[-*[:space:]]*\*\*발견 요약\*\*' "$brep"; then
          warn "the report of basis cycle $cbasis is missing, or it has no \`발견 요약\`: $brep$delta_repair"
          return "$GATE_EXIT_VOCAB"
        fi
      fi
      # --- RESOLUTION MODE: a review of what a base resolution added ---
      #
      # `모드=해소` claims a review that read only the commits a resolution of a
      # base conflict added — `HEAD ^B ^T` — with `--remerge-diff`, where B is
      # the `리뷰 HEAD` of the segment's last cycle that is not itself a
      # resolution and T the base the resolution merged. A combined diff hides
      # a side taken whole; the remerge diff shows it. Everything that makes the
      # claim sound is checked before the row exists: B's row is that last
      # non-resolution cycle, B is an ancestor of this review HEAD, and — read
      # off the report's mode line in check 8 — T is a base this segment's
      # `베이스 판정` named, the set is not empty, and every merge in it brings
      # in nothing but T or its history.
      if [ "$eff_mode" = 해소 ]; then
        case "$cbasis" in
          ''|*[!0-9]*)
            warn "a cycle row with \`모드=해소\` needs a positive integer \`기준 사이클\`: '${cbasis:-(none)}'$resolve_repair"
            return "$GATE_EXIT_VOCAB" ;;
        esac
        cbasis_n=$((10#$cbasis))
        ccyc=$(gate_field_of '사이클' "$@")
        case "$ccyc" in
          ''|*[!0-9]*) ccyc_ok=0 ;;
          *) if [ "$((10#$ccyc))" -gt "$cbasis_n" ]; then ccyc_ok=1; else ccyc_ok=0; fi ;;
        esac
        if [ "$ccyc_ok" != 1 ]; then
          warn "the \`사이클\` ('$ccyc') of a \`모드=해소\` cycle row has to be an integer greater than \`기준 사이클\` ($cbasis)$resolve_repair"
          return "$GATE_EXIT_VOCAB"
        fi
        brow=$(gate_base_resolve_basis_row "$seg")
        cs=$(gate_row_field "$brow" '사이클')
        case "$cs" in ''|*[!0-9]*) cs=-1 ;; *) cs=$((10#$cs)) ;; esac
        if [ -z "$brow" ] || [ "$cs" -ne "$cbasis_n" ]; then
          warn "basis cycle $cbasis is not the last cycle of segment $seg that is not a resolution (${cs#-1}) — a resolution review takes that cycle as its basis$resolve_repair"
          return "$GATE_EXIT_VOCAB"
        fi
        bhead=$(gate_row_field "$brow" '리뷰 HEAD')
        wt=$(gate_segment_worktree "$seg")
        if [ -z "$wt" ] || [ ! -d "$wt" ]; then
          warn "cannot judge the ancestry of basis review HEAD $bhead and review HEAD $rh — there is no segment worktree: '${wt:-(none)}'$resolve_repair"
          return "$GATE_EXIT_VOCAB"
        fi
        rc=0
        ( cd "$wt" && git merge-base --is-ancestor "$bhead" "$rh" ) >/dev/null 2>&1 || rc=$?
        case "$rc" in
          0) ;;
          1) warn "basis review HEAD $bhead is not an ancestor of the review HEAD $rh of this row — a resolution review does not hold$resolve_repair"
             return "$GATE_EXIT_VOCAB" ;;
          *) warn "cannot judge the ancestry of basis review HEAD $bhead and review HEAD $rh (git exit $rc, worktree $wt)$resolve_repair"
             return "$GATE_EXIT_VOCAB" ;;
        esac
        # ONLY A SEGMENT WHOSE 다음 READS 해소 리뷰 TAKES ONE. That value stands
        # only when the basis cycle let a merge through and HEAD has since moved
        # past it, so a resolution review never stands in for the re-review of
        # a cycle that asked for a fix: it reads only what came after B, and B's
        # findings are not judged again.
        rnx=$(gate_segment_review_next "$seg")
        if [ "$rnx" != '해소 리뷰' ]; then
          warn "segment $seg reads 다음=$rnx, not 해소 리뷰 — a cycle row with \`모드=해소\` is written only for a HEAD a base resolution moved past a review that let the merge through"
          return "$GATE_EXIT_RULE"
        fi
      fi
      # Check 8 — EVERY row, not only delta rows: the report is the source of
      # the mode and the row must agree with it. The dangerous direction is
      # under-claiming, not over-claiming. A report that says 델타 under a row
      # that stays silent reads as 전체, gets picked as the next cycle's full
      # basis, and a delta then stacks on a review that read part of the tree.
      # Both absent read as the same 전체, so no row written before this field
      # existed is refused by it. Rewriting the row to what the report says
      # repairs the MODE mismatch only; the basis-number and basis-head
      # refusals below stand however the row is rewritten, so they carry the
      # re-review tail instead.
      #
      # ONE LINE IS ANCHORED FIRST and the values are read off that line only,
      # so the same phrase somewhere in the report body cannot be picked up.
      # POSIX ERE throughout: `\b` is unreliable under macOS libc regcomp and
      # BRE `\|` is a GNU extension, both of which the portability lint names.
      # `awk 'NR==1'` and not `head -1`: the first line is wanted, but an
      # early-exiting reader on the right of a pipe is the pipefail trap this
      # tree's suite refuses, and `awk` reads to the end.
      local rep line rmode rcyc rhead rbase r1 r2 rt rset rbad
      rep=$(gate_report_abs "$(gate_field_of '리포트 경로' "$@")")
      if [ -f "$rep" ]; then
        line=$({ grep -E '^[-*[:space:]]*\*\*리뷰 모드\*\*: (전체|델타|해소)( |$)' "$rep" || true; } | awk 'NR==1')
        rmode=$(printf '%s\n' "$line" | sed -E -n 's/^[-*[:space:]]*\*\*리뷰 모드\*\*: (전체|델타|해소).*/\1/p')
        [ -n "$rmode" ] || rmode=전체
        if [ "$rmode" != "$eff_mode" ]; then
          warn "the mode ($eff_mode) of the cycle row differs from the review mode ($rmode) of the report — rewrite the row with the mode the report states: $rep"
          return "$GATE_EXIT_VOCAB"
        fi
        if [ "$eff_mode" = 델타 ]; then
          rcyc=$(printf '%s\n' "$line" | sed -E -n 's/.*기준 사이클 ([0-9]+).*/\1/p')
          rhead=$(printf '%s\n' "$line" | sed -E -n 's/.*기준 리뷰 HEAD `([0-9a-f]+)`.*/\1/p')
          if [ -z "$rcyc" ] || [ "$((10#$rcyc))" -ne "$cbasis_n" ]; then
            warn "the basis cycle (${rcyc:-(none)}) of the report differs from the basis cycle ($cbasis) of the row: $rep$delta_repair"
            return "$GATE_EXIT_VOCAB"
          fi
          # Short and long shas may be mixed between the row and the report;
          # both are resolved to a commit and the COMMITS are compared.
          r1=$(cd "$wt" && git rev-parse --verify "${rhead}^{commit}" 2>/dev/null || true)
          r2=$(cd "$wt" && git rev-parse --verify "${bhead}^{commit}" 2>/dev/null || true)
          if [ -z "$r1" ] || [ -z "$r2" ]; then
            warn "cannot resolve the basis review HEAD (${rhead:-(none)}) of the report and the review HEAD ($bhead) of the basis row — cannot judge: $rep$delta_repair"
            return "$GATE_EXIT_VOCAB"
          fi
          if [ "$r1" != "$r2" ]; then
            warn "the basis review HEAD ($rhead) of the report is not the same commit as the review HEAD ($bhead) of the basis row: $rep$delta_repair"
            return "$GATE_EXIT_VOCAB"
          fi
        fi
        if [ "$eff_mode" = 해소 ]; then
          rcyc=$(printf '%s\n' "$line" | sed -E -n 's/.*기준 사이클 ([0-9]+).*/\1/p')
          rhead=$(printf '%s\n' "$line" | sed -E -n 's/.*기준 리뷰 HEAD `([0-9a-f]+)`.*/\1/p')
          rbase=$(printf '%s\n' "$line" | sed -E -n 's/.*베이스 `([0-9a-f]+)`.*/\1/p')
          if [ -z "$rcyc" ] || [ "$((10#$rcyc))" -ne "$cbasis_n" ]; then
            warn "the basis cycle (${rcyc:-(none)}) of the report differs from the basis cycle ($cbasis) of the row: $rep$resolve_repair"
            return "$GATE_EXIT_VOCAB"
          fi
          r1=$(gate_commit_in "$wt" "$rhead" || true)
          r2=$(gate_commit_in "$wt" "$bhead" || true)
          if [ -z "$r1" ] || [ "$r1" != "$r2" ]; then
            warn "the basis review HEAD (${rhead:-(none)}) of the report is not the commit of the basis row's review HEAD ($bhead): $rep$resolve_repair"
            return "$GATE_EXIT_VOCAB"
          fi
          rt=$(gate_commit_in "$wt" "$rbase" || true)
          if [ -z "$rt" ]; then
            warn "the base (${rbase:-(none)}) on the report's review-mode line does not resolve in $wt: $rep$resolve_repair"
            return "$GATE_EXIT_VOCAB"
          fi
          # T IS A BASE THE GATE OBSERVED. A resolution review reads `^T`, so a
          # T the caller chose would cut any commit it liked out of the review.
          if [ -z "$(gate_base_rows "$seg" | gate_rows_field_values '베이스' | while IFS= read -r c; do
                       [ "$(gate_commit_in "$wt" "$c" || true)" = "$rt" ] && { printf y; break; }
                     done || true)" ]; then
            warn "the base $rbase on the report's review-mode line is not one a \`베이스 판정\` row of $seg named — a resolution review reviews against a base the gate observed: $rep$resolve_repair"
            return "$GATE_EXIT_VOCAB"
          fi
          rset=$( (cd "$wt" && git rev-list "$rh" "^$r1" "^$rt") 2>/dev/null) || rset=''
          if [ -z "$rset" ]; then
            warn "there is no commit in $rh ^$r1 ^$rt — a resolution review has nothing to read: $rep$resolve_repair"
            return "$GATE_EXIT_VOCAB"
          fi
          # Every merge in the set brings in the base and nothing else: a parent
          # other than the first that is not T or its history would put another
          # branch's commits past a review that reads only this set's remerge.
          rbad=$( (cd "$wt" && git rev-list --merges --parents "$rh" "^$r1" "^$rt") 2>/dev/null \
                  | while read -r _m _p1 rest; do
                      for c in $rest; do
                        (cd "$wt" && git merge-base --is-ancestor "$c" "$rt") >/dev/null 2>&1 || printf '%s ' "$c"
                      done
                    done || true)
          if [ -n "$rbad" ]; then
            warn "a merge in $rh ^$r1 ^$rt brings in ${rbad% } — not the base $rt or its history: $rep$resolve_repair"
            return "$GATE_EXIT_VOCAB"
          fi
        fi
      elif [ "$eff_mode" = 해소 ]; then
        warn "cannot open the report of a cycle row with \`모드=해소\`: $rep$resolve_repair"
        return "$GATE_EXIT_VOCAB"
      elif [ "$eff_mode" = 델타 ]; then
        # A full row whose report cannot be opened passes here — no new refusal
        # on the existing path; the merge rule already catches the absence at
        # merge time. A delta row has nothing to back its claim without it.
        warn "cannot open the report of a cycle row with \`모드=델타\`: $rep$delta_repair"
        return "$GATE_EXIT_VOCAB"
      fi
      # Checks 9 to 11 — A DEFECT THAT MAKES THE COUNT ITSELF WRONG IS REFUSED;
      # a classification defect is not. A report that cannot be classified only
      # falls back to `다음=수정`, but a row whose numbers differ from its report,
      # or a report that dropped a P1 from the count into a slice that does not
      # own it, would feed the merge rule a count no review made.
      #
      # Check 9 compares NUMBERS only, never item counts: an item count disagrees
      # with legitimate reports in either item shape. It is skipped when the
      # summary line cannot be read or is the recovery head. Checks 10 and 11
      # read the other-slice section, the one place a review drops a P1 from the
      # count, which is why they run at record time.
      local rcounts rsum rv cv aid arow
      if [ -f "$rep" ] && rcounts=$(gate_review_report_counts "$rep"); then
        rsum=$(gate_report_count "$rcounts" '요약')
        if [ "$rsum" = "정규" ]; then
          for k in P0 P1; do
            rv=$(gate_report_count "$rcounts" "$k"); cv=$(gate_field_of "$k" "$@")
            case "$cv" in
              ''|*[!0-9]*) cv='x' ;;
              *) cv=$((10#$cv)) ;;
            esac
            if [ "$cv" != "$rv" ]; then
              warn "the \`${k}\` of the cycle row ($(gate_field_of "$k" "$@")) differs from the first \`발견 요약\` line of its report ($rv) — write the row with the report's numbers: $rep"
              return "$GATE_EXIT_VOCAB"
            fi
          done
        fi
        if [ "$(gate_report_count "$rcounts" '몫 항목')" != "$(gate_report_count "$rcounts" '몫')" ]; then
          warn "the other-slice section of the report has $(gate_report_count "$rcounts" '몫 항목') item(s) but its \`다른 슬라이스 몫\` line reads '$(gate_report_count "$rcounts" '몫')' — the count the review dropped is not the count it lists: $rep"
          return "$GATE_EXIT_VOCAB"
        fi
        # EVERY ITEM IS CHECKED, NOT EVERY ASSIGNMENT THE PARSER CAUGHT. An item
        # whose `배정` line is missing, doubled or written at another indent
        # would otherwise be dropped from the count with nothing below looking
        # at it.
        if [ "$(gate_report_count "$rcounts" '몫 배정')" != "정규" ]; then
          warn "an item of the other-slice section does not carry exactly one \`    - **배정**: 슬라이스 <id>\` line (four spaces, one per item) — an item with no readable assignment cannot be dropped from the count. Dispatch the review of $seg again without --slice: $rep"
          return "$GATE_EXIT_VOCAB"
        fi
        # ONLY A SLICE STILL TO LAND OWNS A FINDING. A slice that is merged,
        # done, parked or ready to apply will not take the finding up, so the
        # P1 would leave the count for nobody. The review is not told which
        # slices have landed, so the refusal names the way out: review again
        # without `--slice`, which counts every finding of this segment.
        local ast
        while IFS= read -r aid; do
          [ -n "$aid" ] || continue
          arow=$(gate_segment_last_segment_row "$aid")
          ast=$(gate_row_field "$arow" '상태')
          case "$ast" in 계획됨|실행중|리뷰중) ;; *) ast='' ;; esac
          if [ "$aid" = "$seg" ] || [ -z "$arow" ] || [ -z "$ast" ]; then
            warn "the other-slice section assigns an item to slice '$aid', which is not another segment of this run still to land (계획됨·실행중·리뷰중) — a finding of this segment, of a landed or parked slice or of no slice is counted here. Dispatch the review of $seg again without --slice: $rep"
            return "$GATE_EXIT_VOCAB"
          fi
        done <<EOF
$(printf '%s\n' "$rcounts" | sed -n 's/^배정=//p')
EOF
      fi
      # NO LONGER DEFERRED FOR THIS ARM. The `segment` arm still leaves its
      # caller's `id=` free to win, but a caller's `세그먼트=` never reaches this
      # line: the refusal at the top of the arm rejects it in every spelling the
      # row reader would read, so the gate's value in front is the only one.
      #
      # The gate now also writes one field of its own BEHIND the caller's:
      # `발견 지문`, computed from the report check 8 already resolved into
      # `$rep`. Behind, because the row reader takes the last value — in front,
      # a caller's value would win. The refusal at the top still rejects a
      # caller's `발견 지문`, so here the position is a second defence, not the
      # only one.
      #
      # ONE STEP OF DEGRADATION AT THE CAP, NOT TWO. A row that would cross
      # `GATE_ROW_MAX` with the field is written without it and warns once. The
      # `segment` arm swaps its field for a marker first; this arm has no marker
      # because an absent key already reads exactly like "no fingerprint", and a
      # marker would be longer than the 12-byte value it replaces. Without this
      # step a long cycle row that is legal today — a review already paid for —
      # would turn into a refused write.
      #
      # `리뷰 종결` GOES LAST, behind the fingerprint: `다음` as it reads once
      # this row is the segment's last, so the ledger says why each review
      # ended the loop or did not. It is derived from the row's own counts and
      # the rows before it, and the fingerprint is computed from the report
      # alone, so the field never enters it. A row still over the cap without
      # the fingerprint drops this field too, with its own warning.
      # THE REPORT IS THE CANONICAL ONE OF THIS CYCLE. `gate_review_report_path`
      # numbers a segment's reports by its `cycle` rows, so this row's report is
      # that path, or a re-dispatch's `-r<k>` (k ≥ 2) beside it. Any other path
      # is refused here, the last refusal before anything is written: a report
      # at another path may be another review's, overwritten or never read.
      local rp_want rp_got rp_k
      rp_want=$(gate_report_norm "$(gate_review_report_path "$seg")")
      rp_got=$(gate_report_norm "$rep")
      if [ "$rp_got" != "$rp_want" ]; then
        rp_k=${rp_got#"${rp_want%.md}-r"}; rp_k=${rp_k%.md}
        case "$rp_got" in
          "${rp_want%.md}-r"*.md) ;;
          *) rp_k='' ;;
        esac
        case "$rp_k" in
          ''|*[!0-9]*|0*) rp_k='' ;;
        esac
        if [ -z "$rp_k" ] || [ "$rp_k" -lt 2 ]; then
          warn "the \`리포트 경로\` of the cycle row ($rp_got) is not the canonical report of this cycle ($rp_want, or its -r<k> re-dispatch with k ≥ 2) — record the report the review wrote at the path \`gate.sh review-line\` printed"
          return "$GATE_EXIT_VOCAB"
        fi
      fi
      # THE CAUSE FIELDS — written by the gate, behind the caller's and in front
      # of `발견 지문`, every value a closed word or a number. None refuses the
      # row: they record why this review ran, what changed the tree since the
      # last one, how its head stands to that one's and how the report is
      # shaped, and they are computed against the segment's last `cycle` row
      # before this one becomes it. `앞 HEAD` is read whatever the mode — the
      # delta and resolution checks above keep their own worktree demand.
      local c_trig c_fix c_prev c_fmt c_pin c_wt c_fx=()
      c_trig=$(gate_cycle_trigger_of "$seg" "$rep")
      c_fix=$(gate_cycle_fix_path "$seg" "$rh")
      c_wt=$(gate_segment_worktree "$seg")
      c_prev=$(gate_cycle_prev_head "$seg" "$c_wt" "$rh")
      c_fmt=$(gate_report_format_fields "$rep" "$rh")
      # THE REVIEWED COMMIT IS PINNED LAST, after every refusal: a refused row
      # leaves no ref behind.
      c_pin=$(gate_cycle_pin_review_head "$seg" "$rh")
      c_fx=("계기=$c_trig" "수정 경로=$c_fix" "앞 HEAD=$c_prev" "리뷰 HEAD 고정=$c_pin")
      while IFS= read -r ca; do
        [ -n "$ca" ] && c_fx+=("$ca")
      done <<EOF
$c_fmt
EOF
      local fp rc_end crow_new
      fp=$(gate_cycle_fingerprint "$rep" "$(gate_field_of 'P0' "$@")" "$(gate_field_of 'P1' "$@")")
      crow_new="- \`cycle\` | 세그먼트=$seg$(printf ' | %s' "$@")"
      rc_end=$(gate_cycle_review_closure "$seg" "$crow_new")
      if [ "$(gate_row_projected_bytes 'cycle' "세그먼트=$seg" "$@" "${c_fx[@]}" "발견 지문=$fp" "리뷰 종결=$rc_end")" -le "$GATE_ROW_MAX" ]; then
        gate_append 'cycle' "세그먼트=$seg" "$@" "${c_fx[@]}" "발견 지문=$fp" "리뷰 종결=$rc_end"
      elif [ "$(gate_row_projected_bytes 'cycle' "세그먼트=$seg" "$@" "${c_fx[@]}" "리뷰 종결=$rc_end")" -le "$GATE_ROW_MAX" ]; then
        warn "cycle 행이 상한을 넘어 「발견 지문」 을 빼고 기록합니다 — 세그먼트 $seg, 사이클 $(gate_field_of '사이클' "$@")"
        gate_append 'cycle' "세그먼트=$seg" "$@" "${c_fx[@]}" "리뷰 종결=$rc_end"
      else
        warn "cycle 행이 상한을 넘어 「발견 지문」 과 「리뷰 종결」 을 빼고 기록합니다 — 세그먼트 $seg, 사이클 $(gate_field_of '사이클' "$@")"
        gate_append 'cycle' "세그먼트=$seg" "$@" "${c_fx[@]}"
      fi
      log "리뷰 사이클 기록 — $seg"
      ;;
    problem)
      # The row every open obligation is derived from. With no writer,
      # `gate_open_obligations` read an empty set and termination condition 3 —
      # "obligations are empty or excused" — held vacuously on every run, while
      # the narrow excuse rule beside it could never be reached at all.
      #
      # `동일성` is the key those readers group by, and `생성 등급` is what the
      # excuse rule reads, so both are required: a row missing either produces an
      # obligation that can never be closed and never be excused.
      for k in '동일성' '현재 단' '생성 등급'; do
        if [ -z "$(gate_field_of "$k" "$@")" ]; then
          warn "a problem row needs \`${k}\`"
          return "$GATE_EXIT_VOCAB"
        fi
      done
      # SAME DEFERRED DECISION AS THE `segment` ARM ABOVE, for `세그먼트` rather
      # than `id`.
      gate_append 'problem' "세그먼트=$seg" "$@"
      log "문제 기록 — $seg"
      ;;
    clause)
      # SETTLING ONE AUTHORIZED TERMINATION CLAUSE. The manifest holds the
      # question and this row holds the answer, so condition 10 can be decided
      # from the ledger rather than from a rationale's wording.
      local cid cst
      cid=$(gate_field_of 'id' "$@")
      cst=$(gate_field_of '상태' "$@")
      [ -n "$cid" ] || { warn "a termination-clause row needs \`id\`"; return "$GATE_EXIT_VOCAB"; }
      case " $(gate_clause_ids | tr '\n' ' ') " in
        *" $cid "*) : ;;
        *) warn "this termination clause is not in the manifest: ${cid}"; return "$GATE_EXIT_VOCAB" ;;
      esac
      case "$cst" in
        충족|불가능) : ;;
        보류)
          # A CLAUSE HANDED TO THE NEXT RUN, and its disposition is not
          # `불가능`'s. Impossible ends the clause forever; on hold says a
          # person's answer is outstanding and the successor picks it up. So the
          # evidence has to BE that outstanding question — an open approval
          # whose cutpoint is the literal `판단`, found in the ledger rather than
          # asserted in the wording.
          #
          # THE WHOLE SET, AND NOT THE LAST MATCH. The collection loop below used
          # to overwrite one variable on every hit, so a rationale naming two
          # approvals was checked against one of them — the last — and the other
          # could hold a second clause with nothing objecting. The extraction is
          # a function now because the `done` file's reporter has to derive its
          # answer from the same bytes; two expressions over one field is how the
          # gate came to check an id the morning never saw and report one the gate
          # never measured.
          local cev jid ojid cev_ids other last_other other_ids
          cev=$(gate_field_of '근거' "$@")
          cev_ids=$(gate_clause_evidence_ids "$cev")
          if [ -z "$cev_ids" ]; then
            warn "the \`근거\` of a termination clause in \`보류\` has to name an open \`절단점=판단\` approval id (observed: ${cev:-(none)})"
            return "$GATE_EXIT_VOCAB"
          fi
          # EVERY named id must be open, not merely one of them. A rationale that
          # names an answered approval beside an open one would otherwise settle
          # the clause on the strength of the open one while telling the morning
          # it waits on both.
          for jid in $cev_ids; do
            gate_judgment_approval_open "$jid" && continue
            warn "the ${jid} named by the grounds of the \`보류\` termination clause is not an open \`절단점=판단\` approval"
            return "$GATE_EXIT_VOCAB"
          done
          # ONE QUESTION HOLDS ONE CLAUSE.
          #
          # Condition 10 is the only one of the eleven that measures what the USER
          # authorized the run against, and `보류` settles a clause for it — so
          # with no constraint here a single grade-2 judgment, submitted once,
          # could be cited by every clause in the manifest and the run would
          # propose `done` with nothing actually settled. The morning would read
          # a run that ended with one open question, which is a state the design
          # deliberately permits, while none of the authorized clauses had been
          # met.
          #
          # Distinctness is the floor rather than "the question must name the
          # clause": the gate can verify that two clauses do not lean on one
          # answer, and it cannot verify that a free-text question is ABOUT a
          # clause. What it refuses is the amplification — one answer excusing
          # many obligations — which is the whole of the failure.
          #
          # EXCEPT A QUESTION ABOUT THE DESIGN STEP. Its answer is not an excuse
          # for several obligations but the common precondition of every clause
          # that needs the document, so one answer releasing all of them is the
          # plain fact. And the design stage emits one judgment for the whole
          # document, so there is no path on which it could raise one question
          # per clause. The exception keys on what the approval is about (its
          # `막는 세그먼트` is the design step id), which the gate can verify; the
          # two floors above — at least one id, every id an open `판단`
          # approval — still apply to it.
          for other in $(gate_clause_ids); do
            [ -n "$other" ] || continue
            [ "$other" = "$cid" ] && continue
            last_other=$( { gate_rows '종료 절' | grep -F "id=$other " || true; } | tail -1)
            [ -n "$last_other" ] || continue
            [ "$(gate_row_field "$last_other" '상태')" = "보류" ] || continue
            other_ids=$(gate_clause_evidence_ids "$(gate_row_field "$last_other" '근거')")
            for jid in $cev_ids; do
              for ojid in $other_ids; do
                [ "$jid" = "$ojid" ] || continue
                gate_approval_keyed_on_design_step "$jid" && continue
                warn "approval ${jid} is already holding termination clause ${other} — one answer cannot settle several clauses"
                warn "to hold this clause, raise a separate question for it (condition 10 is the only condition that measures what the user authorized)"
                return "$GATE_EXIT_VOCAB"
              done
            done
          done ;;
        *) warn "the \`상태\` of a termination-clause row has to be one of \`충족\`, \`불가능\`, \`보류\` (observed: ${cst:-(none)})"
           return "$GATE_EXIT_VOCAB" ;;
      esac
      # Evidence is a ledger reference or an observable artifact, never prose —
      # a clause settled by assertion is the same hollow value the whole
      # contract exists to remove.
      [ -n "$(gate_field_of '근거' "$@")" ] \
        || { warn "a termination-clause row needs \`근거\`"; return "$GATE_EXIT_VOCAB"; }
      gate_append '종료 절' "$@"
      log "종료 절 정산 — $cid ($cst)"
      ;;
    judgment)
      # GRADE 1, WHICH HAD NO WRITER. The contract and the kickoff both say a
      # grade-1 judgment is adopted together with a row carrying `등급`·`기준`·
      # `되돌리는 법`, and the gate had no entry point for one: the three places
      # that append `자율 승인` are all the gate judging an ACT, `등급=` appears
      # once and is hard-coded to 0, and `되돌리는 법=` once with a fixed value.
      # So the autonomous decisions a night is made of left no trace, and the
      # morning report's whole premise — that they are cheap to undo because
      # they are written down — had nothing to stand on.
      # The field floor is per grade and lives in one place, because the acting
      # path has to apply it BEFORE the auto-adoption floor reads those same
      # fields — see `gate_judgment_fields_ok`.
      local jcls jgrade
      gate_judgment_fields_ok "$@" || return "$GATE_EXIT_VOCAB"
      jcls=$(gate_field_of '판단 부류' "$@")
      jgrade=$(gate_field_of '등급' "$@")
      case "$jgrade" in
        1) : ;;
        2)
          # THE PATH THE OLD REFUSAL PROMISED. It said in as many words that
          # grade 2 is raised to an approval, while refusing — and no such path
          # existed anywhere in the tree, so the one grade whose entire
          # definition is "a person decides this" had nowhere to go but a
          # vocabulary error.
          #
          # AND THE PATH BACK, WHICH IS WHAT WAS MISSING. Raising the question
          # was only half a lifecycle: a grade-2 judgment never reaches the
          # resolution block on the acting path (that block runs only when the
          # auto-adoption floor escalated, and the floor is consulted for grade 1
          # alone), so once the person answered there was no arm that noticed.
          # Every re-submission came back here and asked again. Reading the
          # state BEFORE issuing is what turns an answer into an adoption.
          local jq_id jq_st jq_rc=0 jq_cons=0
          jq_id=$(gate_judgment_target_id "$seg" "$@") || return "$GATE_EXIT_RULE"
          jq_st=$(gate_approval_state "$jq_id")
          gate_person_refusal_consumable "$jq_id" || jq_cons=$?
          if [ "$jq_cons" = "0" ]; then
            log "승인 $jq_id 의 거절을 이 판단이 소비합니다 (세그먼트는 park 되어 있습니다)"
            GATE_RESOLVED_APPROVAL="$jq_id"
            GATE_JUDGMENT_DECISION="거절 소비"
          elif [ "$jq_cons" = "2" ]; then
            warn "승인 $jq_id 의 거절은 그 세그먼트가 park 된 뒤에만 소비됩니다 — 먼저 act --kind segment 로 상태=park 행을 쓰세요"
            return "$GATE_EXIT_RULE"
          elif [ "$jq_st" = "승인" ]; then
            # ONE ANSWER OPENS ONE JUDGMENT, the same floor the acting path
            # applies. A judgment approval carries no binding tuple, so nothing
            # about it expires — without this the first answer would adopt every
            # later judgment that hashed to the same id.
            if gate_has_row '자율 승인' "| 해소 승인=$jq_id |"; then
              warn "approval $jq_id has already been used for one adoption — one answer opens one judgment"
              warn "if this raises a different judgment on the same standard, it has to be asked again as a new question"
              return "$GATE_EXIT_RULE"
            fi
            # AN ANSWER AUTO-RESOLUTION CLOSED IS NOT LENT TO A CLASS IT NEVER
            # SAW. The approval id is a hash of `기준 — 근거` and carries no
            # class, so a resubmission with a different class reaches the same
            # answer — and auto-resolution judges the class only on the
            # submission that OPENS the question, which a submission finding the
            # approval already `승인` never is. An answer it closed for an
            # adoptable class, whose adoption row never got written because the
            # gate stopped between the two appends, survives as answered and
            # unspent; without this it opened a class that hands risk to the
            # user with nobody asked. An answer closed just now for this very
            # submission, and an answer a person gave, still open the judgment.
            if [ "${GATE_AUTO_RESOLVED_APPROVAL:-}" != "$jq_id" ] \
               && [ "$(gate_row_field "$(gate_approval_last_row "$jq_id")" '처분 사유')" = "자동 해소" ] \
               && ! gate_judgment_class_adoptable "$jcls"; then
              warn "approval $jq_id is an answer closed by an earlier auto-resolution, so it is not adopted for the class of this judgment (class ${jcls:-(none)})"
              warn "to raise it under this class, it has to be asked again as a new question with a different standard and different grounds"
              return "$GATE_EXIT_RULE"
            fi
            log "승인 $jq_id 이 해소되어 이 판단을 채택으로 엽니다"
            GATE_RESOLVED_APPROVAL="$jq_id"
          else
            gate_issue_judgment_approval "$alias" "$seg" \
              "$(gate_field_of '기준' "$@")" "$(gate_field_of '근거' "$@")" \
              "$jcls" "$(gate_judgment_seat)" || jq_rc=$?
            # THROUGH THE TRANSLATION, not around it. Propagating the raw value
            # sent the router exit 9 for an answered-but-spent approval, which
            # is the one code the contract does not define. `이미 닫힌 물음` and
            # `이미 쓰인 답` are both refusals of this submission, so both leave
            # as the rule refusal the router already knows — except an answer
            # auto-resolution closed just now, which is unspent and adopts.
            case "$(gate_judgment_approval_disposition "$jq_rc")" in
              발행) return "$GATE_EXIT_APPROVAL" ;;
              답있음)
                if [ -n "${GATE_AUTO_RESOLVED_APPROVAL:-}" ] \
                   && [ "$GATE_AUTO_RESOLVED_APPROVAL" = "$jq_id" ]; then
                  GATE_RESOLVED_APPROVAL="$jq_id"
                else
                  return "$GATE_EXIT_RULE"
                fi ;;
              *) return "$GATE_EXIT_RULE" ;;
            esac
          fi ;;
        *) warn "a judgment row takes only grades 1 and 2 — grade 0 needs no record (observed: ${jgrade:-(none)})"
           return "$GATE_EXIT_VOCAB" ;;
      esac
      # `해소 승인` NAMES THE ANSWER THAT OPENED THIS ADOPTION, and `-` says the
      # floor admitted it on its own. Without the field there is no way to ask
      # whether an answer has already been spent, and a judgment approval has no
      # binding tuple to expire — so one answered question opened every later
      # judgment that hashed to the same id.
      # `결정=거절 소비` is one other decision: a person's refusal of a
      # `사람-결정` question, spent by the resubmission that parks on it.
      # `결정=자유 입력 소비` is the last: a `사람-결정` answered in the person's
      # own words. That answer closes `승인` like the label does, and the row
      # spending it used to read `채택` — the ledger then said the question's
      # recommendation was carried out when the person had written something
      # else, a "no, park it" included. The class is the literal `사람-결정`:
      # only that class closes on free text, so only it has words to spend.
      if [ -z "${GATE_JUDGMENT_DECISION:-}" ] && [ -n "${GATE_RESOLVED_APPROVAL:-}" ] \
         && [ "$(gate_approval_field "$GATE_RESOLVED_APPROVAL" '판단 부류')" = "사람-결정" ] \
         && [ "$(gate_row_field "$(gate_approval_last_row "$GATE_RESOLVED_APPROVAL")" '처분 사유')" = "자유 입력" ]; then
        GATE_JUDGMENT_DECISION="자유 입력 소비"
      fi
      # THE ROW IS NARROWED TO THE CAP, NOT REFUSED BY IT. The caller's argv
      # goes on the row as given while it fits. `gate_append` ends the process
      # on a row past `GATE_ROW_MAX`, and at grade 2 that would come after the
      # closing `승인` row is committed, leaving an answered question with no
      # adoption row. So the three free-text fields are narrowed until the row
      # fits; the approval id was derived
      # above from the argv as submitted, so narrowing does not change which
      # answer this row spends. An overflow outside those three fields is a
      # submission the gate cannot record, and it is refused, not died on.
      local jw
      if ! jw=$(gate_judgment_adoption_width 전체 "kind=judgment" "결정=${GATE_JUDGMENT_DECISION:-채택}" \
                  "세그먼트=${seg:--}" "해소 승인=${GATE_RESOLVED_APPROVAL:--}" "$@"); then
        warn "the judgment row does not fit the row cap of $GATE_ROW_MAX bytes even with \`기준\`, \`근거\` and \`되돌리는 법\` narrowed to 40 bytes — the overflow is in another field; shorten that field and submit again"
        return "$GATE_EXIT_VOCAB"
      fi
      gate_judgment_adoption_row append "$jw" "kind=judgment" "결정=${GATE_JUDGMENT_DECISION:-채택}" \
        "세그먼트=${seg:--}" "해소 승인=${GATE_RESOLVED_APPROVAL:--}" "$@"
      # The grade is read from the row rather than hard-coded: a grade-2 judgment
      # whose question has been answered lands here too, and a line claiming
      # grade 1 for it would misdescribe the one event the morning most needs to
      # tell apart — an adoption the floor admitted on its own from one a person
      # opened.
      # `부류` may legitimately be empty here: it is required at grade 1 alone,
      # because its only consumer is the auto-adoption floor and a grade-2
      # judgment never reaches that floor. A classless grade-2 judgment that lands
      # here was opened by a person's answer — auto-resolution refuses a question
      # without a class, so it never sends one here.
      log "판단 등급 $jgrade 기록 — 부류 ${jcls:-없음}"
      ;;
    blocked)
      # THE ROUTER MAY RESOLVE A RUN-SCOPE BLOCK, AND MAY NOT CREATE ONE. Blocks
      # are raised by the gate itself — the surface check and the watcher's
      # transcription — so a router that could write an arbitrary one would be
      # inventing the very state that governs whether the run may end. What it
      # gets is the other half, which nothing had: the disposition of a stall
      # observation is the router's job, and until now that job had no verb.
      #
      # `스코프=cone` IS THE OTHER HALF, and its polarity is the opposite one:
      # the router MAY create a cone. A cone is not a run stop — it holds what
      # stands on a refuted premise and lets the siblings keep going — which is
      # exactly the disposition an open question needs and the one nothing could
      # express. The gate does not take the declaration on trust: it derives the
      # cone itself and refuses a declaration that is narrower.
      local why cause prior scope
      scope=$(gate_field_of '스코프' "$@")
      # AN ABSENT SCOPE MEANS `run`, and that default is compatibility rather
      # than convenience. Before the cone existed the resolution form carried no
      # scope at all — `act --kind blocked -- 원인=해소 사유=… 근거=…` — because
      # `run` was the only thing a router could resolve, and the arm wrote the
      # field itself. Making the field required turned every existing caller of
      # that form into an exit 2, which is the same shape as the two open issues
      # about a newly required field invalidating runs already in flight. The
      # vocabulary check still runs; it just runs on a value that is filled in.
      [ -n "$scope" ] || scope=run
      gate_shift_halt_fields_refused "$@" && return "$GATE_EXIT_VOCAB"
      why=$(gate_field_of '사유' "$@")
      cause=$(gate_field_of '원인' "$@")
      gate_check_scope "$scope" || return "$GATE_EXIT_VOCAB"
      [ -n "$why" ] || { warn "a \`blocked\` row needs \`사유\`"; return "$GATE_EXIT_VOCAB"; }
      [ -n "$(gate_field_of '근거' "$@")" ] \
        || { warn "a \`blocked\` row needs \`근거\` — what was looked at to judge it resolved is all that is left in the morning"; return "$GATE_EXIT_VOCAB"; }
      if [ "$scope" = "cone" ]; then
        gate_record_cone "$alias" "$@" || return $?
        return 0
      fi
      if [ "$scope" != "run" ]; then
        warn "the \`blocked\` scopes a router may write are run (resolution) and cone only — an act-scope block is written by the gate (observed: ${scope})"
        return "$GATE_EXIT_VOCAB"
      fi
      if [ "$cause" != "해소" ]; then
        warn "the \`원인\` of a \`blocked\` row has to be \`해소\` — making a block is the work of the gate (observed: ${cause:-(none)})"
        return "$GATE_EXIT_VOCAB"
      fi
      # A cone row anchored on a run-scope step (design, audit, split or visual) holds
      # the run just as a run-scope row does, and a driver-written one or a
      # shift's routing block has no lineage a later attempt could release it
      # by — so this form is its way out, and it must find it by `사유`.
      # The resolution itself stays `스코프=run`: that row is inside the set
      # `cc_unresolved_blocked` folds, which is all the release needs.
      prior=$( { gate_rows 'blocked' | grep -F '스코프=run' | grep -F "사유=$why " || true; } | tail -1)
      if [ -z "$prior" ] \
         && [ "$( { cc_unresolved_blocked "$LEDGER" | cut -f2- | grep -cxF -- "$why" || true; } )" != "0" ]; then
        prior=$( { gate_rows 'blocked' | grep -F '스코프=cone' | grep -F "사유=$why " || true; } | tail -1)
      fi
      if [ -z "$prior" ]; then
        warn "there is no run-scope or step-anchored cone \`blocked\` row to resolve: ${why}"
        return "$GATE_EXIT_VOCAB"
      fi
      case "$(printf '%s' "$prior" | tr '|' '\n' | sed -n 's/^ *원인=//p' | sed 's/[[:space:]]*$//' | tail -1)" in
        무효화)
          # The enforcement-surface block. Its own resume line says this run's
          # baseline is never retaken, so clearing it here would be the run
          # re-authorizing itself past the boundary that refused it.
          warn "this block cannot be resolved (\`원인=무효화\`): ${why} — kick off again as a new run"
          return "$GATE_EXIT_RULE" ;;
      esac
      # NO BANNER HERE, and this is the most dangerous of the sites that write a
      # run-scope block. It is the RESOLUTION path — a person has just cleared
      # the block — so instrumenting "a run-scope block row was added", which is
      # the obvious pattern, raises "the run has anchored" at the exact moment
      # somebody unblocked it.
      gate_append 'blocked' "대상=-" "스코프=run" "$@"
      log "런 스코프 막힘 해소 — $why"
      ;;
    handoff)
      # THE ROW THAT CARRIES WHAT THE SNAPSHOT CANNOT. A shift ends and its
      # successor starts from the snapshot alone, and the snapshot is a record
      # of PROGRESS — it says what landed, never what was tried and dropped. So
      # the successor re-walks the predecessor's dead ends, and the morning
      # report's request for the rejected alternative is answerable only if a
      # router happened to write it into free-text rationale, where no reader
      # looks.
      #
      # A shift is an event of the WHOLE RUN, so `--segment` is not required —
      # the same exemption `blocked`, `clause` and `judgment` already hold, and
      # for the same reason: demanding a part makes the kind that describes the
      # whole unwritable.
      local hn hwhy hd hb hc hlen hw=300 hci
      hn=$(gate_field_of '교대' "$@")
      hwhy=$(gate_field_of '사유' "$@")
      case "$hwhy" in
        상한|승인|종단|중단|대기|이월) : ;;
        *) warn "the \`사유\` of a handoff row is out of vocabulary: ${hwhy:-(none)} — \`상한\` \`승인\` \`종단\` \`중단\` \`대기\` \`이월\`"
           return "$GATE_EXIT_VOCAB" ;;
      esac
      # `CI 대기` IS A LIST OF SEGMENT IDS, comma-joined, and it is never narrowed
      # below: a clipped list would shrink the relay's wait set without a word.
      hci=$(gate_field_of 'CI 대기' "$@")
      hci=$(printf '%s' "$hci" | tr -d ' ')
      # `-` is the field's empty spelling — every shift row carries the field —
      # so it names no segment and must not pass the empty-set check below.
      [ "$hci" != "-" ] || hci=""
      case "$hci" in
        *[!A-Za-z0-9._,-]*)
          warn "\`CI 대기\` has to be segment ids joined by ',' (received: $hci)"
          return "$GATE_EXIT_VOCAB" ;;
      esac
      # `리셋 대기` NAMES THE CUT STAGES WHOSE LIMIT HAS NOT RESET, in the same
      # grammar as `CI 대기`, and it is never narrowed either. Each key is taken
      # only when the gate itself can read a clock for it: the stage's latest
      # `stage-result` is a cut (`한도 종료`, or the 429 `크래시`), that attempt's
      # stream yields a reset under the last-frame rule, and the reset is within
      # the horizon. Any key that fails is exit 3 with no row, the same code as
      # the empty-set refusal below and not the argv exit 2: the field is well
      # formed, and it is the ledger that refuses it. The shift then hands off
      # `중단`, as it did before this field existed.
      local hrs hk hat
      hrs=$(gate_field_of '리셋 대기' "$@")
      hrs=$(printf '%s' "$hrs" | tr -d ' ')
      [ "$hrs" != "-" ] || hrs=""
      case "$hrs" in
        *[!A-Za-z0-9._,#-]*)
          warn "\`리셋 대기\` has to be stage keys joined by ',' (received: $hrs)"
          return "$GATE_EXIT_VOCAB" ;;
      esac
      if [ -n "$hrs" ] && [ "$hwhy" != "대기" ]; then
        warn "\`리셋 대기\` belongs to a \`대기\` handoff only (received with \`사유=$hwhy\`)"
        return "$GATE_EXIT_VOCAB"
      fi
      for hk in $(printf '%s' "$hrs" | tr ',' ' '); do
        hat=$(gate_cut_key_reset_at "$hk")
        if [ -z "$hat" ]; then
          warn "\`리셋 대기\` key $hk has no reset clock — its latest \`stage-result\` is not a cut, or the cut attempt's stream does not carry a binding \`rejected\` frame — so the \`대기\` handoff is refused; hand off \`중단\`"
          return "$GATE_EXIT_RULE"
        fi
        if ! gate_cut_reset_within "$hat"; then
          warn "\`리셋 대기\` key $hk resets at $hat, further than ${GATE_RESET_HORIZON_SECONDS}s from now — a relay does not wait on it; hand off \`중단\`"
          return "$GATE_EXIT_RULE"
        fi
      done
      # `master 대기` NAMES THE SEGMENTS WAITING ON THEIR BASE BRANCH, in the
      # grammar of `CI 대기`, never narrowed, and taken only on a `대기` handoff
      # and only for a segment whose `다음` is `master 대기` now: the relay wakes
      # on the base branch's reading for these, and a segment that has moved on
      # would hold a wait nothing ends.
      local hms hm
      hms=$(gate_field_of 'master 대기' "$@")
      hms=$(printf '%s' "$hms" | tr -d ' ')
      [ "$hms" != "-" ] || hms=""
      case "$hms" in
        *[!A-Za-z0-9._,-]*)
          warn "\`master 대기\` has to be segment ids joined by ',' (received: $hms)"
          return "$GATE_EXIT_VOCAB" ;;
      esac
      if [ -n "$hms" ] && [ "$hwhy" != "대기" ]; then
        warn "\`master 대기\` belongs to a \`대기\` handoff only (received with \`사유=$hwhy\`)"
        return "$GATE_EXIT_VOCAB"
      fi
      for hm in $(printf '%s' "$hms" | tr ',' ' '); do
        if [ "$(gate_segment_review_next "$hm")" != "master 대기" ]; then
          warn "\`master 대기\` segment $hm does not read \`다음\`=\`master 대기\` now — read the snapshot again"
          return "$GATE_EXIT_RULE"
        fi
      done
      # `대기` HANDS THE WAIT TO THE SEAT CALL'S RELAY, SO IT NEEDS SOMETHING TO
      # WAIT ON. Without a live stage or supervisor, without a `CI 대기` or
      # `master 대기` segment and without a `리셋 대기` key the relay would wake
      # at once and the successor would find the same nothing — a shift turn
      # spent to learn it. Refused without a row; a shift with nothing to wait
      # on hands off with another reason.
      if [ "$hwhy" = "대기" ] && [ -z "$hci" ] && [ -z "$hrs" ] && [ -z "$hms" ] \
         && [ -z "$(cc_relay_wait_stages "$RUN_DIR")" ]; then
        warn "nothing to wait on — no live stage or supervisor, no \`CI 대기\` segment and no \`리셋 대기\` key, so a \`대기\` handoff is refused"
        return "$GATE_EXIT_RULE"
      fi
      # `종단` SAYS THE RUN HAS ENDED, SO IT IS TAKEN ONLY FROM A RUN THAT HAS.
      # The vocabulary check alone let a shift write `사유=종단` with no accepted
      # termination proposal behind it: the run then carried no `done`, the
      # watcher read it as still going, and nothing would ever end it. The two
      # marks read here are the ones the gate already treats as "the run has
      # ended" — the `done` file and the end token of the ledger — so no third
      # reader is introduced. Refused without a row: a shift that has not ended
      # the run hands off with `중단`.
      if [ "$hwhy" = "종단" ] && ! [ -s "$RUN_DIR/done" ] \
         && [ -z "$(gate_end_token)" ]; then
        warn "종료 제안 없이 종단 인계를 쓸 수 없습니다 — the run has neither \`done\` nor an ending row; propose termination first, or hand off with \`사유=중단\`"
        return "$GATE_EXIT_RULE"
      fi
      # `이월` SAYS THE RUN WAITS FOR ITS NEXT RUN, NOT FOR A PERSON: what is
      # left is answers a carry found no room for before the deadline, kept in
      # `이월` rows. Taken only when that is all that is left. A `CI 대기`
      # segment is refused here because the relay reads that field from a `대기`
      # hand-off alone, so a CI finishing before the deadline would wake nobody;
      # `리셋 대기` is already refused above for every reason but `대기`.
      local hdu
      if [ "$hwhy" = "이월" ]; then
        if [ -n "$hci" ]; then
          warn "\`CI 대기\` 세그먼트($hci)가 있는 인계는 사유=대기 입니다 — 이월 인계를 쓰지 않습니다"
          return "$GATE_EXIT_RULE"
        fi
        hdu=$(gate_defer_handoff_unmet)
        if [ -n "$hdu" ]; then
          warn "이월 인계를 쓸 수 없습니다 — $hdu"
          return "$GATE_EXIT_RULE"
        fi
        # PAST THE DEADLINE THE HAND-OFF IS TAKEN ONLY WHERE IT ENDS THE RUN.
        # The relay wakes `이월` at the deadline plus one second, a time already
        # behind us, so a hand-off taken without the ending would stay the
        # latest hand-off of a run that never ends, and each successor shift
        # would hand off `이월` again. With this hand-off read as the latest,
        # the ending (`gate_defer_end_ready`) must hold; when it does not,
        # something besides the carried answers still holds the run, and the
        # hand-off names it — guard 1 below then takes `중단`, since it reads
        # the same judgment.
        if gate_past_deadline && ! gate_defer_end_ready; then
          warn "이월 답 말고 런을 붙드는 것이 있습니다 — 마감이 지나 이월 인계는 그 자리에서 런을 끝낼 때만 받습니다; 그것을 이름 짓는 사유(살아 있는 스테이지·감독자나 CI 대기면 사유=대기, 그 밖이면 사유=중단)로 인계하세요"
          return "$GATE_EXIT_RULE"
        fi
      fi
      # `중단` ASKS A PERSON, SO IT IS NOT TAKEN WHEN NOTHING IS LEFT TO ASK. An
      # answer carried over is a person's answer already given, and handing off
      # `중단` for it puts the same decision before them again. Two checks: the
      # state — every condition of `이월` holds and nothing but the carried
      # answers holds the run (`gate_defer_only_left`, the judgment the ending
      # past the deadline reads too) — and the raw `막힌 지점`, before it is
      # narrowed below, naming a carried-over record. The text is free, so the
      # second check backs the first rather than replacing it.
      local hdrec
      if [ "$hwhy" = "중단" ]; then
        if [ -z "$hci" ] && [ -z "$(gate_defer_handoff_unmet)" ] \
           && gate_defer_only_left; then
          warn "막는 것이 다음 런으로 넘긴 중단 답뿐입니다 — 사람에게 다시 묻지 않습니다; 사유=이월 로 인계하세요"
          return "$GATE_EXIT_RULE"
        fi
        hdrec=$(gate_text_names_deferred "$(gate_field_of '막힌 지점' "$@")")
        if [ -n "$hdrec" ]; then
          warn "막힌 지점이 다음 런으로 넘긴 중단 기록을 가리킵니다($hdrec) — 그 답은 다시 묻지 않습니다; 남은 것이 그것뿐이면 사유=이월 로 인계하세요"
          return "$GATE_EXIT_RULE"
        fi
      fi
      case "$hn" in
        ''|*[!0-9]*)
           warn "a handoff row needs \`교대=<정수>\` — the \`적용 이후 교대 수\` of the morning report stands on this scale"
           return "$GATE_EXIT_VOCAB" ;;
      esac
      # THREE FREE-TEXT FIELDS AT 300 CHARACTERS, THEN NARROWED AGAIN IF THE ROW
      # STILL DOES NOT FIT. Three Korean fields at their full width are past the
      # 1024-byte row cap on their own, and `gate_append` answers that with a
      # `die` — which would turn the row that reports a handoff into the thing
      # that kills the run performing it. The declared width is the ceiling; the
      # cap is the constraint; this loop is where the two are reconciled instead
      # of colliding at 3am.
      #
      # `CI 대기` counts toward the length and is never narrowed, so a row that
      # still does not fit at the narrowest width is refused rather than written
      # with a shorter wait set. `리셋 대기` is the same, and is written only
      # when it names a key, so a row without one is the row written before it.
      local hrsf=""
      [ -z "$hrs" ] || hrsf=" | 리셋 대기=$hrs"
      [ -z "$hms" ] || hrsf="$hrsf | master 대기=$hms"
      while [ "$hw" -ge 40 ]; do
        hd=$(gate_row_safe "$(gate_field_of '버린 선택지' "$@")" "$hw")
        hb=$(gate_row_safe "$(gate_field_of '막힌 지점' "$@")" "$hw")
        hc=$(gate_row_safe "$(gate_field_of '다음 후보' "$@")" "$hw")
        hlen=$(printf -- '- `handoff` | 교대=%s | 사유=%s | 버린 선택지=%s | 막힌 지점=%s | 다음 후보=%s | CI 대기=%s%s | 대상=%s | 기록 시각=%s | prev=%064d\n' \
                 "$hn" "$hwhy" "$hd" "$hb" "$hc" "${hci:--}" "$hrsf" "$alias" "$(now_iso)" 0 \
               | wc -c | tr -d ' ')
        [ "$hlen" -le "$GATE_ROW_MAX" ] && break
        hw=$((hw - 40))
      done
      if [ "$hlen" -gt "$GATE_ROW_MAX" ]; then
        warn "the handoff row does not fit in ${GATE_ROW_MAX} bytes even with its free text narrowed to the floor — \`CI 대기\`, \`리셋 대기\` and \`master 대기\` are never cut, so nothing is written"
        return "$GATE_EXIT_VOCAB"
      fi
      gate_append 'handoff' "교대=$hn" "사유=$hwhy" \
        "버린 선택지=$hd" "막힌 지점=$hb" "다음 후보=$hc" "CI 대기=${hci:--}" \
        ${hrs:+"리셋 대기=$hrs"} ${hms:+"master 대기=$hms"} \
        "대상=$alias" "기록 시각=$(now_iso)"
      log "교대 $hn 기록 — 사유 $hwhy"
      # PAST THE DEADLINE THERE IS NOTHING FOR THE RELAY TO WAKE FOR, so the
      # same act ends the run: a run with a progress axis that carried an answer
      # over after its deadline would otherwise never end.
      if [ "$hwhy" = "이월" ] && gate_defer_end_due; then
        gate_end_run 마감 "$(gate_defer_end_why)" 마감 || true
      fi
      ;;
    limit-cleared)
      # THE SEAT'S ONE WAY TO SAY "THE LIMIT HAS CLEARED". A person at the seat
      # who switched accounts or saw the window reset has information no shift
      # can derive — the cut attempt's stream still carries the old reset time —
      # and before this row the only carrier was the seat's own prose, which no
      # successor reads. A row survives the shift that would have acted on it.
      #
      # SEAT ONLY, judged in the order `gate_cap_directive`'s seat arm uses. That
      # arm exempts a non-seat caller from the seat cap; this one refuses it,
      # because a shift or a stage writing this row would be the run asserting
      # its own release from a limit, which is exactly the judgment the
      # re-attach rule exists to make from evidence.
      if [ -n "$(gate_shift_self_ordinal)" ] || cc_caller_is_stage \
         || [ -n "${CC_PIPELINE_SHIFT_ID:-}" ]; then
        warn "a \`한도 해제\` row is written by the seat only — a shift or a stage cannot declare its own limit cleared"
        return "$GATE_EXIT_RULE"
      fi
      # ONE KEY FROM ARGV, AND THE GATE BUILDS THE REST. `run_row_body` carries
      # every `k=v` it is handed and de-duplicates `교대` alone, so passing argv
      # through would put a caller's `레인=` next to the gate's on one row — and
      # the lane and time this row testifies to have to be the gate's.
      local lf lk lwhy lw=300 llen
      for lf in "$@"; do
        lk="${lf%%=*}"
        [ "$lk" = "근거" ] && continue
        warn "a \`한도 해제\` row takes \`근거\` and nothing else from argv: ${lk} — \`레인\` and \`기록 시각\` are the gate's"
        return "$GATE_EXIT_VOCAB"
      done
      lwhy=$(gate_field_of '근거' "$@")
      [ -n "$lwhy" ] || { warn "a \`한도 해제\` row needs \`근거\` — a summary of what the person said"; return "$GATE_EXIT_VOCAB"; }
      local llane lat
      llane=$(gate_lane_label)
      lat=$(now_iso)
      while [ "$lw" -ge 40 ]; do
        lwhy=$(gate_row_safe "$(gate_field_of '근거' "$@")" "$lw")
        llen=$(gate_row_projected_bytes '한도 해제' "근거=$lwhy" "레인=$llane" "기록 시각=$lat")
        [ "$llen" -le "$GATE_ROW_MAX" ] && break
        lw=$((lw - 40))
      done
      # NOTHING READS THIS ROW BUT A SHIFT'S RE-ATTACH RULE. It enters no
      # termination condition, no progress vector and no notification; it moves
      # the chain tip and nothing else.
      gate_append '한도 해제' "근거=$lwhy" "레인=$llane" "기록 시각=$lat"
      log "한도 해제 기록 — 레인 $llane"
      ;;
    reentry)
      # THE BOOT-TIME RE-ENTRY'S OWN ROW, `재진입`, written in the same tick and
      # before the `router-shift` it precedes. It is the base time of a
      # reboot-class re-attachment delay, and its `부팅 시각` against its `기록
      # 시각` is the time from boot to the first tick after login.
      #
      # NOT A SHIFT AND NOT A STAGE. A boot-time re-entry carries no pipeline
      # marker but `CC_PIPELINE_REENTRY`; a shift or a stage writing this row
      # would be a run claiming the machine rebooted under it.
      if [ -n "$(gate_shift_self_ordinal)" ] || cc_caller_is_stage \
         || [ -n "${CC_PIPELINE_SHIFT_ID:-}" ]; then
        warn "a \`재진입\` row is written by a boot-time re-entry only — a shift or a stage cannot write it"
        return "$GATE_EXIT_RULE"
      fi
      # `사유` AND `레이블` FROM ARGV, AND THE GATE BUILDS THE REST: the target,
      # the boot time from the kernel reading every boot judgement here uses,
      # and the time of the row.
      local rf rk rwhy rlabel rboot rat
      for rf in "$@"; do
        rk="${rf%%=*}"
        case "$rk" in 사유|레이블) continue ;; esac
        warn "a \`재진입\` row takes \`사유\` and \`레이블\` and nothing else from argv: ${rk} — \`대상\`, \`부팅 시각\` and \`기록 시각\` are the gate's"
        return "$GATE_EXIT_VOCAB"
      done
      rwhy=$(gate_field_of '사유' "$@")
      case "$rwhy" in
        대기|중단|상한) : ;;
        *) warn "the \`사유\` of a \`재진입\` row is the reason the re-entry issues: \`대기\` \`중단\` \`상한\` (received: ${rwhy:-(none)})"
           return "$GATE_EXIT_VOCAB" ;;
      esac
      rlabel=$(gate_row_safe "$(gate_field_of '레이블' "$@")" 80)
      [ -n "$rlabel" ] || { warn "a \`재진입\` row needs \`레이블\` — the dispatch label that ran it"; return "$GATE_EXIT_VOCAB"; }
      rboot=$(cc_epoch_to_iso "$(boot_epoch)")
      rat=$(now_iso)
      gate_append '재진입' "대상=$alias" "부팅 시각=${rboot:--}" "기록 시각=$rat" \
        "사유=$rwhy" "레이블=$rlabel"
      log "재진입 기록 — 부팅 ${rboot:--} · 사유 $rwhy · 레이블 $rlabel"
      ;;
    halt-answer)
      # THE SEAT'S WAY TO CARRY A PERSON'S ANSWER TO A HALT RECORD INTO THE RUN.
      # A stage that reached a question only a person can answer writes a halt
      # record with the question and its options verbatim, and stops. The seat
      # asks the person; before this row the answer travelled only as prose in
      # the next shift's launch prompt, which the shift's procedure had no place
      # for — measured: an audit's synthesis question was answered at the seat,
      # two shifts read the answer and both stopped because nothing in their
      # procedure consumed it, and the run was re-kicked from scratch.
      #
      # SEAT ONLY, judged as `limit-cleared` judges it. A shift or a stage
      # writing this row would be the run answering its own question for a
      # person.
      #
      # ONE EXCEPTION, AND ONLY FOR A SHIFT: a binding-tier stop answered
      # `재수렴` when the manifest's `## 인가` pre-adopts the `구속-이탈` class.
      # The person made that answer at kickoff, by freezing the row, so the
      # shift is not answering for them — it is carrying a frozen answer. Every
      # other condition is checked below, after the record has been read, and
      # a shift that misses one is refused exactly as before. A stage never
      # writes this row.
      #
      # AND THE SEAT MAY ANSWER WITHOUT A PERSON, from the record itself. A
      # stage that halted on a question it could already answer from the
      # interview record, the manifest's authorization, a fact of this machine
      # or a standing instruction writes that answer as the record's
      # `**추천**`, and the seat copies it with `답한 주체=좌석` — measured: five
      # halts of one night each waited for a person until morning, and every
      # one of them carried its answer in the run's own records. The gate does
      # the deciding, by `gate_halt_recommendation` and
      # `gate_halt_auto_answer_admit`; the seat only asks.
      #
      # `답한 주체` TELLS THE THREE WRITERS APART on the row: `사람` (the
      # default, which every call written before the field still means),
      # `좌석` and `교대`, which only the gate stamps.
      #
      # EVERY WRITER'S ANSWER IS ROUTABLE OR NOT RECORDED. After the option
      # check, and for an automatic answer after its bounds,
      # `gate_halt_answer_route` asks whether a branch of the shift's
      # procedure can carry the answer out; when none can, nothing is written
      # and the refusal's two lines — `라우팅 불가 — <reason>` and
      # `실행할 수 있는 선택지: …` — let the seat ask again with the labels that
      # do route. A person's answer takes no automatic bound but does take this.
      local hshift=''
      if cc_caller_is_stage; then
        warn "a \`중단 답\` row is written by the seat only — a shift or a stage cannot answer a halt record for a person"
        return "$GATE_EXIT_RULE"
      fi
      if [ -n "$(gate_shift_self_ordinal)" ] || [ -n "${CC_PIPELINE_SHIFT_ID:-}" ]; then
        hshift=1
      fi
      local hf hk hrec hopt hwhy hw=300 hlen hskill hdig hlane hat hatt hattdig hstep hpre='' hcls hrow hadopt='' hby hkinds=''
      for hf in "$@"; do
        hk="${hf%%=*}"
        case "$hk" in 중단\ 기록|선택지|근거|첨부|답한\ 주체) continue ;; esac
        warn "a \`중단 답\` row takes \`중단 기록\`, \`선택지\`, \`근거\`, an optional \`답한 주체\` and an optional \`첨부\` from argv and nothing else: ${hk} — the rest is the gate's"
        return "$GATE_EXIT_VOCAB"
      done
      hrec=$(gate_field_of '중단 기록' "$@")
      hopt=$(gate_field_of '선택지' "$@")
      hwhy=$(gate_field_of '근거' "$@")
      hby=$(gate_field_of '답한 주체' "$@")
      if [ -n "$hshift" ]; then
        if [ -n "$hby" ]; then
          warn "a shift does not name \`답한 주체\` — the gate stamps \`교대\` on the one \`중단 답\` row a shift may write"
          return "$GATE_EXIT_RULE"
        fi
        hby=교대
      else
        # REQUIRED FROM THE SEAT. Left to default, a seat that ran a record's
        # recipe itself and forgot the field wrote a row the morning report
        # read as a person's answer. A row written before the field existed
        # still reads `사람` (`gate_halt_answered_by`); a new call names it.
        if [ -z "$hby" ]; then
          warn "the seat names \`답한 주체\` on every \`중단 답\` row — \`사람\` for a person's answer, \`좌석\` for one the seat gave itself"
          return "$GATE_EXIT_VOCAB"
        fi
        case "$hby" in
          사람|좌석) ;;
          교대) warn "\`답한 주체=교대\` is the gate's stamp on a shift's row — the seat writes \`사람\` or \`좌석\`"
                return "$GATE_EXIT_RULE" ;;
          *) warn "\`답한 주체\` is one of 사람 · 좌석 · 교대: $hby"
             return "$GATE_EXIT_VOCAB" ;;
        esac
      fi
      [ -n "$hrec" ] && [ -n "$hwhy" ] && { [ -n "$hopt" ] || [ "$hby" = "좌석" ]; } || {
        warn "a \`중단 답\` row needs \`중단 기록\` (the halt record's absolute path), \`선택지\` (one option of that record, verbatim — a seat answer may leave it out and take the record's \`**추천**\`) and \`근거\` (a summary of what the person said, or of what the seat read)"
        return "$GATE_EXIT_VOCAB"; }
      # THE SEAT RUNNING A RECORD IS NOT THE SEAT ANSWERING ONE. The two
      # `좌석 실행` halts hand the seat a recipe or a command list to run on this
      # host, and `좌석 실행` is the option the seat took by running it — so the
      # row says `좌석`, whatever the switch below says, and its `근거 종류` says
      # what was done rather than what a recommendation rested on. Only those
      # two halts, with that option line, take this branch.
      local hseatrun='' hrstep
      if [ "$hby" = "좌석" ] && [ "$hopt" = "좌석 실행" ]; then
        hrstep=$(sed -n 's/^\*\*스텝\*\*: //p' "$hrec" 2>/dev/null | sed -n '1p')
        case "$hrstep" in
          'Step 3 잔여 검증 좌석 실행'*|'Step 3 게이트 도달 좌석 실행'*) ;;
          *) warn "\`선택지=좌석 실행\` answers only a \`Step 3 잔여 검증 좌석 실행\` or \`Step 3 게이트 도달 좌석 실행\` halt — this record's step is \`${hrstep:-(none)}\`: $hrec"
             return "$GATE_EXIT_RULE" ;;
        esac
        if ! gate_halt_option_labels "$hrec" | grep -xF '좌석 실행' >/dev/null; then
          warn "this halt record offers no \`좌석 실행\` option line, so the seat has nothing it was asked to run: $hrec"
          return "$GATE_EXIT_RULE"
        fi
        case "$hrstep" in
          'Step 3 게이트 도달 좌석 실행'*)
            [ -n "$(gate_field_of '첨부' "$@")" ] || {
              warn "a seat run of a command halt carries \`첨부\` — each listed command's exit status and the tail of its output"
              return "$GATE_EXIT_VOCAB"; }
            # Every listed command is screened before the seat's answer is
            # taken: a command on an enforcement surface goes to a person.
            local hcl
            while IFS= read -r hcl; do
              [ -n "$hcl" ] || continue
              gate_halt_surface_tokens "$hcl" "the listed command \`$hcl\`" "$hrec" || return "$?"
            done <<EOF
$(LC_ALL=C awk '$0 == "<!-- /cc-pipeline-halt v1 -->" { exit }
  inb && /^\*\*/ { inb = 0 }
  /^\*\*좌석 실행 명령\*\*:/ { inb = 1; next }
  inb && NF { print }' "$hrec" 2>/dev/null || true)
EOF
            ;;
        esac
        hseatrun=1
        hkinds='좌석 실행'
      fi
      # A SEAT APPLY IS ITS OWN BRANCH. The stage wrote the bytes of every
      # enforcement-surface edit into the record; `좌석 적용` has the gate commit
      # them over the record's base once a person approved them — proved by the
      # question frame — or once the seat inherits that approval for the same
      # segment, and `사람 몫으로 넘김` records that a person takes over edits
      # the run cannot commit. Both labels mean this only on that step.
      local hsa='' hsastep
      case "$hopt" in
        '좌석 적용'|'사람 몫으로 넘김')
          hsastep=$(sed -n 's/^\*\*스텝\*\*: //p' "$hrec" 2>/dev/null | sed -n '1p')
          case "$hsastep" in
            'Step 3 강제 표면 좌석 적용'*) ;;
            *) warn "\`선택지=$hopt\` answers only a \`Step 3 강제 표면 좌석 적용\` halt — this record's step is \`${hsastep:-(none)}\`: $hrec"
               return "$GATE_EXIT_RULE" ;;
          esac
          case "$hby:$hopt" in
            교대:*) warn "a shift does not answer a seat-apply halt — the seat hands it to a person"; return "$GATE_EXIT_RULE" ;;
            '좌석:사람 몫으로 넘김') warn "\`사람 몫으로 넘김\` is a person's answer — the seat does not hand edits to a person for them"; return "$GATE_EXIT_RULE" ;;
          esac
          hsa=1 ;;
      esac
      # THE SWITCH THAT TURNS OFF EVERY ANSWER NO PERSON GAVE turns this one off
      # too: a recommendation on a halt record is the same thing as a
      # recommendation on an approval, which the switch already stops waiting
      # for. Off, the seat asks the person. An inherited seat apply is not a
      # recommendation: the person answered it once for the segment, and the
      # switch does not take that answer back.
      if [ "$hby" = "좌석" ] && [ -z "$hseatrun" ] && [ -z "$hsa" ] && ! gate_auto_resolve_enabled; then
        warn "CC_CMDS_AUTOPILOT_AUTO_RESOLVE is off, so the seat does not answer a halt record without a person"
        return "$GATE_EXIT_RULE"
      fi
      # A SHIFT'S RECORD IS ONE ITS ROW VOUCHES FOR. A file under `halt/shift/`
      # with no gate row naming it is not a question this run asked.
      local hsrow=''
      hsrow=$(gate_shift_halt_row_of "$hrec")
      case "$hrec" in
        "$RUN_DIR"/halt/shift/*)
          [ -n "$hsrow" ] || {
            warn "no \`shift-halt\` row of this run wrote this record, so it is not a question this run asked: $hrec"
            return "$GATE_EXIT_VOCAB"; } ;;
      esac
      # THE KEY NAMES A STAGE THIS RUN DISPATCHED. The shift re-attaches or
      # re-dispatches that stage with the answer, so a key with no
      # `stage-result` row is an answer nobody can hand on. A shift's record
      # needs only the segment row: the next shift carries its answer out, and
      # a segment the shift stopped before any stage ran is still one it can
      # act on. That segment row is the `교대-정지` route's condition, so
      # `gate_halt_answer_route` refuses its absence below, with the routing
      # refusal's two lines.
      if [ -n "$hsrow" ]; then
        gate_shift_halt_record_intact "$seg" "$hrec" "$hsrow" || return "$?"
      else
        [ -n "$(gate_stage_result_rows_of "$seg")" ] || {
          warn "no \`stage-result\` row names $seg — --segment has to be the segment id, or the step id for the design step, of the stage that halted"
          return "$GATE_EXIT_VOCAB"; }
      fi
      # THE RECORD IS THIS RUN'S, AND IT IS A HALT RECORD. Only the run
      # directory's own `halt/` is accepted, by prefix and with no `..`, so a
      # file elsewhere cannot be passed off as a question this run asked.
      case "$hrec" in
        "$RUN_DIR"/halt/*.md) ;;
        *) warn "\`중단 기록\` has to be a file under this run's halt directory ($RUN_DIR/halt/): $hrec"
           return "$GATE_EXIT_VOCAB" ;;
      esac
      case "$hrec" in
        */../*|*/./*) warn "\`중단 기록\` cannot carry a relative segment: $hrec"; return "$GATE_EXIT_VOCAB" ;;
      esac
      # A doubled slash below the run directory is the same file under a
      # spelling the `halt/shift/` prefix test does not match, so it would take
      # a shift's record down the stage branch past the digest check. The run
      # directory itself may carry one (a TMPDIR that ends in a slash), so only
      # the part below it is read.
      case "${hrec#"$RUN_DIR"/}" in
        *//*) warn "\`중단 기록\` cannot carry a doubled slash below the run directory: $hrec"; return "$GATE_EXIT_VOCAB" ;;
      esac
      [ -f "$hrec" ] || { warn "the halt record does not exist: $hrec"; return "$GATE_EXIT_VOCAB"; }
      local hfirst=''
      IFS= read -r hfirst < "$hrec" || true
      if [ "${hfirst#<!-- cc-pipeline-halt v1;}" = "$hfirst" ] \
         || ! grep -qxF '<!-- /cc-pipeline-halt v1 -->' "$hrec"; then
        warn "not a complete halt record (opening header and closing fence): $hrec"
        return "$GATE_EXIT_VOCAB"
      fi
      # A SEAT ANSWER IS THE RECORD'S OWN RECOMMENDATION. With no `선택지` the
      # gate copies the label; with one it has to be that label byte for byte,
      # so the seat cannot pass off a choice of its own as the record's. What
      # the recommendation rests on is quoted in the attachment, which is
      # therefore required, and the kinds are stamped on the row as
      # `근거 종류` because the record lives in the volatile run directory and
      # the morning report reads the ledger.
      # A SEAT APPLY IS READ ONCE. The record is copied to a file only the gate
      # holds, and its digest, the frame token and every byte it commits come
      # from that copy — the seat and a shift can both rewrite `halt/*`, and
      # nothing compares a stage record's digest again when its answer is used.
      local hread=$hrec hsacopy='' hsadig='' hsaq='' hsascope='' hsadecl
      local hsac='' hsana='' hsafr='' hsasn='' hsasd='' hsacf='' hsacr='' hsanh=''
      if [ -n "$hsa" ]; then
        hsacopy=$(mktemp "${TMPDIR:-/tmp}/gate-sa-rec.XXXXXX") || return 1
        GATE_SA_COPY=$hsacopy
        cat "$hrec" > "$hsacopy" || return 1
        hread=$hsacopy
        hsadig=$(shasum -a 256 "$hsacopy" | cut -d' ' -f1)
        if grep -q '^\*\*추천\*\*' "$hsacopy"; then
          warn "a seat-apply halt carries no \`**추천**\` — a person sees its edits, so no recommendation answers it: $hrec"
          return "$GATE_EXIT_RULE"
        fi
        gate_seat_apply_parse "$hsacopy" || return "$?"
        case "$hopt" in
          '좌석 적용')
            [ "$GATE_SA_NA" -gt 0 ] || {
              warn "the record applies no file, so \`좌석 적용\` has nothing to commit — its options are \`사람 몫으로 넘김\` and \`보류\`: $hrec"
              return "$GATE_EXIT_RULE"; }
            gate_seat_apply_subject_ok "$GATE_SA_SUBJECT" || {
              warn "\`**좌석 적용 커밋 제목**\` is not one line of the form \`type(scope): <title>\`, at most 100 characters and without a trailer: $GATE_SA_SUBJECT"
              return "$GATE_EXIT_RULE"; }
            hsadecl=$(gate_segment_declared_whole "$seg") || hsadecl=''
            hsascope=$(gate_seat_apply_scope "$hsadecl") || {
              warn "the enforcement-surface classifier could not be loaded, so the apply scope cannot be derived"
              return "$GATE_EXIT_RULE"; }
            hsaq=$(gate_seat_apply_question "$hsadig" "$seg" "$hsascope")
            if [ "$hby" = "사람" ]; then
              gate_seat_apply_frame "$hsadig" "$hsaq" "$hsacopy" "$hopt" || return "$?"
              hsafr=$GATE_SA_FRAME
              hsasn=$(printf '%s\n' "$hsascope" | grep -c . || true)
              hsasd=$(gate_seat_apply_scope_digest "$hsascope")
              hkinds='좌석 적용'
            else
              gate_halt_seat_apply_covered "$seg" || return "$?"
              hsacf=$GATE_SA_COV_FRAME
              hsacr=$GATE_SA_COV_REC
              hkinds='좌석 적용 승계'
            fi
            gate_seat_apply_check "$seg" "$alias" || return "$?"
            # A placeholder of the commit's length until the commit exists.
            hsac=0000000000000000000000000000000000000000
            hsana=$GATE_SA_NA
            ;;
          '사람 몫으로 넘김')
            if [ "$GATE_SA_NA" -gt 0 ] || [ "$GATE_SA_NH" -eq 0 ]; then
              warn "\`사람 몫으로 넘김\` answers a record whose every file is left to a person — this one applies $GATE_SA_NA and leaves $GATE_SA_NH: $hrec"
              return "$GATE_EXIT_RULE"
            fi ;;
        esac
        [ "$GATE_SA_NH" -eq 0 ] || hsanh=$GATE_SA_NH
      fi
      # On a design stage's ladder record the row also carries the gate's
      # `잔여 판정` stamp: who froze which residual items on what reading. It is
      # not clipped, so it is counted in the projection below as well as in
      # the append.
      local hladder=''
      if [ "$hby" = "좌석" ] && [ -z "$hseatrun" ] && [ -z "$hsa" ]; then
        gate_halt_recommendation "$hrec" || return "$?"
        gate_halt_design_check "$hrec" || return "$?"
        hladder=$GATE_HALT_LADDER_STAMP
        if [ -z "$hopt" ]; then
          hopt=$GATE_HALT_REC_LABEL
        elif [ "$hopt" != "$GATE_HALT_REC_LABEL" ]; then
          warn "a seat answer is the record's \`**추천**\` (\`$GATE_HALT_REC_LABEL\`), not \`$hopt\` — another option needs a person"
          return "$GATE_EXIT_RULE"
        fi
        if [ -z "$(gate_field_of '첨부' "$@")" ]; then
          warn "a seat answer carries \`첨부\` — the attachment quoting each \`**추천 근거**\` part with where it stands, and how to undo the answer"
          return "$GATE_EXIT_VOCAB"
        fi
        hkinds=$GATE_HALT_REC_KINDS
      fi
      # THE ANSWER IS ONE OF THE OPTIONS THE STAGE WROTE, byte for byte. A free
      # answer has no option line to match, and the stage resumed with it would
      # be handed something its own record never offered.
      # The label is one of the `**선택지**:` block's, whole: a line elsewhere in
      # the record that starts the same way — a command line, a quoted line —
      # is not an option, and a label is not the prefix of a longer one.
      if ! gate_halt_option_labels "$hread" | grep -xF -- "$hopt" >/dev/null; then
        warn "\`선택지\` is not one of the options this halt record lists verbatim: $hopt"
        # A record with no option line at all is the writer's fault, not the
        # answer's: options run inline after `**선택지**:` are read by no one, so
        # every answer to it is refused here with the same line as a typo.
        [ -n "$(gate_halt_option_lines "$hread")" ] \
          || warn "this halt record has no option line of the form \`- \`<label>\` — <description>\` inside its \`**선택지**:\` block — its options were written inline or elsewhere, so no answer to it can be recorded until each option sits on its own line under \`**선택지**:\`: $hrec"
        return "$GATE_EXIT_VOCAB"
      fi
      # WHAT THE OPTION CANNOT CARRY GOES IN AN ATTACHMENT. `근거` is clipped to
      # fit the row, and an option such as "the person measures it and reports
      # back" is answered by values, not by the label — measured: the stage was
      # re-attached with the label alone and halted again asking for the values
      # the person had already given at the seat. The attachment sits under the
      # same `halt/` so the resumed prompt's path is never read as a document
      # argument, and it must not itself look like a halt record, which every
      # halt-directory scan identifies by its header.
      hatt=$(gate_field_of '첨부' "$@")
      hattdig=''
      if [ -n "$hatt" ]; then
        case "$hatt" in
          "$RUN_DIR"/halt/*.md) ;;
          *) warn "\`첨부\` has to be a .md file under this run's halt directory ($RUN_DIR/halt/): $hatt"
             return "$GATE_EXIT_VOCAB" ;;
        esac
        case "$hatt" in
          */../*|*/./*) warn "\`첨부\` cannot carry a relative segment: $hatt"; return "$GATE_EXIT_VOCAB" ;;
        esac
        [ "$hatt" != "$hrec" ] || { warn "\`첨부\` cannot be the halt record itself: $hatt"; return "$GATE_EXIT_VOCAB"; }
        [ -s "$hatt" ] || { warn "the attachment does not exist or is empty: $hatt"; return "$GATE_EXIT_VOCAB"; }
        if grep -q '^<!-- cc-pipeline-halt v1' "$hatt"; then
          warn "the attachment carries a halt record header, so a halt-directory scan would read it as a record: $hatt"
          return "$GATE_EXIT_VOCAB"
        fi
        hattdig=$(shasum -a 256 "$hatt" | cut -d' ' -f1)
      fi
      # `근거 제출` TO A CLAUSE'S EVIDENCE REQUEST IS THE ATTACHMENT. The next
      # shift settles the clause on what the seat ran and saw, and the option
      # label carries none of that, so the answer is refused without the file
      # beside the record that holds it.
      if [ -n "$hsrow" ] && gate_clause_key_id "$seg" >/dev/null && [ "$hopt" = "근거 제출" ] \
         && [ "$hatt" != "${hrec%.md}.answer.md" ]; then
        warn "\`근거 제출\` carries \`첨부=${hrec%.md}.answer.md\` — what was run for the clause, on which commit, its exit status, the values observed and who ran it"
        return "$GATE_EXIT_RULE"
      fi
      hskill=$(sed -n 's/^\*\*스킬\*\*: //p' "$hrec" | sed -n '1p' | sed 's/[[:space:]]*$//')
      if [ -n "$hshift" ]; then
        # The shift's exception, in full. The step is read up to its first
        # ` — `, the same cut 「Handing on a person's answer to a halt」 item 2
        # makes, so the record this admits is exactly the one that item routes
        # to re-convergence. How many it may write is the manifest row's
        # `상한`, counted over the key's automatic `재수렴` answers, and the
        # same record re-converged once goes to a person — both are
        # `gate_halt_auto_answer_admit`'s, below, which the seat's answers pass
        # too. A person's earlier `재수렴` on another record of the key does not
        # use up the bound. And the record has to be the key's latest settled
        # halt, `gate_halt_auto_answer_current`'s, for both writers alike.
        hstep=$(sed -n 's/^\*\*스텝\*\*: //p' "$hrec" | sed -n '1p')
        hstep="${hstep%% — *}"
        while IFS= read -r hrow; do
          [ -n "$hrow" ] || continue
          hcls=$(printf '%s' "$hrow" | tr '|' '\n' | sed -n 's/^ *판단 부류=//p' | sed 's/[[:space:]]*$//' | tail -1)
          [ "$hcls" = "구속-이탈" ] && { hadopt=1; break; }
        done <<EOF
$(manifest_autoadopt_rows)
EOF
        if [ -z "$hadopt" ] || [ "$hskill" != "implement-unattended" ] \
           || [ "${hstep#*CFI-U3 BT-STOP}" = "$hstep" ] || [ "$hopt" != "재수렴" ]; then
          warn "a \`중단 답\` row is written by the seat only — a shift may write one only for an implement-unattended binding-tier stop (CFI-U3 BT-STOP) answered \`재수렴\`, under a \`자동 채택\` row of class 구속-이탈 in \`## 인가\`"
          return "$GATE_EXIT_RULE"
        fi
        hpre="자동 채택(구속-이탈) — "
      fi
      # A PERSON'S `골격 재검토` ON A RESIDUAL LADDER WAITS FOR THE KEY TO GO
      # QUIET. A row written while an attempt of the key is running — the
      # design stage re-attached on the seat's `잔여로 두고 동결` — is taken up
      # by that attempt's `정상 완료` together with the seat's answer, and the
      # design key's re-convergence then sees an answer a stage already took,
      # whose previous answer is not a freeze: the person's review would be
      # spent with nothing opened. Refused here, it is written again once the
      # freeze row stands, and the after-the-freeze entry opens.
      if [ "$hby" = "사람" ] && [ "$hopt" = "골격 재검토" ] && gate_stage_live_attempt "$seg"; then
        case "$(sed -n 's/^\*\*스텝\*\*: //p' "$hrec" | sed -n '1p')" in
          *'/ ladder-unsettled'*)
            warn "단계($seg)에 살아 있는 시도가 있는 동안에는 잔여 사다리 기록에 사람의 「골격 재검토」 를 쓰지 않습니다 — 그 시도가 끝나 행이 선 뒤 다시 쓰세요: $hrec"
            return "$GATE_EXIT_RULE" ;;
        esac
      fi
      if [ "$hby" != "사람" ]; then
        gate_halt_auto_answer_admit "$seg" "$hrec" "$hopt" || return "$?"
        gate_halt_auto_answer_current "$seg" "$hrec" || return "$?"
      fi
      # AN ANSWER NO BRANCH CAN CARRY OUT IS NOT RECORDED, whoever gave it.
      # Recorded, it sat in `answered_halts[]` as answered, so every reader
      # that counts unanswered records — the watcher's idle exit, rekick's
      # `사람 대기`, the seat's questions — passed over a record the shift could
      # only stop on. The refusal writes nothing, and its second line names
      # the labels that do route, so the seat can ask again with them.
      local hroutable
      if ! gate_halt_answer_route "$seg" "$hrec" "$hopt" "$hby" >/dev/null; then
        hroutable=$(gate_halt_answer_routable_options "$seg" "$hrec" "$hby")
        warn "실행할 수 있는 선택지: ${hroutable:-없음}"
        return "$GATE_EXIT_RULE"
      fi
      if [ "$hby" != "사람" ]; then
        if [ "$hby" = "교대" ]; then
          log "자동 채택 — 구속-이탈 ($seg ← 재수렴)"
        else
          log "자동 답 — 좌석이 기록의 추천을 고름 ($seg ← $hopt)"
        fi
      fi
      if [ -n "$hsa" ]; then hdig=$hsadig; else hdig=$(shasum -a 256 "$hrec" | cut -d' ' -f1); fi
      hlane=$(gate_lane_label)
      hat=$(now_iso)
      # The seat-apply fields are measured with a 40-character placeholder for
      # `좌석 커밋`, so a row that cannot fit is refused before anything is
      # committed rather than after, on the rollback path.
      while [ "$hw" -ge 40 ]; do
        hwhy=$(gate_row_safe "$hpre$(gate_field_of '근거' "$@")" "$hw")
        hlen=$(gate_row_projected_bytes '중단 답' "세그먼트=$seg" "중단 기록=$hrec" \
          "스킬=${hskill:-미상}" "선택지=$hopt" "답한 주체=$hby" "근거=$hwhy" \
          ${hkinds:+"근거 종류=$hkinds"} ${hsac:+"좌석 커밋=$hsac"} ${hsana:+"적용 파일=$hsana"} \
          ${hsafr:+"승인 프레임=$hsafr"} ${hsasn:+"적용 범위 수=$hsasn"} ${hsasd:+"적용 범위 다이제스트=$hsasd"} \
          ${hsacf:+"승계 프레임=$hsacf"} ${hsacr:+"승계 원본=$hsacr"} ${hsanh:+"사람 몫=$hsanh"} \
          ${hladder:+"잔여 판정=$hladder"} "기록 다이제스트=$hdig" ${hatt:+"첨부=$hatt"} ${hatt:+"첨부 다이제스트=$hattdig"} \
          "레인=$hlane" "기록 시각=$hat")
        [ "$hlen" -le "$GATE_ROW_MAX" ] && break
        hw=$((hw - 40))
      done
      [ "$hlen" -le "$GATE_ROW_MAX" ] || {
        if [ -n "$hsa" ]; then
          warn "the \`중단 답\` row of this seat apply does not fit the row cap even with \`근거\` clipped (${hlen} bytes over ${GATE_ROW_MAX}) — nothing was committed; a shorter record path or segment key is needed"
          return "$GATE_EXIT_RULE"
        fi
        warn "the \`중단 답\` row does not fit the row cap even with \`근거\` clipped — the option or the path is too long to record"
        return "$GATE_EXIT_VOCAB"; }
      # THE COMMIT, THEN THE ROW, AND THE COMMIT UNDONE WHEN THE ROW FAILS. The
      # commit is built off the working tree and lands by a fast-forward with
      # hooks and the filesystem monitor off — `merge` runs `post-merge`, and
      # `core.fsmonitor` can name a command — and refusing to overwrite an
      # ignored file. The tree was clean and at the base, so resetting the branch
      # to the base loses nothing. A process killed between the two leaves a
      # commit no row names, which the merge's provenance check refuses.
      if [ -n "$hsa" ] && [ "$hopt" = '좌석 적용' ]; then
        hsac=$(gate_seat_apply_build "$GATE_SA_WT") && [ -n "$hsac" ] || {
          warn "the seat-apply commit could not be built from the record — nothing was committed: $hrec"
          return "$GATE_EXIT_RULE"; }
        ( cd "$GATE_SA_WT" && git -c core.hooksPath=/dev/null -c core.fsmonitor=false \
            merge --ff-only --no-overwrite-ignore --quiet "$hsac" ) >/dev/null 2>&1 || {
          ( cd "$GATE_SA_WT" && git update-ref HEAD "$GATE_SA_BASE" \
              && git -c core.hooksPath=/dev/null reset --hard --quiet "$GATE_SA_BASE" ) >/dev/null 2>&1 || true
          warn "could not fast-forward the worktree of $seg to the seat-apply commit $hsac — the branch is back at $GATE_SA_BASE"
          return "$GATE_EXIT_RULE"; }
        if ! ( gate_append '중단 답' "세그먼트=$seg" "중단 기록=$hrec" "스킬=${hskill:-미상}" \
                 "선택지=$hopt" "답한 주체=$hby" "근거=$hwhy" ${hkinds:+"근거 종류=$hkinds"} \
                 "좌석 커밋=$hsac" "적용 파일=$hsana" \
                 ${hsafr:+"승인 프레임=$hsafr"} ${hsasn:+"적용 범위 수=$hsasn"} ${hsasd:+"적용 범위 다이제스트=$hsasd"} \
                 ${hsacf:+"승계 프레임=$hsacf"} ${hsacr:+"승계 원본=$hsacr"} ${hsanh:+"사람 몫=$hsanh"} \
                 "기록 다이제스트=$hdig" ${hatt:+"첨부=$hatt"} ${hatt:+"첨부 다이제스트=$hattdig"} \
                 "레인=$hlane" "기록 시각=$hat" ); then
          ( cd "$GATE_SA_WT" && git update-ref HEAD "$GATE_SA_BASE" \
              && git -c core.hooksPath=/dev/null reset --hard --quiet "$GATE_SA_BASE" ) >/dev/null 2>&1 \
            || warn "the branch of $seg could not be reset to $GATE_SA_BASE — $hsac is on it with no row naming it"
          warn "the \`중단 답\` row of the seat apply could not be written, so the commit $hsac was undone and the branch is back at $GATE_SA_BASE"
          return "$GATE_EXIT_RULE"
        fi
        log "좌석 적용 — $seg ← $hsac ($GATE_SA_NA 파일, $hby)"
        printf '좌석 커밋=%s\n' "$hsac"
      else
        # ITS ONE READER IS THE SNAPSHOT'S `answered_halts[]`, which a shift
        # routes from. It enters no termination condition and no progress
        # vector, and nothing is notified from it.
        gate_append '중단 답' "세그먼트=$seg" "중단 기록=$hrec" "스킬=${hskill:-미상}" \
          "선택지=$hopt" "답한 주체=$hby" "근거=$hwhy" ${hkinds:+"근거 종류=$hkinds"} \
          ${hsanh:+"사람 몫=$hsanh"} ${hladder:+"잔여 판정=$hladder"} "기록 다이제스트=$hdig" \
          ${hatt:+"첨부=$hatt"} ${hatt:+"첨부 다이제스트=$hattdig"} \
          "레인=$hlane" "기록 시각=$hat"
      fi
      log "중단 답 기록 — $seg ← $hopt ($hby)"
      ;;
    shift-halt)
      # THE SHIFT STOPS ONE SEGMENT, NOT THE RUN. A segment-scope stop used to
      # end the shift with `handoff 사유=중단`, so one segment's question held
      # every sibling until morning — measured: a run whose one segment met a
      # merge refusal stopped the four segments that did not depend on it. This
      # writes the question as a halt record the seat can answer and a cone row
      # that holds only what stands on that segment, and the shift goes on.
      #
      # THE GATE WRITES THE RECORD, not the shift. The options are the site
      # table's, the recommendation is checked against the files it quotes, and
      # the row carries the digest of the exact bytes written — so the seat
      # answers a record whose every line the gate vouches for.
      if cc_caller_is_stage || { [ -z "$(gate_shift_self_ordinal)" ] && [ -z "${CC_PIPELINE_SHIFT_ID:-}" ]; }; then
        warn "\`shift-halt\` is written by the routing shift only — a stage halts with its own record, and the seat asks a person directly"
        return "$GATE_EXIT_RULE"
      fi
      local sf sk ssite sq sobs srec sgr srow sinfo sopts sdir sn sdst stmp sdig sord r
      local sw=300 slen sline sexp
      for sf in "$@"; do
        sk="${sf%%=*}"
        case "$sk" in 자리|질문|관측|추천|추천\ 근거|절) continue ;; esac
        warn "\`shift-halt\` takes \`자리\`, \`질문\`, \`관측\`, an optional \`추천\`, an optional \`추천 근거\` and, at \`종료 절 근거\` only, \`절\` from argv and nothing else: ${sk} — the rest is the gate's"
        return "$GATE_EXIT_VOCAB"
      done
      ssite=$(gate_field_of '자리' "$@")
      if [ -n "$GATE_SHIFT_HALT_SITE" ] && [ -n "$ssite" ] && [ "$ssite" != "$GATE_SHIFT_HALT_SITE" ]; then
        warn "\`--site\` and \`자리\` name two different sites: $GATE_SHIFT_HALT_SITE / $ssite"
        return "$GATE_EXIT_VOCAB"
      fi
      [ -n "$ssite" ] || ssite=$GATE_SHIFT_HALT_SITE
      srow=$(gate_shift_halt_site_row "$ssite") || {
        warn "\`${ssite:-(none)}\` is not a site of the shift-halt table — a run-scope stop stays a \`handoff\` with \`사유=중단\`"
        return "$GATE_EXIT_VOCAB"; }
      sq=$(gate_field_of '질문' "$@")
      sobs=$(gate_field_of '관측' "$@")
      [ -n "$sq" ] && [ -n "$sobs" ] || {
        warn "\`shift-halt\` needs \`질문\` (what a person is asked) and \`관측\` (what the shift saw)"
        return "$GATE_EXIT_VOCAB"; }
      local sclause
      sclause=$(gate_field_of '절' "$@")
      if [ "$ssite" = "종료 절 근거" ]; then
        # A CLAUSE'S EVIDENCE REQUEST STOPS NO SEGMENT. The key is the gate's
        # own `clause-<id>`, so a shift cannot misspell it into a segment id,
        # and the cone stands on that one key.
        case "$seg" in ''|-) ;; *)
          warn "\`종료 절 근거\` stops no segment — call it with \`--segment -\` and name the clause in \`절\`"
          return "$GATE_EXIT_VOCAB" ;;
        esac
        [ -n "$sclause" ] || {
          warn "\`종료 절 근거\` needs \`절=<id>\` — the termination clause whose evidence is asked for"
          return "$GATE_EXIT_VOCAB"; }
        gate_clause_key_id "clause-$sclause" >/dev/null || {
          warn "the manifest declares no termination clause $sclause"
          return "$GATE_EXIT_RULE"; }
        case "$(gate_clause_last_state "$sclause")" in
          충족|불가능)
            warn "termination clause $sclause is already settled as $(gate_clause_last_state "$sclause") — no evidence is asked for it"
            return "$GATE_EXIT_RULE" ;;
        esac
        seg="clause-$sclause"
        # One open request per clause, except the one the shift writes when an
        # answer's attachment fell short: that request carries the answer out,
        # so an answered request does not refuse its successor.
        local cl_open cl_ans
        cl_open=$(gate_clause_open_request "$sclause")
        if [ -n "$cl_open" ]; then
          cl_ans=$( { grep -n "^- \`중단 답\` " "$LEDGER" 2>/dev/null || true; } \
                    | { grep -F "| 중단 기록=$cl_open |" || true; } | tail -1)
          if [ -z "$cl_ans" ] || [ "$(gate_row_field "${cl_ans#*:}" '선택지')" != "근거 제출" ]; then
            warn "an evidence request for termination clause $sclause is still waiting for its answer to be carried out: $cl_open"
            return "$GATE_EXIT_RULE"
          fi
        fi
      else
        [ -z "$sclause" ] || {
          warn "\`절\` rides only at \`종료 절 근거\`: $ssite"
          return "$GATE_EXIT_VOCAB"; }
        [ -n "$(gate_segment_field "$seg" '상태')" ] || {
          warn "there is no segment row for $seg — a shift stops a segment the ledger knows"
          return "$GATE_EXIT_VOCAB"; }
      fi
      # A SEGMENT WHOSE ANSWER IS CARRIED OVER IS NOT STOPPED AGAIN. The person
      # already answered its halt and the next run takes the answer up; a shift
      # record here would put a second question about the same stop before them.
      sline=$(gate_key_deferred_answer "$seg")
      if [ -n "$sline" ]; then
        warn "$seg 의 중단 답(원장 ${sline} 번째 줄)은 다음 런으로 넘겼습니다 — 이 세그먼트에 교대 정지 기록을 쓰지 않습니다"
        return "$GATE_EXIT_RULE"
      fi
      srec=$(gate_field_of '추천' "$@")
      sgr=$(gate_field_of '추천 근거' "$@")
      sinfo=$(printf '%s' "$srow" | cut -d'|' -f3)
      if [ "$(printf '%s' "$srow" | cut -d'|' -f2)" = "없음" ]; then
        # Dropped, not refused: the site settles that no record of the run
        # answers it, so the shift's argument changes nothing it could change.
        [ -z "$srec$sgr" ] || warn "$ssite 은 추천을 싣지 않는 자리입니다 — 넘어온 추천을 버리고 (없음) 으로 씁니다"
        srec=''; sgr=''
      elif [ -n "$srec" ]; then
        case "$srec" in
          재시도|'세그먼트 park') ;;
          *) warn "\`추천\` has to be one of this site's option labels byte for byte (\`재시도\` · \`세그먼트 park\`): $srec"
             return "$GATE_EXIT_RULE" ;;
        esac
        gate_shift_halt_grounds "$alias" "$sgr" || return "$?"
      elif [ -n "$sgr" ]; then
        warn "\`추천 근거\` without \`추천\` grounds nothing"
        return "$GATE_EXIT_VOCAB"
      fi
      sdir=$(gate_shift_halt_dir) || {
        warn "this run's halt/shift is not a real directory at $RUN_DIR/halt/shift — the record is not written"
        return "$GATE_EXIT_RULE"; }
      sn=1
      while IFS= read -r r; do
        [ -n "$r" ] || continue
        [ "$(gate_row_field "$r" '스코프')" = "cone" ] || continue
        [ "$(gate_row_field "$r" '앵커 세그먼트')" = "$seg" ] || continue
        [ -n "$(gate_row_field "$r" '중단 기록')" ] || continue
        [ -n "$(gate_row_field "$r" '기록 다이제스트')" ] || continue
        sn=$((sn + 1))
      done <<EOF
$(gate_rows 'blocked')
EOF
      sdst="$sdir/$seg#$sn.md"
      sopts=$(gate_shift_halt_options "$ssite")
      stmp=$(mktemp "$sdir/.shift-halt.XXXXXX") || {
        warn "could not make a temporary file under $sdir"
        return "$GATE_EXIT_RULE"; }
      {
        printf '<!-- cc-pipeline-halt v1; writer=gate; reader=orchestrator; stage=%s#%s; run=%s -->\n' "$seg" "$sn" "$RUN_ID"
        printf '**중단 시각**: %s\n' "$(now_iso)"
        printf '**스킬**: autopilot-router-shift\n'
        printf '**스텝**: 교대 정지 — %s\n' "$ssite"
        printf '**분류**: gate-unanswerable\n'
        printf '**질문 문면**: %s\n' "$(printf '%s' "$sq" | tr '\n\r' '  ')"
        printf '**선택지**:\n%s\n' "$sopts"
        if [ -n "$srec" ]; then
          printf '**추천**: `%s` — 추천 근거의 인용이 이 선택지를 정한다\n' "$srec"
          printf '**추천 근거**: %s\n' "$(printf '%s' "$sgr" | tr '\n\r' '  ')"
        else
          printf '**추천**: (없음) — %s\n' "$sinfo"
          printf '**추천 근거**: (없음)\n'
        fi
        printf '**하네스 오류**: (없음)\n'
        printf '**관측 상세**: %s\n' "$(printf '%s' "$sobs" | tr '\n\r' '  ')"
        printf '**재호출 명령**: (없음)\n'
        printf '**후속**: 보류 큐\n'
        printf '<!-- /cc-pipeline-halt v1 -->\n'
      } > "$stmp" || { rm -f "$stmp"; warn "could not write the halt record"; return "$GATE_EXIT_RULE"; }
      sdig=$(shasum -a 256 "$stmp" | cut -d' ' -f1)
      # `mv -n` NEVER REPLACES. A file already at the name is either an earlier
      # record this count missed or something placed there to be answered in
      # this record's stead, and both are refused with no row written.
      mv -n "$stmp" "$sdst" 2>/dev/null || true
      if [ -e "$stmp" ]; then
        rm -f "$stmp"
        warn "a file is already at $sdst — the record is not written and no row is added"
        return "$GATE_EXIT_RULE"
      fi
      sord=$(gate_shift_self_ordinal)
      sexp=$(printf '%*s' "$GATE_CONE_LIST_MAX" '' | tr ' ' 'x')
      while [ "$sw" -ge 40 ]; do
        sline=$(gate_row_safe "$sobs" "$sw")
        slen=$(gate_row_projected_bytes 'blocked' "대상=$alias" '스코프=cone' '원인=막힘' \
          "앵커 세그먼트=$seg" "사유=교대 정지 — $ssite" "근거=$sline" "중단 기록=$sdst" \
          "기록 다이제스트=$sdig" "자리=$ssite" ${sord:+"교대=$sord"} \
          '의존 세그먼트 수=999' "의존 세그먼트=$sexp")
        [ "$slen" -le "$GATE_ROW_MAX" ] && break
        sw=$((sw - 40))
      done
      r=0
      GATE_SHIFT_HALT_WRITING=1 gate_record_cone "$alias" '스코프=cone' '원인=막힘' \
        "앵커 세그먼트=$seg" "사유=교대 정지 — $ssite" "근거=$sline" "중단 기록=$sdst" \
        "기록 다이제스트=$sdig" "자리=$ssite" ${sord:+"교대=$sord"} || r=$?
      if [ "$r" != "0" ]; then
        # A record with no row is one nothing vouches for and every halt scan
        # would still count, so it goes with the row that failed.
        rm -f "$sdst"
        return "$r"
      fi
      log "교대 정지 기록 — $seg ($ssite) → $sdst"
      ;;
    review-dismiss)
      # THE SEAT'S WAY TO CARRY A PERSON'S DISMISSAL OF REVIEW FINDINGS TO THE
      # MERGE. The merge rule and the apply precondition read the segment's last
      # `cycle` row and refuse while P0 or P1 is above zero, and nothing else
      # could change that but another review cycle — which re-raises a finding
      # the reviewer still holds. Measured: two cycles raised the same P0 about
      # an operational precondition outside the declared files, a person
      # answered two halt records keeping the design as it was, and the run
      # dead-ended because no row could carry that answer to the merge check.
      #
      # SEAT ONLY, judged as `limit-cleared` judges it. A shift or a stage
      # writing this row would be the run waving its own review through.
      if [ -n "$(gate_shift_self_ordinal)" ] || cc_caller_is_stage \
         || [ -n "${CC_PIPELINE_SHIFT_ID:-}" ]; then
        warn "a \`리뷰 기각\` row is written by the seat only — a shift or a stage cannot dismiss review findings for a person"
        return "$GATE_EXIT_RULE"
      fi
      local df dk dcyc dhead dwhy dw=300 dlen drow dlane dat dp0 dp1 drep
      for df in "$@"; do
        dk="${df%%=*}"
        case "$dk" in 사이클|리뷰\ HEAD|근거) continue ;; esac
        warn "a \`리뷰 기각\` row takes \`사이클\`, \`리뷰 HEAD\` and \`근거\` from argv and nothing else: ${dk} — the rest is the gate's"
        return "$GATE_EXIT_VOCAB"
      done
      dcyc=$(gate_field_of '사이클' "$@")
      dhead=$(gate_field_of '리뷰 HEAD' "$@")
      dwhy=$(gate_field_of '근거' "$@")
      [ -n "$dcyc" ] && [ -n "$dhead" ] && [ -n "$dwhy" ] || {
        warn "a \`리뷰 기각\` row needs \`사이클\` and \`리뷰 HEAD\` (of the cycle the person looked at) and \`근거\` (a summary of what the person said)"
        return "$GATE_EXIT_VOCAB"; }
      # BOUND TO THE LAST CYCLE, BY NUMBER AND BY HEAD. A person dismisses what
      # they looked at; a cycle recorded after that is a review they have not
      # seen, and a dismissal naming an older one would wave the newer through.
      drow=$(gate_segment_last_cycle_row "$seg")
      [ -n "$drow" ] || { warn "no \`cycle\` row names $seg — there is no review to dismiss"; return "$GATE_EXIT_VOCAB"; }
      if [ "$(gate_row_field "$drow" '사이클')" != "$dcyc" ] \
         || [ "$(gate_row_field "$drow" '리뷰 HEAD')" != "$dhead" ]; then
        warn "the last \`cycle\` row of $seg is 사이클=$(gate_row_field "$drow" '사이클') 리뷰 HEAD=$(gate_row_field "$drow" '리뷰 HEAD') — a dismissal names that cycle exactly"
        return "$GATE_EXIT_VOCAB"
      fi
      dp0=$(gate_row_field "$drow" 'P0'); dp1=$(gate_row_field "$drow" 'P1')
      if [ "${dp0:-0}" = "0" ] && [ "${dp1:-0}" = "0" ]; then
        warn "the last \`cycle\` row of $seg has no findings to dismiss (P0=0 P1=0)"
        return "$GATE_EXIT_VOCAB"
      fi
      drep=$(gate_row_field "$drow" '리포트 경로')
      dlane=$(gate_lane_label)
      dat=$(now_iso)
      while [ "$dw" -ge 40 ]; do
        dwhy=$(gate_row_safe "$(gate_field_of '근거' "$@")" "$dw")
        dlen=$(gate_row_projected_bytes '리뷰 기각' "세그먼트=$seg" "사이클=$dcyc" \
          "리뷰 HEAD=$dhead" "기각 P0=${dp0:-0}" "기각 P1=${dp1:-0}" "리포트 경로=${drep:--}" \
          "근거=$dwhy" "레인=$dlane" "기록 시각=$dat")
        [ "$dlen" -le "$GATE_ROW_MAX" ] && break
        dw=$((dw - 40))
      done
      [ "$dlen" -le "$GATE_ROW_MAX" ] || {
        warn "the \`리뷰 기각\` row does not fit the row cap even with \`근거\` clipped"
        return "$GATE_EXIT_VOCAB"; }
      # ITS READERS ARE THE MERGE RULE (through GATE_SEGMENT_REVIEW_DISMISSED),
      # THE APPLY PRECONDITION AND THE SNAPSHOT'S `cycles[].기각`. Each honours
      # it only while the segment's last `cycle` row is still the one it names.
      gate_append '리뷰 기각' "세그먼트=$seg" "사이클=$dcyc" "리뷰 HEAD=$dhead" \
        "기각 P0=${dp0:-0}" "기각 P1=${dp1:-0}" "리포트 경로=${drep:--}" \
        "근거=$dwhy" "레인=$dlane" "기록 시각=$dat"
      log "리뷰 기각 기록 — $seg 사이클 $dcyc (P0=${dp0:-0} P1=${dp1:-0})"
      ;;
    halt-settle)
      # A PERSON'S ANSWER TO A RE-CONVERGENCE HALT, SETTLED WITHOUT A SESSION.
      # The shift tries it before carrying such an answer, and on a refusal
      # carries the answer as before. It launches nothing, asks no router and
      # writes nothing in a tree — so it is bookkeeping, and a run past its
      # deadline still takes it: what it records is an answer a person gave.
      #
      # ARGV IS THE ANSWER'S LINE AND NOTHING ELSE. The key is --segment, and
      # the verdict and the document's value come from the record the answer
      # names, never from the caller.
      if cc_caller_is_stage; then
        warn "\`halt-settle\` is the routing shift's act — a stage does not settle an answer to a halt"
        return "$GATE_EXIT_RULE"
      fi
      local hsf hsk hsl
      for hsf in "$@"; do
        hsk="${hsf%%=*}"
        [ "$hsk" = "중단 답 줄" ] && continue
        warn "\`halt-settle\` takes \`중단 답 줄=<n>\` from argv and nothing else: ${hsk} — the key is --segment and the verdict is the record's"
        return "$GATE_EXIT_VOCAB"
      done
      hsl=$(gate_field_of '중단 답 줄' "$@")
      case "$hsl" in
        ''|*[!0-9]*|0*) warn "\`halt-settle\` needs \`중단 답 줄=<n>\`, a ledger line number"
           return "$GATE_EXIT_VOCAB" ;;
      esac
      gate_halt_settle "$seg" "$hsl" || return "$?"
      ;;
    replan)
      # A SIBLING'S PLAN, VOIDED BY ANOTHER SEGMENT'S RE-CONVERGENCE. The
      # re-convergence moved the binding surface, and a plan derived before it
      # would be carried into process B on a document that is no longer the one
      # it read. The row resets `implement_process_b` the way a re-convergence
      # row does, so the sibling's next implement dispatch is process A.
      #
      # ARGV IS THE CITE KEY AND NOTHING ELSE. The segment is `--segment`, and
      # `회차` is counted here — a caller that could supply it could reset the
      # cap. Every clause is the one `gate_replan_eval` decides, the same call
      # `replan_due[]` makes, so the snapshot and this refusal cannot disagree.
      local rpf rpk rpc
      for rpf in "$@"; do
        rpk="${rpf%%=*}"
        [ "$rpk" = "재수렴" ] && continue
        warn "\`replan\` takes \`재수렴=<스테이지>#<실행 버전>\` from argv and nothing else: ${rpk} — the segment is --segment and the round is counted by the gate"
        return "$GATE_EXIT_VOCAB"
      done
      rpc=$(gate_field_of '재수렴' "$@")
      [ -n "$rpc" ] || { warn "\`replan\` needs \`재수렴=<스테이지>#<실행 버전>\`"; return "$GATE_EXIT_VOCAB"; }
      # A RUN THAT HAS ENDED IS NOT RE-PLANNED. The plan file would move under a
      # run nothing will dispatch again, and the row would say a sibling is to be
      # planned afresh by a run that is over.
      if [ -s "$RUN_DIR/done" ]; then
        warn "this run has already ended — a re-plan is not recorded after the end"
        return "$GATE_EXIT_RULE"
      fi
      if ! gate_replan_eval "$seg" "$rpc"; then
        warn "re-plan of $seg citing $rpc is refused — clause $GATE_REPLAN_CLAUSE: $GATE_REPLAN_WHY"
        return "$GATE_EXIT_RULE"
      fi
      # THE PLAN FILE MOVES FIRST, THEN THE ROW. A row without the move leaves a
      # plan file both implement-row writers fall back to hashing, so a process A
      # that died before writing its new plan would put the void digest back
      # after the row. A move without the row is a plan file the next process A
      # replaces anyway.
      void_segment_plan "$seg"
      gate_append '재계획' "세그먼트=$seg" "재수렴=$rpc" "회차=$GATE_REPLAN_ROUND"
      log "형제 재계획 — $seg ($rpc 인용, 회차 $GATE_REPLAN_ROUND): 다음 구현 파견은 과정 A 입니다"
      ;;
    base-check)
      # A read of the remote and an isolated merge, and one row. The routing
      # shift calls it before a merge; every check lives in the row builder.
      gate_base_check_row "$seg" "$alias" "$@" || return $?
      ;;
    remote-check)
      # A read of the remote, written as `원격 판독` rows only where a value
      # moved; the act row beside it records that the read was made.
      if [ $# -gt 0 ]; then
        warn "\`remote-check\` takes nothing after -- — what it reads is the gate's: $*"
        return "$GATE_EXIT_VOCAB"
      fi
      gate_remote_state_refresh "$alias" "$seg"
      ;;
    review-carry)
      # The carry-over twin of `review-dismiss`, without its seat-only refusal:
      # the routing shift writes this row after opening one issue per
      # carry-over finding. Every check lives in the row builder the driver
      # calls too.
      gate_review_carry_row "$seg" "$@" || return $?
      log "리뷰 이월 기록 — $seg 사이클 $(gate_field_of '사이클' "$@") (이슈 $(gate_field_of '건수' "$@")건)"
      ;;
    obligation)
      # THE ONLY EXIT FROM TERMINATION CONDITION 9. `리뷰 의무` rows are written
      # in exactly one place and always as `상태=미이행`, nothing in the tree
      # wrote `상태=이행`, and the router's row-writing kinds did not include the
      # series — so the condition held against every run that ever deferred a
      # review, and no such run could propose that it was done. Condition 3's
      # excusal is for a different series and does not reach this one. The
      # refusal read as the mechanism working, which is why it survived until a
      # run tried to finish.
      #
      # Fulfilling is an APPEND, not an edit: the reader takes the LAST row per
      # obligation id, so the issuing row stays where it is and the morning can
      # still see both when the review was deferred and when it landed.
      local oid oprior ost oalias oseg omerge olanding ocover overdict orhead
      oid=$(gate_field_of '의무 id' "$@")
      [ -n "$oid" ] || { warn "an obligation row needs \`의무 id\`"; return "$GATE_EXIT_VOCAB"; }
      # Evidence, on the same terms the `blocked` arm already demands it. An
      # obligation closed on the router's say-so is a review that did not happen
      # and left a row saying it did — which is worse than leaving it open,
      # because the open one is at least visible in the morning.
      [ -n "$(gate_field_of '근거' "$@")" ] \
        || { warn "an obligation row needs \`근거\` — what was looked at to judge it fulfilled is all that is left in the morning"; return "$GATE_EXIT_VOCAB"; }
      oprior=$( { gate_rows '리뷰 의무' | grep -F "의무 id=$oid " || true; } | tail -1)
      if [ -z "$oprior" ]; then
        warn "there is no review obligation row to fulfill: ${oid}"
        return "$GATE_EXIT_VOCAB"
      fi
      ost=$(gate_row_field "$oprior" '상태')
      if [ "$ost" != "미이행" ]; then
        warn "this review obligation is already closed: ${oid} (\`상태\`=${ost:-(none)})"
        return "$GATE_EXIT_VOCAB"
      fi
      oalias=$(gate_row_field "$oprior" '대상')
      oseg=$(gate_row_field "$oprior" '세그먼트')
      omerge=$(gate_row_field "$oprior" '머지 커밋')

      # `--target` IS COMPARED AND NOT MERELY RECORDED. The landing test below
      # runs in the anchor repository of the target the merge was authorized
      # against, so a fulfillment aimed at a different target measures the right
      # commit in the wrong repository and reports 미착지 with full confidence.
      # The code is the vocabulary one because every other refusal in this arm is,
      # and because the repair really is to fix the argv — which is exactly what 2
      # tells the router to do.
      if [ -n "$oalias" ] && [ "$oalias" != "-" ] && [ "$alias" != "$oalias" ]; then
        warn "the target of obligation ${oid} is '$oalias', but --target says '$alias'"
        warn "call again with the target that row names — the repository the landing judgment runs in differs per target"
        return "$GATE_EXIT_VOCAB"
      fi

      # LANDING FIRST, CONTAINMENT SECOND. Reversed, a merge that never landed is
      # judged on whether some review covered it, and the retry path for that
      # merge breaks along with the judgment.
      #
      # A row carrying `머지 커밋=-` predates the anchor and cannot be measured at
      # all, so it passes with `이행 판정=앵커 없음` rather than being refused —
      # refusing it would strand obligations written before this field existed.
      # THIS ARM DISAPPEARS when `리뷰 의무` rows with `머지 커밋=-` reach zero at
      # the ledger root, and nothing else expires it.
      if [ -z "$omerge" ] || [ "$omerge" = "-" ]; then
        overdict='앵커 없음'
      else
        # CALLED PLAINLY, never through `$(…)`: the sentence rides on a global and
        # a command substitution runs the predicate in a subshell, which discards
        # it. The verdict rides on a global for the same reason.
        gate_obligation_landing "${oalias:-$alias}" "$omerge"
        olanding="$GATE_LANDING_VERDICT"
        case "$olanding" in
          미착지) overdict='미착지' ;;
          착지)
            orhead=$(gate_segment_review_head "$oseg")
            gate_obligation_covers "${oalias:-$alias}" "$omerge" "$orhead"
            ocover="$GATE_COVER_VERDICT"
            case "$ocover" in
              '덮는다') overdict='착지·포함' ;;
              '덮지 않는다')
                warn "no review covers the merge commit ${omerge} of obligation ${oid}: ${GATE_COVER_WHY}"
                warn "record a cycle row that covers that commit first, then call again with the same argv"
                return "$GATE_EXIT_VOCAB" ;;
              *)
                warn "could not judge whether obligation ${oid} is covered: ${GATE_COVER_WHY}"
                return "$GATE_EXIT_VOCAB" ;;
            esac ;;
          *)
            # 판정 불가 IS A REFUSAL AND NEVER A VALUE — there is no row to carry
            # it on, because the row exists only when the obligation is fulfilled.
            # The exit code is shared with the other refusals here and the SENTENCE
            # carries the distinction: which of fetch, ref or ancestry failed to
            # answer. No automatic retry sits here either — how many attempts at
            # what interval is not a number anybody has measured.
            warn "could not judge the landing of obligation ${oid}: ${GATE_LANDING_WHY}"
            warn "there is no automatic retry — call again with the same argv once the judgment becomes possible"
            return "$GATE_EXIT_VOCAB" ;;
        esac
      fi

      # The carried fields come from the row being closed and never from argv.
      # `세그먼트` is what ties the fulfillment to the merge it belongs to,
      # `생성 등급` is the value the excusal rule reads later, and `대상` names the
      # repository the landing test just ran in — a router that could restate any
      # of them could also restate it wrongly. They sit AFTER `"$@"` so the
      # router's argv is overwritten rather than merely accompanied.
      #
      # `이행 판정` IS WRITTEN ON EVERY BRANCH. Written conditionally it becomes a
      # key outside the carried set, the router's argv survives in that position,
      # and the field built to COUNT exemptions turns into the handle that inflates
      # them. Its value set is closed at three; there is no fourth and no
      # `판정 불가`, because that outcome refused above and left no row.
      gate_append '리뷰 의무' "$@" "상태=이행" \
        "세그먼트=$oseg" \
        "대상=${oalias:-$alias}" \
        "머지 커밋=$omerge" \
        "생성 등급=$(gate_row_field "$oprior" '생성 등급')" \
        "이행 판정=$overdict" \
        "발행 시각=$(gate_row_field "$oprior" '발행 시각')" \
        "이행 시각=$(now_iso)"
      # THE LANDING SENTENCE IS LOGGED EVEN WHEN NOTHING WAS REFUSED. `미착지` is
      # a passing disposition, so without this line the only witness to WHY it
      # did not land is a variable nobody reads — and the two 미착지 sentences
      # differ in the one way an operator acts on: one says the base does not
      # contain it yet, the other that no retry will ever make it.
      log "리뷰 의무 이행 $oid — 대상 ${oalias:-$alias} · 이행 판정 $overdict${GATE_LANDING_WHY:+ · $GATE_LANDING_WHY}"
      ;;
    obligation-done|obligation-drop)
      # CLOSING AN OBLIGATION THE RUN ACTUALLY DISCHARGED. Until this arm the
      # open set could only grow: the list emitted every problem identity and
      # nothing subtracted, `act --kind obligation` refuses everything outside
      # the review-obligation series, and the one exit — the excusal — opens only
      # for a creating grade at or below `워크트리쓰기`, while a REFUSED act
      # structurally carries `등급 미상`. Refusal is the main way problem rows
      # come to exist, so the narrow excuse missed the dominant case by
      # construction and termination condition 3 could not be satisfied at all.
      #
      # TWO VERBS AND NOT ONE, because the two differ in TENSE and therefore in
      # when they are checked. `종결` says the obligation's content was
      # discharged; its evidence is a past act row and the past cannot be
      # rewritten, so it is never re-verified. `포기` says this run has decided
      # not to do it; that leans on the segment being terminal, which is a
      # present-tense claim on a reversible field, so it is re-verified at
      # exclusion time in `gate_obligation_disposition` rather than trusted from
      # here. Checking `포기` only at write time would make it a permanent
      # verdict standing on a field the run can rewrite — the amnesty defect this
      # slice exists to remove.
      #
      # The row grades `읽기` like every other bookkeeping act, and deliberately.
      # It touches nothing outside the ledger, so a higher grade would be false;
      # and once recording spends the authorization budget the router is pushed
      # toward recording less, which is the force that produced this whole
      # defect. Raising the grade would not stop the evasion either — an evasion
      # is mounted by OPENING obligations, so a toll on closing them is a
      # defence on the wrong axis.
      local odisp oseries oident ooid owhy oanchors oanchor oaline opline
      local oother oprior oseg orow okey ot
      case "$kind" in
        obligation-done) odisp='종결'; oseries='의무 종결' ;;
        *)               odisp='포기'; oseries='의무 포기' ;;
      esac
      oident=$(gate_field_of '동일성' "$@")
      if [ -z "$oident" ]; then
        warn "${oseries} 행에 「동일성」이 필요합니다 — 닫으려는 의무를 problem 행이 실은 자유 텍스트 동일성으로 지목하세요"
        return "$GATE_EXIT_VOCAB"
      fi
      # The identity is taken and the derived id is computed HERE rather than
      # accepted from argv. A router that could restate the id could also restate
      # it wrongly, and the wrong obligation would close silently.
      opline=$(gate_problem_last_line "$oident")
      if [ -z "$opline" ]; then
        warn "그 동일성의 problem 행이 원장에 없습니다: ${oident}"
        return "$GATE_EXIT_VOCAB"
      fi
      oprior=$(gate_obligation_disposition "$oident")
      if [ -n "$oprior" ]; then
        warn "이미 처분된 의무입니다: ${oident} (처분=${oprior})"
        return "$GATE_EXIT_VOCAB"
      fi
      ooid=$(gate_obligation_id "$oident")
      # 충돌 거절 — two OPEN obligations deriving the same id. The id is eight hex
      # digits, so a collision is possible however unlikely, and without this
      # clause the residual is not "a rare hash collision" but "the wrong
      # obligation closes" — a reader keyed on the id cannot tell which bundle
      # the row meant. Refusing is the only disposition that keeps the id usable
      # as a key.
      oother=$( { gate_open_obligations | sed 's/^obligation=//' || true; } \
                | while IFS= read -r orow; do
                    [ -n "$orow" ] || continue
                    if [ "$orow" != "$oident" ] \
                       && [ "$(gate_obligation_id "$orow")" = "$ooid" ]; then
                      printf '%s\n' "$orow"
                    fi
                  done )
      if [ -n "$oother" ]; then
        warn "의무 식별자 ${ooid} 이 열린 의무 둘에서 유도됩니다 — 종결을 거절합니다"
        warn "  지목한 것: ${oident}"
        warn "  충돌하는 것: $(printf '%s' "$oother" | tr '\n' ' ')"
        return "$GATE_EXIT_RULE"
      fi
      owhy=$(gate_field_of '근거' "$@")
      if [ -z "$owhy" ]; then
        warn "${oseries} 행에 「근거」가 필요합니다"
        return "$GATE_EXIT_VOCAB"
      fi
      # EVIDENCE LAYER 1, and the gate resolves layer 1 ONLY. What it can check is
      # that the rationale names an object findable in this ledger and that the
      # object came AFTER the problem row. Whether that act actually discharged
      # the obligation is layer 2, and the gate cannot decide it — so it does not
      # pretend to. That residual is carried to the morning by the terminal
      # enumeration, which names each disposed obligation beside its anchor.
      oanchors=$(gate_obligation_evidence_anchors "$owhy")
      if [ -z "$oanchors" ]; then
        warn "산문만인 근거는 통과하지 못합니다 — 원장에서 찾을 수 있는 객체를 하나 이상 지목하세요"
        warn "  인정되는 형태: 행 앵커 A-<8자리 16진> · 승인 id J-<8자리 16진> · 리뷰 의무 id RO-… · 이 원장의 세그먼트 id"
        return "$GATE_EXIT_VOCAB"
      fi
      while IFS= read -r oanchor; do
        [ -n "$oanchor" ] || continue
        oaline=$(gate_evidence_row_line "$oanchor")
        if [ -z "$oaline" ]; then
          warn "근거가 지목한 ${oanchor} 을 원장에서 찾을 수 없습니다"
          return "$GATE_EXIT_VOCAB"
        fi
        # THE ORDER CHECK IS THE ONE THAT CARRIES WEIGHT AT LAYER 1. It blocks the
        # cheapest forgery there is — reaching up the ledger for any identifier
        # already lying around — because without it a freshly opened obligation
        # can be closed by something that existed before it.
        if [ "$oaline" -le "$opline" ]; then
          warn "근거 ${oanchor} 은 닫으려는 문제 행보다 원장에서 앞에 있습니다 (근거 ${oaline}행 · 문제 ${opline}행)"
          return "$GATE_EXIT_RULE"
        fi
        # 증폭 방지 — one anchor closes one obligation. This file already holds the
        # same discipline for a held termination clause, and the comment there
        # names the reason: what is refused is the amplification, not the single
        # answer.
        #
        # COMPARED BY THE OBJECT RESOLVED, NOT BY THE SPELLING. A `grep -F` of the
        # token over earlier closing rows let an extension (`RO-f` → `RO-foo`) or a
        # second spelling of the same row through, and refused `S1` because an
        # earlier row cited `S1-x`. Each earlier closing row's anchors are resolved
        # again here; the id arms resolve to a first declaration, so the answer is
        # the one they got when that row was written. A segment is keyed by its id
        # whichever spelling names it — the bare id, or an `A-` on one of its
        # `segment` rows — so those two spellings collide as well.
        okey=$(gate_evidence_object_key "$oanchor")
        oprior=$( { gate_rows '의무 종결'; gate_rows '의무 포기'; } \
                  | while IFS= read -r orow; do
                      [ -n "$orow" ] || continue
                      gate_obligation_evidence_anchors "$(gate_row_field "$orow" '근거')" \
                        | while IFS= read -r ot; do
                            [ -n "$ot" ] || continue
                            if [ "$(gate_evidence_object_key "$ot")" = "$okey" ]; then
                              printf '%s\n' "$orow"
                            fi
                          done
                    done | tail -1)
        if [ -n "$oprior" ]; then
          warn "근거 앵커 ${oanchor} 이 가리키는 객체는 이미 의무 $(gate_row_field "$oprior" '의무 id') 을 닫는 데 쓰였습니다 — 근거 하나가 여러 의무를 닫을 수 없습니다"
          return "$GATE_EXIT_RULE"
        fi
      done <<GATE_OBL_ANCHORS
$oanchors
GATE_OBL_ANCHORS
      if [ "$kind" = "obligation-drop" ]; then
        if ! gate_obligation_segments_terminal "$oident"; then
          warn "포기는 그 의무를 실은 problem 행의 세그먼트가 전부 종단일 것을 요구합니다"
          return "$GATE_EXIT_RULE"
        fi
      fi
      # 필드 승계 — the segment comes from the row being closed and never from
      # argv, the same rule the review-obligation arm above already applies.
      oseg=$(gate_row_field \
        "$( { gate_rows 'problem' | grep -F "동일성=$oident " || true; } | tail -1)" '세그먼트')
      # THE VERBATIM IDENTITY IS NOT CARRIED. A row has a 1024-byte cap and the
      # identity is unbounded Korean free text, so what goes on the row is the
      # derived id — which every reader keys on — plus a truncated label for the
      # person reading in the morning. No predicate reads the label.
      gate_append "$oseries" "의무 id=$ooid" \
        "표시 동일성=$(gate_obligation_display "$oident")" \
        "처분=$odisp" "세그먼트=${oseg:--}" "근거=$owhy" "처분 시각=$(now_iso)"
      log "의무 ${odisp} ${ooid}"
      ;;
  esac
  return 0
}

gate_drain_stall() {
  # Move each line of the watcher's observation file into the ledger as a row,
  # then truncate. Chained and locked because this is the writer; the watcher's
  # own append was neither, and the chain then read as broken from that row on.
  local f="$RUN_DIR/stall" line ts why cmd
  [ -s "$f" ] || return 0
  while IFS="$(printf '\t')" read -r ts why cmd; do
    [ -n "$why" ] || continue
    # THE KEY IS "THIS 사유 IS CURRENTLY UNRESOLVED", not "this 사유 appears
    # anywhere in the ledger". Substring-matching the whole ledger meant the
    # second stall of a run never landed — including one that came after a
    # person had written the resolving row — and the observation file is
    # truncated below, so that observation vanished with nothing recording it.
    # The morning report and termination condition 5 then could not tell "it
    # stalled once and was resolved" from "it is still stalling".
    if [ "$( { cc_unresolved_blocked "$LEDGER" | cut -f2- | grep -cxF "$why" || true; } )" != "0" ]; then
      continue
    fi
    # NO BANNER HERE EITHER. Every condition transcribed on this path was already
    # announced by the watcher two lines before it wrote the observation, so a
    # notice here is the same event reaching the user a second time — under a
    # different title and a different group, and spending one of the eight
    # stacking slots that an approval actually waiting for an answer needs.
    #
    # `원인=불명` is written HERE AND NOWHERE ELSE, which is what lets the
    # watcher's anchored arm exclude "conditions the watcher authored" by
    # structure instead of by a list of reason strings that goes stale silently.
    gate_append 'blocked' "대상=-" "스코프=run" "원인=불명" "사유=$why" \
      "관측=$ts" "재개 명령=$cmd"
  done < "$f"
  : > "$f"
}

gate_drain_checks() {
  # Move each transition the CI poller observed into the ledger as a `checks`
  # row. Same arrangement as the stall drain above and for the same reason: the
  # poller is a detached process and therefore not the ledger's writer, and an
  # unchained append from there reads as a broken chain from that row on.
  #
  # THE FILE IS RENAMED ASIDE, NOT READ IN PLACE AND TRUNCATED. The poller
  # appends on its own schedule, so a `: > "$f"` after the read throws away every
  # line that landed while this loop was running. A rename inside the same
  # directory is atomic and sends the poller's next `>>` to a fresh file, which
  # is the only ordering that loses nothing.
  #
  # A DRAIN THAT DIES BETWEEN THE RENAME AND THE `rm` LEAVES A FILE, AND THIS
  # FUNCTION IS THE ONLY THING THAT READS IT BACK. Nothing else in the tree opens
  # a `checks.observed.draining.*`, so without the sweep below those lines never
  # reach the ledger — and the loss is permanent rather than merely likely,
  # because the poller seeds its transition table from exactly those files and so
  # treats the stranded states as ALREADY RECORDED. It writes on transitions
  # only, so it never re-emits them; restarting it re-seeds the same state out of
  # the ledger. A `실패` that died in a drain would stop refusing merges forever.
  # The comment that used to sit here claimed the poller's seeding is what kept
  # those observations visible. Seeding is what closed the door, not what opened
  # it, and that inversion is why this path read as covered.
  #
  # The abort path is not hypothetical: `gate_append` calls `die` when an append
  # fails — an unwritable lock path, a full disk, a wrong ledger path — and that
  # `die` has no data precondition at all. The sweep also closes the `$$` reuse
  # window, where a later gate with a recycled pid renamed over a file a dead
  # drain had left behind: the file is consumed before that rename is attempted.
  #
  # OLDEST FIRST, AND IT CARRIES WEIGHT. Both consumers of this series take the
  # LAST record — the poller's `tbl_get` and `gate_check_merge_checks` both end
  # in `tail -1` — so the producer has to emit in age order at both layers.
  # Draining the newest stranded file first would land a stale `통과` after a
  # real `실패` and disarm the merge refusal, which is the exact outcome the
  # recovery exists to prevent. `ls -tr` orders by mtime, and `mv` carries the
  # original's mtime across, so the ordering is the order the lines were observed.
  #
  # NO DEDUPE HERE — IT IS THE POLLER'S JOB. What `gate_drain_stall` dedupes
  # against is the ledger's RESOLUTION state, and a `checks` row has no such
  # concept; no termination clause attaches to this series. The rule this series
  # actually needs is "write only on a transition", and a transition is a
  # property of two consecutive OBSERVATIONS. This function runs on gate acts —
  # rare and irregular — so deciding it here would mean a reverse scan of the
  # whole ledger on every act path. The poller holds the previous state in memory
  # and answers in O(1).
  #
  # NO BANNER. A CI result is an input for the router, not news for a person.
  #
  # THE ANCESTRY WINDOW IS THIS SERIES' ONE REAL EXPOSURE, and it is worth naming
  # because it is invisible from here. A snapshot digest compares its chain tip
  # against the last `GATE_ANCESTRY_WINDOW` rows' `prev`, and those rows are
  # counted by DISTANCE, not by kind — so a drain that appends that many rows at
  # once can make a sibling seat's held digest read as stale even though nothing
  # it cares about moved. The two rules above bound it: rows are written only on
  # transitions, and one `(PR, head sha)` lifecycle transitions a handful of
  # times. A single-segment run cannot reach the window; THREE OR MORE SEGMENTS
  # TRANSITIONING INSIDE ONE WINDOW CAN, and that exposure grows with how many
  # segments run at once rather than with anything here. There is no numeric
  # cap on concurrent stages: what bounds it is the route's usage admission,
  # which dispatches a stage only while the lane's weekly allowance admits it.
  #
  # THE SWEEP, THE RENAME AND THE TRANSCRIPTION RUN UNDER ONE LOCK, and without it
  # the sweep undid the ordering it was written to keep. `gate_verb_act` holds no
  # lock of its own and `ledger.lock` is taken and dropped per row, so two acts
  # draining at once interleave row by row: one picks up a stranded `통과` and
  # blocks on the ledger lock, the other transcribes the same file, removes it and
  # appends the poller's newer `실패`, and then the first lands its `통과` last.
  # `ls -tr` orders FILES; it cannot order two processes' appends. The same lock
  # also keeps the sweep off a sibling's file while that sibling is still reading
  # it, so every `draining.*` its holder sees really is stranded.
  local f="$RUN_DIR/checks.observed" t lk="$RUN_DIR/checks.drain.lock" held=1
  [ -d "$RUN_DIR" ] || return 0
  # A lock that cannot be MADE — as opposed to one somebody holds — falls back to
  # the unlocked drain rather than to no drain: skipping would hand the merge
  # check below a ledger without the poller's newest observation.
  gate_checks_drain_lock "$lk" || {
    held=0
    warn "could not create the \`checks\` drain lock and drains without it: $lk"
  }
  while IFS= read -r t; do
    [ -n "$t" ] || continue
    gate_drain_checks_file "$t"
    rm -f "$t"
  done <<EOF
$( { ls -tr "$RUN_DIR"/checks.observed.draining.* 2>/dev/null || true; } )
EOF
  if [ -s "$f" ]; then
    t="$f.draining.$$"
    if mv "$f" "$t" 2>/dev/null; then
      gate_drain_checks_file "$t"
      rm -f "$t"
    fi
  fi
  [ "$held" = "0" ] || gate_checks_drain_unlock "$lk"
}

gate_checks_drain_lock() {
  # gate_checks_drain_lock <lockdir> — the drain's own mutex. NOT `ledger.lock`:
  # that one is held per row by `gate_append`, which this section calls, so taking
  # it here would wait on itself.
  #
  # IT IS RELEASED BY THE HOLDER'S DEATH, and that is the property it needs. The
  # very case the sweep exists for is a drain that died mid-way — `gate_append`
  # calls `die` — and a plain `mkdir` lock left behind by that death would stop
  # every later drain for the rest of the run. So the owner line carries the pid,
  # and a waiter that finds that pid gone takes the lock over — through
  # `gate_checks_drain_takeover`, which judges again under a mutex of its own,
  # because a rename alone lets a waiter acting on a stale read remove the fresh
  # lock the other waiter has just taken.
  #
  # IT WAITS RATHER THAN GIVES UP. A drain that skipped would let the merge check
  # a few lines later read a ledger missing the poller's newest `실패`. A live
  # holder's section is a handful of appends; the only way to wait long is a
  # holder whose pid has been recycled by an unrelated process, and the owner
  # line's own timestamp — or the directory's mtime when that line cannot be read
  # — bounds that at the same sixty seconds `gate_index_lock` uses.
  local lockdir="$1" owner opid ots now dead undated=0
  while ! mkdir "$lockdir" 2>/dev/null; do
    owner=$(cat "$lockdir/owner" 2>/dev/null || true)
    opid=$(printf '%s' "$owner" | sed -n 's/^\([0-9][0-9]*\)[[:space:]][[:space:]]*[0-9][0-9]*$/\1/p')
    ots=$(printf '%s' "$owner" | sed -n 's/^[0-9][0-9]*[[:space:]][[:space:]]*\([0-9][0-9]*\)$/\1/p')
    [ -n "$ots" ] || ots=$(gate_mtime "$lockdir")
    if [ -z "$ots" ]; then
      # "THE LOCK IS GONE" AND "THE LOCK CANNOT BE MADE" read the same from here,
      # and only the first may loop. One more attempt separates them, and a lock
      # that stays present yet undateable gives up after a bounded number of
      # looks rather than spinning.
      mkdir "$lockdir" 2>/dev/null && break
      [ -d "$lockdir" ] || return 1
      undated=$(( undated + 1 ))
      [ "$undated" -gt 20 ] && return 1
      sleep 0.05
      continue
    fi
    now=$(date -u +%s)
    if { [ -n "$opid" ] && ! cc_pid_exists "$opid"; } || [ $((now - ots)) -ge 60 ]; then
      gate_checks_drain_takeover "$lockdir" "$owner"
      continue
    fi
    sleep 0.05
  done
  printf '%s %s\n' "$$" "$(date -u +%s)" > "$lockdir/owner" 2>/dev/null || true
  return 0
}

gate_checks_drain_takeover() {
  # gate_checks_drain_takeover <lockdir> <owner line judged dead> — remove a dead
  # holder's lock, and only that lock.
  #
  # THE VERDICT IS TAKEN AGAIN UNDER A SECOND MUTEX, BECAUSE THE RENAME ALONE
  # NAMES ONE WINNER ONLY WHEN BOTH WAITERS STILL LOOK AT THE SAME LOCK. Two
  # waiters read the dead owner; the first renames the lock away, takes a fresh
  # one and starts its section; the second, still acting on what it read before,
  # renames THAT fresh lock away and takes one of its own. Both then hold the
  # drain, and the row-by-row interleaving the lock exists to stop is back — a
  # stale `통과` landing after a real `실패`. The death of a holder is the very
  # case this lock is for, so the double-waiter window opens exactly when it
  # matters.
  #
  # Under `<lockdir>.takeover` the owner line is read again and has to be the one
  # judged dead; a lock with no owner line yet has to be old by its own mtime,
  # because a fresh `mkdir` also has no owner line for a moment. A waiter that
  # finds anything else leaves the lock alone and goes back to waiting. The only
  # way to change the lock between that read and the rename is its holder's own
  # release, and a holder judged dead has none — except under the sixty-second
  # arm, where the holder may be a recycled pid that is alive; that residual is
  # two consecutive commands wide and is not closed here.
  #
  # A TAKEOVER SECTION IS A READ AND A RENAME, so a `.takeover` older than ten
  # seconds belongs to a taker that died inside it and is removed. Two waiters
  # removing it together can both enter, which needs a dead drain AND a dead
  # taker in the same run.
  local lockdir="$1" seen="$2" tk="$1.takeover" tts now cur lts dead
  if ! mkdir "$tk" 2>/dev/null; then
    tts=$(gate_mtime "$tk"); now=$(date -u +%s)
    if [ -n "$tts" ] && [ $((now - tts)) -ge 10 ]; then
      rmdir "$tk" 2>/dev/null || true
    fi
    sleep 0.05
    return 0
  fi
  cur=$(cat "$lockdir/owner" 2>/dev/null || true)
  if [ -d "$lockdir" ] && [ "$cur" = "$seen" ]; then
    if [ -z "$cur" ]; then
      lts=$(gate_mtime "$lockdir"); now=$(date -u +%s)
      if [ -z "$lts" ] || [ $((now - lts)) -lt 60 ]; then
        rmdir "$tk" 2>/dev/null || true
        return 0
      fi
    fi
    dead="$lockdir.dead.$$.$(date -u +%s)"
    if mv "$lockdir" "$dead" 2>/dev/null; then
      rm -rf "$dead" 2>/dev/null || true
    fi
  fi
  rmdir "$tk" 2>/dev/null || true
  return 0
}

gate_checks_drain_unlock() {
  # One rename, for the reason `gate_index_unlock` gives: `rm -rf` unlinks the
  # owner line first and passes through an owner-less lock on every release.
  local dead="$1.dead.$$.$(date -u +%s)"
  if mv "$1" "$dead" 2>/dev/null; then
    rm -rf "$dead" 2>/dev/null || true
  fi
}

gate_drain_checks_file() {
  # gate_drain_checks_file <path> — transcribe one drained file into `checks`
  # rows. Split out of its caller because TWO sources feed it and they must be
  # transcribed identically: the file this act renamed aside, and any file a
  # previous drain left behind when it died before its `rm`.
  #
  # TWO LINE SHAPES. The poller writes `ts seg pr sha st g pend req fail`; a line
  # of the earlier seven-column shape, left in a file from before the round
  # column existed, has `필수 집합` where `g` now sits. A line is the new shape
  # only when both of those columns are whole numbers and it has nine columns;
  # anything else is read the old way, as round 0 with nothing running.
  local src="$1" ts seg pr sha st req fail g pend line tab
  [ -f "$src" ] || return 0
  tab=$(printf '\t')
  while IFS= read -r line; do
    g=0; pend=0
    case "$(printf '%s' "$line" | awk -F'\t' '{ print (NF >= 9 && $6 ~ /^[0-9]+$/ && $7 ~ /^[0-9]+$/) ? "new" : "old" }')" in
      new) IFS="$tab" read -r ts seg pr sha st g pend req fail <<EOF
$line
EOF
           ;;
      *)   IFS="$tab" read -r ts seg pr sha st req fail <<EOF
$line
EOF
           ;;
    esac
    [ -n "$pr" ] && [ -n "$sha" ] && [ -n "$st" ] || {
      warn "a line of \`checks.observed\` is missing required columns and is not transcribed: '${ts:-}'"
      continue
    }
    case "$st" in
      대기|통과|실패|미등록|'판정 불가') : ;;
      *) warn "the \`상태\` of a \`checks.observed\` line is out of vocabulary and is not transcribed: '$st'"
         continue ;;
    esac
    # EVERY FIELD SPELLED AS A LITERAL, never forwarded as `"$@"`. The field-table
    # lint compares this call site against the contract in both directions, and a
    # forwarded list switches off the direction that catches a field which exists
    # in the table and is written by nobody — which is the defect that lint is for.
    gate_append 'checks' "PR=$pr" "head sha=$sha" "상태=$st" \
      "필수 집합=$(gate_row_safe "$req" "$GATE_CHECKS_REQ_MAX")" \
      "실패 체크=$(gate_row_safe "$fail" "$GATE_CHECKS_FAIL_MAX")" \
      "관측=$ts" "세그먼트=${seg:--}" "재실행 회차=$g" "진행 중=$pend"
  done < "$src"
}

gate_drain_notify_state() {
  # The emitter's own active state, moved from the run directory into the report
  # as one line of prose.
  #
  # WHY THE INDIRECTION. Days later a reader cannot tell "nothing happened" from
  # "the banners were switched off" — the kickoff says the resolved state out
  # loud and that utterance goes with the session. Both seats therefore record
  # it, and neither appends to the report itself: the watcher takes no lock and
  # this process does, so two unlocked appends to one file interleave and what
  # breaks is the ledger ROW beside the prose, not the prose. This is the
  # ledger's writer, so this is where the line becomes durable.
  #
  # The hash chain is untouched by construction: it hashes only lines carrying
  # the row prefix, and the kickoff's own stub already puts prose in this file.
  #
  # THE MARKER IS SEPARATE FROM THE OBSERVATION. Using the state file as its own
  # once-guard is the mistake the stall arm already made — the gate empties that
  # file on every act, the guard came back to life, and the arm re-fired every
  # pass.
  local f m
  if [ -z "${RUN_DIR:-}" ]; then return 0; fi
  f="$RUN_DIR/notify.state"; m="$RUN_DIR/notify.reported"
  if [ ! -s "$f" ]; then return 0; fi
  if [ -f "$m" ]; then return 0; fi
  printf '%s · 배너 좌석: %s\n' "$(now_iso)" \
    "$( { cat "$f" 2>/dev/null || true; } | sed -n '1p')" >> "$LEDGER" 2>/dev/null || true
  : > "$m" 2>/dev/null || true
  return 0
}

gate_past_deadline() {
  # `벽시계 마감` read the way the driver reads it, for the one narrow purpose
  # `gate_run_ended_ok` states below. True when the clock has passed it.
  #
  # THE COMPARISON IS MADE IN THE DEADLINE'S OWN ZONE, and that is a portability
  # fact rather than a style choice. `date -d` is GNU and `date -j -f` is BSD, so
  # neither parses an offset-bearing stamp; what both have is `date +FMT` under a
  # TZ. Render now there, and compare digit strings.
  #
  # AN UNREADABLE DEADLINE WARNS AND DOES NOT ENFORCE. Discarding it in silence
  # is how a run comes to report a boundary it does not have.
  local dl stamp off now
  [ -n "${MANIFEST:-}" ] || return 1
  dl=$(manifest_field '인가' '벽시계 마감')
  [ -n "$dl" ] && [ "$dl" != "없음" ] && [ "$dl" != "(없음)" ] || return 1
  stamp=$(printf '%s' "$dl" | cut -c1-19 | tr -cd '0-9')
  off=$(printf '%s' "$dl" | cut -c20-)
  case "$off" in
    Z|'')      now=$(date -u +%Y%m%d%H%M%S) ;;
    # POSIX TZ inverts the sign: UTC+9 is written `UTC-9`.
    +*:*)      now=$(TZ="UTC-${off#+}" date +%Y%m%d%H%M%S) ;;
    -*:*)      now=$(TZ="UTC+${off#-}" date +%Y%m%d%H%M%S) ;;
    *)
      warn "could not read the time zone of the wall-clock deadline ($dl) — the deadline is not enforced"
      return 1 ;;
  esac
  [ ${#stamp} -eq 14 ] || { warn "could not read the format of the wall-clock deadline ($dl) — the deadline is not enforced"; return 1; }
  [ "$now" -gt "$stamp" ] 2>/dev/null
}

gate_unbounded_notice() {
  # BOTH PROGRESS-AXIS BOUNDS UNDECLARED IS A STATE, AND THE RUN HAD NO WAY TO
  # HEAR ABOUT IT.
  #
  # The manifest check is asymmetric and each half of the asymmetry is a
  # decision. It hard-fails a manifest without `벽시계 마감` — the field the
  # fixed-graph path actually reads. It says nothing about `비용 천장` and
  # `무진전 상한`, the two that bound a ROUTER run, because undeclared is legal
  # for both and that legality is the whole of their backward compatibility.
  # Both halves are right on their own; together they mean a manifest that
  # PASSES the check reads as "the bounds were checked" while the two bounds
  # that matter may both be absent.
  #
  # A REQUIRED CHECK CANNOT REPAIR THAT. The check runs on every verb against a
  # frozen block nobody can edit, so making the field required would kill a run
  # in flight on its next `snapshot` — in the middle of the night, for a
  # manifest that was conforming when it was written. What can be done for a run
  # whose manifest is already frozen is to TELL it, which is what this is: the
  # fact, once, naming both fields and what is left unbounded.
  #
  # ONCE, kept with a marker file. A warning on every act is the thing that
  # teaches a reader to skip the line that matters.
  [ -n "${RUN_DIR:-}" ] || return 0
  [ -e "$RUN_DIR/unbounded-notice" ] && return 0
  gate_progress_axes_unbounded || return 0
  : > "$RUN_DIR/unbounded-notice"
  warn "this run declares neither \`비용 천장\` nor \`무진전 상한\` (a value that does not read as a number counts as undeclared) — neither progress axis carries a cap"
  warn "the only bound left is \`벽시계 마감\`, and only in this state does it stand as the dispatch and merge gate on the router path"
}

gate_progress_axes_unbounded() {
  # True when NO progress-axis bound is in force.
  #
  # Undeclared counts, and so does declared in a spelling its own boundary
  # refuses to enforce — a value `gate_b4_percent` warns about and walks away
  # from bounds exactly nothing, and counting it as declared is how a run comes
  # to report a bound it does not have. One predicate, so the boundary and its
  # readers cannot each answer this differently.
  #
  # WRITTEN AS A PER-AXIS WALK because the tree is expected to gain axes. Adding
  # an axis is adding an arm here beside the boundary that enforces it, never a
  # second predicate that can disagree.
  local cost bound
  cost=$(manifest_field '인가' '비용 천장')
  bound=$(manifest_field '인가' '무진전 상한')
  case "$cost" in
    ''|없음|'(없음)') : ;;
    *) if gate_cost_figure_ok "$cost"; then return 1; fi ;;
  esac
  case "$bound" in
    ''|없음|'(없음)') : ;;
    *) case "$bound" in *[!0-9]*) : ;; *) return 1 ;; esac ;;
  esac
  return 0
}

gate_done_note() {
  # gate_done_note <한 줄> — record a terminal line WITHOUT erasing one that is
  # already there.
  #
  # A boundary can end the run and the router can still propose termination
  # afterwards — the ending gate exempts `propose-done` on purpose, because a run
  # that cannot record that it ended is a run the snapshot renders in flight
  # forever. So both writers reach this file, and the proposal used to arrive
  # with a truncating `>`: the morning then read "종료 조건 성립" for a night that
  # was actually stopped by a cost ceiling, and the boundary's reason was gone.
  #
  # THE FIRST LINE STAYS FIRST. Readers `cat` the whole file, so appending costs
  # nothing and keeps both accounts; the operative reason is the one that ended
  # the run, and it is the one on top.
  if [ -s "$RUN_DIR/done" ]; then
    printf '%s\n' "$1" >> "$RUN_DIR/done"
  else
    printf '%s\n' "$1" > "$RUN_DIR/done"
  fi
}

readonly GATE_REKICK_CAUSES="마감 천장 무진전 사이클예산 표면이동 연기마감 결함 판단정지 대상미선언 슬라이싱 시각승인대기 말단상한 P0잔존 해당없음"

gate_rekick_cause_ok() {
  # gate_rekick_cause_ok <토큰> — true when the token is one of the fourteen.
  #
  # A CLOSED SET, AND A VALUE OUTSIDE IT IS A CODE DEFECT. Every caller passes
  # a literal or a value chosen from a fixed map, so a stray spelling here is a
  # bug in this file — and folding it into `해당없음` would hide that bug behind
  # the token whose whole meaning is "a person looks at this".
  local t
  [ -n "${1:-}" ] || return 1
  for t in $GATE_REKICK_CAUSES; do
    [ "$t" = "$1" ] && return 0
  done
  return 1
}

gate_segment_p0_cap_park() {
  # gate_segment_p0_cap_park <segment> — print the absolute path of the
  # segment's last review report and return 0 when the segment is parked past
  # the re-check cap with P0 left; return 1 otherwise.
  #
  # THREE FACTS, ALL READ FROM ROWS THAT ALWAYS CARRY THEM. The last `segment`
  # row says `park`; the last `cycle` row's canonical `P0` is above zero; and
  # the ladder walk counts more re-check reviews than the cap allows. The
  # cycle row's `리뷰 종결` is not read: it is written after `발견 지문` and is
  # the field a row over the length cap drops, so a run whose cap row lost it
  # would read as one that never reached the cap.
  local sid=$1 row p0 k
  [ -n "$sid" ] || return 1
  [ "$(gate_segment_field "$sid" '상태')" = "park" ] || return 1
  row=$(gate_segment_last_cycle_row "$sid")
  [ -n "$row" ] || return 1
  p0=$(gate_row_field "$row" 'P0')
  gate_canon_count "$p0" || return 1
  [ "$p0" -gt 0 ] 2>/dev/null || return 1
  k=$(gate_report_count "$(gate_segment_review_walk "$sid")" '확인 리뷰 수')
  [ "${k:-0}" -gt "$(gate_segment_recheck_cap "$sid")" ] 2>/dev/null || return 1
  gate_report_abs "$(gate_row_field "$row" '리포트 경로')"
}

gate_segment_dep_park_unmet() {
  # gate_segment_dep_park_unmet <segment> — print the predecessors a dependency
  # park names, space-separated, and return 0 when the segment's last `blocked`
  # row is one; return 1 otherwise.
  #
  # A DEPENDENCY PARK IS KNOWN BY ITS `미완 선행` FIELD AND NOTHING ELSE. The
  # driver's dependency park and its declaration-defect park share the scope,
  # the cause and the reason `게이트 park`; only the former names the
  # predecessors it waited on, in a field of its own. The free sentence beside
  # it is never parsed.
  local row v
  row=$(gate_rows 'blocked' | gate_rows_field_eq '대상' "$1" | tail -1)
  [ -n "$row" ] || return 1
  [ "$(gate_row_field "$row" '스코프')" = "cone" ] || return 1
  [ "$(gate_row_field "$row" '원인')" = "무효화" ] || return 1
  v=$(gate_row_field "$row" '미완 선행')
  [ -n "$v" ] || return 1
  printf '%s' "$v" | tr ',' ' '
}

gate_rekick_p0_residual() {
  # gate_rekick_p0_residual [<ledger>] [<manifest>] — print one
  # `<segment>\t<report>` line per segment parked at the re-check cap with P0
  # left, in ledger order, and return 0 when the run's ending is a `P0잔존`
  # ending; return 1 otherwise. Reads the ledger and the manifest and nothing
  # else, so the successor's first step can ask it of the predecessor's ledger.
  #
  # ALL FOUR MUST HOLD.
  #   (가) the manifest declares a design document;
  #   (나) at least one segment is parked at the re-check cap with P0 left
  #        (`gate_segment_p0_cap_park`);
  #   (다) every other segment the ledger's `segment` rows know has landed
  #        (`머지됨` or `완료`), or is a dependency park whose every unmet
  #        predecessor is a (나) segment or another such dependency park;
  #   (라) no approval is open, act or judgment.
  # A run that also holds a blocking P1 park, an aborted segment or an open
  # question is not this ending: those go to a person as they always did.
  #
  # DEPENDENCIES ARE COUNTED TRANSITIVELY. C waiting on B waiting on A, with A
  # the P0 park, admits B and then C; the walk repeats until nothing is added.
  # A dependent left by a writer that names no `미완 선행` is not admitted, so
  # the answer there is the conservative one — `해당없음` and a person.
  local LEDGER="${1:-${LEDGER:-}}" MANIFEST="${2:-${MANIFEST:-}}"
  local segs sid rep p0lines="" acc=" " deps d changed allin st
  [ -n "$LEDGER" ] && [ -f "$LEDGER" ] || return 1
  gate_manifest_has_design_doc || return 1
  [ -z "$(gate_pending_approval_ids)" ] || return 1
  segs=$(gate_rows 'segment' | gate_row_ids | awk 'NF && !s[$0]++')
  [ -n "$segs" ] || return 1
  for sid in $segs; do
    rep=$(gate_segment_p0_cap_park "$sid") || continue
    printf -v p0lines '%s%s\t%s\n' "$p0lines" "$sid" "$rep"
    acc="$acc$sid "
  done
  [ -n "$p0lines" ] || return 1
  changed=1
  while [ "$changed" = "1" ]; do
    changed=0
    for sid in $segs; do
      case "$acc" in *" $sid "*) continue ;; esac
      deps=$(gate_segment_dep_park_unmet "$sid") || continue
      allin=1
      for d in $deps; do
        case "$acc" in *" $d "*) : ;; *) allin=0; break ;; esac
      done
      [ -n "$deps" ] && [ "$allin" = "1" ] || continue
      acc="$acc$sid "; changed=1
    done
  done
  for sid in $segs; do
    case "$acc" in *" $sid "*) continue ;; esac
    st=$(gate_segment_field "$sid" '상태')
    case "$st" in 머지됨|완료) continue ;; esac
    return 1
  done
  printf '%s' "$p0lines"
}

gate_p0_residual_fingerprint() {
  # gate_p0_residual_fingerprint <selector output> — the `재킥 지문` of a
  # `P0잔존` ending: one `gate_cycle_p0_fingerprint` component per P0 segment,
  # sorted, de-duplicated and joined with commas. One unknown component makes
  # the whole value `(미상)`, which stops the chain rather than letting the
  # known half of the set compare as if it were all of it.
  local sid rep c comps="" unk=0
  while IFS='	' read -r sid rep; do
    [ -n "$sid" ] || continue
    c=$(gate_cycle_p0_fingerprint "$rep")
    [ "$c" = "(미상)" ] && unk=1
    comps="$comps$c
"
  done <<EOF
$1
EOF
  if [ "$unk" = "1" ] || [ -z "$comps" ]; then
    printf '(미상)'; return 0
  fi
  printf '%s' "$comps" | awk 'NF' | LC_ALL=C sort -u | paste -s -d, -
}

gate_p0_residual_done_line() {
  # gate_p0_residual_done_line <근거> [<덧붙임>] — print the `done` line of a
  # `P0잔존` ending and return 0, or print nothing and return 1 when the
  # selector does not hold. Every site that writes the first line of `done` on
  # an ending `gate_end_row` may turn into `P0잔존` asks this first, so the
  # morning render, the morning report and the banner never call such a run a
  # completion.
  local why="$1" extra="${2:-}" sel segs
  sel=$(gate_rekick_p0_residual) || return 1
  segs=$(printf '%s\n' "$sel" | cut -f1 | awk 'NF' | paste -s -d, - | sed 's/,/, /g')
  printf '%s 종단 — P0 잔존 — 확인 리뷰 상한에서 P0 가 남은 세그먼트: %s%s · 근거 %s' \
    "$(now_iso)" "$segs" "$extra" "$why"
}

gate_end_token() {
  # gate_end_token — print this run's END TOKEN, or print nothing and return 1.
  #
  # The end token is the `재킥 원인` of the EARLIEST run-scope row that carries
  # one: an ending row (`자율 승인` with `결정=종료`) or a run-scope `blocked`
  # row, which is how the surface-move site ends a run. A later row never
  # changes it. Latest-wins would let a run stopped by a surface move pick up a
  # `마감` ending afterwards and read as a quiet run — a cause that needed a
  # person turned into one that needs nobody.
  #
  # Matched on whole fields between ` | ` separators, the same exactness
  # `gate_run_ended_ok` uses: `gate_append` maps `|` out of every value, so a
  # separator on both sides only ever stands at a real field boundary.
  local row
  row=$(gate_end_token_row) || return 1
  printf '%s' "$row" | awk '
    { n = split($0, f, / \| /)
      for (i = 2; i <= n; i++) {
        if (index(f[i], "재킥 원인=") == 1) {
          v = f[i]; sub(/^재킥 원인=/, "", v); print v; exit
        }
      }
    }'
}

gate_end_token_row() {
  # gate_end_token_row — print the whole row `gate_end_token` reads its token
  # from, or print nothing and return 1. One selector for every reader, because
  # `종료 부류` and `재킥 지문` are read off that same row, and a second copy of
  # the selection would be free to pick a different one.
  #
  # A run-scope `blocked` row whose cause is `대상미선언` or `슬라이싱` is NOT an
  # ending: those two park a slice and the run goes on, so they settle no end
  # token even when the row is run-scope (the slicing invalidation is). An
  # ending row that carries one of them is still read — that is the run's own
  # end site naming the park it stopped behind.
  [ -n "${LEDGER:-}" ] && [ -f "$LEDGER" ] || return 1
  awk '
    (index($0, "- `자율 승인` | ") == 1 && index($0, " | 결정=종료 | ") > 0) ||
    (index($0, "- `blocked` | ") == 1 && index($0, " | 스코프=run | ") > 0) {
      blk = (index($0, "- `blocked` | ") == 1)
      n = split($0, f, / \| /)
      for (i = 2; i <= n; i++) {
        if (index(f[i], "재킥 원인=") == 1) {
          v = f[i]; sub(/^재킥 원인=/, "", v)
          if (blk && (v == "대상미선언" || v == "슬라이싱")) break
          print; found = 1; exit
        }
      }
    }
    END { exit found ? 0 : 1 }' "$LEDGER" 2>/dev/null
}

gate_end_row() {
  # gate_end_row <기준> <근거> <재킥 원인> [<종료 부류>] [<재킥 지문>]
  #
  # The run-scope ending row, `자율 승인` with `결정=종료`, carrying the closed
  # `재킥 원인` token. `종료 부류=완료` marks a normal completion, whose token is
  # still `해당없음`; `재킥 지문` goes with `결함` and `P0잔존` only. The row is appended
  # whether or not the run already has an end token — a later row is a true
  # account of what else happened, and the earliest-row rule keeps it from
  # changing the token.
  #
  # EVERY SITE THAT WRITES `done` WRITES AN ENDING ROW. The three `done` arms of
  # a termination proposal reach `done` without `gate_end_run`, so they call
  # this directly; without it the run has a mark and no end token, and anything
  # that reads the token reads the run as still going.
  local std="$1" why="$2" cause="$3" ekind="${4:-}" fp="${5:-}" _why_free _p0
  if ! gate_rekick_cause_ok "$cause"; then
    warn "rekick cause '$cause' is not one of the fourteen closed tokens — this is a defect in the gate"
    return 1
  fi
  # THE ONE SITE THAT WRITES `P0잔존`. Every ending of both executors reaches
  # this function, so the run whose only unlanded work is a re-check-cap park
  # with P0 left is read here once, rather than at each arm where a forgotten
  # arm would end it quietly. Only a caller that named no cause of its own
  # (`해당없음`) and no kind other than a normal completion is re-read: a
  # person's `포기` and a take-over's `이어받음` are decisions this does not
  # second-guess, and every other cause already names why the run stopped. The
  # kind is dropped, because a run with P0 left is not a normal completion.
  if [ "$cause" = "해당없음" ] && { [ -z "$ekind" ] || [ "$ekind" = "완료" ]; } \
     && _p0=$(gate_rekick_p0_residual); then
    cause=P0잔존; ekind=""
    fp=$(gate_p0_residual_fingerprint "$_p0")
  fi
  case "$cause" in 결함|P0잔존) : ;; *) fp="" ;; esac
  # `유도 절단점=-` for the reason the boundary approval row carries it: an
  # ending has no act, so there is no argv to derive a rung from. Every row that
  # fills `절단점` fills this slot beside it, and a reader holding one without
  # the other cannot tell an ending from a row a writer forgot to finish.
  _why_free=$(gate_free_budget "kind=boundary" "결정=종료" "대상=-" "세그먼트=-" \
    "절단점=경계" "유도 절단점=-" "축2=읽기" "등급=1" "기준=$std" "되돌리는 법=새 런으로 다시 킥오프" \
    "재킥 원인=$cause" ${ekind:+"종료 부류=$ekind"} ${fp:+"재킥 지문=$fp"})
  # A `P0잔존` fingerprint the row cannot carry is unknown, not clipped: a
  # clipped component list would compare as a different set, and `(미상)`
  # stops the chain.
  if [ "$cause" = "P0잔존" ] && [ "${_why_free:-0}" -le 0 ]; then
    fp='(미상)'
    _why_free=$(gate_free_budget "kind=boundary" "결정=종료" "대상=-" "세그먼트=-" \
      "절단점=경계" "유도 절단점=-" "축2=읽기" "등급=1" "기준=$std" "되돌리는 법=새 런으로 다시 킥오프" \
      "재킥 원인=$cause" "재킥 지문=$fp")
  fi
  gate_append '자율 승인' "kind=boundary" "결정=종료" "대상=-" "세그먼트=-" \
    "절단점=경계" "유도 절단점=-" "축2=읽기" "등급=1" "기준=$std" \
    "되돌리는 법=새 런으로 다시 킥오프" "재킥 원인=$cause" \
    ${ekind:+"종료 부류=$ekind"} ${fp:+"재킥 지문=$fp"} \
    "근거=$(gate_row_safe "$why" "$_why_free")"
}

gate_end_cause_of() {
  # gate_end_cause_of <경계 이름> — the token a boundary ends a run with when
  # its caller names none.
  case "$1" in
    B4)   printf '천장' ;;
    B5)   printf '무진전' ;;
    마감) printf '마감' ;;
    *)    printf '해당없음' ;;
  esac
}

gate_end_run() {
  # gate_end_run <경계 이름> <사유> [<재킥 원인> [<종료 부류> [<재킥 지문>]]]
  # — a boundary ENDS the run.
  #
  # THE DIFFERENCE BETWEEN THIS AND `gate_issue_boundary_approval` IS THE WHOLE
  # POINT. An approval asks a person; ending needs no one, and the state this
  # design targets is precisely the one where nobody is awake to be asked. A
  # boundary that could only ask is a boundary that does nothing at 4am.
  #
  # Idempotent by the mark itself: `done` already written means some earlier
  # decision — this boundary, another one, or an accepted proposal — already
  # ended the run, and the first reason is the true one. Rewriting it would
  # replace the morning's account of why the night stopped.
  local name="$1" why="$2"
  [ -s "$RUN_DIR/done" ] && return 0
  # PUBLISHED BY HARD LINK, AND THE ROW IS WRITTEN ONLY BY THE WINNER.
  #
  # `mv -n` was the wrong primitive for this. It is `stat` then `rename`, so two
  # boundaries firing together can both see an absent target and the second's
  # rename replaces the first's file — the same read-then-act the bare `>` had,
  # one layer down. `ln` is a single `link(2)`: it fails atomically when the
  # target exists, so exactly one caller can win and the loser learns it did not.
  #
  # AND THE LEDGER ROW MOVED BELOW THE RACE. It used to be appended before the
  # publish, by every caller — so two boundaries firing together left two
  # `결정=종료` rows for a run that ended once, and the morning could not tell
  # which one the mark belongs to. The row now records the decision that actually
  # took effect, and a loser writes nothing anywhere.
  #
  # THE ROW CARRIES ITS CAUSE. A caller that names none gets the boundary's own
  # token (`gate_end_cause_of`); an unknown token is refused before anything is
  # published, so a defect cannot leave a `done` with no row behind it.
  #
  # A SIXTH ARGUMENT REPLACES THE BOUNDARY'S OWN `done` LINE. The all-met arm
  # ends a run that is not stopped at a boundary but satisfied, so it hands in
  # the line an accepted proposal writes (`gate_satisfied_done_line`) and keeps
  # the race and the row of this function.
  local cause="${3:-}" ekind="${4:-}" fp="${5:-}" line="${6:-}"
  [ -n "$cause" ] || cause=$(gate_end_cause_of "$name")
  if ! gate_rekick_cause_ok "$cause"; then
    warn "rekick cause '$cause' is not one of the fourteen closed tokens — this is a defect in the gate"
    return 1
  fi
  # The `done` line says what the ending row will say. `gate_end_row` turns an
  # uncaused ending into `P0잔존` when the selector holds, and the line is
  # written before that row, so it asks the same selector here; a line handed
  # in by the all-met arm already made the same choice.
  if [ -z "$line" ] && [ "$cause" = "해당없음" ] && { [ -z "$ekind" ] || [ "$ekind" = "완료" ]; }; then
    line=$(gate_p0_residual_done_line "$why") || line=""
  fi
  [ -n "$line" ] || line=$(printf '%s 종단 — 경계 %s · 근거 %s' "$(now_iso)" "$name" "$why")
  printf '%s\n' "$line" > "$RUN_DIR/done.$$"
  if ! ln "$RUN_DIR/done.$$" "$RUN_DIR/done" 2>/dev/null; then
    # Lost the race, or the filesystem cannot hard-link. Either way something
    # else owns the mark now; the loser leaves no row and no leftover file.
    rm -f "$RUN_DIR/done.$$" 2>/dev/null || true
    return 0
  fi
  rm -f "$RUN_DIR/done.$$" 2>/dev/null || true
  # The rationale is clipped to what the row has left; see `gate_free_budget`.
  gate_end_row "$name" "$why" "$cause" "$ekind" "$fp"
  warn "boundary $name ends the run — $why"
  if cc_caller_is_router && cc_run_end_settled "$RUN_DIR" && cc_notify_claim_ended; then
    # `ended` is the event kind the run's other terminal points already use. A
    # kind outside the notifier's closed set raises nothing at all, so a banner
    # spelled for this one caller would be a banner that never arrives.
    if [ -n "${6:-}" ]; then
      cc_notify_fire ended "런이 종단했습니다 — 아침 보고서를 확인하세요" || true
    else
      cc_notify_fire ended "경계 $name 이 런을 끝냈습니다 — 아침 보고서를 확인하세요" || true
    fi
    cc_notify_mark_ended_fired
  fi
  return 0
}

gate_satisfied_done_line() {
  # gate_satisfied_done_line <근거> — print the `done` line of a run that ends
  # with every termination condition met.
  #
  # TWO SITES END A RUN ON THAT STATE — an accepted proposal and a refused act
  # whose next obligation cannot be named — and they must write the same line.
  # All-met still allows open judgment questions (condition 2 counts act
  # approvals only) and clauses on `보류` (condition 10 counts them settled), and
  # this line is the only place either becomes visible: the morning render, the
  # morning report and the banner all read the first line of `done`.
  #
  # ALL-MET WITH A RE-CHECK-CAP P0 PARK IS NOT A COMPLETION. The clauses can be
  # settled while a declared slice sits parked with P0 left, and the ending row
  # then carries `P0잔존`; this line says the same, before that row is written.
  local why="$1" qids qn held
  gate_p0_residual_done_line "$why" && return 0
  qids=$(gate_pending_approval_ids 판단 | tr '\n' ' ' | sed 's/[[:space:]]*$//')
  qn=$(gate_pending_approval_ids 판단 | gate_count)
  # THE HELD CLAUSES ARE NAMED. `보류` settles condition 10, so a clause on
  # hold leaves no trace in the unmet list — and a run that answered every
  # authorized clause and one that deferred all of them behind questions would
  # otherwise write the same terminal line. This is the residual class the
  # design put in this file rather than in a condition of its own, so it has to
  # carry what is actually outstanding.
  held=$(gate_held_clause_ids | tr '\n' ' ' | sed 's/[[:space:]]*$//')
  if [ -n "$qids" ]; then
    printf '%s 종단 — 질의 잔여 %s건 · 승인 %s%s · 근거 %s' \
      "$(now_iso)" "$qn" "$qids" "${held:+ · 보류 절 $held}" "$why"
  else
    printf '%s 종단 — 종료 조건 성립%s · 근거 %s' \
      "$(now_iso)" "${held:+ · 보류 절 $held}" "$why"
  fi
}

gate_fleet_busy_state() {
  # gate_fleet_busy_state — `live`, `dead` or `none` for the fleet run markers
  # that carry this run's id.
  #
  # A MARKER IS THE ONLY EVIDENCE THAT A FIXED-GRAPH RUN IS ALIVE. The backlog
  # record is not: fleet rewrites it to `done` only after `run.sh` returns, so a
  # dispatch job that died — a reboot, launchd tearing the job down, a kill —
  # leaves it `dispatched` forever, and reading that as alive would hand a dead
  # run the automatic branch.
  #
  # The test is `fleet_busy_live`'s first half, byte for byte: the pid is alive
  # and still the process that wrote the marker, its fingerprint taken in UTC the
  # way the writer took it. fleet.sh cannot be sourced to call the function
  # itself — it runs `main "$@"` at its last line — so the same test is asked of
  # the shared holder predicate, with the fingerprint taken under UTC, and the
  # gate keeps no liveness test of its own. The probe half is the run's own live
  # stages, which is what the probe reports as `도는중` for this run id.
  local d f pid fp run seen=0
  d="$(run_pace_root)/busy"
  [ -d "$d" ] || { printf 'none'; return 0; }
  for f in "$d"/*; do
    [ -f "$f" ] || continue
    run=$(sed -n '3p' "$f" 2>/dev/null | tr -d '[:space:]')
    [ "$run" = "$RUN_ID" ] || continue
    seen=1
    pid=$(sed -n '1p' "$f" 2>/dev/null | tr -d '[:space:]')
    fp=$(sed -n '2p' "$f" 2>/dev/null || true)
    if TZ=UTC0 cc_holder_is_live "$pid" "$fp"; then
      printf 'live'; return 0
    fi
  done
  if [ "$seen" = "1" ]; then
    if [ "$(cc_live_stages "$RUN_DIR" 2>/dev/null || printf 0)" -gt 0 ] 2>/dev/null; then
      printf 'live'
    else
      printf 'dead'
    fi
    return 0
  fi
  printf 'none'
}

gate_defer_end_due() {
  # gate_defer_end_due — true when a run that carried its answers over should
  # end now with `마감`: the deadline has passed, the latest `handoff` says
  # `사유=이월`, and the ending holds (`gate_defer_end_ready`). The clock end
  # of the acting path, `gate_verb_end_overdue` and the `이월` hand-off past
  # the deadline all ask this one helper.
  local last
  gate_past_deadline || return 1
  # Read from the file rather than `gate_rows`: the hand-off arm asks this
  # right after appending its row, and a warmed memo would not hold it.
  last=$( { grep "^- \`handoff\` " "$LEDGER" 2>/dev/null || true; } | tail -1)
  [ "$(gate_row_field "$last" '사유')" = "이월" ] || return 1
  gate_defer_end_ready
}

gate_defer_end_ready() {
  # gate_defer_end_ready — the ending's own conditions, the latest hand-off
  # aside: no stage or supervisor is alive, and — on a run with a progress
  # axis, which the clock does not otherwise end — nothing but the carried
  # answers holds the run (`gate_defer_only_left`). The `이월` hand-off past
  # the deadline asks this before it writes its row, reading itself as the
  # latest hand-off.
  #
  # WHY THE COMPLETION CONDITIONS ARE NOT READ. They measure whether the run
  # did the work it set out to do, and a run with a progress axis that handed
  # work to the next run always keeps lines for it — an unsettled closing
  # clause, an open obligation, an unmet review obligation. Those need a stage
  # to clear, and past the deadline the router parks every request, so no run
  # past its deadline clears them. Reading them kept the ending from ever
  # holding on such a run. What is read instead is what this run can still do
  # without a stage — merge a segment, wait on CI, take an answer to an
  # approval, clear a `blocked` row — and what it still has to ask a person.
  # `마감` is not `충족`, so those lines stay in the completion read after the
  # ending row and in the morning report.
  [ -z "$(cc_relay_wait_stages "$RUN_DIR")" ] || return 1
  gate_progress_axes_unbounded && return 0
  gate_defer_only_left
}

gate_defer_end_why() {
  printf '벽시계 마감 경과 (%s) — 남은 중단 답을 다음 런으로 넘긴 런이다' \
    "$(manifest_field '인가' '벽시계 마감')"
}

gate_verb_end_overdue() {
  # gate_verb_end_overdue — close a run that passed its deadline with no end
  # token, once.
  #
  # A QUIET RUN IS ONE NO VERB REACHES, so the deadline branch inside the
  # acting path never fires for it, and this verb writes its end row instead.
  # The token is chosen by whether the driver is still alive, not by the
  # deadline alone: an alive run past its deadline is the quiet run this verb
  # exists for and takes `마감`, while a run that already stopped without a
  # classified end row takes `해당없음` and goes to a person. Writing `마감` for
  # both would read every unclassified stop as a deadline.
  #
  # UNOBSERVABLE COUNTS AS STOPPED. Every doubt lands on the human branch.
  #
  # Liveness, in order. A fleet marker for this run means the fixed graph:
  # alive → `마감`, dead → `해당없음`. Otherwise the router path: a live shift, a
  # live relay or a live stage (the lease's holders) is alive — a relay waiting
  # only on CI holds the run with neither of the others — and takes `마감` only when both
  # progress axes are unbounded — a run with an axis declared is ended by that
  # axis, the same narrowing the acting path's deadline branch applies.
  #
  # IDEMPOTENT. An existing end token returns before anything is read, and
  # `gate_end_run` writes nothing when the done mark is already published.
  gate_end_token >/dev/null 2>&1 && return 0
  gate_past_deadline || return 0
  local fleet why
  # A RUN THAT HANDED ITS LAST ANSWERS TO THE NEXT RUN stopped by design, not
  # unclassified: it takes `마감`, so the successor derivation picks the
  # automatic branch and the carried answers reach the next run.
  if gate_defer_end_due; then
    gate_end_run 마감 "$(gate_defer_end_why)" 마감
    return 0
  fi
  fleet=$(gate_fleet_busy_state)
  why="벽시계 마감이 지났고 종료 토큰이 없다"
  case "$fleet" in
    live) gate_end_run 마감 "$why — 고정 그래프 실행 표지가 살아 있다" 마감 ;;
    dead) gate_end_run 마감 "$why — 고정 그래프 실행 표지의 프로세스가 없다(분류 없이 멈춘 런)" 해당없음 ;;
    *)
      if cc_shift_is_live "$RUN_DIR" || cc_relay_is_live "$RUN_DIR" \
         || [ "$(cc_live_stages "$RUN_DIR" 2>/dev/null || printf 0)" -gt 0 ] 2>/dev/null; then
        gate_progress_axes_unbounded || return 0
        gate_end_run 마감 "$why — 살아 있는 shift 나 스테이지가 있다" 마감
      else
        gate_end_run 마감 "$why — 살아 있는 구동기를 관측하지 못했다(분류 없이 멈춘 런)" 해당없음
      fi ;;
  esac
}

gate_verb_end_abandoned() {
  # gate_verb_end_abandoned <이어받음|포기> [<후계 런 id>] — close a run that
  # another run took over, or that a person gave up.
  #
  # NO BOUNDARY ENDS SUCH A RUN, so before this verb nothing could record that
  # it was over: its watchers stayed up, and the morning could not tell it from
  # a run still in progress. This writes the same two things every other ending
  # writes — `done` and one end row — through `gate_end_run`, so its first-write
  # rule and its idempotence are the ones every boundary already has.
  #
  # THE CAUSE TOKEN IS `해당없음` AND THE KIND CARRIES WHAT HAPPENED. `재킥
  # 원인` is a closed set read by the re-kick path; neither a take-over nor a
  # person's decision is a reason to kick the run again automatically, and
  # `해당없음` is the token that sends a reader to a person. `종료 부류` is free
  # beside it and says which of the two this was.
  #
  # ONLY THE SEAT IN THE PERSON'S TURN, OR A KICKOFF TAKING OVER, MAY CALL IT.
  # Both are outside every stage and every shift, so a call carrying a stage's
  # or a shift's marker is refused: neither of those knows that a person gave
  # up or that another run took over, and an end they wrote would be a guess.
  #
  # A LIVE SHIFT OR STAGE IS REFUSED, and nothing is written. Something is
  # still working in that run, so it has not been abandoned — whoever is
  # closing it has to stop that first, or wait for it.
  local cause="$1" succ="${2:-}" why live
  if cc_caller_is_stage || [ -n "${CC_PIPELINE_SHIFT_ID:-}" ]; then
    warn "end-abandoned is called by the seat in the person's turn or by a kickoff taking over this run — not by a stage or a shift"
    return "$GATE_EXIT_RULE"
  fi
  case "$cause" in
    이어받음|포기) ;;
    *) warn "--cause has to be 이어받음 or 포기 (received: ${cause:-(none)})"
       return "$GATE_EXIT_VOCAB" ;;
  esac
  if [ -n "$succ" ]; then
    [ "$cause" = "이어받음" ] || {
      warn "--successor names the run that took over, so it goes with --cause 이어받음 only"
      return "$GATE_EXIT_VOCAB"; }
    case "$succ" in
      .*|*[!A-Za-z0-9._-]*)
        warn "--successor has to be a run id (letters, digits, '.', '_' and '-'): $succ"
        return "$GATE_EXIT_VOCAB" ;;
    esac
    [ "$succ" != "${RUN_ID:-}" ] || {
      warn "--successor names this run itself: $succ"
      return "$GATE_EXIT_VOCAB"; }
  fi
  live=$(cc_live_stages "$RUN_DIR" 2>/dev/null || printf 0)
  live=$(( ${live:-0} + $(cc_waiting_fresh_count "$RUN_DIR" "${LEDGER:-}" 2>/dev/null || printf 0) ))
  if cc_shift_is_live "$RUN_DIR" || cc_relay_is_live "$RUN_DIR" || [ "$live" -gt 0 ] 2>/dev/null; then
    warn "this run still has a live shift, relay or stage — it has not been abandoned, so nothing is written"
    return "$GATE_EXIT_RULE"
  fi
  case "$cause" in
    이어받음) why="다른 런이 이 런을 이어받았다${succ:+ — 후계 런 $succ}" ;;
    포기)     why="사람이 이 런을 포기했다" ;;
  esac
  gate_end_run "$cause" "$why" 해당없음 "$cause"
}

gate_run_ended_ok() {
  # gate_run_ended_ok <kind> <cutpoint> [<verb>]
  #
  # THE WALL CLOCK IS NO LONGER THE YARDSTICK AND THE GATE IT HELD IS NOT GONE.
  # What used to sit here was a dispatch-and-merge gate keyed on `벽시계 마감`;
  # this is the same gate keyed on whether a progress-based boundary has ENDED
  # the run.
  #
  # The clock measured elapsed time and the thing worth stopping is pointless
  # spinning. In three measured cases the clock ran through no fault of the
  # run's — the machine was asleep for 35 hours, an external queue held it for
  # most of 262 minutes, nobody resumed it. One run died having performed ZERO
  # acts, and the independent review it forced cost 2h17m and 82.23 USD. The
  # purpose survives; the yardstick is replaced, because the clock was a poor
  # proxy for it.
  #
  # WHAT ENDS A RUN NOW is `gate_end_run`, called from the two boundaries that
  # sit outside the pending-approval suppression: the cost ceiling at 100% and
  # the stagnation bound. This function only reads the mark they leave.
  #
  # It gates DISPATCH and MERGE and nothing else, exactly as the deadline did —
  # a stage in flight runs to completion and is classified normally, and the run
  # may still record rows, close approvals and propose that it is done. A
  # boundary that stopped everything would strand the run instead of ending it.
  #
  # THE MARK IS A CACHE AND THE LEDGER ROW IS THE AUTHORITY. `$RUN_DIR` is
  # volatile — a reaper, a temp sweep or a hand `rm -rf` takes it — and
  # `gate_main` calls `rundir_init` on every entry, which RE-CREATES the
  # directory empty. A run whose directory had been collected would come back
  # with no `done` file, this function would answer "not ended", and the end
  # would not be a refusal but a state the very next gate call silently
  # repaired: a run past its cost ceiling resuming dispatch. The ledger lives
  # OUTSIDE `$RUN_DIR` and is covered by the hash chain, so the row survives
  # everything the mark does not.
  local kind="$1" cut="$2" verb="${3:-}" mark idx merge_idx row
  if [ -s "$RUN_DIR/done" ]; then
    mark=$(cat "$RUN_DIR/done" 2>/dev/null || true)
  elif gate_has_row '자율 승인' '| 결정=종료 |'; then
    # The mark is gone and the row is not, so the reason is rebuilt from the
    # ending row's own fields. Both refusals below interpolate it, and an empty
    # parenthesis would tell the morning nothing about why the night stopped.
    #
    # MATCHED ON THE FIELD, NOT ON THE LINE. The bare substring `결정=종료 `
    # appears in free-text values too — `argv` and `근거` carry whatever a stage
    # typed, and a stage auditing this very code types the marker it is looking
    # for. Measured: two rows across every ledger in this repository contain it
    # and NEITHER is an ending row; one killed a live run, whose ledger then
    # pinned it forever because the row is authority and the chain is immutable.
    # Surrounding separators are the exact test rather than a tighter guess:
    # `gate_append` maps `|` out of every key and value, so a separator on both
    # sides cannot occur inside a value and appears only at a real boundary.
    row=$( { gate_rows '자율 승인' | grep -F '| 결정=종료 |' || true; } | tail -1)
    mark="경계 $(gate_row_field "$row" '기준') · 근거 $(gate_row_field "$row" '근거') (원장 종료 행 — 종단 표시는 수거됐습니다)"
  elif gate_progress_axes_unbounded && gate_past_deadline; then
    # THE CLOCK IS KEPT FOR THE MANIFESTS THAT HAVE NOTHING ELSE.
    #
    # Moving the yardstick to a progress-axis bound is right for a manifest that
    # declares one. Every manifest written before those fields were read declares
    # neither, and undeclared is legal for both — so for those runs the
    # replacement would not be a replacement but a removal, and the router path
    # would be left with no enforced bound at all. The failure shape is the worst
    # one available: unattended, it is silence rather than a crash.
    #
    # NARROW ON PURPOSE. When either bound is validly declared this arm is never
    # reached and the clock has no say over the run, which is the whole of why
    # the yardstick moved — the three measured cases where it ended a run through
    # no fault of the run's are not re-admitted here. The predicate above is the
    # same one every other reader of "is this run bounded" uses, so the run that
    # gets this gate is exactly the run that has nothing else.
    mark="벽시계 마감 경과 ($(manifest_field '인가' '벽시계 마감')) — 「비용 천장」과 「무진전 상한」이 둘 다 유효하게 선언되지 않아 마감이 유일한 경계입니다"
    # THE ARM NOW ENDS THE RUN, AND ONLY UNDER AN ACTING VERB. It used to refuse
    # and write nothing, so a run past its deadline never recorded that it had
    # ended and no later reader could tell why it stopped. `plan` reaches this
    # function too, and a dry run writes nothing — so the ending row is written
    # under `act` and `exec` alone. After it, `done` exists and the first arm
    # above answers every later call with the same refusal this arm gives.
    case "$verb" in
      act|exec) gate_end_run 마감 "$mark" 마감 || true ;;
    esac
  elif gate_defer_end_due; then
    # THE ONE CLOCK ENDING A RUN WITH A PROGRESS AXIS GETS. Such a run is ended
    # by its axis, and the clock arm above never reaches it — but a run whose
    # last hand-off gave its remaining answers to the next run has nothing left
    # for an axis to measure, and without this it would sit past its deadline
    # with no ending, so no successor would ever take the answers up. Written
    # under an acting verb only, for the reason the arm above gives.
    mark=$(gate_defer_end_why)
    case "$verb" in
      act|exec) gate_end_run 마감 "$mark" 마감 || true ;;
    esac
  else
    return 0
  fi

  if [ "$kind" = "skill" ]; then
    warn "the run has already terminated ($mark) — no new stage is launched. A stage already running goes to the end"
    return "$GATE_EXIT_RULE"
  fi
  # A DONE PROPOSAL HAS NO ACT BEHIND IT, so the merge arm below must not judge
  # it. `--cutpoint` is required of every acting call and carries no meaning
  # here — there is nothing for it to authorize — yet the deadline this replaces
  # read it and refused the proposal as if it were a merge. The consequence was
  # the worst available one: a run past its bound could not record that it had
  # ended, so the snapshot rendered it in flight forever and the watcher never
  # reaped itself.
  case "$kind" in propose-done) return 0 ;; esac
  # A BOOKKEEPING ACT HAS NO ACT BEHIND IT EITHER, for the same reason. It only
  # appends a row, and the router labels every call with the target's cutpoint,
  # so on a target whose cutpoint is `머지` the merge arm below read the row as a
  # merge and refused it. Measured: the shift whose `propose-done` had just been
  # accepted wrote its `handoff 사유=종단` row next, as its protocol requires,
  # got exit 3 here, and the gate filed it `무기록` — its abandoned alternatives
  # lost from the ledger. A row recorded after the end is what this function's
  # header already promises.
  gate_kind_is_bookkeeping "$kind" && return 0
  merge_idx=$(cutpoint_index '머지') || return 0
  idx=$(cutpoint_index "$cut") || return 0
  if [ "$idx" -ge "$merge_idx" ]; then
    warn "the run has already terminated ($mark) — there is no merge after termination"
    return "$GATE_EXIT_RULE"
  fi
  return 0
}

gate_ancestor_dirs() {
  # gate_ancestor_dirs <abs-dir> — every directory from the filesystem root down
  # to <abs-dir> itself, one per line, ROOT FIRST, `/` excluded.
  #
  # The walk is the same one the CLAUDE.md read allow-list takes in
  # `gate_write_settings`, with the same two termination bounds: the value has
  # to keep changing under `dirname`, and it has to be absolute to contribute
  # anything (`dirname .` is `.`, so a relative or empty input would otherwise
  # loop forever). That loop is deliberately NOT refactored onto this helper —
  # it renders settings bytes that enter the enforcement-surface digest — and
  # the two are held together by a test asserting the same directory SET
  # instead. The order is reversed here because the harness loads an
  # instruction chain outermost first, so the deepest file wins on conflicts.
  local adir="$1" aprev
  case "$adir" in /*) : ;; *) return 0 ;; esac
  {
    while [ -n "$adir" ] && [ "$adir" != "/" ]; do
      printf '%s\n' "$adir"
      aprev="$adir"
      adir=$(dirname "$adir")
      [ "$adir" != "$aprev" ] || break
    done
  } | awk '{ a[NR] = $0 } END { for (i = NR; i > 0; i--) print a[i] }'
}

gate_stage_policy_sources_map() {
  # The host map that names instruction files to leave OUT of a stage's chain,
  # `<source-id><TAB><absolute path>` per line. Host-local on purpose: the paths
  # are absolute and differ per machine, so a list shipped in the repository
  # would be right on its author's box and silently empty everywhere else.
  # `CC_GATE_STAGE_POLICY_SOURCES` is the test seam, the same shape as
  # `CC_GATE_SETTINGS_OVERRIDE` — the suite does not isolate `HOME`, so every
  # test that touches the map points this at a fixture (or at nothing).
  printf '%s' "${CC_GATE_STAGE_POLICY_SOURCES:-${HOME:-}/.config/cc-cmds/stage-policy-sources}"
}

gate_stage_policy_inventory_dirs() {
  # gate_stage_policy_inventory_dirs <inventory> — the config dirs of the
  # inventory a routed stage can be granted, one per line: the router's own
  # set, `unattended` `enabled` (a new grant) or `draining` (a held one), and a
  # row enrolled for interactive-seat lending, whose seat a lent stage reads
  # though it is disabled for unattended work. Nothing when the file does not
  # parse; the caller has already run the router's inventory check.
  jq -r '.accounts[]? | select(.unattended == "enabled" or .unattended == "draining"
      or (.interactive_lending == "auto" and .interactive_reserved == true and .unattended == "disabled"))
    | .config_dir // empty' "$1" 2>/dev/null || true
}

gate_personal_rules_seat_dir() {
  # The config dir the run was opened from, as the run directory records it;
  # nothing when the record cannot be read.
  { lane_record_read "$RUN_DIR/config-dir" "런 디렉터리의 config-dir" "-" >/dev/null 2>&1 \
      && printf '%s' "$LANE_RECORD"; } || true
}

gate_personal_rules_source() {
  # The file the personal rules block is copied from. The SEAT's, never this
  # process's: a routed stage is synthesized under its lease directory, and a
  # block read from there would differ per stage. Falls back to this process's
  # config dir only when the seat record cannot be read.
  # `CC_GATE_PERSONAL_RULES_SOURCE` is the test seam; it outranks the seat
  # record and every `HOME`/`CLAUDE_CONFIG_DIR` override, so a suite that
  # exports either still never reads a person's file.
  local seat
  if [ -n "${CC_GATE_PERSONAL_RULES_SOURCE:-}" ]; then
    printf '%s' "$CC_GATE_PERSONAL_RULES_SOURCE"
    return 0
  fi
  seat=$(gate_personal_rules_seat_dir)
  if [ -n "$seat" ]; then
    printf '%s/CLAUDE.md' "$seat"
  else
    printf '%s/CLAUDE.md' "${CLAUDE_CONFIG_DIR:-${HOME:-}/.claude}"
  fi
}

gate_stage_rules_status_ok() {
  # gate_stage_rules_status_ok <line> — whether <line> is one of the two status
  # lines `stage-rules.sh extract` ends with. Anything else is a failed check,
  # whatever the exit code said.
  case "$1" in
    'stage rules: untagged — legacy v6 policy') return 0 ;;
  esac
  grep -q -E '^stage rules: ok unattended=[0-9]+ bytes=[0-9]+ tokens~[0-9]+(\.[0-9]+)? interactive=[0-9]+ untagged=[0-9]+ malformed=[0-9]+$' <<< "$1"
}

gate_personal_rules_extract() {
  # gate_personal_rules_extract — write this run's personal rules snapshot under
  # `instructions/personal/`: the block as `<sha256>.md` and the pointer
  # `current` naming it, or `legacy untagged`. Called at run open and, for a
  # run opened before this snapshot existed, by the first synthesis that finds
  # no pointer. Never fails the caller.
  #
  # THE FAILURE IS RECORDED, NOT SWALLOWED. stdout, stderr and the exit code
  # are kept apart: only exit 0 with a status line as the last stdout line
  # logs that line. Anything else — a crash, a signal, a line in neither
  # grammar — logs `stage rules: 검사 실패 rc=<n>` with the first stderr line,
  # leaves `extract.err` on disk for the morning, and points `current` at
  # `failed rc=<n>` unless a pointer is already there, so the stages fall back
  # to the frozen v6 policy instead of running without the person's rules.
  #
  # ONE WRITER AT A TIME. Run open and a late extract from two launches can
  # meet; `personal.lock` (a directory, taken with `mkdir`) orders them, the
  # wait is bounded, and the lock is released on every way out of the
  # subshell. A pointer found under the lock is the winner's and is kept.
  # `CC_GATE_STAGE_RULES_BIN` is the test seam for the helper.
  local bin src pdir
  bin="${CC_GATE_STAGE_RULES_BIN:-$GATE_DIR/stage-rules.sh}"
  src=$(gate_personal_rules_source)
  pdir="$RUN_DIR/instructions/personal"
  (
    umask 077
    mkdir -p "$pdir" || exit 0
    lock="$RUN_DIR/instructions/personal.lock"
    got=0 i=0
    while [ "$i" -lt 50 ]; do
      if mkdir "$lock" 2>/dev/null; then got=1; break; fi
      i=$((i + 1))
      sleep 0.2
    done
    if [ "$got" = 1 ]; then
      trap 'rmdir "$lock" 2>/dev/null || true' EXIT
    else
      log "stage rules: $lock was not released within 10s — extracting without it"
    fi
    [ ! -f "$pdir/current" ] || exit 0
    rc=0
    bash "$bin" extract --source "$src" --out-dir "$pdir" \
      > "$pdir/extract.out" 2> "$pdir/extract.err" || rc=$?
    line=$(tail -n 1 "$pdir/extract.out" 2>/dev/null || true)
    if [ "$rc" = 0 ] && gate_stage_rules_status_ok "$line"; then
      log "$line"
      bytes=$(sed -n 's/.* bytes=\([0-9][0-9]*\) .*/\1/p' <<< "$line")
      if [ -n "$bytes" ] && [ "$bytes" -gt 24576 ]; then
        log "stage rules: the personal rules block is $bytes bytes, over the 24576-byte alert line — every stage carries it; run stage-rules.sh status after the run"
      fi
    else
      first=$(head -n 1 "$pdir/extract.err" 2>/dev/null || true)
      first=$(cut -b 1-200 <<< "$first")
      log "stage rules: 검사 실패 rc=$rc${first:+ — $first}"
      if [ ! -f "$pdir/current" ]; then
        ptmp=$(mktemp "$pdir/.current.XXXXXX") || exit 0
        printf 'failed rc=%s\n' "$rc" > "$ptmp"
        mv -n "$ptmp" "$pdir/current" 2>/dev/null || true
        [ ! -e "$ptmp" ] || rm -f "$ptmp"
      fi
    fi
  )
}

gate_personal_rules_lease_notice() {
  # gate_personal_rules_lease_notice — on a routed run, one log line naming the
  # eligible lease directories whose CLAUDE.md differs from the seat's. The
  # snapshot is the seat's alone, so a stage granted such a directory runs on
  # rules its own CLAUDE.md does not say; this line is how the morning learns.
  local seat seat_sha d dsha differ=""
  run_routed && [ -f "$RUN_DIR/inventory.json" ] \
    && route_inventory_check "$RUN_DIR/inventory.json" >/dev/null 2>&1 || return 0
  seat=$(gate_personal_rules_seat_dir)
  [ -n "$seat" ] || seat="${CLAUDE_CONFIG_DIR:-${HOME:-}/.claude}"
  seat_sha=$(shasum -a 256 "$seat/CLAUDE.md" 2>/dev/null | cut -d' ' -f1 || true)
  while IFS= read -r d; do
    [ -n "$d" ] && [ "$d" != "$seat" ] || continue
    dsha=$(shasum -a 256 "$d/CLAUDE.md" 2>/dev/null | cut -d' ' -f1 || true)
    [ "$dsha" = "$seat_sha" ] || differ="$differ $d"
  done <<GATE_LEASE_DIRS
$(gate_stage_policy_inventory_dirs "$RUN_DIR/inventory.json")
GATE_LEASE_DIRS
  [ -z "$differ" ] || log "stage rules: lease CLAUDE.md differs from the seat's, stages there still get the seat's snapshot:$differ"
}

gate_stage_instructions() {
  # gate_stage_instructions <alias> — synthesize the instruction file a stage of
  # this target is launched with; print its absolute path, or `warn` and return
  # 127 (the same code as a missing wrapper — a launch precondition).
  #
  # WHAT REPLACES AUTOMATIC CLAUDE.md LOADING. A stage launched with these
  # instructions runs with `CLAUDE_CODE_DISABLE_CLAUDE_MDS=1`, so nothing it
  # would have loaded on its own reaches it; this file is the whole of what it
  # gets. Its team members get a second file through the subagent append (THE
  # MEMBERS FILE, below). The lead file is `stage-policy.md` (the English stage
  # policy) and the run's `# Personal rules` block, both byte-identical for
  # every target, kind and segment of one run — the cache-stable head — then
  # the target's instruction chain: `CLAUDE.md`, `.claude/CLAUDE.md`, `CLAUDE.local.md` of
  # every ancestor of the target's MAIN worktree, root first, whichever exist.
  #
  # THE MAIN WORKTREE, NOT THE STAGE'S. The launchers never `cd` into a stage
  # worktree (the automatic loader read the router's cwd chain, which for a
  # non-home target was not even the target's), a review of a PR that edits
  # `CLAUDE.md` must not be judged by the rule that PR proposes, and orderbook's
  # repository-root file is gitignored and exists only in the main worktree. The
  # chain is the ANCESTOR chain because that is where the orderbook rules live —
  # in a file outside git, above the repository — so "the target's CLAUDE.md"
  # read literally would drop them without a trace.
  #
  # CONTENT-ADDRESSED AND FREE OF VOLATILE TOKENS: no run id, time, segment,
  # attempt or worktree path goes in, the name is the sha256 of the bytes, and
  # so every stage of one target in one run shares one lead file — and one
  # prompt-cache head — and every team member shares one members file. `umask
  # 077` because an ancestor file may carry
  # a credential line: the automatic loader sent those bytes too, but the disk
  # copy must not be readable by another user, and the hook denies a stage every
  # write under `instructions/`.
  #
  # REFUSALS FAIL CLOSED. An empty or non-directory main worktree would make the
  # chain empty and the stage would run on the policy alone, having quietly
  # lost every repository rule; a missing policy file would put it back on
  # automatic loading, which is the state this replaces. Both refuse rather than
  # degrade. A `.claude/rules/` directory anywhere in the chain refuses because
  # `paths:`-conditioned rules cannot be flattened without either widening them
  # to always-on or dropping them, and both are silent; an `@import` line
  # outside a fenced block refuses because verbatim injection does not expand
  # it. Today no target or ancestor has either, so nothing is stopped.
  #
  # THE USER-SCOPE SETTINGS DIRECTORY IS NOT AN ANCESTOR. The chain excludes
  # only `/`, so a main worktree under the home directory walks through it, and
  # on a host without `CLAUDE_CONFIG_DIR` the home `.claude/` IS the user-scope
  # directory — its `CLAUDE.md` is the global instruction file this policy
  # declares itself a replacement for, and its `rules/` are user-scope rules,
  # not repository ones. So a chain directory whose `.claude` resolves to that
  # directory contributes neither; its plain `CLAUDE.md` and `CLAUDE.local.md`
  # are included as usual. The derivation is the settings renderer's own.
  #
  # THE HOST MAP EXCLUDES ANCESTOR FILES, guards evaluated in this order per
  # line: a malformed line (no TAB, path not absolute) refuses, naming the line
  # — a typo must not switch an exclusion off silently; a path not on disk logs
  # one line and excludes nothing; a path equal to one of the target root's own
  # three instruction files refuses — repository rules cannot be excluded; any
  # other path joins the exclusion set, and one outside this chain simply never
  # matches (the map is host-wide, so the cc-cmds workspace file is not in an
  # orderbook chain, and refusing it would stop every orderbook launch). Every
  # comparison is between PHYSICAL paths on both sides: with one side left as
  # spelled, a symlinked spelling (`/var` vs `/private/var`) would judge a real
  # ancestor as "outside the chain" and the exclusion would vanish silently.
  # A line whose source id is `keep` names a file the chain carries anyway and
  # logs that it was kept. Without a map line an ancestor goes into the chain
  # verbatim: the map is the only way to leave one out.
  #
  # THE PERSONAL RULES BLOCK. The policy is followed by `# Personal rules`, the
  # snapshot this run took at open (`gate_personal_rules_extract`), read
  # through the pointer `instructions/personal/current` and never from a
  # config dir at synthesis time: a routed launch synthesizes under its lease
  # directory, and its own CLAUDE.md must not leak into the block. A pointer
  # that reads `legacy untagged` or `failed rc=<n>` swaps the policy for the
  # frozen v6 copy (`legacy/stage-policy.v6.md`) with no personal block — the
  # rules a stage got before the tags existed. No pointer means a run opened
  # before this release; the snapshot is taken then, under the same lock. No
  # branch of this refuses for the state of the tags: a shift launch calls this
  # same synthesis and passes its refusal on.
  #
  # THE MEMBERS FILE. Beside the lead file the same inputs make a second one,
  # for the Agent-tool members, who are read-only: the same policy, a header
  # saying the repository's files come as paths, the ancestors outside the
  # repository root verbatim (after the same exclusion), and in place of each
  # of the repository root's own instruction files the absolute path of the
  # main worktree's file with one sentence telling the member to read the parts
  # it needs. It is content-addressed the same way, and a pointer
  # `instructions/<lead sha256>.member` holding its path is written beside the
  # lead file, so a launcher that holds only the lead path — a launch token
  # carries one — finds the members file, and a resume that follows the lead
  # file follows its members file too.
  local alias="$1" root slug policy rootp cfgdir cfgp map excl=$'\n' keep=$'\n' n line id p pp
  local d f name label fence_hit i tmp sha dst mtmp msha mdst ptmp pdir pline psha psnap
  local chain_files=() labels=() roots=()
  root=$(target_field "$alias" '메인 워크트리')
  if [ -z "$root" ] || [ ! -d "$root" ]; then
    warn "stage instructions: target '$alias' has no usable main worktree ('${root:-}') — refusing to launch; an empty chain would drop every repository rule"
    return 127
  fi
  slug=$(target_field "$alias" '원격 슬러그')
  if [ -z "$slug" ]; then
    warn "stage instructions: target '$alias' has no remote slug in the manifest — refusing to launch; the chain labels need it"
    return 127
  fi
  policy="$GATE_DIR/stage-policy.md"
  if [ ! -f "$policy" ]; then
    warn "stage instructions: stage policy not found: $policy — refusing to launch; automatic CLAUDE.md loading is not a fallback"
    return 127
  fi
  pdir="$RUN_DIR/instructions/personal"
  [ -f "$pdir/current" ] || gate_personal_rules_extract || true
  pline=$(head -n 1 "$pdir/current" 2>/dev/null || true)
  psha="${pline%% *}"
  psnap=""
  if [ "$psha" != "$pline" ] && [ "${#psha}" = 64 ] && [ -z "${psha//[0-9a-f]/}" ] \
     && [ -f "$pdir/$psha.md" ]; then
    psnap="$pdir/$psha.md"
  else
    case "$pline" in
      'legacy untagged'|'failed rc='*) : ;;
      *) log "stage instructions: personal rules pointer unreadable ('${pline:-none}') — using the frozen v6 policy" ;;
    esac
    policy="$GATE_DIR/legacy/stage-policy.v6.md"
    if [ ! -f "$policy" ]; then
      warn "stage instructions: frozen v6 policy not found: $policy — refusing to launch; automatic CLAUDE.md loading is not a fallback"
      return 127
    fi
  fi
  rootp=$(cd "$root" && pwd -P)
  cfgdir="${CLAUDE_CONFIG_DIR:-}"
  [ -n "$cfgdir" ] || cfgdir="${HOME:-}${HOME:+/.claude}"
  cfgp=""
  [ -n "$cfgdir" ] && [ -d "$cfgdir" ] && cfgp=$(cd "$cfgdir" && pwd -P)

  map=$(gate_stage_policy_sources_map)
  if [ -n "$map" ] && [ -f "$map" ]; then
    n=0
    while IFS= read -r line || [ -n "$line" ]; do
      n=$((n + 1))
      case "$line" in ''|'#'*) continue ;; esac
      case "$line" in
        *"	"*) : ;;
        *) warn "stage instructions: host map line $n has no TAB (expected <source-id><TAB><absolute path>): $map"
           return 127 ;;
      esac
      id="${line%%	*}"
      p="${line#*	}"
      case "$p" in
        /*) : ;;
        *) warn "stage instructions: host map line $n names a path that is not absolute: $map"
           return 127 ;;
      esac
      if [ ! -e "$p" ]; then
        log "stage instructions: source $id is not on disk, nothing excluded: $p"
        continue
      fi
      pp="$(cd "$(dirname "$p")" && pwd -P)/$(basename "$p")"
      if [ "$id" = keep ]; then
        keep="$keep$pp"$'\n'
        continue
      fi
      case "$pp" in
        "$rootp/CLAUDE.md"|"$rootp/.claude/CLAUDE.md"|"$rootp/CLAUDE.local.md")
          warn "stage instructions: host map line $n names a target root instruction file, which cannot be excluded: $p"
          return 127 ;;
      esac
      excl="$excl$pp"$'\n'
    done < "$map"
  fi

  while IFS= read -r d; do
    [ -n "$d" ] || continue
    if [ -d "$d/.claude/rules" ]; then
      if [ -z "$cfgp" ] || [ "$(cd "$d/.claude" && pwd -P)" != "$cfgp" ]; then
        warn "stage instructions: $d/.claude/rules/ exists — refusing to launch; conditional rules cannot be injected verbatim, and a person decides whether to flatten or drop them"
        return 127
      fi
    fi
    for name in CLAUDE.md .claude/CLAUDE.md CLAUDE.local.md; do
      f="$d/$name"
      [ -f "$f" ] || continue
      if [ "$name" = ".claude/CLAUDE.md" ] && [ -n "$cfgp" ] \
        && [ "$(cd "$d/.claude" && pwd -P)" = "$cfgp" ]; then
        continue
      fi
      pp="$(cd "$(dirname "$f")" && pwd -P)/$(basename "$f")"
      case "$excl" in
        *$'\n'"$pp"$'\n'*) log "stage instructions: excluding $pp by the host map"; continue ;;
      esac
      if [ "$d" != "$rootp" ]; then
        case "$keep" in
          *$'\n'"$pp"$'\n'*) log "stage instructions: keeping $pp by the host map" ;;
        esac
      fi
      # An `@import` line outside a fenced block: verbatim injection does not
      # expand it, so the imported rules would be lost silently. The shape
      # requires a path (`@~`, `@.`, `@/`, or `@name/`), so an annotation line
      # such as `@Transactional` in a Java target's notes is not refused.
      fence_hit=$(awk '
        /^[[:space:]]*(```|~~~)/ { fence = !fence; next }
        !fence && /^[[:space:]]*@(~|\.|\/|[A-Za-z0-9_.-]+\/)/ { print NR; exit }
      ' "$f")
      if [ -n "$fence_hit" ]; then
        warn "stage instructions: $f:$fence_hit is an @import line outside a code fence — refusing to launch; verbatim injection cannot expand it"
        return 127
      fi
      if [ "$d" = "$rootp" ]; then
        label="$slug/$name"
        roots[${#roots[@]}]=1
      else
        label="$f"
        roots[${#roots[@]}]=0
      fi
      chain_files[${#chain_files[@]}]="$f"
      labels[${#labels[@]}]="$label"
    done
  done < <(gate_ancestor_dirs "$rootp")

  # THE TARGET-HOOK PARAGRAPH, decided at the root the launched session starts
  # at. The launch does not move the directory, so that root is this process's
  # own; when it carries a Bash hook of its own, the session is told how a
  # remote command gets past both hooks. Members do not issue remote commands
  # and their file goes without it.
  local hooked=0
  gate_target_has_bash_hook "$(pwd -P)" && hooked=1

  (
    umask 077
    mkdir -p "$RUN_DIR/instructions" || exit 1
    tmp=$(mktemp "$RUN_DIR/instructions/.stage.XXXXXX") || exit 1
    {
      cat "$policy"
      if [ -n "$psnap" ]; then
        printf '\n# Personal rules\n\n'
        cat "$psnap"
      fi
      printf '\n# Repository instructions\n\nThe files below are the instruction chain of the target repository, root first. Each begins with a heading naming its file.\n'
      i=0
      while [ "$i" -lt "${#chain_files[@]}" ]; do
        printf '\n---\n# %s\n\n' "${labels[$i]}"
        cat "${chain_files[$i]}"
        i=$((i + 1))
      done
      if [ "$hooked" = 1 ]; then
        printf '\n---\n'
        gate_thp thp_instruction_paragraph
      fi
    } > "$tmp" || { rm -f "$tmp"; exit 1; }
    sha=$(shasum -a 256 "$tmp" | cut -d' ' -f1)
    dst="$RUN_DIR/instructions/$sha.md"
    # `mv -n` publishes atomically and refuses an existing target; the name is
    # the content hash, so an existing target holds these same bytes. But `mv -n`
    # leaves its source behind on refusal, and that source holds the same
    # credential-bearing bytes — remove it, or one copy accumulates per launch.
    mv -n "$tmp" "$dst" 2>/dev/null || true
    [ ! -e "$tmp" ] || rm -f "$tmp"
    [ -f "$dst" ] || exit 1
    # The members file and its pointer, published the same way.
    mtmp=$(mktemp "$RUN_DIR/instructions/.member.XXXXXX") || exit 1
    {
      cat "$policy"
      if [ -n "$psnap" ]; then
        printf '\n# Personal rules\n\n'
        cat "$psnap"
      fi
      printf '\n# Repository instructions\n\nThe files below are the instruction chain of the target repository, root first. Each begins with a heading naming its file; the repository'"'"'s own files are given as paths to read, not as their text.\n'
      i=0
      while [ "$i" -lt "${#chain_files[@]}" ]; do
        printf '\n---\n# %s\n\n' "${labels[$i]}"
        if [ "${roots[$i]}" = 1 ]; then
          printf '%s\n\nRead the parts that bear on a file before you judge or quote a rule about it.\n' "${chain_files[$i]}"
        else
          cat "${chain_files[$i]}"
        fi
        i=$((i + 1))
      done
    } > "$mtmp" || { rm -f "$mtmp"; exit 1; }
    msha=$(shasum -a 256 "$mtmp" | cut -d' ' -f1)
    mdst="$RUN_DIR/instructions/$msha.md"
    mv -n "$mtmp" "$mdst" 2>/dev/null || true
    [ ! -e "$mtmp" ] || rm -f "$mtmp"
    [ -f "$mdst" ] || exit 1
    ptmp=$(mktemp "$RUN_DIR/instructions/.pointer.XXXXXX") || exit 1
    printf '%s\n' "$mdst" > "$ptmp" || { rm -f "$ptmp"; exit 1; }
    mv -n "$ptmp" "$RUN_DIR/instructions/$sha.member" 2>/dev/null || true
    [ ! -e "$ptmp" ] || rm -f "$ptmp"
    printf '%s' "$dst"
  ) || {
    warn "stage instructions: could not publish the synthesized file under $RUN_DIR/instructions — refusing to launch"
    return 127
  }
}

gate_stage_instructions_for_launch() {
  # gate_stage_instructions_for_launch <alias> <resume-session-id|''> — the
  # `--instructions` file for this launch, printed; empty means "launch in
  # legacy mode, without the option". Synthesis refusals propagate (127).
  #
  # EVERY LAUNCH LOGS THE DIGEST, resume or not, so the run log alone says
  # which synthesis each launch ran on — no ledger field carries it.
  #
  # RESUME FOLLOWS THE SESSION'S OWN RECORD. A session born under automatic
  # loading and resumed with the switch-off plus a new append sees NEITHER the
  # old CLAUDE.md nor the new policy (measured; `--system-prompt-snapshot off`
  # does not repair it), so a session with no record — born before this
  # mechanism — resumes in legacy mode, exactly as it was born. A session with
  # a record resumes on the RECORDED file even when the current synthesis
  # differs: the resumed main session keeps the append it was born with while
  # members spawned after the resume receive the new subagent append, so
  # passing the new file would put the lead and its team on different policies.
  # Only when the recorded file is gone from disk does the current synthesis
  # stand in, and the log says so.
  local alias="$1" resume="$2" now rec recf
  now=$(gate_stage_instructions "$alias") || return $?
  log "stage instructions: $alias sha256=$(basename "$now" .md)"
  if [ -z "$resume" ]; then
    printf '%s' "$now"
    return 0
  fi
  rec="$RUN_DIR/instructions/session/$resume"
  if [ ! -f "$rec" ]; then
    log "resuming a session launched before stage instructions; launching in legacy mode"
    printf ''
    return 0
  fi
  recf="$RUN_DIR/instructions/$(tr -d '[:space:]' < "$rec").md"
  if [ ! -f "$recf" ]; then
    log "stage instructions: recorded file $(basename "$recf") is gone; passing the current synthesis"
    printf '%s' "$now"
    return 0
  fi
  if [ "$recf" != "$now" ]; then
    log "stage instructions: session $resume was launched with $(basename "$recf" .md); current synthesis is $(basename "$now" .md) — keeping the recorded file"
  fi
  printf '%s' "$recf"
}

gate_stage_member_instructions() {
  # gate_stage_member_instructions <lead file> — the members file the pointer
  # beside <lead file> names, printed; empty when there is no pointer (a file
  # synthesized before the members file existed) or it names nothing usable, and
  # then the wrapper gives the members the lead file, as before.
  local lead="$1" ptr m
  [ -n "$lead" ] || return 0
  ptr="${lead%.md}.member"
  [ -f "$ptr" ] || return 0
  m=$(head -n 1 "$ptr")
  [ -n "$m" ] && [ -s "$m" ] || return 0
  printf '%s' "$m"
}

gate_stage_instructions_record() {
  # gate_stage_instructions_record <session-id> <file> — remember which
  # synthesis a NEW session was launched with, so a later resume can follow it.
  # Same umask as the files themselves; a stage cannot write here.
  local sid="$1" f="$2" tmp
  (
    umask 077
    mkdir -p "$RUN_DIR/instructions/session" || exit 1
    tmp=$(mktemp "$RUN_DIR/instructions/session/.rec.XXXXXX") || exit 1
    printf '%s\n' "$(basename "$f" .md)" > "$tmp" || { rm -f "$tmp"; exit 1; }
    mv "$tmp" "$RUN_DIR/instructions/session/$sid"
  ) || warn "stage instructions: could not record the synthesis for session $sid"
}

gate_act_worktree() {
  # gate_act_worktree <별칭> [<세그먼트>] — the directory this target's acts
  # actually run in.
  #
  # THE SEGMENT'S OWN WORKTREE FIRST, when the act carries a segment and that
  # segment row's `워크트리` passes gate_segment_worktree_of_target. A segment
  # act used to ignore the row entirely and run in the target's tree, so every
  # stage worked in the shared main worktree and the router had to switch that
  # tree onto the segment's branch to make anything land.
  #
  # Then `실행 워크트리`, the main worktree as the last fallback. One field could
  # not carry both duties: the sidecar path has to converge on the main worktree so
  # that N linked worktrees of one repository do not split the state a single
  # writer owns, while the act has to run where the branch actually is. For a pr
  # or branch anchor those are never the same directory — git refuses to check a
  # branch out twice.
  #
  # ONE RESOLUTION FOR FOUR READERS, and that is the whole reason this is a
  # function. Each of them read the field itself, and they disagreed: the
  # act ran in the execution worktree while its approval's binding tuple was
  # frozen against the MAIN worktree's head and compared against that same head
  # later. So an answer given at 22:00 stayed "fresh" through a night of commits
  # landing in the tree the act was actually run in, and a sibling segment moving
  # the main worktree expired approvals about a tree that had not moved. Freezing
  # and comparing must resolve identically or every approval already issued goes
  # stale at once and a person is asked the same question all over again. The
  # segment argument is part of that one resolution: all four readers pass it,
  # and one that did not would bind an approval to a different tree.
  #
  # The four are: the act's own cwd (`GATE_ACT_CWD`), the grading base
  # (`GATE_GRADE_CWD`, and `gate_tree_root` on top of it), the approval id's
  # fourth field, and the freeze/staleness head probe.
  #
  # THE UNDECLARED ARM RESOLVES HERE TOO, and it reads its own variable rather
  # than `GATE_ACT_CWD`. An undeclared alias has no target row, so both
  # `target_field` lookups below answer empty and every reader that was not the
  # one call site assigning `GATE_ACT_CWD` got that empty string: the grading
  # base fell through to `$PWD`, the tree root followed it, the approval id
  # carried `""` in its fourth field, and the two `cd "$(…)"` readers ran a
  # successful no-op `cd ""` that read the GATE'S OWN head instead of the
  # target's. Reading `GATE_ACT_CWD` here instead would make the declared arm
  # pick up a parent gate's exported value, which is the inheritance defect the
  # assignment site below was moved up to close — so the undeclared arm gets a
  # variable of its own, set where the flag is set and never exported.
  #
  # A PREDICATE FAILURE FALLS BACK HERE AND IS REFUSED BY THE CALLER. Returning
  # non-zero instead would read better and cannot be done: two of the three
  # readers compose this as `cd "$(gate_act_worktree …)"`, where an empty stdout
  # sends the `cd` to the caller's directory rather than stopping anything. So
  # the refusal lives in gate_verb_act's pre-check, which runs before any rule or
  # approval and names both the offending value and the condition it failed. The
  # two must stay in step: a caller that resolves through here without that
  # pre-check in front of it gets the silent fallback back.
  #
  # THE AUDIT STAGE'S OWN ACTS RUN IN THE AUDIT'S WORKTREE. The audit is a
  # run-scope step, so its acts carry `--segment -` and no row names a tree for
  # them; left to the fallback below they ran in the main worktree, the one every
  # run and session on the repository fast-forwards after a merge, and the
  # audit's freeze check read that moving `HEAD` as a mismatch. The arm keys on
  # the caller being that stage (`gate_caller_is_audit_stage`) and on the tree
  # already existing as a worktree of this target, which the dispatch made — so
  # the design step, the router and every segment keep their resolution.
  local wt
  [ "${GATE_UNDECLARED:-0}" = "1" ] && { printf '%s' "$GATE_UNDECLARED_WT"; return 0; }
  case "${2:-}" in
    ''|-) if gate_caller_is_audit_stage \
             && wt=$(gate_audit_worktree_path "$1") \
             && gate_path_of_target "$wt" "$1"; then
            printf '%s' "$wt"
            return 0
          fi ;;
    *) if wt=$(gate_segment_worktree_of_target "$2" "$1"); then
         printf '%s' "$wt"
         return 0
       fi ;;
  esac
  wt=$(target_field "$1" '실행 워크트리')
  case "$wt" in
    ''|'(없음)') wt=$(target_field "$1" '메인 워크트리') ;;
  esac
  printf '%s' "$wt"
}

gate_audit_worktree_path() {
  # gate_audit_worktree_path <별칭> — `<메인 워크트리>-run-<런 id>-<감사 단계 id>`,
  # the tree the run-scope audit step runs in. Returns 1 with nothing printed
  # when the plan does not name exactly one audit step or the target has no
  # main worktree. One name per (run, step), so a re-audit of the same key finds
  # the tree the first audit used.
  local step main
  step=$(gate_run_scope_step audit) || return 1
  main=$(target_field "$1" '메인 워크트리' 2>/dev/null || true)
  case "$main" in ''|'(없음)') return 1 ;; esac
  printf '%s%s%s-%s' "$main" "$WORKTREE_INFIX" "$RUN_ID" "$step"
}

gate_caller_is_audit_stage() {
  # 0 when this gate call comes from the run-scope audit stage or a member it
  # spawned: the launcher hands the stage `CC_PIPELINE_STAGE_ID=<step>#<attempt>`
  # and the step is the plan's single audit step with no `segment` row of its
  # own — the same facts `gate_stage_row_segment` reads. The router and the
  # driver carry no stage id, so they never match.
  local sid="${CC_PIPELINE_STAGE_ID:-}" step
  [ -n "$sid" ] || return 1
  step=$(gate_run_scope_step audit) || return 1
  [ "${sid%#*}" = "$step" ] || return 1
  [ -z "$(gate_segment_field "$step" '상태')" ]
}

gate_audit_worktree_ensure() {
  # gate_audit_worktree_ensure <별칭> — the audit dispatch's tree: created
  # detached at the tip of the target's base branch when absent, reused when it
  # is already a worktree of this target, and refused when the path is taken by
  # anything else. Then admitted to the stage settings the way a `segment` row
  # admits its worktree, because no row will name this one.
  #
  # PERFORMED, NOT CHECKED. It runs from the dispatch switch, after the row and
  # every rule, so a refused dispatch leaves no tree behind; and before the
  # launch, so the stage's first act already resolves here.
  local alias="$1" wt root base lk
  if ! wt=$(gate_audit_worktree_path "$alias"); then
    warn "감사 워크트리 경로를 정하지 못했습니다 — 실행 계획의 감사 단계 하나와 대상 ${alias} 의 메인 워크트리가 있어야 합니다"
    return "$GATE_EXIT_RULE"
  fi
  if [ -e "$wt" ]; then
    if ! gate_path_of_target "$wt" "$alias"; then
      warn "감사 워크트리 자리 ${wt} 가 이미 있지만 대상 ${alias} 의 워크트리가 아닙니다 — 건드리지 않고 감사를 띄우지 않습니다"
      return "$GATE_EXIT_RULE"
    fi
    log "감사 워크트리 재사용 — $wt"
  else
    root=$(target_field "$alias" '메인 워크트리')
    base=$(target_field "$alias" '베이스 브랜치' 2>/dev/null || true)
    if [ -z "$base" ]; then
      warn "대상 ${alias} 에 베이스 브랜치 가 없어 감사 워크트리를 만들 수 없습니다"
      return "$GATE_EXIT_RULE"
    fi
    if ! ( cd "$root" && git worktree add --detach "$wt" "$base" >/dev/null 2>&1 ); then
      warn "감사 워크트리를 베이스 ${base} 끝에 분리해 만들지 못했습니다: $wt"
      return "$GATE_EXIT_RULE"
    fi
    log "감사 워크트리 — $wt (베이스 ${base} 끝에 분리)"
  fi
  [ -n "${RUN_DIR:-}" ] || return 0
  lk="$RUN_DIR/settings.lock"
  if gate_settings_lock "$lk"; then
    GATE_SETTINGS_LOCK_HELD="$lk"
    gate_resettle_settings_for_segment "$(gate_run_scope_step audit)" "$wt" >/dev/null
    gate_settings_lock_release
  else
    warn "인가 디렉터리를 재유도하지 못했습니다 — settings.lock 을 기다리다 시간이 넘었습니다 ($lk); 감사 워크트리 $wt 는 다음 재유도까지 인가 목록에 오르지 않습니다"
  fi
  return 0
}

gate_plan_unchecked_axes() {
  # gate_plan_unchecked_axes <kind> — the axes this dry run did NOT evaluate,
  # named on stderr.
  #
  # A forecast that reports only its verdict reads as a complete answer, and the
  # router acts on it as one. Two axes stay structurally out of reach here, and
  # each of them returns a code the router has no other way to anticipate — so
  # what this turns a passing `plan` into is "these held, and these two were not
  # looked at" rather than a green light.
  #
  # THE ENFORCEMENT SURFACE IS DELIBERATELY ABSENT FROM THIS LIST. It used to be
  # unreachable for this verb and is now compared like any other read; listing it
  # here would keep telling the router to expect a blind spot that was closed.
  local kind="$1"
  warn "plan(dry-run) unchecked axes — the axes below are the ones this preview did not evaluate:"
  # Not compared, because a dry run is not bound to the state it read: the guard
  # on the way in skips it for this verb outright. So the same argv issued as
  # `act` can still come back 4 when a sibling segment landed a row in between.
  warn "  - snapshot digest — act checks --snapshot-digest against the current value and returns 4 when they differ"
  case "$kind" in
    segment|cycle|problem|blocked|clause|judgment|obligation|obligation-done|obligation-drop|limit-cleared|reentry|halt-answer|review-dismiss|review-carry|shift-halt|base-check|remote-check|replan|halt-settle)
      # The `키=값` list after `--` is validated by the row writer, and the row
      # writer runs only on the performing path. The record-time checks are
      # defined by `gate_record_row` and this note does not enumerate them — a
      # count kept here goes stale the moment one is added. The kinds, for
      # example: predecessor monotonicity, an absent predecessor, a cycle row's
      # required keys, HEAD shape and delta checks, the caller-key refusals, the
      # cone anchor. Naming the axis is what lets the router expect them instead
      # of meeting them.
      warn "  - record row field validity (${kind}) — the \`키=값\` fields after -- are checked at record time, so an act with the same argv can come back 2 or 6" ;;
  esac
}

# ---------------------------------------------------------------------------
# The apply act — `act --kind apply -- 적용`.
#
# THE GATE RUNS THE COMMAND AND THE ROUTER NAMES NONE OF IT. The argv is the one
# token `적용`; the command and its probe are the frozen ones the driver's S9
# reads (`apply_field`, `apply_probe_cmd`), the commit is the merge commit the
# router recorded on the `머지됨` row and the gate proves, and the verdict is the
# driver's own `apply_disposition`, fed the exit-code mapping the driver's own
# `apply_probe_codes` reads from the manifest. A router that could pass the
# command would be an apply nobody authorized, and a second copy of the verdict table is a
# second answer to what an exit code means. A mapping row frozen against other
# probe bytes than the probe this act runs is a refusal, not the default 0/2.
#
# FIVE PRECONDITIONS, AHEAD OF THE RULE CATALOG AND OUTSIDE IT. `리뷰-후-머지` is
# a rule a manifest may switch off; the facts below are what make this act an
# apply of the reviewed change at all, so `끔` must not reach them. Every one is
# a read, and a refusal leaves neither a row nor a worktree.
#
# THE GATE DOES NOT FETCH. A merge happens on the remote, so a clone that has
# not fetched lacks the commit or the base that holds it, and precondition 4
# refuses — the router fetches through its own pre-authorized exec and calls
# again. Fetching here would make the act's outcome depend on a network read
# the ledger does not show.
# ---------------------------------------------------------------------------

gate_apply_value() {
  # gate_apply_value <segment> <key> — the frozen apply field with its backtick
  # rendering stripped, `(없음)` and `없음` read as absent.
  local v
  v=$(apply_unquote "$(apply_field "$1" "$2" 2>/dev/null || true)")
  case "$v" in '(없음)'|'없음') v="" ;; esac
  printf '%s' "$v"
}

gate_segment_cutpoint() {
  # gate_segment_cutpoint <alias> <segment> — the rung the segment stops at: its
  # own row first (a declaration-filled row carries it), the slice declaration
  # second, the target row last.
  local v
  v=$(gate_segment_field "$2" '절단점')
  [ -n "$v" ] || v=$(gate_apply_value "$2" '절단점')
  [ -n "$v" ] || v=$(target_field "$1" '절단점' 2>/dev/null || true)
  printf '%s' "$v"
}

gate_segment_owes_apply() {
  # gate_segment_owes_apply <alias> <segment> — a frozen apply command, the
  # pipeline as its actor, and `배포` as the segment's cutpoint. Only such a
  # segment has an apply this run is to perform, so only its `머지됨` is not an
  # ending.
  [ -n "$(gate_apply_value "$2" '적용 명령')" ] || return 1
  [ "$(gate_apply_value "$2" '적용 주체')" = "파이프라인" ] || return 1
  [ "$(gate_segment_cutpoint "$1" "$2")" = "배포" ]
}

gate_segment_apply_pending() {
  # gate_segment_apply_pending <segment> — the last row is `머지됨` carrying the
  # `적용=대기` the segment arm wrote. Read from the ledger alone, so this and
  # `cc_nonterminal_segments` answer from the same bytes.
  [ "$(gate_segment_field "$1" '상태')" = "머지됨" ] \
    && [ "$(gate_segment_field "$1" '적용')" = "대기" ]
}

gate_apply_line_of() {
  # gate_apply_line_of <series> <key> <value> — the ledger line number of the
  # last row of that series whose <key> field equals <value>, empty when none.
  # Field equality, not a substring: a later `cycle` row of another segment
  # carrying `선행 세그먼트=<seg>` must not be read as this segment's last.
  # The `<n>:` prefix `grep -n` adds sits in the row's first `|` field, which
  # the field matcher never reads.
  { grep -nE "^- \`$1\`" "$LEDGER" 2>/dev/null || true; } \
    | gate_rows_field_eq "$2" "$3" | tail -1 | cut -d: -f1
}

gate_segment_apply_state() {
  # gate_segment_apply_state <alias> <segment> — what the segment still owes
  # after its merge, one of three words. `대기`: the last row is `머지됨`
  # carrying `적용=대기`, read from the ledger alone, so it answers from the
  # bytes exit condition 1 and `cc_nonterminal_segments` read. `인계`: the last
  # row is `머지됨`, a frozen apply command exists, its actor is a person, and
  # no `적용 인계` row names the segment yet — the handover row is the only way
  # that command reaches the morning. `없음`: everything else, so a merge with
  # no command, a cutpoint below `배포` or a handover already written is the
  # segment's end. Two readers only: the apply preconditions and the snapshot.
  # The alias is taken for the signature; the answer reads the ledger and the
  # frozen apply fields alone.
  if [ "$(gate_segment_field "$2" '상태')" != "머지됨" ]; then
    printf '없음'
  elif gate_segment_apply_pending "$2"; then
    printf '대기'
  elif [ -n "$(gate_apply_value "$2" '적용 명령')" ] \
       && [ "$(gate_apply_value "$2" '적용 주체')" = "사람" ] \
       && [ -z "$(gate_apply_line_of '적용 인계' '세그먼트' "$2")" ]; then
    printf '인계'
  else
    printf '없음'
  fi
}

gate_apply_refuse() {
  # gate_apply_refuse <전제 번호> <message> — one refusal shape for all five, so
  # the router's handoff can quote the number and the sentence.
  warn "적용 행위 전제 $1 불충족 — $2"
  warn "적용 워크트리도 원장 행도 남기지 않았습니다"
  return "$GATE_EXIT_RULE"
}

gate_apply_preconditions() {
  # gate_apply_preconditions <verb> <alias> <segment> — the five, in order. On
  # success sets GATE_APPLY_MERGE (M), GATE_APPLY_SUBJECT (the reviewed head,
  # which is M^2 or the head M^2 honestly renumbers), GATE_APPLY_COMMAND and
  # GATE_APPLY_PROBE. A segment whose actor is a person gets its handover row
  # here and the caller ends with 0.
  #
  # THE ORDER IS REPOSITORY, 1, THEN WHAT THE SEGMENT OWES, THEN 2 TO 5. A
  # segment past 1 whose `gate_segment_apply_state` is `없음` owes no apply:
  # GATE_APPLY_NOT_OWED is set and 0 returned before 2 to 5 are read, so a merge
  # with no command or a cutpoint below `배포` ends there instead of being
  # refused by a precondition that only an owed apply needs. 1 stays ahead of
  # it, so an apply on an unmerged segment, or a second one on a segment that
  # already ended, is still refused.
  local verb="$1" alias="$2" seg="$3"
  local st m pol cline sline crow p0 p1 rh rep rep_abs root base parents m2 rhfull actor cut repo ralias t why
  GATE_APPLY_MERGE=""; GATE_APPLY_SUBJECT=""; GATE_APPLY_COMMAND=""; GATE_APPLY_PROBE=""
  GATE_APPLY_HANDOVER=""; GATE_APPLY_NOT_OWED=""

  # The repository is the one the plan row declares. Every path below — the
  # merge commit's lookup and the apply worktree beside the root — is derived
  # from `--target`, so a row whose `레포` names another target is refused
  # before anything else is read, rather than applied under the wrong root.
  repo=$(gate_segment_field "$seg" '레포' | tr -d '`')
  if [ -n "$repo" ]; then
    ralias=$(alias_for_slug "$repo" 2>/dev/null || true)
    [ "$ralias" = "$alias" ] || { gate_apply_refuse 4 "세그먼트 ${seg} 의 레포 ${repo} 는 대상 ${ralias:-(선언 안 됨)} 이고 --target ${alias} 가 아닙니다"; return $?; }
  fi

  # 1 — the last segment row is `머지됨` and names its merge commit.
  st=$(gate_segment_field "$seg" '상태')
  [ "$st" = "머지됨" ] || { gate_apply_refuse 1 "세그먼트 ${seg} 의 마지막 segment 행이 머지됨 이 아닙니다 (${st:-행 없음})"; return $?; }
  m=$(gate_segment_field "$seg" '머지 커밋')
  [ -n "$m" ] || { gate_apply_refuse 1 "세그먼트 ${seg} 의 머지됨 행에 머지 커밋 이 없습니다"; return $?; }

  # A segment that owes no apply ends here: no row, no worktree, and 0.
  if [ "$(gate_segment_apply_state "$alias" "$seg")" = "없음" ]; then
    GATE_APPLY_NOT_OWED=1
    return 0
  fi

  # 2 — the resolved policy reviews before it merges. Resolved the way
  # `gate_resolve_review_policy` resolves it: the row, and absence is strict.
  pol=$(gate_segment_field "$seg" '리뷰 정책')
  [ -n "$pol" ] || pol='선리뷰후머지'
  [ "$pol" = "선리뷰후머지" ] || { gate_apply_refuse 2 "세그먼트 ${seg} 의 리뷰 정책이 선리뷰후머지 가 아닙니다 (${pol})"; return $?; }

  # 3 — the last cycle row passed, its report is a finished one, and it came
  # before the merge was recorded.
  crow=$(gate_segment_last_cycle_row "$seg")
  [ -n "$crow" ] || { gate_apply_refuse 3 "세그먼트 ${seg} 의 cycle 행이 없습니다"; return $?; }
  p0=$(gate_row_field "$crow" 'P0'); p1=$(gate_row_field "$crow" 'P1')
  # A carried-over cycle passes as a dismissed one does, but only with P0=0:
  # a carry moves open P1 findings to issues and never waves a P0 through.
  if { [ "${p0:-}" != "0" ] || [ "${p1:-}" != "0" ]; } \
     && ! gate_cycle_dismissed "$seg" "$(gate_row_field "$crow" '사이클')" "$(gate_row_field "$crow" '리뷰 HEAD')" \
     && ! { [ "${p0:-}" = "0" ] \
            && gate_cycle_carried "$seg" "$(gate_row_field "$crow" '사이클')" "$(gate_row_field "$crow" '리뷰 HEAD')"; }; then
    gate_apply_refuse 3 "세그먼트 ${seg} 의 마지막 cycle 행이 P0=${p0:-?} P1=${p1:-?} 입니다"; return $?
  fi
  rep=$(gate_row_field "$crow" '리포트 경로')
  rep_abs=$(gate_report_abs "$rep")
  { [ -n "$rep_abs" ] && [ -f "$rep_abs" ]; } \
    || { gate_apply_refuse 3 "마지막 cycle 행의 리포트가 없습니다: ${rep:-(없음)}"; return $?; }
  grep -qE '^[-*[:space:]]*\*\*발견 요약\*\*' "$rep_abs" \
    || { gate_apply_refuse 3 "리포트에 발견 요약 이 없습니다: ${rep}"; return $?; }
  cline=$(gate_apply_line_of 'cycle' '세그먼트' "$seg")
  sline=$(gate_apply_line_of 'segment' 'id' "$seg")
  { [ -n "$cline" ] && [ -n "$sline" ] && [ "$cline" -lt "$sline" ]; } \
    || { gate_apply_refuse 3 "마지막 cycle 행이 원장 순서로 머지됨 행보다 앞서지 않습니다"; return $?; }

  # 4 — M is a two-parent merge of the reviewed head, or of the honest release
  # metadata renumbering merge of it against the base the segment's last
  # `베이스 판정` row named — the proof the merge act and the merge check use —
  # and the local remote-tracking base already holds it.
  rh=$(gate_row_field "$crow" '리뷰 HEAD')
  root=$(alias_root "$alias" 2>/dev/null || true)
  [ -n "$root" ] && [ -d "$root" ] || { gate_apply_refuse 4 "대상 ${alias} 의 루트를 찾지 못했습니다"; return $?; }
  base=$(target_field "$alias" '베이스 브랜치' 2>/dev/null || true)
  [ -n "$base" ] || { gate_apply_refuse 4 "대상 ${alias} 에 베이스 브랜치 가 없습니다"; return $?; }
  ( cd "$root" && git cat-file -e "${m}^{commit}" ) 2>/dev/null \
    || { gate_apply_refuse 4 "머지 커밋 ${m} 이 로컬에 없습니다 — 게이트는 fetch 하지 않습니다"; return $?; }
  parents=$( cd "$root" && git rev-list --parents -n 1 "$m" 2>/dev/null | awk '{print NF - 1}')
  [ "$parents" = "2" ] || { gate_apply_refuse 4 "머지 커밋 ${m} 의 부모가 둘이 아닙니다 (${parents:-?}) — squash·rebase 착지는 적용하지 않습니다"; return $?; }
  m2=$( cd "$root" && git rev-parse --verify -q "${m}^2" 2>/dev/null || true)
  rhfull=$( cd "$root" && git rev-parse --verify -q "${rh}^{commit}" 2>/dev/null || true)
  if ! { [ -n "$m2" ] && [ "$m2" = "$rhfull" ]; }; then
    t=$(gate_row_field "$(gate_base_last_row "$seg")" '베이스')
    why='베이스 판정 행 없음'
    if [ -n "$m2" ] && [ -n "$rhfull" ] && [ -n "$t" ]; then
      if gate_meta_resolved "$root" "$rhfull" "$m2" "$t"; then
        why=""
      else
        why=${GATE_META_WHY:-no answer}
      fi
    fi
    [ -z "$why" ] \
      || { gate_apply_refuse 4 "머지 커밋의 둘째 부모(${m2:-?})가 cycle 행의 리뷰 HEAD(${rh:-?})와 같지 않습니다 — 리뷰 HEAD 의 릴리스 메타 재번호 머지로도 증명되지 않습니다 (${why})"; return $?; }
  fi
  ( cd "$root" && git merge-base --is-ancestor "$m" "refs/remotes/origin/$base" ) 2>/dev/null \
    || { gate_apply_refuse 4 "머지 커밋 ${m} 이 로컬 origin/${base} 의 조상이 아닙니다 — 게이트는 fetch 하지 않습니다"; return $?; }

  # 5 — a command, then who runs it, then the probe and the rung.
  GATE_APPLY_COMMAND=$(gate_apply_value "$seg" '적용 명령')
  [ -n "$GATE_APPLY_COMMAND" ] || { gate_apply_refuse 5 "세그먼트 ${seg} 에 적용 명령 이 없습니다"; return $?; }
  actor=$(gate_apply_value "$seg" '적용 주체')
  if [ "$actor" = "사람" ]; then
    # A HANDOVER, NOT A REFUSAL. The command travels to the morning as a string
    # and nothing runs, which is what the driver's S9 does for the same actor.
    GATE_APPLY_HANDOVER=1
    [ "$verb" = "act" ] || return 0
    gate_append '적용 인계' "세그먼트=$seg" "대상=$alias" "적용 주체=사람" \
      "머지 커밋=$m" "적용 명령=$(gate_row_safe "$GATE_APPLY_COMMAND" 400)" "관측=$(now_iso)"
    log "적용 인계 — $seg (적용 주체가 사람)"
    return 0
  fi
  [ "$actor" = "파이프라인" ] || { gate_apply_refuse 5 "세그먼트 ${seg} 의 적용 주체가 파이프라인 이 아닙니다 (${actor:-(없음)})"; return $?; }
  GATE_APPLY_PROBE=$(apply_probe_cmd "$seg" 2>/dev/null || true)
  [ -n "$GATE_APPLY_PROBE" ] || { gate_apply_refuse 5 "세그먼트 ${seg} 에 적용 프로브 가 없습니다"; return $?; }
  cut=$(gate_segment_cutpoint "$alias" "$seg")
  [ "$cut" = "배포" ] || { gate_apply_refuse 5 "세그먼트 ${seg} 의 절단점이 배포 가 아닙니다 (${cut:-(없음)})"; return $?; }
  # 5's refusals of a missing command and of a cutpoint other than `배포` are
  # no longer reached past the owed check above; they stay as the last net
  # should the two readings ever disagree.
  GATE_APPLY_MERGE="$m"; GATE_APPLY_SUBJECT="$rhfull"
  return 0
}

gate_apply_segment_row() {
  # gate_apply_segment_row <alias> <segment> <키=값>... — a segment row written by
  # the apply arm: through the segment arm, with the marker that lets it write
  # `적용 준비` and `완료`, and with the plan row's `선행` carried again because
  # the arm refuses a row that drops it.
  local alias="$1" seg="$2" deps rc=0; shift 2
  deps=$(gate_segment_field "$seg" '선행')
  GATE_APPLY_ARM=1
  gate_record_row 'segment' "$seg" "$alias" "$@" ${deps:+"선행=$deps"} || rc=$?
  GATE_APPLY_ARM=""
  return "$rc"
}

gate_perform_apply() {
  # gate_perform_apply <alias> <segment> — the act itself, after the catalog
  # passed. Zero retries: a second apply after an unknown outcome is a second
  # apply, and the act that follows is refused at precondition 1 anyway because
  # the last row is no longer `머지됨`.
  local alias="$1" seg="$2" root wt m cmd probe pre rc=0 post disp out err codes nu ne map
  m="$GATE_APPLY_MERGE"; cmd="$GATE_APPLY_COMMAND"; probe="$GATE_APPLY_PROBE"
  # The exit-code mapping is read once, from the manifest alone and against the
  # probe this act runs, and both verdicts below take it — the driver's S9 does
  # the same, so the two cannot read one code two ways.
  # A row frozen against another probe's bytes is refused here, never read as
  # 0/2: the default would flip the verdict of a mapping that put 0 and 2 the
  # other way round.
  local crc=0
  codes=$(apply_probe_codes "$probe") || crc=$?
  case "$crc" in
    0) ;;
    2) warn "적용 프로브 코드 행의 프로브 sha256(${codes% *})이 실행할 적용 프로브의 sha256(${codes#* })과 맞지 않습니다 — 적용 워크트리도 원장 행도 남기지 않았습니다"
       return "$GATE_EXIT_RULE" ;;
    *) warn "적용 프로브 코드 행을 읽을 수 없습니다 — 적용 워크트리도 원장 행도 남기지 않았습니다"
       return "$GATE_EXIT_RULE" ;;
  esac
  nu="${codes% *}"; ne="${codes#* }"; map="대응 불필요=${nu}·필요=${ne}"
  root=$(alias_root "$alias") || return 1
  wt="$(dirname "$root")/$(basename "$root")${WORKTREE_INFIX}${RUN_ID}-${seg}-apply"
  if [ -e "$wt" ]; then
    warn "적용 워크트리 자리가 이미 있습니다: $wt — 남은 적용의 흔적일 수 있어 건드리지 않습니다"
    return "$GATE_EXIT_RULE"
  fi
  ( cd "$root" && git worktree add --detach "$wt" "$m" >/dev/null 2>&1 ) || {
    warn "적용 워크트리를 머지 커밋 ${m} 에 고정하지 못했습니다: $wt"
    return "$GATE_EXIT_RULE"
  }
  gate_apply_segment_row "$alias" "$seg" "상태=적용 준비" "워크트리=$wt" "고정 커밋=$m" \
    "적용 명령=$(gate_row_safe "$cmd" 400)" || {
    rc=$?
    ( cd "$root" && git worktree remove --force "$wt" >/dev/null 2>&1; git worktree prune >/dev/null 2>&1 ) || true
    return "$rc"
  }

  apply_probe "$wt" "$probe"; pre=$?
  disp=$(apply_disposition "$nu" "$ne" "$pre")
  case "$disp" in
    건너뜀)
      gate_apply_segment_row "$alias" "$seg" "상태=완료" "워크트리=$wt" "고정 커밋=$m" "적용=건너뜀" || return $?
      ( cd "$root" && git worktree remove --force "$wt" >/dev/null 2>&1; git worktree prune >/dev/null 2>&1 ) || true
      log "적용 건너뜀 — $seg (사전 프로브 $pre, $map)"
      return 0 ;;
    '사전 실패')
      # Refused before anything is touched, the way the driver refuses: the
      # apply whose need could not be established has no evidence behind it.
      gate_apply_segment_row "$alias" "$seg" "상태=park" "워크트리=$wt" "고정 커밋=$m" "적용=사전 실패" || return $?
      gate_append 'blocked' "대상=$seg" "스코프=act" "원인=막힘" "사유=적용 사전 실패(exit $pre)" \
        "관측=사전 프로브 실패(exit $pre, $map) — 아무것도 건드리기 전에 거부했다" \
        "재개 명령=$(gate_row_safe "$cmd" 240)"
      ( cd "$root" && git worktree remove --force "$wt" >/dev/null 2>&1; git worktree prune >/dev/null 2>&1 ) || true
      warn "적용 사전 실패 — 사전 프로브 exit $pre ($map), 명령을 실행하지 않았습니다"
      return "$GATE_EXIT_PARK" ;;
  esac

  out="${RUN_DIR:-${TMPDIR:-/tmp}}/log/apply-$seg.out"; err="${out%.out}.err"
  mkdir -p "$(dirname "$out")" 2>/dev/null || true
  log "$seg: 적용 실행 (재시도 없음)"
  ( cd "$wt" && sh -c "$cmd" ) >"$out" 2>"$err" || rc=$?
  apply_probe "$wt" "$probe"; post=$?
  disp=$(apply_disposition "$nu" "$ne" "$pre" "$rc" "$post")
  if [ "$disp" = "수렴" ]; then
    gate_apply_segment_row "$alias" "$seg" "상태=완료" "워크트리=$wt" "고정 커밋=$m" "적용=수렴" || return $?
    ( cd "$root" && git worktree remove --force "$wt" >/dev/null 2>&1; git worktree prune >/dev/null 2>&1 ) || true
    log "적용 수렴 — $seg (사전 $pre → 사후 $post, $map)"
    return 0
  fi
  # 적용 불명. The worktree stays: it is the only reproduction of a state that
  # may be half-applied, which is what a person needs in the morning.
  gate_apply_segment_row "$alias" "$seg" "상태=park" "워크트리=$wt" "고정 커밋=$m" "적용=불명" || return $?
  gate_append 'blocked' "대상=-" "스코프=run" "원인=막힘" "사유=적용 불명 $seg" \
    "관측=사전 프로브 exit $pre · 명령 exit $rc · 사후 프로브 exit $post ($map) — 워크트리 보존: $wt" \
    "재개 명령=$(gate_row_safe "$cmd" 240)"
  warn "적용 불명 — 명령 exit $rc, 사후 프로브 exit $post ($map). 워크트리를 남겼습니다: $wt"
  return "$GATE_EXIT_PARK"
}

gate_park_record() {
  # gate_park_record <칸> <원인> <관측> <argv...> — the `blocked` row of a reach
  # park and its repair line. It reads `alias`, `segment`, `graded` and
  # `rationale` from `gate_verb_act`, its only caller's scope.
  #
  # TWO CALLERS, ONE ROW. The dispatch parks before the act; the rerun performer
  # parks after its POST, past the dispatch's seat, and the row a person reads in
  # the morning must not depend on which of the two wrote it. The digest is the
  # argv's either way, so the same act at the same head meets the dispatch's
  # "already parked" next time.
  local cell="$1" cause="$2" obs="$3"; shift 3
  local _ad; _ad=$(printf '%s' "$*" | shasum -a 256 | cut -d' ' -f1)
  # THE THREE FREE-TEXT FIELDS ARE SIZED FROM WHAT IS LEFT, not from three
  # constants. A row that exceeds the cap is not a truncated row — `gate_append`
  # refuses it and the process ends, so the park verdict this block exists to
  # record would vanish exactly when it is most needed. The fixed part is
  # measured here rather than assumed: an alias, a segment id and a stage id
  # are caller-shaped and nothing bounds their length.
  local _seg55="${CC_PIPELINE_SEGMENT:-$segment}" _stg="${CC_PIPELINE_STAGE_ID:--}"
  local _fixed _free _rb _jb=0 _ob _cb _jl='' _jfix='' _jx=()
  # A JUDGMENT'S VERDICT RIDES IN FIELDS OF ITS OWN, never inside `근거=`: that
  # field is the stage's rationale, and a verdict folded into it could not be
  # told apart from what the stage claimed. Absent a judgment the row is the
  # row it always was.
  if [ "${GATE_PREAUTH_JUDGE:--}" != "-" ]; then
    _jl=$(gate_preauth_judge_label "$GATE_PREAUTH_JUDGE")
    _jfix="사전 인가 판단=$_jl | 판단 이유= | "
  fi
  _fixed=$(printf -- '- `blocked` | 교대=999 | 대상=%s | 스코프=act | 원인=막힘 | 사유=도달 park | 도달 판정=%s | 세그먼트=%s | 스테이지=%s | 축2=%s | 도달=%s | 행위 다이제스트=%s | %s근거= | 관측= | 재개 명령= | prev=%064d\n' \
            "$alias" "$cell" "$_seg55" "$_stg" "$graded" "${GATE_REACH:--}" "$_ad" "$_jfix" 0 \
          | wc -c | tr -d ' ')
  _free=$(( GATE_ROW_MAX - _fixed - 8 ))
  [ "$_free" -lt 0 ] && _free=0
  # The rationale first — it is the one a person reads in the morning — then the
  # judgment's reason, then the act excerpt, then the re-invocation line, each
  # capped at its own ceiling.
  _rb=$(( _free / 2 )); [ "$_rb" -gt 160 ] && _rb=160
  _free=$(( _free - _rb ))
  if [ -n "$_jl" ]; then
    _jb=$(( _free / 2 )); [ "$_jb" -gt 400 ] && _jb=400
    _free=$(( _free - _jb ))
    _jx=("사전 인가 판단=$_jl" "판단 이유=$(gate_row_safe "$(gate_preauth_judge_reason "$GATE_PREAUTH_JUDGE")" "$_jb")")
  fi
  _ob=$(( _free / 3 )); [ "$_ob" -gt 60 ] && _ob=60
  _free=$(( _free - _ob ))
  _cb="$_free"; [ "$_cb" -gt 240 ] && _cb=240
  gate_append 'blocked' "대상=$alias" "스코프=act" "원인=막힘" "사유=도달 park" \
    "도달 판정=$cell" "세그먼트=$_seg55" \
    "스테이지=$_stg" "축2=$graded" "도달=${GATE_REACH:--}" \
    "행위 다이제스트=$_ad" ${_jx[@]+"${_jx[@]}"} "근거=$(gate_row_safe "$rationale" "$_rb")" \
    "관측=$(gate_row_safe "$obs" "$_ob")" "재개 명령=$(gate_row_safe "$*" "$_cb")"
  gate_park_repair_line "$cell" "$cause"
}

# ---------------------------------------------------------------------------
# The rerun act — `act --kind ci-rerun -- 재실행 <head sha>`.
#
# ONE ACT, THREE SEATS. The spelling and the routed-run/tip refusals stand at the
# preconditions, ahead of the drain, so they read neither the ledger nor GitHub;
# the lock, `다음` and the eligibility of every failing run stand just ahead of
# the merge check, after the drain and the rule loop; the POST and its
# confirmation are the performer's. The lock taken at the second seat is held to
# the end of the gate process, so everything from `다음` to the closing row runs
# under it.
#
# EVERY CHECK ERRS TOWARDS A PARK. A rerun that cannot be proved harmless — it
# may start a deploy, or the run cannot be proved this pull request's own — is
# left to a person, and all of the failing runs are rerun or none is.
# ---------------------------------------------------------------------------
GATE_CI_RERUN_CONFIRM_TRIES=10
GATE_CI_RERUN_CONFIRM_SLEEP=3

gate_ci_rerun_preconditions() {
  # gate_ci_rerun_preconditions <segment> <sha> — the refusals that need neither
  # the ledger nor GitHub: a run the routing shift does not drive, or an argv
  # sha that is not the worktree's tip. Passing sets the marker the rule branch
  # opens on, exported because the rule files run as processes of their own.
  local seg="$1" sha="$2" tip
  if ! run_routed; then
    warn "the rerun act runs only on a routed run — this run has no routing record"
    return "$GATE_EXIT_RULE"
  fi
  tip=$(gate_segment_tip "$seg") || tip=""
  if [ -z "$tip" ] || [ "$tip" != "$sha" ]; then
    warn "the rerun names head $sha, but the segment worktree's tip is ${tip:-(unresolved)} — read 다음 again"
    return "$GATE_EXIT_RULE"
  fi
  GATE_CI_RERUN_PRE=1
  export GATE_CI_RERUN_PRE
}

gate_ci_rerun_lock_release() {
  [ -n "${GATE_CI_RERUN_LOCK:-}" ] || return 0
  rm -rf "$GATE_CI_RERUN_LOCK" 2>/dev/null || true
  GATE_CI_RERUN_LOCK=""
}

gate_ci_rerun_lock() {
  # gate_ci_rerun_lock <segment> — the segment's rerun mutex, or 1 at once.
  #
  # IT DOES NOT WAIT AND IS NEVER TAKEN BY AGE. A second act on the same head
  # while one is live is refused, not queued, and the lock is taken over only
  # when its owner's pid is gone: the POST and the confirmation reads can last
  # longer than any age bound would, and taking a live lock would send a second
  # rerun to the same head.
  local dir="$RUN_DIR/ci-rerun.$1.lock" rc=0
  gate_ci_seg_lock_take "$dir" || rc=$?
  [ "$rc" = "1" ] && return 1
  # Released by `gate_on_exit`: a shell keeps one EXIT trap, and the verb's
  # trap is already that one.
  [ "$rc" = "2" ] || GATE_CI_RERUN_LOCK="$dir"
  return 0
}

gate_ci_seg_lock_take() {
  # gate_ci_seg_lock_take <dir> — the per-segment mutex both CI acts use: 0 when
  # taken and held, 1 when a live owner holds it, 2 when it was taken for a
  # forecast and already given back.
  local dir="$1" owner opid
  if ! mkdir "$dir" 2>/dev/null; then
    owner=$(cat "$dir/owner" 2>/dev/null || true)
    opid=$(printf '%s' "$owner" | sed -n 's/^\([0-9][0-9]*\)[[:space:]].*$/\1/p')
    if [ -n "$opid" ] && ! cc_pid_exists "$opid"; then
      rm -rf "$dir" 2>/dev/null || true
      mkdir "$dir" 2>/dev/null || return 1
    else
      return 1
    fi
  fi
  # A FORECAST ONLY ASKS. `plan` installs no EXIT trap, and a lock it kept would
  # refuse the act it forecasts.
  if [ "${verb:-}" = "plan" ]; then
    rm -rf "$dir" 2>/dev/null || true
    return 2
  fi
  # `BASHPID`, not `$$`: in a subshell `$$` is the parent's pid, which outlives
  # the gate that took the lock.
  printf '%s %s\n' "${BASHPID:-$$}" "$(date -u +%s)" > "$dir/owner" 2>/dev/null || true
  return 0
}

gate_ci_rerun_gh() {
  # gate_ci_rerun_gh <args...> — `gh` under the read-scoped runner, with the
  # repository named on the command line alone. The two variables are unset in
  # a subshell rather than through `env -u`: `env` would look `gh` up on PATH,
  # where run.sh has put the system directories first, and the program it found
  # would not be the one every other act of the gate runs.
  ( unset GH_REPO GH_HOST; gate_run_readonly gh "$@" )
}

gate_ci_rerun_on_hit() {
  # gate_ci_rerun_on_hit <file> — 0 when the workflow file's top-level `on` key
  # names one of the four events that fire from the base branch's files
  # (workflow_run, check_suite, check_run, status), or cannot be read. The key
  # is matched quoted, and as YAML 1.1's `true`; a block mapping is read by its
  # direct keys, a scalar, flow list or flow mapping by its words.
  # The awk exits 0 for "park" and 1 for "clear", so an awk that fails to run
  # at all reads as neither and the caller's `||` parks on it too.
  LC_ALL=C awk -v q="'" '
    function hit(s) { return s ~ /(^|[^A-Za-z0-9_])(workflow_run|check_suite|check_run|status)([^A-Za-z0-9_]|$)/ }
    function unq(s) { gsub(/"/, "", s); gsub(q, "", s); return s }
    !found {
      k = $0; sub(/[ \t]*:.*$/, "", k)
      if ($0 ~ /^[^ \t#][^:]*:/ && (k == "on" || k == "\"on\"" || k == q "on" q || k == "true")) {
        found = 1; v = $0; sub(/^[^:]*:[ \t]*/, "", v)
        if (v ~ /^#/) v = ""; sub(/[ \t]+#.*$/, "", v)
        if (v != "") { scalar = 1; exit }
        inblk = 1
      }
      next
    }
    inblk {
      if ($0 ~ /^[ \t]*(#.*)?$/) next
      if ($0 !~ /^[ \t]/) { inblk = 0; next }
      ind = match($0, /[^ \t]/) - 1
      if (minind == "" || ind < minind) minind = ind
      line[++n] = $0; lind[n] = ind
    }
    END {
      if (!found) exit 0
      if (scalar) {
        if (hit(v)) exit 0
        # A plain word, a flow list or a flow mapping is read by its words;
        # anything else is a form this reader does not know.
        if (v ~ /^[A-Za-z_]/ || v ~ /^\[.*\]$/ || v ~ /^\{.*\}$/) exit 1
        exit 0
      }
      if (n == 0) exit 0
      for (i = 1; i <= n; i++) {
        if (lind[i] != minind) continue
        k = line[i]; sub(/^[ \t]*/, "", k); sub(/^-[ \t]*/, "", k)
        sub(/[ \t]+#.*$/, "", k); sub(/[ \t]*:.*$/, "", k)
        if (hit(unq(k))) exit 0
      }
      exit 1
    }' "$1"
}

gate_ci_rerun_x5_hit() {
  # gate_ci_rerun_x5_hit <file> — 0 when the run's own workflow file carries an
  # `environment` key in any spelling or names a file under .github/workflows/.
  # Read as text, never as YAML: a comment or a paths filter that matches counts
  # towards the park, which is the direction every check here may err in.
  LC_ALL=C grep -Eq '(^|[^A-Za-z0-9_])environment["'"'"']?[[:space:]]*:|\.github/workflows/' "$1"
}

gate_ci_rerun_checks_tsv() {
  # gate_ci_rerun_checks_tsv <json> — `<bucket>\t<name>\t<link>` per check of a
  # `gh pr checks --json` answer, or 1 when the answer is not a list.
  printf '%s' "$1" | jq -r 'if type == "array" then .[] | [(.bucket // ""), (.name // ""), (.link // "")] | join("\t") else error("not a list") end' 2>/dev/null
}

gate_ci_rerun_run_tsv() {
  # gate_ci_rerun_run_tsv <slug> <run id> — one tab-separated line of the run's
  # fields the eligibility reads, or 1 when the read fails:
  #   status event head_sha head_branch repository head_repository name path
  #   workflow_id run_attempt
  local out
  out=$(gate_ci_rerun_gh api "repos/$1/actions/runs/$2" 2>/dev/null) || return 1
  printf '%s' "$out" | jq -er '[(.status // ""), (.event // ""), (.head_sha // ""), (.head_branch // ""),
      (.repository.full_name // ""), (.head_repository.full_name // ""), (.name // ""),
      (.path // ""), (.workflow_id // "" | tostring), (.run_attempt // "" | tostring)] | join("\t")' 2>/dev/null
}

gate_check_ci_rerun() {
  # gate_check_ci_rerun <kind> — the lock, `다음` and the eligibility of every
  # failing run, for the rerun act and nothing else. Refusal exits 3 with no
  # row; a park sets the park cell for the dispatch below it to write; an
  # eligible set leaves `GATE_CI_RERUN_VERDICT=eligible` and the runs for the
  # performer.
  [ "$1" = "ci-rerun" ] || return 0
  local seg="$segment" al="$alias" wt h nx rd a slug br prs n pnum phead pref
  local checks fails pend runs="" r rj st wf_name wf_path wf_id ev hsha hbr rfull hfull
  local basebr obs="" unk="" bad="" tmpd ids id kind val f bn rc _b name link
  wt=$(gate_segment_worktree "$seg")
  h=$(gate_worktree_tip "$wt") || { warn "the segment worktree's tip does not resolve"; exit "$GATE_EXIT_RULE"; }
  if ! gate_ci_rerun_lock "$seg"; then
    warn "another rerun act of segment $seg holds its lock — not queued, read 다음 again"
    exit "$GATE_EXIT_RULE"
  fi
  # `다음` AGAIN, from the gate's own ledger after this act's drain — never the
  # value the router read. A rerun while the segment's review still runs is
  # taken on the early rerun predicate instead (`gate_ci_early`): `다음` stays
  # the table's until that review ends, so it cannot say `CI 재실행` yet.
  nx=$(gate_segment_review_next "$seg")
  if [ "$nx" != "CI 재실행" ] && ! gate_ci_early "$seg"; then
    warn "다음 of segment $seg is '$nx', not 'CI 재실행', and no early rerun stands on it — the rerun act is refused"
    exit "$GATE_EXIT_RULE"
  fi
  # ITS OWN ROUNDS ONLY: a label round open or failed on the same head is the
  # label act's to park, never this act's.
  rd=$(cc_ci_round "$LEDGER" "$seg" "$h")
  a=$(cc_ci_round_get "$rd" ra)
  if [ "$a" = "열림" ] || [ "$a" = "실패" ]; then
    GATE_PARK_CELL='재실행요청실패'
    if [ "$a" = "열림" ]; then GATE_PARK_CAUSE='open'; else GATE_PARK_CAUSE='closed'; fi
    GATE_PARK_OBS="회차:$a"
    export GATE_PARK_CELL GATE_PARK_CAUSE GATE_PARK_OBS
    return 0
  fi
  slug=$(target_field "$al" '원격 슬러그' 2>/dev/null || true)
  br=$( { cd "$wt" 2>/dev/null && git branch --show-current 2>/dev/null; } || true)
  if [ -z "$slug" ] || [ -z "$br" ]; then
    gate_ci_rerun_park '재실행대상미상' "PR 결속 불가 (슬러그 ${slug:-없음}, 브랜치 ${br:-없음})"; return 0
  fi
  # THE PULL REQUEST IS THE BRANCH'S ONE OPEN PR AT THIS HEAD.
  if ! prs=$(gate_ci_rerun_gh pr list -R "$slug" --head "$br" --state open --json number,headRefOid,headRefName 2>/dev/null) \
     || ! prs=$(printf '%s' "$prs" | jq -r '.[] | [(.number|tostring), .headRefOid, .headRefName] | join(" ")' 2>/dev/null); then
    gate_ci_rerun_park '재실행대상미상' "PR 조회 실패 ($br)"; return 0
  fi
  n=$(printf '%s\n' "$prs" | grep -c . || true)
  read -r pnum phead pref <<EOF
$prs
EOF
  if [ "$n" != "1" ] || [ "$phead" != "$h" ]; then
    warn "the branch $br has $n open pull request(s), head ${phead:-(none)} against tip $h — the head moved; read 다음 again"
    exit "$GATE_EXIT_RULE"
  fi
  # THE FAILING SET, FROM THE CHECKS SCREEN AS IT IS NOW.
  # `gh pr checks` exits 8 while any check is pending, and its output is still
  # the list, so the status is not the verdict — the parse is.
  local raw
  raw=$(gate_ci_rerun_gh pr checks "$pnum" -R "$slug" --json name,bucket,link,workflow,event 2>/dev/null || true)
  if ! checks=$(gate_ci_rerun_checks_tsv "$raw"); then
    gate_ci_rerun_park '재실행대상미상' "체크 조회 실패 (PR $pnum)"; return 0
  fi
  pend=$(printf '%s\n' "$checks" | awk -F'\t' '$1 == "pending" { n++ } END { print n + 0 }')
  if [ "$pend" -gt 0 ]; then
    warn "$pend check(s) of PR $pnum are still pending — the rerun waits for the set to settle"
    exit "$GATE_EXIT_RULE"
  fi
  fails=$(printf '%s\n' "$checks" | awk -F'\t' '$1 == "fail"')
  basebr=$(gate_base_remote_tip "$al" "$wt" 2>/dev/null) || basebr=""
  if [ -z "$basebr" ] || ! ( cd "$wt" && git cat-file -e "$basebr^{commit}" ) 2>/dev/null; then
    warn "the base branch's tip ${basebr:-(unknown)} is not a local object — fetch the base first"
    exit "$GATE_EXIT_RULE"
  fi
  if [ -z "$fails" ]; then
    warn "PR $pnum shows no failing check now — nothing to rerun"
    exit "$GATE_EXIT_RULE"
  fi
  # X1 on each link, and the distinct run ids. A failing check with no details
  # link (a commit status posted without a target URL) cannot be judged, so it
  # is unknown like any other non-Actions link — skipping it would rerun the
  # rest, or leave nothing to rerun and no park.
  while IFS="$(printf '\t')" read -r _b name link; do
    [ -n "$_b$name$link" ] || continue
    case "$link" in
      "https://github.com/$slug/actions/runs/"*)
        r=${link#"https://github.com/$slug/actions/runs/"}; r=${r%%/*}
        case "$r" in ''|*[!0-9]*) unk="${unk:-$name:-}" ;; *)
          case " $runs " in *" $r "*) ;; *) runs="${runs:+$runs }$r" ;; esac
          [ -n "$obs" ] || obs="$name:$r" ;;
        esac ;;
      *) unk="${unk:-$name:-}" ;;
    esac
  done <<EOF
$fails
EOF
  if [ -n "$unk" ]; then gate_ci_rerun_park '재실행대상미상' "$unk"; return 0; fi
  [ -n "$runs" ] || { warn "no Actions run behind PR $pnum's failing checks"; exit "$GATE_EXIT_RULE"; }
  # EVERY RUN IS READ BEFORE ANY IS JUDGED: a read failure parks ahead of a run
  # still in progress, and that ahead of eligibility.
  local readfail="" running="" line atts="" wfs="" x
  local -a rl=()
  for r in $runs; do
    if line=$(gate_ci_rerun_run_tsv "$slug" "$r"); then
      rl+=("${r}	${line}")
    else
      readfail="${readfail:-$r}"
    fi
  done
  if [ -n "$readfail" ]; then gate_ci_rerun_park '재실행대상미상' "실행 읽기 실패:$readfail"; return 0; fi
  for line in "${rl[@]}"; do
    [ "$(printf '%s' "$line" | cut -f2)" = "completed" ] || running="${running:-$(printf '%s' "$line" | cut -f1)}"
  done
  if [ -n "$running" ]; then
    warn "run $running of PR $pnum has not completed — the rerun waits for it"
    exit "$GATE_EXIT_RULE"
  fi
  ids=$(target_field "$al" '배포트리거 식별자' 2>/dev/null || true)
  tmpd=$(mktemp -d "${TMPDIR:-/tmp}/gate-ci-rerun.XXXXXX") || exit "$GATE_EXIT_RULE"
  for line in "${rl[@]}"; do
    # `cut`, never `read`: a tab is whitespace to `read`, so an empty field
    # would shift every field after it.
    r=$(printf '%s' "$line" | cut -f1);       ev=$(printf '%s' "$line" | cut -f3)
    hsha=$(printf '%s' "$line" | cut -f4);    hbr=$(printf '%s' "$line" | cut -f5)
    rfull=$(printf '%s' "$line" | cut -f6);   hfull=$(printf '%s' "$line" | cut -f7)
    wf_name=$(printf '%s' "$line" | cut -f8); wf_path=$(printf '%s' "$line" | cut -f9)
    wf_id=$(printf '%s' "$line" | cut -f10);  x=$(printf '%s' "$line" | cut -f11)
    # X2 — this pull request's own run, at this head, from this repository.
    if [ "$ev" != "pull_request" ] || [ "$hsha" != "$h" ] || [ "$rfull" != "$slug" ] \
       || [ "$hfull" != "$slug" ] || [ "$hbr" != "$pref" ]; then
      rm -rf "$tmpd"; gate_ci_rerun_park '재실행대상미상' "실행:$r event=${ev:-?}"; return 0
    fi
    wf_path=${wf_path%%@*}; bn=${wf_path##*/}
    # X3 — every kind of identifier on its own field. A `workflow:` value
    # matches the run's name, its file's basename with or without the
    # extension, and the workflow id.
    while IFS= read -r id; do
      kind="${id%%:*}"; val="${id#*:}"
      [ -n "$id" ] && [ -n "$val" ] || continue
      case "$kind" in
        workflow)
          case "$val" in
            "$wf_name"|"$bn"|"${bn%.*}"|"${bn%.*}.yml"|"${bn%.*}.yaml"|"$wf_id") bad="workflow:$val" ;;
          esac ;;
        branch) [ "$val" = "$hbr" ] && bad="branch:$val" ;;
        argv)
          case "gh api -X POST -i repos/$slug/actions/runs/$r/rerun-failed-jobs" in *"$val"*) bad="argv:$val" ;; esac ;;
      esac
      [ -z "$bad" ] || break
    done <<EOF
$(printf '%s' "$ids" | tr ',' '\n' | sed 's/^[[:space:]]*//; s/[[:space:]]*$//')
EOF
    if [ -n "$bad" ]; then rm -rf "$tmpd"; gate_ci_rerun_park '재실행배포트리거' "$bad:$r"; return 0; fi
    # X5 — the run's own file at this head. Only a clean "no match" clears it.
    rc=1
    if [ -n "$wf_path" ] && ( cd "$wt" && git show "$h:$wf_path" ) > "$tmpd/wf.$r" 2>/dev/null; then
      gate_ci_rerun_x5_hit "$tmpd/wf.$r" && rc=0 || rc=$?
      [ "$rc" = "1" ] || rc=0
    else
      rc=0
    fi
    if [ "$rc" = "0" ]; then rm -rf "$tmpd"; gate_ci_rerun_park '재실행배포트리거' "${bn:-워크플로}:$r"; return 0; fi
    atts="${atts:+$atts }$r:$x"
    wfs="${wfs:+$wfs,}${wf_name:--}"
  done
  # X4 — the base branch's workflow files, once for the whole set. None found
  # is not "none declared": the tree could not be read.
  local wfl
  wfl=$( { cd "$wt" && git ls-tree -r --name-only "$basebr" -- .github/workflows; } 2>/dev/null) || wfl=""
  while IFS= read -r f; do
    case "$f" in *.yml|*.yaml) ;; *) continue ;; esac
    rc=0
    if ( cd "$wt" && git show "$basebr:$f" ) > "$tmpd/base.wf" 2>/dev/null; then
      gate_ci_rerun_on_hit "$tmpd/base.wf" && rc=0 || rc=$?
    fi
    if [ "$rc" != "1" ]; then rm -rf "$tmpd"; gate_ci_rerun_park '재실행배포트리거' "기본 브랜치 ${f##*/}"; return 0; fi
  done <<EOF
$wfl
EOF
  rm -rf "$tmpd"
  GATE_CI_RERUN_VERDICT=eligible
  GATE_CI_RERUN_RUNS="$runs"
  GATE_CI_RERUN_PR="$pnum"; GATE_CI_RERUN_SLUG="$slug"; GATE_CI_RERUN_HEAD="$h"
  GATE_CI_RERUN_BASE="$basebr"; GATE_CI_RERUN_FAILS="$fails"; GATE_CI_RERUN_MAX=$(cc_ci_round_get "$rd" max)
  GATE_CI_RERUN_OBS="$obs"; GATE_CI_RERUN_ATTS="$atts"; GATE_CI_RERUN_WFS="$wfs"
  return 0
}

gate_ci_rerun_park() {
  # gate_ci_rerun_park <칸> <관측> — set the park cell for the dispatch.
  GATE_PARK_CELL="$1"; GATE_PARK_CAUSE='-'; GATE_PARK_OBS="$2"
  GATE_CI_RERUN_VERDICT=""
  export GATE_PARK_CELL GATE_PARK_CAUSE GATE_PARK_OBS
}

gate_ci_rerun_base_evidence() {
  # gate_ci_rerun_base_evidence — the base branch's newest result for the
  # failing names: 실패 · 통과 · 없음 · 판정 불가. A read failure is 판정 불가 and
  # parks nothing: it only decides whether a second failure is the base's own.
  local out names
  names=$(printf '%s\n' "$GATE_CI_RERUN_FAILS" | awk -F'\t' 'NF >= 2 { print $2 }')
  out=$(gate_ci_rerun_gh api "repos/$GATE_CI_RERUN_SLUG/commits/$GATE_CI_RERUN_BASE/check-runs?per_page=100" \
        --jq '.check_runs[] | [.name, (.conclusion // "")] | join("\t")' 2>/dev/null) || { printf '판정 불가'; return 0; }
  printf '%s\n' "$out" | GATE_CIB_NAMES="$names" awk -F'\t' '
    BEGIN { n = split(ENVIRON["GATE_CIB_NAMES"], w, "\n"); for (i = 1; i <= n; i++) if (w[i] != "") want[w[i]] = 1 }
    ($1 in want) && !($1 in seen) { seen[$1] = 1
      if ($2 == "failure" || $2 == "timed_out" || $2 == "cancelled" || $2 == "action_required") f = 1
      else if ($2 == "success" || $2 == "neutral" || $2 == "skipped") p = 1 }
    END { if (f) print "실패"; else if (p) print "통과"; else print "없음" }'
}

gate_perform_ci_rerun() {
  # gate_perform_ci_rerun <alias> <segment> <argv...> — the request row, one POST
  # per run, the confirmation, and the closing row. No retry: a POST that did
  # not take is a person's, and a second POST after an unknown outcome would be
  # a second rerun.
  local al="$1" seg="$2"; shift 2
  if [ "${GATE_CI_RERUN_VERDICT:-}" != "eligible" ] || [ -z "${GATE_CI_RERUN_RUNS:-}" ]; then
    warn "the rerun act reached its performer without an eligibility verdict — nothing was requested"
    return "$GATE_EXIT_RULE"
  fi
  local slug="$GATE_CI_RERUN_SLUG" h="$GATE_CI_RERUN_HEAD" pr="$GATE_CI_RERUN_PR"
  local k base r code codes="" failed="" tries new wfs="${GATE_CI_RERUN_WFS:--}" fc screen=""
  # One numbering for rerun and label rounds: the pair's highest round + 1.
  k=$(( ${GATE_CI_RERUN_MAX:-0} + 1 ))
  base=$(gate_ci_rerun_base_evidence)
  fc=$(printf '%s\n' "$GATE_CI_RERUN_FAILS" | awk -F'\t' 'NF >= 2 { printf "%s%s", (n++ ? "," : ""), $2 }')
  local -a common=("세그먼트=$seg" "PR=$pr" "head sha=$h" "처분=재실행")
  local runs_f; runs_f=$(printf '%s' "$GATE_CI_RERUN_RUNS" | tr ' ' ',')
  # THE ROW BEFORE THE POST: a gate that dies between the two leaves a request a
  # person can see, never a rerun nobody recorded.
  gate_append 'CI 처분' "${common[@]}" "상태=요청" "회차=$k" "실행=$runs_f" \
    "워크플로=$(gate_row_safe "${wfs:--}" 200)" "실패 체크=$(gate_row_safe "${fc:--}" "$GATE_CHECKS_FAIL_MAX")" \
    "기본 브랜치=$base" "응답=-" "관측=$(date -u +%Y-%m-%dT%H:%M:%SZ)" || return $?
  for r in $GATE_CI_RERUN_RUNS; do
    code=$(gate_ci_rerun_gh api -X POST -i "repos/$slug/actions/runs/$r/rerun-failed-jobs" 2>/dev/null \
           | awk 'NR == 1 && /^HTTP\// { print $2; exit }' || true)
    [ -n "$code" ] || code=000
    codes="${codes:+$codes,}$code"
    case "$code" in 2??) ;; *) failed=1 ;; esac
  done
  if [ -z "$failed" ]; then
    # THE ATTEMPT ROSE, THEN THE SCREEN MOVED: a `수락` whose checks screen still
    # shows the old failing job would have the poller read that job as the new
    # round's failure.
    local e rid want ok
    for e in ${GATE_CI_RERUN_ATTS:-}; do
      rid=${e%%:*}; want=${e#*:}
      case "$want" in ''|*[!0-9]*) failed=1; codes="$codes,attempt"; break ;; esac
      want=$(( want + 1 )); ok=""
      tries=0
      while [ "$tries" -lt "$GATE_CI_RERUN_CONFIRM_TRIES" ]; do
        new=$(gate_ci_rerun_run_tsv "$slug" "$rid" | cut -f10 || true)
        [ "$new" = "$want" ] && { ok=1; break; }
        tries=$(( tries + 1 )); sleep "$GATE_CI_RERUN_CONFIRM_SLEEP"
      done
      [ -n "$ok" ] || { failed=1; codes="$codes,attempt"; break; }
    done
    if [ -z "$failed" ]; then
      tries=0; ok=""
      while [ "$tries" -lt "$GATE_CI_RERUN_CONFIRM_TRIES" ]; do
        screen=$(gate_ci_rerun_checks_tsv "$(gate_ci_rerun_gh pr checks "$pr" -R "$slug" --json name,bucket,link 2>/dev/null || true)" || true)
        if [ -n "$screen" ] && printf '%s\n' "$GATE_CI_RERUN_FAILS" | GATE_CIS_NOW="$screen" awk -F'\t' '
             BEGIN { n = split(ENVIRON["GATE_CIS_NOW"], l, "\n")
                     for (i = 1; i <= n; i++) { split(l[i], c, "\t"); key[c[2] "\t" c[3]] = c[1] } }
             NF >= 3 { k = $2 "\t" $3; if ((k in key) && key[k] == "fail") stale = 1 }
             END { exit stale ? 1 : 0 }'; then
          ok=1; break
        fi
        tries=$(( tries + 1 )); sleep "$GATE_CI_RERUN_CONFIRM_SLEEP"
      done
      [ -n "$ok" ] || { failed=1; codes="화면"; }
    fi
  fi
  if [ -z "$failed" ]; then
    gate_append 'CI 처분' "${common[@]}" "상태=수락" "회차=$k" "실행=$runs_f" \
      "워크플로=$(gate_row_safe "${wfs:--}" 200)" "실패 체크=$(gate_row_safe "${fc:--}" "$GATE_CHECKS_FAIL_MAX")" \
      "기본 브랜치=$base" "응답=$codes" "관측=$(date -u +%Y-%m-%dT%H:%M:%SZ)" || return $?
    log "$seg: 재실행 수락 — 회차 $k, 실행 $runs_f"
    return 0
  fi
  gate_append 'CI 처분' "${common[@]}" "상태=실패" "회차=$k" "실행=$runs_f" \
    "워크플로=$(gate_row_safe "${wfs:--}" 200)" "실패 체크=$(gate_row_safe "${fc:--}" "$GATE_CHECKS_FAIL_MAX")" \
    "기본 브랜치=$base" "응답=$(gate_row_safe "$codes" 120)" "관측=$(date -u +%Y-%m-%dT%H:%M:%SZ)" || return $?
  warn "reach park — judgment '재실행요청실패'. GitHub did not take the rerun (응답=$codes) and the gate does not try again"
  gate_park_record '재실행요청실패' 'closed' "${GATE_CI_RERUN_OBS:-$codes}" "$@"
  return "$GATE_EXIT_PARK"
}

# ---------------------------------------------------------------------------
# The match act — `act --kind ci-match -- 대조 <head sha>`.
#
# A SEGMENT WHOSE CI FAILS ONLY WITH WHAT THE BASE BRANCH ALREADY FAILS WITH
# HAS NOTHING OF ITS OWN TO FIX. Sent to the implement stage it spends the fix
# budget on a failure it did not cause, and every segment of every run on the
# same base does the same. The act reads the head's failing checks, turns each
# failing job's log into signatures with the adapter beside this file, and
# writes on the `CI 처분` series how they stand against the base branch's
# reading — the `master 판독` row — and against the events resolved since the
# segment's base: `초과` (something of its own), `재합류 필요` (a failure the
# base has since fixed), `부분집합` (only what the base fails with), `수리 통과`
# (a repair run's segment that removes its own event and adds nothing), or
# `판정 불가`.
#
# IT CHANGES NOTHING OUTSIDE THE RUN. Every GitHub call is a GET under the
# read-scoped runner; the one write outside the ledger and the run directory
# is the representative marker below, under the state root.
# ---------------------------------------------------------------------------

gate_ci_match_preconditions() {
  # gate_ci_match_preconditions <segment> <sha> — the refusals that need
  # neither the ledger nor GitHub, as for the rerun act.
  local seg="$1" sha="$2" tip
  if ! run_routed; then
    warn "the match act runs only on a routed run — this run has no routing record"
    return "$GATE_EXIT_RULE"
  fi
  tip=$(gate_segment_tip "$seg") || tip=""
  if [ -z "$tip" ] || [ "$tip" != "$sha" ]; then
    warn "the match names head $sha, but the segment worktree's tip is ${tip:-(unresolved)} — read 다음 again"
    return "$GATE_EXIT_RULE"
  fi
}

gate_ci_match_lock_release() {
  [ -n "${GATE_CI_MATCH_LOCK:-}" ] || return 0
  rm -rf "$GATE_CI_MATCH_LOCK" 2>/dev/null || true
  GATE_CI_MATCH_LOCK=""
}

gate_check_ci_match() {
  # gate_check_ci_match <kind> — the target, a fresh reading, the lock and
  # `다음`, for the match act only. Refusal exits 3 with no row of its own.
  [ "$1" = "ci-match" ] || return 0
  local seg="$segment" al wt h nx rc=0 dir
  if ! gate_ci_join_target "$seg"; then
    warn "segment $seg is not a CI join target — there is no CI verdict to match"
    exit "$GATE_EXIT_RULE"
  fi
  al=$(gate_segment_target_alias "$seg")
  # The reading this act compares against is the one the ledger holds, so it
  # is brought up to date first — an act, unlike a forecast, may write it.
  [ "${verb:-}" != "act" ] || gate_master_row_if_changed
  if ! gate_master_fresh "$al"; then
    warn "no fresh 'master 판독' row for target $al — the base branch's reading is missing or older than ${GATE_MASTER_STALE_SECONDS}s"
    exit "$GATE_EXIT_RULE"
  fi
  # A reading still `진행 중` or `판정 불가` need not list every failure of its
  # tip, and a match against it could hide one, so it waits for red or green.
  case "$(gate_row_field "$(gate_master_last_row "$al")" '상태')" in
    빨강|초록) ;;
    *) warn "the 'master 판독' row for target $al is not settled red or green — the match waits for the next reading"
       exit "$GATE_EXIT_RULE" ;;
  esac
  wt=$(gate_segment_worktree "$seg")
  h=$(gate_worktree_tip "$wt") || { warn "the segment worktree's tip does not resolve"; exit "$GATE_EXIT_RULE"; }
  dir="$RUN_DIR/ci-match.$seg.lock"
  gate_ci_seg_lock_take "$dir" || rc=$?
  if [ "$rc" = "1" ]; then
    warn "another match act of segment $seg holds its lock — not queued, read 다음 again"
    exit "$GATE_EXIT_RULE"
  fi
  [ "$rc" = "2" ] || GATE_CI_MATCH_LOCK="$dir"
  nx=$(gate_segment_review_next "$seg")
  case "$nx" in
    'CI 대조'|'master 대기'|'master 수리 불가') ;;
    *) warn "다음 of segment $seg is '$nx', not 'CI 대조', 'master 대기' or 'master 수리 불가' — the match act is refused"
       exit "$GATE_EXIT_RULE" ;;
  esac
  GATE_CI_MATCH_ADMIT=1; GATE_CI_MATCH_ALIAS="$al"; GATE_CI_MATCH_HEAD="$h"
  return 0
}

gate_ci_match_kill_tree() {
  # gate_ci_match_kill_tree <pid> — the process and everything under it: the
  # read runs two subshells deep, so the direct child alone is not the `gh`.
  local c
  for c in $(pgrep -P "$1" 2>/dev/null || true); do gate_ci_match_kill_tree "$c"; done
  kill "$1" 2>/dev/null || true
}

gate_ci_match_gh() {
  # gate_ci_match_gh <out file> <gh args…> — one GET into the file, abandoned
  # after GATE_CI_MATCH_GH_SECONDS. A read that hangs leaves the act's lock
  # held for as long as it hangs, and the act would rather say `판정 불가`.
  local out=$1 pid t=0 lim
  shift
  gate_ci_rerun_gh "$@" > "$out" 2>/dev/null &
  pid=$!
  lim=$((GATE_CI_MATCH_GH_SECONDS * 5))
  while kill -0 "$pid" 2>/dev/null; do
    if [ "$t" -ge "$lim" ]; then
      gate_ci_match_kill_tree "$pid"
      wait "$pid" 2>/dev/null || true
      return 124
    fi
    sleep 0.2; t=$((t + 1))
  done
  wait "$pid"
}

gate_master_resolved_after() {
  # gate_master_resolved_after <segment> <alias> — the ids of the events in the
  # target's last reading that were resolved after the segment's base, one per
  # line, an id per resolving commit the segment's HEAD does not contain.
  #
  # THE BASE IS WHAT THE HEAD CONTAINS, not a row. A `베이스 판정` row moves
  # when base-check runs, before the rejoin merge lands, so reading the base off
  # it would drop the event between the check and the merge and send the
  # segment back to L7; once the merge lands the resolving commit is an
  # ancestor of HEAD and the event leaves the set, so a joined fix is never
  # asked for again.
  #
  # AN OBJECT THE WORKTREE DOES NOT HAVE IS AFTER. The worktrees are full
  # clones, so every ancestor of HEAD is in the object store, and a commit
  # that is not there cannot be one. That is the usual case, not an edge: the
  # resolving commit is the merge GitHub made on the base branch, and nothing
  # fetches while a segment waits. Only a commit that resolves and is an
  # ancestor of HEAD counts as joined. The gate still does not fetch; the
  # rejoin's base-check reads the remote, and the router fetches before it.
  local seg=$1 al=$2 row ev wt head e id res full
  row=$(gate_master_last_row "$al")
  ev=$(gate_row_field "$row" '사건')
  [ -n "$ev" ] && [ "$ev" != "-" ] || return 0
  wt=$(gate_segment_worktree "$seg")
  head=$(gate_worktree_tip "$wt") || return 0
  for e in $(printf '%s' "$ev" | tr ',' '\n' | awk -F':' '$3 != "-" { print $1 ":" $3 }'); do
    id=${e%%:*}; res=${e#*:}
    if full=$(gate_commit_in "$wt" "$res"); then
      gate_iso_git "$wt" merge-base --is-ancestor "$full" "$head" >/dev/null 2>&1 && continue
    fi
    printf '%s\n' "$id"
  done
}

gate_master_open_events() {
  # gate_master_open_events <alias> — the ids of the events in the target's
  # last reading that carry no resolving commit, one per line. An event is
  # resolved only by a complete observation, so a reading that is `진행 중` or
  # `판정 불가` still lists every event the base branch had not fixed.
  local ev
  ev=$(gate_row_field "$(gate_master_last_row "$1")" '사건')
  [ -n "$ev" ] && [ "$ev" != "-" ] || return 0
  printf '%s' "$ev" | tr ',' '\n' | awk -F':' 'NF && $3 == "-" { print $1 }'
}

gate_ci_match_reading_mark() {
  # gate_ci_match_reading_mark <master 판독 row> — `<팁 7>/<관측>/<서명 지문 12>`,
  # the reading a match was made against. The merge check computes the same
  # mark from the ledger's last reading and compares the two strings.
  local tip fp
  tip=$(gate_row_field "$1" '팁'); fp=$(gate_row_field "$1" '서명 지문')
  printf '%.7s/%s/%.12s' "${tip:--}" "$(gate_row_field "$1" '관측')" "${fp:--}"
}

gate_ci_match_events_mark() {
  # gate_ci_match_events_mark <master 판독 row> — the first 12 hex of the
  # sha256 of the row's `사건` field: every event's id, first commit,
  # resolving commit and repair state at the reading matched against.
  local fp
  fp=$(printf '%s\n' "$(gate_row_field "$1" '사건')" | gate_ci_signature fingerprint 2>/dev/null || true)
  printf '%.12s' "${fp:--}"
}

gate_ci_match_same_reading() {
  # gate_ci_match_same_reading <match row> <master 판독 row> — 0 when the match
  # was made against a reading with the same signature fingerprint and event
  # field as this one. Those two are all the comparison set is made of, and
  # they are what the relay wakes on. The tip and the observation time are
  # left out: a base commit that fixes nothing moves the tip, the reading's
  # refresh rewrites the time, and the match would come out the same.
  local was fp
  was=$(gate_row_field "$1" '판독 지문'); fp=$(gate_row_field "$2" '서명 지문')
  [ "${was##*/}" = "$(printf '%.12s' "${fp:--}")" ] \
    && [ "$(gate_row_field "$1" '판독 사건')" = "$(gate_ci_match_events_mark "$2")" ]
}

gate_master_event_state() {
  # gate_master_event_state <alias> <id> — that event's repair state in the
  # target's last reading, or nothing.
  gate_row_field "$(gate_master_last_row "$1")" '사건' | tr ',' '\n' \
    | awk -F':' -v id="$2" '$1 == id { s = $0; sub(/^[^:]*:[^:]*:[^:]*:/, "", s); print s; exit }'
}

gate_repair_event_row() {
  # gate_repair_event_row — the manifest's `수리 사건` row, `<slug>\t<베이스>\t<사건 id>\t<서명 sha256>`,
  # or nothing. The row is positional: `- \`수리 사건\` | <slug> | <베이스> | <사건 id> | <서명 sha256>`.
  [ -n "${MANIFEST:-}" ] && [ -f "$MANIFEST" ] || return 0
  grep -E '^- `수리 사건` ' "$MANIFEST" 2>/dev/null | awk -F'|' '
    function trim(s) { sub(/^[ \t]+/, "", s); sub(/[ \t]+$/, "", s); return s }
    NF == 5 { print trim($2) "\t" trim($3) "\t" trim($4) "\t" trim($5); exit }' || true
}

gate_master_claim() {
  # gate_master_claim <event id> <segment> — 0 when this segment holds the
  # event's representative marker after the call. The marker is a directory
  # under the state root holding `owner` = `<run id> <segment>`. A marker whose
  # owner run has ended (`done` in its run directory), or whose owner is a
  # segment of this run that merged or parked, is taken over.
  local id=$1 seg=$2 root dir me owner orun oseg ost
  root="${XDG_STATE_HOME:-$HOME/.local/state}/cc-cmds"
  dir="$root/master-claims/$id"
  me="${RUN_ID:-${RUN_DIR##*/}} $seg"
  mkdir -p "$root/master-claims" 2>/dev/null || return 1
  if mkdir "$dir" 2>/dev/null; then
    printf '%s\n' "$me" > "$dir/owner" 2>/dev/null || true
    return 0
  fi
  owner=$(head -1 "$dir/owner" 2>/dev/null || true)
  [ "$owner" = "$me" ] && return 0
  orun=${owner%% *}; oseg=${owner#* }
  if [ -n "$orun" ] && [ "$orun" = "${RUN_ID:-${RUN_DIR##*/}}" ]; then
    ost=$(gate_segment_field "$oseg" '상태')
    case "$ost" in 머지됨|park) ;; *) return 1 ;; esac
  elif [ -z "$owner" ] || [ -f "$root/run/$orun/done" ]; then
    :
  else
    return 1
  fi
  printf '%s\n' "$me" > "$dir/owner.tmp" 2>/dev/null && mv -f "$dir/owner.tmp" "$dir/owner" 2>/dev/null || return 1
  return 0
}

gate_perform_ci_match() {
  # gate_perform_ci_match <alias> <segment> — the reads, the comparison and the
  # match row. A read that fails makes the result `판정 불가` rather than the
  # act's failure: the row is what the disposition waits on.
  local al="$1" seg="$2"
  if [ "${GATE_CI_MATCH_ADMIT:-}" != "1" ] || [ -z "${GATE_CI_MATCH_HEAD:-}" ]; then
    warn "the match act reached its performer without its admission — nothing was read"
    return "$GATE_EXIT_RULE"
  fi
  al="${GATE_CI_MATCH_ALIAS:-$al}"
  local h="$GATE_CI_MATCH_HEAD" slug tmpd rd g pr mrow cur fp="" n=0 prec="" incomplete="" fc=""
  local line cid name concl app durl job s outp p sigs="" res_ids="" id
  slug=$(target_field "$al" '원격 슬러그' 2>/dev/null || true)
  rd=$(cc_ci_round "$LEDGER" "$seg" "$h"); g=$(cc_ci_round_get "$rd" g)
  pr=$(gate_rows 'checks' | gate_rows_field_eq '세그먼트' "$seg" | gate_rows_field_eq 'head sha' "$h" \
       | awk 'NF { r = $0 } END { if (r != "") print r }')
  pr=$(gate_row_field "$pr" 'PR'); [ -n "$pr" ] || pr='-'
  mrow=$(gate_master_last_row "$al")
  tmpd=$(mktemp -d "${TMPDIR:-/tmp}/gate-ci-match.XXXXXX") || return "$GATE_EXIT_RULE"
  if [ -z "$slug" ]; then
    incomplete=1
  elif ! gate_ci_match_gh "$tmpd/runs" api --paginate "repos/$slug/commits/$h/check-runs?per_page=100" \
         --jq '.check_runs[] | [(.id | tostring), .name, (.status // ""), (.conclusion // ""), (.app.slug // ""), (.details_url // "")] | join("\t")'; then
    incomplete=1
  else
    # A check still running is not a settled set: the match waits for nothing
    # and says so.
    awk -F'\t' 'NF && $3 != "completed" { f = 1 } END { exit !f }' "$tmpd/runs" && incomplete=1
    # `cut`, never `read`, for the reason the rerun act gives: an empty field
    # would shift every field after it. The loop reads on its own descriptor so
    # nothing inside it can drain the list.
    while IFS= read -r line <&3; do
      [ -n "$line" ] || continue
      cid=$(printf '%s' "$line" | cut -f1);    name=$(printf '%s' "$line" | cut -f2)
      concl=$(printf '%s' "$line" | cut -f4);  app=$(printf '%s' "$line" | cut -f5)
      durl=$(printf '%s' "$line" | cut -f6)
      case "$concl" in failure|timed_out|cancelled|action_required) ;; *) continue ;; esac
      fc="${fc:+$fc,}$name"
      # An Actions check run is the job of the same id; the details URL names
      # it as well, and the URL wins when the two disagree.
      if [ "$app" != "github-actions" ]; then incomplete=1; continue; fi
      job=$(printf '%s' "$durl" | sed -n 's#.*/job/\([0-9][0-9]*\).*#\1#p')
      [ -n "$job" ] || job="$cid"
      case "$job" in ''|*[!0-9]*) incomplete=1; continue ;; esac
      if ! gate_ci_match_gh "$tmpd/steps" api "repos/$slug/actions/jobs/$job" \
             --jq '.steps[]? | select(.conclusion == "failure") | .name'; then
        incomplete=1; continue
      fi
      if ! gate_ci_match_gh "$tmpd/log.full" api --allow-escape-sequences "repos/$slug/actions/jobs/$job/logs"; then
        incomplete=1; continue
      fi
      head -c "$GATE_CI_MATCH_LOG_MAX_BYTES" "$tmpd/log.full" > "$tmpd/log" 2>/dev/null || : > "$tmpd/log"
      set --
      # A log cut at the cap may end between two suites, where nothing in the
      # part kept says a suite is missing, so the adapter is told.
      s=$(wc -c < "$tmpd/log.full" 2>/dev/null | tr -d ' ')
      [ "${s:-0}" -le "$GATE_CI_MATCH_LOG_MAX_BYTES" ] || set -- --truncated
      while IFS= read -r s; do [ -z "$s" ] || set -- "$@" --step "$s"; done < "$tmpd/steps"
      outp=$(gate_ci_signature extract --repo "$slug" --check "$name" "$@" < "$tmpd/log" 2>/dev/null) || { incomplete=1; continue; }
      p=$(printf '%s\n' "$outp" | sed -n '1s/^정밀도: //p')
      s=$(printf '%s\n' "$outp" | tail -n +2 | { grep -v '^$' || true; })
      if [ -z "$s" ]; then incomplete=1; continue; fi
      sigs=$(printf '%s\n%s\n' "$sigs" "$s")
      case "$p" in 단언) [ -n "$prec" ] || prec='단언' ;; *) prec='단계' ;; esac
    done 3< "$tmpd/runs"
  fi
  sigs=$(printf '%s\n' "$sigs" | { grep -v '^$' || true; } | LC_ALL=C sort -u)
  [ -n "$fc" ] || incomplete=1
  if [ -n "$sigs" ]; then
    n=$(printf '%s\n' "$sigs" | gate_count)
    fp=$(printf '%s\n' "$sigs" | gate_ci_signature fingerprint)
    printf '%s\n' "$sigs" > "$tmpd/seg"
    gate_ci_signature_keep "$fp" < "$tmpd/seg"
  else
    : > "$tmpd/seg"
  fi
  # The comparison set: the reading's signatures and those of the events
  # resolved after the segment's base.
  cur=$(gate_row_field "$mrow" '서명 지문')
  if [ -n "$cur" ] && [ "$cur" != "-" ] && [ -f "$(gate_ci_signature_file "$cur")" ]; then
    LC_ALL=C sort -u "$(gate_ci_signature_file "$cur")" > "$tmpd/cur"
  else
    : > "$tmpd/cur"
  fi
  res_ids=$(gate_master_resolved_after "$seg" "$al")
  : > "$tmpd/res"
  for id in $res_ids; do
    [ ! -f "$(gate_ci_signature_file "event-$id")" ] || cat "$(gate_ci_signature_file "event-$id")" >> "$tmpd/res"
  done
  LC_ALL=C sort -u "$tmpd/res" -o "$tmpd/res"
  # Events the segment waits on: unresolved events of the reading whose
  # signatures it shares, else every unresolved event.
  local waits="" all_open="" e
  for e in $(gate_row_field "$mrow" '사건' | tr ',' '\n' | awk -F':' '$3 == "-" { print $1 }'); do
    all_open="${all_open:+$all_open,}$e"
    if [ -f "$(gate_ci_signature_file "event-$e")" ] \
       && [ -n "$(LC_ALL=C comm -12 "$tmpd/seg" "$(gate_ci_signature_file "event-$e")" 2>/dev/null)" ]; then
      waits="${waits:+$waits,}$e"
    fi
  done
  [ -n "$waits" ] || waits="$all_open"
  local result outside resonly
  outside=$(LC_ALL=C sort -u "$tmpd/cur" "$tmpd/res" | LC_ALL=C comm -23 "$tmpd/seg" - 2>/dev/null || true)
  resonly=$(LC_ALL=C comm -12 "$tmpd/seg" "$tmpd/res" 2>/dev/null | LC_ALL=C comm -23 - "$tmpd/cur" 2>/dev/null || true)
  if [ -n "$outside" ]; then
    result='초과'
  elif [ -n "$incomplete" ] || [ -z "$sigs" ]; then
    result='판정 불가'
  elif [ -n "$resonly" ]; then
    result='재합류 필요'
  else
    result='부분집합'
    # A repair run's segment passes when it adds nothing, every signature is
    # assertion-precise, and none of its own event's signatures is left.
    local rrow rslug rbr rid own
    rrow=$(gate_repair_event_row)
    if [ -n "$rrow" ] && [ "$prec" = "단언" ]; then
      rslug=$(printf '%s' "$rrow" | cut -f1); rbr=$(printf '%s' "$rrow" | cut -f2); rid=$(printf '%s' "$rrow" | cut -f3)
      own=$(gate_ci_signature_file "event-$rid")
      if [ "$rslug" = "$slug" ] && [ "$rbr" = "$(base_branch "$al" 2>/dev/null || true)" ] && [ -s "$own" ] \
         && [ -z "$(LC_ALL=C comm -12 "$tmpd/seg" "$own" 2>/dev/null)" ]; then
        result='수리 통과'
      fi
    fi
  fi
  rm -rf "$tmpd"
  # The representative marker: one waiting segment per event the host could
  # not start a repair run for asks the person, and the ledger says which.
  local rep='-'
  case "$result" in
    부분집합|'판정 불가')
      for e in $(printf '%s' "$waits" | tr ',' ' '); do
        [ "$(gate_master_event_state "$al" "$e")" = '띄울 수 없음' ] || continue
        if gate_master_claim "$e" "$seg"; then rep='예'; fi
      done ;;
  esac
  # The row carries a 64-hex fingerprint and the reading's fingerprint on top
  # of the rerun row's fields, so its two free-length fields are cut shorter
  # than the rerun row's: the widest match row stays near 900 bytes.
  local mfp mtip
  mtip=$(gate_row_field "$mrow" '팁'); mfp=$(gate_row_field "$mrow" '서명 지문')
  gate_append 'CI 처분' "세그먼트=$seg" "PR=$pr" "head sha=$h" "처분=대조" "상태=대조" "회차=${g:-0}" \
    "실행=-" "워크플로=-" "실패 체크=$(gate_row_safe "${fc:--}" 200)" \
    "기본 브랜치=-" "응답=-" "관측=$(date -u +%Y-%m-%dT%H:%M:%SZ)" \
    "결과=$result" "정밀도=${prec:--}" "서명 수=$n" "서명 지문=${fp:--}" \
    "판독 지문=$(gate_ci_match_reading_mark "$mrow")" "판독 사건=$(gate_ci_match_events_mark "$mrow")" \
    "사건=$(gate_row_safe "${waits:--}" 120)" "대표=$rep" || return $?
  log "$seg: CI 대조 — $result (서명 ${n}개)"
  return 0
}

# ---------------------------------------------------------------------------
# The label act — `act --kind label-ack -- 라벨 <head sha>`.
#
# A CHECK THE KICKOFF LET A LABEL ANSWER. Some required checks fail by design
# until a reviewer labels the pull request — an API-surface guard that passes
# once the change is labelled as intended. A person decided at kickoff, in a
# `라벨 인정` row, which (target, check) pairs a label may answer, and the
# slice's `라벨 인정` field binds that decision to the slice that changes the
# guarded surface. This act is the run's only way to put a label on a pull
# request: the exec path refuses every PR label write.
#
# THE SAME SEATS AS THE RERUN ACT, AND THE SAME LOCK. The spelling and the
# routed-run/tip refusals stand at the preconditions; `다음`, the binding, the
# acknowledgement and every workflow the label event can wake stand at the
# rerun's eligibility seat; the request row, the POST and the confirmation are
# the performer's. Every check errs towards a park, and nothing is written
# before the last one passes.
# ---------------------------------------------------------------------------
GATE_LABEL_ACK_CONFIRM_TRIES=10
GATE_LABEL_ACK_CONFIRM_SLEEP=3

gate_label_ack_preconditions() {
  # gate_label_ack_preconditions <segment> <sha> — the rerun act's two
  # refusals, for the label act: a run the routing shift does not drive, or an
  # argv sha that is not the worktree's tip. Passing sets the marker the rule
  # branch opens on.
  local seg="$1" sha="$2" tip
  if ! run_routed; then
    warn "the label act runs only on a routed run — this run has no routing record"
    return "$GATE_EXIT_RULE"
  fi
  tip=$(gate_segment_tip "$seg") || tip=""
  if [ -z "$tip" ] || [ "$tip" != "$sha" ]; then
    warn "the label act names head $sha, but the segment worktree's tip is ${tip:-(unresolved)} — read 다음 again"
    return "$GATE_EXIT_RULE"
  fi
  GATE_LABEL_ACK_PRE=1
  export GATE_LABEL_ACK_PRE
}

gate_label_ack_types() {
  # gate_label_ack_types <file> <event> — whether a pull request labelled now
  # starts this workflow for <event> (`pull_request` or `pull_request_target`):
  # `받음` when its `types` hold `labeled`, `받지않음` when they do not or the
  # event is not named at all, `읽지못함` for any shape this reader does not
  # know. The top-level `on` key is read the way `gate_ci_rerun_on_hit` reads
  # it, quoted and as YAML 1.1's `true` included. An event named with no
  # `types` takes GitHub's default types, which do not hold `labeled`.
  # Unknown: an anchor, an alias or a merge key in the `on` block, a second
  # document, an inline mapping, a `types` of any shape but a flow or block
  # list, and a file that cannot be read.
  [ -r "$1" ] || { printf '읽지못함'; return 0; }
  LC_ALL=C awk -v q="'" -v ev="$2" '
    function unq(s) { gsub(/"/, "", s); gsub(q, "", s); return s }
    function trimc(s) { sub(/[ \t]+#.*$/, "", s); sub(/^#.*$/, "", s); sub(/^[ \t]+/, "", s); sub(/[ \t]+$/, "", s); return s }
    function flow(s, want,   inner, m, w, j) {
      inner = substr(s, 2, length(s) - 2); m = split(inner, w, ",")
      for (j = 1; j <= m; j++) if (unq(trimc(w[j])) == want) return 1
      return 0
    }
    /^(---|\.\.\.)([ \t].*)?$/ { if (content) bad = 1; next }
    !/^[ \t]*(#.*)?$/ { content = 1 }
    !found {
      k = $0; sub(/[ \t]*:.*$/, "", k)
      if ($0 ~ /^[^ \t#][^:]*:/ && (k == "on" || k == "\"on\"" || k == q "on" q || k == "true")) {
        found = 1; v = $0; sub(/^[^:]*:/, "", v); v = trimc(v)
        if (v != "") scalar = 1; else inblk = 1
      }
      next
    }
    inblk {
      if ($0 ~ /^[ \t]*(#.*)?$/) next
      if ($0 !~ /^[ \t]/) { inblk = 0; next }
      ind = match($0, /[^ \t]/) - 1
      if (minind == "" || ind < minind) minind = ind
      line[++n] = $0; lind[n] = ind
    }
    END {
      if (bad || !found) { print "읽지못함"; exit }
      if (scalar) {
        if (v ~ /[&*]/) { print "읽지못함"; exit }
        if (v ~ /^\[.*\]$/) { print "받지않음"; exit }
        if (unq(v) ~ /^[A-Za-z_]+$/) { print "받지않음"; exit }
        print "읽지못함"; exit
      }
      if (n == 0) { print "읽지못함"; exit }
      for (i = 1; i <= n; i++) if (line[i] ~ /(^|[ \t:,\[-])[&*][A-Za-z0-9_]/ || line[i] ~ /<</) { print "읽지못함"; exit }
      ei = 0
      for (i = 1; i <= n; i++) {
        if (lind[i] != minind) continue
        s = line[i]; sub(/^[ \t]*/, "", s)
        if (s ~ /^-/) { if (unq(trimc(substr(s, 2))) == ev) { print "받지않음"; exit }; continue }
        k = s; sub(/[ \t]*:.*$/, "", k)
        if (unq(k) == ev) { ei = i; break }
      }
      if (!ei) { print "받지않음"; exit }
      s = line[ei]; sub(/^[^:]*:/, "", s); s = trimc(s)
      if (s == "null" || s == "~" || s == "{}") { print "받지않음"; exit }
      if (s != "") { print "읽지못함"; exit }
      cmin = ""
      for (i = ei + 1; i <= n && lind[i] > minind; i++) if (cmin == "" || lind[i] < cmin) cmin = lind[i]
      ti = 0
      for (i = ei + 1; i <= n && lind[i] > minind; i++) {
        if (lind[i] != cmin) continue
        s = line[i]; sub(/^[ \t]*/, "", s); k = s; sub(/[ \t]*:.*$/, "", k)
        if (unq(k) == "types") { ti = i; break }
      }
      if (!ti) { print "받지않음"; exit }
      s = line[ti]; sub(/^[^:]*:/, "", s); s = trimc(s)
      if (s ~ /^\[.*\]$/) { print (flow(s, "labeled") ? "받음" : "받지않음"); exit }
      if (s != "") { print "읽지못함"; exit }
      got = 0; any = 0
      for (i = ti + 1; i <= n; i++) {
        s = line[i]; sub(/^[ \t]*/, "", s)
        if (lind[i] < lind[ti]) break
        if (lind[i] == lind[ti] && s !~ /^-/) break
        if (s !~ /^-/) { print "읽지못함"; exit }
        any = 1
        if (unq(trimc(substr(s, 2))) == "labeled") got = 1
      }
      if (!any) { print "읽지못함"; exit }
      print (got ? "받음" : "받지않음")
    }' "$1" 2>/dev/null || printf '읽지못함'
}

gate_label_ack_argv() {
  # gate_label_ack_argv <slug> <pr> <label> — the POST as the performer spells
  # it, the string an `argv:` deploy-trigger identifier is compared against.
  printf 'gh api -X POST -i repos/%s/issues/%s/labels -f labels[]=%s' "$1" "$2" "$3"
}

gate_label_ack_park() {
  # gate_label_ack_park <칸> <관측> — set the park cell for the dispatch.
  GATE_PARK_CELL="$1"; GATE_PARK_CAUSE='-'; GATE_PARK_OBS="$2"
  GATE_LABEL_ACK_VERDICT=""
  export GATE_PARK_CELL GATE_PARK_CAUSE GATE_PARK_OBS
}

gate_check_label_ack() {
  # gate_check_label_ack <kind> — the lock, `다음`, the pull request, the failing
  # check, the acknowledgement, the workflows a label event wakes and the
  # label already on the pull request, for the label act and nothing else.
  # Refusal exits 3 with no row; a park sets the park cell for the dispatch
  # below it; an eligible act leaves `GATE_LABEL_ACK_VERDICT=eligible`.
  [ "$1" = "label-ack" ] || return 0
  local seg="$segment" al="$alias" wt h nx rd a ad slug br prs n pnum phead pref raw checks
  local acks sacks fails pend cands="" _b name link check="" clink="" label r line
  local wf_name="" wf_path="" wf_id="" bn basebr tmpd f src rc t1 t2 x5set="" bad="" ids id kind val labels
  wt=$(gate_segment_worktree "$seg")
  h=$(gate_worktree_tip "$wt") || { warn "the segment worktree's tip does not resolve"; exit "$GATE_EXIT_RULE"; }
  if ! gate_ci_rerun_lock "$seg"; then
    warn "another CI act of segment $seg holds its lock — not queued, read 다음 again"
    exit "$GATE_EXIT_RULE"
  fi
  # 1 — `다음` again from the gate's own ledger, and an open or failed label
  # round closed as a park without a POST.
  nx=$(gate_segment_review_next "$seg")
  if [ "$nx" != "CI 라벨 인정" ]; then
    warn "다음 of segment $seg is '$nx', not 'CI 라벨 인정' — the label act is refused"
    exit "$GATE_EXIT_RULE"
  fi
  rd=$(cc_ci_round "$LEDGER" "$seg" "$h")
  a=$(cc_ci_round_get "$rd" a); ad=$(cc_ci_round_get "$rd" ad)
  if [ "$ad" = "라벨" ] && { [ "$a" = "열림" ] || [ "$a" = "실패" ]; }; then
    GATE_PARK_CELL='라벨요청실패'
    if [ "$a" = "열림" ]; then GATE_PARK_CAUSE='open'; else GATE_PARK_CAUSE='closed'; fi
    GATE_PARK_OBS="회차:$a"
    export GATE_PARK_CELL GATE_PARK_CAUSE GATE_PARK_OBS
    return 0
  fi
  # 2 — the branch's one open pull request at this head.
  slug=$(target_field "$al" '원격 슬러그' 2>/dev/null || true)
  br=$( { cd "$wt" 2>/dev/null && git branch --show-current 2>/dev/null; } || true)
  if [ -z "$slug" ] || [ -z "$br" ]; then
    warn "the label act cannot bind a pull request (slug ${slug:-none}, branch ${br:-none})"
    exit "$GATE_EXIT_RULE"
  fi
  if ! prs=$(gate_ci_rerun_gh pr list -R "$slug" --head "$br" --state open --json number,headRefOid,headRefName 2>/dev/null) \
     || ! prs=$(printf '%s' "$prs" | jq -r '.[] | [(.number|tostring), .headRefOid, .headRefName] | join(" ")' 2>/dev/null); then
    warn "reading the open pull requests of $br failed — nothing was labelled"
    exit "$GATE_EXIT_RULE"
  fi
  n=$(printf '%s\n' "$prs" | grep -c . || true)
  read -r pnum phead pref <<EOF
$prs
EOF
  if [ "$n" != "1" ] || [ "$phead" != "$h" ] || [ "$pref" != "$br" ]; then
    warn "the branch $br has $n open pull request(s), head ${phead:-(none)} against tip $h — the head moved; read 다음 again"
    exit "$GATE_EXIT_RULE"
  fi
  # 3 — a declared check failing at H on the checks screen as it is now.
  raw=$(gate_ci_rerun_gh pr checks "$pnum" -R "$slug" --json name,bucket,link 2>/dev/null || true)
  if ! checks=$(gate_ci_rerun_checks_tsv "$raw"); then
    warn "reading the checks of PR $pnum failed — nothing was labelled"
    exit "$GATE_EXIT_RULE"
  fi
  pend=$(printf '%s\n' "$checks" | awk -F'\t' '$1 == "pending" { n++ } END { print n + 0 }')
  if [ "$pend" -gt 0 ]; then
    warn "$pend check(s) of PR $pnum are still pending — the label act waits for the set to settle"
    exit "$GATE_EXIT_RULE"
  fi
  fails=$(printf '%s\n' "$checks" | awk -F'\t' '$1 == "fail"')
  acks=$(manifest_label_ack_checks "$al")
  while IFS="$(printf '\t')" read -r _b name link; do
    [ -n "$name" ] || continue
    case "
$acks
" in *"
$name
"*) cands="${cands}${name}	${link}
" ;; esac
  done <<EOF
$fails
EOF
  if [ -z "$cands" ]; then
    warn "no check a \`라벨 인정\` row of target $al names is failing on PR $pnum now — nothing to label"
    exit "$GATE_EXIT_RULE"
  fi
  # 4 — the slice's own field names the check too. No slicing section, or a
  # slice without the field, is no acknowledgement.
  sacks=""
  if [ -n "${DOC:-}" ] && [ -f "$DOC" ] && slicing_present "$DOC" 2>/dev/null; then
    sacks=$(slice_label_ack_checks "$DOC" "$seg" 2>/dev/null || true)
  fi
  while IFS="$(printf '\t')" read -r name link; do
    [ -n "$name" ] || continue
    case "
$sacks
" in *"
$name
"*) check="$name"; clink="$link"; break ;; esac
  done <<EOF
$cands
EOF
  if [ -z "$check" ]; then
    gate_label_ack_park '라벨인정없음' "$(printf '%s' "$cands" | sed -n 1p | cut -f1)"; return 0
  fi
  label=$(manifest_label_ack_label "$al" "$check")
  case "$clink" in
    "https://github.com/$slug/actions/runs/"*)
      r=${clink#"https://github.com/$slug/actions/runs/"}; r=${r%%/*}
      case "$r" in ''|*[!0-9]*) r="" ;; esac ;;
    *) r="" ;;
  esac
  if [ -n "$r" ] && line=$(gate_ci_rerun_run_tsv "$slug" "$r"); then
    wf_name=$(printf '%s' "$line" | cut -f7); wf_path=$(printf '%s' "$line" | cut -f8)
    wf_id=$(printf '%s' "$line" | cut -f9); wf_path=${wf_path%%@*}
  fi
  # 5 — every workflow a label event can wake, from H's files and the base
  # branch tip's. The gate does not fetch: a base it does not hold is refused.
  basebr=$(gate_base_remote_tip "$al" "$wt" 2>/dev/null) || basebr=""
  if [ -z "$basebr" ] || ! ( cd "$wt" && git cat-file -e "$basebr^{commit}" ) 2>/dev/null; then
    warn "the base branch's tip ${basebr:-(unknown)} is not a local object — fetch the base first"
    exit "$GATE_EXIT_RULE"
  fi
  tmpd=$(mktemp -d "${TMPDIR:-/tmp}/gate-label-ack.XXXXXX") || exit "$GATE_EXIT_RULE"
  # (a) the failing check's own workflow at H has to start on `labeled`.
  t1="읽지못함"
  if [ -n "$wf_path" ] && ( cd "$wt" && git show "$h:$wf_path" ) > "$tmpd/own.wf" 2>/dev/null; then
    t1=$(gate_label_ack_types "$tmpd/own.wf" pull_request)
  fi
  if [ "$t1" != "받음" ]; then
    rm -rf "$tmpd"; gate_label_ack_park '라벨새실행없음' "$check:${wf_path:-워크플로 미상}:$t1"; return 0
  fi
  # (b) every file either source holds that a label wakes, or that cannot be
  # read, meets the rerun's file test (X5).
  for src in "$h" "$basebr"; do
    while IFS= read -r f; do
      case "$f" in *.yml|*.yaml) ;; *) continue ;; esac
      if ! ( cd "$wt" && git show "$src:$f" ) > "$tmpd/wf" 2>/dev/null; then
        rm -rf "$tmpd"; gate_label_ack_park '라벨배포트리거' "읽기 실패 ${f##*/}"; return 0
      fi
      t1=$(gate_label_ack_types "$tmpd/wf" pull_request)
      t2=$(gate_label_ack_types "$tmpd/wf" pull_request_target)
      [ "$t1" = "받지않음" ] && [ "$t2" = "받지않음" ] && continue
      x5set="${x5set}${f##*/}
"
      rc=1
      gate_ci_rerun_x5_hit "$tmpd/wf" && rc=0 || rc=$?
      if [ "$rc" != "1" ]; then rm -rf "$tmpd"; gate_label_ack_park '라벨배포트리거' "${f##*/}"; return 0; fi
    done <<EOF
$( { cd "$wt" && git ls-tree -r --name-only "$src" -- .github/workflows; } 2>/dev/null || true)
EOF
  done
  # (c) the base branch's files that fire on the end of the new run.
  while IFS= read -r f; do
    case "$f" in *.yml|*.yaml) ;; *) continue ;; esac
    rc=0
    if ( cd "$wt" && git show "$basebr:$f" ) > "$tmpd/base.wf" 2>/dev/null; then
      gate_ci_rerun_on_hit "$tmpd/base.wf" && rc=0 || rc=$?
    fi
    if [ "$rc" != "1" ]; then rm -rf "$tmpd"; gate_label_ack_park '라벨배포트리거' "기본 브랜치 ${f##*/}"; return 0; fi
  done <<EOF
$( { cd "$wt" && git ls-tree -r --name-only "$basebr" -- .github/workflows; } 2>/dev/null || true)
EOF
  rm -rf "$tmpd"
  # (d) the target's deploy-trigger identifiers: `workflow:` on the files (b)
  # tested, `branch:` on the pull request's head branch, `argv:` on the POST.
  ids=$(target_field "$al" '배포트리거 식별자' 2>/dev/null || true)
  while IFS= read -r id; do
    kind="${id%%:*}"; val="${id#*:}"
    [ -n "$id" ] && [ -n "$val" ] || continue
    case "$kind" in
      workflow)
        [ -n "$wf_name" ] && [ "$val" = "$wf_name" ] && bad="workflow:$val"
        [ -n "$wf_id" ] && [ "$val" = "$wf_id" ] && bad="workflow:$val"
        while IFS= read -r bn; do
          [ -n "$bn" ] || continue
          case "$val" in "$bn"|"${bn%.*}"|"${bn%.*}.yml"|"${bn%.*}.yaml") bad="workflow:$val" ;; esac
        done <<EOF
$x5set
EOF
        ;;
      branch) [ "$val" = "$pref" ] && bad="branch:$val" ;;
      argv)
        case "$(gate_label_ack_argv "$slug" "$pnum" "$label")" in *"$val"*) bad="argv:$val" ;; esac ;;
    esac
    [ -z "$bad" ] || break
  done <<EOF
$(printf '%s' "$ids" | tr ',' '\n' | sed 's/^[[:space:]]*//; s/[[:space:]]*$//')
EOF
  if [ -n "$bad" ]; then gate_label_ack_park '라벨배포트리거' "$bad"; return 0; fi
  # 6 — a label already on the pull request starts nothing when put on again.
  if ! labels=$(gate_ci_rerun_gh pr view "$pnum" -R "$slug" --json labels --jq '.labels[].name' 2>/dev/null); then
    warn "reading the labels of PR $pnum failed — nothing was labelled"
    exit "$GATE_EXIT_RULE"
  fi
  case "
$labels
" in *"
$label
"*) gate_label_ack_park '라벨이미있음' "$check:$label"; return 0 ;; esac
  GATE_LABEL_ACK_VERDICT=eligible
  GATE_LABEL_ACK_PR="$pnum"; GATE_LABEL_ACK_SLUG="$slug"; GATE_LABEL_ACK_HEAD="$h"
  GATE_LABEL_ACK_CHECK="$check"; GATE_LABEL_ACK_LINK="$clink"; GATE_LABEL_ACK_LABEL="$label"
  GATE_LABEL_ACK_RUN="${r:--}"; GATE_LABEL_ACK_WF="${wf_name:--}"; GATE_LABEL_ACK_BASE="$basebr"
  GATE_LABEL_ACK_K=$(( $(cc_ci_round_get "$rd" max) + 1 ))
  return 0
}

gate_label_ack_gh_write() {
  # gate_label_ack_gh_write <credential lines> <gh args...> — `gh` under the
  # WRITE-scoped credential the merge uses, exported inside a subshell only and
  # with the repository named on the command line alone. Never the read-scoped
  # runner: every stage holds that credential, and a label it could POST would
  # put a second way to label around this act.
  local creds="$1" line; shift
  (
    unset GH_REPO GH_HOST GH_ENTERPRISE_TOKEN GITHUB_ENTERPRISE_TOKEN
    while IFS= read -r line; do
      [ -n "$line" ] || continue
      export "$line"
    done <<CREDS
$creds
CREDS
    gh "$@"
  )
}

gate_perform_label_ack() {
  # gate_perform_label_ack <alias> <segment> <argv...> — the request row, one
  # POST, the confirmation and the closing row. No retry, for the rerun's
  # reason: a second POST after an unknown outcome would be a second event.
  local al="$1" seg="$2"; shift 2
  if [ "${GATE_LABEL_ACK_VERDICT:-}" != "eligible" ]; then
    warn "the label act reached its performer without an eligibility verdict — nothing was requested"
    return "$GATE_EXIT_RULE"
  fi
  local slug="$GATE_LABEL_ACK_SLUG" h="$GATE_LABEL_ACK_HEAD" pr="$GATE_LABEL_ACK_PR"
  local check="$GATE_LABEL_ACK_CHECK" oldlink="$GATE_LABEL_ACK_LINK" label="$GATE_LABEL_ACK_LABEL"
  local k="$GATE_LABEL_ACK_K" creds base code tries ok="" screen st
  # THE WRITE CREDENTIAL BEFORE THE ROW: an act that cannot POST leaves no
  # request a person would have to close.
  creds=$(cred_gate_env) || return "$GATE_EXIT_RULE"
  # `기본 브랜치` measured the way the rerun measures it, for the label check.
  base=$(GATE_CI_RERUN_FAILS="fail	${check}	${oldlink}" GATE_CI_RERUN_SLUG="$slug" \
         GATE_CI_RERUN_BASE="$GATE_LABEL_ACK_BASE" gate_ci_rerun_base_evidence)
  local -a common=("세그먼트=$seg" "PR=$pr" "head sha=$h" "처분=라벨")
  local -a rest=("실행=$GATE_LABEL_ACK_RUN" "워크플로=$(gate_row_safe "$GATE_LABEL_ACK_WF" 200)"
    "실패 체크=$(gate_row_safe "$check" "$GATE_CHECKS_FAIL_MAX")" "기본 브랜치=$base")
  local ckf lbf
  ckf=$(gate_row_safe "$check" 200); lbf=$(gate_row_safe "$label" 200)
  gate_append 'CI 처분' "${common[@]}" "상태=요청" "회차=$k" "${rest[@]}" "체크=$ckf" "라벨=$lbf" \
    "응답=-" "관측=$(date -u +%Y-%m-%dT%H:%M:%SZ)" || return $?
  code=$(gate_label_ack_gh_write "$creds" api -X POST -i "repos/$slug/issues/$pr/labels" -f "labels[]=$label" 2>/dev/null \
         | awk 'NR == 1 && /^HTTP\// { print $2; exit }' || true)
  [ -n "$code" ] || code=000
  case "$code" in
    2??)
      # THE OLD FAILURE LEFT THE SCREEN AND A NEW RUN OF THE SAME CHECK CAME:
      # the screen shows one run per name, so a new link under the same name
      # is the run the label started.
      tries=0
      while [ "$tries" -lt "$GATE_LABEL_ACK_CONFIRM_TRIES" ]; do
        screen=$(gate_ci_rerun_checks_tsv "$(gate_ci_rerun_gh pr checks "$pr" -R "$slug" --json name,bucket,link 2>/dev/null || true)" || true)
        st=$(printf '%s\n' "$screen" | GATE_LA_NAME="$check" GATE_LA_OLD="$oldlink" awk -F'\t' '
          $2 == ENVIRON["GATE_LA_NAME"] { if ($3 == ENVIRON["GATE_LA_OLD"]) old = 1; else if ($3 != "") nw = 1 }
          END { print (nw && !old) ? "ok" : "no" }')
        [ "$st" = "ok" ] && { ok=1; break; }
        tries=$(( tries + 1 )); sleep "$GATE_LABEL_ACK_CONFIRM_SLEEP"
      done
      [ -n "$ok" ] || code="$code,화면" ;;
  esac
  if [ -n "$ok" ]; then
    gate_append 'CI 처분' "${common[@]}" "상태=수락" "회차=$k" "${rest[@]}" "체크=$ckf" "라벨=$lbf" \
      "응답=$code" "관측=$(date -u +%Y-%m-%dT%H:%M:%SZ)" || return $?
    log "$seg: 라벨 수락 — 회차 $k, 체크 $check, 라벨 $label"
    return 0
  fi
  gate_append 'CI 처분' "${common[@]}" "상태=실패" "회차=$k" "${rest[@]}" "체크=$ckf" "라벨=$lbf" \
    "응답=$(gate_row_safe "$code" 120)" "관측=$(date -u +%Y-%m-%dT%H:%M:%SZ)" || return $?
  warn "reach park — judgment '라벨요청실패'. The label POST or the new run's confirmation failed (응답=$code) and the gate does not try again"
  gate_park_record '라벨요청실패' 'closed' "$check:$code" "$@"
  return "$GATE_EXIT_PARK"
}

gate_kind_is_bookkeeping() {
  # gate_kind_is_bookkeeping <kind> — the row kinds an `act` performs by
  # APPENDING A ROW and doing nothing else. Every one of them grades `읽기`.
  #
  # THE SET IS SPELLED ONCE. Two readers need it — the dispatch that performs
  # them and the all-met arm that must not refuse them — and when the arm carried
  # no copy at all, the terminal shift could not write the one row the protocol
  # requires it to write.
  #
  # THE TWO OBLIGATION-CLOSING KINDS BELONG HERE AND NOT ON THE ARGV0 TABLE.
  # That table has no row for a `키=값` list, so left out of this set they grade
  # `등급 미상` and are refused — a failure that wears the exact face of the
  # defect they exist to fix, "the obligation cannot be closed", while the code
  # that closes it sits right there. Their grade stays `읽기` for the same reason
  # every other row kind's does: once recording costs authorization budget, the
  # router is pushed toward recording less, and that pressure is what produced
  # the defect in the first place.
  #
  # `limit-cleared` IS HERE FOR THE SEAT'S SAKE. The seat writes it at its own
  # context ceiling as readily as anywhere else — a person saying "the limit is
  # cleared" does not wait for the seat to have room — and it enters no tree.
  # `halt-answer` is here on the same ground: a person's answer to a halt record
  # arrives whenever it arrives, and recording it enters no tree.
  # `review-dismiss` likewise: the merge it unblocks is graded on its own, and
  # `review-carry` on the same ground — the issues it records were opened by
  # acts graded on their own, and the merge after it is graded too.
  # `shift-halt` writes one file under the run directory's `halt/shift/` and one
  # row, and enters no tree. `base-check` reads the remote's ref and merges in
  # an object directory it removes again, and writes one row. `remote-check`
  # reads the remote and writes rows only. `replan` moves one plan file under
  # the run directory aside and writes one row, and enters no tree.
  # `halt-settle` writes one row, claims an attempt number and moves one plan
  # file under the run directory, and enters no tree — and the answer it
  # records arrives whenever a person gives it, deadline or not.
  # `reentry` is here for the seat cap's sake: a boot-time re-entry carries no
  # session id under launchd, so the context reading falls back to the lane's
  # newest transcript, and a large one would refuse the row the reboot-class
  # delay is measured from. It writes one row and enters no tree.
  case "$1" in
    segment|cycle|problem|blocked|clause|judgment|obligation|handoff) return 0 ;;
    obligation-done|obligation-drop|limit-cleared|reentry|halt-answer|review-dismiss|review-carry) return 0 ;;
    shift-halt|base-check|remote-check|replan|halt-settle) return 0 ;;
  esac
  return 1
}

gate_act_enters_resolved_tree() {
  # gate_act_enters_resolved_tree <verb> <kind> — whether this act will `cd` into
  # the tree the segment resolution picked. The dispatch switch below is the one
  # that decides it, so this answers with the switch's own classification rather
  # than with a second list of names.
  #
  # NAMING THE VERBS INSTEAD WAS THE DEFECT. The worktree predicate used to fire
  # for `kind = skill` and `verb = exec` only, while the switch sends everything
  # but the bookkeeping kinds, `propose-done` and `router-shift` to the read-only
  # runner — which `cd`s into the same resolved tree. So the kinds left out USED
  # that resolution without passing the predicate that protects it, and `merge`
  # is one of them: a segment row naming another repository's worktree sent a
  # `git push` to the target's main tree with nothing said.
  #
  # AND `merge` IS NOT RECOGNISED BY ITS KIND. The anchor check and the review
  # obligation issuer both key on `--cutpoint 머지`, so any kind at all wearing
  # that cutpoint is a merge. "The router does not emit `--kind merge`" is
  # therefore no defence, and any enumeration of names has the same hole one
  # kind later.
  #
  # `plan` IS CLASSIFIED WITH `act`. A forecast has to answer for the act it
  # names, and splitting them here would recreate the band where `plan` says
  # 통과 예상 and the `act` behind it exits. `exec` takes no `--kind`, so its
  # second argument is always empty and falls through to the general answer.
  case "$1" in exec) return 0 ;; esac
  # `apply` makes its own worktree at the merge commit and enters no other; the
  # segment row's tree is the pre-merge branch and is routinely gone by then.
  case "$2" in propose-done|router-shift|apply) return 1 ;; esac
  gate_kind_is_bookkeeping "$2" && return 1
  return 0
}

# ---------------------------------------------------------------------------
# A target's own Bash hook — `admit`, the refusal rows, the repeat block and
# the remote state.
#
# A target repository may carry a PreToolUse Bash hook of its own. The harness
# runs it beside this run's hook on every Bash call and a deny from either one
# wins, so a guard that reads the act's words refuses a gate call carrying them,
# while this run's hook refuses everything that is not a gate call. The two
# allowed sets are disjoint and the run cannot push at all. The second allowed
# shape is the way through: the session issues the command bare, the run hook
# records the bytes as a request and refuses them, `admit` grades those bytes
# exactly as `exec` would, writes the row and leaves a one-use ticket, and the
# same bytes issued again pass the run hook on the ticket while the target's
# hook judges them for real. Nothing here runs the act.
#
# THE SERIES. `대상 거절` is a refusal the target's hook made or is predicted to
# make, keyed on target, segment, act digest and form (`감쌈` for a gate call,
# `맨` for a bare command) and carrying the condition it was recorded under.
# `대상 훅` is a root's hook digest, written when the root is first seen with a
# hook and whenever the digest moves. `원격 판독` is what the remote says about
# a segment's branch and pull request, written when a value changes. `맨 명령
# 결과` closes an admitted remote act once the remote shows its effect.
#
# THE CONDITION is the sha256 of five things a refusal can depend on: the
# issuing root's hook digest, the segment worktree's HEAD, the remote tip and
# the pull request as the last `원격 판독` row of the segment reads them, and
# the segment's last `중단 답` row. Time and the number of shifts do not move
# it, so the same refusal is not met again until one of the five moves.
# ---------------------------------------------------------------------------
GATE_ADMIT_TTL=300
GATE_ADMIT_SETTLE_AFTER=30

gate_admit_load() {
  # gate_admit_load <id|last> — reads the calling stage's or shift's live
  # request into the GATE_ADMIT_* globals and prints its bytes. Exit 3 when the
  # call has no caller key, there is no request, it expired (it is removed) or
  # it is not the one named; exit 2 when its directory is gone.
  local want="$1" f now rec rid rcaller
  GATE_ADMIT_CALLER=$(gate_thp thp_caller_key)
  if [ -z "$GATE_ADMIT_CALLER" ]; then
    warn "admit reads the request of the calling stage or shift, and this call carries neither CC_PIPELINE_STAGE_ID nor CC_PIPELINE_SHIFT_ID"
    exit "$GATE_EXIT_RULE"
  fi
  GATE_ADMIT_KEY=$(gate_thp thp_key_norm "$GATE_ADMIT_CALLER")
  f="$RUN_DIR/admit/req/$GATE_ADMIT_KEY"
  if [ ! -f "$f" ] || [ -L "$f" ]; then
    warn "there is no live request for $GATE_ADMIT_CALLER — issue the command bare first: the run hook refuses it and records it as the request this verb reads"
    exit "$GATE_EXIT_RULE"
  fi
  now=$(date -u +%s)
  rec=$(jq -r '.recorded // 0' "$f" 2>/dev/null || true)
  case "$rec" in ''|*[!0-9]*) rec=0 ;; esac
  if [ $((rec + GATE_ADMIT_TTL)) -le "$now" ]; then
    rm -f "$f"
    warn "the request of $GATE_ADMIT_CALLER expired ${GATE_ADMIT_TTL} seconds after it was recorded and is removed — issue the command bare again, then admit"
    exit "$GATE_EXIT_RULE"
  fi
  rid=$(jq -r '.id // empty' "$f" 2>/dev/null || true)
  rcaller=$(jq -r '.caller // empty' "$f" 2>/dev/null || true)
  if [ -z "$rid" ] || [ "$rcaller" != "$GATE_ADMIT_CALLER" ]; then
    warn "the request file of $GATE_ADMIT_CALLER does not read as this caller's request — issue the command bare again"
    exit "$GATE_EXIT_RULE"
  fi
  if [ "$want" != "last" ] && [ "$want" != "$rid" ]; then
    warn "the live request of $GATE_ADMIT_CALLER is $rid, not $want — a newer bare command replaced it; admit $rid or issue the command again"
    exit "$GATE_EXIT_RULE"
  fi
  GATE_ADMIT_FILE="$f"
  GATE_ADMIT_REQ_ID="$rid"
  # The bytes through a sentinel, so a trailing newline is not lost to `$( )`.
  GATE_ADMIT_BYTES=$(jq -j '.command_b64 | @base64d' "$f" 2>/dev/null; printf x)
  GATE_ADMIT_BYTES=${GATE_ADMIT_BYTES%x}
  GATE_ADMIT_CWD=$(jq -r '.cwd // empty' "$f" 2>/dev/null || true)
  GATE_ADMIT_PDIR=$(jq -r '.project_dir // empty' "$f" 2>/dev/null || true)
  printf '요청 %s: %s\n' "$rid" "$GATE_ADMIT_BYTES"
  if [ -z "$GATE_ADMIT_CWD" ] || [ ! -d "$GATE_ADMIT_CWD" ]; then
    warn "the directory the request was issued from is gone: '${GATE_ADMIT_CWD:-(none)}'"
    exit "$GATE_EXIT_VOCAB"
  fi
  if [ -z "$GATE_ADMIT_PDIR" ] || [ ! -d "$GATE_ADMIT_PDIR" ]; then
    warn "the request carries no session root (CLAUDE_PROJECT_DIR was not in the hook's environment), so no ticket could be tied to the repository whose hook judges the command — use the exec form"
    exit "$GATE_EXIT_RULE"
  fi
}

gate_admit_pred_passes() {
  # gate_admit_pred_passes <prediction> — whether admit issues a ticket on what
  # the issuing root's hooks are predicted to answer: a pass, or a hook failure
  # the harness does not block on. A probe timeout, a refusal, a defer and
  # `판정 불가` are recorded as a refusal instead.
  case "$1" in
    통과|'비차단 오류') return 0 ;;
    *) return 1 ;;
  esac
}

gate_admit_words() {
  # gate_admit_words — splits the request's bytes with the closed grammar into
  # GATE_ADMIT_WORDS. Exit 2 when the line is not one the grammar reads: the
  # gate grades words, and a line whose words depend on a shell's expansion
  # would be graded as one act and run as another.
  local tf w
  GATE_ADMIT_WORDS=()
  tf=$(mktemp "${TMPDIR:-/tmp}/gate-admit.XXXXXX") || die "could not create a temporary file for the request's words"
  if ! gate_thp thp_closed_words "$GATE_ADMIT_BYTES" >"$tf"; then
    rm -f "$tf"
    warn "the request is not one plain command line — admit reads words split on blanks, '…' verbatim, \"…\" holding no \$ \` \\ or !, and outside quotes only letters, digits, non-ASCII and _@%+=:,./- with no leading NAME=, no word starting with an unquoted =, no leading ~ and no * ? [ { #"
    warn "issue such an act through exec instead"
    exit "$GATE_EXIT_VOCAB"
  fi
  while IFS= read -r -d '' w; do GATE_ADMIT_WORDS+=("$w"); done <"$tf"
  rm -f "$tf"
  if [ "${#GATE_ADMIT_WORDS[@]}" -eq 0 ]; then
    warn "the request holds no command"
    exit "$GATE_EXIT_VOCAB"
  fi
}

gate_admit_words_push() {
  # gate_admit_words_push — true when the request's words are a git command
  # with `push` among them. A push behind a wrapper never reaches here:
  # `gate_admit_wrapped_push_refuse` refuses it first.
  local w
  [ "${GATE_ADMIT_WORDS[0]##*/}" = "git" ] || return 1
  for w in "${GATE_ADMIT_WORDS[@]}"; do
    [ "$w" != "push" ] || return 0
  done
  return 1
}

gate_admit_wrapped_push_refuse() {
  # gate_admit_wrapped_push_refuse — exits 2 when the request is a push behind
  # a wrapper. The grader strips `env`, `command`, `nice` and the rest and
  # grades the push inside, but the refspec check and the ticket's binding to
  # the repository's state read the git command's own words, which a wrapper
  # moves — so a wrapped push would leave with neither. Refused before it is
  # graded, so no row and no ticket is written for it.
  [ "${GATE_ADMIT_WORDS[0]##*/}" != "git" ] || return 0
  case "$(gate_push_unwrap_of_argv0 "${GATE_ADMIT_WORDS[@]}" 2>/dev/null)" in
    ''|해당없음) return 0 ;;
  esac
  warn "this push runs behind '${GATE_ADMIT_WORDS[0]##*/}', and a ticket binds a push to the repository state the gate graded only when the command starts with git itself"
  warn "issue the push as the plain git command (git push origin <branch>), with nothing before git, then admit it again"
  exit "$GATE_EXIT_VOCAB"
}

gate_admit_git_dir() {
  # gate_admit_git_dir <argv…> — the directory a git command runs in: the
  # request's directory, moved by every `-C <dir>` before the subcommand, and
  # the repository `--git-dir` names when it names one — that is the repository
  # whose HEAD and refs the push reads, wherever the command runs. A relative
  # `--git-dir` is git's own: read from the directory every `-C` led to.
  local w prev="" dir="$GATE_ADMIT_CWD" gd=""
  shift
  for w in "$@"; do
    case "$prev" in
      -C) case "$w" in /*) dir="$w" ;; *) dir="$dir/$w" ;; esac ;;
      --git-dir) gd="$w" ;;
      -c|--work-tree|--namespace) ;;
      *)
        case "$w" in
          --git-dir=*) gd="${w#--git-dir=}" ;;
          -*) ;;
          *) break ;;
        esac ;;
    esac
    prev="$w"
  done
  if [ -n "$gd" ]; then
    case "$gd" in /*) dir="$gd" ;; *) dir="$dir/$gd" ;; esac
  fi
  printf '%s' "$dir"
}

gate_admit_head_refspec_ok() {
  # gate_admit_head_refspec_ok <segment> <argv…> — status 2 for a bare push
  # that takes its source from the checked-out branch, from a directory that is
  # not the segment's worktree. A bare command runs in the session's own
  # directory — on the router path the target's main worktree — and there
  # `HEAD`, `@`, and a push naming no refspec at all (`--all` and `--mirror`
  # too) all push that tree's branches, not the segment's. `git -C <dir>` moves
  # the directory; a remote named by `--repo` makes the first operand a refspec.
  local seg="$1" w pushed=0 head=0 refspec=0 pos=0 repo=0 skip=0 dir wt top
  shift
  [ "${1##*/}" = "git" ] || return 0
  dir=$(gate_admit_git_dir "$@")
  shift
  for w in "$@"; do
    if [ "$pushed" = "0" ]; then
      [ "$w" != "push" ] || pushed=1
      continue
    fi
    if [ "$skip" = "1" ]; then skip=0; continue; fi
    case "$w" in
      -o|--push-option|--receive-pack|--exec) skip=1 ;;
      --repo) skip=1; repo=1 ;;
      --repo=*) repo=1 ;;
      --all|--mirror|--branches) head=1 ;;
      --tags) refspec=1 ;;
      -*) ;;
      *)
        pos=$((pos + 1))
        if [ "$pos" -gt 1 ] || [ "$repo" = "1" ]; then
          refspec=1
          case "$w" in HEAD|HEAD:*|+HEAD|+HEAD:*|@|@:*|+@|+@:*) head=1 ;; esac
        fi ;;
    esac
  done
  [ "$pushed" = "1" ] || return 0
  [ "$refspec" = "1" ] || head=1
  [ "$head" = "1" ] || return 0
  wt=$(gate_segment_worktree "$seg" 2>/dev/null || true)
  top=$( { cd "$dir" 2>/dev/null && git rev-parse --show-toplevel 2>/dev/null; } || true)
  if [ -n "$wt" ] && [ -n "$top" ] && [ "$(gate_thp thp_phys "$top")" = "$(gate_thp thp_phys "$wt")" ]; then
    return 0
  fi
  warn "this push takes its source from the branch checked out where it runs ('${top:-$dir}'), which is not the worktree of segment $seg — it names HEAD or @, or names no branch at all"
  warn "name the remote and the branch (git push origin <branch>) or point git at the segment's worktree with -C, then issue it bare again"
  return "$GATE_EXIT_VOCAB"
}

gate_target_has_bash_hook() {
  # gate_target_has_bash_hook <root> — true when a session started at <root>
  # gets a PreToolUse Bash hook from the project settings, or when those
  # settings cannot be read (an unreadable guard is not an absent one).
  local root="$1" hooks rc=0
  [ -n "$root" ] && [ -d "$root" ] || return 1
  hooks=$(gate_thp thp_bash_hooks "$root" 2>/dev/null) || rc=$?
  [ -n "$hooks" ] || [ "$rc" -ne 0 ]
}

gate_admit_root_rule() {
  # gate_admit_root_rule <alias> — the issuing-root rule. The hook that judges a
  # session's Bash is the one under the root that session started at; when the
  # target carries a Bash hook and the request's root does not share the
  # target's common git directory, that hook never saw the command, so the
  # bare form would pass a guard that did not judge it. Exit 3 then. A target
  # with no hook needs no such check: the root's own guard judged the command.
  local al="$1" mw tcd rcd
  mw=$(target_field "$al" '메인 워크트리' 2>/dev/null || true)
  gate_target_has_bash_hook "$mw" || return 0
  tcd=$(gate_thp thp_common_dir "$mw")
  rcd=$(gate_thp thp_common_dir "$GATE_ADMIT_PDIR")
  if [ -n "$rcd" ] && [ "$rcd" = "$tcd" ]; then return 0; fi
  warn "target '$al' carries its own Bash hook, and the session that issued this request started at '$GATE_ADMIT_PDIR', which is not a checkout of that repository — that hook never judged the command"
  warn "issue the act from a session started in the target's repository; a session started elsewhere cannot reach this target above 커밋 through the bare form"
  exit "$GATE_EXIT_RULE"
}

gate_target_hook_row() {
  # gate_target_hook_row <alias> <root> — writes a `대상 훅` row the first
  # time a root is seen with a hook and whenever its hook digest moves. A root
  # that never had a hook writes nothing.
  local al="$1" root="$2" dc d c last
  [ -n "$root" ] && [ -d "$root" ] || return 0
  root=$(gate_thp thp_phys "$root")
  dc=$(gate_thp thp_hook_digest "$root")
  d=${dc%% *}; c=${dc#* }
  last=$(gate_rows '대상 훅' | gate_rows_field_eq '루트' "$root" | tail -1)
  if [ -z "$last" ]; then
    [ "$d" != "-" ] || return 0
  elif [ "$(gate_row_field "$last" '다이제스트')" = "$d" ]; then
    return 0
  fi
  gate_append '대상 훅' "대상=$al" "루트=$root" "다이제스트=$d" "훅 수=$c" "기록 시각=$(now_iso)"
}

gate_segment_branch() {
  # gate_segment_branch <segment> — the branch the segment row names, else the
  # branch its worktree is on; empty when neither answers.
  local seg="$1" br wt
  # The last value any of the segment's rows carried — a later state row does
  # not repeat it — read the way `gate_review_line` reads it.
  br=$(gate_rows 'segment' | gate_rows_field_eq 'id' "$seg" | gate_rows_field_values '브랜치' \
       | awk 'NF { v = $0 } END { print v }')
  if [ -z "$br" ] || [ "$br" = "-" ]; then
    wt=$(gate_segment_worktree "$seg" 2>/dev/null || true)
    # Only an absolute directory: a row may carry `-` or `(없음)`, and `cd -`
    # goes to OLDPWD and prints it, which put a path into the snapshot's JSON.
    case "$wt" in /*) ;; *) wt="" ;; esac
    br=$( { [ -n "$wt" ] && [ -d "$wt" ] && cd "$wt" 2>/dev/null && git branch --show-current 2>/dev/null; } || true)
  fi
  printf '%s' "$br"
}

gate_json_str_or_null() {
  # gate_json_str_or_null <value> — a JSON string, or `null` when the value is
  # empty or `-`.
  case "$1" in ''|-) printf 'null' ;; *) printf '"%s"' "$(gate_json_escape "$1")" ;; esac
}

gate_remote_last_row() {
  # gate_remote_last_row <segment> — the segment's last `원격 판독` row.
  gate_rows '원격 판독' | gate_rows_field_eq '세그먼트' "$1" | tail -1
}

gate_remote_last_known_row() {
  # gate_remote_last_known_row <segment> — the segment's last `원격 판독` row
  # whose `원격 팁` is not `미상`. A read that could not reach the remote is
  # written as a change, but it observed nothing, so a ticket's before and
  # after are both taken from the reads that did.
  gate_rows '원격 판독' | gate_rows_field_eq '세그먼트' "$1" \
    | awk -F' [|] ' '{ k = 1; for (i = 1; i <= NF; i++) if ($i == "원격 팁=미상") k = 0; if (k) r = $0 } END { if (r != "") print r }'
}

gate_refusal_condition() {
  # gate_refusal_condition <alias> <segment> <root> — computes the condition
  # into GATE_COND and its five elements into GATE_COND_HOOK, GATE_COND_HEAD,
  # GATE_COND_TIP, GATE_COND_PR and GATE_COND_ANSWER.
  local al="$1" seg="$2" root="$3" wt rr ar
  GATE_COND_HOOK='-'; GATE_COND_ROOT='-'
  if [ -n "$root" ] && [ "$root" != "-" ] && [ -d "$root" ]; then
    GATE_COND_ROOT=$(gate_thp thp_phys "$root")
    GATE_COND_HOOK=$(gate_thp thp_hook_digest "$GATE_COND_ROOT" | awk '{print $1}')
  fi
  GATE_COND_HEAD='-'; GATE_COND_TIP='-'; GATE_COND_PR='-'; GATE_COND_ANSWER='-'
  if [ -n "$seg" ] && [ "$seg" != "-" ]; then
    wt=$(gate_segment_worktree "$seg" 2>/dev/null || true)
    GATE_COND_HEAD=$(gate_worktree_tip "$wt" 2>/dev/null || printf -- '-')
    rr=$(gate_remote_last_row "$seg")
    if [ -n "$rr" ]; then
      GATE_COND_TIP=$(gate_row_field "$rr" '원격 팁')
      GATE_COND_PR="$(gate_row_field "$rr" 'PR')/$(gate_row_field "$rr" 'PR 상태')/$(gate_row_field "$rr" 'PR HEAD')"
    fi
    ar=$(gate_rows '중단 답' | gate_rows_field_eq '세그먼트' "$seg" | tail -1)
    [ -z "$ar" ] || GATE_COND_ANSWER=$(printf '%s' "$ar" | shasum -a 256 | cut -c1-16)
  fi
  GATE_COND=$(printf '%s\n%s\n%s\n%s\n%s\n' "$GATE_COND_HOOK" "$GATE_COND_HEAD" "$GATE_COND_TIP" \
    "$GATE_COND_PR" "${GATE_COND_ANSWER:--}" | shasum -a 256 | cut -d' ' -f1)
}

gate_refusal_row() {
  # gate_refusal_row <alias> <segment> <actor> <form> <basis> <act digest>
  #   <bytes> <text> [<판정>] — writes one `대상 거절` row under the condition
  # GATE_COND holds, once per (target, segment, digest, form, condition); the
  # whole command goes to the `refused.<n>` file beside the ledger rows.
  local al="$1" seg="$2" actor="$3" form="$4" basis="$5" dig="$6" bytes="$7" text="$8" verdict="${9:-}"
  local n side
  if gate_has_row '대상 거절' "대상=$al" "세그먼트=$seg" "행위 다이제스트=$dig" "형태=$form" "조건=$GATE_COND"; then
    return 0
  fi
  n=$(gate_rows '대상 거절' | gate_count)
  n=$((n + 1))
  side="refused.$n"
  printf '%s' "$bytes" > "$RUN_DIR/$side" 2>/dev/null || side='-'
  gate_append '대상 거절' "대상=$al" "세그먼트=$seg" "행위자=$actor" "형태=$form" "근거=$basis" \
    ${verdict:+"판정=$verdict"} "행위 다이제스트=$dig" "명령=$(gate_row_safe "$bytes" 120)" "곁파일=$side" \
    "거절 문면=$(gate_row_safe "${text:-미상}" 160)" "조건=$GATE_COND" "루트=$GATE_COND_ROOT" "훅 다이제스트=$GATE_COND_HOOK" \
    "HEAD=$GATE_COND_HEAD" "원격 팁=$GATE_COND_TIP" "PR=$GATE_COND_PR" "중단 답=$GATE_COND_ANSWER" \
    "기록 시각=$(now_iso)"
}

gate_refusal_block() {
  # gate_refusal_block <alias> <segment> <act digest> <form> — exit 3 when the
  # last refusal row of this key was recorded under the condition that holds
  # now. Nothing the refusal could depend on has moved, so the same call meets
  # the same refusal; the message names what would move it. The hook element is
  # read again at the root the row names, which is the root whose hook refused.
  local al="$1" seg="$2" dig="$3" form="$4" row
  row=$(gate_rows '대상 거절' | gate_rows_field_eq '대상' "$al" | gate_rows_field_eq '세그먼트' "$seg" \
        | gate_rows_field_eq '행위 다이제스트' "$dig" | gate_rows_field_eq '형태' "$form" | tail -1)
  [ -n "$row" ] || return 0
  gate_refusal_condition "$al" "$seg" "$(gate_row_field "$row" '루트')"
  [ "$(gate_row_field "$row" '조건')" = "$GATE_COND" ] || return 0
  warn "the target's own Bash hook refused this act before, and nothing it could depend on has moved since: $(gate_row_safe "$row" 400)"
  warn "it opens again when one of these moves: the issuing root's hook digest (the guard script or settings.local.json — not settings.json while the run is open), the segment worktree's HEAD (a commit), the remote tip or the pull request (remote-check reads them), or a 재시도 answer to the 대상 훅 거절 halt"
  exit "$GATE_EXIT_RULE"
}

gate_guard_refusals_json() {
  # The snapshot's `guard_refusals[]`: one element per (target, segment, act
  # digest, form), from its last `대상 거절` row, newest first, at most 20 —
  # `대상`, `세그먼트`, `형태`, `근거`, `행위 다이제스트`, `명령`, `거절 문면`
  # and `조건` (`같음` while the recorded condition still holds, else `바뀜`).
  local out
  out=$( { gate_rows '대상 거절' || true; } | awk '{ r[NR] = $0 } END { for (i = NR; i >= 1; i--) print r[i] }' \
         | { gseen=""; gn=0
           # `continue` past the cap rather than `break`: a reader that stops
           # early leaves the writer a broken pipe, and under pipefail that
           # fails the substitution.
           while IFS= read -r row; do
             [ -n "$row" ] || continue
             [ "$gn" -lt 20 ] || continue
             gt=$(gate_row_field "$row" '대상'); gs=$(gate_row_field "$row" '세그먼트')
             gd=$(gate_row_field "$row" '행위 다이제스트'); gf=$(gate_row_field "$row" '형태')
             gk="$gt|$gs|$gd|$gf"
             # An if, not a case: bash 3.2 closes `$( … )` at a pattern's `)`.
             if [ "${gseen#*"<$gk>"}" != "$gseen" ]; then continue; fi
             gseen="$gseen<$gk>"
             gn=$((gn + 1))
             gate_refusal_condition "$gt" "$gs" "$(gate_row_field "$row" '루트')"
             gc='바뀜'; [ "$(gate_row_field "$row" '조건')" != "$GATE_COND" ] || gc='같음'
             printf '    {"대상": "%s", "세그먼트": "%s", "형태": "%s", "근거": "%s", "행위 다이제스트": "%s", "명령": "%s", "거절 문면": "%s", "조건": "%s"},\n' \
               "$(gate_json_escape "$gt")" "$(gate_json_escape "$gs")" "$(gate_json_escape "$gf")" \
               "$(gate_json_escape "$(gate_row_field "$row" '근거')")" "$(gate_json_escape "$gd")" \
               "$(gate_json_escape "$(gate_row_field "$row" '명령')")" \
               "$(gate_json_escape "$(gate_row_field "$row" '거절 문면')")" "$gc"
           done; } )
  [ -n "$out" ] || return 0
  printf '%s\n' "${out%,}"
}

gate_refused_flag() {
  # gate_refused_flag <bytes> <flag> — the word after <flag> in the part of a
  # recorded gate call before its first `--`, quotes stripped; empty when the
  # flag is not there or names a variable rather than a value.
  local s="$1" want="$2" w prev="" out=""
  s=${s%% -- *}
  set -f
  # shellcheck disable=SC2086
  for w in $s; do
    w=$(printf '%s' "$w" | tr -d "\"'")
    if [ "$prev" = "$want" ]; then out="$w"; break; fi
    prev="$w"
  done
  set +f
  case "$out" in *'$'*) out="" ;; esac
  printf '%s' "$out"
}

gate_refused_drain() {
  # gate_refused_drain — turns the run hook's records under `admit/refused/`
  # into `대상 거절 형태=감쌈 근거=예측` rows, the way `checks.observed` is
  # drained: the hook writes no row, and this is the writer. The act digest is
  # read from the words after the record's first unquoted `--`.
  local d="$RUN_DIR/admit/refused" f tg sg bytes inner dig v t pd kind actor
  [ -d "$d" ] || return 0
  for f in "$d"/*/*; do
    [ -f "$f" ] || continue
    case "${f##*/}" in .tmp.*) continue ;; esac
    tg=$(jq -r '.target // empty' "$f" 2>/dev/null || true)
    sg=$(jq -r '.segment // empty' "$f" 2>/dev/null || true)
    pd=$(jq -r '.project_dir // empty' "$f" 2>/dev/null || true)
    v=$(jq -r '.verdict // empty' "$f" 2>/dev/null || true)
    t=$(jq -r '.text // empty' "$f" 2>/dev/null || true)
    kind=$(jq -r '.caller_kind // empty' "$f" 2>/dev/null || true)
    bytes=$(jq -j '.command_b64 // "" | @base64d' "$f" 2>/dev/null; printf x)
    bytes=${bytes%x}
    inner=$(gate_thp thp_after_dashdash "$bytes" 2>/dev/null) || inner="$bytes"
    dig=$(gate_thp thp_act_digest "$inner")
    case "$kind" in stage) actor='스테이지' ;; shift) actor='교대' ;; *) actor='미상' ;; esac
    # A shift carries no target or segment in its environment; the call's own
    # `--target` and `--segment` name them.
    [ -n "$tg" ] || tg=$(gate_refused_flag "$bytes" --target)
    [ -n "$sg" ] || sg=$(gate_refused_flag "$bytes" --segment)
    [ -n "$tg" ] || tg='-'
    [ -n "$sg" ] || sg='-'
    gate_target_hook_row "$tg" "$pd"
    gate_refusal_condition "$tg" "$sg" "$pd"
    gate_refusal_row "$tg" "$sg" "$actor" 감쌈 예측 "$dig" "$bytes" "${v:-거절}: ${t:-미상}"
    rm -f "$f"
  done
}

gate_remote_tip_of() {
  # gate_remote_tip_of <slug> <branch> <dir> — the tip the remote reports for
  # the branch, `없음` when it has none, `미상` when the read fails. The same
  # read `gate_base_remote_tip` makes, from <dir> so a repository's own URL
  # rewriting applies.
  local slug="$1" br="$2" dir="$3" out sha
  if ! out=$(cd "$dir" 2>/dev/null && GIT_TERMINAL_PROMPT=0 git ls-remote "https://github.com/$slug.git" "refs/heads/$br" 2>/dev/null); then
    printf '미상'; return 0
  fi
  sha=$(printf '%s\n' "$out" | GATE_FEQ_V="refs/heads/$br" awk '$2 == ENVIRON["GATE_FEQ_V"] { n++; s = $1 } END { if (n == 1) print s }')
  case "$sha" in
    '') printf '없음' ;;
    *[!0-9a-f]*) printf '미상' ;;
    *) printf '%s' "$sha" ;;
  esac
}

gate_remote_gh() {
  # The `gh` program the pull-request read runs, resolved at call time. A stub
  # ahead on the caller's PATH cannot stand in for it, for the reason
  # `gate_metrics_gh` gives: run.sh puts the system prefixes first, so on the
  # Ubuntu CI runner /usr/bin/gh wins, its read of a fixture slug fails, and
  # every pull-request field reads `미상`. A test names the stub here instead.
  printf '%s' "${CC_REMOTE_GH:-gh}"
}

gate_remote_pr_of() {
  # gate_remote_pr_of <slug> <branch> <dir> <head> — `<번호>\t<상태>\t<HEAD>`
  # for the segment's pull request: the open one; when there is none, the
  # merged one whose head is <head>; `없음` fields when neither exists;
  # `불일치` when two are open; `미상` when the read fails. A closed,
  # unmerged pull request is never the segment's.
  local slug="$1" br="$2" dir="$3" head="$4" json gh
  gh=$(gate_remote_gh)
  if ! json=$(cd "$dir" 2>/dev/null && GH_PROMPT_DISABLED=1 "$gh" pr list -R "$slug" --head "$br" --state all \
                --json number,state,headRefOid 2>/dev/null); then
    printf '미상\t미상\t미상'; return 0
  fi
  printf '%s' "$json" | jq -r --arg h "$head" '
    if type != "array" then "미상\t미상\t미상"
    else ([ .[] | select(.state == "OPEN") ]) as $o
      | if ($o | length) > 1 then "불일치\t불일치\t불일치"
        elif ($o | length) == 1 then "\($o[0].number)\tOPEN\t\($o[0].headRefOid)"
        else ([ .[] | select(.state == "MERGED" and .headRefOid == $h) ]) as $m
          | if ($m | length) > 0 then "\($m[0].number)\tMERGED\t\($m[0].headRefOid)"
            else "없음\t없음\t없음" end
        end
    end' 2>/dev/null || printf '미상\t미상\t미상'
}

gate_remote_state_one() {
  # gate_remote_state_one <alias> <segment> — reads the segment's branch tip
  # and pull request and writes a `원격 판독` row when a value changed, then
  # settles the segment's used tickets. A failed read is `미상`, not a refusal.
  local al="$1" seg="$2" slug br wt dir head tip prl prn prs prh last
  slug=$(target_field "$al" '원격 슬러그' 2>/dev/null || true)
  br=$(gate_segment_branch "$seg")
  [ -n "$slug" ] && [ -n "$br" ] || return 0
  wt=$(gate_segment_worktree "$seg" 2>/dev/null || true)
  dir="$wt"
  [ -n "$dir" ] && [ -d "$dir" ] || dir=$(target_field "$al" '메인 워크트리' 2>/dev/null || true)
  [ -n "$dir" ] && [ -d "$dir" ] || return 0
  head=$(gate_worktree_tip "$wt" 2>/dev/null || printf '미상')
  tip=$(gate_remote_tip_of "$slug" "$br" "$dir")
  prl=$(gate_remote_pr_of "$slug" "$br" "$dir" "$head")
  prn=$(printf '%s' "$prl" | cut -f1); prs=$(printf '%s' "$prl" | cut -f2); prh=$(printf '%s' "$prl" | cut -f3)
  last=$(gate_remote_last_row "$seg")
  if [ -z "$last" ] || [ "$(gate_row_field "$last" '워크트리 HEAD')" != "$head" ] \
     || [ "$(gate_row_field "$last" '원격 팁')" != "$tip" ] || [ "$(gate_row_field "$last" 'PR')" != "$prn" ] \
     || [ "$(gate_row_field "$last" 'PR 상태')" != "$prs" ] || [ "$(gate_row_field "$last" 'PR HEAD')" != "$prh" ] \
     || [ "$(gate_row_field "$last" '브랜치')" != "$br" ]; then
    gate_append '원격 판독' "세그먼트=$seg" "브랜치=$br" "워크트리 HEAD=$head" "원격 팁=$tip" \
      "PR=$prn" "PR 상태=$prs" "PR HEAD=$prh" "판독 시각=$(now_iso)"
  fi
  # A read both halves answered is stamped, so settlement can tell a remote
  # that did not move from one nobody read.
  if [ "$tip" != "미상" ] && [ "$prn" != "미상" ]; then
    mkdir -p "$RUN_DIR/admit/read" 2>/dev/null && touch "$RUN_DIR/admit/read/$(gate_thp thp_key_norm "$seg")" 2>/dev/null || true
  fi
  gate_admit_settle "$seg"
}

gate_remote_state_refresh() {
  # gate_remote_state_refresh <alias> [<segment>] — the remote state of one
  # segment, or of every non-terminal segment of the target, read inside this
  # process and written as `원격 판독` rows; the checks file is drained too, so
  # the poller's last observation of the same pull request is on the ledger.
  local al="$1" seg="${2:-}" s
  if [ -n "$seg" ] && [ "$seg" != "-" ]; then
    gate_remote_state_one "$al" "$seg"
  else
    for s in $(gate_segment_ids); do
      gate_segment_terminal "$s" && continue
      gate_segment_worktree_of_target "$s" "$al" >/dev/null 2>&1 || continue
      gate_remote_state_one "$al" "$s"
    done
  fi
  gate_drain_checks
}

gate_remote_stage() {
  # gate_remote_stage <segment> — `push 필요 | PR 필요 | PR 있음 | 머지됨 |
  # 불일치 | 미상`, from the last `원격 판독` row against the live HEAD. A row
  # whose worktree HEAD is not the live one is stale, and stale reads `미상`.
  local seg="$1" row wt head tip prn prs prh
  row=$(gate_remote_last_row "$seg")
  [ -n "$row" ] || { printf '미상'; return 0; }
  wt=$(gate_segment_worktree "$seg" 2>/dev/null || true)
  head=$(gate_worktree_tip "$wt" 2>/dev/null || true)
  tip=$(gate_row_field "$row" '원격 팁')
  prn=$(gate_row_field "$row" 'PR'); prs=$(gate_row_field "$row" 'PR 상태'); prh=$(gate_row_field "$row" 'PR HEAD')
  if [ -z "$head" ] || [ "$(gate_row_field "$row" '워크트리 HEAD')" != "$head" ] \
     || [ "$tip" = "미상" ] || [ "$prn" = "미상" ]; then
    printf '미상'; return 0
  fi
  [ "$prn" != "불일치" ] || { printf '불일치'; return 0; }
  [ "$prs" != "MERGED" ] || { printf '머지됨'; return 0; }
  if [ "$tip" = "없음" ]; then printf 'push 필요'; return 0; fi
  if [ "$tip" != "$head" ]; then
    if ( cd "$wt" 2>/dev/null && git merge-base --is-ancestor "$tip" "$head" 2>/dev/null ); then
      printf 'push 필요'
    else
      printf '불일치'
    fi
    return 0
  fi
  if [ "$prn" = "없음" ]; then printf 'PR 필요'; return 0; fi
  if [ "$prh" = "$head" ]; then printf 'PR 있음'; else printf '불일치'; fi
}

gate_admit_settle() {
  # gate_admit_settle <segment> — L3: the segment's tickets consumed more than
  # GATE_ADMIT_SETTLE_AFTER seconds ago are settled against the remote state.
  # A remote write whose effect shows writes `맨 명령 결과 판정=관측`; one whose
  # effect does not writes `대상 거절 형태=맨 근거=추정 판정=추정`; a read
  # writes `맨 명령 결과 판정=미상`. Settled tickets move to `admit/settled/`.
  local seg="$1" f now mt kind row before after al dig bytes rid tid actor pd rd
  [ -d "$RUN_DIR/admit/used" ] || return 0
  now=$(date -u +%s)
  for f in "$RUN_DIR"/admit/used/*; do
    [ -f "$f" ] || continue
    [ "$(jq -r '.segment // empty' "$f" 2>/dev/null || true)" = "$seg" ] || continue
    mt=$(gate_mtime "$f"); [ -n "$mt" ] || continue
    [ $((now - mt)) -gt "$GATE_ADMIT_SETTLE_AFTER" ] || continue
    kind=$(jq -r '.remote // "-"' "$f" 2>/dev/null || printf -- '-')
    al=$(jq -r '.target // "-"' "$f" 2>/dev/null || printf -- '-')
    dig=$(jq -r '.digest // "-"' "$f" 2>/dev/null || printf -- '-')
    rid=$(jq -r '.request // "-"' "$f" 2>/dev/null || printf -- '-')
    tid=$(jq -r '.id // "-"' "$f" 2>/dev/null || printf -- '-')
    actor=$(jq -r '.actor // "미상"' "$f" 2>/dev/null || printf '미상')
    pd=$(jq -r '.project_dir // empty' "$f" 2>/dev/null || true)
    case "$kind" in
      쓰기)
        before=$(jq -r '.remote_before // ""' "$f" 2>/dev/null || true)
        # Only a read made after the consumption can show the effect; until one
        # exists the ticket waits, or an unread push would read as refused.
        # The row is written only on a change, so the read's own stamp is the
        # marker file every successful read touches. A last read that could
        # not reach the remote shows nothing either, so the ticket waits too.
        row=$(gate_remote_last_row "$seg")
        rd=$(gate_mtime "$RUN_DIR/admit/read/$(gate_thp thp_key_norm "$seg")")
        if [ -z "$row" ] || [ -z "$rd" ] || [ "$rd" -le "$mt" ] \
           || [ "$(gate_row_field "$row" '원격 팁')" = "미상" ]; then
          continue
        fi
        row=$(gate_remote_last_known_row "$seg")
        after="$(gate_row_field "$row" '원격 팁')/$(gate_row_field "$row" 'PR')/$(gate_row_field "$row" 'PR 상태')/$(gate_row_field "$row" 'PR HEAD')"
        if [ -n "$row" ] && [ "$after" != "$before" ]; then
          gate_append '맨 명령 결과' "대상=$al" "세그먼트=$seg" "행위자=$actor" "요청=$rid" "티켓=$tid" \
            "행위 다이제스트=$dig" "판정=관측" "기록 시각=$(now_iso)"
        else
          bytes=$(jq -j '.command_b64 // "" | @base64d' "$f" 2>/dev/null; printf x); bytes=${bytes%x}
          gate_refusal_condition "$al" "$seg" "$pd"
          gate_refusal_row "$al" "$seg" "$actor" 맨 추정 "$dig" "$bytes" 미상 추정
        fi ;;
      읽기)
        gate_append '맨 명령 결과' "대상=$al" "세그먼트=$seg" "행위자=$actor" "요청=$rid" "티켓=$tid" \
          "행위 다이제스트=$dig" "판정=미상" "기록 시각=$(now_iso)" ;;
    esac
    mkdir -p "$RUN_DIR/admit/settled" 2>/dev/null && mv -f "$f" "$RUN_DIR/admit/settled/" 2>/dev/null || rm -f "$f"
  done
}

gate_admit_prepare() {
  # gate_admit_prepare <alias> <segment> <actor> <graded> — before the row: the
  # ticket's content into GATE_ADMIT_TJSON and its id into GATE_ADMIT_TID. The
  # content is the bytes, the request directory, the common git directory of
  # the request's root, the caller, the expiry and, for a push, the directory
  # it runs in with the digest of that repository's HEAD, refs and push
  # settings (`thp_refs_digest`). The id ends in the
  # seal of that content, and the row carries the id — so the run hook can tell
  # a ticket this gate graded from a file another hand put in its place, and a
  # push from one whose source moved after it was graded.
  local al="$1" seg="$2" actor="$3" graded="$4" now remote before row rdir="" rdig=""
  now=$(date -u +%s)
  remote='-'
  if [ "$graded" = "읽기" ]; then
    case "${GATE_ACT_DERIVED:-}" in push|PR|머지) remote='읽기' ;; esac
  else
    case "${GATE_ACT_DERIVED:-}" in push|PR|머지) remote='쓰기' ;; esac
  fi
  before=""
  if [ "$seg" != "-" ]; then
    row=$(gate_remote_last_known_row "$seg")
    [ -z "$row" ] || before="$(gate_row_field "$row" '원격 팁')/$(gate_row_field "$row" 'PR')/$(gate_row_field "$row" 'PR 상태')/$(gate_row_field "$row" 'PR HEAD')"
  fi
  if gate_admit_words_push; then
    rdir=$(gate_thp thp_phys "$(gate_admit_git_dir "${GATE_ADMIT_WORDS[@]}")")
    rdig=$(gate_thp thp_refs_digest "$rdir")
    if [ -z "$rdig" ]; then
      warn "the directory this push runs in ('${rdir:-$GATE_ADMIT_CWD}') is not a checkout whose HEAD and branches could be read, so no ticket could be bound to what it pushes"
      exit "$GATE_EXIT_RULE"
    fi
  fi
  GATE_ADMIT_TJSON=$(jq -nc --arg b "$GATE_ADMIT_BYTES" --arg cwd "$GATE_ADMIT_CWD" \
     --arg cd "$(gate_thp thp_common_dir "$GATE_ADMIT_PDIR")" --arg caller "$GATE_ADMIT_CALLER" \
     --argjson exp "$((now + GATE_ADMIT_TTL))" --arg req "$GATE_ADMIT_REQ_ID" \
     --arg tg "$al" --arg sg "$seg" --arg dig "$GATE_ADMIT_DIGEST" --arg remote "$remote" \
     --arg before "$before" --arg actor "$actor" --arg pd "$GATE_ADMIT_PDIR" \
     --arg rd "$rdir" --arg rg "$rdig" \
     '{command_b64: ($b | @base64), cwd: $cwd, common_dir: $cd, caller: $caller,
       expires: $exp, request: $req, target: $tg, segment: $sg, digest: $dig,
       remote: $remote, remote_before: $before, actor: $actor, project_dir: $pd,
       refs_dir: $rd, refs_digest: $rg}') || die "could not compose the ticket"
  GATE_ADMIT_TID="T-${now}-$$-$(printf '%s' "$GATE_ADMIT_TJSON" | gate_thp thp_ticket_seal)"
}

gate_admit_issue() {
  # gate_admit_issue — after the row: the ticket `admit/ticket/<caller key>`,
  # the content gate_admit_prepare composed with its id and the row's line. A
  # newer ticket replaces an older one, and the request is consumed. Prints the
  # bytes to issue again and the ticket id.
  local line tdir tmp
  line=$( { grep -nF "| 티켓=$GATE_ADMIT_TID |" "$LEDGER" 2>/dev/null || true; } | tail -1 | cut -d: -f1)
  tdir="$RUN_DIR/admit/ticket"
  mkdir -p "$tdir" || die "could not create the ticket directory: $tdir"
  tmp=$(mktemp "$tdir/.tmp.XXXXXX") || die "could not create the ticket file in $tdir"
  printf '%s' "$GATE_ADMIT_TJSON" | jq -c --arg id "$GATE_ADMIT_TID" --arg line "${line:--}" \
     '. + {id: $id, line: $line}' > "$tmp" \
    || { rm -f "$tmp"; die "could not write the ticket"; }
  mv -f "$tmp" "$tdir/$GATE_ADMIT_KEY" || { rm -f "$tmp"; die "could not publish the ticket"; }
  rm -f "$GATE_ADMIT_FILE"
  printf '티켓 %s — 다음 명령을 바이트 그대로 한 번 다시 내십시오 (%s초 안, 같은 디렉터리):\n%s\n' \
    "$GATE_ADMIT_TID" "$GATE_ADMIT_TTL" "$GATE_ADMIT_BYTES"
}

gate_verb_act() {
  local verb="$1" kind="$2" alias="$3" segment="$4" cutpoint="$5" surface="$6"
  local snapdig="$7" rationale="$8" worktree="$9"
  shift 9
  local argv="$*"

  [ -n "$alias" ]    || { printf 'gate: --target is required\n' >&2; exit 2; }
  [ -n "$cutpoint" ] || { printf 'gate: --cutpoint is required\n' >&2; exit 2; }
  # `propose-done` is the one kind with no act behind it — it asks whether the
  # run may stop, and demanding an argv would force the router to invent a
  # command whose only purpose is to satisfy a parser. `base-check` is the other
  # kind that takes nothing after `--`: every field of its row is the gate's, and
  # its arm refuses any argv. Demanding one here left no spelling that passed
  # both, so a segment whose review read `머지` stopped short of the merge.
  if [ "$kind" != "propose-done" ] && [ "$kind" != "base-check" ] && [ "$kind" != "remote-check" ]; then
    [ $# -ge 1 ] || { printf 'gate: an argv is required after --\n' >&2; exit 2; }
  fi
  # `exec` DOES NOT TAKE `--kind`, AND THE USAGE HEADER ALREADY SAID SO. A kind
  # names a row the gate PERFORMS, which is an `act`/`plan` notion; `exec`
  # declares its surface with `--surface` and runs the argv itself. But the
  # option parser is verb-agnostic, so `exec --kind skill` arrived here carrying
  # a kind, and two arms below read `kind` without asking which verb they are
  # under: the grading arm pins `워크트리쓰기` instead of consulting the argv0
  # table, and the manifest write guard is skipped outright.
  #
  # Both arms rest on ONE premise — a dispatch argv is a prompt a launcher
  # consumes, not a command line this process runs — and only `act` reaches a
  # launcher. `exec` hands the argv to the read-scoped runner, which runs `"$@"`
  # verbatim, so under that verb the premise is false and the two arms gave a
  # real write both a false grade and an exemption from the guard. The
  # self-declaration check could not catch it either: it compares the declared
  # surface against the value the grading arm just pinned, so `--surface
  # 워크트리쓰기` agreed with itself by construction and exit 6 was unreachable.
  #
  # REFUSING THE FLAG IS WHAT CLOSES BOTH ARMS AT ONCE. Narrowing each arm to
  # `verb = act` closes them one at a time and leaves the next kind-reading arm
  # to remember the verb on its own; making `kind` unreachable under `exec`
  # makes every such arm `act`-only by construction, without either arm naming
  # the verb.
  if [ "$verb" = "exec" ] && [ -n "$kind" ]; then
    printf 'gate: exec does not take --kind — declare the surface of an exec with --surface, and act is the verb that carries a kind\n' >&2
    exit 2
  fi

  # Vocabulary first, and by return status rather than `die` — see surface_index.
  cutpoint_index "$cutpoint" >/dev/null || exit "$GATE_EXIT_VOCAB"

  # THE APPLY ACT HAS ONE SPELLING. Its argv is the fixed token and nothing else,
  # its rung is `배포`, and it names a segment — the command it runs is the frozen
  # one, so any further argv word would be a command the router chose.
  if [ "$kind" = "apply" ]; then
    if [ $# -ne 1 ] || [ "$1" != "적용" ]; then
      warn "act --kind apply 의 argv 는 고정 토큰 「적용」 하나입니다 — 적용 명령은 게이트가 동결 선언에서 읽습니다"
      exit "$GATE_EXIT_VOCAB"
    fi
    [ "$cutpoint" = "배포" ] || { warn "act --kind apply 는 --cutpoint 배포 로만 냅니다 (받은 값: ${cutpoint})"; exit "$GATE_EXIT_VOCAB"; }
    { [ -n "$segment" ] && [ "$segment" != "-" ]; } \
      || { warn "act --kind apply 는 --segment <구현 세그먼트 id> 가 필요합니다"; exit "$GATE_EXIT_VOCAB"; }
  fi
  # THE RERUN ACT HAS ONE SPELLING TOO: the token `재실행` and the 40-character
  # head it reruns, at the `PR` rung, for one segment. The runs it reruns are
  # the gate's choice, so any further word would be one the router chose. The
  # head rides in the argv so that the park digest is per head: without it the
  # first park would park every later head's rerun as well.
  if [ "$kind" = "ci-rerun" ]; then
    if [ $# -ne 2 ] || [ "$1" != "재실행" ] || ! printf '%s' "$2" | grep -Eq '^[0-9a-f]{40}$'; then
      warn "act --kind ci-rerun 의 argv 는 「재실행 <40자리 워크트리 HEAD>」 하나입니다 — 다시 돌릴 실행은 게이트가 고릅니다"
      exit "$GATE_EXIT_VOCAB"
    fi
    [ "$cutpoint" = "PR" ] || { warn "act --kind ci-rerun 은 --cutpoint PR 로만 냅니다 (받은 값: ${cutpoint})"; exit "$GATE_EXIT_VOCAB"; }
    { [ -n "$segment" ] && [ "$segment" != "-" ]; } \
      || { warn "act --kind ci-rerun 은 --segment <세그먼트 id> 가 필요합니다"; exit "$GATE_EXIT_VOCAB"; }
  fi
  # THE MATCH ACT'S ONE SPELLING, on the rerun act's pattern: the token `대조`
  # and the head whose failures it compares, at the `PR` rung, for one segment.
  # Which checks and which logs it reads are the gate's choice.
  if [ "$kind" = "ci-match" ]; then
    if [ $# -ne 2 ] || [ "$1" != "대조" ] || ! printf '%s' "$2" | grep -Eq '^[0-9a-f]{40}$'; then
      warn "act --kind ci-match 의 argv 는 「대조 <40자리 워크트리 HEAD>」 하나입니다 — 읽을 체크와 로그는 게이트가 고릅니다"
      exit "$GATE_EXIT_VOCAB"
    fi
    [ "$cutpoint" = "PR" ] || { warn "act --kind ci-match 는 --cutpoint PR 로만 냅니다 (받은 값: ${cutpoint})"; exit "$GATE_EXIT_VOCAB"; }
    { [ -n "$segment" ] && [ "$segment" != "-" ]; } \
      || { warn "act --kind ci-match 는 --segment <세그먼트 id> 가 필요합니다"; exit "$GATE_EXIT_VOCAB"; }
  fi
  # THE LABEL ACT'S ONE SPELLING, in the rerun's shape: the token `라벨` and the
  # head. The check and the label are the manifest's, never the router's.
  if [ "$kind" = "label-ack" ]; then
    if [ $# -ne 2 ] || [ "$1" != "라벨" ] || ! printf '%s' "$2" | grep -Eq '^[0-9a-f]{40}$'; then
      warn "act --kind label-ack 의 argv 는 「라벨 <40자리 워크트리 HEAD>」 하나입니다 — 체크와 라벨은 게이트가 매니페스트에서 읽습니다"
      exit "$GATE_EXIT_VOCAB"
    fi
    [ "$cutpoint" = "PR" ] || { warn "act --kind label-ack 은 --cutpoint PR 로만 냅니다 (받은 값: ${cutpoint})"; exit "$GATE_EXIT_VOCAB"; }
    { [ -n "$segment" ] && [ "$segment" != "-" ]; } \
      || { warn "act --kind label-ack 은 --segment <세그먼트 id> 가 필요합니다"; exit "$GATE_EXIT_VOCAB"; }
  fi

  # ---- the argv ladder, derived and compared against the declaration --------
  #
  # THE SEAM IS HERE AND NOT AT `gate_export_cutpoints`, and the position is the
  # whole of the repair. Five consumers read the declared rung as a threshold —
  # the rule catalog's `GATE_ACT`, the target-ceiling exporter, the wall-clock
  # deadline, the undeclared-target layers and the obligation issuer — and
  # #Nharu/cc-cmds#505 names only the first. Fixing the rule call site alone
  # leaves the other four open to the identical misspelling, so the value is
  # corrected once, above all of them. The exporter cannot be that place: three
  # of the five already sit above it.
  #
  # DERIVE FIRST, AND ONLY WHERE THE argv IS A COMMAND. `propose-done` has no act
  # behind it, a `skill` or `router-shift` argv begins with a stage kind or a
  # handoff reason, and a bookkeeping act's argv is a list of `키=값` fields.
  # Feeding any of those to the table asks a question it cannot answer, so the
  # split is the same one `GATE_HISTORY_INTEGRATION` already makes verbatim a few
  # hundred lines below — and for the same reason, which is that the answer there
  # would be a guess rather than a fact.
  GATE_ACT_DERIVED=""
  case "$kind" in
    propose-done|skill|router-shift|apply|ci-rerun|ci-match|label-ack) : ;;
    *) gate_kind_is_bookkeeping "$kind" \
         || GATE_ACT_DERIVED=$(ladder_of_argv0 "$@") ;;
  esac
  # Set beside the derivation above because they answer the same question — is
  # this argv a COMMAND — and a second answer computed elsewhere is a second
  # chance to disagree. `argv_graded` says the grade came from the table rather
  # than from the act kind; the other two carry what the caller declared.
  local argv_graded=0
  GATE_DECLARED=""; GATE_UNKNOWN_DECLARED=0
  export GATE_DECLARED GATE_UNKNOWN_DECLARED
  GATE_ACT_EFFECTIVE="$cutpoint"
  if [ -n "$GATE_ACT_DERIVED" ]; then
    local d_idx r_idx
    d_idx=$(cutpoint_index "$GATE_ACT_DERIVED") || exit "$GATE_EXIT_VOCAB"
    r_idx=$(cutpoint_index "$cutpoint") || exit "$GATE_EXIT_VOCAB"
    if [ "$d_idx" -gt "$r_idx" ]; then
      # UNDER-DECLARATION, AND IT IS REFUSED BEFORE exit 4 ON PURPOSE. Exit 4
      # tells the router "re-read the snapshot and try again", and a retry with
      # the same misspelled argv walks straight back into this same refusal —
      # so the staleness comparison below must not get to answer first.
      # THE RULE IS DESCRIBED AND NOT NAMED, and the omission is deliberate. The
      # catalog refusal spells its own rule's name on stderr — `rule refused:
      # 절단점-준수` — and that name is the only thing separating the two
      # refusals for a reader scanning the transcript. Spelling it here as part
      # of a PRESCRIPTION would put it on the exit-8 message too, and then the
      # two consumers this axis exists to tell apart become one string again:
      # deleting either check leaves the other answering for it. The router's
      # exit-code table carries the name; this message carries the repair.
      warn "under-declared: argv is grade '$GATE_ACT_DERIVED' but was declared '$cutpoint' — a low declaration does not widen the authorization"
      warn "raise the declaration to '$GATE_ACT_DERIVED' and call again with the same argv. Even raised, if it goes past the cutpoint of the target it is not authorized, and the prescription then is not to raise again but to park — that refusal comes back not as this exit 8 but as exit 3 of the authorization-ceiling rule"
      exit "$GATE_EXIT_LADDER"
    fi
    if [ "$d_idx" -lt "$r_idx" ]; then
      # OVER-DECLARATION PASSES, AND THE CONSUMERS TAKE THE DERIVED RUNG. The
      # router labels every act with its target's cutpoint, so this is the
      # ordinary path and refusing it would be a wall. What it is not is silent:
      # the ledger carries both values and this line carries the third thing
      # neither field can say, which is that one of them was lowered.
      warn "over-declared: argv is grade '$GATE_ACT_DERIVED' but was declared '$cutpoint' — this act is judged at the derived grade"
      GATE_ACT_EFFECTIVE="$GATE_ACT_DERIVED"
    fi
  fi
  export GATE_ACT_DERIVED GATE_ACT_EFFECTIVE

  # Snapshot binding, and it sits HERE — after the state-independent argument
  # and vocabulary checks, and before anything that writes. Under parallel
  # segments a background stage can land a row between the router reading the
  # snapshot and calling here; the main session also compacts, and a compacted
  # router carrying a remembered digest is a correctness failure that is
  # otherwise invisible. Exit 4 turns both into a loud re-read.
  #
  # It used to sit further down, after target resolution — which registers an
  # undeclared target by APPENDING a `대상 추가` row. The digest was therefore
  # compared against a ledger the gate itself had just changed, so an act that
  # registered a target could never satisfy its own binding. That was invisible
  # while the digest ignored the ledger; making the digest honest made the
  # ordering matter. A check on observed state has to run before the observer
  # mutates that state.
  if [ "$verb" != "plan" ]; then
    [ -n "$snapdig" ] || { printf 'gate: --snapshot-digest is required\n' >&2; exit 2; }
    local now nowvec nowtip obsvec obstip stale=0 twopart=0
    now=$(gate_snapshot_digest)
    nowvec="${now%%-*}"; nowtip="${now##*-}"
    case "$snapdig" in
      *-*) twopart=1; obsvec="${snapdig%%-*}"; obstip="${snapdig##*-}" ;;
      # THE OLD ONE-PART FORM KEEPS ITS OLD MEANING, WHICH IS EXACT EQUALITY. The
      # permission hook's own instructions, this repository's fixtures and other
      # sessions' copies of this file all carry a bare digest, so a format change
      # that refused it would stop runs that are already in flight over a
      # spelling. Left empty here and handled as a whole-string compare below.
      *) obsvec=""; obstip="" ;;
    esac
    if [ "$twopart" = "0" ]; then
      [ "$snapdig" = "$(gate_snapshot_digest_legacy)" ] || stale=1
    else
      # BOTH HALVES ARE CHECKED FOR SHAPE BEFORE EITHER IS COMPARED, and an empty
      # half is a FORMAT error rather than a comparison that happens to succeed.
      # `<벡터해시>-` has the two-part form, so it reached the ancestry probe with
      # an empty tip and the probe degenerated to `grep -qF "prev="` — true of
      # every ledger holding a single row. The one value that still had to be
      # right, the vector half, is printed in full by the refusal message, so
      # there was nothing left to guess.
      #
      # THE ARM IS SELECTED ON THE FORM AND NOT ON AN EMPTY VECTOR HALF. That
      # selector had the mirror defect: `-<팁>` is two-part by the `case` above
      # but carries an empty vector, so it fell through to the one-part formula
      # and was refused for a reason that was not its own.
      case "$obsvec$obstip" in
        *[!0-9a-f]*) stale=1 ;;
      esac
      { [ ${#obsvec} -eq 64 ] && [ ${#obstip} -eq 64 ]; } || stale=1
      # THE VECTOR HALF IS EXACT, and that is where the check earns its keep: the
      # vector moves only on progress, so a mismatch is a router acting on state
      # that genuinely moved — a compacted one carrying a remembered value
      # included. Nothing about this half is relaxed.
      [ "$obsvec" = "$nowvec" ] || stale=1
      # AND THE TIP HALF IS BOUNDED ANCESTRY RATHER THAN EQUALITY. Equal is the
      # ordinary case. Otherwise the tip the caller observed has to appear as the
      # `prev` of one of the last GATE_ANCESTRY_WINDOW rows — a point the chain
      # has grown past while somebody else appended between the read and the act,
      # which is concurrency and not staleness. A tip that is on no row at all,
      # or on a row the chain has left far behind, is neither.
      #
      # WHAT THE BOUND DOES NOT BUY. K measures DISTANCE and not KIND, so a
      # digest presented a few rows after a pending approval was opened still
      # passes. The vector cannot be widened to cover that: the vector's own note
      # explains that a boundary firing always issues an approval, so counting
      # approvals would let the remedy reset the counter that fired it. What the
      # bound removes is the property that a value read hours ago passed forever.
      #
      # ANCHORED TO THE FIELD BOUNDARY AND TO END OF LINE. The boundary alone
      # still matched a carrier that supplies no separator at all, because a
      # fixed-string probe matches anywhere in the row. `prev` is the last field
      # by construction, so the row anchor costs nothing and refuses that third
      # carrier. `$obstip` is 64 lowercase hex by the shape check above, so it
      # carries no regular-expression metacharacter.
      #
      # ANCHORED TO THE FIELD BOUNDARY. A row's real `prev` is its last field and
      # is written as ` | prev=<hex>`, and gate_append maps `|` out of every field
      # a caller supplies, KEY AND VALUE ALIKE, so no field can forge that
      # boundary. The key half of that transform landed later than this anchor,
      # which is why both halves are named: while the maps covered values only,
      # a caller could spell ` | prev` as a field's KEY and put the separator into
      # the very row this probe reads. Unanchored,
      # `근거=prev=<hex>` matched: the authorisation row carries the caller's own
      # rationale verbatim, so ONE act with a valid digest let a caller mint the
      # ancestor token it would present later, while knowing no real value in the
      # ledger. Measured on a live 107-row ledger: the rows carrying `prev=` and
      # the rows carrying ` | prev=` are the same rows, so the anchor loses no
      # legitimate ancestor.
      #
      # NOT A PIPE. `grep -q` exits at its first match, which closes the pipe on
      # an upstream that is still writing — under `pipefail` that SIGPIPE turns a
      # found ancestor into a failed test. The window is bounded rows, so a here
      # string costs nothing and removes the race the lint refuses.
      #
      # THE SHAPE CHECK ABOVE AND THIS ANCHOR CLOSE DIFFERENT DOORS, and neither
      # closes the other's. A prefix of a real tip satisfies a substring match
      # even anchored, so the length check is what refuses it; a minted token is a
      # perfect 64-character lowercase hex, so the anchor is what refuses it.
      if [ "$stale" = "0" ] && [ "$obstip" != "$nowtip" ] \
         && ! grep -qE " \| prev=$obstip\$" <<<"$(gate_ancestry_window)"; then
        stale=1
      fi
    fi
    if [ "$stale" != "0" ]; then
      warn "stale snapshot digest: observed '$snapdig' vs now '$now'"
      exit "$GATE_EXIT_STALE"
    fi
  fi

  # THE CONTEXT CAP, AHEAD OF EVERYTHING BELOW THAT CAN WRITE. Under this line
  # come the undeclared-target registration, the rule catalog, the approval
  # issuance and the row append, and the cap must come back with no row at all —
  # so it stands here, after the digest comparison and before the first writer.
  # All three verbs pass through: `plan` previews an act, and a shift at the cap
  # is to end rather than preview.
  gate_cap_directive "$verb" "$kind"

  # THE PLANNED ROW IS FILLED FROM THE FROZEN DOCUMENT, before anything below
  # reads the argv — the review policy resolution, the rules and the segment
  # arm all see the fields the document declares and never a transcription.
  if [ "${GATE_FROM_DECLARATION:-}" = "1" ]; then
    gate_from_declaration "$verb" "$alias" "$segment" "$@" || exit $?
    # A SLICE AN EARLIER RUN LANDED IS NOT PLANNED AGAIN. Its terminal row is
    # already this ledger's (or, on `plan`, would be), and a planned row after it
    # would put the landed work back on the dispatch list.
    if [ -n "${GATE_DECL_SELF_IMPORTED:-}" ]; then
      [ "$verb" = "plan" ] && printf '통과 예상: kind=%s target=%s 처분=착지 들여오기(계획 행 없음) segment=%s\n' "$kind" "$alias" "$segment"
      exit 0
    fi
    set -- "${GATE_DECL_FIELDS[@]}"
    argv="$*"
  fi

  # THE APPLY ACT'S FIVE PRECONDITIONS, before the first writer below — the
  # undeclared-target registration is one — and so before the catalog, the
  # approval block and every row. A person as the actor ends here with its
  # handover row and 0. A segment that owes no apply ends here too, with no row
  # and 0. The subject head is bound only after precondition 4 proved it, and
  # only for this act.
  if [ "$kind" = "apply" ]; then
    gate_apply_preconditions "$verb" "$alias" "$segment" || exit $?
    if [ -n "${GATE_APPLY_NOT_OWED:-}" ]; then
      if [ "$verb" = "plan" ]; then
        printf '통과 예상: kind=apply target=%s 처분=불필요(적용을 빚지지 않음)\n' "$alias"
      else
        log "적용 불필요 — ${segment} 는 적용을 빚지지 않습니다 (머지됨 행에 적용=대기 가 없고 사람 인계도 남지 않았습니다)"
      fi
      exit 0
    fi
    if [ -n "${GATE_APPLY_HANDOVER:-}" ]; then
      [ "$verb" = "plan" ] && printf '통과 예상: kind=apply target=%s 처분=인계(적용 주체 사람)\n' "$alias"
      exit 0
    fi
    GATE_SUBJECT_HEAD="$GATE_APPLY_SUBJECT"
    export GATE_SUBJECT_HEAD GATE_APPLY_COMMAND
  fi
  # THE RERUN ACT'S TWO PRECONDITIONS, at the same seat and for the same reason.
  # They read neither the ledger nor GitHub — the drain has not run yet — so the
  # eligibility waits for its own seat beside the merge check.
  if [ "$kind" = "ci-rerun" ]; then
    gate_ci_rerun_preconditions "$segment" "$2" || exit $?
  fi
  if [ "$kind" = "ci-match" ]; then
    gate_ci_match_preconditions "$segment" "$2" || exit $?
  fi
  if [ "$kind" = "label-ack" ]; then
    gate_label_ack_preconditions "$segment" "$2" || exit $?
  fi

  case " $(target_aliases | tr '\n' ' ') " in
    *" $alias "*) : ;;
    # THE EFFECTIVE RUNG AND NOT THE DECLARED ONE, here and at the six sites
    # below. This one decides whether an undeclared repository is refused
    # outright or quietly REGISTERED with a `대상 추가` row, so a merge spelled
    # `--cutpoint 커밋` used to walk past the refusal and leave the registration
    # behind it.
    *) gate_undeclared_target "$alias" "$GATE_ACT_EFFECTIVE" "$worktree" || exit $? ;;
  esac

  # The router's declared surface is a CHECKED CLAIM, not a self-grant. A
  # mismatch is exit 6 — the same idiom the slicing declaration's `슬라이스 수`
  # already uses, where a value the writer supplies is compared against one the
  # reader derives instead of being trusted.

  # Where the act runs. A declared target names its own worktree and the act
  # belongs there; an undeclared one has no row to read, so the act stays in
  # the caller's directory and is bounded by the layers above instead. The
  # resolution itself lives in gate_act_worktree, which the approval's freeze
  # and staleness comparison call too — a stage woke on the main worktree's
  # branch every time until this was resolved in one place.
  #
  # RESOLVED HERE, AHEAD OF THE GRADING BASE THAT READS IT. This assignment used
  # to sit far below the grade, so the only value the grade could reach was the
  # one a parent gate exported — the parent's tree, never this act's. Once a
  # `--segment` act started running in the segment's worktree the two parted:
  # paths outside the segment tree but inside the caller's graded `워크트리쓰기`
  # and paths inside it graded `트리밖쓰기`, so the axis that decides which rules
  # apply was answering about a directory the act does not enter.
  #
  # THE UNDECLARED ARM RESOLVES THROUGH THE SAME CALL, and that is what makes
  # this one line rather than two branches. The undeclared arm used to assign
  # `$worktree` here directly, which fixed the act's own cwd and nothing else:
  # `gate_act_worktree` still answered empty for an alias with no target row, so
  # the grading base, the tree root, the approval id's fourth field and the
  # freeze/staleness probe each resolved somewhere the act was not. Registration
  # now records that worktree beside the undeclared flag and the resolver
  # returns it, so all four readers and this assignment take one value.
  GATE_ACT_CWD=$(gate_act_worktree "$alias" "$segment")
  # A bare command runs where the session issued it, not where the segment's
  # worktree is, so the bare form grades and roots it there.
  [ "${GATE_ADMIT:-}" != "1" ] || GATE_ACT_CWD="$GATE_ADMIT_CWD"
  export GATE_ACT_CWD

  # A STAGE MAY NOT BE DISPATCHED INTO A SEGMENT THAT HAS NO `segment` ROW.
  #
  # The progress vector is built from the goal digest, the target rows, the
  # `segment` rows and the open obligations — and from nothing a running stage
  # emits. So a run whose segments were never written has a vector that cannot
  # move: the stagnation boundary counts three identical digests and issues an
  # approval while a stage is working normally, and its question text says only
  # that the progress hash has not changed. Reading that line, "the router
  # stopped", "the stage is slow" and "nobody wrote the row" are the same
  # sentence. Measured: an audit stage worked 16 minutes, produced its report
  # and three independent witnesses, terminated as `정상 완료` — and the
  # boundary fired in the middle of it, with 38 `자율 승인` rows in the ledger
  # and not one of them an input to the vector.
  #
  # The kickoff already says to write these rows. That is prose, and prose is
  # what the omission got past; the same omission also silently costs the run
  # termination condition 1, which counts `segment` rows, so a run that skips
  # them cannot merge anything and cannot propose it is done — a debt taken on
  # here and presented much later wearing a different face.
  #
  # NO `act` CONJUNCT. Both checks here are pure reads of rows already written,
  # and excluding the dry run from them was the mechanism rather than a side
  # effect: moving the early return alone leaves this arm still keyed on `act`,
  # so `plan --kind skill` would go on answering "통과 예상" for a segment with no
  # row and for a predecessor that has not landed.
  #
  # AHEAD OF THE RULE CATALOG AND THE APPROVAL BLOCK, and that ordering is half
  # of what these two checks are worth. They used to sit below both, so a
  # dispatch that lay outside the pre-authorization was answered with an approval
  # instead of with this refusal: the run issued a pending question, froze its
  # binding tuple against the FALLBACK tree nobody had chosen, and exited 5. An
  # open approval stops the run, so a person answered it in the morning, the
  # segment row was then repaired, and the same argv — now resolving to the
  # segment's own tree — read that answer as stale and threw it away. A refusal
  # that names the field to fix has to come before anything writes an approval
  # about the same act.
  # THE ONE EXEMPTION: the run-scope steps — the design, the audit and the
  # split. `--segment -` with one of those stage kinds names no segment, so
  # there is no row to require and no `선행` to land; the stage is keyed on the
  # plan's step id of that kind instead (see `gate_run_scope_step`). The
  # exemption is keyed on all three facts — the kind, the `-`, and a plan that
  # names exactly one step of that kind and, for the design and the audit,
  # either requires a design or, for the audit, names no design step at all —
  # so `-` with any other stage kind, or with a plan that does not say this,
  # still meets the refusal below. Writing a `segment` row for the step was the
  # other way out and was dropped: that row is what termination condition 1
  # counts, and none of these steps is a segment.
  #
  # THE EXEMPTION SITS UP HERE FOR THE SAME REASON THE REFUSAL IT EXEMPTS DOES.
  # It carries refusals of its own — a plan that does not name exactly one step
  # of the kind, a run whose `설계 문서` is still `(없음)`, the audit's
  # preconditions and the predecessor check below — and all of them are refusals
  # about THIS act, so they have to be reached before anything writes an
  # approval about it. Left at the old site below the approval block, the
  # exemption would also have arrived too late to be one: the row check above
  # would already have refused the dispatch it exists to let through.
  #
  # THE EXEMPTION IS A TABLE, NOT ONE ROW. A base run's split step is not a
  # segment either, so `--segment -` with stage kind `split` is exempted on the
  # same three facts — the kind, the `-`, and a plan naming exactly one step of
  # the table's skill for it (see `gate_run_scope_step`).
  #
  # A `reconverge` WITH `-` IS THE RUN-SCOPE AUDIT'S CONTINUATION, and only that.
  # When a person adopts the requirement an audit composed, the router
  # re-converges the document on the audit's own key and audits it again; for an
  # audit that has no segment that key is `-`, and without this the dispatch met
  # the segment-row refusal below on every spelling, leaving the person's answer
  # nowhere to go. It rides on the audit's row of the table, and only when the
  # audit step has no `segment` row and its last `stage-result` row is an audit
  # that parked on purpose — the one state a composed requirement is asked in —
  # so any other `- reconverge` still meets the refusal below.
  #
  # A `--resume` OF THAT RE-CONVERGENCE IS THE OTHER STATE. Once it has run, the
  # last row on the key is its own `종류=reconverge` row, so a re-attachment
  # after a crash or a limit, a continuation, or a halt answer handed on would
  # never see the parked audit again. Under `--resume` the re-convergence is
  # admitted when the key's last row is a re-convergence whose session is the
  # one being resumed — the last attempt, and no older session on the key.
  #
  # A CARRY OF A HALTED RE-CONVERGENCE'S ANSWER IS THE THIRD. A re-convergence
  # that parked on purpose leaves its own row last on the key, and the person's
  # answer goes to a fresh session; the carry act's scope check
  # (`gate_carry_scope_ok`) runs below, before any row about this act, so a
  # carry this branch admits and that check refuses leaves nothing behind.
  #
  # AND ON THE DESIGN STEP'S KEY, THE REVIEW A PERSON OPENS ON ITS LADDER. A
  # person who answers a design stage's residual-ladder record `골격 재검토`
  # sends the frozen document back through re-convergence, scoped to the
  # residual items that record froze, and then through a fresh audit. It rides
  # on the design's row of the table, only in the two states
  # `gate_design_reconverge_entry` reads, and its prompt has to carry the scope
  # `잔여 동결 재검토 <that record>`. When the audit's continuation and this
  # review both hold, the gate does not pick one: the dispatch is refused.
  local stage_key="$segment" stage_is_run_scope_step=0 rs_kind="${1:-}" rs_table="${1:-}" rs_skill rs_astep="" rs_alast=""
  local rs_dstep="" rs_drec="" rs_aok="" rs_dok="" rs_dwhy=""
  if [ "$kind" = "skill" ] && [ "$segment" = "-" ] && [ "$rs_kind" = "reconverge" ]; then
    rs_table=""
    if rs_astep=$(gate_run_scope_step audit); then
      gate_audit_reconverge_keyable "$rs_astep" "${GATE_RESUME:-}" && rs_aok=1
      rs_alast=$GATE_AUDIT_RECONVERGE_LAST
      # AN AUDIT THAT ASKED FOR ITS SKELETAL RE-CONVERGENCE takes one too, and
      # only with that scope: the prompt names the document and then exactly
      # `감사 골격급`, optionally followed by the report it read. Once that
      # re-convergence has a row the key's last row is a re-convergence, so a
      # second one is refused until a fresh audit stands.
      if [ -z "$rs_aok" ] && [ -z "${GATE_RESUME:-}" ] \
         && gate_audit_skeleton_reconverge_keyable "$rs_astep"; then
        local rs_sp rs_srest
        rs_sp=$(gate_skill_prompt_of "$@")
        rs_srest=${rs_sp#'/cc-cmds:design-reconverge '}
        rs_srest=${rs_srest#* }
        case "$rs_srest" in
          '감사 골격급'|'감사 골격급 '*.md) rs_aok=1 ;;
          *) warn "골격급 재수렴의 프롬프트는 /cc-cmds:design-reconverge <design_doc> 감사 골격급 이어야 합니다 — 지금 범위는 「${rs_srest}」 입니다" ;;
        esac
      fi
    fi
    if rs_dstep=$(gate_run_scope_step design) \
       && [ -z "$(gate_segment_field "$rs_dstep" '상태')" ]; then
      if gate_design_reconverge_entry "$rs_dstep"; then
        rs_dok=1
        rs_drec=$GATE_DRC_RECORD
      else
        rs_dwhy=$GATE_DRC_WHY
      fi
    fi
    if [ -n "$rs_aok" ] && [ -n "$rs_dok" ]; then
      warn "- reconverge 가 감사 단계(${rs_astep})의 재수렴과 설계 단계(${rs_dstep})의 잔여 동결 재검토 양쪽에 다 맞습니다 — 게이트는 둘 중 하나를 고르지 않습니다"
      exit "$GATE_EXIT_RULE"
    elif [ -n "$rs_aok" ]; then
      rs_table=audit
    elif [ -n "$rs_dok" ]; then
      rs_table=design
    else
      warn "- reconverge 는 감사 단계(${rs_astep:-없음})의 마지막 행이 의도된 park 로 끝난 감사이거나, 재수렴 요청=예 로 정상 완료된 감사에 범위 감사 골격급 을 실었거나, --resume 이 그 마지막 재수렴 행의 세션일 때만 받습니다 — 지금 마지막 행은 종류=$(gate_row_field "$rs_alast" '종류') · 종단 부류=$(gate_row_field "$rs_alast" '종단 부류') 입니다"
      [ -z "$rs_dwhy" ] || warn "설계 단계의 잔여 동결 재검토로도 받지 않습니다 — $rs_dwhy"
    fi
  fi
  if [ "$kind" = "skill" ] && [ "$segment" = "-" ] \
     && { [ "$rs_table" = "design" ] || [ "$rs_table" = "audit" ] || [ "$rs_table" = "split" ] \
          || [ "$rs_table" = "visual" ]; }; then
    rs_skill=$(gate_run_scope_skill_of "$rs_table")
    if ! stage_key=$(gate_run_scope_step "$rs_table"); then
      case "$rs_table" in
        design)
          warn "설계 스테이지를 --segment - 로 띄우려면 실행 계획이 design_required=true 이고 skill 이 design 인 단계를 정확히 하나 가져야 합니다"
          warn "세그먼트가 아닌 설계 단계의 파일 키는 그 단계 id 이며, 계획이 그것을 하나로 정하지 못하면 게이트가 고르지 않습니다" ;;
        audit)
          warn "${rs_kind} 스테이지를 --segment - 로 띄우려면 실행 계획이 skill 이 design-audit 인 단계를 정확히 하나 가지고, design_required=true 이거나 skill 이 design 인 단계가 없어야 합니다"
          warn "세그먼트가 아닌 감사 단계의 파일 키는 그 단계 id 이며, 계획이 그것을 하나로 정하지 못하면 게이트가 고르지 않습니다" ;;
        *)
          warn "${rs_kind} 스테이지를 --segment - 로 띄우려면 실행 계획이 skill 이 ${rs_skill} 인 단계를 정확히 하나 가져야 합니다"
          warn "세그먼트가 아닌 런 범위 단계의 파일 키는 그 단계 id 이며, 계획이 그것을 하나로 정하지 못하면 게이트가 고르지 않습니다" ;;
      esac
      exit "$GATE_EXIT_RULE"
    fi
    stage_is_run_scope_step=1

    # AND THE DOCUMENT MUST ALREADY HAVE A NAME. `## 요소` → `설계 문서` is what
    # the dispatch, every guard standing around it and the later audit all
    # resolve the document through, and the kickoff is what names it — in front
    # of the person, before the freeze. A run that requires a design and still
    # arrives here with `(없음)` has no name anything downstream can agree on,
    # so the act is refused rather than that value being read as a path. The
    # gate does not compose one either: a path invented at dispatch names a
    # document no guard is watching and no audit will read, and the run would
    # go on around it.
    local design_doc
    design_doc=$(manifest_field '요소' '설계 문서')
    case "$design_doc" in
      '' | '없음' | '(없음)')
        if [ "$rs_kind" = "design" ]; then
          warn "설계 스테이지를 --segment - 로 띄우려면 매니페스트 ## 요소 의 설계 문서 가 실제 경로여야 합니다 — 지금은 비었거나 (없음) 입니다"
        else
          warn "${rs_kind} 스테이지를 --segment - 로 띄우려면 매니페스트 ## 요소 의 설계 문서 가 실제 경로여야 합니다 — 지금은 비었거나 (없음) 입니다"
        fi
        warn "이 값은 킥오프가 사람 앞에서 정해 동결하는 것이며, 게이트는 경로를 지어내지 않습니다"
        exit "$GATE_EXIT_RULE"
        ;;
    esac

    if [ "$rs_kind" = "split" ] && [ "$(gate_snapshot_design_scope)" != "base" ]; then
      warn "분할 스테이지는 실행 계획의 design_scope 가 base 인 런에서만 띄웁니다"
      exit "$GATE_EXIT_RULE"
    fi

    # THE AUDIT READS A FROZEN DOCUMENT, AND THE GATE CHECKS THAT IT IS ONE. Three
    # facts, all read before anything is written: the design step ended
    # `정상 완료`, the document carries the frozen status line as a whole line,
    # and neither step has a dispatch still running. The router cannot be the
    # only party that knows this — an audit launched under a live design stage
    # edits a document the design is still writing, and both hold the same lock.
    # The status line is read rather than a digest, because the audit itself
    # edits the document and leaves that line alone.
    #
    # A plan with no design step at all has no design result to read: its
    # document was frozen before the run, so the status line and the audit's own
    # live attempt are the whole precondition there. A plan that names design
    # steps but not exactly one is still refused — which step to wait on is not
    # the gate's to pick.
    #
    # A DESIGN STEP WITH NO ROW AT ALL OVER A FROZEN DOCUMENT COUNTS AS DONE. A
    # run kicked off again over a document that is already there and frozen —
    # the recovery after a split stopped and a person fixed the document — has
    # its design skipped by both routers and the driver, so no design row is
    # ever written, and the frozen document is the same input a `정상 완료`
    # would have left. Condition 1 already reads that run this way; refusing its
    # audit here would leave it waiting on a design nobody dispatches. A row
    # that exists still decides, and the status line is still required.
    #
    # The audit's continuation shares its key and its document lock, so it does
    # not start while an attempt on that key is still running.
    if [ "$rs_kind" = "reconverge" ] && [ "$rs_table" = "audit" ] && gate_stage_live_attempt "$stage_key"; then
      warn "감사 단계($stage_key)의 재수렴은 그 단계에 살아 있는 시도가 없을 때만 뜹니다 — 그 시도가 끝난 뒤 다시 파견하세요"
      exit "$GATE_EXIT_RULE"
    fi
    # The design's review edits the document the audit reads, so it waits for
    # both keys, and its prompt names the scope and the record it reviews.
    if [ "$rs_kind" = "reconverge" ] && [ "$rs_table" = "design" ]; then
      if gate_stage_live_attempt "$stage_key" \
         || { [ -n "$rs_astep" ] && gate_stage_live_attempt "$rs_astep"; }; then
        warn "설계 단계($stage_key)의 잔여 동결 재검토는 설계 단계와 감사 단계 어느 쪽에도 살아 있는 시도가 없을 때만 뜹니다 — 그 시도가 끝난 뒤 다시 파견하세요"
        exit "$GATE_EXIT_RULE"
      fi
      if [ -z "${GATE_RESUME:-}" ]; then
        local rs_dp rs_rest
        rs_dp=$(gate_skill_prompt_of "$@")
        rs_rest=${rs_dp#'/cc-cmds:design-reconverge '}
        rs_rest=${rs_rest#* }
        case "$rs_rest" in
          "잔여 동결 재검토 $rs_drec"|"잔여 동결 재검토 $rs_drec "*) ;;
          *)
            warn "설계 단계의 재수렴 프롬프트는 /cc-cmds:design-reconverge <design_doc> 잔여 동결 재검토 ${rs_drec} 이어야 합니다 — 범위와 그 잔여 사다리 기록의 절대 경로를 그대로 싣습니다"
            exit "$GATE_EXIT_RULE" ;;
        esac
      fi
    fi
    if [ "$rs_kind" = "audit" ]; then
      local au_dstep="" au_rows au_last
      if au_dstep=$(gate_run_scope_step design); then
        au_rows=$(gate_stage_result_rows_of "$au_dstep")
        au_last=$(gate_row_field "$(printf '%s\n' "$au_rows" | tail -1)" '종단 부류')
        if { [ -n "$au_rows" ] && [ "$au_last" != "정상 완료" ]; } \
           || { [ -z "$au_rows" ] && ! doc_is_frozen "${DOC:-}"; }; then
          warn "감사 스테이지는 설계 단계($au_dstep)의 마지막 결과가 정상 완료일 때만 뜹니다 — 지금은 ${au_last:-결과 행 없음} 입니다"
          exit "$GATE_EXIT_RULE"
        fi
      elif [ "$(gate_plan_skill_step_count design)" != "0" ]; then
        warn "감사 스테이지는 설계 단계 뒤에만 뜹니다 — 실행 계획이 skill 이 design 인 단계를 정확히 하나 가져야 합니다"
        exit "$GATE_EXIT_RULE"
      fi
      if [ -z "${DOC:-}" ] || ! grep -qxF '**상태**: 동결됨' "$DOC" 2>/dev/null; then
        warn "감사 스테이지는 동결된 설계 문서에만 뜹니다 — ${DOC:-$design_doc} 에 「**상태**: 동결됨」 한 줄이 없습니다"
        exit "$GATE_EXIT_RULE"
      fi
      if { [ -n "$au_dstep" ] && gate_stage_live_attempt "$au_dstep"; } || gate_stage_live_attempt "$stage_key"; then
        warn "감사 스테이지는 설계 단계와 감사 단계 어느 쪽에도 살아 있는 시도가 없을 때만 뜹니다 — 그 시도가 끝난 뒤 다시 파견하세요"
        exit "$GATE_EXIT_RULE"
      fi
    fi

    # AND THE ARGV MUST NAME THE DOCUMENT THE PRELUDE RESOLVED. The key is not a
    # path: outside a repository it is the absolute path with its leading `/`
    # removed, and only `derive_paths_from_manifest` knows which reading applies.
    # A shift that joined the key onto the home worktree itself passed
    # `<worktree>/Users/…/docs/x.md`, the stage wrote the document there, and the
    # freeze check, the audit and the implementation all looked at `DOC` and found
    # nothing — measured. The snapshot carries `DOC` as `design_doc` so no shift
    # composes it; this refuses the dispatch that composed one anyway. A base
    # run's design stage is the same dispatch under another slash command, so
    # it is held to the same path.
    #
    # THE AUDIT, THE SPLIT AND THE RE-CONVERGENCE ARE HELD TO IT TOO, and more
    # strictly. Every check standing around those acts — the predecessor's
    # `정상 완료`, the freeze, the split's registry predicate — reads `DOC`, so an
    # audit over another path would still leave the `정상 완료` row that clears
    # the split, and a split over another path publishes tracker tickets from
    # bytes nobody froze or audited. Their prompt must also BEGIN with the step's
    # own slash command: matched anywhere, a command quoted later in the prompt
    # would be the one whose argument is compared.
    #
    # NOT ON A `--resume`. A re-attachment, a continuation and a halt answer
    # carry a fixed sentence, never the slash command, and the session they
    # resume is pinned further down to this step's own `stage-result` rows — the
    # rows of a dispatch that passed this check when it first started.
    local dd_prompt="" dd_arg dd_prev="" dd_cmd="" dd_path
    for dd_arg in "$@"; do
      [ "$dd_prev" = "-p" ] && dd_prompt="$dd_arg"
      dd_prev="$dd_arg"
    done
    if [ "$rs_kind" = "design" ]; then
      # THE LEADING COMMAND WINS. The router appends the intent's first line
      # verbatim, so a ticket about these skills can quote a sibling design
      # command later in the prompt; matched anywhere in a fixed order, that
      # quotation would decide which command the tier refusals below judge. A
      # prompt that begins with none of them keeps the anywhere match it had.
      case "$dd_prompt" in
        '/cc-cmds:design-discuss-unattended '*) dd_cmd='/cc-cmds:design-discuss-unattended ' ;;
        '/cc-cmds:design-base-unattended '*)    dd_cmd='/cc-cmds:design-base-unattended ' ;;
        '/cc-cmds:design-solo-unattended '*)    dd_cmd='/cc-cmds:design-solo-unattended ' ;;
        *'/cc-cmds:design-discuss-unattended '*) dd_cmd='/cc-cmds:design-discuss-unattended ' ;;
        *'/cc-cmds:design-base-unattended '*)    dd_cmd='/cc-cmds:design-base-unattended ' ;;
        *'/cc-cmds:design-solo-unattended '*)    dd_cmd='/cc-cmds:design-solo-unattended ' ;;
      esac
      # THE SELECTION FUNCTION PICKS THE SKILL, AND A LEAD-ONLY MISMATCH IS
      # REFUSED BOTH WAYS. The command is compared with `manifest_design_skill`,
      # which reads scope, tier and path by the contract sentence written on it
      # in `run.sh` (`design_tier` decides whether the graph carries the audit;
      # `design_path` records who writes a team-4 single-scope document; a plan
      # with no `design_path` key reads `discuss-audit` there). When it picks
      # the lead-only skill — a `solo` plan, or a `team-4` plan on `solo-audit`
      # — the design stage is that skill and nothing else: a discussion command,
      # or a design command this case does not know, would run a design the
      # plan did not freeze. When it picks anything else, the lead-only skill
      # would drop the discussion a person approved. The base and discussion
      # commands keep what they did before, so no plan frozen before `solo` or
      # `design_path` existed meets a new refusal.
      #
      # NOT ON A `--resume`, for the reason given above: a re-attachment carries
      # a fixed sentence and no slash command, so testing it here would refuse
      # every resume of a lead-only design stage.
      if [ -z "${GATE_RESUME:-}" ]; then
        local dd_skill
        dd_skill=$(manifest_design_skill)
        if [ "$dd_skill" = "design-solo-unattended" ] && [ "$dd_cmd" != '/cc-cmds:design-solo-unattended ' ]; then
          warn "선택 함수가 design-solo-unattended 를 고른 계획의 설계 스테이지는 /cc-cmds:design-solo-unattended 로만 띄웁니다 — 이 프롬프트는 ${dd_cmd:-알려진 설계 명령이 아닌 것}입니다"
          warn "설계 명령은 스냅숏의 design_skill 값($dd_skill)을 그대로 쓰세요"
          exit "$GATE_EXIT_RULE"
        fi
        if [ "$dd_skill" != "design-solo-unattended" ] && [ "$dd_cmd" = '/cc-cmds:design-solo-unattended ' ]; then
          warn "/cc-cmds:design-solo-unattended 는 선택 함수가 design-solo-unattended 를 고른 계획에서만 띄웁니다 — 이 계획의 design_skill 은 $dd_skill 입니다"
          warn "설계 명령은 스냅숏의 design_skill 값($dd_skill)을 그대로 쓰세요"
          exit "$GATE_EXIT_RULE"
        fi
      fi
      case "$dd_cmd" in
        ?*)
          dd_path="${dd_prompt#*"$dd_cmd"}"
          dd_path="${dd_path%% *}"
          if [ "$dd_path" != "$DOC" ]; then
            warn "설계 스테이지의 문서 인자가 매니페스트에서 해석한 경로와 다릅니다 — 인자: ${dd_path} / 해석: ${DOC}"
            warn "문서 경로는 스냅숏의 design_doc 값을 그대로 쓰세요. 설계 문서 키를 워크트리 경로에 직접 붙이지 마세요"
            exit "$GATE_EXIT_RULE"
          fi
          ;;
      esac
    elif [ -z "${GATE_RESUME:-}" ]; then
      case "$rs_kind" in
        audit)      dd_cmd='/cc-cmds:design-audit-unattended ' ;;
        split)      dd_cmd='/cc-cmds:design-base-unattended --split ' ;;
        visual)     dd_cmd='/cc-cmds:visual-unattended ' ;;
        reconverge) dd_cmd='/cc-cmds:design-reconverge ' ;;
      esac
      case "$dd_prompt" in
        "$dd_cmd"*) ;;
        *)
          warn "${rs_kind} 스테이지의 프롬프트는 ${dd_cmd}<design_doc> 으로 시작해야 합니다"
          exit "$GATE_EXIT_RULE" ;;
      esac
      dd_path="${dd_prompt#"$dd_cmd"}"
      dd_path="${dd_path%% *}"
      # The re-convergence's argument is compared below, with every dispatch
      # that carries one, against the run's document argument.
      if [ "$rs_kind" != "reconverge" ] && [ "$dd_path" != "${DOC:-}" ]; then
        warn "${rs_kind} 스테이지의 문서 인자가 매니페스트에서 해석한 경로와 다릅니다 — 인자: ${dd_path} / 해석: ${DOC:-}"
        warn "문서 경로는 스냅숏의 design_doc 값을 그대로 쓰세요"
        exit "$GATE_EXIT_RULE"
      fi
    fi

    # PREDECESSORS ARE RUN-SCOPE STEPS, so `선행` of the segment rows cannot say
    # whether they landed. Each `depends_on` of an audit, split or visual step must
    # have ended its last run-scope row `정상 완료`, and a design predecessor must
    # also have left the document frozen — an audit or a split over an
    # unfinished design reads bytes nobody settled, and the split's tracker
    # writes cannot be undone. A design predecessor with no row at all over a
    # frozen document counts as done, for the reason given above.
    #
    # THE DESIGN AND A RE-CONVERGENCE TAKE NO PREDECESSOR CHECK HERE: the design
    # opens the run, and the audit a re-convergence rides on passed this one.
    local rs_dep rs_dk rs_last rs_deps=""
    case "$rs_kind" in
      audit | split | visual)
        rs_deps=$( { manifest_plan_json 2>/dev/null \
                     | jq -r --arg id "$stage_key" '.steps[]? | select(type == "object" and .id == $id) | .depends_on[]? // empty' 2>/dev/null \
                     || true; } ) ;;
    esac
    for rs_dep in $rs_deps; do
      [ -n "$rs_dep" ] || continue
      if ! rs_dk=$(gate_run_scope_kind_of_key "$rs_dep"); then
        warn "${rs_kind} 단계 ${stage_key} 의 선행 ${rs_dep} 는 런 범위 단계표의 단계가 아닙니다 — 이 그래프는 게이트가 읽지 못합니다"
        exit "$GATE_EXIT_RULE"
      fi
      if [ "$rs_dk" = "design" ] && [ -z "$(gate_run_scope_rows "$rs_dep" design)" ] \
         && doc_is_frozen "${DOC:-}"; then
        continue
      fi
      rs_last=$(gate_run_scope_last_row "$rs_dep" "$rs_dk")
      if [ "$(gate_row_field "$rs_last" '종단 부류')" != '정상 완료' ]; then
        warn "${rs_kind} 단계 ${stage_key} 의 선행 ${rs_dep} 가 아직 정상 완료로 끝나지 않았습니다 (마지막 행 종단 부류=$(gate_row_field "$rs_last" '종단 부류'))"
        warn "선행이 정상 완료로 끝난 뒤에 다시 디스패치하세요"
        exit "$GATE_EXIT_RULE"
      fi
      # An audit predecessor has ended only when it has concluded: one that
      # asked for a skeletal re-convergence, or one a re-convergence came after,
      # still has an audit to run.
      if [ "$rs_dk" = "audit" ] && ! gate_audit_concluded "$rs_dep"; then
        warn "${rs_kind} 단계 ${stage_key} 의 선행 ${rs_dep} 가 아직 정상 완료로 끝나지 않았습니다 — 감사 단계(${rs_dep})가 $GATE_AUDIT_WHY"
        warn "선행이 정상 완료로 끝난 뒤에 다시 디스패치하세요"
        exit "$GATE_EXIT_RULE"
      fi
      if [ "$rs_dk" = "design" ] && ! doc_is_frozen "${DOC:-}"; then
        warn "${rs_kind} 단계 ${stage_key} 의 선행 설계 단계 ${rs_dep} 는 끝났지만 설계 문서가 동결되어 있지 않습니다"
        exit "$GATE_EXIT_RULE"
      fi
    done
  elif [ "$kind" = "skill" ] && [ -z "$(gate_segment_field "$segment" '상태')" ]; then
    warn "세그먼트 ${segment} 의 segment 행이 없습니다 — 스테이지를 띄우기 전에 act --kind segment 로 그 행을 먼저 쓰세요"
    warn "그 행이 없으면 진전 벡터가 움직일 수 없어 정상 스테이지 위에서 정체 경계가 발화하고, 종료 조건 1 도 이 세그먼트를 세지 못합니다"
    exit "$GATE_EXIT_RULE"
  fi
  # A SEGMENT HELD ON A PERSON-SET QUESTION (`사람-결정`, `시각-승인`) IS NOT
  # DISPATCHED TO. The question
  # is open because only a person can say what that segment does next, and a
  # stage or a re-plan sent there meanwhile would be the router answering it.
  # Every other segment is routed as before; the hold is the question's
  # `막는 세그먼트` and nothing wider.
  if { [ "$kind" = "skill" ] || [ "$kind" = "replan" ]; } && [ "$segment" != "-" ]; then
    local ph_id
    ph_id=$(gate_segment_person_hold "$segment")
    if [ -n "$ph_id" ]; then
      warn "세그먼트 ${segment} 는 $(gate_approval_field "$ph_id" '판단 부류') 판단 승인 ${ph_id} 의 답을 기다리고 있습니다 — 답이 오기 전에는 이 세그먼트로 ${kind} 를 보내지 않습니다"
      warn "보류 집합 밖의 세그먼트를 계속 라우팅하세요. 답이 오면 answered_judgments 에 나타납니다"
      exit "$GATE_EXIT_RULE"
    fi
  fi
  # A SCREEN SLICE IS NOT IMPLEMENTED BEFORE ITS SCREENS ARE APPROVED. While the
  # run waits, an open `시각-승인` holds the segment above; this refusal is the
  # predicate's own defence for the case the hold does not cover — an approval
  # adopted and the sidecar's implementation-approval line removed or voided
  # afterwards — and a person's `거부` or `무효` on the segment's `시각-승인`
  # refuses it for the rest of the run, consumed or not, whatever the sidecar
  # says (`gate_segment_visual_refusal`).
  if [ "$kind" = "skill" ] && [ "${1:-}" = "implement" ] && [ "$segment" != "-" ] \
     && gate_segment_screen_slice "$segment"; then
    local ss_why ss_ref
    ss_ref=$(gate_segment_visual_refusal "$segment")
    if [ -n "$ss_ref" ]; then
      warn "세그먼트 ${segment} 는 화면 슬라이스인데 사람이 시각-승인 판단 승인 ${ss_ref} 을 $(gate_approval_state "$ss_ref") 로 닫았습니다 — 이 런에서는 그 화면의 구현을 보내지 않습니다"
      warn "그 세그먼트는 park 로 두고, 그 화면이 필요한 조항은 그 답을 근거로 불가능으로 정산하세요"
      exit "$GATE_EXIT_RULE"
    fi
    if ! ss_why=$(gate_visual_approval_holds); then
      warn "세그먼트 ${segment} 는 화면 슬라이스인데 설계 문서의 구현 승인이 서지 않습니다 (${ss_why}) — 화면이 승인되기 전에는 구현을 보내지 않습니다"
      warn "고정 좌석에서 /cc-cmds:visual 로 화면을 승인해 사이드카에 구현 승인 줄을 다시 쓴 뒤 디스패치하세요"
      exit "$GATE_EXIT_RULE"
    fi
  fi

  # THE DOCUMENT ARGUMENT AND THE CYCLE BUDGET, the two facts the driver fixes
  # for its own dispatches and a router dispatch used to leave to the router.
  # Both are refusals about this act, so they sit with the row check, ahead of
  # the rule catalog and the approval block.
  #
  # The document argument is compared only where the prompt carries one: a
  # dispatch with none passes as it always has. Where it carries one, it must be
  # the path the driver would have put there — the design document, or the
  # anchor brief of a run without one — so a stage cannot be pointed at another
  # document under this run's authorization.
  #
  # The budget is the re-implementation cycle cap `REIMPL_CYCLE_CAP`, counted in
  # `cycle` rows only, so a crash retry or a resume spends nothing. Reaching it
  # refuses the next implement dispatch; the router then reads `다음`, which at
  # the cap is `리드 수정` or a value that ends the segment's review loop.
  # The run-scope audit's re-convergence carries the same document argument as
  # a segment's, so the comparison reaches it too.
  if [ "$kind" = "skill" ] \
     && { [ "$stage_is_run_scope_step" = "0" ] || [ "${1:-}" = "reconverge" ]; }; then
    case "${1:-}" in
      implement|review|lead-fix|reconverge)
        local da_got da_want
        da_got=$(gate_prompt_doc_arg "$1" "$(gate_skill_prompt_of "$@")")
        da_want=$(gate_doc_arg_path)
        if [ -n "$da_got" ] && [ "$da_got" != "$da_want" ]; then
          warn "${1} 파견의 문서 인자가 이 런의 문서 인자와 다릅니다 — 프롬프트 ${da_got}, 런 ${da_want}"
          warn "스냅숏의 「문서 인자」 값을 그대로 첫 문서 인자로 실어 다시 파견하세요"
          exit "$GATE_EXIT_RULE"
        fi
        ;;
    esac
    # A BASE RESOLUTION IS AN IMPLEMENT DISPATCH WHOSE PROMPT CARRIES
    # `베이스 해소: <sha>`, and it spends the base resolution's allowance, not the
    # cycle budget. It is dispatched only while `다음` is `베이스 해소`, and only
    # onto the base the segment's latest `베이스 판정` row named: a base the
    # router picked would merge a tree no check judged.
    local br_dir
    br_dir=""
    if [ "${1:-}" = "implement" ]; then
      br_dir=$(printf '%s\n' "$(gate_skill_prompt_of "$@")" | awk '
        !got && /베이스 해소:/ { s = $0; sub(/.*베이스 해소:[ \t]*/, "", s); n = split(s, w, /[ \t]+/)
                                print "T:" (n > 0 ? w[1] : ""); got = 1 }')
    fi
    if [ -n "$br_dir" ]; then
      local br_next br_t br_want br_c1 br_c2 br_wt br_rejoin=""
      br_next=$(gate_segment_review_next "$segment")
      br_t=${br_dir#T:}
      # A REJOIN IS A BASE RESOLUTION WITH NO CONFLICT. A segment whose CI
      # waits on a base-branch failure the base has since fixed takes the base
      # in, so its prompt carries `부류=master 재합류` beside the directive, and
      # it is let in only while `다음` reads `master 재합류` and the latest base
      # check moved (`이동`): a check that found the base already in (`일치`)
      # leaves nothing to merge, and one that found a conflict is the base
      # resolution's. It spends no cycle budget, as a base resolution does not.
      case "$(gate_skill_prompt_of "$@")" in *'부류=master 재합류'*) br_rejoin=1 ;; esac
      if [ -n "$br_rejoin" ]; then
        if [ "$br_next" != "master 재합류" ]; then
          warn "세그먼트 ${segment} 의 다음 처분은 「${br_next}」 입니다 — master 재합류는 「다음」 이 「master 재합류」 일 때만 파견합니다"
          warn "스냅숏의 review_next[] 의 「다음」 을 읽고 그 처분으로 가세요"
          exit "$GATE_EXIT_RULE"
        fi
        if [ "$(gate_row_field "$(gate_base_last_row "$segment")" '판정')" != "이동" ]; then
          warn "세그먼트 ${segment} 의 마지막 베이스 판정이 「이동」 이 아닙니다 — master 재합류는 base-check 가 「이동」 을 적은 뒤에만 파견합니다"
          warn "base-check 를 먼저 부르고, 「일치」 면 파견하지 않으며 「충돌」 이면 「다음」 을 다시 읽으세요"
          exit "$GATE_EXIT_RULE"
        fi
      elif [ "$br_next" != "베이스 해소" ]; then
        warn "세그먼트 ${segment} 의 다음 처분은 「${br_next}」 입니다 — 베이스 해소는 「다음」 이 「베이스 해소」 일 때만 파견합니다"
        warn "스냅숏의 review_next[] 의 「다음」 을 읽고 그 처분으로 가세요"
        exit "$GATE_EXIT_RULE"
      fi
      br_want=$(gate_row_field "$(gate_base_last_row "$segment")" '베이스')
      br_wt=$(gate_act_worktree "$alias" "$segment")
      br_c1=$(gate_commit_in "$br_wt" "$br_t" || true)
      br_c2=$(gate_commit_in "$br_wt" "$br_want" || true)
      if [ -z "$br_c1" ] || [ "$br_c1" != "$br_c2" ]; then
        warn "베이스 해소 파견의 베이스 (${br_t:-없음}) 가 세그먼트 ${segment} 의 마지막 베이스 판정의 베이스 (${br_want:-없음}) 와 다릅니다"
        warn "스냅숏의 review_next[] 의 「베이스」 값을 그대로 「베이스 해소:」 뒤에 실어 다시 파견하세요"
        exit "$GATE_EXIT_RULE"
      fi
    elif [ "${1:-}" = "implement" ]; then
      local ci_dir ci_ok=""
      # A CI FIX IS AN IMPLEMENT DISPATCH WHOSE PROMPT CARRIES `CI 수정: <sha>`.
      # It is let in only while `다음` reads `CI 수정` and only onto the head that
      # failed twice, and it spends the CI fix allowance rather than the cycle
      # budget — a segment whose review passed has usually used that budget up.
      # The row that spends the allowance is written by `act` alone and once per
      # (segment, head): a forecast, a dispatch refused further on and a stage
      # that died before its commit leave the head as it was, and the same head
      # is dispatched again rather than counted again.
      # The sha is the hex run after the colon: the prompt quotes the whole
      # directive, so the closing quote follows the sha with no space between.
      ci_dir=$(printf '%s\n' "$(gate_skill_prompt_of "$@")" | awk '
        !got && /CI 수정:/ { s = $0; sub(/.*CI 수정:[ \t]*/, "", s); t = ""
                            if (match(s, /^[0-9a-fA-F]+/)) t = substr(s, 1, RLENGTH)
                            print "T:" t; got = 1 }')
      if [ -n "$ci_dir" ]; then
        local ci_next ci_h ci_t ci_v
        ci_next=$(gate_segment_review_next "$segment")
        ci_h=$(gate_worktree_tip "$(gate_act_worktree "$alias" "$segment")" || true)
        ci_t=${ci_dir#T:}
        if [ "$ci_next" != "CI 수정" ]; then
          warn "세그먼트 ${segment} 의 다음 처분은 「${ci_next}」 입니다 — CI 수정은 「다음」 이 「CI 수정」 일 때만 파견합니다"
          warn "스냅숏의 review_next[] 의 「다음」 을 읽고 그 처분으로 가세요"
          exit "$GATE_EXIT_RULE"
        fi
        if [ -z "$ci_h" ] || [ "$ci_t" != "$ci_h" ]; then
          warn "CI 수정 파견의 sha (${ci_t:-없음}) 가 세그먼트 ${segment} 의 워크트리 HEAD (${ci_h:-없음}) 가 아닙니다"
          warn "스냅숏의 review_next[] 의 「head sha」 값을 그대로 「CI 수정:」 뒤에 실어 다시 파견하세요"
          exit "$GATE_EXIT_RULE"
        fi
        ci_ok=1
        if [ "$verb" = "act" ] && [ "$(cc_ci_round_get "$(cc_ci_round "$LEDGER" "$segment" "$ci_h")" fix)" != "1" ]; then
          ci_v=$(gate_ci_verdict_row "$segment" "$ci_h" \
            "$(cc_ci_round_get "$(cc_ci_round "$LEDGER" "$segment" "$ci_h")" g)")
          gate_append 'CI 처분' "세그먼트=$segment" "PR=$(gate_row_field "$ci_v" 'PR')" \
            "head sha=$ci_h" "처분=수정" "상태=-" "회차=-" "실행=-" "워크플로=-" \
            "실패 체크=$(gate_row_safe "$(gate_row_field "$ci_v" '실패 체크')" "$GATE_CHECKS_FAIL_MAX")" \
            "기본 브랜치=-" "응답=-" "관측=$(date -u +%Y-%m-%dT%H:%M:%SZ)"
        fi
      fi
      # A CI JOIN IS A REVIEW FIX DISPATCH WHOSE PROMPT ALSO CARRIES
      # `CI 합류: <sha>`: the review's findings and the CI failure that survived
      # its rerun go to one implement stage. It is let in only while `다음` reads
      # `CI 합류 수정` and only onto the head that failed, and while `다음` reads
      # that value a review fix dispatch without the line is refused — sent
      # without it, the failure is dropped and the new head fails again. A
      # `--resume` dispatch continues a stage that already got its prompt and is
      # left alone. While `다음` waits on CI or on its rerun, a review fix dispatch
      # is refused too: the verdict decides whether the failure joins the fix.
      # Unlike a CI fix, a join spends the cycle budget as a review fix does.
      local cj_dir cj_next cj_h cj_t cj_v cj_prompt
      cj_prompt=$(gate_skill_prompt_of "$@")
      cj_dir=$(printf '%s\n' "$cj_prompt" | awk '
        !got && /CI 합류:/ { s = $0; sub(/.*CI 합류:[ \t]*/, "", s); t = ""
                            if (match(s, /^[0-9a-fA-F]+/)) t = substr(s, 1, RLENGTH)
                            print "T:" t; got = 1 }')
      cj_next=$(gate_segment_review_next "$segment")
      if [ -n "$cj_dir" ]; then
        cj_h=$(gate_worktree_tip "$(gate_act_worktree "$alias" "$segment")" || true)
        cj_t=${cj_dir#T:}
        if [ "$cj_next" != "CI 합류 수정" ]; then
          warn "세그먼트 ${segment} 의 다음 처분은 「${cj_next}」 입니다 — CI 합류는 「다음」 이 「CI 합류 수정」 일 때만 파견합니다"
          warn "스냅숏의 review_next[] 의 「다음」 을 읽고 그 처분으로 가세요"
          exit "$GATE_EXIT_RULE"
        fi
        if [ -z "$cj_h" ] || [ "$cj_t" != "$cj_h" ]; then
          warn "CI 합류 파견의 sha (${cj_t:-없음}) 가 세그먼트 ${segment} 의 워크트리 HEAD (${cj_h:-없음}) 가 아닙니다"
          warn "스냅숏의 review_next[] 의 「head sha」 값을 그대로 「CI 합류:」 뒤에 실어 다시 파견하세요"
          exit "$GATE_EXIT_RULE"
        fi
        if [ "$verb" = "act" ] && [ -z "$(gate_rows 'CI 처분' | gate_rows_field_eq '세그먼트' "$segment" \
             | gate_rows_field_eq 'head sha' "$cj_h" | gate_rows_field_eq '처분' '합류')" ]; then
          cj_v=$(gate_ci_verdict_row "$segment" "$cj_h" \
            "$(cc_ci_round_get "$(cc_ci_round "$LEDGER" "$segment" "$cj_h")" g)")
          gate_append 'CI 처분' "세그먼트=$segment" "PR=$(gate_row_field "$cj_v" 'PR')" \
            "head sha=$cj_h" "처분=합류" "상태=-" "회차=-" "실행=-" "워크플로=-" \
            "실패 체크=$(gate_row_safe "$(gate_row_field "$cj_v" '실패 체크')" "$GATE_CHECKS_FAIL_MAX")" \
            "기본 브랜치=-" "응답=-" "관측=$(date -u +%Y-%m-%dT%H:%M:%SZ)"
        fi
      elif [ "$cj_next" = "CI 합류 수정" ] && [ -z "${GATE_RESUME:-}" ]; then
        warn "세그먼트 ${segment} 의 다음 처분은 「CI 합류 수정」 입니다 — 리뷰 지적과 함께 「CI 합류: <head sha>」 줄을 실어 파견합니다"
        warn "스냅숏의 review_next[] 의 「head sha」 값을 그대로 「CI 합류:」 뒤에 실어 다시 파견하세요"
        exit "$GATE_EXIT_RULE"
      fi
      if [ -z "$cj_dir" ] && [ -z "$ci_dir" ]; then
        case "$cj_prompt" in
          *'수정 대상: '*' 의 P0·P1'*|*' 의 P0·P1'*'수정 대상: '*)
            case "$cj_next" in
              'CI 대기'|'CI 재실행'|'CI 대기 한도'|'CI 대조'|'master 대기'|'master 재합류'|'master 수리 불가')
                warn "세그먼트 ${segment} 의 다음 처분은 「${cj_next}」 입니다 — CI 판정이 서기 전에는 리뷰 지적 수정을 파견하지 않습니다"
                warn "스냅숏의 review_next[] 의 「다음」 을 읽고 그 처분으로 가세요"
                exit "$GATE_EXIT_RULE" ;;
            esac ;;
        esac
      fi
      # A CI fix let in above is exempt from the cycle budget, on top of the
      # exemptions `gate_implement_cycle_admissible` holds.
      if ! gate_implement_cycle_admissible "$segment" && [ -z "$ci_ok" ]; then
        warn "세그먼트 ${segment} 의 사이클 예산이 소진됐습니다 — cycle 행 ${GATE_IMPL_CYCLE_N}개, 상한 ${GATE_IMPL_CYCLE_CAP}"
        warn "구현을 다시 파견하지 말고 스냅숏의 review_next[] 의 「다음」 을 읽으세요 — 상한에서는 「리드 수정」 이나 끝내는 값입니다"
        exit "$GATE_EXIT_RULE"
      fi
    fi
    # `다음` HOLDS THE LEAD FIX AND THE REVIEW AFTER IT. The lead fix is
    # dispatched only while `다음` is `리드 수정`. That alone keeps it to one per
    # round: once a lead-fix row stands, whatever it ended as, `다음` is the
    # re-check, and a second lead fix waits for that review to ask for it. A
    # re-convergence whose prompt carries the scope `설계 수준 잔여 <report>` is
    # dispatched only while `다음` is `재수렴`, and on the report of the last
    # cycle, the one whose design-level items it reads. A review dispatch
    # with no implement or lead-fix row after the segment's last cycle row
    # passes only when the segment's tree has moved past that row's
    # `리뷰 HEAD` — the same head reviewed again writes the same report. Its
    # `--slice` must name the segment it reviews, or the report would drop that
    # segment's own findings from the count as another slice's. These reach the
    # routing path only — the driver's dispatches do not pass here, and its own
    # branch on `다음` is what holds them.
    local rn_prompt rn_next rn_slice rn_row rn_rhead rn_head
    rn_prompt=$(gate_skill_prompt_of "$@")
    case "${1:-}" in
      lead-fix)
        rn_next=$(gate_segment_review_next "$segment")
        if [ "$rn_next" != "리드 수정" ]; then
          warn "세그먼트 ${segment} 의 다음 처분은 「${rn_next}」 입니다 — 리드 수정은 「다음」 이 「리드 수정」 일 때만 파견합니다"
          warn "스냅숏의 review_next[] 의 「다음」 을 읽고 그 처분으로 가세요"
          exit "$GATE_EXIT_RULE"
        fi ;;
      reconverge)
        local rn_rp rn_want
        case "$rn_prompt" in
          *'설계 수준 잔여 '*)
            # Split the way `gate_prompt_report_path` splits: the word after
            # `설계 수준 잔여`, quotes dropped.
            rn_rp=$(printf '%s' "$rn_prompt" | tr -s ' \t' '\n\n' | tr -d "\"'" \
              | awk '!got && w3 == "설계" && w2 == "수준" && w1 == "잔여" { print; got = 1 }
                     { w3 = w2; w2 = w1; w1 = $0 }')
            rn_next=$(gate_segment_review_next "$segment")
            if [ "$rn_next" != "재수렴" ]; then
              warn "세그먼트 ${segment} 의 다음 처분은 「${rn_next}」 입니다 — 설계 수준 잔여 재수렴은 「다음」 이 「재수렴」 일 때만 파견합니다"
              warn "스냅숏의 review_next[] 의 「다음」 을 읽고 그 처분으로 가세요"
              exit "$GATE_EXIT_RULE"
            fi
            rn_want=$(gate_report_abs "$(gate_row_field "$(gate_segment_last_cycle_row "$segment")" '리포트 경로')")
            if [ -z "$rn_rp" ] || [ "$rn_rp" != "$rn_want" ]; then
              warn "설계 수준 잔여 재수렴의 리포트 (${rn_rp:-없음}) 가 세그먼트 ${segment} 의 마지막 cycle 행 리포트 (${rn_want}) 와 다릅니다"
              warn "스냅숏의 review_next[] 의 「리포트 경로」 값을 그대로 실어 다시 파견하세요"
              exit "$GATE_EXIT_RULE"
            fi ;;
        esac ;;
      review)
        rn_row=$(gate_segment_last_cycle_row "$segment")
        if [ -n "$rn_row" ] && ! gate_segment_authored_after_last_cycle "$segment"; then
          rn_rhead=$(gate_row_field "$rn_row" '리뷰 HEAD')
          rn_head=$( { cd "$(gate_act_worktree "$alias" "$segment")" 2>/dev/null \
                       && git --no-optional-locks rev-parse HEAD 2>/dev/null; } || true)
          case "$rn_head" in
            "$rn_rhead"*)
              if [ -n "$rn_rhead" ]; then
                warn "세그먼트 ${segment} 의 마지막 cycle 행 뒤에 구현·리드 수정 행이 없고 작업 트리 HEAD 가 그 행의 리뷰 HEAD (${rn_rhead}) 그대로입니다 — 같은 HEAD 를 다시 리뷰하지 않습니다"
                warn "스냅숏의 review_next[] 의 「다음」 을 읽으세요"
                exit "$GATE_EXIT_RULE"
              fi ;;
          esac
        fi
        # awk splits the words, not the shell: an unquoted expansion would
        # glob a prompt that carries `*`.
        rn_slice=$(printf '%s\n' "$rn_prompt" | awk '
          !got { for (i = 1; i <= NF; i++) if ($i == "--slice") { print "S:" (i < NF ? $(i + 1) : ""); got = 1; break } }')
        if [ -n "$rn_slice" ] && [ "${rn_slice#S:}" != "$segment" ]; then
          rn_slice=${rn_slice#S:}
          warn "리뷰 파견의 --slice (${rn_slice:-없음}) 가 --segment ${segment} 와 다릅니다 — 다른 슬라이스의 범위로 리뷰하면 이 세그먼트의 발견이 집계에서 빠집니다"
          exit "$GATE_EXIT_RULE"
        fi
        # A branch whose enforcement surface changed outside a seat apply is
        # not reviewed: the review would pass bytes nobody approved on to the
        # merge. The hold writes the cone `blocked` row once and says why; a
        # forecast writes nothing and answers with the same code. A check that
        # could not be decided refuses too, under a reason of its own.
        rn_pvrc=0
        rn_pv=$(gate_surface_provenance "$segment" "$alias") || rn_pvrc=$?
        if [ "$rn_pvrc" = "$GATE_EXIT_RULE" ]; then
          [ "$verb" = "plan" ] || gate_surface_provenance_hold "$segment" >/dev/null 2>&1 || true
          warn "세그먼트 ${segment} 의 브랜치에서 강제 표면이 좌석 적용 밖에서 바뀌었습니다 — 리뷰를 파견하지 않습니다: $(printf '%s' "$rn_pv" | tr '\t\n' ' ;')"
          exit "$GATE_EXIT_RULE"
        elif [ "$rn_pvrc" != 0 ]; then
          if [ "$verb" != "plan" ] \
             && ! gate_has_row 'blocked' "앵커 세그먼트=$segment" '사유=강제 표면 출처 판정 불가'; then
            gate_append 'blocked' "대상=${CC_PIPELINE_TARGET:--}" "스코프=cone" "원인=판정 불가" \
              "앵커 세그먼트=$segment" '사유=강제 표면 출처 판정 불가' \
              "근거=$(gate_row_safe "$(printf '%s' "$rn_pv" | tr '\t\n' ' ;')" 300)" \
              "관측=$(now_iso)" \
              "재개 명령=세그먼트 워크트리와 HEAD, 플러그인의 분류 라이브러리를 복구한 뒤 같은 리뷰를 다시 파견하세요" || true
          fi
          warn "세그먼트 ${segment} 의 강제 표면 출처를 판정할 수 없습니다 — 리뷰를 파견하지 않습니다: $(printf '%s' "$rn_pv" | tr '\t\n' ' ;')"
          exit "$GATE_EXIT_RULE"
        fi ;;
    esac
  fi

  # A REVIEW DISPATCH RECORDS ITS REPORT PATH, AND A RECOVERY IS HELD TO IT.
  # Both are refusals about this act, so they sit here, ahead of the boundaries
  # and the approval row. `--recovery` is a review's marker only — on any other
  # dispatch it is out of range, exit 2. Its premises are the ledger's, and one
  # that fails is exit 3 with no row: the re-dispatch repeats an authorized
  # dispatch, and only a review that died of a dropped connection with nothing
  # saved may repeat it.
  #
  # The path rides on the row as a fixed field and is never clipped: a clipped
  # path would make the recovery's comparison silently wrong. So the fixed
  # fields are measured here with the widest values the row can take, and a
  # path they cannot hold refuses the dispatch, exit 2, the way the `중단 답`
  # writer refuses a record that does not fit.
  local rv_rp=""
  if [ "$kind" = "skill" ] && [ "${1:-}" = "review" ]; then
    rv_rp=$(gate_prompt_report_path "$(gate_skill_prompt_of "$@")")
  fi
  if [ -n "$GATE_RECOVERY" ]; then
    if [ "${1:-}" != "review" ]; then
      printf 'gate: --recovery is used only on a review dispatch (stage kind received: %s)\n' "${1:-(none)}" >&2
      exit "$GATE_EXIT_VOCAB"
    fi
    local rv_why
    rv_why=$(gate_review_recovery_refusal "$segment" "$rv_rp")
    if [ -n "$rv_why" ]; then
      warn "전송 단절 재파견 거절 — $rv_why"
      warn "이 리뷰는 전송 단절 재파견 대상이 아닙니다 — 리뷰 복구의 다른 갈래나 그 자리의 park 문면으로 가세요"
      exit "$GATE_EXIT_RULE"
    fi
  fi
  # A REVIEW DISPATCH NAMES THE CANONICAL REPORT AND DECLARES WHY IT GOES.
  # Both checks run on `act` and `plan` alike — the forecast must give the
  # act's answer — on a review dispatch that is not a recovery: a `--recovery`
  # re-dispatch and a prompt carrying `--recover` repeat an earlier dispatch,
  # are held to its path above, and inherit its trigger rather than declaring
  # one.
  #
  # The path is `gate_review_report_path`, the one the review line prints;
  # anything else — none at all included — is refused, exit 2, and a report the
  # router named could otherwise land on another review's.
  #
  # The trigger is one token of the closed vocabulary. A token the ledger
  # stands behind (`gate_cycle_trigger_facts`) is taken whatever else F holds:
  # the router names the reason it actually dispatched, and the gate ranks
  # nothing. `라우터 판단` is taken only when F is empty and a reason is given.
  # Anything else is exit 2 with no row and no park, and the refusal prints F so
  # one copy settles the redeclaration.
  local rv_trig="" rv_recov=0
  if [ "$kind" = "skill" ] && [ "${1:-}" = "review" ]; then
    if [ -n "$GATE_RECOVERY" ] \
       || printf '%s\n' "$(gate_skill_prompt_of "$@")" | awk '{ for (i = 1; i <= NF; i++) if ($i == "--recover") f = 1 } END { exit !f }'; then
      rv_recov=1
    fi
  fi
  if [ -n "$GATE_TRIGGER_SEEN" ]; then
    if [ "$kind" != "skill" ] || [ "${1:-}" != "review" ]; then
      printf 'gate: --trigger and --trigger-reason are used only on a review dispatch (stage kind received: %s)\n' "${1:-(none)}" >&2
      exit "$GATE_EXIT_VOCAB"
    fi
    if [ "$rv_recov" = "1" ]; then
      printf 'gate: a recovery review dispatch declares no trigger — it inherits the trigger of the dispatch it repeats\n' >&2
      exit "$GATE_EXIT_VOCAB"
    fi
  fi
  if [ "$kind" = "skill" ] && [ "${1:-}" = "review" ] && [ "$rv_recov" = "0" ]; then
    local rv_want rv_f rv_ok=0
    rv_want=$(gate_review_report_path "$segment")
    if [ -z "$rv_rp" ] || [ "$(gate_report_norm "$(gate_report_abs "$rv_rp")")" != "$(gate_report_norm "$rv_want")" ]; then
      warn "리뷰 파견의 --report-path (${rv_rp:-없음}) 가 세그먼트 ${segment} 의 정본 리포트 경로 (${rv_want}) 와 다릅니다"
      warn "gate.sh review-line --segment ${segment} 가 찍는 경로를 그대로 실어 다시 파견하세요"
      exit "$GATE_EXIT_VOCAB"
    fi
    rv_f=$(gate_cycle_trigger_facts "$segment")
    case "|$GATE_TRIGGER_TOKENS|" in
      *"|$GATE_TRIGGER|"*) [ -n "$GATE_TRIGGER" ] && rv_ok=1 ;;
    esac
    if [ "$rv_ok" = "1" ]; then
      rv_ok=0
      if [ "$GATE_TRIGGER" = "라우터 판단" ]; then
        [ -z "$rv_f" ] && [ -n "$GATE_TRIGGER_REASON" ] && rv_ok=1
      elif [ -z "$GATE_TRIGGER_REASON" ] && grep -qxF -- "$GATE_TRIGGER" <<<"$rv_f"; then
        rv_ok=1
      fi
    fi
    if [ "$rv_ok" != "1" ]; then
      warn "리뷰 파견의 계기 (${GATE_TRIGGER:-없음}) 를 원장 사실과 대조해 받지 않았습니다 — F = {$(printf '%s\n' "$rv_f" | awk 'NF { printf "%s%s", (n++ ? ", " : ""), $0 }')}"
      warn "F 안의 토큰 하나를 --trigger '<토큰>' 으로 다시 선언하세요. F 가 비었을 때만 --trigger '라우터 판단' --trigger-reason '<사유>' 를 받고, --trigger-reason 은 그때만 씁니다"
      exit "$GATE_EXIT_VOCAB"
    fi
    rv_trig=$GATE_TRIGGER
  fi
  if [ -n "$rv_rp" ]; then
    local rv_len
    rv_len=$(gate_row_projected_bytes '자율 승인' "kind=$kind" "결정=$verb" "대상=$alias" "세그먼트=$segment" \
      "절단점=$cutpoint" "유도 절단점=$cutpoint" "축2=외부상태변경" "자격=주변" "행위자=스테이지" \
      "리포트 경로=$rv_rp" ${rv_trig:+"계기=$rv_trig"} ${GATE_RECOVERY:+"복구=$GATE_RECOVERY"} "근거=")
    if [ "$rv_len" -gt "$GATE_ROW_MAX" ]; then
      warn "리포트 경로가 길어 리뷰 파견 행이 행 상한 (${GATE_ROW_MAX}바이트) 을 넘습니다 — 경로는 자르지 않으므로 이 파견을 거절합니다: $rv_rp"
      exit "$GATE_EXIT_VOCAB"
    fi
  fi

  # ONE DISPATCH PER KEY ON A ROUTED RUN, refused before any row about this act.
  # The authorization row comes later and the attempt derivation counts it, so a
  # refusal any later would leave a row that moves a waiting dispatch's attempt.
  # The act holds the key's dispatch lock from here until it exits, settles a
  # waiter of this key that died since the prelude, and only then asks whether
  # the key is still in flight. `plan` takes no lock and answers the same
  # question by reading.
  if [ "$kind" = "skill" ] && run_routed; then
    if [ "$verb" = "act" ]; then
      if ! gate_dispatch_lock_take "$stage_key"; then
        warn "another act is dispatching $stage_key right now — do not dispatch it again; gate.sh wait --segment $stage_key"
        exit "$GATE_EXIT_INFLIGHT"
      fi
      gate_settle_dead_waiters "$stage_key"
      if gate_key_in_flight "$stage_key"; then
        warn "$stage_key is already in flight (a live supervisor, stage or waiter) — do not dispatch it again; gate.sh wait --segment $stage_key"
        exit "$GATE_EXIT_INFLIGHT"
      fi
    elif [ "$verb" = "plan" ]; then
      if { [ -f "$RUN_DIR/$stage_key.dispatching" ] && gate_dispatch_lock_holder_live "$RUN_DIR/$stage_key.dispatching"; } \
         || gate_key_in_flight "$stage_key"; then
        warn "$stage_key is already in flight — an act would be refused with $GATE_EXIT_INFLIGHT"
        exit "$GATE_EXIT_INFLIGHT"
      fi
    fi
  fi

  # A CARRY ACT HANDS A PERSON'S HALT ANSWER TO THE KEY'S NEXT ATTEMPT. Its
  # checks come after the in-flight refusal, so a key still running is refused
  # the way every dispatch is, and before every row about this act, so a refused
  # carry leaves the answer where it was. The dispatch form itself has already
  # met the prompt-head and document-argument checks a fresh dispatch meets.
  GATE_HA_LINE=''; GATE_HA_BOUND=''; GATE_HA_SCOPE=''
  if [ -n "$GATE_CARRY_ANSWER" ]; then
    local ha_rc=0
    gate_carry_check "$alias" "$stage_key" "${1:-}" "$(gate_skill_prompt_of "$@")" || ha_rc=$?
    [ "$ha_rc" = "0" ] || exit "$ha_rc"
  elif [ "$kind" = "skill" ] && { [ "$verb" = "act" ] || [ "$verb" = "plan" ]; }; then
    # AN ANSWER AN EARLIER RUN CARRIED OVER GOES ON ONLY THROUGH A CARRY ACT.
    # Any other dispatch of its key would land a `stage-result` that spends the
    # answer by position with no card in the session's hands. A re-kickoff's
    # first dispatch of a run-scope step brings such an answer in and is
    # refused here; a later dispatch, and an adopted segment's first one, finds
    # it already in and is refused the same way.
    local ci_rc=0 ci_ln
    gate_chain_halt_import "$stage_key" "$verb" || ci_rc=$?
    [ "$ci_rc" = "0" ] || exit "$ci_rc"
    ci_ln=$(gate_key_imported_deferred_answer "$stage_key")
    if [ -n "$ci_ln" ]; then
      warn "${stage_key} 에는 앞선 런이 다음 런으로 넘긴 중단 답(원장 ${ci_ln} 번째 줄)이 아직 쓰이지 않고 있습니다 — 이 파견은 띄우지 않습니다. 그 답은 --carry-answer ${ci_ln} 로 내세요"
      exit "$GATE_EXIT_RULE"
    fi
  fi

  # WHERE THIS ACT WILL RUN, AND NO SILENT FALLBACK. A segment row naming a
  # worktree that is not this target's would send the act to the target's own
  # tree instead — which is exactly how every stage ended up in the shared main
  # worktree. The repair is the merge's repair (fix the segment row, call again
  # with the same argv), so the code is the merge's too.
  #
  # `exec` AND NOT ONLY A STAGE DISPATCH. The dispatch got this refusal first and
  # `exec` was left on the fallback, which put the original defect back on the
  # one verb that runs `git commit`, `git push` and `gh pr create`. There the
  # fallback is silent end to end: both candidate directories exist, so the `cd`
  # succeeds and the act simply lands in the main worktree with nothing said.
  #
  # RECORDING KINDS ARE DELIBERATELY OUT. `act --kind segment` is the only way to
  # repair a segment row, so refusing it on the strength of that same row would
  # brick the run at precisely the command the message below tells the reader to
  # run. What is left out is exactly that: the bookkeeping kinds, `propose-done`
  # and `router-shift`, none of which enters the resolved tree at all.
  #
  # AND THE DOMAIN IS THE DISPATCH SWITCH'S OWN CLASSIFICATION, not a list of
  # verb names. This block used to name `skill` and `exec`, which left every
  # other kind using the resolution without passing through here — `merge` among
  # them, and a merge is recognised by its CUTPOINT rather than by its kind, so
  # no enumeration of names ever closed it. `gate_act_enters_resolved_tree`
  # answers from the switch itself, so the two cannot drift apart when a kind is
  # added.
  #
  # NOT ON AN UNDECLARED TARGET, AND THE GUARD IS THE SAME ONE THE RESOLUTION
  # CARRIES. This refusal exists to protect that resolution, so the two must ask
  # about the same tree; they did not. An undeclared alias has no target row, so
  # its `공통 git 디렉터리` is the empty string and the predicate fails for every
  # segment row however correct that row is — and the act does not enter the
  # row's tree anyway, because the arm above sends it to the caller's
  # `--worktree`. What went out was exit 10 telling the reader to repair a row
  # that was already right, which is a refusal with no repair behind it.
  #
  # A ROW NAMING ANOTHER DECLARED TARGET'S WORKTREE IS WARNED ABOUT, NOT REFUSED.
  # That tree is one this run already acts in, so the prescribed repair would be
  # breaking a true row; what was wrong in that case was only that the fallback
  # was silent. So the act still falls back to this target's own tree and two
  # lines name who owns the row's tree and where the act really runs. The values
  # that name no declared target's tree at all — another repository, a path that
  # is gone, a relative one — are refused exactly as before.
  if [ -n "$segment" ] && [ "$segment" != "-" ] \
     && [ "${GATE_UNDECLARED:-0}" != "1" ] \
     && gate_act_enters_resolved_tree "$verb" "$kind"; then
    local seg_wt seg_why seg_other
    seg_wt=$(gate_segment_worktree "$segment")
    case "$seg_wt" in
      ''|-|'(없음)') : ;;
      *)
        if ! gate_segment_worktree_of_target "$segment" "$alias" >/dev/null; then
          if seg_other=$(gate_segment_worktree_other_target "$segment" "$alias"); then
            warn "세그먼트 ${segment} 의 워크트리 '${seg_wt}' 는 대상 '$alias' 이 아니라 대상 '${seg_other}' 의 워크트리입니다"
            warn "이 행위는 대상 '$alias' 의 트리 '${GATE_ACT_CWD}' 에서 돕니다 — 세그먼트 행이 가리키는 트리가 아닙니다"
          else
            case "$seg_wt" in
              /*) if [ ! -d "$seg_wt" ]; then
                    seg_why="디렉터리가 없습니다"
                  else
                    seg_why="대상 '$alias' 의 공통 git 디렉터리와 다릅니다"
                  fi ;;
              *)  seg_why="절대 경로가 아닙니다" ;;
            esac
            warn "세그먼트 ${segment} 의 워크트리 '${seg_wt}' 는 대상 '$alias' 의 워크트리가 아닙니다 — ${seg_why}"
            warn "이 행위가 어디서 도는지 말할 수 없어 수행하지 않습니다 — 세그먼트 행의 워크트리를 고쳐 같은 argv 로 다시 부르세요"
            exit "$GATE_EXIT_ANCHOR"
          fi
        fi ;;
    esac
  fi

  # THE GRADING BASE IS THE DIRECTORY THE ACT ACTUALLY RUNS IN, and it is handed
  # over IN-PROCESS rather than through the environment: the exported copy is
  # visible to children too, and a child must not grade against its parent's
  # tree. `plan` is not excluded — it forecasts what `act` would do, so it has to
  # resolve what `act` would resolve.
  #
  # THE BASE IS RESOLVED HERE, NOT INHERITED. Reading `GATE_ACT_CWD` at this point
  # could only ever pick up an EXPORTED value, because this process does not
  # assign it until 200-odd lines below — so the two write guards measured their
  # relative operands against the OUTER run's worktree and a stage reached a
  # fail-open with ordinary flags: `--segment` defaults to `-`, so a stage running
  # in a segment worktree that names only a target gets the main worktree as the
  # act's directory while the operand is absolutized against the segment's, and
  # `cp /tmp/evil plugins/cc-cmds/orchestrator/gate.sh` then passes both guards
  # and lands on the live installed gate. The comment on `gate_grade_cwd()`
  # already claims the value is always one THIS process computed; this line is
  # what makes that claim true.
  #
  # THE SAME RESOLVER, THE SAME ARGUMENTS, so this and the assignment below cannot
  # disagree — `gate_act_worktree` is a pure resolver and `gate_act_worktree`'s own
  # comment requires its three readers to resolve identically.
  #
  # `grade` KEEPS TODAY'S BEHAVIOUR, and that is the correct base for it rather
  # than a fallback failure. `grade` answers about the caller, so it leaves
  # `GATE_GRADE_CWD` empty and falls to `$PWD` in `gate_grade_cwd()`. Refusing
  # when the value is absent would refuse every `grade` instead, which is a
  # different decision than this one.
  #
  # AN UNDECLARED TARGET IS NO LONGER EXCLUDED. It was, on the reasoning that
  # its act "stays in the caller's directory because there is no row to read" —
  # but the act did not stay there: the assignment above put it in the
  # `--worktree` the caller named, while this block left the base empty and
  # `gate_grade_cwd()` fell to `$PWD`. So the base and the tree root answered
  # about the gate's own directory while the act ran elsewhere, and a relative
  # write under an undeclared target graded `워크트리쓰기` wherever it landed.
  # `gate_act_worktree` now answers for the undeclared arm too, so the base
  # takes the same value the act runs in.
  if [ "$verb" != "grade" ]; then
    local actwt
    actwt=$(gate_act_worktree "$alias" "$segment")
    [ "${GATE_ADMIT:-}" != "1" ] || actwt="$GATE_ADMIT_CWD"
    if [ -n "$actwt" ]; then
      GATE_GRADE_CWD=$(gate_real_prefix "$actwt")
    fi
  fi

  local graded
  case "$kind" in
    propose-done)
      graded="읽기" ;;
    skill|router-shift)
      # A stage dispatch's argv does NOT begin with a command: its first token
      # is the STAGE KIND that selects a settings variant, and the wrapper is
      # what eventually runs a binary. Feeding that token to the argv0 table
      # asked a question the table cannot answer, so every stage dispatch graded
      # `등급 미상` and fell into the pre-authorization rule's external-state
      # arm — which made dispatching any stage impossible.
      #
      # The grade is `워크트리쓰기`, and it is not a guess: the stage runs under
      # the read-scoped credential and inside a settings file that denies what
      # this run does not authorize, so what it can reach on its own is the
      # tree. Anything it does ABOVE that grade goes back through this gate as
      # its own act and is graded there.
      #
      # A ROUTING SHIFT HAS THE SAME SHAPE AND WAS LEFT OUT OF IT. Its first
      # token is the handoff reason — `상한`, `승인` — which is no more a command
      # than a stage kind is, so it graded `등급 미상` and the launcher could not
      # be reached at all: declared `읽기` the act came back 6, declared not at
      # all it came back 2. It starts its successor the way a stage dispatch
      # starts one, under the same read-scoped credential, so it takes the same
      # grade rather than a second answer to one question.
      graded="워크트리쓰기" ;;
    apply)
      # The argv is a token and not a command, so the table has nothing to say;
      # what the act performs is the frozen apply command, which changes state
      # outside the tree by definition.
      graded="외부상태변경" ;;
    ci-rerun|label-ack)
      # The same: `재실행 <sha>` and `라벨 <sha>` are tokens, and what the act
      # performs is the gate's own POST to GitHub, a change of state outside
      # the tree.
      graded="외부상태변경" ;;
    ci-match)
      # `대조 <sha>` is a token as well; what the act performs is GETs and the
      # ledger row, so it reads.
      graded="읽기" ;;
    *)
      if gate_kind_is_bookkeeping "$kind"; then
        # A bookkeeping act: its argv is a list of `키=값` fields, not a command,
        # and what it performs is the ledger row the gate would write anyway. It
        # reaches nothing outside the ledger, so it grades `읽기`.
        #
        # THE SET IS ASKED FOR HERE, NOT SPELLED AGAIN. This site carried a
        # private copy of the list and that copy was missing `handoff`, so the
        # one act whose argv begins with `교대=0` graded `등급 미상` and the
        # terminal shift's own row came back 6 — refused by the axis that was
        # never about it.
        graded="읽기"
      else
        graded=$(surface_of_argv0 "$@")
        argv_graded=1
      fi ;;
  esac
  # 형태 미상 IS REFUSED BEFORE THE DECLARATION IS EVEN READ, and that ordering
  # is the whole point of the token. This is a tool the table knows, in a form
  # the parser could not read — so the caller's declaration is a claim about
  # bytes nobody understood, and admitting it would let `curl --x -X POST` be
  # declared `읽기` and performed. Unlike `등급 미상`, no declaration rescues it;
  # the repair is to respell the command so its verb and options are visible.
  if [ "$graded" = "$GATE_FORM_UNKNOWN" ]; then
    warn "axis 2 \`형태 미상\` — this is a tool in the table, but what it does cannot be read in this shape: $1 (it cannot be waved through by declaration. Rewrite it so the subcommand and the options are visible)"
    exit "$GATE_EXIT_VOCAB"
  fi
  # --- 부류·표지·하한 -----------------------------------------------------
  # Three values the grade cannot carry, computed once here so the comparator,
  # the disposition evaluator and the ledger row all read the same answer.
  #
  # `등급 출처` is three-valued rather than a boolean: `표` is a grade the table
  # proved from argv, `불투명` is a runner whose payload the table cannot see,
  # and `미상` is a command with no row at all. The three take different
  # comparators and leave different marks on the row, and collapsing any two of
  # them loses exactly the distinction the axis was added for.
  GATE_GRADE_SOURCE='표'; GATE_OPAQUE=0; GATE_FLOOR=''
  GATE_MARK=''; GATE_MARK_TRIGGER=''
  export GATE_GRADE_SOURCE GATE_OPAQUE GATE_FLOOR GATE_MARK GATE_MARK_TRIGGER
  if [ "$argv_graded" = "1" ]; then
    GATE_OPAQUE=$(gate_argv_opaque "$@")
    local _mk; _mk=$(gate_act_mark "$@")
    GATE_MARK="${_mk%%	*}"; GATE_MARK_TRIGGER="${_mk#*	}"
    if [ "$GATE_OPAQUE" = "1" ] || [ "$graded" = "등급 미상" ]; then
      local _fl _rest _fmark _ftrig
      _fl=$(gate_opaque_floor "$@")
      GATE_FLOOR="${_fl%%	*}"; _rest="${_fl#*	}"
      _fmark="${_rest%%	*}"; _ftrig="${_rest#*	}"
      # A mark the OUTER argv could not show. `bash -c 'aws … --with-decryption'`
      # is a secret print that `gate_act_mark` answers nothing for, because the
      # name it sees is `bash`. `비밀출력` outranks `파괴` where both appear: the
      # first is a disclosure that cannot be taken back once printed.
      if [ -z "$GATE_MARK" ] || { [ "$GATE_MARK" = "파괴" ] && [ "$_fmark" = "비밀출력" ]; }; then
        [ -n "$_fmark" ] && { GATE_MARK="$_fmark"; GATE_MARK_TRIGGER="$_ftrig"; }
      fi
    fi
    [ "$GATE_OPAQUE" = "1" ] && GATE_GRADE_SOURCE='불투명'
    [ "$graded" = "등급 미상" ] && GATE_GRADE_SOURCE='미상'
  fi

  # --- 비교기 -------------------------------------------------------------
  # OVER-DECLARATION IS ACCEPTED IN BOTH MODES, and it is what makes an honest
  # declaration possible at all: the table is path-blind, so a caller who knows
  # their `mkdir` lands outside the worktree had no spelling that was both true
  # and accepted. Strict equality refused 687 such calls in this corpus.
  #
  # UNDER-DECLARATION IS STILL EXIT 6. What it is compared against depends on the
  # class: a table-graded form against the table, and an opaque one against the
  # FLOOR — because the table's answer for `sh -c` says only that a shell ran,
  # and the floor is the part of its payload the gate could actually read.
  if [ -n "$surface" ]; then
    surface_index "$surface" >/dev/null || exit "$GATE_EXIT_VOCAB"
    local _bound="$graded" _bi _si
    if [ "$GATE_GRADE_SOURCE" = "불투명" ] && gate_auto_resolve_enabled; then
      _bound="${GATE_FLOOR:-읽기}"
    elif [ "$GATE_GRADE_SOURCE" = "미상" ]; then
      _bound="${GATE_FLOOR:-읽기}"
    fi
    if [ "$_bound" = "등급 미상" ]; then
      # Off mode, unknown command: today's answer, unchanged — a declaration
      # cannot be compared against a grade that does not exist.
      warn "axis 2 self-declaration mismatch: declared '$surface' vs graded '$graded'"
      gate_orchestrator_script_hint "$1"
      exit "$GATE_EXIT_GRADE"
    fi
    _bi=$(surface_index "$_bound") || exit "$GATE_EXIT_VOCAB"
    _si=$(surface_index "$surface") || exit "$GATE_EXIT_VOCAB"
    if [ "$_si" -lt "$_bi" ]; then
      warn "axis 2 under-declaration: declared '$surface' is lower than the $( [ "$_bound" = "$graded" ] && printf 'grade' || printf 'floor' ) '$_bound'"
      if [ "$graded" = "등급 미상" ]; then gate_orchestrator_script_hint "$1"; fi
      exit "$GATE_EXIT_GRADE"
    fi
    GATE_DECLARED="$surface"
  fi
  if [ "$graded" = "등급 미상" ] && [ -n "$surface" ] && gate_auto_resolve_enabled; then
    # THE DECLARATION PATH. A command with no row may still run, and only while
    # the run is unattended-resolving: the declaration is what the disposition
    # evaluator then judges, and with the switch off there is no evaluator to
    # judge it — so off mode keeps today's refusal rather than admitting a claim
    # nothing will check.
    GATE_UNKNOWN_DECLARED=1
  fi
  if [ "$graded" = "등급 미상" ] && [ "${GATE_UNKNOWN_DECLARED:-0}" != "1" ]; then
    # THE GENERIC MESSAGE COMES FIRST SO THE SPECIFIC ONE IS READ LAST. Both
    # lines name a repair and the two repairs are opposites: the generic one
    # says respell the command, the version-skew advisory says do NOT respell it
    # because both respellings available here are losses. Printed the other way
    # round the reader's last instruction was the one that does not apply, and
    # the two spellings it invites are exactly the two the advisory forbids.
    #
    # The generic message names WHICH repair, because two different things
    # arrive here: a tool the table has never listed (widen the table), and a
    # recognized tool in a form the sub-table could not parse (respell the
    # command). Without the distinction the router sees one refusal and has no
    # way to tell which.
    warn "axis 2 \`등급 미상\` — an argv0 that is not in the grade table does not fall through to \`읽기\`: $1 (if that tool has never been entered in the table, the table has to be widened; if it is in the table and the shape could not be read, rewrite it so the subcommand is visible)"
    gate_orchestrator_script_hint "$1"
    [ "$verb" = "plan" ] || exit "$GATE_EXIT_VOCAB"
  fi

  # --- 도달 필수 ----------------------------------------------------------
  # REQUIRED ONLY WHERE THE ANSWER CARRIES INFORMATION. Demanded of every call,
  # the field becomes a formality on `cat` and stops meaning anything on the one
  # row the morning actually reads. Demanded of none, an external write lands
  # with no record of which environment it touched.
  if gate_auto_resolve_enabled && [ "$argv_graded" = "1" ] && [ -z "${GATE_REACH:-}" ] \
     && gate_reach_required "$graded" "$@"; then
    warn "--reach is required — the reach of this act carries information (grade '$graded', source '$GATE_GRADE_SOURCE'). Allowed tokens: $REACHES"
    exit "$GATE_EXIT_VOCAB"
  fi

  # The watcher's observations, transcribed into properly chained rows. It
  # records them as a file precisely because it is not the ledger's writer; this
  # is the writer, so this is where they become rows.
  gate_drain_stall
  # The CI poller's observations, on the same seat and for the same reason. IT IS
  # HERE AND NOT IN THE PRELUDE, and the position is the whole of its safety: the
  # caller's digest has already passed the staleness test above, so an append
  # made now cannot retroactively invalidate the very call that made it.
  # "Simplifying" this up into the prelude brings the #592 ordering defect back to
  # life in a new series, which is why the reason is written down beside the call.
  gate_drain_checks
  # The run hook's records of a target hook refusing a gate call, on the same
  # seat for the same reason: the hook writes no row, and this is the writer.
  gate_refused_drain
  # This seat's own state, then the watcher's — both go through the same file, so
  # whichever wrote it first is the one line the report carries and the two seats
  # cannot leave two lines for one fact.
  cc_notify_seat_state || true
  gate_drain_notify_state

  # THE DEADLINE IS A DISPATCH GATE. It is frozen into the binding digest and
  # compared at entry, and then nothing read it — `gate.sh` mentioned neither
  # the field nor a comparison, and the only callers of the driver's own
  # deadline helper sit in the fixed-graph loop the router never enters. So the
  # value a user answered for at kickoff did not reach execution, which is the
  # shape #208 already recorded for the cutpoint. Measured: a run past its
  # deadline had `plan --kind skill` answer "통과 예상".
  #
  # It gates DISPATCH and MERGE and nothing else, per the contract: a stage in
  # flight runs to completion and is classified normally, and the run may still
  # record, close and propose. Checking only at entry would be half — a deadline
  # that was in the future when the run started is the normal case.
  #
  # A CARRY ACT THE ENDED RUN REFUSES KEEPS ITS ANSWER. The person answered, and
  # a plain refusal would leave the answer with no session and no record that
  # the next run should take it up — so, under `act`, the carry writes its
  # `이월` row after the ending row this check wrote, and ends as a carry that
  # found no room does. Its own checks already passed: an answer that is not
  # this dispatch's to carry was refused before this point, and leaves no row.
  if [ "$verb" != "grade" ]; then
    local re_rc=0
    gate_run_ended_ok "$kind" "$GATE_ACT_EFFECTIVE" "$verb" || re_rc=$?
    if [ "$re_rc" != "0" ]; then
      if [ -n "$GATE_HA_LINE" ] && [ "$kind" = "skill" ] && [ "$verb" = "act" ]; then
        gate_carry_defer_row "$alias" "$(gate_stage_row_segment "$stage_key" "${1:-}")" \
          "$stage_key" - "$GATE_HA_LINE" \
          "$(if gate_past_deadline; then printf '마감 경과'; else printf '런 종료 경과'; fi)"
        exit "$GATE_EXIT_ROUTE"
      fi
      exit "$re_rc"
    fi
  fi

  # THE PUSH RUNG IS RE-DERIVED HERE, and here is the earliest it can be: the
  # base branch it compares against lives on the target row. Raising only — an
  # honest `머지` declaration on a base-branch push keeps the review rule in
  # front of it, and the generic ladder seam would have pulled that back down.
  #
  # THE PUSH IS RECOGNIZED AND GRADED BY WHAT GIT SAYS IT UPDATES — see
  # `gate_push_base_updates`. Matching `git push` as the first two words let
  # `git -c k=v push`, `git -C <dir> push`, `command git push` and `env git
  # push` through as something other than a push, and the approval question
  # then showed a base merge as `push`.
  #
  # A BASE UPDATE IS `머지` WHATEVER WAS DECLARED. A higher declaration is
  # brought down to `머지`, the over-declaration rule the ladder above applies,
  # because the router labels acts with its target's cutpoint and `배포` on a
  # base push is the ordinary label — and the binding block below is keyed on
  # the merge rung. A push updating no base keeps its declaration.
  #
  # A PUSH THE DRY-RUN CANNOT REPRODUCE IS REFUSED HERE, before any rule and
  # whatever the policy or `룰 설정` says: what such a push puts on the base is
  # not known, and the probe was not run for it. The repair is a spelling the
  # gate can measure, so the code is the vocabulary one.
  #
  # THE REFUSAL ITSELF LANDS AFTER THE WRITE GUARDS BELOW, not here. A shell
  # string reaches `형태미상` when it cannot be shown to run no push, which is
  # most strings that write anything — so a string that writes the manifest
  # would otherwise be refused as an unmeasurable push, and the guard that names
  # the real cause would never speak. Both refuse before the act runs; the order
  # only decides which cause the caller is told.
  GATE_PUSH_DONE=0
  local push_unknown=0
  if [ "$argv_graded" = "1" ] && [ "${GATE_UNDECLARED:-0}" != "1" ]; then
    gate_push_base_updates "$alias" "$@"
    [ "$GATE_PUSH_KIND" = '형태미상' ] && push_unknown=1
    if [ "$push_unknown" = 0 ] && [ "$GATE_PUSH_KIND" != '해당없음' ]; then
      local _pr _pi _ei
      case "$GATE_PUSH_KIND" in
        갱신|여럿) _pr='머지' ;;
        *)        _pr=$(gate_push_static_rung "$alias") ;;
      esac
      GATE_ACT_DERIVED="$_pr"
      _pi=$(cutpoint_index "$_pr") || exit "$GATE_EXIT_VOCAB"
      _ei=$(cutpoint_index "$GATE_ACT_EFFECTIVE") || exit "$GATE_EXIT_VOCAB"
      if [ "$_pi" -gt "$_ei" ]; then
        warn "under-declared: the destination of this push is the base branch of the target, so it is the '$_pr' cell — '$GATE_ACT_EFFECTIVE' does not stand the review requirement up"
        warn "raise the declaration to '$_pr' and call again with the same argv"
        exit "$GATE_EXIT_LADDER"
      fi
      if [ "$_pr" = '머지' ] && [ "$_ei" -gt "$_pi" ]; then
        warn "over-declared: this push updates the base branch of the target, so it is the '$_pr' cell — declared '$GATE_ACT_EFFECTIVE', judged at '$_pr'"
        GATE_ACT_EFFECTIVE="$_pr"
        export GATE_ACT_DERIVED GATE_ACT_EFFECTIVE
      fi
    fi
  fi

  # The cutpoint export stays here and the worktree resolution does not: this one
  # needs `GATE_ACT_EFFECTIVE`, which the ladder above only settles by this point,
  # while the worktree needs nothing the target row has not already supplied.
  if [ "${GATE_UNDECLARED:-0}" != "1" ]; then
    gate_export_cutpoints "$alias" "$GATE_ACT_EFFECTIVE" || exit $?
  fi
  # WHAT THE RULES SEE IS THE GRADE argv PROVED, RAISED BY AN HONEST DECLARATION
  # — never lowered by one. The three classes give three inputs, and the reason
  # is one sentence each. A table-graded form: the table proved it, so the
  # declaration adds nothing a rule should read. An opaque runner: the table saw
  # a shell, the caller saw the payload, so the higher of the two is the honest
  # floor. A command with no row: the declaration is all there is, and it is
  # floored at `워크트리쓰기` so that declaring `읽기` cannot buy the read
  # exemptions — the review rule returns early on a read, so a `merge-seg.sh`
  # declared as a local read would merge with no review record at all.
  case "$GATE_GRADE_SOURCE" in
    불투명) GATE_SURFACE=$(gate_surface_max "$graded" "${GATE_DECLARED:-읽기}") ;;
    미상)   GATE_SURFACE=$(gate_surface_max "${GATE_DECLARED:-워크트리쓰기}" '워크트리쓰기') ;;
    *)      GATE_SURFACE="$graded" ;;
  esac
  export GATE_SURFACE

  # THE SECOND argv-DERIVED VALUE, PUBLISHED BESIDE THE FIRST. `리뷰-후-머지`
  # narrows on the graded surface and then splits that surface's worktree-write
  # cell with this; keeping the two exports together is what stops a later
  # editor from moving one and leaving the other behind.
  #
  # THE KIND-PINNED ARMS ANSWER 0, AND THAT 0 IS A FACT RATHER THAN A GUESS.
  # Where the grade came from the kind rather than from the table, the argv is
  # not a command at all — a bookkeeping act's argv is a list of `키=값` fields,
  # a stage dispatch's first token is a stage kind, a routing shift's is a
  # handoff reason. Asking "does this command integrate history" of a field list
  # has no answer, and 0 is the honest one: no history is being integrated.
  GATE_HISTORY_INTEGRATION=0
  case "$kind" in
    propose-done|skill|router-shift|apply|ci-rerun|ci-match|label-ack) : ;;
    *) gate_kind_is_bookkeeping "$kind" \
         || GATE_HISTORY_INTEGRATION=$(gate_history_integration "$@") ;;
  esac
  # A COMMAND WITH NO ROW IS ALWAYS "CHECK IT". The predicate answers from a
  # table of names, so a name it has never seen answers 0 — and a declaration
  # path that admits such a command would then hand the review rule a merge it
  # never examined. `scripts/merge-seg.sh` runs `git merge` inside; declared as a
  # local write it would land on the base with no review record.
  [ "$GATE_GRADE_SOURCE" = "미상" ] && GATE_HISTORY_INTEGRATION=1
  export GATE_HISTORY_INTEGRATION

  # A DISPATCH ARGV IS A PROMPT, NOT A COMMAND LINE, so the guard below has
  # nothing to look at there. `skill` and `router-shift` hand their argv to a
  # launcher — the first token is consumed as the stage kind or the handoff
  # reason and the rest goes to the wrapper — and no byte of it is ever run as a
  # command by this process. What the successor then does comes back through
  # this gate as its own act and is guarded there, which is the same reading the
  # grading arm above already gives these two kinds.
  #
  # WITHOUT THIS THE PROTOCOL REFUSED ITS OWN MANDATED FORM. A shift is
  # dispatched as `-p "/cc-cmds:autopilot-router-shift <매니페스트>"` because the
  # successor has to be told which run it is resuming, and the guard's last arm
  # is basename containment over the argv elements — so that one element carries
  # the manifest's name and every routing shift was refused with `매니페스트에
  # 쓰려 합니다`, exit 3. It stayed invisible while a routing shift graded
  # `등급 미상`, because the vocabulary refusal above returns before this line;
  # giving it the `워크트리쓰기` grade is what moved the act into this range.
  #
  # Residual, stated rather than hidden: a dispatch is no longer measured by
  # this guard at all, so a prompt that instructs the successor to write the
  # manifest is not caught here. It is caught where it becomes an act — the
  # successor's own gate call — which is the only place the write actually
  # exists.
  #
  # THE SHARD FENCE STANDS ON BOTH VERBS, the way the two guards beside it do.
  # An `act` of any kind but the two dispatch kinds hands its argv to the same
  # `gate_run_readonly` an `exec` does, so a fence keyed on the verb left
  # `act --kind x -- cat "$RUN_DIR/shared/1/…"` open to the routing seat with
  # no refusal and an approval row that does not say a shard was read. The
  # outer `case` already sets aside the two kinds whose argv is a prompt.
  case "$kind" in
    skill|router-shift|apply) : ;;
    *) gate_manifest_write_guard "$graded" "$@" || exit $?
       gate_rundir_write_guard "$graded" "$@" || exit $?
       gate_plugin_root_write_guard "$graded" "$@" || exit $?
       gate_surface_write_guard "$graded" "$@" || exit $?
       gate_pace_write_guard "$graded" "$@" || exit $?
       gate_shard_exec_guard "$@" || exit $? ;;
  esac

  if [ "$push_unknown" = 1 ]; then
    warn "형태 미상 — 이 git push 는 게이트가 dry-run 으로 무엇이 베이스에 올라가는지 잴 수 없는 형태입니다: ${GATE_PUSH_FORM_WORD}"
    warn "셸 -c·env -S·sudo 문자열은 git 을 부르거나 \$·백틱·백슬래시·글로브·괄호를 담거나 셸·eval·xargs 같은 실행기를 담으면 push 가 없다고 읽을 수 없어 이 거절에 닿습니다 — 그 명령을 래퍼 없이 직접 부릅니다"
    warn "셸 -c·sudo 래퍼, {} 를 받는 find -exec, 환경 할당(LANG·LC_*·TZ 밖의 모두 — HOME=·XDG_CONFIG_HOME=·GIT_* 포함)과 env 옵션, 실행 설정 키, 허용 목록 밖 push 옵션(축약 포함) 없이 git push <원격> <refspec> 으로 다시 부릅니다 — 게이트가 아는 래퍼(command·할당 없는 env·lockf·timeout 등)와 -f·-u·--force-with-lease·--tags 같은 옵션은 그대로 둡니다"
    exit "$GATE_EXIT_VOCAB"
  fi

  # Layer 2 of the CLAUDE.md audit. It refuses nothing; it publishes the three
  # values the `리뷰-후-적용` rule reads. Placed after the manifest guard so an
  # act that is refused outright never reaches a rule at all.
  gate_claudemd_slot_guard "$graded" "$@"

  # WHAT THE AUTO-ADOPTION RULE READS. A rule checker is a separate `/bin/sh`
  # process and cannot call this file's functions, so the gate resolves the
  # vocabulary and hands over values — the same division `절단점-준수` already
  # has, where the checker receives two integers rather than a copy of the
  # ladder. `GATE_REVERT_SURFACE` in particular is the argv0 grading of the undo
  # command, and re-deriving it inside the checker would put a second copy of
  # the grading table where the portability lint does not look.
  GATE_KIND="$kind"
  GATE_JUDGMENT_CLASS=""
  GATE_REVERT=""
  GATE_REVERT_SURFACE=""
  # Set only when an ANSWERED approval is what opened this act, so the row can
  # say which one and a second use of the same answer is refusable.
  GATE_RESOLVED_APPROVAL=""
  GATE_JUDGMENT_DECISION=""
  if [ "$kind" = "judgment" ]; then
    # THE ROW IS WELL-FORMED BEFORE THE FLOOR IS ASKED ABOUT IT. Otherwise a
    # judgment missing a required field fails the floor for want of the very
    # field it is missing, and the refusal that reaches the router is exit 5 —
    # "a person must answer this" — for what is actually a typo. Worse, the
    # approval gets WRITTEN, so the run then carries an open question nobody
    # asked and termination waits on it.
    gate_judgment_fields_ok "$@" || exit "$GATE_EXIT_VOCAB"
    GATE_JUDGMENT_CLASS=$(gate_field_of '판단 부류' "$@")
    GATE_REVERT=$(gate_field_of '되돌리는 법' "$@")
    GATE_REVERT_SURFACE=$(gate_revert_surface "$GATE_REVERT")
  fi
  export GATE_KIND GATE_JUDGMENT_CLASS GATE_REVERT GATE_REVERT_SURFACE

  # THE REVIEW POLICY, RESOLVED BEFORE THE CATALOG RUNS. The checkers are
  # separate processes and receive this as ambient state; resolving it after the
  # loop would leave them nothing to read. It is also outside `gate_rule_enabled`
  # on purpose — the ceiling comparison is the part of this axis a manifest may
  # not switch off, and putting it inside a checker would let one setting turn
  # off both the check and the ceiling that bounds it.
  gate_resolve_review_policy "$segment" "$alias" "$kind" "$@" || exit $?

  # THE ANCHOR CHECK, and its position is the whole of its effect. Every one of
  # its refusals names the SEGMENT ROW as the thing to repair, and any refusal
  # that names a field to repair has to come before an approval is written: the
  # approval id carries the resolved worktree, so repairing the row after an
  # approval was answered changes the id and orphans the answer. The dispatch
  # pre-check above obeys that for the same reason. This check used to sit below
  # the approval block, so an act outside pre-authorization was asked first,
  # answered, and only then refused here — and the repair orphaned the answer.
  #
  # IT CANNOT MOVE ANY HIGHER THAN THIS LINE. Its first statement returns 0
  # unless `GATE_REVIEW_POLICY` is `선머지후리뷰`, and the call directly above is
  # what sets that. Placed beside the dispatch pre-check it would read an empty
  # policy and pass every merge without looking — the check switched off with
  # no message. Between here and the approval block nothing writes a row.
  #
  # WHICH REFUSAL WINS CHANGES WITH THE MOVE, and that is intended. The rule
  # loop, the auto-adoption floor and the reach evaluator now all run after it,
  # so a merge both unanchorable and refused by a rule reports 10 rather than 3.
  # 10 names the row, 3 names a rule, and a rule refusal fixed first would only
  # arrive at this one next. It still sits above both appends and above the
  # forecast arm, so a merge refused here leaves no row and `plan` answers with
  # the same code `act` would.
  #
  # THIS SITE AND THE ISSUER BELOW TAKE THE EFFECTIVE RUNG TOGETHER, and splitting
  # them is the one wrong way to do it: both narrow on `= 머지`, so leaving the
  # anchor check on the declared value lets an under-declared merge skip the
  # anchor and reach the issuer anyway — a row with no commit to close it. The
  # same pairing holds for the kind: both skip a bookkeeping act, because a
  # row write labelled `머지` by the router merges nothing, and an issuer that
  # still saw it would reopen a slot the segment already fulfilled.
  gate_check_merge_anchor "$segment" "$GATE_ACT_EFFECTIVE" "$alias" "$kind" || exit $?

  # THE MERGE WAITS FOR ITS ORDER. A segment whose `선행 ∪ 머지 순서` names a
  # slice that has not landed may be implemented beside it, but may not put its
  # work on the base first — that order is what the declaration's `머지 순서`
  # promised. Only an act that lands is held: a remote merge argv, a `git push`
  # git says updates the base, or a command the table cannot read that writes
  # outside the worktree. A commit or a push to the segment branch is not.
  #
  # NO ROW AND NO PARK CELL. The refusal is a wait, not a defect: the router
  # retries once the predecessor lands, and a parked predecessor holds this
  # segment through the cone instead. And it is outside `gate_rule_enabled` and
  # the review policy, because the order is the declaration's, not a rule a
  # manifest may switch off.
  local _moi _mom _mo_land=0 _mo_dep _mo_st
  _moi=$(cutpoint_index "$GATE_ACT_EFFECTIVE" 2>/dev/null) || _moi=-1
  _mom=$(cutpoint_index '머지' 2>/dev/null) || _mom=0
  if [ "$_moi" -ge "$_mom" ] && ! gate_kind_is_bookkeeping "$kind" \
     && [ -n "$segment" ] && [ "$segment" != '-' ] \
     && [ -n "$(gate_segment_field "$segment" '상태')" ]; then
    case "$kind" in
      propose-done|skill|router-shift|apply|ci-rerun|ci-match|label-ack) : ;;
      *)
        [ "$(gate_merge_binding_of_argv0 "$@")" = '해당없음' ] || _mo_land=1
        if [ "$_mo_land" = 0 ]; then
          [ "${GATE_PUSH_DONE:-0}" = 1 ] || gate_push_base_updates "$alias" "$@"
          case "${GATE_PUSH_KIND:-}" in 갱신|여럿) _mo_land=1 ;; esac
        fi
        if [ "$_mo_land" = 0 ]; then
          case "$GATE_GRADE_SOURCE" in
            미상|불투명)
              case "$GATE_SURFACE" in 읽기|워크트리쓰기) : ;; *) _mo_land=1 ;; esac ;;
          esac
        fi ;;
    esac
    if [ "$_mo_land" = 1 ]; then
      for _mo_dep in $(gate_chain_deps_of "$segment"); do
        gate_segment_ever_landed "$_mo_dep" && continue
        _mo_st=$(gate_segment_field "$_mo_dep" '상태')
        warn "세그먼트 ${segment} 의 머지 순서 선행 ${_mo_dep} 가 아직 착지하지 않았습니다(「상태」=${_mo_st:-(없음)}) — 그 세그먼트가 머지된 뒤에 이 세그먼트를 머지합니다"
        warn "구현은 함께 진행할 수 있지만 베이스에 올리는 순서는 선언의 「선행 ∪ 머지 순서」를 따릅니다 — 선행이 머지되면 같은 argv 로 다시 부릅니다"
        exit "$GATE_EXIT_RULE"
      done
    fi
  fi

  # THE MERGE ARGV IS BOUND TO THE HEAD THE RULE READS. The review rule compares
  # the review against the segment worktree's HEAD; a remote merge merges the
  # pull request's head as the server holds it. An argv that does not pin the
  # server to that HEAD is refused here, before the rule runs, so the head the
  # rule approved is the only head the merge can take.
  #
  # THIS SITE CHANGES WHICH CODE AN UNBOUND MERGE GETS. A remote merge argv
  # with no binding, or one naming another commit, now gets 2 from this line
  # where before it reached a `--admin` refusal (3), an act outside
  # pre-authorization (5) or the cutpoint ceiling (3). The repair is the REST
  # merge with its `sha` field — a `gh pr merge` without `--admin` binds
  # nothing whatever it carries — and every one of those later checks still
  # runs once it is there.
  #
  # NOT IN THE RULE FILE AND NOT IN THE ANCHOR CHECK. The rule files carry the
  # review predicate and are kept byte-identical, so a check added there would
  # be a change to the predicate's own file; and the argv unwraps this reading
  # needs live in this file, not in a `/bin/sh` checker. The anchor check answers a
  # different question — whether a deferred review has a commit to anchor to —
  # and returns early outside `선머지후리뷰`, the one policy this check is not
  # for.
  #
  # WHAT STAYS OPEN: a merge made outside the gate, from the web UI or another
  # machine, binds nothing. The record of such a merge is the segment row's
  # `머지 대조`, which compares what landed rather than what was requested.
  #
  # IT OPENS WHERE THE RULE FIRES, at `머지` AND ABOVE. Keyed on `머지` alone,
  # a push declared `배포` — the target's cutpoint, which is how the router
  # labels its acts — skipped every binding below while the rule approved the
  # worktree's HEAD, and an unreviewed source landed.
  local _mbi _mmi
  _mbi=$(cutpoint_index "$GATE_ACT_EFFECTIVE" 2>/dev/null) || _mbi=-1
  _mmi=$(cutpoint_index '머지' 2>/dev/null) || _mmi=0
  if [ "$_mbi" -ge "$_mmi" ] && ! gate_kind_is_bookkeeping "$kind" \
     && [ "${GATE_REVIEW_POLICY:-}" = '선리뷰후머지' ] \
     && [ -n "$segment" ] && [ "$segment" != '-' ] \
     && [ -n "$(gate_segment_field "$segment" '상태')" ] \
     && gate_rule_enabled '리뷰-후-머지'; then
    local mbind mhead="" mrow mspec
    # THE RULE MUST READ THE ROW THE GATE READS — see `gate_rule_row_mismatch`.
    # Checked first: every binding below is to the HEAD of the gate's row, and
    # is worth nothing if the rule approved another row's tree.
    mrow=$(gate_rule_row_mismatch "$segment")
    if [ -n "$mrow" ]; then
      warn "리뷰-후-머지 룰이 고르는 세그먼트 $segment 의 마지막 ${mrow} 행이 게이트가 고르는 행과 다릅니다 — 다른 세그먼트의 행 문면에 「$( [ "$mrow" = segment ] && printf 'id' || printf '세그먼트')=$segment 」 가 들어 있어 룰이 그 행을 읽게 됩니다"
      warn "이 세그먼트의 ${mrow} 행을 하나 더 써서 마지막 행이 되게 한 뒤 다시 부릅니다"
      exit "$GATE_EXIT_VOCAB"
    fi
    mbind=$(gate_merge_binding_of_argv0 "$@")
    if [ "$mbind" != '해당없음' ]; then
      mhead=$(gate_segment_tip "$segment") || mhead=""
      if [ "$mbind" = '없음' ] || [ -z "$mhead" ] || [ "$mbind" != "$mhead" ]; then
        warn "원격 머지 argv 가 세그먼트 $segment 의 워크트리 HEAD 에 결속되지 않았습니다 — 결속 인자: ${mbind}, 워크트리 HEAD: ${mhead:-읽지 못함}"
        warn "머지는 REST 서식 gh api -X PUT repos/<owner>/<repo>/pulls/<n>/merge -f sha=<워크트리 HEAD 40자> -f merge_method=<merge|squash|rebase> 로 다시 부릅니다. --admin 없는 gh pr merge 는 --match-head-commit 을 달아도 결속이 아닙니다 — 머지 큐를 요구하는 베이스에서 그것은 자동 머지를 켜거나 큐에 넣어 헤드를 요청 시점에만 대조하기 때문입니다. 머지 큐를 요구하는 베이스에서는 REST 머지가 405 로 거부되어 게이트를 지나는 결속된 머지가 서지 않으므로, 그 머지는 사람에게 넘깁니다. GraphQL mergePullRequest 는 그 필드 하나만 둔 mutation 의 input 안에 expectedHeadOid: \"<워크트리 HEAD>\" 를 인라인으로 한 번 적고(# 주석·\"\"\" 블록 문자열·프래그먼트·지시어·다른 mutation 필드·파일 본문·input 변수 통째 넘김은 읽지 않고, \$변수 는 엔드포인트를 정확히 graphql 로 적었을 때만 query·operationName 이 아닌 필드에서 읽습니다), 결속 인자가 없는 머지(…/merges, mergeBranch)와 머지 없이 ref 를 바꾸는 GraphQL mutation(updateRefs·updateRef·createCommitOnBranch 등)과 머지 없이 브랜치를 옮기는 REST 쓰기(…/git/refs, …/contents/…, …/merge-upstream, …/branches/<b>/rename 을 비롯해 이슈·PR·라벨·코멘트 엔드포인트 밖의 모든 비-GET REST 호출)와 대상 저장소를 적은 gh repo sync 는 세그먼트 브랜치로 push 한 뒤 위 REST 서식으로 바꿔 부릅니다. 자동 머지·머지 큐 진입·백그라운드 머지(gh pr merge --auto, enablePullRequestAutoMerge, enqueuePullRequest, …/pulls/<n>/merge-async)는 HEAD 를 요청 시점에만 대조하고 머지는 나중에 일어나므로 결속으로 받지 않습니다 — 위 REST 서식으로 바로 머지합니다. REST 머지의 쿼리스트링에 sha 를 두지 않고, find -exec 안에서 {} 를 받는 gh 호출은 맨 철자로 바꿔 부릅니다"
        exit "$GATE_EXIT_VOCAB"
      fi
    else
      # A LOCAL PUSH TO THE BASE CARRIES NO BINDING ARGUMENT, but git can say
      # what it will put on the base — see `gate_push_base_updates` and
      # `gate_push_source_mismatch`.
      [ "${GATE_PUSH_DONE:-0}" = 1 ] || gate_push_base_updates "$alias" "$@"
      mhead=$(gate_segment_tip "$segment") || mhead=""
      mspec=$(gate_push_source_mismatch "$alias" "$mhead")
      if [ -n "$mspec" ]; then
        warn "베이스로 가는 git push 의 소스가 세그먼트 $segment 의 워크트리 HEAD 가 아닙니다 — 갱신: ${mspec}, 워크트리 HEAD: ${mhead:-읽지 못함}"
        warn "리뷰-후-머지 룰은 세그먼트 워크트리의 HEAD 를 대조합니다. 그 HEAD 를 올리도록 HEAD:<베이스> 나 <세그먼트 브랜치>:<베이스> 로 다시 부릅니다(세그먼트의 행위는 세그먼트 워크트리에서 돕니다)"
        exit "$GATE_EXIT_VOCAB"
      fi
    fi
    gate_meta_resolved_export "$segment" "$mhead"
  fi

  # WHAT THE ORDER PREDICATE READS. The checker is a separate `/bin/sh` and
  # cannot call the reader above it, and letting it grep the ledger itself would
  # put a THIRD copy of "which obligations are open" beside this file's reader
  # and termination condition 9 — the gate folds it, the checker receives the
  # value. Narrowed to this segment for the reason the reader's own comment
  # gives: run-wide, a sibling's open obligation refuses this segment's merge.
  GATE_SEGMENT_OPEN_OBLIGATIONS=$(gate_unfulfilled_review_obligations "$segment" \
    | tr '\n' ' ' | sed 's/[[:space:]]*$//')
  export GATE_SEGMENT_OPEN_OBLIGATIONS
  # The segment's last cycle row, its last segment row, a person's dismissal of
  # that cycle and its carry-over to issues, all folded here for the same
  # reason: the checkers read no ledger rows themselves. A checker that picked
  # its own row by substring read a `선행 세그먼트=<seg>` field of another
  # segment's row as this segment's last cycle; the selection is the gate's
  # field-equality reader, written once.
  GATE_SEGMENT_LAST_CYCLE=$(gate_segment_last_cycle_row "$segment")
  GATE_SEGMENT_LAST_SEGMENT=$(gate_segment_last_segment_row "$segment")
  GATE_SEGMENT_REVIEW_DISMISSED=$(gate_segment_review_dismissed "$segment")
  GATE_SEGMENT_REVIEW_CARRIED=$(gate_segment_review_carried "$segment")
  export GATE_SEGMENT_LAST_CYCLE GATE_SEGMENT_LAST_SEGMENT \
    GATE_SEGMENT_REVIEW_DISMISSED GATE_SEGMENT_REVIEW_CARRIED

  local rules_rc=0
  # THE CHECKERS ARE NOT TOUCHED BY THIS AXIS AT ALL, and that is the point of
  # putting the seam upstream: `GATE_ACT` arrives already corrected, so not one
  # line of the catalog changes and no checker acquires a second copy of the
  # ladder.
  # A rule that answers differently with no person present reads the mode from
  # here: the rule files run as processes of their own and cannot call the
  # gate's function.
  if gate_auto_resolve_enabled; then GATE_AUTO_RESOLVE=1; else GATE_AUTO_RESOLVE=0; fi
  export GATE_AUTO_RESOLVE
  gate_run_rules "$GATE_ACT_EFFECTIVE" "$alias" "$segment" "$argv" \
    "$(gate_preauth_argv "$alias" "$@")" || rules_rc=$?

  # THE AUTO-ADOPTION FLOOR. It runs beside the catalog rather than only inside
  # it because its other consumer — a judgment a stage emitted in its terminal
  # message — is not an act and never reaches `gate_run_rules` at all. Keeping
  # one implementation for both is what stops the emitted path from becoming the
  # loose one.
  if [ "$rules_rc" = "0" ] && [ "$kind" = "judgment" ] \
     && [ "$(gate_field_of '등급' "$@")" = "1" ]; then
    gate_autoadopt_ok "$GATE_JUDGMENT_CLASS" "$GATE_REVERT" || rules_rc="$GATE_EXIT_APPROVAL"
  fi

  # --- 처분 평가기 ---------------------------------------------------------
  # AFTER THE CATALOG, BEFORE THE APPROVAL BLOCK. A rule refusal is `rules_rc=3`
  # and the evaluator does not run then: "the cutpoint does not authorize this"
  # and "this lands somewhere the run may not reach" are different sentences, and
  # reporting the second where the first holds sends the morning to the wrong
  # repair.
  #
  # The verdict is computed here and DISPATCHED further down, after the surface
  # check, the segment-row check and the merge anchor have had their say. Those
  # three refuse acts this one would have parked, and a park row written ahead of
  # them would record a disposition the act never actually reached.
  GATE_PARK_CELL="" GATE_PARK_CAUSE='-' GATE_PARK_SX='-' GATE_PARK_SW='-' GATE_PARK_REFF='-'
  GATE_PARK_GEFF='-' GATE_PARK_NEVER='-' GATE_PARK_TRIG='-' GATE_PARK_PROPOSAL='-'
  GATE_PARK_EV=1 GATE_PREAUTH_JUDGE='-'
  # A plan that carries no act (`--kind propose-done`) has no argv at all.
  GATE_PARK_ARGV0="${1:-}"
  GATE_PARK_ARGV0="${GATE_PARK_ARGV0##*/}"
  # OFF MODE WITH NOTHING DECLARED IS TODAY, EXACTLY. The reach axis is optional
  # there — the required-check above runs only while the switch is on — so an act
  # that declared no reach has made no claim for the evaluator to judge, and
  # judging it anyway would turn `-` into `도달미상` and issue an approval on
  # every ordinary external act. Measured: a rule switched OFF still refused,
  # because this evaluator answered in its place.
  #
  # A LABEL WRITE ON A PULL REQUEST IS THE EXCEPTION, read ahead of that guard.
  # Its cell refuses whatever reach is declared and whatever row the manifest
  # holds, so it cannot wait for the switch or a declaration: with the switch
  # off and no `--reach`, the evaluator below never runs, and a broad form row
  # would open the write on the ordinary row path. In both modes it parks — the
  # off mode's approval would let a person open what the row path never may.
  local _prlabel=0
  if [ "$argv_graded" = "1" ] && [ "$rules_rc" != "$GATE_EXIT_RULE" ] \
     && gate_pr_label_write "$@"; then
    _prlabel=1
    GATE_PARK_CELL='PR라벨쓰기'
    rules_rc=0
  fi
  if [ "$_prlabel" = "0" ] && [ "$argv_graded" = "1" ] && [ "$rules_rc" != "$GATE_EXIT_RULE" ] \
     && { gate_auto_resolve_enabled || [ -n "${GATE_REACH:-}" ]; }; then
    # The verdict is `<칸>\t<원인>\t<판단>` on the first line; the facts the
    # repair line reads follow on the second, printed from the same subshell. The
    # cause and the facts stay here — the ledger's `도달 판정=` takes the cell
    # alone, and the judgment goes to fields of its own on the row.
    local _out _cell _pcause _facts _rest
    _out=$(gate_reach_disposition "$alias" "$rules_rc" "$graded" "$@"
           printf '\n%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s' "$GATE_RF_SX" "$GATE_RF_SW" "$GATE_RF_REFF" \
             "$GATE_RF_GEFF" "$GATE_RF_NEVER" "$GATE_RF_TRIG" "$GATE_RF_EV" "$GATE_RF_PROPOSAL")
    _cell=${_out%%
*}
    _facts=${_out#*
}
    _pcause='-'
    case "$_cell" in
      *"	"*)
        _rest=${_cell#*	}; _cell=${_cell%%	*}
        _pcause=${_rest%%	*}
        case "$_rest" in *"	"*) GATE_PREAUTH_JUDGE=${_rest#*	} ;; esac ;;
    esac
    [ -n "$_pcause" ] || _pcause='-'
    [ -n "$GATE_PREAUTH_JUDGE" ] || GATE_PREAUTH_JUDGE='-'
    IFS='	' read -r GATE_PARK_SX GATE_PARK_SW GATE_PARK_REFF GATE_PARK_GEFF GATE_PARK_NEVER \
      GATE_PARK_TRIG GATE_PARK_EV GATE_PARK_PROPOSAL <<EOF || true
$_facts
EOF
    if gate_auto_resolve_enabled; then
      GATE_PARK_CELL="$_cell" GATE_PARK_CAUSE="$_pcause"
      # THE EVALUATOR REPLACES THE PRE-AUTHORIZATION RULE'S QUESTION, and only in
      # this mode. That rule answers `승인 대기` for an external-state act with no
      # matching row — the one approval class that is never auto-resolved,
      # because nobody wrote a recommendation for it. Unattended that is a night
      # spent waiting, which is the defect this whole axis exists to remove. The
      # match itself is not lost: `P` is an INPUT to the prod and deploy-trigger
      # cells, so an act the manifest never named still parks — as a row, with a
      # cell naming why, and with the run continuing.
      if [ "$rules_rc" = "$GATE_EXIT_APPROVAL" ]; then
        rules_rc=0
        [ -n "$_cell" ] || warn "outside the pre-authorization, but the reach judgment passes — proceeding instead of raising an approval (reach '${GATE_REACH:--}')"
      fi
    elif [ -n "$_cell" ] && [ "$GATE_GRADE_SOURCE" = "표" ]; then
      # OFF MODE: the same table, and its park cells become the approval this
      # gate has always issued. The switch decides WHO answers, not what the
      # answer is about — so a run with a person in front of it sees the same
      # acts stop, as questions rather than as rows. The opaque and unknown
      # classes keep today's behaviour entirely, which is what "off mode is
      # unchanged" has to mean for them.
      if [ "$_pcause" = "-" ]; then
        warn "reach judgment '$_cell' — auto-resolution is off, so it is issued as an approval"
      else
        warn "reach judgment '$_cell' (cause $_pcause) — auto-resolution is off, so it is issued as an approval"
      fi
      rules_rc="$GATE_EXIT_APPROVAL"
    fi
  fi
  export GATE_PARK_CELL
  # THE RESOLUTION IS READ BEFORE THE DRY-RUN ARM. `plan` answers "would this
  # act pass", and once the approval is answered the honest answer is yes — an
  # arm that reported "still needs an approval" would be describing a state that
  # no longer exists, and it is the arm a router consults before acting.
  if [ "$rules_rc" = "$GATE_EXIT_APPROVAL" ]; then
    local ap_id ap_st
    if [ "$kind" = "judgment" ]; then
      # A JUDGMENT'S APPROVAL IS THE JUDGMENT APPROVAL. Keying it on the act
      # variant would hash an argv that is a list of fields and attach a binding
      # tuple describing a tree the question has nothing to do with — and the
      # same judgment resubmitted would then produce a second approval instead
      # of finding the first.
      # A `답한 승인=<id>` citation names the id directly, so the consuming row's
      # `근거` can say what was done (`gate_judgment_target_id`).
      ap_id=$(gate_judgment_target_id "$segment" "$@") || exit "$GATE_EXIT_RULE"
    else
      # THE SAME RESOLUTION THE ISSUER USES. Asking for the id with a tree the
      # issuer did not key it on looks up an approval that was never written.
      ap_id=$(gate_act_approval_id "$alias" "$argv" "$(gate_act_worktree "$alias" "$segment")")
    fi
    ap_st=$(gate_approval_state "$ap_id")
    local ap_cons=1
    [ "$kind" = "judgment" ] && { gate_person_refusal_consumable "$ap_id" && ap_cons=0 || ap_cons=$?; }
    if [ "$ap_cons" = "2" ]; then
      warn "승인 $ap_id 의 거절은 그 세그먼트가 park 된 뒤에만 소비됩니다 — 먼저 act --kind segment 로 상태=park 행을 쓰세요"
      exit "$GATE_EXIT_RULE"
    fi
    if [ "$ap_cons" = "0" ]; then
      # A PERSON'S REFUSAL OF A PERSON-SET QUESTION IS SPENT HERE, not refused
      # again: the resubmission is the router saying it parked on that answer,
      # and the row it writes is what retires the answer.
      log "승인 $ap_id 의 거절을 이 판단이 소비합니다 (세그먼트는 park 되어 있습니다)"
      GATE_RESOLVED_APPROVAL="$ap_id"
      GATE_JUDGMENT_DECISION="거절 소비"
      rules_rc=0
      ap_st="소비"
    fi
    case "$ap_st" in
      소비) : ;;
      승인)
        # AN ANSWER IS SPENT ONCE. A judgment approval carries no binding tuple,
        # so nothing about it goes stale — `gate_approval_state` returns `승인`
        # for that id for the rest of the run, and the arm below turned every
        # later judgment resolving to the same id into an adoption that never
        # met the floor. Recording which approval opened which adoption is what
        # makes "already used" a question the ledger can answer.
        if [ "$kind" = "judgment" ] && gate_has_row '자율 승인' "| 해소 승인=$ap_id |"; then
          warn "approval $ap_id has already been used for one adoption — one answer opens one judgment"
          warn "if this raises a different judgment on the same standard, it has to be asked again as a new question"
        elif [ "$kind" = "judgment" ] \
             && [ "${GATE_AUTO_RESOLVED_APPROVAL:-}" != "$ap_id" ] \
             && [ "$(gate_row_field "$(gate_approval_last_row "$ap_id")" '처분 사유')" = "자동 해소" ] \
             && ! gate_judgment_class_adoptable "$GATE_JUDGMENT_CLASS"; then
          # THE SAME FLOOR THE RECORDING ARM APPLIES, because both run inside one
          # act and closing only one of them leaves the other open. A grade-1
          # judgment the auto-adoption floor will not take is escalated to an
          # approval here, and that escalation resolves against the id the
          # recording arm would have resolved against — `기준 — 근거` and nothing
          # else — so the class this submission carries is not the class the
          # answer was given about.
          #
          # A REFUSAL AND NOT A RE-ISSUE. Leaving `rules_rc` at
          # `GATE_EXIT_APPROVAL` drops through to the issuing path below and
          # re-opens the very question, putting the same standard and rationale in
          # front of a person with nothing in the text to tell the two classes
          # apart. The `무효` and `거부` arms below refuse outright for the same
          # reason.
          warn "approval $ap_id is an answer closed by an earlier auto-resolution, so it is not adopted for the class of this act (class ${GATE_JUDGMENT_CLASS:-(none)})"
          warn "to raise it under this class, it has to be asked again as a new question with a different standard and different grounds"
          exit "$GATE_EXIT_RULE"
        elif [ "$kind" != "judgment" ] && ! gate_act_approval_fresh "$ap_id" "$alias" "$segment"; then
          # THE TUPLE IS WHAT MAKES AN ACT APPROVAL EXPIRE. A question's answer
          # is durable and carries no tuple; an act's answer was given about a
          # tree, and this arm is the only place that says so. `rules_rc` is left
          # at `GATE_EXIT_APPROVAL` on purpose so the issuing path below
          # supersedes the stale row with a fresh question.
          warn "the tree moved after approval $ap_id received its answer — that answer does not open this act"
          warn "even with the same argv this is an act on a different tree, so the approval is issued again"
        else
          log "승인 $ap_id 이 해소되어 이 행위를 엽니다"
          GATE_RESOLVED_APPROVAL="$ap_id"
          rules_rc=0
        fi ;;
      무효)
        warn "approval $ap_id was closed as void — this act is not performed"
        exit "$GATE_EXIT_RULE" ;;
      거부)
        # A REFUSAL IS AN ANSWER, AND WITHOUT THIS ARM IT READS AS SILENCE.
        # `거부` is neither `대기` nor `승인`, so control fell out of this
        # `case` and reached the issuing path below — which re-opened the very
        # question that had just been answered no. The person would have got
        # the same question again the next morning, and every morning after,
        # off one answer they already gave.
        warn "approval $ap_id was closed as rejected — this act is not performed"
        exit "$GATE_EXIT_RULE" ;;
    esac
  fi

  if [ "$rules_rc" = "$GATE_EXIT_APPROVAL" ] && [ "$verb" = "plan" ]; then
    # A DRY RUN NEVER WRITES. `plan` answers "would this pass, and if not which
    # rule refuses it" — issuing an approval to answer that mutates the run the
    # question was about. Worse than untidy: an open approval suspends B1..B3
    # and blocks termination condition 2, so asking the question would stall the
    # run that asked it. The exit code still carries the answer.
    warn "plan(dry-run): this act is outside the pre-authorization and needs an approval wait — it was not issued"
    exit "$GATE_EXIT_APPROVAL"
  fi
  if [ "$rules_rc" = "$GATE_EXIT_APPROVAL" ]; then
    # Nothing above resolved it, so the act is genuinely blocked. A rule asking
    # for an approval and the gate not WRITING one is the same hole as recording
    # without performing, in the other direction: the run stops, nothing says
    # why, and the termination conditions never see the thing that is blocking
    # them. The row is the approval — issuing it is not bookkeeping after the
    # fact.
    if [ "$kind" = "judgment" ]; then
      # NO `자율 승인` ROW IS WRITTEN HERE. The refusal lands before the act is
      # recorded, which is what keeps a judgment from being adopted merely
      # because somebody submitted it — the union floor is the whole of the
      # admission, and a row written first would BE the adoption.
      # Reaching here with an ANSWERED approval means the resolution block above
      # found it spent — an unspent answer would have cleared `rules_rc` and this
      # branch would not run. So there is nothing to issue and nothing to adopt:
      # the judgment needs a question of its own.
      local iss_rc=0
      gate_issue_judgment_approval "$alias" "$segment" \
        "$(gate_field_of '기준' "$@")" "$(gate_field_of '근거' "$@")" \
        "$GATE_JUDGMENT_CLASS" "$(gate_judgment_seat)" || iss_rc=$?
      case "$(gate_judgment_approval_disposition "$iss_rc")" in
        발행) exit "$GATE_EXIT_APPROVAL" ;;
        답있음)
          # AN ANSWER CLOSED JUST NOW BY AUTO-RESOLUTION IS UNSPENT, so it opens
          # this judgment the way a person's answer would on the resubmission.
          # An older answer arriving here was found spent above and still refuses.
          if [ -n "${GATE_AUTO_RESOLVED_APPROVAL:-}" ] \
             && [ "$GATE_AUTO_RESOLVED_APPROVAL" = "${GATE_LAST_JUDGMENT_APPROVAL_ID:-}" ]; then
            GATE_RESOLVED_APPROVAL="$GATE_AUTO_RESOLVED_APPROVAL"
            rules_rc=0
          else
            exit "$GATE_EXIT_RULE"
          fi ;;
        닫힘) exit "$GATE_EXIT_RULE" ;;
        *) exit "$iss_rc" ;;
      esac
    else
      gate_issue_act_approval "$alias" "$segment" "$GATE_ACT_EFFECTIVE" "$graded" "$argv"
      exit "$GATE_EXIT_APPROVAL"
    fi
  fi
  [ "$rules_rc" = "0" ] || exit "$rules_rc"

  # THE ONE KIND THAT OUTLIVES THE SURFACE MOVE IS THE RUN SAYING IT ENDED.
  #
  # A moved enforcement surface is permanent: the branch below writes a run-scope
  # `blocked` row with `원인=무효화` and refuses every act after it. Termination
  # condition 5 then reads that row as unmet forever, and the whole point of the
  # invalidated arm further down is that such a run must still be able to write
  # `done` — as invalidated, never as satisfied.
  #
  # Without this bypass that arm could not be reached by the state it exists for.
  # The check sits above it, so the only `propose-done` that ever got past here
  # was one on a run whose blocked row had been placed by hand, and a real
  # invalidated run stayed `진행 중` forever — the exact condition the arm was
  # added to end. The render line that tells a person to propose done in this
  # state was, for the same reason, an instruction that could not be followed.
  #
  # The bypass is narrow in both directions. It needs the row to be there
  # ALREADY, so the first act after a surface move still takes the refusal, the
  # row and the banner — the detection is not weakened, only the second visit is
  # let through. And `propose-done` authorizes nothing: with that row present the
  # disposition is `무효화` by construction, so the only thing this can reach is
  # the arm that records the run as invalid.
  if ! { [ "$kind" = "propose-done" ] && gate_has_row 'blocked' '사유=강제 표면 이동'; }; then
    gate_surface_check "$verb" || exit $?
  fi

  # THE ROW CHECK AND THE WORKTREE PRE-CHECK USED TO SIT HERE, and they are now
  # above the rule catalog and the approval block — a refusal naming the field to
  # fix has to come before anything writes an approval about the same act. The
  # run-scope steps' exemption moved up with them, because an exemption reached
  # after the refusal it exempts is not one.
  #
  # `선행` STAYED, and the run-scope steps are exempt from it for the reason
  # stated up there: `--segment -` names no segment, so it has no predecessor to
  # land.
  if [ "$kind" = "skill" ] && [ "$stage_is_run_scope_step" = "0" ]; then
    # ORDER, AND THE SECOND CONSUMER OF `선행`.
    #
    # With only the cone's declared axis reading it, declaring narrowly would be
    # free: a segment that names no predecessor simply stays out of the cone, and
    # staying out is the direction that pays. The field costs something only when
    # its two consumers pull in opposite directions, and this is the other one —
    # a predecessor that has not LANDED is not a base this segment can be
    # dispatched onto, because the work it depends on is not in any tree yet.
    #
    # `머지됨` and `완료` only. `park` is terminal and did NOT land, so a
    # dependent dispatched over a parked predecessor is precisely the ordering
    # failure the declaration exists to prevent — unless the park came after a
    # `머지됨`: the merged work is on the base whatever the park says, so
    # `gate_segment_landed_now` steps back over a trailing `park` (and any
    # `적용 준비`) to the row before it. Such a merge that still owed this run's
    # apply did not finish the slice, and is refused as not landed.
    #
    # A `완료` an earlier run left at a pull request still open is brought in
    # with its `출처` and without a `머지 커밋`, so that this run does not do the
    # slice again — and its work is on no base this segment could branch from.
    # That row is not a landing here.
    #
    # Only `선행` is read here: a `머지 순서` predecessor orders the merge, not
    # the dispatch, and is checked at the merge below.
    local dep dst dep_row lrc
    for dep in $(gate_deps_of "$segment"); do
      [ -n "$dep" ] || continue
      lrc=0
      gate_segment_landed_now "$dep" || lrc=$?
      [ "$lrc" != "0" ] || continue
      if [ "$lrc" = "2" ]; then
        warn "the preceding segment ${dep} was merged but parked before the apply this run owes it was done — its slice is not finished"
        warn "dispatch again once a run applies ${dep}, or if there is no dependency rewrite the \`선행\` of the segment row"
        exit "$GATE_EXIT_RULE"
      fi
      dep_row=$(gate_rows 'segment' | gate_rows_field_eq 'id' "$dep" | tail -1)
      dst=$(gate_row_field "$dep_row" '상태')
      if [ "$dst" = "완료" ]; then
        warn "the preceding segment ${dep} was brought in from an earlier run at a pull request that is not merged — its work is not on the base this segment branches from"
        warn "dispatch again once that pull request is merged and a run brings the merge in, or if there is no dependency rewrite the \`선행\` of the segment row"
        exit "$GATE_EXIT_RULE"
      fi
      case "$dst" in
        *) warn "the preceding segment ${dep} has not landed yet (\`상태\`=${dst:-(none)}) — this segment has to branch on top of it"
           warn "dispatch again once the predecessor reaches \`머지됨\` or \`완료\`, or if there is no dependency rewrite the \`선행\` of the segment row"
           exit "$GATE_EXIT_RULE" ;;
      esac
    done
  fi

  # The eleven conditions are evaluated on EVERY act, not only on a done proposal.
  # A gate that can refuse a proposal but never cause one leaves the router
  # alone deciding when the night ends — so when every condition holds and the
  # router reaches for something else, it has to name what is left.
  local unmet disposition
  unmet=$(gate_done_conditions)
  disposition=$(gate_done_disposition "$unmet")
  if [ "$kind" = "propose-done" ]; then
    # THE DRY RUN ANSWERS AND WRITES NOTHING, and this arm sits ABOVE all three
    # of the arms that write, because two of them do it with an exit status of
    # zero. Without it, asking whether the run may stop ENDED the run: the `done`
    # file was created with an empty rationale, the terminal banner fired on a
    # live run, and the status was 0 in both directions — while the accepting arm
    # writes no ledger row at all. Neither the exit code nor the ledger told the
    # question apart from the act; only the file did.
    if [ "$verb" = "plan" ]; then
      # THE UNCHECKED AXES ARE NAMED HERE TOO, and this is the forecast that
      # needs them most. Every other `plan` announces what it did not look at
      # before returning; this one returned straight from the verdict, so the
      # single question that decides whether the night ends — "may the run
      # stop?" — was the one answered without disclosing its blind spot. The
      # snapshot digest is not compared on any dry run, so a `충족` here can
      # still meet exit 4 as an act when a sibling segment lands a row in
      # between, and nothing said so.
      case "$disposition" in
        충족)
          gate_plan_unchecked_axes "$kind"
          printf '통과 예상: 종료 조건이 전부 성립합니다 — act 로 내면 done 을 기록합니다\n'
          return 0 ;;
        무효화)
          gate_plan_unchecked_axes "$kind"
          printf '통과 예상: 무효화 종료 — act 로 내면 충족이 아니라 무효로 기록합니다\n'
          return 0 ;;
        *)
          warn "plan(dry-run): the termination proposal is refused — $(gate_unmet_summary "$unmet")"
          printf '%s\n' "$unmet" >&2
          exit "$GATE_EXIT_RULE" ;;
      esac
    fi
    # AN INVALIDATED RUN MUST STILL BE ABLE TO SAY IT ENDED. Condition 5 counts
    # a run-scope `blocked` row whose cause is `무효화` as permanently unmet —
    # deliberately, because clearing it would be the run re-authorizing itself
    # past the boundary that refused it. But the consequence was that such a run
    # could never write `done`: the snapshot rendered it `진행 중` forever, the
    # watcher's own exit condition never held, and a person had to kill three
    # processes by hand.
    #
    # The run is over either way. What changes here is only whether that fact
    # reaches disk. So when the invalidation is the ONLY thing left unmet, the
    # proposal is accepted and the `done` file records the run as invalidated
    # rather than as satisfied — the two must not read alike in the morning.
    # Condition 1's line for a run whose design step will not be dispatched
    # again reaches this arm on the same footing: no segment can ever exist.
    # Tested by POSITIVE equality against the token, and the arm below tests the
    # other accepted value the same way. Everything the function did not name —
    # including a value it never printed — falls through to the refusing arm.
    if [ "$disposition" = "무효화" ]; then
      warn "termination is recorded while the run is invalidated — it stands as void, not as satisfied"
      local _void_free
      _void_free=$(gate_free_budget "kind=$kind" "결정=act" "대상=$alias" "세그먼트=$segment" \
        "절단점=$GATE_ACT_EFFECTIVE" "유도 절단점=${GATE_ACT_DERIVED:--}" \
        "축2=$graded" "등급=1" "기준=무효화 종료" "되돌리는 법=새 런으로 다시 킥오프")
      gate_append '자율 승인' "kind=$kind" "결정=act" "대상=$alias" "세그먼트=$segment" \
        "절단점=$GATE_ACT_EFFECTIVE" "유도 절단점=${GATE_ACT_DERIVED:--}" \
        "축2=$graded" "등급=1" "기준=무효화 종료" \
        "되돌리는 법=새 런으로 다시 킥오프" "근거=$(gate_row_safe "$rationale" "$_void_free")"
      # THE UNREACHABLE CLAUSES ARE NAMED, for the reason the satisfied arm
      # names held ones: the ledger rows carry `상태=불가능`, but the morning
      # reads this line and the render, and neither said which goal was lost.
      local _void_imp _void_held
      _void_imp=$(gate_impossible_clause_ids | tr '\n' ' ' | sed 's/[[:space:]]*$//')
      _void_held=$(gate_held_clause_ids | tr '\n' ' ' | sed 's/[[:space:]]*$//')
      # The ending row below turns into `P0잔존` when the selector holds, and
      # this line is written first, so it asks the same selector.
      local _void_line
      _void_line=$(gate_p0_residual_done_line "$rationale" \
          " · 무효화${_void_imp:+ · 불가능 절 $_void_imp}${_void_held:+ · 보류 절 $_void_held}") \
        || _void_line=$(printf '%s 종단 — 무효화%s%s · 근거 %s' "$(now_iso)" \
             "${_void_imp:+ · 불가능 절 $_void_imp}" "${_void_held:+ · 보류 절 $_void_held}" "$rationale")
      gate_done_note "$_void_line"
      # Every `done` writer writes an ending row; gate_end_row says why.
      gate_end_row "무효화 종료" "$rationale" 해당없음 || true
      # The itemised dispositions land beside `done`, never inside it — the file
      # is a one-line contract with four consumers. An invalidated run gets the
      # enumeration too: what it disposed of on the way to being invalidated is
      # exactly what the morning has to look at.
      gate_write_disposition_report
      # `ended` and not `rekick`: the run has WRITTEN its ending here, so what is
      # left for a person is to read the result rather than to re-open anything.
      # The instruction to kick off again belongs to the site that anchors the
      # run, which has already spoken by the time this one does.
      if gate_may_raise_banner && cc_run_end_settled "$RUN_DIR" && cc_notify_claim_ended; then
        cc_notify_fire ended "런이 무효화된 채로 종료됐습니다 — 아침 보고서를 확인하세요" || true
        cc_notify_mark_ended_fired
      fi
      return 0
    fi
    if [ "$disposition" != "충족" ]; then
      warn "termination proposal refused — unmet conditions:"
      case "$unmet" in
        *" 미정산"*) warn "for an unsettled clause, leave grounds with act --kind clause or mark it \`불가능\`" ;;
      esac
      # A separate `case`: the one above stops at its first match, and a run
      # blocked at design carries both lines at once.
      case "$unmet" in
        *"1 세그먼트가 하나도 없고 설계 단계가 더는 파견되지 않습니다 "*)
          warn "the design is blocked, so this run can never produce a segment — settle the termination clauses that lean on the document as \`불가능\` (a clause held by a judgment approval the design stage opened: as \`보류\` naming that approval id), and this proposal is recorded as an invalidated termination" ;;
        *"1 세그먼트가 하나도 없고 감사 단계가 더는 파견되지 않습니다 "*)
          warn "the audit this plan opens on will not be dispatched again, so this run can never produce a segment — settle the termination clauses that lean on the audit or the segments as \`불가능\`, and this proposal is recorded as an invalidated termination" ;;
        *"1 베이스 분할이 더는 파견되지 않습니다 "*)
          warn "the base audit or split will not be dispatched again, so this run can never complete its split — settle the termination clauses that lean on the split as \`불가능\`, and this proposal is recorded as an invalidated termination" ;;
      esac
      printf '%s\n' "$unmet" >&2
      # THE ROW CARRIES A SUMMARY, NOT THE WHOLE LIST. Joining every unmet
      # condition made this field grow with the run — one unmet segment per
      # non-terminal segment, one per unsettled clause — and the row has a
      # 1024-byte cap, so a run with enough of them could not record its own
      # rejection: the append died and the router got exit 1 with no row at all.
      # Measured at 1228 bytes with nine segments in flight.
      #
      # The full text is already on stderr immediately above, which is where a
      # reader looks; what the row needs is enough to say what happened and how
      # many, bounded by construction.
      gate_append '자율 승인' "kind=$kind" "결정=기각" "대상=$alias" "세그먼트=$segment" \
        "절단점=$GATE_ACT_EFFECTIVE" "유도 절단점=${GATE_ACT_DERIVED:--}" \
        "축2=$graded" "등급=0" "기준=종료 조건 아홉" \
        "되돌리는 법=해당 없음(거부)" \
        "근거=$(gate_unmet_summary "$unmet")"
      exit "$GATE_EXIT_RULE"
    fi
    log "종료 조건이 전부 성립합니다"
    # The run's END, recorded as a FILE in the run directory. The ledger already
    # carries the row, but a row is not a thing another process can test cheaply
    # — and two processes need to: the liveness watcher, whose loop had no exit
    # condition and therefore outlived every run it watched, and a person asking
    # "is this still going?" without knowing the row grammar.
    #
    # A THIRD TERMINAL CLASS, because a run may now end while questions are
    # still open. No termination condition is created for the open question —
    # a condition exists to REFUSE a proposal, and an open question must not
    # refuse one; that refusal is the defect being removed. That rules out a
    # condition for this residual and does not fix how many conditions there
    # are: condition 11 was added later for a reason of its own. So the residual is
    # recorded in the `done` file beside `무효화`, which already sits there for
    # the same structural reason, and the morning tells the three apart at a
    # glance.
    #
    # THE PERSON SET (`사람-결정`, `시각-승인`) IS THE EXCEPTION AND NEVER
    # REACHES THIS ARM OPEN. Termination condition 2 counts it, because a
    # segment of this run is held on it, so `unmet` is not empty while one is
    # waiting and the run does not end over it.
    gate_done_note "$(gate_satisfied_done_line "$rationale")"
    # Each arm writes its ending row beside `done`, as the invalidated arm does:
    # only the satisfied one is a normal completion, `종료 부류=완료`.
    if [ -n "$(gate_pending_approval_ids 판단)" ]; then
      gate_end_row "질의 잔여 종단" "$rationale" 해당없음 || true
    else
      gate_end_row "종료 조건 성립" "$rationale" 해당없음 완료 || true
    fi
    gate_write_disposition_report
    # The notification seat is carried over from the other parent; its own
    # `done` write is not. That write spelled the same file with the older
    # single-class line and would have run after the branch above, overwriting
    # the very distinction that branch exists to record. The banner is kept
    # whole and fires on every terminal class, including the one holding open
    # questions — that is still an ending someone should be told about.
    # The other arm that decides the run's end. `ended`, because what a person
    # does next here is look at the result and decide what follows — the per-run
    # replace slot is exactly right for a fact that supersedes any earlier state
    # of the same run, and re-raising it costs nothing.
    if gate_may_raise_banner && cc_run_end_settled "$RUN_DIR" && cc_notify_claim_ended; then
      cc_notify_fire ended "런이 종단했습니다 — 아침 보고서를 확인하세요" || true
      cc_notify_mark_ended_fired
    fi
  # BOOKKEEPING IS EXEMPT, AND THE EXEMPTION IS THIS ARM'S OWN PURPOSE READ
  # CORRECTLY. What it refuses is a router that walks past a satisfied ending and
  # keeps routing; a row recording WHY the seat stopped is not walking past
  # anything. Without it all eight bookkeeping kinds are refused with exit 3 in
  # exactly the state where the protocol requires the terminal shift to write its
  # `handoff` row — and no `--rationale` reaches them, because the three sources
  # `gate_names_next_obligation` can name are all empty precisely when `unmet`
  # is. The morning then loses the last shift's rejected alternatives whole.
  elif [ -z "$unmet" ] && ! gate_kind_is_bookkeeping "$kind"; then
    # THE LITERAL TEST STAYS. Every other site compares the disposition token by
    # positive equality, and this one cannot: the chain ends at `fi`, so there is
    # no refusing arm to fall into, and the polarity is inverted — ENTERING this
    # branch is what produces the refusal. Written as `= "충족"` an unrecognized
    # value would SKIP the obligation check and let the act proceed unexamined,
    # which is the one place the token form would be looser than the literal.
    #
    # `--rationale` does not switch this axis off. Skipping it removes a rare
    # false red and opens a false green in the far commoner all-met state, where
    # there is nothing to name and `act` refuses every rationale too — so the
    # skip would make `plan` answer 0 exactly where `act` answers 3. What the
    # missing input gets instead is disclosure.
    if [ "$verb" = "plan" ] && [ -z "$rationale" ]; then
      warn "plan(dry-run): with no --rationale the obligation-naming axis was evaluated on empty grounds — ask again with the argv the router will actually issue and it becomes exact"
    fi
    if ! gate_names_next_obligation "$rationale"; then
      warn "every termination condition holds, but the next obligation could not be named — the run terminates as satisfied"
      # THE RUN IS ENDED HERE, NOT ONLY DECLARED ENDED. This arm has always said
      # the run terminates as satisfied and then written neither `done` nor an
      # ending row, so the watcher kept the run alive and a `사유=종단` handoff
      # had nothing to stand on. `plan` predicts and never ends a run; an ended
      # run is left as it is, because `gate_end_run` does nothing once `done`
      # exists. The exit code stays 3: the act itself is still refused.
      #
      # AND IT IS ENDED THE WAY AN ACCEPTED PROPOSAL ENDS IT. All-met admits open
      # judgment questions and held clauses, and `gate_names_next_obligation`
      # does not look at either, so this arm meets that state too. It writes the
      # proposal's `done` line, keeps `종료 부류=완료` for a run with no open
      # question, and writes the disposition report — otherwise the first line,
      # which `gate_done_note` never replaces, would call a run that still owes
      # answers a normal completion.
      if { [ "$verb" = "act" ] || [ "$verb" = "exec" ]; } && ! [ -s "$RUN_DIR/done" ]; then
        local end_why end_kind=완료
        end_why="${rationale:-다음 의무 지목 불가}"
        [ -z "$(gate_pending_approval_ids 판단)" ] || end_kind=""
        gate_end_run "종료 조건 성립" "$end_why" 해당없음 "$end_kind" "" \
          "$(gate_satisfied_done_line "$end_why")" || true
        gate_write_disposition_report || true
      fi
      exit "$GATE_EXIT_RULE"
    fi
  fi

  # THE CI VERDICT, AND ITS SEAT IS THREE PROPERTIES AT ONCE: after the rule
  # loop so a CI refusal is not confused with a rule refusal, upstream of both
  # appends — the `자율 승인` row below and the obligation row the issuer writes —
  # so a refused merge leaves no obligation nothing can close, and above the
  # forecast arm so `plan` answers with the same code `act` would. The merge
  # anchor check moved above the approval block; this one does not follow it,
  # because up there it would run before the rule loop. It refuses by setting
  # the park cell rather than by returning, so the block immediately below
  # writes the row — no new exit code is minted for it. It takes the effective
  # rung for the same reason the anchor check does: an under-declared merge
  # must not skip it. It does not take the kind: what decides whether an act
  # merges is the surface and history-integration values set above, so a stage
  # launch or a read labelled `머지` is let through on what it does rather than
  # on what it is called.
  # THE RERUN ACT'S OWN VERDICT stands right ahead of it, on the same seat and
  # for the same reasons: past the drain and the rule loop, ahead of every
  # append, and above the forecast. Every other kind returns from it at once.
  gate_check_ci_rerun "$kind"
  gate_check_ci_match "$kind"
  gate_check_label_ack "$kind"
  gate_check_merge_checks "$segment" "$GATE_ACT_EFFECTIVE"
  # THE LANDING TREE'S OWN GATE, asked before it lands. Same seat as the CI
  # verdict above and for the same three reasons; it does nothing when that
  # verdict already set the park cell.
  gate_check_grade_regression "$segment" "$GATE_ACT_EFFECTIVE" "$alias" "$@"
  # THE ENFORCEMENT-SURFACE PROVENANCE, in the same seat on the same narrowing.
  # It refuses rather than parks: what it found is a branch to repair, not a
  # cell a declaration could open.
  gate_check_surface_provenance "$segment" "$GATE_ACT_EFFECTIVE" "$alias" || exit $?

  # --- park 디스패치 -------------------------------------------------------
  # THE JUDGMENT WAS MADE ABOVE; ONLY THE WRITE IS HERE. Everything between the
  # two is a refusal axis that would have stopped this act anyway, and a park row
  # written ahead of them would record a disposition the act never reached.
  if [ -n "${GATE_PARK_CELL:-}" ]; then
    local _ad; _ad=$(printf '%s' "$*" | shasum -a 256 | cut -d' ' -f1)
    if [ "$verb" = "plan" ]; then
      # The forecast answers with the same code the act would take, and writes
      # nothing — a dry run that left a park row would make the run's own record
      # of what it refused depend on who asked.
      printf 'park 예상: 도달 판정=%s kind=%s target=%s 축2=%s 도달=%s\n' \
        "$GATE_PARK_CELL" "$kind" "$alias" "$graded" "${GATE_REACH:--}"
      gate_park_repair_line "$GATE_PARK_CELL" "${GATE_PARK_CAUSE:--}"
      return "$GATE_EXIT_PARK"
    fi
    # RE-DECLARING DOES NOT RE-OPEN IT. The same act at the same digest takes the
    # verdict already recorded, and no second row is written: a stage that
    # answers a park by changing its `--reach` and trying again would otherwise
    # walk the table until some cell let it through.
    if gate_has_row 'blocked' "행위 다이제스트=$_ad"; then
      warn "this act is already parked (act digest=$_ad) — re-declaring does not change the disposition"
      exit "$GATE_EXIT_PARK"
    fi
    warn "reach park — judgment '$GATE_PARK_CELL'. This act was not performed, and retrying or re-declaring with a different reach gets the same judgment. If it is not essential, carry on with what can be done without it; if it was essential, write a halt record with \`분류\` 'gate-unanswerable' and stop"
    gate_park_record "$GATE_PARK_CELL" "${GATE_PARK_CAUSE:--}" "${GATE_PARK_OBS:-$1}" "$@"
    exit "$GATE_EXIT_PARK"
  fi

  # THE FORECAST IS ISSUED HERE, past every read-only axis and before every
  # write. Above this line sit the surface comparison, the segment-row existence
  # check, the predecessor-landing check, the termination conditions, the
  # obligation-naming arm and the anchor check — all reads, and all of them axes
  # the same argv meets as an `act`. Below it sit the boundaries, the credential
  # resolution, the ledger append and the act itself.
  if [ "$verb" = "plan" ]; then
    gate_plan_unchecked_axes "$kind"
    # The forecast reports the rung the act would be ADJUDICATED at, and names the
    # derived one beside it. Reporting the declared word would make the dry run
    # disagree with the row the same argv writes as an `act` — which is the one
    # thing a forecast must not do.
    printf '통과 예상: kind=%s target=%s 절단점=%s 유도=%s 축2=%s\n' \
      "$kind" "$alias" "$GATE_ACT_EFFECTIVE" "${GATE_ACT_DERIVED:--}" "$graded"
    return 0
  fi

  gate_boundaries "$graded" "$kind"

  # Which credential the act will actually run under, recorded on every act.
  # With neither pipeline credential provisioned the gate used to fall through
  # to whatever the calling environment already held — on a developer machine a
  # full-scope `gh` login — and say nothing, so the layer the separation exists
  # to provide was absent while every surface reported normal operation. The
  # fallback stays (refusing would stop every host that has not provisioned one
  # yet), but it is no longer silent: it is one field in the morning's report.
  local credmode='분리'
  if ! cred_readonly_env >/dev/null 2>&1; then
    credmode='주변'
    # Loud only above `읽기`. A bookkeeping act reaches nothing a credential
    # could widen, and a warning on every row teaches the reader to skip the
    # line that matters.
    [ "$graded" = "읽기" ] || \
      warn "no pipeline credential, so this runs with the ambient credential — credential separation is not attached to this act"
  fi

  # WHO IS WRITING THIS ROW, recorded for the readers that come later. `교대=`
  # is 0 for the lead and for a stage alike — it reads only the shift marker —
  # so nothing on the row told the lead's dispatch from a stage's. The progress
  # vector's `dispatches=` positively selects on this field so that a stage
  # calling `act --kind skill` cannot write the router's own progress; the
  # morning report and a replay read it too. It does not replace the runtime
  # caller check in `gate_boundaries` — that reads the environment at judgment
  # time, this is for whoever reads the row afterwards. The stage test comes
  # before the shift marker because a stage a shift launched inherits
  # `CC_PIPELINE_SHIFT_ID`.
  local actor='리드'
  if cc_caller_is_stage; then
    actor='스테이지'
  elif [ -n "${CC_PIPELINE_SHIFT_ID:-}" ]; then
    actor='교대'
  fi

  # A TARGET'S OWN BASH HOOK. The bare form first meets what only it has: the
  # refspec check, the issuing-root rule and the credential rule; then the remote
  # state its settlement will compare against. Both forms then meet the repeat
  # block, and the bare form asks the issuing root's hooks what they will say.
  # All of it sits here, past every read-only axis and the boundaries, because
  # the remote read and the hook row are writes.
  local _admit_pred="" _admit_text="" _admit_tid="없음" _form='감쌈' _adig=""
  if [ "${GATE_ADMIT:-}" = "1" ]; then
    _form='맨'
    gate_admit_head_refspec_ok "$segment" "$@" || exit "$GATE_EXIT_VOCAB"
    gate_admit_root_rule "$alias"
    # The bare command runs under the session's own credential, not the
    # read-scoped set the gate hands an exec; where the run separates the two,
    # anything above a read would leave that separation behind.
    if [ "$credmode" = "분리" ] && [ "$graded" != "읽기" ]; then
      warn "this run separates the pipeline credential, and the bare form runs under the session's own — an act graded '$graded' cannot be admitted bare here"
      warn "issue it through exec, which runs it under the separated credential"
      exit "$GATE_EXIT_RULE"
    fi
    case "${GATE_ACT_DERIVED:-}" in
      push|PR|머지) [ "$segment" = "-" ] || gate_remote_state_refresh "$alias" "$segment" ;;
    esac
  fi
  if [ "$verb" = "exec" ] || { [ "$verb" = "act" ] && ! gate_kind_is_bookkeeping "$kind"; }; then
    _adig=$(printf '%s' "$*" | shasum -a 256 | cut -d' ' -f1)
    # The segment's own old tickets settle first, so a remote write whose
    # effect never showed is a refusal row before the block reads the rows.
    [ "$segment" = "-" ] || gate_admit_settle "$segment"
    gate_refusal_block "$alias" "$segment" "$_adig" "$_form"
  fi
  if [ "${GATE_ADMIT:-}" = "1" ]; then
    GATE_ADMIT_DIGEST="$_adig"
    gate_target_hook_row "$alias" "$GATE_ADMIT_PDIR"
    local _pr_out
    _pr_out=$(gate_thp thp_probe "$GATE_ADMIT_PDIR" "$GATE_ADMIT_BYTES" "$GATE_ADMIT_CWD" "admit-$GATE_ADMIT_REQ_ID")
    _admit_pred=$(printf '%s\n' "$_pr_out" | sed -n 1p)
    _admit_text=$(printf '%s\n' "$_pr_out" | sed -n 2p)
    [ -n "$_admit_pred" ] || _admit_pred='판정 불가'
    # The ticket's content and sealed id are fixed before the row, which
    # carries the id; the file itself is written after the row. A non-blocking
    # failure is a pass, since the harness runs the tool after it; a probe
    # timeout is not, since a ticket would let the real guard's late refusal
    # go unrecorded.
    if gate_admit_pred_passes "$_admit_pred"; then
      gate_admit_prepare "$alias" "$segment" "$actor" "$graded"
      _admit_tid="$GATE_ADMIT_TID"
    fi
  fi

  # A BOOKKEEPING KIND IS DECIDED BEFORE THE APPROVAL ROW IS WRITTEN, and every
  # other kind after it. The two orderings look inconsistent and are not: what
  # the early row buys is a record surviving a crash PART WAY THROUGH AN ACT,
  # and a bookkeeping kind performs no act — its entire effect is one atomic
  # `gate_append`, which either lands whole or not at all. So writing approval
  # first buys nothing there and costs the thing this ordering must not cost: a
  # REFUSED row still leaves a row saying the gate approved it, and refusals on
  # this arm are ordinary (a ceiling excess, a missing `워크트리`, an obligation
  # naming another target). A refusal that grows the ledger is indistinguishable
  # in the morning from an act that happened.
  #
  # THE SET IS STILL SPELLED ONCE. Moving the branch above the approval row is
  # an ordering change and not a second copy of the vocabulary — re-spelling the
  # kinds here would leave this arm behind the moment a kind is added, which is
  # exactly what `gate_kind_is_bookkeeping` exists to prevent.
  local rc=0
  local bookkeeping=
  if gate_kind_is_bookkeeping "$kind"; then
    bookkeeping=1
    gate_record_row "$kind" "$segment" "$alias" "$@" || return $?
  fi

  # TWO FIELDS AND NOT ONE. `절단점` is what the gate ADJUDICATED this act as and
  # `유도 절단점` is what the argv itself said, `-` where the table stayed silent.
  # Folded into one field, "the argv says this is a merge" and "the caller says
  # this is a merge" become the same sentence — and telling those apart is the
  # entire subject of this axis.
  # TWO CALL SITES, AND THE SECOND IS exec's ALONE. The shared row is already
  # within five bytes of the 1024-byte cap on the router's own `act` rows, so the
  # seven fields this axis adds cannot go there. The exec row carries them with a
  # budget of its own: `근거` is clipped first at 240 bytes and the argv excerpt
  # takes what is left, so a long alias or segment shrinks the excerpt rather
  # than pushing the row past the cap.
  #
  # `행위자` RIDES ON BOTH SITES, and the cap sentence above is about the seven
  # exec fields rather than about any one field. The seat is a fact about who
  # called and not about which verb was called, so a stage that reaches `exec`
  # has to be as legible as one that reaches `act` — and the progress vector's
  # `dispatches=` positively selects on this field, so a row missing it is a row
  # that cannot be attributed. It costs at most 25 bytes (`| 행위자=` plus the
  # longest value). The shared site has no spare room to spend it from — `근거`
  # takes what `gate_free_budget` leaves, so a long rationale fills the row to
  # the cap, and the longest non-exec act row in this repository's ledgers
  # measures 1023 bytes by the gate's ruler — which is why `행위자` is in that
  # budget's field list and not added after it. On the exec site the budget pays for it
  # explicitly — `${#actor}` is in `_row_fixed` and the constant carries the key,
  # so the argv excerpt shrinks rather than the row growing.
  if [ "$verb" = "exec" ]; then
    local _row_fixed _argv_budget _ad2 _adm=()
    _ad2=$(printf '%s' "$*" | shasum -a 256 | cut -d' ' -f1)
    # The bare form's four fields say which request was graded, whether a ticket
    # was left and what the issuing root's hooks were predicted to answer.
    if [ "${GATE_ADMIT:-}" = "1" ]; then
      _adm=("형태=맨" "요청=$GATE_ADMIT_REQ_ID" "티켓=$_admit_tid" "예측=$_admit_pred")
    fi
    _row_fixed=$(( ${#alias} + ${#segment} + ${#GATE_ACT_EFFECTIVE} + ${#graded} + ${#actor} + 336 ))
    [ "${#_adm[@]}" -eq 0 ] || _row_fixed=$(( _row_fixed + ${#_adm[0]} + ${#_adm[1]} + ${#_adm[2]} + ${#_adm[3]} + 12 ))
    _argv_budget=$(( 1024 - 16 - _row_fixed ))
    [ "$_argv_budget" -gt 128 ] && _argv_budget=128
    [ "$_argv_budget" -lt 0 ] && _argv_budget=0
    local _ex=() _jx2=() _jl2
    _ex=("kind=$kind" "결정=$verb" "대상=$alias" "세그먼트=$segment" \
      "절단점=$GATE_ACT_EFFECTIVE" "유도 절단점=${GATE_ACT_DERIVED:--}" \
      "축2=$graded" "자격=$credmode" "행위자=$actor" \
      "등급 출처=$GATE_GRADE_SOURCE" "선언=${GATE_DECLARED:--}" \
      "표지=${GATE_MARK:--}" "파괴 출처=$(gate_destructive_source)" \
      "도달=${GATE_REACH:--}" "유도 도달=$(gate_reach_derived "$alias" "$@")" \
      "식별자 대조=$(gate_dev_identifier_check "$alias" "$@")" \
      "행위 다이제스트=$_ad2" ${_adm[@]+"${_adm[@]}"} \
      "argv=$(gate_row_safe "$*" "$_argv_budget")")
    # A machine-global act a judgment opened carries the verdict and its reason,
    # the reason taking only what the row has left once everything else is in.
    if [ "${GATE_PREAUTH_JUDGE:--}" != "-" ]; then
      _jl2=$(gate_preauth_judge_label "$GATE_PREAUTH_JUDGE")
      _jx2=("사전 인가 판단=$_jl2")
      _jx2+=("판단 이유=$(gate_row_safe "$(gate_preauth_judge_reason "$GATE_PREAUTH_JUDGE")" \
        "$(gate_free_budget "${_ex[@]}" "사전 인가 판단=$_jl2" "판단 이유=" "근거=$(gate_row_safe "$rationale" 240)")")")
    fi
    gate_append '자율 승인' "${_ex[@]}" ${_jx2[@]+"${_jx2[@]}"} \
      "근거=$(gate_row_safe "$rationale" 240)"
  else
    # A review dispatch carries its report path and, on a re-dispatch after a
    # dropped connection, the recovery marker, both as fixed fields: `근거`
    # takes what they leave, and the path is never clipped (its fit was
    # measured before any row). The declared trigger rides beside the path; a
    # `라우터 판단` trigger's reason opens `근거`, so the one clip below takes
    # both and the reason is never clipped apart from the rationale.
    local _act_free _act_fx=() actwhy=$rationale
    [ -z "$rv_rp" ] || _act_fx+=("리포트 경로=$rv_rp")
    [ -z "$rv_trig" ] || _act_fx+=("계기=$rv_trig")
    [ -z "$GATE_RECOVERY" ] || _act_fx+=("복구=$GATE_RECOVERY")
    [ "$rv_trig" != "라우터 판단" ] || actwhy="계기 사유: $GATE_TRIGGER_REASON; $rationale"
    _act_free=$(gate_free_budget "kind=$kind" "결정=$verb" "대상=$alias" "세그먼트=$segment" \
      "절단점=$GATE_ACT_EFFECTIVE" "유도 절단점=${GATE_ACT_DERIVED:--}" \
      "축2=$graded" "자격=$credmode" "행위자=$actor" ${_act_fx[@]+"${_act_fx[@]}"})
    gate_append '자율 승인' "kind=$kind" "결정=$verb" "대상=$alias" "세그먼트=$segment" \
      "절단점=$GATE_ACT_EFFECTIVE" "유도 절단점=${GATE_ACT_DERIVED:--}" \
      "축2=$graded" "자격=$credmode" "행위자=$actor" ${_act_fx[@]+"${_act_fx[@]}"} \
      "근거=$(gate_row_safe "$actwhy" "$_act_free")"
  fi
  log "게이트 통과 — $verb $GATE_ACT_EFFECTIVE ($alias)"

  # THE PACE ROW RIDES ON THE APPROVAL ROW AND ON NOTHING ELSE. `snapshot` is a
  # read and must stay one, so the only place the ledger learns that the sensor's
  # verdict moved is here, once per approved act or exec, and only when it moved.
  gate_pace_row_if_changed
  # The base branch's reading rides on the same seat for the same reason.
  gate_master_row_if_changed

  # The RESOLVED policy and not a flag value. What decides whether a merge defers
  # its review is the segment row bounded by the target's ceiling, and a caller
  # that could name the policy on the command line could also name one the
  # ceiling forbids.
  # THE FIFTH CONSUMER, AND IT SITS BELOW THE SEAM — so the seam alone does not
  # reach it and this call site is corrected on its own. Left reading the declared
  # rung it would go on comparing `= 머지` against a word the caller chose, and
  # "an under-declared merge issues no obligation" would survive the whole repair.
  # THE KIND TRAVELS WITH IT: a bookkeeping act reaches this line before its own
  # return below, and the issuer must know it is one so as not to reopen a slot
  # the segment already fulfilled.
  gate_issue_review_obligation "$segment" "$GATE_ACT_EFFECTIVE" "$graded" "$GATE_REVIEW_POLICY" "$alias" "$kind"

  [ -n "$bookkeeping" ] && return 0

  # THE BARE FORM PERFORMS NOTHING. The row above is its record; what is left is
  # either the refusal its root's hooks predicted — a `대상 거절` row, and the
  # request stays for a corrected retry to replace — or the ticket the run hook
  # lets the same bytes through on once.
  if [ "${GATE_ADMIT:-}" = "1" ]; then
    if ! gate_admit_pred_passes "$_admit_pred"; then
      gate_refusal_condition "$alias" "$segment" "$GATE_ADMIT_PDIR"
      gate_refusal_row "$alias" "$segment" "$actor" 맨 예측 "$_ad2" "$GATE_ADMIT_BYTES" \
        "$_admit_pred: ${_admit_text:-미상}"
      warn "the hooks of the issuing root '$GATE_ADMIT_PDIR' are predicted to answer '$_admit_pred' for this command: ${_admit_text:-(no text)}"
      warn "no ticket is left; the refusal is on the ledger and the same act stays closed until its condition moves"
      exit "$GATE_EXIT_RULE"
    fi
    gate_admit_issue
    return 0
  fi

  # ---- and now PERFORM it -------------------------------------------------
  #
  # Recording without performing is what the first cut of this file did, and it
  # makes the whole layer unreachable: layer 1 denies every bash line that is
  # not this script, so if this script does not run the line, nothing runs at
  # all. The row is written BEFORE the act, deliberately — a row with no act is
  # an over-report a person can see in the morning, and an act with no row is
  # the thing this design exists to prevent.
  # EVERY RETURN FROM HERE DOWN EMITS, AND EMITS LAST. The emission runs from an
  # EXIT trap, so it sees the state after this call's final ledger write — and
  # the exits below write different numbers of rows: the `자율 승인` row above is
  # the last write for `exec`, for `act --kind skill` and for a bookkeeping kind
  # (whose own row was already written above it), and a failed act writes one
  # more at the bottom. That sentence stays true for `act --kind skill` now that
  # the dispatch returns at once: the stage's terminal `stage-result` row is
  # written by the detached supervisor in its own process, hours later, and is
  # not a write of THIS call. A pre-append value would hand the caller a digest already
  # stale on arrival and every acting call after it would come back exit 4 — a
  # run that deadlocks loudly on the mechanism meant to speed it up. `plan` never
  # reaches this line and emits nothing, which is why the re-read after a `plan`
  # stays in the router's contract.
  [ "$kind" = "propose-done" ] && return 0
  case "$verb" in
    exec)
      # The stage's own credential set: read-scoped, so a `gh pr merge` spelled
      # here fails at the API rather than at a string match.
      gate_run_readonly "$@" || rc=$?
      ;;
    act)
      case "$kind" in
        # The return is LAUNCH success — the supervisor was detached and the
        # token consumed — and not the stage's rc, which `wait` reports.
        # `stage_key` is the segment id, or the plan's design step id when the
        # dispatch named `-` (the exemption above set it).
        # The run-scope audit gets its own tree first; a refusal there is the
        # act's failure and nothing is launched.
        skill) gate_dispatch_doc_arg "${1:-}"
               # The design's review runs where the design ran, not in the
               # audit's tree.
               if [ "$stage_is_run_scope_step" = "1" ] \
                  && { [ "${1:-}" = "audit" ] \
                       || { [ "${1:-}" = "reconverge" ] && [ "$rs_table" = "audit" ]; }; }; then
                 gate_audit_worktree_ensure "$alias" || rc=$?
               fi
               [ "$rc" != "0" ] || gate_launch_stage "$alias" "$stage_key" "$@" || rc=$? ;;
        # The first token after `--` is the HANDOFF REASON here, the way it is
        # the stage kind for `skill`. Same shape, different layer: this one
        # decides whether the suppressor below applies, and the settings variant
        # is always `shift`.
        router-shift) gate_relay_route "$alias" "$@" || rc=$? ;;
        # The frozen command at the proved merge commit, never the argv.
        apply) gate_perform_apply "$alias" "$segment" || rc=$? ;;
        # The POST and its confirmation, never the argv: `재실행 <sha>` run as a
        # command would skip the performer's guard.
        ci-rerun) gate_perform_ci_rerun "$alias" "$segment" "$@" || rc=$? ;;
        # The reads and the match row, never the argv.
        ci-match) gate_perform_ci_match "$alias" "$segment" || rc=$? ;;
        # The label POST and its confirmation, the same way as the rerun's.
        label-ack) gate_perform_label_ack "$alias" "$segment" "$@" || rc=$? ;;
        *)     gate_run_readonly "$@" || rc=$? ;;
      esac
      ;;
  esac
  # The act's own status passes through, the way `env` and `nice` pass one
  # through. A gate REFUSAL is 2..7 and always arrives with a `gate:` line on
  # stderr and no output from the act, so the two are told apart by what came
  # with the code rather than by the code alone — which is the honest reading,
  # since an act is free to exit 3 for its own reasons and no remapping can
  # both preserve its status and reserve a band.
  #
  # A failure gets a SECOND row. The first is written before the act so that a
  # crash mid-act still leaves a record; adding the outcome to that row would
  # mean holding it until the act returned, which is the property being bought
  # by writing early.
  if [ "$rc" != "0" ]; then
    warn "the act failed (rc=$rc) — the row is already in the ledger"
    gate_append '자율 승인' "kind=$kind" "결정=결과" "대상=$alias" "세그먼트=$segment" \
      "절단점=$GATE_ACT_EFFECTIVE" "유도 절단점=${GATE_ACT_DERIVED:--}" \
      "축2=$graded" "근거=rc=$rc"
  fi
  return "$rc"
}

# ---------------------------------------------------------------------------
# An undeclared repository — three layers, and the gate never grants a cutpoint.
#
# A repository the manifest does not name has no cutpoint, so a row that gave it
# one would move the seat of authorization from the manifest (which this run
# cannot write) to the ledger (which it can). That is the property the split
# writer exists to hold, and it does not rest on whether the row is forgeable:
# even an unforgeable approval would be relocating authorization.
#
# Why an approval can open a MERGE on a declared target but cannot open a PUSH
# here: the declared target already has a cutpoint and the approval opens one
# act inside it, while here there is no cutpoint to open, so the approval would
# be creating a permission SCOPE. The first is an event inside an authorization,
# the second is an extension of one.
# ---------------------------------------------------------------------------
gate_undeclared_target() {
  # gate_undeclared_target <alias> <cutpoint> <worktree>
  local alias="$1" cut="$2" wt="$3" idx branch_idx cg layer
  branch_idx=$(cutpoint_index '브랜치') || return "$GATE_EXIT_VOCAB"
  idx=$(cutpoint_index "$cut") || return "$GATE_EXIT_VOCAB"

  if [ "$idx" -gt "$branch_idx" ]; then
    # Layer 2. The honest default, and its cost is one command in the morning.
    # `인가 한도` would be the wrong cause — that one means an act exceeded a
    # cutpoint the target HAS, and the whole point here is that it has none.
    #
    # The row carries `재킥 원인=대상미선언` and stays act-scope: it parks the
    # slice that needs this target, not the run, and it is not an end token —
    # whatever later ends the run reads this row as the change a re-authorization
    # would have to carry.
    gate_append 'blocked' "대상=$alias" "스코프=act" "원인=막힘" "사유=대상 미선언" \
      "관측=$(now_iso)" "재개 명령=/cc-cmds:autopilot <목표> — 이 레포를 대상에 포함해 재킥오프" \
      "재킥 원인=대상미선언"
    warn "target '$alias' is not declared in the manifest — grade '$cut' needs a re-authorization, and the gate does not grant it"
    return "$GATE_EXIT_RULE"
  fi

  # Layers 0 and 1. The same preflight a manifest target gets, and it is not
  # optional: stash attribution is per-REPOSITORY rather than per-worktree, and
  # this very tree already has two working trees sharing one `.git` and one
  # `refs/stash`.
  [ -n "$wt" ] || {
    warn "an undeclared target '$alias' needs --worktree (with no preprocessed target there is nothing to judge)"
    return "$GATE_EXIT_VOCAB"
  }
  [ -d "$wt" ] || { warn "the worktree of undeclared target '$alias' does not exist: $wt"; return "$GATE_EXIT_VOCAB"; }
  cg=$(gate_common_git_of_dir "$wt" || true)
  [ -n "$cg" ] || { warn "could not read the common git directory of undeclared target '$alias'"; return "$GATE_EXIT_VOCAB"; }

  # Layer 0 is read-only; anything at `커밋` or above is a local write.
  layer=0
  [ "$idx" -ge "$(cutpoint_index '커밋')" ] && layer=1

  gate_has_row '대상 추가' "별칭=$alias " || \
    gate_append '대상 추가' "별칭=$alias" \
      "원격 슬러그=$(cd "$wt" && git config --get remote.origin.url 2>/dev/null | sed 's#.*[:/]\([^/]*/[^/]*\)\(\.git\)\{0,1\}$#\1#' || printf '미상')" \
      "메인 워크트리=$wt" "공통 git 디렉터리=$cg" \
      "베이스 브랜치=$(cd "$wt" && git rev-parse --abbrev-ref HEAD 2>/dev/null || printf '미상')" \
      "층=$layer" "발견 경로=$rationale" "기록 시각=$(now_iso)"

  # The effective cutpoint is HARDCODED to `브랜치`. Not inherited from the run
  # maximum, not chosen by the router — nothing above it leaves the machine, and
  # that is the entire reason no approval is needed.
  GATE_TARGET_CUTPOINT='브랜치'
  GATE_TARGET_INDEX="$branch_idx"
  GATE_ACT_INDEX="$idx"
  # The merge rung travels with the act rung, exactly as on the declared path.
  # A checker that fires at merge OR ABOVE needs both integers to decide it is
  # NOT firing, so shipping only one makes it refuse for want of an index — and
  # that refusal lands on acts far below merge, where the checker had nothing to
  # say. Fail-closed in a checker is right; reaching it with a half-filled
  # environment is the caller's defect.
  GATE_MERGE_INDEX=$(cutpoint_index '머지') || return "$GATE_EXIT_VOCAB"
  export GATE_TARGET_CUTPOINT GATE_TARGET_INDEX GATE_ACT_INDEX GATE_MERGE_INDEX
  GATE_UNDECLARED=1
  # The tree this alias's acts run in, recorded where the flag is set so that
  # `gate_act_worktree` can answer for an alias that has no target row. `$wt`
  # is already known to be a directory holding a git tree — the layer-0 checks
  # above required it and `gate_common_git_of_dir` read it.
  GATE_UNDECLARED_WT="$wt"
  return 0
}

gate_act_approval_id() {
  # gate_act_approval_id <alias> <argv> [<해소된 워크트리>]
  #
  # Factored out because TWO places must agree on it: the one that issues the
  # approval and the one that asks whether it has since been answered. They were
  # one expression in one place, so nothing could ask. They must also agree on
  # the THIRD argument, which means both have to resolve the tree through
  # gate_act_worktree with the same segment — the same requirement the freeze and
  # the staleness comparison already carry, and this is its fourth reader.
  #
  # THE TREE IS PART OF THE IDENTITY, NOT ONLY OF THE FRESHNESS PROBE. The
  # binding tuple records the tree as a 12-character head fragment and staleness
  # compares that fragment, which identified the tree only while a target had one
  # of them. Two segment worktrees branched from the same base have the SAME
  # head, and that is exactly the moment a run dispatches its first stage into
  # each — so a person's answer about segment A's act opened segment B's
  # identical argv, because B computed A's id and read A's head out of B's tree.
  # Keyed on the tree, the two acts are two approvals and the question is asked
  # about the tree it is answered for. It also ends the mirror case: once the two
  # trees diverge, A and B each saw the other's answer as stale and superseded it
  # under the shared id, putting the same question in front of a person on a
  # loop.
  printf 'A-%s' "$(printf '%s|%s|%s|%s' "$RUN_ID" "$1" \
    "$(printf '%s' "$2" | shasum -a 256 | cut -d' ' -f1)" "${3:-}" \
    | shasum -a 256 | cut -c1-8)"
}

gate_approval_state() {
  # The LAST row for this id wins, the way the termination conditions already
  # read approvals and review obligations.
  #
  # THE ID IS MATCHED AS A WHOLE FIELD, `| 승인 id=<id> |`, here and in every
  # reader of one approval's rows. A free-text field may quote another
  # approval's id — a router citing its own earlier decision in `기준` puts
  # `승인 id=<id>` into that judgment's `질문 문면` — and a substring match read
  # such a row as the last row of the id it quoted, so a closed judgment could
  # read as `승인` and be adopted with nobody asked. No value keeps a `|` on its
  # way into the ledger, so the two bars bound this field alone.
  { gate_rows '승인' | grep -F "| 승인 id=$1 |" || true; } | tail -1 \
    | tr '|' '\n' | sed -n 's/^ *상태=//p' | sed 's/[[:space:]]*$//' | tail -1
}

gate_approval_field() {
  # gate_approval_field <승인 id> <키> — the last value that key ever carried on
  # a row for this approval.
  #
  # NOT "the last row's value", which is what `gate_approval_state` wants and
  # this does not: `close` appends a resolution row carrying only the id, the
  # state, the question, the answer and the time, so a reader that looked at the
  # last row for `구속 튜플` found nothing on every answered approval — that is,
  # on exactly the approvals whose tuple anyone would want to check.
  { gate_rows '승인' | grep -F "| 승인 id=$1 |" || true; } \
    | tr '|' '\n' | sed -n "s/^ *$2=//p" | sed 's/[[:space:]]*$//' | tail -1
}

gate_act_tuple_head() {
  # gate_act_tuple_head <승인 id> — the head fragment frozen into an act
  # approval's binding tuple, or nothing when the tuple holds none.
  #
  # The tuple is `<별칭>/<베이스 브랜치>/<head 앞자리>/<축2 등급>`, and a base
  # branch may itself contain `/`. So the fragment is taken by dropping the LAST
  # component and then taking the last of what remains — cutting at the second
  # `/` would read `feat` out of `feat/x` and compare a branch name against a
  # sha for the rest of the run.
  local t rest
  t=$(gate_approval_field "$1" '구속 튜플')
  # `-` (a question) and `B1` (a boundary) are tuples with no tree in them.
  case "$t" in */*/*/*) : ;; *) return 0 ;; esac
  rest=${t%/*}
  printf '%s' "${rest##*/}"
}

gate_act_approval_fresh() {
  # gate_act_approval_fresh <승인 id> <별칭> [<세그먼트>] — 0 when the tree this
  # approval was answered against is still the tree in front of us.
  #
  # THE BINDING TUPLE FINALLY HAS A READER. It was written at issue time and read
  # by nothing anywhere in the tree, so the property stated beside it — an act
  # approval's answer is valid only against the tree it named, which is the whole
  # reason it carries shas and a question does not — was a sentence rather than a
  # check. An answer given at 22:00 opened the same argv at 04:00 across every
  # commit that had landed in between.
  #
  # It compares the head fragment ALONE. The alias is the lookup key, the base
  # branch is not what the act is about, and the axis-2 grade is re-derived on
  # every entry anyway. The comparison takes the CURRENT head's first bytes to
  # the stored fragment's length, because the fragment is stored clipped.
  #
  # UNMEASURABLE READS AS FRESH, deliberately. This exists to catch a tree that
  # MOVED; a tuple with no head in it, or a worktree whose HEAD cannot be read
  # now, is not a moved tree, and re-opening an approval over it would ask a
  # person a question the second asking cannot answer any better.
  #
  # THE TREE IT NAMED IS THE ONE THE ACT RUNS IN, resolved through
  # gate_act_worktree — the same call the issuer freezes through, so the two
  # sides cannot drift apart.
  # AN UNRESOLVED TREE FALLS TO THE UNMEASURABLE ARM, it does not `cd` into
  # nothing. `cd ""` SUCCEEDS and leaves the shell where it was, so an empty
  # resolution used to read the GATE'S OWN head and compare a stranger's sha
  # against this approval's fragment — a silently wrong answer in both
  # directions. An empty result is strictly better: it says so and is taken as
  # fresh, which is what the paragraph above already prescribes.
  local frag cur wt
  frag=$(gate_act_tuple_head "$1")
  [ -n "$frag" ] || return 0
  wt=$(gate_act_worktree "$2" "${3:-}")
  if [ -n "$wt" ]; then
    cur=$(cd "$wt" 2>/dev/null && git rev-parse HEAD 2>/dev/null || true)
  else
    cur=''
  fi
  [ -n "$cur" ] || {
    warn "could not read a HEAD to check the binding tuple of approval $1 against — this is not a tree that moved, so it is taken as fresh"
    return 0
  }
  [ "$frag" = "${cur:0:${#frag}}" ]
}

gate_issue_act_approval() {
  # gate_issue_act_approval <alias> <segment> <cutpoint> <grade> <argv>
  #
  # An ACT approval, as against the boundary variant: the binding tuple is
  # act-shaped, so staleness is re-derived against the tree it named. The id is
  # derived from the act rather than random, so the same blocked act asked twice
  # produces one pending approval instead of a queue of duplicates.
  local alias="$1" seg="$2" cut="$3" grade="$4" argv="$5" id ad base head st wt
  ad=$(printf '%s' "$argv" | shasum -a 256 | cut -d' ' -f1)
  # Resolved ONCE and used by both the id and the head below, so the two cannot
  # answer about different trees.
  wt=$(gate_act_worktree "$alias" "$seg")
  id=$(gate_act_approval_id "$alias" "$argv" "$wt")
  # PRESENCE WAS THE WRONG GUARD ONCE THE TUPLE GOT A READER. The id is derived
  # from the alias and the argv and holds no sha, so an approval that has gone
  # stale keeps its id — and a presence check then refused to issue the very
  # re-approval the staleness finding asks for, leaving the act exiting 5 with
  # nothing pending for anyone to answer. What each state does:
  #   대기  one open approval per act, which is the original property
  #   승인  reached only when the caller found the tuple stale, so SUPERSEDE it
  #         by appending a fresh `대기` row under the same id — the id names the
  #         act and the row sequence tells the morning what happened to it
  #   그 외 `거부`/`무효` are terminal and the caller exits before arriving here
  st=$(gate_approval_state "$id")
  case "$st" in
    대기) return 0 ;;
    ''|승인) : ;;
    *) return 0 ;;
  esac
  base=$(target_field "$alias" '베이스 브랜치')
  # An unresolved tree leaves the head EMPTY rather than `cd ""`-ing into the
  # gate's own directory and freezing a stranger's sha into the binding tuple.
  # `gate_act_approval_fresh` already treats a tuple with no head as fresh.
  if [ -n "$wt" ]; then
    head=$(cd "$wt" 2>/dev/null && git rev-parse HEAD 2>/dev/null || true)
  else
    head=''
  fi
  # THE QUESTION IS A FIXED LITERAL AND THE BLOCK IS STILL WRITTEN: the anchor on
  # the row has to name something, and the close path fills the answer region
  # of this block the same way it does a judgment's.
  #
  # THE FIFTH RECORDING SITE sits on the row below. `$cut` is already the
  # EFFECTIVE rung — the caller resolved it before the rule loop — so the
  # derived value is read from the exported global rather than threaded through
  # a sixth parameter. A question a person answers in the morning has to say
  # which rung it is about, and the rung the run acted on is the effective one.
  local q='사전 인가 밖 행위를 수행할까요'
  gate_approval_sidecar_write "$id" issue '질문' "$q" \
    || warn "could not write the question into the approval sidecar — the row is issued, but there is no block where the anchor $(gate_approval_sidecar_anchor "$id") points"
  gate_append '승인' "승인 id=$id" "상태=대기" "대상=$alias" "절단점=$cut" \
    "유도 절단점=${GATE_ACT_DERIVED:--}" \
    "행위 다이제스트=$ad" "구속 튜플=$alias/$base/${head:0:12}/$grade" \
    "막는 세그먼트=$seg" "질문 문면=$q" \
    "답변 문면=-" "사이드카 앵커=$(gate_approval_sidecar_anchor "$id")" \
    "발행 시각=$(now_iso)" "해소 시각=-"
  # Raised the moment the row is seated. The row's own idempotence guard is the
  # early return above, so the notice inherits it exactly — same key, same
  # condition — and an act blocked twice produces one pending approval and one
  # banner rather than a queue of either.
  gate_notify_approval "$id" "$q — $alias / $cut / $grade"
  warn "approval wait issued $id — $alias / $cut / $grade"
  gate_warn_canon_prompt "$id" "$q"
}

gate_names_next_obligation() {
  # gate_names_next_obligation <rationale>
  #
  # Admissible: an open obligation's identity, a segment in a non-terminal
  # state, or a termination clause marked unmet. Prose does not count — the
  # named thing has to be findable in the ledger, which is what makes the
  # refusal checkable rather than a matter of tone.
  local why="$1" o sid st
  [ -n "$why" ] || return 1
  # A `while read` inside a pipeline runs in a subshell, so it cannot return
  # from this function — the loop below is a plain `for` over a substitution for
  # exactly that reason.
  for o in $(gate_open_obligations | sed 's/^obligation=//'); do
    case "$why" in *"$o"*) return 0 ;; esac
  done
  for sid in $(gate_segment_ids); do
    [ -n "$sid" ] || continue
    st=$(gate_segment_field "$sid" '상태')
    # Nameable exactly when condition 1 counts it, a pending apply included.
    if ! gate_segment_apply_pending "$sid"; then
      case " $TERMINAL_SEGMENT_STATES " in *" $st "*) continue ;; esac
    fi
    case "$why" in *"$sid"*) return 0 ;; esac
  done
  # A termination clause, named by its id and actually marked unmet. The arm
  # here used to accept any rationale CONTAINING the word `미충족` — no clause
  # id, no check that anything was unmet — which is the prose path the comment
  # above denies, sitting on the function's own last line. It meant the only
  # thing standing between a run and an early "satisfied" ending was whether the
  # router happened to use one Korean word.
  for o in $(gate_unmet_clause_ids); do
    case "$why" in *"$o"*) return 0 ;; esac
  done
  return 1
}

gate_clause_ids() {
  # The termination point, decomposed at kickoff into checkable rows. The gate
  # never read these at all — `종료 절` appears zero times in it — so the nine
  # conditions measured the ledger's shape and never the thing the user actually
  # authorized the run against.
  manifest_clause_rows_raw | gate_row_ids
}

gate_clause_evidence_ids() {
  # gate_clause_evidence_ids <근거> — every `J-<8자리 16진>` the rationale names,
  # one per line, deduplicated.
  #
  # ONE EXTRACTION FOR THE CHECK AND FOR THE REPORT, which is the whole reason
  # this exists as a function. The write-time floor looped over pending approvals
  # and kept the LAST match, while the `done` file's reporter ran a different
  # expression that took the FIRST — so the set the gate refused duplicates over
  # and the set the morning was told about were two different values read out of
  # one field, and neither of them was the whole set.
  #
  # It reads the TEXT rather than intersecting with the pending list, because the
  # reporter must still name an approval that has since been answered. Requiring
  # the ids to be open is a separate question, asked by the write-time floor
  # alone.
  { printf '%s' "${1:-}" | tr -c '0-9A-Za-z-' '\n' \
      | grep -E '^J-[0-9a-f]{8}$' || true; } | sort -u
}

gate_judgment_approval_open() {
  # gate_judgment_approval_open <승인 id> — 0 when that id is an OPEN
  # `절단점=판단` approval, which is what `보류` evidence has to be.
  case " $(gate_pending_approval_ids 판단 | tr '\n' ' ') " in
    *" $1 "*) return 0 ;;
  esac
  return 1
}

gate_approval_keyed_on_design_step() {
  # gate_approval_keyed_on_design_step <승인 id> — 0 when that approval is a
  # question about the run-scope design step: its issuing row's `막는 세그먼트`
  # is the plan's single design step id, and that id is not also a segment.
  #
  # The key is what the approval is ABOUT, not who wrote it, because that is
  # the one fact the gate can check: the emission absorber passes the stage key
  # through to the issuing row, and a design step never has a `segment` row.
  # The FIRST row is read because it is the issuing one; a transition row need
  # not carry the field.
  local dstep first
  dstep=$(gate_run_scope_step design) || return 1
  [ -z "$(gate_segment_field "$dstep" '상태')" ] || return 1
  first=$( { gate_rows '승인' | grep -F "승인 id=$1 " || true; } | sed -n '1p')
  [ -n "$first" ] || return 1
  [ "$(gate_row_field "$first" '막는 세그먼트')" = "$dstep" ]
}

gate_design_step_has_open_approval() {
  # 0 when some PENDING approval is a question about the run-scope design step.
  #
  # This is what separates the two ways a design stage exits 0 with nothing at
  # the document path. One reached a point it could not decide for the person,
  # emitted a judgment, and the absorber opened an approval keyed on the step —
  # that stage did its job and the run is waiting on a person, so dispatching it
  # again would ask the same question and bill for it a second time. The other
  # simply stopped producing: a team member ended its turn without a witness, a
  # save never happened before the turn boundary, a wait ceiling cut the
  # discussion. Nothing is waiting on a person there, and the work is lost
  # unless the step is dispatched again.
  #
  # Both are written `공허한 성공`, so the class cannot tell them apart and the
  # open approval is the fact that can.
  local id
  for id in $(gate_pending_approval_ids); do
    gate_approval_keyed_on_design_step "$id" && return 0
  done
  return 1
}

gate_design_fresh_attempts() {
  # stdin: the design step's `stage-result` rows in ledger order. Prints how
  # many of them are fresh attempts rather than re-attachments.
  #
  # THE ROUTERS' DEFINITION, WORD FOR WORD: a row is a re-attachment when its
  # `세션 id` is not `미상` and stands on an earlier row of the step, and every
  # other row is a fresh attempt. The routers stop the design on this count and
  # condition 1 closes its window on it; two definitions would let one side
  # stop on a state the other still reads as retryable.
  local row sid seen=' ' n=0
  while IFS= read -r row; do
    [ -n "$row" ] || continue
    sid=$(gate_row_field "$row" '세션 id')
    case "$sid" in
      '' | '미상') n=$((n + 1)) ;;
      *) case "$seen" in
           *" $sid "*) ;;
           *) n=$((n + 1)); seen="$seen$sid " ;;
         esac ;;
    esac
  done
  printf '%s' "$n"
}

gate_design_row_has_limit_envelope() {
  # gate_design_row_has_limit_envelope <step id> <row> — 0 when that attempt's
  # stream carries the usage-limit envelope. The same file and the same string
  # the routers read before re-attaching, so a limit crash is told apart the
  # same way on both sides. No attempt number, no run directory or no stream
  # reads as no envelope: that is the side where the depth applies, and the
  # depth is what lets a stalled run close.
  local ver
  ver=$(gate_row_field "$2" '실행 버전')
  [ -n "$ver" ] && [ -n "${RUN_DIR:-}" ] || return 1
  grep -qF '"api_error_status":429' "$RUN_DIR/log/$1#$ver.json" 2>/dev/null
}

gate_clause_settled() {
  # A clause is settled when a `종료 절` row in the LEDGER names it — written by
  # the router through `act --kind clause` with its evidence, or marked
  # impossible. The manifest holds the question; the ledger holds the answer.
  # The value is CAPTURED, not piped into `grep -q`: an early-exiting reader on
  # the right of a pipe kills the writer with SIGPIPE, and under `pipefail` the
  # whole pipeline then reports failure even though the match was found. This
  # file's own scanner catches that shape, and it caught this one.
  #
  # `보류` COUNTS AS SETTLED HERE, DELIBERATELY, and the reason is worth stating
  # because the opposite reading is the obvious one. A condition exists to
  # REFUSE a proposal, and an open question must not refuse one — that refusal
  # is the defect this slice removes, and it is why no condition was created
  # for an open question. What keeps `보류` from being a free pass is not this function: it is
  # the write-time floor (the evidence must be an OPEN `절단점=판단` approval,
  # and no two clauses may lean on the same one) plus the `done` file recording
  # every held clause with the question holding it. The state's disposition is
  # visible; it is not silent the way `충족` would be.
  #
  # AND `보류` KEEPS COUNTING ONCE THE ANSWER ARRIVES. The opposite reading was
  # here first — the clause went back to unsettled the moment its question closed
  # — and it made a run a person ANSWERED leave less behind than one nobody
  # touched: the answer flipped condition 10 back to unmet, the done proposal was
  # refused, and the terminal line that carries the run's residual was never
  # written at all. The contract hands an answered hold to the SUCCESSOR run
  # rather than re-opening this one, so re-settling the clause as `충족` or
  # `불가능` is that run's work, with the answer in hand. What travels across the
  # boundary is the `done` file, which names the clause, every approval holding
  # it, and the state each of those approvals is now in.
  local last ids
  last=$( { gate_rows '종료 절' | grep -F "id=$1 " || true; } | tail -1)
  [ -n "$last" ] || return 1
  if [ "$(gate_row_field "$last" '상태')" = "보류" ]; then
    ids=$(gate_clause_evidence_ids "$(gate_row_field "$last" '근거')")
    # No id at all is not "nothing to check" — the write-time floor refuses such
    # a row, so one here means the field was lost, and unsettled is the safe read.
    [ -n "$ids" ] || return 1
  fi
  return 0
}

gate_held_clause_ids() {
  # Clauses whose LAST row is `보류`, with the approvals each is waiting on.
  # These settle condition 10 and are therefore invisible to `gate_done_conditions`
  # — which is exactly why the `done` file has to name them, or a run that
  # settled nothing and a run that settled everything write the same ending.
  #
  # ALL of them, from the same extraction the write-time floor uses. A clause may
  # legitimately name more than one approval, and reporting the first while the
  # floor checked the last meant the morning could read an id the gate had never
  # measured anything about.
  #
  # EACH ID CARRIES ITS APPROVAL'S CURRENT STATE. A hold whose answer has already
  # arrived and a hold still waiting are otherwise the same string, and those are
  # the two things the morning most needs to tell apart — the first is work the
  # successor run can finish, the second is a question still owed to a person.
  # The clause stays settled either way, so this line is the only place where the
  # arrival of an answer becomes visible.
  local cid last jid jst jids
  for cid in $(gate_clause_ids); do
    [ -n "$cid" ] || continue
    last=$( { gate_rows '종료 절' | grep -F "id=$cid " || true; } | tail -1)
    [ -n "$last" ] || continue
    [ "$(gate_row_field "$last" '상태')" = "보류" ] || continue
    jids=""
    for jid in $(gate_clause_evidence_ids "$(gate_row_field "$last" '근거')"); do
      [ -n "$jid" ] || continue
      jst=$(gate_approval_state "$jid")
      jids="$jids $jid:${jst:-미상}"
    done
    jids=${jids# }
    printf '%s(%s)\n' "$cid" "${jids:-승인 미상}"
  done
}

gate_unmet_clause_ids() {
  local cid
  for cid in $(gate_clause_ids); do
    [ -n "$cid" ] || continue
    gate_clause_settled "$cid" || printf '%s\n' "$cid"
  done
}

gate_impossible_clause_ids() {
  # Clauses whose LAST row is `불가능`. They settle condition 10 like any other
  # settled clause, and that was the whole of what the gate did with them — so a
  # run that settled every clause as unreachable read `충족` and wrote the same
  # terminal line as a run that reached every one. Condition 10 now prints one
  # anchored line per id from here and the disposition reads that line as an
  # invalidation, which is what the kickoff contract already promised.
  local cid last
  for cid in $(gate_clause_ids); do
    [ -n "$cid" ] || continue
    last=$( { gate_rows '종료 절' | grep -F "id=$cid " || true; } | tail -1)
    [ -n "$last" ] || continue
    [ "$(gate_row_field "$last" '상태')" = "불가능" ] && printf '%s\n' "$cid"
  done
  return 0
}

# gate_check_merge_anchor <segment> <cutpoint> <alias> [<kind>]
#
# A merge that cannot say WHAT IT MERGES is refused before it happens. The
# obligation this act is about to issue carries the tip of the segment worktree
# as its anchor, and the fulfilling review is matched against that commit — so
# an obligation issued without one is a row nobody can ever close, and
# termination condition 9 then holds the run open on it forever. Refusing at the
# issuing point costs one merge; writing the unanchorable row costs the run.
#
# THE FIVE FAILURES GET FIVE DIFFERENT SENTENCES, and none of the five uses
# the word 「룰」. That is a load-bearing prohibition rather than a matter of
# style: a refusal phrased as a rule refusal is folded into the rule catalog by
# the next reader, and every entry of that catalog is switchable — so the fold
# would quietly bring this refusal inside the range of `끔`, which is precisely
# what its own exit code exists to deny. The fourth and fifth sentences inherit
# that prohibition unchanged.
#
# THE FOURTH ASKS WHO OWNS THE WORKTREE. The other three settle for a row, a
# directory and a readable HEAD, and a perfectly good worktree of ANOTHER
# REPOSITORY clears all three — absolute, present, holding commits. Its tip then
# went out as the anchor and keyed the review obligation, while the push itself
# ran in this target's own tree: the obligation's commit and the pushed commit
# sat in different ref spaces, so the containment check at fulfilment time could
# never hold and the unclosable row held the run open. Asking
# `gate_segment_worktree_of_target` here is what puts this check, the widening
# and the resolution on ONE predicate instead of three different questions.
#
# THE FIFTH ASKS WHETHER THE TIP IS ALREADY ON THE BASE BRANCH, because the
# fourth cannot ask it. Ownership is `--git-common-dir` equality and nothing
# else, and kickoff pins the target row's value to the one read in THAT TARGET'S
# OWN MAIN WORKTREE — so a segment row naming that target's main or exec worktree
# makes the two values equal by construction and the fourth answers yes. The tip
# resolved under that yes is the base branch tip, the landing test at fulfilment
# time (`git merge-base --is-ancestor <머지 커밋> refs/heads/<베이스>`) then holds
# unconditionally, and the covering axis degenerates to "is the review HEAD a
# descendant of the base tip" — which a `cycle` row about an unrelated segment
# satisfies. The other-repository case failed loudly with a row nobody could
# close; this one closes as if it had been reviewed, and no warning goes out on
# the way.
#
# IT COMPARES AGAINST THE REF THE FULFILMENT ARM FINALLY DECIDES ON, NOT THE ONE IT
# LOOKS AT FIRST: `refs/remotes/origin/<베이스>` when the anchor repository has an
# origin, `refs/heads/<베이스>` only when it has none. The local branch is not
# asked on a target with an origin, because in this pipeline merges happen on
# the server and every segment tree is cut from the tracking ref, so the local
# branch never advances during a run. Asked alone, it let the tip of a SIBLING
# segment that had already merged to the remote base pass — its obligation was
# issued on the sibling's tip and closed at once on the sibling's review — and
# it refused a tip that was only on the local branch and not yet on the remote,
# which is new work rather than a hollow anchor. It is NOT byte-for-byte the
# fulfilment arm's comparison: that arm fetches first, and this one does not.
# A stale tracking ref can only be BEHIND the remote, so it errs toward letting
# the merge through and never adds a refusal the fetched answer would not give.
#
# It FAILS OPEN. An anchor root, a base branch, or a compared ref (the tracking
# ref, or the local branch on a target with no origin) that does not resolve
# leaves the merge alone: the sentence fires on a positive observation that the
# anchor is hollow, and folding "could not look" into "looked and found" would
# break a freshly cloned repository that never had the ref. A target with an
# origin but no tracking ref does NOT fall back to the local branch — that
# branch is frozen at kickoff here, so it is no stand-in for the remote. It also
# skips an undeclared target, for the reason the fourth gives.
#
# AND IT EXEMPTS A TIP THAT ALREADY HAS AN OPEN OBLIGATION ON THIS SEGMENT. What
# it refuses is ISSUING an obligation nothing can distinguish; a second merge at
# a tip whose slot is already open issues nothing — the duplicate guard in
# `gate_issue_review_obligation` returns without a row — so the harm is absent
# and the refusal would only take out the idempotence the duplicate guard exists
# to provide.
#
# NONE OF THE FIVE IS ASKED OF A BOOKKEEPING ACT, AND THE ISSUER IS NOT EITHER.
# A bookkeeping kind appends a row and performs nothing, so it merges nothing;
# it arrives in this window only because the router labels every act with the
# target's cutpoint, so on a `머지` target a `segment`, `cycle` or park row is
# spelled `--cutpoint 머지`. Every sentence here reads the segment row AS IT
# STANDS, and that reading is wrong for every bookkeeping act at once: for a
# `segment` act the payload is the row that will replace the one read, so the
# fourth refused the repair it had itself prescribed; and once a segment's
# obligation is fulfilled its tip is on the base branch with no open slot, so
# the fifth refused the closing `segment` row, the park row the router is told
# to write after a repeated 10, and the `cycle` row of a single-tree run whose
# sibling had moved the shared tip. Exit 10's only prescribed repair is a row
# write, so the router had no way out and the run could not end.
#
# EXEMPTING THIS CHECK ALONE IS THE WRONG HALF. The issuer keys an obligation
# on (run, segment, tip) and its duplicate guard walks the UNFULFILLED ids only,
# so a bookkeeping act at `머지` on a segment whose slot was already fulfilled
# would append a second `미이행` row under the same id — reopening termination
# condition 9 on a merge that never happened. That reopening was silent before
# the fifth sentence existed, and the fifth turned it into a loud 10: the
# refusal was the symptom of the issuer's reach, not a defect of its own. So
# both sites test `gate_kind_is_bookkeeping` and return before reading a row.
# A merge act itself — `--kind merge`, or `exec` at the `머지` rung — still
# passes through both, so the other-repository anchoring the fourth sentence
# exists to refuse is not let back in.
#
# THE OWNERSHIP QUESTION IS NOT DROPPED for a `segment` act, it moves to the
# row being written: the row writer refuses a non-terminal row whose worktree
# lies outside every declared target's repository, before anything is written.
#
# THE PREDICATE ITSELF IS NOT NARROWED to "and not the target's own main or exec
# worktree". In a run that uses no linked worktree a segment row naming the main
# worktree is the normal state and its tip is real work, so that narrowing
# refuses every single-tree run. The hollowness is a property of the TIP, which
# is why it is asked about the tip.
#
# WHERE THE SECOND AND THIRD SENTENCES ACTUALLY STAND TODAY. The dispatch-time
# worktree pre-check (`이 행위가 어디서 도는지 말할 수 없어`) runs above this
# function and covers `--kind merge` too, so it answers first for every worktree
# value it inspects. The second sentence's live domain is therefore the two
# spellings that pre-check's `case` skips — `-` and `(없음)` — and 35-13c is the
# clause that measures exactly that. The third (an unreadable HEAD) is reached
# only by a worktree whose branch is unborn: `gate_segment_tip` asks for the
# commit with `--verify`, so such a HEAD resolves to nothing and this sentence
# answers. Before that it asked without `--verify`, and the literal word `HEAD`
# leaked out as the tip. The reach is rare because `wt_create` never builds an
# unborn tree, and the sentence is kept for the tree something else built.
gate_check_merge_anchor() {
  local seg="$1" cut="$2" alias="$3" kind="${4:-}" wt tip aroot abr bref oid open_id slot_open
  [ "${GATE_REVIEW_POLICY:-}" = "선머지후리뷰" ] || return 0
  [ "$cut" = "머지" ] || return 0
  # A bookkeeping act merges nothing — see the head comment. The `unset` drops
  # any anchor the environment carried in, so a value a parent gate exported
  # cannot outlive the act that resolved it.
  if gate_kind_is_bookkeeping "$kind"; then
    unset GATE_MERGE_ANCHOR
    return 0
  fi

  # `상태` is required on every segment row, so its absence is the absence of the
  # row rather than of one field.
  if [ -z "$seg" ] || [ "$seg" = "-" ] || [ -z "$(gate_segment_field "$seg" '상태')" ]; then
    warn "there is no segment row in the ledger to name the commit that would be merged: '${seg:--}'"
    warn "record the segment row first, then call again with the same argv"
    return "$GATE_EXIT_ANCHOR"
  fi
  wt=$(gate_segment_worktree "$seg")
  if [ -z "$wt" ] || [ ! -d "$wt" ]; then
    warn "the worktree directory of segment '$seg' does not exist: '${wt:--}'"
    warn "the commit that would be merged cannot be read there, so this merge is not issued"
    return "$GATE_EXIT_ANCHOR"
  fi
  # NOT ON AN UNDECLARED TARGET, AND THE GUARD IS THE ONE THE RESOLUTION CARRIES.
  # An undeclared alias has no target row, so its `공통 git 디렉터리` is empty and
  # the predicate fails for every segment row however correct that row is. Without
  # this conjunct every merge on an undeclared target would be told to repair a row
  # that is already right — a refusal with no repair behind it, which is the same
  # shape the resolution and the worktree predicate already had to take out.
  if [ "${GATE_UNDECLARED:-0}" != "1" ] \
     && ! gate_segment_worktree_of_target "$seg" "$alias" >/dev/null; then
    warn "세그먼트 '$seg' 의 워크트리 '$wt' 는 대상 '$alias' 의 워크트리가 아닙니다"
    warn "그 자리의 HEAD 는 이 머지가 미는 커밋과 다른 ref 공간에 있어 리뷰 의무의 앵커가 될 수 없습니다 — 세그먼트 행의 워크트리를 고쳐 같은 argv 로 다시 부르세요"
    return "$GATE_EXIT_ANCHOR"
  fi
  tip=$(gate_segment_tip "$seg") || tip=""
  if [ -z "$tip" ]; then
    warn "could not resolve HEAD in the worktree '$wt' of segment '$seg'"
    warn "the commit that would be merged cannot be written down, so this merge is not issued"
    return "$GATE_EXIT_ANCHOR"
  fi
  # The fifth sentence. See the head comment for why it is asked about the tip
  # and not about the worktree, and for each of the three conjuncts that keep it
  # from firing where the harm it names is absent.
  if [ "${GATE_UNDECLARED:-0}" != "1" ]; then
    aroot=$(alias_root "$alias" 2>/dev/null) || aroot=""
    abr=$(base_branch "$alias" 2>/dev/null) || abr=""
    # The ref the fulfilment arm finally decides on: the tracking ref when the
    # anchor repository has an origin, the local branch only when it has none.
    # No fetch — see the head comment for why a stale tracking ref is harmless.
    bref=""
    if [ -n "$aroot" ] && [ -d "$aroot" ] && [ -n "$abr" ]; then
      if ( cd "$aroot" && git remote get-url origin >/dev/null 2>&1 ); then
        bref="refs/remotes/origin/$abr"
      else
        bref="refs/heads/$abr"
      fi
    fi
    if [ -n "$bref" ] \
       && ( cd "$aroot" && git rev-parse --verify --quiet "$bref" >/dev/null 2>&1 ) \
       && ( cd "$aroot" && git merge-base --is-ancestor "$tip" "$bref" >/dev/null 2>&1 ); then
      # Keyed exactly as the issuer keys it, so "this tip's slot" means the same
      # thing in both places. Re-deriving it rather than sharing a helper would
      # let the two drift into agreeing about different slots.
      slot_open=""
      oid="RO-$(printf '%s|%s|%s' "$RUN_ID" "$seg" "$tip" | shasum -a 256 | cut -c1-8)"
      for open_id in $(gate_unfulfilled_review_obligations "$seg"); do
        if [ "$open_id" = "$oid" ]; then slot_open=1; break; fi
      done
      if [ -z "$slot_open" ]; then
        warn "세그먼트 '$seg' 의 팁 '$tip' 은 이미 대상 '$alias' 의 베이스 브랜치 '$abr' 에 담겨 있습니다 ($bref)"
        warn "이 의무는 어떤 리뷰로도 구별되지 않습니다 — 세그먼트 행의 워크트리를 고쳐 같은 argv 로 다시 부르세요"
        return "$GATE_EXIT_ANCHOR"
      fi
    fi
  fi
  # Resolved once and reused by the issuer below, so the value on the row is the
  # same one this check passed on. Re-reading it there would open a window in
  # which the refusal and the row disagree about the same worktree.
  GATE_MERGE_ANCHOR="$tip"
  export GATE_MERGE_ANCHOR
  return 0
}

gate_check_merge_checks() {
  # gate_check_merge_checks <segment> <cutpoint> — refuse a merge whose
  # PR has a recorded CI failure. THE SIBLING, and the sibling-ness is
  # load-bearing.
  #
  # WHY IT IS NOT FOLDED INTO `gate_check_merge_anchor`. That check returns at
  # once unless the review policy is `선머지후리뷰`, and every slice this design
  # ships is `선리뷰후머지` — folded in, this would be dead code in 5 of 5. It
  # would reproduce, one layer down, the very defect this design named elsewhere:
  # a reader that does not exist. For the same reason it is not a rule in the
  # catalogue either — every entry there can be switched off by configuration.
  #
  # THE POLARITY IS REFUSAL, NOT SKIPPING, AND SILENCE IS THE DEFAULT. There is
  # no wait here to skip and there must not be one: a gate holding the router's
  # turn has no path back to wakefulness either. So a run with no poller behaves
  # exactly as it does today, and that co-existence costs nothing.
  #
  # NO `gh` CALL IS MADE HERE. The head being compared is the worktree's local
  # `git rev-parse`, so a force-push — which opens a new CI lifecycle — makes the
  # recorded row mismatch and this check says nothing about it.
  #
  # A STALE `통과` ROW CANNOT CAUSE A BAD MERGE: all it can do is fail to refuse,
  # which is the behaviour of a run with no poller at all. The only stale value
  # that could matter is `실패`, and the poller writes a new row on the
  # `실패 → 통과` transition while this reads the newest row of the round. After
  # a rerun the polarity turns: the round's own `통과` is required, not merely
  # the absence of a failure.
  local seg="$1" cut="$2" row tip st req
  [ "$cut" = "머지" ] || return 0
  [ -n "$seg" ] && [ "$seg" != "-" ] || return 0
  # WHAT IS REFUSED IS WHAT MERGES, and the `머지` label does not say that. The
  # router labels every act with the target's cutpoint, so on a `머지` target the
  # stage launch that would fix the red check, the routing shift, the proposal to
  # stop, a `gh pr checks` read and every bookkeeping row all arrive here spelled
  # `--cutpoint 머지`. Refusing them parked the one stage able to push the new
  # head the refusal below asks for, so a segment whose CI went red once could
  # never recover on its own.
  #
  # THE NARROWING IS `리뷰-후-머지`'s, ON THE SAME TWO argv-DERIVED VALUES. A
  # read changes nothing, and a worktree write that integrates no history merges
  # nothing — the kind-pinned stage launch and routing shift land there, and the
  # bookkeeping kinds grade `읽기`. What stays refused is every surface that
  # leaves the worktree (`git push`, `gh pr merge`) and a worktree write that
  # does integrate history, which covers an opaque runner and a command with no
  # row as well, because both are answered 1.
  #
  # IT IS NOT A LIST OF KIND NAMES. `--kind` carries any word and `exec` takes
  # none, so a name-based exemption would let `act --kind skill`'s spelling vouch
  # for whatever argv came with it; the surface is what the gate proved.
  #
  # THE EXEMPTION IS "IS 0", NOT "IS NOT 1": a path that reaches here without the
  # value set is then refused rather than waved through.
  [ "${GATE_SURFACE:-}" = "읽기" ] && return 0
  if [ "${GATE_SURFACE:-}" = "워크트리쓰기" ] && [ "${GATE_HISTORY_INTEGRATION:-}" = "0" ]; then
    return 0
  fi

  tip=$(gate_segment_tip "$seg") || tip=""
  [ -n "$tip" ] || return 0
  # THE ROW IS THE ONE THE CI LAYER READS. The round of (segment, tip) comes from
  # `cc_ci_round`, and the verdict is the newest `checks` row of that segment
  # and head whose `재실행 회차` is the round, so a row of another head written
  # later does not hide this head's verdict, and a failure of a round a rerun
  # already superseded is not read as the current one. Taking the last row of
  # the segment whatever its head returned silently whenever another head's row
  # came last.
  local rd a g why ad
  rd=$(cc_ci_round "$LEDGER" "$seg" "$tip")
  a=$(cc_ci_round_get "$rd" a); g=$(cc_ci_round_get "$rd" g); ad=$(cc_ci_round_get "$rd" ad)
  row=$(gate_ci_verdict_row "$seg" "$tip" "${g:-0}")
  st=$(gate_row_field "$row" '상태')
  req=$(gate_row_field "$row" '필수 집합')
  if [ "$a" = "열림" ]; then
    # A rerun or a label was requested and never closed: what GitHub is running
    # is unknown.
    if [ "$ad" = "라벨" ]; then
      why="a label of this head ($tip) was requested and has no closing row"
    else
      why="a rerun of this head ($tip) was requested and has no closing row"
    fi
  elif gate_ci_repair_pass "$seg" "$tip" "${g:-0}"; then
    # A REPAIR RUN'S HEAD MERGES ON ITS MATCH, NOT ON A GREEN CHECK. Its base
    # is broken, so its own CI fails with the base's failures, and what says it
    # is fit to land is that it adds none and leaves none of the event it
    # repairs. Unlike the stale `통과` above, a stale `수리 통과` is not harmless
    # — it lets a failing head through — so it counts only against the
    # reading it was made against, and only while that reading is fresh.
    return 0
  elif [ "${g:-0}" -ge 1 ]; then
    # AFTER A RERUN ONLY A PASS OF THAT ROUND MERGES. The round's first verdict
    # comes after the rerun began, so anything short of `통과` — no row yet, a
    # pending or unreadable answer, a second failure — is not a green check.
    [ "$st" = "통과" ] && return 0
    why="round $g of this head ($tip) has not passed — 상태 '${st:-(관측 없음)}'"
  elif gate_ci_join_target "$seg" && [ -n "$(gate_segment_last_cycle_row "$seg")" ]; then
    # ON A REVIEWED CI JOIN TARGET ONLY A VERDICT MERGES. Round 0's `통과`, or
    # its `미등록` past the grace — "this head has no CI" — and nothing else: no
    # row yet, a pending or unreadable answer, a failure with or without a
    # required set, and a wait past its cap are refused, and `다음` names the wait
    # or the way back. A review that ended before CI used to merge a head whose
    # verdict had not come.
    if [ "$st" = "통과" ] || cc_ci_unregistered_expired "$st" 0 "$(gate_row_field "$row" '관측')"; then
      return 0
    fi
    why="round 0 of this head ($tip) has no passing verdict — 상태 '${st:-(관측 없음)}'"
  else
    # OFF A CI JOIN TARGET NOTHING RECORDED IS NOT A VERDICT. The gate has nothing
    # to say, so it says nothing — that is what makes the poller optional rather
    # than a new dependency there.
    [ -n "$row" ] || return 0
    case "$st" in 실패) : ;; *) return 0 ;; esac
    # A BROKEN QUESTION IS NOT READ AS AN ANSWER — that is the whole reason
    # `판정 불가` exists as a value of its own on both fields.
    [ "$req" = "판정 불가" ] && return 0
    why="CI failed at this very head ($tip) — 필수 집합 '$req', 실패 체크 '$(gate_row_field "$row" '실패 체크')'"
  fi

  # A ROUTED RUN HAS A WAY ON, SO THE REFUSAL POINTS AT IT. `다음` reads the
  # same round and sends the segment to the rerun act, to the wait, or back to
  # the implement stage; a park cell here would stop on a person a segment the
  # router can move. A run with no routing record, and the fixed-graph driver,
  # have no branch for those values and keep today's park.
  if run_routed; then
    warn "the merge of segment '$seg' is refused: $why"
    warn "다음=$(gate_segment_review_next "$seg") — read review_next[] in the snapshot and take that disposition instead of merging"
    exit "$GATE_EXIT_RULE"
  fi
  warn "CI on the PR of segment '$seg': $why"
  warn "an unattended run parks on a failing check whether or not it is required; fix the failing check and push a new head, and the poller opens a new lifecycle for it"
  # NO NEW EXIT CODE. The refusal leaves through the park dispatch immediately
  # below, so it becomes an act-scope `blocked` row like every other reach park
  # and `plan` forecasts it with the same code.
  [ -n "${GATE_PARK_CELL:-}" ] || GATE_PARK_CELL="CI실패"
  export GATE_PARK_CELL
  return 0
}

gate_ci_repair_pass() {
  # gate_ci_repair_pass <segment> <head sha> <round> — the head's newest match
  # row of that round reads `수리 통과`, its `판독 지문` is the mark of the
  # target's last `master 판독` row, and that reading is fresh and settled
  # red or green. A reading still `진행 중` or `판정 불가` passes no merge,
  # whatever its mark.
  local seg=$1 h=$2 g=$3 al m last
  run_routed || return 1
  al=$(gate_segment_target_alias "$seg")
  [ -n "$al" ] || return 1
  m=$(gate_ci_match_row "$seg" "$h" "$g")
  [ "$(gate_row_field "$m" '결과')" = '수리 통과' ] || return 1
  gate_master_fresh "$al" || return 1
  last=$(gate_master_last_row "$al")
  case "$(gate_row_field "$last" '상태')" in 빨강|초록) ;; *) return 1 ;; esac
  [ "$(gate_row_field "$m" '판독 지문')" = "$(gate_ci_match_reading_mark "$last")" ]
}

gate_check_grade_regression() {
  # gate_check_grade_regression <segment> <cutpoint> <alias> [argv…] — refuse a merge
  # whose landing tree's gate grades an argv the base's gate knew as empty or
  # `등급 미상`. The second sibling, at the same seat for the same three reasons.
  #
  # THE ONLY LOOK AT THE LANDING TREE BEFORE IT LANDS. Serializing the merges
  # does not govern traffic from outside the run, and CI on the base branch is
  # an observation after the fact that cannot stop the merge it reports on. A
  # grading table broken so that an argv comes back empty refuses nothing and
  # writes `축2=` with no value on every row that act leaves — a forged record,
  # not a crash — so nothing downstream notices it either.
  #
  # IT IS NOT WIRED INTO THE DRIVER'S MERGE FUNCTION. The unattended router
  # merges through this verb, so this seat covers that path; the driver's own
  # fixed-graph merge is a path no unattended run takes, and a second copy
  # there would double the surface without covering anything new.
  #
  # THE CHILD GATES ARE ASKED WITH `grade`, UNDER `env -i`, IN A THROWAWAY RUN.
  # `plan`/`act`/`exec` enter this very function and would recurse. Even
  # `grade` walks the whole prelude — the run opening writes a `run` row and
  # the pin hops into the calling run's pinned copy — so pointed at this run
  # a child would write into this ledger and grade the pinned version instead
  # of the merged one. The probe script builds each child its own repository,
  # manifest and state home, and `env -i` cuts every variable this process
  # carries, `CC_GATE_SOURCE_ONLY` among them.
  #
  # THE PROBE IS THE BASE'S COPY. A tree under examination that could supply
  # its own examiner could pass itself. Only when the base does not carry the
  # probe yet is the landing tree's copy used, and that is said aloud. The
  # installed plugin has no `scripts/`, so the gate's own directory is never
  # searched.
  #
  # NO FETCH. The base ref is the same one the merge anchor check decides on,
  # so on a stale tracking ref the tree computed here can differ from the one
  # the host would produce. That residual is accepted, as it is there.
  local seg="$1" cut="$2" alias="$3" tip aroot abr bref btree mb rtree mt probe out rc line
  local mhc="" mhc_set=0 a
  shift 3
  [ -z "${GATE_PARK_CELL:-}" ] || return 0
  [ "$cut" = "머지" ] || return 0
  [ -n "$seg" ] && [ "$seg" != "-" ] || return 0
  # The narrowing is the CI verdict's, on the same two argv-derived values and
  # for the same reason — see that function.
  [ "${GATE_SURFACE:-}" = "읽기" ] && return 0
  if [ "${GATE_SURFACE:-}" = "워크트리쓰기" ] && [ "${GATE_HISTORY_INTEGRATION:-}" = "0" ]; then
    return 0
  fi
  # NO OPERAND, NO VERDICT. An undeclared target, an unresolved tip or an
  # unresolved base leave nothing to compare, and the anchor check and the CI
  # verdict each answer those cases on their own.
  [ "${GATE_UNDECLARED:-0}" != "1" ] || return 0
  aroot=$(alias_root "$alias" 2>/dev/null) || aroot=""
  abr=$(base_branch "$alias" 2>/dev/null) || abr=""
  [ -n "$aroot" ] && [ -d "$aroot" ] && [ -n "$abr" ] || return 0
  # THE HEAD THE LANDING ARGV NAMES IS THE ONE EXAMINED. `gh pr merge …
  # --match-head-commit <sha>` lands exactly that commit, and the worktree's
  # local tip can be a different one — behind a push, or ahead of it. Examining
  # the local tip would let a tip that leaves the orchestrator alone wave
  # through a named head that does not, at the zero-cost return below. A named
  # sha this repository cannot resolve to a commit leaves nothing honest to
  # compare, so it parks rather than falling back to the local tip. The REST
  # merge names its head in the `sha` field (`-f sha=<sha>`, `-F sha=<sha>`)
  # and lands exactly that commit too, so that field is read the same way; a
  # value in a file (`sha=@<file>`) is not read here, and the binding check
  # has refused that argv before this runs.
  while [ "$#" -gt 0 ]; do
    a="$1"; shift
    case "$a" in
      --match-head-commit) mhc_set=1; mhc="${1:-}"; [ "$#" -eq 0 ] || shift ;;
      --match-head-commit=*) mhc_set=1; mhc="${a#--match-head-commit=}" ;;
      -f|-F|--field|--raw-field)
        case "${1:-}" in
          sha=@*) : ;;
          sha=*) mhc_set=1; mhc="${1#sha=}" ;;
        esac
        [ "$#" -eq 0 ] || shift ;;
      -fsha=*|-Fsha=*|--field=sha=*|--raw-field=sha=*)
        a="${a#*sha=}"
        case "$a" in @*) : ;; *) mhc_set=1; mhc="$a" ;; esac ;;
    esac
  done
  if [ "$mhc_set" = "1" ]; then
    tip=$( cd "$aroot" && [ -n "$mhc" ] && git rev-parse --verify --quiet "$mhc^{commit}" 2>/dev/null ) || tip=""
    if [ -z "$tip" ]; then
      warn "the landing argv names head '${mhc}', which does not resolve to a commit in '$aroot' — the grade-regression probe has nothing to examine"
      GATE_PARK_CELL="등급회귀판정불가"; export GATE_PARK_CELL
      return 0
    fi
  else
    tip=$(gate_segment_tip "$seg") || tip=""
    [ -n "$tip" ] || return 0
  fi
  if ( cd "$aroot" && git remote get-url origin >/dev/null 2>&1 ); then
    bref="refs/remotes/origin/$abr"
  else
    bref="refs/heads/$abr"
  fi
  btree=$( cd "$aroot" && git rev-parse --verify --quiet "$bref^{tree}" 2>/dev/null ) || btree=""
  [ -n "$btree" ] || return 0

  # ZERO COST WHEN THE ORCHESTRATOR DOES NOT MOVE — asked first of the segment's
  # own side. A three-way merge takes each path from whichever side changed it,
  # so when the tip left `plugins/cc-cmds/orchestrator` as it was at the merge
  # base, the landing tree's copy is the base's and there is nothing to compare.
  # Asking this before `merge-tree` is what keeps a merge that touches no
  # orchestrator file from being parked because its history cannot be merged
  # at all — that merge is the landing checks' business, not this one's. The
  # directory and not `gate.sh` alone, because the gate sources its siblings.
  # With no merge base there is no side to ask, so the tip is compared with the
  # base itself: when the two carry the same directory, whatever lands does too.
  #
  # `-r` ON BOTH `diff-tree` CALLS, and without it the zero cost is a promise
  # only. A non-recursive `diff-tree` compares the pathspec at the top-level
  # entry `plugins`, so any change anywhere under `plugins/` — a `plugin.json`
  # bump, which every segment of this repository makes — reads as "differs".
  mb=$( cd "$aroot" && git merge-base "$bref" "$tip" 2>/dev/null ) || mb=""
  if ( cd "$aroot" && git diff-tree -r --quiet "${mb:-$bref}" "$tip" -- plugins/cc-cmds/orchestrator ) >/dev/null 2>&1; then
    return 0
  fi

  # A conflict or a failure is not "nothing changed": the tree the host would
  # land cannot be named, so nothing was measured.
  if ! mt=$( cd "$aroot" && git merge-tree --write-tree "$bref" "$tip" 2>/dev/null ); then
    warn "could not compute the tree this merge would land (git merge-tree reported a conflict or failed) — the grade-regression probe did not run"
    GATE_PARK_CELL="등급회귀판정불가"; export GATE_PARK_CELL
    return 0
  fi
  rtree=$(printf '%s\n' "$mt" | sed -n '1p')

  # The segment's change can already be on the base (a sibling landed the same
  # edit), and then the landing tree does not move the orchestrator either.
  if ( cd "$aroot" && git diff-tree -r --quiet "$btree" "$rtree" -- plugins/cc-cmds/orchestrator ) >/dev/null 2>&1; then
    return 0
  fi

  probe=$(mktemp "${TMPDIR:-/tmp}/cc-grade-probe-script.XXXXXX") || probe=""
  if [ -z "$probe" ]; then
    warn "could not make a temporary file for the grade-regression probe"
    GATE_PARK_CELL="등급회귀판정불가"; export GATE_PARK_CELL
    return 0
  fi
  if ! ( cd "$aroot" && git cat-file blob "$bref:scripts/grade-regression-probe.sh" ) > "$probe" 2>/dev/null; then
    if ( cd "$aroot" && git cat-file blob "$rtree:scripts/grade-regression-probe.sh" ) > "$probe" 2>/dev/null; then
      warn "the base '$abr' does not carry the grade-regression probe yet, so the copy in the landing tree is used — this merge is examined by the examiner it brings"
    else
      rm -f "$probe"
      warn "neither the base '$abr' nor the landing tree carries scripts/grade-regression-probe.sh, so the orchestrator change in this merge cannot be examined"
      GATE_PARK_CELL="등급회귀판정불가"; export GATE_PARK_CELL
      return 0
    fi
  fi
  rc=0
  out=$(bash "$probe" --repo "$aroot" --before "$btree" --after "$rtree" 2>&1) || rc=$?
  rm -f "$probe"
  # A PASS SAYS WHAT IT COMPARED. Silence on a pass would look the same as the
  # zero-cost return above, and the positive control's line is what shows the
  # children graded anything at all. On the log stream only, so the forecast
  # line and the exit code are the ones a merge the probe never ran gets.
  case "$rc" in
    0)
      printf '%s\n' "$out" | { grep -E '^(대조|양성 대조|변화|판정):' || true; } | while IFS= read -r line; do
        log "grade-regression probe: $line"
      done ;;
    1)
      printf '%s\n' "$out" | { grep -E '^(회귀|판정):' || true; } | while IFS= read -r line; do
        warn "grade-regression probe: $line"
      done
      GATE_PARK_CELL="등급회귀" ;;
    *)
      printf '%s\n' "$out" | { grep -E '^판정:' || true; } | while IFS= read -r line; do
        warn "grade-regression probe (exit $rc): $line"
      done
      GATE_PARK_CELL="등급회귀판정불가" ;;
  esac
  [ -z "${GATE_PARK_CELL:-}" ] || export GATE_PARK_CELL
  return 0
}

# The two judgments the fulfillment arm makes, and the sentence each leaves
# behind. They are functions rather than inline blocks because each has THREE
# outcomes and the third one — "the world did not answer" — is the one an inline
# block loses: folded into either neighbour it becomes a confident yes or a
# confident no about something nothing measured.
# THE VERDICT TRAVELS IN A VARIABLE, NOT ON STDOUT. Both predicates answer with a
# verdict AND a sentence, and a caller that took the verdict through `$(…)` ran
# the function in a subshell — so the sentence, set on a global, was discarded at
# the moment it was assigned. Every refusal then printed its reason as the empty
# string, which is precisely the state the third value exists to prevent: the
# operator is told the gate could not decide and not told what failed to answer.
# Returning both the same way is what keeps them together.
GATE_LANDING_VERDICT=""
GATE_LANDING_WHY=""
GATE_COVER_VERDICT=""
GATE_COVER_WHY=""

gate_landing_unlanded_why() {
  # gate_landing_unlanded_why <root> <ref> <머지 커밋>
  #
  # WORDING ONLY. Two commits with no common ancestor are not going to acquire one
  # by waiting, and an operator reading 미착지 needs to know which of the two they
  # are looking at. The DISPOSITION is 미착지 either way: a fourth outcome here
  # would leak into `이행 판정`, whose value set is closed at three.
  local root="$1" ref="$2" m="$3"
  if ( cd "$root" && git merge-base "$m" "$ref" >/dev/null 2>&1 ); then
    printf '%s 가 머지 커밋을 담고 있지 않습니다' "$ref"
  else
    printf '머지 커밋과 %s 에 공통 조상이 없습니다 — 재시도로 풀리지 않습니다' "$ref"
  fi
}

gate_landing_rewritten_landed() {
  # gate_landing_rewritten_landed <root> <ref> <머지 커밋>
  #
  # A REWRITING MERGE NEVER MAKES THE TIP AN ANCESTOR. `--squash` and `--rebase`
  # build new commits on the server side, so the ancestry test answers no for
  # that sha forever while the change itself IS on the base branch. Left at that,
  # every deferred obligation in such a repository closes on `근거` alone and the
  # containment predicate is never called once — the debt is discharged having
  # consulted no review at all.
  #
  # The second clause is TREE EQUALITY, on the same grounds the staleness ladder
  # already admits a same-tree exception: a rewrite that leaves the tree
  # byte-identical carried the content across. The window is bounded to what the
  # base gained since it forked from the merged commit — outside that window an
  # equal tree says nothing about THIS merge. No common ancestor means no window
  # and the answer stays no, which is the case the wording helper already calls
  # unrecoverable.
  local root="$1" ref="$2" m="$3" t mb tt
  t=$( cd "$root" && git rev-parse --verify --quiet "${m}^{tree}" 2>/dev/null ) || t=""
  [ -n "$t" ] || return 1
  mb=$( cd "$root" && git merge-base "$m" "$ref" 2>/dev/null ) || mb=""
  [ -n "$mb" ] || return 1
  for tt in $( cd "$root" && git log --format=%T "${mb}..${ref}" 2>/dev/null ); do
    [ "$tt" = "$t" ] && return 0
  done
  return 1
}

gate_obligation_landing() {
  # gate_obligation_landing <대상 별칭> <머지 커밋>
  #
  # Prints 착지 / 미착지 / 판정 불가 and leaves the explaining sentence in
  # `GATE_LANDING_WHY`.
  #
  # IT RUNS IN THE TARGET'S ANCHOR REPOSITORY AND NOT IN THE SEGMENT WORKTREE.
  # Collapsing those two directories into one is the most common misreading of
  # this design: the worktree holds the commit that was merged, and the base
  # branch it has to land on lives in the target's own repository root.
  local al="$1" m="$2" root br rc
  GATE_LANDING_VERDICT=""
  GATE_LANDING_WHY=""
  root=$(alias_root "$al" 2>/dev/null) || root=""
  if [ -z "$root" ] || [ ! -d "$root" ]; then
    GATE_LANDING_WHY="대상 '$al' 의 앵커 저장소 루트를 해소하지 못했습니다"
    GATE_LANDING_VERDICT='판정 불가'; return 0
  fi
  br=$(base_branch "$al" 2>/dev/null) || br=""
  if [ -z "$br" ]; then
    GATE_LANDING_WHY="대상 '$al' 의 베이스 브랜치를 해소하지 못했습니다"
    GATE_LANDING_VERDICT='판정 불가'; return 0
  fi

  # The local branch first, and when it answers yes NOTHING TOUCHES THE NETWORK.
  # An unresolvable `refs/heads/<베이스>` is ordinary rather than an error — a
  # fresh clone need not carry one — and falls through to the remote arm.
  rc=0
  ( cd "$root" && git merge-base --is-ancestor "$m" "refs/heads/$br" >/dev/null 2>&1 ) || rc=$?
  if [ "$rc" = "0" ]; then
    GATE_LANDING_WHY="로컬 refs/heads/$br 가 이미 머지 커밋을 담고 있습니다"
    GATE_LANDING_VERDICT='착지'; return 0
  fi

  # No origin means the local refs ARE the whole world, so the answer above is
  # final rather than provisional. Reaching for a remote that does not exist would
  # turn a settled 미착지 into an unsettleable one.
  if ! ( cd "$root" && git remote get-url origin >/dev/null 2>&1 ); then
    case "$rc" in
      1) if gate_landing_rewritten_landed "$root" "refs/heads/$br" "$m"; then
           GATE_LANDING_WHY="원격이 없고 로컬 refs/heads/$br 가 머지 커밋과 같은 트리의 커밋을 담고 있습니다 — 다시 쓰인 머지입니다"
           GATE_LANDING_VERDICT='착지'; return 0
         fi
         GATE_LANDING_WHY="원격이 없어 로컬 refs/heads/$br 가 세계 전부입니다 — $(gate_landing_unlanded_why "$root" "refs/heads/$br" "$m")"
         GATE_LANDING_VERDICT='미착지'; return 0 ;;
      *) GATE_LANDING_WHY="원격이 없고 로컬 refs/heads/$br 에 대한 조상 검사가 답하지 못했습니다 (git rc=$rc)"
         GATE_LANDING_VERDICT='판정 불가'; return 0 ;;
    esac
  fi

  # A FAILED FETCH IS A REFUSAL AND NOT A 미착지. The failure leaves the stale
  # tracking ref exactly where it was, so the ancestor test below would run and
  # would answer — with the confidence of a measurement and the content of a
  # guess. `base_fetch` cannot be used here: it reports success on a dead remote.
  if ! base_fetch_ref "$al" "$br"; then
    GATE_LANDING_WHY="원격 fetch 가 실패해 refs/remotes/origin/$br 가 낡은 채로 남았습니다"
    GATE_LANDING_VERDICT='판정 불가'; return 0
  fi
  # A fetch that succeeded and still left no tracking ref is also a refusal. That
  # the branch has zero population today means the answer is MISSING, not that it
  # is no.
  if ! ( cd "$root" && git rev-parse --verify --quiet "refs/remotes/origin/$br" >/dev/null 2>&1 ); then
    GATE_LANDING_WHY="fetch 는 성공했으나 refs/remotes/origin/$br 가 없습니다"
    GATE_LANDING_VERDICT='판정 불가'; return 0
  fi
  # THREE BRANCHES, NEVER FOLDED TO TWO. A merge commit that does not resolve in
  # this repository exits 128 here, and 128 is a refusal rather than a no.
  rc=0
  ( cd "$root" && git merge-base --is-ancestor "$m" "refs/remotes/origin/$br" >/dev/null 2>&1 ) || rc=$?
  case "$rc" in
    0) GATE_LANDING_WHY="refs/remotes/origin/$br 가 머지 커밋을 담고 있습니다"
       GATE_LANDING_VERDICT='착지'; return 0 ;;
    1) if gate_landing_rewritten_landed "$root" "refs/remotes/origin/$br" "$m"; then
         GATE_LANDING_WHY="refs/remotes/origin/$br 가 머지 커밋과 같은 트리의 커밋을 담고 있습니다 — 다시 쓰인 머지입니다"
         GATE_LANDING_VERDICT='착지'; return 0
       fi
       GATE_LANDING_WHY=$(gate_landing_unlanded_why "$root" "refs/remotes/origin/$br" "$m")
       GATE_LANDING_VERDICT='미착지'; return 0 ;;
    *) GATE_LANDING_WHY="refs/remotes/origin/$br 에 대한 조상 검사가 답하지 못했습니다 (git rc=$rc)"
       GATE_LANDING_VERDICT='판정 불가'; return 0 ;;
  esac
}

gate_segment_review_head() {
  # gate_segment_review_head <segment> — the `리뷰 HEAD` of that segment's LAST
  # `cycle` row. Last and not first: a segment reviewed twice is answered by the
  # review that happened most recently, which is the one the containment test is
  # about.
  local row
  row=$(gate_segment_last_cycle_row "$1")
  [ -n "$row" ] || return 0
  gate_row_field "$row" '리뷰 HEAD'
}

gate_obligation_covers() {
  # gate_obligation_covers <대상 별칭> <머지 커밋> <리뷰 HEAD>
  #
  # Prints 덮는다 / 덮지 않는다 / 판정 불가 and leaves the sentence in
  # `GATE_COVER_WHY`. The question is whether the review that closed this
  # obligation actually looked at the commit that was merged — a review of the
  # segment is not the same thing as a review of that commit.
  local al="$1" m="$2" r="$3" root rc tm tr
  GATE_COVER_VERDICT=""
  GATE_COVER_WHY=""
  # NO REVIEW AT ALL IS `덮지 않는다`, NOT `판정 불가`. The third value is for a
  # question the world declined to answer — an unresolvable sha, a dead remote, a
  # missing ref — and it is a refusal whose repair is "make the judgment possible
  # and call again". The absence of a `cycle` row is not that: it is a complete,
  # confident answer that no review covers this commit, and its repair is "record
  # the review". Folding the two together sends the operator to look for a broken
  # repository when what is missing is the review itself.
  if [ -z "$r" ] || [ "$r" = "-" ]; then
    GATE_COVER_WHY="this segment has no cycle row carrying \`리뷰 HEAD\`"
    GATE_COVER_VERDICT='덮지 않는다'; return 0
  fi
  root=$(alias_root "$al" 2>/dev/null) || root=""
  if [ -z "$root" ] || [ ! -d "$root" ]; then
    GATE_COVER_WHY="could not resolve the anchor repository root of target '$al'"
    GATE_COVER_VERDICT='판정 불가'; return 0
  fi
  # `--is-ancestor` answers the equal case with 0 as well, so "ancestor of, or the
  # same as" is one test rather than two.
  rc=0
  ( cd "$root" && git merge-base --is-ancestor "$m" "$r" >/dev/null 2>&1 ) || rc=$?
  case "$rc" in
    0) GATE_COVER_WHY="review HEAD $r contains the merge commit"
       GATE_COVER_VERDICT='덮는다'; return 0 ;;
    1) : ;;
    *) GATE_COVER_WHY="the ancestry check on review HEAD $r did not answer (git rc=$rc)"
       GATE_COVER_VERDICT='판정 불가'; return 0 ;;
  esac
  # The tree exception, on the same terms the freshness ladder already grants it.
  # A rebase or an amend moves the commit id and leaves the reviewed bytes
  # identical; refusing those would refuse reviews that did happen.
  tm=$( { cd "$root" 2>/dev/null && git rev-parse "${m}^{tree}" 2>/dev/null; } || true)
  tr=$( { cd "$root" 2>/dev/null && git rev-parse "${r}^{tree}" 2>/dev/null; } || true)
  if [ -n "$tm" ] && [ "$tm" = "$tr" ]; then
    GATE_COVER_WHY="the tree of review HEAD $r is the tree of the merge commit (rebase or amend)"
    GATE_COVER_VERDICT='덮는다'; return 0
  fi
  GATE_COVER_WHY="review HEAD $r does not contain the merge commit and its tree differs"
  GATE_COVER_VERDICT='덮지 않는다'; return 0
}

# The three answers `gate_segment_cycle_verdict` leaves, in globals for the same
# reason the landing and cover verdicts are: a caller reading them through
# `$(…)` would run the function in a subshell and lose two of the three.
GATE_CYCLE_COUNT_VERDICT=""
GATE_CYCLE_COVER_VERDICT=""
GATE_CYCLE_NUMBER=""

gate_segment_cycle_verdict() {
  # gate_segment_cycle_verdict <세그먼트> <대상 별칭> <머지 팁>
  #
  # What that segment's LAST `cycle` row says about a merge of <머지 팁>:
  #   GATE_CYCLE_COUNT_VERDICT  충족 | 이월 | 기각 | 위반 | 판정 불가 | 리뷰 없음
  #   GATE_CYCLE_COVER_VERDICT  덮는다 | 덮지 않는다 | 판정 불가
  #   GATE_CYCLE_NUMBER         the row's `사이클`, or 없음
  #
  # THE ONE DERIVATION. The `머지 대조` of a merged segment row is formatted from
  # this, and the convergence value a later change writes on the cycle row is
  # meant to read the same function rather than a second reading of the same
  # row. The count half is `gate_segment_review_count_verdict`, the function the
  # review's `다음` table reads, and it reads a dismissal and a carry-over the
  # way that table does, so the merge record and the merge decision cannot
  # disagree about the same cycle. `기각` and `이월` bind only a `리뷰 기각` or
  # `리뷰 이월` row with the last cycle's `사이클` and `리뷰 HEAD`, so a newer
  # cycle is read by its counts again.
  #
  # A MISSING COUNT IS NOT ZERO. The merge rule fills an absent `P0`/`P1` with 0
  # before comparing; that reading is left alone there, and not copied here —
  # a row that states no count has not said the findings are closed, and the
  # record of the merge is the place that has to be able to say so.
  # `gate_canon_count` in the count function keeps that.
  local seg="$1" al="$2" tip="$3" row rh n
  GATE_CYCLE_COUNT_VERDICT=""
  GATE_CYCLE_COVER_VERDICT=""
  GATE_CYCLE_NUMBER='없음'
  row=$(gate_segment_last_cycle_row "$seg")
  GATE_CYCLE_COUNT_VERDICT=$(gate_segment_review_count_verdict "$seg")
  if [ -n "$row" ]; then
    n=$(gate_row_field "$row" '사이클')
    case "$n" in
      ''|*[!0-9]*|0*) : ;;
      *) GATE_CYCLE_NUMBER="$n" ;;
    esac
  fi
  if [ -z "$tip" ]; then
    GATE_CYCLE_COVER_VERDICT='판정 불가'
  else
    rh=""
    [ -z "$row" ] || rh=$(gate_row_field "$row" '리뷰 HEAD')
    gate_obligation_covers "$al" "$tip" "$rh"
    GATE_CYCLE_COVER_VERDICT="$GATE_COVER_VERDICT"
  fi
}

gate_segment_landed_exempt() {
  # gate_segment_landed_exempt <세그먼트> <대상 별칭> <커밋> — returns 0 when a
  # `완료`/`park` row may carry a `커밋` that has already landed:
  #   1. this segment already has a `상태=머지됨` row, so its merge was recorded
  #      and compared there; or
  #   2. another segment's `상태=머지됨` row carries a `커밋` that contains this
  #      one — as an ancestor, or as the same tree after a rewriting merge — so
  #      the change landed inside a merge the ledger already compared.
  # A sibling row with no `커밋` exempts nothing: it names no commit this one
  # could have landed inside.
  local seg="$1" al="$2" c="$3" root row sid sc
  [ -n "$(gate_rows 'segment' | gate_rows_field_eq 'id' "$seg" | gate_rows_field_eq '상태' '머지됨')" ] && return 0
  root=$(alias_root "$al" 2>/dev/null) || root=""
  [ -n "$root" ] && [ -d "$root" ] || return 1
  while IFS= read -r row; do
    [ -n "$row" ] || continue
    sid=$(gate_row_field "$row" 'id')
    [ "$sid" != "$seg" ] || continue
    sc=$(gate_row_field "$row" '커밋')
    [ -n "$sc" ] || continue
    ( cd "$root" && git merge-base --is-ancestor "$c" "$sc" >/dev/null 2>&1 ) && return 0
    gate_landing_rewritten_landed "$root" "$sc" "$c" && return 0
  done <<EOF
$(gate_rows 'segment' | gate_rows_field_eq '상태' '머지됨')
EOF
  return 1
}

gate_merge_check_value() {
  # gate_merge_check_value <리뷰 정책> <카운트 판정> <커버리지 판정> [<메타>] —
  # the `머지 대조` value. Closed set: 충족 · 이월 · 기각 · 메타 해소 ·
  # 위반(카운트) · 위반(미포함) · 위반(카운트·미포함) · 리뷰 없음 · 판정 불가 ·
  # 정책 면제.
  #
  # `메타 해소` is a passing count over a tip the review did not cover, when
  # <메타> is 1: the tip is the renumbering merge of the reviewed HEAD, whose
  # tree that HEAD and the merged base fix to the object id. Only the coverage
  # half is excused, and only by that proof.
  #
  # `이월` EXCUSES THE COUNT HALF ONLY. A carry-over moves the open P1 findings
  # to issues; it says nothing about whether the review saw the merged commit,
  # so a carried cycle that does not cover the merge is still `위반(미포함)`.
  # `기각` excuses the count half only too, P0 included: a person read the
  # cycle's findings at the seat and let the merge through, which says nothing
  # about whether that review saw the merged commit either.
  #
  # `판정 불가` OUTRANKS A PARTIAL VIOLATION. A value that names one violation
  # while the other half went unmeasured reads as the whole answer, and the
  # repair it points to may not be the one that is missing.
  local pol="$1" cnt="$2" cov="$3" meta="${4:-0}"
  if [ "$pol" != '선리뷰후머지' ]; then printf '%s' '정책 면제'; return 0; fi
  if [ "$cnt" = '리뷰 없음' ]; then printf '%s' '리뷰 없음'; return 0; fi
  if [ "$cnt" = '판정 불가' ] || [ "$cov" = '판정 불가' ]; then printf '%s' '판정 불가'; return 0; fi
  case "$cnt:$cov" in
    '충족:덮는다') printf '%s' '충족' ;;
    '이월:덮는다') printf '%s' '이월' ;;
    '기각:덮는다') printf '%s' '기각' ;;
    '위반:덮는다') printf '%s' '위반(카운트)' ;;
    '충족:덮지 않는다'|'이월:덮지 않는다'|'기각:덮지 않는다')
      if [ "$meta" = 1 ]; then printf '%s' '메타 해소'; else printf '%s' '위반(미포함)'; fi ;;
    '위반:덮지 않는다') printf '%s' '위반(카운트·미포함)' ;;
    *) printf '%s' '판정 불가' ;;
  esac
}

gate_issue_review_obligation() {
  # gate_issue_review_obligation <segment> <cutpoint> <grade> <policy> <alias> [<kind>]
  #
  # `선머지후리뷰` does not REMOVE the review, it defers it — and a deferral with
  # no record is a removal that nobody wrote down. The row is what makes the
  # deferral survive the merge: termination condition 9 refuses to let the run
  # end while one is unfulfilled.
  #
  # `생성 등급` is the axis-2 grade of the act that created the obligation, and
  # NOTHING IN THIS TREE READS IT ON THIS SERIES. The excusal rule reads a field
  # of the same name on `problem` rows, which is a different series with a
  # different writer, and this comment used to claim that reader as its own — so
  # the field looked load-bearing and an implementer changing it would have
  # searched for a consumer that does not exist. It is kept because the morning
  # wants to know what kind of act deferred the review, not because a predicate
  # is waiting on it.
  #
  # THE ALIAS ARRIVES AS AN ARGUMENT because there is nowhere else to get it: it
  # is on neither the segment row nor this series, and only the calling scope
  # knows which target the merge was authorized against. The row carries it as
  # `대상` so the fulfilling side runs its landing test in THAT target's anchor
  # repository rather than in the segment worktree — two directories the shape
  # of this design invites collapsing into one.
  #
  # `머지 커밋` IS THE COMMIT BEING MERGED and not a commit the merge creates:
  # the tip of the segment worktree at issue time. A `cycle` row's `리뷰 HEAD`
  # lives in that same ref space, and the containment test between the two means
  # nothing unless both name commits that exist before the merge does.
  #
  # THE DUPLICATE GUARD ASKS ABOUT STATE, NOT EXISTENCE. A fulfillment row
  # carries the same `의무 id=`, so an existence test suppressed every issue
  # after the first fulfillment — a segment's second merge then created no
  # obligation at all, which is the hole this series exists to close. And the
  # question is narrowed to THIS segment: asked run-wide, a sibling segment's
  # open obligation suppresses this one's, trading a defect inside a segment for
  # the guarantee between segments.
  #
  # AND IT ISSUES NOTHING FOR A BOOKKEEPING ACT. Such an act merges nothing;
  # it carries `머지` only because the router labels acts with the target's
  # cutpoint. The guard above walks the unfulfilled ids only, so a row write
  # on a segment whose slot was already fulfilled would append a second
  # `미이행` row under the same id and hold the run open on a merge that never
  # happened. The anchor check skips the same set for the same reason — the two
  # exemptions are one decision, spelled at both sites.
  local seg="$1" cut="$2" grade="$3" policy="$4" alias="$5" kind="${6:-}" id tip
  [ "$policy" = "선머지후리뷰" ] || return 0
  [ "$cut" = "머지" ] || return 0
  gate_kind_is_bookkeeping "$kind" && return 0
  [ -n "$seg" ] && [ "$seg" != "-" ] || return 0
  # THE ANCHOR IS RESOLVED BEFORE THE ID, because the id is keyed on it. The
  # order is safe: this issuer runs only under `선머지후리뷰` at cutpoint `머지`,
  # which is exactly the window in which the pre-issue anchor check has already
  # run and refused an unreadable tip, so nothing new can fail here.
  tip="${GATE_MERGE_ANCHOR:-}"
  [ -n "$tip" ] || { tip=$(gate_segment_tip "$seg") || tip=""; }
  if [ -z "$tip" ]; then
    warn "could not read the tip of segment '$seg', so the review obligation cannot be issued"
    return "$GATE_EXIT_ANCHOR"
  fi
  # The id is keyed on (run, segment, ANCHOR) and NOT on the review cycle: it is
  # the key of a review SLOT, not of a cycle. Re-keying it per cycle would change
  # what termination condition 9 counts.
  #
  # THE ANCHOR IS IN THE KEY BECAUSE (run, segment) ALONE COLLAPSES N MERGES INTO
  # ONE DEBT. Under `끔` the ordering predicate does not run, so a second merge at
  # a NEW tip reaches this issuer with the first tip's slot still open and the
  # duplicate guard below returns without a row — the second merge leaves no
  # trace at all. Fulfilling the one slot then closes on the first tip, which a
  # review does cover, and everything between the two tips lands on the base
  # branch reviewed by nobody with nothing in the ledger to say so. The reason
  # cycle-keying was rejected does not carry over: an unreviewed second merge
  # SHOULD raise the count condition 9 holds the run open on.
  id="RO-$(printf '%s|%s|%s' "$RUN_ID" "$seg" "$tip" | shasum -a 256 | cut -c1-8)"
  # Membership is decided over a VALUE rather than over a pipeline exit status:
  # ids are `RO-` plus hex and carry no whitespace, so the word-splitting loop
  # this file already uses for the same list reads them exactly.
  local open_id
  for open_id in $(gate_unfulfilled_review_obligations "$seg"); do
    [ "$open_id" = "$id" ] && return 0
  done
  gate_append '리뷰 의무' "의무 id=$id" "상태=미이행" "세그먼트=$seg" \
    "대상=$alias" "머지 커밋=$tip" "생성 등급=$grade" \
    "발행 시각=$(now_iso)" "이행 시각=-"
  log "리뷰 의무 발행 $id — 세그먼트 $seg · 대상 $alias · 머지 커밋 $tip (선머지후리뷰)"
}

gate_run_readonly() {
  # Runs the act under the READ-scoped credential. A `gh pr merge` spelled here
  # then fails at the GitHub API rather than at a string match, and that failure
  # is unforgeable — which is the property no string matcher can have. Acts that
  # genuinely need the write-scoped credential do not come through this door;
  # they are performed by the gate's own verbs.
  #
  # The act runs in the TARGET's worktree, and the whole body is a subshell so
  # that neither the credential exports nor the `cd` outlive the act. `--target`
  # is a parameter of both acting verbs and every target row carries an absolute
  # `메인 워크트리`, but nothing used to carry that value to the act's working
  # directory — so a manifest could declare nine targets and only the home one
  # could receive an act. The two spellings a router reached for instead were
  # both refused: calling from the target's own directory trips the manifest's
  # origin-worktree pin, and `git -C <path>` was ungradeable.
  local line dir="${GATE_ACT_CWD:-}"
  (
    while IFS= read -r line; do
      [ -n "$line" ] || continue
      export "$line"
    done <<CREDS
$(cred_readonly_env 2>/dev/null || true)
CREDS
    if [ -n "$dir" ]; then
      cd "$dir" || { printf 'gate: could not change into the target worktree: %s\n' "$dir" >&2; exit 1; }
    fi
    "$@"
  )
}

gate_pin_attempt() {
  # gate_pin_attempt <segment> — pin this dispatch's attempt number, echo it.
  #
  # A NAMED FUNCTION rather than a block inside the launcher, so a test can burn
  # it. Inlined, the only thing a suite could reach was the launcher's source
  # text, and a shape assertion stays green as long as the literals survive —
  # deleting the advance loop below leaves every literal in place and lands two
  # dispatches on one path with nothing red.
  #
  # THE ROW COUNT IS THE STARTING POINT AND NOT THE ANSWER. A dispatch that died
  # before its row landed leaves the count where it was, and the router
  # re-dispatches the same segment id — so two attempts would land on one path.
  # The driver pins the same way and for the same reason, and its readers consult
  # the pin FIRST, which is what makes one file the answer for both sides instead
  # of each deriving its own.
  #
  # The count is taken from the gate's OWN rows and not from the driver's
  # `stage_attempt`: the gate has already appended this dispatch's `자율 승인` row
  # by the time it gets here, while the driver counts `stage-result` rows that
  # only land at termination. Two counting bases, one pin — the advance loop is
  # what makes them agree on the file.
  #
  # AND THE PROGRESS VECTOR DELIBERATELY DOES NOT SHARE THIS COUNT. Here every
  # authorisation row must consume a number, outcome unknown, or two attempts
  # land on one log path; there (`dispatches=` in `gate_progress_vector`) an
  # attempt that produced nothing observable must count for nothing, or a
  # dispatch that dies at launch resets the stagnation counter. Same rows,
  # opposite questions — a shared helper would be wrong for one of them.
  #
  # A ROUTED LAUNCH PASSES THE NUMBER IT ALREADY CLAIMED as the second argument,
  # and that number is pinned as it is. Deriving again would skip the claim the
  # same launch has just made. Two dispatches of one key are kept apart by the
  # per-key dispatch lock the act holds, not by comparing two derivations.
  local seg="$1" attempt="${2:-}"
  mkdir -p "$RUN_DIR/log"
  [ -n "$attempt" ] || attempt=$(gate_derive_attempt "$seg")
  printf '%s\n' "$attempt" > "$RUN_DIR/$seg.attempt"
  printf '%s' "$attempt"
}

gate_derive_attempt() {
  # gate_derive_attempt <segment> — the number `gate_pin_attempt` would pin now,
  # with nothing written. A routed launch derives it before asking the router,
  # because the lineage it asks for carries the number, and pins that number.
  #
  # A NUMBER ALREADY CLAIMED IS SKIPPED. A claim stays for the life of the run,
  # and an attempt that ended before it left a log — a waiter that died, a
  # deadline park — would otherwise be derived again and refused as claimed on
  # every later dispatch. That is the design step's case: its authorization rows
  # carry `세그먼트=-`, so the count above is always 1 for it.
  local seg="$1" attempt
  attempt=$( { gate_rows '자율 승인' | grep -F 'kind=skill ' || true; } \
             | { grep -cF "세그먼트=$seg " || true; } )
  [ "${attempt:-0}" -ge 1 ] || attempt=1
  while [ -e "$RUN_DIR/log/$seg#$attempt.json" ] || [ -e "$RUN_DIR/log/$seg#$attempt.err" ] \
        || [ -e "$RUN_DIR/$seg.attempt.$attempt" ]; do
    attempt=$(( attempt + 1 ))
  done
  printf '%s' "$attempt"
}

gate_stage_emitted_judgment_id() {
  # gate_stage_emitted_judgment_id <stage-key> <stream> — the approval id the
  # absorber issued for the judgment this attempt's terminal message emitted, or
  # nothing when it emitted none (no marker, or grade 0).
  #
  # THE ID IS DERIVED, NOT LOOKED UP BY ROW POSITION. The absorber keys every
  # stage of a segment on the bare segment, so `막는 세그먼트` cannot tell this
  # dispatch's question from a review stage's or an earlier cycle's; and an
  # issue that meets the same question already `대기` writes no new row, so the
  # last issuing row need not be this attempt's either. The id hashes the stage
  # key and the question text, which is exactly what the absorber hashed.
  local key="$1" stream="$2" res
  res=$( { grep '"type":"result"' "$stream" 2>/dev/null || true; } | tail -1)
  gate_emitted_judgment_fields "$res" || return 0
  gate_judgment_approval_id "$key" \
    "$(gate_judgment_question "${GATE_EMIT_STD:-미상}" "${GATE_EMIT_WHY:-스테이지 방출}")"
}

gate_stage_has_unspent_answer() {
  # gate_stage_has_unspent_answer <stage-key> <approval id> — 0 when a person
  # answered the judgment this stage's last attempt emitted and no adoption row
  # has consumed the answer yet. That is the re-attachment that carries an
  # answer; it is never a continuation. The run-scope design step also counts
  # any answered approval on the step, as the step's open predicate below does.
  local key="$1" jid="${2:-}" id dstep
  if dstep=$(gate_run_scope_step design 2>/dev/null) && [ "$dstep" = "$key" ] \
     && [ -z "$(gate_segment_field "$key" '상태')" ]; then
    for id in $(gate_rows '승인' | tr '|' '\n' | sed -n 's/^ *승인 id=//p' | sed 's/[[:space:]]*$//' | sort -u); do
      [ -n "$id" ] || continue
      [ "$(gate_approval_state "$id")" = "승인" ] || continue
      if gate_has_row '자율 승인' "| 해소 승인=$id |"; then continue; fi
      gate_approval_keyed_on_design_step "$id" && return 0
    done
  fi
  [ -n "$jid" ] || return 1
  [ "$(gate_approval_state "$jid")" = "승인" ] || return 1
  if gate_has_row '자율 승인' "| 해소 승인=$jid |"; then return 1; fi
  return 0
}

gate_stage_has_open_judgment() {
  # gate_stage_has_open_judgment <stage-key> <approval id> — 0 when the
  # judgment this stage's last attempt emitted is still `대기`. A question
  # another dispatch of the same segment raised — a review stage, an earlier
  # cycle — neither blocks this continuation nor is answered by it. The design
  # step keeps its own predicate, which asks the question about the step.
  local key="$1" jid="${2:-}" dstep
  if dstep=$(gate_run_scope_step design 2>/dev/null) && [ "$dstep" = "$key" ] \
     && [ -z "$(gate_segment_field "$key" '상태')" ]; then
    gate_design_step_has_open_approval
    return $?
  fi
  [ -n "$jid" ] || return 1
  [ "$(gate_approval_state "$jid")" = "대기" ]
}

gate_continuation_argv() {
  # gate_continuation_argv <stage-key> <stage-kind> <cli args...> — decide
  # whether a `--resume` dispatch is a CONTINUATION. On one, GATE_CONTINUED is
  # non-empty and GATE_CONTINUE_ARGV holds the argv to launch; otherwise the
  # caller's argv stands. Returns 0, or GATE_EXIT_RULE on a refusal.
  #
  # A continuation is a resume of a stage whose last row is `공허한 성공`: it
  # ended its turn in prose, with no gate act and no halt record. What it needs
  # is the fixed continue message naming the unmet predicate, not the stage
  # prompt again — resent into a full context, the prompt restarts the stage
  # from the top. So the gate substitutes the message the driver sends from the
  # same definition, and the router's prompt is not used. A resume that carries
  # an answer, or one that picks up a crash, is not a continuation and its
  # argv passes through unchanged.
  #
  # THE JUDGMENT CONSULTED IS THE ONE THE LAST ATTEMPT EMITTED, and only that
  # one. A question another dispatch of the same segment or an earlier cycle
  # raised neither blocks this continuation nor is answered by it.
  #
  # The refusals come before the attempt pin and the launch token, so a refused
  # continuation consumes neither an attempt number nor a continuation.
  local key="$1" skind="$2"
  shift 2
  GATE_CONTINUED=""
  local last sess att turns n unmet i stream jid dstep missing
  last=$(gate_stage_result_rows_of "$key" | tail -1)
  # A STAGE A MODEL REFUSAL ENDED gets ONE re-attachment of its own session,
  # with the fixed refusal message in place of the router's prompt, and no
  # more: the ledger's `거절 종료` rows of the key are the counter, so a second
  # refusal is refused here and its disposition is a cone `blocked` with
  # `원인=거절 소진`. It spends no continuation, and a fresh dispatch is not
  # this function's to refuse.
  if [ "$(gate_row_field "$last" '종단 부류')" = '거절 종료' ]; then
    n=$( { gate_stage_result_rows_of "$key" || true; } | grep -cF '종단 부류=거절 종료' || true)
    if [ "${n:-0}" -ge 2 ]; then
      warn "this stage has ended in a model refusal ${n} times ($key) — it is re-attached once and no more; record a cone \`blocked\` anchored on it with \`원인=거절 소진\`, and leave what it saved in place"
      return "$GATE_EXIT_RULE"
    fi
    sess=$(gate_row_field "$last" '세션 id')
    if [ "$sess" != "$GATE_RESUME" ]; then
      warn "a refused stage is re-attached to the last attempt's session ($key: ${sess:-미상}), not $GATE_RESUME — with no session on that row, record a cone \`blocked\` with \`원인=거절 소진\` rather than dispatching it afresh"
      return "$GATE_EXIT_RULE"
    fi
    GATE_CONTINUE_ARGV=()
    i=0
    while [ "$#" -gt 0 ]; do
      if [ "$1" = "-p" ] && [ "$#" -ge 2 ]; then
        GATE_CONTINUE_ARGV+=(-p "$(refusal_message)"); shift 2; i=1
      else
        GATE_CONTINUE_ARGV+=("$1"); shift
      fi
    done
    [ "$i" = "1" ] || GATE_CONTINUE_ARGV+=(-p "$(refusal_message)")
    GATE_CONTINUED=1
    log "거절 재부착 — $key ← 세션 $GATE_RESUME (1회)"
    return 0
  fi
  [ "$(gate_row_field "$last" '종단 부류')" = '공허한 성공' ] || return 0
  att=$(gate_row_field "$last" '실행 버전')
  stream="$RUN_DIR/log/$key#$att.json"
  jid=$(gate_stage_emitted_judgment_id "$key" "$stream")
  gate_stage_has_unspent_answer "$key" "$jid" && return 0
  if gate_stage_has_open_judgment "$key" "$jid"; then
    if dstep=$(gate_run_scope_step design 2>/dev/null) && [ "$dstep" = "$key" ]; then
      warn "the design step has an approval that is still pending, so it is not continued — stop the design, holding the clauses that need the document 보류 on that approval ($key)"
    else
      warn "the judgment this stage's last attempt emitted is still pending (approval $jid), so it is not continued — wait for the answer ($key)"
    fi
    return "$GATE_EXIT_RULE"
  fi
  sess=$(gate_row_field "$last" '세션 id')
  if [ "$sess" != "$GATE_RESUME" ]; then
    warn "a continuation resumes the last attempt's session ($key: ${sess:-미상}), not $GATE_RESUME — with no session on that row, dispatch the stage afresh"
    return "$GATE_EXIT_RULE"
  fi
  turns=$(stream_last_num_turns "$stream")
  if [ "${turns:-0}" = "0" ]; then
    warn "the last attempt ran zero turns, so there is nothing to continue — dispatch the stage afresh instead ($key#$att)"
    return "$GATE_EXIT_RULE"
  fi
  # THE SAME FAILURE REASON ENDS THE CHAIN AS THE CAP DOES. Two attempts in a
  # row with one `실패 서명` whose cause is not `-` would only spend the next
  # continuation on the same wall; the refusal is the cap's, with the reason
  # and the signature named.
  local fsig_prev fsig_last fsig_same=0
  fsig_last=$(gate_row_field "$last" '실패 서명')
  fsig_prev=$(gate_row_field "$(gate_stage_result_rows_of "$key" | tail -2 | sed -n '1{$!p;}')" '실패 서명')
  same_failure_reason "$fsig_prev" "$fsig_last" && fsig_same=1
  if [ "$fsig_same" = "1" ] || [ "$(continue_count "$key")" -ge "$CONTINUE_MAX" ]; then
    [ "$fsig_same" = "0" ] || warn "같은 실패 사유 — 직전 시도와 실패 서명이 같다: $fsig_last ($key)"
    # A RUN-SCOPE STEP IS NOT TOLD TO RECORD A BLOCK HERE. A cone may be
    # anchored on its step id, but a block would only hold the run on a step
    # that has nothing left to continue. What the design step has is the
    # design stop, which termination condition 1 records once the same counter
    # reaches the cap. The audit step has no stop of its own: an audit that
    # produced nothing leaves the document unaudited, and a plan built on it
    # would build on what nobody read — so the run stops before planning.
    if dstep=$(gate_run_scope_step design 2>/dev/null) && [ "$dstep" = "$key" ]; then
      warn "this design step has been continued $CONTINUE_MAX times with no frozen document — it is not continued again and not dispatched afresh; stop the design: settle the clauses that need the document as 불가능 and propose done, which condition 1 records as 무효화 ($key)"
    elif dstep=$(gate_run_scope_step audit 2>/dev/null) && [ "$dstep" = "$key" ]; then
      warn "감사를 더 이어가지 않는다 — 세그먼트를 계획하지 않는다: 이 감사 단계는 산출물 없이 $CONTINUE_MAX 번 이어갔습니다. 감사되지 않은 문서로 세그먼트를 계획하지 말고 사유=중단 인수인계로 교대를 끝내세요 ($key)"
    else
      warn "this stage has been continued $CONTINUE_MAX times with no artifact — it is not continued again; record it as blocked ($key)"
    fi
    return "$GATE_EXIT_RULE"
  fi
  case "$skind" in
    design) unmet="동결된 설계 문서도 정지 기록도 없다" ;;
    audit)  unmet="판독자 리포트 파일(docs/design-audit/<slug>.reader-*.md)도 감사 종결 문구($LIT_AUDIT_TERMINAL)도 없다" ;;
    visual) unmet="검토 통과로 확정된 시각 사이드카도 시각 종결 문구($LIT_VISUAL_TERMINAL)도 정지 기록도 없다" ;;
    # An implement attempt filed `공허한 성공` for its residual share names the
    # missing headings verbatim, so the continued session can find each item.
    implement)
      missing=$(residual_share_missing "${DOC:-}" "$key" "$RUN_DIR/halt" "$RUN_DIR/$key.plan.md")
      if [ -n "$missing" ]; then unmet=$(residual_unmet_message "$missing")
      else unmet="게이트를 거친 행위도 정지 기록도 없다"; fi ;;
    *)      unmet="게이트를 거친 행위도 정지 기록도 없다" ;;
  esac
  GATE_CONTINUE_ARGV=()
  i=0
  while [ "$#" -gt 0 ]; do
    if [ "$1" = "-p" ] && [ "$#" -ge 2 ]; then
      GATE_CONTINUE_ARGV+=(-p "$(continue_message "$unmet")"); shift 2; i=1
    else
      GATE_CONTINUE_ARGV+=("$1"); shift
    fi
  done
  [ "$i" = "1" ] || GATE_CONTINUE_ARGV+=(-p "$(continue_message "$unmet")")
  GATE_CONTINUED=1
  n=$(continue_spend "$key")
  log "스테이지 계속 — $key ← 세션 $GATE_RESUME, 계속 메시지 ($n/$CONTINUE_MAX)"
  return 0
}

gate_launch_route_park() {
  # gate_launch_route_park <alias> <row segment> <segment> <why> [<lineage>] —
  # the row a routed dispatch leaves when it stops before the pin. Act scope,
  # like a reach park: this dispatch was not performed and nothing waits for an
  # answer.
  #
  # A SUPERVISOR THAT STOPS PASSES ITS LINEAGE, and the row's `근거` then starts
  # with `계보=<lineage>`. Its attempt is already pinned, and `gate.sh wait` and
  # settlement recognise this attempt's park by that field — without it the
  # pinned attempt reads as a launch that never happened.
  local alias="$1" rowseg="$2" seg="$3" why="$4" lin="${5:-}" basis
  basis=$why
  [ -z "$lin" ] || basis="계보=$lin $why"
  gate_append 'blocked' "대상=$alias" "스코프=act" "원인=막힘" "사유=라우터 판정" \
    "세그먼트=$rowseg" "스테이지=$seg" "근거=$(gate_row_safe "$basis" 300)" \
    "관측=$(now_iso)" "재개 명령=라우터가 부여할 때 같은 세그먼트를 다시 파견하세요" \
    || warn "could not write the routing stop row ($seg)"
  warn "$why — $seg is not launched"
}

gate_redispatch_line() {
  # gate_redispatch_line <alias> <row segment> — the command a deadline park's
  # resume field names: the same dispatch again, with a fresh digest. The stage's
  # own argv is not repeated — a prompt does not fit on a row, and the router
  # that dispatched it holds it.
  #
  # THE ROW SEGMENT AND NOT THE KEY. A segment dispatch's row segment is its key,
  # but a run-scope step's is `-`, and `act` takes such a step only as
  # `--segment -` with the step's kind as the first stage argument — the step id
  # in `--segment` is refused there as a segment with no `segment` row (exit 3).
  printf 'gate.sh act --kind skill --target %s --segment %s --cutpoint <절단점> --snapshot-digest <새 H> -- <같은 스테이지 인자>' "$1" "$2"
}

gate_wait_deadline_park() {
  # gate_wait_deadline_park <alias> <row segment> <key> <lineage> <ready-at iso>
  #                         <basis> <recovery> <redispatch> — the cone row a
  # stage that cannot finish inside the deadline leaves. Anchored on the key —
  # the segment id, or a run-scope step id (design, audit, split or visual) — never on
  # the lineage; the lineage rides in `근거` so this attempt's park can be
  # recognised. On a run-scope step it holds the run (termination condition 5)
  # until a later attempt of the key or a `원인=해소` row releases it.
  local alias="$1" rowseg="$2" key="$3" lin="$4" ready="$5" basis="$6" rec="$7" redo="$8" rc=0
  case "$basis" in *"계보=$lin"*) ;; *) basis="계보=$lin $basis" ;; esac
  [ -n "$rec" ] || rec="$WAIT_LOOP_DEADLINE_RECOVERY"
  gate_record_cone "$alias" "스코프=cone" "원인=막힘" "사유=마감 초과 — $key" \
    "앵커 세그먼트=$key" "세그먼트=$rowseg" "스테이지=$key" \
    "근거=$(gate_row_safe "$basis" 200)" "관측=$(now_iso) ready_at=$ready" \
    "재개 명령=$(gate_row_safe "$rec — $redo" 360)" || rc=$?
  if [ "$rc" != "0" ]; then
    warn "the deadline cone row was refused (rc=$rc) — an act-scope row stands in ($key)"
    gate_launch_route_park "$alias" "$rowseg" "$key" "마감 초과 — ready_at $ready ($rec)" "$lin"
  fi
  warn "마감 초과 — $key 는 마감 안에 끝낼 수 없어 기동하지 않습니다 (ready_at $ready)"
}

gate_launch_route_drop() {
  # gate_launch_route_drop — hand back the lease this dispatch minted, on an exit
  # after the grant and before the supervisor takes over. A lease the lineage
  # already had before this call is not this dispatch's to release.
  local rc=0
  [ "${GATE_ROUTE_MINTED:-0}" = "1" ] || return 0
  route_lease_release "$(run_pace_root)/leases" "$RUN_ID" "$GATE_ROUTE_LINEAGE" "$GATE_ROUTE_NONCE" || rc=$?
  [ "$rc" = "0" ] || warn "the lease release ended rc=$rc ($GATE_ROUTE_LINEAGE)"
  GATE_ROUTE_MINTED=0
  return 0
}

gate_launch_route() {
  # gate_launch_route <alias> <segment> <stage-kind> — routing on: derive the
  # attempt, claim it, and ask the router for this launch. Leaves the answer in
  # GATE_ROUTE_ATTEMPT, GATE_ROUTE_LINEAGE, GATE_ROUTE_ENV, GATE_ROUTE_NONCE
  # (empty when the grant carries no lease), GATE_ROUTE_ACCOUNT (`-` for a
  # seat), GATE_ROUTE_CFG, GATE_ROUTE_MINTED and GATE_ROUTE_BIND. Called in the
  # dispatch's own shell, never in a substitution, because it sets those.
  #
  # THE ATTEMPT IS CLAIMED BEFORE THE ROUTER IS ASKED. Two dispatches of one
  # segment that derive the same number would ask for the same lineage and share
  # one lease; the exclusive create lets exactly one of them through. The claim
  # stays for the life of the run, as the consumed attempt it names.
  #
  # 0 on a grant. GATE_EXIT_ROUTE, with its row written, on a `WAIT`, a `PARK`
  # and a resume the binding does not allow — the binding is checked whatever
  # the envelope's basis. The guard record is compared by the caller, before
  # this, under either guard.
  local alias="$1" seg="$2" kind="$3" rowseg why event=first reqbind="" req prior verdict dormant
  GATE_ROUTE_ATTEMPT=""; GATE_ROUTE_LINEAGE=""; GATE_ROUTE_ENV=""; GATE_ROUTE_NONCE=""
  GATE_ROUTE_VERDICT=""; GATE_ROUTE_WHY=""; GATE_ROUTE_EVENT=""
  GATE_ROUTE_ACCOUNT="-"; GATE_ROUTE_CFG=""; GATE_ROUTE_MINTED=0; GATE_ROUTE_BIND=""
  rowseg=$(gate_stage_row_segment "$seg" "$kind")
  GATE_ROUTE_ATTEMPT=$(gate_derive_attempt "$seg")
  if ! ( set -C; : > "$RUN_DIR/$seg.attempt.$GATE_ROUTE_ATTEMPT" ) 2>/dev/null; then
    warn "attempt $GATE_ROUTE_ATTEMPT of $seg is already claimed by another dispatch — this one is refused"
    return "$GATE_EXIT_RULE"
  fi
  GATE_ROUTE_LINEAGE="$GATE_ROUTE_LINEAGE_HEAD$seg#$GATE_ROUTE_ATTEMPT"
  # A CARRY ASKS TWICE AND PICKS ONE, in a function of its own, so every other
  # dispatch below asks exactly as it did.
  if [ -n "${GATE_HA_LINE:-}" ] && [ -n "${GATE_CARRY_ANSWER:-}" ]; then
    gate_launch_route_carry "$alias" "$seg" "$kind" "$rowseg"
    return $?
  fi
  if [ -n "${GATE_RESUME:-}" ]; then
    event=resume
    GATE_ROUTE_BIND=$(gate_resume_binding_of "$seg" "$GATE_RESUME" 2>/dev/null) || GATE_ROUTE_BIND=""
    case "$GATE_ROUTE_BIND" in ''|-) ;; *) reqbind=$GATE_ROUTE_BIND ;; esac
  fi
  GATE_ROUTE_EVENT=$event
  req=$(jq -cn --arg run "$RUN_ID" --arg lin "$GATE_ROUTE_LINEAGE" --arg ev "$event" \
          --arg kind "$kind" --arg bound "$reqbind" --argjson pid "$$" \
          --argjson dl "$(wait_request_deadline "$kind")" \
          '{run_id: $run, lineage: $lin, event: $ev, kind: $kind, holders: [$pid],
            bound_account: (if $bound == "" then null else $bound end)}
           + (if $dl == null then {} else {deadline: $dl} end)') \
    || { warn "could not build the router request ($seg)"; return 1; }
  prior=$( { route_lease_of "$(run_pace_root)/leases" "$RUN_ID" "$GATE_ROUTE_LINEAGE" 2>/dev/null || true; } \
           | { jq -r '.nonce // empty' 2>/dev/null || true; })
  GATE_ROUTE_ENV=$(route_resolve "$req") || { warn "the account resolver stopped — $seg is not launched"; return 1; }
  verdict=$(printf '%s' "$GATE_ROUTE_ENV" | jq -r '.verdict // ""' 2>/dev/null || true)
  why=$(printf '%s' "$GATE_ROUTE_ENV" | jq -r '"라우터 판정 \(.verdict) \(.reason // "-")"
        + (if (.recovery // "") != "" then " — \(.recovery)" else "" end)' 2>/dev/null) \
    || why="라우터 판정 $verdict"
  GATE_ROUTE_VERDICT=$verdict
  GATE_ROUTE_WHY=$why
  case "$verdict" in
    GRANT) ;;
    WAIT)
      # THE FIRST HEARTBEAT IS WRITTEN HERE, synchronously, so the wait shows on
      # the ledger before this act returns; the caller turns the rest into a
      # supervisor that waits. A refused row leaves nothing to wait on.
      if ! gate_stage_wait_row "$GATE_ROUTE_LINEAGE" "$GATE_ROUTE_ENV" "$GATE_ROUTE_BIND"; then
        gate_launch_route_park "$alias" "$rowseg" "$seg" "$why (stage-wait 행 기록 거부)"
        return "$GATE_EXIT_ROUTE"
      fi
      return 0 ;;
    PARK)
      if [ "$(printf '%s' "$GATE_ROUTE_ENV" | jq -r '.reason // ""' 2>/dev/null || true)" = "deadline" ]; then
        gate_wait_deadline_park "$alias" "$rowseg" "$seg" "$GATE_ROUTE_LINEAGE" \
          "$(wait_epoch_iso "$(printf '%s' "$GATE_ROUTE_ENV" | jq -r '.ready_at | if type == "number" then floor | tostring else "" end' 2>/dev/null || true)")" \
          "계보=$GATE_ROUTE_LINEAGE 라우터 마감 판정" \
          "$(printf '%s' "$GATE_ROUTE_ENV" | jq -r '.recovery // ""' 2>/dev/null || true)" \
          "$(gate_redispatch_line "$alias" "$rowseg")"
      else
        gate_launch_route_park "$alias" "$rowseg" "$seg" "$why"
      fi
      return "$GATE_EXIT_ROUTE" ;;
    *) warn "the router answered without a verdict — $seg is not launched"; return 1 ;;
  esac
  GATE_ROUTE_NONCE=$(printf '%s' "$GATE_ROUTE_ENV" | jq -r '.nonce // empty')
  GATE_ROUTE_ACCOUNT=$(printf '%s' "$GATE_ROUTE_ENV" | jq -r '.account // "-"')
  GATE_ROUTE_CFG=$(printf '%s' "$GATE_ROUTE_ENV" | jq -r '.config_dir // empty')
  if [ -n "$GATE_ROUTE_NONCE" ] && [ "$GATE_ROUTE_NONCE" != "$prior" ]; then GATE_ROUTE_MINTED=1; fi
  if [ -z "$GATE_ROUTE_CFG" ]; then
    warn "the grant names no config directory — $seg is not launched"
    gate_launch_route_drop
    return 1
  fi
  if [ "$event" = "resume" ] && ! gate_resume_grant_ok "$GATE_ROUTE_BIND" "$GATE_ROUTE_ENV"; then
    dormant=$(printf '%s' "$GATE_ROUTE_ENV" | jq -r 'if .dormant == true then "1" else "0" end')
    if [ "$dormant" = "1" ] && [ -n "$GATE_ROUTE_BIND" ] && [ "$GATE_ROUTE_BIND" != "-" ]; then
      why="휴면 구속 — 세션 $GATE_RESUME 은 계정 $GATE_ROUTE_BIND 에 구속돼 있으나 라우터가 휴면 봉투를 냈다"
    else
      why="재부착 구속 불일치 — 구속 ${GATE_ROUTE_BIND:-(없음)}, 봉투 계정 $GATE_ROUTE_ACCOUNT"
    fi
    gate_launch_route_drop
    gate_launch_route_park "$alias" "$rowseg" "$seg" "$why"
    return "$GATE_EXIT_ROUTE"
  fi
  return 0
}

gate_launch_route_ask() {
  # gate_launch_route_ask <segment> <stage-kind> <event> <bound account or ""> —
  # one router question for this dispatch's lineage, the request built the way
  # `gate_launch_route` builds it. Prints the envelope.
  local seg="$1" kind="$2" event="$3" bound="$4" req
  req=$(jq -cn --arg run "$RUN_ID" --arg lin "$GATE_ROUTE_LINEAGE" --arg ev "$event" \
          --arg kind "$kind" --arg bound "$bound" --argjson pid "$$" \
          --argjson dl "$(wait_request_deadline "$kind")" \
          '{run_id: $run, lineage: $lin, event: $ev, kind: $kind, holders: [$pid],
            bound_account: (if $bound == "" then null else $bound end)}
           + (if $dl == null then {} else {deadline: $dl} end)') \
    || { warn "could not build the router request ($seg)"; return 1; }
  route_resolve "$req" || { warn "the account resolver stopped — $seg is not launched"; return 1; }
}

gate_launch_route_take() {
  # gate_launch_route_take <envelope> <prior nonce> — set the grant's globals
  # from <envelope>, the way `gate_launch_route` sets them after a grant.
  GATE_ROUTE_ENV=$1
  GATE_ROUTE_NONCE=$(printf '%s' "$1" | jq -r '.nonce // empty')
  GATE_ROUTE_ACCOUNT=$(printf '%s' "$1" | jq -r '.account // "-"')
  GATE_ROUTE_CFG=$(printf '%s' "$1" | jq -r '.config_dir // empty')
  GATE_ROUTE_MINTED=0
  if [ -n "$GATE_ROUTE_NONCE" ] && [ "$GATE_ROUTE_NONCE" != "$2" ]; then GATE_ROUTE_MINTED=1; fi
}

gate_launch_route_why() {
  # gate_launch_route_why <envelope> — the `라우터 판정 …` text of a verdict.
  printf '%s' "$1" | jq -r '"라우터 판정 \(.verdict) \(.reason // "-")"
        + (if (.recovery // "") != "" then " — \(.recovery)" else "" end)' 2>/dev/null \
    || printf '라우터 판정 %s' "$(printf '%s' "$1" | jq -r '.verdict // ""' 2>/dev/null)"
}

gate_launch_route_carry() {
  # gate_launch_route_carry <alias> <segment> <stage-kind> <row segment> — the
  # routing of a carry act, after the attempt is claimed. Leaves the same
  # globals `gate_launch_route` leaves, with GATE_RESUME set to the halted
  # session when the bound side is picked and emptied when the fresh side is.
  #
  # THE QUERY HALF asks the bound question when the key's halted attempt has a
  # session, and the fresh one (`event=first`) whenever the bound answer is not a
  # grant the binding allows. A bound grant the binding refuses (`재부착 구속
  # 불일치`, `휴면 구속`) hands its lease back here, before the fresh question —
  # put off, the minted lease would outlive the dispatch. A bound PARK for one of
  # the reasons only a bound resume can meet (`deadline`, `resume-unbound`,
  # `resume-bound-unknown-account`, `resume-bound-ineligible`,
  # `resume-logged-out`) goes on to the fresh question; any other bound PARK —
  # a run-wide or a configuration verdict — parks as today. A bound
  # `resume-bound-exhausted` WAIT whose `until` plus the stage's expected
  # duration lies past the run's deadline is read as a bound deadline PARK: it
  # is the one WAIT the router does not hold to the deadline.
  #
  # THE PICK takes the first of: the bound grant, a fresh grant (a seat grant
  # included), a bound WAIT with an `until`, a fresh WAIT with one, a bound WAIT
  # with none, a fresh WAIT with none — and with nothing left, when the fresh
  # side parked on the deadline, the `이월` row. A fresh PARK on any other reason
  # is a configuration a person fixes and parks as today. Every WAIT envelope
  # leaves no router state, and a fresh grant is always picked, so no envelope
  # left unpicked leaves a lease behind.
  #
  # THE COMMIT HALF sets the picked side's event, binding and envelope, and only
  # then writes the deadline or `stage-wait` row the picked verdict calls for.
  local alias="$1" seg="$2" kind="$3" rowseg="$4" bound="${GATE_HA_BOUND:-}"
  local bind="" reqbind="" benv="" bv="" bcls="none" bwhy="" breason="" buntil=""
  local fenv="" fv="" fcls="" freason="" funtil="" prior dormant pick obs
  if [ -n "$bound" ]; then
    bind=$(gate_resume_binding_of "$seg" "$bound" 2>/dev/null) || bind=""
    case "$bind" in ''|-) ;; *) reqbind=$bind ;; esac
    prior=$( { route_lease_of "$(run_pace_root)/leases" "$RUN_ID" "$GATE_ROUTE_LINEAGE" 2>/dev/null || true; } \
             | { jq -r '.nonce // empty' 2>/dev/null || true; })
    benv=$(gate_launch_route_ask "$seg" "$kind" resume "$reqbind") || return 1
    bv=$(printf '%s' "$benv" | jq -r '.verdict // ""' 2>/dev/null || true)
    breason=$(printf '%s' "$benv" | jq -r '.reason // ""' 2>/dev/null || true)
    bwhy=$(gate_launch_route_why "$benv")
    case "$bv" in
      GRANT)
        gate_launch_route_take "$benv" "$prior"
        if [ -z "$GATE_ROUTE_CFG" ]; then
          warn "the grant names no config directory — $seg is not launched"
          gate_launch_route_drop
          return 1
        fi
        if gate_resume_grant_ok "$bind" "$benv"; then
          bcls=grant
        else
          dormant=$(printf '%s' "$benv" | jq -r 'if .dormant == true then "1" else "0" end')
          if [ "$dormant" = "1" ] && [ -n "$bind" ] && [ "$bind" != "-" ]; then
            bwhy="휴면 구속 — 세션 $bound 은 계정 $bind 에 구속돼 있으나 라우터가 휴면 봉투를 냈다"
          else
            bwhy="재부착 구속 불일치 — 구속 ${bind:-(없음)}, 봉투 계정 $GATE_ROUTE_ACCOUNT"
          fi
          gate_launch_route_drop
          bcls=fall
        fi ;;
      WAIT)
        buntil=$(printf '%s' "$benv" | jq -r '.until_epoch | if type == "number" then floor | tostring else "" end' 2>/dev/null || true)
        # Held to the deadline the way the router holds every other WAIT
        # (`rt_past_deadline`): a release that cannot finish its expected
        # duration before the deadline does not fit, however early it opens.
        if [ "$breason" = "resume-bound-exhausted" ] && [ -n "$buntil" ] \
           && wait_past_deadline "$buntil" "$(stage_expected_duration "$kind")"; then
          bcls=fall
          bwhy="$bwhy — 마감 뒤에 열리는 묶인 대기라 마감 PARK 로 다룬다"
        elif [ -n "$buntil" ]; then
          bcls=wait-until
        else
          bcls=wait-open
        fi ;;
      PARK)
        case "$breason" in
          deadline|resume-unbound|resume-bound-unknown-account|resume-bound-ineligible|resume-logged-out) bcls=fall ;;
          *) bcls=stop ;;
        esac ;;
      *) warn "the router answered without a verdict — $seg is not launched"; return 1 ;;
    esac
  else
    bwhy="재부착할 세션 없음"
  fi
  if [ "$bcls" = "grant" ]; then
    GATE_RESUME=$bound; GATE_ROUTE_EVENT=resume; GATE_ROUTE_BIND=$bind
    GATE_ROUTE_VERDICT=GRANT; GATE_ROUTE_WHY=$bwhy
    log "중단 답 운반 — $seg ← 묶인 세션 $bound 재부착"
    return 0
  fi
  if [ "$bcls" = "stop" ]; then
    GATE_ROUTE_EVENT=resume; GATE_ROUTE_BIND=$bind; GATE_ROUTE_ENV=$benv
    GATE_ROUTE_VERDICT=PARK; GATE_ROUTE_WHY=$bwhy
    gate_launch_route_park "$alias" "$rowseg" "$seg" "$bwhy"
    return "$GATE_EXIT_ROUTE"
  fi
  prior=$( { route_lease_of "$(run_pace_root)/leases" "$RUN_ID" "$GATE_ROUTE_LINEAGE" 2>/dev/null || true; } \
           | { jq -r '.nonce // empty' 2>/dev/null || true; })
  fenv=$(gate_launch_route_ask "$seg" "$kind" first "") || return 1
  fv=$(printf '%s' "$fenv" | jq -r '.verdict // ""' 2>/dev/null || true)
  freason=$(printf '%s' "$fenv" | jq -r '.reason // ""' 2>/dev/null || true)
  case "$fv" in
    GRANT) fcls=grant ;;
    WAIT)
      funtil=$(printf '%s' "$fenv" | jq -r '.until_epoch | if type == "number" then floor | tostring else "" end' 2>/dev/null || true)
      if [ -n "$funtil" ]; then fcls=wait-until; else fcls=wait-open; fi ;;
    PARK)
      if [ "$freason" = "deadline" ]; then fcls=fall; else fcls=stop; fi ;;
    *) warn "the router answered without a verdict — $seg is not launched"; return 1 ;;
  esac
  if [ "$fcls" = "grant" ]; then pick=fresh
  elif [ "$bcls" = "wait-until" ]; then pick=bound
  elif [ "$fcls" = "wait-until" ]; then pick=fresh
  elif [ "$bcls" = "wait-open" ]; then pick=bound
  elif [ "$fcls" = "wait-open" ]; then pick=fresh
  elif [ "$fcls" = "fall" ]; then pick=defer
  else pick=stop
  fi
  case "$pick" in
    bound)
      GATE_RESUME=$bound; GATE_ROUTE_EVENT=resume; GATE_ROUTE_BIND=$bind; GATE_ROUTE_ENV=$benv
      GATE_ROUTE_VERDICT=WAIT; GATE_ROUTE_WHY=$bwhy
      if ! gate_stage_wait_row "$GATE_ROUTE_LINEAGE" "$benv" "$bind" "$GATE_HA_LINE"; then
        gate_launch_route_park "$alias" "$rowseg" "$seg" "$bwhy (stage-wait 행 기록 거부)"
        return "$GATE_EXIT_ROUTE"
      fi
      log "중단 답 운반 — $seg 는 묶인 세션 $bound 의 계정을 기다린다"
      return 0 ;;
    fresh)
      GATE_RESUME=""; GATE_ROUTE_EVENT=first; GATE_ROUTE_BIND=-
      GATE_ROUTE_VERDICT=$fv; GATE_ROUTE_WHY=$(gate_launch_route_why "$fenv")
      if [ "$fv" = "GRANT" ]; then
        gate_launch_route_take "$fenv" "$prior"
        if [ -z "$GATE_ROUTE_CFG" ]; then
          warn "the grant names no config directory — $seg is not launched"
          gate_launch_route_drop
          return 1
        fi
        log "중단 답 운반 — $seg 를 새 세션으로 파견한다 ($bwhy)"
        return 0
      fi
      GATE_ROUTE_ENV=$fenv
      if ! gate_stage_wait_row "$GATE_ROUTE_LINEAGE" "$fenv" "-" "$GATE_HA_LINE"; then
        gate_launch_route_park "$alias" "$rowseg" "$seg" "$GATE_ROUTE_WHY (stage-wait 행 기록 거부)"
        return "$GATE_EXIT_ROUTE"
      fi
      log "중단 답 운반 — $seg 는 새 세션의 계정을 기다린다 ($bwhy)"
      return 0 ;;
    defer)
      GATE_ROUTE_EVENT=first; GATE_ROUTE_BIND=-; GATE_ROUTE_ENV=$fenv
      GATE_ROUTE_VERDICT=PARK; GATE_ROUTE_WHY=$(gate_launch_route_why "$fenv")
      obs="묶인 판정: ${bv:-없음} ${breason:--} ($bwhy) · 새 판정: PARK deadline ready_at $(wait_epoch_iso "$(printf '%s' "$fenv" | jq -r '.ready_at | if type == "number" then floor | tostring else "" end' 2>/dev/null || true)")"
      gate_carry_defer_row "$alias" "$rowseg" "$seg" "$GATE_ROUTE_LINEAGE" "$GATE_HA_LINE" "$obs"
      return "$GATE_EXIT_ROUTE" ;;
  esac
  GATE_ROUTE_EVENT=first; GATE_ROUTE_BIND=-; GATE_ROUTE_ENV=$fenv
  GATE_ROUTE_VERDICT=$fv; GATE_ROUTE_WHY=$(gate_launch_route_why "$fenv")
  gate_launch_route_park "$alias" "$rowseg" "$seg" "$GATE_ROUTE_WHY"
  return "$GATE_EXIT_ROUTE"
}

gate_launch_wait() {
  # gate_launch_wait <alias> <key> <stage-kind> <cli args...> — the dispatch
  # half of a routed launch the router answered WAIT. The first `stage-wait`
  # row is already on the ledger. Pins the claimed attempt, writes a wait token,
  # starts the supervisor that waits, and leaves the marker and the FIFO entry
  # before returning 0 — the act's per-key dispatch lock is released only after
  # this returns, and the supervisor reads the marker only after that, so it
  # never meets a half-written one.
  #
  # Every refusal here comes BEFORE the pin, as on the grant path, so a host
  # state a person has to change does not consume an attempt.
  local alias="$1" seg="$2" kind="$3"; shift 3
  local rowseg stall instr rrc=0 attempt out suplog nonce tmp sup grp upto rec wnonce m
  rowseg=$(gate_stage_row_segment "$seg" "$kind")
  # WITHOUT A READABLE STALL THRESHOLD THERE IS NO CHUNK TO WAIT IN, and the
  # wait falls back to what a WAIT did before it could be waited on.
  if ! stall=$(cc_effective_stall "$RUN_DIR"); then
    warn "$GATE_ROUTE_WHY — the effective stall threshold cannot be read, so $seg does not wait and is not launched"
    return "$GATE_EXIT_ROUTE"
  fi
  # A TRIAL SYNTHESIS in the environment this act runs in: the account is not
  # known yet, and the supervisor synthesizes again under the one it is granted.
  instr=$(gate_stage_instructions_for_launch "$alias" "${GATE_RESUME:-}") || return $?
  if [ -n "${GATE_RESUME:-}" ]; then
    gate_continuation_argv "$seg" "$kind" "$@" || return $?
    [ -z "$GATE_CONTINUED" ] || set -- "${GATE_CONTINUE_ARGV[@]}"
  fi
  attempt=$(gate_pin_attempt "$seg" "$GATE_ROUTE_ATTEMPT")
  if [ -n "${GATE_HA_CARD_LINE:-}" ] && ! gate_halt_card_write "$seg#$attempt" "$GATE_HA_CARD_LINE"; then
    warn "the answer card could not be written — $seg does not wait and is not launched"
    return "$GATE_EXIT_RULE"
  fi
  out=$(stage_log_path "$seg")
  suplog="${out%.json}.sup.log"
  mkdir -p "$RUN_DIR/log"
  rm -f "$RUN_DIR/$seg.launch.taken"
  nonce=$(od -An -N16 -tx1 /dev/urandom | tr -d ' \n')
  [ -n "$nonce" ] || { warn "could not create the launch nonce ($seg)"; return 1; }
  # THE WAIT TOKEN: the three lines every token has (the instructions line is
  # empty — the supervisor synthesizes after its grant), then the word `wait`,
  # the lineage, the event the router was asked with, and the binding.
  tmp=$(mktemp "$RUN_DIR/.launch.$seg.XXXXXX")
  printf '%s\n%s\n%s\n%s\n%s\n%s\n%s\n' "$nonce" "${GATE_RESUME:-}" "" wait \
    "$GATE_ROUTE_LINEAGE" "${GATE_ROUTE_EVENT:-first}" "${GATE_ROUTE_BIND:--}" > "$tmp"
  mv "$tmp" "$RUN_DIR/$seg.launch"
  sup=$( cc_detach_exec "$suplog" "$suplog" \
           env CC_CLAUDE_BIN="$CLI_BIN" \
           bash "$GATE_DIR/gate.sh" supervise-stage --manifest "$MANIFEST" \
             --target "$alias" --segment "$seg" --nonce "$nonce" -- "$kind" "$@" )
  if [ -z "$sup" ]; then
    warn "the waiting supervisor failed to start ($seg) — the launch token is withdrawn"
    rm -f "$RUN_DIR/$seg.launch"
    return 1
  fi
  printf '%s\n' "$sup" > "$RUN_DIR/$seg.sup"
  cc_proc_fingerprint "$sup" > "$RUN_DIR/$seg.sup.start"
  grp=$(printf '%s' "$GATE_ROUTE_ENV" | jq -r '.group // "-"' 2>/dev/null || printf '%s' '-')
  upto=$(printf '%s' "$GATE_ROUTE_ENV" | jq -r '.until_epoch | if type == "number" then floor | tostring else "-" end' 2>/dev/null || printf '%s' '-')
  # THE FIFO ENTRY IS HELD BY THE SUPERVISOR, never by this act: the act ends in
  # a moment, and an entry held by a dead pid is filtered out on arrival. The
  # group goes in through a representative account, because an organisation
  # group's WAIT names no account. No account to represent it leaves no entry.
  wnonce="-"
  if [ "$grp" != "-" ]; then
    rrc=0
    rec=$(route_lease_wait_put --table "$(run_pace_root)/leases" --now "$(now_epoch)" --run-id "$RUN_ID" \
            --lineage "$GATE_ROUTE_LINEAGE" --group "$grp" --inventory "$RUN_DIR/inventory.json" \
            --holder "$sup" 2>/dev/null) || rrc=$?
    if [ "$rrc" = "0" ]; then
      wnonce=$(printf '%s' "$rec" | jq -r '.nonce // "-"' 2>/dev/null || printf '%s' '-')
    else
      log "대기 항목을 FIFO 에 넣지 못했습니다 rc=$rrc — $seg#$attempt ($GATE_ROUTE_LINEAGE)"
    fi
  fi
  m="$RUN_DIR/$seg.waiting"
  if ! wait_marker_write "$m" "보유자=$sup" "지문=$(cc_proc_fingerprint "$sup")" "기록자=게이트" \
         "계보=$GATE_ROUTE_LINEAGE" "그룹=$grp" "까지=$upto" "갱신=$(now_epoch)" "종류=$kind" \
         "논스=$wnonce" "시도=$attempt" "재파견=$(gate_redispatch_line "$alias" "$rowseg")" \
         "$(wait_seen_kv "$GATE_ROUTE_ENV")"; then
    warn "could not write the waiting marker ($seg) — the waiting supervisor ends on its own"
    [ "$wnonce" = "-" ] || route_lease_wait_drop "$(run_pace_root)/leases" "$RUN_ID" "$GATE_ROUTE_LINEAGE" "$wnonce" >/dev/null 2>&1 || true
    return 1
  fi
  log "스테이지 파견 — $seg#$attempt (감독자 $sup, 대기 중 — 그룹 $grp, 까지 $(wait_epoch_iso "$upto"))"
  return 0
}

# The waiting supervisor's four callbacks for `stage_wait_loop`. They read the
# dispatch they belong to from GATE_SUP_* globals the supervisor sets.
gate_sup_wait_heartbeat() {
  gate_stage_wait_row "$GATE_SUP_LINEAGE" "$1" "$GATE_SUP_BIND" "${GATE_SUP_CARRY:-}"
}

gate_sup_wait_deadline() {
  # <ready-at iso> <basis> <recovery>
  #
  # An attempt that waited holding a person's answer keeps the answer for the
  # next run: the `이월` row with the card's line, not the deadline row.
  if [ -n "${GATE_SUP_CARRY:-}" ]; then
    gate_carry_defer_row "$GATE_SUP_ALIAS" "$GATE_SUP_ROWSEG" "$GATE_SUP_KEY" "$GATE_SUP_LINEAGE" \
      "$GATE_SUP_CARRY" "$(gate_row_safe "$2" 200) ready_at=$1"
    return 0
  fi
  gate_wait_deadline_park "$GATE_SUP_ALIAS" "$GATE_SUP_ROWSEG" "$GATE_SUP_KEY" "$GATE_SUP_LINEAGE" \
    "$1" "$2" "$3" "$(cc_waiting_field "$GATE_SUP_MARKER" '재파견')"
}

gate_sup_wait_stop() {
  gate_launch_route_park "$GATE_SUP_ALIAS" "$GATE_SUP_ROWSEG" "$GATE_SUP_KEY" "$1" "$GATE_SUP_LINEAGE"
}

gate_sup_wait_ended() {
  # The same run-end refusal the act prelude applies to a dispatch, read again
  # because this supervisor passed that prelude once, before its wait began.
  gate_run_ended_ok skill -
}

gate_sup_await_dispatch() {
  # gate_sup_await_dispatch <key> — wait until the act that started this
  # supervisor has released its dispatch lock: until then the marker, the FIFO
  # entry and the redispatch line may not exist yet. A lock whose holder is dead
  # is released for this purpose too.
  local key="$1" f
  f="$RUN_DIR/$key.dispatching"
  while [ -f "$f" ]; do
    gate_dispatch_lock_holder_live "$f" || return 0
    sleep 0.2
  done
  return 0
}

gate_launch_stage() {
  # gate_launch_stage <alias> <segment> <stage-kind> <cli args...>
  #
  # The wrapper's only legitimate caller, stated in one place. It is an argv
  # laundering tool for whoever holds an allow-list entry, so the set of callers
  # is a design commitment rather than an accident — and this is it.
  local alias="$1" seg="$2" kind="$3"; shift 3
  local wrapper="$GATE_DIR/stage-wrapper.sh"
  [ -f "$wrapper" ] || { warn "the stage wrapper is missing: $wrapper"; return 127; }

  # RE-ATTACH, NOT RE-RUN. The contract already says a stage cut mid-flight is
  # continued rather than restarted, and the wrapper already accepts `--resume`
  # — nothing carried the router's intent to it, so the only recovery available
  # was a full re-run. Measured: a review stage died to a machine sleep after
  # 1h53m and 51.84 USD with all five reviewers' output on disk and only the
  # synthesis missing; re-running would have paid for the whole thing again.
  #
  # The session id is CHECKED against this run's own ledger, not taken on trust.
  # A resume is an instruction to continue somebody's transcript, so an
  # unchecked value would let one segment continue another segment's — or
  # another run's — session. It must appear as the `세션 id` of a `stage-result`
  # row for THIS segment.
  #
  # Validated HERE, before the CLI binary is resolved. Resolving first makes
  # "the binary is missing" mask "the argv is wrong", which is the same defect
  # the wrapper already had and had fixed: a host without the CLI answered 127
  # to a bad resume id and the refusal never named the real fault.
  if [ -n "${GATE_RESUME:-}" ]; then
    local known
    known=$( gate_stage_result_rows_of "$seg" \
             | { grep -cF "세션 id=$GATE_RESUME " || true; } )
    if [ "${known:-0}" = "0" ]; then
      warn "the session to resume is not in the ledger record of this segment: $GATE_RESUME"
      return "$GATE_EXIT_VOCAB"
    fi
  fi

  # `bash`, not `/bin/sh`. The wrapper declares `#!/usr/bin/env bash` and uses
  # `set -o pipefail`, and naming an interpreter on the command line OVERRIDES
  # the shebang — so on a distribution whose `/bin/sh` is dash the wrapper died
  # at its second line with "Illegal option -o pipefail", taking every stage
  # launch with it. macOS hid this because its `/bin/sh` is bash.
  #
  # `CC_CLAUDE_BIN` is HANDED DOWN rather than re-resolved. run.sh resolves the
  # binary and only then pins PATH to the sanitized set, so a child that looks
  # it up again searches a PATH the CLI is not on — and the wrapper's hard stop
  # then reports "binary not found" for a run whose binary was found two
  # seconds earlier. Every stage launch failed that way, with the gate's own
  # sanitization as the cause.
  [ -n "${CLI_BIN:-}" ] || { warn "the gate could not resolve the CLI binary"; return 127; }

  # THE ATTEMPT NUMBER, derived rather than passed. The session id is a function
  # of run, segment and attempt, and the caller was leaving the attempt at its
  # default — so the id was a function of run and segment alone. A stage that
  # died before producing anything had already taken that id, and every retry of
  # the same segment was refused by the CLI with "Session ID ... is already in
  # use". Dying is not an exotic path: the contract itself lists the terminal
  # closing, Ctrl+C, the token limit, the network dropping and a reboot, and all
  # five are written as "retry".
  #
  # The failure was worse than a refusal because it happened AFTER the gate
  # passed and after the row was appended — so the ledger showed the segment
  # attempted twice with nothing to show for either, and the cause lived in one
  # line of the CLI's stdout.
  #
  # Derived from the ledger and NOT taken as argv: adding an `--attempt` flag
  # would let a router re-type the number it used last time, which reproduces the
  # collision through the one surface that is supposed to prevent it. The
  # derivation and the pin both sit behind `gate_pin_attempt` so a test can burn
  # them. The pin is written HERE, in the dispatch half, and the supervisor only
  # reads it — one writer, so the two halves cannot disagree about the attempt.
  #
  # THE DISPATCH RETURNS AT ONCE. What used to follow here — the wrapper launch,
  # the pid record, the `wait`, the outcome row — now runs in a SUPERVISOR whose
  # lineage is cut from this process (`cc_detach_exec`), because the routing
  # session that issues this act ends for reasons of its own (cap, approval,
  # crash) and the harness reaps that session's descendants. Measured: a stage
  # dispatched from a shift died with the shift, and since the row was written
  # after the `wait` in this same function, the ledger showed no stage at all.
  #
  # The supervisor is `gate.sh supervise-stage`, a re-entry of this file rather
  # than a second script, so `MANIFEST`/`RUN_DIR`/`LEDGER` are derived once by
  # the same prelude every verb passes. What crosses the process boundary is
  # argv only: the manifest, the target, the segment, a one-shot nonce, and the
  # CLI argv after `--`.
  #
  # THE LAUNCH TOKEN. A verb that starts a stage with no authorization row and
  # no boundary evaluation is an authorization bypass if a router can spell it.
  # So the dispatch writes `<seg>.launch` (line 1 the nonce, line 2 the resume
  # id or empty, line 3 the instructions file or empty for legacy mode) and the
  # supervisor CONSUMES it with `mv -n` and compares the
  # nonce; a second caller cannot take a consumed token. A stale
  # `<seg>.launch.taken` from the previous attempt — that attempt has already
  # terminated, settled or been refused — is removed first, because `mv -n`
  # would otherwise never move the new token.
  #
  # The return value of this act is now LAUNCH success, not the stage's rc. A
  # caller that wants the rc issues `gate.sh wait --segment <id>`.
  if ! command -v perl >/dev/null 2>&1 && ! command -v python3 >/dev/null 2>&1; then
    warn "there is no interpreter (perl or python3) to launch the supervisor — the dispatch is refused ($seg)"
    return "$GATE_EXIT_RULE"
  fi
  # ROUTING ON: THE ROUTER IS ASKED BEFORE ANYTHING IS SYNTHESIZED OR PINNED.
  # The instructions are synthesized against the directory the grant names, so
  # the grant has to exist first; a `WAIT` or `PARK` stops here with no pin, so
  # the recovery rule that reads "a pin and no row" as a consumed attempt is
  # untouched. Every exit below that refuses after the grant hands back the
  # lease this dispatch minted. Routing off asks nothing and inherits the
  # environment, as before.
  # THE GUARD RECORD IS CHECKED ON EVERY LAUNCH. A routed record with no regular
  # baseline is refused; with no record this passes without a word, which is
  # today's launch.
  local routed=0 rrc=0 gwhy
  if ! gwhy=$(routing_guard_check); then
    gate_launch_route_park "$alias" "$(gate_stage_row_segment "$seg" "$kind")" "$seg" "$gwhy"
    return "$GATE_EXIT_ROUTE"
  fi
  # THE ANSWER CARD THIS ATTEMPT GETS: the carried answer's, or — when the key's
  # last attempt carried one and crashed, ran into a limit or was ended from
  # outside — that answer's again, since the attempt may have died holding it.
  GATE_HA_CARD_LINE=${GATE_HA_LINE:-}
  [ -n "$GATE_HA_CARD_LINE" ] || GATE_HA_CARD_LINE=$(gate_halt_card_crash_line "$seg")
  if run_routed; then
    routed=1
    gate_launch_route "$alias" "$seg" "$kind" "$@" || return $?
    # A CARRY THAT PICKED THE HALTED SESSION re-attaches it with the fixed resume
    # sentence, not the dispatch form, and a waiting one wakes up with the same:
    # the session already holds its question, and the card holds the answer.
    if [ -n "${GATE_HA_LINE:-}" ] && [ -n "${GATE_RESUME:-}" ]; then
      local ha_argv=() ha_p=0
      while [ "$#" -gt 0 ]; do
        if [ "$1" = "-p" ] && [ "$#" -ge 2 ]; then
          ha_argv+=(-p "$GATE_CARRY_RESUME_MESSAGE"); shift 2; ha_p=1
        else
          ha_argv+=("$1"); shift
        fi
      done
      [ "$ha_p" = "1" ] || ha_argv+=(-p "$GATE_CARRY_RESUME_MESSAGE")
      set -- "${ha_argv[@]}"
    fi
    # A WAIT IS NOT A STOP: the dispatch half pins, starts a supervisor that
    # waits for an account before it spawns, and returns.
    if [ "$GATE_ROUTE_VERDICT" = "WAIT" ]; then
      gate_launch_wait "$alias" "$seg" "$kind" "$@"
      return $?
    fi
  fi
  # THE STAGE INSTRUCTIONS, SYNTHESIZED BEFORE ANY SIDE EFFECT. A refusal here
  # (127, like a missing wrapper) is a launch precondition — a host or
  # repository state a person has to change — so it must not consume an
  # attempt number or leave a session record behind: the pin below and the
  # record after it both come later on purpose.
  local instr
  if [ "$routed" = "1" ]; then
    instr=$(CLAUDE_CONFIG_DIR="$GATE_ROUTE_CFG" gate_stage_instructions_for_launch "$alias" "${GATE_RESUME:-}") \
      || { rrc=$?; gate_launch_route_drop; return "$rrc"; }
  else
    instr=$(gate_stage_instructions_for_launch "$alias" "${GATE_RESUME:-}") || return $?
  fi
  # A RESUME OF A STAGE THAT ENDED IN PROSE carries the continue message instead
  # of the router's prompt, and is refused here — still before the pin — when it
  # may not be continued.
  if [ -n "${GATE_RESUME:-}" ]; then
    gate_continuation_argv "$seg" "$kind" "$@" || { rrc=$?; [ "$routed" = "0" ] || gate_launch_route_drop; return "$rrc"; }
    [ -z "$GATE_CONTINUED" ] || set -- "${GATE_CONTINUE_ARGV[@]}"
  fi
  local attempt out suplog nonce tmp sup
  if [ "$routed" = "1" ]; then
    # THE PIN IS THE ATTEMPT THE LINEAGE WAS ASKED FOR, taken as claimed.
    attempt=$(gate_pin_attempt "$seg" "$GATE_ROUTE_ATTEMPT")
  else
    attempt=$(gate_pin_attempt "$seg")
  fi
  if [ -n "$GATE_HA_CARD_LINE" ] && ! gate_halt_card_write "$seg#$attempt" "$GATE_HA_CARD_LINE"; then
    warn "the answer card could not be written — $seg is not launched"
    [ "$routed" = "0" ] || gate_launch_route_drop
    return "$GATE_EXIT_RULE"
  fi
  if [ "$routed" = "1" ]; then
    # ONE ROW PER GRANT, A SEAT OR DORMANT GRANT INCLUDED, after every step
    # likely to refuse: a row written before a refusal is a lease row nothing
    # closes. The dispatch id is the lineage string itself, so the row's
    # derived `계보` is the lease's.
    gate_stage_lease_row "$GATE_ROUTE_LINEAGE" "$GATE_ROUTE_ENV" "$GATE_ROUTE_BIND" || {
      rrc=$?
      warn "the \`stage-lease\` row was refused (rc=$rrc) — $seg is not launched"
      gate_launch_route_drop
      return "$GATE_EXIT_RULE"
    }
  fi
  if [ -z "${GATE_RESUME:-}" ] && [ -n "$instr" ]; then
    gate_stage_instructions_record "$(session_uuid "$seg" "$attempt")" "$instr"
  fi
  # THE STREAM IS SCOPED BY ATTEMPT; the supervisor derives the same name from
  # the same pin through `stage_log_path`, so the supervisor's own log sits
  # beside the stage's stream under the same attempt.
  out=$(stage_log_path "$seg")
  suplog="${out%.json}.sup.log"
  mkdir -p "$RUN_DIR/log"
  rm -f "$RUN_DIR/$seg.launch.taken"
  nonce=$(od -An -N16 -tx1 /dev/urandom | tr -d ' \n')
  [ -n "$nonce" ] || {
    warn "could not create the launch nonce ($seg)"
    [ "$routed" = "0" ] || gate_launch_route_drop
    return 1
  }
  tmp=$(mktemp "$RUN_DIR/.launch.$seg.XXXXXX")
  printf '%s\n%s\n%s\n' "$nonce" "${GATE_RESUME:-}" "$instr" > "$tmp"
  # ROUTING ON ADDS FOUR LINES, after the three the supervisor reads by
  # position: the lineage, the lease nonce (`-` with none), the account (`-` for
  # a seat) and the config directory. The supervisor is started after this and
  # cannot ask; everything it needs crosses here.
  if [ "$routed" = "1" ]; then
    printf '%s\n%s\n%s\n%s\n' "$GATE_ROUTE_LINEAGE" "${GATE_ROUTE_NONCE:--}" \
      "$GATE_ROUTE_ACCOUNT" "$GATE_ROUTE_CFG" >> "$tmp"
  fi
  mv "$tmp" "$RUN_DIR/$seg.launch"
  # THE SUPERVISOR'S PID COMES FROM THE COMMAND SUBSTITUTION AND NEVER FROM
  # `$!`. After a double fork `$!` names the middle process, already dead; the
  # helper prints the grandchild's pid and returns when the middle exits, which
  # is the moment the grandchild is adopted — so there is no window in which
  # this side holds a pid that is not yet orphaned. `CC_CLAUDE_BIN` rides on
  # `env` in the detached argv so the re-entered gate resolves the same binary
  # this one did rather than searching a PATH the CLI is not on — through `env`
  # and not an assignment here, because the test harness holds that name as a
  # top-level global and an in-process source of this file would overwrite it.
  sup=$( cc_detach_exec "$suplog" "$suplog" \
           env CC_CLAUDE_BIN="$CLI_BIN" \
           bash "$GATE_DIR/gate.sh" supervise-stage --manifest "$MANIFEST" \
             --target "$alias" --segment "$seg" --nonce "$nonce" -- "$kind" "$@" )
  if [ -z "$sup" ]; then
    warn "the supervisor failed to start ($seg) — the launch token is withdrawn"
    rm -f "$RUN_DIR/$seg.launch"
    [ "$routed" = "0" ] || gate_launch_route_drop
    return 1
  fi
  # THE SUPERVISOR JOINS THE LEASE'S HOLDERS, because this act returns at once
  # and its own pid stops counting the moment it does. Not fatal: the supervisor
  # holds itself before it launches anything, and a supervisor already gone is
  # refused as a holder — both are logged and nothing else.
  if [ "$routed" = "1" ] && [ -n "$GATE_ROUTE_NONCE" ]; then
    rrc=0
    route_lease_hold "$(run_pace_root)/leases" "$RUN_ID" "$GATE_ROUTE_LINEAGE" "$GATE_ROUTE_NONCE" "$sup" >/dev/null 2>&1 || rrc=$?
    [ "$rrc" = "0" ] || log "감독자 임대 보유 rc=$rrc — $seg#$attempt ($GATE_ROUTE_LINEAGE)"
  fi
  # `.sup` and `.sup.start` are the SUPERVISOR's identity, written by this side
  # because the supervisor cannot know its own pid before it exists. The
  # fingerprint goes through `cc_proc_fingerprint` and nothing else: a hand-
  # spelled `ps -o lstart=` leaves the padding `ps` adds, the compare fails
  # every time, and the orphan predicate quietly reads "no supervisor".
  printf '%s\n' "$sup" > "$RUN_DIR/$seg.sup"
  cc_proc_fingerprint "$sup" > "$RUN_DIR/$seg.sup.start"
  # A COURTESY WAIT FOR `<seg>.pid`, NOT A GATE. The supervisor writes the pid
  # record within milliseconds of consuming the token; giving it up to five
  # seconds makes the snapshot taken right after this act deterministic (the
  # stage is in `live_stages[]`), and a record that has not appeared by then is
  # logged, not failed — the supervisor's outcome is the ledger's to report.
  local waited=0
  while [ ! -f "$RUN_DIR/$seg.pid" ] && [ "$waited" -lt 25 ]; do
    sleep 0.2; waited=$((waited + 1))
  done
  if [ -f "$RUN_DIR/$seg.pid" ]; then
    log "스테이지 파견 — $seg#$attempt (감독자 $sup, pid $(cat "$RUN_DIR/$seg.pid" 2>/dev/null || printf '?'))"
  else
    log "스테이지 파견 — $seg#$attempt (감독자 $sup, pid 기록은 아직 없음 — wait 이 원장으로 판정합니다)"
  fi
  return 0
}

gate_sup_halt_hold_put() {
  # gate_sup_halt_hold_put <segment> <attempt> <lineage> <account> <config dir>
  #
  # THE HOLD RECORD OF A STAGE THAT STOPPED ON A QUESTION, written by the
  # supervisor after the terminal row and before the lease goes back. Once the
  # lease is gone the session's binding lives only in the ledger row, which
  # cc-lane does not read, and a borrow tick a few seconds later would take the
  # account as an idle donor. The record beside the lease table is what pushes
  # that group to the back of the donor ranking until the same key's next
  # attempt is spawned or the run ends.
  #
  # It is written only for this attempt's own `의도된 park` row, on an account
  # and a session id the ledger accepts. Always rc 0: a failed write warns, and
  # the caller's release goes on.
  local seg="$1" attempt="$2" lineage="$3" acct="$4" cfg="$5" row sid rc=0
  row=$( gate_stage_result_rows_of "$seg" | { grep -F "실행 버전=$attempt " || true; } | tail -1 ) || row=""
  [ -n "$row" ] || return 0
  [ "$(gate_row_field "$row" '종단 부류')" = "의도된 park" ] || return 0
  run_ledger_account_ok "$acct" || return 0
  sid=$(gate_row_field "$row" '세션 id')
  run_session_id_shape_ok "$sid" || return 0
  route_halt_hold_put --table "$(run_pace_root)/leases" --run-id "$RUN_ID" --key "$seg" \
    --lineage "$lineage" --account "$acct" --config-dir "$cfg" --session-id "$sid" \
    --run-dir "$RUN_DIR" --halted-at "$(date -u +%s)" || rc=$?
  [ "$rc" = "0" ] || warn "the hold record of the stopped stage was not written (rc=$rc, $seg#$attempt) — the lease is released all the same"
  return 0
}

gate_verb_supervise_stage() {
  # gate_verb_supervise_stage <alias> <segment> <nonce> <stage-kind> <cli args...>
  #
  # THE DETACHED HALF OF A DISPATCH. Runs under init, not under the routing
  # session, so the routing session's end cannot reach it. Everything it needs
  # it re-derives through the same prelude every other verb passes; the values
  # it cannot re-derive — the resume id and the proof that a dispatch act
  # actually authorised this launch — arrive through the launch token.
  #
  # THIS VERB CALLS `gate_boundaries` ON NOTHING AND WRITES NO `자율 승인` ROW.
  # The dispatch act already wrote the authorization row and evaluated the
  # boundaries; this is the performing half of that same act, split across a
  # process boundary. Its only ledger write is the `stage-result` row.
  local alias="$1" seg="$2" nonce="$3" kind="$4"; shift 4
  local wrapper="$GATE_DIR/stage-wrapper.sh"
  [ -f "$wrapper" ] || { warn "the stage wrapper is missing: $wrapper"; return 127; }
  [ -n "${CLI_BIN:-}" ] || { warn "the gate could not resolve the CLI binary"; return 127; }

  # CONSUME THE TOKEN FIRST, AND ONLY THIS CALL'S OWN MOVE COUNTS. The token is
  # moved with `mv -n` to a name no other process uses, so the move's exit
  # status says whether THIS call took it: a rename is exclusive on its source,
  # so of two callers exactly one succeeds and the other finds the source gone.
  # Testing for `.launch.taken` afterwards is a different question, and the
  # wrong one — that file stays for the stage's whole life, so a second caller
  # holding the nonce (it is readable in the run directory) found it and
  # started a second supervisor beside the first. Measured on a fixture before
  # this repair. A nonce that differs from the one on this argv was written for
  # a different launch and is refused too; the refused call has still spent the
  # token, so it cannot be retried into a launch.
  local taken="$RUN_DIR/$seg.launch.taken" mine="$RUN_DIR/$seg.launch.taken.$$" got resume
  if ! mv -n "$RUN_DIR/$seg.launch" "$mine" 2>/dev/null || [ ! -f "$mine" ]; then
    warn "the launch token is missing or already consumed ($seg) — the supervisor is not started"
    return "$GATE_EXIT_RULE"
  fi
  mv -f "$mine" "$taken"
  got=$(sed -n '1p' "$taken" 2>/dev/null | tr -d '[:space:]')
  if [ -z "$got" ] || [ "$got" != "$nonce" ]; then
    warn "the launch nonce differs from the token ($seg) — the supervisor is not started"
    return "$GATE_EXIT_RULE"
  fi
  resume=$(sed -n '2p' "$taken" 2>/dev/null | tr -d '[:space:]')
  # The instructions file rides on the token's third line: the dispatch half
  # synthesized it (and refused before pinning an attempt if it could not), so
  # the supervisor passes it through rather than deriving it again. It is a
  # path, so no whitespace stripping; empty means legacy mode.
  local instr
  instr=$(sed -n '3p' "$taken" 2>/dev/null)
  # ROUTING LINES 4–7, read into memory once — the token's name is reused by
  # the next attempt, so nothing below reads it again. THE SHAPE OF THE TOKEN
  # SAYS WHICH LAUNCH THIS IS, and the run's routing record must agree with it:
  # three lines are an unrouted launch; seven lines whose fourth starts `B:`
  # are a grant (lineage, lease nonce, account, config directory — `-` is a
  # value on 5 and 6); seven lines whose fourth is the word `wait` are a
  # supervisor that waits for an account before it spawns (lineage, event,
  # bound account — `-` when none). A lineage always starts `B:`, so the
  # fourth line cannot be read two ways. Any other shape, or a shape the
  # routing record disagrees with, was written by a dispatch half this
  # process does not match, and nothing is started.
  local routed=0 waiting=0 r_lineage="" r_nonce="" r_acct="" r_cfg="" r_event="" r_bound="" hrc
  local tok_lines tok4
  tok_lines=$(awk 'END { print NR }' "$taken" 2>/dev/null || printf 0)
  tok4=$(sed -n '4p' "$taken" 2>/dev/null)
  case "$tok_lines:$tok4" in
    3:)
      if run_routed; then
        warn "the launch token carries no routing lines although this run is routed ($seg) — the supervisor is not started"
        return "$GATE_EXIT_RULE"
      fi
      ;;
    7:B:*)
      run_routed || { warn "the launch token carries a grant although this run is not routed ($seg) — the supervisor is not started"; return "$GATE_EXIT_RULE"; }
      routed=1
      r_lineage="$tok4"
      r_nonce=$(sed -n '5p' "$taken" 2>/dev/null)
      r_acct=$(sed -n '6p' "$taken" 2>/dev/null)
      r_cfg=$(sed -n '7p' "$taken" 2>/dev/null)
      if [ -z "$r_nonce" ] || [ -z "$r_acct" ] || [ -z "$r_cfg" ]; then
        warn "the launch token's grant lines are incomplete ($seg) — the supervisor is not started"
        return "$GATE_EXIT_RULE"
      fi
      [ "$r_nonce" != "-" ] || r_nonce=""
      ;;
    7:wait)
      run_routed || { warn "the launch token asks to wait although this run is not routed ($seg) — the supervisor is not started"; return "$GATE_EXIT_RULE"; }
      routed=1 waiting=1
      r_lineage=$(sed -n '5p' "$taken" 2>/dev/null)
      r_event=$(sed -n '6p' "$taken" 2>/dev/null)
      r_bound=$(sed -n '7p' "$taken" 2>/dev/null)
      case "$r_lineage" in B:*) ;; *) warn "the wait token carries no lineage ($seg) — the supervisor is not started"; return "$GATE_EXIT_RULE" ;; esac
      [ -n "$r_event" ] || { warn "the wait token carries no event ($seg) — the supervisor is not started"; return "$GATE_EXIT_RULE"; }
      [ "$r_bound" != "-" ] || r_bound=""
      ;;
    *)
      warn "the launch token has a shape no dispatch half writes ($seg, $tok_lines lines) — the supervisor is not started"
      return "$GATE_EXIT_RULE"
      ;;
  esac

  # THE PIN IS READ, NEVER WRITTEN, HERE. The dispatch half wrote it; a second
  # writer would let the two halves disagree about which attempt this is.
  local attempt
  attempt=$( { cat "$RUN_DIR/$seg.attempt" 2>/dev/null || true; } | tr -d '[:space:]')
  [ -n "$attempt" ] || { warn "there is no attempt pin ($seg) — the dispatch half did not leave one"; return 1; }

  # A WAIT TOKEN: WAIT FOR AN ACCOUNT BEFORE ANYTHING IS SPAWNED. First the act
  # that started this process has to finish — the marker is written after this
  # process exists. No marker then means that act failed after starting this
  # one, and this attempt ends without a park row. The loop writes every row it
  # stops on; on a grant, everything a grant at dispatch time would have done
  # before the pin is done here: the instructions under the granted account,
  # the `stage-lease` row, the session's synthesis record.
  local wm=""
  if [ "$waiting" = "1" ]; then
    local wrc=0 wenv
    wm="$RUN_DIR/$seg.waiting"
    gate_sup_await_dispatch "$seg"
    if [ ! -f "$wm" ] || [ "$(cc_waiting_field "$wm" '보유자' | tr -d '[:space:]')" != "$$" ]; then
      warn "there is no waiting marker of this supervisor ($seg) — the act that started it did not finish, and nothing is spawned"
      rm -f "$RUN_DIR/$seg.sup" "$RUN_DIR/$seg.sup.start"
      return "$GATE_EXIT_RULE"
    fi
    GATE_SUP_ALIAS=$alias GATE_SUP_KEY=$seg GATE_SUP_LINEAGE=$r_lineage GATE_SUP_BIND=$r_bound GATE_SUP_MARKER=$wm
    GATE_SUP_ROWSEG=$(gate_stage_row_segment "$seg" "$kind")
    GATE_SUP_CARRY=$(gate_halt_card_line "$seg#$attempt")
    stage_wait_loop "$seg" "$kind" "$wm" "$r_event" "$r_bound" \
      gate_sup_wait_heartbeat gate_sup_wait_deadline gate_sup_wait_stop gate_sup_wait_ended || wrc=$?
    if [ "$wrc" != "0" ]; then
      rm -f "$RUN_DIR/$seg.sup" "$RUN_DIR/$seg.sup.start" "$RUN_DIR/$seg.launch.taken"
      return 0
    fi
    wenv=$WAIT_LOOP_ENV
    r_nonce=$(printf '%s' "$wenv" | jq -r '.nonce // empty' 2>/dev/null || true)
    r_acct=$(printf '%s' "$wenv" | jq -r '.account // "-"' 2>/dev/null || printf '%s' '-')
    r_cfg=$(printf '%s' "$wenv" | jq -r '.config_dir // empty' 2>/dev/null || true)
    # THE END IS READ ONCE MORE AFTER THE LEASE ROW, the last row before the
    # spawn: the loop read it on the grant, and synthesizing the instructions
    # under the granted account takes long enough for a boundary to land.
    local prep_why="부여 뒤 기동 준비 거부 — 지시문 합성 또는 stage-lease 행이 거절됐다"
    if [ -z "$r_cfg" ] \
       || ! instr=$(CLAUDE_CONFIG_DIR="$r_cfg" gate_stage_instructions_for_launch "$alias" "$resume") \
       || ! gate_stage_lease_row "$r_lineage" "$wenv" "$r_bound" \
       || { ! gate_sup_wait_ended && prep_why="런이 이미 종료됐다 — $seg 는 부여를 받았지만 기동하지 않는다"; }; then
      gate_sup_wait_stop "$prep_why"
      [ -z "$r_nonce" ] || route_lease_release "$(run_pace_root)/leases" "$RUN_ID" "$r_lineage" "$r_nonce" >/dev/null 2>&1 || true
      wait_drop "$wm"
      rm -f "$RUN_DIR/$seg.sup" "$RUN_DIR/$seg.sup.start" "$RUN_DIR/$seg.launch.taken"
      return "$GATE_EXIT_RULE"
    fi
    if [ -z "$resume" ] && [ -n "$instr" ]; then
      gate_stage_instructions_record "$(session_uuid "$seg" "$attempt")" "$instr"
    fi
  fi
  # The plugin root the wrapper injects, so the stage's slash commands resolve.
  # This assignment was once deleted by an edit that moved the block above it;
  # `--plugin-dir "$plugin_dir"` stayed, so under `set -u` every stage dispatch
  # died on an unbound variable, and nothing caught it because no test ran the
  # launch path past its argument checks. The stub-CLI fixtures enter it now.
  #
  # THE STREAM IS SCOPED BY ATTEMPT AND OPENED FOR APPEND. The launcher once
  # wrote every dispatch of one segment to a single truncating path, so the
  # implementation stage's transcript was erased by the review stage of the same
  # segment. THE PATH COMES FROM THE READER'S OWN FUNCTION: `stage_log_path`
  # reads the pin, so this resolves to the same name `stage_session_id` and
  # `predicate_reconverge` will read. The stream goes to a FILE rather than
  # through a `tee` — a tee would make `$!` the tee's pid, and the pid is what
  # the watcher uses to tell a working stage from a stopped router.
  local plugin_dir out err id_flag
  plugin_dir=$(cd "$(dirname "$GATE_DIR")" && pwd)
  out=$(stage_log_path "$seg")
  err="${out%.json}.err"
  if [ -n "$resume" ]; then
    id_flag="--resume $resume"
    log "스테이지 재부착 — $seg ← 세션 $resume"
  else
    id_flag="--session-id $(session_uuid "$seg" "$attempt")"
  fi

  # THE LINE OF THIS ATTEMPT'S DISPATCH ROW, for the outcome recorder's fourth
  # condition. The global row count the recorder used to compare meant "the
  # stage itself called the gate at least once" only while the dispatch was
  # blocking — nobody else could write a row in that window. Now the router
  # writes rows for the stage's whole lifetime, so the recorder looks instead
  # for a `행위자=스테이지` row of this segment AFTER this line.
  #
  # `rowseg` IS WHAT THE ROWS CARRY, `seg` IS WHAT THE FILES ARE NAMED BY. They are
  # the same string for a segment and differ for the run-scope design step, whose
  # dispatch row, stage rows and `stage-result` all say `세그먼트=-` while its pin,
  # stream and pid record are named by the step id.
  local dispatch_line rowseg
  rowseg=$(gate_stage_row_segment "$seg" "$kind")
  dispatch_line=$( { grep -n '^- `자율 승인`' "$LEDGER" 2>/dev/null || true; } \
                   | { grep -F 'kind=skill ' || true; } | { grep -F '결정=act' || true; } \
                   | { grep -F "세그먼트=$rowseg " || true; } | tail -1 | cut -d: -f1)

  # THE COMPACTION WINDOW IS READ ONCE AND USED TWICE. The flag on the argv and
  # the `압축 창` value on the row are both derived from `$window`, so the row
  # cannot claim `(argv)` when no flag went out, nor the reverse. Injection
  # happens only when the reading itself says `(argv)`; `(꺼짐)` and `(미상)`
  # inject nothing — the window is an optimisation, and an uncertain reading
  # must not stop a launch. The project layer is read from this process's cwd,
  # which is its caller's: the act does not move it, so a stage starts in the
  # directory the session that dispatched it was in, not in the segment's
  # worktree.
  # A `--resume` re-attachment passes through here too, so the same flag rides
  # beside `-r`. The flag goes to the WRAPPER, before `--`: the wrapper refuses
  # a caller's `--autocompact` after `--` as a reserved flag, and it puts the
  # gate's own copy on the CLI argv itself.
  local window ac_val ac_flags=""
  ac_val=$(gate_autocompact_argv_value "$kind")
  if [ "$routed" = "1" ]; then
    window=$(gate_autocompact_effective "$ac_val" "$(gate_settings_file "$kind")" "$PWD" "$r_cfg")
  else
    window=$(gate_autocompact_effective "$ac_val" "$(gate_settings_file "$kind")" "$PWD")
  fi
  case "$window" in *"(argv)") ac_flags="--autocompact ${window%(argv)}" ;; esac

  # EFFORT AND MODEL COME FROM THE DRIVER'S TABLE, sourced rather than copied, so
  # a stage the router launches and one the driver spawns cannot run the same
  # kind at two efforts. Like the window, the effort is read once: the value on
  # the argv and the value on the row are the same string. Both ride the resume
  # re-attachment too — a resumed session does not keep the effort it started
  # with.
  local effort launch_flags
  effort=$(stage_effort_of "$kind")
  launch_flags=$(stage_launch_flags "$kind")

  local rc=0 spid
  # THE STAGE IS HANDED WHAT THE HOOK WILL DEMAND OF IT. Layer 1 routes every
  # Bash line, Write and Edit through the gate, and the gate's argv needs a
  # manifest path, a target, a cutpoint and a snapshot digest. A stage that has
  # none of them cannot comply and cannot even write a halt record — the halt
  # path derives its own location from the run id, and reading the run id needs
  # Bash, which the hook has just refused. Measured: an implementation stage
  # was blocked fourteen times, edited nothing, left the tree byte-identical,
  # and exited 0 with `subtype: success`. The digest is deliberately NOT among
  # them: it moves on every ledger write, so the stage reads it with `gate.sh
  # snapshot`, which the hook's allow-list already permits.
  #
  # `CC_CMDS_AUTOPILOT_AUTO_RESOLVE` below carries the INTERPRETED value, not the
  # raw one, and it is pinned rather than left to inheritance. The switch decides
  # whether a refused act becomes an exit code or an approval a person answers,
  # so a stage that read it differently than the launcher would take a
  # disposition the run never chose. Ambient inheritance already carries the
  # variable; what it does not carry is agreement — a shell profile or a resumed
  # session can put another spelling in the environment between the two reads.
  # Baking the resolved `1`/`0` in makes that impossible instead of unlikely.
  #
  # THE BACKGROUND WAIT CEILING, because a fan-out stage does not fit under the
  # default one. Measured: a dispatched audit stage was killed at exactly 600s
  # with "Background tasks still running after 600s; terminating", reported
  # `subtype: success` and exit 0, and published nothing. Raised rather than
  # removed: `0` waits forever, and a hung stage under a live pid reads as a
  # heartbeat, so the run sits until the person comes back. A finite ceiling
  # still kills.
  #
  # AN HOUR WAS NOT ENOUGH FOR A TEAM-TIER STAGE, so it is four. Measured: an
  # unattended design stage spawned its four roster members into the background
  # and was terminated at the 3600 s mark while waiting on the fourth witness —
  # three had published, the fourth had been killed by the system — after 1 h
  # 55 m and 20.57 USD, leaving the spawn-time stub on disk and nothing else.
  # The discussion itself is what sits in the background here, so the ceiling is
  # a cap on how long a team may talk, not on how long a wedge may last. Four
  # hours also stays above the liveness watcher's stage-age arm, which names a
  # stage older than two hours without ending it — so a wedged stage is reported
  # first and killed second.
  #
  # WHAT THE KILL DOES NOT BUY IS A CLASSIFICATION. The terminated process still
  # returns rc=0 with `subtype: success`, `terminal_reason: completed` and
  # `is_error: false`, so the terminal class reads 정상 완료 and the design arm
  # skips redispatch on it. Raising the ceiling makes that outcome rarer; it does
  # not make the kill visible, and the document is the only place the difference
  # survives.
  #
  # `bash`, not `/bin/sh`: the wrapper uses `set -o pipefail`, and naming an
  # interpreter on the command line overrides the shebang — on a distribution
  # whose `/bin/sh` is dash the wrapper died at its second line.
  #
  # ROUTING ON: THIS PROCESS HOLDS THE LEASE BEFORE IT LAUNCHES ANYTHING. The
  # dispatch act that took the grant has returned, so without this hold a stage
  # could run on a lease whose holders are all dead. A stale lease is not
  # revived (rc 5), and no stage is launched on any answer but 0. Then the
  # four-line record goes down before the launch — a settlement reads the
  # account from its fourth line, and it must be there however early the stage
  # dies — and the wrapper is handed the grant's directory explicitly; the
  # wrapper itself is not changed.
  #
  # THE MEMBERS FILE IS FOUND FROM THE LEAD PATH, through the pointer beside it,
  # so the token keeps its one instructions line and a resume, which follows the
  # recorded lead file, follows that file's members file with it.
  local member_instr
  member_instr=$(gate_stage_member_instructions "${instr:-}")
  if [ "$routed" = "1" ]; then
    if [ -n "$r_nonce" ]; then
      hrc=0
      route_lease_hold "$(run_pace_root)/leases" "$RUN_ID" "$r_lineage" "$r_nonce" "$$" >/dev/null 2>&1 || hrc=$?
      if [ "$hrc" != "0" ]; then
        warn "the supervisor could not hold its lease (rc=$hrc, $r_lineage) — the stage is not launched ($seg#$attempt)"
        return "$GATE_EXIT_RULE"
      fi
    fi
    printf '%s\n%s\n%s\n%s\n' "$window" "$(lane_label_of "$r_cfg")" "${effort:--}" "$r_acct" > "$RUN_DIR/$seg.window"
    # The directory this attempt runs under, the record the driver's launch
    # writes too: with routing on, `transcript_of_session` finds a stage's
    # transcript only through it, and without it the terminal row could not
    # count the session's organization moves.
    write_run_record "$RUN_DIR/$seg.config-dir" "$r_cfg" \
      || warn "the attempt's config directory record was not written ($seg#$attempt) — the transcript readers will not find it"
    local -x CLAUDE_CONFIG_DIR="$r_cfg"
  fi
  # THE RE-ATTACHMENT ORGANIZATION CHECK, the same one the driver's launch makes.
  # The previous attempt's record goes first, so a fresh session never carries
  # it; a re-attachment then compares the session's last organization with the
  # one its directory requests now, records a difference and launches anyway.
  rm -f "$RUN_DIR/$seg.org-reattach"
  if [ -n "$resume" ]; then
    local rcfg=""
    if [ "$routed" = "1" ]; then
      rcfg="$r_cfg"
    else
      rcfg=$(resolve_account 2>/dev/null) || rcfg=""
    fi
    [ -z "$rcfg" ] || reattach_org_note "$seg" "$rcfg" "$resume"
  fi
  # THE AUDIT'S PASS MARKER, on an audit stage only: `reaudit` once the audit's
  # key has had a re-convergence in this run, `first` otherwise. The audit
  # writes it into its report fence and never counts passes itself. A fresh
  # dispatch and a `--resume` launch here alike, so both carry it.
  if [ "$kind" = "audit" ]; then
    local -x CC_PIPELINE_AUDIT_PASS
    CC_PIPELINE_AUDIT_PASS=$(audit_pass_of "$seg")
  fi
  # THE ANSWER CARD, when the dispatch wrote one for this attempt. Its path
  # follows from `seg#attempt`, so the launch token carries nothing new; an
  # attempt with no card gets no variable, whatever this process inherited.
  if [ -f "$(gate_halt_card_path "$seg#$attempt")" ]; then
    local -x CC_PIPELINE_HALT_ANSWER
    CC_PIPELINE_HALT_ANSWER=$(gate_halt_card_path "$seg#$attempt")
  else
    unset CC_PIPELINE_HALT_ANSWER
  fi
  CLAUDE_CODE_PRINT_BG_WAIT_CEILING_MS="${CC_ORCH_BG_WAIT_CEILING_MS:-14400000}" \
  CC_CLAUDE_BIN="$CLI_BIN" \
  CC_PIPELINE_RUN_ID="$RUN_ID" \
  CC_PIPELINE_RUN_DIR="$RUN_DIR" \
  CC_PIPELINE_MANIFEST="$MANIFEST" \
  CC_PIPELINE_LEDGER="$LEDGER" \
  CC_PIPELINE_GRANT="$GRANT" \
  CC_PIPELINE_GATE="$GATE_DIR/gate.sh" \
  CC_PIPELINE_TARGET="$alias" \
  CC_PIPELINE_SEGMENT="$rowseg" \
  CC_PIPELINE_STAGE_ID="$seg#$attempt" \
  CC_CMDS_AUTOPILOT_AUTO_RESOLVE="$(gate_auto_resolve_enabled && printf 1 || printf 0)" \
  bash "$wrapper" \
    --settings "$(gate_settings_file "$kind")" \
    --plugin-dir "$plugin_dir" \
    ${instr:+--instructions "$instr"} \
    ${member_instr:+--member-instructions "$member_instr"} \
    $id_flag \
    $ac_flags \
    $launch_flags \
    -- "$@" >> "$out" 2>> "$err" < /dev/null &
  # `$!` IS CORRECT HERE — no fork sits between this shell and the wrapper, and
  # the wrapper `exec`s into the CLI, so this pid is the stage's own. This is
  # the one place the dispatch path may use it; the dispatch half must not.
  spid=$!
  # ONE BLOCK WRITES ALL THREE. `.pid`, `.start` and `.kind` have one lifetime,
  # so they have one writer and one remover; splitting the writer across two
  # processes makes a partial set expressible, and `.kind` is what tells a
  # gate-dispatched record from a driver-spawned one (`liveness.sh`).
  #
  # `.kind` PRECEDES `.start`, because only one of the three can come back empty.
  # A stage that has already exited and been reaped has no start time to read, so
  # `.start` is written empty — and `.kind` is the marker that tells this record
  # from a driver-spawned one for every reader downstream. Written the other way
  # round, any interruption between the two leaves the empty fingerprint and NOT
  # the marker, which is the strictly less useful half: a record nobody can even
  # attribute. This order is not by itself a settlement guarantee — the candidate
  # predicate asks for a non-empty `.start` as well, deliberately — but it makes
  # a partial set attributable, and the lenient capture below is what keeps this
  # block from being interrupted at all.
  printf '%s\n' "$spid" > "$RUN_DIR/$seg.pid"
  printf '%s\n' "$kind" > "$RUN_DIR/$seg.kind"
  cc_proc_fingerprint "$spid" > "$RUN_DIR/$seg.start"
  # THE MARKER GOES ONLY NOW that all three records exist: in between the key
  # reads as a live stage, never as nothing at all.
  [ -z "$wm" ] || wait_drop "$wm"
  # THE HOLD RECORD GOES ONLY NOW, after the three records above: the key's next
  # attempt is a stage process, and a routed one holds its own grant, which the
  # lease table already shows. An absent record is a successful no-op.
  route_halt_hold_drop --table "$(run_pace_root)/leases" --run-id "$RUN_ID" --key "$seg" \
    || warn "the hold record of an earlier attempt was not removed ($seg#$attempt)"
  # `.window` IS A RECORD, NOT A LIVENESS INPUT. Two lines — the effective
  # window and the lane — kept beside the three above so a settlement that runs
  # after this process is gone can still put them on the row. No reader makes
  # its presence a precondition: absent, the row says `(미상)`. The effort and
  # the routed account are lines 3 and 4 of the same record; an unrouted launch
  # writes neither, and the routed one wrote all four before the launch above.
  if [ "$routed" = "1" ]; then
    # The stage joins the lease's holders, so the lease outlives this process
    # if it is killed. Not fatal: this process already holds it.
    if [ -n "$r_nonce" ]; then
      hrc=0
      route_lease_hold "$(run_pace_root)/leases" "$RUN_ID" "$r_lineage" "$r_nonce" "$spid" >/dev/null 2>&1 || hrc=$?
      [ "$hrc" = "0" ] || log "스테이지 임대 보유 rc=$hrc — $seg#$attempt ($r_lineage)"
    fi
  else
    printf '%s\n%s\n' "$window" "$(gate_lane_label)" > "$RUN_DIR/$seg.window"
  fi
  # `.anchor` IS A RECORD TOO, written for a re-attachment only: the base the
  # re-attachment delay is measured from. A dispatch with no base removes it,
  # so a record left by an earlier attempt is never stamped on this one's row.
  if [ -n "$resume" ]; then
    gate_reattach_anchor_write "$seg"
  else
    rm -f "$RUN_DIR/$seg.anchor"
  fi

  # THE TERM TRAP, NEW WITH THE SUPERVISOR. A person who wants a detached stage
  # to stop kills the CLI pid; a TERM that reaches the supervisor instead is
  # forwarded, the child is waited on, and the SAME terminal path records the
  # outcome — an intended stop leaves a row. Without this the wrapper's Mode A
  # (`exec`) has nobody on the exit path at all.
  GATE_SUP_TERM=0
  trap 'kill -TERM "$spid" 2>/dev/null; GATE_SUP_TERM=1' TERM INT
  wait "$spid" || rc=$?
  # A signal interrupts `wait` with 128+n before the child is reaped; wait once
  # more for the real status. Only when the first wait WAS interrupted — a
  # second wait on an already-reaped pid answers 127 for an unrelated reason.
  if [ "$GATE_SUP_TERM" = "1" ] && [ "$rc" -gt 128 ]; then
    rc=0; wait "$spid" || rc=$?
  fi
  trap - TERM INT

  # RECORD FIRST, REMOVE AFTER. The invariant re-attachment rests on is "a
  # dispatch record present means this attempt is not yet settled; absent means
  # no attempt, or its row is already in the ledger" — true only in this order.
  # The window this opens (CLI dead, row being written) is closed on the reader
  # side by `cc_orphan_stages`' `.sup` condition.
  #
  # THE RECORDER'S STATUS IS TAKEN, NOT ASSUMED. The blocking dispatch this
  # supervisor replaced called the recorder on the left of `|| rc=$?`, and bash
  # ignores errexit inside a function body called there; a plain call under
  # this process's `set -euo pipefail` gave every unguarded substitution in the
  # recorder the power to end the supervisor before the row. `|| rec_rc=$?`
  # restores that posture for the whole body and keeps the status for the log.
  local rec_rc=0
  if [ "$routed" = "1" ]; then
    gate_record_stage_outcome "$alias" "$seg" "$kind" "$attempt" "$rc" "$dispatch_line" "$out" "$window" "${effort:--}" "$r_acct" || rec_rc=$?
  else
    gate_record_stage_outcome "$alias" "$seg" "$kind" "$attempt" "$rc" "$dispatch_line" "$out" "$window" "${effort:--}" || rec_rc=$?
  fi
  [ "$rec_rc" = "0" ] || warn "the stage result recorder ended non-zero ($seg#$attempt rc=$rec_rc)"
  # THE LEASE GOES BACK ONLY ONCE THE TERMINAL ROW IS IN, with the lineage and
  # nonce this process read from the token at its start. A recorder that failed
  # leaves the lease to the run's end, so a stage with no row never also loses
  # the reservation that row would have closed.
  if [ "$routed" = "1" ] && [ -n "$r_nonce" ] && [ "$rec_rc" = "0" ]; then
    # A STAGE THAT STOPPED ON A QUESTION KEEPS ITS ACCOUNT VISIBLE, written BEFORE
    # the release (`gate_sup_halt_hold_put`). It never stops the release.
    gate_sup_halt_hold_put "$seg" "$attempt" "$r_lineage" "$r_acct" "$r_cfg"
    hrc=0
    route_lease_release "$(run_pace_root)/leases" "$RUN_ID" "$r_lineage" "$r_nonce" || hrc=$?
    [ "$hrc" = "0" ] || warn "the lease release ended rc=$hrc ($r_lineage)"
  fi
  # THE SAME SET THE SETTLEMENT PATH REMOVES, including the three files the
  # dispatch act wrote hours ago — that act returned long since, so this is the
  # only process that can remove them. Removed ONLY when this attempt's
  # `stage-result` row is in the ledger — the same `(세그먼트, 실행 버전)` key the
  # settlement and `wait` read. A recorder that returned without the row must
  # leave the record in place: the invariant above says a present record is an
  # unsettled attempt, and the prelude settlement closes it as `외부 종료` on
  # the next gate call. Removing the files without the row is the other shape —
  # no row and no record — which nothing settles and every re-dispatch repeats.
  if [ -n "$( gate_stage_result_rows_of "$seg" \
              | { grep -F "실행 버전=$attempt " || true; } )" ]; then
    rm -f "$RUN_DIR/$seg.pid" "$RUN_DIR/$seg.start" "$RUN_DIR/$seg.kind" \
          "$RUN_DIR/$seg.sup" "$RUN_DIR/$seg.sup.start" "$RUN_DIR/$seg.launch.taken" \
          "$RUN_DIR/$seg.window" "$RUN_DIR/$seg.anchor"
  else
    warn "there is no \`stage-result\` row for this attempt, so a segment file is left behind ($seg#$attempt) — the prelude settlement picks it up"
  fi
  # THE COST SAMPLE IS WRITTEN LAST, after the records above are gone. `gate.sh
  # wait` keeps waiting while `.sup` is present, and summarising a log of a few
  # hundred megabytes with it still there would hold the waiter for as long.
  # Taken whatever the recorder answered — a failed attempt used the account
  # all the same — but only for a routed launch on an account the ledger would
  # accept as one: a seat or an unknown account has no quota group to divide by.
  if [ "$routed" = "1" ] && run_ledger_account_ok "$r_acct"; then
    route_cost_sample_put "$(run_pace_root)/costs" --run-id "$RUN_ID" --lineage "$r_lineage" \
      --kind "$kind" --account "$r_acct" --log "$out" || warn "the cost sample was not written ($seg#$attempt)"
  fi
  log "스테이지 종단 — $seg#$attempt (rc=$rc)"
  return "$rc"
}

gate_settle_lost_dispatches() {
  # Settle every lost dispatch — a gate-dispatched record whose process AND
  # supervisor are gone — with one `stage-result` row of class `외부 종료`.
  # Called from the prelude on every verb but `plan`; see the call site.
  #
  # THE CANDIDATE PREDICATE. `cc_orphan_stages` enumerates every record whose
  # process is gone, and that list is shared with the alarm and the snapshot.
  # Settlement acts on the SUBSET the gate itself dispatched: `<seg>.kind` is
  # present (only the supervisor writes it), `<seg>.start` is non-empty (a
  # judgeable fingerprint) and `<seg>.attempt` exists (the row's `실행 버전`).
  # A driver-spawned record (`.pid`/`.start`/`.pgid`, no `.kind`) is collected
  # by the driver's own `stage_collect`; settling it here would pre-empt that
  # and write a second `stage-result` with a `실행 버전` that is not an attempt.
  # A record missing the fingerprint or the pin is listed by the alarm and left
  # alone here — it cannot be settled and must not be silently dropped.
  #
  # THE ORDER. (1) enumerate and filter; (2) PRE-EMPT by renaming `<seg>.pid`
  # to `<seg>.pid.settling.<pid>` — `mv` is exclusive on the source, so of two
  # concurrent settlers exactly one proceeds, and a stalled marker reclaimed by
  # `cc_orphan_stages` is re-pre-empted the same way; (3) skip the append when
  # a `stage-result` for `(세그먼트, 실행 버전)` already exists, so the
  # invariant "one row per attempt" survives a settler that died after its
  # append; (4) append; (5) remove the same file set the supervisor's normal
  # path removes. No `cost` row — there is no envelope to read a cost from, and
  # the morning report counts these as `정산됨(비용 불명)` instead.
  local seg src kind attempt marker sid window lane acct
  for seg in $( { cc_orphan_stages "$RUN_DIR" || true; } | sort -u); do
    [ -n "$seg" ] || continue
    [ -f "$RUN_DIR/$seg.kind" ] || continue
    [ -s "$RUN_DIR/$seg.start" ] || continue
    [ -f "$RUN_DIR/$seg.attempt" ] || continue
    marker="$RUN_DIR/$seg.pid.settling.$$"
    if [ -f "$RUN_DIR/$seg.pid" ]; then
      mv "$RUN_DIR/$seg.pid" "$marker" 2>/dev/null || continue
    else
      src=""
      for src in "$RUN_DIR/$seg.pid.settling"*; do [ -f "$src" ] && break; src=""; done
      [ -n "$src" ] || continue
      [ "$src" = "$marker" ] || mv "$src" "$marker" 2>/dev/null || continue
    fi
    kind=$( { cat "$RUN_DIR/$seg.kind" 2>/dev/null || true; } | tr -d '[:space:]')
    attempt=$( { cat "$RUN_DIR/$seg.attempt" 2>/dev/null || true; } | tr -d '[:space:]')
    # The window and lane the launch recorded, if the record survived; neither
    # is a condition of settling, only a value on the row.
    window=$(gate_window_sidecar_read "$seg")
    lane=$(gate_lane_sidecar_read "$seg")
    # The account is read with the other two, BEFORE the record is removed below;
    # an absent fourth line is an absent field, never a re-resolution.
    acct=$(stage_account_of "$seg")
    if [ -z "$( gate_stage_result_rows_of "$seg" \
                | { grep -F "실행 버전=$attempt " || true; } )" ]; then
      sid=$(stage_session_id "$seg")
      # The attempt ran a session, so its moves and re-attachment record go on
      # its row as on a supervisor's.
      local om ro re
      om=$(stage_org_moves_of "$seg" || true)
      ro=$(stage_reattach_org_of "$seg")
      re=$(stage_reattach_ctx_of "$seg")
      # No effort was recorded anywhere the settlement can read, so it says
      # `(미상)`; the served model is in the stream's first frame if the stage
      # got that far.
      gate_reattach_anchor_fields "$seg"
      local hacarry
      hacarry=$(gate_halt_card_line "$seg#$attempt")
      gate_append 'stage-result' "세그먼트=$(gate_stage_row_segment "$seg" "${kind:-}")" "스테이지=$seg" "종류=${kind:-미상}" \
        "종료 코드=-" "실행 버전=$attempt" "세션 id=${sid:-미상}" "부모=-" \
        "압축 창=$window" "레인=$lane" ${acct:+"계정=$acct"} \
        ${om:+"조직 이동=$om"} ${ro:+"재부착 조직=$ro"} ${re:+"재기록 추정=$re"} "기록자=게이트" \
        "effort=(미상)" "서빙 모델=$(stage_served_model_of "$(stage_log_path "$seg")")" \
        ${GATE_RA_BASE:+"재부착 기준=$GATE_RA_BASE"} ${GATE_RA_DELAY:+"재부착 지연=$GATE_RA_DELAY"} \
        ${GATE_RA_WIN:+"창 종류=$GATE_RA_WIN"} ${GATE_RA_SLEEP:+"마지막 절전=$GATE_RA_SLEEP"} \
        "종단 부류=외부 종료" "실패 서명=$(failure_signature "${kind:-미상}" '외부 종료' - -)" \
        "관측=파견 기록이 프로세스보다 오래 살았고 종단 result 줄이 없다 — 정산 시각 $(now_iso)" \
        ${hacarry:+"답 운반=$hacarry"}
      log "잃어버린 파견 정산 — $seg#$attempt (외부 종료)"
    else
      log "잃어버린 파견 정리 — $seg#$attempt (행은 이미 있음)"
    fi
    rm -f "$marker" "$RUN_DIR/$seg.start" "$RUN_DIR/$seg.kind" \
          "$RUN_DIR/$seg.sup" "$RUN_DIR/$seg.sup.start" "$RUN_DIR/$seg.launch.taken" \
          "$RUN_DIR/$seg.window" "$RUN_DIR/$seg.anchor"
    GATE_SETTLED_SEGMENTS="$GATE_SETTLED_SEGMENTS $seg"
  done
  gate_settle_dead_waiters
  gate_settle_dead_shift
  return 0
}

gate_settle_dead_shift() {
  # The third candidate set: a `shift.live` whose shift AND launcher are both
  # gone. The launcher writes the `무기록` row of a shift that ended without a
  # handoff, after its `wait` — so when the launcher dies with it (a reboot, a
  # host that stopped, a killed seat) nobody writes it, the ledger ends on a
  # `교대 기동` with no answer, and the successor reads the predecessor's older
  # handoff as the latest word.
  #
  # BOTH MUST BE DEAD. The launcher's own trace runs between the shift's death
  # and its marker removal; settling while it lives would write a second row in
  # that window. A file without lines 3 and 4 predates the launcher record and
  # cannot be judged, so it is left to the launcher that wrote it.
  #
  # PRE-EMPTED BY A RENAME, the device the lost-dispatch settlement uses: `mv`
  # is exclusive on its source, so of two settlers exactly one goes on. The row
  # itself is `gate_shift_trace_unrecorded`'s, whose own guard skips a shift that
  # did write a handoff. `relay.live` is not touched — a dead relay already reads
  # dead, and its `handback` line is the watcher's clock.
  local f="$RUN_DIR/shift.live" m spid sfp lpid lfp row n alias
  [ -f "$f" ] || return 0
  spid=$( { sed -n '1p' "$f" 2>/dev/null || true; } | tr -d '[:space:]')
  sfp=$(sed -n '2p' "$f" 2>/dev/null || true)
  lpid=$( { sed -n '3p' "$f" 2>/dev/null || true; } | tr -d '[:space:]')
  lfp=$(sed -n '4p' "$f" 2>/dev/null || true)
  [ -n "$lpid" ] && [ -n "$lfp" ] || return 0
  if cc_holder_is_live "$spid" "$sfp" || cc_holder_is_live "$lpid" "$lfp"; then
    return 0
  fi
  m="$f.settling.$$"
  mv "$f" "$m" 2>/dev/null || return 0
  row=$( { LC_ALL=C grep -E '^- `교대 기동` ' "$LEDGER" 2>/dev/null || true; } | tail -1)
  n=$(printf '%s\n' "$row" | sed -n 's/.* | 서수=\([0-9][0-9]*\) | .*/\1/p')
  alias=$(printf '%s\n' "$row" | sed -n 's/.* | 대상=\([^|]*[^ |]\) | .*/\1/p')
  if [ -n "$n" ] && [ -n "$alias" ]; then
    # In a subshell: `gate_append` answers a failure with `die`, and the prelude
    # must not end the verb over a trace.
    ( gate_shift_trace_unrecorded "$alias" "$n" "-" ) \
      || warn "교대 $n 의 무기록 인계 행을 정산하지 못했습니다"
    log "죽은 교대 정산 — 교대 $n (교대와 실행기가 모두 없다)"
  fi
  rm -f "$m" "$RUN_DIR/shift.in-progress"
  return 0
}

gate_settle_dead_waiters() {
  # gate_settle_dead_waiters [<own key>] — the second candidate set: a
  # gate-written waiting marker whose holder is gone, with no `<key>.pid` and a
  # pin. The supervisor died before it spawned anything, so nothing else will
  # ever write this attempt's terminal row. With <own key>, only that key is
  # looked at and the dispatch lock this act already holds is used, not taken
  # again — the act runs this after taking its lock, so a waiter that died after
  # the prelude's settlement is still closed before a new attempt is claimed.
  #
  # THE ORDER CLOSES THE RACE WITH A LIVE DISPATCH. The key's dispatch lock is
  # held first (a live holder means another act is on this key: skip it), then
  # the marker is taken by a rename and its holder read again from the moved
  # file — a new waiter that wrote the marker in between is alive, and its
  # marker goes back untouched. The attempt comes from the marker, never from
  # the pin, which a newer attempt may have rewritten.
  #
  # THE ROW NAMES NO ACCOUNT. This attempt never held a lease, and the
  # segment's `.window` may still name an earlier attempt's account.
  # Driver-written markers are the driver's to clear.
  local own="${1:-}" f key me took m pid fp kind att lin nonce hacarry
  me=$(exec sh -c 'echo $PPID')
  for f in "$RUN_DIR"/*.waiting; do
    [ -f "$f" ] || continue
    key=${f##*/}; key=${key%.waiting}
    [ -z "$own" ] || [ "$key" = "$own" ] || continue
    [ "$(cc_waiting_field "$f" '기록자')" = "게이트" ] || continue
    pid=$(cc_waiting_field "$f" '보유자' | tr -d '[:space:]')
    fp=$(cc_waiting_field "$f" '지문')
    if cc_holder_is_live "$pid" "$fp"; then continue; fi
    [ ! -e "$RUN_DIR/$key.pid" ] || continue
    [ -f "$RUN_DIR/$key.attempt" ] || continue
    took=0
    if [ -z "$own" ]; then
      local GATE_DISPATCH_LOCK=""
      gate_dispatch_lock_take "$key" || continue
      took=1
    fi
    m="$f.settling.$me"
    if ! mv "$f" "$m" 2>/dev/null; then
      [ "$took" = "0" ] || gate_dispatch_lock_release
      continue
    fi
    pid=$(cc_waiting_field "$m" '보유자' | tr -d '[:space:]')
    fp=$(cc_waiting_field "$m" '지문')
    if cc_holder_is_live "$pid" "$fp"; then
      mv -n "$m" "$f" 2>/dev/null || true
      [ "$took" = "0" ] || gate_dispatch_lock_release
      continue
    fi
    kind=$(cc_waiting_field "$m" '종류' | tr -d '[:space:]')
    att=$(cc_waiting_field "$m" '시도' | tr -d '[:space:]')
    lin=$(cc_waiting_field "$m" '계보')
    nonce=$(cc_waiting_field "$m" '논스' | tr -d '[:space:]')
    if [ -n "$att" ] \
       && [ -z "$(gate_stage_result_rows_of "$key" | { grep -F "실행 버전=$att " || true; } )" ] \
       && { [ -z "$lin" ] || [ -z "$( { gate_rows 'blocked' || true; } | cc_rows_naming_lineage "$lin")" ]; }; then
      hacarry=$(gate_halt_card_line "$key#$att")
      gate_append 'stage-result' "세그먼트=$(gate_stage_row_segment "$key" "${kind:-}")" "스테이지=$key" "종류=${kind:-미상}" \
        "종료 코드=-" "실행 버전=$att" "세션 id=-" "부모=-" "기록자=게이트" \
        "종단 부류=외부 종료" "실패 서명=$(failure_signature "${kind:-미상}" '외부 종료' - -)" \
        "관측=스폰 전 대기 중 감독자가 사라졌다 — 정산 시각 $(now_iso)" \
        ${hacarry:+"답 운반=$hacarry"}
      log "스폰 전 대기자 정산 — $key#$att (외부 종료)"
      GATE_SETTLED_SEGMENTS="${GATE_SETTLED_SEGMENTS:-} $key"
    else
      log "스폰 전 대기자 정리 — $key#${att:-?} (행은 이미 있음)"
    fi
    if [ -n "$lin" ] && [ -n "$nonce" ] && [ "$nonce" != "-" ]; then
      route_lease_wait_drop "$(run_pace_root)/leases" "$RUN_ID" "$lin" "$nonce" >/dev/null 2>&1 || true
    fi
    rm -f "$RUN_DIR/$key.sup" "$RUN_DIR/$key.sup.start" "$RUN_DIR/$key.launch.taken" "$m"
    [ "$took" = "0" ] || gate_dispatch_lock_release
  done
  return 0
}

# ---------------------------------------------------------------------------
# Run metrics — the collector round and the filing it feeds.
#
# The collector (`collect-run-metrics.sh`) reads every finished run's ledger,
# stream logs and transcripts and prints one journal line per round; the
# trigger predicates are ITS output. This side only decides whether a round is
# due, runs it as a separate process, and turns what fired into at most one
# GitHub issue per round. Nothing here reads a transcript or computes a number.
# ---------------------------------------------------------------------------

gate_metrics_lock() {
  # gate_metrics_lock <root> — one attempt, no waiting, the reaper's lock shape
  # (owner line straight after the `mkdir`, the directory's mtime when the line
  # is unreadable, broken after `GATE_METRICS_LOCK_TTL`). Its own directory, so
  # a stuck collector cannot switch the reaper off or the other way round.
  local root="$1" lock owner ots now
  lock="$root/.metrics.lock"
  if mkdir "$lock" 2>/dev/null; then
    printf '%s %s\n' "$$" "$(date -u +%s)" > "$lock/owner" 2>/dev/null || true
    return 0
  fi
  owner=$(cat "$lock/owner" 2>/dev/null || true)
  ots=$(printf '%s' "$owner" | sed -n 's/^[0-9][0-9]*[[:space:]][[:space:]]*\([0-9][0-9]*\)$/\1/p')
  [ -n "$ots" ] || ots=$(gate_mtime "$lock")
  [ -n "$ots" ] || return 1
  now=$(date -u +%s)
  [ $((now - ots)) -ge "$GATE_METRICS_LOCK_TTL" ] || return 1
  rm -rf "$lock" 2>/dev/null || true
  mkdir "$lock" 2>/dev/null || return 1
  printf '%s %s\n' "$$" "$(date -u +%s)" > "$lock/owner" 2>/dev/null || true
  return 0
}

gate_metrics_unlock() {
  # One rename, then the removal — the same release as the reaper's, so no
  # moment exists in which the lock stands without its owner line.
  local lock dead
  lock="$1/.metrics.lock"
  dead="$lock.dead.$$"
  if mv "$lock" "$dead" 2>/dev/null; then
    rm -rf "$dead" 2>/dev/null || true
  fi
  return 0
}

gate_dashboard_ensure() {
  # gate_dashboard_ensure <verb> — start the run dashboard's server from the
  # run-open branch. Always returns 0: a viewer is never a reason for a run to
  # fail to open, and a host without `python3` opens its runs as before.
  #
  # THE VERB FILTER IS HERE, NOT AT THE CALL SITE, because the run-open branch
  # has no verb condition: the first entry of a new run can be `plan` or
  # `digest-path`. Both are kept out for the reasons the metrics round keeps
  # them out — `plan` writes nothing by contract, and the PreToolUse hook calls
  # `digest-path` before every tool call. A run whose first entry is one of them
  # opens without a server and gets one from `/cc-cmds:dashboard` or the next
  # run's opening.
  #
  # NO GRADE AND NO ROW: this is the gate's own housekeeping, as the metrics
  # round is. The off switch (`CC_CMDS_DASHBOARD=off`, `CI`) is read by
  # `dashboard.py ensure` alone, so it has one reader. `PATH` is normalised as
  # the driver normalises it, so a session that lost `/usr/bin` still finds the
  # system interpreter.
  case "${1:-}" in
    plan|digest-path) return 0 ;;
  esac
  cc_caller_is_stage && return 0
  local py
  py=$(PATH="/usr/bin:/bin:$PATH" command -v python3 2>/dev/null || true)
  [ -n "$py" ] || return 0
  "$py" "$GATE_DIR/dashboard.py" ensure </dev/null >/dev/null 2>&1 || true
  return 0
}

gate_metrics_cycle() {
  # Called from the prelude on every verb but `plan`. Always returns 0: a
  # metrics round is never a reason for the verb the caller asked for to fail.
  #
  # THE ORDER IS FIXED. (1) A stage seat does nothing, not even the stamp — a
  # stage has no business spending its turn on a collector round, and a stamp it
  # wrote would silence the router's round for six hours. (2) The cadence stamp
  # is one cheap read. (3) The lock is one attempt. (4) The stamp is written
  # BEFORE the collector runs, so a collector that dies does not make every
  # following gate call retry it; the leftover `.pending` beside the summary is
  # the evidence. (5) The round is started detached, holding the lock, and this
  # call returns — see `gate_metrics_round` for what runs there.
  #
  # THE NONCE BINDS THE CHILD TO THIS LOCK. It is written into the lock
  # directory before the launch and the child refuses without it, so the
  # internal verb cannot be spelled into running a round nobody locked; and the
  # child releases the lock only while it still carries that nonce, so a child
  # that outlived the expiry does not remove a lock another round has since
  # taken. No trap: a child that dies leaves the lock to the expiry, which is
  # the recovery the in-call round always had.
  local root stampf stamp now ledger_dir nonce tmp pid
  cc_caller_is_stage && return 0
  [ -n "${LEDGER:-}" ] || return 0
  ledger_dir=$(dirname "$LEDGER")
  [ -d "$ledger_dir" ] || return 0
  root=$(gate_reap_root)
  stampf=$(gate_metrics_stamp)
  now=$(date -u +%s)
  stamp=$(sed -n '1s/^\([0-9][0-9]*\)$/\1/p' "$stampf" 2>/dev/null || true)
  if [ -n "$stamp" ] && [ $((now - stamp)) -lt "$GATE_METRICS_INTERVAL" ]; then
    return 0
  fi
  mkdir -p "$root" 2>/dev/null || return 0
  gate_metrics_lock "$root" || return 0
  # Read again inside the lock: two gates that both saw an expired stamp would
  # otherwise run the round one after the other, and file twice.
  stamp=$(sed -n '1s/^\([0-9][0-9]*\)$/\1/p' "$stampf" 2>/dev/null || true)
  if [ -n "$stamp" ] && [ $((now - stamp)) -lt "$GATE_METRICS_INTERVAL" ]; then
    gate_metrics_unlock "$root"
    return 0
  fi
  printf '%s\n' "$now" > "$stampf" 2>/dev/null || true
  nonce=$(od -An -N16 -tx1 /dev/urandom 2>/dev/null | tr -d ' \n' || true)
  tmp=""
  if [ -n "$nonce" ]; then
    tmp=$(mktemp "$root/.metrics.lock/.nonce.XXXXXX" 2>/dev/null || true)
  fi
  if [ -z "$tmp" ] || ! printf '%s\n' "$nonce" > "$tmp" 2>/dev/null \
     || ! mv "$tmp" "$root/.metrics.lock/nonce" 2>/dev/null; then
    [ -z "$tmp" ] || rm -f "$tmp" 2>/dev/null || true
    log "계측 회차 실패 — 회차를 띄우지 못했다(다음 회차에 다시 센다)"
    gate_metrics_unlock "$root"
    return 0
  fi
  mkdir -p "$RUN_DIR/log" 2>/dev/null || true
  # `|| pid=""`: run.sh leaves errexit on, and a plain assignment carries the
  # substitution's status, so a launcher that returned 127 would end the whole
  # gate here — before the verb. Two spellings rather than an optional-argument
  # array, because an empty array under `set -u` is an error on bash 3.2.
  if [ -n "${alias:-}" ]; then
    pid=$( cc_detach_exec "$RUN_DIR/log/metrics-round.log" "$RUN_DIR/log/metrics-round.log" \
             bash "$GATE_DIR/gate.sh" metrics-round --manifest "$MANIFEST" \
               --target "$alias" --nonce "$nonce" ) || pid=""
  else
    pid=$( cc_detach_exec "$RUN_DIR/log/metrics-round.log" "$RUN_DIR/log/metrics-round.log" \
             bash "$GATE_DIR/gate.sh" metrics-round --manifest "$MANIFEST" \
               --nonce "$nonce" ) || pid=""
  fi
  if [ -z "$pid" ]; then
    log "계측 회차 실패 — 회차를 띄우지 못했다(다음 회차에 다시 센다)"
    gate_metrics_unlock "$root"
  fi
  return 0
}

gate_metrics_round_timeout() {
  # `CC_METRICS_ROUND_TIMEOUT_S` overrides the constant for tests; a value that
  # is not a positive integer reads as the constant.
  local t="${CC_METRICS_ROUND_TIMEOUT_S:-}"
  case "$t" in ''|*[!0-9]*|0) t=$GATE_METRICS_ROUND_TIMEOUT_S ;; esac
  printf '%s' "$t"
}

gate_metrics_round() {
  # gate_metrics_round <nonce> — the body of the detached `metrics-round` verb:
  # the collector, the read of its last line, the filing, the release. Always
  # returns 0.
  #
  # THE COLLECTOR IS CUT AT THE DEADLINE, and its stdout goes to a file rather
  # than through `$( )`: a program the TERM stopped can leave children that
  # still hold a pipe, and a substitution would wait for them, which is the
  # unbounded wait the deadline exists to remove. The deadline's rc (143)
  # takes the branch every failed collector already takes.
  local nonce="$1" root ledger_dir collector outf rc line
  ledger_dir=$(dirname "$LEDGER")
  root=$(gate_reap_root)
  collector=$(gate_metrics_collector)
  outf=$(mktemp "${TMPDIR:-/tmp}/cc-metrics-round.XXXXXX" 2>/dev/null || true)
  rc=0
  if [ -z "$outf" ]; then
    rc=1
  else
    # `|| rc=$?`, never `; rc=$?`: run.sh leaves errexit on, so a collector that
    # exited non-zero would otherwise end the round before its release.
    gate_metrics_timed "$(gate_metrics_round_timeout)" \
      bash "$collector" --ledger-dir "$ledger_dir" --state-root "$root" \
      >"$outf" 2>/dev/null || rc=$?
  fi
  if [ "$rc" -ne 0 ]; then
    [ -z "$outf" ] || rm -f "$outf" 2>/dev/null || true
    log "계측 회차 실패 — 수집기 rc=$rc (다음 회차에 다시 센다)"
    gate_metrics_round_release "$root" "$nonce"
    return 0
  fi
  line=$(sed -n '$p' "$outf" 2>/dev/null || true)
  rm -f "$outf" 2>/dev/null || true
  # A blocked round judges nothing and files nothing; its runs return in the
  # next round's delta. Only a log line — the row series and the skip reasons
  # are closed vocabularies.
  if [ "$(printf '%s' "$line" | jq -r '.probe // empty' 2>/dev/null || true)" = "차단" ]; then
    log "계측 회차 차단 — 미수집 $(printf '%s' "$line" | jq -r '.counts["미수집"] // "-"' 2>/dev/null || true), 다음 회차에 델타로 다시 든다"
  fi
  gate_metrics_file "$line" "$ledger_dir" || true
  gate_metrics_round_release "$root" "$nonce"
  return 0
}

gate_metrics_round_release() {
  # gate_metrics_round_release <root> <nonce> — the release, only while the
  # lock still carries this round's nonce. A round that ran past the expiry
  # finds another round's lock there and leaves it alone.
  if [ "$(cat "$1/.metrics.lock/nonce" 2>/dev/null || true)" = "$2" ]; then
    gate_metrics_unlock "$1"
  else
    log "계측 회차 — 잠금이 이 회차의 것이 아니어서 풀지 않는다"
  fi
  return 0
}

gate_metrics_skip() {
  # gate_metrics_skip <사유> <signatures> — the row that says filing did not
  # happen. Without it an unfiled trigger and a round with nothing to file read
  # the same in the morning.
  gate_append '계측 필링 건너뜀' "사유=$1" "세그먼트=-" \
    "트리거=$(gate_row_safe "${2:--}" 240)" "기록 시각=$(now_iso)" || true
}

gate_metrics_absent() {
  # gate_metrics_absent <사유> <fired count> <fired signatures> — a missing
  # prerequisite becomes a skip row only when the round fired something. A
  # close-only round has nothing to file, so "could not file" is not true of
  # it; and because the collector restates a close every round for as long as
  # the condition stays gone, writing the row here made it permanent,
  # six-hourly, and byte-identical to the real signal it exists to carry.
  if [ "${2:-0}" -gt 0 ]; then
    gate_metrics_skip "$1" "$3"
  else
    log "계측 필링 전제 부재($1) — 이 회차는 닫기만 있어 행을 남기지 않는다"
  fi
}

gate_metrics_gh_timeout() {
  # `CC_METRICS_GH_TIMEOUT_S` overrides the constant for tests; a value that is
  # not an integer reads as the constant.
  local t="${CC_METRICS_GH_TIMEOUT_S:-}"
  case "$t" in ''|*[!0-9]*) t=$GATE_METRICS_GH_TIMEOUT_S ;; esac
  printf '%s' "$t"
}

gate_metrics_timed() {
  # gate_metrics_timed <seconds> <command>... — the command's rc, or the rc of
  # a TERM (143) once it has run longer than <seconds>.
  #
  # THE COMMAND MUST BE AN EXTERNAL PROGRAM, not a function: a perl parent
  # forks it and execs it by name, which is what lets the deadline reach the
  # process that holds the caller's stdout.
  #
  # ONE PARENT AND NO WATCHER. The command runs as the leader of a process
  # group of its own — set on both sides of the fork, so the group exists before
  # either side can act — with stdin on /dev/null and every fd above 2 closed,
  # and the parent polls it without blocking. At the deadline the parent sends
  # TERM to the whole group while the leader is still unreaped (a group id
  # cannot be reused while its leader exists, even as a zombie), KILL to the
  # same group after a short grace, and only then reaps the leader; the rc is
  # 143 whatever the command's own exit was. A TERM, INT or HUP to the parent is
  # passed to the group the same way and returns 128 + that signal.
  #
  # So once this returns, the command and every descendant still in its group
  # are gone, and none of them held the caller's fds above 2. A descendant that
  # left the group (a new session, its own job control) is not reached; none of
  # this function's callers start one. There is no backgrounded `sleep` and no
  # subshell whose pid a trap could see empty.
  local secs="$1"
  shift
  perl -MPOSIX -MTime::HiRes=sleep,time -e '
    my $secs = shift @ARGV;
    my $pid = fork();
    exit 127 unless defined $pid;
    if ($pid == 0) {
      POSIX::setpgid(0, 0);
      open(STDIN, "<", "/dev/null");
      POSIX::close($_) for 3 .. 255;
      exec { $ARGV[0] } @ARGV;
      print STDERR "$ARGV[0]: $!\n";
      POSIX::_exit(127);
    }
    POSIX::setpgid($pid, $pid);
    my $got = "";
    $SIG{$_} = sub { $got = $_[0] } for qw(TERM INT HUP);
    my $deadline = time + $secs;
    my $nap = 0.005;
    while (1) {
      my $r = waitpid($pid, POSIX::WNOHANG());
      if ($r == $pid) {
        my $st = $?;
        exit(($st & 127) ? 128 + ($st & 127) : ($st >> 8));
      }
      exit 1 if $r < 0;
      last if $got ne "" || time >= $deadline;
      sleep $nap;
      $nap *= 2 if $nap < 0.05;
    }
    kill "TERM", -$pid;
    sleep 0.5;
    kill "KILL", -$pid;
    waitpid($pid, 0);
    my %num = (TERM => 15, INT => 2, HUP => 1);
    exit($got ne "" ? 128 + $num{$got} : 143);
  ' "$secs" "$@"
}

gate_metrics_scrub_env() {
  # The variables that would move a `gh` call to another repository or host.
  # `--repo` names the repository, but `GH_HOST` and the enterprise tokens still
  # pick the host it is resolved on. Called inside a subshell only.
  unset GH_REPO GH_HOST GH_ENTERPRISE_TOKEN GITHUB_ENTERPRISE_TOKEN
}

gate_metrics_gh_write() {
  # gate_metrics_gh_write <base> <token> <gh-args>... — `gh` under the
  # WRITE-scoped credential, exported inside a subshell only, so the token
  # neither outlives the call nor appears on any argv. `gh auth switch` is never
  # the answer: it changes the machine's account for every other process.
  local base="$1" tok="$2" t; shift 2
  t=$(gate_metrics_gh_timeout)
  (
    gate_metrics_scrub_env
    export GH_TOKEN="$tok"
    export GITHUB_TOKEN=""
    cd "$base" 2>/dev/null || exit 1
    gate_metrics_timed "$t" "$(gate_metrics_gh)" "$@"
  )
}

gate_metrics_repo_tag() {
  # gate_metrics_repo_tag <base> — the first 12 hex of the sha256 of the base's
  # repo-key (its absolute path with `/` turned into `-`). Instrument issues
  # carry this tag instead of anything a reader could recognise the hosting
  # checkout by. It hides the name from a reader and is not a secret: someone
  # who guesses the path can confirm the guess by hashing it.
  printf '%s' "$1" | tr / - | shasum -a 256 | cut -c1-12
}

gate_metrics_row() {
  # gate_metrics_row <결정> <issue number> <signatures> <revert verb> <reason>
  gate_append '자율 승인' "kind=metrics-filing" "결정=$1" "대상=${alias:--}" "세그먼트=-" \
    "절단점=필링" "유도 절단점=-" "등급=1" "기준=계측 트리거 $(gate_row_safe "$3" 200)" \
    "되돌리는 법=gh issue $4 $2 --repo $GATE_METRICS_REPO" "근거=$(gate_row_safe "$5" 240)" || true
}

gate_metrics_file() {
  # gate_metrics_file <journal line> <ledger dir> — what fired becomes at most
  # one issue; what the collector judged recovered is closed.
  #
  # THE SKIP REASONS ARE FOUR AND CLOSED: `번호 없음` (no observation Project
  # number configured, so no issue is created at all — an issue that lands in
  # no Project is invisible to the triage it exists for), `자격 없음` (no
  # write-scoped credential), `조회 실패` (the write credential's identity is
  # not the configured account, or a GitHub call failed — the label creation
  # before an issue is created included), `상한 도달` (an
  # instrument issue with this base's repo tag is already open). A failure to
  # add a created issue to the Project is NOT a skip: the issue stands, the
  # missing step is written beside the ledger as a command, and the filing row
  # is still written.
  #
  # `gh issue reopen` is not called anywhere — a closed instrument issue that
  # fires again is a new issue, and reopening is a human's call.
  #
  # Every issue call names `GATE_METRICS_REPO`, and the label is created before
  # each issue creation rather than assumed: gh resolves `--label` to an id
  # before it creates anything, so a missing label fails the whole creation.
  #
  # Every base's issues share that one public tracker, so each title starts
  # with `[cc-metrics <repo tag>] ` and the round sees only the open issues
  # carrying its own base's tag: the cap, the T6 comment and the close never
  # reach an issue another base filed, nor an untagged `[cc-metrics] ` one. The
  # body names the base by the same tag and never by its directory name.
  local line="$1" ledger_dir="$2" base fired close nf nc sigs project account tok login
  local list nopen open_t6 others tmp url num sig round body_lines title why tag pre
  base=$(dirname "$(dirname "$ledger_dir")")
  tag=$(gate_metrics_repo_tag "$base")
  pre="[cc-metrics $tag] "
  # A line that is not one JSON object is no round at all. Without this an
  # empty line reads as an empty count, the zero test below fails as an error
  # rather than as false, and a skip row would name a trigger that never fired.
  printf '%s' "$line" | jq -e 'type == "object"' >/dev/null 2>&1 || return 0
  fired=$(printf '%s' "$line" | jq -c '.fired // []' 2>/dev/null) || return 0
  close=$(printf '%s' "$line" | jq -c '.close // []' 2>/dev/null) || return 0
  nf=$(printf '%s' "$fired" | jq 'length')
  nc=$(printf '%s' "$close" | jq 'length')
  [ "$nf" -eq 0 ] && [ "$nc" -eq 0 ] && return 0
  # `트리거` carries the fired signatures and nothing else — never the close
  # list, which is what the collector judged gone, not what fired.
  sigs=$(printf '%s' "$fired" | jq -r '[.[].signature] | join(",")')
  round=$(printf '%s' "$line" | jq -r '.round // "-"')
  project=$(gate_metrics_config project)
  if [ -z "$project" ]; then gate_metrics_absent '번호 없음' "$nf" "$sigs"; return 0; fi
  tok=$(cred_write_token 2>/dev/null) || tok=""
  if [ -z "$tok" ]; then gate_metrics_absent '자격 없음' "$nf" "$sigs"; return 0; fi
  account=$(gate_metrics_config account)
  login=$(gate_metrics_gh_write "$base" "$tok" api user --jq .login 2>/dev/null) || login=""
  if [ -z "$login" ] || [ "$login" != "$account" ]; then
    gate_metrics_absent '조회 실패' "$nf" "$sigs"; return 0
  fi
  list=$(gate_metrics_scrub_env; GATE_ACT_CWD="$base" gate_run_readonly gate_metrics_timed "$(gate_metrics_gh_timeout)" \
           "$(gate_metrics_gh)" issue list --repo "$GATE_METRICS_REPO" --label cc-metrics --state open \
           --json number,title 2>/dev/null) \
    || { gate_metrics_absent '조회 실패' "$nf" "$sigs"; return 0; }
  list=$(printf '%s' "$list" | jq -c --arg p "$pre" '[.[] | select(.title | startswith($p))]' 2>/dev/null) \
    || { gate_metrics_absent '조회 실패' "$nf" "$sigs"; return 0; }
  nopen=$(printf '%s' "$list" | jq 'length' 2>/dev/null) || { gate_metrics_absent '조회 실패' "$nf" "$sigs"; return 0; }

  body_lines=$(printf '%s' "$fired" | jq -r '.[] | "- `\(.signature)` — \(.body)"')
  tmp=$(mktemp "${TMPDIR:-/tmp}/cc-metrics-issue.XXXXXX") || return 0
  if [ "$nf" -gt 0 ]; then
    {
      printf '런 계측 수집기의 회차 %s 에서 다음 트리거가 발화했다.\n\n' "$round"
      printf '%s\n\n' "$body_lines"
      printf -- '- 이 회차에 새로 수집된 런: %s\n' "$(printf '%s' "$line" | jq -r '.new_runs | join(", ")')"
      printf -- '- 수집 수: %s\n' "$(printf '%s' "$line" | jq -c '.counts')"
      printf -- '- 레포 표지: `%s` — 요약 파일은 그 레포의 `%s/metrics.json`\n' "$tag" "${ledger_dir#"$base"/}"
    } > "$tmp"
    if [ "$nopen" -gt 0 ]; then
      # An open T6 issue takes the other triggers as a comment: T6 is the slow
      # verdict about the window value, and a defect-shaped trigger arriving
      # while it is open is evidence about the same instrument, not a second
      # thread. Anything else open is the cap.
      open_t6=$(printf '%s' "$list" | jq -r --arg p "${pre}T6/" '[.[] | select(.title | startswith($p))][0].number // empty')
      others=""
      if [ -n "$open_t6" ]; then
        others=$(printf '%s' "$list" | jq -r --argjson f "$fired" --argjson n "$open_t6" --arg p "$pre" \
          '(.[] | select(.number == $n) | .title | ltrimstr($p)) as $t
           | [$f[].signature | select(. != $t)] | join(",")')
      fi
      if [ -n "$open_t6" ] && [ -n "$others" ]; then
        if gate_metrics_gh_write "$base" "$tok" issue comment "$open_t6" --repo "$GATE_METRICS_REPO" \
             --body-file "$tmp" >/dev/null 2>&1; then
          gate_metrics_row '코멘트' "$open_t6" "$others" close "$body_lines"
        else
          gate_metrics_skip '조회 실패' "$sigs"
        fi
      else
        gate_metrics_skip '상한 도달' "$sigs"
      fi
    else
      sig=$(printf '%s' "$fired" | jq -r '.[0].signature')
      title="$pre$sig"
      url=""
      if gate_metrics_gh_write "$base" "$tok" label create cc-metrics --repo "$GATE_METRICS_REPO" --force \
           --color 5319e7 --description '런 계측 수집기가 등록한 이슈' >/dev/null 2>&1; then
        url=$(gate_metrics_gh_write "$base" "$tok" issue create --repo "$GATE_METRICS_REPO" --title "$title" \
                --label cc-metrics --body-file "$tmp" 2>/dev/null | sed -n '$p') || url=""
      fi
      num=$(printf '%s' "$url" | sed -n 's#.*/issues/\([0-9][0-9]*\)$#\1#p')
      if [ -z "$num" ]; then
        gate_metrics_skip '조회 실패' "$sigs"
      else
        if ! gate_metrics_gh_write "$base" "$tok" project item-add "$project" --owner "$account" --url "$url" >/dev/null 2>&1; then
          mkdir -p "$ledger_dir/metrics.unfiled" 2>/dev/null || true
          {
            printf '# 이슈 #%s 를 관측 Project 에 담지 못했다\n\n' "$num"
            printf '이슈는 만들어졌고 Project 담기만 실패했다. 아래 명령으로 담는다.\n\n'
            printf '```\ngh project item-add %s --owner %s --url %s\n```\n' "$project" "$account" "$url"
          } > "$ledger_dir/metrics.unfiled/$num.md" 2>/dev/null || true
        fi
        gate_metrics_row '등록' "$num" "$sigs" close "$body_lines"
      fi
    fi
  fi
  rm -f "$tmp"

  # Closing uses the list read above. A signature is closed only when the
  # collector put it in `close` — three consecutive rounds from the journal in
  # either family, so one round never closes anything. The two families reach it
  # by different evidence, and the row says which: the threshold trigger by its
  # two signs turning good, a defect-shaped one by not being observed again.
  for sig in $(printf '%s' "$close" | jq -r '.[]'); do
    num=$(printf '%s' "$list" | jq -r --arg t "$pre$sig" '[.[] | select(.title == $t)][0].number // empty')
    [ -n "$num" ] || continue
    case "$sig" in
      T6/*) why="같은 층의 두 항이 선행 회차 중앙값 대비 좋은 쪽인 회차가 연속 3회다" ;;
      *)    why="그 조건이 평가된 회차 연속 3회 동안 다시 관측되지 않았다" ;;
    esac
    if gate_metrics_gh_write "$base" "$tok" issue close "$num" --repo "$GATE_METRICS_REPO" >/dev/null 2>&1; then
      gate_metrics_row '닫힘' "$num" "$sig" reopen "$why"
    else
      log "계측 이슈 #$num 닫기 실패 — 다음 회차에 다시 본다"
    fi
  done
  return 0
}

# ---------------------------------------------------------------------------
# Halt reporting: a run that stopped for a reason nobody intended becomes a
# GitHub issue once it has settled.
#
# NOTHING IS WRITTEN AT THE MOMENT A RUN STOPS. The run-open branch creates the
# run's record under the state root; a detached round started from the prelude
# later picks the records whose runs have settled, derives their stop events
# from what the run already recorded (`run-stops.sh`, which knows no `gh`), and
# files each unintended signature once — a comment on the open issue with the
# same title, or a new issue added to the autopilot Project. The result is a
# row in the ledger of the run that HOSTED the round and a disposition in the
# stopped run's own record, and the morning report reads both.
#
# THE POPULATION IS EVERY OPEN RECORD ON THE HOST, not the hosting run's: the
# run that stopped may never call the gate again, and nothing in the tree calls
# it for that run. A run with no record is never reported.
# ---------------------------------------------------------------------------

gate_halt_record_open() {
  # Create this run's record when there is none. NEVER TOUCH ONE THAT EXISTS:
  # the run-open branch runs again whenever the run directory is gone, and a
  # record rewritten there would lose its dispositions and retry counts. `ln`
  # makes "only when absent" atomic, as the `done` record does.
  local f dir tmp ledger mf rd
  [ -n "${RUN_ID:-}" ] && [ -n "${LEDGER:-}" ] || return 0
  f=$(gate_halt_record_path "$RUN_ID")
  [ -e "$f" ] && return 0
  dir=$(dirname "$f")
  mkdir -p "$dir" 2>/dev/null || return 0
  ledger="$LEDGER"; case "$ledger" in /*) ;; *) ledger="$(pwd)/$ledger" ;; esac
  mf="${MANIFEST:-}"; case "$mf" in ''|/*) ;; *) mf="$(pwd)/$mf" ;; esac
  rd="${RUN_DIR:-}"
  tmp=$(mktemp "$dir/.open.XXXXXX" 2>/dev/null) || return 0
  if jq -n --arg s "$GATE_HALT_SCHEMA" --arg run "$RUN_ID" --arg l "$ledger" \
       --arg m "$mf" --arg rd "$rd" --arg t "$(now_iso)" \
       '{schema: $s, run: $run, "원장": $l, "매니페스트": $m, RUN_DIR: $rd,
         "상태": "열림", "열림 시각": $t, "정착 시각": null, "종결 시각": null,
         "정착 토큰": null, "사건": {}, "최종 건너뜀": null, "런 처분": "정착 대기"}' \
       > "$tmp" 2>/dev/null; then
    ln "$tmp" "$f" 2>/dev/null || true
  fi
  rm -f "$tmp" 2>/dev/null || true
  return 0
}

gate_halt_lock() {
  # One attempt, the metrics lock's shape on its own directory.
  local lock owner ots now
  lock=$(gate_halt_lockdir)
  if mkdir "$lock" 2>/dev/null; then
    printf '%s %s\n' "$$" "$(date -u +%s)" > "$lock/owner" 2>/dev/null || true
    return 0
  fi
  owner=$(cat "$lock/owner" 2>/dev/null || true)
  ots=$(printf '%s' "$owner" | sed -n 's/^[0-9][0-9]*[[:space:]][[:space:]]*\([0-9][0-9]*\)$/\1/p')
  [ -n "$ots" ] || ots=$(gate_mtime "$lock")
  [ -n "$ots" ] || return 1
  now=$(date -u +%s)
  [ $((now - ots)) -ge "$GATE_HALT_LOCK_TTL" ] || return 1
  rm -rf "$lock" 2>/dev/null || true
  mkdir "$lock" 2>/dev/null || return 1
  printf '%s %s\n' "$$" "$(date -u +%s)" > "$lock/owner" 2>/dev/null || true
  return 0
}

gate_halt_unlock() {
  local lock dead
  lock=$(gate_halt_lockdir)
  dead="$lock.dead.$$"
  if mv "$lock" "$dead" 2>/dev/null; then
    rm -rf "$dead" 2>/dev/null || true
  fi
  return 0
}

gate_halt_cycle() {
  # Called from the prelude beside the metrics cycle; the same fixed order and
  # the same nonce binding (see `gate_metrics_cycle`). Always returns 0.
  local root stampf stamp now nonce tmp pid lock
  cc_caller_is_stage && return 0
  [ -n "${LEDGER:-}" ] || return 0
  [ -d "$(dirname "$LEDGER")" ] || return 0
  root=$(gate_reap_root)
  stampf=$(gate_halt_stamp)
  lock=$(gate_halt_lockdir)
  now=$(date -u +%s)
  stamp=$(sed -n '1s/^\([0-9][0-9]*\)$/\1/p' "$stampf" 2>/dev/null || true)
  if [ -n "$stamp" ] && [ $((now - stamp)) -lt "$GATE_HALT_INTERVAL" ]; then
    return 0
  fi
  mkdir -p "$root" 2>/dev/null || return 0
  gate_halt_lock || return 0
  stamp=$(sed -n '1s/^\([0-9][0-9]*\)$/\1/p' "$stampf" 2>/dev/null || true)
  if [ -n "$stamp" ] && [ $((now - stamp)) -lt "$GATE_HALT_INTERVAL" ]; then
    gate_halt_unlock
    return 0
  fi
  printf '%s\n' "$now" > "$stampf" 2>/dev/null || true
  nonce=$(od -An -N16 -tx1 /dev/urandom 2>/dev/null | tr -d ' \n' || true)
  tmp=""
  if [ -n "$nonce" ]; then
    tmp=$(mktemp "$lock/.nonce.XXXXXX" 2>/dev/null || true)
  fi
  if [ -z "$tmp" ] || ! printf '%s\n' "$nonce" > "$tmp" 2>/dev/null \
     || ! mv "$tmp" "$lock/nonce" 2>/dev/null; then
    [ -z "$tmp" ] || rm -f "$tmp" 2>/dev/null || true
    log "중단 리포트 회차 실패 — 회차를 띄우지 못했다(다음 회차에 다시 본다)"
    gate_halt_unlock
    return 0
  fi
  mkdir -p "$RUN_DIR/log" 2>/dev/null || true
  if [ -n "${alias:-}" ]; then
    pid=$( cc_detach_exec "$RUN_DIR/log/halt-report-round.log" "$RUN_DIR/log/halt-report-round.log" \
             bash "$GATE_DIR/gate.sh" halt-report-round --manifest "$MANIFEST" \
               --target "$alias" --nonce "$nonce" ) || pid=""
  else
    pid=$( cc_detach_exec "$RUN_DIR/log/halt-report-round.log" "$RUN_DIR/log/halt-report-round.log" \
             bash "$GATE_DIR/gate.sh" halt-report-round --manifest "$MANIFEST" \
               --nonce "$nonce" ) || pid=""
  fi
  if [ -z "$pid" ]; then
    log "중단 리포트 회차 실패 — 회차를 띄우지 못했다(다음 회차에 다시 본다)"
    gate_halt_unlock
  fi
  return 0
}

# Which event dispositions are final. A record whose events are all final is
# closed; anything else is looked at again next round.
GATE_HALT_JQ_FINAL='def fin:
  (.["처분"] | startswith("대상 아님:"))
  or .["처분"] == "건너뜀:자격 없음" or .["처분"] == "건너뜀:스코프 부족"
  or (.["처분"] == "건너뜀:조회 실패" and (.["재시도"] // 0) >= $retries)
  or ((.["처분"] == "등록" or .["처분"] == "코멘트") and (.["담기"] == "성공" or .["담기"] == "포기"));'

# The run-level disposition the morning report shows, derived from the events.
GATE_HALT_JQ_DISP='def rundisp:
  if .["상태"] == "열림" then "정착 대기"
  elif .["런 처분"] == "원장 없음" then "원장 없음"
  elif (.["사건"] | length) == 0 then "대상 없음"
  else ([.["사건"][]]) as $e
    | ([$e[] | select(.["처분"] == "미룸")] | length) as $m
    | if $m > 0 then "미룸 \($m)건"
      elif any($e[]; .["담기"] == "포기") then "담기=포기 #\([$e[] | select(.["담기"] == "포기")][0]["이슈 번호"])"
      elif any($e[]; .["처분"] == "등록") then "등록 #\([$e[] | select(.["처분"] == "등록")][0]["이슈 번호"])"
      elif any($e[]; .["처분"] == "코멘트") then "코멘트 #\([$e[] | select(.["처분"] == "코멘트")][0]["이슈 번호"])"
      elif any($e[]; .["처분"] | startswith("건너뜀:")) then [$e[] | select(.["처분"] | startswith("건너뜀:"))][0]["처분"]
      elif any($e[]; .["처분"] | startswith("대상 아님:")) then [$e[] | select(.["처분"] | startswith("대상 아님:"))][0]["처분"]
      else "정착 대기" end
  end;'

gate_halt_write() {
  # gate_halt_write <file> <json> — a temp file in the same directory, then a
  # rename, so a reader never sees half a record.
  local f="$1" tmp
  tmp=$(mktemp "$(dirname "$f")/.w.XXXXXX" 2>/dev/null) || return 1
  if printf '%s\n' "$2" > "$tmp" 2>/dev/null && mv "$tmp" "$f" 2>/dev/null; then
    return 0
  fi
  rm -f "$tmp" 2>/dev/null || true
  return 1
}

gate_halt_round() {
  # gate_halt_round <nonce> — the body of the detached `halt-report-round`
  # verb. Always returns 0; nothing here stops a run.
  #
  # Per-round state lives in globals rather than subshells, because every
  # event of every record shares one write budget, one credential check, one
  # issue list and one label creation.
  local nonce="$1" dir f ts list
  GATE_HALT_WRITES=0 GATE_HALT_CRED="" GATE_HALT_TOK="" GATE_HALT_LIST="" GATE_HALT_LIST_OK=""
  GATE_HALT_LABEL="" GATE_HALT_EV=""
  GATE_HALT_BASE=$(dirname "$(dirname "$(dirname "$LEDGER")")")
  dir="$(gate_halt_root)/runs"
  if [ -d "$dir" ]; then
    list=""
    for f in "$dir"/*.json; do
      [ -f "$f" ] || continue
      ts=$(jq -r --arg s "$GATE_HALT_SCHEMA" \
             'select(type == "object" and .schema == $s and (.["상태"] == "열림" or .["상태"] == "정착"))
              | .["열림 시각"] // ""' "$f" 2>/dev/null || true)
      [ -n "$ts" ] || continue
      list="${list}${ts}	${f}
"
    done
    while IFS='	' read -r ts f; do
      [ -n "$f" ] || continue
      gate_halt_run "$f" || true
    done <<HALTRUNS
$(printf '%s' "$list" | LC_ALL=C sort)
HALTRUNS
  fi
  gate_halt_backlog_round || true
  gate_halt_prune || true
  if [ "$(cat "$(gate_halt_lockdir)/nonce" 2>/dev/null || true)" = "$nonce" ]; then
    gate_halt_unlock
  else
    log "중단 리포트 회차 — 잠금이 이 회차의 것이 아니어서 풀지 않는다"
  fi
  return 0
}

gate_halt_prune() {
  # Closed records older than the reaper's retention are removed.
  local f now mt
  now=$(date -u +%s)
  for f in "$(gate_halt_root)/runs"/*.json; do
    [ -f "$f" ] || continue
    [ "$(jq -r '.["상태"] // empty' "$f" 2>/dev/null || true)" = "종결" ] || continue
    mt=$(gate_mtime "$f")
    [ -n "$mt" ] || continue
    [ $((now - mt)) -ge "$GATE_REAP_RETENTION" ] || continue
    rm -f "$f" 2>/dev/null || true
  done
  return 0
}

gate_halt_pin() {
  # gate_halt_pin <ledger> — the `판본` of the run's first `run` row, if it is
  # one of the shapes the gate writes; `(형식 외)` for anything else.
  local row v
  row=$( { grep -m1 '^- `run` |' "$1" 2>/dev/null || true; } )
  [ -n "$row" ] || { printf '(미상)'; return 0; }
  v=$(gate_row_field "$row" '판본')
  case "$v" in
    '(미상)'|'(고정 안 함)') printf '%s' "$v"; return 0 ;;
  esac
  if [ "${#v}" -eq 40 ] && [ "$(printf '%s' "$v" | LC_ALL=C tr -d '0-9a-f'; printf x)" = x ]; then
    printf '%s' "$v"
  else
    printf '(형식 외)'
  fi
}

gate_halt_sig_ok() {
  # A signature the body and the title may carry: a known class, and none of
  # the characters that could end a code span, a row field or a line.
  case "$1" in
    run-blocked/*|stage/*|halt/*|cone/*|run-end/*|approval/*|shift/*|stage-launch/*|park/*|segment/*|backlog-park/*) ;;
    *) return 1 ;;
  esac
  case "$1" in *'`'*|*'|'*|*'
'*) return 1 ;; esac
  [ "${#1}" -le 160 ]
}

gate_halt_body() {
  # gate_halt_body <file> <서명> <런> <판본> <정착> <비의도 수> <미결합 0|1> —
  # the public body, from an allowlist only. The tracker is public, so nothing
  # here is free text, a path, a target alias or anything a reader could tell
  # the hosting checkout by.
  local run="$3" settle="$5"
  # `<8 digits>-<8 hex>`, checked by length and by deleting the allowed bytes
  # of each half, for the reasons `gate_halt_record_path` gives.
  if [ "${#run}" -ne 17 ] || [ "${run:8:1}" != "-" ] \
     || [ "$(printf '%s' "${run:0:8}" | LC_ALL=C tr -d '0-9'; printf x)" != x ] \
     || [ "$(printf '%s' "${run:9}" | LC_ALL=C tr -d '0-9a-f'; printf x)" != x ]; then
    run='(형식 외)'
  fi
  case "$settle" in 종단|버려짐|승인대기|관측) ;; *) settle='(형식 외)' ;; esac
  {
    printf '무인 런이 의도되지 않은 이유로 멈춘 채 정착했다. 이 글은 게이트가 자동으로 남겼다.\n\n'
    printf -- '- 서명: `%s`\n' "$2"
    printf -- '- 런: `%s`\n' "$run"
    printf -- '- 판본: `%s`\n' "$4"
    printf -- '- 정착: %s\n' "$settle"
    printf -- '- 비의도 사건 수: %s\n' "$6"
    printf -- '- 관측 시각: %s\n' "$(now_iso)"
    if [ "$7" = "1" ]; then
      printf -- '- 원인 셀 미결합: 이 halt 는 같은 스테이지(교대 정지 기록이면 그 세그먼트의 교대)의 도달 park 행에 결합되지 않았다.\n'
    fi
  } > "$1"
}

gate_halt_skip() {
  # gate_halt_skip <사유> <런> <서명>
  gate_append '중단 리포트 건너뜀' "사유=$1" "런=$(gate_row_safe "$2" 80)" \
    "서명=$(gate_row_safe "$3" 200)" "세그먼트=-" "기록 시각=$(now_iso)" || true
}

gate_halt_row() {
  # gate_halt_row <결정> <issue number> <런> <서명> <담기>
  local undo
  case "$1" in
    등록) undo="gh issue close $2 --repo $GATE_HALT_REPO" ;;
    *)    undo="gh issue comment $2 --repo $GATE_HALT_REPO --delete-last" ;;
  esac
  gate_append '자율 승인' "kind=halt-report" "결정=$1" "대상=-" "세그먼트=-" \
    "절단점=필링" "유도 절단점=-" "등급=1" "기준=의도되지 않은 멈춤의 자동 리포트" \
    "되돌리는 법=$undo" "런=$(gate_row_safe "$3" 80)" "서명=$(gate_row_safe "$4" 200)" \
    "이슈=$2" "담기=$5" || true
}

gate_halt_cred() {
  # Settle this round's credential once: `ok`, `자격 없음`, `스코프 부족` or
  # `조회 실패`.
  #
  # THE SCOPE CHECK READS THE RESPONSE HEADER, case-insensitively, because a
  # classic token's scopes arrive as `X-Oauth-Scopes`. A token whose header is
  # absent (a fine-grained one) is not refused on a guess; it is tried.
  local out hdr body login sc
  [ -n "$GATE_HALT_CRED" ] && return 0
  GATE_HALT_TOK=$(cred_write_token 2>/dev/null) || GATE_HALT_TOK=""
  if [ -z "$GATE_HALT_TOK" ]; then GATE_HALT_CRED='자격 없음'; return 0; fi
  out=$(mktemp "${TMPDIR:-/tmp}/cc-halt-user.XXXXXX" 2>/dev/null) || { GATE_HALT_CRED='조회 실패'; return 0; }
  if ! gate_metrics_gh_write "$GATE_HALT_BASE" "$GATE_HALT_TOK" api -i user > "$out" 2>/dev/null; then
    rm -f "$out"; GATE_HALT_CRED='조회 실패'; return 0
  fi
  hdr=$(awk '{ sub(/\r$/, "") } /^$/ { exit } { print }' "$out" 2>/dev/null || true)
  body=$(awk 'f { print; next } { sub(/\r$/, "") } /^$/ { f = 1 }' "$out" 2>/dev/null || true)
  rm -f "$out"
  login=$(printf '%s' "$body" | jq -r '.login // empty' 2>/dev/null || true)
  if [ -z "$login" ]; then GATE_HALT_CRED='조회 실패'; return 0; fi
  sc=$(printf '%s\n' "$hdr" | awk 'tolower($0) ~ /^x-oauth-scopes:/ { sub(/^[^:]*:/, ""); print; exit }')
  if printf '%s\n' "$hdr" | awk 'tolower($0) ~ /^x-oauth-scopes:/ { f = 1 } END { exit !f }'; then
    # Matched in the shell rather than by `grep -q` on the right of a pipe:
    # under `pipefail` an early-exiting reader can fail the pipeline it matched.
    sc=" $(printf '%s' "$sc" | tr ',' ' ' | tr -s ' \t' '  ') "
    case "$sc" in
      *" repo "*|*" public_repo "*) ;;
      *) GATE_HALT_CRED='스코프 부족'; return 0 ;;
    esac
    case "$sc" in
      *" project "*) ;;
      *) GATE_HALT_CRED='스코프 부족'; return 0 ;;
    esac
  fi
  GATE_HALT_CRED='ok'
}

gate_halt_list() {
  # The open `cc-halt` issues, read once per round with the read credential.
  # `--limit` because gh's default of 30 would hide the 31st open signature
  # and file it again.
  local l
  [ -n "$GATE_HALT_LIST_OK" ] && return 0
  l=$(gate_metrics_scrub_env; GATE_ACT_CWD="$GATE_HALT_BASE" gate_run_readonly gate_metrics_timed "$(gate_metrics_gh_timeout)" \
        "$(gate_metrics_gh)" issue list --repo "$GATE_HALT_REPO" --label cc-halt --state open \
        --limit 1000 --json number,title 2>/dev/null) || return 1
  printf '%s' "$l" | jq -e 'type == "array"' >/dev/null 2>&1 || return 1
  GATE_HALT_LIST="$l"; GATE_HALT_LIST_OK=1
  return 0
}

gate_halt_add() {
  # gate_halt_add <issue number> — the autopilot Project add.
  gate_metrics_gh_write "$GATE_HALT_BASE" "$GATE_HALT_TOK" project item-add "$GATE_HALT_PROJECT" \
    --owner "$GATE_HALT_OWNER" --url "https://github.com/$GATE_HALT_REPO/issues/$1" >/dev/null 2>&1
}

gate_halt_event() {
  # gate_halt_event <event json|""> <서명> <런 행 값> <본문 런> <판본> <정착>
  # <비의도 수> <미결합 0|1> — move one reportable event one step and leave
  # its new state in GATE_HALT_EV. Returns 1 when the step took a final
  # credential skip, so the caller can record it on the run.
  #
  # THE ORDER IS FIXED: credential, identity and scope, lookup, creation or
  # comment, Project add. A Project add that failed is retried on later rounds
  # with no new row; a lookup that failed is retried with one row a round.
  local ev="$1" sig="$2" runf="$3" brun="$4" pin="$5" settle="$6" cnt="$7" unb="$8"
  local disp tries num add k ok tmp url d ttl
  [ -n "$ev" ] || ev='{"처분":"대기","재시도":0,"이슈 번호":null,"담기":"-"}'
  GATE_HALT_EV="$ev"
  disp=$(printf '%s' "$ev" | jq -r '.["처분"] // "대기"')
  tries=$(printf '%s' "$ev" | jq -r '.["재시도"] // 0')
  num=$(printf '%s' "$ev" | jq -r '.["이슈 번호"] // empty')
  add=$(printf '%s' "$ev" | jq -r '.["담기"] // "-"')
  case "$disp" in
    등록|코멘트)
      case "$add" in
        실패:*)
          [ "$GATE_HALT_WRITES" -lt "$GATE_HALT_WRITES_MAX" ] || return 0
          k=${add#실패:}; case "$k" in ''|*[!0-9]*) k=1 ;; esac
          gate_halt_cred
          ok=1
          if [ "$GATE_HALT_CRED" = ok ]; then
            GATE_HALT_WRITES=$((GATE_HALT_WRITES + 1))
            gate_halt_add "$num" && ok=0
          fi
          if [ "$ok" -eq 0 ]; then add='성공'
          elif [ $((k + 1)) -ge "$GATE_HALT_RETRIES" ]; then add='포기'
          else add="실패:$((k + 1))"
          fi
          GATE_HALT_EV=$(printf '%s' "$ev" | jq -c --arg a "$add" '.["담기"] = $a')
          ;;
      esac
      return 0 ;;
    대상\ 아님:*|건너뜀:자격\ 없음|건너뜀:스코프\ 부족) return 0 ;;
    건너뜀:조회\ 실패) [ "$tries" -lt "$GATE_HALT_RETRIES" ] || return 0 ;;
  esac

  gate_halt_cred
  case "$GATE_HALT_CRED" in
    자격\ 없음|스코프\ 부족)
      gate_halt_skip "$GATE_HALT_CRED" "$runf" "$sig"
      GATE_HALT_EV=$(printf '%s' "$ev" | jq -c --arg d "건너뜀:$GATE_HALT_CRED" '.["처분"] = $d')
      return 1 ;;
    조회\ 실패)
      gate_halt_lookup_failed "$ev" "$runf" "$sig" "$tries"
      return 0 ;;
  esac
  if [ $((GATE_HALT_WRITES + 2)) -gt "$GATE_HALT_WRITES_MAX" ]; then
    GATE_HALT_EV=$(printf '%s' "$ev" | jq -c '.["처분"] = "미룸"')
    return 0
  fi
  if ! gate_halt_list; then
    gate_halt_lookup_failed "$ev" "$runf" "$sig" "$tries"
    return 0
  fi
  tmp=$(mktemp "${TMPDIR:-/tmp}/cc-halt-issue.XXXXXX" 2>/dev/null) || return 0
  gate_halt_body "$tmp" "$sig" "$brun" "$pin" "$settle" "$cnt" "$unb"
  # The smallest open number with the exact title takes the comment; a closed
  # issue is never reopened, so a signature whose issues are all closed files
  # a new one.
  ttl="[cc-halt] $sig"
  num=$(printf '%s' "$GATE_HALT_LIST" | jq -r --arg t "$ttl" \
          '[.[] | select(.title == $t) | .number] | min // empty' 2>/dev/null || true)
  d=""
  if [ -n "$num" ]; then
    GATE_HALT_WRITES=$((GATE_HALT_WRITES + 1))
    if gate_metrics_gh_write "$GATE_HALT_BASE" "$GATE_HALT_TOK" issue comment "$num" \
         --repo "$GATE_HALT_REPO" --body-file "$tmp" >/dev/null 2>&1; then
      d='코멘트'
    fi
  else
    # The label is created before the first creation of the round rather
    # than assumed: gh resolves `--label` before it creates anything.
    if [ -z "$GATE_HALT_LABEL" ]; then
      if gate_metrics_gh_write "$GATE_HALT_BASE" "$GATE_HALT_TOK" label create cc-halt \
           --repo "$GATE_HALT_REPO" --force --color b60205 \
           --description '무인 런의 의도되지 않은 멈춤 자동 리포트' >/dev/null 2>&1; then
        GATE_HALT_LABEL=1
      fi
    fi
    if [ -n "$GATE_HALT_LABEL" ]; then
      GATE_HALT_WRITES=$((GATE_HALT_WRITES + 1))
      url=$(gate_metrics_gh_write "$GATE_HALT_BASE" "$GATE_HALT_TOK" issue create --repo "$GATE_HALT_REPO" \
              --title "$ttl" --label cc-halt --body-file "$tmp" 2>/dev/null | sed -n '$p') || url=""
      num=$(printf '%s' "$url" | sed -n 's#.*/issues/\([0-9][0-9]*\)$#\1#p')
      if [ -n "$num" ]; then
        d='등록'
        GATE_HALT_LIST=$(printf '%s' "$GATE_HALT_LIST" | jq -c --argjson n "$num" --arg t "$ttl" \
                           '. + [{number: $n, title: $t}]')
      fi
    fi
  fi
  rm -f "$tmp"
  if [ -z "$d" ]; then
    gate_halt_lookup_failed "$ev" "$runf" "$sig" "$tries"
    return 0
  fi
  GATE_HALT_WRITES=$((GATE_HALT_WRITES + 1))
  if gate_halt_add "$num"; then
    add='성공'
  else
    add='실패:1'
    mkdir -p "$(dirname "$LEDGER")/halt-report.unfiled" 2>/dev/null || true
    {
      printf '# 이슈 #%s 를 autopilot Project 에 담지 못했다\n\n' "$num"
      printf '이슈는 있고 Project 담기만 실패했다. 다음 회차가 다시 담으며, 손으로 담으려면 아래 명령을 쓴다.\n\n'
      printf '```\ngh project item-add %s --owner %s --url https://github.com/%s/issues/%s\n```\n' \
        "$GATE_HALT_PROJECT" "$GATE_HALT_OWNER" "$GATE_HALT_REPO" "$num"
    } > "$(dirname "$LEDGER")/halt-report.unfiled/$num.md" 2>/dev/null || true
  fi
  gate_halt_row "$d" "$num" "$runf" "$sig" "${add%%:*}"
  GATE_HALT_EV=$(printf '%s' "$ev" | jq -c --arg d "$d" --argjson n "$num" --arg a "$add" \
                   '.["처분"] = $d | .["이슈 번호"] = $n | .["담기"] = $a')
  return 0
}

gate_halt_lookup_failed() {
  # gate_halt_lookup_failed <event json> <런 행 값> <서명> <tries so far>
  gate_halt_skip '조회 실패' "$2" "$3"
  GATE_HALT_EV=$(printf '%s' "$1" | jq -c --argjson t "$(( $4 + 1 ))" \
                   '.["처분"] = "건너뜀:조회 실패" | .["재시도"] = $t')
}

gate_halt_run() {
  # gate_halt_run <record file> — one record, one step.
  local f="$1" rec st id ledger rd mf out agg sig cnt excl mark unb ev pin settle cur final
  rec=$(jq -c --arg s "$GATE_HALT_SCHEMA" 'select(type == "object" and .schema == $s)' "$f" 2>/dev/null || true)
  [ -n "$rec" ] || return 0
  st=$(printf '%s' "$rec" | jq -r '.["상태"]')
  id=$(printf '%s' "$rec" | jq -r '.run // ""')
  ledger=$(printf '%s' "$rec" | jq -r '.["원장"] // ""')
  rd=$(printf '%s' "$rec" | jq -r '.RUN_DIR // ""')
  mf=$(printf '%s' "$rec" | jq -r '.["매니페스트"] // ""')
  # A run whose ledger is gone is closed without a report. Fixture runs of
  # other test suites leave by this door when their temporary tree is removed.
  if [ -z "$ledger" ] || [ ! -f "$ledger" ]; then
    rec=$(printf '%s' "$rec" | jq -c --arg t "$(now_iso)" \
            '.["상태"] = "종결" | .["종결 시각"] = $t | .["런 처분"] = "원장 없음"')
    gate_halt_write "$f" "$rec" || true
    return 0
  fi
  if [ "$st" = "열림" ]; then
    cc_run_settled_for_report "$rd" "$ledger" || return 0
    settle=$(cc_run_state "$rd" "$ledger" 2>/dev/null || true)
    rec=$(printf '%s' "$rec" | jq -c --arg t "$(now_iso)" --arg k "$settle" \
            '.["상태"] = "정착" | .["정착 시각"] = $t | .["정착 토큰"] = $k')
    gate_halt_write "$f" "$rec" || return 0
  fi
  settle=$(printf '%s' "$rec" | jq -r '.["정착 토큰"] // ""')
  out=$(mktemp "${TMPDIR:-/tmp}/cc-halt-stops.XXXXXX" 2>/dev/null) || return 0
  if ! gate_halt_stops "$ledger" "$rd" "$mf" > "$out" 2>/dev/null; then
    rm -f "$out"
    log "중단 리포트 — 분류기가 실패했다(다음 회차에 다시 본다): $(gate_row_safe "$id" 80)"
    return 0
  fi
  # One line per signature: the signature, its unintended count, the first
  # intended exclusion, the intended marker (`-` as soon as any intended event
  # of it is an open wait) and whether any unintended event is unbound.
  agg=$(awk -F'\t' '
    NF < 2 { next }
    { s = $1
      if (!(s in seen)) { seen[s] = 1; order[++n] = s }
      if ($2 == "비의도") { u[s]++; if ($4 == "원인 셀 미결합") ub[s] = 1 }
      else if ($2 == "의도") {
        if (!(s in ex)) { ex[s] = $3; mk[s] = $4 }
        else if ($4 != "열린 대기 아님") mk[s] = $4
      }
    }
    END { for (i = 1; i <= n; i++) { s = order[i]
            printf "%s\t%d\t%s\t%s\t%d\n", s, u[s] + 0, (s in ex ? ex[s] : "-"), (s in mk ? mk[s] : "-"), ub[s] + 0 } }
  ' "$out" 2>/dev/null || true)
  rm -f "$out"
  pin=$(gate_halt_pin "$ledger")
  cur='[]'
  # Intended signatures first: they need no credential and no gh call.
  while IFS='	' read -r sig cnt excl mark unb; do
    [ -n "$sig" ] || continue
    gate_halt_sig_ok "$sig" || { log "중단 리포트 — 형식 밖 서명을 건너뛴다"; continue; }
    cur=$(printf '%s' "$cur" | jq -c --arg k "$sig" '. + [$k]')
    [ "$cnt" -eq 0 ] || continue
    ev=$(printf '%s' "$rec" | jq -c --arg k "$sig" '.["사건"][$k] // empty')
    [ -z "$ev" ] || continue
    [ "$mark" = "열린 대기 아님" ] || gate_halt_skip '대상 아님' "$id" "$sig"
    rec=$(printf '%s' "$rec" | jq -c --arg k "$sig" --arg d "대상 아님:$excl" \
            '.["사건"][$k] = {"처분": $d, "재시도": 0, "이슈 번호": null, "담기": "-"}')
  done <<HALTAGG
$agg
HALTAGG
  while IFS='	' read -r sig cnt excl mark unb; do
    [ -n "$sig" ] || continue
    gate_halt_sig_ok "$sig" || continue
    [ "$cnt" -gt 0 ] || continue
    ev=$(printf '%s' "$rec" | jq -c --arg k "$sig" '.["사건"][$k] // empty')
    if gate_halt_event "$ev" "$sig" "$id" "$id" "$pin" "$settle" "$cnt" "$unb"; then :; else
      rec=$(printf '%s' "$rec" | jq -c --arg c "$GATE_HALT_CRED" '.["최종 건너뜀"] = $c')
    fi
    rec=$(printf '%s' "$rec" | jq -c --arg k "$sig" --argjson e "$GATE_HALT_EV" '.["사건"][$k] = $e')
  done <<HALTAGG
$agg
HALTAGG
  # An event that has not reached a final disposition and is no longer in the
  # classifier's output resolved in the meantime; it is dropped.
  rec=$(printf '%s' "$rec" | jq -c --argjson cur "$cur" --argjson retries "$GATE_HALT_RETRIES" \
          "$GATE_HALT_JQ_FINAL"' .["사건"] |= with_entries(select((.value | fin) or (.key as $k | any($cur[]; . == $k))))')
  final=$(printf '%s' "$rec" | jq -r --argjson retries "$GATE_HALT_RETRIES" \
            "$GATE_HALT_JQ_FINAL"' if all(.["사건"][]; fin) then "1" else "0" end')
  if [ "$final" = "1" ]; then
    rec=$(printf '%s' "$rec" | jq -c --arg t "$(now_iso)" '.["상태"] = "종결" | .["종결 시각"] = $t')
  fi
  rec=$(printf '%s' "$rec" | jq -c "$GATE_HALT_JQ_DISP"' .["런 처분"] = rundisp')
  gate_halt_write "$f" "$rec" || true
  return 0
}

gate_halt_backlog_round() {
  # The fleet's parked backlog records, read without a lock — the fleet
  # publishes the backlog by rename, so a read sees one whole version.
  #
  # NO BACKFILL: the first round that finds no `fleet.seen` writes every id
  # parked at that moment as the baseline and files nothing. An id reaches
  # `fleet.seen` once its event is final; until then it waits in
  # `fleet.pending` with its retry state. A park is settled the moment it is
  # seen: nothing but a person puts a parked record back.
  local bl root seen pend parked tmp id reason sig ev cur newp
  bl=$(gate_halt_backlog)
  [ -n "$bl" ] || return 0
  root=$(gate_halt_root)
  mkdir -p "$root" 2>/dev/null || return 0
  seen="$root/fleet.seen"
  pend="$root/fleet.pending"
  parked=""
  if [ -f "$bl" ]; then
    parked=$(jq -R -r --arg s "$GATE_HALT_BACKLOG_SCHEMA" \
               'fromjson? | select(type == "object" and .schema == $s and .status == "parked")
                | [(.id | tostring), ((.park_reason // "") | tostring)] | @tsv' "$bl" 2>/dev/null || true)
  fi
  if [ ! -f "$seen" ]; then
    tmp=$(mktemp "$root/.seen.XXXXXX" 2>/dev/null) || return 0
    printf '%s\n' "$parked" | cut -f1 | sed '/^$/d' > "$tmp" 2>/dev/null || true
    mv "$tmp" "$seen" 2>/dev/null || rm -f "$tmp"
    return 0
  fi
  cur=$(jq -c 'if type == "object" then . else {} end' "$pend" 2>/dev/null || true)
  [ -n "$cur" ] || cur='{}'
  newp='{}'
  while IFS='	' read -r id reason; do
    [ -n "$id" ] || continue
    grep -Fxq -- "$id" "$seen" 2>/dev/null && continue
    case " $GATE_HALT_BACKLOG_REASONS " in
      *" $reason "*) [ -n "$reason" ] || reason='미분류' ;;
      *) reason='미분류' ;;
    esac
    sig="backlog-park/$reason"
    ev=$(printf '%s' "$cur" | jq -c --arg k "$id" '.[$k] // empty')
    gate_halt_event "$ev" "$sig" '-' '(형식 외)' '(미상)' '관측' 1 0 || true
    if [ "$(printf '%s' "$GATE_HALT_EV" | jq -r --argjson retries "$GATE_HALT_RETRIES" \
              "$GATE_HALT_JQ_FINAL"' if fin then "1" else "0" end')" = "1" ]; then
      printf '%s\n' "$id" >> "$seen"
    else
      newp=$(printf '%s' "$newp" | jq -c --arg k "$id" --argjson e "$GATE_HALT_EV" '.[$k] = $e')
    fi
  done <<HALTBL
$parked
HALTBL
  gate_halt_write "$pend" "$newp" || true
  return 0
}

gate_verb_wait() {
  # gate_verb_wait <segment> <interval-seconds> <timeout-seconds>
  #
  # Block until the segment's dispatched stage terminates, then exit with the
  # stage's own rc — or 11/12/13/14/16 (see the exit-code table at the top).
  #
  # THE AUTHORITY IS THE LEDGER READ IN STEP (3); STEP (1) IS A FAST PATH IN
  # FRONT OF IT. This call's own prelude may have just settled the segment, and
  # `GATE_SETTLED_SEGMENTS` — a shell variable of this process, never a file —
  # is how the verb knows without a second read. The two must agree; the ledger
  # wins if they ever do not, and the design is correct with (1) deleted.
  #
  # WRITES NO ROW, EVALUATES NO BOUNDARY, TAKES NO DIGEST. It is not an act:
  # the stage is not this shell's child, so waiting is `kill -0` plus the
  # fingerprint (`cc_stage_is_live`), and a boundary evaluated on entry to a
  # two-hour block would fire B1 on a router doing exactly the right thing.
  #
  # THE ONE THING IT DOES EVALUATE IS THE SHIFT'S HARD CONTEXT CAP, and that
  # happens on the dispatch arm before this function is entered, so it still
  # writes no row here: a shift already over the cap comes back 15 instead of
  # blocking, and everything below stays as it was. A boundary is a question for
  # a person; the cap is a routing instruction, which is why one is excluded
  # here and the other is not.
  #
  # RESOLUTION ORDER on every poll:
  #   (1) settled by this call's prelude → 12
  #   (2) stage alive, or its supervisor alive → heartbeat, keep polling
  #   (3) `<seg>.attempt` pinned and a `stage-result` row for that attempt →
  #       `외부 종료` is 12, otherwise the row's `종료 코드`
  #   (3b) pinned, no such row, and a `blocked` row naming `계보=B:<seg>#<N>`
  #       of that attempt → 16 (the supervisor parked before spawning)
  #   (4) no `<seg>.attempt` → 11
  #   (5) pinned but no row: wait one grace period, re-run (2)/(3); still
  #       nothing → remove `.sup`/`.sup.start`/`.launch`, exit 14
  # `--timeout` elapsed while (2) still holds → 13.
  local seg="$1" interval="$2" timeout="$3"
  local start now elapsed last_beat=0 attempt row code klass grace_done=0 p s
  start=$(date -u +%s)
  while :; do
    now=$(date -u +%s); elapsed=$((now - start))
    case " $GATE_SETTLED_SEGMENTS " in
      *" $seg "*)
        printf '%s [wait] %s 고아였고 정산됨 — rc=%s\n' "$(now_iso)" "$seg" "$GATE_EXIT_WAIT_SETTLED"
        return "$GATE_EXIT_WAIT_SETTLED" ;;
    esac
    if cc_stage_is_live "$RUN_DIR" "$seg" || cc_supervisor_is_live "$RUN_DIR" "$seg"; then
      if [ "$elapsed" -ge "$timeout" ]; then
        printf '%s [wait] %s timeout — rc=%s\n' "$(now_iso)" "$seg" "$GATE_EXIT_WAIT_TIMEOUT"
        return "$GATE_EXIT_WAIT_TIMEOUT"
      fi
      if [ "$last_beat" = "0" ] || [ $((now - last_beat)) -ge "$interval" ]; then
        p=$( { cat "$RUN_DIR/$seg.pid" 2>/dev/null || true; } | tr -d '[:space:]')
        s=$( { cat "$RUN_DIR/$seg.sup" 2>/dev/null || true; } | tr -d '[:space:]')
        # A supervisor that has not spawned yet is waiting for an account, and
        # "살아 있음 — pid -" would read as a launch that is about to fail.
        if [ -z "$p" ] && cc_waiting_is_member "$RUN_DIR" "$LEDGER" "$seg"; then
          printf '%s [wait] %s 대기 중 — 감독 %s · 그룹 %s · 까지 %s\n' \
            "$(now_iso)" "$seg" "${s:--}" \
            "$(cc_waiting_field "$RUN_DIR/$seg.waiting" '그룹')" \
            "$(wait_epoch_iso "$(cc_waiting_field "$RUN_DIR/$seg.waiting" '까지')")"
        else
          printf '%s [wait] %s 살아 있음 — pid %s · 감독 %s · 경과 %s초\n' \
            "$(now_iso)" "$seg" "${p:--}" "${s:--}" "$elapsed"
        fi
        last_beat=$now
      fi
      sleep "$GATE_WAIT_POLL_SECONDS"
      continue
    fi
    attempt=$( { cat "$RUN_DIR/$seg.attempt" 2>/dev/null || true; } | tr -d '[:space:]')
    if [ -z "$attempt" ]; then
      printf '%s [wait] %s 파견 기록 없음 — rc=%s\n' "$(now_iso)" "$seg" "$GATE_EXIT_WAIT_NONE"
      return "$GATE_EXIT_WAIT_NONE"
    fi
    row=$( gate_stage_result_rows_of "$seg" \
           | { grep -F "실행 버전=$attempt " || true; } | tail -1)
    if [ -n "$row" ]; then
      klass=$(printf '%s' "$row" | tr '|' '\n' | sed -n 's/^ *종단 부류=//p' | sed 's/[[:space:]]*$//' | tail -1)
      if [ "$klass" = "외부 종료" ]; then
        printf '%s [wait] %s 고아였고 정산됨 — rc=%s\n' "$(now_iso)" "$seg" "$GATE_EXIT_WAIT_SETTLED"
        return "$GATE_EXIT_WAIT_SETTLED"
      fi
      code=$(printf '%s' "$row" | tr '|' '\n' | sed -n 's/^ *종료 코드=//p' | sed 's/[[:space:]]*$//' | tail -1)
      case "$code" in
        ''|*[!0-9]*)
          printf 'gate: the `stage-result` row of this attempt has no numeric exit code (%s#%s: `종료 코드`=%s)\n' \
            "$seg" "$attempt" "${code:-(none)}" >&2
          return 1 ;;
      esac
      printf '%s [wait] %s 종단 — rc=%s\n' "$(now_iso)" "$seg" "$code"
      return "$code"
    fi
    # (3b) A supervisor that parked before it ever spawned leaves no
    # `stage-result` — the stage never ran — but it leaves a `blocked` row whose
    # `근거` names this attempt's lineage. Without this arm that attempt falls to
    # (5), reads as a launch that failed, and the router dispatches it again into
    # the same exhausted group.
    if [ -n "$( { gate_rows 'blocked' | cc_rows_naming_lineage "B:$seg#$attempt" || true; } | tail -1)" ]; then
      printf '%s [wait] %s 라우터 park — 시도 %s — rc=%s\n' "$(now_iso)" "$seg" "$attempt" "$GATE_EXIT_ROUTE"
      return "$GATE_EXIT_ROUTE"
    fi
    # Pinned, nothing alive, no row. Once: a grace period, because the
    # supervisor may be between consuming the token and writing `.pid`, or
    # between the child's exit and the row's append. Twice: a launch that
    # never produced a supervisor row.
    if [ "$grace_done" = "0" ]; then
      grace_done=1
      sleep "$GATE_WAIT_GRACE_SECONDS"
      continue
    fi
    rm -f "$RUN_DIR/$seg.sup" "$RUN_DIR/$seg.sup.start" "$RUN_DIR/$seg.launch"
    printf '%s [wait] %s 기동 실패 — 시도 %s 의 행이 없습니다 (잔여 sup·launch 를 지웠습니다) — rc=%s\n' \
      "$(now_iso)" "$seg" "$attempt" "$GATE_EXIT_WAIT_NOROW"
    return "$GATE_EXIT_WAIT_NOROW"
  done
}

gate_reattach_anchor_write() {
  # gate_reattach_anchor_write <seg> — `$RUN_DIR/<seg>.anchor` for the
  # re-attachment being dispatched, or no file. Six lines: the base's kind, the
  # base epoch, this dispatch's epoch, `kern.sleeptime` and `kern.waketime` at
  # this moment, and the window kind of the cut (`five_hour`, `seven_day`, `-`).
  #
  # THE BASE IS THE MOMENT THE RUN COULD FIRST HAVE RE-ATTACHED, by class:
  #   리셋 / 한도 해제  the cut attempt's reset, or an earlier `한도 해제` row
  #                     below the cut row — raised to the end of the cut
  #                     attempt (its stream's mtime) when it is earlier still;
  #   깨어남            the host slept before the relay could wake for that
  #                     base (sleep start ≤ base + grace + two polls) and woke
  #                     after it: the wake time;
  #   재진입            a `재진입` row below the cut row;
  # and when a limit class and the reboot class both stand, the later of the
  # two, with that one's kind. Any other re-attachment has no base.
  local seg="$1" f="$RUN_DIR/$1.anchor" hit cutln row klass att stream r lc base="" kind="" mt
  local win="-" g sl wk rb t
  rm -f "$f"
  [ -n "${LEDGER:-}" ] && [ -f "$LEDGER" ] || return 0
  hit=$(LC_ALL=C awk -v k="| 스테이지=$seg |" '
    /^- `stage-result` / { if (index($0, k) > 0) { n = NR; l = $0 } }
    END { if (n) printf "%s\t%s", n, l }' "$LEDGER" 2>/dev/null || true)
  [ -n "$hit" ] || return 0
  cutln=${hit%%"$(printf '\t')"*}
  row=${hit#*"$(printf '\t')"}
  klass=$(gate_row_field "$row" '종단 부류')
  att=$(gate_row_field "$row" '실행 버전')
  stream="$RUN_DIR/log/$seg#$att.json"
  case "$klass" in
    한도\ 종료|크래시)
      r=$(gate_cut_reset_at "$stream")
      lc=$(cc_relay_cut_cleared_at "$LEDGER" "$seg")
      [ -z "$r" ] || { base="$r"; kind="리셋"; }
      if [ -n "$lc" ] && { [ -z "$base" ] || [ "$lc" -lt "$base" ]; }; then
        base="$lc"; kind="한도 해제"
      fi
      if [ -n "$base" ]; then
        mt=$(gate_mtime "$stream")
        case "$mt" in ''|*[!0-9]*) : ;; *) [ "$base" -ge "$mt" ] || base="$mt" ;; esac
        win=$(jq -R -n -r '
          reduce (inputs | (try fromjson catch null) | objects
                  | select(.type == "rate_limit_event")) as $f (null; $f)
          | (.rate_limit_info? // {}) | .rateLimitType // empty
          | select(type == "string")' "$stream" 2>/dev/null || true)
        case "$win" in five_hour|seven_day) : ;; *) win="-" ;; esac
        g=$(cc_reset_grace)
        sl=$(sleep_epoch); wk=$(wake_epoch)
        case "$sl$wk" in
          *[!0-9]*|'') : ;;
          *) if [ -n "$sl" ] && [ -n "$wk" ] \
                && [ "$sl" -le $((base + g + 2 * GATE_WAIT_POLL_SECONDS)) ] \
                && [ "$wk" -gt "$base" ]; then
               base="$wk"; kind="깨어남"
             fi ;;
        esac
      fi ;;
  esac
  t=$(LC_ALL=C awk -F'|' -v n="$cutln" '
    function trim(s) { sub(/^[ \t]+/, "", s); sub(/[ \t]+$/, "", s); return s }
    NR > n && /^- `재진입` / {
      for (i = 2; i <= NF; i++) { f = trim($i); if (index(f, "기록 시각=") == 1) at = substr(f, length("기록 시각=") + 1) }
    }
    END { printf "%s", at }' "$LEDGER" 2>/dev/null || true)
  rb=""
  [ -z "$t" ] || rb=$(cc_iso_to_epoch "$t")
  if [ -n "$rb" ] && { [ -z "$base" ] || [ "$rb" -gt "$base" ]; }; then
    base="$rb"; kind="재진입"
  fi
  [ -n "$base" ] || return 0
  printf '%s\n%s\n%s\n%s\n%s\n%s\n' "$kind" "$base" "$(date -u +%s)" \
    "$(sleep_epoch)" "$(wake_epoch)" "$win" > "$f.tmp.$$" 2>/dev/null \
    && mv -f "$f.tmp.$$" "$f" 2>/dev/null || rm -f "$f.tmp.$$" 2>/dev/null
  return 0
}

gate_reattach_anchor_fields() {
  # gate_reattach_anchor_fields <seg> — set the values of the four fields a
  # `stage-result` row carries when `<seg>.anchor` exists: `GATE_RA_BASE`
  # (`재부착 기준=<kind>@<epoch>`), `GATE_RA_DELAY` (`재부착 지연=<dispatch −
  # base>`), `GATE_RA_WIN` (`창 종류`) and `GATE_RA_SLEEP` (`마지막 절전=
  # <sleeptime>-<waketime>` read as the row is written). No record, all four
  # empty — the row is then the row written before them. The call sites spell
  # the keys themselves, so the field table's lint reads them.
  local f="$RUN_DIR/$1.anchor" kind base disp win sl wk
  GATE_RA_BASE=""; GATE_RA_DELAY=""; GATE_RA_WIN=""; GATE_RA_SLEEP=""
  [ -s "$f" ] || return 0
  kind=$(sed -n '1p' "$f" 2>/dev/null || true)
  base=$(sed -n '2p' "$f" 2>/dev/null | tr -d '[:space:]')
  disp=$(sed -n '3p' "$f" 2>/dev/null | tr -d '[:space:]')
  win=$(sed -n '6p' "$f" 2>/dev/null | tr -d '[:space:]')
  case "$kind" in 리셋|'한도 해제'|깨어남|재진입) : ;; *) return 0 ;; esac
  case "$base$disp" in ''|*[!0-9]*) return 0 ;; esac
  [ -n "$base" ] && [ -n "$disp" ] || return 0
  sl=$(sleep_epoch); wk=$(wake_epoch)
  GATE_RA_BASE="$kind@$base"
  GATE_RA_DELAY=$((disp - base))
  GATE_RA_WIN="${win:--}"
  GATE_RA_SLEEP="${sl:--}-${wk:--}"
  return 0
}

gate_record_stage_outcome() {
  # gate_record_stage_outcome <alias> <segment> <kind> <attempt> <rc> <dispatch-line> [stream] [window] [effort] [account]
  #
  # Two of the five row kinds that had no writer at all. Their absence was not
  # bookkeeping: `cost` is the only input `gate_b4_cost` has, so the cost
  # boundary read an empty set, took its fail-open guard, and could never fire
  # however low the declared ceiling was — the guard treats a missing value as
  # temporary and with no writer the absence is permanent. `stage-result` is
  # what the morning report counts terminal classes from, and what the
  # implementation-review separation rule reads ancestry from; with no rows that
  # rule returns early and passes vacuously on every run it exists to catch.
  #
  # THE SIXTH ARGUMENT IS THE LEDGER LINE OF THIS ATTEMPT'S DISPATCH ROW, not
  # a row count. The count meant "the stage itself called the gate at least
  # once" only while the dispatch blocked; with the supervisor detached the
  # router writes rows for the stage's whole lifetime, and a global compare
  # would file an empty stage as `정상 완료`. Empty is read as line 0.
  local alias="$1" seg="$2" kind="$3" attempt="$4" rc="$5" before="$6"
  # THE STREAM THIS DISPATCH ACTUALLY WROTE, handed down rather than re-derived.
  # Re-deriving is how the writer and the reader came apart once already; the
  # unsuffixed name stays as the fallback for a caller that predates the argument.
  # `given` keeps whether the stream was handed down at all, before the fallback
  # below overwrites `out`: only a handed-down stream is the pinned attempt's own,
  # and only that one is judged for a usage-limit death.
  local out="${7:-}" given="${7:-}" res cost subtype sid klass after denials n_stage psha iserr lx why
  [ -n "$out" ] || out="$RUN_DIR/log/$seg.json"
  # THE WINDOW THE LAUNCH READ, handed down by the supervisor that also put it
  # on the argv; a caller without it falls back to the `.window` record, and
  # with neither the row says `(미상)` rather than guessing a layer.
  local window="${8:-}"
  [ -n "$window" ] || window=$(gate_window_sidecar_read "$seg")
  # THE LANE IS NOT HANDED DOWN AND NOT RESOLVED HERE. The launch wrote it to
  # the same record before the CLI started, and the record outlives this call.
  local lane acct
  lane=$(gate_lane_sidecar_read "$seg")
  # The account the launch wrote on the record's fourth line, through the one
  # parser both writers use; no fourth line means no `계정` field on the row.
  # A routed supervisor hands down the account its launch token carried
  # instead: the record is named by the segment and a later attempt of the same
  # segment can have rewritten it while this one ran.
  # Held to the same rule as the record's line: `-`, an id the account rule
  # accepts, or `(미상)`.
  if [ -n "${10:-}" ]; then
    acct="${10}"
    [ "$acct" = "-" ] || run_ledger_account_ok "$acct" || acct='(미상)'
  else
    acct=$(stage_account_of "$seg")
  fi
  # THE EFFORT THE LAUNCH PUT ON THE ARGV, handed down like the window; `-` when
  # the switch turned it off or the caller predates the argument. The served
  # model is read from the stream, not handed down: it is what answered, not
  # what was asked for.
  local effort="${9:--}" served
  served=$(stage_served_model_of "$out")

  res=$( { grep '"type":"result"' "$out" 2>/dev/null || true; } | tail -1)
  # A launch that never STARTED is reported as such. With no result line the
  # classification falls to `크래시`, which is the right bucket — the dispatch
  # did fail — but it reads as "the stage ran and died", and a reader then looks
  # for the stage's own fault. Measured: an unbound variable in the launch path
  # left `종단 부류=크래시 rc=1` in the ledger with no pid file and no process
  # ever created, and the diagnosis went to the stage first.
  [ -n "$res" ] || warn "the stage process did not start ($seg) — there is no terminal result line. Look at the launch path, not at the stage"
  cost=$(printf '%s' "$res"    | jq -r '.total_cost_usd // empty' 2>/dev/null || true)
  subtype=$(printf '%s' "$res" | jq -r '.subtype // empty'        2>/dev/null || true)
  sid=$(printf '%s' "$res"     | jq -r '.session_id // empty'     2>/dev/null || true)

  # The terminal class, from what the GATE can observe and nothing more. A stage
  # that performed a gated act left rows; one that left none either never got
  # started or arrived somewhere it would not pass. `permission_denials` is the
  # trace that separates those two — the contract asks for exactly that
  # discriminator, "a trace of reaching a decision point", and a denial is one.
  #
  # `적용 불명` is the one class NOT written here, and the omission is
  # deliberate: it is a claim about the apply step's result and its only writer
  # is the driver's apply-outcome-unknown arm. `의도된 park` IS written here —
  # the arm below reads it from the stage's halt record, which the halt
  # contract owns — and `외부 종료` is written by the prelude's settlement,
  # never by this function, because its defining check is the ABSENCE of the
  # result envelope this function reads. `한도 종료` is written here, and only
  # from inside the `크래시` arm.
  #
  # THE FOURTH CONDITION: a `자율 승인` row stamped `행위자=스테이지` for THIS
  # segment, landing AFTER this attempt's dispatch row. Router rows written
  # while the stage ran do not count; a stage that never called the gate has
  # none. `awk 'NR>n'` reads the ledger from that line on; an empty or
  # non-numeric `before` reads the whole file.
  case "$before" in ''|*[!0-9]*) before=0 ;; esac
  # The stage's rows carry `rowseg`, which is `-` for the run-scope design step
  # (see `gate_stage_row_segment`); its `stage-result` row below carries the same.
  local rowseg
  rowseg=$(gate_stage_row_segment "$seg" "$kind")
  after=$( { awk -v n="$before" 'NR>n' "$LEDGER" 2>/dev/null || true; } \
           | { grep -E '^- `자율 승인`' || true; } \
           | { grep -F '| 행위자=스테이지 |' || true; } \
           | { grep -F "세그먼트=$rowseg " || true; } | gate_count)
  # `is_error` is read as well as the status and the subtype. Measured: a stage
  # that slept mid-response returned `subtype: success` WITH `is_error: true`,
  # and only the non-zero status caught it — the same object with a zero status
  # would have been classified as a normal completion.
  iserr=$(printf '%s' "$res" | jq -r '.is_error // false' 2>/dev/null || true)
  # A STAGE THAT PARKED ITSELF IS NOT A SUCCESS, and this arm could not tell the
  # difference. The halt contract names the orchestrator as the reader and three
  # skills write the record, but nothing on this path opened it — so a stage that
  # stopped deliberately, wrote down why, and left the tree untouched was filed
  # as `정상 완료` when it had written a row, and as `공허한 성공` when it had
  # not. Measured twice in one night: a stage refuted a pre-implementation check
  # and halted correctly, and the only way to see that was to open the worktree
  # by hand.
  #
  # The record is checked BEFORE the row-count arms because its answer is more
  # specific than theirs. A halted stage may well have written rows first.
  #
  # THE NAME COMES FROM THE DRIVER'S OWN RULE, not from a second copy of it. This
  # side used to try the attempt-scoped name and fall back to the unsuffixed one
  # WHATEVER THE PIN SAID, which is the opposite of what the driver does: with a
  # pin the scoped name is the only answer. Two readers of one artifact then
  # disagreed about the same dispatch — a run started before the driver scoped its
  # stage ids leaves an unsuffixed record, and resuming that run id pins attempt 2,
  # so the driver saw no record and classified `정상 완료` while this side found the
  # first attempt's record and wrote `의도된 park` into the ledger. The row and the
  # control flow then describe different runs.
  local haltf
  haltf=$(halt_record_path "$seg")
  if [ "$rc" = "0" ] && [ -s "$haltf" ] \
     && [ "$( { grep -vE '^[[:space:]]*$' "$haltf" 2>/dev/null || true; } | tail -1)" = '<!-- /cc-pipeline-halt v1 -->' ]; then
    klass='의도된 park'
  # A MODEL SAFETY REFUSAL, before the crash arm and at either exit code: the
  # driver's reader on the same stream (`stage_refusal_exit`), so the two
  # writers of a row file one attempt alike. Without it a refused stage is a
  # `크래시` here, and a crash buys a fresh dispatch that writes over what the
  # refused stage had saved.
  elif stage_refusal_exit "$out"; then
    klass='거절 종료'
  elif [ "$rc" != "0" ] || [ "${subtype:-}" != "success" ] || [ "${iserr:-false}" = "true" ]; then
    klass='크래시'
    # A STAGE THAT DIED OF THE USAGE LIMIT BY ITSELF is `한도 종료`, carved out
    # of this arm only: every such row is one this arm used to file as `크래시`,
    # and readers dispose of the two alike. It needs a non-zero exit, a stream
    # handed down by the caller, and no halt record — the halt arm above stands
    # only at rc 0, so a halted attempt with a non-zero exit arrives here and
    # stays `크래시`. A limit-shaped stream that misses one of those, or whose
    # shape is incomplete, stays `크래시` and says so on stderr, which is the
    # supervisor's log.
    if [ -n "$given" ] && [ ! -s "$haltf" ]; then
      lx=0; why=$(stage_limit_exit "$out") || lx=$?
      if [ "$lx" = "0" ] && [ "$rc" != "0" ]; then klass='한도 종료'
      elif [ "$lx" = "0" ]; then warn "한도 형상 불완전 (rc) $out"
      elif [ "$lx" = "3" ]; then warn "한도 형상 불완전 ($why) $out"
      fi
    fi
  # A DESIGN STAGE IS ASKED FOR ITS ARTIFACT, because the row-count arm below
  # accepts a ledger row as proof of production and a design stage writes rows
  # all through its discussion. The driver's own arm has always crossed the two
  # authored facts — the freeze literal in the stage's stream and the frozen
  # status line in the document — but only the driver did; this side never
  # looked at the document at all, so the same stage was `정상 완료` here and a
  # hollow success there. Measured three times: a stage whose team member ended
  # its turn without a witness and left the process nothing to wait for; a stage
  # that said what it would sweep next and ended at that turn boundary with the
  # body still in its draft; and a stage killed at the background-wait ceiling
  # mid-discussion. All three returned rc=0 with `subtype: success`, all three
  # had written rows, and all three left a document nobody could use.
  #
  # `공허한 성공` rather than a new class: the vocabulary already names a stage
  # that terminated cleanly and produced nothing, and the redispatch window is
  # keyed on that name plus an absent-or-stub document.
  elif [ "$kind" = "design" ] \
       && ! { grep -qF "$LIT_DESIGN_TERMINAL" "$out" 2>/dev/null && doc_is_frozen "${DOC:-}"; }; then
    klass='공허한 성공'
  # A base split stage is asked for its artifact the same way: its terminal
  # literal in the stream and a registry complete for the current document.
  elif [ "$kind" = "split" ] \
       && ! { grep -qF "$LIT_SPLIT_TERMINAL" "$out" 2>/dev/null && split_registry_complete "${DOC:-}"; }; then
    klass='공허한 성공'
  # A visual stage too: its terminal literal in the stream and its sidecar at
  # `검토 통과`. Either alone is a stage that said it finished over screens nobody
  # reviewed, or reviewed screens whose stage never said it was done.
  elif [ "$kind" = "visual" ] \
       && ! { grep -qF "$LIT_VISUAL_TERMINAL" "$out" 2>/dev/null && visual_sidecar_reviewed "${DOC:-}"; }; then
    klass='공허한 성공'
  # An audit stage is asked for its artifact by the driver's predicate: the
  # terminal phrase, a reader report, and exactly one skeletal-grade fence in
  # the audit report. Without the fence nobody can say whether the document
  # still needs a re-convergence, so the audit has not produced what it owes.
  elif [ "$kind" = "audit" ] && ! audit_artifact_complete "$out"; then
    klass='공허한 성공'
  # AN IMPLEMENT PROCESS B is asked for its own residual result lines. Its rows
  # prove it acted, not that it wrote the W1 flip or the W2 note of every
  # `### R<n>` that is its share — and nothing else reads those lines before the
  # merge, after which the segment cannot be sent back. Process A emits a plan
  # and edits nothing, so it is not asked. `공허한 성공` for the same reason as
  # the two arms above: the continuation is keyed on that name, and it carries
  # the missing headings in its message (`gate_continuation_argv`).
  elif [ "$kind" = "implement" ] \
       && gate_plan_rows_of "$seg" | implement_process_b \
       && [ -n "$(residual_share_missing "${DOC:-}" "$seg" "$RUN_DIR/halt" "$RUN_DIR/$seg.plan.md")" ]; then
    klass='공허한 성공'
  elif [ "${after:-0}" -ge 1 ]; then
    klass='정상 완료'
  else
    denials=$( { grep -c 'permission_denials' "$out" 2>/dev/null || true; } | tail -1)
    if [ "${denials:-0}" != "0" ]; then klass='산출물 없는 정지'; else klass='공허한 성공'; fi
  fi
  # `일시 원인` ON A CRASH ROW AND ON NO OTHER. Whether the crash was a dropped
  # connection is the premise the router's `--recovery '전송 단절'` dispatch is
  # admitted on, and the router cannot call the driver's reader; the row is
  # where it reads it. Judged only on a stream handed down by the caller, the
  # same rule the limit carve-out above keeps: only that one is the pinned
  # attempt's own, so a crash without one is `아니오`.
  local transient=""
  if [ "$klass" = "크래시" ]; then
    transient='아니오'
    if [ -n "$given" ] && stage_transient_exit "$out"; then transient='예'; fi
  fi

  # `plan_sha256`, and only for the implement arm. That arm is split into two
  # processes and process B enters ONLY when this field is on the row — its
  # admission predicate says so and forbids re-deriving a plan instead. Nothing
  # wrote the field, so every dispatch resolved as process A, emitted the plan
  # again and stopped. The tree stayed clean, which is correct for process A, so
  # "A finished" and "B will never come" were indistinguishable from outside.
  #
  # Taken from the stage's own emitted object first, because that is the digest
  # the admission predicate compares against; the plan FILE is the fallback, and
  # it is a fact the gate can compute rather than one the stage reports.
  psha=""
  if [ "$kind" = "implement" ]; then
    # FOUR PATHS, and the two that matter are the last two — the first two ask
    # for JSON the stage does not emit. What a process-A stage actually writes
    # is PROSE: a `## 프로세스 A 완료 — 계획 방출` section carrying
    # `**plan_sha256**: <hex>` and a `**계획**:` path. Measured: a stage
    # completed normally, emitted its plan and stated the digest, and the row
    # still had no field — so process B could not enter and every dispatch
    # re-ran as process A.
    psha=$(printf '%s' "$res" | jq -r '(.result // empty) | fromjson? | .plan_sha256 // empty' 2>/dev/null || true)
    [ -n "$psha" ] || psha=$(printf '%s' "$res" | jq -r '.plan_sha256 // empty' 2>/dev/null || true)
    # The stage's own terminal text. `[0-9a-f]\{64\}` rather than a looser
    # match so a sentence mentioning the field cannot be mistaken for a value.
    # `|| true` like the two siblings above: this function runs under the
    # supervisor's `set -euo pipefail`, where a bare assignment whose pipeline
    # failed ends the process — before the row. A result line that is not JSON
    # is an absent value, not a reason to leave no record.
    if [ -z "$psha" ]; then
      psha=$( { printf '%s' "$res" | jq -r '.result // empty' 2>/dev/null \
             | sed -n 's/.*plan_sha256[^0-9a-f]*\([0-9a-f]\{64\}\).*/\1/p' | sed -n '1p'; } || true)
    fi
    # And the plan file, at the name the stage actually uses — `<segment>.plan.md`
    # in the run directory, not `implement-<segment>.plan.md`.
    if [ -z "$psha" ] && [ -f "$RUN_DIR/$seg.plan.md" ]; then
      psha=$(shasum -a 256 "$RUN_DIR/$seg.plan.md" | cut -d' ' -f1)
    fi
    if [ -z "$psha" ] && [ -f "$RUN_DIR/implement-$seg.plan.md" ]; then
      psha=$(shasum -a 256 "$RUN_DIR/implement-$seg.plan.md" | cut -d' ' -f1)
    fi
  fi
  # THE DOCUMENT'S HASH AT EACH STAGE TERMINATION. The kickoff freezes one, the
  # audit is contractually required to EDIT the document (its reconciliation
  # pass is where findings land, and the largest routing bucket is "apply"), and
  # the implement stage compares against the frozen value — so audit followed by
  # implement in one run halts on freeze-mismatch every time. That is the basic
  # shape of the pipeline blocking itself.
  #
  # The gate is the only writer here, the row is chained like any other, and the
  # value is measured rather than supplied by the stage. What it does NOT decide
  # is whether post-audit bytes should be re-audited before implementation —
  # that question is open (#307) and this row is what makes it answerable, since
  # until now nothing recorded that the bytes had moved at all.
  #
  # THE PATH IS `DOC`, RESOLVED ONCE BY THE PRELUDE. `derive_paths_from_manifest`
  # already turns the manifest key into a path by the contract's rule —
  # repo-relative under `BASE`, then the absolute form, then the composed form
  # when neither exists — and every gate verb runs it before reaching here.
  # This block used to spell two of those three branches again, inline, as bare
  # assignments: `dcur=$( { [ -f "$BASE/$dkey" ] && shasum … ; } | cut … )`.
  # With the file absent the group exits 1, `pipefail` carries that out of the
  # pipeline, and under the supervisor's `set -euo pipefail` the process ended
  # on that line — before the `stage-result` row, the `cost` row, the emitted
  # judgment and the cleanup. Inside the old blocking dispatch the recorder sat
  # on the left of `|| rc=$?`, where errexit is off for the whole body, so the
  # same line was harmless there; the detached supervisor calls it plainly. An
  # absolute-path key — the contract's normal shape for a document outside the
  # repository — made the death deterministic at every termination, and the
  # re-dispatch died on the same line. Measured on three key shapes.
  #
  # An `if`, not `[ … ] && dcur=…`: when the condition is false that compound
  # command's own status is non-zero, which is the same failure in a different
  # spelling. A run without a document leaves `DOC` empty (its `DOC_KEY` is the
  # anchor key, so the key is not the discriminator).
  local dcur=""
  if [ -n "${DOC:-}" ] && [ -f "$DOC" ]; then
    dcur=$( { shasum -a 256 "$DOC" 2>/dev/null || true; } | cut -d' ' -f1)
  fi
  # The guard names the two fields the append below writes, as two arguments:
  # one argument joining them with a space is a field no row ever carries, and
  # the guard read as absent at every termination, so each one appended a row
  # for a document it had already recorded.
  if [ -n "$dcur" ]; then
    gate_has_row '문서 해시' "스테이지=$seg 이후" "sha256=$dcur" \
      || gate_append '문서 해시' "스테이지=$seg 이후" "sha256=$dcur" \
           "동결값=$(manifest_field '요소' '설계 문서 전체 sha256')" "관측=$(now_iso)"
  fi

  # `실패 서명`, by the driver's one helper. The cause clue is the halt record's
  # id for a halt and the unmet residual headings for an implementation's
  # hollow success; otherwise the helper reads the stream's last error event.
  local fsig_clue='' fsig
  if [ "$klass" = "의도된 park" ]; then
    fsig_clue="$seg#$attempt"
  elif [ "$kind" = "implement" ] && [ "$klass" = "공허한 성공" ]; then
    fsig_clue=$(residual_share_missing "${DOC:-}" "$seg" "$RUN_DIR/halt" "$RUN_DIR/$seg.plan.md" 2>/dev/null || true)
  fi
  fsig=$(failure_signature "$kind" "$klass" "$out" \
           "$(stage_progress_of "$kind" "$(gate_segment_worktree "$rowseg" 2>/dev/null || true)" -)" "$fsig_clue")
  # The session's organization moves and this attempt's re-attachment record,
  # by the driver's readers; each is silent when there is nothing to say, so a
  # row with no move is the row written before these fields existed.
  local om ro re rv=""
  om=$(stage_org_moves_of "$seg" || true)
  ro=$(stage_reattach_org_of "$seg")
  re=$(stage_reattach_ctx_of "$seg")
  # `재수렴 판정`, on a re-convergence's row only — the field a sibling's re-plan
  # cites and `replan_due[]` reads, so no router reads the verdict off a stream.
  [ "$kind" != "reconverge" ] || rv=$(gate_reconverge_verdict "$out")
  # `골격급` and `재수렴 요청`, on an audit's row only. The count is the audit
  # report fence's, `미상` without a single fence. The request is `예` when an
  # audit that ended `정상 완료` counted at least one skeleton-grade item and
  # its key has had no re-convergence in this run yet — a re-audit reports what
  # remains and parks itself instead of asking again.
  local sk="" rq=""
  if [ "$kind" = "audit" ]; then
    sk=$(gate_audit_skeleton_count)
    rq=$(audit_row_request "$sk" "$klass" "$seg")
  fi
  # The re-attachment's measured fields, when the dispatch left a base record.
  # They sit before `종단 부류` and after `세션 id`, the order the router's
  # cut count reads a row in.
  gate_reattach_anchor_fields "$seg"
  # `답 운반`, when the dispatch gave this attempt an answer card: the row that
  # takes the answer up names it, and a row of an attempt that died before its
  # session is told apart by it from a stage that read the answer.
  local hacarry
  hacarry=$(gate_halt_card_line "$seg#$attempt")
  if [ -n "$psha" ]; then
    gate_append 'stage-result' "세그먼트=$rowseg" "스테이지=$seg" "종류=$kind" \
      "종료 코드=$rc" "실행 버전=$attempt" "세션 id=${sid:-미상}" \
      "부모=${CLAUDE_CODE_SESSION_ID:-미상}" \
      "압축 창=$window" "레인=$lane" ${acct:+"계정=$acct"} \
      ${om:+"조직 이동=$om"} ${ro:+"재부착 조직=$ro"} ${re:+"재기록 추정=$re"} "기록자=게이트" \
      "effort=$effort" "서빙 모델=$served" \
      ${GATE_RA_BASE:+"재부착 기준=$GATE_RA_BASE"} ${GATE_RA_DELAY:+"재부착 지연=$GATE_RA_DELAY"} \
      ${GATE_RA_WIN:+"창 종류=$GATE_RA_WIN"} ${GATE_RA_SLEEP:+"마지막 절전=$GATE_RA_SLEEP"} \
      "plan_sha256=$psha" ${rv:+"재수렴 판정=$rv"} ${sk:+"골격급=$sk"} ${rq:+"재수렴 요청=$rq"} \
      "종단 부류=$klass" ${transient:+"일시 원인=$transient"} "실패 서명=$fsig" \
      ${hacarry:+"답 운반=$hacarry"}
  else
    gate_append 'stage-result' "세그먼트=$rowseg" "스테이지=$seg" "종류=$kind" \
      "종료 코드=$rc" "실행 버전=$attempt" "세션 id=${sid:-미상}" \
      "부모=${CLAUDE_CODE_SESSION_ID:-미상}" \
      "압축 창=$window" "레인=$lane" ${acct:+"계정=$acct"} \
      ${om:+"조직 이동=$om"} ${ro:+"재부착 조직=$ro"} ${re:+"재기록 추정=$re"} "기록자=게이트" \
      "effort=$effort" "서빙 모델=$served" \
      ${GATE_RA_BASE:+"재부착 기준=$GATE_RA_BASE"} ${GATE_RA_DELAY:+"재부착 지연=$GATE_RA_DELAY"} \
      ${GATE_RA_WIN:+"창 종류=$GATE_RA_WIN"} ${GATE_RA_SLEEP:+"마지막 절전=$GATE_RA_SLEEP"} \
      ${rv:+"재수렴 판정=$rv"} ${sk:+"골격급=$sk"} ${rq:+"재수렴 요청=$rq"} \
      "종단 부류=$klass" ${transient:+"일시 원인=$transient"} "실패 서명=$fsig" \
      ${hacarry:+"답 운반=$hacarry"}
  fi
  # Every audit attempt leaves its `감사 공시` row right after its own row.
  [ "$kind" != "audit" ] || gate_record_audit_disclosure "$seg" "$attempt"
  # Every design attempt leaves its `토론 패스` row right after its own row.
  [ "$kind" != "design" ] || gate_record_discussion_passes "$seg" "$attempt"
  # A re-convergence row voids the segment's plan; the file goes too, or the
  # plan-file fallback above would put the void digest back on the next row.
  [ "$kind" != "reconverge" ] || void_segment_plan "$rowseg"

  # A TERMINAL CLASS THAT LEFT EVIDENCE OF REACHING A POINT NEEDING A PERSON is
  # announced the instant the row is seated — before the cost block, because the
  # row is the fact and the cost is bookkeeping.
  #
  # NO ONCE-MARKER, and that is deliberate rather than an omission. This function
  # is called exactly once, immediately after the child is waited on; a
  # re-dispatch is a genuinely new event and deserves a second notice.
  #
  # THE SPLIT IS A PREDICATE, NOT AN ENUMERATION — did the stage leave evidence
  # that it reached a point needing a person? A deliberate park and a stop with
  # no artifact both did: one says so in its halt record, the other left the
  # trace of arriving at a decision point it declined to settle.
  #
  # A CLASS WHOSE NEED FOR A PERSON CANNOT BE KNOWN HERE IS NOT ANNOUNCED. A
  # crash and a hollow success left nothing this side can read, so at
  # classification time there is no way to tell a stage that needs a person from
  # one that merely died and will be re-dispatched — and a notice sent on that
  # ignorance asks a sleeping person for an action the gate would refuse anyway.
  # If such a condition really does stop the run's progress, it becomes visible
  # where stalling is observable rather than guessed: a park, an anchored run, a
  # stall arm, a termination. A class added later divides itself the same way,
  # and THE DEFAULT IS SILENCE.
  #
  # THE SUBSTITUTE PATH IS NOT ALWAYS IMMEDIATE, and the cost is written down
  # rather than rounded to zero. The predicate that counts unresolved blockage
  # filters on run scope alone while the driver also parks at cone scope, so on
  # that branch the segment park row catches it, and failing that the stall arm
  # does — one silence ceiling later. The delay is the price; losing the
  # condition is not among the outcomes.
  local q
  if [ "$klass" != '정상 완료' ]; then
    case "$klass" in
      '의도된 park')
        # The body is the stage's own Korean question, verbatim from the halt
        # record. The contract binds the WRITER to record it without summarizing,
        # so the reading rule has to be stated somewhere and this is it: take the
        # rest of the `질문 문면` line. The path is already resolved above — the
        # firing point is inside the function that opened it.
        q=$( { sed -n 's/^\*\*질문 문면\*\*: *//p' "$haltf" 2>/dev/null || true; } | sed -n '1p')
        # THE FALLBACK IS NOT FOR A CRASH MID-WRITE. This class requires the
        # closing fence as the record's last non-empty line, so a record cut off
        # part-way is classified as something else and never reaches here. What
        # is reachable is a COMPLETE record whose field could not be read, and
        # the wording says exactly that. An empty extraction must not kill the
        # shell either: this sits on the critical path of an exit-on-error shell.
        #
        # THE QUESTION IS REPORTED, NOT ASKED. Now that a title carries an
        # instruction, handing the stage's raw question straight to the body puts
        # "직접 손대세요" over "계속할까요?" — the title commands, the body asks, and
        # there is nowhere on that screen to answer. The question stays verbatim
        # because it is the best wording this design has; it is wrapped in a
        # statement so the two halves make one speech act. The fallback takes the
        # same form for the same reason.
        if [ -n "$q" ]; then
          q="\`${seg}\` 스테이지가 물음 앞에서 멈췄습니다 — 「${q}」"
        else
          q="\`${seg}\` 스테이지가 스스로 멈췄습니다 — 중단 기록을 확인하세요"
        fi
        # The segment-park marker, written HERE because the attempt number is an
        # argument of this function and is NOT a field of a segment row. The file
        # is named by the segment alone so the segment-row side can find it
        # without deriving an attempt of its own; the attempt is the contents.
        mkdir -p "$RUN_DIR/notify" 2>/dev/null || true
        printf '%s\n' "$attempt" > "$RUN_DIR/notify/park-$seg" 2>/dev/null || true
        if gate_may_raise_banner; then
          cc_notify_fire hands "$q" "park-$seg#$attempt" || true
        fi ;;
      '산출물 없는 정지')
        # ITS OWN WORDING, and it must not borrow the fallback above: this class
        # is DEFINED by the absence of a halt record, so "check the halt record"
        # would send a person to a file that does not exist — the same
        # wrong-instruction failure this channel was built to remove.
        if gate_may_raise_banner; then
          cc_notify_fire hands \
            "\`$seg\` 스테이지가 결정 지점에서 멈췄습니다 — 사용자 대신 정하지 않았습니다" \
            "stop-$seg#$attempt" || true
        fi ;;
    esac
  fi

  # The cost row ACCUMULATES, because that is the shape its only reader wants:
  # the boundary compares one number against the declared ceiling rather than
  # summing the file on every act.
  if [ -n "$cost" ]; then
    # THE READ AND THE WRITE GO IN ONE CRITICAL SECTION. The previous total is
    # the value that makes this row correct, and reading it outside the lock is
    # a read-then-act: two stages terminating together both read the same total
    # and both write `prev + own`, and the second erases the first. Not a corrupt
    # row — a QUIET one. `gate_append_cost` owns both halves.
    n_stage=$(gate_rows 'stage-result' | gate_count)
    gate_append_cost "$cost" "${n_stage:-1}" "$(now_iso)"
  fi

  gate_absorb_emitted_judgment "$alias" "$seg" "$res" "$kind"

  log "스테이지 종단 — $seg ($kind) $klass rc=$rc${cost:+ · ${cost} USD}"
}

gate_absorb_issue() {
  # gate_absorb_issue <alias> <segment> <기준> <근거> <문맥> <판단 부류>
  # <판단 등급> [스테이지 종류] — issue the approval an emitted judgment needs and
  # dispose of every one of the issuer's three returns. ALWAYS returns 0. The
  # kind is the seat that raised the judgment; a caller that has none passes
  # nothing and the row says `미상`.
  #
  # THE CLASS TRAVELS WITH THE QUESTION. The issuer hands it to auto-resolution,
  # which adopts only a class it can name; calling the issuer with four arguments
  # left the class empty on every emitted judgment, so a stage that emitted
  # `시각-면제` exactly as the contract asks was adopted with its class erased
  # from the row. An empty value here means the stage emitted none. The grade
  # travels for the same reason: an adoption row written with `등급=-` leaves the
  # morning unable to tell which grade was adopted without a person.
  #
  # The absorber runs in the middle of recording a stage result, and this file
  # inherits `set -euo pipefail` from the driver it sources. So an unhandled
  # non-zero here does not "fall through": it kills the gate part way through
  # writing the result row, or — where it is returned rather than run bare — it
  # reaches the router as exit 9, which is a value the contract never defined.
  # Both were reachable from all three call sites, and all three simply dropped
  # the value and returned 0.
  #
  # A SILENT `return 0` IS NOT ONE OF THE DISPOSITIONS. The stage has already
  # acted on the decision inside its own turn; if the gate writes neither a row
  # nor an approval nor a warning, the judgment exists only in a terminal
  # message nobody will read again.
  local alias="$1" seg="$2" std="$3" why="$4" ctx="$5" cls="${6:-}" grade="${7:-}" seat="${8:-}" rc=0
  gate_issue_judgment_approval "$alias" "$seg" "$std" "$why" "$cls" "$seat" || rc=$?
  case "$(gate_judgment_approval_disposition "$rc")" in
    발행) ;;
    답있음)
      # An answer is on file for this question, and the approval id derives from
      # the segment and the `기준 — 근거` text alone — not from the class. So a
      # later emission in the same segment with the same text reaches the same
      # answer whatever class it carries, and every emission with no text at all
      # shares one id, because the missing fields are filled in as
      # `미상 — 스테이지 방출`. Naming the spent approval on the row does not by
      # itself refuse a second use; the two checks below do, before any row is
      # written, the same floor the acting path applies.
      local aid="${GATE_LAST_JUDGMENT_APPROVAL_ID:-}"
      # ONE ANSWER OPENS ONE JUDGMENT. A judgment approval carries no binding
      # tuple and never expires, so without this an answer adopted once would
      # adopt every later emission that hashed to the same id.
      if [ -n "$aid" ] && gate_has_row '자율 승인' "| 해소 승인=$aid |"; then
        warn "the answer to the question of the judgment the stage emitted (approval $aid) has already been used for one adoption — one answer opens one judgment ($ctx, class ${cls:-(none)})"
        warn "if a different judgment was emitted on the same standard, it has to be a new question with a different standard and different grounds"
        return 0
      fi
      # AN ANSWER AUTO-RESOLUTION CLOSED EARLIER DOES NOT LEND ITS ADOPTION. It
      # was adopted for the class that emission carried; an unspent one survives
      # only when the gate stopped between closing it and writing the adoption
      # row. An emission whose class may not be adopted — forbidden, absent, or
      # outside the vocabulary — is not adopted through it. An answer closed by
      # auto-resolution just now for this very emission, and an answer a person
      # gave, still open the judgment.
      if [ -n "$aid" ] && [ "${GATE_AUTO_RESOLVED_APPROVAL:-}" != "$aid" ] \
         && [ "$(gate_row_field "$(gate_approval_last_row "$aid")" '처분 사유')" = "자동 해소" ] \
         && ! gate_judgment_class_adoptable "$cls"; then
        warn "the answer to the question of the judgment the stage emitted (approval $aid) was closed by an earlier auto-resolution, so it is not adopted for the class of this emission ($ctx, class ${cls:-(none)})"
        return 0
      fi
      # Narrowed to the cap from 150 bytes down, the widest each free-text
      # field may be on this row, so a row that fits at 150 is the one written.
      # A row that fits at no width is not written: this runs while a stage
      # result is being recorded, and the contract above is to return 0.
      local aw
      if ! aw=$(gate_judgment_adoption_width 150 "kind=judgment" "결정=채택" "세그먼트=$seg" \
                  "판단 부류=$(gate_row_safe "${cls:--}" 60)" "등급=${grade:--}" \
                  "기준=$std" "되돌리는 법=-" "근거=$why" \
                  "출처=스테이지 방출" "해소 승인=${GATE_LAST_JUDGMENT_APPROVAL_ID:--}"); then
        warn "the adoption row for the judgment the stage emitted does not fit the row cap of $GATE_ROW_MAX bytes even with its free-text fields narrowed to 40 bytes — it is not adopted ($ctx, approval ${GATE_LAST_JUDGMENT_APPROVAL_ID:--})"
        return 0
      fi
      gate_judgment_adoption_row append "$aw" "kind=judgment" "결정=채택" "세그먼트=$seg" \
        "판단 부류=$(gate_row_safe "${cls:--}" 60)" "등급=${grade:--}" \
        "기준=$std" "되돌리는 법=-" "근거=$why" \
        "출처=스테이지 방출" "해소 승인=${GATE_LAST_JUDGMENT_APPROVAL_ID:--}"
      log "스테이지가 방출한 판단에 이미 답이 있어 그 답으로 엽니다 — $ctx (승인 ${GATE_LAST_JUDGMENT_APPROVAL_ID:--})"
      ;;
    닫힘)
      if [ -n "${GATE_AUTO_RESOLVED_APPROVAL:-}" ] \
         && [ "$GATE_AUTO_RESOLVED_APPROVAL" = "${GATE_LAST_JUDGMENT_APPROVAL_ID:-}" ]; then
        warn "auto-resolution did not adopt the judgment the stage emitted and closed it as rejected — class ${cls:-(none)} ($ctx, approval $GATE_AUTO_RESOLVED_APPROVAL)"
      else
        warn "the question of the judgment the stage emitted is already closed — the same question was not opened again ($ctx, approval ${GATE_LAST_JUDGMENT_APPROVAL_ID:--})"
      fi
      ;;
    *)
      warn "issuing the approval for the judgment the stage emitted ended with an unknown value ($ctx, rc=$rc) — it is not adopted and is passed over"
      ;;
  esac
  return 0
}

gate_emitted_judgment_fields() {
  # gate_emitted_judgment_fields <result-line> — read the five judgment markers
  # of a stage's terminal message into GATE_EMIT_CLS, GATE_EMIT_GRADE,
  # GATE_EMIT_STD, GATE_EMIT_REVERT and GATE_EMIT_WHY. Returns 0 when there is a
  # judgment to record, 1 when there is none: no text, no marker, or grade 0.
  #
  # ONE READER, because two paths ask about the same emission: the absorber
  # records it, and the continuation check derives the approval id the absorber
  # issued from it. Parsed twice, the two would drift and the continuation would
  # look for an approval the absorber never wrote.
  local res="$1" txt
  GATE_EMIT_CLS="" GATE_EMIT_GRADE="" GATE_EMIT_STD="" GATE_EMIT_REVERT="" GATE_EMIT_WHY=""
  txt=$(printf '%s' "$res" | jq -r '.result // empty' 2>/dev/null || true)
  [ -n "$txt" ] || return 1

  # EVERY MARKER IS READ BEFORE ANY OF THEM DECIDES. The class used to gate the
  # rest, so a return here meant "no judgment was emitted" AND "a judgment was
  # emitted without a class" — and the second is the shape a stage naturally
  # produces, because the three-grade marking convention names `기준` and
  # `되돌리는 법` and has never required a class at all. That judgment vanished:
  # no row, no approval, no warning, while the stage had already ACTED on the
  # decision inside its own turn. It is the exact opposite disposition from a
  # class that is present but out of vocabulary, which escalates.
  GATE_EMIT_CLS=$(printf '%s' "$txt" | sed -n 's/.*\*\*판단 부류\*\*: *\([^ *`]*\).*/\1/p' | sed -n '1p')
  GATE_EMIT_GRADE=$(printf '%s' "$txt"  | sed -n 's/.*\*\*판단 등급\*\*: *\([0-9]\).*/\1/p' | sed -n '1p')
  # THE VALUE ENDS AT THE NEXT MARKER, NOT AT THE END OF THE LINE. A stage's
  # terminal message is one JSON string, so the five markers ordinarily arrive on
  # a single line — and `\(.*\)` then hands each free-text field everything that
  # follows it, markers included. Measured on that ordinary spelling: the undo
  # command came back carrying the standard and the rationale glued onto it. The
  # row keeps that value, and the undo command is what a person reads in the
  # morning, so a swallowed field is worse than an absent one.
  GATE_EMIT_STD=$(printf '%s' "$txt"    | sed -n 's/.*\*\*판단 기준\*\*: *\(.*\)/\1/p' | sed -n '1p' | sed 's/ *\*\*판단 .*$//')
  GATE_EMIT_REVERT=$(printf '%s' "$txt" | sed -n 's/.*\*\*판단 되돌리는 법\*\*: *\(.*\)/\1/p' | sed -n '1p' | sed 's/ *\*\*판단 .*$//')
  GATE_EMIT_WHY=$(printf '%s' "$txt"    | sed -n 's/.*\*\*판단 근거\*\*: *\(.*\)/\1/p' | sed -n '1p' | sed 's/ *\*\*판단 .*$//')

  # No marker of ANY kind — the stage recorded no decision, which is the common
  # case and the only one that may return quietly.
  if [ -z "$GATE_EMIT_CLS" ] && [ -z "$GATE_EMIT_GRADE" ] && [ -z "$GATE_EMIT_STD" ] \
     && [ -z "$GATE_EMIT_REVERT" ] && [ -z "$GATE_EMIT_WHY" ]; then
    return 1
  fi

  # Grade 0 records nothing by contract — an already-written rule fully
  # determined the answer, so there was no decision to record.
  case "$GATE_EMIT_GRADE" in 0) return 1 ;; esac
  return 0
}

gate_absorb_emitted_judgment() {
  # gate_absorb_emitted_judgment <alias> <segment> <result-line> [스테이지 종류]
  #
  # A STAGE CANNOT REACH THE JUDGMENT PATH DIRECTLY, because it writes no
  # sidecar and holds no gate verb. Its only channel for a decision it made is
  # its own terminal message — the same channel `plan_sha256` already travels
  # on — and the gate parses it here.
  #
  # THE EMITTED LINE GOES THROUGH THE SAME UNION FLOOR. Without that, emitting
  # four lines would be enough to adopt anything at all, and the floor would be
  # bypassed by the one path that never touches it — which is the whole design
  # routed around rather than one check missed. When it does not pass, no
  # `자율 승인` row is written and an approval is issued instead.
  local alias="$1" seg="$2" res="$3" seat="${4:-}" cls grade std revert why
  gate_emitted_judgment_fields "$res" || return 0
  cls="$GATE_EMIT_CLS" grade="$GATE_EMIT_GRADE" std="$GATE_EMIT_STD"
  revert="$GATE_EMIT_REVERT" why="$GATE_EMIT_WHY"

  if [ -z "$cls" ]; then
    warn "the stage emitted a judgment with no \`판단 부류\` — no row is written and an approval is issued"
    gate_absorb_issue "$alias" "$seg" "${std:-미상}" "${why:-스테이지 방출}" "판단 부류 없음" "" "$grade" "$seat"
    return 0
  fi
  if ! judgment_class_ok "$cls"; then
    warn "the \`판단 부류\` the stage emitted is out of vocabulary: $cls — no row is written and an approval is issued"
    gate_absorb_issue "$alias" "$seg" "${std:-미상}" "${why:-스테이지 방출}" "어휘 밖 부류 $cls" "$cls" "$grade" "$seat"
    return 0
  fi
  if [ "${grade:-2}" = "2" ] || ! gate_autoadopt_ok "$cls" "$revert"; then
    warn "the judgment the stage emitted did not pass the union of \`자동 채택\` ($cls) — no row is written and an approval is issued"
    gate_absorb_issue "$alias" "$seg" "${std:-미상}" "${why:-스테이지 방출}" "자동 채택 불성립 $cls" "$cls" "$grade" "$seat"
    return 0
  fi
  # Narrowed to the cap from 150 bytes down, as the answered branch of
  # `gate_absorb_issue` is: a row that fits at 150 is the one written, and one
  # that fits at no width is not written, because this runs while a
  # stage result is being recorded and must not end the gate.
  local jw
  if ! jw=$(gate_judgment_adoption_width 150 "kind=judgment" "결정=채택" "세그먼트=$seg" \
              "판단 부류=$cls" "등급=$grade" \
              "기준=${std:-미상}" "되돌리는 법=$revert" "근거=${why:-스테이지 방출}" \
              "출처=스테이지 방출"); then
    warn "the adoption row for the judgment the stage emitted does not fit the row cap of $GATE_ROW_MAX bytes even with its free-text fields narrowed to 40 bytes — it is not adopted ($seg, class $cls)"
    return 0
  fi
  gate_judgment_adoption_row append "$jw" "kind=judgment" "결정=채택" "세그먼트=$seg" \
    "판단 부류=$cls" "등급=$grade" \
    "기준=${std:-미상}" "되돌리는 법=$revert" "근거=${why:-스테이지 방출}" \
    "출처=스테이지 방출"
  log "스테이지가 방출한 판단을 채택했습니다 — $seg 부류 $cls"
}

gate_session_lineage_record() {
  # THE ONLY WRITER, and it is called from the one place the stage/shift guard
  # stands. Enrolment used to live inside the reader below, so every path that
  # merely READ the lineage enrolled its caller as a side effect — and the
  # guard at the entry point could not see those paths at all. `gate_shift_state`
  # put one of them on the `snapshot` path: a caller whose own transcript is
  # absent falls through to the lineage search, so a stage taking a snapshot
  # enrolled itself. An enrolled id is an id allowed to ANSWER, which is exactly
  # the self-approval path the guard exists to keep shut, reached through the
  # reader instead of through the door. Reading is side-effect free from here on.
  local f="$RUN_DIR/session-lineage"
  [ -n "${CLAUDE_CODE_SESSION_ID:-}" ] || return 0
  grep -qxF "$CLAUDE_CODE_SESSION_ID" "$f" 2>/dev/null || \
    printf '%s\n' "$CLAUDE_CODE_SESSION_ID" >> "$f"
}

gate_session_lineage() {
  # Every session id this run has had. A `--resume` gives the run a NEW id and
  # leaves the earlier transcript behind, so an approval issued before the break
  # is answered in one file and looked for in another. The lineage is recorded
  # on every entry by the function above and searched as a set here.
  local f="$RUN_DIR/session-lineage"
  cat "$f" 2>/dev/null || true
}

gate_transcript_files() {
  # Files, plural, and searched by NAME rather than pinned by path+offset: the
  # `--resume` sibling-file case is exactly what a pinned path gets wrong. The
  # transcript directory is keyed by cwd and therefore shared with unrelated
  # sessions, so the search is confined to this run's own lineage.
  #
  # The directory is `gate_transcript_dir`'s, which reads a lead's own session
  # where the CLI wrote it and sends only a stage through the resolver.
  local dir sid
  dir=$(gate_transcript_dir) || return 1
  for sid in $(gate_session_lineage); do
    [ -n "$sid" ] || continue
    find "$dir" -maxdepth 2 -name "$sid.jsonl" 2>/dev/null
  done
}

gate_transcript_torn() {
  # gate_transcript_torn — 0 when any lineage transcript ends mid-line.
  #
  # A TORN LINE IS NOT AN ABSENCE, and under this design the two mean opposite
  # things. The gate reads the transcript while the harness is still appending
  # to it, so the ledger's "discard only the last line" rule does not carry
  # over — that rule assumes the gate is the writer, and here the harness is.
  # An incomplete final line that might hold the very id being looked for makes
  # "not found" ambiguous between "not answered yet" and "half written", so the
  # verdict is HELD rather than decided. Checked FIRST, before any search: a
  # search that ran over the torn file would decide on the lines before the
  # tear as if they were the whole file.
  local f
  for f in $(gate_transcript_files || true); do
    [ -f "$f" ] || continue
    if [ -n "$(tail -c 1 "$f" 2>/dev/null)" ]; then return 0; fi
  done
  return 1
}

gate_frame_candidate() {
  # gate_frame_candidate <승인 id> — the binding candidate for an approval.
  #
  # Sets GATE_FRAME_FILE, GATE_FRAME_LINE and GATE_FRAME_KIND:
  #   answers  a line carrying the id AND a `toolUseResult.answers` map — the
  #            only kind that can close an approval
  #   result   the `tool_result` of an `AskUserQuestion` that asked this id but
  #            produced no answer map (a dismissed dialog, a collapsed call)
  #   asked    the question was put (a `tool_use` carries the id) and no result
  #            frame exists yet
  #   other    a line carries the id and is none of the above — the router's
  #            own tool output echoing the ledger, typically
  #   none     nothing in the lineage carries the id
  #
  # THE BINDING IS THE ID ALONE, NOT THE ID AND THE QUESTION TEXT. Requiring the
  # question on the same line was meant to stop the router pointing `close` at a
  # different question; what it actually did was qualify every line the router
  # READ THE LEDGER on — the ledger row holds both — and reject boundary
  # approvals whose fixed-literal question is shared by dozens of ids. The
  # frame approval below is the real guard: a line closes an approval only if
  # it is the harness-written result of an `AskUserQuestion` whose question
  # carried the id, and the router cannot manufacture that frame.
  #
  # ANSWER FRAMES ARE SEARCHED ACROSS THE WHOLE LINEAGE FIRST, and the first
  # file holding one wins with its LAST such line — latest answer wins, which is
  # the rule a person changing their mind needs. The diagnostic kinds are looked
  # for only when no answer frame exists anywhere, so a dialog dismissed in an
  # earlier session cannot shadow the answer given in a later one.
  #
  # THE DIAGNOSTIC KINDS ARE ALSO DECIDED OVER THE WHOLE LINEAGE, NOT PER FILE.
  # The lineage is oldest first, and a loop that returned from the first file
  # holding the id let an earlier session hide a later one: a ledger echo there
  # came back as `other`, an interrupted earlier call as `result`, and the
  # dialog still up in the later session was never opened. The withdrawal path
  # permits both of those kinds, so the shadow walked past a live question and
  # took its banner down. The last file holding an `AskUserQuestion` for this
  # id wins, and `other` is only what remains when no file holds one — "no
  # question bearing this id was ever put", which is the one meaning it has.
  local id="$1" f line tid qfile="" qtid="" ofile="" oline=""
  GATE_FRAME_FILE=""; GATE_FRAME_LINE=""; GATE_FRAME_KIND="none"
  for f in $(gate_transcript_files || true); do
    [ -f "$f" ] || continue
    line=$( { grep -F "$id" "$f" 2>/dev/null || true; } | { grep -F '"answers":{' || true; } | tail -1)
    if [ -n "$line" ]; then
      GATE_FRAME_FILE="$f"; GATE_FRAME_LINE="$line"; GATE_FRAME_KIND="answers"; return 0
    fi
  done
  for f in $(gate_transcript_files || true); do
    [ -f "$f" ] || continue
    tid=$( { grep -F "$id" "$f" 2>/dev/null || true; } | { grep -F '"name":"AskUserQuestion"' || true; } | tail -1 \
      | jq -r --arg id "$id" '
          [ .message.content[]? | select(type == "object" and .type == "tool_use" and .name == "AskUserQuestion")
            | select([ .input.questions[]? | .question | tostring | contains($id) ] | any) | .id ] | last // ""' 2>/dev/null || true)
    if [ -n "$tid" ]; then qfile="$f"; qtid="$tid"; fi
    line=$( { grep -F "$id" "$f" 2>/dev/null || true; } | tail -1)
    if [ -n "$line" ]; then ofile="$f"; oline="$line"; fi
  done
  if [ -n "$qtid" ]; then
    line=$( { grep -F "\"tool_use_id\":\"$qtid\"" "$qfile" 2>/dev/null || true; } | tail -1)
    GATE_FRAME_FILE="$qfile"
    if [ -n "$line" ]; then GATE_FRAME_LINE="$line"; GATE_FRAME_KIND="result"; else GATE_FRAME_KIND="asked"; fi
    return 0
  fi
  if [ -n "$oline" ]; then
    GATE_FRAME_FILE="$ofile"; GATE_FRAME_LINE="$oline"; GATE_FRAME_KIND="other"; return 0
  fi
  return 1
}

gate_frame_parse() {
  # gate_frame_parse <file> <line> <승인 id> — take one transcript line apart.
  #
  # Sets GATE_FRAME_TYPE (the line's `type`), GATE_FRAME_TID (the `tool_result`
  # block's `tool_use_id`), GATE_FRAME_ERR (1 when that block says `is_error`),
  # GATE_FRAME_ERRTEXT (the first bytes of its content, for the dismissal test),
  # GATE_FRAME_TOOL (the `.name` of the `tool_use` the id joins to, in the same
  # file), GATE_FRAME_HASANS (1 when `toolUseResult.answers` is an object),
  # GATE_FRAME_KEY (the question slot carrying the id — the answers map's key),
  # GATE_FRAME_ANSWER (that slot's answer, verbatim) and GATE_FRAME_LABELS (the
  # `options[].label` the person was shown for that slot, one per line).
  #
  # THE JOIN IS THE FRAME APPROVAL. A `tool_result` names the call it answers by
  # `tool_use_id`; following that id back to its `tool_use` and reading `.name`
  # is what tells an `AskUserQuestion` answer apart from a `Bash` result that
  # happens to contain the same bytes. Nothing about the text decides it.
  #
  # THE SLOT IS FOUND BY CONTAINMENT, NOT POSITION. Measured over the corpus,
  # the id sits at the front of the question in a sixth of the slots and
  # anywhere from offset 1 to past 100 in the rest; a prefix test would reject
  # most of what already exists. The canonical prompt fixes where the gate PUTS
  # the id; this reads it wherever it is.
  local f="$1" line="$2" id="$3" tu
  GATE_FRAME_TYPE=$(printf '%s' "$line" | jq -r '.type // ""' 2>/dev/null || true)
  GATE_FRAME_TID=$(printf '%s' "$line" | jq -r '
    [ .message.content[]? | select(type == "object" and .type == "tool_result") | .tool_use_id ] | last // ""' 2>/dev/null || true)
  GATE_FRAME_ERR=$(printf '%s' "$line" | jq -r '
    [ .message.content[]? | select(type == "object" and .type == "tool_result") | (.is_error == true) ] | last // false
    | if . then "1" else "0" end' 2>/dev/null || printf '0')
  # Clipped inside jq rather than by `head -c` on the right of the pipe: an
  # early-exiting reader there kills the writer under `pipefail`.
  GATE_FRAME_ERRTEXT=$(printf '%s' "$line" | jq -r '
    [ .message.content[]? | select(type == "object" and .type == "tool_result") | (.content | tostring)[0:300] ] | last // ""' 2>/dev/null || true)
  GATE_FRAME_HASANS=$(printf '%s' "$line" | jq -r '
    if (.toolUseResult.answers? | type) == "object" then "1" else "0" end' 2>/dev/null || printf '0')
  GATE_FRAME_KEY=$(printf '%s' "$line" | jq -r --arg id "$id" '
    [ .toolUseResult.questions[]? | .question | select(type == "string" and contains($id)) ] | first // ""' 2>/dev/null || true)
  [ -n "$GATE_FRAME_KEY" ] || GATE_FRAME_KEY=$(printf '%s' "$line" | jq -r --arg id "$id" '
    [ .toolUseResult.answers? | objects | keys[] | select(contains($id)) ] | first // ""' 2>/dev/null || true)
  # THE SLOT AND ITS ENTRY ARE TWO FACTS. A question slot can carry the id while
  # the answers map has no entry under that key — measured at 2.8% of slots in
  # the corpus, a failure mode distinct from free input — so `GATE_FRAME_HASKEY`
  # says whether the map holds the key at all, and an empty answer is not
  # mistaken for an answer of nothing.
  GATE_FRAME_ANSWER=""; GATE_FRAME_HASKEY=0
  if [ -n "$GATE_FRAME_KEY" ]; then
    GATE_FRAME_HASKEY=$(printf '%s' "$line" | jq -r --arg k "$GATE_FRAME_KEY" '
      if (.toolUseResult.answers? | type) == "object" and (.toolUseResult.answers | has($k)) then "1" else "0" end' 2>/dev/null || printf '0')
    GATE_FRAME_ANSWER=$(printf '%s' "$line" | jq -r --arg k "$GATE_FRAME_KEY" '
      .toolUseResult.answers[$k]? // "" | if type == "string" then . else tojson end' 2>/dev/null || true)
  fi
  GATE_FRAME_TOOL=""; GATE_FRAME_LABELS=""
  if [ -n "$GATE_FRAME_TID" ]; then
    tu=$( { grep -F "\"id\":\"$GATE_FRAME_TID\"" "$f" 2>/dev/null || true; } | { grep -F '"type":"tool_use"' || true; } | tail -1)
    if [ -n "$tu" ]; then
      GATE_FRAME_TOOL=$(printf '%s' "$tu" | jq -r --arg tid "$GATE_FRAME_TID" '
        [ .message.content[]? | select(type == "object" and .type == "tool_use" and .id == $tid) | .name ] | last // ""' 2>/dev/null || true)
      GATE_FRAME_LABELS=$(printf '%s' "$tu" | jq -r --arg tid "$GATE_FRAME_TID" --arg id "$id" '
        [ .message.content[]? | select(type == "object" and .type == "tool_use" and .id == $tid)
          | .input.questions[]? | select(.question | tostring | contains($id)) | .options[]? | .label | tostring ] | .[]' 2>/dev/null || true)
    fi
  fi
  return 0
}

gate_menu_matches() {
  # gate_menu_matches <labels, one per line> — 0 when the normalized set of
  # labels a person was shown is exactly the gate's own label set.
  #
  # THE COMPARISON RE-DERIVES THE LABELS FROM THE CONSTANT TABLE. The row
  # stores only a version token; the authority is `gate_menu_labels`, and what
  # is compared is the transcript's `options[].label` — what the person actually
  # saw — against it. A router that rendered its own menu fails here, before any
  # answer is read, which is what makes the label set the gate's and not the
  # router's.
  local shown want l
  shown=$(printf '%s\n' "$1" | while IFS= read -r l; do [ -n "$l" ] && gate_menu_normalize "$l" && printf '\n'; done | LC_ALL=C sort -u)
  want=$(for l in $(gate_menu_labels); do printf '%s\n' "$l"; done | LC_ALL=C sort -u)
  [ "$shown" = "$want" ]
}

gate_menu_label_of() {
  # gate_menu_label_of <answer> — the gate label the answer's normal form equals,
  # or nothing when it equals none of them (free input).
  local norm l
  norm=$(gate_menu_normalize "$1")
  for l in $(gate_menu_labels); do
    [ "$norm" = "$l" ] && { printf '%s' "$l"; return 0; }
  done
  return 0
}

gate_close_settle() {
  # gate_close_settle <승인 id> — the three notification releases every
  # terminal disposition performs, in one place.
  #
  # THE SLOT GOES BACK ON EVERY TERMINAL, and the key is the approval id because
  # that is what the firing site (`cc_notify_fire answer "$q" "$id"`) wrote into
  # the stack. Deriving it differently here would leave the seat occupied by a
  # key nothing releases.
  #
  # AND THE BANNER COMES OFF THE SCREEN. An approval that was voided, refused or
  # granted is equally done being waited on, so leaving its notice up is the
  # state the address was added to end: in the morning the answered and the
  # unanswered look the same. The two calls are deliberately NOT one —
  # reclaiming a slot erases a line in a file and delivers nothing, while
  # clearing changes what is on a person's screen right now, so only the second
  # carries a seat guard, and that guard lives inside the verb.
  cc_notify_stack_release "$1" || true
  cc_notify_clear answer "$1" || true
  gate_notify_overflow_settled || true
  # A CLOSED BOUNDARY APPROVAL RESTARTS ITS BOUNDARY'S COUNT, whatever the
  # disposition. Boundary ids are `<경계 이름>-<8 hex>`, and `SHIFT-FLOOR` has
  # no count to restart.
  case "$1" in
    B[1-4]-*) gate_boundary_rebaseline "${1%-*}" ;;
  esac
}

gate_close_lost() {
  # gate_close_lost <승인 id> — the `close` row was refused by the transition
  # guard: the approval was still `대기` or `철회` when this verb read it, and
  # is not by the time the lock is held.
  #
  # The state check at the top of `close` runs long before the row is written —
  # the transcript is read and parsed in between — and an auto-close landing in
  # that window used to be overwritten by this row, or to overwrite it. A
  # person's answer is not quietly lost to either order: the close fails and
  # says why. Every closing append in `close` carries `--transition` and lands
  # here on refusal; the appends stay literal `gate_append '승인'` calls so the
  # field table lint keeps reading them.
  die "approval '$1' was resolved by another close while this close was reading the answer (now '$(gate_approval_state "$1")') — this answer was not recorded"
}

gate_close() {
  # Resolving an approval reads the HARNESS-WRITTEN transcript rather than the
  # router's prose, so the entity that asks is not the entity that records. The
  # separation is the whole value: a router that could type its own answer would
  # be issuing approvals to itself, and the record would be indistinguishable
  # from one a person gave.
  #
  # That channel is meaningful only while the hook denies Write and Edit to the
  # transcript directory — which is the run settings' job, not this script's.
  # This verb's contract is the narrow one it can actually keep: it never
  # accepts an answer that did not come out of that file.
  #
  # Three outcomes, and every one of them needs the same transcript line.
  # `--void` records `무효` — the question should not have been asked — and
  # `--reject` records `거부` — it was asked, and the answer is no. Before them
  # there was exactly one recording path, so a pending approval had two possible
  # ends: granted, or pending forever. Pending is not inert; it counts against
  # termination condition 2 and suspends the stagnation boundaries, so one
  # approval nobody wants to grant stalls the rest of the run.
  #
  # Voiding is NOT the conservative direction — it REMOVES a blocker — so it
  # keeps the transcript binding rather than becoming a router-writable escape.
  # What it buys a person is the ability to answer "this should not have been
  # asked" without also granting the act.
  #
  # `거부` IS THE OUTCOME A PERSON'S OWN WORDS CAN REACH, and until it existed
  # they could not reach one. `무효` and `승인` are both dispositions the router
  # selects; the recording path held the single literal `상태=승인` and read
  # nothing about the answer's polarity, so an answer of "no" written into the
  # transcript was recorded as a grant. Every refusal on the unattended
  # adoption surface converges on this channel, so a channel that emits a
  # constant leaves the floors above it deciding nothing.
  #
  # THE LADDER, TOP DOWN. Rung 1 holds on a torn transcript. Rung 2 is FRAME
  # APPROVAL — the line is the harness-written result of an `AskUserQuestion`
  # whose question carried the id, joined by `tool_use_id`, and holds an
  # `answers` map — and inside it 2a refuses a menu that is not the gate's, 2b
  # closes on a label that equals one of the gate's by whole-string comparison,
  # and 2c holds on an answer that equals none (free input) or on a slot the
  # frame does not carry. Rung 3 names an ineligible frame (an `is_error`
  # result, another tool's result, a parse failure) and holds. Rung 4 is the
  # diagnostic: a line carries the id and is none of the above — the router's
  # own ledger read, typically — and NOTHING IS WRITTEN. Judgment approvals run
  # every rung; act and boundary approvals have no menu and no label set, so
  # they run 1, the frame approval of 2, 3 and 4 and never 2a/2b/2c.
  #
  # NO RAW-LINE FALLBACK AND NO PROSE SCAN. The fallback's whole observed record
  # was zero true positives and four false ones — a transport frame recorded as
  # the answer — and the polarity vocabulary was the ledger's own words (`승인`
  # is a series name), so it either missed real answers or read the ledger as
  # consent. An unknown shape is named and held; an unknown shape that is
  # guessed at produces an authorization nobody gave.
  local id="$1" void="${2:-0}" reject="${3:-0}" row state q cutp anchor afull adig aex label tok
  # `|| true` on every match: a `grep` that finds nothing exits 1, `pipefail`
  # promotes it, and `set -e` then kills the verb with status 1 and NO message —
  # which reads exactly like a refusal and is not one.
  row=$(gate_approval_last_row "$id")
  [ -n "$row" ] || die "no such approval id in the ledger: $id"
  state=$(gate_row_field "$row" '상태')
  # `철회` IS THE ONE NON-`대기` STATE A LATER ANSWER MAY STILL CLOSE. A withdrawn
  # approval is one whose raising condition went away — no clock, no answer —
  # and a person answering it afterwards is answering a real question; refusing
  # that answer would make the withdrawal decide for them.
  case "$state" in
    대기|철회) ;;
    *) die "approval '$id' is already '$state' — a resolved approval is not closed again" ;;
  esac
  q=$(gate_row_field "$row" '질문 문면')
  cutp=$(gate_row_field "$row" '절단점')
  anchor=$(gate_approval_sidecar_anchor "$id")

  if [ -z "$(gate_transcript_files || true)" ]; then
    warn "the transcript could not be found, so the approval cannot be closed — an answer typed by the router is not accepted"
    exit "$GATE_EXIT_APPROVAL"
  fi

  # ---- rung 1
  if gate_transcript_torn; then
    warn "the last line of the transcript is not complete — the judgment is held and looked at again on the next one"
    exit "$GATE_EXIT_APPROVAL"
  fi

  gate_frame_candidate "$id" || true
  case "$GATE_FRAME_KIND" in
    none)
      warn "there is no response frame for this approval in the transcript — the wait is kept"
      exit "$GATE_EXIT_APPROVAL" ;;
    asked)
      warn "the question of approval $id was asked, but there is no response frame yet — the wait is kept"
      exit "$GATE_EXIT_APPROVAL" ;;
    other)
      # ---- rung 4: a candidate, and not a frame of any kind this ladder knows.
      gate_frame_parse "$GATE_FRAME_FILE" "$GATE_FRAME_LINE" "$id"
      warn "there is a line carrying approval $id, but it is not an answer frame (observed frame: type=${GATE_FRAME_TYPE:-unknown} tool=${GATE_FRAME_TOOL:-(none)}) — nothing is written to the ledger and it is left waiting"
      exit "$GATE_EXIT_APPROVAL" ;;
  esac

  # ---- rung 2 / rung 3: frame approval
  gate_frame_parse "$GATE_FRAME_FILE" "$GATE_FRAME_LINE" "$id"
  if [ "$GATE_FRAME_ERR" = "1" ]; then
    # Two warnings for two opposite facts. The harness's dismissal text means a
    # person was at the screen and closed the dialog without choosing; any
    # other `is_error` says only that the call collapsed, cause unobserved.
    case "$GATE_FRAME_ERRTEXT" in
      *"$GATE_DISMISSAL_TEXT"*)
        warn "the question dialog of approval $id was cancelled (dialog cancelled — a person closed it with no answer) — it is left waiting" ;;
      *)
        warn "the question call of approval $id failed (is_error, cause not observed) — it is left waiting" ;;
    esac
    exit "$GATE_EXIT_APPROVAL"
  fi
  if [ "$GATE_FRAME_KIND" = "result" ]; then
    warn "the response frame of approval $id has no answers map (frame ineligible) — it is left waiting"
    exit "$GATE_EXIT_APPROVAL"
  fi
  if [ -z "$GATE_FRAME_TID" ] || [ "$GATE_FRAME_TYPE" != "user" ]; then
    warn "could not read the binding candidate of approval $id as a tool_result frame (parse failure, type=${GATE_FRAME_TYPE:-unknown}) — it is left waiting"
    exit "$GATE_EXIT_APPROVAL"
  fi
  if [ "$GATE_FRAME_TOOL" != "AskUserQuestion" ]; then
    warn "the binding candidate of approval $id is the result of a tool other than AskUserQuestion (tool=${GATE_FRAME_TOOL:-unknown}) — frame ineligible, it is left waiting"
    exit "$GATE_EXIT_APPROVAL"
  fi
  if [ "$GATE_FRAME_HASANS" != "1" ]; then
    warn "the binding candidate of approval $id has no toolUseResult.answers object (parse failure) — it is left waiting"
    exit "$GATE_EXIT_APPROVAL"
  fi
  tok="$GATE_FRAME_TID"

  if [ "$cutp" != "판단" ]; then
    # ---- act and boundary approvals: the frame decides, the closer's flag is
    # the disposition. There is no menu to compare and no label set to read, so
    # `--void` and `--reject` remain the closer's word; what changed is that the
    # frame must be a real answer to THIS id, and the answer's bytes are kept.
    if [ -z "$GATE_FRAME_KEY" ] || [ "$GATE_FRAME_HASKEY" != "1" ]; then
      warn "the answer frame of approval $id has no entry for the question slot carrying that id — nothing is written to the ledger and it is left waiting"
      exit "$GATE_EXIT_APPROVAL"
    fi
    afull="$GATE_FRAME_ANSWER"
    adig=$(printf '%s' "$afull" | shasum -a 256 | cut -d' ' -f1)
    gate_approval_sidecar_write "$id" answer '답변' "$afull" \
      || warn "could not write the full answer text into the approval sidecar — the row is closed, but the answer section of anchor $anchor is empty"
    if [ "$void" = "1" ]; then
      gate_append '승인' --transition "$id" '대기 철회' 0 "승인 id=$id" "상태=무효" "질문 문면=$q" \
        "답변 문면=트랜스크립트 판독(무효)" "해소 시각=$(now_iso)" \
        "응답 토큰=$tok" "답변 다이제스트=$adig" "사이드카 앵커=$anchor" || gate_close_lost "$id"
      gate_close_settle "$id"
      log "승인 무효 — $id (행위는 수행되지 않습니다)"
      return 0
    fi
    if [ "$reject" = "1" ]; then
      gate_append '승인' --transition "$id" '대기 철회' 0 "승인 id=$id" "상태=거부" "질문 문면=$q" \
        "답변 문면=트랜스크립트 판독" "해소 시각=$(now_iso)" \
        "응답 토큰=$tok" "답변 다이제스트=$adig" "사이드카 앵커=$anchor" || gate_close_lost "$id"
      gate_close_settle "$id"
      log "승인 거부 — $id (물었고 답이 아니오입니다)"
      return 0
    fi
    gate_append '승인' --transition "$id" '대기 철회' 0 "승인 id=$id" "상태=승인" "질문 문면=$q" \
      "답변 문면=트랜스크립트 판독" "해소 시각=$(now_iso)" \
      "응답 토큰=$tok" "답변 다이제스트=$adig" "사이드카 앵커=$anchor" || gate_close_lost "$id"
    gate_close_settle "$id"
    log "승인 해소 — $id"
    return 0
  fi

  # ---- judgment approvals: 2a, 2b, 2c
  if [ -n "$GATE_FRAME_KEY" ] && [ "$GATE_FRAME_HASKEY" = "1" ]; then
    # 2a — the menu the person saw must be the gate's. Compared BEFORE the
    # answer is read: a menu that is not the gate's makes every label on it a
    # label the gate did not define, and an answer chosen from it is not a
    # choice among the gate's dispositions whatever it happens to spell.
    if ! gate_menu_matches "$GATE_FRAME_LABELS"; then
      warn "the menu of approval $id differs from the option set of the gate (seen: $(printf '%s' "$GATE_FRAME_LABELS" | tr '\n' '/') · gate: $(gate_menu_labels | tr ' ' '/')) — the router has to render the labels the prompt verb produced verbatim. It is left waiting"
      exit "$GATE_EXIT_RULE"
    fi
    afull="$GATE_FRAME_ANSWER"
    label=$(gate_menu_label_of "$afull")
  else
    afull=""; label=""
  fi

  if [ -n "$label" ]; then
    # 2b — whole-string equality against the gate's labels, on the normal form
    # (recommendation suffix removed). THE FLAGS MAY ONLY AGREE WITH THE ANSWER:
    # a closer naming `--void` over an answer of `승인` is proposing a
    # disposition against the person's words, and the person's words win.
    if [ "$void" = "1" ] && [ "$label" != "무효" ]; then
      warn "close --void contradicts the answer — the person chose '$(gate_menu_normalize "$afull")'. A flag can only agree with the answer"
      exit "$GATE_EXIT_RULE"
    fi
    if [ "$reject" = "1" ] && [ "$label" != "거부" ]; then
      warn "close --reject contradicts the answer — the person chose '$(gate_menu_normalize "$afull")'. A flag can only agree with the answer"
      exit "$GATE_EXIT_RULE"
    fi
    # A `시각-승인` IS GRANTED BY THE SIDECAR, AND THE LABEL ONLY REPORTS IT. The
    # person approves the screens at the fixed seat, which writes the sidecar's
    # implementation approval; a `승인` label chosen while that predicate does
    # not hold names an approval that does not exist, so it is refused before
    # anything is written and the question stays `대기`. `거부` and `무효` need
    # no predicate: declining to build the screens is the person's to say.
    if [ "$label" = "승인" ] && [ "$(gate_approval_field "$id" '판단 부류')" = "시각-승인" ]; then
      local vwhy
      if ! vwhy=$(gate_visual_approval_holds); then
        warn "approval $id is a '시각-승인' question and the sidecar's implementation approval does not hold ($vwhy) — '승인' is not recorded. Approve the screens at the fixed seat with /cc-cmds:visual first, then answer '승인' again"
        exit "$GATE_EXIT_RULE"
      fi
    fi
    adig=$(printf '%s' "$afull" | shasum -a 256 | cut -d' ' -f1)
    aex=$(gate_row_safe "$afull" "$GATE_A_EXCERPT")
    gate_approval_sidecar_write "$id" answer '답변' "$afull" \
      || warn "could not write the full answer text into the approval sidecar — the row is closed, but the answer section of anchor $anchor is empty"
    # THE ANSWER STORE, BESIDE THE APPROVAL SIDECAR AND NOT INSTEAD OF IT. The
    # sidecar under `docs/` is the tracked record a PERSON reads in the morning;
    # this copy is what the STAGE that asked reads when it comes back. Two
    # readers, two lifetimes — so neither replaces the other, and this one lives
    # in the volatile run directory precisely because a stage picking up its own
    # answer must not make a tracked-tree write.
    #
    # WRITTEN FOR EVERY LABEL, before the disposition is branched on. A refusal's
    # own words are a durable record of why the answer was no, and that record
    # has value; what must not happen is handing those words to a stage as an
    # instruction. `gate_answer_servable` is what refuses that, and the test
    # belongs to the READER rather than here — a writer that decided which
    # answers are worth keeping would be deciding it once, at the only moment
    # the text exists.
    #
    # `절단점=판단` ONLY, which is where this line sits: an act approval's answer
    # is a disposition with nothing for a stage to resume from, and serving one
    # would make the listing show entries that are not answers.
    mkdir -p "$RUN_DIR/answer"
    printf '%s\n' "$afull" > "$RUN_DIR/answer/$id.md"
    gate_append '승인' --transition "$id" '대기 철회' 0 "승인 id=$id" "상태=$label" "질문 문면=$q" \
      "답변 문면=$aex" "해소 시각=$(now_iso)" \
      "응답 토큰=$tok" "답변 다이제스트=$adig" "사이드카 앵커=$anchor" || gate_close_lost "$id"
    gate_close_settle "$id"
    case "$label" in
      승인) log "승인 해소 — $id" ;;
      거부) log "승인 거부 — $id (물었고 답이 아니오입니다)" ;;
      무효) log "승인 무효 — $id (행위는 수행되지 않습니다)" ;;
    esac
    return 0
  fi

  # 2c — a real answer frame whose answer equals no label (free input), or a
  # frame that does not carry this approval's slot at all. `대기` STAYS, THE
  # ANSWER GOES TO THE SIDECAR ONLY, AND THE ROW GETS A REASON. The ledger row
  # must not carry the answer: `gate_approval_field` returns the last value a
  # key ever had, so an answer on a `대기` row would read to every later reader
  # as an answer with no mark of what it was. The person's words are not
  # discarded either — they are in the sidecar block the anchor names — and the
  # reason field is what the morning report reads to surface the approval as
  # "answered, disposition not derived" rather than "nobody answered". Exit 5
  # and not 0: 0 means resolved, and this approval is not.
  local reason
  if [ -n "$GATE_FRAME_KEY" ] && [ "$GATE_FRAME_HASKEY" = "1" ]; then reason='자유 입력'; else reason='슬롯 부재'; fi
  if [ "$(gate_row_field "$row" '처분 사유')" = "$reason" ] && [ "$(gate_row_field "$row" '응답 토큰')" = "$tok" ]; then
    warn "approval $id is already recorded as '$reason' for this answer frame — it is left waiting (it is looked at again when a new answer arrives)"
    exit "$GATE_EXIT_APPROVAL"
  fi
  if [ "$reason" = "자유 입력" ]; then
    if ! gate_approval_sidecar_write "$id" answer '답변' "$afull"; then
      warn "could not write the free-text answer of approval $id into the sidecar — to keep from discarding the answer, nothing is written to the ledger either and it is looked at again on the next judgment"
      exit "$GATE_EXIT_APPROVAL"
    fi
    # A `사람-결정` QUESTION HAS NO DISPOSITION TO DERIVE: what the person wrote
    # IS the decision, and holding it at `대기` would leave the segment held on
    # a question already answered. So free text closes it `승인`, the reason
    # field says the answer was free text, and the words go to the answer store
    # where the router reads them (`gate.sh answers`) — never onto the row.
    # The literal and not the person set: a `시각-승인` question is closed only
    # by its sidecar predicate, so free text for it stays an unread `대기`.
    if [ "$(gate_approval_field "$id" '판단 부류')" = "사람-결정" ]; then
      adig=$(printf '%s' "$afull" | shasum -a 256 | cut -d' ' -f1)
      mkdir -p "$RUN_DIR/answer"
      printf '%s\n' "$afull" > "$RUN_DIR/answer/$id.md"
      gate_append '승인' --transition "$id" '대기 철회' 0 "승인 id=$id" "상태=승인" "질문 문면=$q" \
        "답변 문면=자유 입력(답변 저장소)" "해소 시각=$(now_iso)" "처분 사유=$reason" \
        "응답 토큰=$tok" "답변 다이제스트=$adig" "사이드카 앵커=$anchor" || gate_close_lost "$id"
      gate_close_settle "$id"
      log "승인 해소 — $id (자유 입력, $RUN_DIR/answer/$id.md)"
      return 0
    fi
    warn "the answer of approval $id matches none of the labels offered (free text, $(printf '%s' "$afull" | wc -c | tr -d ' ') bytes — recorded in sidecar $anchor) — no disposition was derived and it is left waiting"
  else
    warn "the answer frame of approval $id has no question slot carrying that id (slot absent) — no disposition was derived and it is left waiting"
  fi
  gate_append '승인' --transition "$id" '대기 철회' 0 "승인 id=$id" "상태=대기" "대상=$(gate_row_field "$row" '대상')" "절단점=$cutp" \
    "막는 세그먼트=$(gate_row_field "$row" '막는 세그먼트')" "질문 문면=$q" \
    "판단 부류=$(c=$(gate_approval_field "$id" '판단 부류'); printf '%s' "${c:--}")" \
    "처분 사유=$reason" "응답 토큰=$tok" "사이드카 앵커=$anchor" "관측 시각=$(now_iso)" || gate_close_lost "$id"
  exit "$GATE_EXIT_APPROVAL"
}

# ---------------------------------------------------------------------------
# Termination — eleven conditions on the gate side, and a router-side proposal
# that must carry evidence rather than prose.
#
# The disagreement runs BOTH ways and the draft had only one direction. A gate
# that can refuse a proposal but never cause one leaves the router alone
# deciding when the night ends, which is not a conjunction at all. So a router
# that declines to propose while every condition holds must name a specific,
# admissible next obligation — and failing to name one ends the run.
# ---------------------------------------------------------------------------
# `TERMINAL_SEGMENT_STATES` — the enumeration and the reasoning behind its third
# element live in `liveness.sh`, sourced above. It is not re-declared here: the
# status line reads the same set through the same file, and a copy is how the
# render and this check came to disagree about the same segment.

gate_done_disposition() {
  # gate_done_disposition <미충족 텍스트> — one of `충족`, `무효화`, `미충족`.
  #
  # Takes the ALREADY COMPUTED text rather than calling `gate_done_conditions`
  # again: three callers each want this verdict about the same evaluation, and a
  # second evaluation could disagree with the first because the ledger moved
  # between them.
  #
  # NEVER THE EMPTY STRING, on any path. The value is compared by equality at
  # every call site and one of those comparisons decides whether the run's `done`
  # file is written — an empty answer there reads as "not this branch" at each
  # arm in turn and falls out of the chain having decided nothing.
  #
  # The recognized values are used with POSITIVE equality by every caller that
  # ACCEPTS on them, so an unrecognized value and the empty string both land in
  # the refusing arm. That is what makes a token here as fail-closed as a
  # predicate would be, which was the one property the predicate form had over
  # this one.
  local unmet="$1" other
  [ -n "$unmet" ] || { printf '충족'; return 0; }
  # Condition 5's invalidation line is the one unmet cause that is permanent by
  # construction. A run left with only that is over — it may record its end, but
  # as invalidated rather than as satisfied.
  #
  # THE MATCH IS ANCHORED TO THE FIXED HEAD OF THAT LINE, not to the phrase
  # wherever it appears. Every condition interpolates free text — a segment's
  # status, an obligation's text, a blocked row's reason — and all of it lands
  # AFTER the line's fixed prose, never at the start. An unanchored substring
  # filter therefore let one router-typed value carrying the phrase delete a
  # genuine unmet cause from this verdict, and a run with conditions actually
  # outstanding recorded itself as invalidated and stopped. Anchoring makes the
  # only line this can drop the one the gate itself writes.
  #
  # Condition 1's design-step line is dropped on the same footing, and the
  # anchoring applies to both heads. It is the zero-segment line of a run whose
  # design step will not be dispatched again: no segment can come into being, so
  # the path forward is closed by construction just as condition 5's is, and
  # what the run may record is its invalidation, never its satisfaction. The
  # plain zero-segment line — a run that has not begun — is not dropped.
  #
  # Condition 10's `불가능 정산` line is dropped on the same footing. A clause
  # the run settled as unreachable is one it will never reach, so a run left
  # with only those lines may record its end as invalidated, never as satisfied.
  # The pattern is anchored at both ends: a clause id is a manifest token without
  # spaces, and the line carries nothing after the fixed tail.
  #
  # A base run's closed-split line is dropped on the same footing: its audit or
  # split will not be dispatched again, so the split can never complete. Its
  # unfinished-split line is not dropped.
  #
  # So is the closed-audit line of a single run whose plan opens on the audit:
  # with no design step, an audit that will not be dispatched again leaves the
  # run no road to a segment. Its unfinished-audit lines are not dropped.
  other=$(printf '%s' "$unmet" \
    | grep -v -e '^5 런 스코프 blocked 가 해소 불가입니다 ' \
              -e '^1 세그먼트가 하나도 없고 설계 단계가 더는 파견되지 않습니다 ' \
              -e '^1 세그먼트가 하나도 없고 감사 단계가 더는 파견되지 않습니다 ' \
              -e '^1 베이스 분할이 더는 파견되지 않습니다 ' \
              -e '^10 종료 절 [^ ]* 불가능 정산$' || true)
  [ -n "$other" ] || { printf '무효화'; return 0; }
  printf '미충족'
}

gate_unmet_summary() {
  # gate_unmet_summary <미충족 텍스트> — the count and the condition numbers,
  # bounded by construction.
  #
  # The row this feeds has a 1024-byte cap and the full list grows with the run
  # — one line per non-terminal segment, one per unsettled clause — so joining
  # the text made a run with enough of them unable to record its own rejection.
  # The numbers cannot exceed eleven distinct values, so this field cannot.
  local unmet="$1" n ids
  n=$(printf '%s\n' "$unmet" | grep -c . || true)
  ids=$(printf '%s\n' "$unmet" | sed -n 's/^\([0-9]\{1,2\}\) .*/\1/p' \
        | sort -un | tr '\n' ',' | sed 's/,$//')
  printf '미충족 %s건 · 조건 %s' "${n:-0}" "${ids:-미상}"
}

gate_unmet_numbers() {
  # gate_unmet_summary's numbers alone, deduplicated and ascending, one per line.
  # Carried separately from the capped text list because it is the half that
  # cannot be truncated: it answers "why can this run not end" in eleven values at
  # most, while the text grows without bound and loses its tail exactly when the
  # night has been long enough for the tail to matter.
  printf '%s\n' "$1" | sed -n 's/^\([0-9]\{1,2\}\) .*/\1/p' | sort -un
}

gate_step_deferred_line() {
  # gate_step_deferred_line <key> — print condition 1's `답 이월 대기` line and
  # return 0 when the key's last `stage-result` is `의도된 park` and its answer
  # is carried over to the next run (`gate_key_deferred_answer`); return 1
  # otherwise. Such a key is neither closed nor void: the next run dispatches it
  # again with the person's answer. The head `1 답 이월 대기 — ` is fixed;
  # `gate_defer_only_left` reads the return value, not the line.
  #
  # The last row is read past pre-session deaths
  # (`gate_stage_last_settled_row`), the test the consumer, the routing and the
  # run-scope admission use: such an attempt never read the card, so the key
  # still stands where the park left it.
  #
  # AN ANSWER BROUGHT IN AND CARRIED OVER AGAIN HALTED IN THE EARLIER RUN. This
  # run refused the key's dispatch when it brought the answer in, so it holds
  # no attempt of the key; the last row is then the earlier run's, read the
  # way the routing reads it (`gate_carry_source_last_row`).
  local ln last
  ln=$(gate_key_deferred_answer "$1")
  [ -n "$ln" ] || return 1
  last=$(gate_stage_last_settled_row "$1")
  [ -n "$last" ] || last=$(gate_carry_source_last_row "$ln")
  [ "$(gate_row_field "$last" '종단 부류')" = '의도된 park' ] || return 1
  printf '1 답 이월 대기 — %s 의 중단 답(원장 %s 번째 줄)을 다음 런이 이어받습니다\n' "$1" "$ln"
}

gate_base_step_closed() {
  # gate_base_step_closed <step id> <row kind> — prints why a base run's audit or
  # split step will not be dispatched again and returns 0, or returns 1. The
  # audit arm of a single run with no design step reads its audit by this too.
  #
  # The depth is the design step's, by the same counter: `공허한 성공` or a crash
  # buys one fresh attempt and two close the step; `외부 종료` and a usage-limit
  # crash keep it open whatever the count, because neither says the stage
  # cannot finish. Any other class but `정상 완료` is a stage that stopped on
  # purpose — a park, a halt with nothing to show — and is not dispatched again.
  local id="$1" k="$2" rows last lastrow fresh
  rows=$(gate_run_scope_rows "$id" "$k")
  [ -n "$rows" ] || return 1
  lastrow=$(printf '%s\n' "$rows" | tail -1)
  last=$(gate_row_field "$lastrow" '종단 부류')
  case "$last" in
    '정상 완료' | '외부 종료') return 1 ;;
  esac
  # A park whose answer the next run takes up is not closed: that run
  # dispatches the step again with the answer (`gate_step_deferred_line`).
  gate_step_deferred_line "$id" >/dev/null && return 1
  if [ "$last" = '공허한 성공' ] || [ "$(terminal_route_class "$last")" = '크래시' ]; then
    if [ "$last" != '공허한 성공' ] \
       && gate_design_row_has_limit_envelope "$(gate_row_field "$lastrow" '스테이지')" "$lastrow"; then
      return 1
    fi
    fresh=$(printf '%s\n' "$rows" | gate_design_fresh_attempts)
    [ "${fresh:-0}" -ge 2 ] || return 1
    printf '새 시도 깊이 소진(%s회)' "$fresh"
    return 0
  fi
  printf '종단 부류 %s' "${last:-미상}"
}

gate_audit_first_unmet() {
  # gate_audit_first_unmet <audit step id> — condition 1's arm for a single run
  # whose plan has no design step and opens on the audit (see the caller).
  # Prints at most one line.
  #
  # An audit that ended `정상 완료` is the run's work done when the plan has no
  # step after it, so the condition holds and condition 10 is left to measure
  # the clauses the person authorized. When an implement step follows, the
  # line names it, and its head is not one `gate_done_disposition` drops: the
  # run is unfinished, not void. An audit that will not be dispatched again —
  # by `gate_base_step_closed`, the same depth the base arm reads — prints the
  # line with its own fixed head that the disposition drops, so the run may
  # record its end as invalidated. A re-convergence on the audit's key that
  # came after its last audit row is waiting on a fresh audit, so that state
  # is not read as closed.
  local astep="$1" arows alast lastrow istep why
  if gate_step_deferred_line "$astep"; then
    return 0
  fi
  arows=$(gate_audit_result_rows_of "$astep")
  if [ -z "$arows" ]; then
    printf '1 세그먼트가 하나도 없습니다 — 감사 단계(%s)가 아직 끝나지 않았습니다\n' "$astep"
    return 0
  fi
  lastrow=$( { gate_stage_result_rows_of "$astep" || true; } \
             | { grep -F -- '- `stage-result`' || true; } | tail -1)
  case "$lastrow" in
    *'| 종류=reconverge '*)
      printf '1 세그먼트가 하나도 없습니다 — 감사 단계(%s)가 재수렴 뒤 새 감사를 기다립니다\n' "$astep"
      return 0 ;;
  esac
  alast=$(gate_row_field "$(printf '%s\n' "$arows" | tail -1)" '종단 부류')
  if [ "$alast" = '정상 완료' ] && ! gate_audit_concluded "$astep" && [ "$GATE_AUDIT_WAIT" = '골격급' ]; then
    printf '1 세그먼트가 하나도 없습니다 — 감사 단계(%s)가 골격급 재수렴을 기다립니다\n' "$astep"
    return 0
  fi
  if [ "$alast" = '정상 완료' ]; then
    istep=$(manifest_plan_json 2>/dev/null \
              | jq -r '[.steps[]? | select(type == "object" and .skill == "implement") | .id // empty | select(. != "")][0] // empty' 2>/dev/null \
              || true)
    [ -z "$istep" ] || printf '1 감사가 끝났으나 다음 단계(%s)가 아직 파견되지 않았습니다\n' "$istep"
    return 0
  fi
  if why=$(gate_base_step_closed "$astep" audit); then
    printf '1 세그먼트가 하나도 없고 감사 단계가 더는 파견되지 않습니다 — %s · %s · 남은 종료 절을 정산하면 런은 무효로 끝납니다\n' "$astep" "$why"
  else
    printf '1 세그먼트가 하나도 없습니다 — 감사 단계(%s)가 아직 끝나지 않았습니다 (종단 부류 %s)\n' "$astep" "${alast:-미상}"
  fi
}

gate_base_split_unmet() {
  # Condition 1's base arm (see the caller). Prints at most one line.
  local sstep astep srow skey why
  if ! sstep=$(gate_run_scope_step split) || ! astep=$(gate_run_scope_step audit); then
    printf '1 베이스 분할이 끝나지 않았습니다 — - · 계획에 감사·분할 단계가 하나씩 있지 않습니다\n'
    return 0
  fi
  srow=$(gate_run_scope_last_row "$sstep" split)
  if [ -n "$srow" ]; then
    skey=$(gate_row_field "$srow" '스테이지')
    if [ "$(gate_row_field "$srow" '종단 부류')" = '정상 완료' ] && predicate_split "$skey"; then
      return 0
    fi
  fi
  if why=$(gate_base_step_closed "$sstep" split); then
    printf '1 베이스 분할이 더는 파견되지 않습니다 — %s · %s · 남은 종료 절을 정산하면 런은 무효로 끝납니다\n' "$sstep" "$why"
  elif [ -z "$srow" ] && why=$(gate_base_step_closed "$astep" audit); then
    printf '1 베이스 분할이 더는 파견되지 않습니다 — %s · %s · 남은 종료 절을 정산하면 런은 무효로 끝납니다\n' "$astep" "$why"
  elif [ -n "$srow" ]; then
    printf '1 베이스 분할이 끝나지 않았습니다 — %s · 종단 부류 %s, 분할 술어 불성립\n' "$sstep" "$(gate_row_field "$srow" '종단 부류')"
  else
    printf '1 베이스 분할이 끝나지 않았습니다 — %s · 분할 단계 행 없음\n' "$sstep"
  fi
}

gate_done_conditions() {
  # Prints one line per UNMET condition, numbered. Empty output means all
  # ELEVEN hold. Never silently empty on an unreadable ledger — that is
  # condition 4.
  #
  # Condition 10 splits into two arms and both print `10`, so the numbering runs
  # 1..11 while the count of printable causes is larger.
  local sid st n

  # 1 — every segment in a terminal state.
  #
  # And at least one segment must exist. Over the empty set "every segment is
  # terminal" is vacuously TRUE, so a run that has not started yet satisfied
  # every condition — which made the very first act of every run trip the rule below that
  # demands a next obligation when everything is already done. A run with no
  # segments has not finished; it has not begun.
  #
  # EXCEPT IN A DESIGN-FIRST GRAPH, where that sentence is only half true. Its
  # segments come from the frozen document's slicing, and the design step is not
  # a segment, so a run whose design never froze has no segments and never will.
  # Such a run is not "not begun": its design step will not be dispatched again,
  # because its last `stage-result` row is of any class but `외부 종료` and it
  # is not a crash that saved nothing, or a SAVED document already sits at the
  # path (a saved document is not dispatched over, while the stage's own
  # spawn-time stub is), or the manifest names no document (the dispatch
  # refuses that value).
  # A fourth reason joins them: the step's fresh-attempt depth is spent (below).
  # Any of the four prints a different line with its own fixed head, and
  # `gate_done_disposition` drops that head the way it drops condition 5's — the
  # run may then record its end, as invalidated and never as satisfied.
  #
  # `외부 종료` IS LEFT OUT because the routers dispatch that step again onto an
  # absent document. The prelude's settlement writes the class about a dispatch
  # whose process and supervisor both vanished, without looking at the document,
  # so a stage ended before its team placed a file at the path lands here having
  # written nothing. Reading that row as "not dispatched again" dropped this line
  # in the one window where a retry was safe, and the run closed as invalidated
  # instead of retrying. A saved file at the path still names the design step
  # through the second reason. The LAST row decides because a step dispatched
  # again carries one row per attempt, and only the latest says how it stands
  # now.
  #
  # A CRASH THAT SAVED NOTHING IS LEFT OUT FOR THE SAME REASON. A stage that
  # died of an API usage limit — which resets on its own — is written
  # `한도 종료` when its own stream shows it and `크래시` otherwise, and this
  # line reads both as `크래시`: without that, a transient limit sits in the same
  # place as a stage that is genuinely broken, and this line then declares the
  # run dead minutes after a transient error. Measured:
  # a design stage died on HTTP 429 with the limit's own reset time in the
  # result envelope, and the next router settled all five termination clauses
  # as `불가능` on that one row, three minutes later, with the limit already
  # due to clear. What actually bars a retry is a document a retry would write
  # over; the stage's spawn-time stub is not one, and the stage's own
  # target-document guard passes that stub rather than parking on it. So the
  # class is not read alone — it is read together with what sits at the path.
  #
  # THE RETRY DEPTH IS READ HERE, AND DECLARED IN THE ROUTER. The gate refuses no
  # dispatch and caps nothing: the routers stop the design themselves. But a
  # `크래시` with no usage-limit envelope and a `공허한 성공` do not clear by
  # themselves, so the routers buy each of them one fresh attempt and then stop
  # the design and propose done. This function counts the same attempts by the
  # same definition (`gate_design_fresh_attempts`) and reads a spent depth as
  # closing the window. Counted on one side only, the router stopped on a state
  # this line still read as the retry window: it printed the plain zero-segment
  # line, `gate_done_disposition` kept it, and every proposal the router was
  # told to make was refused — a run that could neither dispatch nor end.
  #
  # THE CONTINUATION CAP IS READ HERE, AND IT IS NOT THAT BUDGET. It is the
  # gate's own count of `--resume` continuations on the step, the one
  # `gate_continuation_argv` refuses at. Both routers stop the design once it
  # is reached instead of dispatching the step afresh, so a `공허한 성공` step
  # at the cap is not dispatched again; left in the redispatch window it would
  # keep the plain line below standing, and the run could not end.
  #
  # This does not open an empty end. The line only decides the disposition when
  # it is the last one left: condition 7 still holds the run while the design
  # stage is live, and condition 10 still holds it until every termination
  # clause is settled, which on the normal path means the segments the frozen
  # document goes on to produce. Only a router that settles the document's
  # clauses as impossible, with evidence, leaves this line standing alone.
  #
  # A DESIGN THAT FROZE IS NOT A DESIGN THAT STOPPED. `정상 완료` is a row of a
  # class other than the redispatch window's, so it used to fall into
  # `종단 행 있음` and the run could close as invalidated with its audit and its
  # segments never dispatched. When the plan still has a step after the design
  # that has not started — an audit step with no `stage-result` row, or an
  # implement step while no segment row exists — the line names that step, and
  # its head is not one `gate_done_disposition` drops: the run is unfinished,
  # not void. An audit that ran and ended any other way is not named here; the
  # router stops on it, and the old line then lets the run record its end.
  #
  # AND A PLAN THAT ENDS AT THE DESIGN HAS NO STEP TO NAME. When every step of
  # the plan is the design or its audit (`gate_plan_ends_at_design`), a design
  # that ended `정상 완료` — with its audit, when the plan has one, concluded
  # (`gate_audit_concluded`) — is the run's work done, provided the document is
  # still frozen when this reads it. The condition then holds and prints
  # nothing, as the audit-first arm does, and condition 10 measures the clauses
  # the person authorized. Read as `종단 행 있음`, the run closed as invalidated
  # with every clause settled satisfied. A document no longer frozen prints the
  # dropped line with its own reason; an audit that ended any other way keeps
  # `종단 행 있음`.
  #
  # AN AUDIT WAITING ON ITS SKELETAL RE-CONVERGENCE, OR ON THE FRESH AUDIT AFTER
  # A RE-CONVERGENCE ON ITS KEY, waits whatever follows it in the plan: the line
  # is the audit-first arm's, which the disposition does not drop.
  local n_seg dstep dwhy dname drows dlast dlastrow dfresh dnext astep dwait dmet
  n_seg=$(gate_rows 'segment' | gate_count)
  if [ "$n_seg" = "0" ]; then
    dwhy=""; dnext=""; dwait=""; dmet=""
    if dstep=$(gate_run_scope_step design); then
      dname=$(manifest_field '요소' '설계 문서' 2>/dev/null) || dname=""
      drows=$(gate_stage_result_rows_of "$dstep")
      # The driver names its design stage `S1design` and writes no `종류`. A base
      # run never has a segment, so this arm is where the driver's design row
      # has to be read too — otherwise its finished design reads as no row at all
      # and the document it froze as one nobody will dispatch again.
      if [ -z "$drows" ] && [ "$(gate_snapshot_design_scope)" = "base" ]; then
        drows=$( { gate_rows 'stage-result' || true; } \
                 | { grep -F '세그먼트=- | 스테이지=S1design |' || true; })
      fi
      dlastrow=$(printf '%s\n' "$drows" | tail -1)
      dlast=$(gate_row_field "$dlastrow" '종단 부류')
      # `공허한 성공` joins `크래시` in the redispatch window. The two names
      # describe one situation — the stage is over and carried nothing off — and
      # which of them is written depends only on whether the process died or
      # returned zero, which says nothing about whether a retry would destroy
      # work. The document is the discriminator on both, exactly as before.
      #
      # WITH ONE EXCEPTION THE CRASH ARM DOES NOT NEED. A stage that emitted a
      # judgment and opened an approval on this step also exits 0 and also
      # leaves no document, and it is written `공허한 성공` too — but it stopped
      # ON PURPOSE and a person owes it an answer. Redispatching that asks the
      # same question again and bills for it. A crashed stage never emits, so
      # the arm above cannot reach this state and asks nothing about it.
      if [ -n "$drows" ] && [ "$dlast" = '공허한 성공' ] \
         && [ "$(continue_count "$dstep")" -ge "$CONTINUE_MAX" ]; then
        dwhy='계속 소진'
      elif [ -n "$drows" ] && [ "$dlast" != '외부 종료' ] \
         && ! { { [ "$(terminal_route_class "$dlast")" = '크래시' ] \
                  || { [ "$dlast" = '공허한 성공' ] \
                       && ! gate_design_step_has_open_approval; }; } \
                && { [ -z "${DOC:-}" ] || [ ! -e "$DOC" ] || doc_is_early_stub "$DOC"; }; }; then
        dwhy='종단 행 있음'
        if [ "$dlast" = '정상 완료' ]; then
          dnext=$(gate_design_next_undispatched_step) || dnext=""
          # An audit waiting on its skeletal re-convergence, or on the fresh
          # audit after one, is the run's next work whatever follows the audit
          # in the plan: the line names the wait, as the audit-first arm does,
          # and is not a head the disposition drops.
          if [ -z "$dnext" ] && [ "$(gate_snapshot_design_scope)" != "base" ] \
             && astep=$(gate_run_scope_step audit) \
             && ! gate_audit_concluded "$astep"; then
            case "$GATE_AUDIT_WAIT" in
              골격급|재수렴)
                dwait=$(printf '1 세그먼트가 하나도 없습니다 — 감사 단계(%s)가 %s' "$astep" "$GATE_AUDIT_WHY")
                dwhy="" ;;
            esac
          fi
          if [ -z "$dnext" ] && [ -z "$dwait" ] && [ "$(gate_snapshot_design_scope)" != "base" ] \
             && gate_plan_ends_at_design; then
            if astep=$(gate_run_scope_step audit); then
              if gate_audit_concluded "$astep"; then
                if doc_is_frozen "${DOC:-}"; then dwhy=""; dmet=1
                else dwhy='설계 문서가 동결돼 있지 않음'; fi
              fi
            elif doc_is_frozen "${DOC:-}"; then
              dwhy=""; dmet=1
            else
              dwhy='설계 문서가 동결돼 있지 않음'
            fi
          fi
        fi
      else
        case "$dname" in
          '' | '없음' | '(없음)') dwhy='설계 문서 이름 없음' ;;
          *) if [ -n "${DOC:-}" ] && [ -e "$DOC" ] && ! doc_is_early_stub "$DOC"; then
               dwhy='설계 문서가 이미 있음'
             fi ;;
        esac
        # Inside the window, the depth the routers declare: a `공허한 성공`, or
        # a `크래시` whose stream holds no usage-limit envelope, gets one fresh
        # attempt. Once two stand the routers stop the design, and this line
        # names the step so the proposal they make closes the run. `외부 종료`
        # and a limit crash keep the window whatever the count.
        if [ -z "$dwhy" ] && [ -n "$drows" ] && [ "$dlast" != '외부 종료' ] \
           && { [ "$dlast" = '공허한 성공' ] \
                || ! gate_design_row_has_limit_envelope "$dstep" "$dlastrow"; }; then
          dfresh=$(printf '%s\n' "$drows" | gate_design_fresh_attempts)
          if [ "${dfresh:-0}" -ge 2 ]; then
            dwhy="새 시도 깊이 소진(${dfresh}회)"
          fi
        fi
      fi
      # A BASE RUN'S FINISHED DESIGN IS NOT A DEAD ONE. In a single run a design
      # that ended `정상 완료` with no segment after it means the plan stopped
      # there, and when the plan ends at the design (and its audit) that ending
      # and the frozen document are the run's work done, judged above; in a base
      # run it is the normal road to the audit and the split, which the base arm
      # below judges.
      #
      # So is one that was never dispatched because the document was already
      # there and frozen. A base run kicked off again over the same document —
      # the recovery after a split stopped and a person fixed the document —
      # skips the design in both routers and the driver, so it has no design row
      # at all, and the frozen document is the same input a `정상 완료` would
      # have left. An unfrozen document keeps the line: nothing audits or splits
      # it.
      if [ "$(gate_snapshot_design_scope)" = "base" ]; then
        if [ "$dlast" = '정상 완료' ] \
           || { [ -z "$drows" ] && [ "$dwhy" = '설계 문서가 이미 있음' ] && doc_is_frozen "${DOC:-}"; }; then
          dwhy=""
        fi
      fi
    fi
    # A RUN-SCOPE STEP WHOSE PARK'S ANSWER IS CARRIED OVER comes first, before
    # every other reading of the design, the audit, the re-convergence or the
    # split on the same key: the step is neither closed nor void, and is not
    # waiting on anything this run can do — the next run dispatches it again
    # with the answer.
    local dfer="" dk
    for dk in "$dstep" "$(gate_run_scope_step audit 2>/dev/null || true)" \
              "$(gate_run_scope_step split 2>/dev/null || true)"; do
      [ -n "$dk" ] || continue
      dfer=$(gate_step_deferred_line "$dk") && break
      dfer=""
    done
    if [ -n "$dfer" ]; then
      printf '%s\n' "$dfer"
    elif [ -n "$dnext" ]; then
      printf '1 설계가 동결됐으나 다음 단계(%s)가 아직 파견되지 않았습니다\n' "$dnext"
    elif [ -n "$dwait" ]; then
      # A plan that ends at its audit, waiting on the fresh audit after a
      # re-convergence: not a head the disposition drops.
      printf '%s\n' "$dwait"
    elif [ -n "$dwhy" ]; then
      printf '1 세그먼트가 하나도 없고 설계 단계가 더는 파견되지 않습니다 — %s · %s · 남은 종료 절을 정산하면 런은 무효로 끝납니다\n' "$dstep" "$dwhy"
    elif [ "$dmet" = 1 ]; then
      # The plan ended at the design (and its audit), and it froze: held.
      :
    elif [ "$(gate_snapshot_design_scope)" = "base" ]; then
      # A BASE RUN NEVER HAS A SEGMENT. Its graph ends at the split, so "no
      # segment" is its normal end and the plain line below would hold it
      # forever. What it waits on instead is the split: met when the split step's
      # latest attempt carries its terminal literal and the registry is complete
      # for the current document, closed when the audit or the split will not be
      # dispatched again, and otherwise not finished yet.
      gate_base_split_unmet
    elif [ -z "$dstep" ] && astep=$(gate_run_scope_step audit); then
      # A SINGLE RUN WHOSE PLAN OPENS ON THE AUDIT. Its document was frozen
      # before the run, so there is no design step for the arm above to read,
      # and the audit is the step that decides whether anything can follow.
      # Without this arm the plain line below stood whatever the audit did: an
      # audit-only plan could not end after its audit finished, and a plan whose
      # audit parked before any segment could not even end as invalidated.
      gate_audit_first_unmet "$astep"
    else
      printf '1 세그먼트가 하나도 없습니다 — 런이 아직 아무것도 만들지 않았습니다\n'
    fi
  fi
  for sid in $(gate_segment_ids); do
    [ -n "$sid" ] || continue
    st=$(gate_segment_field "$sid" '상태')
    # A merge that still owes its apply is not an ending — the same marker
    # `cc_nonterminal_segments` reads, so the run-state reader agrees.
    if gate_segment_apply_pending "$sid"; then
      printf '1 세그먼트 %s 의 적용이 남았습니다 (머지됨 · 적용=대기)\n' "$sid"
      continue
    fi
    # A segment whose park's answer is carried over waits for the next run,
    # whatever state its row reads.
    gate_step_deferred_line "$sid" && continue
    case " $TERMINAL_SEGMENT_STATES " in
      *" $st "*) ;;
      *) printf '1 세그먼트 %s 의 상태가 종단이 아닙니다 (%s)\n' "$sid" "${st:-미상}" ;;
    esac
  done

  # 2 — no ACT approval still waiting. `절단점=판단` is excluded deliberately:
  # its answer is an input to work that has not begun, so it survives the night
  # and a successor run consumes it, while an act approval's answer is valid
  # only against the tree its binding tuple named. A run that could never end
  # while a question was open is the failure this whole design removes.
  n=$(gate_pending_approval_ids act | gate_count)
  [ "$n" = "0" ] || printf '2 대기 중인 행위 승인이 %s건 있습니다\n' "$n"
  # THE QUESTIONS THE RUN DOES NOT END AROUND are the person set, `사람-결정`
  # and `시각-승인`. Their answer is not an input a successor consumes but the
  # decision a segment of THIS run is held on — the segment cannot reach a
  # terminal state while one is open, and a run that ended over it would leave
  # the held work with no run to resume it. So they count here, as their own
  # line, while every other `판단` approval stays excluded as above.
  n=$(gate_pending_approval_ids 사람 | gate_count)
  [ "$n" = "0" ] || printf '2 대기 중인 사람 판단 승인(사람-결정·시각-승인)이 %s건 있습니다\n' "$n"

  # 3 — obligations empty, or disposed. THE SUBTRACTION MOVED INTO
  # `gate_open_obligations` and is no longer applied a second time here: three
  # dispositions now close an obligation — `종결`, `포기` and `면제` — and the
  # list is what knows about all three. Re-applying the excusal here would name
  # only one of them and would say nothing about the other two.
  #
  # The excuse itself stays NARROW: every problem row of the identity sits in a
  # parked segment AND the highest creation grade any of them recorded is at or
  # below `워크트리쓰기`. An obligation made by a higher-graded act is never
  # excused, because that is precisely the obligation whose effects left the
  # machine.
  gate_open_obligations | while IFS= read -r o; do
    [ -n "$o" ] || continue
    printf '3 미해결 의무가 남아 있습니다: %s\n' "${o#obligation=}"
  done

  # 4 — ledger damage
  n=$(gate_ledger_damage)
  [ "$n" = "0" ] || printf '4 원장 손상 행이 %s건입니다\n' "$n"

  # 5 — blocks holding the run resolved or enumerated
  #
  # "Holding the run" is a run-scope row or a cone row anchored on a design
  # step: a step stands in front of every segment, so its cone is the whole run.
  #
  # LAST ROW PER `사유` WINS, the way conditions 2 and 9 already read approvals
  # and review obligations. Counting raw rows made this a one-way latch: a
  # ledger row is never deleted, so a single run-scope block — including one the
  # watcher raised on a false positive — took the run's ability to propose done
  # away permanently. The comment above promised "resolved or enumerated" and
  # the code implemented neither.
  #
  # Measured: an audit stage completed normally, the watcher observed a stall
  # that had not happened, the gate transcribed it, and the run then satisfied
  # the other eight conditions and was refused on this one with no verb in
  # existence that could clear it.
  #
  # `원인=무효화` is deliberately NOT resolvable. That is the enforcement-surface
  # block, whose own resume line says this run's baseline is never retaken — a
  # run that could clear it would be re-authorizing itself past the boundary
  # that had just refused it.
  # The fold itself lives in `liveness.sh` so that this condition and the status
  # line read one rule rather than two copies of it. What stays here is the
  # RENDERING: these two sentences are the only place a person is told how to
  # clear the block, so they are not the shared function's business. The first
  # of them is also read as a value: `gate_done_disposition` anchors on the
  # invalidation line's fixed head (`5 런 스코프 blocked 가 해소 불가입니다 `) to
  # tell an invalidated run from an unmet one, so that head and its grep there
  # change together or an invalidated run can no longer record its end.
  local reason cause
  cc_unresolved_blocked "$LEDGER" \
    | while IFS="$(printf '\t')" read -r cause reason; do
        [ -n "$reason" ] || continue
        if [ "$cause" = "무효화" ]; then
          printf '5 런 스코프 blocked 가 해소 불가입니다 (%s) — 이 런은 끝났습니다\n' "$reason"
        else
          printf '5 런을 막는 blocked(런 스코프 또는 런 범위 스텝 앵커 cone)가 미해소입니다 (%s) — 해소했다면 act --kind blocked 로 원인=해소 행을 쓰세요; 런 범위 스텝의 마감 파킹은 그 재개 명령으로 다시 파견해도 풀립니다(사유가 중단 답 라우팅 — 으로 시작하는 라우팅 막힘은 계보가 없어 다시 파견해도 풀리지 않고 원인=해소 로만 풀립니다)\n' "$reason"
        fi
      done

  # 6 — terminal-act cap
  gate_terminal_cap_ok || printf '6 말단 행위 상한을 넘었습니다\n'

  # 7 — no live stage process
  n=$(gate_live_stages)
  [ "$n" = "0" ] || printf '7 살아 있는 스테이지가 %s개입니다\n' "$n"

  # 8 — report file exists
  [ -f "$BASE/docs/pipeline-run/$RUN_ID.md" ] || printf '8 리포트 파일이 없습니다\n'

  # 10 — every authorized termination clause is settled.
  #
  # Conditions 1 to 9 measure the ledger's SHAPE — segments terminal, approvals
  # closed, no damage, no live stage. None of them measures the thing the user
  # actually authorized the run against, so a run with five of six clauses
  # unsettled passed all nine and ended as `충족`. The clauses were frozen into
  # the binding digest at kickoff and then read by nothing: `종료 절` appeared
  # zero times in this file.
  for sid in $(gate_unmet_clause_ids); do
    [ -n "$sid" ] || continue
    # TERSE ON PURPOSE. Every unmet line is joined into the rejection row's
    # `근거` field, and that row has a 1024-byte cap — a verbose condition with
    # several clauses overflowed it and turned a rule refusal into a `die`. The
    # repair instruction belongs beside the refusal, not inside the row.
    printf '10 종료 절 %s 미정산\n' "$sid"
  done
  # A clause settled `불가능` is settled, and it is also a goal this run will
  # never reach. Leaving it out of this list made such a run read `충족`, and the
  # morning could not tell it from a run that reached every clause. The line has
  # its own fixed head so `gate_done_disposition` can drop it the way it drops
  # condition 5's: what the run records is then its invalidation.
  for sid in $(gate_impossible_clause_ids); do
    [ -n "$sid" ] || continue
    printf '10 종료 절 %s 불가능 정산\n' "$sid"
  done

  # 10b — the clause list is not EMPTY. Condition 10 iterates the parsed clauses
  # and reports the unsettled ones, so a manifest whose `종료 절` rows are spelled
  # such that none matches yields an empty list and the condition is satisfied
  # VACUOUSLY — the run can propose done the moment it starts, having been
  # measured against nothing. The `종료 지점` prose still reads correctly to a
  # person, which is why this passes every human check.
  #
  # This fires HERE and not in `check_manifest`, deliberately. A hard stop at
  # entry would refuse every manifest already written without clause rows —
  # including runs in flight, which is the failure mode two open issues in this
  # repository are about. Refusing the PROPOSAL instead costs nothing to a run
  # that never tries to end and blocks exactly the thing that was wrong.
  [ -n "$(manifest_clauses)" ] \
    || printf '10 매니페스트에 파싱되는 종료 절이 하나도 없습니다 — 종료 지점이 산문으로만 있어 이 런은 무엇에도 대조되지 않습니다\n'

  # 9 — no unfulfilled review obligation. Condition 3 does not subsume this:
  # 3 narrows when an EXISTING obligation is excused, and 9 holds the ones
  # `선머지후리뷰` deliberately deferred. This design's own four slices all
  # declare that mode, so the first run of it against itself takes this path.
  n=$(gate_unfulfilled_review_obligations | gate_count)
  [ "$n" = "0" ] || printf '9 미이행 리뷰 의무가 %s건입니다\n' "$n"

  # 11 — no segment under `선리뷰후머지` whose merge was recorded against a
  # review that did not clear it. The merge rule refuses such a merge only when
  # the merge goes through the gate; this reads what the merged row recorded,
  # so a merge made any other way is held here instead.
  #
  # THE LAST ROW CARRYING `머지 대조` ANSWERS, not the last row. A later row
  # without the field — a `완료` written after the merge — says nothing about
  # the comparison and does not clear it. What clears it is an appended second
  # `머지됨` row whose comparison reads a passing value. A coverage violation
  # clears with a review covering the merged commit and its `cycle` row before
  # that second row; a count violation clears with the person's `리뷰 기각` of
  # the merged last cycle at the seat before it, which reads `기각`. A run
  # cannot write a dismissal, so an unattended run is held here on a count
  # violation until a person answers.
  #
  # `룰 설정: 끔` turns this off with the rule, and only this: the field is still
  # written, so the morning can read what the setting let through.
  #
  # THE PASSING VALUES ARE NAMED AND EVERYTHING ELSE HOLDS, an empty value
  # included. Listing the failing values instead let any spelling outside the
  # list — the one a caller could still get onto the ledger — read as a pass.
  # `이월` passes: it records a merge the merge rule let through after the last
  # cycle's open P1 findings were carried over to issues. `기각` passes: it
  # records a merge of a cycle a person dismissed at the seat — only the seat
  # writes `리뷰 기각` — which the merge rule and the `다음` table read before
  # the counts and let through. A `P0 > 0` or `P1 > 0` with neither still reads
  # `위반(카운트)` and holds, and either one that does not cover the merged tip
  # reads `위반(미포함)` and holds — save `메타 해소`, which passes: the tip the
  # review did not cover is the renumbering merge of the reviewed HEAD, whose
  # tree that HEAD and the merged base fix to the object id.
  if gate_rule_enabled '리뷰-후-머지'; then
    local pol mcv mrow
    for sid in $(gate_segment_ids); do
      [ -n "$sid" ] || continue
      pol=$(gate_segment_field "$sid" '리뷰 정책')
      [ "${pol:-선리뷰후머지}" = '선리뷰후머지' ] || continue
      mrow=$(gate_rows 'segment' | gate_rows_field_eq 'id' "$sid" \
              | gate_rows_having_field '머지 대조' | tail -1)
      [ -n "$mrow" ] || continue
      mcv=$(gate_row_field "$mrow" '머지 대조')
      case "$mcv" in
        '충족'|'정책 면제'|'이월'|'기각'|'메타 해소') ;;
        *) printf '11 세그먼트 %s 의 머지 대조가 %s 입니다\n' "$sid" "${mcv:-(빈 값)}" ;;
      esac
    done
  fi
}

gate_pending_approval_ids() {
  # gate_pending_approval_ids [act|판단] — pending approval ids, optionally
  # narrowed by whether the row's `절단점` is the literal `판단`.
  #
  # The narrowing exists because the two kinds of answer have different lifetimes
  # and only one of them expires with the night. An ACT approval's answer is
  # valid now — its binding tuple carries head and base shas and freshness is
  # re-derived against them — so a run may not end while one is open. A QUESTION
  # approval's answer is an input to work that has not started; it is durable,
  # and a successor run can consume it. Counting the second kind in termination
  # condition 2 is what made one open question a run that could never say it was
  # done, which is the defect this design exists to remove.
  #
  # `사람` NARROWS FURTHER, to the `판단` approvals whose class is in the person
  # set: the kind of question the run does not end around. Its answer is not an
  # input a successor consumes but the decision the held segment is waiting on,
  # so termination condition 2 counts these beside the act approvals.
  local want="${1:-}" id st row cut
  for id in $(gate_rows '승인' | tr '|' '\n' | sed -n 's/^ *승인 id=//p' | sed 's/[[:space:]]*$//' | sort -u); do
    [ -n "$id" ] || continue
    row=$( { gate_rows '승인' | grep -F "| 승인 id=$id |" || true; } | tail -1)
    st=$(gate_row_field "$row" '상태')
    [ "$st" = "대기" ] || continue
    if [ -n "$want" ]; then
      cut=$(gate_row_field "$row" '절단점')
      case "$want" in
        act)  [ "$cut" = "판단" ] && continue ;;
        판단) [ "$cut" = "판단" ] || continue ;;
        사람) [ "$cut" = "판단" ] || continue
              judgment_class_person "$(gate_row_field "$row" '판단 부류')" || continue ;;
      esac
    fi
    printf '%s\n' "$id"
  done
  return 0
}

gate_unfulfilled_review_obligations() {
  # gate_unfulfilled_review_obligations [segment]
  #
  # With no argument this is the run-wide list that termination condition 9
  # counts. With one it is narrowed to that segment, which is what the issuing
  # guard and the order predicate need — asked run-wide, they would let a
  # sibling segment's open obligation answer a question posed about this one,
  # and the answer would be wrong in the permissive direction for the issuer and
  # in the refusing direction for the predicate.
  local want="${1:-}" id st row seg
  local GATE_ROWS_MEMO_LEDGER GATE_ROWS_MEMO_N GATE_ROWS_MEMO_KINDS GATE_ROWS_MEMO_ROWS
  gate_ledger_warm '리뷰 의무'
  for id in $(gate_rows '리뷰 의무' | tr '|' '\n' | sed -n 's/^ *의무 id=//p' | sed 's/[[:space:]]*$//' | sort -u); do
    [ -n "$id" ] || continue
    row=$( { gate_rows '리뷰 의무' | grep -F "의무 id=$id " || true; } | tail -1)
    st=$(gate_row_field "$row" '상태')
    [ "$st" = "미이행" ] || continue
    if [ -n "$want" ]; then
      seg=$(gate_row_field "$row" '세그먼트')
      [ "$seg" = "$want" ] || continue
    fi
    printf '%s\n' "$id"
  done
  return 0
}

gate_grade_rank() {
  # gate_grade_rank <grade> — a rank over THIS function's own closed set.
  #
  # SELF-CONTAINED ON PURPOSE, and not a second copy of `surface_index`. That
  # function answers an empty string and rc=1 for a value off its ladder, and the
  # gate is sourced under `errexit` with `nounset`, so an unguarded assignment
  # from it dies on the very input this comparison exists to handle — with rc=1,
  # which is also an act's own failure code, so the morning cannot tell a refusal
  # from a failed act. Ranking here means a value off the ladder never reaches a
  # numeric comparison at all.
  #
  # EVERY UNKNOWN VALUE RANKS ABOVE EVERY KNOWN GRADE, which is what makes
  # `등급 미상` un-excusable. That token is the grade a REFUSED act structurally
  # carries, and refused acts are the main way problem rows come to exist — so
  # letting it fall through to the low end would excuse exactly the obligations
  # the narrow rule was written to keep open. When the grading table later splits
  # that token into "no row in the table" and "deliberate refusal", both halves
  # are still unknown values here and both still rank at the top; this arm holds
  # its own guard rather than consuming one that has not landed yet.
  case "$1" in
    읽기)         printf '1' ;;
    워크트리쓰기) printf '2' ;;
    트리밖쓰기)   printf '3' ;;
    외부상태변경) printf '4' ;;
    *)            printf '9' ;;
  esac
}

# The highest known grade the narrow excuse still admits — `워크트리쓰기`.
readonly EXCUSE_GRADE_CEILING=2

gate_obligation_excused() {
  # gate_obligation_excused <identity>
  #
  # BOTH AXES ARE UNIVERSALLY QUANTIFIED over the problem rows carrying this
  # identity, and neither reads `tail -1` any more. The last row used to win on
  # both, and both fields arrive in the router's argv — so writing one more
  # problem row for the same identity, naming a parked segment and a low creation
  # grade, excused an obligation that had been opened at a higher grade in a live
  # segment. The chain stayed intact, the row was well formed, and the act was
  # itself graded `읽기` so it spent no budget. A barrier standing on a field the
  # run can rewrite is not a barrier, and this was that defect on two axes at
  # once — the design fixed the grade axis first and the segment axis was still
  # carrying it.
  #
  # Grade axis: the HIGHEST creation grade ever recorded for the identity. Once a
  # row claims a grade the claim is kept, so a later row cannot lower it.
  # Segment axis: excused only when EVERY such row sits in a terminal segment.
  # Both quantifiers point the same way — adding a row can only move the answer
  # AWAY from excusal, never toward it.
  #
  # TERMINAL IS RE-READ AT CALL TIME rather than carried, and that is a
  # deliberate split by tense. Segment state is reversible — park→실행중→park is
  # rc=0 at every step — so "this segment is terminal" is a claim about the
  # present, and a claim about the present is re-verified where it is used. The
  # obligation-closing verbs make the same split for the same reason: `종결`
  # cites a past act and is never re-checked because the past cannot be
  # rewritten, `포기` cites a current state and is re-checked at exclusion time.
  # `park` AND NOT THE WIDER TERMINAL SET. The excuse's segment test is narrowed
  # here, not widened: this slice changes the QUANTIFIER on both axes and nothing
  # else, and swapping `park` for every terminal state would open the excuse to
  # obligations in merged and completed segments — a change nobody asked for,
  # arriving disguised as a refactor. The `포기` verb, which is a different
  # disposition with a different question, uses the wider set on purpose.
  local ident="$1"
  gate_obligation_segments_parked "$ident" || return 1
  [ "$(gate_grade_rank "$(gate_obligation_top_grade "$ident")")" \
    -le "$EXCUSE_GRADE_CEILING" ]
}

gate_obligation_top_grade() {
  # gate_obligation_top_grade <identity> — the HIGHEST `생성 등급` any problem row
  # for the identity has recorded, or `없음` when there are none. Once a row
  # claims a grade the claim is kept, so a later row cannot lower it.
  local ident="$1" rows row grade rank best=0 top='없음'
  rows=$( { gate_rows 'problem' | grep -F "동일성=$ident " || true; } )
  while IFS= read -r row; do
    [ -n "$row" ] || continue
    grade=$(gate_row_field "$row" '생성 등급')
    rank=$(gate_grade_rank "$grade")
    if [ "$rank" -gt "$best" ]; then best="$rank"; top="${grade:-없음}"; fi
  done <<GATE_TOP_GRADE_ROWS
$rows
GATE_TOP_GRADE_ROWS
  # A here-document and not a pipe: a `while` on the right of a pipe runs in a
  # subshell, so `best` would be discarded at the loop's end and every identity
  # would compare against 0.
  printf '%s' "$top"
}

gate_obligation_segments() {
  # gate_obligation_segments <identity> — the distinct segments its problem rows
  # name, space separated. The bundle crosses segments, so this is a set.
  { gate_rows 'problem' | grep -F "동일성=$1 " || true; } \
    | tr '|' '\n' | sed -n 's/^ *세그먼트=//p' | sed 's/[[:space:]]*$//' \
    | { grep -v '^$' || true; } | LC_ALL=C sort -u \
    | tr '\n' ' ' | sed 's/[[:space:]]*$//'
}

gate_obligation_segments_parked() {
  # gate_obligation_segments_parked <identity> — EVERY problem row carrying the
  # identity sits in a `park` segment, judged now.
  local ident="$1" rows row seg st n=0
  rows=$( { gate_rows 'problem' | grep -F "동일성=$ident " || true; } )
  [ -n "$rows" ] || return 1
  while IFS= read -r row; do
    [ -n "$row" ] || continue
    n=$((n + 1))
    seg=$(gate_row_field "$row" '세그먼트')
    [ -n "$seg" ] || return 1
    st=$(gate_segment_field "$seg" '상태')
    [ "$st" = "park" ] || return 1
  done <<GATE_PARK_ROWS
$rows
GATE_PARK_ROWS
  [ "$n" -gt 0 ]
}

gate_terminal_cap_ok() {
  local a cap n
  for a in $(target_aliases); do
    cap=$(target_field "$a" '말단 행위 상한')
    case "$cap" in ''|없음) continue ;; esac
    # THE FIELD SEPARATOR IS PART OF THE PATTERN, and without it this counts every
    # merge TWICE. The row now carries `유도 절단점=` beside `절단점=`, and an
    # unanchored substring matches inside the longer key — so one merge whose argv
    # derived `머지` would consume two of the target's terminal-act budget. Anchored
    # to ` | `, `| 유도 절단점=머지 ` cannot match, because the text immediately
    # before `절단점` there is `유도 ` and not `| `.
    #
    # `결정=(act|exec)` IS PART OF THE PATTERN FOR THE SECOND HALF OF THE SAME
    # COUNTING ERROR. An act that FAILS writes a `결정=결과` row carrying the
    # identical `절단점`, so one merge that could not reach its remote consumed
    # TWO of the target's terminal budget — and the budget is spent by acts
    # PERFORMED, under either verb `act` or `exec`, not by rows written about
    # them. A succeeding merge writes no result row, which is why this never
    # showed up until an argv that fails by construction (`gh pr merge` against
    # a local bare remote) was counted. The refusal and void rows the
    # propose-done path writes are excluded by the same token.
    #
    # BOTH VERBS, NOT ONE. The row above carries `결정=$verb`, and a stage session
    # performs every merge it makes as `exec` — the hook forces that verb on all
    # of its bash. Narrowed to `act` alone, a merge the stage pushed passed this
    # count untouched and a run past its cap could still propose its own end.
    n=$(gate_rows '자율 승인' | grep -F "대상=$a " | grep -E '\| 결정=(act|exec) \|' \
          | grep -cF '| 절단점=머지 ' || true)
    [ "$n" -le "$cap" ] || return 1
  done
  return 0
}

gate_live_stages() {
  # Delegated. This is termination condition 7's only input, and condition 7 has
  # no resolving verb — so a pid that had been reused blocked the run's end
  # PERMANENTLY, since pid files are removed only when a stage exits normally.
  # `kill -0` alone cannot see that; the shared predicate compares the recorded
  # start-time fingerprint too.
  cc_live_stages "$RUN_DIR"
}

# ---------------------------------------------------------------------------
# The router shift — the session cap, measured from here.
#
# Cost grows as N x (P + C) / 2, so a routing loop that never restarts pays for
# its whole history on every turn. The remedy is to end the routing session on a
# threshold and start a successor, and the reason it is measured HERE is that
# nobody else can: the router cannot read its own context (an estimate would be
# memory wearing a number), and the watcher refuses on charter — it resumes
# nothing, retries nothing and decides nothing. The gate already holds the three
# pieces this needs: it can tell a router from a stage, it knows where the
# transcripts are, and reading the tail of one costs milliseconds.
#
# THE SOFT CAP IS 300K BECAUSE MARGINAL RETURN COLLAPSES BELOW IT. Measured on
# the worst observed session at a 75K restart floor: 500K saves 46.5%, 300K
# saves 64.9%, 250K saves 68.8%. The step down to 300K buys 18.4 points; the next
# one buys 4.6 and takes the shift count from 28 to 36, and every shift pays for
# a successor re-finding its bearings.
#
# THE HARD CAP IS 1.5x THE SOFT ONE. Past the soft cap a shift still needs room
# to finish what it started — receive a dispatch result, write its handoff row —
# and at a median 926 tokens per turn that is roughly 162 turns of slack, which
# does not reach the 500K band where 39.1% of all cost sits.
#
# TURN COUNT IS A SECOND-ORDER TRIPWIRE AND NOT A SHIFT TRIGGER. Turns per shift
# spread 57..277, a 4.9x spread, which makes them a poor proxy for the quantity
# actually being capped. What the tripwire catches is a pathological low-cost
# loop — hundreds of turns adding almost nothing — and that is a failure of
# PROGRESS rather than of context, so it belongs to the stagnation boundary that
# already exists and not here.
#
# A SESSION CAP IS A ROUTING INSTRUCTION, NOT AN APPROVAL. Every one of B1..B4
# writes a `상태=대기` approval and stops the run until a person answers, so
# routing the cap through that machinery would end the night at the first
# threshold crossing. The one exception is the livelock guard below, and it is
# marked as one where it lives.
# ---------------------------------------------------------------------------
readonly SHIFT_SOFT_TOKENS=300000
readonly SHIFT_HARD_TOKENS=450000
# THE SEAT'S CEILING HAS ITS OWN NAME, NOT THE SHIFT'S SOFT CONSTANT. The value
# happens to equal `SHIFT_SOFT_TOKENS`, and the same 300000 is also spelled
# across the scripts as the AUTOCOMPACT WINDOW, a different quantity entirely;
# sharing a constant because the numbers agree is how moving one of them makes
# grep pick the other. The name is what tells them apart. No pin lint guards it:
# pins keep a value equal across a file boundary, and this one never leaves this
# file.
readonly SEAT_HARD_TOKENS=300000
readonly SHIFT_TURN_TRIPWIRE=400
readonly SHIFT_HANDOFF_CAP=3
readonly SHIFT_FLOOR_MAX=130000

gate_shift_launches() {
  # How many routing shifts this ledger has actually LAUNCHED: the count of
  # `교대 기동` rows, which `gate_launch_shift` writes immediately before it execs
  # the wrapper and in no other place.
  #
  # AN ATTEMPT IS NOT A LAUNCH, and counting the act's `자율 승인` row made the two
  # one thing. `gate_verb_act` appends that row BEFORE the dispatch, so it is on
  # the ledger even when the launcher turns back — held behind a live stage, or
  # stopped at the handoff floor — and both of those return having started
  # nothing. Every turned-back attempt therefore consumed an ordinal, and the
  # ordinal is what names `log/shift-<n>.json`: the file for that number was never
  # written by any run, so a morning reader following the scale landed on nothing.
  # Neither arm is exotic — the held one is the recovery `autopilot` prescribes.
  #
  # LAUNCHES AND NOT ENDINGS EITHER. The count of `handoff` rows stood here before
  # that, and it diverges the moment a shift dies before writing its own row.
  # Counting the launch directly is the only form that survives both.
  local n
  if [ -z "${LEDGER:-}" ] || [ ! -f "$LEDGER" ]; then printf '0'; return 0; fi
  n=$( { gate_rows '교대 기동' || true; } | gate_count)
  printf '%s' "${n:-0}"
}

gate_shift_number() {
  # The number of the shift that HOLDS THE ROUTING SEAT as this row is written.
  # `0` is the lead's own seat and the sidecar reserves it for a run whose
  # routing never left the lead, so a shard must never stamp it.
  #
  # A SHIFT READS ITS OWN MARKER. `CC_PIPELINE_SHIFT_ID` is `<run-id>#<n>` and the
  # launcher wrote that `<n>` from `gate_shift_launches`, so the number a shard
  # stamps is the number it was launched under — one expression carried across
  # the process boundary rather than re-derived on the far side of it. The count
  # of ENDED handoffs used to stand here, and it is a different quantity: shift 1
  # stamped `0` right up to its own handoff row, byte-identical to the value that
  # means routing never left the lead, and no reader could tell the two apart.
  #
  # AND THE ABSENCE OF THAT MARKER IS A SEAT, NOT A COUNT. This fell through to
  # `gate_shift_launches`, so from the first launch of the night onward every row
  # the LEAD wrote stamped the number of the shift then running — and `0`, the
  # value the sidecar reserves for "routing never left the lead", stopped being
  # written at all. The lead's rows became byte-identical to that shift's, which
  # is the same indistinguishability the paragraph above describes, arriving from
  # the other side.
  #
  # ONE EXPRESSION MUST NOT ANSWER TWO QUESTIONS. "How many shifts have been
  # launched" belongs to `gate_launch_shift`'s ordinal and nothing else; "who is
  # sitting in the routing seat as this row is written" is this function. Sharing
  # one expression between them is the root of the defect rather than a detail of
  # it, so the fallback here is the constant the seat is defined as.
  #
  # The expression is `run_shift_number` in `run.sh`, byte for byte: the driver
  # stamps the same `교대=` on the rows it chains, so the two writers must not be
  # able to derive two numbers for one seat.
  run_shift_number
}

gate_transcript_of_session() {
  # The transcript file for one session id, or nothing. Searched by NAME for the
  # same reason `gate_transcript_files` does: the directory is keyed by cwd and
  # shared with unrelated sessions.
  #
  # NOT FOUND IS RC 1, so a caller can tell it from a file; every caller takes
  # the status on the left of `||`, because this file runs under errexit.
  local sid="$1" dir f
  [ -n "$sid" ] || return 1
  dir=$(gate_transcript_dir) || return 1
  # Globbed rather than piped into an early-terminating reader. A reader that
  # stops at the first line kills the writer on its left, and under `pipefail`
  # that turns "found it" into a failed pipeline. The two patterns are the two
  # depths `-maxdepth 2` covered, and the first existing match still wins.
  for f in "$dir/$sid.jsonl" "$dir"/*/"$sid.jsonl"; do
    [ -f "$f" ] || continue
    printf '%s\n' "$f"
    return 0
  done
  return 1
}

gate_transcript_dir() {
  # gate_transcript_dir — the `projects` directory the transcript readers search,
  # rc 1 when it cannot be named or is not there.
  #
  # THE CALLER'S OWN SESSION IS READ WHERE THE CLI WROTE IT. A lead or a shift
  # reading its own transcript — `close`, a withdrawal, the router context, the
  # shift floor — takes `${CLAUDE_CONFIG_DIR:-$HOME/.claude}`, the rule the CLI
  # writes by. No launcher puts the variable into a lead, so the resolver's
  # second tier would send a lead started without it to the run's recorded seat,
  # where its transcript is not: every approval `close` would be refused even with
  # routing off, a withdrawal held, and the shift cap blind to its pressure.
  #
  # ONLY A STAGE'S TRANSCRIPT GOES THROUGH THE RESOLVER. A stage runs on the lane
  # it was launched on, and the resolver's first tier is that stage's own
  # environment.
  local cfg
  if cc_caller_is_stage; then
    cfg=$(resolve_account 2>/dev/null) || return 1
  else
    cfg="${CLAUDE_CONFIG_DIR:-$HOME/.claude}"
  fi
  [ -d "${cfg%/}/projects" ] || return 1
  printf '%s' "${cfg%/}/projects"
}

gate_transcript_miss_note() {
  # gate_transcript_miss_note — one log line per run when a reader found no
  # transcript and the caller's environment named no directory: the number
  # that follows is a `0` that means "not found", and the morning reader should
  # be able to tell it from a measurement. No row.
  [ -z "${CLAUDE_CONFIG_DIR:-}" ] || return 0
  [ -n "${RUN_DIR:-}" ] && [ -d "$RUN_DIR" ] || return 0
  ( set -C; : > "$RUN_DIR/transcript-miss.noted" ) 2>/dev/null || return 0
  log "트랜스크립트를 찾지 못했다 — 호출자 환경에 설정 디렉터리가 없고 판독한 디렉터리에도 이 세션의 파일이 없다 (런마다 한 번)"
}

gate_usage_scan() {
  # Reads a JSONL stream on stdin and prints
  # "<첫 턴 총 컨텍스트> <마지막 턴 읽기+생성+입력>".
  #
  # THE TWO ENDS ARE MEASURED DIFFERENTLY BECAUSE THEY ARE DIFFERENT QUANTITIES.
  # The FLOOR is the first turn's read PLUS its creation — on a session's opening
  # turn the cache breakpoint has not been established, so most of the prefix is
  # billed as creation and the read component alone reports a floor several times
  # too small. Conflating the two is the error this file's own measurement
  # history records: a floor quoted at 21,736 was the read component of a turn
  # whose actual context was 116,055.
  #
  # THE CURRENT CONTEXT IS THE LAST TURN'S READ + CREATION + INPUT. Read alone
  # assumed the prefix was already cached, and on a turn before the breakpoint
  # settles it is not: 210 of 6,804 measured turns reported less than 60% of
  # their actual context that way. A cap compared against that number does not
  # give a wrong answer, it does not fire on that act at all. The floor keeps
  # read + creation and does not add input — the two ends are independent
  # outputs, and `SHIFT_FLOOR_MAX` is compared against the first alone, so this
  # sum cannot move the livelock guard.
  #
  # THE INPUT PATTERN CARRIES ITS OPENING QUOTE. Without it `input_tokens":`
  # also matches inside both cache field names, and the first match would add a
  # cache component a second time — a plausible number nobody catches by eye.
  #
  # NO SCORED LINE PRINTS `-` AS THE SECOND FIELD, NEVER `0`. A transcript that
  # resolves but holds no line past the skip — a shift that died on its first
  # request, whose only record is an error with every token field at zero — has
  # no current context, and a `0` there is read downstream as a measurement: it
  # lands on the launch row's `컨텍스트` as a number and lets the hard cap pass
  # without the line an unresolved context owes. The floor keeps printing `0`;
  # its readers already take `0` as "no floor".
  awk '
    {
      r = 0; c = 0; i = 0
      if (match($0, /"cache_read_input_tokens":[ ]*[0-9]+/)) {
        s = substr($0, RSTART, RLENGTH); sub(/[^0-9]*/, "", s); r = s + 0
      }
      if (match($0, /"cache_creation_input_tokens":[ ]*[0-9]+/)) {
        s = substr($0, RSTART, RLENGTH); sub(/[^0-9]*/, "", s); c = s + 0
      }
      if (match($0, /"input_tokens":[ ]*[0-9]+/)) {
        s = substr($0, RSTART, RLENGTH); sub(/[^0-9]*/, "", s); i = s + 0
      }
      if (r == 0 && c == 0) next
      if (first == 0) first = r + c
      last = r + c + i
      scored = 1
    }
    END {
      if (scored) printf "%d %d", first + 0, last + 0
      else printf "%d -", first + 0
    }
  ' 2>/dev/null
}

gate_router_context() {
  # The routing session's context right now, in tokens, or `0`.
  #
  # THE CURRENT SESSION COMES FIRST AND THE LINEAGE IS THE FALLBACK, and the
  # order is not a preference. A shift is deliberately kept OUT of
  # `session-lineage` — that is what stops it answering its own approvals — so
  # lineage holds lead sessions only, and a shift asking lineage how big it is
  # would be handed the lead's number instead of its own.
  #
  # A SHIFT IS RESOLVED BY ITS ORDINAL AND NEVER BY EITHER OF THOSE TWO. Its
  # `CLAUDE_CODE_SESSION_ID` may have been inherited from the seat that launched
  # it, and the lineage holds lead sessions only, so both roads lead to the
  # lead's transcript — a plausible number belonging to another session. With a
  # cap comparing against this value that is worse than no number at all: a
  # newborn shift would read the lead's context as its own and end on its first
  # act, and so would its successor. Unresolved therefore reads `0` here, which
  # is what the cap predicate sees too — one number for the snapshot and the
  # enforcement both.
  #
  # Bounded read. The tail is where the last turn is, and 256KB of it is many
  # records; on a 42MB transcript this costs milliseconds, which is what makes it
  # affordable on a path the gate takes often.
  local f v n
  n=$(gate_shift_self_ordinal)
  if [ -n "$n" ]; then
    v=$(gate_shift_context_of "$n")
    case "${v:-}" in ''|*[!0-9]*) printf '0'; return 0 ;; esac
    printf '%s' "$v"
    return 0
  fi
  f=$(gate_transcript_of_session "${CLAUDE_CODE_SESSION_ID:-}") || f=""
  if [ -z "$f" ]; then
    f=$( { gate_transcript_files 2>/dev/null || true; } | tail -1)
  fi
  [ -n "$f" ] && [ -f "$f" ] || { gate_transcript_miss_note; printf '0'; return 0; }
  v=$(tail -c 262144 "$f" 2>/dev/null | gate_usage_scan | awk '{print $2}')
  case "${v:-}" in ''|*[!0-9]*) v=0 ;; esac
  printf '%s' "$v"
}

gate_shift_self_ordinal() {
  # gate_shift_self_ordinal — the ordinal of the shift RUNNING THIS PROCESS, or
  # nothing when the caller is not a shift.
  #
  # THE TEST IS THE ONE THE SHARED FENCE AND THE APPROVAL ROW ALREADY USE: a
  # caller that is not a stage and carries `CC_PIPELINE_SHIFT_ID` is the routing
  # shard. A stage a shift launched inherits that variable and is a stage first,
  # so it answers nothing here — a stage is not capped, and reading the launching
  # shift's ordinal for it would cap it under someone else's context.
  local n
  cc_caller_is_stage && return 0
  [ -n "${CC_PIPELINE_SHIFT_ID:-}" ] || return 0
  n="${CC_PIPELINE_SHIFT_ID##*#}"
  case "$n" in ''|*[!0-9]*) return 0 ;; esac
  [ "$n" -ge 1 ] || return 0
  printf '%s' "$n"
}

gate_shift_context_of() {
  # gate_shift_context_of <ordinal> — the current context of routing shift
  # <ordinal>, in tokens, or nothing when its transcript cannot be found or
  # holds no usage line to score.
  #
  # IT READS ONE SESSION, NAMED BY ITS ORDINAL, AND NEVER FALLS BACK. The id is
  # the one `gate_launch_shift` handed that shift as `--session-id`, derived here
  # by the same expression. `gate_router_context` reads the transcript of the
  # process RUNNING THIS CODE and falls back to the lineage, and both of those are
  # the seat whenever the caller is not the shift in question — the launcher
  # measuring its outgoing shift, above all. The floor guard in the launcher
  # already records this confusion once, and an empty answer is what stops it
  # recurring: no number is better than the seat's number under a shift's name.
  local n="$1" f v
  case "$n" in ''|*[!0-9]*) return 0 ;; esac
  [ "$n" -ge 1 ] || return 0
  f=$(gate_transcript_of_session "$(session_uuid "shift" "$n")") || f=""
  [ -n "$f" ] && [ -f "$f" ] || return 0
  v=$(tail -c 262144 "$f" 2>/dev/null | gate_usage_scan | awk '{print $2}')
  case "${v:-}" in ''|*[!0-9]*) return 0 ;; esac
  printf '%s' "$v"
}

gate_shift_org_moves_of() {
  # gate_shift_org_moves_of <ordinal> — the organization moves routing shift
  # <ordinal>'s session went through, read from the transcript
  # `gate_shift_context_of` reads, by the same session id and with the same
  # refusal to fall back. Nothing when the transcript cannot be found or the
  # session never moved, so the launch row stays as it was; a move is logged
  # once as a warning. A shift runs under the seat it was launched from, which
  # is where a person's `/login` reaches a running session.
  local n="$1" sid f m
  case "$n" in ''|*[!0-9]*) return 0 ;; esac
  [ "$n" -ge 1 ] || return 0
  sid=$(session_uuid "shift" "$n")
  f=$(gate_transcript_of_session "$sid") || f=""
  [ -n "$f" ] && [ -f "$f" ] || return 0
  m=$(transcript_org_moves "$f")
  case "$m" in ''|0|*[!0-9]*) return 0 ;; esac
  warn "교대 $n 세션 $sid 이 실행 중 조직을 ${m}번 옮겼다"
  printf '%s' "$m"
}

gate_shift_floor() {
  # The context this routing session STARTED at — the price of having restarted.
  #
  # A shift is a new process and inherits no compaction summary, so its floor is
  # the static prefix plus the snapshot plus the handoff rows: measured at
  # 73K..77K, against 109K..118K for an automatic compaction whose floor carries
  # a 37K..49K summary inside it. The difference is part of what the mechanism
  # buys, and quoting the compaction floor here would erase it.
  local f v
  f=$(gate_transcript_of_session "${CLAUDE_CODE_SESSION_ID:-}") || f=""
  if [ -z "$f" ]; then
    f=$( { gate_transcript_files 2>/dev/null || true; } | tail -1)
  fi
  [ -n "$f" ] && [ -f "$f" ] || { printf '0'; return 0; }
  v=$(head -c 1048576 "$f" 2>/dev/null | gate_usage_scan | awk '{print $1}')
  case "${v:-}" in ''|*[!0-9]*) v=0 ;; esac
  printf '%s' "$v"
}

gate_shift_state() {
  # The `shift` block of the snapshot, as a JSON object.
  local n ctx floor over over_hard
  n=$(gate_shift_number)
  ctx=$(gate_router_context)
  floor=$(gate_shift_floor)
  over=false
  [ "${ctx:-0}" -ge "$SHIFT_SOFT_TOKENS" ] && over=true
  over_hard=false
  [ "${ctx:-0}" -ge "$SHIFT_HARD_TOKENS" ] && over_hard=true
  printf '{"n": %s, "context": %s, "soft": %s, "hard": %s, "over_soft": %s, "over_hard": %s, "floor": %s}' \
    "${n:-0}" "${ctx:-0}" "$SHIFT_SOFT_TOKENS" "$SHIFT_HARD_TOKENS" "$over" "$over_hard" "${floor:-0}"
}

gate_cap_directive() {
  # gate_cap_directive <verb> <kind> — ends the calling SHIFT when its context
  # has reached the hard cap, by exiting `GATE_EXIT_CAP`, and refuses the
  # calling SEAT's act when its context has reached `SEAT_HARD_TOKENS`, by
  # exiting `GATE_EXIT_RULE`. Returns 0 when the caller may go on. Spelled once
  # and called from every arm that enforces it.
  #
  # IT RUNS BEFORE ANY ROW IS WRITTEN. The cap is a routing instruction and not
  # a refusal, and a refusal leaves no row in this ledger — so the signal has to
  # come back before the undeclared-target registration, the rule catalog, the
  # approval issuance and the row append, all of which can write.
  #
  # TWO CALLERS ARE CAPPED, EACH BY ITS OWN ARM AND ITS OWN CODE. A stage runs
  # under its own process and its own budget and is not capped here at all. A
  # shift is told to END (15): its successor takes over and nothing it asked
  # for was wrong. A seat — a caller that is neither a stage nor a shift — is
  # REFUSED (3): it cannot end itself, so what it is told is to pick the one act
  # that moves the work off it, `router-shift`.
  #
  # BOOKKEEPING KINDS ARE EXEMPT BY CALLING THE SET, NOT BY COPYING IT. The one
  # thing a capped shift must still be able to do is write
  # `act --kind handoff … 사유=상한`, and that act comes back through here. A
  # second copy of that set is how a terminal shift once failed to write the one
  # row the protocol requires of it.
  #
  # AN UNRESOLVED CONTEXT DOES NOT FIRE, it only says so. A shift whose own
  # transcript cannot be found has no honest number, and the only numbers within
  # reach belong to other sessions; a cap that fires on one of those ends the
  # night at the first act of every shift in turn. No row is written for it
  # either — a line on stderr is what a morning reader gets, and a refusal that
  # grew a row would be indistinguishable from an act that happened.
  local verb="$1" kind="${2:-}" n ctx
  n=$(gate_shift_self_ordinal)
  if [ -z "$n" ]; then
    # THE SEAT ARM. A caller carrying `CC_PIPELINE_SHIFT_ID` that did not parse
    # to an ordinal is not a seat, and a stage is never one.
    cc_caller_is_stage && return 0
    [ -z "${CC_PIPELINE_SHIFT_ID:-}" ] || return 0
    # It stands on act, exec and plan only. A seat does not `wait` on a stage;
    # it waits for its synchronous `router-shift` call to come back, and the
    # argument for capping `wait` is about a shift blocked on a long stage.
    [ "$verb" != "wait" ] || return 0
    # The exemption is the bookkeeping set, CALLED, plus `router-shift`, which
    # is not in that set and dispatches from its own arm. Refusing
    # `router-shift` would leave a capped seat no way to hand over at all. Its
    # argv is not inspected: the first token after `--` is a handoff reason,
    # not a command, and grading it would add a refusal path to the one call a
    # seat must always be able to make.
    gate_kind_is_bookkeeping "$kind" && return 0
    [ "$kind" != "router-shift" ] || return 0
    # THE CAP BINDS ONLY THE RUN ACTS THAT PASS THROUGH THIS GATE, and no other
    # property of the session. It does not make the seat's context smaller; it
    # stops the seat from growing it by doing the shift's work.
    ctx=$(gate_router_context)
    case "${ctx:-}" in ''|*[!0-9]*) return 0 ;; esac
    [ "$ctx" -ge "$SEAT_HARD_TOKENS" ] || return 0
    printf 'gate: 좌석의 컨텍스트가 %s 토큰으로 좌석 상한 %s 에 닿아 이 행위를 거절합니다 — `act --kind router-shift` 로 교대를 내어 라우팅을 넘기십시오 (%s)\n' \
      "$ctx" "$SEAT_HARD_TOKENS" "$verb" >&2
    exit "$GATE_EXIT_RULE"
  fi
  gate_kind_is_bookkeeping "$kind" && return 0
  ctx=$(gate_shift_context_of "$n")
  case "${ctx:-}" in
    ''|*[!0-9]*)
      printf 'gate: 교대 %s 의 트랜스크립트를 해소하지 못해(또는 점수 매길 사용량 줄이 없어) 하드 상한을 평가하지 않았습니다 (%s)\n' \
        "$n" "$verb" >&2
      return 0 ;;
  esac
  [ "$ctx" -ge "$SHIFT_HARD_TOKENS" ] || return 0
  printf 'gate: 교대 %s 의 컨텍스트가 %s 토큰으로 하드 상한 %s 에 닿았습니다 — `act --kind handoff` 를 `사유=상한` 으로 쓰고 이 교대를 끝내십시오 (%s)\n' \
    "$n" "$ctx" "$SHIFT_HARD_TOKENS" "$verb" >&2
  exit "$GATE_EXIT_CAP"
}

gate_snapshot_segments_json() {
  # `머지 대기` is the part of `선행 ∪ 머지 순서` that has not landed — what
  # the merge-order check would hold this segment's merge on right now.
  local out sid
  out=$( gate_segment_ids | while IFS= read -r sid; do
           [ -n "$sid" ] || continue
           mo=$(gate_segment_field "$sid" '머지 순서')
           mw=""
           for d in $(gate_chain_deps_of "$sid"); do
             gate_segment_ever_landed "$d" || mw="$mw $d"
           done
           # THE REMOTE STATE, from the last `원격 판독` row and the live HEAD,
           # and the review prompt — what a shift needs to push, open a pull
           # request or dispatch the review without spelling any of it. The
           # snapshot reads no remote; `remote-check` writes the row it reads.
           sbr=$(gate_segment_branch "$sid")
           shead=$(gate_worktree_tip "$(gate_segment_worktree "$sid" 2>/dev/null || true)" 2>/dev/null || true)
           srr=$(gate_remote_last_row "$sid")
           srl=""
           [ -z "$sbr" ] || srl=$(gate_review_line "$sid" 2>/dev/null || true)
           # `적용` is the apply state the apply act's preconditions read, so
           # the router and the gate cannot disagree on whether a merge is the
           # segment's end. `착지` is the dispatch floor's own answer for a
           # predecessor (`gate_segment_landed_now`), so the router plans a
           # dependent on the judgment the floor will apply to it.
           # `강제 표면` and `좌석 적용 커밋` are what a shift copies into the
           # implement dispatch line, spelled as the driver spells its own.
           sland=false
           gate_segment_landed_now "$sid" && sland=true
           printf '    {"id": "%s", "상태": "%s", "적용": "%s", "착지": %s, "워크트리": "%s", "선행": "%s", "머지 순서": "%s", "머지 대기": %s, "커밋": "%s", "마지막 스테이지": "%s", "브랜치": %s, "HEAD": %s, "원격 팁": %s, "PR": {"번호": %s, "상태": %s, "HEAD": %s}, "원격 단계": "%s", "리뷰 줄": %s, "강제 표면": "%s", "좌석 적용 커밋": "%s"},\n' \
             "$(gate_json_escape "$sid")" \
             "$(gate_json_escape "$(gate_segment_field "$sid" '상태')")" \
             "$(gate_json_escape "$(gate_segment_apply_state "" "$sid")")" \
             "$sland" \
             "$(gate_json_escape "$(gate_segment_field "$sid" '워크트리')")" \
             "$(gate_json_escape "$(gate_segment_field "$sid" '선행')")" \
             "$(gate_json_escape "${mo:-없음}")" \
             "$(gate_json_id_array $mw)" \
             "$(gate_json_escape "$(gate_segment_field "$sid" '커밋')")" \
             "$(gate_json_escape "$(gate_row_field "$( { gate_rows 'stage-result' | grep -F "세그먼트=$sid " || true; } | tail -1)" '스테이지')")" \
             "$(gate_json_str_or_null "$sbr")" "$(gate_json_str_or_null "$shead")" \
             "$(gate_json_str_or_null "$(gate_row_field "$srr" '원격 팁')")" \
             "$(gate_json_str_or_null "$(gate_row_field "$srr" 'PR')")" \
             "$(gate_json_str_or_null "$(gate_row_field "$srr" 'PR 상태')")" \
             "$(gate_json_str_or_null "$(gate_row_field "$srr" 'PR HEAD')")" \
             "$(gate_json_escape "$(gate_remote_stage "$sid")")" \
             "$(gate_json_str_or_null "$srl")" \
             "$(gate_json_escape "$(gate_segment_surface_paths "$sid")")" \
             "$(gate_json_escape "$(gate_segment_seat_commits "$sid")")"
         done )
  [ -n "$out" ] || return 0
  printf '%s\n' "${out%,}"
}

gate_snapshot_blocked_json() {
  # Unresolved only, AND THE FOLD THAT DECIDES IT IS THE CANONICAL ONE. Resolution
  # in this ledger is an APPEND, not an edit: the closing row carries `원인=해소`
  # and the row it closes stays exactly where it is. Filtering the closing row out
  # therefore kept the block and dropped the evidence that it was gone — the
  # opposite of what this comment used to promise — and the successor has no
  # history to notice with, so a block somebody had already cleared sat in every
  # shard's input for the rest of the night.
  #
  # `cc_unresolved_blocked` takes the LAST row per `사유` and drops it when that
  # row resolves. Termination condition 5 and the status line already read it,
  # and its own header says it exists so those two read one rule rather than two
  # copies of it; this projector was a third copy and the only wrong one.
  #
  # The span is the canonical fold's — run-scope rows and cone rows anchored on
  # a design step — and the scope and anchor are those of the row the fold kept,
  # read from the fold itself. Narrowing here is deliberate — a fourth private
  # copy of the fold is precisely the defect.
  local out reason scope anchor
  out=$( { cc_unresolved_blocked_where "${LEDGER:-}" || true; } \
         | tail -40 | while IFS="$(printf '\t')" read -r reason scope anchor; do
           [ -n "$reason" ] || continue
           printf '    {"스코프": "%s", "사유": "%s", "앵커": "%s"},\n' \
             "$(gate_json_escape "$scope")" \
             "$(gate_json_escape "$reason")" \
             "$(gate_json_escape "$anchor")"
         done )
  [ -n "$out" ] || return 0
  printf '%s\n' "${out%,}"
}

gate_snapshot_cycles_json() {
  local out row
  out=$( { gate_rows 'cycle' || true; } | tail -20 | while IFS= read -r row; do
           [ -n "$row" ] || continue
           # `모드`, `리뷰 HEAD` and `리포트 경로` are what the router needs to
           # pick a delta basis without opening the ledger; an absent `모드`
           # is emitted as the empty string and the reader takes it as 전체.
           # `기각` is "1" when a person dismissed that cycle's findings.
           cdis=''
           cs=$(gate_row_field "$row" '세그먼트'); cc=$(gate_row_field "$row" '사이클')
           ch=$(gate_row_field "$row" '리뷰 HEAD')
           gate_cycle_dismissed "$cs" "$cc" "$ch" && cdis=1
           printf '    {"세그먼트": "%s", "사이클": "%s", "P0": "%s", "P1": "%s", "모드": "%s", "리뷰 HEAD": "%s", "리포트 경로": "%s", "기각": "%s"},\n' \
             "$(gate_json_escape "$cs")" \
             "$(gate_json_escape "$cc")" \
             "$(gate_json_escape "$(gate_row_field "$row" 'P0')")" \
             "$(gate_json_escape "$(gate_row_field "$row" 'P1')")" \
             "$(gate_json_escape "$(gate_row_field "$row" '모드')")" \
             "$(gate_json_escape "$ch")" \
             "$(gate_json_escape "$(gate_row_field "$row" '리포트 경로')")" \
             "$cdis"
         done )
  [ -n "$out" ] || return 0
  printf '%s\n' "${out%,}"
}

gate_snapshot_ci_keys_json() {
  # gate_snapshot_ci_keys_json <segment> — the keys a CI value adds to its
  # `review_next[]` element: what `CI 수정: <sha>` names, the PR and the failing
  # checks a person reads at a park, and the round and base evidence the value
  # was decided on. The same ledger reads `gate_ci_next` makes. At
  # `CI 대기 한도` <nx> it also carries the round's `상태` (`관측 없음` when no
  # verdict came) and its `대기 시계`, which the park's evidence quotes.
  local s=$1 nx=${2:-} h rd g v st
  h=$(gate_segment_tip "$s" || true)
  rd=$(cc_ci_round "$LEDGER" "$s" "$h")
  g=$(cc_ci_round_get "$rd" g)
  v=$(gate_ci_verdict_row "$s" "$h" "${g:-0}")
  printf ', "head sha": "%s", "PR": "%s", "실패 체크": "%s", "재실행 회차": "%s", "기본 브랜치": "%s"' \
    "$(gate_json_escape "$h")" \
    "$(gate_json_escape "$(gate_row_field "$v" 'PR')")" \
    "$(gate_json_escape "$(gate_row_field "$v" '실패 체크')")" \
    "$(gate_json_escape "${g:-0}")" \
    "$(gate_json_escape "$(cc_ci_round_get "$rd" base)")"
  if [ "$nx" = 'CI 대기 한도' ]; then
    st=$(gate_row_field "$v" '상태')
    printf ', "상태": "%s", "대기 시계": "%s"' \
      "$(gate_json_escape "${st:-관측 없음}")" \
      "$(gate_json_escape "$(gate_ci_wait_clock "$s" "$h" "${g:-0}")")"
  fi
  if [ "$nx" = 'CI 대조' ] || [ "$nx" = 'master 대기' ] || [ "$nx" = 'master 재합류' ] \
     || [ "$nx" = 'master 수리 불가' ]; then
    gate_snapshot_master_keys_json "$s" "$h" "${g:-0}" "$nx"
  fi
}

gate_snapshot_master_keys_json() {
  # gate_snapshot_master_keys_json <segment> <head sha> <round> <nx> — what the
  # four values that compare with the base branch add: the events the match
  # row waits on (`-` before a match), the reading's state and when it was
  # observed. `master 수리 불가` also carries what the person is asked about —
  # each waited event's first commit, a summary of its signatures (the first
  # three lines of the kept list and their count) and the repair reasons.
  local s=$1 h=$2 g=$3 nx=$4 al mrow m ev e fcs="" sum="" f n
  al=$(gate_segment_target_alias "$s")
  mrow=$(gate_master_last_row "$al")
  m=$(gate_ci_match_row "$s" "$h" "$g")
  ev=$(gate_row_field "$m" '사건')
  printf ', "사건": "%s", "master 상태": "%s", "판독 관측": "%s"' \
    "$(gate_json_escape "${ev:--}")" \
    "$(gate_json_escape "$(gate_row_field "$mrow" '상태')")" \
    "$(gate_json_escape "$(gate_row_field "$mrow" '관측')")"
  [ "$nx" = 'master 수리 불가' ] || return 0
  for e in $(printf '%s' "$ev" | tr ',' ' '); do
    [ "$e" != '-' ] || continue
    fcs="${fcs:+$fcs, }$e $(gate_row_field "$mrow" '사건' | tr ',' '\n' | awk -F':' -v id="$e" '$1 == id { print $2; exit }')"
    f=$(gate_ci_signature_file "event-$e")
    if [ -f "$f" ]; then
      n=$(gate_count < "$f")
      sum="${sum:+$sum; }$e ${n}개: $(head -3 "$f" | paste -sd ',' -)"
    fi
  done
  printf ', "처음 커밋": "%s", "서명 요약": "%s", "수리 사유": "%s"' \
    "$(gate_json_escape "${fcs:--}")" \
    "$(gate_json_escape "${sum:--}")" \
    "$(gate_json_escape "$(gate_row_field "$mrow" '수리 사유')")"
}

gate_snapshot_ci_early_json() {
  # One element per unmerged segment where `gate_ci_early` holds: `세그먼트`,
  # `head sha`, and the `PR` and `실패 체크` of round 0's verdict.
  local out s h v
  out=$(gate_segment_ids | while IFS= read -r s; do
          [ -n "$s" ] || continue
          gate_ci_early "$s" || continue
          h=$(gate_segment_tip "$s" || true)
          v=$(gate_ci_verdict_row "$s" "$h" 0)
          printf '    {"세그먼트": "%s", "head sha": "%s", "PR": "%s", "실패 체크": "%s"},\n' \
            "$(gate_json_escape "$s")" "$(gate_json_escape "$h")" \
            "$(gate_json_escape "$(gate_row_field "$v" 'PR')")" \
            "$(gate_json_escape "$(gate_row_field "$v" '실패 체크')")"
        done )
  [ -n "$out" ] || return 0
  printf '%s\n' "${out%,}"
}

gate_snapshot_review_next_json() {
  # One element per segment that has a `cycle` row and has not merged:
  # `다음` and the last cycle's `사이클`, `리뷰 HEAD` and `리포트 경로` — what a
  # carry-over act names, and at `리드 수정` and `확인 리뷰` the cap report the
  # lead fix and the re-check name. A segment with no cycle row is left out:
  # its `다음` is `리뷰 없음` by definition.
  #
  # At the three base values the element also carries what the resolution and
  # its review name: the basis cycle and its `리뷰 HEAD` (the segment's last
  # cycle that is not a resolution), and the base, the conflicted files and
  # the class of the latest `베이스 판정` row. At the thirteen CI values —
  # `CI 재실행`, `CI 대기`, `CI 대기 한도`, `CI 수정`, `CI 합류 수정`, `CI 리뷰`,
  # `CI 기존 실패`, `CI 수정 한도`, `CI 라벨 인정`, `CI 대조`, `master 대기`,
  # `master 재합류`, `master 수리 불가` — it carries the keys
  # `gate_snapshot_ci_keys_json` names.
  local out s row nx brow bcy
  out=$(gate_segment_ids | while IFS= read -r s; do
          [ -n "$s" ] || continue
          [ "$(gate_segment_field "$s" '상태')" = "머지됨" ] && continue
          row=$(gate_segment_last_cycle_row "$s")
          [ -n "$row" ] || continue
          nx=$(gate_segment_review_next "$s")
          printf '    {"세그먼트": "%s", "다음": "%s", "사이클": "%s", "리뷰 HEAD": "%s", "리포트 경로": "%s"' \
            "$(gate_json_escape "$s")" "$(gate_json_escape "$nx")" \
            "$(gate_json_escape "$(gate_row_field "$row" '사이클')")" \
            "$(gate_json_escape "$(gate_row_field "$row" '리뷰 HEAD')")" \
            "$(gate_json_escape "$(gate_report_abs "$(gate_row_field "$row" '리포트 경로')")")"
          # An if, not a case: this runs inside `$( … )`, and bash 3.2 closes the
          # substitution at a case pattern's `)`.
          if [ "$nx" = '베이스 해소' ] || [ "$nx" = '해소 리뷰' ] || [ "$nx" = '베이스 해소 한도' ]; then
              bcy=$(gate_base_resolve_basis_row "$s")
              brow=$(gate_base_last_row "$s")
              printf ', "기준 사이클": "%s", "기준 리뷰 HEAD": "%s", "베이스": "%s", "충돌 파일": "%s", "부류": "%s"' \
                "$(gate_json_escape "$(gate_row_field "$bcy" '사이클')")" \
                "$(gate_json_escape "$(gate_row_field "$bcy" '리뷰 HEAD')")" \
                "$(gate_json_escape "$(gate_row_field "$brow" '베이스')")" \
                "$(gate_json_escape "$(gate_row_field "$brow" '충돌 파일')")" \
                "$(gate_json_escape "$(gate_row_field "$brow" '부류')")"
          fi
          if [ "$nx" = 'CI 재실행' ] || [ "$nx" = 'CI 대기' ] || [ "$nx" = 'CI 수정' ] \
             || [ "$nx" = 'CI 리뷰' ] || [ "$nx" = 'CI 기존 실패' ] || [ "$nx" = 'CI 수정 한도' ] \
             || [ "$nx" = 'CI 합류 수정' ] || [ "$nx" = 'CI 대기 한도' ] \
             || [ "$nx" = 'CI 라벨 인정' ] \
             || [ "$nx" = 'CI 대조' ] || [ "$nx" = 'master 대기' ] || [ "$nx" = 'master 재합류' ] \
             || [ "$nx" = 'master 수리 불가' ]; then
              gate_snapshot_ci_keys_json "$s" "$nx"
          fi
          printf '},\n'
        done )
  [ -n "$out" ] || return 0
  printf '%s\n' "${out%,}"
}

gate_segment_ahead_count() {
  # gate_segment_ahead_count <segment> — how many commits the segment
  # worktree's HEAD carries that neither `refs/heads/<base>` nor
  # `refs/remotes/origin/<base>` reaches, counting against every one of the two
  # that resolves: a local base left behind the remote would otherwise read the
  # difference as the segment's own work. The base is the `베이스 브랜치` of the
  # target the segment row's `레포` names (the slice's, then the home target's,
  # when the row names none). Prints an integer, or `미상` when the worktree is
  # gone, no base ref resolves or the count fails.
  local seg=$1 wt slug al br rn rems refs='' r n
  wt=$(gate_segment_worktree "$seg")
  [ -n "$wt" ] && [ -d "$wt" ] || { printf '미상'; return 0; }
  slug=$(gate_segment_field "$seg" '레포' | tr -d '`')
  al=''
  [ -z "$slug" ] || al=$(alias_for_slug "$slug" 2>/dev/null) || al=''
  [ -n "$al" ] || al=$(gate_slice_alias "$seg" 2>/dev/null) || al=''
  [ -n "$al" ] || al=$(home_alias 2>/dev/null) || al=''
  br=''
  [ -z "$al" ] || br=$(base_branch "$al" 2>/dev/null) || br=''
  [ -n "$br" ] || { printf '미상'; return 0; }
  # A leading remote name the worktree knows is stripped, as
  # `gate_push_base_branch` strips it.
  case "$br" in
    */*)
      rn=${br%%/*}
      rems=$( { cd "$wt" 2>/dev/null && git remote 2>/dev/null; } || true)
      case "
$rems
" in
        *"
$rn
"*) br=${br#*/} ;;
      esac ;;
  esac
  for r in "refs/heads/$br" "refs/remotes/origin/$br"; do
    if ( cd "$wt" 2>/dev/null && git rev-parse --verify -q "$r^{commit}" ) >/dev/null 2>&1; then
      refs="$refs $r"
    fi
  done
  [ -n "$refs" ] || { printf '미상'; return 0; }
  # shellcheck disable=SC2086
  n=$( { cd "$wt" 2>/dev/null && git rev-list --count HEAD --not $refs 2>/dev/null; } || true)
  case "$n" in
    ''|*[!0-9]*) printf '미상' ;;
    *) printf '%s' "$n" ;;
  esac
}

gate_implement_next_of() {
  # gate_implement_next_of <segment> — the `implement_next[]` element of one
  # segment, or nothing when its last `stage-result` row is not an implement
  # stage that ended `정상 완료`. A digest is a plan EMISSION the first time it
  # appears after the void boundary — the last `종류=reconverge` row or `재계획`
  # row, the boundary `implement_process_b` resets on — and a plan EXECUTION
  # when it repeats: process B carries process A's digest. `무커밋 구현` counts
  # the `정상 완료` implement rows after the boundary that left no commit: every
  # one of them when the branch is not ahead of its base, only the emissions
  # when it is.
  local seg=$1 rows last res ahead st cnt_all cnt_emit dg cnt nx
  rows=$(gate_plan_rows_of "$seg")
  last=$( { printf '%s\n' "$rows" | grep '^- `stage-result` ' || true; } | tail -1)
  [ -n "$last" ] || return 0
  [ "$(gate_row_field "$last" '종류')" = 'implement' ] || return 0
  [ "$(gate_row_field "$last" '종단 부류')" = '정상 완료' ] || return 0
  # One awk over the rows, `index` and field splits rather than a regex over
  # Korean names. It consumes its whole input (no `exit`): an early-exiting
  # reader kills the writer with SIGPIPE, and under `pipefail` the pipeline
  # then fails though the answer was found.
  res=$(printf '%s\n' "$rows" | LC_ALL=C awk '
  function fld(line, key,   n, i, a) {
    n = split(line, a, " [|] ")
    for (i = 1; i <= n; i++) if (index(a[i], key "=") == 1) return substr(a[i], length(key) + 2)
    return ""
  }
  index($0, "- `재계획`") == 1 { split("", seen); all = 0; emit = 0; next }
  index($0, "- `stage-result`") == 1 {
    k = fld($0, "종류")
    if (k == "reconverge") { split("", seen); all = 0; emit = 0; next }
    if (k != "implement") next
    d = fld($0, "plan_sha256")
    first = (d != "" && !(d in seen))
    if (d != "") seen[d] = 1
    if (fld($0, "종단 부류") == "정상 완료") { all++; if (first) emit++ }
    ph = (d == "") ? "미상" : (first ? "A" : "B")
    ld = d
  }
  END { printf "%s %d %d %s\n", (ph == "" ? "미상" : ph), all, emit, (ld == "" ? "-" : ld) }')
  read -r st cnt_all cnt_emit dg <<<"$res"
  [ "$dg" = '-' ] && dg=''
  ahead=$(gate_segment_ahead_count "$seg")
  if [ "$ahead" = '0' ]; then cnt=$cnt_all; else cnt=$cnt_emit; fi
  if [ "$ahead" = '미상' ]; then nx='판정 불가'
  elif [ "$st" = 'A' ] || [ "$ahead" = '0' ]; then
    if [ "$cnt" -le 2 ]; then nx='구현'; else nx='사람'; fi
  else nx='리뷰'
  fi
  if [ "$ahead" = '미상' ]; then ahead='"미상"'; fi
  printf '    {"세그먼트": "%s", "다음": "%s", "단계": "%s", "plan_sha256": "%s", "앞선 커밋": %s, "무커밋 구현": %s},\n' \
    "$(gate_json_escape "$seg")" "$nx" "$st" "$(gate_json_escape "$dg")" "$ahead" "$cnt"
}

gate_snapshot_implement_next_json() {
  # One element per segment that is not `머지됨`, `완료` or `park` and whose
  # last `stage-result` row is an implement stage that ended `정상 완료`
  # (`gate_implement_next_of`). A segment whose last stage was a review, a
  # crash or a park has no element: the rules that already read those decide it.
  local out s sst
  out=$(gate_segment_ids | while IFS= read -r s; do
          [ -n "$s" ] || continue
          sst=$(gate_segment_field "$s" '상태')
          if [ "$sst" = '머지됨' ] || [ "$sst" = '완료' ] || [ "$sst" = 'park' ]; then continue; fi
          gate_implement_next_of "$s"
        done )
  [ -n "$out" ] || return 0
  printf '%s\n' "${out%,}"
}

# THE STALL LABELS, computed by `stall-class.awk` from the whole ledger and
# nothing else. ONE AWK PROCESS on the success path, whatever the ledger's size:
# every `snapshot` call — `--fields H` included, because the projection renders
# the whole object first — pays for this, so the root is taken by parameter
# expansion rather than by `dirname` or `gate_report_abs`. That is the same
# string, byte for byte: the entry normalization makes `MANIFEST` a LOGICAL
# absolute path with no `.` or `..` in it, so stripping two components off its
# directory is exactly what the relative arm of `gate_report_abs` gets by letting
# a logical `cd` fold the two `..`.
#
# FAILURE IS OPEN AND VISIBLE. A classifier that fails leaves `"stalls": []` and
# one warning line, never a failed snapshot: the output is taken into a variable
# and printed only after the awk has exited 0, because an awk that printed one
# entry and then died would otherwise leave half a JSON object inside a snapshot
# that `--fields H` parses whole. No bash arithmetic touches these values, and
# nothing in the body leaves the function any way but normally. The awk's own
# stderr is dropped so that the failure is the one line below and not two.
gate_snapshot_stalls_json() {
  local mdir root st
  mdir=${MANIFEST%/*}
  root=${mdir%/*}
  root=${root%/*}
  st=$(LC_ALL=C awk -v mode=last -v root="$root" -f "$GATE_DIR/stall-class.awk" "$LEDGER" 2>/dev/null) \
    || { warn "정체 라벨 계산 실패 — stalls 를 비웠습니다: $GATE_DIR/stall-class.awk"; st=''; }
  if [ -n "$st" ]; then
    printf '%s\n' "$st"
  fi
}

gate_snapshot_handoff_json() {
  # The last `SHIFT_HANDOFF_CAP` handoffs and no more. The whole series would
  # grow without bound across a night, and an unbounded resume payload spends on
  # the successor's first turn exactly what the shift exists to save.
  #
  # `사유` AND `기록 시각` ARE WHAT MAKE AN ENTRY READABLE AS A PAST OBSERVATION.
  # Without them a successor cannot tell how old a wall is, and repeats a wait a
  # predecessor recorded hours ago as if it had just been measured; nor can it
  # tell the gate's `사유=무기록` entry — a fact that a shift ended, carrying no
  # judgment — from a shift's own handoff.
  #
  # `무기록` ROWS DO NOT COUNT AGAINST THE CAP. A run of shifts that die on their
  # first request — a usage limit that has not cleared, a crash loop — each leaves
  # one, and counting them would push the last real handoff, the only entry with a
  # `버린 선택지` or a measured `막힌 지점`, out of every prescribed read after
  # three of them. The window is the last `SHIFT_HANDOFF_CAP` real handoffs, plus
  # the series' final row when that row is `무기록`: the successor still learns
  # that its predecessor ended without a word, and the payload stays bounded at
  # one entry over the cap however long the run of them is.
  local out row all last tr_v
  all=$( { gate_rows 'handoff' || true; } )
  last=$(printf '%s\n' "$all" | tail -1)
  [ "$(gate_row_field "$last" '사유')" = '무기록' ] || last=''
  out=$( { printf '%s\n' "$all" | while IFS= read -r row; do
             [ -n "$row" ] || continue
             [ "$(gate_row_field "$row" '사유')" = '무기록' ] || printf '%s\n' "$row"
           done | tail -"$SHIFT_HANDOFF_CAP"
           [ -z "$last" ] || printf '%s\n' "$last"
         } | while IFS= read -r row; do
           [ -n "$row" ] || continue
           # `일시 원인` is the gate's own field on a `무기록` row and `-` on every
           # other: the seat relaunches on it without reading the stream.
           tr_v=$(gate_row_field "$row" '일시 원인')
           printf '    {"교대": "%s", "사유": "%s", "버린 선택지": "%s", "막힌 지점": "%s", "다음 후보": "%s", "기록 시각": "%s", "일시 원인": "%s"},\n' \
             "$(gate_json_escape "$(gate_row_field "$row" '교대')")" \
             "$(gate_json_escape "$(gate_row_field "$row" '사유')")" \
             "$(gate_json_escape "$(gate_row_field "$row" '버린 선택지')")" \
             "$(gate_json_escape "$(gate_row_field "$row" '막힌 지점')")" \
             "$(gate_json_escape "$(gate_row_field "$row" '다음 후보')")" \
             "$(gate_json_escape "$(gate_row_field "$row" '기록 시각')")" \
             "$(gate_json_escape "${tr_v:--}")"
         done )
  [ -n "$out" ] || return 0
  printf '%s\n' "${out%,}"
}

gate_shift_trace_unrecorded() {
  # gate_shift_trace_unrecorded <alias> <ordinal> <rc> — after a shift has been
  # reaped, write the `handoff` row it did not write itself: `사유=무기록`.
  #
  # A SHIFT THAT ENDS WITHOUT A HANDOFF USED TO LEAVE ONE `log` LINE AND NO ROW.
  # The successor then read the predecessor's last handoff as the latest word,
  # and the morning reader could not tell a shift that did nothing from one that
  # never ran. The gate is the one process still alive at that moment, so the
  # trace is its to write; `무기록` is a value of its own so that it is never
  # read as the `중단` a shift chose, and the handoff arm already refuses it on
  # argv.
  #
  # WHETHER THE SHIFT WROTE ONE IS READ FROM THE APPROVAL ROW, NOT THE HANDOFF
  # ROW. The approval row's `교대` and `행위자` come from the environment the gate
  # gave the shift, so argv cannot forge them; the handoff row's own `교대=` is
  # whatever its caller passed. A bookkeeping act writes its row before its
  # approval row, so a refused handoff leaves no approval row and counts as none.
  #
  # `행위 수` FILTERS ON `행위자=교대`. A stage the shift launched carries the same
  # `교대=<n>` on its rows, and counting those would credit the shift with work
  # it did not do. A snapshot call writes no row, so `0` means "no gate act",
  # not "no request".
  #
  # `막힌 지점` IS DESCRIPTIVE AND FIXED. The feed carries this field to the lead,
  # where an imperative would read as an instruction; and a fixed sentence keeps
  # the row near a known length. It still goes through the projection, because a
  # row over the cap is a `die` and not a truncation.
  # Counted rather than tested with `grep -q`: under `pipefail` an early-exiting
  # reader can leave its writer on SIGPIPE, and the pipeline would then answer
  # "no handoff" for a shift that wrote one.
  local alias="$1" n="$2" rc="$3" mine own acts why at
  mine=$( { gate_rows '자율 승인' || true; } | grep -F "| 교대=$n |" \
            | grep -F '| 행위자=교대 |' || true)
  own=$(printf '%s\n' "$mine" | grep -cF "| 교대=$n | kind=handoff |" || true)
  case "${own:-}" in ''|*[!0-9]*) own=0 ;; esac
  [ "$own" -eq 0 ] || return 0
  acts=$(printf '%s\n' "$mine" | grep -c . || true)
  case "${acts:-}" in ''|*[!0-9]*) acts=0 ;; esac
  why="교대 ${n} 이 인계 행 없이 끝났다 — 종료 코드 ${rc}, 게이트 행위 ${acts}회"
  if [ "$rc" != "0" ] && stage_limit_exit "$RUN_DIR/log/shift-$n.json" >/dev/null 2>&1; then
    why="${why}; 교대 자신의 스트림이 한도 종료 형상이다"
  fi
  # `일시 원인` — whether the lost shift's own stream ended on a dropped
  # connection, by the driver's one reader. The launcher reads this field to
  # decide on its probe, and the seat reads it on the snapshot's `handoff[]`;
  # neither re-reads the stream.
  local transient='아니오'
  if stage_transient_exit "$RUN_DIR/log/shift-$n.json"; then transient='예'; fi
  at=$(now_iso)
  if [ "$(gate_row_projected_bytes 'handoff' "교대=$n" "사유=무기록" "버린 선택지=-" \
          "막힌 지점=$why" "다음 후보=-" "대상=$alias" "기록 시각=$at" \
          "종료 코드=$rc" "행위 수=$acts" "일시 원인=$transient")" -gt "$GATE_ROW_MAX" ]; then
    why='-'
  fi
  gate_append 'handoff' "교대=$n" "사유=무기록" "버린 선택지=-" \
    "막힌 지점=$why" "다음 후보=-" "대상=$alias" "기록 시각=$at" \
    "종료 코드=$rc" "행위 수=$acts" "일시 원인=$transient"
  log "교대 $n 무기록 — 게이트가 인계 행을 대신 남김 (rc=$rc, 행위 ${acts}회)"
}

gate_shift_launch_lock() {
  # gate_shift_launch_lock — the run's launch mutex, `$RUN_DIR/shift-launch.lock`.
  # ONE ATTEMPT, NO WAITING: a caller that loses is refused, because the winner
  # is about to hold the run for hours and queueing behind it buys nothing.
  #
  # IT COVERS MILLISECONDS, NOT THE SHIFT. Two launchers that both passed the
  # reason check used to count the same ordinal, write over the same
  # `log/shift-$n.json` and start two shifts on one ledger. The lock spans only
  # the check of the live records and the publication of this launcher's claim
  # in them — `relay.live` or `shift.live` — and the long exclusion after that is
  # those records' pid and fingerprint, which survive a reboot correctly where a
  # lock would not. So a dead owner, or an owner line older than sixty seconds,
  # is taken over: four orders of magnitude above the section it guards. The
  # takeover is a rename, so exactly one of two stealers wins it.
  local lock="$RUN_DIR/shift-launch.lock" owner opid ots now dead
  if mkdir "$lock" 2>/dev/null; then
    printf '%s %s\n' "$$" "$(date -u +%s)" > "$lock/owner" 2>/dev/null || true
    return 0
  fi
  owner=$(cat "$lock/owner" 2>/dev/null || true)
  opid=$(printf '%s' "$owner" | sed -n 's/^\([0-9][0-9]*\)[[:space:]][[:space:]]*[0-9][0-9]*$/\1/p')
  ots=$(printf '%s' "$owner" | sed -n 's/^[0-9][0-9]*[[:space:]][[:space:]]*\([0-9][0-9]*\)$/\1/p')
  [ -n "$ots" ] || ots=$(gate_mtime "$lock")
  [ -n "$ots" ] || return 1
  now=$(date -u +%s)
  if { [ -n "$opid" ] && ! cc_pid_exists "$opid"; } || [ $((now - ots)) -ge 60 ]; then
    dead="$lock.dead.$$.$now"
    mv "$lock" "$dead" 2>/dev/null || return 1
    rm -rf "$dead" 2>/dev/null || true
    mkdir "$lock" 2>/dev/null || return 1
    printf '%s %s\n' "$$" "$(date -u +%s)" > "$lock/owner" 2>/dev/null || true
    return 0
  fi
  return 1
}

gate_shift_launch_unlock() {
  # One rename, then the removal of the renamed directory — the release shape of
  # `gate_index_unlock`, so no owner-less lock is ever left in place.
  local lock="$RUN_DIR/shift-launch.lock" dead
  [ -d "$lock" ] || return 0
  dead="$lock.dead.$$.$(date -u +%s)"
  mv "$lock" "$dead" 2>/dev/null || { rm -rf "$lock" 2>/dev/null || true; return 0; }
  rm -rf "$dead" 2>/dev/null || true
  return 0
}

gate_shift_launch_claim() {
  # gate_shift_launch_claim <사유> — under the launch lock: refuse when another
  # launcher holds the run, else publish this one's claim before the lock is
  # released. Returns 0 with the claim published, 3 refused.
  #
  # ANOTHER LAUNCHER HOLDS THE RUN when a live relay is not this process, a live
  # shift exists, or `shift.live`'s launcher lines name a live process that is
  # not this one. THE CLAIM is `relay.live` for `대기` — the write the pre-launch
  # wait would make a moment later, moved inside the lock — and for every other
  # reason a `shift.live` whose four lines all name this gate; the launch
  # overwrites lines 1 and 2 with the successor's pid.
  local reason="$1" rpid lpid lfp me
  me="$$"
  gate_shift_launch_lock || {
    warn "another launcher holds this run — a live shift, relay or launch is in progress, so nothing is launched; do not re-issue the same call, follow the ledger and the watcher"
    return "$GATE_EXIT_RULE"; }
  rpid=$( { sed -n '1p' "$RUN_DIR/relay.live" 2>/dev/null || true; } | tr -d '[:space:]')
  lpid=$( { sed -n '3p' "$RUN_DIR/shift.live" 2>/dev/null || true; } | tr -d '[:space:]')
  lfp=$(sed -n '4p' "$RUN_DIR/shift.live" 2>/dev/null || true)
  if { cc_relay_is_live "$RUN_DIR" && [ "$rpid" != "$me" ]; } \
     || cc_shift_is_live "$RUN_DIR" \
     || { [ "$lpid" != "$me" ] && cc_holder_is_live "$lpid" "$lfp"; }; then
    gate_shift_launch_unlock
    warn "this run still has a live shift, relay or launcher — another launcher holds this run, so nothing is launched; do not re-issue the same call, follow the ledger and the watcher"
    return "$GATE_EXIT_RULE"
  fi
  if [ "$reason" = "대기" ]; then
    [ -n "$GATE_RELAY_STARTED" ] || GATE_RELAY_STARTED=$(date -u +%s)
    gate_relay_write "$(cc_relay_wait_stages "$RUN_DIR")" "$(gate_relay_ci_segments)" \
      "$(gate_relay_reset_set)"
  else
    [ -n "$GATE_RELAY_FP" ] || GATE_RELAY_FP=$(cc_proc_fingerprint "$me")
    printf '%s\n%s\n%s\n%s\n' "$me" "$GATE_RELAY_FP" "$me" "$GATE_RELAY_FP" \
      > "$RUN_DIR/shift.live" 2>/dev/null || true
  fi
  gate_shift_launch_unlock
  return 0
}

gate_seat_call_write() {
  # gate_seat_call_write <alias> <cutpoint> <surface> — `$RUN_DIR/seat-call`,
  # one `<key>=<value>` per line: `manifest`, `target`, `gate`, `cutpoint`,
  # `surface`. Written through a temp file in the same directory and a rename.
  local alias="$1" cp="$2" sf="$3" man="${MANIFEST:-}" t
  [ -n "$man" ] || return 0
  case "$man" in
    /*) : ;;
    *) man="$(cd "$(dirname "$man")" 2>/dev/null && pwd)/$(basename "$man")" ;;
  esac
  t="$RUN_DIR/seat-call.tmp.$$"
  {
    printf 'manifest=%s\n' "$man"
    printf 'target=%s\n' "$alias"
    printf 'gate=%s\n' "$GATE_DIR/gate.sh"
    printf 'cutpoint=%s\n' "$cp"
    printf 'surface=%s\n' "$sf"
  } > "$t" 2>/dev/null && mv -f "$t" "$RUN_DIR/seat-call" 2>/dev/null || {
    rm -f "$t" 2>/dev/null
    warn "could not write seat-call — a boot-time re-entry will not find how this seat calls"
  }
  return 0
}

gate_shift_launch_drop_claim() {
  # An early return after the claim and before the launch takes this launcher's
  # own `shift.live` down with it, so a launch that started nothing does not
  # hold the run until its process is gone. A `shift.live` that names another
  # process is not this launcher's, and stays.
  local p
  p=$( { sed -n '1p' "$RUN_DIR/shift.live" 2>/dev/null || true; } | tr -d '[:space:]')
  [ "$p" != "$$" ] || rm -f "$RUN_DIR/shift.live"
  return 0
}

gate_launch_shift() {
  # gate_launch_shift <alias> <사유> <cli args...>
  #
  # The successor routing session. It runs under the `shift` settings variant,
  # which is narrower than any stage's, and it is NOT recorded in
  # `session-lineage` — see the marker's own comment at the entry point.
  local alias="$1" reason="$2"; shift 2
  local wrapper="$GATE_DIR/stage-wrapper.sh"
  [ -f "$wrapper" ] || { warn "the stage wrapper is missing: $wrapper"; return 127; }
  [ -n "${CLI_BIN:-}" ] || { warn "the gate could not resolve the CLI binary"; return 127; }

  case "$reason" in
    상한|승인|종단|중단) : ;;
    대기) gate_relay_reentry_allowed || {
            warn "\`대기\` re-enters a wait only when the latest handoff is \`대기\` and no shift was launched after it"
            return "$GATE_EXIT_RULE"; }
          # A CLOSED RUN IS NOT WAITED ON AGAIN. The relay hands a closed run back
          # with the ledger still in the re-entry state above — nothing was
          # launched after the `대기` handoff — so without this refusal the seat's
          # re-issue would re-enter, see `done` on its first poll and hand back at
          # once, appending an act row to the closed run's ledger every turn.
          [ ! -e "$RUN_DIR/done" ] || {
            warn "\`대기\` does not re-enter a wait on a run that has ended — read the end from \`done\`"
            return "$GATE_EXIT_RULE"; } ;;
    *) warn "the handoff reason is out of vocabulary: ${reason:-(none)} — \`상한\` \`승인\` \`종단\` \`중단\` \`대기\`"
       return "$GATE_EXIT_VOCAB" ;;
  esac
  # ONE LAUNCHER PER RUN, between the reason check and the pre-launch wait. A
  # launch from inside the relay loop already holds the run and skips it.
  if [ -z "$GATE_RELAY_INNER" ]; then
    gate_shift_launch_claim "$reason" || return $?
  fi
  # The hand-back leaves `relay.live` in place: its `handback=` line is what the
  # watcher measures the next seat turn from, and a dead relay reads as dead.
  gate_relay_before_launch "$reason" || return 0

  # THE REMOTE STATE OF EVERY OPEN SEGMENT, read before the successor starts so
  # its first snapshot already says which segment needs a push, a pull request
  # or nothing — a shift that has to find that out by trying is a shift that
  # meets a target hook's refusal it could have read. A failed read is `미상`
  # and never holds the launch. A launch from inside the relay loop skips it:
  # the relay's wait and its reads only read the ledger and call no `gh`, so its
  # successor reads the rows the last read left, and a stale one reads `미상`.
  # The launch the loop calls appends the CI drain and the `교대 기동` row.
  if [ -z "$GATE_RELAY_INNER" ]; then
    gate_remote_state_refresh "$alias" || true
  fi

  # NO LIVE-STAGE SUPPRESSOR ANY MORE. It held a `상한` shift back while a stage
  # ran, on the stated premise that a live stage is the router's child and would
  # be orphaned by the session's end. The supervisor is detached from the routing
  # session now, so that premise is false — and a suppressor whose premise is
  # false is pure cost: it held the very condition the cap exists to end for as
  # long as a stage that no longer needed it ran. Its exit code (`10`, a
  # duplicate of `GATE_EXIT_ANCHOR`) went with it; a shift launch now has two
  # outcomes, the successor's rc or an approval (5).

  # THE LIVELOCK GUARD, AND IT IS THE ONE PLACE A CAP BECOMES AN APPROVAL.
  #
  # If the handoff floor grows with every shift the design inverts: simulated on
  # the measured trajectory, a floor fixed at 75K saves 64.9% over 28 shifts,
  # while one growing 8K per shift costs 1083% more than doing nothing and
  # livelocks at 2,613 shifts. Handing the whole ledger to the successor is the
  # most natural way to build exactly that shape.
  #
  # 130,000 IS CHOSEN AGAINST THRASHING, NOT AGAINST ECONOMICS. The break-even
  # moved 34% in a single round of re-derivation, and a guard hung on a number
  # that moves like that is a guard on nothing. At a 150K floor the shift count
  # goes 28 → 42 and turns per shift 151 → 96: handoff is already half the work,
  # well before break-even. 130,000 sits before that degradation shows, and the
  # derivation does not depend on the break-even assumption at all.
  #
  # AND THE RESPONSE IS AN APPROVAL RATHER THAN A SHIFT. A floor near a third of
  # the cap is not a state routing can fix, so neither trimming the floor nor
  # warning and continuing is right. THIS IS THE SOLE EXCEPTION TO "a session cap
  # is a routing instruction, not an approval" — written here because an
  # implementer following that rule would otherwise decline to raise one.
  # AND IT MEASURES THE OUTGOING SHIFT, NOT THE PROCESS DOING THE LAUNCHING.
  #
  # `gate_shift_floor` reads the transcript of the session RUNNING THIS CODE. When
  # the lead calls it that is the lead's opening context — a constant that does
  # not move all night, and not the growing quantity the paragraph above is about
  # at all. It failed in both directions: below the cap the guard never spoke, and
  # above it the FIRST launch of the night issued an approval and returned with no
  # successor, leaving the run without a routing seat.
  #
  # A SHIFT calling this IS the predecessor being replaced, so its own opening
  # context is the handoff floor that grows shift to shift. The lead is not
  # measured: a floor that does not exist yet cannot be compared, and a guard that
  # measures nothing beats one that measures the wrong process.
  local floor=0
  if [ -n "${CC_PIPELINE_SHIFT_ID:-}" ]; then
    floor=$(gate_shift_floor)
  fi
  if [ "${floor:-0}" -gt "$SHIFT_FLOOR_MAX" ]; then
    # Bound to the progress digest, as before this argument existed: the floor
    # itself grows shift to shift, and salting with it would mint one approval
    # per launch attempt for a single condition.
    gate_issue_boundary_approval SHIFT-FLOOR \
      "인수인계 바닥이 ${floor} 토큰으로 상한 ${SHIFT_FLOOR_MAX} 를 넘었습니다 — 교대가 일을 대신하고 있어 라우팅으로 풀리지 않습니다" \
      "$(gate_progress_digest)"
  fi
  # AUTO-RESOLVED, THE LAUNCH GOES AHEAD. Returning here would end the run's
  # routing with nobody left to start a successor, which is the stop the
  # auto-resolution exists to remove; the ledger keeps the issue and close rows.
  #
  # SO DOES AN ID ALREADY GRANTED FOR THIS SAME STATE. The issuer keeps an
  # answered id quiet while its binding has not moved, so on the launch after a
  # grant nothing is issued and nothing is auto-resolved either. Stopping then
  # answered the approval exit code with no approval pending — nothing for a
  # person to close, and no successor started. A refused or voided id is not a
  # "continue", so it still stops as before.
  local floor_granted=""
  if [ -n "${GATE_BOUNDARY_SUPPRESSED:-}" ] \
    && [ "$(gate_approval_state "$GATE_BOUNDARY_SUPPRESSED")" = "승인" ]; then
    floor_granted=1
  fi
  if [ "${floor:-0}" -gt "$SHIFT_FLOOR_MAX" ] && [ -z "${GATE_BOUNDARY_AUTO_RESOLVED:-}" ] \
    && [ -z "$floor_granted" ]; then
    warn "handoff stopped: the handover floor ${floor} > ${SHIFT_FLOOR_MAX} — an approval was issued"
    gate_shift_launch_drop_claim
    # AN ISSUED APPROVAL REPORTS AS ONE. Every other approval site in this file
    # answers `GATE_EXIT_APPROVAL`, and the conversion that does it for the rule
    # path runs before the dispatch that reaches here — so a `return 0` handed the
    # caller the code meaning "the successor ran to completion" for a call that
    # started nothing at all. The duplicate-suppressed re-issue answers 5 too: the
    # approval is open either way, and only the first call would otherwise say so.
    return "$GATE_EXIT_APPROVAL"
  fi

  # A SHIFT LOST TO A DROPPED CONNECTION IS RELAUNCHED ONCE THE CONNECTION
  # ANSWERS. When the last handoff is the gate's `무기록` row with
  # `일시 원인=예`, the launch waits and probes first, up to three times; the
  # verdict is read from that row and the stream is not matched again. The
  # probe sits here, inside the launcher, because the launcher is already
  # blocked in `wait` for a shift's whole life and the seat cannot poll — there
  # is no other place to wait for the connection to come back. It sits before
  # the instructions, the launch row and `shift.in-progress`, so its worst case
  # (210 seconds) does not eat the marker's 300-second window.
  #
  # BOTH REFUSALS WRITE NO `교대 기동` ROW. That row exists only for a shift
  # that started, and `gate_shift_launches` counts it into the next ordinal and
  # the `log/shift-<n>.json` name; a refusal is a warn line and exit 3, and the
  # seat waits for a person as it did before this path existed. Both drop the
  # launcher's claim like every other early return here, or the person's launch
  # that follows reads the run as held by another launcher. The bound is
  # three consecutive such launches: the trailing `교대 기동` rows that carry
  # `연결 확인=`, counted back from the end until one that does not.
  #
  # A PERSON'S TURN SKIPS BOTH. After a refusal the seat waits for a person and
  # issues the same launch again only on a person's word — a "continue", or the
  # launch that follows an answered stop record. The gate cannot hear that word,
  # so it reads the turn off the ledger: no `교대 기동` row after the last
  # handoff, and besides this act's own `자율 승인` row at least one more
  # `kind=router-shift` `결정=act` row after that handoff — an earlier attempt
  # that turned back having started nothing. Only `결정=act`: the launch that
  # wrote the handoff appends its own `결정=결과` row after it, and counting that
  # one made every first relaunch a person's turn. Why it turned back is not on
  # the row, and it does not matter: the seat re-issues only after a person
  # either way. Without
  # this, the refusals above were permanent — the bound is broken only by a
  # launch row without `연결 확인=` or a new handoff, and the bound refused the
  # launch that would write either. This launch's row carries no `연결 확인=`,
  # so it ends the streak; a shift it starts that dies the same way again meets
  # the probe and the bound from the start.
  local probe_note=""
  local lh after_lh human_turn=""
  lh=$( { gate_rows 'handoff' || true; } | tail -1)
  if [ "$(gate_row_field "$lh" '사유')" = '무기록' ] && [ "$(gate_row_field "$lh" '일시 원인')" = '예' ]; then
    after_lh=$(gate_ledger_rows_after "$lh")
    if [ "$(printf '%s\n' "$after_lh" | { grep -E '^- `교대 기동`' || true; } | gate_count)" = "0" ] \
      && [ "$(printf '%s\n' "$after_lh" | { grep -E '^- `자율 승인`' || true; } \
              | gate_rows_field_eq 'kind' 'router-shift' | gate_rows_field_eq '결정' 'act' | gate_count)" -ge 2 ]; then
      human_turn=1
      log "전송 단절 재기동 — 같은 인계 뒤 앞선 시도가 돌아선 다음의 사람 차례 기동이므로 탐침과 연속 상한을 건너뛴다"
    fi
  fi
  if [ -z "$human_turn" ] && [ "$(gate_row_field "$lh" '사유')" = '무기록' ] \
    && [ "$(gate_row_field "$lh" '일시 원인')" = '예' ]; then
    local streak k=0 s
    streak=$( { gate_rows '교대 기동' || true; } | awk '
      { n = split($0, f, "|"); has = 0
        for (i = 2; i <= n; i++) { s = f[i]; sub(/^ +/, "", s); if (index(s, "연결 확인=") == 1) has = 1 }
        c = has ? c + 1 : 0 }
      END { print c + 0 }')
    if [ "${streak:-0}" -ge 3 ]; then
      warn "전송 단절 재기동 거절 — 연결 확인을 거친 교대 기동이 연속 ${streak}번입니다; 상한은 세 번입니다"
      gate_shift_launch_drop_claim
      return "$GATE_EXIT_RULE"
    fi
    for s in $(net_probe_sleeps); do
      k=$((k + 1))
      sleep "$s"
      if net_probe_once; then probe_note="$k/성공"; break; fi
    done
    if [ -z "$probe_note" ]; then
      warn "전송 단절 재기동 거절 — 연결 탐침이 ${k}번 모두 닿지 않았습니다"
      gate_shift_launch_drop_claim
      return "$GATE_EXIT_RULE"
    fi
    log "전송 단절 뒤 연결 확인 ${probe_note} — 교대를 기동한다"
  fi

  # THE SHIFT'S INSTRUCTIONS — the same policy file and the same synthesis as a
  # stage of the home target, never a narrower variant (that would be a second
  # drift surface and a second cache head). Synthesized BEFORE the `교대 기동`
  # row and the in-progress marker, so a refusal (127) leaves no shift on record
  # that never started. A shift is always a new session, so there is no resume
  # arm here.
  local instr member_instr irc=0
  instr=$(gate_stage_instructions_for_launch "$alias" "") || irc=$?
  if [ "$irc" != "0" ]; then
    gate_shift_launch_drop_claim
    return "$irc"
  fi
  member_instr=$(gate_stage_member_instructions "$instr")

  local plugin_dir n rc=0
  plugin_dir=$(cd "$(dirname "$GATE_DIR")" && pwd)
  # ONE EXPRESSION OWNS THE SCALE. `gate_shift_launches` counts the rows written
  # by launches that actually happened, and THIS launch has not written its own
  # yet — it is written a few lines below, past both early returns — so the
  # ordinal is that count plus one.
  #
  # The count used to include this act's own `자율 승인` row and was taken as the
  # ordinal directly. That put attempts and launches on one scale: the two early
  # returns above leave the act row behind and start nothing, so a held attempt
  # moved the scale and the number it consumed named a `log/shift-N.json` no run
  # ever wrote. Adding one to a count of ENDED handoffs, the form before that, put
  # the identifier a notch above the number the successor's own rows would carry.
  n=$(( $(gate_shift_launches) + 1 ))
  [ "${n:-0}" -ge 1 ] || n=1
  mkdir -p "$RUN_DIR/log"
  gate_stage_instructions_record "$(session_uuid "shift" "$n")" "$instr"

  # AN EXPIRY TIMESTAMP AND NOT AN EMPTY MARKER. The watcher's after-stage arm
  # reads this file to keep from calling a shift "router silent after a stage
  # ended" — a misreading that writes a run-scope `blocked` row with cause
  # unknown, and an unresolved run-scope block is an input to the termination
  # condition, so the run cannot finish. But `RUN_DIR` is never pruned: written
  # as a bare marker and tested with `[ ! -f ]`, a shift that dies right after
  # its handoff leaves the file behind for the rest of the night and the safety
  # device becomes a silent hole. 300 seconds is the cold-start budget a first
  # run is expected to measure against.
  printf '%s\n' "$(( $(date +%s) + 300 ))" > "$RUN_DIR/shift.in-progress"

  # NO PID FILE, DELIBERATELY. A pid file is what makes a STAGE visible to the
  # watcher's liveness count, and a shift recorded there would read as a live
  # stage — which suppresses the very arms that exist to notice a router that
  # stopped. The expiry marker above is the shift's liveness token instead —
  # and beside it `shift.live` (pid + fingerprint, written below) is the token
  # that does not expire: it sits OUTSIDE the `*.pid` glob, so the structural
  # guarantee that it is never counted as a stage needs no sibling-file check.
  # THE LAUNCH ROW, AND THE SCALE IS COUNTED FROM IT RATHER THAN FROM THE ACT.
  # It sits below both early returns and above the exec, so it exists exactly
  # when a successor was actually started. `gate_shift_launches` reads it.
  #
  # THE FIELD IS `서수`, NOT `교대`. `gate_append` stamps the routing SEAT on every
  # row unless the caller supplies `교대` itself, so spelling this field `교대`
  # would suppress that stamp on the one row whose whole purpose is to carry an
  # ordinal — and the two numbers are different quantities: the seat is who
  # launched this shift, the ordinal is which shift was launched.
  #
  # THE SHIFT'S WINDOW IS RECORDED AND NOT INJECTED. A routing session gets no
  # argv window — the injection table is per stage kind and the shift is not
  # one — so the reading below has no argv layer, and the row carries what the
  # settings and lane give the successor, with the session id to join on.
  #
  # EFFORT AND MODEL ARE INJECTED, unlike the window: they come from the same
  # sourced table the stages use, under the kind `shift`, and the effort the
  # argv carries is the one the row records.
  #
  # `컨텍스트` IS THE OUTGOING SHIFT'S, NOT THE LAUNCHER'S. Launches are serial,
  # so the shift this one replaces is ordinal n-1, and it has already ended by the
  # time the seat's `act --kind router-shift` reaches this line. Calling today's
  # context function here would read the transcript of the process doing the
  # launching — the seat — which is the confusion the floor guard above records.
  # A kickoff launch has no outgoing shift and an unresolved transcript has no
  # honest number, so both carry `-`.
  #
  # `조직 이동` IS THE OUTGOING SHIFT'S TOO, for the same reason, and silent
  # when it is 0 or unreadable — a kickoff launch has no outgoing shift at all.
  local window effort model launch_flags prev_ctx='' som=''
  window=$(gate_autocompact_effective "" "$(gate_settings_file shift)" "$PWD")
  effort=$(stage_effort_of shift)
  model=$(stage_model_of shift)
  launch_flags=$(stage_launch_flags shift)
  if [ "$n" -gt 1 ]; then
    prev_ctx=$(gate_shift_context_of "$((n - 1))")
    som=$(gate_shift_org_moves_of "$((n - 1))" || true)
  fi
  # THE POLLER'S VERDICTS ENTER THE LEDGER BEFORE THE SUCCESSOR STARTS, inside
  # or outside the relay loop. A relay woken by a CI verdict hands the shift a
  # snapshot that already carries it, rather than the `CI 대기` the last drain
  # left; the drain appends under its own lock and is done before the row below.
  # The base branch's reading goes in first for the same reason: a relay woken
  # by it hands over a snapshot whose `다음` already reads the new reading.
  gate_master_row_if_changed
  gate_drain_checks
  gate_append '교대 기동' "서수=$n" "사유=$reason" "대상=$alias" "기록 시각=$(now_iso)" \
    "세션 id=$(session_uuid "shift" "$n")" "레인=$(gate_lane_label)" "압축 창=$window" \
    "컨텍스트=${prev_ctx:--}" "effort=${effort:--}" "모델=${model:--}" \
    ${som:+"조직 이동=$som"} ${probe_note:+"연결 확인=$probe_note"}
  # THE RUN NOW ENDS ON `done`, AND ONLY THE SEAT SAYS SO. A seat that hands its
  # turn to a shift settles the exit clauses after the last segment, so from here
  # the ledger-derived terminal conjunction opens a settlement window instead of
  # ending the run. Written below every early return, so a `router-shift` that
  # launched nothing leaves no marker; and only for the seat, because a stage or a
  # shift reaches this arm too, and a marker on a driver run would keep a run that
  # finished from ever reading 종단.
  gate_may_raise_banner && { [ -e "$RUN_DIR/ends-on-done" ] || printf '1\n' > "$RUN_DIR/ends-on-done"; }
  # `seat-call` — HOW THE SEAT CALLS, so a boot-time re-entry can call the same
  # way without parsing prose: the manifest's absolute path, the alias, this
  # run's pinned gate, and the `--cutpoint` and `--surface` this `router-shift`
  # carried. Under the same seat predicate as the marker above, and atomic, so a
  # reader sees no record or a whole one. `cutpoint` and `surface` are the act's
  # own argv, in scope here from `gate_verb_act`.
  gate_may_raise_banner && gate_seat_call_write "$alias" "${cutpoint:-}" "${surface:-}"
  log "교대 $n 시작 — 사유 $reason"
  # THE SUCCESSOR'S SEAT IS THIS LAUNCHER'S PROPERTY, NOT ITS CALLER'S AMBIENT
  # ENVIRONMENT. A prefix assignment adds and overwrites; it never unsets. So a
  # shift launched from a stage seat — a stage reaches this arm like any other
  # gate call, and nothing refuses `--kind router-shift` there — inherited both
  # stage markers, and the successor was a router that `cc_caller_is_stage`
  # answered "stage" for, for its whole life: the judgment predicate never
  # evaluated B1..B3 on that seat, and its dispatch rows stamped `행위자=스테이지`,
  # so the progress vector did not see them either. The two markers are cleared
  # HERE rather than told apart in the actor block, because "a stage a shift
  # launched" and "a shift a stage launched" carry byte-identical environments
  # and no branch order answers both. `gate_launch_stage` deliberately leaves
  # `CC_PIPELINE_SHIFT_ID` in place for the opposite direction; that stays.
  #
  # `CC_PIPELINE_REENTRY` IS CLEARED THE SAME WAY. A boot-time re-entry exports
  # it so that no banner rises from a process with no seat; the shift and its
  # stages are already "not the router" by `CC_PIPELINE_SHIFT_ID`, and a test
  # run inside a stage must not inherit a fourth marker it never set.
  CLAUDE_CODE_PRINT_BG_WAIT_CEILING_MS="${CC_ORCH_BG_WAIT_CEILING_MS:-14400000}" \
  CC_CLAUDE_BIN="$CLI_BIN" \
  CC_PIPELINE_RUN_ID="$RUN_ID" \
  CC_PIPELINE_RUN_DIR="$RUN_DIR" \
  CC_PIPELINE_MANIFEST="$MANIFEST" \
  CC_PIPELINE_LEDGER="$LEDGER" \
  CC_PIPELINE_GRANT="$GRANT" \
  CC_PIPELINE_GATE="$GATE_DIR/gate.sh" \
  CC_PIPELINE_TARGET="$alias" \
  CC_PIPELINE_SEGMENT= \
  CC_PIPELINE_STAGE_ID= \
  CC_PIPELINE_REENTRY= \
  CC_PIPELINE_SHIFT_ID="$RUN_ID#$n" \
  CC_CMDS_AUTOPILOT_AUTO_RESOLVE="$(gate_auto_resolve_enabled && printf 1 || printf 0)" \
  bash "$wrapper" \
    --settings "$(gate_settings_file shift)" \
    --plugin-dir "$plugin_dir" \
    --instructions "$instr" \
    ${member_instr:+--member-instructions "$member_instr"} \
    --session-id "$(session_uuid "shift" "$n")" \
    $launch_flags \
    -- "$@" > "$RUN_DIR/log/shift-$n.json" 2> "$RUN_DIR/log/shift-$n.err" < /dev/null &
  # BACKGROUNDED SO THERE IS A PID TO RECORD, then waited on — the call still
  # blocks for the successor's whole life exactly as before. `$!` IS CORRECT
  # HERE: no fork sits between this shell and the wrapper, and the wrapper
  # `exec`s into the CLI, so the pid holds. `shift.live` is what the watcher's
  # `shift_active` reads once `shift.in-progress` has expired: with a detached
  # supervisor a stage can now end at any point of a shift's life, and the
  # after-stage arm would otherwise fire mid-shift and write a run-scope
  # `blocked` row that no run can end past without a person.
  #
  # LINES 3 AND 4 ARE THIS LAUNCHER, the gate process that waits on the shift and
  # writes its `무기록` row. `cc_shift_is_live` reads lines 1 and 2 only, so the
  # watcher's answer does not move. The prelude's dead-shift settlement reads
  # all four: a shift whose launcher is still alive is the launcher's to trace,
  # and only when both are gone — a reboot, a killed seat — is the row nobody
  # else will write.
  local spid=$!
  printf '%s\n%s\n%s\n%s\n' "$spid" "$(cc_proc_fingerprint "$spid")" \
    "$$" "$(cc_proc_fingerprint "$$")" > "$RUN_DIR/shift.live"
  rm -f "$RUN_DIR/relay.live"
  wait "$spid" || rc=$?
  [ "$rc" != "0" ] || gate_relay_enter_if_waiting
  rm -f "$RUN_DIR/shift.in-progress" "$RUN_DIR/shift.live"
  log "교대 $n 종료 (rc=$rc)"
  # IN A SUBSHELL, SO A FAILED TRACE CANNOT BECOME THE ACT'S EXIT CODE.
  # `gate_append` answers a failure with `die`, and a 1 here would read at the
  # seat as "the shift itself died". The subshell does not run the parent's EXIT
  # trap, so the digest is still emitted once, by the parent, after this row.
  # `gate_rows` reads the file and not a memo, so it sees what the shift wrote.
  ( gate_shift_trace_unrecorded "$alias" "$n" "$rc" ) \
    || warn "교대 $n 의 무기록 인계 행을 남기지 못했습니다 — 교대의 종료 코드 ${rc} 는 그대로 돌려줍니다"
  # THE SHIFT'S RETURN IS WHERE A SEAT RUN'S ENDING REACHES A PERSON. A `done`
  # the shift wrote raised nothing — the shift is not the seat — and its process
  # is gone now, so the settlement is over and the seat has its turn back. The
  # sentence is read from `done`'s first line, so a boundary or an invalidation
  # inside the shift is announced as what it was. Without `done` nothing is said.
  gate_shift_return_banner
  return "$rc"
}

gate_shift_return_banner() {
  # The ended banner of a settled seat run, raised where the seat gets its turn
  # back: a shift's return, and a relay's hand-back of a run that closed while it
  # waited — that return launched nothing, so it never passes the line above.
  # The anchor sits here, beside the emitter, and not at either caller: the
  # firing table reads a few lines past it, and a caller holds only the call.
  # SHIFT-RETURN FIRING SITE — the ended banner of a settled seat run.
  if gate_may_raise_banner && cc_run_end_settled "$RUN_DIR" && cc_notify_claim_ended; then
    cc_notify_fire ended "$(cc_notify_ended_text "$RUN_DIR")" || true
    cc_notify_mark_ended_fired
  fi
  return 0
}

# ---------------------------------------------------------------------------
# The relay — the wait a shift hands out of its turn.
#
# A SHIFT THAT HAS NOTHING LEFT BUT WAITING ENDS WITH `handoff 사유=대기`, and
# the seat call that launched it — this process, blocked in `gate_launch_shift`
# — does the waiting in the shell: it polls the wait set every
# `GATE_WAIT_POLL_SECONDS` and launches a fresh successor when a condition
# wakes it. No `claude` process lives while it waits, so a two-hour stage costs
# no shift turns at all, where a foreground `gate.sh wait` inside the shift kept
# a whole session open for it.
#
# THE MARKERS HAND OVER, NEVER LEAVE A GAP. `relay.live` is written after the
# shift is reaped and before its markers are removed, and removed only after the
# successor's `shift.live` is on disk; a seat re-entry writes it before its first
# poll. While a relay lives, the watcher always sees one live marker. The file
# outlives the relay on purpose: its `handback` line is the watcher's base time
# for the seat turn that follows a hand-back.
#
# THE WAIT AND THE READS ONLY READ THE LEDGER. While it waits the relay never
# drains `checks.observed`, never appends a row and never calls `gh` — it reads
# the three sources the poller and the drain already keep, through
# `cc_ci_records`, which the watcher reads too. A drain in the wait would append
# rows inside the seat's open call and stale every sibling digest. The shift
# launch the loop calls is the one writer: it appends the CI drain and the
# `교대 기동` row.

GATE_RELAY_SEAT_START=""
GATE_RELAY_INNER=""
GATE_RELAY_ENTERED=""
GATE_RELAY_HANDED_BACK=""
GATE_RELAY_STARTED=""
GATE_RELAY_FP=""

gate_relay_route() {
  # gate_relay_route <alias> <사유> <cli args...> — the `router-shift` act: one
  # launch, then the relay loop for as long as the shift it launched ends `대기`.
  #
  # A SUCCESSOR IS HANDLED BY THE SAME RULE AS THE FIRST SHIFT. rc 0 with a
  # `대기` handoff after its launch row continues the loop; anything else — rc
  # 0 under another reason, an approval (5), a dead shift — ends it and is the
  # seat call's result, so the seat's three outcomes do not change.
  local alias="$1" reason="$2" rc=0; shift 2
  GATE_RELAY_SEAT_START=$(date -u +%s)
  GATE_RELAY_INNER=""
  GATE_RELAY_ENTERED=""
  GATE_RELAY_HANDED_BACK=""
  gate_launch_shift "$alias" "$reason" "$@" || rc=$?
  while [ "$rc" = "0" ] && [ -n "$GATE_RELAY_ENTERED" ] && [ -z "$GATE_RELAY_HANDED_BACK" ]; do
    gate_relay_wait || return 0
    # `done` AGAIN, BETWEEN THE WAKE AND THE LAUNCH. The wait checked it before
    # judging the wake, and a run that closed in between must not get a successor.
    if [ -e "$RUN_DIR/done" ]; then
      gate_relay_hand_back "$(cc_relay_wait_stages "$RUN_DIR")" "$(gate_relay_ci_segments)" \
        "$(gate_relay_reset_set)" "런이 끝났다"
      return 0
    fi
    # THE INNER MARKER SKIPS THE PRE-LAUNCH WAIT. The wake was judged here a
    # moment ago, and judging it again at the launcher would wait on the rest of
    # the set instead of the element that just finished. The launch row still
    # carries `사유=대기`, which is what this successor was launched for.
    GATE_RELAY_ENTERED=""
    GATE_RELAY_INNER=1
    gate_launch_shift "$alias" 대기 "$@" || rc=$?
    GATE_RELAY_INNER=""
  done
  return "$rc"
}

gate_relay_hold() {
  # The hold this call compares against. The test hook is honoured only below
  # the declared constant and only as a positive integer, so it can shorten a
  # test's wait and can never lengthen a real one.
  local t="${CC_GATE_RELAY_HOLD_TEST_SECONDS:-}"
  case "$t" in
    ''|*[!0-9]*) printf '%s' "$GATE_RELAY_HOLD_SECONDS"; return 0 ;;
  esac
  t=$((10#$t))
  if [ "$t" -gt 0 ] && [ "$t" -lt "$GATE_RELAY_HOLD_SECONDS" ]; then
    printf '%s' "$t"
  else
    printf '%s' "$GATE_RELAY_HOLD_SECONDS"
  fi
}

gate_relay_reentry_allowed() {
  # Succeeds when the ledger's latest `handoff` carries `사유=대기` and no
  # `교대 기동` row follows it — the one state a relay waits in. Read with awk
  # from the file, never through the row memo: the relay reads the ledger again
  # and again while other processes append to it.
  #
  # AND THE ONE OTHER STATE: A SHIFT THAT DIED OF THE LIMIT. The latest handoff
  # is the gate's own `무기록` for it, no launch follows, and the stream of the
  # latest `교대 기동` — that shift — yields a reset clock within the horizon.
  # The seat (or a boot-time re-entry) re-issues `대기` at once instead of
  # waiting for the reset itself, and the relay holds it until the reset. With
  # no clock, or one further than the horizon, it stays refused.
  local st n at
  [ -n "${LEDGER:-}" ] && [ -f "$LEDGER" ] || return 1
  # `이월` waits too: for the deadline, after which the successor ends the run
  # (`gate_relay_defer_clock`).
  st=$(LC_ALL=C awk '
    /^- `handoff` / {
      w = "x"
      if (index($0, " | 사유=대기 | ") > 0 || index($0, " | 사유=이월 | ") > 0) w = "w"
      else if (index($0, " | 사유=무기록 | ") > 0) w = "u"
    }
    /^- `교대 기동` / { w = "x" }
    END { printf "%s", w }
  ' "$LEDGER" 2>/dev/null || true)
  case "$st" in
    w) return 0 ;;
    u) : ;;
    *) return 1 ;;
  esac
  n=$( { LC_ALL=C grep -E '^- `교대 기동` ' "$LEDGER" 2>/dev/null || true; } | tail -1)
  n=$(gate_row_field "$n" '서수')
  case "$n" in ''|*[!0-9]*) return 1 ;; esac
  at=$(gate_cut_key_reset_at "교대#$n")
  [ -n "$at" ] && gate_cut_reset_within "$at"
}

gate_relay_ci_segments() {
  # The `CI 대기` segments of the reference row — the latest `handoff`, when it
  # is `대기` — comma-joined, or empty. A latest `handoff` of any other reason
  # names no CI wait: under a limit-shaped `무기록` the relay holds for that
  # shift's reset alone, and an older shift's `대기` must not put its stale `CI
  # 대기` back into the set.
  [ -n "${LEDGER:-}" ] && [ -f "$LEDGER" ] || return 0
  LC_ALL=C awk -F'|' '
    function trim(s) { sub(/^[ \t]+/, "", s); sub(/[ \t]+$/, "", s); return s }
    /^- `handoff` / {
      ci = ""
      if (index($0, " | 사유=대기 | ") == 0) next
      for (i = 2; i <= NF; i++) {
        f = trim($i)
        if (index(f, "CI 대기=") == 1) ci = substr(f, length("CI 대기=") + 1)
      }
    }
    END { if (ci != "-") printf "%s", ci }
  ' "$LEDGER" 2>/dev/null || true
}

gate_relay_master_segments() {
  # The `master 대기` segments of the reference row — the latest `handoff`,
  # when it is `대기` — comma-joined, or empty; read as `gate_relay_ci_segments`
  # reads its field.
  [ -n "${LEDGER:-}" ] && [ -f "$LEDGER" ] || return 0
  LC_ALL=C awk -F'|' '
    function trim(s) { sub(/^[ \t]+/, "", s); sub(/[ \t]+$/, "", s); return s }
    /^- `handoff` / {
      mw = ""
      if (index($0, " | 사유=대기 | ") == 0) next
      for (i = 2; i <= NF; i++) {
        f = trim($i)
        if (index(f, "master 대기=") == 1) mw = substr(f, length("master 대기=") + 1)
      }
    }
    END { if (mw != "-") printf "%s", mw }
  ' "$LEDGER" 2>/dev/null || true
}

gate_relay_master_wake() {
  # gate_relay_master_wake <segments> — 0 when the base branch of any of the
  # segments has a reading that differs from the ledger's last `master 판독`
  # row in its state, signature fingerprint or events, or a reading that is
  # absent or older than GATE_MASTER_STALE_SECONDS: the disposition then reads
  # differently, back to L7 when the reading is gone. A reading only observed
  # again is not a wake — the master stage observes every few minutes.
  #
  # The ledger is read from the file, not the row memo, as the relay's other
  # readers do: other processes append while it polls.
  local segs=$1 s al slug br st rd last ep now
  now=$(date -u +%s)
  for s in $(printf '%s' "$segs" | tr ',' ' '); do
    al=$(gate_segment_target_alias "$s")
    [ -n "$al" ] || continue
    slug=$(target_field "$al" '원격 슬러그' 2>/dev/null || true)
    br=$(base_branch "$al" 2>/dev/null || true)
    { [ -n "$slug" ] && [ -n "$br" ]; } || continue
    last=$( { LC_ALL=C grep -E '^- `master 판독` ' "$LEDGER" 2>/dev/null || true; } \
            | { grep -F "| 대상=$al |" || true; } | tail -1)
    st=$(gate_master_state "$slug" "$br")
    rd=""
    [ -z "$st" ] || rd=$(gate_master_reading "$st") || rd=""
    [ -n "$rd" ] || return 0
    ep=$(cc_iso_to_epoch "$(printf '%s\n' "$rd" | awk -F'\t' '$1 == "관측" { print $2 }')")
    [ -n "$ep" ] && [ $((now - ep)) -le "$GATE_MASTER_STALE_SECONDS" ] || return 0
    [ "$(gate_row_field "$last" '상태')" = "$(printf '%s\n' "$rd" | awk -F'\t' '$1 == "상태" { print $2 }')" ] || return 0
    [ "$(gate_row_field "$last" '서명 지문')" = "$(printf '%s\n' "$rd" | awk -F'\t' '$1 == "서명 지문" { print $2 }')" ] || return 0
    [ "$(gate_row_field "$last" '사건')" = "$(printf '%s\n' "$rd" | awk -F'\t' '$1 == "사건" { print $2 }')" ] || return 0
  done
  return 1
}

gate_cut_reset_at() {
  # gate_cut_reset_at <stream> — the epoch a cut attempt's limit resets at, or
  # nothing. ONE RULE, THE LAST FRAME: the answer is the last `rate_limit_event`
  # frame's `resetsAt`, and only when `stage_limit_exit` says that frame binds —
  # exit 0, or exit 3 whose letters name neither `F` (the frame is not
  # `rejected`) nor `R` (its `resetsAt` is not a number). A torn tail (`T`) or an
  # extra init (`P`) does not make the clock wrong; a window that allowed again,
  # or a frame with no typed clock, does. This is the frame the router's (a)
  # reads, so the gate and the router never disagree about which clock binds.
  local stream="${1:-}" letters="" lx=0 at
  [ -n "$stream" ] && [ -s "$stream" ] || return 0
  letters=$(stage_limit_exit "$stream" 2>/dev/null) || lx=$?
  case "$lx" in
    0) : ;;
    3) case ",$letters," in *,F,*|*,R,*) return 0 ;; esac ;;
    *) return 0 ;;
  esac
  at=$(jq -R -n -r '
    reduce (inputs | (try fromjson catch null) | objects
            | select(.type == "rate_limit_event")) as $f (null; $f)
    | (.rate_limit_info? // {}) | .resetsAt
    | if type == "number" then (floor | tostring) else empty end' \
    "$stream" 2>/dev/null) || return 0
  case "$at" in ''|*[!0-9]*) return 0 ;; esac
  printf '%s' "$at"
}

gate_cut_key_reset_at() {
  # gate_cut_key_reset_at <key> — the reset clock of one `리셋 대기` key, or
  # nothing. A stage key's clock comes from its latest `stage-result`, and only
  # when that row is a cut — `한도 종료` or `크래시`, the 429 crash the limit
  # shape did not fully hold for — from that attempt's own stream. `교대#<n>` is
  # the relay's own key for a shift that died of the limit: shift n's stream.
  local key="$1" row klass att
  case "$key" in
    교대#*)
      att=${key#교대#}
      case "$att" in ''|*[!0-9]*) return 0 ;; esac
      gate_cut_reset_at "$RUN_DIR/log/shift-$att.json"
      return 0 ;;
  esac
  # From the file and not the row memo: the relay calls this on every poll
  # while other processes append.
  row=$( { LC_ALL=C grep -E '^- `stage-result` ' "$LEDGER" 2>/dev/null || true; } \
         | { grep -F "| 스테이지=$key |" || true; } | tail -1)
  [ -n "$row" ] || return 0
  klass=$(gate_row_field "$row" '종단 부류')
  case "$klass" in 한도\ 종료|크래시) : ;; *) return 0 ;; esac
  att=$(gate_row_field "$row" '실행 버전')
  case "$att" in ''|*[!0-9]*) return 0 ;; esac
  gate_cut_reset_at "$RUN_DIR/log/$key#$att.json"
}

gate_relay_reset_set() {
  # The reset member of the relay's wait set, as `<key>:<epoch>[,…]`, or empty —
  # derived again from the reference row on every call, never carried in memory.
  # The reference row is the latest `handoff`: under `대기` its `리셋 대기` keys,
  # each with the clock it has now; under a limit-shaped `무기록` the shift that
  # wrote nothing, `교대#<n>` with the clock of its own stream.
  [ -n "${LEDGER:-}" ] && [ -f "$LEDGER" ] || return 0
  local last why keys k at out="" n
  last=$( { LC_ALL=C grep -E '^- `handoff` ' "$LEDGER" 2>/dev/null || true; } | tail -1)
  why=$(gate_row_field "$last" '사유')
  case "$why" in
    대기)
      keys=$(gate_row_field "$last" '리셋 대기')
      [ "$keys" != "-" ] || keys=""
      for k in $(printf '%s' "$keys" | tr ',' ' '); do
        at=$(gate_cut_key_reset_at "$k")
        [ -z "$at" ] || out="${out:+$out,}$k:$at"
      done ;;
    무기록)
      n=$(gate_row_field "$last" '교대')
      case "$n" in ''|*[!0-9]*) return 0 ;; esac
      at=$(gate_cut_key_reset_at "교대#$n")
      [ -z "$at" ] || out="교대#$n:$at" ;;
  esac
  printf '%s' "$out"
}

gate_deadline_epoch() {
  # gate_deadline_epoch — the manifest's `벽시계 마감` as epoch seconds, or
  # nothing when it is absent or does not read. The stamp's first 19
  # characters are converted as UTC and its `±HH:MM` offset is taken off.
  local dl ep off h m s
  [ -n "${MANIFEST:-}" ] || return 0
  dl=$(manifest_field '인가' '벽시계 마감')
  case "$dl" in ''|없음|'(없음)') return 0 ;; esac
  ep=$(cc_iso_to_epoch "$(printf '%s' "$dl" | cut -c1-19)Z")
  case "$ep" in ''|*[!0-9]*) return 0 ;; esac
  off=$(printf '%s' "$dl" | cut -c20-)
  case "$off" in
    Z|'') s=0 ;;
    [+-][0-9][0-9]:[0-9][0-9])
      h=$(printf '%s' "$off" | cut -c2-3); m=$(printf '%s' "$off" | cut -c5-6)
      s=$(( (10#$h * 3600) + (10#$m * 60) ))
      case "$off" in +*) s=$((0 - s)) ;; esac ;;
    *) return 0 ;;
  esac
  printf '%s' "$((ep + s))"
}

gate_relay_defer_clock() {
  # gate_relay_defer_clock — the `이월` member of the relay's wait set: the
  # epoch one second past the deadline when the latest `handoff` is `이월`, or
  # empty. Derived again from the reference row on every call, like the reset
  # member. The reset horizon does not apply: the relay hands back after its
  # hold as it always does, and the seat issues the same call again.
  [ -n "${LEDGER:-}" ] && [ -f "$LEDGER" ] || return 0
  local last dl
  last=$( { LC_ALL=C grep -E '^- `handoff` ' "$LEDGER" 2>/dev/null || true; } | tail -1)
  [ "$(gate_row_field "$last" '사유')" = "이월" ] || return 0
  dl=$(gate_deadline_epoch)
  [ -n "$dl" ] || return 0
  printf '%s' "$((dl + 1))"
}

gate_cut_reset_within() {
  # gate_cut_reset_within <epoch> — the clock is close enough to wait on: no
  # further than one five_hour window plus the grace from now. A relay has no
  # deadline exit, so a seven_day clock days away would keep the seat's re-issue
  # loop — and a boot-time re-entry's label — busy for days.
  local at="${1:-}" now
  case "$at" in ''|*[!0-9]*) return 1 ;; esac
  now=$(date -u +%s)
  [ "$at" -le $((now + GATE_RESET_HORIZON_SECONDS)) ]
}

gate_relay_write() {
  # gate_relay_write <stages> <ci> <reset> [<handback>] — publish `relay.live`
  # atomically: pid, fingerprint, `refreshed`, `started`, the stage and
  # supervisor keys, the CI segments, the reset clocks, and `handback` when the
  # relay returns. The pid is this gate process, which is the relay itself.
  #
  # `reset=` IS ONE LINE, `<key>:<epoch>` joined by `,`, like `stages=` and
  # `ci=`: `cc_relay_field` returns the last matching line only. Every caller
  # passes it, the per-poll refresh and the hand-back included — this file is
  # rewritten whole, so a line written once would be gone after the first poll.
  #
  # `defer=` IS DERIVED HERE, not passed: it is the `이월` member's clock
  # (`gate_relay_defer_clock`), and computing it inside keeps every caller —
  # the hand-back included — writing it without one more argument each.
  local t="$RUN_DIR/relay.live.tmp.$$" defer
  [ -n "$GATE_RELAY_FP" ] || GATE_RELAY_FP=$(cc_proc_fingerprint "$$")
  defer=$(gate_relay_defer_clock)
  {
    printf '%s\n%s\n' "$$" "$GATE_RELAY_FP"
    printf 'refreshed=%s\nstarted=%s\nstages=%s\nci=%s\nreset=%s\ndefer=%s\n' \
      "$(date -u +%s)" "$GATE_RELAY_STARTED" "${1:--}" "${2:--}" "${3:--}" "${defer:--}"
    [ -z "${4:-}" ] || printf 'handback=%s\n' "$4"
  } > "$t" 2>/dev/null && mv -f "$t" "$RUN_DIR/relay.live" 2>/dev/null || {
    rm -f "$t" 2>/dev/null
    warn "could not write relay.live — the watcher will not see this relay"
  }
  return 0
}

gate_relay_poller_live() {
  # The `checks` poller writes a bare pid, so a bare existence test is all its
  # record can answer.
  local p
  p=$( { cat "$RUN_DIR/checks.pid" 2>/dev/null || true; } | tr -d '[:space:]')
  case "$p" in ''|*[!0-9]*) return 1 ;; esac
  cc_pid_exists "$p"
}

gate_relay_enter_if_waiting() {
  # Called between `wait "$spid"` and the removal of the shift's markers, for a
  # shift that ended rc 0. Enters the relay only when that shift's own latest
  # `handoff` is `대기` — the launch row is the ledger's latest `교대 기동`,
  # since launches are serial — and writes `relay.live` here, before the
  # caller removes `shift.live`. ALWAYS RETURNS 0: it is the tail of an `||`
  # list under `set -e`.
  if gate_relay_reentry_allowed; then
    GATE_RELAY_STARTED=$(date -u +%s)
    gate_relay_write "$(cc_relay_wait_stages "$RUN_DIR")" "$(gate_relay_ci_segments)" \
      "$(gate_relay_reset_set)"
    GATE_RELAY_ENTERED=1
  fi
  return 0
}

gate_relay_before_launch() {
  # gate_relay_before_launch <사유> — the pre-launch wait of a seat re-entry.
  # Returns 0 to go on and launch, 1 when the relay handed the turn back and
  # nothing is to be launched. A launch from inside the relay loop carries the
  # inner marker and skips it, and so does every reason but `대기`.
  [ "$1" = "대기" ] && [ -z "$GATE_RELAY_INNER" ] || return 0
  [ -n "$GATE_RELAY_STARTED" ] || GATE_RELAY_STARTED=$(date -u +%s)
  gate_relay_write "$(cc_relay_wait_stages "$RUN_DIR")" "$(gate_relay_ci_segments)" \
    "$(gate_relay_reset_set)"
  GATE_RELAY_ENTERED=""
  gate_relay_wait
}

gate_relay_wait() {
  # The poll. Returns 0 when a wake condition stands (launch the successor) and
  # 1 after handing the turn back. The set is derived again here: a stage that
  # ended between the shift's handoff and this line has left the live set, so
  # an empty set means what was waited on is over, and the successor is
  # launched at once.
  #
  # RETURN CONDITIONS COME FIRST on every poll — a closed run, the hold, a dead
  # poller under a CI wait — so a run that has ended never gets a successor.
  #
  # A RESET IS THE THIRD MEMBER. A cut whose limit has not reset keeps the set
  # non-empty though no stage is live and no CI is pending, so the relay holds
  # until `cc_relay_wake_keys` says the reset plus the grace has passed or a
  # `한도 해제` row stands. Its keys are read again from the reference row here,
  # not carried over from the shift that named them.
  #
  # `이월` IS THE FOURTH. A hand-off that carried its answers over waits for
  # the deadline, so the set is not empty though nothing else is in it, and
  # the relay wakes one second past the deadline (`cc_relay_wake_keys`) to
  # launch the successor whose first act ends the run.
  #
  # THE BASE BRANCH IS THE FIFTH. The `master 대기` segments of the reference
  # row hold the set open, and the relay wakes when `gate_relay_master_wake`
  # says their base branch's reading moved or went stale. The watcher's keys
  # do not carry this member: the relay reads the reading files itself.
  local stages ci reset defer hold now mw
  stages=$(cc_relay_wait_stages "$RUN_DIR")
  ci=$(gate_relay_ci_segments)
  reset=$(gate_relay_reset_set)
  defer=$(gate_relay_defer_clock)
  mw=$(gate_relay_master_segments)
  [ -n "$GATE_RELAY_STARTED" ] || GATE_RELAY_STARTED=$(date -u +%s)
  gate_relay_write "$stages" "$ci" "$reset"
  hold=$(gate_relay_hold)
  log "교대 대기 — 스테이지·감독자 ${stages:--} · CI ${ci:--} · 리셋 ${reset:--} · 이월 ${defer:--} · master ${mw:--}"
  while :; do
    now=$(date -u +%s)
    if [ -e "$RUN_DIR/done" ]; then
      gate_relay_hand_back "$stages" "$ci" "$reset" "런이 끝났다"
      return 1
    fi
    if [ $((now - GATE_RELAY_SEAT_START)) -ge "$hold" ]; then
      gate_relay_hand_back "$stages" "$ci" "$reset" "좌석 호출의 대기 상한 ${hold}초가 지났다"
      return 1
    fi
    if [ -n "$ci" ] && ! gate_relay_poller_live; then
      gate_relay_hand_back "$stages" "$ci" "$reset" "CI 를 기다리는데 checks 폴러가 살아 있지 않다"
      return 1
    fi
    if [ -z "$stages" ] && [ -z "$ci" ] && [ -z "$reset" ] && [ -z "$defer" ] && [ -z "$mw" ]; then
      log "교대 대기 끝 — 기다리던 것이 이미 끝났다"
      return 0
    fi
    if [ -n "$(cc_relay_wake_keys "$RUN_DIR" "$LEDGER")" ]; then
      log "교대 대기 끝 — 깨움 조건이 섰다"
      return 0
    fi
    if [ -n "$mw" ] && gate_relay_master_wake "$mw"; then
      log "교대 대기 끝 — master 판독이 바뀌었거나 낡았다"
      return 0
    fi
    sleep "$GATE_WAIT_POLL_SECONDS"
    gate_relay_write "$stages" "$ci" "$reset"
  done
}

gate_relay_hand_back() {
  # gate_relay_hand_back <stages> <ci> <reset> <why> — rc 0 to the seat with
  # nothing launched and nothing appended; `handback` is the one trace, and it
  # is what the watcher measures the following seat turn from.
  #
  # A CLOSED RUN IS HANDED BACK AS ENDED. The ledger is still in the re-entry
  # state, so a line inviting the re-issue would send the seat into a call the
  # launcher refuses; this one says not to, and raises the ended banner the
  # seat would otherwise only see on a shift's return.
  gate_relay_write "$1" "$2" "$3" "$(date -u +%s)"
  GATE_RELAY_HANDED_BACK=1
  if [ -e "$RUN_DIR/done" ]; then
    printf '%s [relay] 대기를 거둔다 — %s · 다시 내지 않는다\n' "$(now_iso)" "$4"
    gate_shift_return_banner
    return 0
  fi
  printf '%s [relay] 대기가 이어진다 — %s · 같은 호출을 대기 로 다시 낸다\n' "$(now_iso)" "$4"
  return 0
}

# ---------------------------------------------------------------------------
# The four boundaries.
#
# All four convert to a PENDING APPROVAL rather than a park: the run has not
# failed, it has stopped moving, and a night should not be spent on a condition
# one sentence from the user would clear.
#
# B1..B3 are SUSPENDED while an approval is open. A run in that state is not
# stalled, it is waiting — and without the suspension B1's own remedy would
# reset the counter that fired it, which is the same defect the progress vector
# was rebuilt to remove, reappearing one layer up.
#
# B1..B3 ARE EVALUATED ON A JUDGMENT ONLY. A judgment is a gate call on which
# all three hold: (1) the caller is not a stage — `cc_caller_is_stage` is
# false, i.e. `CC_PIPELINE_SEGMENT` and `CC_PIPELINE_STAGE_ID` are both empty
# (a routing shard carries neither and IS the router); (2) the grade is above
# `읽기`; (3) the kind is neither `skill` nor `router-shift`. Condition (2)
# alone drops every reconnaissance read and every bookkeeping act (`segment`,
# `cycle`, `problem`, `blocked`, `clause`, `judgment`, `obligation`, `handoff`
# all grade `읽기`) and `propose-done` — WITHOUT A LIST, because a list is a
# hole the moment a kind is added. Condition (3) makes a dispatch the act that
# MAKES progress rather than a judgment about it, so the evaluation-order
# problem (B1 firing in the dispatch act's own preamble, before the stage
# exists) does not move — it disappears.
#
# A router that only reads is caught by none of B1..B3, and that is an ACCEPTED
# residual: counting reads is exactly the defect that fired B1 on the router's
# first three reconnaissance reads, and what bounds the rest is the shift cap,
# the wall-clock deadline and B4. So B4 sits OUTSIDE the predicate — a read
# still spends tokens, and a cost boundary inside the predicate would leave a
# reconnaissance-only overrun unseen by every boundary at once.
#
# B2 lives inside the same block and inherits the predicate, and that is a fix
# rather than a side effect: B2 never had a live-stage early return, so four
# gate calls from a stage could fire B2 against itself.
# ---------------------------------------------------------------------------
# N=5, NOT 3. Replaying a real ledger, N=3 fired three times on one healthy run
# and N=5 fired zero times. A contract-keeping router emits at most three
# above-read acts between structural rows (commit, push, PR creation — or push,
# merge), so 3 was never a binding condition. The asymmetry decides the rest: a
# false positive costs a night and the in-flight stage's work; a false negative
# costs two more acts before the slower detector (B3, 40 acts) takes over.
readonly B1_STAGNATION_N=5
# M stays at 3. B2 counts the INVARIANCE of the obligation set, not the repeat
# of a judgment, so judgments becoming rarer changes how fast it is reached and
# not what it means — and the direction is slower, which is the safe one.
readonly B2_OBLIGATION_M=3
readonly B3_ACT_BUDGET=40

# THE BOUNDED SATURATING READ CREDIT. A shift the launcher starts is a fresh
# print-mode process with no conversation history, so it MUST read before it can
# declare a segment, and the minimum number of those reads is three — which is
# exactly `B1_STAGNATION_N`. The healthy way to start a run was therefore the
# boundary's own firing condition. What is wrong is not the sign of the vector's
# read exclusion but that the allowance was all-or-nothing: zero or unbounded.
#
# THIS VALUE WAS CHOSEN AND NOT DERIVED, which is recorded because no
# measurement picks it. Observed launch bursts are two to three; replaying the
# corpus gives 90 firings at 3, 47 at 8 and 33 at 12, and launch-phase false
# positives are zero at every value. So the credit does not buy the launch phase
# — it sells sensitivity AFTER the launch — and 8 leaves headroom above the
# observed burst without covering twelve consecutive reads in silence.
readonly B1_READ_CREDIT=8

gate_boundary_binding() {
  # gate_boundary_binding <B1|B2|B3|B4> — the value that boundary's own
  # predicate decides on.
  #
  # ONE DEFINITION BECAUSE TWO READERS MUST AGREE. The predicates salt their
  # approval ids with this value and the withdrawal below compares a value
  # stored in a row against the current one; two copies of the expression let
  # the comparison answer "it moved" for a value that had not, and the
  # withdrawal would then discard a live question.
  #
  # B4 HAS NO BINDING OF ITS OWN YET — it holds one integer percentage and one
  # threshold, and a bucket tier would need a width no observation can validate
  # against a boundary that has never fired. It passes the progress digest until
  # a width is decided, so its shape is its siblings' and its value is today's.
  # B3's KEY IS FREE OF THE OBLIGATION COMPONENT AS WELL AS ITS OWN COUNTER'S
  # INPUT, and the two exclusions are there for different reasons. `acts=` was
  # this counter's own input, and is filtered here; the obligation set is the
  # component a run can move for free — opening a
  # problem row under a new identity changes the open set and therefore this key,
  # and the act that opens it grades `읽기`, so a fresh window costs nothing at
  # all. Measured: one problem row per cycle mixed with reads kept the boundaries
  # silent past 122 acts with termination condition 3 holding throughout. With the
  # component removed the three evasion shapes fire again at the control value of
  # 41. The vector itself has since lost the component (`gate_progress_vector`
  # says why), so B1 no longer moves on it either and this key needs no filter
  # for it.
  case "$1" in
    # B5 counts what B1 counts and disposes of it differently, so it reads the
    # same value by name rather than by a second call to the same helper.
    B1|B4|B5) gate_progress_digest ;;
    # B2 IS BOUND TO WHAT ITS COUNT IS WAITING ON, not to the open set. The open
    # set moves both ways for free — open and close a new identity, or toggle a
    # parked segment — so a binding on it withdrew a standing B2 question the
    # moment the run did either, and the withdrawal restarts the count. The whole
    # latch is no better: a new identity opened and closed again latches, so it
    # would withdraw the question just the same. What moves this value is a
    # member of the window being seen disposed, which is the one event
    # `gate_b2_obligations` counts as progress.
    B2)    gate_b2_waiting | shasum -a 256 | cut -d' ' -f1 ;;
    B3)    gate_progress_vector \
             | { grep -v '^acts=' || true; } | shasum -a 256 | cut -d' ' -f1 ;;
    *)     return 1 ;;
  esac
}

gate_boundaries() {
  # gate_boundaries <graded> <kind> — evaluated on every act and exec.
  #
  # CALLED FROM `gate_verb_act` AND NOT FROM THE PREAMBLE. Every verb passes the
  # preamble, so a boundary evaluated there would fire B1 on entry to a
  # two-hour `wait` and re-evaluate it on every heartbeat. The boundaries are
  # per act; the preamble is where settlement and bookkeeping live, and the
  # temptation to hoist something here is exactly what this sentence is for.
  local graded="${1:-}" kind="${2:-}" judgment=1
  # `act` AND NOT EVERY APPROVAL. This helper gained a narrowing argument and
  # three of its four call sites got one; this was the fourth, so `want` was
  # empty, the narrowing was skipped entirely, and a `절단점=판단` approval
  # counted here.
  #
  # Before questions could stay open past the night, every approval class that
  # could be open also counted toward termination condition 2, so the B1..B3
  # suspension was tied to the run's ability to end. Making a run able to end
  # with an open question cut that tie and left the suspension unbounded: one
  # grade-2 judgment at 22:10, with nobody awake to answer it — the premise of
  # this whole slice — switched off stagnation detection, obligation backlog and
  # the 40-act budget until the wall-clock deadline. The reason recorded for the
  # suspension ("waiting, not stalled") is false for this class specifically,
  # because the design promises the run keeps going alongside the question.
  local pending ids id closed=
  # WITHDRAWAL IS ACCOUNTED FOR BEFORE THE SUSPENSION IS COUNTED, and the order
  # is the point. An open boundary approval suspends B1..B3, so an approval whose
  # condition has already gone away goes on suspending them until a person closes
  # a question that is no longer about anything. Counting first would defer every
  # withdrawal by one evaluation, and on a run with one stale approval and nothing
  # else open it would defer it for the rest of the night.
  #
  # THE PENDING LIST IS ENUMERATED ONCE ON THE COMMON PATH. `gate_pending_approval_ids`
  # greps the whole ledger per approval id, so this runs on every gate call of the
  # night against a ledger that only grows; re-enumerating unconditionally would
  # pay that cost twice for the overwhelmingly common case of nothing being open.
  # The second enumeration happens only when a withdrawal actually landed, which
  # is the one case where the first answer has gone stale.
  #
  # THE DISPOSITION LATCH IS UPDATED FIRST, on every act and outside the judgment
  # predicate, and B2's window record beside it. The morning counts read the
  # latch, B2's binding and progress read the window record, and the withdrawal
  # below reads that binding; a disposition that holds only between two
  # judgments — an excusal walked back before the next one — is recorded only if
  # every act looks.
  gate_disposition_latch_update
  gate_b2_window_observe
  ids=$(gate_pending_approval_ids act)
  if gate_withdraw_stale_boundaries "$ids"; then
    ids=$(gate_pending_approval_ids act)
  fi
  # WITHDRAWAL RUNS FIRST, AUTO-RESOLUTION SECOND, and neither subsumes the
  # other. Withdrawal removes an approval whose condition has gone away, so it
  # has nothing left to answer; auto-resolution answers one that still stands
  # but carries a recommendation. A boundary approval left open — issued before
  # auto-resolution existed, or while it was switched off — suspends B1..B3 and
  # waits on a person. Resolving it here is what lets a run already in flight
  # pick the hotfix up on its next act instead of carrying the stop to morning.
  # Not a B4 at or above the ceiling, not one a person already answered, and a
  # close another writer reached first is left as that writer left it.
  # The list is re-enumerated only when something actually closed, on the same
  # reasoning as the withdrawal above.
  if gate_auto_resolve_enabled; then
    for id in $ids; do
      [ "$(gate_row_field "$(gate_approval_last_row "$id")" '절단점')" = "경계" ] || continue
      gate_boundary_auto_resolvable "${id%-*}" || continue
      gate_approval_person_answered "$id" && continue
      if gate_auto_close_approval "$id" 승인 \
        "$(gate_row_field "$(gate_approval_last_row "$id")" '질문 문면')" "계속"; then
        closed=1
      fi
    done
    if [ -n "$closed" ]; then
      ids=$(gate_pending_approval_ids act)
    fi
  fi
  pending=$(printf '%s\n' "$ids" | gate_count)
  # A PERSON-SET QUESTION SUSPENDS B1..B3 ONLY WHEN NO SHIFT IS LIVE. It is the
  # kind of question the run does not end around, so with no shift running the run
  # is genuinely waiting on a person and stagnation is not what is happening. A
  # live shift is still routing the segments the question does not hold, and
  # counting the question there would switch off the very detection the
  # paragraph above restored for open questions.
  if ! cc_shift_is_live "$RUN_DIR"; then
    pending=$((pending + $(gate_pending_approval_ids 사람 | gate_count)))
  fi

  # THE JUDGMENT PREDICATE — see the block comment above. A stage is not a
  # judging actor, a read is not a judgment, and a dispatch or a shift launch
  # is the act that MAKES progress rather than a judgment about it. The stage
  # check reads the environment through the one owner of the seat markers.
  if cc_caller_is_stage; then judgment=0; fi
  [ "$graded" = "읽기" ] && judgment=0
  case "$kind" in skill|router-shift) judgment=0 ;; esac

  # THE PROGRESS DIGEST IS COMPUTED ONCE AND HANDED TO BOTH READERS. It walks
  # the whole ledger, so computing it per boundary doubled that walk on every
  # judging call — measured as a suite that stopped finishing. And the two
  # boundaries are meant to be counting THE SAME NUMBER, which is worth holding
  # structurally rather than by two call sites happening to agree.
  local pdig=""
  if [ "$judgment" = "1" ]; then pdig=$(gate_boundary_binding B1); fi
  if [ "$pending" = "0" ] && [ "$judgment" = "1" ]; then
    gate_b1_stagnation "$pdig"
    gate_b2_obligations
    gate_b3_act_budget
  fi
  # B5 IS A JUDGMENT BOUNDARY EVALUATED OUTSIDE THE SUPPRESSION, which is the
  # only combination that can bound a run whose B1 question nobody answered —
  # B1's own firing opens the approval that then stops B1 from counting.
  if [ "$judgment" = "1" ]; then
    gate_b5_stagnation_bound "$pdig"
  fi
  # B4 stays live even while waiting, and OUTSIDE the judgment predicate too: a
  # read-only router still spends tokens, and a boundary inside the predicate
  # would leave that spend unseen by every boundary at once.
  gate_b4_cost
  # AND THE RUN IS TOLD WHEN IT HAS NEITHER. Said to the ROUTER, because it is
  # the seat that can do something about it and the one whose output a person
  # reads in the morning; a stage would carry the line into a transcript nobody
  # opens. Once per run, by a marker.
  if cc_caller_is_router; then
    gate_unbounded_notice
  fi
}

gate_b1_read_run() {
  # Two counts over the `자율 승인` rows since the progress digest was last
  # observed to move, printed as `<n> <m>`: `n` is the read-graded `exec`
  # authorisations and `m` is every other authorisation row in the stretch.
  #
  # THE CREDIT IS A SUPPRESSION AND NOT A VECTOR COMPONENT, and the placement is
  # the decision rather than an implementation detail. A component would leak
  # into `gate_b3_act_budget`'s window key — the vector less its own input —
  # and into `--snapshot-digest`, so a counter that saturates would move two
  # values it has no business moving, and the second of those is what makes a
  # snapshot reproducible. Here the vector does not change by one byte.
  #
  # THE STRETCH'S ORIGIN COMES FROM THE PROGRESS DIGEST ITSELF, and it used to be
  # a second hand-copy of `gate_progress_vector`'s membership rule. Six `index()`
  # literals enumerated "the rows that move the vector" and four of them
  # disagreed with it in three directions. A new `problem` moves the vector
  # through the open-obligation set and was not enumerated at all, so a stretch
  # that was really empty inherited the previous one's count: with that count in
  # `[1, C)` the credit SILENCED B1 on a genuinely stalled run, which is the
  # boundary's whole purpose inverted. A second `segment` row carrying the same
  # state and commit, and a `cycle` row with no `세그먼트=`, move nothing and
  # reset here.
  #
  # THE RULE CANNOT BE COPIED, WHICH IS WHY IT IS NOT COPIED ANY MORE. The vector
  # is a FOLD and not a per-row predicate — `segment` ids are deduplicated,
  # `cycle` rows are counted per segment, `problem` rows collapse to an identity
  # set — so whether a given row moved it is not decidable from that row alone.
  # `gate_b1_stagnation` already compares the digest on every evaluation, so it
  # records the ledger's row count at the moment the digest moves and this counts
  # forward from there. One definition, and an input added to the vector later is
  # picked up here for free.
  #
  # A NON-READ AUTHORISATION SPENDS THE CREDIT; IT DOES NOT VOID IT. A judgment,
  # an obligation and a handoff write `결정=act`, an auto-adopted judgment writes
  # `결정=채택`, a failed act writes `결정=결과`, a refused `propose-done` writes
  # `결정=기각`, and a row may carry no `축2=` at all. None of those moves the
  # vector and none of them is reconnaissance, so leaving them invisible held
  # `n` at whatever the reads before them had reached and three reads followed
  # by a night of judgments sat inside the credit for ever. The first repair
  # answered `-1` for any such row, and that voided the credit on EVERY shift the
  # gate launches: `act --kind router-shift` evaluates the boundaries before it
  # writes its own `결정=act` row, so the origin is recorded ahead of that row and
  # the launch row lands inside the next stretch; and the most common
  # reconnaissance read — a `grep` with no match — exits 1 and writes a
  # `결정=결과` row of its own. Replaying a recorded ledger, both launch-phase B1
  # firings the credit exists to forgive came back at exactly the same rows.
  #
  # So every row is COUNTED and none is skipped: `n` reads, `m` everything else,
  # and the caller forgives the stretch while `n + m` is under the credit. A
  # launch burst — one launch row, two or three reads, at most one failed read —
  # spends four or five of the eight, and a router that reads once and then
  # spins on judgments spends the rest within a few evaluations. Skipping
  # `결정=결과` alone was considered and rejected: an adopted judgment's row
  # carries the router's own fields verbatim, so any exemption keyed on a field's
  # presence can be satisfied by writing that field. With every row counted the
  # fields decide only which of `n` and `m` a row lands in, and that matters to
  # the `n >= 1` floor alone.
  #
  # THE TESTS ARE ANCHORED ON THE ROW'S DELIMITERS for the reason
  # `gate_b3_exec_total` is: `--rationale` lands in `근거=` untransformed, and an
  # unanchored `축2=읽기` therefore matched text the ROUTER writes. `gate_append`
  # maps `|` out of every key and value, so the delimiter form is unforgeable.
  #
  # `LC_ALL=C` for the reason the `stage-normal` pass pins it: `index` is then a
  # byte operation on both the BWK awk this ships on and a runner's gawk, so the
  # two hosts agree on where a field starts.
  local origin
  origin=$(cat "$RUN_DIR/progress-origin" 2>/dev/null || printf '0')
  case "$origin" in ''|*[!0-9]*) origin=0 ;; esac
  { grep '^- `' "$LEDGER" 2>/dev/null || true; } | LC_ALL=C awk -v skip="$origin" '
      BEGIN { n = 0; m = 0 }
      NR <= skip { next }
      index($0, "- `자율 승인`") == 1 {
        if (index($0, " | 결정=exec | ") > 0 && index($0, " | 축2=읽기 | ") > 0) n = n + 1
        else m = m + 1
      }
      END { printf "%d %d\n", n, m }'
}

gate_b1_stagnation() {
  # THE LIVE-STAGE SUPPRESSION IS GONE. It neither raised nor reset the counter,
  # so the value FROZE while a stage ran, and the first judgment after the last
  # stage died used that value and fired at once — the very moment a healthy
  # run resumes routing. Measured: live, the counter held at 4 and nothing
  # fired; the first judgment after the stage died raised it to 5 and fired.
  # And because B1's own approval suspends B1..B3, the counter did not merely
  # freeze — it froze AT THE FIRING THRESHOLD.
  #
  # What the suppression was for (a stage firing B1 against itself) is covered
  # completely by the caller condition in `gate_boundaries`. B1 now measures the
  # ROUTER, not the run, and the router's cadence does not change because a
  # stage is running elsewhere. Replaying a real 1037-row ledger with the
  # suppression removed and the caller condition applied, judgments went from
  # 19 to 28, the longest freeze stayed at 4, and N=5 fired zero times.
  #
  # THE COUNTER IS NOT RESET AT A SHIFT BOUNDARY. `progress-repeat` lives in
  # the run directory and carries across shifts. Zeroing it at shift launch
  # ("a new shift, fresh eyes") would mean B1 can never see a stall longer than
  # one shift, and the shift cap would become a way to launder stagnation. The
  # unit of judgment is the whole router — the seat and every shift as one —
  # and `교대 기동` is not progress.
  #
  # AFTER A PERSON CLOSES THE APPROVAL, what to expect: while it is open there
  # is neither evaluation nor counting. Closing it, whatever the disposition,
  # RESTARTS the counter: `gate_close_settle` rebaselines B1 to the current
  # digest with the count at 0, so the answer is not followed by a count already
  # past the threshold. The judgments after that raise the count again on the
  # same key, and when it reaches the threshold they compute the SAME id — which
  # the issuer keeps quiet, because the marker it left (`boundary-B1.asked`, the
  # digest it last asked about) still equals the digest and the id already
  # carries an answer. So no new question appears. One structural row landing
  # takes `n` back to 0, clears that marker (below), and yields a fresh id. So
  # "keep going" buys exactly one frozen state, and the router has to move a
  # structural row to earn the next question. The rebaseline moves the count,
  # never the marker — restarting the count is what the answer means, while
  # clearing the marker is reserved for the binding value actually moving.
  #
  # This paragraph used to credit `gate_has_row` with the suppression, and that
  # was false: the issuer re-opened any answered id the moment its predicate
  # held again, so the answered B1 came back on the next judgment and blocked
  # the run a person had just released. The mechanism is the issuer's answered
  # arm, and it is written down there.
  #
  # The binding value is named per predicate: for B1 it is the progress digest
  # itself, and `gate_boundary_binding B1` returns exactly that value, so the
  # rebaseline and the `boundary-B1.asked` marker compare against the same
  # bytes `progress-digest` holds.
  #
  # An argument is that same value when the CALLER already paid for the walk —
  # `gate_boundaries` computes it once for this boundary and for B5, which walk
  # the same ledger. Absent, this computes it itself so a direct caller (a test,
  # a probe) still works.
  local h="${1:-}" prev n nread nspent
  [ -n "$h" ] || h=$(gate_boundary_binding B1)
  prev=$(cat "$RUN_DIR/progress-digest" 2>/dev/null || true)
  n=$(cat "$RUN_DIR/progress-repeat" 2>/dev/null || printf '0')
  if [ "$h" = "$prev" ]; then
    n=$((n + 1))
  else
    n=0
    # The digest moved, so whatever B1 last asked about is no longer the state.
    # Clearing the marker is what lets the same digest ask again if it ever
    # comes back — a recurrence rather than the state a person already answered.
    rm -f "$RUN_DIR/boundary-B1.asked"
    # THE STRETCH THE READ CREDIT MEASURES BEGINS HERE, AND THIS IS THE ONLY
    # PLACE THAT KNOWS WHERE. `gate_b1_read_run` used to re-enumerate which row
    # kinds move the vector, which cannot be kept in step with a fold over
    # deduplicated segment ids, per-segment cycle counts and an obligation
    # identity set. Recording the ledger position at the moment the digest is
    # OBSERVED to move gives that stretch one definition.
    #
    # A RUN WITH NO RECORDED DIGEST YET STARTS AT ZERO. On the first evaluation
    # "the digest moved" and "nothing has been compared yet" are the same
    # observation, and taking the row count there would throw away the launch
    # burst this credit exists to forgive — a shift reads before it can declare
    # anything, so those reads are already on the ledger when the first judgment
    # is adjudicated.
    if [ -n "$prev" ]; then
      printf '%s\n' "$(gate_ledger_row_count)" > "$RUN_DIR/progress-origin"
    else
      printf '0\n' > "$RUN_DIR/progress-origin"
    fi
  fi
  printf '%s
' "$h" > "$RUN_DIR/progress-digest"
  printf '%s
' "$n" > "$RUN_DIR/progress-repeat"
  # The counter lives in the run directory and NOT in the hashed vector. Putting
  # it inside its own input is the original defect: raising it 0→1 changed the
  # hash and reset the very count being raised.
  [ "$n" -lt "$B1_STAGNATION_N" ] && return 0
  # ---- the bounded saturating read credit.
  #
  # A stretch of reconnaissance reads is forgiven while it is short. On the
  # cleanest real case a shift was launched, read twice, made one judgment, and
  # B1 fired 1 minute 48 seconds later — before the first non-read act and three
  # rows ahead of its own `segment` row. Across the corpus B1 was behaving as a
  # read-burst detector rather than a stagnation detector: in 58% of its firings
  # the row that moved the vector sat within two rows of the approval it had just
  # opened.
  #
  # AN EMPTY STRETCH IS NOT FORGIVEN. Nothing has been read since the last
  # progress move, so there is no burst to excuse — and a router spinning on
  # judgments alone is precisely the run this boundary exists for. Reading "made
  # of reads" as vacuously true of the empty stretch would silence B1 on it.
  #
  # A NON-READ AUTHORISATION IN THE STRETCH SPENDS ONE UNIT, exactly as a read
  # does, and does not void the stretch. The gate itself writes such rows on
  # the healthy path — the launch row of every shift it starts, the `결정=결과`
  # row of a `grep` that matched nothing — so a stretch that had to be made of
  # reads alone was never a read burst on any run the gate launched, and the
  # credit fired B1 at the same rows it was added to forgive. What stays is the
  # floor: at least one read must be in the stretch, so a router spinning on
  # judgments alone is not forgiven by rows that are nothing but judgments.
  #
  # THE CREDIT HAS NO KEY. Every key variant measured identically to a plain
  # count because the credit SATURATES at `C`, and the variants built from
  # existing fields measured worst — `세그먼트` and `절단점` barely move inside a
  # burst, so two thirds of the credit never gets issued. The count itself is
  # re-derived from the ledger rather than tallied.
  #
  # WHAT IT DOES STORE IS ONE POSITION, beside the two files written just above.
  # An earlier note here claimed the credit wrote nothing at all, which was never
  # true of the function it sits in, and the claim is what argued the stretch's
  # origin into a second copy of the vector's membership rule — the copy that
  # disagreed with it in three directions.
  # Two words on one line, read through a heredoc rather than `set --`: the
  # positional parameters are the act's argv here and must not be clobbered.
  # The read floor stands FIRST in the list so an empty value fails the test
  # (exit 2) toward issuing, never toward suppressing.
  nread=0; nspent=0
  read -r nread nspent <<EOF || true
$(gate_b1_read_run)
EOF
  if [ "$nread" -ge 1 ] && [ "$((nread + nspent))" -lt "$B1_READ_CREDIT" ]; then
    # THE TRACE GOES TO ITS OWN SERIES. `blocked` is read by B2, so writing there
    # would let this suppression move another boundary's input; and a suppression
    # that is frequent and silent is the one thing this boundary must not become.
    # The property the series name carries is that NO boundary reads it.
    gate_append '경계 억제' "경계=B1" "사유=읽기 크레딧" \
      "크레딧 잔량=$((B1_READ_CREDIT - nread - nspent))" "기록 시각=$(now_iso)"
    # A suppression, not a reset: `progress-repeat` is left alone, so a run that
    # really does stop once the reading ends still reaches the threshold on the
    # judgments that follow. This is the same shape as the live-stage carry in
    # B3, which defers a firing without removing it.
    return 0
  fi
  # Bound to the digest this predicate just compared — the value that, by
  # construction, has not moved for `n` judgments.
  gate_issue_boundary_approval B1 "진전 해시가 연속 ${n}회 판정 동안 불변입니다" "$h"
}

gate_b2_waiting() {
  # The obligations B2's current count is waiting on and that have not been
  # seen disposed since that count started — the window `gate_b2_obligations`
  # keeps, less `obligation-window-done` — one per line, sorted. B2's binding
  # value.
  #
  # Read from the files rather than recomputed from the open set, because the
  # open set is exactly the value a run can move for free. Between two restarts
  # the window is fixed and the done list only grows, so this value only
  # shrinks, and it shrinks exactly when a member of the window is seen disposed
  # — the event the count takes as progress. A member disposed and reopened
  # stays out: a value that could return to an earlier one would match the
  # marker an answered question left and hold the re-issue quiet.
  #
  # NOT LESS THE RUN LATCH, which is what it used to subtract. The latch keeps
  # an identity's first disposition for the whole run, so a window holding only
  # identities latched before it was taken — an excusal that lapsed when its
  # segment resumed — bound to the digest of the empty set for good. Once that
  # constant had been answered, every later B2 question carried it too and was
  # held quiet by the answered marker.
  local window wdone nl ident
  nl=$(printf '\n_'); nl=${nl%_}
  window=$(cat "${RUN_DIR:-}/obligation-window" 2>/dev/null || true)
  wdone=$(cat "${RUN_DIR:-}/obligation-window-done" 2>/dev/null || true)
  while IFS= read -r ident; do
    [ -n "$ident" ] || continue
    case "$nl$wdone$nl" in *"$nl$ident$nl"*) continue ;; esac
    printf '%s\n' "$ident"
  done <<GATE_B2_WAITING | LC_ALL=C sort
$window
GATE_B2_WAITING
}

gate_b2_window_observe() {
  # Append to `obligation-window-done` every member of B2's window that has a
  # disposition now. Called on every act from `gate_boundaries`, right after the
  # latch, and again at the head of `gate_b2_obligations`.
  #
  # PER ACT for the reason the latch gives: a disposition that holds only between
  # two judgments — an excusal walked back before the next one — is seen only if
  # every act looks. PER WINDOW, unlike the latch, so an obligation disposed once
  # before this window was taken still counts when it is disposed again inside
  # it. The list is emptied whenever the window is rewritten.
  #
  # The check-then-append takes no lock, as the latch's does not; a duplicate
  # line is harmless because every reader tests membership.
  local f wdone nl ident
  [ -n "${RUN_DIR:-}" ] && [ -s "$RUN_DIR/obligation-window" ] || return 0
  f="$RUN_DIR/obligation-window-done"
  nl=$(printf '\n_'); nl=${nl%_}
  wdone=$(cat "$f" 2>/dev/null || true)
  while IFS= read -r ident; do
    [ -n "$ident" ] || continue
    case "$nl$wdone$nl" in *"$nl$ident$nl"*) continue ;; esac
    [ -n "$(gate_obligation_disposition "$ident")" ] || continue
    printf '%s\n' "$ident" >> "$f"
  done < "$RUN_DIR/obligation-window"
  return 0
}

gate_b2_obligations() {
  # B2 catches the repeat defect B1 cannot. Fixing the same fault a different
  # way each time moves `head_sha`, so B1 never fires — but the obligation
  # multiset's elements are defined by IDENTITY, so however the patch differs
  # the element stays put. Progress means `|O|` genuinely fell, or an element
  # left and no element of the same identity came back.
  #
  # THAT DEFINITION IS NOW WHAT THE CODE DOES, and it was a digest equality. Any
  # change of the open set reset the counter — a set that GREW as well as one
  # that shrank — and once obligations could be closed the set became cheap to
  # move both ways: a new identity opened and closed again, or a parked segment
  # walked to `실행중` and back so its excusal lapsed and returned, reset the
  # count while another obligation stayed blocked for good. Before the closing
  # verbs a reset cost the run its termination condition 3; after them it cost
  # nothing.
  #
  # So progress is read against the WINDOW — the obligations this count is
  # waiting on — and the count restarts when a member of the window has been
  # seen disposed since the count started (`gate_b2_window_observe`). A new
  # identity is not progress, and neither is closing one: it is not in the
  # window, so it is not what this counter was waiting on.
  #
  # ON PROGRESS THE WINDOW SHRINKS TO ITS REMAINDER; it is not retaken from the
  # open set. Retaking it let a pair out of step by one judgment reset the count
  # on every judgment: open a new identity, close the window member left over
  # from the previous pair, and the restart put the new identity into the window
  # for the next judgment to close. The open set is taken only when the
  # remainder is empty — every obligation the count was waiting on has been
  # disposed, which is the progress this boundary exists to see — and when the
  # window is empty, which is also what the first evaluation of a run does. So
  # the resets a run can buy between two such points are bounded by the window's
  # size, whatever it opens and closes in between.
  #
  # A member is counted the first time it is seen disposed and leaves the
  # window then; walking its excusal back and forth afterwards moves nothing.
  # The run latch is not read here: it keeps an identity's first disposition for
  # the whole run, so an obligation excused once, resumed, and taken into a later
  # window could never count as progress however it was disposed — the window
  # froze, and with the answered marker never cleared B2 asked once per run.
  local window wdone curopen remain ident n progress=0 nl cur nwin=0 nrem=0
  nl=$(printf '\n_'); nl=${nl%_}
  gate_b2_window_observe
  curopen=$(gate_open_obligations | sed 's/^obligation=//')
  n=$(cat "$RUN_DIR/obligation-repeat" 2>/dev/null || printf '0')
  case "$n" in ''|*[!0-9]*) n=0 ;; esac
  window=$(cat "$RUN_DIR/obligation-window" 2>/dev/null || true)
  wdone=$(cat "$RUN_DIR/obligation-window-done" 2>/dev/null || true)
  remain=""
  while IFS= read -r ident; do
    [ -n "$ident" ] || continue
    nwin=$((nwin + 1))
    case "$nl$wdone$nl" in *"$nl$ident$nl"*) continue ;; esac
    nrem=$((nrem + 1))
    remain="$remain$ident$nl"
  done <<GATE_B2_WINDOW
$window
GATE_B2_WINDOW
  if [ "$nwin" -eq 0 ] || [ "$nrem" -lt "$nwin" ]; then progress=1; fi
  # The marker is cleared on progress, for the reason B1 gives: once the run has
  # moved, the same condition coming back is a recurrence the issuer must be
  # allowed to ask about again.
  if [ "$progress" = "1" ]; then
    n=0; rm -f "$RUN_DIR/boundary-B2.asked"
    if [ "$nrem" -eq 0 ]; then
      remain=$(printf '%s\n' "$curopen" | awk 'length($0) > 0')
      [ -z "$remain" ] || remain="$remain$nl"
    fi
    printf '%s' "$remain" > "$RUN_DIR/obligation-window"
    : > "$RUN_DIR/obligation-window-done"
  else
    n=$((n + 1))
  fi
  printf '%s\n' "$n" > "$RUN_DIR/obligation-repeat"
  [ "$n" -lt "$B2_OBLIGATION_M" ] && return 0
  [ -z "$(printf '%s' "$curopen" | tr -d '\n')" ] && return 0
  cur=$(gate_boundary_binding B2)
  # THE QUESTION TEXT SAYS 판정, NOT 사이클, and that is not cosmetic. `사이클` is
  # a declared row series in this contract, and `n` counts evaluations of this
  # function — the single production caller of the boundary set is the `act`
  # verb, so the unit is gate acts. Naming the row series here would have the one
  # sentence a person reads state a unit nothing counts. The sibling above
  # already spells it 판정.
  #
  # Bound to the window less the members seen disposed (`gate_b2_waiting`),
  # which moves exactly when this predicate's progress arm can fire; the
  # progress digest can move under an unchanged obligation set.
  gate_issue_boundary_approval B2 "의무 집합이 연속 ${n}회 판정 동안 진전 없이 그대로입니다" "$cur"
}

gate_b3_act_budget() {
  # Counts only `exec` acts graded above `읽기` since the last progress move.
  # Without that qualifier B3 fires on GRAMMAR: the argv-vector rule turns one
  # pipeline step into three gate calls, and the dry-run verbs exist so the
  # router never has to spend the budget finding out whether something passes.
  # `grep` with no match exits 1, `pipefail` promotes it, and `set -e` then
  # kills the whole gate on the ordinary case of "no exec acts yet" — silently,
  # with the exit status of a refusal and none of the message.
  #
  # THE WINDOW IS THE WHOLE POINT, AND IT USED TO BE MISSING. The sentence above
  # said "since the last progress move" while the count ran over the entire
  # ledger from the run's first row, so the budget was a LIFETIME cap wearing the
  # name of a window. Past it the boundary fired on every judgment for the rest
  # of the run — and because the count is in the message, and the message is in
  # the approval id, each firing opened a NEW pending approval rather than
  # re-opening one. Every pending approval blocks termination condition 1 and
  # can only be closed by a person, so a run that crossed the budget could not
  # be finished at all: each act needed to reach the end re-armed the thing
  # stopping it. Measured at 71 against a budget of 40.
  #
  # The reset mirrors B1 and B2 — a digest of the progress vector beside the
  # count it belongs to. What differs is what is stored: B1 counts repeats of an
  # unchanged digest, while this counts acts SINCE that digest last changed, so
  # the companion file holds the baseline the current total is measured from
  # rather than a repeat tally.
  local n total prev base h live
  # A LIVE STAGE IS NOT A SPINNING ROUTER, and this boundary is only about the
  # second. The preamble above says what it watches for in as many words — the
  # ROUTER burning acts without progress. The actor filter below already keeps a
  # stage's own rows out of `total`; what it does not do is keep a judgment made
  # WHILE a stage is alive from firing on whatever else the window holds, and
  # that is what this guard adds. The measurement below predates the `행위자`
  # field — it was taken when every act a dispatched stage authorised through
  # this gate landed in `total`, which is the count the filter now corrects.
  #
  # THE MISMATCH IS BETWEEN THIS BUDGET AND A STAGE'S LIFETIME, not between a
  # router and its budget. A stage moves the progress vector when it TERMINATES:
  # a review holds its segment at `리뷰중` from dispatch to completion, so a
  # multi-round review team publishes witnesses, mints nonces and drafts its
  # report for the whole of its run with the vector frozen. The window therefore
  # cannot close while the stage that is doing the work is doing it, and the
  # budget is exhausted by exactly the thing whose absence the boundary exists
  # to report.
  #
  # Measured on run 20260912-376f0543: the segment reached `리뷰중` at 15:01Z and
  # the review stage had authorised 84 acts by 15:36Z with the vector unmoved —
  # more than twice the budget, all of them the stage's own, none of them a
  # router. Five boundary approvals were raised across that night (three B1, two
  # B3) and a person answered every one of them `무효`. Unattended there is
  # nobody to answer, and each one ends the shift, so a review long enough to
  # cross this budget stops the night it is running in.
  #
  # SUPPRESSION ALONE DEFERS THE FIRING; IT DOES NOT REMOVE IT. This is the
  # defect the first version of this guard shipped with, and it is worth stating
  # rather than quietly fixing, because the shape recurs: a guard placed to skip
  # an evaluation removes nothing when the value being evaluated is DERIVED at
  # each call rather than carried across them.
  #
  # `total` is re-counted from the ledger every time, while `base` is a file.
  # Skipping the evaluation froze the file and left the count growing, so the
  # stage's acts were still owed — and the bill arrived one act later. The
  # sequence: the launch act records `base`, the stage authorises N acts under
  # the guard, the stage terminates, and the ROUTER's next act is where the
  # segment row actually moves. Boundaries are evaluated in that act BEFORE its
  # own row is appended (`gate_boundaries` runs ahead of the append and the
  # launch in the act path), and the rows a terminating stage does write —
  # `stage-result`, `문서 해시`, `cost` — are none of the progress vector's
  # inputs. So the key is unchanged, no re-baseline happens, and `n` is the
  # stage's whole run. Reproduced on a fixture: 41 acts under a live stage, then
  # the first router act after it ended fired with `live=0`.
  #
  # So the guard CARRIES THE BASELINE FORWARD instead of skipping past it. Every
  # suppressed evaluation moves `base` to `total` and records the current key,
  # which makes the stage's acts spent history rather than deferred debt: the
  # window that matters reopens at the moment the stage ends. B1 needs no such
  # move because its counter lives in a file and simply is not incremented while
  # suppressed — same intent, different bookkeeping, and copying B1's shape
  # without its storage is what produced the deferral.
  #
  # WHAT THIS COSTS IS REAL AND IS NOT NOTHING. A stage that is alive and
  # spinning through this gate — a retry loop, say — was caught by this arm and
  # now is not. No other arm takes it: every liveness-watcher arm requires zero
  # live stages, and each of those acts grows the ledger so the watcher's
  # idleness never accrues either. That blind spot is filed separately; it is
  # bought deliberately here, because the alternative measured worse — the arm
  # stopped an unattended night on every long review, and it could not tell a
  # spinning stage from a working one in the first place.
  #
  # THE SAME SPELLING B1 USES, `gate_live_stages`, because two spellings of one
  # predicate sitting in neighbouring arms read as two predicates. It counts
  # PROCESSES, NOT PID FILES (`liveness.sh`, sourced at the top of this file), so
  # a stage that died without cleaning up does not keep the boundary suppressed.
  # Positively selected, matching the progress vector: the grade must be present
  # and must not be `읽기`. Excluding `읽기` alone also counts a row carrying no
  # grade at all, and here that spends budget on an act nobody established was
  # above a read.
  total=$(gate_b3_exec_total)
  # THE WINDOW KEY EXCLUDES THIS COUNTER'S OWN INPUT, and getting that wrong is
  # how the boundary was silently disarmed once already.
  #
  # `total` above USED TO BE byte-for-byte the same pipeline as the vector's
  # `acts=` line, so keying the window on the full progress digest put the
  # count inside its own hash input and BOTH branches yielded zero: when
  # `total` moved the digest moved, the baseline was reset to `total`, and `n`
  # was 0; when `total` did not move the baseline already equalled it, and `n`
  # was 0 again. The boundary then could not fire on any input at all. Measured
  # on a live run: baseline 72 against a budget of 40, and `n` was 0.
  #
  # That is the counter-inside-its-own-hash defect this file names in
  # `gate_progress_vector`'s preamble and keeps B1's counter in the run
  # directory to avoid. Spending budget is not the kind of progress that should
  # open a new window — if it were, no amount of spending could ever exhaust
  # one — so the key is named per predicate, as the vector less this counter's
  # own input, and that is what `gate_boundary_binding B3` returns.
  #
  # THE VECTOR NO LONGER CARRIES `acts=` AT ALL — it carries `dispatches=`,
  # which this count does not touch — so that exclusion alone would leave the
  # key equal to the full progress digest. The per-predicate spelling is kept
  # regardless: the binding value is the caller's to name, and a component
  # added to the vector later that does derive from this count is excluded
  # there without anyone having to remember why.
  #
  # THE OBLIGATION COMPONENT COMES OUT TOO, for a reason of a different kind. It
  # is not this counter's own input; it is the component a run can move for free.
  # Opening a problem row under a new identity changes the open set and therefore
  # this key, so a fresh window opens — and the act that opens it grades `읽기`,
  # so it spends no budget at all. Measured: one problem row per cycle mixed with
  # reads kept the boundaries silent past 122 acts with termination condition 3
  # holding throughout, and that run was cut by a harness time limit rather than
  # by any ceiling. With the component removed the three evasion shapes all fire
  # again at the control value of 41.
  #
  # THE FREQUENCY ARGUMENT DOES NOT DECIDE THIS. Of 660 observed window openings
  # only 2 were opened by obligations, and a separate decision in this design
  # DECLINES to redesign the clause and segment components that account for far
  # more. The axis that separates them is not how often each fires but whether
  # THIS design makes the path cheaper: the obligation-closing verbs are what
  # turn opening into an open-and-close cycle, so this is a path this slice
  # created and closes, while clause repetition and segment toggling are
  # unchanged before and after and are carried as declared residuals.
  #
  # `B1`'s `gate_progress_digest` is deliberately NOT changed. This decision is
  # about B3's window key alone.
  h=$(gate_boundary_binding B3)
  # THE LIVE-STAGE CARRY. Placed after `total` and `h` rather than before them so
  # the two values have ONE spelling — the suppressed path and the measuring path
  # must agree on what they are, and a second copy of either pipeline is how they
  # would stop agreeing.
  #
  # A key that moved while the stage ran opens a new window exactly as it does
  # on the measuring path below, so the answered marker is cleared here too.
  # Writing the new key without clearing it would leave the measuring path
  # nothing to compare against once the stage ends, and a marker from the old
  # window would outlive the window it belonged to.
  #
  # THIS IS A COUNT STOP, NOT A SKIP: the baseline advances to `total`, so what a
  # stage piles up is spent history rather than a lump billed to the router on
  # the first evaluation after live falls to zero, and the window is kept rather
  # than reset, so launching a stage is not a budget-reset button. Six candidates
  # were replayed against real ledgers: copying B1's guard — skipping the whole
  # boundary while a stage is live — left the worst window at 74 with 5 of 43
  # ledgers over budget, while stopping the count and keeping the window put the
  # worst window at 9 and over-budget ledgers at 0 of 43. A finite wall-clock cap
  # was rejected on the same replay, because stage duration runs to a 39-minute
  # median with 165 at the 90th percentile, so every finite cap returns the worst
  # window to 100.
  #
  # FAIL-CLOSED ON THE LIVE READING. `[ "$(gate_live_stages)" != "0" ]` reads TRUE
  # for an empty value, so losing the signal would stop the count — a boundary
  # that switches itself off when it cannot see is the same class of defect this
  # carry exists to remove. Only a positive integer stops it; anything else keeps
  # counting and lets the boundary fire.
  live=$(gate_live_stages)
  case "$live" in
    ''|*[!0-9]*|0) : ;;
    *)
      prev=$(cat "$RUN_DIR/act-budget-digest" 2>/dev/null || true)
      [ "$h" = "$prev" ] || rm -f "$RUN_DIR/boundary-B3.asked"
      printf '%s\n' "$h"     > "$RUN_DIR/act-budget-digest"
      printf '%s\n' "$total" > "$RUN_DIR/act-budget-base"
      return 0 ;;
  esac
  prev=$(cat "$RUN_DIR/act-budget-digest" 2>/dev/null || true)
  base=$(cat "$RUN_DIR/act-budget-base" 2>/dev/null || printf '0')
  # Progress moved: this act is the first of a new window, so the acts before it
  # are spent history and the baseline becomes the total as of now.
  if [ "$h" != "$prev" ]; then
    base="$total"
    printf '%s\n' "$h"     > "$RUN_DIR/act-budget-digest"
    printf '%s\n' "$base"  > "$RUN_DIR/act-budget-base"
    # A new window: the budget a person released under the old key is spent
    # history, and the marker that kept its answered id quiet goes with it.
    rm -f "$RUN_DIR/boundary-B3.asked"
  fi
  n=$((total - base))
  [ "$n" -lt "$B3_ACT_BUDGET" ] && return 0
  # Bound to the window key — the progress digest, which no longer carries the
  # exec count — because that is the value that opens and closes the window
  # this count lives in. Salting with a digest that contained the count put the
  # count inside the id: every act over budget then minted a new approval,
  # which is the run-cannot-finish loop above.
  gate_issue_boundary_approval B3 "마지막 진전 이후 읽기 초과 exec 가 ${n}회입니다" "$h"
}

gate_b3_exec_total() {
  # Positively selected, matching the progress vector: the grade must be present
  # and must not be `읽기`. Excluding `읽기` alone also counts a row carrying no
  # grade at all, and here that spends budget on an act nobody established was
  # above a read. One function because the rebaseline after a resolved B3 has to
  # measure the same total the boundary compares against — a rebaseline that
  # counted differently would set a baseline the boundary's own total can sit
  # below or above for the rest of the window.
  #
  # ON THE FIELD BOUNDARY, like the progress vector — but the SET is different
  # and deliberately so. The budget counts every act that is not a read, `등급
  # 미상` included: a command the table cannot read still spends the run's
  # terminal-act budget, and a `bash` loop that never gets graded is exactly what
  # the budget exists to bound. Progress excludes it because an unreadable row is
  # not evidence that anything moved; a budget is not evidence of anything. The
  # anchoring is load-bearing now that the exec row carries an `argv=` excerpt:
  # the substring form matched the text `축2=읽기` wherever it appeared, so an
  # excerpt quoting a read declaration silently removed a write row from the
  # budget.
  #
  # AND THE ACTOR MUST BE THE ROUTER'S, by the same positive selection the
  # vector's `dispatches=` applies: the row carries `행위자` and its value is not
  # `스테이지`. This is the router's budget — the window opens on the ROUTER's
  # progress and B3 is evaluated on the router's judgment — but a stage sends
  # every one of its Bash lines through this gate, and most of what a working
  # stage runs grades above `읽기` (`sed`, `cp`, `mkdir`, `install` are all
  # `워크트리쓰기`), so an unfiltered count was dominated by the constrained side
  # while the window key deliberately excluded the rows that side wrote.
  # Measured: a read-only review team of three spent the whole 40 and fired
  # this boundary against a router that had done nothing. Rows written before
  # the field existed carry no `행위자` and contribute nothing — the same safe
  # direction as the vector, and it means a ledger from before the field cannot
  # fire this boundary on history.
  #
  # CALL IT, NEVER CARRY IT. Three sites write `act-budget-base` — a resolved
  # approval, a live stage's carry, and the window key moving — and what keeps
  # them from fighting is not that they agree on a value but that each derives
  # this count AT THE MOMENT IT WRITES. The ledger is append-only, so the count
  # is monotonic, so whichever site writes last writes a watermark no lower than
  # the others and the boundary simply counts again from there. No double
  # subtraction, no negative `n`, and the order the sites fire in does not
  # matter.
  #
  # That property is what a later change would break by hand. Compute this once
  # and pass it across a call boundary, or narrow the population it counts, and a
  # stale total can land after a fresh one — `base` then moves BACKWARDS and `n`
  # jumps by the difference, stepping over the budget without ever equalling it.
  # The three sites look like they merely share a helper; they actually share a
  # timing discipline, and only the second one is load-bearing. The actor filter
  # above is part of this one population, not a narrowing any site applies on
  # its own, so all three still count the same rows.
  #
  # THE DECISION FIELD IS ANCHORED TOO. `--rationale` reaches the row as `근거=`
  # untransformed, so an unanchored `결정=exec` matches text the router writes
  # freely. `gate_append` maps `|` out of every key and every value, so the
  # delimiter form cannot be forged.
  { gate_rows '자율 승인' | grep -F ' | 결정=exec | ' || true; } \
    | { grep -E '\| 축2=[^|]+ \|' || true; } \
    | { grep -vE '\| 축2=읽기 \|' || true; } \
    | { grep -F '| 행위자=' || true; } \
    | { grep -vF '| 행위자=스테이지 |' || true; } | gate_count
}

gate_cost_figure_ok() {
  # gate_cost_figure_ok <값> — true when the value reads as a plain decimal
  # figure, which is the only form `gate_b4_percent`'s arithmetic can consume.
  #
  # `awk` coerces a string with a non-numeric head to 0, the percentage comes
  # out 0, and the boundary returns without a word — so `$50`, `USD 50`, `약 50`
  # and `50달러` were ceilings in name only, while `50 USD` survived on its
  # numeric prefix. One field deciding differently by spelling is worse than one
  # deciding not at all, because nothing in the run distinguishes the two.
  #
  # Spelled once so the boundary and every reader of "is this axis bounded"
  # cannot disagree about which values are figures.
  case "$1" in
    ''|*[!0-9.]*) return 1 ;;
  esac
  case "$1" in
    *.*.*|*.) return 1 ;;
  esac
  return 0
}

gate_b4_percent() {
  # The spent share of the declared cost ceiling as an integer percentage, or
  # nothing when no ceiling is declared or nothing has been spent.
  local declared spent
  declared=$(manifest_field '인가' '비용 천장')
  # `(없음)` joins the undeclared spellings because the kickoff template writes
  # a field it has no value for that way, and a parenthesised placeholder is not
  # a ceiling.
  case "$declared" in ''|없음|'(없음)') return 0 ;; esac
  # A VALUE THAT WILL NOT READ IS NOT A CEILING, AND SAYING SO IS THE POINT.
  # Returning in silence is what this arm used to do, and it left a run believing
  # it had a bound on an axis that has since become one of the things that can
  # end it.
  if ! gate_cost_figure_ok "$declared"; then
    warn "could not read \`비용 천장\` as a number ($declared) — this boundary is not enforced. Write the number only, with no currency symbol and no unit"
    return 0
  fi
  spent=$(gate_rows 'cost' | tail -1 | tr '|' '
' | sed -n 's/^ *누적 usd=//p' | sed 's/[[:space:]]*$//' | tail -1)
  [ -n "$spent" ] || return 0
  awk -v s="$spent" -v d="$declared" 'BEGIN{ if (d+0==0) print 0; else printf "%d", (s/d)*100 }'
}

gate_b5_stagnation_bound() {
  # THE SECOND PROGRESS AXIS, AND THE ONE B1 CANNOT BE. B1 counts exactly this —
  # consecutive router judgments over an unmoved progress digest — and asks. This
  # counts the same thing and ENDS the run. The two differ in disposition and in
  # one structural way that is the whole reason for a second counter.
  #
  # B1..B3 ARE SUPPRESSED WHILE AN ACT-CLASS APPROVAL IS PENDING, and B1's own
  # firing is what opens one. So under manual resolution B1 asks at its
  # threshold, the approval stays open because nobody is awake, and from that
  # moment `progress-repeat` stops advancing — the counter freezes at exactly the
  # value that opened the question. A bound layered on that counter would never
  # be reached. This one is evaluated beside B4, outside the suppression, so it
  # keeps counting while the question waits.
  #
  # THE DIGEST IS B1'S, NOT A VARIANT. An earlier form of this filtered `acts=`
  # out of the progress vector, because that component counted read-exceeding
  # exec calls and was therefore the counter's own input — a counter inside its
  # own hash input never advances. The vector no longer carries `acts=`; it
  # carries `dispatches=`, which counts observed stage outcomes and is not moved
  # by the call being judged. With the reason gone the filter is gone, and both
  # boundaries read the same value — which is what lets "B1 asked and B5 ended"
  # be one story about one number rather than two numbers that can disagree.
  #
  # THE JUDGMENT PREDICATE IS THE CALLER'S, AND SO IS THE DIGEST. `gate_boundaries`
  # already decides what counts as a router judgment (not a stage, grade above
  # read, kind not `skill` or `router-shift`), and it computes the progress
  # digest once for both this boundary and B1 — a second copy of either would be
  # a second place for them to drift apart, and the digest walk is not cheap.
  # An absent argument falls back to computing it, so a direct caller works.
  # An argument is the digest the caller already paid for — same arrangement
  # as B1.
  local bound h="${1:-}" prev n
  bound=$(manifest_field '인가' '무진전 상한')
  case "$bound" in ''|없음|'(없음)') return 0 ;; esac
  # AN UNREADABLE BOUND WARNS AND DOES NOT ENFORCE, the same disposition the cost
  # ceiling takes. Silence would leave a run believing it had a bound on the one
  # axis still able to end it.
  case "$bound" in *[!0-9]*)
    warn "could not read \`무진전 상한\` as an integer ($bound) — this boundary is not enforced. Write the judgment count as a number only"
    return 0 ;;
  esac
  [ -n "$h" ] || h=$(gate_boundary_binding B5)
  prev=$(cat "$RUN_DIR/stagnation-digest" 2>/dev/null || true)
  n=$(cat "$RUN_DIR/stagnation-repeat" 2>/dev/null || printf '0')
  if [ "$h" = "$prev" ]; then n=$((n + 1)); else n=0; fi
  printf '%s\n' "$h" > "$RUN_DIR/stagnation-digest"
  printf '%s\n' "$n" > "$RUN_DIR/stagnation-repeat"
  [ "$n" -lt "$bound" ] && return 0
  gate_end_run B5 "진전 해시가 라우터 판정 연속 ${n}회 동안 불변입니다 (상한 ${bound})"
}

gate_b4_cost() {
  # TWO THRESHOLDS ON ONE FIGURE. 80% opens a boundary approval — a person, if
  # there is one, gets to decide. 100% ENDS THE RUN, and it must, because the
  # ceiling is one of the two bounds that keep a router run finite: the wall
  # clock no longer ends a run that declares either of them, and an approval
  # nobody answers is not a bound.
  local declared spent pct resolved
  declared=$(manifest_field '인가' '비용 천장')
  # The undeclared spellings are the same vocabulary the percentage helper uses.
  case "$declared" in ''|없음|'(없음)') return 0 ;; esac
  spent=$(gate_rows 'cost' | tail -1 | tr '|' '
' | sed -n 's/^ *누적 usd=//p' | sed 's/[[:space:]]*$//' | tail -1)
  [ -n "$spent" ] || return 0
  pct=$(gate_b4_percent)
  # AN UNREADABLE CEILING YIELDS NO PERCENTAGE, and comparing an empty string
  # here is a shell error rather than a decision. The helper already warned.
  [ -n "$pct" ] || return 0
  [ "$pct" -lt 80 ] && return 0
  # 100% ENDS THE RUN RATHER THAN ASKING, and it is checked BEFORE the re-ask
  # suppression below. Suppression exists so a granted B4 is not asked again
  # every act; ending the run is not a question, so letting suppression reach it
  # would turn a bound into a thing a single grant switches off for good.
  if [ "$pct" -ge 100 ]; then
    gate_end_run B4 "비용이 선언 천장에 닿았습니다 (${spent}/${declared})"
    return 0
  fi
  # B4 has no counter to restart, so a resolution records the share it was
  # answered at, and the same question is not asked again until spending has
  # climbed another ten points past it. Without that, a granted B4 re-opened on
  # the next act whose progress digest had not moved.
  resolved=$(cat "$RUN_DIR/cost-resolved-pct" 2>/dev/null || true)
  case "$resolved" in
    ''|*[!0-9]*) : ;;
    *) [ "$pct" -lt $((resolved + 10)) ] && return 0 ;;
  esac
  # B4 HAS NO BINDING VALUE OF ITS OWN YET. It holds one integer percentage and
  # one threshold; a bucket tier would need a bucket width, and no width can be
  # validated against a boundary that has never fired in the corpus. So the
  # shape changes with its siblings — the caller passes the value — and the
  # value stays today's progress digest until a width is decided. When it is,
  # this one argument changes and nothing else does.
  gate_issue_boundary_approval B4 "비용이 선언 천장의 ${pct}%% 입니다 (${spent}/${declared})" "$(gate_boundary_binding B4)"
}

gate_dismissal_observed() {
  # 0 when this run's transcript lineage holds an `is_error` `tool_result` whose
  # content carries the harness's dialog-dismissal text, 1 when it demonstrably
  # does not, and 2 when the question could not be READ.
  #
  # THREE VALUES AND NOT TWO. Every `jq` failure used to become zero hits, so an
  # unreadable line answered "no dismissal was seen" — fail-OPEN, and on the very
  # lines a `grep -F` had already proved carry the dismissal text. The realistic
  # trigger is not a missing parser but a TORN last line: the harness is still
  # appending while this reads, so the tear is checked first, before any search,
  # for the reason `gate_transcript_torn` states — a search over a torn file
  # decides on the lines ahead of the tear as though they were the file. An
  # unreadable verdict is not an absent one, and the caller treats it as a
  # refusal: that is the direction `gate_withdraw_stale_boundaries` already
  # declares for a binding tuple it cannot re-derive.
  #
  # The sibling refusal (rule 2) needs no parser at all — it is a `grep -F` for
  # `"answers":{` — so without this the two rules that the comment below calls
  # two faces of one question gave different answers the moment `jq` stumbled.
  #
  # NOTHING IS STORED, AND THAT IS WHY THIS CARRIER WAS CHOSEN. "A dismissal was
  # seen" has to reach the withdrawal, which fires at a separate moment, and
  # there were three candidate carriers: a new ledger series, a marker in the run
  # directory, and a predicate that re-reads the transcript when asked. A new
  # series would have to be READ by the withdrawal — and the series this slice
  # adds is one whose whole load-bearing property is that no boundary reads it,
  # so the two could not be the same series and an eighteenth is out of scope. A
  # run-directory marker has no defined lifetime across a shift and no way to be
  # adjudicated against the transcript when the two disagree. A predicate that
  # stores nothing cannot disagree with the transcript.
  #
  # THE WINDOW IS THIS RUN'S LINEAGE, WHICH IS WIDER THAN "THIS CYCLE" ON
  # PURPOSE. The cycle boundary is undefined, and the sibling rule — an answer
  # frame refuses the withdrawal — already measures existence over THIS RUN
  # rather than over a cycle or the whole transcript directory. The two rules are
  # two faces of one question, whether a person was there, so a window split
  # between them would leave the same evidence visible to one and invisible to
  # the other. Wider means the withdrawal is refused more often, which is the
  # side away from the failure it exists to prevent: discarding an answer
  # somebody is in the middle of giving.
  #
  # THE TEXT AND THE ERROR FLAG ARE READ OFF THE SAME BLOCK, not merely the same
  # line. A line-level conjunction would also match the router quoting the string
  # into its own output, and while that error is in the refusing direction it
  # would make the predicate true for the rest of the run once quoted.
  local f line hit rc
  if gate_transcript_torn; then return 2; fi
  for f in $(gate_transcript_files || true); do
    [ -f "$f" ] || continue
    while IFS= read -r line; do
      [ -n "$line" ] || continue
      rc=0
      hit=$(printf '%s' "$line" | jq -r --arg t "$GATE_DISMISSAL_TEXT" '
        [ .message.content[]? | select(type == "object" and .type == "tool_result")
          | select(.is_error == true)
          | select((.content | tostring) | contains($t)) ] | length' 2>/dev/null) || rc=$?
      [ "$rc" = "0" ] || return 2
      case "$hit" in ''|*[!0-9]*) return 2 ;; esac
      [ "$hit" != "0" ] && return 0
    done <<EOF
$( { grep -F "$GATE_DISMISSAL_TEXT" "$f" 2>/dev/null || true; } )
EOF
  done
  return 1
}

gate_withdraw_boundary_approval() {
  # gate_withdraw_boundary_approval <승인 id> <사유> — move an OPEN boundary
  # approval to `철회` because the condition that raised it went away.
  #
  # THE STATE IS `철회` AND NOT `만료`, AND THERE IS NO CLOCK. A clock makes this
  # a timeout, and a timeout discards a question that is still true. The trigger
  # is the disappearance of the raising condition, and the caller names which
  # condition in `사유=` rather than leaving a reader to infer it.
  #
  # THE ROUTER HAS NO SURFACE ONTO THIS. It is reached from the boundary
  # evaluation and from nowhere else, and `gate_main` gains no verb for it. The
  # foundation this design rests on is that the router cannot type an answer, and
  # a router-callable withdrawal would route around that foundation with one new
  # verb rather than break it head-on. Rules (2) and (3) below do not close that
  # path — they are about evidence, not about who is calling — so it is closed
  # structurally instead.
  #
  # TWO REFUSALS, BOTH ASKING THE SAME QUESTION: WAS A PERSON THERE?
  #   (2) an answer frame exists for this id — somebody answered, and withdrawing
  #       would throw their answer away; and its unanswered twin, a question that
  #       was PUT and has no result frame yet, which is a dialog still on screen
  #       and is refused on the same ground
  #   (3) a dialog dismissal was observed — somebody was at the screen and closed
  #       the dialog without choosing, which is evidence of presence exactly as
  #       an answer is
  # AN INTERRUPT AND AN `is_error` OF UNOBSERVED CAUSE ARE NOT EVIDENCE OF
  # PRESENCE and do not refuse. Folding those into the dismissal case is the
  # distinction `gate_close` keeps two separate warnings for, and collapsing the
  # three into two is what would make rule (3) unfalsifiable.
  local id="$1" reason="$2" st dm
  st=$(gate_approval_state "$id")
  [ "$st" = "대기" ] || return 0
  # THE TWO PREMISES `gate_close` PUTS AHEAD OF EVERY FRAME READ ARE ITS OWN AND
  # ARE REUSED HERE RATHER THAN RE-DERIVED. Rules (2) and (3) are evidence tests,
  # and an unreadable transcript yields no evidence in either direction — but the
  # frame reader cannot say so. `gate_frame_candidate` returns `none` both when
  # it looked and found nothing and when there was nothing to look at, so "we did
  # not see" and "we saw and there was none" arrived here as one value and both
  # allowed the withdrawal. Holding is the refusing direction, which is what this
  # path already declares for a binding tuple it cannot re-derive.
  if [ -z "$(gate_transcript_files || true)" ]; then
    warn "the withdrawal of approval $id is held — the transcript could not be found, so whether a person was there cannot be read"
    return 0
  fi
  if gate_transcript_torn; then
    warn "the withdrawal of approval $id is held — the last line of the transcript is not complete (judgment held)"
    return 0
  fi
  gate_frame_candidate "$id" || true
  # THE QUESTION IS WHETHER THE DIALOG REACHED A SCREEN, AND TESTING `answers`
  # ALONE ANSWERED IT FOR ONE OF THE THREE KINDS THAT SAY IT DID. `asked` is an
  # `AskUserQuestion` carrying this id whose `tool_result` has not arrived — a
  # dialog that is up and unanswered, which is the state a withdrawal must not
  # walk past, and it walked past it: the row went to `철회`, the banner came off
  # and the seat went back while somebody was looking at the question.
  #
  # `result` FALLS THROUGH ON PURPOSE rather than refusing here. Its causes are
  # what rules (2) and (3) exist to tell apart, and the design puts an interrupt
  # and an `is_error` of unobserved cause on the permitting side; refusing on the
  # kind would collapse all three causes into one and delete that distinction.
  #
  # `other` AND `none` DO NOT REFUSE, and folding them in — the whole-vocabulary
  # reading of "refuse unless `none`" — would close the withdrawal entirely.
  # `other` is a line that carries the id and joins to no `AskUserQuestion` at
  # all: the router's own tool output echoing the ledger, which happens on every
  # ledger read the router makes, so from the first such read onward no boundary
  # approval could ever be withdrawn again. It is also the wrong reading of the
  # evidence — no question bearing this id was ever put, so there was nobody
  # there to answer it.
  case "$GATE_FRAME_KIND" in
    answers)
      warn "the withdrawal of approval $id is refused — there is an answer frame in this run (an approval a person answered is not swept away because the condition disappeared)"
      return 0 ;;
    asked)
      warn "the withdrawal of approval $id is refused — the question was asked and there is no response frame yet (it is an unanswered dialog sitting on the screen)"
      return 0 ;;
  esac
  dm=0
  gate_dismissal_observed || dm=$?
  case "$dm" in
    0)
      warn "the withdrawal of approval $id is refused — a dialog cancellation was observed in this run (that is evidence a person was at the screen)"
      return 0 ;;
    1) ;;
    *)
      warn "the withdrawal of approval $id is held — the cancellation observation could not be read (unjudged does not mean no cancellation)"
      return 0 ;;
  esac
  # No `응답 토큰` and no `답변 다이제스트`: rule (2) has just established that no
  # answer frame exists, so a `-` in either slot would be a value recorded with
  # nothing to compare it against — the defect class this contract removes.
  gate_append '승인' "승인 id=$id" "상태=철회" \
    "질문 문면=$(gate_approval_field "$id" '질문 문면')" \
    "답변 문면=-" "사유=$(gate_row_safe "$reason" "$GATE_REASON_EXCERPT")" \
    "사이드카 앵커=$(gate_approval_sidecar_anchor "$id")" "해소 시각=$(now_iso)"
  # A withdrawn approval is equally done being waited on, so the seat goes back
  # and the banner comes off. `gate_close` does the same at each of its terminals.
  gate_close_settle "$id"
  log "승인 철회 — $id ($reason)"
}

gate_withdraw_stale_boundaries() {
  # Every OPEN boundary approval whose binding value has moved: the question it
  # asked is about a condition that no longer holds.
  #
  # THE BINDING VALUE IN THE ROW IS WHAT MAKES THIS POSSIBLE WITH NO NEW STORAGE.
  # Each boundary approval carries `구속 튜플=<경계 이름>/<결속값>`, and that value
  # is the one the boundary's own predicate decided on — so re-deriving it now
  # through the shared helper and comparing is the whole test.
  #
  # ONLY B1..B3, AND B4 IS OUT FOR THE SAME REASON THE LAUNCHER'S FLOOR APPROVAL
  # IS. The floor approval shares this series and this id shape, but its raising
  # condition is a context measurement rather than a boundary predicate, so there
  # is no binding to re-derive for it and it is left alone rather than withdrawn
  # on a value this function would have to invent. B4's value is invented in
  # exactly that sense: it has no binding of its own yet and carries the progress
  # digest until a bucket width is decided, while its raising condition is an
  # integer percentage the progress vector deliberately excludes. Withdrawing on
  # it therefore fires on any ordinary commit or push while the cost is still
  # over the ceiling — recording `사유=비용 비율 변동` for a ratio that did not
  # move — and `gate_b4_cost` runs OUTSIDE the pending gate, so the same call
  # re-issues. The id is salted with the binding, so each re-issue mints a
  # DIFFERENT id that duplicate suppression cannot see: pending approvals that
  # only a person can close grow without bound, and every one of them blocks the
  # run from ending. B3 shipped this same defect once and was fixed by changing
  # what it salts. B4 joins here when its own predicate decides a value, and the
  # one call site that changes is `gate_b4_cost`'s argument.
  #
  # AN UNREADABLE OR ABSENT TUPLE IS NOT A MOVED CONDITION. Skipping is the
  # refusing direction: the approval stays open and a person still sees it.
  #
  # gate_withdraw_stale_boundaries <pending ids> — 0 when at least one approval
  # was actually withdrawn, so the caller knows whether its list went stale. The
  # ids are passed in rather than re-derived: the caller has just enumerated them
  # and that enumeration walks the whole ledger once per id.
  # The argument is optional so the predicate can also be driven on its own; an
  # ABSENT argument enumerates, an EMPTY one means "the caller looked and found
  # none". Collapsing those two would make the caller's empty answer trigger a
  # second walk of the ledger, which is the cost this argument exists to avoid.
  local ids id name binding cur did=1
  if [ "$#" -ge 1 ]; then ids="$1"; else ids=$(gate_pending_approval_ids act); fi
  for id in $ids; do
    case "$id" in
      B1-*|B2-*|B3-*) ;;
      *) continue ;;
    esac
    name="${id%%-*}"
    binding=$(gate_approval_field "$id" '구속 튜플')
    case "$binding" in "$name"/*) binding="${binding#"$name"/}" ;; *) continue ;; esac
    [ -n "$binding" ] || continue
    cur=$(gate_boundary_binding "$name") || continue
    [ -n "$cur" ] || continue
    [ "$cur" = "$binding" ] && continue
    gate_withdraw_boundary_approval "$id" "$(gate_boundary_withdraw_reason "$name")"
    # The withdrawal can REFUSE — rules (2) and (3) — so whether the caller's list
    # went stale is read off the state rather than assumed from having called.
    [ "$(gate_approval_state "$id")" = "철회" ] && did=0
  done
  return "$did"
}

gate_boundary_withdraw_reason() {
  # The named condition whose disappearance withdrew a boundary approval. Named
  # per boundary rather than left to one generic string: `사유` is the only field
  # on a `철회` row that says WHY, and "조건 소멸" repeated three times would make
  # the field as uninformative as the clock this state replaced.
  #
  # B4 HAS NO ARM HERE BECAUSE IT IS NOT WITHDRAWN. It carries a borrowed
  # binding, so a `비용 비율 변동` arm would name a condition the withdrawal
  # never actually measured — and a named reason for a boundary that does not
  # participate reads, to anyone auditing coverage, as though it did. B4 gets one
  # back when its own predicate decides a value.
  case "$1" in
    B1) printf '진전 재개' ;;
    B2) printf '의무 집합 변동' ;;
    B3) printf '창 키 이동' ;;
    *)  printf '조건 소멸' ;;
  esac
}

gate_disposition_latch() {
  # The run-scoped, append-only set of obligations that have EVER been disposed,
  # one `<처분>\t<동일성>` line each, first disposition wins.
  #
  # THE LATCH EXISTS FOR THE EXEMPTION COMPONENT. `종결` and `포기` are rows, so
  # they only ever accumulate; `면제` is a PREDICATE re-evaluated on every call
  # that re-reads segment state, and segment state is reversible. So the exemption
  # count can FALL, and the word "cumulative" is not true of it without this file.
  # Unlatched, the boundary is evaded by walking a parked segment back to `실행중`
  # one row before the threshold and parking it again: the exemption count drops,
  # termination condition 3 comes back, and only the counter has been reset.
  #
  # Latching every disposition rather than the exemption alone also removes the
  # double count — an identity excused first and closed later would otherwise be
  # a latch line AND a row.
  # READ ONLY. The writer is `gate_disposition_latch_update` and the split is
  # deliberate: the morning status render reads this, and a render that latched
  # would be a read verb with a side effect on the state it reports.
  #
  # FIRST LINE PER IDENTITY. The writer's check-then-append is not under a lock,
  # and it now runs on every act, so a router and a stage acting at once can both
  # append the same identity. Reading only the first line for each keeps "first
  # disposition wins" true and keeps the counts from doubling.
  { cat "${RUN_DIR:-}/obligation-latch" 2>/dev/null || true; } \
    | LC_ALL=C awk '{ i = index($0, "\t"); k = (i > 0) ? substr($0, i + 1) : $0
                      if (length($0) > 0 && !seen[k]++) print }'
}

gate_disposition_latch_update() {
  # Append any identity that now has a disposition and is not already latched.
  # Called from `gate_boundaries` — which runs on every act, ahead of the
  # boundaries that read the latch — and once more when the run writes its
  # terminal marker.
  #
  # PER ACT, AND IT USED TO BE TERMINAL ONLY. The sentence above was here while
  # the only production caller was the terminal report, so the morning render's
  # disposition counts read `0 · 0 · 0` for the whole run, and an excusal that
  # held mid-run and lapsed before the end was never latched — the walk-back
  # this file exists to stop.
  local latch="${RUN_DIR:-}/obligation-latch" ident d tab latched nl
  [ -n "${RUN_DIR:-}" ] && [ -d "$RUN_DIR" ] || return 0
  tab=$(printf '\t')
  nl=$(printf '\n_'); nl=${nl%_}
  # MEMBERSHIP IS THE WHOLE IDENTITY. `grep -F "<tab><identity>"` anchored the
  # start and not the end, so once `P0-ab` was latched `P0-a` read as latched too
  # and its disposition never reached the counts or the terminal enumeration.
  latched=$(gate_disposition_latch | cut -f2-)
  gate_problem_identities | while IFS= read -r ident; do
    [ -n "$ident" ] || continue
    case "$nl$latched$nl" in *"$nl$ident$nl"*) continue ;; esac
    d=$(gate_obligation_disposition "$ident")
    if [ -n "$d" ]; then printf '%s%s%s\n' "$d" "$tab" "$ident" >> "$latch"; fi
  done
  return 0
}

gate_disposition_counts() {
  # `종결 n · 포기 n · 면제 n`, from the latch, for the morning's one-line render.
  local latch tab d n_done=0 n_drop=0 n_ex=0 ident
  tab=$(printf '\t')
  latch=$(gate_disposition_latch)
  while IFS= read -r ident; do
    [ -n "$ident" ] || continue
    d=${ident%%"$tab"*}
    case "$d" in
      종결) n_done=$((n_done + 1)) ;;
      포기) n_drop=$((n_drop + 1)) ;;
      면제) n_ex=$((n_ex + 1)) ;;
    esac
  done <<GATE_DISP_COUNTS
$latch
GATE_DISP_COUNTS
  printf '종결 %s · 포기 %s · 면제 %s' "$n_done" "$n_drop" "$n_ex"
}

gate_write_disposition_report() {
  # THE ITEMISED ENUMERATION GOES IN ITS OWN FILE, and that choice is forced.
  # `done` is a ONE-LINE contract with four consumers — the morning status
  # render's `런 상태` line, the morning report which inserts the file whole, the
  # watcher's terminal banner which uses the file as the banner body, and the
  # status line which reads only its mtime. Widening it to many lines would break
  # the first, make the third vomit the whole list into a notification, and
  # require editing two files that are not in this change's declared set. A
  # sibling file keeps every one of those consumers untouched.
  #
  # WHY THIS FILE EXISTS AT ALL. This design leans on "a person reads it in the
  # morning" in three places, and the morning was told almost nothing: the only
  # thing it received about obligations was a COUNT of the unresolved ones, and
  # the terminal marker said not one word about them. Worse, the open list
  # de-duplicates by identity, so a second problem row for an identity does not
  # move that count — an amnesty could happen and the number would not budge.
  #
  # THE EXEMPTION IS ENUMERATED TOO, and that is the most important decision
  # here. It is the one disposition that writes no row, so it is the only one the
  # morning has no path to see at all; listing the two new verbs while leaving the
  # old one hidden would make the least inspected path the most attractive one.
  # Its anchor is the two values the exemption actually read — the segments and
  # the highest creation grade — so the amnesty class is visible on sight.
  #
  # WHAT THIS FILE DOES NOT UNDERWRITE. Of the three places that lean on the
  # morning, it carries two: evidence layer 2, and a lie told when the row was
  # first written. The third — detecting grade laundering after the fact — needs
  # the ledger to carry argv and the declared grade, and that was split out as
  # separate work, so it stays a residual this release does not support.
  local f="$RUN_DIR/done-obligations" latch tab d ident cur oid row
  [ -d "$RUN_DIR" ] || return 0
  tab=$(printf '\t')
  gate_disposition_latch_update
  latch=$(gate_disposition_latch)
  { printf '# 처분된 의무 — %s\n' "$(now_iso)"
    printf '# 근거 2층(그 행위가 정말 그 의무를 이행했는가)은 게이트가 해소하지 않습니다 — 여기가 그 잔여를 드러내는 자리입니다\n'
    if [ -z "$latch" ]; then
      printf '처분된 의무 없음\n'
    fi
    while IFS= read -r row; do
      [ -n "$row" ] || continue
      d=${row%%"$tab"*}
      ident=${row#*"$tab"}
      oid=$(gate_obligation_id "$ident")
      cur=$(gate_obligation_disposition "$ident")
      case "$d" in
        면제)
          printf '%s | 처분=면제 | 근거=세그먼트 %s · 최고 생성 등급 %s | 동일성=%s\n' \
            "$oid" "$(gate_obligation_segments "$ident")" \
            "$(gate_obligation_top_grade "$ident")" "$(gate_obligation_display "$ident")" ;;
        *)
          printf '%s | 처분=%s | 근거=%s | 동일성=%s\n' "$oid" "$d" \
            "$(gate_row_field \
                "$( { gate_rows "의무 $d" | grep -F "| 의무 id=$oid |" || true; } | tail -1)" '근거')" \
            "$(gate_obligation_display "$ident")" ;;
      esac
      # The latch records the FIRST disposition and never rewrites it, so a
      # disposition that has since lapsed — a `포기` whose segment came back out
      # of terminal — is reported as the latched fact AND as its present state.
      # Hiding the divergence would make the latch look like a live reading.
      if [ "$cur" != "$d" ]; then
        printf '  └ 래치 이후 변동: 현재 처분=%s\n' "${cur:-없음(미처분으로 되돌아옴)}"
      fi
    done <<GATE_DISP_REPORT
$latch
GATE_DISP_REPORT
  } > "$f"
}

gate_issue_boundary_approval() {
  # gate_issue_boundary_approval <name> <question> <binding>
  #
  # A boundary approval has NO act, so it can fill neither an act digest nor an
  # argv digest. The cutpoint slot carries the literal `경계` and the binding
  # tuple is (boundary name, the binding value) — which is why the three
  # approval shapes share one series rather than needing three.
  #
  # THE BINDING VALUE IS THE CALLER'S, AND IT IS THE VALUE THE CALLER'S OWN
  # PREDICATE READ. This function used to salt every boundary's id with the
  # progress digest, while B2 decides on the obligations its window still waits
  # on and B3 on its window key (the vector with `acts=` stripped) — so two of the four were deduplicated on a value their predicate
  # never looks at, and the progress digest moving underneath an unchanged
  # obligation set minted a fresh id per evaluation (measured: 27 distinct ids
  # over 30 B2 cycles, 50 over 90 B3 acts). B1's binding IS the progress digest,
  # so for B1 this is the same equivalence class as before; B4 passes the
  # progress digest until its bucket width is decided, so its
  # shape changes here and its value does not.
  #
  # `RUN_ID` STAYS IN THE SALT. Without it the same condition in two runs shares
  # one id, and the suppression below then reaches across run boundaries.
  #
  # DUPLICATE SUPPRESSION HAS THREE ARMS, AND THE MIDDLE ONE IS THE ONE THAT
  # WAS MISSING. An OPEN id (last row `대기`) is not re-appended. An id nobody
  # has asked is issued. And an id a person has ANSWERED is re-issued only once
  # the binding value has moved away and come back — not on the very next
  # judgment with the value unchanged.
  #
  # The middle arm used to be the first: "the last row is `대기`" alone, so a
  # resolved id re-opened with a fresh `대기` row whenever its predicate held
  # again. For B1 that is every judgment after the answer: the binding is the
  # progress digest, an `승인` row is not in the vector, and neither is anything
  # the router does with its own hands (commit, push, PR, merge), so the digest
  # a person had just said "keep going" about was still the digest at the next
  # judgment — same binding, same id, new `대기` row, B1..B3 suspended again.
  # "Keep going" could not be honoured at all. The contract says what an answer
  # buys instead: one frozen state, with the next question earned only by a
  # structural row moving the digest and minting a new id.
  #
  # WHY NOT "ANY ROW EXISTS", the form this replaced earlier: that swallowed
  # every recurrence after the first answer for good — a condition answered at
  # 22:00 whose binding value moved away and RETURNED at 03:00 could never ask
  # again, because the id had a row. So the answered arm reads a marker
  # beside the counters: `boundary-<name>.asked` holds the binding this boundary
  # was last issued for, and the predicate that owns the counter CLEARS it the
  # moment its binding moves (B1 and B3 when the digest changes, B2 when an
  # obligation it was waiting on is disposed). An answered id with the marker still equal to
  # the binding has been in the same state continuously since the answer, and
  # stays suppressed; one whose marker is gone is a recurrence, and asks. B4 and
  # the handoff floor bind to the progress digest and clear nothing — their
  # value does not return in practice, and an answered one stays answered
  # until the digest moves, which is what a person expects of "yes, continue".
  #
  # THE ANSWERED ARM AND THE REBASELINE ARE TWO DIFFERENT THINGS, AND BOTH HOLD.
  # Closing a boundary approval restarts that boundary's count
  # (`gate_close_settle` → `gate_boundary_rebaseline`), so a person's answer is
  # not immediately followed by a count already past the threshold. The count
  # restarting does not clear the marker, though: when it climbs back to the
  # threshold on the same binding value, the id is the same, it carries an
  # answer, and the marker still equals the binding — so it stays quiet. What
  # asks again is a recurrence, i.e. the binding moving away (clearing the
  # marker) and coming back.
  #
  # AN OPEN ID IS AUTO-RESOLVED WHEN THE SWITCH IS ON, and a freshly issued one
  # is closed right after its `대기` row (below). Both set
  # `GATE_BOUNDARY_AUTO_RESOLVED`. The answered arm sets
  # `GATE_BOUNDARY_SUPPRESSED` instead, because a caller that stops on an issued
  # approval must be able to tell "nothing was issued, the id was already
  # answered" from "an approval is now waiting" — with both empty those two
  # looked the same, and the shift launch stopped with the approval exit code
  # while no approval was pending.
  #
  # THE ANSWERED ARM IS A PERSON'S, NOT THE GATE'S OWN — BUT ONLY WHERE THIS
  # EVALUATION WOULD NOT RESOLVE. An id whose last row is an auto-resolution
  # (`처분 사유=자동 해소`) is not held quiet by the marker when auto-resolution
  # cannot close it now: nobody said "keep going" about that state, the gate
  # merely adopted its own recommendation, and the condition can change while
  # the binding does not — B4 binds to the progress digest, so an 80% resolved
  # automatically and a 100% reached on the same digest compute the same id.
  # Suppressing the second would close the ceiling's one signal with no approval
  # ever issued, so that id re-issues and waits.
  #
  # Where this evaluation WOULD resolve, the auto-resolved id stays quiet like
  # any answered one until its binding moves. Re-issuing there changes no
  # outcome and writes an issue row and a closing row on every call: a
  # SHIFT-FLOOR resolved once added that pair to every later launch in the same
  # state.
  #
  # AUTO-RESOLUTION IS NARROWED TWICE HERE. A B4 at or above the declared
  # ceiling is not resolved (`gate_boundary_auto_resolvable`) and falls through
  # to the notice below; an open approval a person already answered is not
  # resolved either. A close the transition guard refuses leaves
  # `GATE_BOUNDARY_AUTO_RESOLVED` empty, so the SHIFT-FLOOR caller does not
  # launch on a resolution that did not happen.
  local name="$1" q="$2" binding="$3" id st auto=0 rc=0
  GATE_BOUNDARY_AUTO_RESOLVED=""
  GATE_BOUNDARY_SUPPRESSED=""
  id="${name}-$(printf '%s' "$RUN_ID$name$binding" | shasum -a 256 | cut -c1-8)"
  if gate_auto_resolve_enabled && gate_boundary_auto_resolvable "$name"; then
    auto=1
  fi
  st=$(gate_approval_state "$id")
  if [ "$st" = "대기" ]; then
    if [ "$auto" = "1" ] && ! gate_approval_person_answered "$id"; then
      gate_auto_close_approval "$id" 승인 "$q" "계속" || rc=$?
      [ "$rc" != "0" ] || GATE_BOUNDARY_AUTO_RESOLVED="$id"
    fi
    return 0
  fi
  if [ -n "$st" ] && [ "$(cat "$RUN_DIR/boundary-$name.asked" 2>/dev/null || true)" = "$binding" ] \
    && { [ "$auto" = "1" ] \
         || [ "$(gate_row_field "$(gate_approval_last_row "$id")" '처분 사유')" != "자동 해소" ]; }; then
    GATE_BOUNDARY_SUPPRESSED="$id"
    return 0
  fi
  printf '%s\n' "$binding" > "$RUN_DIR/boundary-$name.asked"
  gate_approval_sidecar_write "$id" issue '질문' "$q" \
    || warn "could not write the question into the approval sidecar — the row is issued, but there is no block where the anchor $(gate_approval_sidecar_anchor "$id") points"
  # `유도 절단점=-` FOR THE SAME REASON THE ACT DIGEST IS `-`. A boundary has no
  # act, so there is no argv to derive a rung from, and `경계` in the slot beside
  # it is not a rung at all. Taking the ambient `GATE_ACT_DERIVED` would attach
  # the argv of whatever act happened to trip the boundary to a row that is not
  # about that act.
  gate_append '승인' "승인 id=$id" "상태=대기" "대상=-" "절단점=경계" \
    "유도 절단점=-" \
    "행위 다이제스트=-" "구속 튜플=$name/$binding" "막는 세그먼트=-" \
    "질문 문면=$q" "답변 문면=-" "사이드카 앵커=$(gate_approval_sidecar_anchor "$id")" \
    "발행 시각=$(now_iso)" "해소 시각=-"
  # THE ISSUE ROW STAYS, AND THE CLOSE FOLLOWS IT. The `대기` row is the record
  # that the boundary fired and what it read; the closing row right after it is
  # the record that nobody was waited on. Skipping the issue row would make an
  # auto-resolved stagnation indistinguishable from one that never happened.
  if [ "$auto" = "1" ]; then
    gate_auto_close_approval "$id" 승인 "$q" "계속" || rc=$?
    [ "$rc" != "0" ] || GATE_BOUNDARY_AUTO_RESOLVED="$id"
    return 0
  fi
  # The boundary approvals are the slowest class this design has, by
  # construction: they are evaluated on every act, so one opened while a long
  # stage runs waits out that whole stage — and one of them carries a dollar
  # figure. That is a declared consequence of raising notices only on router
  # calls, not a defect, and it is written down here so it is not rediscovered
  # as one.
  gate_notify_approval "$id" "$q"
  warn "boundary $name fired — approval wait $id: $q"
  gate_warn_canon_prompt "$id" "$q"
}

# The same seam run.sh carries, for the same reason: the tests need the
# definitions without a manifest, a run directory, or a verb. `test-snapshot.sh`
# calls `gate_progress_digest` directly against a fixture ledger, which is the
# only way to assert that issuing an approval leaves the digest unchanged — the
# regression that guards the boundary counters against resetting themselves.
if [ "${CC_GATE_SOURCE_ONLY:-0}" = "1" ]; then
  return 0 2>/dev/null || exit 0
fi

# bash reads a script as it runs it, so a file rewritten in place under a gate
# that is still in `gate_main` would have its bytes past this point executed.
# The `exit` on the next line ends the read here, whatever comes after.
gate_main "$@"
exit
